        protected override void LoadDefaultConfig() => GeneralConfiguration = Configuration.GetDefault();
        protected override void LoadConfig()
        {
            if (_superseded = StandDownForNewerVersion())
            {
                timer.Once(1f, () => Interface.Oxide.ReloadPlugin(Name));
                return;
            }
            base.LoadConfig();
            if (GeneralConfiguration == null)
            {
                LoadConfig<NPCsController, Configuration>(this, LoadDefaultConfig, ref GeneralConfiguration);
            }
            GeneralConfiguration._controller ??= new Configuration.ControllerGeneralConfiguration();
            SaveConfig();
        }
        protected override void SaveConfig()
        {
            Config.WriteObject(GeneralConfiguration);
            SaveDataConfig(this, GeneralConfiguration);
        }
