        public static string GetLangText(Oxide.Core.Libraries.Lang lang, Plugin plugin, string userID, string key, params object[] args)
        {
            string raw = lang?.GetMessage(key, plugin, userID) ?? key;
            if (args == null || args.Length == 0) return raw;
            try
            {
                return string.Format(raw, args);
            }
            catch (FormatException)
            {
                Debug.LogWarning("[Lang] Plugin {0}: invalid translation for key '{1}' (args={2}) - placeholders do not match the arguments; returning unformatted text. Check the lang file.", plugin?.Name ?? "?", key, args.Length);
                return raw;
            }
        }
        public string GetLangText(string userID, string key, params object[] args) => GetLangText(lang, this, userID, key, args);
