        #region Защита версии
        private const string VersionGuardFolder = "NPCsController/VersionGuard";
        private static readonly System.Text.RegularExpressions.Regex InfoVersionRegex =
            new System.Text.RegularExpressions.Regex(@"\[Info\(\s*""[^""]*""\s*,\s*""[^""]*""\s*,\s*""(\d+)\.(\d+)\.(\d+)""\s*\)\]");
        private bool _superseded;

        private bool StandDownForNewerVersion()
        {
            try
            {
                string source = Filename;
                if (string.IsNullOrEmpty(source) || !System.IO.Path.IsPathRooted(source) || !System.IO.File.Exists(source))
                    source = System.IO.Path.Combine(Interface.Oxide.PluginDirectory, Name + ".cs");
                if (!System.IO.File.Exists(source)) return false;
                string folder = System.IO.Path.Combine(Interface.Oxide.DataDirectory, VersionGuardFolder);
                string saved = System.IO.Path.Combine(folder, Name + ".cs");
                string marker = System.IO.Path.Combine(folder, "restore.txt");
                if (System.IO.File.Exists(saved) && TryReadInfoVersion(System.IO.File.ReadAllText(saved), out VersionNumber newer) && newer > Version)
                {
                    string attempt = Version + ">" + newer;
                    if (System.IO.File.Exists(marker) && System.IO.File.ReadAllText(marker).Trim() == attempt
                        && DateTime.UtcNow - System.IO.File.GetLastWriteTimeUtc(marker) < TimeSpan.FromMinutes(2))
                    {
                        Debug.LogError("NPCs Controller {0} was replaced by the saved {1} a moment ago, but {0} loaded again - keeping {0}. To stop restoring {1}, delete the data folder {2}",
                            Version, newer, VersionGuardFolder);
                        return false;
                    }
                    System.IO.File.WriteAllText(marker, attempt);
                    System.IO.File.Copy(saved, source, true);
                    Debug.LogWarning("NPCs Controller {0} is older than {1} installed earlier (another plugin brought an older copy) - {1} is restored and loads in a moment. To keep {0}, delete the data folder {2} and install {0} again",
                        Version, newer, VersionGuardFolder);
                    return true;
                }
                System.IO.Directory.CreateDirectory(folder);
                System.IO.File.Copy(source, saved, true);
                if (System.IO.File.Exists(marker)) System.IO.File.Delete(marker);
            }
            catch (Exception ex)
            {
                Debug.LogError("NPCs Controller version check failed: {0}", ex.Message);
            }
            return false;
        }
        private static bool TryReadInfoVersion(string text, out VersionNumber version)
        {
            System.Text.RegularExpressions.Match match = InfoVersionRegex.Match(text);
            version = match.Success
                ? new VersionNumber(int.Parse(match.Groups[1].Value), int.Parse(match.Groups[2].Value), int.Parse(match.Groups[3].Value))
                : default;
            return match.Success;
        }
        #endregion

