        private const float GameNavmeshPollInterval = 2f;
        private const int GameNavmeshMaxPolls = 150;

        private void RefreshGameNavmeshUnderBuildings()
        {
            int polls = 0;
            Timer poll = null;
            poll = timer.Every(GameNavmeshPollInterval, () =>
            {
                var nav = Rust.Ai.Gen2.Nav.RustNavigation.Instance;
                if (nav == null || !nav.IsDefaultNavmeshBuilt())
                {
                    if (++polls < GameNavmeshMaxPolls) return;
                    poll?.Destroy();
                    Debug.LogWarning<NPCsController>("[Navigation] The game navmesh never finished building - refresh under buildings skipped.");
                    return;
                }
                poll?.Destroy();

                int buildings = 0, blocks = 0;
                foreach (var building in BuildingManager.server.buildingDictionary.Values)
                {
                    if (building?.buildingBlocks == null) continue;
                    bool any = false;
                    Bounds area = default;
                    foreach (var block in building.buildingBlocks)
                    {
                        if (block == null || block.IsDestroyed || block.grade == BuildingGrade.Enum.Twigs) continue;
                        Bounds b = block.WorldSpaceBounds().ToBounds();
                        if (any) area.Encapsulate(b);
                        else { area = b; any = true; }
                        blocks++;
                    }
                    if (!any) continue;
                    nav.RebuildTilesInBounds(area);
                    buildings++;
                }
            });
        }

        private void DeferLoadGraphsUntilMonumentsReady()
        {
            int polls = 0;
            const int maxPolls = 60;
            Timer t = null;
            t = timer.Every(0.5f, () =>
            {
                polls++;
                if (HelperMonuments.Instance != null && HelperMonuments.Instance.allMonuments.Count > 0)
                {
                    t?.Destroy();
                    timer.Once(3f, () => HelperSavedNavMesh.Instance?.LoadAllFromDisk());
                    return;
                }
                if (polls >= maxPolls)
                {
                    t?.Destroy();
                }
            });
        }
        private void Unload()
        {
            if (_superseded) return;
            LogCapture.Stop();
            _fpsTimer?.Destroy();
            _fpsHead = _fpsCount = 0;
            UnloadRec();
            PluginTask.OnUnloadPlugin();

            HelperVehicles.OnUnloadPlugin();
            HelperBuildingNavMesh.OnUnloadPlugin();
            HelperWaterNavMesh.OnUnloadPlugin();
            HelperSavedNavMesh.OnUnloadPlugin();
            HelperPrefabs.OnUnloadPlugin();
            HelperMonuments.OnUnloadPlugin();
            CollectibleHelper.OnUnloadPlugin();
            HelperSafeZones.OnUnloadPlugin();
            HelperDoorTraps.OnUnloadPlugin();
            RustLocalization.OnUnloadPlugin();

            UserIdPool.OnUnloadPlugin();
            ServerObjectForPlugin.OnUnloadPlugin();
            BlackBox.Clear();
            Instance.ClearAllPooledCollection(out string response, RU);
            Instance = null;
        }
