        #region Hooks
        private void OnEntitySpawned(CollectibleEntity entity) => CollectibleHelper.OnEntitySpawned(entity);
        private void OnEntityKill(CollectibleEntity entity) => CollectibleHelper.OnEntityKill(entity);

        private void OnEntityBuilt(Planner plan, GameObject go)
        {
            if (go == null) return;
            if (go.ToBaseEntity() is DecayEntity de)
            {
                if (de is BuildingBlock bb) BuildingNavigation.NoteBlockChange(bb.buildingID, bb, true);
                else
                {
                    BuildingNavigation.NoteBlockChange(de.buildingID);
                    HelperBuildingNavMesh.NoteGeometryChanged(de);
                }
            }
        }
        private void OnEntitySpawned(Door door)
        {
            if (door == null) return;
            Interface.Oxide.NextTick(() =>
            {
                if (door == null || !door.IsValid()) return;
                HelperDoorTraps.Note(door);
                BuildingNavigation.NoteBlockChange(door.buildingID);
                HelperBuildingNavMesh.NoteGeometryChanged(door);
            });
        }
        private void OnEntitySpawned(BuildingBlock block)
        {
            if (block == null) return;
            Interface.Oxide.NextTick(() => { if (block != null && block.IsValid()) BuildingNavigation.NoteBlockChange(block.buildingID, block, true); });
        }
        private void OnEntityKill(DecayEntity entity)
        {
            if (entity == null) return;
            if (entity is BuildingBlock bb) BuildingNavigation.NoteBlockChange(bb.buildingID, bb, false);
            else BuildingNavigation.NoteBlockChange(entity.buildingID);
            if (entity is Door door) HelperDoorTraps.Forget(door);
            HelperBuildingNavMesh.NoteGeometryChanged(entity);
        }
        private void OnEntitySpawned(BaseLadder ladder)
        {
            if (ladder == null) return;
            Interface.Oxide.NextTick(() =>
            {
                if (ladder == null || !ladder.IsValid()) return;
                uint id = BuildingNavigation.FindWatchedBuildingIdNear(ladder.transform.position);
                if (id != 0) BuildingNavigation.NoteBlockChange(id);
                HelperBuildingNavMesh.NoteGeometryChanged(ladder);
            });
        }
        private void OnEntityKill(BaseLadder ladder)
        {
            if (ladder == null) return;
            uint id = BuildingNavigation.FindWatchedBuildingIdNear(ladder.transform.position);
            if (id != 0) BuildingNavigation.NoteBlockChange(id);
            HelperBuildingNavMesh.NoteGeometryChanged(ladder);
        }
        private void OnDoorOpened(Door door, BasePlayer player) => NoteHatchToggle(door);
        private void OnDoorClosed(Door door, BasePlayer player) => NoteHatchToggle(door);
        private void NoteHatchToggle(Door door)
        {
            if (door == null) return;
            if (door.GetComponentInChildren<TriggerLadder>(true) != null)
                BuildingNavigation.NoteBlockChange(door.buildingID);
        }
        private void OnEntitySpawned(BaseEntity entity)
        {
            if (entity == null) return;
            HelperBuildingNavMesh.NoteGeometryChanged(entity);
        }
        private void OnEntityKill(BaseEntity entity) => HelperBuildingNavMesh.NoteGeometryChanged(entity);
        private void OnStructureUpgrade(BaseCombatEntity entity, BasePlayer player, BuildingGrade.Enum grade)
            => HelperBuildingNavMesh.NoteGeometryChanged(entity);
        private void OnStructureUpgraded(BuildingBlock block, BasePlayer player, BuildingGrade.Enum grade, ulong skin)
            => RebuildGameNavmeshAround(block);
        private void OnStructureRotate(BuildingBlock block, BasePlayer player)
        {
            if (block == null) return;
            Interface.Oxide.NextTick(() =>
            {
                if (block == null || !block.IsValid()) return;
                HelperBuildingNavMesh.NoteGeometryChanged(block);
                RebuildGameNavmeshAround(block);
            });
        }
        private static void RebuildGameNavmeshAround(BaseEntity entity)
        {
            if (entity == null || !entity.IsValid()) return;
            var nav = Rust.Ai.Gen2.Nav.RustNavigation.Instance;
            if (nav == null) return;
            Bounds bounds = entity.WorldSpaceBounds().ToBounds();
            nav.RebuildTilesInBounds(bounds);
        }
        private object CanMoveItem(Item item, PlayerInventory playerLoot, ItemContainerId targetContainer, int targetSlot, int amount, ItemMoveModifier itemMoveModifier)
        {
            if(item?.parent != null && item.parent.IsLocked()) return true;
            return null;
        }

        private object CanBeTargeted(BaseCombatEntity target, BaseEntity turret)
        {
            if (target is not BaseCustomNpc bot) return null;
            if (bot.IsSparedBy(turret)) return false;
            if (turret is not AutoTurret at) return null;
            if (at.OwnerID != 0) return null;
            if ((bot.ConfigNPC?.RateSelfDamageFromTurrets() ?? 1f) <= 0f) return false;
            return bot.IsHostile() ? null : (object)false;
        }

        [AutoPatch]
        [HarmonyLib.HarmonyPatch(typeof(Rust.Ai.Gen2.SenseComponent), "CanTarget")]
        internal class SenseComponent_CanTarget_Patch
        {
            [HarmonyLib.HarmonyPostfix]
            private static void Postfix(Rust.Ai.Gen2.SenseComponent __instance, BaseEntity entity, ref bool __result)
            {
                if (__result || !IsVanillaTargetBot(entity) || entity is not BaseCustomNpc bot) return;
                if (!bot.IsValid() || bot.IsDestroyed || bot.IsDead() || bot.IsTransferProtected()) return;
                if (__instance.StanceToward(bot) == Rust.Ai.Gen2.NPCStance.Ignore) return;
                if (SimpleAIMemory.PlayerIgnoreList.Contains(bot)) return;
                if (__instance.Observer != null && __instance.Observer.RefusesToTarget(bot)) return;
                __result = true;
            }
        }

        [AutoPatch]
        [HarmonyLib.HarmonyPatch(typeof(Rust.Ai.Gen2.SenseComponent), nameof(Rust.Ai.Gen2.SenseComponent.StanceToward))]
        internal class SenseComponent_StanceToward_Patch
        {
            [HarmonyLib.HarmonyPostfix]
            private static void Postfix(Rust.Ai.Gen2.SenseComponent __instance, BaseEntity entity, ref Rust.Ai.Gen2.NPCStance __result)
            {
                Rust.Ai.Gen2.NPCTeam team = __instance.team;
                if (team == null || !IsVanillaTargetBot(entity)) return;
                Rust.Ai.Gen2.NPCStance stance = team.players;
                __result = stance == Rust.Ai.Gen2.NPCStance.Ignore && __instance.HurtUsRecently(entity) ? team.attackers : stance;
            }
        }

        [AutoPatch]
        [HarmonyLib.HarmonyPatch(typeof(Rust.Ai.Gen2.SenseComponent), nameof(Rust.Ai.Gen2.SenseComponent.ShouldRefreshFast), HarmonyLib.MethodType.Getter)]
        internal class SenseComponent_ShouldRefreshFast_Patch
        {
            [HarmonyLib.HarmonyPostfix]
            private static void Postfix(Rust.Ai.Gen2.SenseComponent __instance, ref bool __result)
