        private static bool IsVanillaTargetBot(BaseEntity entity) =>
            !ConVar.AI.ignoreplayers && entity is BaseCustomNpc bot && bot.TargetableByNpcs;

        [AutoPatch]
        [HarmonyLib.HarmonyPatch(typeof(AIBrainSenses), nameof(AIBrainSenses.IsValidSenseType))]
        internal class AIBrainSenses_IsValidSenseType_Patch
        {
            [HarmonyLib.HarmonyPostfix]
            private static void Postfix(AIBrainSenses __instance, BaseEntity ent, ref bool __result)
            {
                if (__result || !IsVanillaTargetBot(ent)) return;
                __result = (__instance.senseTypes & global::EntityType.Player) == global::EntityType.Player;
            }
        }

        [AutoPatch]
        [HarmonyLib.HarmonyPatch(typeof(AIBrainSenses), nameof(AIBrainSenses.AiCaresAbout))]
        internal class AIBrainSenses_AiCaresAbout_Patch
        {
            [HarmonyLib.HarmonyPrefix]
            private static bool Prefix(AIBrainSenses __instance, BaseEntity entity, ref bool __result)
            {
                if (!__instance.checkVision || !__instance.ignoreNonVisionSneakers || __instance.owner == null) return true;
                if (!IsVanillaTargetBot(entity) || entity is not BaseCustomNpc bot) return true;
                Vector3 ownerPos = __instance.owner.transform.position;
                if (__instance.listenRange > 0f && bot.TimeSinceLastNoise <= 1f && bot.CanLastNoiseBeHeard(ownerPos, __instance.listenRange)) return true;
                if (__instance.IsTargetInVision(bot)) return true;
                float dist = Vector3.Distance(ownerPos, bot.transform.position);
                BaseAIBrain brain = __instance.brain;
                if (brain == null) return true;
                if ((bot.IsDucked() && dist >= brain.IgnoreSneakersMaxDistance) || dist >= brain.IgnoreNonVisionMaxDistance)
                {
                    __result = false;
                    return false;
                }
                return true;
            }
        }

        [AutoPatch]
        [HarmonyLib.HarmonyPatch(typeof(AIBrainSenses), nameof(AIBrainSenses.UpdateKnownPlayersLOS))]
        internal class AIBrainSenses_UpdateKnownPlayersLOS_Patch
        {
            [HarmonyLib.HarmonyPrefix]
            private static void Prefix(AIBrainSenses __instance, out float __state) => __state = __instance.nextKnownPlayersLOSUpdateTime;

            [HarmonyLib.HarmonyPostfix]
            private static void Postfix(AIBrainSenses __instance, float __state)
            {
                if (__instance.nextKnownPlayersLOSUpdateTime == __state || __instance.ownerAttack == null) return;
                BaseEntity owner = __instance.owner;
                List<BaseEntity> players = __instance.Memory?.Players;
                if (owner == null || players == null) return;
                for (int i = 0; i < players.Count; i++)
                {
                    BaseEntity player = players[i];
                    if (player == null || !IsVanillaTargetBot(player)) continue;
                    bool los = __instance.ownerAttack.CanSeeTarget(player);
                    __instance.Memory.SetLOS(player, los);
                    if (__instance.refreshKnownLOS && los
                        && Vector3.Distance(player.transform.position, owner.transform.position) <= __instance.TargetLostRange)
                    {
                        __instance.Memory.SetKnown(player, owner, __instance);
                    }
                }
            }
        }

