        public static bool IsAdmin(string userID) => Instance?.permission.UserHasPermission(userID, AdminPermission) == true;
        public static void LoadConfig<TPlugin, TConfig>(TPlugin plugin, Action defaultConfig, ref TConfig config) where TPlugin : Plugin where TConfig : class
        {
            try
            {
                bool isLastRu = RU;
                string lastVersion = plugin.Version.ToString();
                string name = typeof(TPlugin).Name;
                if(Interface.Oxide.DataFileSystem.ExistsDatafile($"{name}/ReserveConfig/lastLangRU"))
                {
                    isLastRu = Interface.Oxide.DataFileSystem.ReadObject<bool>($"{name}/ReserveConfig/lastLangRU");
                }
                if(Interface.Oxide.DataFileSystem.ExistsDatafile($"{name}/ReserveConfig/lastVersion"))
                {
                    lastVersion = Interface.Oxide.DataFileSystem.ReadObject<string>($"{name}/ReserveConfig/lastVersion");
                }
                config = plugin.Config.ReadObject<TConfig>();
                bool foreignConfig = IsForeignConfig<TPlugin, TConfig>(plugin);
                if (config == null || isLastRu != RU || lastVersion != plugin.Version.ToString() || foreignConfig)
                {
                    LoadDataConfig<TPlugin, TConfig>(defaultConfig, ref config);
                }

            }
            catch (Exception ex)
            {
                Debug.LogError<TPlugin>("{0}", ex);
                LoadDataConfig<TPlugin, TConfig>(defaultConfig, ref config);
            }
        }
        public static void LoadDataConfig<TPlugin, TConfig>(Action defaultConfig, ref TConfig config) where TPlugin : Plugin where TConfig : class
        {
            try
            {
                string name = typeof(TPlugin).Name;
                if(Interface.Oxide.DataFileSystem.ExistsDatafile($"{name}/ReserveConfig/config"))
                {
                    string reserveJson = Interface.Oxide.DataFileSystem.ReadObject<string>($"{name}/ReserveConfig/config");
                    config = DeserializeReserve<TConfig>(reserveJson);
                    if(config != null)
                    {
                        Debug.LogWarning<TPlugin>("The configuration has been restored from the backup copy");
                        return;
                    }
                }
            }
            catch (Exception ex)
            {
                Debug.LogError<TPlugin>("{0}", ex);
            }

            defaultConfig.Invoke();
        }
        public static void SaveDataConfig<TPlugin, TConfig>(TPlugin plugin, TConfig config) where TPlugin : Plugin where TConfig : class
        {
            string name = typeof(TPlugin).Name;
            Interface.Oxide.DataFileSystem.WriteObject($"{name}/ReserveConfig/config", JsonConvert.SerializeObject(config, Formatting.Indented, settingsSerializer));
            Interface.Oxide.DataFileSystem.WriteObject($"{name}/ReserveConfig/lastLangRU", RU);
            Interface.Oxide.DataFileSystem.WriteObject($"{name}/ReserveConfig/lastVersion", plugin.Version.ToString());
        }
        public static void SaveDataConfig<TConfig>(string pathReserve, VersionNumber version, ref TConfig config)
        {
            Interface.Oxide.DataFileSystem.WriteObject($"{pathReserve}/config", JsonConvert.SerializeObject(config, Formatting.Indented, settingsSerializer));
            Interface.Oxide.DataFileSystem.WriteObject($"{pathReserve}/lastLangRU", RU);
            Interface.Oxide.DataFileSystem.WriteObject($"{pathReserve}/lastVersion", version.ToString());
        }
        private static TConfig DeserializeReserve<TConfig>(string json) where TConfig : class
        {
            JsonSerializerSettings settings = settingsSerializer;
            Dictionary<string, object> raw = JsonConvert.DeserializeObject<Dictionary<string, object>>(json);
            if(raw != null && raw.Count > 0)
            {
                HashSet<string> memberNames = GetMemberNames<TConfig>();
                bool isNewFormat = false;
                foreach(string key in raw.Keys)
                {
                    if(memberNames.Contains(key))
                    {
                        isNewFormat = true;
                        break;
                    }
                }
                if(!isNewFormat)
                {
                    settings = null;
                }
            }
            return JsonConvert.DeserializeObject<TConfig>(json, settings);
        }
        private static bool IsForeignConfig<TPlugin, TConfig>(TPlugin plugin) where TPlugin : Plugin
        {
            try
            {
                Dictionary<string, object> raw = plugin.Config.ReadObject<Dictionary<string, object>>();
                if(raw == null || raw.Count == 0)
                {
                    return false;
                }
                HashSet<string> currentKeys = GetJsonPropertyNames<TConfig>();
                if(currentKeys.Count == 0)
                {
                    return false;
                }
                foreach(string key in raw.Keys)
                {
                    if(currentKeys.Contains(key))
                    {
                        return false;
                    }
                }
                return true;
            }
            catch
            {
                return false;
            }
        }
        private static HashSet<string> GetMemberNames<TConfig>()
        {
            HashSet<string> names = new HashSet<string>();
            if(settingsSerializer.ContractResolver.ResolveContract(typeof(TConfig)) is JsonObjectContract contract)
            {
                foreach(JsonProperty property in contract.Properties)
                {
                    string memberName = property.UnderlyingName ?? property.PropertyName;
                    if(memberName != null)
                    {
                        names.Add(memberName);
                    }
                }
            }
            return names;
        }
        private static HashSet<string> GetJsonPropertyNames<TConfig>()
        {
            HashSet<string> names = new HashSet<string>();
            if(new DefaultContractResolver().ResolveContract(typeof(TConfig)) is JsonObjectContract contract)
            {
                foreach(JsonProperty property in contract.Properties)
                {
                    if(property.PropertyName != null)
                    {
                        names.Add(property.PropertyName);
                    }
                }
            }
            return names;
        }

        #endregion
    }
