        public abstract class BaseConfigurationNPCInventory
        {
            [JsonIgnore]
            protected const int BaseOrder = 0;

            [JsonProperty(RU ? "Настройка рюкзака" : "Backpack settings", Order = BaseOrder + 10)]
            public BackpackSetup Backpack;

            [JsonProperty(RU ? "Настройка одежды" : "Clothing settings", Order = BaseOrder + 50)]
            public WearContainerSetup Wear;

            public sealed class BackpackSetup : BaseContainerSetup<LootItemSetup>
            {
                [JsonProperty(RU ? "Выдавать рюкзак?" : "Should I give out a backpack?")]
                public bool Enabled;

                [JsonProperty(RU ? "Предмет рюкзака" : "Backpack item")]
                public BaseItemSetup Backpack;

                [JsonIgnore]
                private bool sorted;

                public override void InitContainer(ItemContainer container)
                {
                    if(!Enabled) return;
                    Item backpack = Backpack.CreateItem(1);
                    if(backpack == null || backpack.contents == null) return;
                    if(!backpack.MoveToContainer(container))
                    {
                        backpack.Remove();
                        return;
                    }
                    if(!sorted) SortedItems();
                    base.InitContainer(backpack.contents);
                }
                private void SortedItems()
                {
                    if(items != null && items.Count > 0) items.Sort(LootItemSetup.CompareByChance);
                    sorted = true;
                }
            }
            public sealed class WearContainerSetup : BaseContainerSetup<ItemSetup>
            {
                protected override bool CanLockedContents() => false;
                protected override bool CanGiveItem(Item item)
                {
                    return base.CanGiveItem(item) && !item.IsBackpack();
                }
            }
            public sealed class MainContainerSetup : BaseContainerSetup<LootItemSetup>
            {
                [JsonIgnore]
                private bool sorted;

                public override void InitContainer(ItemContainer container)
                {
                    if(!sorted) SortedItems();
                    base.InitContainer(container);
                }
                private void SortedItems()
                {
                    if(items != null && items.Count > 0) items.Sort(LootItemSetup.CompareByChance);
                    sorted = true;
                }
            }
            public sealed class BeltContainerSetup : BaseContainerSetup<ItemSetup>
            {
                protected override bool CanGiveItem(Item item)
                {
                    return base.CanGiveItem(item) && (item.info.category == ItemCategory.Weapon || item.info.category == ItemCategory.Tool || item.info.category == ItemCategory.Ammunition || item.info.category == ItemCategory.Traps || item.info.category == ItemCategory.Medical);
                }
            }
            public interface IContainerSetup
            {
                void InitContainer(ItemContainer container);
            }
            public abstract class BaseContainerSetup<T> : IContainerSetup where T : ItemSetup
            {
                [JsonIgnore]
                protected const int order = 0;

                [JsonProperty(RU ? "Блокировать контейнер?(true - после смерти лут не выпадает)" : "Lock container? (true - after death loot won't drop)", Order = order + 10)]
                public bool CanLock = false;

                [JsonProperty(RU ? "Список предметов" : "List of items", Order = order + 20)]
                public List<T> items = new();

                public virtual void InitContainer(ItemContainer container)
                {
                    if(container != null && items != null && items.Count > 0)
                    {
                        foreach(var item in items)
                        {
                            if(container.IsFull()) break;
                            if(item == null) continue;
                            Item _item = item.CreateItem();
                            if(CanGiveItem(_item))
                            {
                                if(!_item.MoveToContainer(container)) _item.Remove();
                            }
                        }
                    }
                    container?.SetLocked(CanLock, CanLockedContents());
                }

                protected virtual bool CanLockedContents() => CanLock;
                protected virtual bool CanGiveItem(Item item)
                {
                    return item?.info != null;
                }
            }
        }

        public class LootItemSetup : ItemSetup
        {
            [JsonProperty(RU ? "Шанс добычи (% 0 - 100)" : "Chance (% 0 - 100)")]
            private float _chance = 100f;

            [JsonIgnore]
            public float Chance
            {
                get => Mathf.Clamp(_chance, 0f, 100f);
                set => _chance = Mathf.Clamp(value, 0f, 100f);
            }

            public override Item CreateItem() => CanChance() ? base.CreateItem() : null;
            public bool CanChance() => Chance > Random.Range(1f, 100f);
            public static int CompareByChance(LootItemSetup a, LootItemSetup b)
            {
                if(a == null && b == null) return 0;
                if(a == null) return -1;
                if(b == null) return 1;
                float num1 = a.Chance, num2 = b.Chance;
                if(num1 == num2) return 0;
                if(num1 < num2) return -1;
                return 1;
            }
        }
        public class ItemSetup
        {
            [JsonProperty(RU ? "Настройка предмета" : "Item settings")]
            private BaseItemSetup _item;

            [JsonProperty(RU ? "Случайное количество" : "Random amount")]
            private MinMax _amount;

            [JsonProperty(RU ? "Вложения" : "Attachments")]
            private List<ItemSetup> _attachments;

            [JsonIgnore]
            public BaseItemSetup Item
            {
                get => _item;
                set => _item = value;
            }

            [JsonIgnore]
            public MinMax Amount
            {
                get => _amount;
                set => _amount = value;
            }

            [JsonIgnore]
            public List<ItemSetup> Attachments
            {
                get => _attachments;
                set => _attachments = value;
            }

            public virtual Item CreateItem()
            {
                int amount = Mathf.Max(1, _amount.GetRandomInt());
                Item result = _item.CreateItem(amount);
                if(result != null && _attachments != null && _attachments.Count > 0 && result.contents != null)
                {
                    foreach(var attachment in _attachments)
                    {
                        if(attachment != null)
                        {
                            var attachmentItem = attachment.CreateItem();
                            if(attachmentItem != null)
                            {
                                if(!attachmentItem.MoveToContainer(result.contents))
                                {
                                    attachmentItem.Remove();
                                }
                            }
                            else
                            {
                                Debug.LogWarning("Attachment item [{0}] not created", attachment._item.shortNameOrId);
                            }
                        }
                    }

                    if(result.GetHeldEntity() is BaseProjectile projectile)
                    {
                        projectile.SetLightsOn(true);
                    }
                }
                return result;
            }
        }
        public static ItemDefinition ResolveItemDefinition(string shortNameOrId)
        {
            if (string.IsNullOrEmpty(shortNameOrId)) return null;
            ItemDefinition result = null;
            if (int.TryParse(shortNameOrId, out int id)) result = ItemManager.FindItemDefinition(id);
            if (result == null) result = ItemManager.FindDefinitionByPartialName(shortNameOrId);
            return result;
        }

        public struct BaseItemSetup
        {
            [JsonProperty(RU ? "ShortName или ID предмета" : "Item shortname or ID")]
            public string shortNameOrId;

            [JsonProperty(RU ? "Название предмета (оставьте пустым для стандартного названия)" : "Item name (leave empty for default name)")]
            public string name;

            [JsonProperty(RU ? "Скин предмета" : "Item skin")]
            public ulong SkinID;

            [JsonIgnore]
            private ItemDefinition _def;
            [JsonIgnore]
            public ItemDefinition ItemDef => _def ??= GetItemDefinition();

            public BaseItemSetup(string shortNameOrId, ulong skin)
            {
                this.shortNameOrId = shortNameOrId;
                name = "";
                SkinID = skin;
                _def = null;
            }

            public Item CreateItem(int amount)
            {
                if (string.IsNullOrEmpty(shortNameOrId)) return null;
                amount = Mathf.Max(1, amount);
                Item result = null;
                if (ItemDef != null) result = ItemManager.Create(ItemDef, amount, SkinID);
                if (result != null && !string.IsNullOrEmpty(name)) result.name = name;

                if (result == null) Debug.LogWarning("Item [{0}] not created", shortNameOrId);

                return result;
            }
            private ItemDefinition GetItemDefinition() => ResolveItemDefinition(shortNameOrId);

        }

