            private static readonly Dictionary<ulong, VehicleControllerBase> _pilots = new();

            public static bool TryGetPilot(ulong botId, out VehicleControllerBase pilot)
                => _pilots.TryGetValue(botId, out pilot) && pilot != null;

            public static int PilotCount
            {
                get
                {
                    int count = 0;
                    foreach (VehicleControllerBase pilot in _pilots.Values)
                        if (pilot != null) count++;
                    return count;
                }
            }

            public static string Board(BaseCustomNpc bot, BaseVehicle vehicle, out VehicleControllerBase pilot)
            {
                pilot = null;
                if (bot == null || !bot.IsValid()) return "bot is missing";
                if (vehicle == null || vehicle.IsDestroyed) return "vehicle is missing";

                VehicleControllerBase created = VehicleControllerBase.CreateFor(bot, vehicle);
                string error = created.Take(bot, vehicle);
                if (error != null)
                {
                    UnityEngine.Object.Destroy(created);
                    return error;
                }
                pilot = created;
                return null;
            }

            public static string BoardGunner(BaseCustomNpc bot, AttackHelicopter heli, out HeliGunner gunner)
            {
                gunner = null;
                if (bot == null || !bot.IsValid()) return "bot is missing";

                HeliGunner created = bot.gameObject.AddComponent<HeliGunner>();
                string error = created.Take(bot, heli);
                if (error != null)
                {
                    UnityEngine.Object.Destroy(created);
                    return error;
                }
                gunner = created;
                return null;
            }

            public static void ReleaseRoles(BaseCustomNpc bot, Component keep, string why)
            {
                if (bot == null) return;
                ulong id = bot.userID;
                if (_pilots.TryGetValue(id, out VehicleControllerBase pilot) && pilot != null && pilot != keep) pilot.Release(why);
                if (_gunners.TryGetValue(id, out HeliGunner gunner) && gunner != null && gunner != keep) gunner.Release(why);
                foreach (VehicleControllerBase driver in _pilots.Values)
                    if (driver != null) driver.ForgetPassenger(bot);
            }

            public static void ReleaseAll(string why)
            {
                List<VehicleControllerBase> pilots = new List<VehicleControllerBase>(_pilots.Values);
                for (int i = 0; i < pilots.Count; i++)
                    if (pilots[i] != null) pilots[i].Release(why);
                _pilots.Clear();
                ReleaseGunners(why);
            }

            public static void ReleaseGunners(string why)
            {
                List<HeliGunner> gunners = new List<HeliGunner>(_gunners.Values);
                for (int i = 0; i < gunners.Count; i++)
                    if (gunners[i] != null) gunners[i].Release(why);
                _gunners.Clear();
            }

