            private sealed class MinHeap<T>
            {
                private readonly List<float> _keys = new List<float>();
                private readonly List<T> _items = new List<T>();

                public int Count => _keys.Count;

                public void Clear()
                {
                    _keys.Clear();
                    _items.Clear();
                }

                public void Push(float key, T item)
                {
                    _keys.Add(key);
                    _items.Add(item);
                    int i = _keys.Count - 1;
                    while (i > 0)
                    {
                        int parent = (i - 1) / 2;
                        if (_keys[parent] <= key) break;
                        _keys[i] = _keys[parent];
                        _items[i] = _items[parent];
                        i = parent;
                    }
                    _keys[i] = key;
                    _items[i] = item;
                }

                public T Pop(out float key)
                {
                    key = _keys[0];
                    T top = _items[0];
                    int last = _keys.Count - 1;
                    float lastKey = _keys[last];
                    T lastItem = _items[last];
                    _keys.RemoveAt(last);
                    _items.RemoveAt(last);
                    if (last == 0) return top;

                    int i = 0;
                    while (true)
                    {
                        int child = i * 2 + 1;
                        if (child >= last) break;
                        if (child + 1 < last && _keys[child + 1] < _keys[child]) child++;
                        if (_keys[child] >= lastKey) break;
                        _keys[i] = _keys[child];
                        _items[i] = _items[child];
                        i = child;
                    }
                    _keys[i] = lastKey;
                    _items[i] = lastItem;
                    return top;
                }
            }

