            public static bool TryGetRoadSpot(Vector3 near, float maxDist, out Vector3 spot, out Vector3 along)
            {
                EnsureRoads();
                spot = near;
                along = Vector3.forward;
                int node = NearestRoadNode(near, maxDist);
                if (node < 0) return false;

                RoadNode road = _roadNodes[node];
                spot = road.Pos;
                spot.y = TerrainMeta.HeightMap.GetHeight(spot);
                if (road.Links.Count > 0)
                {
                    Vector3 dir = _roadNodes[road.Links[0]].Pos - road.Pos;
                    dir.y = 0f;
                    if (dir.sqrMagnitude > 0.01f) along = dir.normalized;
                }
                return true;
            }

