            #region Профиль транспорта

            public enum VehicleKind
            {
                Car,
                Bike,
                Boat,
                Snowmobile,
                Air,
                Sub,
                Rail,
                Other
            }

            public class VehicleProfile
            {
                private static void MeasureBody(BaseVehicle vehicle, out float halfLength, out float halfWidth)
                {
                    Bounds local = new Bounds(Vector3.zero, Vector3.zero);
                    Transform root = vehicle.transform;

                    AddColliders(vehicle.gameObject, root, ref local);
                    if (vehicle is ModularCar car)
                    {
                        foreach (BaseVehicleModule module in car.AttachedModuleEntities)
                            if (module != null) AddColliders(module.gameObject, root, ref local);
                    }

                    halfLength = Mathf.Max(Mathf.Max(-local.min.z, local.max.z), vehicle.bounds.extents.z);
                    float colliderHalfWidth = Mathf.Max(-local.min.x, local.max.x);
                    halfWidth = vehicle is RidableHorse ? colliderHalfWidth : Mathf.Max(colliderHalfWidth, vehicle.bounds.extents.x);
                }

                private static int _preventBuildingLayer = -2;

                private static void AddColliders(GameObject go, Transform root, ref Bounds local)
                {
                    if (_preventBuildingLayer == -2) _preventBuildingLayer = LayerMask.NameToLayer("Prevent Building");
                    Collider[] colliders = go.GetComponentsInChildren<Collider>();
                    for (int i = 0; i < colliders.Length; i++)
                    {
                        Collider c = colliders[i];
                        if (c == null || c.isTrigger || !c.enabled || c.gameObject.layer == _preventBuildingLayer) continue;
                        if (c.ToBaseEntity() is BasePlayer) continue;
                        Transform t = c.transform;
                        if (LocalShape(c, out Vector3 center, out Vector3 extents))
                        {
                            for (int corner = 0; corner < 8; corner++)
                            {
                                Vector3 point = center + new Vector3(
                                    (corner & 1) == 0 ? extents.x : -extents.x,
                                    (corner & 2) == 0 ? extents.y : -extents.y,
                                    (corner & 4) == 0 ? extents.z : -extents.z);
                                local.Encapsulate(root.InverseTransformPoint(t.TransformPoint(point)));
                            }
                            continue;
                        }
                        Bounds b = c.bounds;
                        for (int corner = 0; corner < 8; corner++)
                        {
                            Vector3 point = b.center + new Vector3(
                                (corner & 1) == 0 ? b.extents.x : -b.extents.x,
                                (corner & 2) == 0 ? b.extents.y : -b.extents.y,
                                (corner & 4) == 0 ? b.extents.z : -b.extents.z);
                            local.Encapsulate(root.InverseTransformPoint(point));
                        }
                    }
                }

                private static bool LocalShape(Collider c, out Vector3 center, out Vector3 extents)
                {
                    switch (c)
                    {
                        case BoxCollider box:
                            center = box.center;
                            extents = box.size * 0.5f;
                            return true;
                        case SphereCollider sphere:
                            center = sphere.center;
                            extents = Vector3.one * sphere.radius;
                            return true;
                        case CapsuleCollider capsule:
                            center = capsule.center;
                            extents = Vector3.one * capsule.radius;
                            extents[capsule.direction] = Mathf.Max(capsule.height * 0.5f, capsule.radius);
                            return true;
                        case WheelCollider wheel:
                            center = wheel.center;
                            extents = Vector3.one * wheel.radius;
                            return true;
                        case MeshCollider mesh when mesh.sharedMesh != null:
                            Bounds bounds = mesh.sharedMesh.bounds;
                            center = bounds.center;
                            extents = bounds.extents;
                            return true;
                    }
                    center = extents = Vector3.zero;
                    return false;
                }

                public VehicleKind Kind;
                public float HalfLength = 2f;
                public float HalfWidth = 1f;
                public float CruiseSpeed = 8f;

                public static VehicleProfile For(BaseVehicle vehicle)
                {
                    VehicleProfile p = new VehicleProfile();

                    MeasureBody(vehicle, out float halfLength, out float halfWidth);
                    p.HalfLength = Mathf.Max(1f, halfLength);
                    p.HalfWidth = Mathf.Max(0.5f, halfWidth);

                    if (vehicle is TrainEngine) p.Kind = VehicleKind.Rail;
                    else if (vehicle is BaseSubmarine) p.Kind = VehicleKind.Sub;
                    else if (vehicle is BaseHelicopter) p.Kind = VehicleKind.Air;
                    else if (vehicle is BaseBoat) p.Kind = VehicleKind.Boat;
                    else if (vehicle is Bike) p.Kind = VehicleKind.Bike;
                    else if (vehicle is Snowmobile) p.Kind = VehicleKind.Snowmobile;
                    else if (vehicle is ModularCar || vehicle is BasicCar) p.Kind = VehicleKind.Car;
                    else p.Kind = VehicleKind.Other;
                    p.CruiseSpeed = CruiseFor(p.Kind);
                    return p;
                }

                public static float CruiseFor(VehicleKind kind)
                {
                    switch (kind)
                    {
                        case VehicleKind.Rail: return 14f;
                        case VehicleKind.Sub: return 5f;
                        case VehicleKind.Air: return 12f;
                        case VehicleKind.Boat: return 9f;
                        case VehicleKind.Bike: return 7f;
                        case VehicleKind.Snowmobile: return 8f;
                        case VehicleKind.Car: return 10f;
                        default: return 6f;
                    }
                }
            }

