            #region Дорожная сеть

            private class RoadNode
            {
                public Vector3 Pos;
                public readonly List<int> Links = new();
                public int Component = -1;

                public bool IsEnd;

                public RoadClass Class = RoadClass.Main;

                public int Road;
            }

            [Flags]
            public enum RoadClass
            {
                Main = 1,
                Side = 2,
                Trail = 4,
                All = Main | Side | Trail
            }

            private static RoadClass ClassOf(PathList road)
            {
                switch (road.Hierarchy)
                {
                    case 1: return RoadClass.Side;
                    case 2: return RoadClass.Trail;
                    default: return RoadClass.Main;
                }
            }

            public enum RoutePreference
            {
                Auto,
                Roads
            }

            private const float OffRoadCostFactor = 1.5f;

            public class RouteInfo
            {
                public string How = "direct";
                public bool ByRoad;
                public float Cost;
                public int EntryImpassable;
                public int ExitImpassable;
                public Vector3 ExitFrom;
                public bool NoWaterRoute;
            }

            private static readonly List<RoadNode> _roadNodes = new();

            private static readonly Dictionary<int, List<int>> _roadGrid = new();
            private const float RoadCell = 50f;

            private const float RoadNodeStep = 12f;

            private const float RoadJunction = 30f;

            private const float RoadEndStitch = 70f;

            private static int CellKey(Vector3 p)
            {
                int cx = Mathf.FloorToInt(p.x / RoadCell);
                int cz = Mathf.FloorToInt(p.z / RoadCell);
                return cx * 100000 + cz;
            }

            private static void BuildRoadGraph()
            {
                _roadNodes.Clear();
                _roadGrid.Clear();

                int roadCount = 0, steep = 0;
                foreach (PathList list in TerrainMeta.Path.Roads)
                {
                    if (list?.Path?.Points == null || list.Path.Points.Length < 2) continue;
                    roadCount++;
                    RoadClass roadClass = ClassOf(list);

                    int prevIndex = -1;
                    int firstIndex = -1;
                    float acc = RoadNodeStep;
                    Vector3[] pts = list.Path.Points;
                    for (int i = 0; i < pts.Length; i++)
                    {
                        if (i > 0) acc += Vector3.Distance(pts[i - 1], pts[i]);
                        if (acc < RoadNodeStep && i != pts.Length - 1) continue;
                        acc = 0f;

                        RoadNode node = new RoadNode { Pos = pts[i], Class = roadClass, Road = roadCount };
                        int index = _roadNodes.Count;
                        _roadNodes.Add(node);
                        if (firstIndex < 0) { firstIndex = index; node.IsEnd = true; }
                        if (i == pts.Length - 1) node.IsEnd = true;
                        if (prevIndex >= 0 && RoadLinkTooSteep(_roadNodes[prevIndex].Pos, node.Pos))
                        {
                            _roadNodes[prevIndex].IsEnd = true;
                            node.IsEnd = true;
                            steep++;
                        }
                        else if (prevIndex >= 0)
                        {
                            node.Links.Add(prevIndex);
                            _roadNodes[prevIndex].Links.Add(index);
                        }
                        prevIndex = index;

                        int key = CellKey(node.Pos);
                        if (!_roadGrid.TryGetValue(key, out List<int> cell)) _roadGrid[key] = cell = new List<int>();
                        cell.Add(index);
                    }
                }

                int junctions = 0, rejected = 0;
                for (int i = 0; i < _roadNodes.Count; i++)
                {
                    RoadNode a = _roadNodes[i];
                    foreach (int j in NodesAround(a.Pos, RoadJunction))
                    {
                        if (j <= i) continue;
                        if (_roadNodes[j].Road == a.Road || a.Links.Contains(j)) continue;
                        if (Vector3.Distance(a.Pos, _roadNodes[j].Pos) > RoadJunction) continue;
                        if (!SegmentPassable(a.Pos, _roadNodes[j].Pos, out _)) { rejected++; continue; }
                        a.Links.Add(j);
                        _roadNodes[j].Links.Add(i);
                        junctions++;
                    }
                }
                int stitched = 0;
                List<int> candidates = new List<int>();
                for (int i = 0; i < _roadNodes.Count; i++)
                {
                    RoadNode a = _roadNodes[i];
                    if (!a.IsEnd) continue;
                    candidates.Clear();
                    foreach (int j in NodesAround(a.Pos, RoadEndStitch))
                    {
                        if (j == i || _roadNodes[j].Road == a.Road || a.Links.Contains(j)) continue;
                        if ((_roadNodes[j].Pos - a.Pos).sqrMagnitude > RoadEndStitch * RoadEndStitch) continue;
                        candidates.Add(j);
                    }
                    if (candidates.Count == 0) continue;
                    candidates.Sort((x, y) => (_roadNodes[x].Pos - a.Pos).sqrMagnitude
                                              .CompareTo((_roadNodes[y].Pos - a.Pos).sqrMagnitude));
                    int best = -1;
                    for (int k = 0; k < candidates.Count && k < 4; k++)
                    {
                        if (SegmentPassable(a.Pos, _roadNodes[candidates[k]].Pos, out _)) { best = candidates[k]; break; }
                        rejected++;
                    }
                    if (best < 0) continue;
                    a.Links.Add(best);
                    _roadNodes[best].Links.Add(i);
                    stitched++;
                }

                int components = 0, biggest = 0;
                bool[] seen = new bool[_roadNodes.Count];
                List<int> stack = new List<int>();
                for (int i = 0; i < _roadNodes.Count; i++)
                {
                    if (seen[i]) continue;
                    int component = components++;
                    int size = 0;
                    stack.Clear();
                    stack.Add(i);
                    seen[i] = true;
                    while (stack.Count > 0)
                    {
                        int cur = stack[stack.Count - 1];
                        stack.RemoveAt(stack.Count - 1);
                        _roadNodes[cur].Component = component;
                        size++;
                        List<int> links = _roadNodes[cur].Links;
                        for (int k = 0; k < links.Count; k++)
                        {
                            if (seen[links[k]]) continue;
                            seen[links[k]] = true;
                            stack.Add(links[k]);
                        }
                    }
                    if (size > biggest) biggest = size;
                }
            }

            private static bool RoadLinkTooSteep(Vector3 a, Vector3 b)
            {
                float run = Vector2.Distance(new Vector2(a.x, a.z), new Vector2(b.x, b.z));
                if (run < 0.5f) return false;
                float rise = Mathf.Abs(TerrainMeta.HeightMap.GetHeight(b) - TerrainMeta.HeightMap.GetHeight(a));
                return Mathf.Atan2(rise, run) * Mathf.Rad2Deg > RouteMaxSlope;
            }

            private static IEnumerable<int> NodesAround(Vector3 p, float radius)
            {
                int steps = Mathf.CeilToInt(radius / RoadCell);
                int cx = Mathf.FloorToInt(p.x / RoadCell);
                int cz = Mathf.FloorToInt(p.z / RoadCell);
                for (int dx = -steps; dx <= steps; dx++)
                {
                    for (int dz = -steps; dz <= steps; dz++)
                    {
                        if (!_roadGrid.TryGetValue((cx + dx) * 100000 + (cz + dz), out List<int> cell)) continue;
                        for (int i = 0; i < cell.Count; i++) yield return cell[i];
                    }
                }
            }

            private static int NearestRoadNode(Vector3 p, float maxDist, int component = -1, RoadClass roads = RoadClass.All)
            {
                int best = -1;
                float bestSqr = maxDist * maxDist;
                foreach (int i in NodesAround(p, maxDist))
                {
                    if (component >= 0 && _roadNodes[i].Component != component) continue;
                    if ((_roadNodes[i].Class & roads) == 0) continue;
                    float sqr = (_roadNodes[i].Pos - p).sqrMagnitude;
                    if (sqr < bestSqr) { bestSqr = sqr; best = i; }
                }
                return best;
            }

            private static bool FindRoadPair(Vector3 from, Vector3 to, float maxDist, out int a, out int b,
                                             RoadClass roads = RoadClass.All)
            {
                a = b = -1;
                float bestOffRoad = float.MaxValue;
                List<int> tried = new List<int>();
                for (int attempt = 0; attempt < 6; attempt++)
                {
                    int candidate = -1;
                    float bestSqr = maxDist * maxDist;
                    foreach (int i in NodesAround(from, maxDist))
                    {
                        if (tried.Contains(_roadNodes[i].Component)) continue;
                        if ((_roadNodes[i].Class & roads) == 0) continue;
                        float sqr = (_roadNodes[i].Pos - from).sqrMagnitude;
                        if (sqr < bestSqr) { bestSqr = sqr; candidate = i; }
                    }
                    if (candidate < 0) break;

                    int component = _roadNodes[candidate].Component;
                    tried.Add(component);
                    int atTarget = NearestRoadNode(to, maxDist, component, roads);
                    if (atTarget < 0) continue;
                    float offRoad = Vector3.Distance(from, _roadNodes[candidate].Pos) + Vector3.Distance(to, _roadNodes[atTarget].Pos);
                    if (offRoad >= bestOffRoad) continue;
                    bestOffRoad = offRoad;
                    a = candidate;
                    b = atTarget;
                }
                return a >= 0;
            }

            private static List<Vector3> RoadPath(int from, int to, RoadClass roads = RoadClass.All)
            {
                List<Vector3> result = RoadPathCore(from, to, roads, out int expanded);
                return result;
            }

            private static float[] _roadBest = new float[0];
            private static int[] _roadCameFrom = new int[0];
            private static readonly MinHeap<int> _roadOpen = new MinHeap<int>();

            private static List<Vector3> RoadPathCore(int from, int to, RoadClass roads, out int expanded)
            {
                expanded = 0;
                List<Vector3> result = new List<Vector3>();
                int count = _roadNodes.Count;
                if (from < 0 || to < 0 || from >= count || to >= count) return result;
                if (from == to) { result.Add(_roadNodes[to].Pos); return result; }

                if (_roadBest.Length < count)
                {
                    _roadBest = new float[count];
                    _roadCameFrom = new int[count];
                }
                for (int i = 0; i < count; i++)
                {
                    _roadBest[i] = float.MaxValue;
                    _roadCameFrom[i] = -1;
                }
                _roadOpen.Clear();

                Vector3 goal = _roadNodes[to].Pos;
                _roadBest[from] = 0f;
                _roadOpen.Push(Vector3.Distance(_roadNodes[from].Pos, goal), from);

                while (_roadOpen.Count > 0)
                {
                    int current = _roadOpen.Pop(out float score);
                    if (score > _roadBest[current] + Vector3.Distance(_roadNodes[current].Pos, goal) + 0.01f) continue;
                    expanded++;

                    if (current == to)
                    {
                        for (int walk = to; walk != from; walk = _roadCameFrom[walk]) result.Add(_roadNodes[walk].Pos);
                        result.Reverse();
                        return result;
                    }

                    RoadNode node = _roadNodes[current];
                    for (int i = 0; i < node.Links.Count; i++)
                    {
                        int next = node.Links[i];
                        if ((_roadNodes[next].Class & roads) == 0) continue;
                        float cost = _roadBest[current] + Vector3.Distance(node.Pos, _roadNodes[next].Pos);
                        if (_roadBest[next] <= cost) continue;
                        _roadBest[next] = cost;
                        _roadCameFrom[next] = current;
                        _roadOpen.Push(cost + Vector3.Distance(_roadNodes[next].Pos, goal), next);
                    }
                }
                return result;
            }

            public static List<Vector3> BuildRoute(Vector3 from, Vector3 to, bool byWater, out string how, float draft = 1.5f)
            {
                List<Vector3> result = BuildRoute(from, to, byWater, draft, out RouteInfo info);
                how = info.How;
                return result;
            }

            public static List<Vector3> BuildRoute(Vector3 from, Vector3 to, bool byWater, float draft, out RouteInfo info)
            {
                info = new RouteInfo();
                return BuildRouteMetered(from, to, byWater, draft, RoutePreference.Auto, RoadClass.All, info);
            }

            public static List<Vector3> BuildRoute(Vector3 from, Vector3 to, RoutePreference preference, RoadClass roads,
                                                   out RouteInfo info)
            {
                info = new RouteInfo();
                return BuildRouteMetered(from, to, false, 1.5f, preference, roads, info);
            }

            public static List<Vector3> RoadRoute(Vector3 from, Vector3 to, RoadClass roads = RoadClass.All, float snap = 300f)
            {
                EnsureRoads();
                List<Vector3> result = new List<Vector3>();
                if (!FindRoadPair(from, to, snap, out int a, out int b, roads)) return result;
                result.Add(_roadNodes[a].Pos);
                if (a == b) return result;
                List<Vector3> road = RoadPath(a, b, roads);
                if (road.Count == 0) result.Clear();
                else result.AddRange(road);
                return result;
            }

            private static List<Vector3> BuildRouteMetered(Vector3 from, Vector3 to, bool byWater, float draft,
                                                           RoutePreference preference, RoadClass roads, RouteInfo info)
            {
                EnsureRoads();
                List<Vector3> result = BuildRouteCore(from, to, byWater, draft, preference, roads, info);
                return result;
            }

            private static List<Vector3> BuildRouteCore(Vector3 from, Vector3 to, bool byWater, float draft,
                                                        RoutePreference preference, RoadClass roads, RouteInfo info)
            {
                List<Vector3> route = new List<Vector3>();
                string how = "direct";
                if (byWater)
                {
                    route.AddRange(WaterRoute(from, to, draft));
                    info.NoWaterRoute = _waterRouteNotFound;
                    info.How = route.Count > 1 ? $"by water around land, {route.Count} points"
                        : _waterRouteNotFound ? "direct by water (no water route found)" : "direct by water";
                    return route;
                }
                if (_roadNodes.Count == 0 || Vector3.Distance(from, to) < 80f || _pass.SnowOnly)
                {
                    route.AddRange(CrossCountry(from, to, ref how));
                    info.How = how;
                    info.Cost = LegCost(from, route, out info.EntryImpassable);
                    return route;
                }
                if (!FindRoadPair(from, to, 300f, out int a, out int b, roads))
                {
                    route.AddRange(CrossCountry(from, to, ref how));
                    info.How = how + " (no roads nearby)";
                    info.Cost = LegCost(from, route, out info.EntryImpassable);
                    return route;
                }
                List<Vector3> road = RoadPath(a, b, roads);
                if (road.Count == 0)
                {
                    route.AddRange(CrossCountry(from, to, ref how));
                    info.How = how + " (no road route)";
                    info.Cost = LegCost(from, route, out info.EntryImpassable);
                    return route;
                }
                string toRoad = "", fromRoad = "";
                int recorded = _landRecord?.Count ?? 0;
                List<Vector3> legIn = CrossCountry(from, _roadNodes[a].Pos, ref toRoad);
                List<Vector3> legOut = CrossCountry(road[road.Count - 1], to, ref fromRoad);
                bool roadCostKnown = _landRecord == null || _landRecord.Count == recorded;

                float roadLength = 0f;
                Vector3 prev = _roadNodes[a].Pos;
                for (int i = 0; i < road.Count; i++)
                {
                    roadLength += Vector3.Distance(prev, road[i]);
                    prev = road[i];
                }
                float roadCost = LegCost(from, legIn, out int badIn) + roadLength
                                 + LegCost(road[road.Count - 1], legOut, out int badOut);
                route.AddRange(legIn);
                route.AddRange(road);
                route.AddRange(legOut);

                if (preference == RoutePreference.Auto && roadCostKnown && Vector3.Distance(from, to) * OffRoadCostFactor < roadCost)
                {
                    List<Vector3> direct = LandRoute(from, to, out int directCells);
                    int directBad = 0;
                    float directCost = direct.Count > 0 ? RouteCost(from, direct, out directBad) : float.MaxValue;
                    if (directCost < float.MaxValue && directCost * OffRoadCostFactor < roadCost)
                    {
                        info.EntryImpassable = directBad;
                        info.How = string.Format("cross-country around the road, {0} points (cost {1:0} vs {2:0} by road, cells {3})",
                            direct.Count, directCost, roadCost, directCells);
                        info.Cost = directCost;
                        return direct;
                    }
                }

                int bad = badIn + badOut;
                info.EntryImpassable = badIn;
                info.ExitImpassable = badOut;
                info.ExitFrom = road[road.Count - 1];
                info.ByRoad = true;
                info.Cost = roadCost;
                info.How = string.Format("by road, {0} nodes, cost {1:0}{2} (entry {3}, exit {4})",
                    road.Count, roadCost, bad > 0 ? $", impassable entry and exit segments {bad}" : "", toRoad, fromRoad);
                return route;
            }

            private static float LegCost(Vector3 from, List<Vector3> leg, out int impassable)
            {
                impassable = 0;
                return leg.Count == 0 ? 0f : RouteCost(from, leg, out impassable);
            }

            private static float RouteCost(Vector3 from, List<Vector3> path, out int impassable)
            {
                float cost = RouteCostCore(from, path, out impassable);
                return cost;
            }

            private static float RouteCostCore(Vector3 from, List<Vector3> path, out int impassable)
            {
                impassable = 0;
                if (path == null || path.Count == 0) return float.MaxValue;

                float total = 0f;
                Vector3 prev = from;
                for (int i = 0; i < path.Count; i++)
                {
                    total += Vector3.Distance(prev, path[i]);
                    if (!SegmentPassable(prev, path[i], out _)) impassable++;
                    prev = path[i];
                }
                return total + impassable * ImpassablePenalty;
            }

            private const float ImpassablePenalty = 200f;

            private static List<Vector3> CrossCountry(Vector3 from, Vector3 to, ref string how)
            {
                if (Vector3.Distance(from, to) > 25f && !SegmentPassable(from, to, out _))
                {
                    Vector3 goal = LandReachableGoal(from, to);
                    List<Vector3> planned = LandRoute(from, goal, out int expanded);
                    if (planned.Count > 0)
                    {
                        how = string.Format("cross-country, {0} points (cells {1}){2}", planned.Count, expanded,
                            goal == to ? "" : $", to the nearest enterable cell {Vector3.Distance(goal, to):0} m from the target");
                        return planned;
                    }
                    how = string.Format("direct with detour (planning failed, cells {0})", expanded);
                    return PassableLeg(from, to);
                }

                List<Vector3> leg = PassableLeg(from, to);
                how = leg.Count > 1 ? "direct with detour" : "direct";
                return leg;
            }

            #endregion

            #region Маршрут по бездорожью

            #region Память мест, где вставали

            private struct StuckSpot
            {
                public Vector3 Pos;
                public float Until;
            }

            private static readonly List<StuckSpot> _stuckSpots = new List<StuckSpot>();

            private const float StuckSpotMemory = 90f;

            private const float StuckSpotRadius = 14f;

            private const float StuckSpotPenalty = 120f;

            public static void RememberStuckSpot(Vector3 pos)
            {
                for (int i = _landReady.Count - 1; i >= 0; i--)
                {
                    LandSearch ready = _landReady[i];
                    if (pos.x > ready.Min.x - StuckSpotRadius && pos.x < ready.Max.x + StuckSpotRadius
                        && pos.z > ready.Min.z - StuckSpotRadius && pos.z < ready.Max.z + StuckSpotRadius) _landReady.RemoveAt(i);
                }
                for (int i = 0; i < _stuckSpots.Count; i++)
                {
                    if (Vector3.Distance(_stuckSpots[i].Pos, pos) > StuckSpotRadius * 0.5f) continue;
                    _stuckSpots[i] = new StuckSpot { Pos = pos, Until = UnityEngine.Time.time + StuckSpotMemory };
                    return;
                }
                _stuckSpots.Add(new StuckSpot { Pos = pos, Until = UnityEngine.Time.time + StuckSpotMemory });
            }

            private static float StuckPenaltyAt(Vector3 pos)
            {
                float penalty = 0f;
                for (int i = _stuckSpots.Count - 1; i >= 0; i--)
                {
                    if (UnityEngine.Time.time >= _stuckSpots[i].Until) { _stuckSpots.RemoveAt(i); continue; }
                    if (Vector3.Distance(_stuckSpots[i].Pos, pos) < StuckSpotRadius) penalty += StuckSpotPenalty;
                }
                return penalty;
            }

            #endregion

            private static float LandCell => _pass.Cell;

            private const float LandMargin = 200f;

            private const int LandNodeLimit = 6000;

            public static List<Vector3> LandRoute(Vector3 from, Vector3 to, out int expanded) => LandRoute(from, to, LandMargin, out expanded);

            public static List<Vector3> LandRoute(Vector3 from, Vector3 to, float margin, out int expanded)
            {
                List<Vector3> result = LandRouteCore(from, to, margin, out expanded);
                return result;
            }

            public static IEnumerator LandRouteSteps(Vector3 from, Vector3 to, float frameBudgetMs) => LandRouteSteps(from, to, frameBudgetMs, LandMargin);

            public static IEnumerator LandRouteSteps(Vector3 from, Vector3 to, float frameBudgetMs, float margin)
            {
                LandSearch search = StartLandSearch(from, to, margin);
                if (search == null) yield break;
                while (!AdvanceLandSearch(search, frameBudgetMs)) yield return null;
            }

            private sealed class LandSearch
            {
                public Vector3 From, To, Min, Max;
                public float Margin;
                public PassProfile Profile;
                public long StartKey, GoalKey;
                public int Expanded;
                public bool Done;
                public float DoneAt;
                public bool OutOfCells;
                public readonly List<Vector3> Cells = new List<Vector3>();
                public bool Smoothing;
                public readonly List<Vector3> Raw = new List<Vector3>();
                public readonly List<Vector3> Result = new List<Vector3>();
                public Vector3 SmoothAnchor;
                public int SmoothI, SmoothK;
                public readonly Dictionary<long, float> Best = new Dictionary<long, float>();
                public readonly Dictionary<long, long> CameFrom = new Dictionary<long, long>();
                public readonly Dictionary<long, float> Score = new Dictionary<long, float>();
                public readonly MinHeap<long> Open = new MinHeap<long>();
            }

            private static readonly LandSearch _landNow = new LandSearch();

            private const float LandReadyLife = 30f;
            private const int LandReadyLimit = 16;
            private static readonly List<LandSearch> _landReady = new List<LandSearch>();

            private static List<KeyValuePair<Vector3, Vector3>> _landRecord;

            public static List<KeyValuePair<Vector3, Vector3>> CollectLandRequests(Action plan)
            {
                List<KeyValuePair<Vector3, Vector3>> requests = new List<KeyValuePair<Vector3, Vector3>>();
                _landRecord = requests;
                try { plan(); }
                finally { _landRecord = null; }
                return requests;
            }

            private static LandSearch StartLandSearch(Vector3 from, Vector3 to, float margin = LandMargin)
            {
                if (FindLandReady(from, to, margin) != null) return null;
                LandSearch search = new LandSearch();
                LandBegin(search, from, to, margin);
                return search;
            }

            private static bool AdvanceLandSearch(LandSearch search, float budgetMs)
            {
                if (search.Done) return true;
                long started = Timestamp();
                bool done = LandStep(search, started + (long)(budgetMs * System.Diagnostics.Stopwatch.Frequency / 1000d));
                if (!done) return false;
                for (int i = _landReady.Count - 1; i >= 0; i--)
                    if (UnityEngine.Time.time - _landReady[i].DoneAt > LandReadyLife) _landReady.RemoveAt(i);
                if (_landReady.Count >= LandReadyLimit) _landReady.RemoveAt(0);
                _landReady.Add(search);
                return true;
            }

            private const int LandReadyShift = 4;

            private const int LandOutOfCellsShift = 10;

            private static bool _landShiftAllowed;

            private static LandSearch FindLandReady(Vector3 from, Vector3 to, float margin)
            {
                int sx = Mathf.FloorToInt(from.x / LandCell), sz = Mathf.FloorToInt(from.z / LandCell);
                long goalKey = LandKey(Mathf.FloorToInt(to.x / LandCell), Mathf.FloorToInt(to.z / LandCell));
                float now = UnityEngine.Time.time;
                LandSearch best = null;
                int bestShift = int.MaxValue;
                for (int i = _landReady.Count - 1; i >= 0; i--)
                {
                    LandSearch ready = _landReady[i];
                    if (ready.GoalKey != goalKey || now - ready.DoneAt > LandReadyLife || Mathf.Abs(ready.Margin - margin) > 0.5f
                        || !ready.Profile.Equals(_pass)) continue;
                    LandUnkey(ready.StartKey, out int rx, out int rz);
                    int shift = Mathf.Max(Mathf.Abs(rx - sx), Mathf.Abs(rz - sz));
                    if (ready.OutOfCells ? shift > Mathf.Max(LandOutOfCellsShift, _landShiftAllowed ? LandReadyShift : 0)
                        : _landShiftAllowed ? shift > LandReadyShift : (from - ready.From).sqrMagnitude > 0.25f) continue;
                    if (shift >= bestShift) continue;
                    best = ready;
                    bestShift = shift;
                }
                return best;
            }

            private const int LandRebaseLook = 3;

            private static List<Vector3> LandRouteCore(Vector3 from, Vector3 to, float margin, out int expanded)
            {
                LandSearch search = FindLandReady(from, to, margin);
                if (search == null && _landRecord != null)
                {
                    _landRecord.Add(new KeyValuePair<Vector3, Vector3>(from, to));
                    expanded = 0;
                    return new List<Vector3>();
                }
                if (search == null)
                {
                    search = _landNow;
                    LandBegin(search, from, to, margin);
                    LandStep(search, long.MaxValue);
                }
                expanded = search.Expanded;
                List<Vector3> result = new List<Vector3>(search.Result);
                if (result.Count == 0) return result;
                if ((to - search.To).sqrMagnitude > 0.25f) result[result.Count - 1] = to;
                if ((from - search.From).sqrMagnitude > 0.25f)
                {
                    for (int k = Mathf.Min(LandRebaseLook, result.Count - 1); k > 0; k--)
                    {
                        if (!SegmentPassable(from, result[k], out _)) continue;
                        result.RemoveRange(0, k);
                        break;
                    }
                }
                return result;
            }

            private static void LandBegin(LandSearch s, Vector3 from, Vector3 to, float margin)
            {
                s.From = from;
                s.To = to;
                s.Margin = margin;
                s.Profile = _pass;
                s.Expanded = 0;
                s.Done = false;
                s.OutOfCells = false;
                s.Smoothing = false;
                s.Cells.Clear();
                s.Raw.Clear();
                s.Result.Clear();
                s.Best.Clear();
                s.CameFrom.Clear();
                s.Score.Clear();
                s.Open.Clear();
                s.Min = Vector3.Min(from, to) - new Vector3(margin, 0f, margin);
                s.Max = Vector3.Max(from, to) + new Vector3(margin, 0f, margin);

                int startX = Mathf.FloorToInt(from.x / LandCell), startZ = Mathf.FloorToInt(from.z / LandCell);
                int goalX = Mathf.FloorToInt(to.x / LandCell), goalZ = Mathf.FloorToInt(to.z / LandCell);
                s.StartKey = LandKey(startX, startZ);
                s.GoalKey = LandKey(goalX, goalZ);
                bool nextToGoal = Mathf.Abs(startX - goalX) <= _pass.EndpointReach && Mathf.Abs(startZ - goalZ) <= _pass.EndpointReach;
                if (s.StartKey == s.GoalKey || !(LandGoalEnterable(goalX, goalZ, to)
                                                 || (nextToGoal && (SegmentPassable(from, LandCentre(goalX, goalZ), out _) || SegmentPassable(from, to, out _)))))
                {
                    s.Done = true;
                    s.DoneAt = UnityEngine.Time.time;
                    return;
                }
                s.Best[s.StartKey] = 0f;
                s.Score[s.StartKey] = Vector3.Distance(from, to);
                s.Open.Push(s.Score[s.StartKey], s.StartKey);
            }

            private static bool LandStep(LandSearch s, long deadline)
            {
                if (s.Done) return true;
                using (PassAs(s.Profile)) return LandStepCore(s, deadline);
            }

            private static bool LandStepCore(LandSearch s, long deadline)
            {
                if (s.Smoothing) return SmoothStep(s, deadline);
                while (s.Open.Count > 0 && s.Expanded < LandNodeLimit)
                {
                    if (deadline != long.MaxValue && Timestamp() >= deadline) return false;
                    long current = s.Open.Pop(out float popped);
                    if (popped > s.Score[current] + 0.01f) continue;
                    s.Expanded++;

                    if (current == s.GoalKey)
                    {
                        long node = current;
                        while (s.CameFrom.TryGetValue(node, out long parent))
                        {
                            LandUnkey(node, out int x, out int z);
                            s.Cells.Add(LandCentre(x, z));
                            node = parent;
                        }
                        s.Cells.Reverse();
                        BeginSmoothing(s);
                        return SmoothStep(s, deadline);
                    }

                    LandUnkey(current, out int cx, out int cz);
                    Vector3 centre = current == s.StartKey ? s.From : LandCentre(cx, cz);
                    int reach = current == s.StartKey ? s.Profile.EndpointReach : 1;

                    for (int dx = -reach; dx <= reach; dx++)
                    {
                        for (int dz = -reach; dz <= reach; dz++)
                        {
                            if (dx == 0 && dz == 0) continue;
                            int nx = cx + dx, nz = cz + dz;
                            Vector3 next = LandCentre(nx, nz);
                            if (next.x < s.Min.x || next.x > s.Max.x || next.z < s.Min.z || next.z > s.Max.z) continue;

                            long nextKey = LandKey(nx, nz);
                            float step = Vector3.Distance(centre, next) + StuckPenaltyAt(next);
                            if (s.Profile.SnowOnly) step += OffSnow(centre, next, out _, out _) * OffSnowCost;
                            float tentative = s.Best[current] + step;
                            if (s.Best.TryGetValue(nextKey, out float known) && tentative >= known) continue;

                            if (!SegmentPassable(centre, next, out _)
                                && !(nextKey == s.GoalKey && SegmentPassable(centre, s.To, out _))) continue;

                            s.Best[nextKey] = tentative;
                            s.CameFrom[nextKey] = current;
                            float nextScore = tentative + Vector3.Distance(next, s.To);
                            s.Score[nextKey] = nextScore;
                            s.Open.Push(nextScore, nextKey);
                        }
                    }
                    LinkToGoalFrom(s, current, cx, cz, centre);
                }
                s.OutOfCells = s.Expanded >= LandNodeLimit;
                s.Done = true;
                s.DoneAt = UnityEngine.Time.time;
                return true;
            }

            private static void LinkToGoalFrom(LandSearch s, long current, int cx, int cz, Vector3 centre)
            {
                if (s.Profile.EndpointReach <= 1 || current == s.GoalKey) return;
                LandUnkey(s.GoalKey, out int gx, out int gz);
                int ring = Mathf.Max(Mathf.Abs(cx - gx), Mathf.Abs(cz - gz));
                if (ring < 2 || ring > s.Profile.EndpointReach) return;
                float tentative = s.Best[current] + Vector3.Distance(centre, s.To);
                if (s.Best.TryGetValue(s.GoalKey, out float known) && tentative >= known) return;
                if (!SegmentPassable(centre, s.To, out _)) return;
                s.Best[s.GoalKey] = tentative;
                s.CameFrom[s.GoalKey] = current;
                s.Score[s.GoalKey] = tentative;
                s.Open.Push(tentative, s.GoalKey);
            }

            private static bool LandGoalEnterable(int goalX, int goalZ, Vector3 to)
            {
                Vector3 goal = LandCentre(goalX, goalZ);
                int reach = _pass.EndpointReach;
                for (int dx = -reach; dx <= reach; dx++)
                {
                    for (int dz = -reach; dz <= reach; dz++)
                    {
                        if (dx == 0 && dz == 0) continue;
                        Vector3 centre = LandCentre(goalX + dx, goalZ + dz);
                        bool neighbour = Mathf.Abs(dx) <= 1 && Mathf.Abs(dz) <= 1;
                        if ((neighbour && SegmentPassable(centre, goal, out _)) || SegmentPassable(centre, to, out _)) return true;
                    }
                }
                return false;
            }

            private const float LandGoalShift = 120f;

            private static Vector3 LandReachableGoal(Vector3 from, Vector3 to)
            {
                int goalX = Mathf.FloorToInt(to.x / LandCell), goalZ = Mathf.FloorToInt(to.z / LandCell);
                int startX = Mathf.FloorToInt(from.x / LandCell), startZ = Mathf.FloorToInt(from.z / LandCell);
                if (Mathf.Abs(startX - goalX) <= _pass.EndpointReach && Mathf.Abs(startZ - goalZ) <= _pass.EndpointReach) return to;
                if (LandGoalEnterable(goalX, goalZ, to)) return to;
                Vector3 back = from - to;
                back.y = 0f;
                float length = Mathf.Min(back.magnitude - LandCell * (_pass.EndpointReach + 1), LandGoalShift);
                back.Normalize();
                Vector3 side = new Vector3(-back.z, 0f, back.x) * LandCell;
                for (float d = LandCell; d <= length; d += LandCell)
                {
                    Vector3 onLine = to + back * d;
                    for (int k = 0; k < 3; k++)
                    {
                        Vector3 probe = k == 0 ? onLine : onLine + side * (k == 1 ? 1f : -1f);
                        int x = Mathf.FloorToInt(probe.x / LandCell), z = Mathf.FloorToInt(probe.z / LandCell);
                        if (x == goalX && z == goalZ) continue;
                        Vector3 centre = LandCentre(x, z);
                        if (WaterLevel.GetOverallWaterDepth(centre, waves: false, volumes: true) > _pass.WaterDepth) continue;
                        if (LandGoalEnterable(x, z, centre)) return centre;
                    }
                }
                return to;
            }

            private static long LandKey(int x, int z) => ((long)x << 32) ^ (uint)z;

            private static void LandUnkey(long key, out int x, out int z)
            {
                x = (int)(key >> 32);
                z = (int)(key & 0xFFFFFFFF);
            }

            private static Vector3 LandCentre(int x, int z)
            {
                Vector3 p = new Vector3((x + 0.5f) * LandCell, 0f, (z + 0.5f) * LandCell);
                p.y = TerrainMeta.HeightMap.GetHeight(p);
                return p;
            }

            private static void BeginSmoothing(LandSearch s)
            {
                List<Vector3> raw = s.Raw;
                raw.Clear();
                raw.AddRange(s.Cells);
                if (raw.Count >= 1 && !SegmentPassable(raw.Count >= 2 ? raw[raw.Count - 2] : s.From, raw[raw.Count - 1], out _)) raw.RemoveAt(raw.Count - 1);
                raw.Add(s.To);
                s.Result.Clear();
                s.SmoothAnchor = s.From;
                s.SmoothI = 0;
                s.SmoothK = raw.Count - 1;
                s.Smoothing = true;
            }

            private static bool SmoothStep(LandSearch s, long deadline)
            {
                List<Vector3> raw = s.Raw;
                while (s.SmoothI < raw.Count)
                {
                    while (s.SmoothK >= s.SmoothI)
                    {
                        if (deadline != long.MaxValue && Timestamp() >= deadline) return false;
                        if (SegmentPassable(s.SmoothAnchor, raw[s.SmoothK], out _)) break;
                        s.SmoothK--;
                    }
                    int furthest = Mathf.Max(s.SmoothK, s.SmoothI);
                    s.Result.Add(raw[furthest]);
                    s.SmoothAnchor = raw[furthest];
                    s.SmoothI = furthest + 1;
                    s.SmoothK = raw.Count - 1;
                }
                s.Smoothing = false;
                s.Done = true;
                s.DoneAt = UnityEngine.Time.time;
                return true;
            }

            #endregion

            #region Маршрут по бездорожью в полосе вокруг пути

            public static float LandBandWeight = 1.2f;
            public static int LandBandNodeLimit = 2000;
            public static float LandBandMonumentCost = 1.5f;
            private const int LandBandSmoothCells = 10, LandBandWidenBack = 8, LandBandWidenAhead = 16, LandBandFringeSpan = 2, LandBandCheckFactor = 4;

            private struct LandEdge
            {
                public long Cell, Parent;
                public float G;
            }

            private sealed class LandBand
            {
                public float[] Widths;
                public readonly List<Vector3> Samples = new List<Vector3>();
                public int[] Level;
                public readonly Dictionary<long, int> Cells = new Dictionary<long, int>();
                public readonly HashSet<long> Fringe = new HashSet<long>();
                public int Reach;
                public int Widenings, PaintAt;
                public readonly List<int> Paint = new List<int>();
            }

            private sealed class LandBandSearch
            {
                public Vector3 From, To, Min, Max;
                public long StartKey, GoalKey;
                public Func<Vector3, Vector3, bool> Passable;
                public float Weight;
                public int NodeLimit;
                public LandBand Band;
                public readonly Dictionary<long, float> G = new Dictionary<long, float>();
                public readonly Dictionary<long, long> Parent = new Dictionary<long, long>();
                public readonly Dictionary<long, bool> Monument = new Dictionary<long, bool>();
                public readonly MinHeap<LandEdge> Open = new MinHeap<LandEdge>();
                public int Expanded, Checks;
                public bool GoalDirect, Found, Done, Smoothing;
                public readonly List<Vector3> Raw = new List<Vector3>();
                public readonly List<Vector3> Result = new List<Vector3>();
                public Vector3 Anchor;
                public int SmoothI, SmLo, SmHi, SmStep, SmCap;
            }

            public static IEnumerator LandRouteSteps(Vector3 from, Vector3 to, float frameBudgetMs, List<Vector3> corridor, float[] widths,
                                                     Func<Vector3, Vector3, bool> passable, List<Vector3> result, int[] stats)
            {
                result?.Clear();
                if (widths == null || widths.Length == 0) widths = new[] { LandMargin };
                LandBandSearch s = new LandBandSearch
                {
                    From = from, To = to, Passable = passable, Weight = LandBandWeight, NodeLimit = LandBandNodeLimit,
                    StartKey = LandKey(Mathf.FloorToInt(from.x / LandCell), Mathf.FloorToInt(from.z / LandCell)),
                    GoalKey = LandKey(Mathf.FloorToInt(to.x / LandCell), Mathf.FloorToInt(to.z / LandCell))
                };
                bool painting = false;
                if (corridor != null && corridor.Count > 0)
                {
                    s.Band = LandBandFor(from, corridor, to, widths);
                    painting = true;
                }
                else
                {
                    Vector3 margin = new Vector3(widths[widths.Length - 1], 0f, widths[widths.Length - 1]);
                    s.Min = Vector3.Min(from, to) - margin;
                    s.Max = Vector3.Max(from, to) + margin;
                    s.NodeLimit = LandNodeLimit;
                }
                long started = Timestamp();
                long deadline = LandDeadline(started, frameBudgetMs);
                bool begun = false;
                while (true)
                {
                    if (painting)
                    {
                        if (!LandBandPaint(s.Band, deadline))
                        {
                            yield return null;
                            started = Timestamp();
                            deadline = LandDeadline(started, frameBudgetMs);
                            continue;
                        }
                        painting = false;
                        if (begun) LandBandRepush(s);
                    }
                    if (!begun)
                    {
                        LandBandBegin(s);
                        begun = true;
                    }
                    if (LandBandStep(s, deadline))
                    {
                        if (s.Found || s.Band == null || s.Band.Fringe.Count == 0 || s.Expanded >= s.NodeLimit
                            || s.Checks >= s.NodeLimit * LandBandCheckFactor || !LandBandWiden(s)) break;
                        painting = true;
                        continue;
                    }
                    yield return null;
                    started = Timestamp();
                    deadline = LandDeadline(started, frameBudgetMs);
                }
                result?.AddRange(s.Result);
                if (stats != null && stats.Length >= 4)
                {
                    stats[0] = s.Expanded;
                    stats[1] = s.Band != null ? s.Band.Widenings : 0;
                    stats[2] = s.Checks;
                    int level = 0;
                    if (s.Band != null)
                        for (int i = 0; i < s.Band.Level.Length; i++) level = Mathf.Max(level, s.Band.Level[i]);
                    stats[3] = Mathf.RoundToInt(widths[s.Band != null ? level : widths.Length - 1]);
                }
            }

            public static List<Vector3> LandRoute(Vector3 from, Vector3 to, List<Vector3> corridor, float[] widths, Func<Vector3, Vector3, bool> passable,
                                                  out int expanded)
            {
                List<Vector3> result = new List<Vector3>();
                int[] stats = new int[4];
                IEnumerator steps = LandRouteSteps(from, to, float.PositiveInfinity, corridor, widths, passable, result, stats);
                while (steps.MoveNext()) { }
                expanded = stats[0];
                return result;
            }

            private static long LandDeadline(long started, float budgetMs)
                => budgetMs >= 1e6f ? long.MaxValue : started + (long)(budgetMs * System.Diagnostics.Stopwatch.Frequency / 1000d);

            private static bool LandBandPass(LandBandSearch s, Vector3 a, Vector3 b)
            {
                s.Checks++;
                return s.Passable != null ? s.Passable(a, b) : SegmentPassable(a, b, out _);
            }

            private static Vector3 LandCentre(long key)
            {
                LandUnkey(key, out int x, out int z);
                return LandCentre(x, z);
            }

            private static LandBand LandBandFor(Vector3 from, List<Vector3> corridor, Vector3 to, float[] widths)
            {
                LandBand band = new LandBand { Widths = widths };
                Vector3 prev = from;
                band.Samples.Add(from);
                for (int i = 0; i <= corridor.Count; i++)
                {
                    Vector3 next = i < corridor.Count ? corridor[i] : to;
                    Vector3 flat = next - prev;
                    flat.y = 0f;
                    float length = flat.magnitude;
                    if (length < 0.5f) continue;
                    int pieces = Mathf.Max(1, Mathf.CeilToInt(length / LandCell));
                    for (int k = 1; k <= pieces; k++) band.Samples.Add(Vector3.Lerp(prev, next, (float)k / pieces));
                    prev = next;
                }
                band.Level = new int[band.Samples.Count];
                HelperMonuments monuments = LandBandMonumentCost > 1f && widths.Length > 1 ? HelperMonuments.Instance : null;
                for (int i = 0; i < band.Samples.Count; i++)
                {
                    if (monuments != null && monuments.HasMonument(band.Samples[i])) band.Level[i] = 1;
                    band.Paint.Add(i);
                }
                return band;
            }

            private static bool LandBandPaint(LandBand band, long deadline)
            {
                while (band.PaintAt < band.Paint.Count)
                {
                    if (deadline != long.MaxValue && Timestamp() >= deadline) return false;
                    int index = band.Paint[band.PaintAt++];
                    Vector3 p = band.Samples[index];
                    float reach = band.Widths[band.Level[index]] + LandCell * 0.5f, reach2 = reach * reach;
                    int x0 = Mathf.FloorToInt((p.x - reach) / LandCell), x1 = Mathf.FloorToInt((p.x + reach) / LandCell);
                    int z0 = Mathf.FloorToInt((p.z - reach) / LandCell), z1 = Mathf.FloorToInt((p.z + reach) / LandCell);
                    for (int x = x0; x <= x1; x++)
                    {
                        float dx = (x + 0.5f) * LandCell - p.x;
                        for (int z = z0; z <= z1; z++)
                        {
                            float dz = (z + 0.5f) * LandCell - p.z, d2 = dx * dx + dz * dz;
                            if (d2 > reach2) continue;
                            long key = LandKey(x, z);
                            if (band.Cells.TryGetValue(key, out int other) && other != index)
                            {
                                Vector3 q = band.Samples[other];
                                float ox = (x + 0.5f) * LandCell - q.x, oz = (z + 0.5f) * LandCell - q.z;
                                if (ox * ox + oz * oz <= d2) continue;
                            }
                            band.Cells[key] = index;
                        }
                    }
                }
                band.Paint.Clear();
                band.PaintAt = 0;
                return true;
            }

            private static bool LandBandWiden(LandBandSearch s)
            {
                LandBand band = s.Band;
                int top = band.Widths.Length - 1, last = band.Samples.Count - 1;
                int lo = Mathf.Max(0, band.Reach - LandBandWidenBack), hi = Mathf.Min(last, band.Reach + LandBandWidenAhead);
                for (int i = lo; i <= hi; i++)
                {
                    if (band.Level[i] >= top) continue;
                    band.Level[i]++;
                    band.Paint.Add(i);
                }
                if (band.Paint.Count == 0)
                {
                    HashSet<int> raise = new HashSet<int>();
                    foreach (long key in band.Fringe)
                    {
                        if (!band.Cells.TryGetValue(key, out int sample)) continue;
                        for (int i = Mathf.Max(0, sample - LandBandFringeSpan); i <= Mathf.Min(last, sample + LandBandFringeSpan); i++)
                            if (band.Level[i] < top) raise.Add(i);
                    }
                    foreach (int i in raise)
                    {
                        band.Level[i]++;
                        band.Paint.Add(i);
                    }
                }
                if (band.Paint.Count == 0) return false;
                band.Widenings++;
                s.Done = false;
                return true;
            }

            private static void LandBandRepush(LandBandSearch s)
            {
                List<long> fringe = new List<long>(s.Band.Fringe);
                s.Band.Fringe.Clear();
                foreach (long key in fringe)
                    LandBandExpand(s, key, key == s.StartKey ? s.From : LandCentre(key), s.G[key]);
            }

            private static void LandBandBegin(LandBandSearch s)
            {
                if (s.StartKey == s.GoalKey)
                {
                    s.Done = true;
                    return;
                }
                s.G[s.StartKey] = 0f;
                s.Expanded = 1;
                LandBandExpand(s, s.StartKey, s.From, 0f);
            }

            private static bool LandBandInMonument(LandBandSearch s, long key, Vector3 point)
            {
                if (LandBandMonumentCost <= 1f || HelperMonuments.Instance == null) return false;
                if (!s.Monument.TryGetValue(key, out bool inside)) s.Monument[key] = inside = HelperMonuments.Instance.HasMonument(point);
                return inside;
            }

            private static void LandBandExpand(LandBandSearch s, long key, Vector3 centre, float g)
            {
                LandUnkey(key, out int cx, out int cz);
                LandBand band = s.Band;
                for (int dx = -1; dx <= 1; dx++)
                {
                    for (int dz = -1; dz <= 1; dz++)
                    {
                        if (dx == 0 && dz == 0) continue;
                        int nx = cx + dx, nz = cz + dz;
                        long next = LandKey(nx, nz);
                        if (s.G.ContainsKey(next)) continue;
                        if (band != null && !band.Cells.ContainsKey(next))
                        {
                            band.Fringe.Add(key);
                            continue;
                        }
                        Vector3 point = LandCentre(nx, nz);
                        if (band == null && (point.x < s.Min.x || point.x > s.Max.x || point.z < s.Min.z || point.z > s.Max.z)) continue;
                        float step = Vector3.Distance(centre, point);
                        if (band != null && LandBandInMonument(s, next, point)) step *= LandBandMonumentCost;
                        float ng = g + step + StuckPenaltyAt(point);
                        s.Open.Push(ng + s.Weight * Vector3.Distance(point, s.To), new LandEdge { Cell = next, Parent = key, G = ng });
                    }
                }
            }

            private static bool LandBandStep(LandBandSearch s, long deadline)
            {
                if (s.Done) return true;
                if (s.Smoothing) return LandBandSmooth(s, deadline);
                while (s.Open.Count > 0 && s.Expanded < s.NodeLimit && s.Checks < s.NodeLimit * LandBandCheckFactor)
                {
                    if (deadline != long.MaxValue && Timestamp() >= deadline) return false;
                    LandEdge edge = s.Open.Pop(out _);
                    if (s.G.ContainsKey(edge.Cell)) continue;
                    Vector3 centre = LandCentre(edge.Cell);
                    Vector3 from = edge.Parent == s.StartKey ? s.From : LandCentre(edge.Parent);
                    bool direct = false;
                    if (!LandBandPass(s, from, centre))
                    {
                        if (edge.Cell != s.GoalKey || !LandBandPass(s, from, s.To)) continue;
                        direct = true;
                    }
                    s.G[edge.Cell] = edge.G;
                    s.Parent[edge.Cell] = edge.Parent;
                    s.Expanded++;
                    if (s.Band != null && s.Band.Cells.TryGetValue(edge.Cell, out int sample) && sample > s.Band.Reach) s.Band.Reach = sample;
                    if (edge.Cell == s.GoalKey)
                    {
                        s.GoalDirect = direct;
                        s.Found = true;
                        LandBandPath(s);
                        return LandBandSmooth(s, deadline);
                    }
                    LandBandExpand(s, edge.Cell, centre, edge.G);
                }
                s.Done = true;
                return true;
            }

            private static void LandBandPath(LandBandSearch s)
            {
                List<Vector3> raw = s.Raw;
                raw.Clear();
                long node = s.GoalKey;
                while (node != s.StartKey && s.Parent.TryGetValue(node, out long parent))
                {
                    raw.Add(LandCentre(node));
                    node = parent;
                }
                raw.Reverse();
                if (raw.Count > 0)
                {
                    Vector3 prev = raw.Count >= 2 ? raw[raw.Count - 2] : s.From;
                    if (s.GoalDirect || (!LandBandPass(s, raw[raw.Count - 1], s.To) && LandBandPass(s, prev, s.To))) raw.RemoveAt(raw.Count - 1);
                }
                raw.Add(s.To);
                s.Result.Clear();
                s.Anchor = s.From;
                s.SmoothI = 0;
                s.SmCap = -1;
                s.Smoothing = true;
            }

            private static bool LandBandSmooth(LandBandSearch s, long deadline)
            {
                List<Vector3> raw = s.Raw;
                while (s.SmoothI < raw.Count)
                {
                    if (s.SmCap < 0)
                    {
                        s.SmLo = s.SmoothI;
                        s.SmHi = -1;
                        s.SmStep = 1;
                        s.SmCap = Mathf.Min(raw.Count - 1, s.SmoothI + LandBandSmoothCells - 1);
                    }
                    while (s.SmHi < 0 && s.SmLo < s.SmCap)
                    {
                        if (deadline != long.MaxValue && Timestamp() >= deadline) return false;
                        int j = Mathf.Min(s.SmoothI + s.SmStep, s.SmCap);
                        if (LandBandPass(s, s.Anchor, raw[j]))
                        {
                            s.SmLo = j;
                            s.SmStep *= 2;
                        }
                        else s.SmHi = j;
                    }
                    while (s.SmHi >= 0 && s.SmHi - s.SmLo > 1)
                    {
                        if (deadline != long.MaxValue && Timestamp() >= deadline) return false;
                        int mid = (s.SmLo + s.SmHi) / 2;
                        if (LandBandPass(s, s.Anchor, raw[mid])) s.SmLo = mid;
                        else s.SmHi = mid;
                    }
                    s.Result.Add(raw[s.SmLo]);
                    s.Anchor = raw[s.SmLo];
                    s.SmoothI = s.SmLo + 1;
                    s.SmCap = -1;
                }
                s.Smoothing = false;
                s.Done = true;
                return true;
            }

            #endregion

            #region Маршрут по воде

            private const float WaterCell = 12f;

            private const float WaterMargin = 150f;

            private const float WaterNavDepth = 1.5f;

            private static float _routeDraft = WaterNavDepth;

            private const int WaterCellsLimit = 90;

            private const float WaterMarginWide = 600f;

            private const float WaterRelaxDepth = 0.5f;

            private const float WaterShoreCost = 1f;

            private const float WaterLineStep = 5f, WaterLineSide = 10f;

            private const float WaterFirstLeg = 40f;

            private static bool _waterRouteNotFound;

            public static List<Vector3> WaterRoute(Vector3 from, Vector3 to, float draft)
            {
                List<Vector3> result = WaterRouteCore(from, to, draft);
                return result;
            }

            private static List<Vector3> WaterRouteCore(Vector3 from, Vector3 to, float draft)
            {
                _routeDraft = Mathf.Max(WaterNavDepth, draft);
                _waterRouteNotFound = false;
                List<Vector3> result = new List<Vector3>();
                if (WaterLineClear(from, to))
                {
                    result.Add(to);
                    return result;
                }
                float relaxed = Mathf.Max(WaterNavDepth, _routeDraft - WaterRelaxDepth), margin = WaterMargin;
                while (!WaterGridRoute(from, to, margin, result, out bool edge))
                {
                    if (edge && margin < WaterMarginWide) margin = WaterMarginWide;
                    else if (_routeDraft > relaxed) _routeDraft = relaxed;
                    else
                    {
                        _waterRouteNotFound = true;
                        result.Add(to);
                        break;
                    }
                }
                return result;
            }

            private static bool WaterGridRoute(Vector3 from, Vector3 to, float margin, List<Vector3> result, out bool edge)
            {
                edge = false;
                float minX = Mathf.Min(from.x, to.x) - margin;
                float maxX = Mathf.Max(from.x, to.x) + margin;
                float minZ = Mathf.Min(from.z, to.z) - margin;
                float maxZ = Mathf.Max(from.z, to.z) + margin;

                float cell = WaterCell;
                int cols = Mathf.CeilToInt((maxX - minX) / cell) + 1;
                int rows = Mathf.CeilToInt((maxZ - minZ) / cell) + 1;
                if (cols > WaterCellsLimit || rows > WaterCellsLimit)
                {
                    cell = Mathf.Max((maxX - minX) / WaterCellsLimit, (maxZ - minZ) / WaterCellsLimit);
                    cols = Mathf.CeilToInt((maxX - minX) / cell) + 1;
                    rows = Mathf.CeilToInt((maxZ - minZ) / cell) + 1;
                }
                _waterMinX = minX;
                _waterMinZ = minZ;
                _waterCellSize = cell;
                _waterCols = cols;
                _waterRows = rows;
                int size = cols * rows;
                if (_waterCells.Length < size) _waterCells = new byte[size];
                else System.Array.Clear(_waterCells, 0, size);

                int startIdx = CellIndex(from, minX, minZ, cell, cols, rows);
                int goalIdx = CellIndex(to, minX, minZ, cell, cols, rows);
                if (startIdx < 0 || goalIdx < 0) return false;
                _waterCells[startIdx] = WaterCellOpenState;
                _waterCells[goalIdx] = WaterCellOpenState;
                if (!WaterCellHasExit(startIdx) || !WaterCellHasExit(goalIdx)) return false;

                List<int> path = WaterAStar(startIdx, goalIdx, out edge);
                if (path.Count == 0) return false;

                List<Vector3> points = new List<Vector3>(path.Count + 1);
                foreach (int index in path) points.Add(WaterCellPoint(index));
                points.Add(to);

                Vector3 cursor = from;
                for (int at = -1; at < points.Count - 1;)
                {
                    int far = at + 1;
                    while (far + 1 < points.Count && (at >= 0 || WaterFlat(from, points[far + 1]) <= WaterFirstLeg) && WaterCellsClear(cursor, points[far + 1])) far++;
                    while (far > at + 1 && !WaterLineClear(cursor, points[far])) far = at + 1 + (far - at - 1) / 2;
                    result.Add(points[far]);
                    cursor = points[far];
                    at = far;
                }
                return true;
            }

            private static bool WaterLineClear(Vector3 a, Vector3 b)
            {
                Vector3 dir = b - a;
                dir.y = 0f;
                float total = dir.magnitude;
                if (total < 1f) return true;
                dir /= total;
                Vector3 side = new Vector3(dir.z, 0f, -dir.x) * WaterLineSide, half = side * 0.5f;
                for (float d = WaterCell * 0.5f; d < total; d += WaterLineStep)
                {
                    Vector3 p = a + dir * d;
                    if (WaterDepth(p) < _routeDraft || WaterDepth(p + half) < _routeDraft || WaterDepth(p - half) < _routeDraft
                        || WaterDepth(p + side) < _routeDraft || WaterDepth(p - side) < _routeDraft) return false;
                }
                return !WaterObstacleAlong(a, b);
            }

            private static float WaterFlat(Vector3 a, Vector3 b) => new Vector2(a.x - b.x, a.z - b.z).magnitude;

            private static float WaterDepth(Vector3 p)
            {
                p.y = TerrainMeta.HeightMap.GetHeight(p);
                return WaterLevel.GetOverallWaterDepth(p, waves: false, volumes: true);
            }

            private static readonly int WaterObstacleMask = LayerMask.GetMask("World", "Construction", "Deployed", "Default", "Vehicle Large", "Prevent Movement");
            private static readonly Collider[] WaterObstacleOverlaps = new Collider[16];
            private static readonly RaycastHit[] WaterObstacleCasts = new RaycastHit[16];
            private static BaseEntity _waterIgnore;
            private static float _waterHull = 3f;

            private static float WaterSurfaceAt(Vector3 p) => WaterLevel.GetWaterSurface(new Vector3(p.x, TerrainMeta.HeightMap.GetHeight(p), p.z), false, true);

            private static bool IsOwnWaterHit(Collider collider)
            {
                BaseEntity entity = collider != null ? collider.ToBaseEntity() : null;
                if (entity == null) return false;
                if (entity is BasePlayer) return true;
                return _waterIgnore != null && (entity == _waterIgnore || entity.GetParentEntity() == _waterIgnore);
            }

            private static bool WaterObstacleAt(Vector3 p, float radius)
            {
                Vector3 center = new Vector3(p.x, WaterSurfaceAt(p) + 1f, p.z);
                int count = Physics.OverlapSphereNonAlloc(center, radius, WaterObstacleOverlaps, WaterObstacleMask, QueryTriggerInteraction.Ignore);
                for (int i = 0; i < count; i++)
                    if (!IsOwnWaterHit(WaterObstacleOverlaps[i])) return true;
                return false;
            }

            private static bool WaterObstacleAlong(Vector3 a, Vector3 b)
            {
                Vector3 dir = b - a;
                dir.y = 0f;
                float length = dir.magnitude;
                if (length < 1f) return false;
                dir /= length;
                Vector3 origin = new Vector3(a.x, WaterSurfaceAt(a) + 1f, a.z);
                int count = Physics.SphereCastNonAlloc(origin, _waterHull, dir, WaterObstacleCasts, length, WaterObstacleMask, QueryTriggerInteraction.Ignore);
                for (int i = 0; i < count; i++)
                {
                    if (WaterObstacleCasts[i].distance <= 0f || IsOwnWaterHit(WaterObstacleCasts[i].collider)) continue;
                    return true;
                }
                return false;
            }

            private const byte WaterCellUnknown = 0, WaterCellOpenState = 1, WaterCellBlocked = 2;
            private static byte[] _waterCells = new byte[0];
            private static float _waterMinX, _waterMinZ, _waterCellSize;
            private static int _waterCols, _waterRows;

            private static Vector3 WaterCellPoint(int index)
            {
                Vector3 p = new Vector3(_waterMinX + index % _waterCols * _waterCellSize, 0f, _waterMinZ + index / _waterCols * _waterCellSize);
                p.y = TerrainMeta.HeightMap.GetHeight(p);
                return p;
            }

            private static bool WaterCellOpen(int index)
            {
                byte state = _waterCells[index];
                if (state == WaterCellUnknown)
                {
                    Vector3 point = WaterCellPoint(index);
                    state = WaterLevel.GetOverallWaterDepth(point, waves: false, volumes: true) >= _routeDraft
                            && !WaterObstacleAt(point, Mathf.Clamp(_waterCellSize * 0.3f, _waterHull, 8f)) ? WaterCellOpenState : WaterCellBlocked;
                    _waterCells[index] = state;
                }
                return state == WaterCellOpenState;
            }

            private static bool WaterNeighbor(int index, bool open)
            {
                int c = index % _waterCols, r = index / _waterCols;
                for (int dr = -1; dr <= 1; dr++)
                {
                    for (int dc = -1; dc <= 1; dc++)
                    {
                        if (dr == 0 && dc == 0) continue;
                        int nc = c + dc, nr = r + dr;
                        if (nc < 0 || nr < 0 || nc >= _waterCols || nr >= _waterRows) continue;
                        if (WaterCellOpen(nr * _waterCols + nc) == open) return true;
                    }
                }
                return false;
            }

            private static bool WaterCellHasExit(int index) => WaterNeighbor(index, true);

            private static bool WaterCellsClear(Vector3 a, Vector3 b)
            {
                Vector3 dir = b - a;
                dir.y = 0f;
                float total = dir.magnitude;
                if (total < 1f) return true;
                dir /= total;
                float step = _waterCellSize * 0.5f;
                for (float d = step; d < total; d += step)
                {
                    int index = CellIndex(a + dir * d, _waterMinX, _waterMinZ, _waterCellSize, _waterCols, _waterRows);
                    if (index < 0 || !WaterCellOpen(index)) return false;
                }
                return true;
            }

            private static int CellIndex(Vector3 p, float minX, float minZ, float cell, int cols, int rows)
            {
                int c = Mathf.RoundToInt((p.x - minX) / cell);
                int r = Mathf.RoundToInt((p.z - minZ) / cell);
                if (c < 0 || r < 0 || c >= cols || r >= rows) return -1;
                return r * cols + c;
            }

            private static float[] _gridBest = new float[0];
            private static int[] _gridCameFrom = new int[0];
            private static readonly MinHeap<int> _gridOpen = new MinHeap<int>();

            private static float GridHeuristic(int dc, int dr)
            {
                dc = Mathf.Abs(dc);
                dr = Mathf.Abs(dr);
                return Mathf.Max(dc, dr) + 0.41f * Mathf.Min(dc, dr);
            }

            private static List<int> WaterAStar(int start, int goal, out bool edge)
            {
                edge = false;
                int cols = _waterCols, rows = _waterRows;
                List<int> result = new List<int>();
                int size = cols * rows;
                if (_gridBest.Length < size)
                {
                    _gridBest = new float[size];
                    _gridCameFrom = new int[size];
                }
                for (int i = 0; i < size; i++)
                {
                    _gridBest[i] = float.MaxValue;
                    _gridCameFrom[i] = -1;
                }
                _gridOpen.Clear();

                int goalC = goal % cols, goalR = goal / cols;
                _gridBest[start] = 0f;
                _gridOpen.Push(GridHeuristic(start % cols - goalC, start / cols - goalR), start);

                while (_gridOpen.Count > 0)
                {
                    int current = _gridOpen.Pop(out float popped);
                    float h = GridHeuristic(current % cols - goalC, current / cols - goalR);
                    if (popped > _gridBest[current] + h + 0.01f) continue;

                    if (current == goal)
                    {
                        for (int walk = goal; walk != start; walk = _gridCameFrom[walk]) result.Add(walk);
                        result.Reverse();
                        return result;
                    }

                    int cc = current % cols, cr = current / cols;
                    if (cc == 0 || cr == 0 || cc == cols - 1 || cr == rows - 1) edge = true;
                    for (int dr = -1; dr <= 1; dr++)
                    {
                        for (int dc = -1; dc <= 1; dc++)
                        {
                            if (dr == 0 && dc == 0) continue;
                            int nc = cc + dc, nr = cr + dr;
                            if (nc < 0 || nr < 0 || nc >= cols || nr >= rows) continue;
                            int next = nr * cols + nc;
                            if (!WaterCellOpen(next)) continue;
                            float step = (dr != 0 && dc != 0) ? 1.41f : 1f;
                            if (next != goal && WaterNeighbor(next, false)) step *= 1f + WaterShoreCost;
                            float cost = _gridBest[current] + step;
                            if (_gridBest[next] <= cost) continue;
                            _gridBest[next] = cost;
                            _gridCameFrom[next] = current;
                            _gridOpen.Push(cost + GridHeuristic(nc - goalC, nr - goalR), next);
                        }
                    }
                }
                return result;
            }

            #endregion

            #region Проходимость маршрута

            private const float RouteProbeStep = 5f;

            private const float RouteWaterStep = 1f;

            private const float RouteMaxSlope = 35f;

            private static int RouteObstacleMask => _routeObstacleMask != 0 ? _routeObstacleMask
                : _routeObstacleMask = LayerMask.GetMask("World", "Construction", "Deployed", "Default", "Tree", "Transparent");

            private static int DeckMask => _deckMask != 0 ? _deckMask
                : _deckMask = LayerMask.GetMask("Terrain", "World", "Construction", "Deployed", "Default");

            private static int _routeObstacleMask, _deckMask;

            public readonly struct PassProfile : IEquatable<PassProfile>
            {
                public readonly float HalfWidth;

                public readonly float Cell;

                public readonly int EndpointReach;

                public readonly bool SnowOnly;

                public readonly float WaterDepth;

                public PassProfile(float halfWidth, float cell, int endpointReach, float waterDepth = LandWaterLimitStatic, bool snowOnly = false)
                {
                    HalfWidth = halfWidth;
                    Cell = cell;
                    EndpointReach = endpointReach;
                    WaterDepth = waterDepth;
                    SnowOnly = snowOnly;
                }

                public static readonly PassProfile Car = new PassProfile(1.3f, 12f, 1);

                public static readonly PassProfile Horse = new PassProfile(0.7f, 8f, 2);

                public static readonly PassProfile Snowmobile = new PassProfile(1.3f, 12f, 1, 0.3f);

                public static readonly PassProfile SnowmobileOnSnow = new PassProfile(1.3f, 12f, 1, 0.3f, true);

                public bool Equals(PassProfile other) => HalfWidth == other.HalfWidth && Cell == other.Cell && EndpointReach == other.EndpointReach
                                                         && WaterDepth == other.WaterDepth && SnowOnly == other.SnowOnly;
                public override bool Equals(object obj) => obj is PassProfile other && Equals(other);
                public override int GetHashCode() => HalfWidth.GetHashCode() ^ (Cell.GetHashCode() * 397) ^ (EndpointReach * 7919) ^ (WaterDepth.GetHashCode() * 31)
                                                     ^ (SnowOnly ? 1 << 20 : 0);
            }

            private const float SnowCrossing = 20f;

            private const float OffSnowCost = 3f;

            private const float SnowProbeStep = 2f;

            private static bool[] _snowSplats;

            public static bool SnowmobileGround(Vector3 point)
            {
                TerrainPhysics physics = TerrainMeta.Physics;
                if (physics == null || physics.splat == null || physics.materials.Length == 0) return false;
                if (_snowSplats == null || _snowSplats.Length != physics.materials.Length)
                {
                    _snowSplats = new bool[physics.materials.Length];
                    for (int i = 0; i < _snowSplats.Length; i++)
                    {
                        string name = physics.materials[i] != null ? physics.materials[i].GetNameLower() : null;
                        _snowSplats[i] = name == "snow" || name == "sand";
                    }
                }
                return _snowSplats[physics.splat.GetSplatMaxIndex(point)] && !TerrainMeta.TopologyMap.GetTopology(point, TerrainTopology.ROAD);
            }

            private static float OffSnow(Vector3 from, Vector3 to, out float longestRun, out Vector3 runEnd)
            {
                float length = CoreEx.DistanceFlat(from, to);
                int steps = Mathf.Max(1, Mathf.CeilToInt(length / SnowProbeStep));
                float step = length / steps, total = 0f, run = 0f;
                longestRun = 0f;
                runEnd = to;
                for (int i = 1; i <= steps; i++)
                {
                    Vector3 p = Vector3.Lerp(from, to, (float)i / steps);
                    if (SnowmobileGround(p))
                    {
                        run = 0f;
                        continue;
                    }
                    total += step;
                    run += step;
                    if (run <= longestRun) continue;
                    longestRun = run;
                    runEnd = p;
                }
                return total;
            }

            public static float OffSnowLength(Vector3 from, List<Vector3> route)
            {
                float total = 0f;
                Vector3 prev = from;
                for (int i = 0; i < route.Count; i++)
                {
                    total += OffSnow(prev, route[i], out _, out _);
                    prev = route[i];
                }
                return total;
            }

            private const float RouteCorridorHalfHeight = 0.7f, RouteCorridorHalfDepth = 0.05f;

            private static PassProfile _pass = PassProfile.Car;

            public static PassScope PassAs(PassProfile profile) => new PassScope(profile);

            public readonly struct PassScope : IDisposable
            {
                private readonly PassProfile _previous;

                public PassScope(PassProfile profile)
                {
                    _previous = _pass;
                    _pass = profile;
                }

                public void Dispose() => _pass = _previous;
            }

            private static readonly RaycastHit[] _routeHits = new RaycastHit[32];

            private const float RouteTopProbe = 100f;

            private const float RouteStepUp = 0.5f;

            private static bool OnVehicle(Collider collider)
            {
                BaseEntity entity = collider != null ? collider.ToBaseEntity() : null;
                for (int depth = 0; depth < 4 && entity != null; depth++)
                {
                    entity = entity.GetParentEntity();
                    if (entity is BaseVehicle) return true;
                }
                return false;
            }

            private static bool IsRoadSurface(Collider collider)
            {
                if (collider == null) return false;
                string name = collider.name;
                return name.StartsWith("Road Mesh", StringComparison.Ordinal)
                       || name.StartsWith("Rail Mesh", StringComparison.Ordinal);
            }

            private static bool DeckAt(Vector3 point, float level, out float deckY)
            {
                deckY = level;
                Vector3 top = new Vector3(point.x, level + 2.5f, point.z);
                if (!Physics.Raycast(top, Vector3.down, out RaycastHit hit, 5f, DeckMask, QueryTriggerInteraction.Ignore))
                    return false;
                if (hit.normal.y < 0.8f || hit.point.y < TerrainMeta.HeightMap.GetHeight(point) + 0.3f) return false;
                deckY = hit.point.y;
                return true;
            }

            public static float PassabilityMemorySeconds = 30f;

            private struct PassMemory
            {
                public bool Passable;
                public Vector3 BlockedAt;
                public float Until;
            }

            private static readonly Dictionary<long, PassMemory> _passCache = new Dictionary<long, PassMemory>();

            private static readonly Dictionary<PassProfile, Dictionary<long, PassMemory>> _passCacheByProfile = new Dictionary<PassProfile, Dictionary<long, PassMemory>>();

            private static Dictionary<long, PassMemory> PassCacheFor(PassProfile profile)
            {
                if (profile.Equals(PassProfile.Car)) return _passCache;
                if (!_passCacheByProfile.TryGetValue(profile, out Dictionary<long, PassMemory> cache))
                    _passCacheByProfile[profile] = cache = new Dictionary<long, PassMemory>();
                return cache;
            }

            private const int PassCacheLimit = 60000;

            private static long PassKey(Vector3 a, Vector3 b)
            {
                long ax = (Mathf.RoundToInt(a.x * 4f) + 32768) & 0xFFFF;
                long az = (Mathf.RoundToInt(a.z * 4f) + 32768) & 0xFFFF;
                long bx = (Mathf.RoundToInt(b.x * 4f) + 32768) & 0xFFFF;
                long bz = (Mathf.RoundToInt(b.z * 4f) + 32768) & 0xFFFF;
                return (ax << 48) | (az << 32) | (bx << 16) | bz;
            }

            private static bool PassKeyFits(Vector3 p) => Mathf.Abs(p.x) < 8000f && Mathf.Abs(p.z) < 8000f;

            public static bool SegmentPassable(Vector3 from, Vector3 to, out Vector3 blockedAt)
            {
                if (PassabilityMemorySeconds <= 0f || !PassKeyFits(from) || !PassKeyFits(to))
                    return SegmentPassableCore(from, to, out blockedAt);

                long key = PassKey(from, to);
                float now = UnityEngine.Time.time;
                Dictionary<long, PassMemory> passCache = PassCacheFor(_pass);
                if (passCache.TryGetValue(key, out PassMemory memory) && now < memory.Until)
                {
                    blockedAt = memory.Passable ? to : memory.BlockedAt;
                    return memory.Passable;
                }

                bool passable = SegmentPassableCore(from, to, out blockedAt);
                if (passCache.Count >= PassCacheLimit) passCache.Clear();
                passCache[key] = new PassMemory { Passable = passable, BlockedAt = blockedAt, Until = now + PassabilityMemorySeconds };
                return passable;
            }

            public static string ExplainSegment(Vector3 from, Vector3 to)
            {
                System.Text.StringBuilder why = new System.Text.StringBuilder();
                return SegmentPassableCore(from, to, out _, why) ? null : why.ToString();
            }

            private static bool SegmentPassableCore(Vector3 from, Vector3 to, out Vector3 blockedAt, System.Text.StringBuilder why = null)
            {
                blockedAt = to;
                float total = Vector3.Distance(from, to);
                if (total < 1f) return true;
                if (_pass.SnowOnly)
                {
                    OffSnow(from, to, out float run, out Vector3 runEnd);
                    if (run > SnowCrossing)
                    {
                        blockedAt = runEnd;
                        why?.AppendFormat("off snow: {0:0} m in a row", run);
                        return false;
                    }
                }
                Vector3 dir = (to - from).normalized;
                Vector3 side = new Vector3(-dir.z, 0f, dir.x).normalized;
                float prevHeight = TerrainMeta.HeightMap.GetHeight(from);
                if (from.y > prevHeight + 0.5f && DeckAt(from, from.y, out float fromDeck)) prevHeight = fromDeck;

                float prevD = 0f, backHeight = prevHeight;
                while (total - prevD > 0.05f)
                {
                    float d = prevD + RouteProbeStep;
                    if (d > total - 0.05f) d = total;
                    int samples = Mathf.CeilToInt((d - prevD) / RouteWaterStep - 0.05f);
                    for (int k = 1; k <= samples; k++)
                    {
                        float w = k == samples ? d : prevD + k * RouteWaterStep;
                        Vector3 c = from + dir * w;
                        Vector3 wet;
                        bool deep = k < samples
                            ? DeepWaterAt(c, prevHeight, out wet)
                            : DeepWaterAt(c + side * _pass.HalfWidth, prevHeight, out wet) || DeepWaterAt(c - side * _pass.HalfWidth, prevHeight, out wet);
                        if (!deep) continue;
                        blockedAt = wet;
                        why?.AppendFormat("water at {0:0.0} m: deep water {1}", w, k < samples ? "between probes" : "at the corridor edge");
                        return false;
                    }
                    Vector3 p = from + dir * d;
                    float h = TerrainMeta.HeightMap.GetHeight(p);
                    p.y = h;

                    float run = Mathf.Min(RouteProbeStep, d);
                    float step = d - prevD;
                    float baseHeight = step >= run - 0.01f ? prevHeight : Mathf.Lerp(prevHeight, backHeight, (run - step) / RouteProbeStep);
                    bool water = WaterLevel.GetOverallWaterDepth(p, waves: false, volumes: true) > _pass.WaterDepth;
                    float slope = Mathf.Atan2(Mathf.Abs(h - baseHeight), run) * Mathf.Rad2Deg;
                    bool onDeck = false;
                    if (water || slope > RouteMaxSlope)
                    {
                        if (!DeckAt(p, prevHeight, out float deck)
                            || Mathf.Atan2(Mathf.Abs(deck - baseHeight), run) * Mathf.Rad2Deg > RouteMaxSlope)
                        {
                            blockedAt = p;
                            why?.AppendFormat("{0} at {1:0.0} m: {2}", water ? "water" : "slope", d, water ? "deep water" : $"terrain slope {slope:0} deg");
                            return false;
                        }
                        h = deck;
                        p.y = h;
                        onDeck = true;
                    }

                    if (!onDeck && Physics.Raycast(new Vector3(p.x, h + RouteTopProbe, p.z), Vector3.down, out RaycastHit top,
                                                   RouteTopProbe + 1f, DeckMask, QueryTriggerInteraction.Ignore)
                        && !(top.collider is TerrainCollider) && !IsRoadSurface(top.collider) && top.point.y - h > RouteStepUp)
                    {
                        blockedAt = top.point;
                        why?.AppendFormat("step at {0:0.0} m: {1} surface {2:0.00} m above terrain", d, top.collider.transform.root.name, top.point.y - h);
                        return false;
                    }

                    Vector3 prevCentre = from + dir * prevD;
                    prevCentre.y = prevHeight + 0.9f;
                    Vector3 nextCentre = new Vector3(p.x, h + 0.9f, p.z);
                    Vector3 leg = nextCentre - prevCentre;
                    float legLength = leg.magnitude;
                    if (legLength > 0.05f)
                    {
                        int hits = Physics.BoxCastNonAlloc(prevCentre, new Vector3(_pass.HalfWidth, RouteCorridorHalfHeight, RouteCorridorHalfDepth),
                                                           leg / legLength, _routeHits,
                                                           Quaternion.LookRotation(leg / legLength), legLength,
                                                           RouteObstacleMask, QueryTriggerInteraction.Ignore);
                        for (int i = 0; i < hits; i++)
                        {
                            RaycastHit obstacle = _routeHits[i];
                            if (obstacle.distance <= 0f || IsRoadSurface(obstacle.collider) || OnVehicle(obstacle.collider)) continue;
                            float ground = Mathf.Max(TerrainMeta.HeightMap.GetHeight(obstacle.point), Mathf.Min(prevHeight, h));
                            float rise = obstacle.point.y - ground;
                            bool steep = Vector3.Angle(obstacle.normal, Vector3.up) >= RouteMaxSlope;
                            if (steep || rise >= 0.4f)
                            {
                                blockedAt = obstacle.point;
                                why?.AppendFormat("obstacle at {0:0.0} m: {1}/{2} layer {3}, rise {4:0.00} m, face {5:0} deg", d, obstacle.collider.transform.root.name,
                                    obstacle.collider.name, LayerMask.LayerToName(obstacle.collider.gameObject.layer), rise, Vector3.Angle(obstacle.normal, Vector3.up));
                                return false;
                            }
                        }
                    }
                    backHeight = prevHeight;
                    prevHeight = h;
                    prevD = d;
                }
                return true;
            }

            private const float LandWaterLimitStatic = 0.5f;

            private static bool DeepWaterAt(Vector3 point, float level, out Vector3 at)
            {
                at = point;
                at.y = TerrainMeta.HeightMap.GetHeight(at);
                return WaterLevel.GetOverallWaterDepth(at, waves: false, volumes: false) > _pass.WaterDepth && !DeckAt(at, level, out _);
            }

            private static List<Vector3> PassableLeg(Vector3 from, Vector3 to)
            {
                List<Vector3> leg = new List<Vector3>();
                if (SegmentPassable(from, to, out _))
                {
                    leg.Add(to);
                    return leg;
                }

                Vector3 flat = to - from;
                flat.y = 0f;
                float half = Mathf.Max(20f, flat.magnitude * 0.5f);
                Vector3 dir = flat.normalized;
                float[] angles = { 25f, -25f, 45f, -45f, 70f, -70f };
                for (int i = 0; i < angles.Length; i++)
                {
                    Vector3 side = from + Quaternion.AngleAxis(angles[i], Vector3.up) * dir * half;
                    side.y = TerrainMeta.HeightMap.GetHeight(side);
                    if (!SegmentPassable(from, side, out _)) continue;
                    if (!SegmentPassable(side, to, out _)) continue;
                    leg.Add(side);
                    leg.Add(to);
                    return leg;
                }

                leg.Add(to);
                return leg;
            }

