            public abstract class VehicleControllerBase : MonoBehaviour
            {
                protected virtual float SteerGain => Tuning?.SteerGain ?? 0.22f;

                protected const float SteerMaxPerFrame = 6f;

                protected virtual float SteerDeadZone => Tuning?.SteerDeadZone ?? 2.5f;

                protected virtual float SteerDamping => Tuning?.SteerDamping ?? -0.06f;

                private float _prevHeadingError;

                protected virtual float DriveInterval => Tuning?.DriveInterval ?? 0f;

                private float _nextDriveAt;
                private float _lastDriveAt;

                protected float TickDelta { get; private set; }

                protected virtual float MountGrace => Tuning?.MountGrace ?? 1.5f;

                private bool _tickedOnce;

                public float DesiredThrottle { get; private set; }
                public float DesiredSteerNormalized { get; private set; }

                protected virtual void OnAttached() { }

                protected virtual void OnReleasing() { }

                protected virtual void OnNewCourse() { }

                protected virtual bool PreDriveTick() => true;

                protected virtual List<Vector3> RouteTo(Vector3 target, out string how)
                {
                    using (PassAs(PassProfile))
                    {
                        List<Vector3> route = BuildRoute(_vehicle.transform.position, target, RoadPreference, Roads, out RouteInfo info);
                        how = info.How;
                        RouteByRoad = info.ByRoad;
                        return route;
                    }
                }

                protected virtual PassProfile PassProfile => PassProfile.Car;

                protected virtual RoutePreference RoadPreference => Tuning?.RoadPreference ?? RoutePreference.Auto;

                protected virtual RoadClass Roads => RoadClass.All;

                public bool RouteByRoad { get; protected set; }

                protected virtual bool KeepToRoad => RouteByRoad;

                protected virtual float RoadCorridor => 5f;

                protected virtual float RoadLeavePenalty => 1.5f;

                protected virtual bool OnGiveUp() => false;

                protected virtual bool PassableHit(Collider collider) => false;

                public Func<Collider, BaseEntity, bool> Rammable { get; set; }
                private bool IsRammable(Collider collider) => Rammable != null && collider != null && Rammable(collider, collider.ToBaseEntity());

                protected const float BrakeSpeedThreshold = 3f;

                protected virtual float SenseExtra => Tuning?.SenseExtra ?? 4f;

                protected virtual float ClimbableSlope => Tuning?.ClimbableSlope ?? 40f;

                protected BaseCustomNpc _bot;
                protected BaseVehicle _vehicle;
                protected BaseMountable _seat;
                protected VehicleProfile _profile;
                protected InputState _input;

