                protected Vector3 FinalGoal => _route.Count > 0 ? _route[_route.Count - 1] : _target;
                protected virtual float FinalApproach => Tuning?.FinalApproach ?? 16f;

                protected virtual bool AvoidsObstacles => true;

                protected virtual bool FlatDistance => false;

                protected virtual float ArriveDistance => Tuning?.ArriveDistance ?? DefaultArriveDistance;

