                protected float _stuckSince;
                protected Vector3 _lastPos;

                protected float MountedAt => _mountedAt;

                public BaseCustomNpc Bot => _bot;
                public BaseVehicle Vehicle => _vehicle;
                public bool HasTarget => _hasTarget;

