                public int NextIndex => _route.Count == 0 ? -1 : Mathf.Min(_routeIndex + 1, _route.Count - 1);

                public Vector3 NextPoint => _route.Count == 0 ? _target : _route[NextIndex];

                public Vector3 AimAt { get; private set; }

                public float DistanceToEnd { get; private set; }

                public float TargetSpeed { get; protected set; }

