                {
                    get => _profile?.CruiseSpeed ?? 0f;
                    set
                    {
                        if (_profile != null && value > 0f) _profile.CruiseSpeed = value;
                    }
                }

                public static VehicleControllerBase CreateFor(BaseCustomNpc bot, BaseVehicle vehicle)
                {
                    if (vehicle is TrainEngine) return bot.gameObject.AddComponent<TrainVehicleController>();
                    if (vehicle is BaseSubmarine) return bot.gameObject.AddComponent<SubmarineController>();
                if (vehicle is AttackHelicopter) return bot.gameObject.AddComponent<AttackHeliController>();
                if (vehicle is BaseHelicopter) return bot.gameObject.AddComponent<AirVehicleController>();
                    if (vehicle is BaseBoat) return bot.gameObject.AddComponent<BoatVehicleController>();
                    if (vehicle is RidableHorse) return bot.gameObject.AddComponent<HorseVehicleController>();
                    return bot.gameObject.AddComponent<GroundVehicleController>();
                }

                public string Take(BaseCustomNpc bot, BaseVehicle vehicle)
                {
                    if (bot == null || !bot.IsValid()) return "bot is missing";
                    if (vehicle == null || vehicle.IsDestroyed) return "vehicle is missing";

                    BaseMountable seat = FindDriverSeat(vehicle);
                    if (seat == null) return "this vehicle has no driver seat";
                    BasePlayer sitting = seat.AnyMounted() ? seat.GetMounted() : null;
                    if (seat.AnyMounted() && sitting != bot)
                        return $"driver seat is already occupied by {(sitting != null ? sitting.displayName : "someone")}";

                    ReleaseRoles(bot, this, "moving to the driver seat");

                    _bot = bot;
                    _botId = bot.userID;
                    _vehicle = vehicle;
                    _profile = VehicleProfile.For(vehicle);
                    _seat = seat;

                    _input = new InputState();

                    if (!_seat.AnyMounted())
                    {
                        _seat.MountPlayer(bot);
                        if (bot.GetMounted() != _seat) return "failed to mount";
                    }

                    CollectOwnColliders();
                    OnAttached();
                    bot.GetComponent<INavigator>()?.Pause();
                    _pilots[_botId] = this;
                    _attached = true;

                    _startedAt = UnityEngine.Time.time;
                    _mountedAt = _startedAt;
                    _lastPos = vehicle.transform.position;
                    _stuckSince = _startedAt;
                    Note(string.Format("{0}: mounted driver seat of {1} ({2}, length {3:0.0} m, width {4:0.0} m)",
                        Debug.Id(bot), vehicle.ShortPrefabName, _profile.Kind,
                        _profile.HalfLength * 2f, _profile.HalfWidth * 2f));
                    return null;
                }

                private const float StopBrakeSpeed = 0.5f;

                public bool Arrived { get; protected set; }

                private float _tripArrive;
                private bool _tripBrake = true;

                private bool _routeGiven;

                private BaseEntity _follow;
                private float _followKeep;

                private const float FollowOvershoot = 12f;

                public BaseEntity FollowTarget => _follow;

                public void DriveTo(Vector3 point) => DriveTo(point, 0f, true);

                public void DriveTo(Vector3 point, float arriveDistance, bool brakeAtEnd = true)
                {
                    OnNewCourse();
                    _tripArrive = arriveDistance;
                    _tripBrake = brakeAtEnd;
                    _follow = null;
                    ResetFollowSearches();
                    _routeGiven = false;
                    Arrived = false;
                    _route.Clear();
                    _routeOrigin = _vehicle != null ? _vehicle.transform.position : point;
                    RouteByRoad = false;
                    _hasWaypoint = false;
                    _hasTarget = true;
                    if (PlanLandByFrames && !FollowRouteReady(point))
                    {
                        _pendingDrive = true;
                        _pendingDriveTo = point;
                        _route.Add(point);
                        _routeIndex = 0;
                        _target = point;
                        ResetProgress();
                        return;
                    }
                    FinishDriveTo(point);
                }

                private float RemainingAlongRoute(Vector3 pos, float straight)
                {
                    if (_route.Count < 2) return straight;
                    int next = Mathf.Clamp(_routeIndex + 1, 0, _route.Count - 1);
                    float sum = Vector2.Distance(new Vector2(pos.x, pos.z), new Vector2(_route[next].x, _route[next].z));
                    for (int k = next; k < _route.Count - 1; k++)
                        sum += Vector2.Distance(new Vector2(_route[k].x, _route[k].z), new Vector2(_route[k + 1].x, _route[k + 1].z));
                    return sum;
                }

                private void FinishDriveTo(Vector3 point)
                {
                    _route.Clear();
                    _route.AddRange(RouteAfterSearches(point, PlanLandByFrames, out string how));
                    _routeIndex = 0;
                    _target = _route.Count > 0 ? _route[0] : point;
                    ResetProgress();
                    Note(string.Format("{0}: target {1}, distance {2:0} m, route {3} ({4} points)",
                        Debug.Id(_bot), point, Vector3.Distance(_vehicle.transform.position, point), how, _route.Count));
                }

                public bool PlanLandByFrames { get; set; }

                private bool _pendingDrive;
                private Vector3 _pendingDriveTo;

                public void SetRoute(IList<Vector3> points, float arriveDistance = 0f, bool brakeAtEnd = true, bool byRoad = false)
                {
                    if (points == null || points.Count == 0) { Halt(); return; }
                    OnNewCourse();
                    _tripArrive = arriveDistance;
                    _tripBrake = brakeAtEnd;
                    _follow = null;
                    ResetFollowSearches();
                    _routeGiven = true;
                    _hasWaypoint = false;
                    Arrived = false;
                    _route.Clear();
                    _route.AddRange(points);
                    _routeOrigin = _vehicle != null ? _vehicle.transform.position : points[0];
                    _routeIndex = 0;
                    _target = _route[0];
                    _hasTarget = true;
                    RouteByRoad = byRoad;
                    ResetProgress();
                    Note(string.Format("{0}: external route assigned, {1} points, distance to end {2:0} m",
                        Debug.Id(_bot), _route.Count, _vehicle != null ? Vector3.Distance(_vehicle.transform.position, _route[_route.Count - 1]) : 0f));
                }

                public void ExtendRoute(IList<Vector3> points)
                {
                    if (points == null || points.Count == 0) return;
                    if (!_hasTarget || _route.Count == 0 || _follow is not null)
                    {
                        SetRoute(points, _tripArrive, _tripBrake, RouteByRoad);
                        return;
                    }
                    _route.AddRange(points);
                    Arrived = false;
                    RouteVersion++;
                    _progressBest = float.MaxValue;
                    _progressAt = UnityEngine.Time.time;
                }

                public void Follow(BaseEntity target, float keepDistance = 0f, float directRange = 0f)
                {
                    if (target == null || target.IsDestroyed || _vehicle == null) return;
                    OnNewCourse();
                    _follow = target;
                    _followKeep = Mathf.Max(0f, keepDistance);
                    _followDirect = Mathf.Max(0f, directRange);
                    _followPlanned = false;
                    _followDirectCheckAt = 0f;
                    ResetFollowSearches();
                    _tripArrive = 0f;
                    _tripBrake = true;
                    _routeGiven = true;
                    _hasWaypoint = false;
                    RouteByRoad = false;
                    Arrived = false;
                    _route.Clear();
                    _route.Add(target.transform.position);
                    _routeOrigin = _vehicle.transform.position;
                    _routeIndex = 0;
                    _target = _route[0];
                    _hasTarget = true;
                    ResetProgress();
                    Note(string.Format("{0}: following {1}, {2}", Debug.Id(_bot), target.ShortPrefabName,
                        _followKeep > 0f ? $"keeping {_followKeep:0} m away" : "through the target"));
                }

                protected virtual float FollowDirectRange => 60f;

                protected virtual float FollowHoldBand => 0f;

                protected virtual bool HoldAtFollow(Vector3 pos, Vector3 target, float distance, float keep) => false;

                protected virtual bool FollowAlwaysStraight => false;

                protected virtual bool FollowLinePassable(Vector3 from, Vector3 to) => SegmentPassable(from, to, out _);

                protected float FollowKeep => _follow != null ? FollowKeepFor(_followKeep) : 0f;

                protected virtual float FollowKeepFor(float keep) => keep;

                private const float FollowReplanShift = 10f;
                private const float FollowReplanInterval = 3f;

                private bool _followPlanned;
                private Vector3 _followPlannedTo;
                private float _followReplanAt;

                private float _followDirect;

                private bool _followDirectOk;
                private float _followDirectCheckAt;

                private bool UpdateFollow(Vector3 pos)
                {
                    if (_follow == null || _follow.IsDestroyed)
                    {
                        Note(string.Format("{0}: follow target disappeared - stopping", Debug.Id(_bot)));
                        Halt();
                        return false;
                    }
                    Vector3 target = _follow.transform.position;
                    Vector3 flat = target - pos;
                    flat.y = 0f;
                    float now = UnityEngine.Time.time;
                    float directRange = _followDirect > 0f ? _followDirect : FollowDirectRange;
                    bool always = FollowAlwaysStraight;
                    bool straight = always || flat.magnitude <= directRange;
                    if (!always && straight && now >= _followDirectCheckAt)
                    {
                        _followDirectCheckAt = now + 1f;
                        _followDirectOk = FollowLinePassable(pos, target);
                    }

                    if (straight && (always || _followDirectOk))
                    {
                        Vector3 point = target;
                        if (_followKeep <= 0f && flat.sqrMagnitude > 1f) point += flat.normalized * FollowOvershoot;
                        _followPlanned = false;
                        _route.Clear();
                        _route.Add(point);
                        _routeIndex = 0;
                        _routeOrigin = pos;
                        return true;
                    }

                    if (!_followPlanned || (target - _followPlannedTo).sqrMagnitude > FollowReplanShift * FollowReplanShift
                        || now >= _followReplanAt)
                    {
                        if (!FollowRouteReady(target)) return true;
                        _followPlanned = true;
                        _followPlannedTo = target;
                        _followReplanAt = now + FollowReplanInterval;
                        List<Vector3> route = RouteAfterSearches(target, true, out _);
                        _route.Clear();
                        if (route.Count > 0) _route.AddRange(route);
                        else _route.Add(target);
                        _routeIndex = 0;
                        _routeOrigin = pos;
                        _nextFanAt = 0f;
                    }
                    return true;
                }

                protected virtual bool FollowSearchesLand => false;

                private const float FollowSearchBudget = 4f;

                private enum FollowSearch { Idle, Running, Ready }
                private FollowSearch _followSearch;
                private readonly List<LandSearch> _followSearches = new List<LandSearch>();

                private bool FollowRouteReady(Vector3 target)
                {
                    if (!FollowSearchesLand) return true;
                    if (_followSearch == FollowSearch.Running) return false;
                    if (_followSearch == FollowSearch.Idle) _followRounds = 0;
                    _followSearch = FollowSearch.Idle;
                    bool shiftWas = _landShiftAllowed;
                    _landShiftAllowed = true;
                    try
                    {
                        while (_followRounds < FollowSearchRounds)
                        {
                            _followSearches.Clear();
                            bool byRoad = RouteByRoad;
                            List<KeyValuePair<Vector3, Vector3>> requests = CollectLandRequests(() => RouteTo(target, out _));
                            RouteByRoad = byRoad;
                            foreach (KeyValuePair<Vector3, Vector3> request in requests)
                            {
                                LandSearch search = StartLandSearch(request.Key, request.Value);
                                if (search != null) _followSearches.Add(search);
                            }
                            if (_followSearches.Count == 0) break;
                            _followRounds++;
                            _followSearch = FollowSearch.Running;
                            AdvanceFollowSearches();
                            if (_followSearch == FollowSearch.Running) return false;
                            _followSearch = FollowSearch.Idle;
                        }
                    }
                    finally { _landShiftAllowed = shiftWas; }
                    _followRounds = 0;
                    return true;
                }

                private List<Vector3> RouteAfterSearches(Vector3 target, bool byFrames, out string how)
                {
                    if (!byFrames || !FollowSearchesLand) return RouteTo(target, out how);
                    bool shiftWas = _landShiftAllowed;
                    _landShiftAllowed = true;
                    try
                    {
                        List<Vector3> route = null;
                        string built = null;
                        CollectLandRequests(() => route = RouteTo(target, out built));
                        how = built;
                        return route;
                    }
                    finally { _landShiftAllowed = shiftWas; }
                }

                private const int FollowSearchRounds = 3;
                private int _followRounds;

                private void AdvanceFollowSearches()
                {
                    long started = Timestamp();
                    for (int i = 0; i < _followSearches.Count; i++)
                    {
                        float left = FollowSearchBudget - (float)((Timestamp() - started) * 1000d / System.Diagnostics.Stopwatch.Frequency);
                        if (left <= 0f || !AdvanceLandSearch(_followSearches[i], left)) return;
                    }
                    _followSearches.Clear();
                    _followSearch = FollowSearch.Ready;
                }

                private void ResetFollowSearches()
                {
                    _followSearches.Clear();
                    _followSearch = FollowSearch.Idle;
                    _pendingDrive = false;
                }

                private void ResetProgress()
                {
                    RouteVersion++;
                    _progressBest = float.MaxValue;
                    _progressAt = UnityEngine.Time.time;
                    _stuckSince = UnityEngine.Time.time;
                    _startedAt = UnityEngine.Time.time;
                    _nextFanAt = 0f;
                }

                public void Halt()
                {
                    _hasTarget = false;
                    _hasWaypoint = false;
                    _follow = null;
                    ResetFollowSearches();
                    _route.Clear();
                    _routeIndex = 0;
                    ApplyInput(0f, 0f, false);
                }

                private ulong _botId;

                private bool _attached;

                private bool _released;

                public void Release(string why)
                {
                    if (_released) return;
                    _released = true;

                    if (_seat != null && _bot != null && _bot.IsValid() && _input != null) ApplyInput(0f, 0f, false);
                    OnReleasing();
                    DropPassengers(why);
                    if (_bot != null && _bot.IsValid() && _bot.isMounted && _bot.GetMounted() == _seat) _bot.DismountSafely();
                    if (_bot != null && _bot.IsValid()) _bot.GetComponent<INavigator>()?.Resume();
                    Unregister();
                    _hasTarget = false;
                    Destroy(this);
                    Note(string.Format("{0}: left vehicle ({1})", Debug.Id(_bot), why));
                }

                private void Unregister()
                {
                    if (_pilots.TryGetValue(_botId, out VehicleControllerBase registered) && registered == this)
                        _pilots.Remove(_botId);
                }

                private void OnDestroy()
                {
                    if (_released || !_attached) return;
                    _released = true;
                    Unregister();
                    if (_vehicle != null && !_vehicle.IsDestroyed) OnReleasing();
                    if (_bot != null && _bot.IsValid()) _bot.GetComponent<INavigator>()?.Resume();
                    DropPassengers("pilot destroyed");
                    Note(string.Format("{0}: pilot destroyed with the bot (bot died or was removed)", _botId));
                }

                private void Update()
                {
                    using (PassAs(PassProfile)) DriveUpdate();
                }

                private void DriveUpdate()
                {
                    if (_released) return;
                    if (_followSearch == FollowSearch.Running) AdvanceFollowSearches();
                    if (_pendingDrive && _followSearch == FollowSearch.Ready && _vehicle != null && FollowRouteReady(_pendingDriveTo))
                    {
                        _pendingDrive = false;
                        FinishDriveTo(_pendingDriveTo);
                    }
                    float now = UnityEngine.Time.time;
                    float interval = DriveInterval;
                    if (interval > 0f)
                    {
                        if (now < _nextDriveAt) return;
                        _nextDriveAt = _nextDriveAt + interval > now ? _nextDriveAt + interval : now + interval;
                    }
                    TickDelta = _lastDriveAt > 0f ? now - _lastDriveAt : UnityEngine.Time.deltaTime;
                    _lastDriveAt = now;

                    if (!_tickedOnce)
                    {
                        _tickedOnce = true;
                        Note(string.Format("{0}: control started", Debug.Id(_bot)));
                    }
                    if (_bot == null || !_bot.IsValid() || _vehicle == null || _vehicle.IsDestroyed)
                    {
                        Release("bot or vehicle disappeared");
                        return;
                    }
                    if (_bot.IsRagdolling()) return;
                    if (_bot.isMounted && _bot.GetMounted() != _seat)
                    {
                        BaseMountable other = _bot.GetMounted();
                        Release($"moved to another seat ({other?.ShortPrefabName ?? "-"} of {other?.VehicleParent()?.ShortPrefabName ?? "-"}, was {_seat?.ShortPrefabName ?? "-"})");
                        return;
                    }
                    if (!_bot.isMounted && UnityEngine.Time.time - _mountedAt < MountGrace) return;
                    if (!_bot.isMounted)
                    {
                        if (_remountAttempts < MaxRemounts && UnityEngine.Time.time >= _nextRemount
                            && _seat != null && !_seat.AnyMounted() && !_vehicle.IsDestroyed
                            && Vector3.Distance(_bot.transform.position, _vehicle.transform.position) < 6f)
                        {
                            _remountAttempts++;
                            _nextRemount = UnityEngine.Time.time + 1.5f;
                            _seat.MountPlayer(_bot);
                            if (_bot.GetMounted() == _seat)
                            {
                                _mountedAt = UnityEngine.Time.time;
                                Note(string.Format("{0}: knocked off by impact - remounted (attempt {1})",
                                    Debug.Id(_bot), _remountAttempts));
                                return;
                            }
                        }
                        if (_remountAttempts >= MaxRemounts)
                        {
                            Release("repeatedly knocked off - vehicle is wedged");
                            return;
                        }
                        Release("bot was dismounted");
                        return;
                    }

                    if (!PreDriveTick()) return;

                    float speed = GetSpeed();
                    if (!_hasTarget)
                    {
                        ApplyInput(_vehicle is GroundVehicle && Mathf.Abs(speed) > StopBrakeSpeed ? -Mathf.Sign(speed) : 0f, 0f, false);
                        return;
                    }

                    Vector3 pos = _vehicle.transform.position;
                    if (_follow is not null && !UpdateFollow(pos)) return;

                    Vector3 aim = AimPoint(pos, speed);
                    if (_route.Count > 0) _target = _route[Mathf.Min(_routeIndex, _route.Count - 1)];
                    Vector3 finish = _route.Count > 0 ? _route[_route.Count - 1] : _target;
                    float distance = FlatDistance
                        ? Vector2.Distance(new Vector2(pos.x, pos.z), new Vector2(finish.x, finish.z))
                        : Vector3.Distance(pos, finish);

                    if (distance < FinalApproach) aim = finish;
                    if (_hasWaypoint)
                    {
                        Vector3 toWaypoint = _waypoint - pos;
                        toWaypoint.y = 0f;
                        if (toWaypoint.magnitude < WaypointReach || UnityEngine.Time.time > _waypointUntil) _hasWaypoint = false;
                        else aim = _waypoint;
                    }
                    AimAt = aim;
                    DistanceToEnd = distance;
                    Vector3 flatToTarget = aim - pos;
                    flatToTarget.y = 0f;

                    if (AvoidsObstacles && _route.Count > 1 && !_hasWaypoint && !_routeGiven && UnityEngine.Time.time >= _nextReroute
                        && DistanceToRoute(pos) > RerouteDistance)
                    {
                        _nextReroute = UnityEngine.Time.time + 8f;
                        Vector3 finalGoal = _route[_route.Count - 1];
                        Note(string.Format("{0}: left the route - rebuilding", Debug.Id(_bot)));
                        DriveTo(finalGoal, _tripArrive, _tripBrake);
                        return;
                    }

                    float remaining = RemainingAlongRoute(pos, distance);
                    if (remaining < _progressBest - ProgressStep)
                    {
                        _progressBest = remaining;
                        _progressAt = UnityEngine.Time.time;
                    }
                    else if (AvoidsObstacles && _route.Count > 0 && !_routeGiven && UnityEngine.Time.time - _progressAt > ProgressTimeout
                             && UnityEngine.Time.time >= _nextReroute)
                    {
                        _nextReroute = UnityEngine.Time.time + 8f;
                        Note(string.Format("{0}: no progress toward target for {1:0} s (closest distance {2:0} m) - rebuilding route",
                            Debug.Id(_bot), UnityEngine.Time.time - _progressAt, _progressBest));
                        DriveTo(_route[_route.Count - 1], _tripArrive, _tripBrake);
                        return;
                    }

                    if (_follow != null)
                    {
                        float keep = FollowKeep;
                        if (keep > 0f && distance <= keep + FollowHoldBand)
                        {
                            if (!HoldAtFollow(pos, _follow.transform.position, distance, keep))
                            {
                                ApplyInput(speed > BrakeSpeedThreshold ? -1f : 0f, 0f, false);
                                TargetSpeed = 0f;
                            }
                            _stuckSince = UnityEngine.Time.time;
                            _progressAt = UnityEngine.Time.time;
                            return;
                        }
                    }
                    else if (distance <= (_tripArrive > 0f ? _tripArrive : ArriveDistance))
                    {
                        Note(string.Format("{0}: arrived, distance to target {1:0.0} m, travel time {2:0} s",
                            Debug.Id(_bot), distance, UnityEngine.Time.time - _startedAt));
                        Arrived = true;
                        Halt();
                        return;
                    }

                    Vector3 forward = _vehicle.transform.forward;
                    forward.y = 0f;
                    float headingError = Vector3.SignedAngle(forward.normalized, flatToTarget.normalized, Vector3.up);

                    float steerHeading = !AvoidsObstacles || distance < FinalApproach
                        ? headingError
                        : ChooseHeading(headingError, speed);
                    if (!AvoidsObstacles || distance < FinalApproach)
                    {
                        _chosenClear = 30f;
                        _chosenVehicle = null;
                        if (FinalApproachSense && AvoidsObstacles && _follow == null && !_hasWaypoint && FinalApproachBlocked(forward, flatToTarget, headingError, distance, speed))
                            return;
                    }
                    float clear = _chosenClear;

                    if (AvoidsObstacles && UnityEngine.Time.time < _reverseUntil)
                    {
                        if (RearBlocked(forward, speed))
                        {
                            Note(string.Format("{0}: obstacle behind {1} at {2:0.0} m - reverse aborted", Debug.Id(_bot), _rearWhat, _rearClear));
                            _reverseUntil = UnityEngine.Time.time;
                            OnReverseAborted();
                            ApplyInput(0f, 0f, false);
                            return;
                        }
                        if (ArcSweep && !ReverseArcOpen(speed))
                        {
                            Note(string.Format("{0}: obstacle {1} on the reverse arc at {2:0.0} m - reverse aborted", Debug.Id(_bot), _arcWhat, _arcClear));
                            _reverseUntil = UnityEngine.Time.time;
                            OnReverseAborted();
                            ApplyInput(0f, 0f, false);
                            return;
                        }
                        float reverseGas = EscapeReverseGas(speed);
                        float reverseSteer = _reverseSteer * SteerMaxPerFrame * (ArcSweep ? _arcScale : 1f);
                        ApplyInput(reverseGas, reverseSteer, false);
                        return;
                    }

                    if (Mathf.Abs(headingError) < 60f) _turnSteps = 0;
                    float turnFrom = _turnSteps > 0 ? 75f : 120f;
                    if (ThreePointTurn && AvoidsObstacles && Mathf.Abs(headingError) > turnFrom && Mathf.Abs(speed) < 3f
                        && UnityEngine.Time.time >= _nextTurnAt && _turnSteps < 4)
                    {
                        float room = Sense(-forward.normalized, 8f).Clear;
                        if (room > 3f)
                        {
                            _turnSteps++;
                            _reverseUntil = UnityEngine.Time.time + TurnReverseTime;
                            _reverseSteer = -Mathf.Sign(headingError);
                            _nextTurnAt = _reverseUntil + 2.5f;
                            _stuckSince = UnityEngine.Time.time;
                            Note(string.Format("{0}: target behind ({1:+0;-0} deg) - turning in stages, stage {2}, rear clearance {3:0.0} m",
                                Debug.Id(_bot), headingError, _turnSteps, room));
                            OnReverseStarted(true);
                            return;
                        }
                    }
                    if (AvoidsObstacles && Mathf.Abs(speed) < 0.4f && UnityEngine.Time.time - _stuckSince > StuckBeforeReverse)
                    {
                        if (_chosenClear < _profile.HalfLength + 4f && IsMoving(_chosenVehicle))
                        {
                            ApplyInput(0f, 0f, false);
                            _stuckSince = UnityEngine.Time.time;
                            if (UnityEngine.Time.time >= _nextWaitNote)
                            {
                                _nextWaitNote = UnityEngine.Time.time + 10f;
                                Note(string.Format("{0}: waiting for {1} to pass", Debug.Id(_bot), _chosenVehicle.ShortPrefabName));
                            }
                            return;
                        }
                        _escapeAttempts++;

                        if (_escapeAttempts >= 2 && UnityEngine.Time.time >= _escapeRouteUntil && !KeepToRoad)
                        {
                            Vector3 open = FindOpenDirection();
                            if (open != Vector3.zero)
                            {
                                _escapeRouteUntil = UnityEngine.Time.time + 12f;
                                SetWaypoint(open);
                                _escapeAttempts = 0;
                                _stuckSince = UnityEngine.Time.time;
                                Note(string.Format("{0}: wedged - moving toward open space via {1}",
                                    Debug.Id(_bot), open));
                                return;
                            }
                        }

                        if (_escapeAttempts == EscapeGiveUp && !_detourTried && !KeepToRoad)
                        {
                            _detourTried = true;
                            Vector3 side = FindDetourPoint();
                            if (side != Vector3.zero)
                            {
                                SetWaypoint(side);
                                _escapeAttempts = 0;
                                _stuckSince = UnityEngine.Time.time;
                                Note(string.Format("{0}: detouring around obstacle via {1}",
                                    Debug.Id(_bot), side));
                                return;
                            }
                        }

                        if (_escapeAttempts > EscapeGiveUp)
                        {
                            if (OnGiveUp())
                            {
                                Note(string.Format("{0}: failed to escape after {1} attempts - subclass recovery succeeded, retrying",
                                    Debug.Id(_bot), _escapeAttempts - 1));
                                _escapeAttempts = 0;
                                _detourTried = false;
                                _stuckSince = UnityEngine.Time.time;
                                return;
                            }
                            Note(string.Format("{0}: failed to escape after {1} attempts - abandoning vehicle",
                                Debug.Id(_bot), _escapeAttempts - 1));
                            Release("permanently stuck");
                            return;
                        }

                        if (_escapeAttempts == 3)
                        {
                            bool pushed = PushVehicle(3);
                            Note(string.Format("{0}: {1} - chassis was grounded{2}",
                                Debug.Id(_bot), pushed ? "pushed vehicle" : "failed to push",
                                _vehicle.IsFlipped() ? " and overturned" : ""));
                        }

                        RememberBlocked(_vehicle.transform.forward);
                        RememberStuckSpot(_vehicle.transform.position + _vehicle.transform.forward * 4f);

                        _reverseUntil = UnityEngine.Time.time + ReverseDuration;
                        _reverseSteer = ChooseReverse();
                        if (ThreePointTurn && Mathf.Abs(headingError) > 100f) _reverseSteer = -Mathf.Sign(headingError);
                        _stuckSince = UnityEngine.Time.time;
                        Note(string.Format("{0}: blocked by {1} at {2:0.0} m - reversing (attempt {3}), then detour {4:+0;-0} deg",
                            Debug.Id(_bot), _senseHit, clear, _escapeAttempts, _chosenOffset)
                            + string.Format(", rear clearance {0:0.0} m", _reverseClear));
                        OnReverseStarted(false);
                        return;
                    }

                    float desiredSpeed = DesiredSpeed(distance, steerHeading, clear);
                    TargetSpeed = desiredSpeed;
                    float throttle = ThrottleFor(speed, desiredSpeed);
                    float steer = SteerFor(steerHeading, speed);
                    if (ArcSweep && AvoidsObstacles && _turnSteps > 0 && throttle > 0f && speed < 3f && Mathf.Abs(steer) > SteerMaxPerFrame * 0.3f)
                    {
                        steer = ForwardArcSteer(steer, speed, headingError, forward, out bool stop);
                        if (stop) throttle = speed > 0.3f ? -1f : 0f;
                    }

                    ApplyInput(throttle, steer, Mathf.Abs(steerHeading) > 25f);
                    WatchStall(pos, speed);
                }

                protected virtual float DesiredSpeed(float distance, float headingError, float clear)
                {
                    float v = _profile.CruiseSpeed;
                    if (SpeedLimit > 0f) v = Mathf.Min(v, SpeedLimit);

                    float turn = Mathf.Abs(headingError);
                    if (turn > 60f) v = Mathf.Min(v, 3f);
                    else if (turn > 30f) v = Mathf.Min(v, 5f);

                    bool ramming = _follow != null && _followKeep <= 0f;
                    if (_tripBrake && !ramming)
                    {
                        float toStop = _follow != null ? distance - FollowKeep : distance;
                        v = Mathf.Min(v, Mathf.Max(2f, toStop * 0.5f));
                    }

                    if (clear < 50f) v = Mathf.Min(v, Mathf.Max(0f, (clear - 2f) * 0.8f));

                    if (_chosenClimb > ClimbableSlope * 0.6f) v = Mathf.Min(v, 4f);
                    return v;
                }

                protected virtual float ThrottleFor(float speed, float desired)
                {
                    float diff = desired - speed;
                    if (diff > 0.5f) return 1f;
                    if (diff < -0.5f) return speed > BrakeSpeedThreshold ? -1f : 0f;
                    return 0f;
                }

                protected virtual float SteerFor(float headingError, float speed)
                {
                    float dt = Mathf.Max(0.01f, TickDelta);
                    float rate = (headingError - _prevHeadingError) / dt;
                    _prevHeadingError = headingError;

                    if (Mathf.Abs(headingError) < SteerDeadZone && Mathf.Abs(rate) < 20f) return 0f;

                    float speedFactor = Mathf.Clamp01(1f - speed / Mathf.Max(1f, _profile.CruiseSpeed * 1.5f));
                    float steer = (headingError * SteerGain + rate * SteerDamping)
                                  * Mathf.Lerp(0.35f, 1f, speedFactor);
                    return Mathf.Clamp(steer, -SteerMaxPerFrame, SteerMaxPerFrame);
                }

                protected virtual float FanHalfAngle => Tuning?.FanHalfAngle ?? 100f;

                protected virtual int FanRays => Tuning?.FanRays ?? 13;

                protected virtual float FanInterval => Tuning?.FanInterval ?? 0.15f;

                private float _nextFanAt;

                public bool FanStraightOnly
                {
                    get => _fanStraightOnly;
                    set
                    {
                        if (_fanStraightOnly && !value) _nextFanAt = 0f;
                        _fanStraightOnly = value;
                    }
                }
                private bool _fanStraightOnly;

                protected virtual float TurnPenalty => Tuning?.TurnPenalty ?? 0.3f;

                protected virtual float UsefulClear => Tuning?.UsefulClear ?? 15f;

                protected virtual float ClimbPenalty => Tuning?.ClimbPenalty ?? 0.35f;

                protected virtual float DropPenalty => Tuning?.DropPenalty ?? 12f;

                protected virtual float BlockedPenalty => Tuning?.BlockedPenalty ?? 25f;

                protected virtual float HeadingStickiness => Tuning?.HeadingStickiness ?? 2f;

                protected virtual float StuckBeforeReverse => Tuning?.StuckBeforeReverse ?? 2.5f;

                protected virtual float ReverseDuration => Tuning?.ReverseDuration ?? 1.8f;

                protected float _reverseUntil;

                protected virtual void OnReverseStarted(bool turnStep) { }

                protected virtual void OnReverseAborted() { }

                private float _reverseSteer;

                protected virtual bool ThreePointTurn => false;

                protected virtual float TurnReverseTime => 2f;

                protected int _turnSteps;
                private float _nextTurnAt;

                private Vector3 _waypoint;
                protected bool _hasWaypoint;
                private float _waypointUntil;

                private const float WaypointReach = 6f;

                private void SetWaypoint(Vector3 point)
                {
                    _waypoint = point;
                    _hasWaypoint = true;
                    _waypointUntil = UnityEngine.Time.time + 15f;
                }

                protected int _escapeAttempts;

                private bool _detourTried;

                private float _escapeRouteUntil;

                protected virtual float RerouteDistance => Tuning?.RerouteDistance ?? 35f;

                private float _nextReroute;

                protected virtual float ProgressStep => 5f;

                protected virtual float ProgressTimeout => Tuning?.ProgressTimeout ?? 20f;

                private float _progressBest = float.MaxValue;
                private float _progressAt;

                protected virtual float DetourDistance => Tuning?.DetourDistance ?? 45f;

                protected virtual int MaxRemounts => Tuning?.MaxRemounts ?? 3;

                private int _remountAttempts;
                private float _nextRemount;

                protected virtual int EscapeGiveUp => Tuning?.EscapeGiveUp ?? 4;

                private float _chosenOffset;
                private float _chosenClear;
                private string _senseHit = "-";

                protected virtual float LandWaterLimit => Tuning?.LandWaterLimit ?? PassProfile.WaterDepth;

                protected virtual float BoatWaterMin => Tuning?.BoatWaterMin ?? 0.8f;

                protected static float BoatShallowDepth(float halfLength) => 0.45f + Mathf.Clamp((halfLength - 2.5f) * 0.33f, 0f, 1.55f);

                private const float SurfaceStep = 3f, LandSurfaceStep = 1f;

                private static readonly float[] SideSigns = { 0f, 1f, -1f };

                private float SurfaceLimitAlong(Vector3 dir, float reach, float level)
                {
                    if (_profile.Kind == VehicleKind.Air) return reach;

                    bool needsWater = _profile.Kind == VehicleKind.Boat || _profile.Kind == VehicleKind.Sub;
                    float waterMin = _profile.Kind == VehicleKind.Boat
                        ? Mathf.Max(BoatWaterMin, BoatShallowDepth(_profile.HalfLength))
                        : BoatWaterMin;
                    Vector3 from = _vehicle.transform.position;
                    float step = needsWater ? SurfaceStep : LandSurfaceStep;
                    Vector3 side = new Vector3(-dir.z, 0f, dir.x).normalized * (_profile.HalfWidth + 0.3f);
                    for (float d = step; d <= reach; d += step)
                    {
                        for (int i = 0; i < (needsWater ? 1 : SideSigns.Length); i++)
                        {
                            Vector3 probe = from + dir * d + side * SideSigns[i];
                            probe.y = TerrainMeta.HeightMap.GetHeight(probe);
                            float depth = WaterLevel.GetOverallWaterDepth(probe, waves: false, volumes: needsWater);
                            bool bad = needsWater ? depth < waterMin : depth > LandWaterLimit;
                            if (bad && !needsWater && DeckAt(probe, level, out _)) bad = false;
                            if (bad) return Mathf.Max(0f, d - step);
                        }
                    }
                    return reach;
                }

                private float _groundLevel;
                private int _groundLevelFrame = -1;

                private float GroundLevel(float terrainHere)
                {
                    if (_groundLevelFrame == UnityEngine.Time.frameCount) return _groundLevel;
                    _groundLevelFrame = UnityEngine.Time.frameCount;
                    _groundLevel = terrainHere;
                    Vector3 pos = _vehicle.transform.position;
                    if (Physics.Raycast(pos + Vector3.up * 1.5f, Vector3.down, out RaycastHit hit, 4f, DeckMask,
                                        QueryTriggerInteraction.Ignore)
                        && !IsOwn(hit.collider) && hit.point.y > terrainHere)
                        _groundLevel = hit.point.y;
                    return _groundLevel;
                }

                protected struct SenseResult
                {
                    public float Clear;
                    public string What;
                    public float Climb;
                    public float Drop;
                    public BaseVehicle Vehicle;
                }

                private const float GroundStep = 2f;

                protected virtual float GroundClearance => Tuning?.GroundClearance ?? 0.35f;

                protected virtual float DropLimit => Tuning?.DropLimit ?? 2.5f;

                private const float FloorScanReach = 16f;

                private static int _senseMask, _floorMask, _vehicleMask, _contactMask, _touchMask;
                private static int SenseMask => _senseMask != 0 ? _senseMask
                    : _senseMask = LayerMask.GetMask("Terrain", "World", "Construction", "Deployed", "Default", "Tree", "Transparent");
                private static int FloorMask => _floorMask != 0 ? _floorMask
                    : _floorMask = LayerMask.GetMask("World", "Construction", "Deployed", "Default", "Tree");
                private static int VehicleMask => _vehicleMask != 0 ? _vehicleMask
                    : _vehicleMask = LayerMask.GetMask("Vehicle Large", "Vehicle Detailed", "Vehicle World");
                private static int ContactMask => _contactMask != 0 ? _contactMask
                    : _contactMask = LayerMask.GetMask("Terrain", "World", "Construction", "Deployed", "Default");
                private static int TouchMask => _touchMask != 0 ? _touchMask
                    : _touchMask = LayerMask.GetMask("World", "Construction", "Deployed", "Default", "Tree", "Transparent", "Vehicle Large", "Vehicle Detailed");

                private static readonly RaycastHit[] _senseHits = new RaycastHit[64];

                private const float NearVehiclesRefresh = 0.3f;
                private readonly List<BaseEntity> _nearVehicles = new List<BaseEntity>();
                private float _nearVehiclesUntil;
                private Vector3 _nearVehiclesAt;
                private float _nearVehiclesRadius;

                private const float BoatSenseLift = 0.55f, BoatSenseHalfHeight = 1.15f;

                private const float SenseSegment = 5f;
                private static readonly Vector3[] SenseProfile = new Vector3[13];
                private static readonly float[] SenseAlong = new float[13];

                private static bool StraightProfile(int from, int to)
                {
                    float span = SenseAlong[to] - SenseAlong[from];
                    if (span <= 0.01f) return true;
                    for (int k = from + 1; k < to; k++)
                    {
                        float y = Mathf.Lerp(SenseProfile[from].y, SenseProfile[to].y, (SenseAlong[k] - SenseAlong[from]) / span);
                        if (Mathf.Abs(SenseProfile[k].y - y) > 0.25f) return false;
                    }
                    return true;
                }

                private static bool LevelDeckAt(Vector3 point, float level, out float deckY)
                {
                    deckY = level;
                    if (!Physics.Raycast(new Vector3(point.x, level + 2.5f, point.z), Vector3.down, out RaycastHit hit, 5f, DeckMask,
                                         QueryTriggerInteraction.Ignore))
                        return false;
                    if (hit.normal.y < 0.8f || Mathf.Abs(hit.point.y - level) > 0.5f
                        || hit.point.y < TerrainMeta.HeightMap.GetHeight(point) + 0.3f)
                        return false;
                    Bounds bounds = hit.collider.bounds;
                    if (!IsRoadSurface(hit.collider) && Mathf.Max(bounds.size.x, bounds.size.z) < 8f) return false;
                    deckY = hit.point.y;
                    return true;
                }

                private void SenseHits(int hitCount, float alongStart, float alongScale, Vector3 basePos, bool onDeck,
                                       float flatBelow, Vector3 castDir, ref SenseResult result)
                {
                    for (int i = 0; i < hitCount; i++)
                    {
                        RaycastHit hit = _senseHits[i];
                        if (hit.distance <= 0.05f) continue;

                        if (hit.collider != null && (IsOwn(hit.collider) || PassableHit(hit.collider) || IsRammable(hit.collider))) continue;

                        BaseEntity ent = hit.collider != null ? hit.collider.ToBaseEntity() : null;
                        if (ent != null && (ent == _vehicle || ent == _bot)) continue;
                        if (ent != null && ent.GetParentEntity() == _vehicle) continue;
                        float along = alongStart + hit.distance * alongScale;
                        if (along >= result.Clear) continue;
                        if (IsRoadSurface(hit.collider)) continue;
                        if (hit.collider is TerrainCollider && GroundKind && TerrainClimbableAt(hit.point, castDir)) continue;

                        float faceAngle = Vector3.Angle(hit.normal, Vector3.up);
                        if (faceAngle < ClimbableSlope && hit.point.y <= flatBelow) continue;
                        float groundAtHit = TerrainMeta.HeightMap.GetHeight(hit.point);
                        if (onDeck) groundAtHit = Mathf.Max(groundAtHit, basePos.y);
                        bool aboveGround = hit.point.y - groundAtHit > 0.3f;
                        if (faceAngle < ClimbableSlope && !aboveGround) continue;

                        result.Clear = along;
                        result.What = hit.collider != null ? hit.collider.name : "?";
                    }
                }

                private bool GroundKind => _profile.Kind != VehicleKind.Air && _profile.Kind != VehicleKind.Boat && _profile.Kind != VehicleKind.Sub;

                private bool TerrainClimbableAt(Vector3 point, Vector3 dir)
                {
                    dir.y = 0f;
                    if (dir.sqrMagnitude < 0.0001f) return false;
                    dir.Normalize();
                    float rise = TerrainMeta.HeightMap.GetHeight(point + dir * 0.5f) - TerrainMeta.HeightMap.GetHeight(point - dir * 0.5f);
                    return Mathf.Atan2(rise, 1f) * Mathf.Rad2Deg <= ClimbableSlope;
                }

                protected SenseResult Sense(Vector3 dir, float reach)
                {
                    SenseResult result = new SenseResult { Clear = reach, What = "-", Climb = 0f, Drop = 0f };
                    if (_vehicle == null) return result;

                    Vector3 basePos = _vehicle.transform.position;
                    float terrainHere = TerrainMeta.HeightMap.GetHeight(basePos);
                    bool waterline = _profile.Kind == VehicleKind.Boat;
                    basePos.y = waterline ? WaterLevel.GetWaterSurface(basePos, false, true) : GroundLevel(terrainHere);
                    bool onDeck = !waterline && basePos.y > terrainHere + 0.5f;

                    int mask = SenseMask;

                    Vector3 boxHalf = new Vector3(Mathf.Min(_profile.HalfWidth + 0.1f, 1.5f), waterline ? BoatSenseHalfHeight : 0.6f, 0.05f);
                    Vector3 localDir = _vehicle.transform.InverseTransformDirection(dir);
                    float reachOut = Mathf.Abs(localDir.x) * _profile.HalfWidth
                                     + Mathf.Abs(localDir.z) * _profile.HalfLength + 0.5f;
                    Vector3 boxFrom = basePos + Vector3.up * (waterline ? BoatSenseLift : 0.7f) + dir * reachOut;
                    if (waterline && NearHullBlocked(boxFrom - dir * 0.3f, boxHalf, dir, out string touching))
                    {
                        result.Clear = 0f;
                        result.What = touching;
                        return result;
                    }

                    bool followTerrain = !onDeck && GroundKind;
                    if (!followTerrain)
                    {
                        int hitCount = Physics.BoxCastNonAlloc(boxFrom, boxHalf, dir, _senseHits,
                                                               Quaternion.LookRotation(dir, Vector3.up), reach, mask,
                                                               QueryTriggerInteraction.Ignore);
                        SenseHits(hitCount, 0f, 1f, basePos, onDeck, float.MinValue, dir, ref result);
                    }
                    else
                    {
                        Vector3 flatDir = new Vector3(dir.x, 0f, dir.z);
                        if (flatDir.sqrMagnitude < 0.0001f) flatDir = _vehicle.transform.forward;
                        flatDir.y = 0f;
                        flatDir.Normalize();
                        int points = Mathf.Clamp(Mathf.CeilToInt(reach / SenseSegment), 1, SenseProfile.Length - 1);
                        float step = reach / points;
                        float level = basePos.y;
                        for (int k = 0; k <= points; k++)
                        {
                            float d = k * step;
                            Vector3 p = boxFrom + flatDir * d;
                            float h = basePos.y;
                            if (k > 0)
                            {
                                h = TerrainMeta.HeightMap.GetHeight(p);
                                if (h < level - 0.25f && LevelDeckAt(p, level, out float deck)) h = deck;
                            }
                            level = h;
                            p.y = h + 0.7f;
                            SenseProfile[k] = p;
                            SenseAlong[k] = d;
                        }
                        int from = 0;
                        while (from < points && SenseAlong[from] < result.Clear)
                        {
                            int to = from + 1;
                            while (to < points && StraightProfile(from, to + 1)) to++;
                            Vector3 segment = SenseProfile[to] - SenseProfile[from];
                            float length = segment.magnitude;
                            if (length > 0.01f)
                            {
                                Vector3 castDir = segment / length;
                                int hitCount = Physics.BoxCastNonAlloc(SenseProfile[from], boxHalf, castDir, _senseHits,
                                                                       Quaternion.LookRotation(castDir, Vector3.up), length,
                                                                       mask, QueryTriggerInteraction.Ignore);
                                SenseHits(hitCount, SenseAlong[from], (SenseAlong[to] - SenseAlong[from]) / length,
                                          basePos, onDeck, SenseProfile[from].y - 0.55f, castDir, ref result);
                            }
                            from = to;
                        }
                    }

                    if (GroundKind && !onDeck)
                    {
                        float prevHeight = TerrainMeta.HeightMap.GetHeight(basePos);
                        for (float d = GroundStep; d <= result.Clear; d += GroundStep)
                        {
                            Vector3 probe = basePos + dir * d;
                            float height = TerrainMeta.HeightMap.GetHeight(probe);
                            float diff = height - prevHeight;
                            prevHeight = height;

                            float slope = Mathf.Abs(Mathf.Atan2(diff, GroundStep) * Mathf.Rad2Deg);
                            if (diff > 0f) result.Climb = Mathf.Max(result.Climb, slope);
                            else result.Drop = Mathf.Max(result.Drop, -diff);

                            bool steep = diff > 0f && slope > ClimbableSlope;
                            bool drop = -diff > DropLimit;
                            if (!steep && !drop) continue;
                            if (DeckAt(probe, basePos.y, out _)) break;
                            result.Clear = Mathf.Max(0f, d - GroundStep);
                            result.What = steep ? "slope" : "cliff";
                            break;
                        }
                    }

                    if (GroundKind)
                    {
                        float floorReach = Mathf.Min(result.Clear, _profile.HalfLength + 1f + FloorScanReach);
                        for (float d = _profile.HalfLength + 1f; d <= floorReach; d += 1.5f)
                        {
                            Vector3 above = basePos + dir * d;
                            float floorDepth = 3.5f;
                            if (!onDeck)
                            {
                                float terrainAt = TerrainMeta.HeightMap.GetHeight(above);
                                above.y = Mathf.Max(terrainAt, basePos.y);
                                floorDepth = above.y - Mathf.Min(terrainAt, basePos.y) + 3.5f;
                            }
                            above.y += 2.5f;
                            if (!Physics.Raycast(above, Vector3.down, out RaycastHit floor, floorDepth, FloorMask,
                                                 QueryTriggerInteraction.Ignore))
                                continue;

                            if (floor.collider != null && (IsOwn(floor.collider) || IsRoadSurface(floor.collider) || IsRammable(floor.collider))) continue;
                            if (floor.normal.y > 0.9f && Mathf.Abs(floor.point.y - basePos.y) < 0.6f) continue;

                            float floorGround = TerrainMeta.HeightMap.GetHeight(floor.point);
                            if (onDeck) floorGround = Mathf.Max(floorGround, basePos.y);
                            float rise = floor.point.y - floorGround;
                            if (rise < GroundClearance) continue;

                            result.Clear = Mathf.Max(0f, d - 1.5f);
                            result.What = floor.collider != null ? floor.collider.name : "rock";
                            break;
                        }
                    }

                    float toVehicle = OtherVehicleAhead(dir, result.Clear, out string vehicleName, out BaseVehicle aheadVehicle);
                    if (toVehicle < result.Clear)
                    {
                        result.Clear = toVehicle;
                        result.What = vehicleName;
                        result.Vehicle = aheadVehicle;
                    }

                    float surface = SurfaceLimitAlong(dir, reach, basePos.y);
                    if (surface < result.Clear)
                    {
                        result.Clear = surface;
                        result.What = _profile.Kind == VehicleKind.Boat || _profile.Kind == VehicleKind.Sub
                            ? "shore" : "water";
                    }
                    return result;
                }

                private static int _nearHullMask;
                private static readonly Collider[] _nearHullHits = new Collider[16];

                private bool NearHullBlocked(Vector3 center, Vector3 boxHalf, Vector3 dir, out string what)
                {
                    what = null;
                    if (_nearHullMask == 0) _nearHullMask = LayerMask.GetMask("World", "Construction", "Deployed", "Default");
                    int count = Physics.OverlapBoxNonAlloc(center, new Vector3(boxHalf.x, boxHalf.y, 0.35f), _nearHullHits,
                                                           Quaternion.LookRotation(dir, Vector3.up), _nearHullMask, QueryTriggerInteraction.Ignore);
                    for (int i = 0; i < count; i++)
                    {
                        Collider collider = _nearHullHits[i];
                        if (collider == null || IsOwn(collider) || PassableHit(collider)) continue;
                        BaseEntity ent = collider.ToBaseEntity();
                        if (ent != null && (ent == _vehicle || ent == _bot || ent.GetParentEntity() == _vehicle)) continue;
                        what = collider.name;
                        return true;
                    }
                    return false;
                }

                private BaseVehicle _chosenVehicle;

                private float _nextWaitNote;

                private static bool IsMoving(BaseVehicle vehicle)
                {
                    if (vehicle == null || vehicle.IsDestroyed) return false;
                    if (vehicle is TrainCar train) return Mathf.Abs(train.GetTrackSpeed()) > 0.3f;
                    return vehicle.GetWorldVelocity().sqrMagnitude > 0.25f;
                }

                private const float PassMargin = 0.6f;

                private float OtherVehicleAhead(Vector3 dir, float reach, out string name, out BaseVehicle vehicle)
                {
                    name = "-";
                    vehicle = null;
                    float best = reach;

                    float radius = reach + 4f;
                    Vector3 here = _vehicle.transform.position;
                    if (UnityEngine.Time.time >= _nearVehiclesUntil || _nearVehiclesRadius < radius + Vector3.Distance(here, _nearVehiclesAt))
                    {
                        _nearVehicles.Clear();
                        _nearVehiclesRadius = Mathf.Max(radius, 34f) + Mathf.Max(8f, 2f * Mathf.Abs(GetSpeed()) * NearVehiclesRefresh);
                        _nearVehiclesAt = here;
                        _nearVehiclesUntil = UnityEngine.Time.time + NearVehiclesRefresh;
                        Vis.Entities(here, _nearVehiclesRadius, _nearVehicles, VehicleMask, QueryTriggerInteraction.Ignore);
                    }
                    for (int i = 0; i < _nearVehicles.Count; i++)
                    {
                        BaseEntity other = _nearVehicles[i];
                        if (other == null || other == _vehicle || other.IsDestroyed) continue;
                        if (other.GetParentEntity() == _vehicle) continue;
                        if (Rammable != null && Rammable(null, other)) continue;
                        BaseVehicle otherVehicle = other as BaseVehicle;
                        Transform ot = other.transform;
                        Vector3 ext, origin;
                        if (otherVehicle != null)
                        {
                            ext = other.bounds.extents;
                            origin = ot.position;
                        }
                        else if (other is HotAirBalloon && GroundBalloonAhead(other, out Vector3 footCenter, out ext))
                            origin = ot.TransformPoint(footCenter);
                        else continue;

                        Vector3 to = origin - _vehicle.transform.position;
                        to.y = 0f;
                        float dist = to.magnitude;
                        if (dist < 0.1f || dist > radius) continue;
                        float along = Vector3.Dot(to, dir);
                        if (along <= 0f) continue;

                        Vector3 across = new Vector3(dir.z, 0f, -dir.x);
                        float otherAcross = Mathf.Abs(ext.x * Vector3.Dot(ot.right, across)) + Mathf.Abs(ext.z * Vector3.Dot(ot.forward, across));
                        float otherAlong = Mathf.Abs(ext.x * Vector3.Dot(ot.right, dir)) + Mathf.Abs(ext.z * Vector3.Dot(ot.forward, dir));
                        float ownHalfWidth = Mathf.Min(_profile.HalfWidth, 1.5f);
                        if (Mathf.Abs(Vector3.Dot(to, across)) > ownHalfWidth + otherAcross + PassMargin) continue;

                        float gap = along - _profile.HalfLength - otherAlong;
                        if (gap < best) { best = Mathf.Max(0f, gap); name = other.ShortPrefabName; vehicle = otherVehicle; }
                    }
                    return best;
                }

                private bool GroundBalloonAhead(BaseEntity balloon, out Vector3 center, out Vector3 extents)
                {
                    center = extents = Vector3.zero;
                    if (_profile == null || _profile.Kind == VehicleKind.Air || _profile.Kind == VehicleKind.Boat || _profile.Kind == VehicleKind.Sub
                        || balloon.transform.position.y - _vehicle.transform.position.y > BalloonAboveSkip)
                        return false;
                    return BalloonFootprint(balloon, out center, out extents);
                }

                public static bool BalloonFootprint(BaseEntity balloon, out Vector3 center, out Vector3 extents)
                {
                    center = extents = Vector3.zero;
                    if (balloon.net == null) return false;
                    float now = UnityEngine.Time.time;
                    ulong id = balloon.net.ID.Value;
                    if (!_balloonShapes.TryGetValue(id, out BalloonShape shape) || now - shape.At >= BalloonShapeRefresh)
                    {
                        if (_balloonShapes.Count > 32) _balloonShapes.Clear();
                        shape = MeasureBalloon(balloon, now);
                        _balloonShapes[id] = shape;
                    }
                    center = shape.Center;
                    extents = shape.Extents;
                    return shape.Valid;
                }
                private const float BalloonLowHeight = 2.5f, BalloonAboveSkip = 3f, BalloonShapeRefresh = 3f;
                private struct BalloonShape
                {
                    public float At;
                    public bool Valid;
                    public Vector3 Center, Extents;
                }
                private static readonly Dictionary<ulong, BalloonShape> _balloonShapes = new Dictionary<ulong, BalloonShape>();
                private static BalloonShape MeasureBalloon(BaseEntity balloon, float now)
                {
                    Transform root = balloon.transform;
                    float top = root.position.y + BalloonLowHeight;
                    Vector3 min = Vector3.positiveInfinity, max = Vector3.negativeInfinity;
                    foreach (Collider c in balloon.GetComponentsInChildren<Collider>())
                    {
                        if (c == null || c.isTrigger || !c.enabled || (VehicleMask & (1 << c.gameObject.layer)) == 0 || c.bounds.min.y > top) continue;
                        Vector3 middle, half;
                        switch (c)
                        {
                            case BoxCollider box: middle = box.center; half = box.size * 0.5f; break;
                            case SphereCollider sphere: middle = sphere.center; half = Vector3.one * sphere.radius; break;
                            case CapsuleCollider capsule:
                                middle = capsule.center;
                                half = Vector3.one * capsule.radius;
                                half[capsule.direction] = Mathf.Max(capsule.height * 0.5f, capsule.radius);
                                break;
                            case MeshCollider mesh when mesh.sharedMesh != null: middle = mesh.sharedMesh.bounds.center; half = mesh.sharedMesh.bounds.extents; break;
                            default: continue;
                        }
                        for (int corner = 0; corner < 8; corner++)
                        {
                            Vector3 local = root.InverseTransformPoint(c.transform.TransformPoint(middle + new Vector3(
                                (corner & 1) == 0 ? half.x : -half.x, (corner & 2) == 0 ? half.y : -half.y, (corner & 4) == 0 ? half.z : -half.z)));
                            min = Vector3.Min(min, local);
                            max = Vector3.Max(max, local);
                        }
                    }
                    BalloonShape shape = new BalloonShape { At = now, Valid = min.x <= max.x };
                    if (shape.Valid)
                    {
                        shape.Center = (min + max) * 0.5f;
                        shape.Extents = (max - min) * 0.5f;
                    }
                    return shape;
                }

                private float ClearAlong(Vector3 dir, float reach, out string what)
                {
                    SenseResult sense = Sense(dir, reach);
                    what = sense.What;
                    return sense.Clear;
                }

                private readonly HashSet<Collider> _ownColliders = new HashSet<Collider>();

                private Rigidbody _ownBody;

                private readonly HashSet<Transform> _ownRoots = new HashSet<Transform>();

                private float _nextOwnRefresh;

                private void CollectOwnColliders()
                {
                    _ownColliders.Clear();
                    _ownRoots.Clear();
                    if (_vehicle == null) return;
                    _ownBody = _vehicle.GetComponent<Rigidbody>();
                    _ownRoots.Add(_vehicle.transform.root);
                    _nextOwnRefresh = UnityEngine.Time.time + 5f;

                    foreach (Collider c in _vehicle.GetComponentsInChildren<Collider>()) _ownColliders.Add(c);
                    if (_vehicle is ModularCar car)
                    {
                        foreach (BaseVehicleModule module in car.AttachedModuleEntities)
                        {
                            if (module == null) continue;
                            _ownRoots.Add(module.transform.root);
                            foreach (Collider c in module.GetComponentsInChildren<Collider>()) _ownColliders.Add(c);
                        }
                    }
                    if (_bot != null)
                    {
                        _ownRoots.Add(_bot.transform.root);
                        foreach (Collider c in _bot.GetComponentsInChildren<Collider>()) _ownColliders.Add(c);
                    }
                }

                private bool IsOwn(Collider collider)
                {
                    if (collider == null) return false;
                    if (_ownColliders.Contains(collider)) return true;
                    if (_ownBody != null && collider.attachedRigidbody == _ownBody) return true;
                    if (_ownRoots.Contains(collider.transform.root)) return true;

                    if (UnityEngine.Time.time >= _nextOwnRefresh)
                    {
                        CollectOwnColliders();
                        return _ownColliders.Contains(collider) || _ownRoots.Contains(collider.transform.root);
                    }
                    return false;
                }

                protected int GroundContacts()
                {
                    if (_vehicle == null) return 0;
                    Transform t = _vehicle.transform;
                    int mask = ContactMask;
                    int contacts = 0;

                    for (int sx = -1; sx <= 1; sx += 2)
                    {
                        for (int sz = -1; sz <= 1; sz += 2)
                        {
                            Vector3 corner = t.position
                                             + t.right * (sx * _profile.HalfWidth * 0.8f)
                                             + t.forward * (sz * _profile.HalfLength * 0.8f)
                                             + Vector3.up * 0.5f;
                            if (Physics.Raycast(corner, Vector3.down, 1.2f, mask, QueryTriggerInteraction.Ignore))
                                contacts++;
                        }
                    }
                    return contacts;
                }

                #region Память упоров

                private readonly Dictionary<int, float> _blockedSectors = new Dictionary<int, float>();

                private const float SectorWidth = 15f;

                protected virtual float BlockMemory => Tuning?.BlockMemory ?? 12f;

                private static int SectorOf(Vector3 dir)
                {
                    float angle = Mathf.Atan2(dir.x, dir.z) * Mathf.Rad2Deg;
                    return Mathf.RoundToInt(angle / SectorWidth);
                }

                protected void RememberBlocked(Vector3 dir)
                {
                    if (dir.sqrMagnitude < 0.001f) return;
                    _blockedSectors[SectorOf(dir)] = UnityEngine.Time.time + BlockMemory;
                }

                protected bool IsBlocked(Vector3 dir)
                {
                    if (!_blockedSectors.TryGetValue(SectorOf(dir), out float until)) return false;
                    if (UnityEngine.Time.time >= until)
                    {
                        _blockedSectors.Remove(SectorOf(dir));
                        return false;
                    }
                    return true;
                }

                #endregion

                private float ChooseHeading(float headingErrorToTarget, float speed)
                {
                    if (UnityEngine.Time.time < _nextFanAt) return headingErrorToTarget + _chosenOffset;
                    _nextFanAt = UnityEngine.Time.time + FanInterval;

                    float reach = Mathf.Clamp(speed * speed / 6f + SenseExtra + 6f, 8f, 30f);
                    Vector3 forward = _vehicle.transform.forward;
                    forward.y = 0f;
                    if (forward.sqrMagnitude < 0.001f) { _chosenClear = reach; return headingErrorToTarget; }
                    forward.Normalize();

                    Vector3 straightDir = Quaternion.AngleAxis(headingErrorToTarget, Vector3.up) * forward;
                    SenseResult straight = Sense(straightDir, reach);
                    if (_fanStraightOnly)
                    {
                        _fan.Clear();
                        _chosenClear = straight.Clear;
                        _chosenOffset = 0f;
                        _senseHit = straight.What;
                        _chosenVehicle = straight.Vehicle;
                        _chosenClimb = straight.Climb;
                        return headingErrorToTarget;
                    }
                    float penalty = straight.Clear < _profile.HalfLength * 2f + 2f ? TurnPenalty * 0.25f : TurnPenalty;
                    bool keepToRoad = KeepToRoad && _route.Count > 1;
                    float horizon = keepToRoad ? UsefulClear : Mathf.Max(UsefulClear, Mathf.Min(reach, Mathf.Abs(speed) * 1.6f));
                    Vector3 origin = _vehicle.transform.position;

                    float bestScore = float.MinValue;
                    if (Mathf.Abs(headingErrorToTarget) <= FanHalfAngle)
                    {
                        bestScore = HeadingScore(straight, straightDir, 0f, penalty, horizon, IsBlocked(straightDir), keepToRoad, origin);
                        if (Mathf.Abs(_chosenOffset) < 8f) bestScore += HeadingStickiness;
                    }
                    float bestOffset = headingErrorToTarget;
                    SenseResult best = straight;
                    _fan.Clear();

                    for (int i = 0; i < FanRays; i++)
                    {
                        float angleFromNose = -FanHalfAngle + i * (FanHalfAngle * 2f / (FanRays - 1));
                        float offset = angleFromNose - headingErrorToTarget;

                        Vector3 dir = Quaternion.AngleAxis(angleFromNose, Vector3.up) * forward;
                        SenseResult sense = Sense(dir, reach);
                        bool blocked = IsBlocked(dir);

                        float score = HeadingScore(sense, dir, offset, penalty, horizon, blocked, keepToRoad, origin);
                        if (Mathf.Abs(offset - _chosenOffset) < 8f) score += HeadingStickiness;

                        _fan.Add(new FanSample
                        {
                            Angle = angleFromNose, Clear = sense.Clear, Blocked = blocked, What = sense.What
                        });

                        if (score > bestScore)
                        {
                            bestScore = score;
                            bestOffset = angleFromNose;
                            best = sense;
                        }
                    }

                    _chosenClear = best.Clear;
                    _chosenOffset = bestOffset - headingErrorToTarget;
                    _senseHit = best.What;
                    _chosenVehicle = best.Vehicle;
                    _chosenClimb = best.Climb;
                    return bestOffset;
                }

                private float HeadingScore(SenseResult sense, Vector3 dir, float offset, float penalty, float horizon,
                                           bool blocked, bool keepToRoad, Vector3 origin)
                {
                    float score = Mathf.Min(sense.Clear, horizon)
                                  - Mathf.Abs(offset) * penalty
                                  - Mathf.Max(0f, sense.Climb - ClimbableSlope * 0.6f) * ClimbPenalty
                                  - (sense.Drop > DropLimit * 0.6f ? DropPenalty : 0f)
                                  - (blocked ? BlockedPenalty : 0f);
                    if (keepToRoad)
                    {
                        float off = DistanceToRouteAhead(origin + dir * Mathf.Min(sense.Clear, 10f), 8);
                        if (off > RoadCorridor) score -= (off - RoadCorridor) * RoadLeavePenalty;
                    }
                    return score;
                }

                private float ChooseReverse()
                {
                    Vector3 forward = _vehicle.transform.forward;
                    forward.y = 0f;
                    if (forward.sqrMagnitude < 0.001f) return 1f;
                    forward.Normalize();

                    float bestClear = -1f;
                    float bestAngle = 180f;
                    for (int i = -2; i <= 2; i++)
                    {
                        float angle = 180f + i * 25f;
                        Vector3 dir = Quaternion.AngleAxis(angle, Vector3.up) * forward;
                        if (IsBlocked(dir)) continue;

                        float clear = Sense(dir, 14f).Clear;
                        if (clear > bestClear) { bestClear = clear; bestAngle = angle; }
                    }

                    _reverseClear = Mathf.Max(0f, bestClear);
                    float offset = Mathf.DeltaAngle(180f, bestAngle);
                    return offset > 0f ? -1f : 1f;
                }

                private float _reverseClear;

                private bool RearBlocked(Vector3 forward, float speed)
                {
                    float now = UnityEngine.Time.time;
                    bool fresh = _rearFor != _reverseUntil;
                    if (!fresh && now < _rearCheckAt) return _rearBlocked;
                    _rearCheckAt = now + 0.2f;
                    Vector3 back = -forward;
                    back.y = 0f;
                    if (back.sqrMagnitude < 0.001f) return _rearBlocked = false;
                    float need = RearNeed(speed);
                    SenseResult rear = Sense(back.normalized, need + 1f);
                    _rearClear = rear.Clear;
                    _rearWhat = rear.What;
                    if (fresh)
                    {
                        _rearFor = _reverseUntil;
                        _rearStart = rear.Clear;
                    }
                    bool alongside = _rearStart <= 0.5f && rear.Clear >= _rearStart - 0.3f;
                    _rearBlocked = rear.Clear < need && !alongside;
                    if (alongside && rear.Clear < need && _rearNotedFor != _reverseUntil)
                    {
                        _rearNotedFor = _reverseUntil;
                        Note(string.Format("{0}: obstacle behind {1} at {2:0.0} m already at maneuver start and not closer - reverse not aborted", Debug.Id(_bot), rear.What, rear.Clear));
                    }
                    return _rearBlocked;
                }
                protected virtual float RearNeed(float speed) => Mathf.Max(1.2f, Mathf.Abs(speed) * 0.6f + 0.8f);

                protected virtual float EscapeReverseGas(float speed) => -1f;

                private float _rearFor, _rearStart, _rearNotedFor;
                private float _rearCheckAt;
                private bool _rearBlocked;
                private float _rearClear;
                private string _rearWhat;

                public bool ArcSweep { get; set; }
                private float _arcScale = 1f;
                private float _arcCheckAt, _arcFor = -1f, _arcNotedFor = -1f, _arcClear, _arcForwardAt, _arcForwardClear;
                private bool _arcOpen = true, _arcForwardBlocked;
                private string _arcWhat = "-", _arcForwardWhat = "-";
                private float _wheelBase, _rearAxle, _maxSteer = 35f;
                private bool _axlesMeasured;
                private const float ArcStep = 0.3f, ArcMargin = 0.25f, ArcLow = 0.35f;
                private static readonly float[] ArcScales = { 1f, 0.5f, 0f };
                private static readonly Collider[] _arcHits = new Collider[32];
                private static readonly HashSet<Collider> _arcStart = new HashSet<Collider>(), _arcTouch = new HashSet<Collider>();

                private void MeasureAxles()
                {
                    _axlesMeasured = true;
                    _wheelBase = 0f;
                    if (_vehicle == null) return;
                    float front = float.MinValue, rear = float.MaxValue;
                    foreach (WheelCollider wheel in _vehicle.GetComponentsInChildren<WheelCollider>())
                    {
                        float z = _vehicle.transform.InverseTransformPoint(wheel.transform.position).z;
                        front = Mathf.Max(front, z);
                        rear = Mathf.Min(rear, z);
                    }
                    if (front > rear + 0.3f)
                    {
                        _wheelBase = front - rear;
                        _rearAxle = rear;
                    }
                    if (_vehicle is ModularCar car && car.carSettings != null) _maxSteer = car.MaxSteerAngle;
                }

                private float ArcClear(float steer, int dir, float reach, out string what)
                {
                    what = "-";
                    if (_vehicle == null || _profile == null) return reach;
                    if (!_axlesMeasured) MeasureAxles();
                    Transform t = _vehicle.transform;
                    Vector3 forward = t.forward;
                    forward.y = 0f;
                    if (forward.sqrMagnitude < 0.001f) return reach;
                    forward.Normalize();
                    float yaw = Mathf.Atan2(forward.x, forward.z);
                    float axleZ = _wheelBase > 0f ? _rearAxle : 0f;
                    Vector3 axle = t.position + forward * axleZ;
                    float curvature = _wheelBase > 0f ? Mathf.Tan(Mathf.Clamp(steer, -1f, 1f) * _maxSteer * Mathf.Deg2Rad) / _wheelBase : 0f;
                    float terrainHere = TerrainMeta.HeightMap.GetHeight(t.position);
                    float baseY = GroundLevel(terrainHere);
                    bool onDeck = baseY > terrainHere + 0.5f;
                    Vector3 half = new Vector3(_profile.HalfWidth + ArcMargin, 0.65f, _profile.HalfLength + ArcMargin);
                    Vector3 touch = new Vector3(_profile.HalfWidth + 0.03f, 0.65f, _profile.HalfLength + 0.03f);
                    _arcStart.Clear();
                    _arcTouch.Clear();
                    ArcCollect(t.position, yaw, half, baseY, terrainHere, onDeck, _arcStart, null);
                    ArcCollect(t.position, yaw, touch, baseY, terrainHere, onDeck, _arcTouch, null);
                    float startDepth = onDeck ? 0f : BodyWaterDepth(t.position, forward);
                    for (float u = ArcStep; u <= reach + 0.001f; u += ArcStep)
                    {
                        float mid = yaw + dir * curvature * ArcStep * 0.5f;
                        axle += dir * new Vector3(Mathf.Sin(mid), 0f, Mathf.Cos(mid)) * ArcStep;
                        yaw += dir * curvature * ArcStep;
                        Vector3 heading = new Vector3(Mathf.Sin(yaw), 0f, Mathf.Cos(yaw));
                        Vector3 center = axle - heading * axleZ;
                        if (!onDeck)
                        {
                            float depth = BodyWaterDepth(center, heading);
                            if (depth > LandWaterLimit && depth > startDepth + 0.05f)
                            {
                                what = "water";
                                return Mathf.Max(0f, u - ArcStep);
                            }
                        }
                        Collider hit = ArcCollect(center, yaw, half, baseY, terrainHere, onDeck, null, _arcStart);
                        if (hit == null)
                        {
                            hit = ArcCollect(center, yaw, touch, baseY, terrainHere, onDeck, null, _arcTouch);
                            if (hit == null) continue;
                        }
                        what = hit.name;
                        return Mathf.Max(0f, u - ArcStep);
                    }
                    return reach;
                }

                private float BodyWaterDepth(Vector3 center, Vector3 heading)
                {
                    Vector3 right = new Vector3(heading.z, 0f, -heading.x);
                    float deepest = 0f;
                    for (int i = 0; i < 4; i++)
                    {
                        Vector3 corner = center + heading * (i < 2 ? _profile.HalfLength : -_profile.HalfLength) + right * (i % 2 == 0 ? _profile.HalfWidth : -_profile.HalfWidth);
                        corner.y = TerrainMeta.HeightMap.GetHeight(corner);
                        deepest = Mathf.Max(deepest, WaterLevel.GetOverallWaterDepth(corner, waves: false, volumes: false));
                    }
                    return deepest;
                }

                private Collider ArcCollect(Vector3 center, float yaw, Vector3 half, float baseY, float terrainHere, bool onDeck, HashSet<Collider> into, HashSet<Collider> except)
                {
                    float level = onDeck ? baseY : baseY + TerrainMeta.HeightMap.GetHeight(center) - terrainHere;
                    center.y = level + 0.3f + half.y;
                    int count = Physics.OverlapBoxNonAlloc(center, half, _arcHits, Quaternion.Euler(0f, yaw * Mathf.Rad2Deg, 0f), SenseMask,
                                                           QueryTriggerInteraction.Ignore);
                    Collider found = null;
                    for (int i = 0; i < count; i++)
                    {
                        Collider collider = _arcHits[i];
                        _arcHits[i] = null;
                        if (found != null || collider == null || collider is TerrainCollider || IsOwn(collider) || PassableHit(collider)
                            || IsRammable(collider) || IsRoadSurface(collider) || collider.bounds.max.y < level + ArcLow)
                            continue;
                        BaseEntity entity = collider.ToBaseEntity();
                        if (entity != null && (entity == _vehicle || entity == _bot || entity.GetParentEntity() == _vehicle)) continue;
                        if (into != null) into.Add(collider);
                        else if (!except.Contains(collider)) found = collider;
                    }
                    return found;
                }

                private bool ReverseArcOpen(float speed)
                {
                    float now = UnityEngine.Time.time;
                    bool fresh = _arcFor != _reverseUntil;
                    if (!fresh && now < _arcCheckAt) return _arcOpen;
                    _arcCheckAt = now + 0.2f;
                    _arcFor = _reverseUntil;
                    float need = RearNeed(speed) + 0.3f;
                    string firstWhat = "-";
                    float firstClear = need;
                    for (int i = 0; i < ArcScales.Length; i++)
                    {
                        float clear = ArcClear(_reverseSteer * ArcScales[i], -1, need, out string what);
                        if (i == 0)
                        {
                            firstWhat = what;
                            firstClear = clear;
                        }
                        if (clear < need) continue;
                        if (i > 0 && _arcNotedFor != _reverseUntil)
                        {
                            _arcNotedFor = _reverseUntil;
                            Note(string.Format("{0}: {1} on the reverse arc at {2:0.0} m with full lock - reversing with {3:0%} lock", Debug.Id(_bot), firstWhat, firstClear, ArcScales[i]));
                        }
                        _arcScale = ArcScales[i];
                        return _arcOpen = true;
                    }
                    _arcWhat = firstWhat;
                    _arcClear = firstClear;
                    return _arcOpen = false;
                }

                private float ForwardArcSteer(float steer, float speed, float headingError, Vector3 forward, out bool stop)
                {
                    stop = false;
                    float now = UnityEngine.Time.time;
                    float need = 0.6f + Mathf.Max(0f, speed) * 0.8f;
                    float fraction = steer / SteerMaxPerFrame;
                    if (now >= _arcForwardAt)
                    {
                        _arcForwardAt = now + 0.2f;
                        _arcForwardClear = ArcClear(fraction, 1, need + 0.3f, out _arcForwardWhat);
                        _arcForwardBlocked = _arcForwardClear < need;
                    }
                    if (!_arcForwardBlocked) return steer;
                    stop = true;
                    if (ThreePointTurn && Mathf.Abs(headingError) > ArcTurnFrom && _turnSteps < 4)
                    {
                        float room = Sense(-forward.normalized, 8f).Clear;
                        if (room > 2f)
                        {
                            _turnSteps++;
                            _reverseUntil = now + TurnReverseTime;
                            _reverseSteer = -Mathf.Sign(headingError);
                            _nextTurnAt = _reverseUntil + 2.5f;
                            _stuckSince = now;
                            Note(string.Format("{0}: {1} on the forward arc at {2:0.0} m, target behind ({3:+0;-0} deg) - turning in stages, stage {4}, rear clearance {5:0.0} m",
                                Debug.Id(_bot), _arcForwardWhat, _arcForwardClear, headingError, _turnSteps, room));
                            OnReverseStarted(true);
                            return steer;
                        }
                    }
                    for (int i = 1; i < ArcScales.Length; i++)
                    {
                        if (ArcClear(fraction * ArcScales[i], 1, need + 0.3f, out _) < need) continue;
                        stop = false;
                        return steer * ArcScales[i];
                    }
                    return steer;
                }
                private const float ArcTurnFrom = 75f;

                public bool FinalApproachSense { get; set; }
                private const float FinalStopClear = 3f;
                private float _finalSenseAt, _finalClear = 30f;
                private string _finalWhat = "-";
                private BaseVehicle _finalVehicle;
                private bool FinalApproachBlocked(Vector3 forward, Vector3 flatToTarget, float headingError, float distance, float speed)
                {
                    float now = UnityEngine.Time.time;
                    if (now >= _finalSenseAt)
                    {
                        _finalSenseAt = now + FanInterval;
                        float reach = Mathf.Max(4f, distance);
                        SenseResult ahead = forward.sqrMagnitude > 0.001f ? Sense(forward.normalized, reach) : new SenseResult { Clear = reach, What = "-" };
                        if (Mathf.Abs(headingError) < 60f && flatToTarget.sqrMagnitude > 0.01f)
                        {
                            SenseResult toAim = Sense(flatToTarget.normalized, reach);
                            if (toAim.Clear < ahead.Clear) ahead = toAim;
                        }
                        _finalClear = ahead.Clear;
                        _finalWhat = ahead.What;
                        _finalVehicle = ahead.Vehicle;
                    }
                    _chosenClear = _finalClear;
                    _chosenVehicle = _finalVehicle;
                    if (_finalClear > FinalStopClear || Mathf.Abs(speed) > 1.5f || IsMoving(_finalVehicle)) return false;
                    Note(string.Format("{0}: {1} {2:0.0} m ahead on the final approach, {3:0} m before the end - the route ends here", Debug.Id(_bot), _finalWhat, _finalClear, distance));
                    Arrived = true;
                    Halt();
                    _finalClear = 30f;
                    return true;
                }

                protected struct FanSample
                {
                    public float Angle;
                    public float Clear;
                    public bool Blocked;
                    public string What;
                }

                private readonly List<FanSample> _fan = new List<FanSample>();
                private float _chosenClimb;

                protected void ApplyInput(float throttle, float steerDegrees, bool sharpSteer)
                {
                    DesiredThrottle = Mathf.Clamp(throttle, -1f, 1f);
                    DesiredSteerNormalized = Mathf.Clamp(steerDegrees / SteerMaxPerFrame, -1f, 1f);
                    SendControl(throttle, steerDegrees, sharpSteer);
                }

                protected abstract void SendControl(float throttle, float steerDegrees, bool sharpSteer);

                protected void PushPlayerInput(int buttons, Vector3 mouseDelta)
                {
                    if (_input == null || _seat == null) return;
                    _input.previous.buttons = _input.current.buttons;
                    _input.previous.mouseDelta = _input.current.mouseDelta;
                    _input.current.buttons = buttons;
                    _input.current.mouseDelta = mouseDelta;
                    _seat.PlayerServerInput(_input, _bot);
                }

                protected virtual float AimLookAhead(float speed) => Mathf.Clamp(Mathf.Abs(speed) * 1.6f, 10f, 28f);

                public bool AimClearPath { get; set; }
                private const float AimCheckInterval = 0.25f;
                private static readonly float[] AimShares = { 1f, 0.6f, 0.35f };
                private float _aimCheckAt, _aimShare = 1f;

                private Vector3 AimPoint(Vector3 pos, float speed)
                {
                    float lookAhead = AimLookAhead(speed);
                    if (!AimClearPath || _route.Count == 0) return AimAlong(pos, lookAhead);
                    if (UnityEngine.Time.time >= _aimCheckAt)
                    {
                        _aimCheckAt = UnityEngine.Time.time + AimCheckInterval;
                        _aimShare = AimShares[AimShares.Length - 1];
                        for (int i = 0; i < AimShares.Length; i++)
                        {
                            if (!SegmentPassable(pos, AimAlong(pos, lookAhead * AimShares[i]), out _)) continue;
                            _aimShare = AimShares[i];
                            break;
                        }
                    }
                    return AimAlong(pos, lookAhead * _aimShare);
                }

                private Vector3 AimAlong(Vector3 pos, float lookAhead)
                {
                    if (_route.Count == 0) return _target;

                    bool hairpins = HairpinAngle > 0f;

                    int seg = _routeIndex;
                    float bestSqr = float.MaxValue;
                    float bestT = 0f;
                    for (int i = Mathf.Max(0, _routeIndex - 1); i < _route.Count - 1; i++)
                    {
                        float t = ProjectOnSegment(pos, _route[i], _route[i + 1]);
                        Vector3 p = Vector3.Lerp(_route[i], _route[i + 1], t);
                        float sqr = (p - pos).sqrMagnitude;
                        bool tie = hairpins && bestSqr < float.MaxValue && sqr <= bestSqr * 1.0001f + 0.01f
                                   && (bestT >= 0.999f || seg < _routeIndex);
                        if (sqr >= bestSqr && !tie) continue;
                        bestSqr = sqr;
                        seg = i;
                        bestT = t;
                    }
                    _routeIndex = Mathf.Max(_routeIndex, seg);

                    Vector3 cursor = Vector3.Lerp(_route[seg], _route[seg + 1 < _route.Count ? seg + 1 : seg], bestT);
                    float left = lookAhead;
                    for (int i = seg; i < _route.Count - 1; i++)
                    {
                        Vector3 a = i == seg ? cursor : _route[i];
                        Vector3 b = _route[i + 1];
                        float len = Vector3.Distance(a, b);
                        if (len >= left) return Vector3.Lerp(a, b, left / Mathf.Max(0.01f, len));
                        left -= len;
                        if (hairpins && i + 2 < _route.Count && IsHairpin(i + 1)) return b;
                    }
                    return _route[_route.Count - 1];
                }

                protected virtual float HairpinAngle => 0f;

                private bool IsHairpin(int index)
                {
                    Vector3 a = _route[index] - _route[index - 1];
                    Vector3 b = _route[index + 1] - _route[index];
                    a.y = 0f;
                    b.y = 0f;
                    return a.sqrMagnitude > 0.01f && b.sqrMagnitude > 0.01f && Vector3.Angle(a, b) > HairpinAngle;
                }

                private static float ProjectOnSegment(Vector3 p, Vector3 a, Vector3 b)
                {
                    Vector3 ab = b - a;
                    ab.y = 0f;
                    float len = ab.sqrMagnitude;
                    if (len < 0.01f) return 0f;
                    Vector3 ap = p - a;
                    ap.y = 0f;
                    return Mathf.Clamp01(Vector3.Dot(ap, ab) / len);
                }

                private float DistanceToRoute(Vector3 pos)
                {
                    if (_route.Count == 0) return 0f;
                    float best = float.MaxValue;
                    int first = Mathf.Max(0, _routeIndex - 1);
                    if (first == 0) best = FlatDistanceToSegment(pos, _routeOrigin, _route[0]);
                    for (int i = first; i < _route.Count - 1; i++)
                    {
                        float d = FlatDistanceToSegment(pos, _route[i], _route[i + 1]);
                        if (d < best) best = d;
                    }
                    if (best == float.MaxValue) best = FlatDistanceToSegment(pos, _route[_route.Count - 1], _route[_route.Count - 1]);
                    return best;
                }

                private float DistanceToRouteAhead(Vector3 pos, int segments)
                {
                    if (_route.Count == 0) return 0f;
                    int first = Mathf.Max(0, _routeIndex - 1);
                    float best = first == 0 ? FlatDistanceToSegment(pos, _routeOrigin, _route[0]) : float.MaxValue;
                    int last = Mathf.Min(_route.Count - 1, first + segments);
                    for (int i = first; i < last; i++)
                    {
                        float d = FlatDistanceToSegment(pos, _route[i], _route[i + 1]);
                        if (d < best) best = d;
                    }
                    if (best == float.MaxValue) best = FlatDistanceToSegment(pos, _route[_route.Count - 1], _route[_route.Count - 1]);
                    return best;
                }

                private static float FlatDistanceToSegment(Vector3 p, Vector3 a, Vector3 b)
                {
                    Vector3 closest = Vector3.Lerp(a, b, ProjectOnSegment(p, a, b));
                    closest.y = p.y;
                    return Vector3.Distance(p, closest);
                }

                private Vector3 FindOpenDirection()
                {
                    Vector3 pos = _vehicle.transform.position;
                    Vector3 forward = _vehicle.transform.forward;
                    forward.y = 0f;
                    if (forward.sqrMagnitude < 0.001f) return Vector3.zero;
                    forward.Normalize();

                    float bestClear = 0f;
                    Vector3 bestPoint = Vector3.zero;
                    for (int i = 0; i < 12; i++)
                    {
                        Vector3 dir = Quaternion.AngleAxis(i * 30f, Vector3.up) * forward;
                        float clear = ClearAlong(dir, 30f, out _);
                        if (clear <= bestClear) continue;
                        Vector3 point = pos + dir * Mathf.Min(clear - 2f, 25f);
                        point.y = TerrainMeta.HeightMap.GetHeight(point);
                        if (!SegmentPassable(pos, point, out _)) continue;
                        bestClear = clear;
                        bestPoint = point;
                    }
                    return bestClear > 8f ? bestPoint : Vector3.zero;
                }

                protected bool UprightVehicle()
                {
                    if (_vehicle == null || _vehicle.IsDestroyed) return false;

                    Vector3 flat = _vehicle.transform.forward;
                    flat.y = 0f;
                    if (flat.sqrMagnitude < 0.01f) flat = Vector3.forward;

                    Vector3 place = _vehicle.transform.position;
                    place.y = TerrainMeta.HeightMap.GetHeight(place) + 1f;

                    Rigidbody body = _vehicle.GetComponent<Rigidbody>();
                    if (body != null) { body.linearVelocity = Vector3.zero; body.angularVelocity = Vector3.zero; }

                    _vehicle.transform.SetPositionAndRotation(place,
                        Quaternion.LookRotation(flat.normalized, Vector3.up));
                    _vehicle.SendNetworkUpdateImmediate();
                    return true;
                }

                protected virtual bool Pushable => !(_vehicle is BaseBoat);

                protected bool PushVehicle(int times)
                {
                    if (_vehicle == null || _bot == null || !_bot.IsValid() || !Pushable) return false;

                    bool wasMounted = _bot.isMounted;
                    if (wasMounted)
                    {
                        BaseMountable mounted = _bot.GetMounted();
                        if (mounted == null || !mounted.HasValidDismountPosition(_bot)) return false;
                        _bot.EnsureDismounted();
                        if (_bot.isMounted) return false;
                    }

                    Vector3 side = _vehicle.transform.position - _vehicle.transform.right * 2f;
                    side.y = _vehicle.transform.position.y;
                    _bot.transform.position = side;
                    _bot.ServerPosition = side;

                    for (int i = 0; i < times; i++)
                        _vehicle.RPC_WantsPush(new BaseEntity.RPCMessage { player = _bot });

                    if (wasMounted && _seat != null && !_seat.AnyMounted())
                    {
                        _seat.MountPlayer(_bot);
                        _mountedAt = UnityEngine.Time.time;
                        return _bot.GetMounted() == _seat;
                    }
                    return true;
                }

                private Vector3 FindDetourPoint()
                {
                    Vector3 pos = _vehicle.transform.position;
                    Vector3 goal = _route.Count > 0 ? _route[Mathf.Min(_routeIndex + 1, _route.Count - 1)] : _target;
                    Vector3 toTarget = goal - pos;
                    toTarget.y = 0f;
                    if (toTarget.sqrMagnitude < 1f) return Vector3.zero;
                    Vector3 dir = toTarget.normalized;

                    float[] angles = { 60f, -60f, 90f, -90f, 120f, -120f };
                    for (int i = 0; i < angles.Length; i++)
                    {
                        Vector3 side = pos + Quaternion.AngleAxis(angles[i], Vector3.up) * dir * DetourDistance;
                        side.y = TerrainMeta.HeightMap.GetHeight(side);
                        if (!SegmentPassable(pos, side, out _)) continue;
                        if (!SegmentPassable(side, goal, out _)) continue;
                        return side;
                    }
                    return Vector3.zero;
                }

                protected Vector3 DeeperWaterDirection(float radius)
                {
                    Vector3 pos = _vehicle.transform.position;
                    Vector3 best = Vector3.zero;
                    float bestDepth = WaterLevel.GetOverallWaterDepth(pos, waves: false, volumes: true);

                    for (float r = radius; r <= radius * 4f; r += radius)
                    {
                        for (int a = 0; a < 12; a++)
                        {
                            float rad = a * Mathf.PI * 2f / 12f;
                            Vector3 dir = new Vector3(Mathf.Cos(rad), 0f, Mathf.Sin(rad));
                            float depth = WaterLevel.GetOverallWaterDepth(pos + dir * r, waves: false, volumes: true);
                            if (depth > bestDepth + 0.5f) { bestDepth = depth; best = dir; }
                        }
                        if (best != Vector3.zero) return best;
                    }
                    return best;
                }

                protected virtual float GetSpeed()
                {
                    Rigidbody body = _vehicle.GetComponent<Rigidbody>();
                    if (body == null) return 0f;
                    return Vector3.Dot(body.linearVelocity, _vehicle.transform.forward);
                }

                private void WatchStall(Vector3 pos, float speed)
                {
                    if (Vector3.Distance(pos, _lastPos) > 1f)
                    {
                        _lastPos = pos;
                        _stuckSince = UnityEngine.Time.time;
                        _escapeAttempts = 0;
                        _detourTried = false;
                        _remountAttempts = 0;
                        return;
                    }
                    if (UnityEngine.Time.time - _stuckSince > 6f)
                    {
                        _stuckSince = UnityEngine.Time.time;
                    }
                }

                private readonly List<BaseCustomNpc> _passengers = new List<BaseCustomNpc>();

                private readonly List<BaseMountable> _passengerSeats = new List<BaseMountable>();

                public string TakePassenger(BaseCustomNpc rider)
                {
                    if (rider == null || !rider.IsValid()) return "passenger is missing";
                    if (_vehicle == null || _vehicle.IsDestroyed) return "vehicle is missing";
                    if (rider == _bot) return "this is the driver";

                    BaseMountable seat = FindFreeSeat(_vehicle);
                    if (seat == null) return "no free seats";

                    ReleaseRoles(rider, null, "mounting passenger seat");

                    MoveBot(rider, _vehicle.transform.position + Vector3.up * 1.5f);
                    seat.MountPlayer(rider);
                    if (rider.GetMounted() != seat) return "failed to mount";

                    rider.GetComponent<INavigator>()?.Pause();
                    _passengers.Add(rider);
                    _passengerSeats.Add(seat);
                    Note(string.Format("{0}: mounted passenger {1}", Debug.Id(_bot), Debug.Id(rider)));
                    return null;
                }

                public void ForgetPassenger(BaseCustomNpc rider)
                {
                    int index = _passengers.IndexOf(rider);
                    if (index < 0) return;
                    _passengers.RemoveAt(index);
                    _passengerSeats.RemoveAt(index);
                }

                public void DropPassengers(string why)
                {
                    for (int i = _passengers.Count - 1; i >= 0; i--)
                    {
                        BaseCustomNpc rider = _passengers[i];
                        BaseMountable seat = _passengerSeats[i];
                        _passengers.RemoveAt(i);
                        _passengerSeats.RemoveAt(i);
                        if (rider == null || !rider.IsValid()) continue;

                        if (rider.isMounted && rider.GetMounted() == seat) rider.DismountSafely();
                        rider.GetComponent<INavigator>()?.Resume();
                        Note(string.Format("{0}: passenger {1} dismounted ({2})",
                            Debug.Id(_bot), Debug.Id(rider), why));
                    }
                }

                public bool DropPassenger(BaseCustomNpc rider, string why)
                {
                    int index = _passengers.IndexOf(rider);
                    if (index < 0) return false;
                    BaseMountable seat = _passengerSeats[index];
                    _passengers.RemoveAt(index);
                    _passengerSeats.RemoveAt(index);
                    if (rider == null || !rider.IsValid()) return true;
                    if (rider.isMounted && rider.GetMounted() == seat) rider.DismountSafely();
                    rider.GetComponent<INavigator>()?.Resume();
                    Note(string.Format("{0}: passenger {1} dismounted ({2})", Debug.Id(_bot), Debug.Id(rider), why));
                    return true;
                }

                private static BaseMountable FindFreeSeat(BaseVehicle vehicle)
                {
                    foreach (BaseVehicle.MountPointInfo mp in vehicle.allMountPoints)
                    {
                        if (mp == null || mp.isDriver || mp.mountable == null) continue;
                        if (mp.mountable.AnyMounted()) continue;
                        return mp.mountable;
                    }
                    return null;
                }

                private static BaseMountable FindDriverSeat(BaseVehicle vehicle)
                {
                    foreach (BaseVehicle.MountPointInfo mp in vehicle.allMountPoints)
                    {
                        if (mp != null && mp.isDriver && mp.mountable != null) return mp.mountable;
                    }
                    return null;
                }
            }

            #endregion

            #region Наземный транспорт

            public class GroundVehicleController : VehicleControllerBase
            {
                private float _nextGroundNote;
                private int _flippedTicks;
                private float _hangingSince;

                public bool SnowOnly { get; set; }

                protected override PassProfile PassProfile
                {
                    get
                    {
                        if (!(_vehicle is Snowmobile)) return PassProfile.Car;
                        return SnowOnly ? PassProfile.SnowmobileOnSnow : PassProfile.Snowmobile;
                    }
                }

                protected override bool PreDriveTick()
                {
                    if (_vehicle == null) return true;
                    if (UnityEngine.Time.time < _nextGroundNote) return true;
                    _nextGroundNote = UnityEngine.Time.time + 2f;

                    int contacts = GroundContacts();

                    if (_vehicle.IsFlipped())
                    {
                        _flippedTicks++;
                        if (_flippedTicks == 1) PushVehicle(2);
                        else
                        {
                            UprightVehicle();
                            Note(string.Format("{0}: car was overturned - set upright", Debug.Id(_bot)));
                            _flippedTicks = 0;
                        }
                    }
                    else _flippedTicks = 0;

                    if (contacts <= 1 && Mathf.Abs(GetSpeed()) < 0.5f)
                    {
                        _hangingSince = _hangingSince > 0f ? _hangingSince : UnityEngine.Time.time;
                        RememberBlocked(_vehicle.transform.forward);
                        bool pushed = PushVehicle(2);
                        Note(string.Format("{0}: chassis grounded (supports {1}/4) - {2}",
                            Debug.Id(_bot), contacts, pushed ? "pushing" : "failed to push"));

                        if (UnityEngine.Time.time - _hangingSince > 5f)
                        {
                            _hangingSince = 0f;
                            if (UprightVehicle())
                                Note(Debug.Id(_bot) + ": freed car from obstruction");
                        }
                    }
                    else _hangingSince = 0f;
                    return true;
                }

                protected override float DriveInterval => Tuning?.DriveInterval ?? 0.05f;

                protected override bool FollowSearchesLand => true;

                protected override bool ThreePointTurn => true;

                protected override float SteerDamping => Tuning?.SteerDamping ?? 0.05f;

                protected virtual float SteerFadeSpeed => Tuning?.SteerFadeSpeed ?? 15f;

                private const float MouseSteerScale = 0.1f;

                private float _sentSteer;

                private bool _steerSynced;
                private float _steerSyncedFor = -1f;

                private Rigidbody _body;

                protected override float SteerFor(float headingError, float speed)
                {
                    if (_body == null) _body = _vehicle.GetComponent<Rigidbody>();
                    float yawRate = _body != null ? _body.angularVelocity.y * Mathf.Rad2Deg : 0f;
                    if (Mathf.Abs(headingError) < SteerDeadZone && Mathf.Abs(yawRate) < 10f) return 0f;

                    float fade = Mathf.Lerp(1f, 0.35f, Mathf.Abs(speed) / Mathf.Max(1f, SteerFadeSpeed));
                    float steer = (headingError * SteerGain - yawRate * SteerDamping) * fade;
                    return Mathf.Clamp(steer, -SteerMaxPerFrame, SteerMaxPerFrame);
                }

                private float _bikeThrottle, _bikeHold;
                private const float BikeThrottleGain = 0.25f, BikeHoldGain = 0.12f, BikeThrottleRate = 1.5f;
                private const float BikeBrakeOver = 1.5f;

                protected override float ThrottleFor(float speed, float desired)
                {
                    if (!(_vehicle is Bike)) return base.ThrottleFor(speed, desired);
                    float diff = desired - speed;
                    if (diff < -BikeBrakeOver && speed > BrakeSpeedThreshold)
                    {
                        _bikeHold = _bikeThrottle = 0f;
                        return -1f;
                    }
                    if (desired < 0.5f && Mathf.Abs(speed) < 0.5f) _bikeHold = 0f;
                    float dt = Mathf.Max(0.01f, TickDelta);
                    _bikeHold = Mathf.Clamp01(_bikeHold + diff * BikeHoldGain * dt);
                    float want = Mathf.Clamp01(_bikeHold + diff * BikeThrottleGain);
                    _bikeThrottle = Mathf.MoveTowards(_bikeThrottle, want, BikeThrottleRate * dt);
                    return _bikeThrottle;
                }

                private float CurrentSteer()
                {
                    if (_vehicle is Bike bike) return bike.SteerInput;
                    if (_vehicle is Snowmobile snowmobile) return snowmobile.SteerInput;
                    return _sentSteer;
                }

                protected override void SendControl(float throttle, float steerDegrees, bool sharpSteer)
                {
                    int buttons = 0;
                    if (throttle > 0.1f) buttons |= (int)BUTTON.FORWARD;
                    else if (throttle < -0.1f) buttons |= (int)BUTTON.BACKWARD;
                    if (sharpSteer) buttons |= (int)BUTTON.SPRINT;

                    if (_steerSyncedFor != MountedAt)
                    {
                        _steerSyncedFor = MountedAt;
                        _steerSynced = false;
                    }

                    float wanted = Mathf.Clamp(steerDegrees / SteerMaxPerFrame, -1f, 1f);
                    Vector3 mouse = Vector3.zero;
                    if (_steerSynced && Mathf.Abs(wanted) > 0.01f)
                    {
                        buttons |= (int)BUTTON.FIRE_THIRD;
                        mouse = new Vector3((wanted - CurrentSteer()) / MouseSteerScale, 0f, 0f);
                        _sentSteer = wanted;
                    }
                    else
                    {
                        _sentSteer = 0f;
                        _steerSynced = true;
                    }
                    PushPlayerInput(buttons, mouse);
                    if (_vehicle is Bike bike && throttle >= 0f) bike.ThrottleInput = throttle;
                }
            }

            public class HorseVehicleController : GroundVehicleController
            {
                private sealed class BotHorseInput : IHorseInputProvider
                {
                    public float Move;
                    public float Steer;
                    public float GetMoveInput() => Move;
                    public float GetSteerInput() => Steer;
                }

                private readonly BotHorseInput _horseInput = new BotHorseInput();
                private RidableHorse _horse;
                private float _wantSpeed;
                private float _nextGaitChange;

                protected override bool ThreePointTurn => false;

                protected override bool Pushable => false;
                protected override bool PreDriveTick() => true;
                protected override PassProfile PassProfile => PassProfile.Horse;

                protected virtual RidableHorse.GaitType MaxGait => RidableHorse.GaitType.Canter;

                protected virtual float GaitChangeInterval => 1f;

                protected override void OnAttached()
                {
                    base.OnAttached();
                    _horse = _vehicle as RidableHorse;
                }

                protected override void OnReleasing()
                {
                    if (_horse != null && _horse.inputProvider == _horseInput) _horse.inputProvider = null;
                    if (_horse != null) _horse.nextAutoAvoidanceCheckTime = 0f;
                    _horse = null;
                    base.OnReleasing();
                }

                protected override float DesiredSpeed(float distance, float headingError, float clear)
                    => _wantSpeed = base.DesiredSpeed(distance, headingError, clear);

                protected override void SendControl(float throttle, float steerDegrees, bool sharpSteer)
                {
                    if (_horse == null || _horse.IsDestroyed)
                    {
                        base.SendControl(throttle, steerDegrees, sharpSteer);
                        return;
                    }
                    if (_horse.inputProvider != _horseInput) _horse.inputProvider = _horseInput;
                    _horse.currentAvoidanceState = RidableHorse.HorseAvoidanceState.Normal;
                    _horse.avoidanceSteeringInput = 0;
                    _horse.nextAutoAvoidanceCheckTime = float.MaxValue;
                    _horseInput.Move = throttle > 0.1f ? 1f : throttle < -0.5f ? -1f : 0f;
                    _horseInput.Steer = Mathf.Clamp(steerDegrees / SteerMaxPerFrame, -1f, 1f);
                    UpdateGait();
                    PushPlayerInput(0, Vector3.zero);
                }

                private void UpdateGait()
                {
                    if (UnityEngine.Time.time < _nextGaitChange) return;
                    RidableHorse.GaitType want = WantedGait();
                    if (_horse.currentGait < want) _horse.IncrementGait(false);
                    else if (_horse.currentGait > want) _horse.RetrogradeGait();
                    else return;
                    _nextGaitChange = UnityEngine.Time.time + GaitChangeInterval;
                }

                private RidableHorse.GaitType WantedGait()
                {
                    if (_horseInput.Move <= 0f || _horse.gaits == null) return RidableHorse.GaitType.Walk;
                    float breed = _horse.currentBreed != null ? _horse.currentBreed.maxSpeed : 1f;
                    int top = Mathf.Min((int)MaxGait, _horse.gaits.Length - 1);
                    for (int i = 0; i < top; i++)
                        if (_horse.gaits[i].maxSpeed * breed >= _wantSpeed) return (RidableHorse.GaitType)i;
                    return (RidableHorse.GaitType)top;
                }
            }

            #endregion

            #region Водный транспорт

            public class BoatVehicleController : VehicleControllerBase
            {
                private BoatAiPilot _provider;
                private MotorRowboat _motorBoat;
                private float _nextEngineCheck;

                protected override void OnAttached()
                {
                    _motorBoat = _vehicle as MotorRowboat;
                    if (_motorBoat != null)
                    {
                        _motorBoat.EngineToggle(true);
                        Note(string.Format("{0}: started boat engine", Debug.Id(_bot)));
                    }

                    _provider = new BoatAiPilot(this);
                    _vehicle.AddAIDriver(_provider);
                }

                protected override void OnReleasing()
                {
                    if (_provider == null || _vehicle == null || _vehicle.IsDestroyed) return;
                    _vehicle.RemoveAIDriver();
                    _provider = null;
                }

                protected override List<Vector3> RouteTo(Vector3 target, out string how)
                {
                    _waterIgnore = _vehicle;
                    _waterHull = Mathf.Max(2f, (_profile != null ? _profile.HalfWidth : 1.5f) + 1f);
                    try { return BuildRoute(_vehicle.transform.position, target, true, out how, ShallowDepth + 0.5f); }
                    finally
                    {
                        _waterIgnore = null;
                        _waterHull = 3f;
                    }
                }

                #region Ведение по линии

                protected virtual bool SteerAlongRoute => true;

                private bool LaneMode => SteerAlongRoute && FollowTarget == null;

                protected bool LaneDirect => _laneDirect;
                protected float LaneClear => _laneClear;

                protected const float LaneBaseError = 29f;
                private const float LaneAimTime = 2.5f, LaneAimMin = 15f, LaneAimMax = 40f;
                private const float LaneYawGain = 1.5f, LaneYawMax = 40f, LaneYawPerSteer = 50f, LaneRateGain = 0.04f, LaneGasError = 3f;
                private const float LaneTurnRate = 30f, LaneTurnDeviation = 4f, LaneBrake = 4f, LaneMinSpeed = 2.5f, LaneTurnSpan = 20f, LaneMinTurn = 15f;
                private const float LaneSharpTurn = 60f, LaneTurnLag = 0.5f, LaneSharpLook = 80f, LaneSharpStartMax = 20f, LaneSharpSlack = 2f, LaneDeviationMin = 1f;
                private const float LaneSteerageMinSpeed = 2.5f;
                private int _laneSegment = -1, _laneFrame = -1;
                private bool _laneDirect, _laneDirectOpen;
                private float _laneHeading, _laneClear, _laneSenseAt, _laneDesired;

                protected override float DesiredSpeed(float distance, float headingError, float clear)
                {
                    if (!LaneMode) return _laneDesired = base.DesiredSpeed(distance, headingError, clear);

                    headingError = LaneHeading(headingError);
                    float sense = _laneDirect ? _laneClear : clear;
                    float baseError = _laneDirect ? Mathf.Clamp(headingError, -LaneBaseError, LaneBaseError) : headingError;
                    _laneDesired = base.DesiredSpeed(distance, baseError, sense);
                    _laneDesired = Mathf.Min(_laneDesired, LaneSpeedLimit(headingError));
                    _laneDesired = LaneGas(_laneDesired, headingError);
                    return _laneDesired;
                }

                protected override float SteerFor(float headingError, float speed)
                {
                    if (!LaneMode) return base.SteerFor(headingError, speed);
                    return LaneSteer(LaneHeading(headingError), speed, _laneDesired);
                }

                protected float LaneSteer(float headingError, float speed, float desired)
                {
                    float rate = LaneRate(headingError);
                    float lane = Mathf.Clamp(rate / LaneYawPerSteer + (rate - YawRate()) * LaneRateGain, -1f, 1f) * SteerMaxPerFrame;
                    return desired - speed < -0.5f && speed > 3f ? -lane : lane;
                }

                private float YawRate()
                {
                    Rigidbody body = _vehicle != null ? _vehicle.rigidBody : null;
                    return body != null ? body.angularVelocity.y * Mathf.Rad2Deg : 0f;
                }

                private static float Flat(Vector3 a, Vector3 b) => Vector2.Distance(new Vector2(a.x, a.z), new Vector2(b.x, b.z));

                private float LaneRate(float headingError) => Mathf.Clamp(headingError * LaneYawGain, -LaneYawMax, LaneYawMax);

                protected float LaneHeading(float fanHeading)
                {
                    if (_laneFrame == UnityEngine.Time.frameCount) return _laneDirect ? _laneHeading : fanHeading;
                    _laneFrame = UnityEngine.Time.frameCount;
                    _laneDirect = false;
                    _laneSegment = -1;
                    if (_vehicle == null || _profile == null || !AvoidsObstacles || DistanceToEnd < FinalApproach) return fanHeading;

                    Vector3 forward = _vehicle.transform.forward;
                    forward.y = 0f;
                    Vector3 position = _vehicle.transform.position;
                    Vector3 to = LaneAim(position) - position;
                    to.y = 0f;
                    if (forward.sqrMagnitude < 0.001f || to.sqrMagnitude < 1f) return fanHeading;

                    float error = Vector3.SignedAngle(forward, to, Vector3.up);
                    if (Mathf.Abs(error) > FanHalfAngle && FollowTarget != null) return fanHeading;
                    float look = Mathf.Clamp(error, -FanHalfAngle, FanHalfAngle);
                    float now = UnityEngine.Time.time;
                    if (now >= _laneSenseAt)
                    {
                        _laneSenseAt = now + FanInterval;
                        float v = GetSpeed();
                        float reach = Mathf.Clamp(v * v / 6f + SenseExtra + 6f, 8f, 30f);
                        Vector3 dir = Mathf.Abs(error) <= FanHalfAngle ? to.normalized : Quaternion.AngleAxis(look, Vector3.up) * forward.normalized;
                        SenseResult sense = Sense(dir, reach);
                        _laneDirectOpen = sense.Clear >= reach - 0.5f && !IsBlocked(dir);
                        _laneClear = sense.Clear;
                    }
                    if (!_laneDirectOpen) return fanHeading;
                    _laneDirect = true;
                    _laneHeading = error;
                    return error;
                }

                private Vector3 LaneAim(Vector3 position)
                {
                    Vector3 aim = AimAt;
                    IReadOnlyList<Vector3> route = Route;
                    _laneSegment = -1;
                    if (route == null || route.Count < 2 || DistanceFromRoute(route, aim) > 3f) return aim;
                    float speed = Mathf.Abs(GetSpeed());
                    float ahead = Mathf.Clamp(speed * LaneAimTime, LaneAimMin, LaneAimMax);
                    if (FollowTarget != null || !LaneProject(route, position, out int segment, out Vector3 projected))
                        return LaneAimOffRoute(position, ahead, aim);

                    float along = Flat(projected, route[segment + 1]);
                    for (int k = segment + 1; k + 1 < route.Count && along <= ahead + LaneSharpLook; k++)
                    {
                        Vector3 inbound = route[k] - route[k - 1], outbound = route[k + 1] - route[k];
                        inbound.y = 0f;
                        outbound.y = 0f;
                        float turn = inbound.sqrMagnitude > 0.01f && outbound.sqrMagnitude > 0.01f ? Vector3.Angle(inbound, outbound) : 0f;
                        if (turn >= LaneSharpTurn)
                        {
                            if (along > LaneTurnStart(turn) + speed * LaneTurnLag || speed > LaneTurnSpeed(turn) + LaneSharpSlack) break;
                            Vector3 offset = position - route[k];
                            offset.y = 0f;
                            return LanePoint(route, k, route[k], Mathf.Max(0f, Vector3.Dot(offset, outbound.normalized)) + ahead, out _laneSegment);
                        }
                        along += Flat(route[k], route[k + 1]);
                    }
                    return LanePoint(route, segment, projected, ahead, out _laneSegment);
                }

                protected virtual Vector3 LaneAimOffRoute(Vector3 position, float ahead, Vector3 aim) => aim;

                private static float LaneTurnSpeed(float turn)
                {
                    float sag = 1f - Mathf.Cos(Mathf.Min(turn, 180f) * 0.5f * Mathf.Deg2Rad);
                    return sag < 0.0005f ? float.MaxValue : Mathf.Max(LaneMinSpeed, LaneTurnDeviation / sag * LaneTurnRate * Mathf.Deg2Rad);
                }

                private static float LaneTurnStart(float turn) =>
                    Mathf.Min(LaneSharpStartMax, LaneTurnSpeed(turn) / (LaneTurnRate * Mathf.Deg2Rad) * Mathf.Tan(Mathf.Min(turn, 170f) * 0.5f * Mathf.Deg2Rad));

                private static float LaneAlignSpeed(float off, float deviation)
                {
                    float sag = 1f - Mathf.Cos(Mathf.Min(off, 90f) * Mathf.Deg2Rad);
                    return sag < 0.0005f ? float.MaxValue : Mathf.Max(LaneMinSpeed, deviation / sag * LaneTurnRate * Mathf.Deg2Rad);
                }

                protected float LaneSpeedLimit(float headingError)
                {
                    IReadOnlyList<Vector3> route = Route;
                    float limit = float.MaxValue;
                    Vector3 position = _vehicle.transform.position, forward = _vehicle.transform.forward;
                    forward.y = 0f;
                    float speed = Mathf.Abs(GetSpeed());
                    bool corner = false;
                    if (LaneProject(route, position, out int segment, out Vector3 projected))
                    {
                        corner = _laneSegment > segment;
                        float along = Flat(projected, route[segment + 1]), window = speed * speed / (2f * LaneBrake) + LaneSharpLook;
                        for (int k = segment + 1; k + 1 < route.Count && along <= window; k++)
                        {
                            float turn = VertexTurn(route, k);
                            if (turn > LaneMinTurn)
                            {
                                float v = LaneTurnSpeed(turn);
                                limit = Mathf.Min(limit, Mathf.Sqrt(v * v + 2f * LaneBrake * Mathf.Max(0f, along - LaneTurnStart(turn))));
                            }
                            along += Flat(route[k], route[k + 1]);
                        }
                    }
                    float off = Mathf.Abs(headingError), deviation = LaneTurnDeviation;
                    if (route != null && _laneSegment >= 0 && _laneSegment + 1 < route.Count && forward.sqrMagnitude > 0.001f)
                    {
                        Vector3 lane = route[_laneSegment + 1] - route[_laneSegment];
                        lane.y = 0f;
                        if (lane.sqrMagnitude > 0.01f)
                        {
                            off = Vector3.Angle(forward, lane);
                            Vector3 u = lane.normalized, f = forward.normalized, from = position - route[_laneSegment];
                            float side = u.x * from.z - u.z * from.x, away = u.x * f.z - u.z * f.x;
                            if (side * away > 0f) deviation = Mathf.Max(LaneDeviationMin, LaneTurnDeviation - Mathf.Abs(side));
                        }
                    }
                    return Mathf.Min(limit, corner ? LaneTurnSpeed(off) : LaneAlignSpeed(off, deviation));
                }

                protected float LaneGas(float desired, float headingError)
                {
                    if (desired < LaneSteerageMinSpeed) return desired;
                    if (Mathf.Abs(headingError) < LaneGasError && Mathf.Abs(LaneRate(headingError) - YawRate()) < LaneGasError) return desired;
                    float speed = GetSpeed();
                    if (Mathf.Abs(desired - speed) > 0.5f) return desired;
                    return speed > desired && speed > 3.2f ? speed - 0.6f : speed + 0.6f;
                }

                private bool LaneProject(IReadOnlyList<Vector3> route, Vector3 position, out int segment, out Vector3 point)
                {
                    segment = -1;
                    point = position;
                    if (route == null || route.Count < 2) return false;
                    float best = float.MaxValue;
                    for (int i = Mathf.Max(0, NextIndex - 2); i + 1 < route.Count; i++)
                    {
                        Vector3 a = route[i], ab = route[i + 1] - a, ap = position - a;
                        ab.y = 0f;
                        ap.y = 0f;
                        float t = ab.sqrMagnitude > 0.0001f ? Mathf.Clamp01(Vector3.Dot(ap, ab) / ab.sqrMagnitude) : 0f;
                        float sqr = (ap - ab * t).sqrMagnitude;
                        if (sqr >= best) continue;
                        best = sqr;
                        segment = i;
                        point = a + ab * t;
                    }
                    return segment >= 0;
                }

                private static Vector3 LanePoint(IReadOnlyList<Vector3> route, int segment, Vector3 from, float distance, out int at)
                {
                    for (int i = segment; i + 1 < route.Count; i++)
                    {
                        Vector3 a = i == segment ? from : route[i], b = route[i + 1];
                        float length = Flat(a, b);
                        if (length >= distance)
                        {
                            at = i;
                            return Vector3.Lerp(a, b, distance / Mathf.Max(0.01f, length));
                        }
                        distance -= length;
                    }
                    at = route.Count - 2;
                    return route[route.Count - 1];
                }

                private static float VertexTurn(IReadOnlyList<Vector3> route, int k)
                {
                    Vector3 back = route[0];
                    float left = LaneTurnSpan;
                    for (int i = k; i > 0; i--)
                    {
                        float length = Flat(route[i], route[i - 1]);
                        if (length >= left)
                        {
                            back = Vector3.Lerp(route[i], route[i - 1], left / Mathf.Max(0.01f, length));
                            break;
                        }
                        left -= length;
                    }
                    Vector3 ahead = LanePoint(route, k, route[k], LaneTurnSpan, out _);
                    Vector3 inbound = route[k] - back, outbound = ahead - route[k];
                    inbound.y = 0f;
                    outbound.y = 0f;
                    return inbound.sqrMagnitude > 0.01f && outbound.sqrMagnitude > 0.01f ? Vector3.Angle(inbound, outbound) : 0f;
                }

                private static float DistanceFromRoute(IReadOnlyList<Vector3> route, Vector3 point)
                {
                    float best = float.MaxValue;
                    for (int i = 0; i + 1 < route.Count; i++)
                    {
                        Vector3 a = route[i], ab = route[i + 1] - a, ap = point - a;
                        ab.y = 0f;
                        ap.y = 0f;
                        float t = ab.sqrMagnitude > 0.0001f ? Mathf.Clamp01(Vector3.Dot(ap, ab) / ab.sqrMagnitude) : 0f;
                        best = Mathf.Min(best, (ap - ab * t).magnitude);
                    }
                    return best;
                }

                #endregion

                private static readonly int FollowHullMask = LayerMask.GetMask("World", "Construction");

                protected override bool FollowLinePassable(Vector3 from, Vector3 to)
                {
                    Vector3 flat = to - from;
                    flat.y = 0f;
                    float length = flat.magnitude;
                    float reach = length - FollowKeep;
                    if (reach < 1f) return true;
                    Vector3 dir = flat / length;
                    float need = ShallowDepth + 0.3f;
                    for (float d = 5f; d <= reach; d += 5f)
                    {
                        Vector3 p = from + dir * d;
                        p.y = TerrainMeta.HeightMap.GetHeight(p);
                        if (WaterLevel.GetOverallWaterDepth(p, waves: false, volumes: true) < need) return false;
                    }
                    Vector3 start = new Vector3(from.x, WaterLevel.GetWaterSurface(from, false, true) - 0.5f, from.z);
                    return !Physics.SphereCast(start, Mathf.Max(1f, _profile.HalfWidth), dir, out _, reach, FollowHullMask, QueryTriggerInteraction.Ignore);
                }

                protected override bool PreDriveTick()
                {
                    if (_motorBoat != null && UnityEngine.Time.time >= _nextEngineCheck)
                    {
                        _nextEngineCheck = UnityEngine.Time.time + 1f;
                        _motorBoat.DriverHeartbeat();
                        if (!_motorBoat.HasFlag(BaseEntity.Flags.On)) _motorBoat.EngineToggle(true);
                    }

                    if (_motorBoat == null) return true;
                    WatchDebris();
                    CheckHung(_unshallowing ? _deepDirection : _vehicle.transform.forward * Mathf.Sign(DesiredThrottle));
                    return UnshallowIfNeeded(_vehicle.transform.position);
                }

                private const float HungThrust = 0.3f, HungRelease = 0.5f, HungWait = 2f, HungNudgeEvery = 3f, HungNudgeStep = 1.5f;
                private const float HungGap = 1f, HungEpisodeMove = 4f, HungEpisodeTime = 15f;
                private float _hungSince = -1f, _hungLast = -1f, _nextNudge, _lastNudgeAt = -100f;
                private Vector3 _hungAt;
                private int _nudges;
                private void CheckHung(Vector3 direction)
                {
                    Rigidbody body = _vehicle.rigidBody;
                    Buoyancy buoyancy = _motorBoat.buoyancy;
                    float now = UnityEngine.Time.time;
                    Vector3 position = _vehicle.transform.position;
                    if (_nudges > 0 && (now - _lastNudgeAt > HungEpisodeTime
                                        || new Vector2(position.x - _hungAt.x, position.z - _hungAt.z).magnitude > HungEpisodeMove))
                        _nudges = 0;
                    if (body == null || body.isKinematic || buoyancy == null || Mathf.Abs(DesiredThrottle) < 0.5f || Mathf.Abs(GetSpeed()) > 0.3f
                        || buoyancy.submergedFraction > (_hungSince >= 0f || _nudges > 0 ? HungRelease : HungThrust))
                    {
                        if (_hungSince >= 0f && now - _hungLast > HungGap) _hungSince = -1f;
                        return;
                    }
                    _hungLast = now;
                    if (_hungSince < 0f) _hungSince = now;
                    direction.y = 0f;
                    if (_debris != null || _capsizedSince >= 0f || now - _hungSince < HungWait || now < _nextNudge || direction.sqrMagnitude < 0.01f) return;
                    _nextNudge = now + HungNudgeEvery;
                    direction.Normalize();
                    float best = Sense(direction, 8f).Clear;
                    if (best < 4f)
                    {
                        for (int i = 1; i < 8; i++)
                        {
                            Vector3 dir = Quaternion.Euler(0f, i * 45f, 0f) * direction;
                            float clear = Sense(dir, 8f).Clear;
                            if (clear <= best + 0.5f) continue;
                            best = clear;
                            direction = dir;
                        }
                    }
                    if (_nudges == 0) _hungAt = position;
                    _nudges = Mathf.Min(_nudges + 1, 3);
                    _lastNudgeAt = now;
                    _motorBoat.WakeUp();
                    buoyancy.Wake();
                    body.AddForce(direction.normalized * (HungNudgeStep * _nudges), ForceMode.VelocityChange);
                    Note(string.Format("{0}: hull stuck (submerged {1:0.00}, propeller not pushing) - nudge {2:0.#} m/s", Debug.Id(_bot),
                        buoyancy.submergedFraction, HungNudgeStep * _nudges));
                }

                private const float EscapeReverseSpeed = 2.5f;
                protected override float EscapeReverseGas(float speed) => speed < -EscapeReverseSpeed ? 0f : -1f;

                protected override float RearNeed(float speed) => Mathf.Max(0.3f, Mathf.Abs(speed) * 0.5f);

                private static int _debrisMask;
                private static readonly Collider[] _debrisHits = new Collider[64];
                private readonly HashSet<JunkPileWater> _ignoredDebris = new HashSet<JunkPileWater>();
                private readonly HashSet<Collider> _passableDebris = new HashSet<Collider>();
                protected override bool PassableHit(Collider collider) => _passableDebris.Count > 0 && _passableDebris.Contains(collider);

                private const float DebrisWait = 2f, DebrisMove = 3f, DebrisCheckEvery = 0.5f, DebrisFast = 4f, DebrisForget = 15f, DebrisLost = 1.25f, DebrisGas = 2f;
                private JunkPileWater _debris, _debrisPile;
                private float _debrisSince, _debrisNextCheck, _debrisSeenAt = -100f, _debrisGasAt = -100f;
                private Vector3 _debrisMark;
                private int _debrisNudges;
                private void WatchDebris()
                {
                    float now = UnityEngine.Time.time;
                    if (now < _debrisNextCheck) return;
                    _debrisNextCheck = now + DebrisCheckEvery;
                    if (Mathf.Abs(DesiredThrottle) >= 0.5f) _debrisGasAt = now;
                    Rigidbody body = _vehicle.rigidBody;
                    if (RightCapsized(now, body)) return;
                    JunkPileWater debris = body == null || body.isKinematic || Mathf.Abs(GetSpeed()) > DebrisFast ? null : DebrisUnderHull();
                    if (debris == null)
                    {
                        if (now - _debrisSeenAt > DebrisLost) _debris = null;
                        return;
                    }
                    Vector3 position = _vehicle.transform.position;
                    if (!ReferenceEquals(debris, _debrisPile) || now - _debrisSeenAt > DebrisForget)
                    {
                        _debrisPile = debris;
                        _debrisNudges = 0;
                        _debrisMark = position;
                        _debrisSince = now;
                    }
                    _debrisSeenAt = now;
                    _debris = debris;
                    float moved = new Vector2(position.x - _debrisMark.x, position.z - _debrisMark.z).magnitude;
                    if (moved >= DebrisMove || now - _debrisGasAt > DebrisGas)
                    {
                        _debrisMark = position;
                        _debrisSince = now;
                        return;
                    }
                    if (now - _debrisSince < DebrisWait) return;
                    _debrisSince = now;
                    _debrisMark = position;
                    if (_debrisNudges > 0 && IgnoreDebris(debris))
                    {
                        Note(string.Format("{0}: still caught on floating debris {1} after a nudge - collisions with it are ignored", Debug.Id(_bot),
                            debris.ShortPrefabName));
                        _debris = null;
                    }
                    _debrisNudges++;
                    Vector3 away = position - debris.transform.position;
                    away.y = 0f;
                    if (away.sqrMagnitude < 0.25f) away = _vehicle.transform.forward * Mathf.Sign(DesiredThrottle);
                    away.y = 0f;
                    if (away.sqrMagnitude < 0.01f) return;
                    _motorBoat.WakeUp();
                    if (_motorBoat.buoyancy != null) _motorBoat.buoyancy.Wake();
                    body.AddForce(away.normalized * HungNudgeStep, ForceMode.VelocityChange);
                    Note(string.Format("{0}: caught on floating debris {1} (moved {2:0.0} m in {3:0} s) - nudge {4:0.#} m/s away from it", Debug.Id(_bot),
                        debris.ShortPrefabName, moved, DebrisWait, HungNudgeStep));
                }

                private const float CapsizeWait = 1f, CapsizeDebrisMemory = 10f, CapsizeCalm = 5f;
                private float _capsizedSince = -1f, _uprightAt = -100f;
                private bool _capsizePushed, _capsizeActed;
                private bool RightCapsized(float now, Rigidbody body)
                {
                    if (!_vehicle.IsFlipped() || body == null || body.isKinematic)
                    {
                        if (_capsizedSince >= 0f)
                        {
                            if (_capsizeActed)
                                Note(string.Format("{0}: boat upright again after {1:0.0} s capsized on floating debris", Debug.Id(_bot), now - _capsizedSince));
                            _capsizedSince = -1f;
                            _uprightAt = now;
                        }
                        if (_capsizePushed && now - _uprightAt > CapsizeCalm) _capsizePushed = false;
                        return false;
                    }
                    JunkPileWater pile = DebrisUnderHull(true);
                    if (pile != null) _debrisSeenAt = now;
                    else if (_capsizedSince < 0f && now - _debrisSeenAt > CapsizeDebrisMemory) return false;
                    else pile = _debrisPile;
                    if (_capsizedSince < 0f)
                    {
                        _capsizedSince = now;
                        _capsizeActed = false;
                    }
                    if (_capsizeActed || now - _capsizedSince < CapsizeWait) return true;
                    _capsizeActed = true;
                    if (pile != null && !pile.IsDestroyed) IgnoreDebris(pile);
                    _motorBoat.WakeUp();
                    if (_motorBoat.buoyancy != null) _motorBoat.buoyancy.Wake();
                    string what = pile != null ? pile.ShortPrefabName : "-";
                    if (_capsizePushed)
                    {
                        Vector3 flat = _vehicle.transform.forward;
                        flat.y = 0f;
                        if (flat.sqrMagnitude < 0.01f) flat = Vector3.ProjectOnPlane(_vehicle.transform.up, Vector3.up);
                        if (flat.sqrMagnitude < 0.01f) flat = Vector3.forward;
                        Vector3 place = _vehicle.transform.position;
                        place.y = WaterLevel.GetWaterSurface(place, false, true);
                        body.linearVelocity = Vector3.zero;
                        body.angularVelocity = Vector3.zero;
                        _vehicle.transform.SetPositionAndRotation(place, Quaternion.LookRotation(flat.normalized, Vector3.up));
                        _vehicle.SendNetworkUpdateImmediate();
                        Note(string.Format("{0}: capsized on floating debris {1} again after a righting push - set upright on the water", Debug.Id(_bot), what));
                        return true;
                    }
                    _capsizePushed = true;
                    Vector3 up = _vehicle.transform.InverseTransformDirection(Vector3.up);
                    float tilt = Vector3.Angle(Vector3.up, up);
                    Vector3 axis = Vector3.Cross(Vector3.up, up);
                    axis = axis.sqrMagnitude > 0.0001f ? axis.normalized : Vector3.forward;
                    body.AddRelativeTorque(axis * (body.mass * 9f * Mathf.Clamp(tilt / 180f, 0.4f, 1f)), ForceMode.Impulse);
                    Note(string.Format("{0}: capsized on floating debris {1} (tilt {2:0} deg) - collisions with it are ignored, righting push", Debug.Id(_bot),
                        what, tilt));
                    return true;
                }

                private JunkPileWater DebrisUnderHull(bool ignoredToo = false)
                {
                    if (_debrisMask == 0) _debrisMask = LayerMask.GetMask("World", "Default", "Deployed", "Prevent Movement");
                    Bounds bounds = _vehicle.bounds;
                    Transform t = _vehicle.transform;
                    int count = Physics.OverlapBoxNonAlloc(t.TransformPoint(bounds.center), bounds.extents + Vector3.one * 0.3f, _debrisHits, t.rotation,
                                                           _debrisMask, QueryTriggerInteraction.Ignore);
                    for (int i = 0; i < count; i++)
                    {
                        BaseEntity entity = _debrisHits[i] != null ? _debrisHits[i].ToBaseEntity() : null;
                        if (entity == null || entity == _vehicle) continue;
                        JunkPileWater debris = PileOf(entity);
                        if (debris != null && !debris.IsDestroyed && (ignoredToo || !_ignoredDebris.Contains(debris))) return debris;
                    }
                    return null;
                }

                private static JunkPileWater PileOf(BaseEntity entity)
                {
                    for (int depth = 0; depth < 3 && entity != null; depth++)
                    {
                        if (entity is JunkPileWater pile) return pile;
                        SpawnPointInstance spawned = entity.GetComponent<SpawnPointInstance>();
                        if (spawned != null && spawned.parentSpawnPointUser is Component group)
                        {
                            JunkPileWater owner = group != null ? group.GetComponentInParent<JunkPileWater>() : null;
                            if (owner != null) return owner;
                        }
                        entity = entity.GetParentEntity();
                    }
                    return null;
                }

                private bool IgnoreDebris(JunkPileWater debris)
                {
                    if (!_ignoredDebris.Add(debris)) return false;
                    Collider[] own = _vehicle.GetComponentsInChildren<Collider>(true);
                    List<Collider> other = new List<Collider>(debris.GetComponentsInChildren<Collider>(true));
                    if (debris.spawngroups != null)
                        foreach (SpawnGroup group in debris.spawngroups)
                        {
                            if (group == null) continue;
                            foreach (SpawnPointInstance instance in group.SpawnInstances)
                                if (instance != null && instance.Entity != null && !instance.Entity.IsDestroyed) other.AddRange(instance.Entity.GetComponentsInChildren<Collider>(true));
                        }
                    foreach (Collider b in other)
                        if (b != null && !b.isTrigger) _passableDebris.Add(b);
                    foreach (Collider a in own)
                    {
                        if (a == null || a.isTrigger) continue;
                        foreach (Collider b in other)
                            if (b != null && !b.isTrigger) Physics.IgnoreCollision(a, b, true);
                    }
                    return true;
                }

                protected override bool OnGiveUp() => (_hungSince >= 0f && _nudges < 3) || _debris != null || _capsizedSince >= 0f;

                protected override void SendControl(float throttle, float steerDegrees, bool sharpSteer)
                {
                    int buttons = 0;
                    if (throttle > 0.1f) buttons |= (int)BUTTON.FORWARD;
                    else if (throttle < -0.1f) buttons |= (int)BUTTON.BACKWARD;
                    PushPlayerInput(buttons, Vector3.zero);
                }

                private float ShallowDepth => BoatShallowDepth(_profile.HalfLength);

                private int _shallowCount;

                protected virtual int ShallowGiveUp => Tuning?.ShallowGiveUp ?? 4;

                private float _unshallowUntil;

                private Vector3 _deepDirection;

                protected virtual float UnshallowReverseSpeed => 3f;

                private const float UnshallowSteerLimit = 0.3f;
                private const float UnshallowMaxTime = 8f;
                private const float UnshallowExtraDepth = 0.5f;
                private bool _unshallowing, _unshallowAhead;
                private float _unshallowStarted;
                private float _unshallowDepth;

                private bool UnshallowIfNeeded(Vector3 pos)
                {
                    if (GetSpeed() > 0.6f) { _shallowCount = 0; _unshallowing = false; return true; }

                    float depth = WaterLevel.GetOverallWaterDepth(pos, waves: false, volumes: true);
                    float now = UnityEngine.Time.time;

                    if (_unshallowing)
                    {
                        if (now >= _unshallowUntil && depth < ShallowDepth + UnshallowExtraDepth && depth > _unshallowDepth + 0.05f && now - _unshallowStarted < UnshallowMaxTime)
                        {
                            _unshallowDepth = depth;
                            _unshallowUntil = now + 1f;
                        }
                        if (now < _unshallowUntil && _unshallowAhead)
                        {
                            Vector3 nose = _vehicle.transform.forward;
                            nose.y = 0f;
                            float bowError = Vector3.SignedAngle(nose, _deepDirection, Vector3.up);
                            float ahead = GetSpeed() > UnshallowReverseSpeed ? 0f : 1f;
                            float steerLimit = SteerMaxPerFrame * UnshallowSteerLimit;
                            ApplyInput(ahead, Mathf.Clamp(bowError * 0.2f, -steerLimit, steerLimit), false);
                            return false;
                        }
                        if (now < _unshallowUntil)
                        {
                            float sternError = Vector3.SignedAngle(-_vehicle.transform.forward, _deepDirection, Vector3.up);
                            float back = GetSpeed() < -UnshallowReverseSpeed ? 0f : -1f;
                            float limit = SteerMaxPerFrame * UnshallowSteerLimit;
                            ApplyInput(back, Mathf.Clamp(-sternError * 0.2f, -limit, limit), false);
                            return false;
                        }
                        _unshallowing = false;
                    }

                    if (depth >= ShallowDepth) { _shallowCount = 0; return true; }

                    float bestDepth = depth;
                    Vector3 bestDir = Vector3.zero;
                    float[] rings = { 15f, 25f, 40f };
                    for (int r = 0; r < rings.Length; r++)
                    {
                        for (int i = 0; i < 12; i++)
                        {
                            Vector3 dir = Quaternion.AngleAxis(i * 30f, Vector3.up) * Vector3.forward;
                            Vector3 probe = pos + dir * rings[r];
                            probe.y = TerrainMeta.HeightMap.GetHeight(probe);
                            float d = WaterLevel.GetOverallWaterDepth(probe, waves: false, volumes: true);
                            if (d <= bestDepth + 0.3f) continue;
                            bestDepth = d;
                            bestDir = dir;
                        }
                    }

                    _shallowCount++;
                    if (_shallowCount >= ShallowGiveUp)
                    {
                        Note(string.Format("{0}: aground {1} times in a row - cannot reach target by water, dismounting",
                            Debug.Id(_bot), _shallowCount));
                        Release("boat aground");
                        return false;
                    }
                    if (bestDir == Vector3.zero) return true;

                    _deepDirection = bestDir;
                    Vector3 bow = _vehicle.transform.forward;
                    bow.y = 0f;
                    _unshallowAhead = bow.sqrMagnitude > 0.01f && Vector3.Dot(bow.normalized, bestDir) > 0.2f;
                    _unshallowing = true;
                    _unshallowStarted = now;
                    _unshallowDepth = depth;
                    _unshallowUntil = now + 3f;

                    Note(string.Format("{0}: aground ({1:0.0} m) - {2} to depth {3:0.0} m",
                        Debug.Id(_bot), depth, _unshallowAhead ? "heading forward" : "backing", bestDepth));
                    return false;
                }

            }

            #endregion

            #region Воздушный транспорт

            public class AirVehicleController : VehicleControllerBase
            {
                protected virtual float CruiseAltitude => _landing ? LandingSinkAltitude : Tuning?.CruiseAltitude ?? 45f;

                private const float LandingSinkAltitude = -8f;

                private const float LandedClearance = 1.5f;

                private const float RestSpeed = 0.3f;
                private const float RestTime = 3f;

                public void LandAt(Vector3 spot)
                {
                    DriveTo(spot, LandingArrive);
                    _landAtEnd = true;
                    Note(string.Format("{0}: flying to land at {1}", Debug.Id(_bot), spot));
                }

                public bool Landed { get; private set; }

                public bool IsLanding => _landing;

                private const float LandingArrive = 4f;

                private bool _landAtEnd;
                private bool _landing;
                private float _landingSince, _restSince, _nextLandingNote;
                private static readonly int LandedGroundMask = LayerMask.GetMask("Terrain", "World", "Construction", "Deployed");

                protected override void OnNewCourse()
                {
                    _landAtEnd = false;
                    _landing = false;
                    Landed = false;
                }

                private void TickLanding()
                {
                    if (!_landAtEnd || Landed) return;
                    float now = UnityEngine.Time.time;
                    if (!_landing)
                    {
                        if (!Arrived) return;
                        _landing = true;
                        _landingSince = _restSince = _nextLandingNote = now;
                        Note(string.Format("{0}: over the landing spot - descending", Debug.Id(_bot)));
                    }
                    Vector3 pos = _vehicle.transform.position;
                    bool byRay = Physics.Raycast(pos + Vector3.up * 0.5f, Vector3.down, out RaycastHit hit, 200f, LandedGroundMask, QueryTriggerInteraction.Ignore);
                    float clearance = byRay ? pos.y - hit.point.y : pos.y - TerrainMeta.HeightMap.GetHeight(pos);
                    Vector3 velocity = _body != null ? _body.linearVelocity : Vector3.zero;
                    float sink = Mathf.Abs(velocity.y);
                    if (velocity.sqrMagnitude > RestSpeed * RestSpeed) _restSince = now;
                    bool touched = clearance <= LandedClearance && sink <= 0.6f;
                    if (!touched && now - _restSince < RestTime)
                    {
                        if (now - _landingSince > 20f && now >= _nextLandingNote)
                        {
                            _nextLandingNote = now + 10f;
                            Note(string.Format("{0}: still descending after {1:0} s - clearance {2:0.0} m ({3}), sink {4:0.0} m/s, speed {5:0.0} m/s",
                                Debug.Id(_bot), now - _landingSince, clearance, byRay ? LayerMask.LayerToName(hit.collider.gameObject.layer) : "terrain map",
                                sink, new Vector2(velocity.x, velocity.z).magnitude));
                        }
                        return;
                    }
                    Landed = true;
                    Halt();
                    Note(touched
                        ? string.Format("{0}: landed", Debug.Id(_bot))
                        : string.Format("{0}: landed - resting {1:0.0} m above the ground under its center", Debug.Id(_bot), clearance));
                }

                protected override bool FlatDistance => true;

                protected override bool AvoidsObstacles => false;

                protected override bool FollowAlwaysStraight => true;

                protected override float HairpinAngle => 120f;

                protected virtual float AltitudeDeadZone => Tuning?.AltitudeDeadZone ?? 4f;

                protected virtual float MaxAirSpeed => 16f;

                protected virtual float CruiseTilt => 10f;

                protected virtual float MaxTilt => 25f;

                protected virtual float TiltThrottle => 0.75f;

                protected virtual float ClimbThrottleCap => 0.9f;

                private const float TiltFloor = 6f;
                private const float TiltStep = 0.5f;

                protected virtual float TiltPerSpeed => 2.5f;
                protected virtual float DragTilt => 1.6f;

                protected virtual float TiltRate => 20f;

                protected virtual float YawRateGain => 1.2f;
                protected virtual float MaxYawRate => 30f;

                protected virtual float YawResponse => 0.12f;
                protected virtual float YawButton => 0.2f;

                protected virtual float ClimbRate => 5f;
                protected virtual float SinkRate => 3f;
                protected virtual float AltitudeGain => 0.35f;
                protected virtual float ClimbGain => 0.25f;

                protected virtual float SideSlipBank => 0.02f;
                protected virtual float MaxSideBank => 0.08f;

                protected virtual bool SideFeedForward => false;

                protected float BankForSideSpeed(float speed) => Mathf.Sin(TiltForSpeed(speed) * Mathf.Deg2Rad);

                protected virtual float RollGain => 3f;

                protected float NoseDown => -Mathf.Asin(Mathf.Clamp(_vehicle.transform.forward.y, -1f, 1f))
                                            * Mathf.Rad2Deg;

                protected float NoseDownRate => _body != null
                    ? _vehicle.transform.InverseTransformDirection(_body.angularVelocity).x * Mathf.Rad2Deg : 0f;

                protected float YawRate => _body != null ? _body.angularVelocity.y * Mathf.Rad2Deg : 0f;

                protected float Bank => _vehicle.transform.right.y;

                protected virtual float RollDamping => Tuning?.RollDamping ?? 0f;

                private float _prevBank;
                private float _bankRate;
                private int _bankFrame = -1;

                protected float RollTo(float wantBank)
                {
                    float bank = Bank;
                    if (_bankFrame != UnityEngine.Time.frameCount)
                    {
                        float dt = Mathf.Max(0.005f, UnityEngine.Time.deltaTime);
                        float rate = _bankFrame < 0 ? 0f : (bank - _prevBank) / dt;
                        _bankRate = Mathf.Lerp(_bankRate, rate, 0.3f);
                        _prevBank = bank;
                        _bankFrame = UnityEngine.Time.frameCount;
                    }
                    float error = bank - wantBank;
                    if (Mathf.Abs(error) < 0.02f && Mathf.Abs(_bankRate) < 0.05f) return 0f;
                    return Mathf.Clamp(error * RollGain + _bankRate * RollDamping, -1f, 1f);
                }

                protected virtual float PitchGain => Tuning?.PitchGain ?? 0.06f;

                protected virtual float PitchDamping => Tuning?.PitchDamping ?? 0.015f;

                protected float PitchFor(float wantNoseDown)
                {
                    float error = wantNoseDown - NoseDown;
                    float rate = NoseDownRate;
                    if (Mathf.Abs(error) < 1f && Mathf.Abs(rate) < 2f) return 0f;
                    return Mathf.Clamp(error * PitchGain - rate * PitchDamping, -ForwardPitch, ForwardPitch);
                }

                protected virtual float ForwardPitch => Tuning?.ForwardPitch ?? 0.55f;

                public BaseEntity FaceTarget { get; set; }

                private BaseHelicopter _heli;
                protected Rigidbody _body;
                private float _lastAirAt;
                private float _airDt = 0.02f;
                private float _tilt;
                private float _holdY = float.NaN;
                private float _climbTrim;
                private bool _climbFirst;
                private float _terrainAhead;
                private float _altitude;
                private float _yawCommand;
                private int _yawFrame = -1;
                private int _yawHeld;
                private float _yawKick = 40f;
                private float _prevYawRate = float.NaN;
                private float _nextEngineTry;
                private float _obstacleTop = float.MinValue;
                private float _obstacleNow = float.MinValue;
                private float _obstacleRoll;
                private float _nextObstacleScan;
                private float _spanHalfWidth;
                private float[] _tiltSpeed;
                private float[] _tiltHover;
                private float _tiltLimit;
                private float _prevHoldY = float.NaN;
                private float _holdRate;

                protected bool ClimbFirst => _climbFirst;

                public float AirSpeedLimit
                {
                    get
                    {
                        if (_tiltSpeed == null) return MaxAirSpeed;
                        int i = TiltIndexFor(TiltThrottle);
                        return _tiltSpeed[i];
                    }
                }

                protected override void OnAttached()
                {
                    _heli = _vehicle as BaseHelicopter;
                    _body = _vehicle.GetComponent<Rigidbody>();
                    _holdY = float.NaN;
                    _prevHoldY = float.NaN;
                    _holdRate = 0f;
                    _tilt = 0f;
                    _climbTrim = 0f;
                    _climbFirst = false;
                    _yawFrame = -1;
                    _yawHeld = 0;
                    _yawKick = 40f;
                    _prevYawRate = float.NaN;
                    _obstacleTop = _obstacleNow = float.MinValue;
                    _obstacleRoll = 0f;
                    _spanHalfWidth = SpanHalfWidth(_vehicle);
                    BuildTiltTable();
                    if (_heli == null) return;
                    _heli.TryStartEngine(_bot);
                    Note(string.Format("{0}: started rotor", Debug.Id(_bot)));
                }

                protected override List<Vector3> RouteTo(Vector3 target, out string how)
                {
                    how = "by air";
                    return new List<Vector3> { target };
                }

                protected override float AimLookAhead(float speed) => Mathf.Clamp(Mathf.Abs(speed) * 3f, 20f, 50f);

                protected override float SteerFor(float headingError, float speed)
                {
                    _yawFrame = UnityEngine.Time.frameCount;
                    _yawCommand = YawCommand(headingError);
                    return _yawCommand * SteerMaxPerFrame;
                }

                private float YawCommand(float headingError)
                {
                    float want = Mathf.Clamp(headingError * YawRateGain, -MaxYawRate, MaxYawRate);
                    return Mathf.Clamp((want - YawRate) * YawGain(), -1f, 1f);
                }

                private float YawGain() => YawResponse * Mathf.Min(1f, 0.05f / Mathf.Max(0.005f, _airDt));

                private float HoverYaw(Vector3 pos)
                {
                    if (FaceTarget != null && !FaceTarget.IsDestroyed)
                    {
                        Vector3 to = FaceTarget.transform.position - pos;
                        to.y = 0f;
                        Vector3 forward = _vehicle.transform.forward;
                        forward.y = 0f;
                        if (to.sqrMagnitude > 36f && forward.sqrMagnitude > 0.001f)
                            return YawCommand(Vector3.SignedAngle(forward, to, Vector3.up));
                    }
                    return YawCommand(0f);
                }

                protected virtual float FollowBrake => 1.5f;

                protected override float FollowHoldBand
                {
                    get
                    {
                        Vector3 v = _body != null ? _body.linearVelocity : Vector3.zero;
                        Vector3 rel = new Vector3(v.x, 0f, v.z) - FollowVelocity();
                        return Mathf.Max(25f, rel.sqrMagnitude / (2f * FollowBrake));
                    }
                }

                protected override float DesiredSpeed(float distance, float headingError, float clear)
                {
                    float keep = FollowKeep;
                    if (keep <= 0f) return base.DesiredSpeed(distance, headingError, clear);
                    float lead = FollowLead();
                    float v = base.DesiredSpeed(distance + 2f * lead, headingError, clear);
                    return Mathf.Min(v, Mathf.Max(2f, lead + Mathf.Sqrt(2f * FollowBrake * Mathf.Max(0f, distance - keep))));
                }

                private BaseEntity _followVelOf;
                private Vector3 _followPrev;
                private float _followPrevAt;
                private Vector3 _followVel;

                protected Vector3 FollowVelocity()
                {
                    BaseEntity target = FollowKeep > 0f ? FollowTarget : null;
                    if (target == null || target.IsDestroyed)
                    {
                        _followVelOf = null;
                        _followVel = Vector3.zero;
                        return Vector3.zero;
                    }
                    float now = UnityEngine.Time.time;
                    Vector3 pos = target.transform.position;
                    if (!ReferenceEquals(target, _followVelOf))
                    {
                        _followVelOf = target;
                        _followPrev = pos;
                        _followPrevAt = now;
                        _followVel = Vector3.zero;
                        return _followVel;
                    }
                    float dt = now - _followPrevAt;
                    if (dt < 0.1f) return _followVel;
                    Vector3 v = (pos - _followPrev) / dt;
                    v.y = 0f;
                    if (v.sqrMagnitude > 40f * 40f) v = _followVel;
                    _followVel = Vector3.Lerp(_followVel, v, Mathf.Min(1f, dt / 0.5f));
                    _followPrev = pos;
                    _followPrevAt = now;
                    return _followVel;
                }

                private float FollowLead()
                {
                    BaseEntity target = FollowTarget;
                    if (target == null || _vehicle == null) return 0f;
                    Vector3 to = target.transform.position - _vehicle.transform.position;
                    to.y = 0f;
                    return to.sqrMagnitude > 1f ? Vector3.Dot(FollowVelocity(), to.normalized) : 0f;
                }

                private float _wantSide;
                private int _wantSideFrame = -1;

                protected override bool HoldAtFollow(Vector3 pos, Vector3 target, float distance, float keep)
                {
                    Vector3 to = target - pos;
                    to.y = 0f;
                    Vector3 forward = _vehicle.transform.forward;
                    forward.y = 0f;
                    if (forward.sqrMagnitude < 0.001f) forward = Vector3.forward;
                    forward.Normalize();
                    Vector3 right = new Vector3(forward.z, 0f, -forward.x);
                    float steer = 0f;
                    Vector3 move;
                    float range = to.magnitude;
                    if (range > 6f)
                    {
                        Vector3 dir = to / range;
                        Vector3 face = FollowFace(target) - pos;
                        face.y = 0f;
                        steer = SteerFor(Vector3.SignedAngle(forward, face.sqrMagnitude > 1f ? face : dir, Vector3.up), GetSpeed());
                        move = dir * Mathf.Clamp((distance - keep) * 0.4f, -5f, 6f);
                    }
                    else move = keep > 6f ? forward * 4f : Vector3.zero;
                    move += FollowVelocity() + FollowDrift(pos, target);
                    TargetSpeed = Vector3.Dot(move, forward);
                    _wantSide = Vector3.Dot(move, right);
                    _wantSideFrame = UnityEngine.Time.frameCount;
                    ApplyInput(0f, steer, false);
                    return true;
                }

                protected virtual Vector3 FollowFace(Vector3 target) => target;

                protected virtual Vector3 FollowDrift(Vector3 pos, Vector3 target) => Vector3.zero;

                protected virtual bool PitchOverride(Vector3 velocity, out float noseDown)
                {
                    noseDown = 0f;
                    return false;
                }

                protected virtual float PitchOverrideRate => TiltRate;

                protected override void SendControl(float throttle, float steerDegrees, bool sharpSteer)
                {
                    if (_vehicle == null) { PushPlayerInput(0, Vector3.zero); return; }

                    float now = UnityEngine.Time.time;
                    float dt = Mathf.Clamp(now - _lastAirAt, 0.005f, 0.25f);
                    _lastAirAt = now;
                    _airDt = dt;
                    Vector3 pos = _vehicle.transform.position;
                    Vector3 velocity = _body != null ? _body.linearVelocity : Vector3.zero;
                    RestartEngine(now);

                    float holdY = UpdateHoldHeight(pos, velocity);
                    float wantClimb = Mathf.Clamp((holdY - pos.y) * AltitudeGain + HoldRise(holdY, dt), -SinkRate, ClimbRate);
                    float climbExtra = Mathf.Max(0f, _climbTrim + (wantClimb - velocity.y) * ClimbGain);
                    int buttons = ThrottleButtons(ClimbThrottle(wantClimb, velocity.y, dt));

                    float yawRate = YawRate;
                    if (_yawHeld != 0 && !float.IsNaN(_prevYawRate))
                    {
                        float kick = (yawRate - _prevYawRate) * _yawHeld / dt;
                        if (kick > 0f) _yawKick = Mathf.Clamp(Mathf.Lerp(_yawKick, kick, 0.1f), 10f, 250f);
                    }
                    else _yawKick += (40f - _yawKick) * Mathf.Min(1f, dt / 20f);
                    _prevYawRate = yawRate;
                    float yaw = _yawFrame == UnityEngine.Time.frameCount ? _yawCommand : HoverYaw(pos);
                    if (_altitude < 3f) yaw = 0f;
                    float press = Mathf.Max(YawButton, Mathf.Min(0.7f, 0.6f * _yawKick * dt * YawGain()));
                    float release = press * 0.5f;
                    if (yaw > press || (_yawHeld > 0 && yaw > release)) _yawHeld = 1;
                    else if (yaw < -press || (_yawHeld < 0 && yaw < -release)) _yawHeld = -1;
                    else _yawHeld = 0;
                    if (_yawHeld > 0) buttons |= (int)BUTTON.RIGHT;
                    else if (_yawHeld < 0) buttons |= (int)BUTTON.LEFT;

                    Vector3 forward = _vehicle.transform.forward;
                    forward.y = 0f;
                    if (forward.sqrMagnitude < 0.0001f) forward = Vector3.forward;
                    forward.Normalize();
                    Vector3 right = new Vector3(forward.z, 0f, -forward.x);
                    float along = Vector3.Dot(velocity, forward);
                    float side = Vector3.Dot(velocity, right);
                    float want = _hasTarget ? Mathf.Min(TargetSpeed, MaxAirSpeed) : 0f;
                    _tiltLimit = TiltLimitFor(Mathf.Min(TiltThrottle, ClimbThrottleCap - climbExtra));
                    float noseDownLimit = _tiltLimit, noseUpLimit = _tiltLimit;
                    if (FollowKeep > 0f)
                    {
                        noseDownLimit = Mathf.Min(_tiltLimit, Mathf.Abs(TiltForSpeed(want)) + CruiseTilt);
                        noseUpLimit = Mathf.Min(_tiltLimit, CruiseTilt);
                    }
                    float wantTilt = Mathf.Clamp(TiltForSpeed(want) + (want - along) * TiltPerSpeed,
                        -noseUpLimit, _climbFirst ? 0f : noseDownLimit);
                    float tiltRate = TiltRate;
                    if (PitchOverride(velocity, out float overrideTilt))
                    {
                        wantTilt = overrideTilt;
                        tiltRate = PitchOverrideRate;
                    }
                    _tilt = Mathf.MoveTowards(_tilt, wantTilt, tiltRate * dt);
                    float wantSide = _wantSideFrame == UnityEngine.Time.frameCount ? _wantSide : 0f;
                    float wantBank = Mathf.Clamp((side - wantSide) * SideSlipBank - (SideFeedForward ? BankForSideSpeed(wantSide) : 0f), -MaxSideBank, MaxSideBank);

                    PushPlayerInput(buttons, new Vector3(RollTo(wantBank), PitchFor(_tilt), 0f));
                }

                private void BuildTiltTable()
                {
                    _tiltSpeed = null;
                    _tiltHover = null;
                    _tiltLimit = CruiseTilt;
                    if (_heli == null || _body == null) return;
                    float drag = _body.linearDamping;
                    float mass = _body.mass;
                    float g = -Physics.gravity.y;
                    if (drag < 0.01f || mass < 1f || _heli.engineThrustMax < 1f || g <= 0f) return;
                    int count = Mathf.FloorToInt(MaxTilt / TiltStep) + 1;
                    List<float> speed = new List<float>(count), hover = new List<float>(count);
                    for (int i = 0; i < count; i++)
                    {
                        float tilt = i * TiltStep * Mathf.Deg2Rad;
                        float up = Mathf.Cos(tilt);
                        float lift = Mathf.InverseLerp(_heli.liftDotMax, 1f, up);
                        float side = 1f - Mathf.InverseLerp(_heli.altForceDotMin, 1f, up);
                        float perThrottle = _heli.engineThrustMax / mass * (_heli.liftFraction * lift - side * Mathf.Sin(tilt * 0.5f));
                        if (perThrottle <= 0.01f) break;
                        float throttle = g * (1f - lift * _heli.hoverForceScale * up) / perThrottle;
                        if (throttle > 1f) break;
                        float accel = g * lift * _heli.hoverForceScale * Mathf.Sin(tilt)
                                      + _heli.engineThrustMax / mass * Mathf.Max(0f, throttle) * side * Mathf.Cos(tilt * 0.5f);
                        speed.Add(accel / drag);
                        hover.Add(throttle);
                    }
                    if (speed.Count < 2) return;
                    _tiltSpeed = speed.ToArray();
                    _tiltHover = hover.ToArray();
                    Note(string.Format("{0}: tilt limit {1:0.0} deg - up to {2:0.0} m/s without losing altitude",
                        Debug.Id(_bot), TiltIndexFor(TiltThrottle) * TiltStep, AirSpeedLimit));
                }

                private int TiltIndexFor(float budget)
                {
                    int i = 0;
                    while (i + 1 < _tiltHover.Length && _tiltHover[i + 1] <= budget) i++;
                    return i;
                }

                private float TiltLimitFor(float budget)
                    => _tiltHover == null ? CruiseTilt : Mathf.Max(TiltFloor, TiltIndexFor(budget) * TiltStep);

                private float TiltForSpeed(float speed)
                {
                    if (_tiltSpeed == null) return speed * DragTilt;
                    float s = Mathf.Abs(speed);
                    for (int i = 1; i < _tiltSpeed.Length; i++)
                    {
                        if (_tiltSpeed[i] < s) continue;
                        return Mathf.Sign(speed) * (i - 1 + Mathf.InverseLerp(_tiltSpeed[i - 1], _tiltSpeed[i], s)) * TiltStep;
                    }
                    return Mathf.Sign(speed) * (_tiltSpeed.Length - 1) * TiltStep;
                }

                private float HoldRise(float holdY, float dt)
                {
                    float rate = float.IsNaN(_prevHoldY) ? 0f : Mathf.Clamp((holdY - _prevHoldY) / dt, -2f * ClimbRate, 2f * ClimbRate);
                    _prevHoldY = holdY;
                    _holdRate += (rate - _holdRate) * Mathf.Min(1f, dt / 0.5f);
                    return Mathf.Max(0f, _holdRate);
                }

                private void RestartEngine(float now)
                {
                    if (!(_heli is PlayerHelicopter heli) || heli.engineController == null || heli.IsOn() || heli.IsStartingUp
                        || now < _nextEngineTry) return;
                    _nextEngineTry = now + 2f;
                    IFuelSystem fuel = heli.GetFuelSystem();
                    if (fuel != null && !fuel.HasFuel()) return;
                    heli.engineController.FinishStartingEngine();
                    Note(string.Format("{0}: engine was off - restarted", Debug.Id(_bot)));
                }

                protected virtual bool LandingDescent => _landing;

                private float UpdateHoldHeight(Vector3 pos, Vector3 velocity)
                {
                    float ground = TerrainMeta.HeightMap.GetHeight(pos);
                    float cruise = CruiseAltitude;
                    float band = Mathf.Clamp(AltitudeDeadZone, 0f, Mathf.Min(cruise * 0.5f, Mathf.Max(0f, cruise - 20f)));
                    _terrainAhead = LandingDescent ? ground : TerrainAhead(pos, velocity, ground);
                    float floor = Mathf.Max(ground + cruise - band, _terrainAhead + Mathf.Min(15f, cruise * 0.6f));
                    float ceil = Mathf.Max(ground + cruise + band, floor);
                    _holdY = Mathf.Clamp(float.IsNaN(_holdY) ? pos.y : _holdY, floor, ceil);
                    _altitude = pos.y - ground;
                    _climbFirst = _climbFirst
                        ? _altitude < cruise * 0.5f + 2f || pos.y < floor - 4f
                        : _altitude < cruise * 0.5f || pos.y < floor - 8f;
                    return _holdY;
                }

                private float TerrainAhead(Vector3 pos, Vector3 velocity, float ground)
                {
                    Vector3 nose = _vehicle.transform.forward;
                    nose.y = 0f;
                    Vector3 flight = velocity;
                    flight.y = 0f;
                    bool byNose = nose.sqrMagnitude > 0.01f;
                    bool byFlight = flight.sqrMagnitude > 4f;
                    if (byNose) nose.Normalize();
                    if (byFlight) flight.Normalize();
                    float worst = ground;
                    for (float d = 20f; d <= 100f; d += 20f)
                    {
                        if (byNose) worst = Mathf.Max(worst, TerrainMeta.HeightMap.GetHeight(pos + nose * d));
                        if (byFlight) worst = Mathf.Max(worst, TerrainMeta.HeightMap.GetHeight(pos + flight * d));
                    }
                    if (byFlight || byNose) worst = Mathf.Max(worst, ObstacleTop(pos, byFlight ? flight : nose));
                    return worst;
                }

                protected virtual float ObstacleLookAhead => 80f;
                protected virtual float ObstacleProbeRadius => _profile != null ? Mathf.Clamp(Mathf.Max(_profile.HalfWidth, _spanHalfWidth) + 2f, 3f, 8f) : 3f;
                protected static readonly int ObstacleClimbMask = LayerMask.GetMask("World", "Construction", "Tree");

                private static float SpanHalfWidth(BaseVehicle vehicle)
                {
                    if (vehicle == null) return 0f;
                    int layer = LayerMask.NameToLayer("Prevent Building");
                    float half = 0f;
                    foreach (BoxCollider box in vehicle.GetComponentsInChildren<BoxCollider>(true))
                    {
                        if (box == null || box.gameObject.layer != layer) continue;
                        Vector3 center = vehicle.transform.InverseTransformPoint(box.transform.TransformPoint(box.center));
                        float width = box.size.x * 0.5f * Mathf.Abs(box.transform.lossyScale.x);
                        half = Mathf.Max(half, Mathf.Abs(center.x) + width);
                    }
                    return half;
                }

                private const float ObstacleHold = 3f;
                private float ObstacleTop(Vector3 pos, Vector3 dir)
                {
                    float now = UnityEngine.Time.time;
                    if (now >= _obstacleRoll)
                    {
                        _obstacleTop = now < _obstacleRoll + ObstacleHold ? _obstacleNow : float.MinValue;
                        _obstacleNow = float.MinValue;
                        _obstacleRoll = now + ObstacleHold;
                    }
                    if (now >= _nextObstacleScan)
                    {
                        _nextObstacleScan = now + 0.25f;
                        float start = (_profile != null ? _profile.HalfLength : 4f) + ObstacleProbeRadius + 1f;
                        float found = float.MinValue;
                        float lower = Mathf.Min(15f, CruiseAltitude * 0.6f);
                        for (int level = 0; level < 2; level++)
                        {
                            Vector3 origin = pos + dir * start + Vector3.down * (level * lower);
                            if (level > 0 && origin.y - TerrainMeta.HeightMap.GetHeight(origin) < ObstacleProbeRadius + 2f) break;
                            if (Physics.SphereCast(origin, ObstacleProbeRadius, dir, out RaycastHit hit, ObstacleLookAhead,
                                    ObstacleClimbMask, QueryTriggerInteraction.Ignore))
                                found = Mathf.Max(found, ObstacleRoof(hit, origin, pos, dir));
                        }
                        float height = pos.y - TerrainMeta.HeightMap.GetHeight(pos);
                        if (height > ObstacleProbeRadius + 2f
                            && Physics.SphereCast(pos, ObstacleProbeRadius + 1f, Vector3.down, out RaycastHit below, height,
                                ObstacleClimbMask, QueryTriggerInteraction.Ignore)
                            && below.distance > 0f && below.point.y > TerrainMeta.HeightMap.GetHeight(below.point) + 1f)
                            found = Mathf.Max(found, below.point.y);
                        _obstacleNow = Mathf.Max(_obstacleNow, found);
                    }
                    return Mathf.Max(_obstacleTop, _obstacleNow);
                }

                private float ObstacleRoof(RaycastHit hit, Vector3 origin, Vector3 pos, Vector3 dir)
                {
                    bool inside = hit.distance <= 0f || hit.point == Vector3.zero;
                    float bottom = inside ? origin.y - ObstacleProbeRadius : hit.point.y;
                    Vector3 column = inside ? origin : hit.point + dir;
                    float top = bottom;
                    float from = Mathf.Max(pos.y, bottom) + 100f;
                    if (Physics.Raycast(new Vector3(column.x, from, column.z), Vector3.down, out RaycastHit roof,
                            from - bottom + 1f, ObstacleClimbMask, QueryTriggerInteraction.Ignore))
                        top = Mathf.Max(top, roof.point.y);
                    else if (!inside && hit.collider != null) top = Mathf.Max(top, Mathf.Min(hit.collider.bounds.max.y, pos.y + 100f));
                    return top;
                }

                private float ClimbThrottle(float wantClimb, float climb, float dt)
                {
                    float error = wantClimb - climb;
                    float throttle = HoverThrottle() + _climbTrim + error * ClimbGain;
                    if (throttle > -0.8f && throttle < 1f)
                        _climbTrim = Mathf.Clamp(_climbTrim + error * 0.08f * dt, -0.25f, 0.25f);
                    return Mathf.Clamp(throttle, -0.8f, 1f);
                }

                private float HoverThrottle()
                {
                    if (_heli == null || _body == null) return 0f;
                    Vector3 upAxis = _vehicle.transform.up;
                    float up = Mathf.Clamp01(Vector3.Dot(upAxis, Vector3.up));
                    float lift = Mathf.InverseLerp(_heli.liftDotMax, 1f, up);
                    Vector3 tiltAxis = upAxis - Vector3.up;
                    float down = tiltAxis.sqrMagnitude > 1e-6f ? tiltAxis.normalized.y * (1f - Mathf.InverseLerp(_heli.altForceDotMin, 1f, up)) : 0f;
                    float thrust = _heli.engineThrustMax * (_heli.liftFraction * lift + down);
                    if (thrust < 1f) return 1f;
                    return Mathf.Clamp((1f - _heli.hoverForceScale * lift * up) * _body.mass * -Physics.gravity.y / thrust, -0.8f, 1f);
                }

                private int ThrottleButtons(float want)
                {
                    float current = _heli != null ? _heli.currentThrottle : 0f;
                    if (current < want - 0.02f) return want > 0f ? (int)BUTTON.FORWARD : 0;
                    if (current > want + 0.02f) return want < 0f ? (int)BUTTON.BACKWARD : 0;
                    return 0;
                }

                protected override bool PreDriveTick()
                {
                    if (_vehicle == null) return true;
                    TickLanding();
                    return true;
                }
            }

            #endregion

            #region Боевой вертолёт

            public class AttackHeliController : AirVehicleController
            {
                protected virtual float RocketRange => 220f;

                protected virtual float AttackAltitude => 30f;

                protected virtual float RocketMinRange => 35f;

                protected virtual float RocketAim => 8f;

                protected virtual float RocketCooldown => 1.5f;

                protected virtual float RocketHitRadius => 10f;

                protected virtual float RocketMaxDive => 25f;
                protected virtual float RocketDiveSpeed => 3f;

                protected virtual float RocketHoldDive => RocketMaxDive - 2f;

                protected virtual float RocketDiveTime => 3f;
                protected virtual float RocketDivePause => 4f;

                protected virtual float RocketDiveHold => 1.5f;

                protected virtual float RocketDiveRate => 10f;
                protected override float PitchOverrideRate => _recovering ? RocketRecoverRate : RocketDiveRate;

                protected virtual float RocketRecoverRate => 40f;
                protected virtual float RocketRecoverTime => 1.5f;

                protected virtual float RocketRecoverPitch => 1f;
                protected override float ForwardPitch => _recovering ? Mathf.Max(base.ForwardPitch, RocketRecoverPitch) : base.ForwardPitch;

                protected virtual float RocketNoseTrim => 1.5f;

                protected virtual float RocketTightRadius => 3f;
                protected virtual float RocketSettleStep => 0.3f;

                protected virtual float RocketStallTime => 4f;
                protected virtual float RocketSteepExtra => 5f;
                protected virtual float RocketSteepTime => 30f;

                protected virtual float RocketOrbitBank => 0.2f;

                private AttackHelicopter _attack;
                private Vector3 _fireAt;
                private bool _hasFireTarget;
                private float _nextRocket;
                private float _nextFlare;
                private float _nextSamScan;
                private float _nextProjection;
                private bool _rocketsReady;
                private bool _rocketAiming;
                private float _rocketBias;
                private float _diveStart;
                private float _diveSwing;
                private float _diveArrived;
                private float _diveBlockedUntil;
                private float _recoverUntil;
                private bool _recovering;
                private float _pitchAt;
                private bool _diveFired;
                private bool _diveLineBlocked;
                private float _orbitBase = float.NaN;
                private float _orbitBearing = float.NaN;
                private int _orbitTry;
                private float _orbitUntil;
                private int _orbitDriftFrame = -1;
                private readonly List<float> _orbitTried = new List<float>();
                private float _nextLineProbe;
                private float _stallSince = -1f;
                private float _steepUntil;
                private float _prevMiss = float.NaN;
                private float _baseKeep;
                private ItemDefinition _ammoDef;
                private float _ammoSpeed;
                private float _ammoGravity;
                private int _keepFrame = -1;
                private float _keepHeight = float.NaN;
                private float _keepNeed;

                protected override void OnAttached()
                {
                    base.OnAttached();
                    _attack = _vehicle as AttackHelicopter;
                }

                protected override float CruiseAltitude => _hasFireTarget ? AttackAltitude : base.CruiseAltitude;

                public void FireAt(Vector3 point)
                {
                    bool first = !_hasFireTarget;
                    if (first)
                    {
                        _rocketBias = 0f;
                        _rocketsReady = true;
                        ResetOrbit();
                    }
                    _fireAt = point;
                    _hasFireTarget = true;
                    if (!first && (point - _fireNoted).sqrMagnitude <= 15f * 15f) return;
                    _fireNoted = point;
                    Note(string.Format("{0}: rocket target {1}", Debug.Id(_bot), point));
                }
                private Vector3 _fireNoted;

                public void CeaseFire()
                {
                    _hasFireTarget = false;
                    ResetOrbit();
                }

                protected virtual float RocketOrbitStep => 25f;
                protected virtual float RocketOrbitSpeed => 8f;
                protected virtual float RocketOrbitTime => 60f;

                private void ResetOrbit()
                {
                    _orbitBase = _orbitBearing = float.NaN;
                    _orbitTry = 0;
                    _orbitTried.Clear();
                    _stallSince = -1f;
                }

                private float BearingFromTarget(Vector3 pos) => Mathf.Atan2(pos.x - _fireAt.x, pos.z - _fireAt.z) * Mathf.Rad2Deg;

                private bool OrbitActive(float now) => !float.IsNaN(_orbitBearing) && now < _orbitUntil && _attack != null
                    && Mathf.Abs(Mathf.DeltaAngle(BearingFromTarget(_attack.transform.position), _orbitBearing)) > 5f;

                private bool NextOrbit(string why, bool step = true)
                {
                    Vector3 pos = _attack.transform.position;
                    float current = BearingFromTarget(pos);
                    if (!Tried(current)) _orbitTried.Add(current);
                    if (float.IsNaN(_orbitBase)) _orbitBase = current;
                    _orbitTry++;
                    _orbitUntil = UnityEngine.Time.time + RocketOrbitTime;
                    if (PickOrbitBearing(pos, current, out float bearing))
                    {
                        _orbitBearing = bearing;
                        _orbitTried.Add(bearing);
                        Note(string.Format("{0}: {1} - moving around target to a firing spot {2:+0;-0} deg away", Debug.Id(_bot), why,
                            Mathf.DeltaAngle(current, bearing)));
                        return true;
                    }
                    if (!step) return false;
                    float shift = Mathf.Repeat(_orbitTry * RocketOrbitStep + 180f, 360f) - 180f;
                    _orbitBearing = _orbitBase + _orbitTry * RocketOrbitStep;
                    Note(string.Format("{0}: {1}, no clear firing spot found around target - circling, shift {2:+0;-0} deg from the original spot",
                        Debug.Id(_bot), why, shift));
                    return false;
                }

                private bool Tried(float bearing)
                {
                    foreach (float tried in _orbitTried)
                        if (Mathf.Abs(Mathf.DeltaAngle(tried, bearing)) < 12f) return true;
                    return false;
                }

                private static readonly float[] OrbitShifts = { 25f, -25f, 50f, -50f, 75f, -75f, 100f, -100f, 130f, -130f, 160f, -160f };

                private bool PickOrbitBearing(Vector3 pos, float current, out float bearing)
                {
                    bearing = float.NaN;
                    if (!RocketBallistics(_attack.GetRockets(), out float speed, out float gravity)) return false;
                    if (new Vector2(pos.x - _fireAt.x, pos.z - _fireAt.z).magnitude < 10f) return false;
                    foreach (float shift in OrbitShifts)
                    {
                        float candidate = current + shift;
                        if (Tried(candidate) || !FiringSpot(candidate, pos.y, speed, gravity)) continue;
                        bearing = candidate;
                        return true;
                    }
                    return false;
                }

                private bool FiringSpot(float bearing, float currentY, float speed, float gravity)
                {
                    Vector3 dir = new Vector3(Mathf.Sin(bearing * Mathf.Deg2Rad), 0f, Mathf.Cos(bearing * Mathf.Deg2Rad));
                    Vector3 spot = _fireAt + dir * Mathf.Max(_baseKeep, RocketMinRange);
                    spot.y = HoverEstimate(spot, -dir, currentY, false);
                    spot = _fireAt + dir * KeepAt(spot.y - _fireAt.y);
                    spot.y = HoverEstimate(spot, -dir, currentY, true);
                    spot = _fireAt + dir * KeepAt(spot.y - _fireAt.y) + Vector3.up * (spot.y - _fireAt.y);
                    float distance = Vector3.Distance(spot, _fireAt);
                    if (distance > RocketRange || distance < RocketMinRange) return false;
                    float nose = BallisticNose(spot, _fireAt, speed, gravity);
                    if (float.IsNaN(nose) || nose > RocketMaxDive - 1f) return false;
                    return PredictedArcClear(spot, -dir, nose, speed, gravity);
                }

                private float KeepAt(float height)
                {
                    if (height <= 0f) return Mathf.Max(_baseKeep, RocketMinRange);
                    float cap = RocketRange * 0.8f;
                    if (RocketStandoffLimit > 0f) cap = Mathf.Min(cap, Mathf.Sqrt(Mathf.Max(0f, RocketStandoffLimit * RocketStandoffLimit - height * height)));
                    return Mathf.Max(Mathf.Max(_baseKeep, RocketMinRange), Mathf.Min(StandoffFor(height), cap));
                }

                private float HoverEstimate(Vector3 spot, Vector3 toTarget, float currentY, bool obstacles)
                {
                    float ground = TerrainMeta.HeightMap.GetHeight(spot);
                    float cruise = CruiseAltitude;
                    float band = Mathf.Clamp(AltitudeDeadZone, 0f, Mathf.Min(cruise * 0.5f, Mathf.Max(0f, cruise - 20f)));
                    float margin = Mathf.Min(15f, cruise * 0.6f);
                    float floor = ground + cruise - band;
                    for (float d = 20f; d <= 100f; d += 20f)
                        floor = Mathf.Max(floor, TerrainMeta.HeightMap.GetHeight(spot + toTarget * d) + margin);
                    if (obstacles)
                    {
                        float from = Mathf.Max(currentY, floor) + 60f;
                        for (float d = 0f; d <= 80f; d += 20f)
                        {
                            Vector3 column = spot + toTarget * d;
                            if (Physics.SphereCast(new Vector3(column.x, from, column.z), ObstacleProbeRadius, Vector3.down, out RaycastHit hit, from - ground + 5f,
                                    ObstacleClimbMask, QueryTriggerInteraction.Ignore)
                                && hit.point.y > TerrainMeta.HeightMap.GetHeight(hit.point) + 1f)
                                floor = Mathf.Max(floor, hit.point.y + margin);
                        }
                    }
                    return Mathf.Clamp(currentY, floor, Mathf.Max(ground + cruise + band, floor));
                }

                private bool PredictedArcClear(Vector3 spot, Vector3 toTarget, float nose, float speed, float gravity)
                {
                    float rad = nose * Mathf.Deg2Rad;
                    Vector3 forward = toTarget * Mathf.Cos(rad) + Vector3.down * Mathf.Sin(rad);
                    Vector3 side = new Vector3(toTarget.z, 0f, -toTarget.x) * 1.12f;
                    Vector3 start = spot + Vector3.up * 0.55f + forward * 2.05f;
                    if (!ArcHits(start, forward, speed, gravity, out _)) return false;
                    return ArcHits(start + side, forward, speed, gravity, out _) || ArcHits(start - side, forward, speed, gravity, out _);
                }

                protected override Vector3 FollowDrift(Vector3 pos, Vector3 target)
                {
                    if (float.IsNaN(_orbitBearing) || !_hasFireTarget || _attack == null || UnityEngine.Time.time >= _orbitUntil) return Vector3.zero;
                    Vector3 from = pos - _fireAt;
                    from.y = 0f;
                    float radius = from.magnitude;
                    if (radius < 10f) return Vector3.zero;
                    float delta = Mathf.DeltaAngle(Mathf.Atan2(from.x, from.z) * Mathf.Rad2Deg, _orbitBearing);
                    if (Mathf.Abs(delta) < 3f) return Vector3.zero;
                    _orbitDriftFrame = UnityEngine.Time.frameCount;
                    Vector3 tangent = Vector3.Cross(Vector3.up, from / radius);
                    return tangent * Mathf.Clamp(delta * Mathf.Deg2Rad * radius * 0.4f, -RocketOrbitSpeed, RocketOrbitSpeed);
                }

                private bool OrbitDrifting => _orbitDriftFrame == UnityEngine.Time.frameCount;
                protected override bool SideFeedForward => OrbitDrifting || base.SideFeedForward;
                protected override float MaxSideBank => OrbitDrifting ? Mathf.Max(base.MaxSideBank, RocketOrbitBank) : base.MaxSideBank;

                protected override Vector3 FollowFace(Vector3 target)
                {
                    if (!_hasFireTarget || !_rocketsReady) return target;
                    Vector3 lead = _fireAt - target;
                    lead.y = 0f;
                    return lead.sqrMagnitude <= FireFaceLead * FireFaceLead ? _fireAt : target;
                }
                private const float FireFaceLead = 40f;

                protected override float FollowKeepFor(float keep)
                {
                    _baseKeep = keep;
                    if (keep <= 0f || !_hasFireTarget || !_rocketsReady || _attack == null) return keep;
                    float height = _attack.transform.position.y - _fireAt.y;
                    if (height <= 0f) return keep;
                    if (_keepFrame != UnityEngine.Time.frameCount || height != _keepHeight)
                    {
                        _keepFrame = UnityEngine.Time.frameCount;
                        _keepHeight = height;
                        _keepNeed = StandoffFor(height);
                    }
                    float cap = RocketRange * 0.8f;
                    if (RocketStandoffLimit > 0f) cap = Mathf.Min(cap, Mathf.Sqrt(Mathf.Max(0f, RocketStandoffLimit * RocketStandoffLimit - height * height)));
                    return Mathf.Max(keep, Mathf.Min(_keepNeed, cap));
                }

                private float StandoffFor(float height)
                {
                    float tan = Mathf.Tan(Mathf.Clamp(RocketHoldDive, 5f, 80f) * Mathf.Deg2Rad);
                    if (!RocketBallistics(_attack.GetRockets(), out float speed, out float gravity) || gravity <= 0.0001f) return height / tan;
                    float a = gravity * (1f + tan * tan) / (2f * speed * speed);
                    return (-tan + Mathf.Sqrt(tan * tan + 4f * a * height)) / (2f * a);
                }

                private bool RocketBallistics(AttackHelicopterRockets rockets, out float speed, out float gravity)
                {
                    speed = 0f;
                    gravity = 0f;
                    ItemDefinition def = AttackHeliAim.NextRocket(rockets);
                    if (def == null) return false;
                    if (def != _ammoDef)
                    {
                        _ammoDef = def;
                        _ammoSpeed = 0f;
                        ItemModProjectile mod = def.GetComponent<ItemModProjectile>();
                        GameObject prefab = mod != null && mod.projectileObject != null ? mod.projectileObject.Get() : null;
                        ServerProjectile projectile = prefab != null ? prefab.GetComponent<ServerProjectile>() : null;
                        if (projectile != null)
                        {
                            _ammoSpeed = (projectile.initialVelocity + Vector3.forward * projectile.speed).magnitude;
                            _ammoGravity = -Physics.gravity.y * projectile.gravityModifier;
                        }
                    }
                    if (_ammoSpeed <= 0f) return false;
                    speed = Mathf.Max(_ammoSpeed, _attack.GetSpeed() + 2f);
                    gravity = _ammoGravity;
                    return true;
                }

                private static float BallisticNose(Vector3 from, Vector3 to, float speed, float gravity)
                {
                    float x = new Vector2(to.x - from.x, to.z - from.z).magnitude;
                    float y = to.y - from.y;
                    if (x < 0.5f) return y < 0f ? 90f : -90f;
                    if (gravity <= 0.0001f) return -Mathf.Atan2(y, x) * Mathf.Rad2Deg;
                    float a = gravity * x * x / (2f * speed * speed);
                    float disc = x * x - 4f * a * (y + a);
                    if (disc < 0f) return float.NaN;
                    return -Mathf.Atan((x - Mathf.Sqrt(disc)) / (2f * a)) * Mathf.Rad2Deg;
                }

                private float RocketAimNose(AttackHelicopterRockets rockets)
                {
                    Vector3 from = rockets != null ? rockets.MuzzleMidPoint() + _attack.transform.forward : _attack.transform.position;
                    float nose = RocketBallistics(rockets, out float speed, out float gravity) ? BallisticNose(from, _fireAt, speed, gravity) : float.NaN;
                    if (float.IsNaN(nose))
                    {
                        Vector3 to = _fireAt - from;
                        nose = Mathf.Atan2(-to.y, new Vector2(to.x, to.z).magnitude) * Mathf.Rad2Deg;
                    }
                    return nose;
                }

                public float RocketStandoffLimit { get; set; }

                protected override bool PreDriveTick()
                {
                    bool go = base.PreDriveTick();
                    if (_attack == null || _attack.IsDestroyed) return go;

                    TryFlares();
                    TryRockets();
                    return go;
                }

                private void TryFlares()
                {
                    float now = UnityEngine.Time.time;
                    if (now < _nextFlare || now < _nextSamScan) return;
                    _nextSamScan = now + SamScanInterval;

                    Vector3 pos = _attack.transform.position;
                    if (pos.y - TerrainMeta.HeightMap.GetHeight(pos) < 15f) return;

                    List<SamSite> sams = Pool.Get<List<SamSite>>();
                    BaseEntity.Query.Server.GetInSphere(pos, SamDanger, sams);
                    SamSite hunter = null;
                    for (int i = 0; i < sams.Count; i++)
                    {
                        SamSite sam = sams[i];
                        if (sam == null || sam.IsDestroyed || !sam.IsPowered()) continue;
                        if (Vector3.Distance(sam.transform.position, pos) > sam.vehicleScanRadius) continue;
                        if (!ReferenceEquals(sam.currentTarget, _attack)) continue;
                        hunter = sam;
                        break;
                    }
                    Pool.FreeUnmanaged(ref sams);
                    if (hunter == null) return;

                    _nextFlare = UnityEngine.Time.time + FlareCooldown;
                    if (_attack.GetRockets() != null && _attack.GetRockets().TryFireFlare())
                        Note(string.Format("{0}: tracked by SAM site {1} at {2:0} m - deployed flare",
                            Debug.Id(_bot), hunter.ShortPrefabName, Vector3.Distance(hunter.transform.position, pos)));
                }

                protected override bool PitchOverride(Vector3 velocity, out float noseDown)
                {
                    bool diving = _rocketAiming;
                    float now = UnityEngine.Time.time;
                    float dt = Mathf.Clamp(now - _pitchAt, 0f, 0.25f);
                    _pitchAt = now;
                    _recovering = false;
                    if (DivePitch(velocity, diving, now, dt, out noseDown)) return true;
                    if (diving)
                    {
                        _recoverUntil = now + RocketRecoverTime;
                        if (!_diveFired && _diveLineBlocked) NextOrbit("line of fire blocked");
                    }
                    if (now >= _recoverUntil || _attack == null || NoseDown <= 2f) return false;
                    noseDown = 0f;
                    _recovering = true;
                    return true;
                }

                private bool DivePitch(Vector3 velocity, bool diving, float now, float dt, out float noseDown)
                {
                    noseDown = 0f;
                    _rocketAiming = false;
                    if (!_hasFireTarget || !_rocketsReady || ClimbFirst || _attack == null) return false;
                    if (now < _nextRocket - 1f || now < _diveBlockedUntil) return false;
                    Vector3 to = _fireAt - _attack.transform.position;
                    float distance = to.magnitude;
                    if (distance > RocketRange || distance < RocketMinRange) return false;
                    Vector3 flat = new Vector3(to.x, 0f, to.z);
                    Vector3 forward = _attack.transform.forward;
                    forward.y = 0f;
                    if (flat.sqrMagnitude < 1f || forward.sqrMagnitude < 0.001f) return false;
                    if (Vector3.Angle(forward, flat) > RocketAim) return false;
                    float range = flat.magnitude;
                    Vector3 line = flat / range;
                    float closing = Vector3.Dot(velocity, line) - Mathf.Max(0f, Vector3.Dot(FollowVelocity(), line));
                    float minRun = RocketMinRange * 1.5f;
                    float aim = RocketAimNose(_attack.GetRockets());
                    float maxDive = now < _steepUntil ? RocketMaxDive + RocketSteepExtra : RocketMaxDive;
                    float swing = Mathf.Max(0f, Mathf.Min(aim, maxDive) - NoseDown);
                    float back = Mathf.Max(0f, -closing) * swing / Mathf.Max(1f, RocketDiveRate) * 0.5f;
                    float height = -to.y;
                    float reach = aim - (Mathf.Atan2(height, range) - Mathf.Atan2(height, range + back)) * Mathf.Rad2Deg;
                    if (!diving && (range < Mathf.Max(minRun, FollowKeep * 0.9f - back) || reach > maxDive - 0.5f || closing > RocketDiveSpeed))
                    {
                        if (reach > maxDive - 0.5f && range >= FollowKeep * 0.9f - back && closing <= RocketDiveSpeed && !OrbitActive(now)) SteepStall(now);
                        else _stallSince = -1f;
                        return false;
                    }
                    _stallSince = -1f;
                    if (!diving && OrbitActive(now)) return false;
                    if (!diving && now >= _nextLineProbe)
                    {
                        _nextLineProbe = now + 1f;
                        if (RocketBallistics(_attack.GetRockets(), out float arcSpeed, out float arcGravity)
                            && !PredictedArcClear(_attack.transform.position, flat / range, aim, arcSpeed, arcGravity))
                        {
                            NextOrbit("line of fire from here is blocked");
                            return false;
                        }
                    }
                    float cutRange = Mathf.Max(minRun, FollowKeep * 0.75f), cutClosing = RocketDiveSpeed * 2.5f;
                    if (diving && (range < cutRange || closing > cutClosing))
                    {
                        _diveBlockedUntil = now + RocketDivePause;
                        return false;
                    }
                    _diveCutSoon = diving && (range - Mathf.Max(0f, closing) * RocketCutLead < cutRange || closing > cutClosing * 0.8f);
                    if (!diving)
                    {
                        _diveStart = now;
                        _diveFired = _diveLineBlocked = false;
                        _diveArrived = -1f;
                        _rocketBias = 0f;
                        _diveSwing = swing;
                    }
                    if (_diveArrived < 0f && aim - NoseDown < 2f) _diveArrived = now;
                    if (now - _diveStart > DiveLimit || (_diveArrived >= 0f && now - _diveArrived > RocketDiveHold))
                    {
                        _diveBlockedUntil = now + RocketDivePause;
                        return false;
                    }
                    if (Mathf.Abs(aim - NoseDown) < 3f && Mathf.Abs(NoseDownRate) < 5f)
                        _rocketBias = Mathf.Clamp(_rocketBias + (aim - NoseDown) * RocketNoseTrim * dt, -3f, 3f);
                    noseDown = Mathf.Clamp(aim + _rocketBias, -5f, maxDive);
                    _rocketAiming = true;
                    return true;
                }

                private void SteepStall(float now)
                {
                    if (_stallSince < 0f) _stallSince = now;
                    if (now - _stallSince < RocketStallTime) return;
                    _stallSince = -1f;
                    if (NextOrbit("nose cannot reach the firing angle at this range", false)) return;
                    ResetOrbit();
                    _steepUntil = now + RocketSteepTime;
                    Note(string.Format("{0}: no lower firing spot around target - diving steeper, up to {1:0} deg", Debug.Id(_bot), RocketMaxDive + RocketSteepExtra));
                }

                private bool DiveEnding(float now)
                {
                    if (_diveCutSoon) return true;
                    return now - _diveStart > DiveLimit - 0.3f || (_diveArrived >= 0f && now - _diveArrived > RocketDiveHold - 0.3f);
                }

                private float DiveLimit => Mathf.Max(RocketDiveTime, _diveSwing / Mathf.Max(1f, RocketDiveRate) * 1.5f + RocketDiveHold);
                private const float RocketCutLead = 0.5f;
                private bool _diveCutSoon;

                private void TryRockets()
                {
                    if (!_hasFireTarget || UnityEngine.Time.time < _nextProjection) return;
                    _nextProjection = UnityEngine.Time.time + 0.1f;

                    AttackHelicopterRockets rockets = _attack.GetRockets();
                    if (rockets == null) return;
                    _rocketsReady = rockets.GetRocketAmount() > 0;
                    if (!_rocketsReady)
                    {
                        Note(string.Format("{0}: out of rockets", Debug.Id(_bot)));
                        _hasFireTarget = false;
                        return;
                    }

                    Vector3 pos = _attack.transform.position;
                    float distance = Vector3.Distance(pos, _fireAt);
                    if (distance > RocketRange || distance < RocketMinRange) return;

                    Vector3 hit = ProjectedHit(rockets);
                    float miss = Vector3.Distance(hit, _fireAt);
                    float prevMiss = _prevMiss;
                    _prevMiss = _rocketAiming ? miss : float.NaN;
                    if (_rocketAiming && miss > RocketHitRadius && Mathf.Abs(RocketAimNose(rockets) - NoseDown) < 1f
                        && Vector3.Distance(hit, pos) < distance - RocketHitRadius && hit.y - TerrainMeta.HeightMap.GetHeight(hit) > 2f)
                        _diveLineBlocked = true;
                    if (miss > RocketHitRadius || UnityEngine.Time.time < _nextRocket || !rockets.CanFireRocket) return;
                    if (_rocketAiming && miss > RocketTightRadius && (float.IsNaN(prevMiss) || miss < prevMiss - RocketSettleStep)
                        && !DiveEnding(UnityEngine.Time.time)) return;
                    if (Vector3.Distance(hit, pos) < RocketMinRange) return;
                    if (!RocketLineClear(rockets, hit))
                    {
                        if (_rocketAiming) _diveLineBlocked = true;
                        return;
                    }

                    _nextRocket = UnityEngine.Time.time + RocketCooldown;
                    _diveBlockedUntil = UnityEngine.Time.time + RocketDivePause;
                    if (rockets.TryFireRocket(_bot))
                    {
                        _diveFired = true;
                        ResetOrbit();
                        Note(string.Format("{0}: salvo at target, range {1:0} m, predicted burst {2:0.0} m from it, rockets left {3}",
                            Debug.Id(_bot), distance, miss, rockets.GetRocketAmount()));
                    }
                }

                private Vector3 ProjectedHit(AttackHelicopterRockets rockets)
                {
                    Vector3 origin = rockets.MuzzleMidPoint() + rockets.rocketMuzzlePositions[0].forward;
                    Vector3 forward = _attack.transform.forward;
                    if (RocketBallistics(rockets, out float speed, out float gravity)
                        && Ballistics.TryGetPhysicsProjectileHitPos(origin, forward, speed, -gravity, out Vector3 hit, 1.5f, 0.5f, 32f, _attack)) return hit;
                    return origin + forward * 1000f;
                }

                private static readonly int RocketLineMask = LayerMask.GetMask("Terrain", "World", "Construction", "Deployed", "Default", "Tree");
                private float _nextLineNote;

                private bool RocketLineClear(AttackHelicopterRockets rockets, Vector3 hit)
                {
                    Transform[] muzzles = rockets.rocketMuzzlePositions;
                    if (muzzles == null || muzzles.Length < 2 || muzzles[0] == null || muzzles[1] == null
                        || !RocketBallistics(rockets, out float speed, out float gravity)) return true;
                    int next = rockets.leftSide ? 0 : 1;
                    if (RocketArcHits(muzzles[next], speed, gravity, out RaycastHit block)) return true;
                    if (RocketArcHits(muzzles[1 - next], speed, gravity, out _))
                    {
                        rockets.leftSide = !rockets.leftSide;
                        return true;
                    }
                    if (UnityEngine.Time.time >= _nextLineNote)
                    {
                        _nextLineNote = UnityEngine.Time.time + 5f;
                        Note(string.Format("{0}: rocket line of fire blocked ({1}) - not firing", Debug.Id(_bot), block.collider != null
                            ? string.Format("{0} at {1:0} m", block.collider.name, Vector3.Distance(block.point, muzzles[next].position)) : "off target"));
                    }
                    return false;
                }

                private const float RocketArcStep = 0.2f, RocketArcRadius = 0.3f;

                private bool RocketArcHits(Transform muzzle, float speed, float gravity, out RaycastHit block)
                    => ArcHits(muzzle.position + muzzle.forward, muzzle.forward, speed, gravity, out block);

                private bool ArcHits(Vector3 pos, Vector3 forward, float speed, float gravity, out RaycastHit block)
                {
                    block = default;
                    Vector3 velocity = forward * speed;
                    float left = new Vector2(_fireAt.x - pos.x, _fireAt.z - pos.z).magnitude + RocketHitRadius + 30f;
                    for (int i = 0; i < 80 && left > 0f; i++)
                    {
                        Vector3 step = velocity * RocketArcStep + Vector3.down * (0.5f * gravity * RocketArcStep * RocketArcStep);
                        velocity += Vector3.down * (gravity * RocketArcStep);
                        float length = step.magnitude;
                        if (length < 0.01f) break;
                        Vector3 dir = step / length;
                        if (Physics.SphereCast(pos, RocketArcRadius, dir, out block, length, RocketLineMask, QueryTriggerInteraction.Ignore)
                            && Vector3.Distance(block.point, _fireAt) > RocketHitRadius) return false;
                        if (Physics.Raycast(pos, dir, out block, length, RocketLineMask, QueryTriggerInteraction.Ignore))
                            return Vector3.Distance(block.point, _fireAt) <= RocketHitRadius;
                        pos += step;
                        left -= new Vector2(step.x, step.z).magnitude;
                    }
                    block = default;
                    return false;
                }

                protected virtual float SamDanger => 400f;

                protected virtual float FlareCooldown => 4f;

                protected virtual float SamScanInterval => 1f;
            }

            #endregion

            #region Стрелок боевого вертолёта

            public class HeliGunner : MonoBehaviour
            {
                protected virtual float TurretRange => 250f;

                protected virtual float SectorTolerance => 2f;

                protected virtual float SteadyAngle => 3f;

                private Vector3 _lastGun;
                private bool _hasLastGun;

                public bool TargetInSector { get; private set; }

                public float TargetYaw { get; private set; }

                private BaseCustomNpc _bot;
                private ulong _botId;
                private BaseMountable _seat;
                private bool _attached;
                private bool _released;
                private AttackHelicopter _heli;
                private AttackHelicopterTurret _turret;
                private BaseEntity _target;
                private Vector3 _groundTarget;
                private bool _hasGroundTarget;

                private readonly AttackHelicopter.GunnerInputState _input = new AttackHelicopter.GunnerInputState();

                public BaseCustomNpc Bot => _bot;

                public string Take(BaseCustomNpc bot, AttackHelicopter heli)
                {
                    if (bot == null || !bot.IsValid()) return "bot is missing";
                    if (heli == null || heli.IsDestroyed) return "helicopter is missing";

                    AttackHelicopterTurret turret = heli.GetTurret();
                    if (turret == null) return "turret has not spawned yet";

                    BaseMountable seat = FindPassengerSeat(heli);
                    if (seat == null) return "no free gunner seat";

                    ReleaseRoles(bot, this, "mounting turret seat");

                    _bot = bot;
                    _botId = bot.userID;
                    _heli = heli;
                    _turret = turret;

                    MoveBot(bot, heli.transform.position + Vector3.up * 1.5f);
                    seat.MountPlayer(bot);
                    if (bot.GetMounted() != seat) return "failed to mount";
                    _seat = seat;

                    bot.GetComponent<INavigator>()?.Pause();
                    _gunners[_botId] = this;
                    _attached = true;
                    Note(string.Format("{0}: mounted turret, ammo {1}",
                        Debug.Id(bot), _turret.InventoryAmmo));
                    return null;
                }

                public void Aim(BaseEntity target)
                {
                    _target = target;
                    _hasGroundTarget = false;
                    Note(string.Format("{0}: turret target - {1}", Debug.Id(_bot),
                        target != null ? target.ShortPrefabName : "none"));
                }

                public void Aim(Vector3 point)
                {
                    _target = null;
                    _groundTarget = point;
                    _hasGroundTarget = true;
                    Note(string.Format("{0}: turret target - point {1}", Debug.Id(_bot), point));
                }

                public void CeaseFire()
                {
                    _target = null;
                    _hasGroundTarget = false;
                }

                public void Release(string why)
                {
                    if (_released) return;
                    _released = true;

                    if (_bot != null && _bot.IsValid())
                    {
                        if (_bot.isMounted && _bot.GetMounted() == _seat) _bot.DismountSafely();
                        _bot.GetComponent<INavigator>()?.Resume();
                    }
                    ReleaseTurret();
                    Destroy(this);
                    Note(string.Format("{0}: left turret ({1})", Debug.Id(_bot), why));
                }

                private void ReleaseTurret()
                {
                    if (_heli != null && !_heli.IsDestroyed)
                    {
                        using(var flags = _heli.StartSetFlags(BaseEntity.FlagsUpdateMode.SendNetworkUpdate))
                            flags.Set(BaseEntity.Flags.Reserved9, false);
                    }
                    if (_gunners.TryGetValue(_botId, out HeliGunner registered) && registered == this)
                        _gunners.Remove(_botId);
                }

                private void OnDestroy()
                {
                    if (_released || !_attached) return;
                    _released = true;
                    ReleaseTurret();
                    if (_bot != null && _bot.IsValid()) _bot.GetComponent<INavigator>()?.Resume();
                    Note(string.Format("{0}: gunner destroyed with the bot (bot died or was removed)", _botId));
                }

                private void Update()
                {
                    if (_released) return;
                    if (_bot == null || !_bot.IsValid() || _heli == null || _heli.IsDestroyed)
                    {
                        Release("bot or helicopter disappeared");
                        return;
                    }
                    if (_bot.isMounted && _bot.GetMounted() != _seat)
                    {
                        Release("left gunner seat");
                        return;
                    }
                    if (_turret == null) _turret = _heli.GetTurret();
                    if (_turret == null) return;

                    bool wantGunner = _heli.IsOn() && _bot.GetMounted() == _seat;
                    if (_heli.GunnerIsInGunnerView != wantGunner)
                    {
                        using(var flags = _heli.StartSetFlags(BaseEntity.FlagsUpdateMode.SendNetworkUpdate))
                            flags.Set(BaseEntity.Flags.Reserved9, wantGunner);
                    }
                    if (!wantGunner) return;

                    Vector3 aimPoint;
                    if (_target != null && !_target.IsDestroyed) aimPoint = _target.CenterPoint();
                    else if (_hasGroundTarget) aimPoint = _groundTarget;
                    else
                    {
                        _hasLastGun = false;
                        return;
                    }

                    Vector3 eye = _bot.eyes.position;
                    Vector3 to = aimPoint - eye;
                    float distance = to.magnitude;
                    if (distance < 0.1f) return;
                    Vector3 want = to / distance;
                    Vector3 dir = ClampToTurret(want);
                    TargetInSector = Vector3.Angle(dir, want) <= SectorTolerance;
                    Vector3 local = _heli.transform.InverseTransformDirection(want);
                    TargetYaw = Mathf.Atan2(local.x, local.z) * Mathf.Rad2Deg;
                    bool inRange = distance <= TurretRange && distance > 3f;
                    Vector3 gun = _heli.transform.InverseTransformDirection(dir);
                    bool steady = _hasLastGun && Vector3.Angle(gun, _lastGun) <= SteadyAngle;
                    _lastGun = gun;
                    _hasLastGun = true;

                    _bot.eyes.rotation = Quaternion.LookRotation(dir, Vector3.up);
                    _bot.viewAngles = _bot.eyes.rotation.eulerAngles;
                    _input.Reset();
                    _input.eyePos = eye;
                    _input.eyeRay = new Ray(eye + dir * 0.5f, dir);
                    _input.fire1 = inRange && TargetInSector && steady && HasAmmo();

                    _turret.InputTick(_input);
                }

                private Vector3 ClampToTurret(Vector3 dir)
                {
                    Transform heli = _heli.transform;
                    Vector3 local = heli.InverseTransformDirection(dir);
                    float pitch = Mathf.Clamp(Mathf.Asin(Mathf.Clamp(-local.y, -1f, 1f)) * Mathf.Rad2Deg,
                        _heli.turretPitchClamp.x, _heli.turretPitchClamp.y);
                    float yaw = Mathf.Clamp(Mathf.Atan2(local.x, local.z) * Mathf.Rad2Deg,
                        _heli.turretYawClamp.x, _heli.turretYawClamp.y);
                    return heli.TransformDirection(Quaternion.Euler(pitch, yaw, 0f) * Vector3.forward);
                }

                private bool HasAmmo()
                {
                    if (_turret.InventoryAmmo > 0 || _turret.ClipAmmo > 0) return true;
                    if (_turret.GetAttachedHeldEntity() is BaseProjectile gun && gun.primaryMagazine != null && gun.primaryMagazine.contents > 0) return true;
                    if (_turret.inventory == null) return false;
                    foreach (Item item in _turret.inventory.itemList)
                        if (item.info.category == ItemCategory.Ammunition && item.amount > 0) return true;
                    return false;
                }

                private static BaseMountable FindPassengerSeat(BaseVehicle vehicle)
                {
                    foreach (BaseVehicle.MountPointInfo mp in vehicle.allMountPoints)
                    {
                        if (mp == null || mp.isDriver || mp.mountable == null) continue;
                        if (mp.mountable.AnyMounted()) continue;
                        return mp.mountable;
                    }
                    return null;
                }
            }

            private static readonly Dictionary<ulong, HeliGunner> _gunners = new Dictionary<ulong, HeliGunner>();

            #endregion

            #region Подводный транспорт

            public class SubmarineController : VehicleControllerBase
            {
                protected virtual float CruiseDepth => Tuning?.CruiseDepth ?? 6f;

                protected virtual float DepthDeadZone => Tuning?.DepthDeadZone ?? 1.5f;

                protected virtual float BottomClearance => Tuning?.BottomClearance ?? 3f;

                protected override float ArriveDistance => 20f;

                protected override float FinalApproach => 45f;

                protected override bool FlatDistance => true;

                private BaseSubmarine _sub;
                private float _nextSubNote;
                private float _agroundSince;
                private bool _pushTried;

                protected override void OnAttached()
                {
                    _sub = _vehicle as BaseSubmarine;
                    if (_sub == null) return;
                    Note(string.Format("{0}: at submarine controls", Debug.Id(_bot)));
                }

                protected override List<Vector3> RouteTo(Vector3 target, out string how)
                {
                    float need = CruiseDepth + BottomClearance;
                    Vector3 deep = DeepWaterNear(target, need, out float moved);
                    List<Vector3> route = BuildRoute(_vehicle.transform.position, deep, true, out how, need);
                    if (moved > 1f) how += $", target moved away from shallows by {moved:0} m";
                    return route;
                }

                protected override bool PreDriveTick()
                {
                    if (_sub == null) return true;

                    Vector3 pos = _sub.transform.position;
                    float bottom = TerrainMeta.HeightMap.GetHeight(pos);

                    if (pos.y - bottom < BottomClearance)
                    {
                        if (_agroundSince <= 0f) { _agroundSince = UnityEngine.Time.time; _pushTried = false; }
                        float aground = UnityEngine.Time.time - _agroundSince;

                        if (aground > 10f && !_pushTried)
                        {
                            _pushTried = true;
                            bool pushed = PushVehicle(4);
                            Note(string.Format("{0}: aground for {1} s - {2}",
                                Debug.Id(_bot), aground, pushed ? "pushing boat" : "failed to push"));
                        }
                        if (aground > 30f)
                        {
                            Note(string.Format("{0}: boat aground for {1:0} s - dismounting",
                                Debug.Id(_bot), aground));
                            Release("submarine aground");
                            return false;
                        }

                        Vector3 deeper = DeeperWaterDirection(40f);
                        if (deeper != Vector3.zero)
                        {
                            float heading = Vector3.SignedAngle(_sub.transform.forward, deeper, Vector3.up);
                            int buttons = (int)BUTTON.SPRINT;
                            if (heading > 8f) buttons |= (int)BUTTON.RIGHT;
                            else if (heading < -8f) buttons |= (int)BUTTON.LEFT;
                            buttons |= Mathf.Abs(heading) < 60f ? (int)BUTTON.FORWARD : (int)BUTTON.BACKWARD;
                            PushPlayerInput(buttons, Vector3.zero);

                            if (UnityEngine.Time.time >= _nextSubNote)
                            {
                                _nextSubNote = UnityEngine.Time.time + 2f;
                                Note(string.Format("{0}: seabed clearance only {1:0.0} m - moving deeper",
                                    Debug.Id(_bot), pos.y - bottom));
                            }
                            return false;
                        }
                    }
                    else _agroundSince = 0f;

                    return true;
                }

                protected override void SendControl(float throttle, float steerDegrees, bool sharpSteer)
                {
                    if (_vehicle == null) { PushPlayerInput(0, Vector3.zero); return; }

                    int buttons = 0;
                    if (throttle > 0.1f) buttons |= (int)BUTTON.FORWARD;
                    else if (throttle < -0.1f) buttons |= (int)BUTTON.BACKWARD;

                    if (steerDegrees > 1f) buttons |= (int)BUTTON.RIGHT;
                    else if (steerDegrees < -1f) buttons |= (int)BUTTON.LEFT;

                    Vector3 pos = _vehicle.transform.position;
                    float surface = WaterLevel.GetWaterSurface(pos, waves: false, volumes: true);
                    float bottom = TerrainMeta.HeightMap.GetHeight(pos);
                    float depth = surface - pos.y;
                    float overBottom = pos.y - bottom;

                    if (overBottom < BottomClearance) buttons |= (int)BUTTON.SPRINT;
                    else if (depth < CruiseDepth - DepthDeadZone) buttons |= (int)BUTTON.DUCK;
                    else if (depth > CruiseDepth + DepthDeadZone) buttons |= (int)BUTTON.SPRINT;

                    PushPlayerInput(buttons, Vector3.zero);
                }
            }

            #endregion

            #region Рельсовый транспорт

            public class TrainVehicleController : VehicleControllerBase
            {
                protected virtual float LeverPressTime => 0.15f;

                protected virtual float BrakingDistance => 250f;

                protected virtual float ArriveRail => 30f;

                protected virtual float RailCruise => 16f;

                protected virtual float BlockedGiveUp => 30f;

                protected override float GetSpeed() => _train != null ? _train.GetTrackSpeed() : 0f;

                protected override bool AvoidsObstacles => false;

                protected override float FinalApproach => ArriveRail;

                protected override float ArriveDistance => ArriveRail;

                private TrainEngine _train;
                private float _leverUntil;
                private bool _leverPressed;
                private int _side;
                private List<TrainTrackSpline> _railRoute;
                private int _railIndex;
                private bool _railForward = true;
                private float _stoodSince;

                protected override void OnAttached()
                {
                    _train = _vehicle as TrainEngine;
                    if (_train == null) return;
                    Note(string.Format("{0}: in locomotive cab, throttle notch {1}",
                        Debug.Id(_bot), _train.CurThrottleSetting));
                }

                protected override List<Vector3> RouteTo(Vector3 target, out string how)
                {
                    _railRoute = null;
                    _railIndex = 0;
                    how = "by rail";
                    if (_train == null) return new List<Vector3> { target };

                    TrainTrackSpline from = _train.FrontTrackSection ?? NearestSpline(_train.transform.position);
                    TrainTrackSpline to = NearestSpline(target);
                    List<TrainTrackSpline> route = RailRoute(from, to);
                    if (route == null || route.Count == 0)
                    {
                        how = "by rail without a route: segments are disconnected";
                        return new List<Vector3> { target };
                    }
                    _railRoute = route;

                    List<Vector3> line = new List<Vector3>();
                    Vector3 last = _train.transform.position;
                    for (int i = 0; i < route.Count; i++)
                    {
                        Vector3[] pts = route[i].GetPointsWorld();
                        if (pts == null || pts.Length == 0) continue;

                        bool straight = (pts[0] - last).sqrMagnitude <= (pts[pts.Length - 1] - last).sqrMagnitude;
                        for (int k = 0; k < pts.Length; k++)
                        {
                            Vector3 p = straight ? pts[k] : pts[pts.Length - 1 - k];
                            if (line.Count == 0 || (p - line[line.Count - 1]).sqrMagnitude > 4f) line.Add(p);
                        }
                        if (line.Count > 0) last = line[line.Count - 1];
                    }

                    int nearest = 0;
                    float bestSqr = float.MaxValue;
                    Vector3 pos = _train.transform.position;
                    for (int i = 0; i < line.Count; i++)
                    {
                        float sqr = (line[i] - pos).sqrMagnitude;
                        if (sqr < bestSqr) { bestSqr = sqr; nearest = i; }
                    }
                    if (nearest > 0) line.RemoveRange(0, nearest);

                    _railForward = DecideForward(from, route.Count > 1 ? route[1] : null, target);

                    line.Add(target);
                    how = $"by rail ({route.Count} segments)";
                    return line;
                }

                private bool DecideForward(TrainTrackSpline cur, TrainTrackSpline next, Vector3 target)
                {
                    if (cur == null || _train == null) return true;

                    cur.GetPointAndTangentCubicHermiteWorld(_train.FrontWheelSplineDist, out Vector3 tangent);
                    bool goUp;
                    if (next != null && _railGraph.TryGetValue(cur, out RailLinks links))
                    {
                        goUp = links.Next.Contains(next) || !links.Prev.Contains(next);
                    }
                    else
                    {
                        cur.GetDistance(target, 1f, out float targetDist);
                        goUp = targetDist >= _train.FrontWheelSplineDist;
                    }

                    Vector3 dir = (goUp ? tangent : -tangent).normalized;
                    return Vector3.Dot(_train.transform.forward, dir) >= 0f;
                }

                protected override bool PreDriveTick()
                {
                    if (_train == null) return true;

                    if (Mathf.Abs(_train.GetTrackSpeed()) < 0.3f
                        && _train.CurThrottleSetting != TrainEngine.EngineSpeeds.Zero)
                    {
                        if (_stoodSince <= 0f) _stoodSince = UnityEngine.Time.time;
                        float stood = UnityEngine.Time.time - _stoodSince;
                        if (stood > BlockedGiveUp)
                        {
                            _stoodSince = 0f;
                            Halt();
                            return false;
                        }
                    }
                    else _stoodSince = 0f;

                    if (_leverPressed && UnityEngine.Time.time >= _leverUntil)
                    {
                        _leverPressed = false;
                        _leverUntil = UnityEngine.Time.time + LeverPressTime;
                        PushPlayerInput(SideButton(), Vector3.zero);
                        return false;
                    }
                    return true;
                }

                protected override void SendControl(float throttle, float steerDegrees, bool sharpSteer)
                {
                    if (_train == null) { PushPlayerInput(0, Vector3.zero); return; }

                    _side = SideForRoute();
                    int buttons = SideButton();

                    if (UnityEngine.Time.time < _leverUntil && !_leverPressed)
                    {
                        PushPlayerInput(buttons, Vector3.zero);
                        return;
                    }

                    int want = DesiredNotch();
                    int now = (int)_train.CurThrottleSetting;
                    if (want > now) buttons |= (int)BUTTON.FORWARD;
                    else if (want < now) buttons |= (int)BUTTON.BACKWARD;

                    if (want != now)
                    {
                        _leverPressed = true;
                        _leverUntil = UnityEngine.Time.time + LeverPressTime;
                    }

                    PushPlayerInput(buttons, Vector3.zero);
                }

                private int SideButton()
                    => _side < 0 ? (int)BUTTON.LEFT : _side > 0 ? (int)BUTTON.RIGHT : 0;

                private int DesiredNotch()
                {
                    int zero = (int)TrainEngine.EngineSpeeds.Zero;
                    if (!_hasTarget) return zero;

                    Vector3 pos = _vehicle.transform.position;
                    float distance = Vector3.Distance(pos, FinalGoal);
                    if (distance <= ArriveRail) return zero;

                    bool ahead = _railForward;

                    int steps;
                    if (distance > BrakingDistance * 2f) steps = 3;
                    else if (distance > BrakingDistance) steps = 2;
                    else steps = 1;

                    if (Mathf.Abs(_train.GetTrackSpeed()) > RailCruise && steps > 1) steps--;

                    return ahead ? zero + steps : zero - steps;
                }

                private int SideForRoute()
                {
                    if (_train == null || _railRoute == null || _railRoute.Count == 0) return 0;
                    TrainTrackSpline cur = _train.FrontTrackSection;
                    if (cur == null) return 0;

                    for (int i = _railIndex; i < _railRoute.Count; i++)
                    {
                        if (_railRoute[i] == cur) { _railIndex = i; break; }
                    }
                    if (_railRoute[_railIndex] != cur || _railIndex + 1 >= _railRoute.Count) return 0;

                    TrainTrackSpline want = _railRoute[_railIndex + 1];
                    if (!_railGraph.TryGetValue(cur, out RailLinks links)) return 0;

                    cur.GetPointAndTangentCubicHermiteWorld(_train.FrontWheelSplineDist, out Vector3 tangent);
                    bool facing = Vector3.Dot(_train.transform.forward, tangent) >= 0f;
                    bool goingUp = facing == (_train.GetTrackSpeed() >= 0f);

                    List<TrainTrackSpline> options = goingUp ? links.Next : links.Prev;
                    int idx = options.IndexOf(want);
                    if (idx < 0 || options.Count < 2) return 0;

                    bool flag = goingUp ^ facing;
                    if (idx == 0) return flag ? 1 : -1;
                    if (idx == options.Count - 1) return flag ? -1 : 1;
                    return 0;
                }
            }

            #endregion

            #region Управление лодкой

            public class BoatAiPilot : IAiInputProvider
            {
                private readonly BoatVehicleController _pilot;

                public BoatAiPilot(BoatVehicleController pilot) { _pilot = pilot; }

                public void OnAdd(BaseVehicle vehicle) { }

                public void OnRemove(BaseVehicle vehicle) { }

                public void OnTick(BaseVehicle vehicle, float delta) { }

                public void OnTick(BaseVehicle vehicle, float delta, ref float steering, ref float gasPedal)
                {
                    if (_pilot == null) { steering = 0f; gasPedal = 0f; return; }
                    steering = -_pilot.DesiredSteerNormalized;
                    gasPedal = _pilot.DesiredThrottle;
                }
            }

