            #region Поиск транспорта

            public static bool HasFreeDriverSeat(BaseVehicle vehicle, BasePlayer forWhom = null)
            {
                if (vehicle == null) return false;
                foreach (BaseVehicle.MountPointInfo mp in vehicle.allMountPoints)
                {
                    if (mp == null || !mp.isDriver || mp.mountable == null) continue;
                    if (!mp.mountable.AnyMounted()) return true;
                    return forWhom != null && mp.mountable.GetMounted() == forWhom;
                }
                return false;
            }

            public static BaseVehicle FindVehicleNear(Vector3 pos, float radius, string nameFilter = null, BasePlayer freeFor = null)
            {
                List<BaseVehicle> found = Pool.Get<List<BaseVehicle>>();
                Vis.Entities(pos, radius, found, LayerMask.GetMask("Vehicle Large", "Vehicle Detailed", "Vehicle World", "Default", "Deployed"), QueryTriggerInteraction.Ignore);
                BaseVehicle best = null;
                float bestDist = float.MaxValue;
                for (int i = 0; i < found.Count; i++)
                {
                    BaseVehicle v = found[i];
                    if (v == null || v.IsDestroyed) continue;
                    if (v is BaseVehicleModule) continue;
                    if (v.VehicleParent() != null) continue;
                    bool drivable = false;
                    foreach (BaseVehicle.MountPointInfo mp in v.allMountPoints)
                    {
                        if (mp != null && mp.isDriver && mp.mountable != null) { drivable = true; break; }
                    }
                    if (!drivable) continue;
                    if (freeFor != null && !HasFreeDriverSeat(v, freeFor)) continue;
                    if (!string.IsNullOrEmpty(nameFilter)
                        && v.ShortPrefabName.IndexOf(nameFilter, StringComparison.OrdinalIgnoreCase) < 0) continue;
                    float d = Vector3.Distance(pos, v.transform.position);
                    if (d < bestDist) { bestDist = d; best = v; }
                }
                Pool.FreeUnmanaged(ref found);
                return best;
            }

            #endregion

            #region Подготовка транспорта

            public static Vector3 FindWaterSpot(Vector3 near, float minDepth = 5f, float maxDepth = 25f)
            {
                float maxRadius = minDepth >= 8f ? 160f : 70f;
                for (float radius = 10f; radius <= maxRadius; radius += 6f)
                {
                    for (int i = 0; i < 16; i++)
                    {
                        Vector3 dir = Quaternion.AngleAxis(i * 22.5f, Vector3.up) * Vector3.forward;
                        Vector3 spot = near + dir * radius;
                        spot.y = TerrainMeta.HeightMap.GetHeight(spot);
                        float depth = WaterLevel.GetOverallWaterDepth(spot, waves: false, volumes: true);
                        if (depth < minDepth || depth > maxDepth) continue;
                        spot.y += depth;
                        return spot;
                    }
                }
                return Vector3.zero;
            }

            public static bool MoveBot(BaseCustomNpc bot, Vector3 point)
            {
                INavigator navigator = bot.GetComponent<INavigator>();
                if (navigator != null && navigator.Warp(point)) return true;

                bot.transform.position = point;
                bot.ServerPosition = point;
                return false;
            }

            public static Vector3 FindOpenSpot(Vector3 near)
            {
                Vector3 best = near + Vector3.forward * 3f;
                float bestScore = -1f;
                int mask = LayerMask.GetMask("Terrain", "World", "Construction", "Deployed", "Default", "Tree");
                for (int i = 0; i < 12; i++)
                {
                    Vector3 dir = Quaternion.AngleAxis(i * 30f, Vector3.up) * Vector3.forward;
                    Vector3 spot = near + dir * 4f;
                    spot.y = TerrainMeta.HeightMap.GetHeight(spot);
                    if (WaterLevel.GetOverallWaterDepth(spot, waves: false, volumes: true) > LandWaterLimitStatic) continue;

                    float score = 0f;
                    for (int k = 0; k < 4; k++)
                    {
                        Vector3 probe = Quaternion.AngleAxis(k * 90f, Vector3.up) * Vector3.forward;
                        score += Physics.Raycast(spot + Vector3.up, probe, out RaycastHit hit, 12f, mask,
                                                 QueryTriggerInteraction.Ignore) ? hit.distance : 12f;
                    }
                    if (score > bestScore) { bestScore = score; best = spot; }
                }
                return best;
            }

            public static bool FindLandingSpot(Vector3 near, float radius, float clearance, out Vector3 spot)
            {
                for (float r = 0f; r <= radius; r += 5f)
                {
                    int count = r < 1f ? 1 : Mathf.Max(6, Mathf.RoundToInt(2f * Mathf.PI * r / 5f));
                    for (int i = 0; i < count; i++)
                    {
                        Vector3 point = near + Quaternion.Euler(0f, i * 360f / count, 0f) * Vector3.forward * r;
                        if (IsLandable(point, clearance, out spot)) return true;
                    }
                }
                spot = near;
                return false;
            }

            private const float LandingMaxRise = 1.5f;
            private static readonly int LandingSurfaceMask = LayerMask.GetMask("Terrain", "World", "Construction", "Deployed");
            private static readonly int LandingObstacleMask = LayerMask.GetMask("World", "Construction", "Deployed", "Tree", "Default", "Transparent",
                "Vehicle Large", "Vehicle World", "Vehicle Detailed");

            private static bool IsLandable(Vector3 point, float clearance, out Vector3 spot)
            {
                spot = point;
                if (!Physics.Raycast(point + Vector3.up * 200f, Vector3.down, out RaycastHit hit, 400f, LandingSurfaceMask, QueryTriggerInteraction.Ignore)) return false;
                if (hit.collider is not TerrainCollider) return false;
                spot = hit.point;
                if (WaterLevel.GetOverallWaterDepth(spot, waves: false, volumes: true) > 0.1f) return false;
                for (int k = 0; k < 8; k++)
                {
                    Vector3 edge = spot + Quaternion.Euler(0f, k * 45f, 0f) * Vector3.forward * clearance;
                    if (Mathf.Abs(TerrainMeta.HeightMap.GetHeight(edge) - spot.y) > LandingMaxRise) return false;
                }
                if (Physics.CheckCapsule(spot + Vector3.up * (clearance + 0.5f), spot + Vector3.up * 30f, clearance, LandingObstacleMask, QueryTriggerInteraction.Ignore)) return false;
                return !CoreEx.InSafeZone(spot, clearance);
            }

            public static Vector3 DeepWaterNear(Vector3 target, float need, out float moved)
            {
                moved = 0f;
                if (WaterLevel.GetOverallWaterDepth(target, waves: false, volumes: true) >= need) return target;

                for (float radius = 20f; radius <= 200f; radius += 20f)
                {
                    for (int a = 0; a < 16; a++)
                    {
                        float rad = a * Mathf.PI * 2f / 16f;
                        Vector3 probe = target + new Vector3(Mathf.Cos(rad), 0f, Mathf.Sin(rad)) * radius;
                        if (WaterLevel.GetOverallWaterDepth(probe, waves: false, volumes: true) < need) continue;
                        moved = radius;
                        probe.y = WaterLevel.GetWaterOrTerrainSurface(probe, waves: false, volumes: true);
                        return probe;
                    }
                }
                return target;
            }

            public static string BuildEngine(BaseVehicle vehicle)
            {
                ModularCar car = vehicle as ModularCar;
                if (car == null) return null;

                int filled = 0, missing = 0, engines = 0;
                foreach (BaseVehicleModule module in car.AttachedModuleEntities)
                {
                    VehicleModuleEngine engine = module as VehicleModuleEngine;
                    if (engine == null) continue;
                    engines++;

                    Rust.Modular.EngineStorage storage = engine.GetContainer() as Rust.Modular.EngineStorage;
                    if (storage?.inventory == null || storage.slotTypes == null) continue;

                    for (int i = 0; i < storage.inventory.capacity && i < storage.slotTypes.Length; i++)
                    {
                        if (storage.inventory.GetSlot(i) != null) continue;
                        ItemDefinition def = FindEnginePart(storage.slotTypes[i]);
                        if (def == null) { missing++; continue; }

                        Item part = ItemManager.Create(def, 1, 0UL);
                        if (part == null) { missing++; continue; }
                        if (!part.MoveToContainer(storage.inventory, i, allowStack: false))
                        {
                            part.Remove();
                            missing++;
                            continue;
                        }
                        filled++;
                    }
                    storage.RefreshLoadoutData();
                }

                if (engines == 0) return "no engine module";
                return missing > 0
                    ? $"engine partially assembled ({filled} parts, missing {missing})"
                    : $"engine assembled ({filled} parts)";
            }

            private static ItemDefinition FindEnginePart(Rust.Modular.EngineStorage.EngineItemTypes type)
            {
                string name;
                switch (type)
                {
                    case Rust.Modular.EngineStorage.EngineItemTypes.Crankshaft: name = "crankshaft"; break;
                    case Rust.Modular.EngineStorage.EngineItemTypes.Carburetor: name = "carburetor"; break;
                    case Rust.Modular.EngineStorage.EngineItemTypes.SparkPlug:  name = "sparkplug";  break;
                    case Rust.Modular.EngineStorage.EngineItemTypes.Piston:     name = "piston";     break;
                    case Rust.Modular.EngineStorage.EngineItemTypes.Valve:      name = "valve";      break;
                    default: return null;
                }
                for (int tier = 3; tier >= 1; tier--)
                {
                    ItemDefinition def = ItemManager.FindItemDefinition(name + tier);
                    if (def != null) return def;
                }
                return null;
            }

            public static string ArmAttackHeli(BaseEntity entity)
            {
                AttackHelicopter heli = entity as AttackHelicopter;
                if (heli == null) return null;

                AttackHelicopterRockets rockets = heli.GetRockets();
                if (rockets?.inventory == null) return "weapon compartment unavailable";

                int rocketCount = AddAmmo(rockets.inventory, rockets.hvRocketDef, 8)
                                  + AddAmmo(rockets.inventory, rockets.incendiaryRocketDef, 4);

                int flareCount = rockets.flareItemDef != null ? AddAmmo(rockets.inventory, rockets.flareItemDef, 6) : 0;

                int turretAmmo = 0;
                string weaponName = "none";
                AttackHelicopterTurret turret = heli.GetTurret();
                if (turret?.inventory != null)
                {
                    if (turret.inventory.GetSlot(0) == null)
                    {
                        ItemDefinition gun = ItemManager.FindItemDefinition("lmg.m249")
                                             ?? ItemManager.FindItemDefinition("rifle.lr300");
                        if (gun != null)
                        {
                            Item weapon = ItemManager.Create(gun, 1, 0UL);
                            if (weapon != null && weapon.MoveToContainer(turret.inventory, 0, allowStack: false))
                                weaponName = gun.shortname;
                            else weapon?.Remove();
                        }
                    }
                    else weaponName = turret.inventory.GetSlot(0).info.shortname;

                    AttackHelicopterTurret armed = turret;
                    NPCsController.Instance.timer.Once(1f, () =>
                    {
                        if (armed == null || armed.IsDestroyed || armed.inventory == null) return;
                        int ammo = AddAmmo(armed.inventory, "ammo.rifle", 500);
                        Note($"turret loaded: ammo {ammo}");
                    });
                }

                return $"rockets {rocketCount}, flares {flareCount}, turret {weaponName}";
            }

            public static int AddAmmo(ItemContainer container, string shortname, int amount)
                => AddAmmo(container, ItemManager.FindItemDefinition(shortname), amount);

            public static int AddAmmo(ItemContainer container, ItemDefinition def, int amount)
            {
                if (amount <= 0 || def == null || container == null) return 0;

                Item item = ItemManager.Create(def, amount, 0UL);
                if (item == null) return 0;
                if (!item.MoveToContainer(container))
                {
                    item.Remove();
                    return 0;
                }
                return amount;
            }

            public static string FuelUp(BaseVehicle vehicle)
            {
                IFuelSystem fuel = vehicle.GetFuelSystem();
                if (fuel == null) return "no fuel tank";
                EntityFuelSystem entityFuel = fuel as EntityFuelSystem;
                StorageContainer container = entityFuel?.GetFuelContainer();
                if (container == null || container.inventory == null) return "fuel tank unavailable";
                ItemDefinition def = ItemManager.FindItemDefinition("lowgradefuel");
                if (def == null) return "fuel item not found in the game";
                Item item = ItemManager.Create(def, 500, 0uL);
                if (item == null) return "failed to create fuel";
                if (!item.MoveToContainer(container.inventory))
                {
                    item.Remove();
                    return "fuel did not fit in tank";
                }
                return fuel.HasFuel(true) ? "full" : "fueled, but the game does not detect it";
            }

