            #region Патрульные цели

            public class PatrolTarget
            {
                public string Name;
                public Vector3 Pos;
            }

            public static List<PatrolTarget> CollectPatrolTargets(bool water)
            {
                List<PatrolTarget> result = new List<PatrolTarget>();
                var monuments = TerrainMeta.Path != null ? TerrainMeta.Path.Monuments : null;
                if (monuments == null) return result;

                for (int i = 0; i < monuments.Count; i++)
                {
                    MonumentInfo m = monuments[i];
                    if (m == null) continue;
                    Vector3 center = m.transform.position + m.Bounds.center;
                    center.y = TerrainMeta.HeightMap.GetHeight(center);

                    if (water)
                    {
                        if (!HasDeepWaterAround(center, 80f)) continue;
                        Vector3 spot = FindApproachOnWater(center);
                        if (spot == Vector3.zero) continue;
                        result.Add(new PatrolTarget { Name = m.displayPhrase.english, Pos = spot });
                    }
                    else
                    {
                        if (WaterLevel.GetOverallWaterDepth(center, waves: false, volumes: true) > 0.5f) continue;
                        result.Add(new PatrolTarget { Name = m.displayPhrase.english, Pos = center });
                    }
                }
                return result;
            }

            private static bool HasDeepWaterAround(Vector3 center, float radius)
            {
                for (int i = 0; i < 8; i++)
                {
                    Vector3 dir = Quaternion.AngleAxis(i * 45f, Vector3.up) * Vector3.forward;
                    Vector3 p = center + dir * radius;
                    p.y = TerrainMeta.HeightMap.GetHeight(p);
                    if (WaterLevel.GetOverallWaterDepth(p, waves: false, volumes: true) >= 4f) return true;
                }
                return false;
            }

            private static Vector3 FindApproachOnWater(Vector3 center)
            {
                for (float radius = 20f; radius <= 80f; radius += 15f)
                {
                    for (int i = 0; i < 12; i++)
                    {
                        Vector3 dir = Quaternion.AngleAxis(i * 30f, Vector3.up) * Vector3.forward;
                        Vector3 p = center + dir * radius;
                        p.y = TerrainMeta.HeightMap.GetHeight(p);
                        if (WaterLevel.GetOverallWaterDepth(p, waves: false, volumes: true) >= 3f) return p;
                    }
                }
                return Vector3.zero;
            }

            private static readonly int OpenWaterObstacleMask = LayerMask.GetMask("World", "Construction", "Deployed", "Default", "Transparent",
                "Vehicle Large", "Vehicle World");

            public static bool TryOpenWaterNear(Vector3 point, float clearance, float radius, out Vector3 spot, float minDepth = 3f)
            {
                for (float r = 0f; r <= radius; r += OpenWaterStep)
                {
                    int count = r < 1f ? 1 : Mathf.Max(8, Mathf.RoundToInt(2f * Mathf.PI * r / OpenWaterStep));
                    for (int i = 0; i < count; i++)
                    {
                        Vector3 p = point + Quaternion.Euler(0f, i * 360f / count, 0f) * Vector3.forward * r;
                        if (WaterLevel.GetOverallWaterDepth(p, waves: false, volumes: true) < minDepth || !IsOpenWater(p, clearance)) continue;
                        p.y = TerrainMeta.HeightMap.GetHeight(p);
                        spot = p;
                        return true;
                    }
                }
                spot = point;
                return false;
            }

            private const float OpenWaterStep = 5f;

            public static bool IsOpenWater(Vector3 point, float clearance)
            {
                float surface = WaterSystem.OceanLevel;
                return !Physics.CheckCapsule(new Vector3(point.x, surface - 1f, point.z), new Vector3(point.x, surface + 6f, point.z), clearance,
                    OpenWaterObstacleMask, QueryTriggerInteraction.Ignore);
            }

