            #region Граф рельсов

            private class RailLinks
            {
                public readonly List<TrainTrackSpline> Next = new List<TrainTrackSpline>();
                public readonly List<TrainTrackSpline> Prev = new List<TrainTrackSpline>();
                public float Length;
            }

            private static readonly Dictionary<TrainTrackSpline, RailLinks> _railGraph
                = new Dictionary<TrainTrackSpline, RailLinks>();

            private static readonly List<TrainTrackSpline> _railSplines = new List<TrainTrackSpline>();

            private static readonly List<Bounds> _railBounds = new List<Bounds>();

            private const float RailBoundsPad = 6f;

            private static void BuildRailGraph()
            {
                _railGraph.Clear();
                _railSplines.Clear();
                _railBounds.Clear();

                int links = 0, forks = 0;
                foreach (TrainTrackSpline spline in UnityEngine.Object.FindObjectsByType<TrainTrackSpline>(FindObjectsSortMode.InstanceID))
                {
                    if (spline == null || spline.points == null || spline.points.Length < 2) continue;
                    RailLinks item = new RailLinks();
                    WorldSplineData data = spline.GetData();
                    item.Length = data != null ? data.Length : 0f;
                    CollectTracks(spline.nextTracks, item.Next);
                    CollectTracks(spline.prevTracks, item.Prev);
                    links += item.Next.Count + item.Prev.Count;
                    if (item.Next.Count > 1 || item.Prev.Count > 1) forks++;
                    _railGraph[spline] = item;
                    _railSplines.Add(spline);

                    Vector3[] world = spline.GetPointsWorld();
                    Bounds box = new Bounds(world[0], Vector3.zero);
                    for (int i = 1; i < world.Length; i++) box.Encapsulate(world[i]);
                    box.Expand(RailBoundsPad * 2f);
                    _railBounds.Add(box);
                }
            }

            private static void CollectTracks(List<TrainTrackSpline.ConnectedTrackInfo> list, List<TrainTrackSpline> into)
            {
                foreach (TrainTrackSpline.ConnectedTrackInfo item in list)
                    if (item?.track != null) into.Add(item.track);
            }

            public static TrainTrackSpline NearestSpline(Vector3 pos)
            {
                EnsureRails();
                TrainTrackSpline best = null;
                float bestDist = float.MaxValue;

                int seed = -1;
                float seedBound = float.MaxValue;
                for (int i = 0; i < _railSplines.Count; i++)
                {
                    if (_railSplines[i] == null) continue;
                    float bound = _railBounds[i].SqrDistance(pos);
                    if (bound < seedBound) { seedBound = bound; seed = i; }
                }
                if (seed >= 0)
                {
                    best = _railSplines[seed];
                    bestDist = best.GetDistance(pos, 1f, out _);
                }

                for (int i = 0; i < _railSplines.Count; i++)
                {
                    TrainTrackSpline spline = _railSplines[i];
                    if (i == seed || spline == null) continue;
                    if (Mathf.Sqrt(_railBounds[i].SqrDistance(pos)) >= bestDist) continue;
                    float dist = spline.GetDistance(pos, 1f, out _);
                    if (dist < bestDist) { bestDist = dist; best = spline; }
                }
                return best;
            }

            private static List<TrainTrackSpline> RailRoute(TrainTrackSpline from, TrainTrackSpline to)
            {
                List<TrainTrackSpline> result = RailRouteCore(from, to, out int visited);
                return result;
            }

            private static List<TrainTrackSpline> RailRouteCore(TrainTrackSpline from, TrainTrackSpline to, out int visited)
            {
                visited = 0;
                if (from == null || to == null) return null;
                if (from == to) return new List<TrainTrackSpline> { from };

                Dictionary<TrainTrackSpline, TrainTrackSpline> cameFrom
                    = new Dictionary<TrainTrackSpline, TrainTrackSpline> { [from] = null };
                Queue<TrainTrackSpline> queue = new Queue<TrainTrackSpline>();
                queue.Enqueue(from);

                while (queue.Count > 0)
                {
                    TrainTrackSpline cur = queue.Dequeue();
                    visited++;
                    if (cur == to) break;
                    if (!_railGraph.TryGetValue(cur, out RailLinks links)) continue;

                    for (int side = 0; side < 2; side++)
                    {
                        List<TrainTrackSpline> neighbours = side == 0 ? links.Next : links.Prev;
                        for (int i = 0; i < neighbours.Count; i++)
                        {
                            TrainTrackSpline next = neighbours[i];
                            if (next == null || cameFrom.ContainsKey(next)) continue;
                            cameFrom[next] = cur;
                            queue.Enqueue(next);
                        }
                    }
                }

                if (!cameFrom.ContainsKey(to)) return null;
                List<TrainTrackSpline> route = new List<TrainTrackSpline>();
                for (TrainTrackSpline s = to; s != null; s = cameFrom[s]) route.Add(s);
                route.Reverse();
                return route;
            }

            #endregion

            #region Состояние «еду»

            public class DriveState : FSM.RouterState
            {
                public enum Phase { Walk, Board, Drive, Leave }

                protected virtual float SearchRadius => 60f;

                protected virtual float BoardDistance => 4f;

                protected virtual float EntryReach => 0.6f;

                protected virtual float BoatReach => 40f;

                protected virtual float DriveTimeout => 600f;

                protected virtual float WalkPace => 2f;
                protected virtual float TripStartAllowance => 60f;

                protected virtual float TripPaceShare => 0.8f;

                public float TimeLimit(Vector3 from, Vector3 to) => Mathf.Min(DriveTimeout, TripStartAllowance + Vector3.Distance(from, to) / WalkPace);

                public bool FitsTimeLimit(Vector3 from, Vector3 to, float routeLength, float cruise)
                    => TripStartAllowance + routeLength / Mathf.Max(0.5f, cruise * TripPaceShare) <= TimeLimit(from, to);

                protected virtual float GiveUpDistance => 120f;

                protected virtual float NoProgressGiveUp => 40f;

                private const float ProgressStep = 5f;

                private const float LeaveWait = 5f;

                private const float StoppedSpeed = 0.1f;

                public override bool YieldsToTurretEscape => false;

                private Vector3 _trip;
                private bool _hasTrip;
                private BaseVehicle _vehicle;
                private Vector3 _approach;
                private VehicleControllerBase _pilot;
                private bool _landingOnTimeout;
                private Phase _phase;
                private float _phaseSince;
                private float _bestLeft = float.MaxValue;
                private float _bestAt;
                private int _bestRoute;
                private float _timeLimit;
                private Vector3 _destination;
                private float _haltedAt = -1f;

                public override string Name => "Drive";

                public Phase CurrentPhase => _phase;

                public VehicleControllerBase Pilot => _pilot;

                public bool HasTrip => _hasTrip;

                public Vector3 Trip => _trip;

                public bool StopForLeave()
                {
                    if (_phase != Phase.Drive || _pilot == null || _pilot is AirVehicleController) return true;
                    if (_haltedAt < 0f)
                    {
                        _haltedAt = UnityEngine.Time.time;
                        _pilot.Halt();
                        Note(string.Format("{0}: stopping the vehicle to leave it", Debug.Id(Owner)));
                    }
                    return ReadyToLeave();
                }

                public bool HaltedToLeave => _phase == Phase.Drive && _haltedAt >= 0f && _pilot != null && !_pilot.Arrived;

                public void ResumeDrive()
                {
                    if (!HaltedToLeave) return;
                    _haltedAt = -1f;
                    _pilot.DriveTo(_destination);
                    Note(string.Format("{0}: no need to leave - driving on", Debug.Id(Owner)));
                }

                public void CancelTrip()
                {
                    _hasTrip = false;
                    if (_pilot != null || _vehicle != null) Cleanup();
                }

                protected override BaseEntity GetChaseEnemy => null;
                protected override float MinDistanceMovedEnemyForAddPoint => 0f;

                protected override void Start() { }

                protected override void OnDestroy()
                {
                    base.OnDestroy();
                    Cleanup();
                }

                public void SetTrip(Vector3 target)
                {
                    _trip = target;
                    _hasTrip = true;
                    _pickedUntil = 0f;
                }

                protected override bool CanEnterState()
                {
                    if (!_hasTrip || !Owner.IsValid()) return false;
                    return PickVehicle() != null;
                }

                protected virtual BaseVehicle FindVehicle()
                    => FindVehicleNear(Owner.transform.position, SearchRadius, null, Owner);

                protected virtual void OnPilotBoarded(VehicleControllerBase pilot) { }

                private const float PickHold = 1.5f;
                private BaseVehicle _picked;
                private bool _pickedNone;
                private float _pickedUntil;

                private BaseVehicle PickVehicle()
                {
                    if (UnityEngine.Time.time < _pickedUntil
                        && (_pickedNone || _picked != null && !_picked.IsDestroyed && HasFreeDriverSeat(_picked, Owner))) return _picked;
                    _picked = ReachableVehicle();
                    _pickedNone = _picked == null;
                    _pickedUntil = UnityEngine.Time.time + PickHold;
                    return _picked;
                }

                private BaseVehicle ReachableVehicle()
                {
                    BaseVehicle vehicle = FindVehicle();
                    if (vehicle == null) return null;
                    _entryFrom = vehicle.transform.position;
                    if (Navigator == null)
                    {
                        _approach = Owner.transform.position;
                        return vehicle;
                    }

                    if (vehicle is BaseBoat) return FindShore(vehicle, out _approach) ? vehicle : null;
                    if (FindEntry(vehicle, out _approach)) return vehicle;

                    if (Vector3.Distance(Owner.transform.position, vehicle.transform.position) <= BoardDistance * 2.5f)
                    {
                        _approach = Owner.transform.position;
                        return vehicle;
                    }
                    _approach = ApproachPoint(vehicle);
                    return Navigator.HasCompletePathTo(_approach) ? vehicle : null;
                }

                private Vector3 _entryFrom;
                private float _nextEntryCheck;
                private float _finalStepSince = -1f;
                private const float FinalStepTime = 3f;

                private bool FindEntry(BaseVehicle vehicle, out Vector3 entry)
                {
                    entry = Vector3.zero;
                    BaseMountable seat = null;
                    foreach (BaseVehicle.MountPointInfo mp in vehicle.allMountPoints)
                        if (mp != null && mp.isDriver && mp.mountable != null) { seat = mp.mountable; break; }
                    Transform[] points = seat != null && seat.dismountPositions != null && seat.dismountPositions.Length > 0
                        ? seat.dismountPositions : vehicle.dismountPositions;
                    if (points == null || points.Length == 0) return false;

                    Vector3 bot = Owner.transform.position;
                    List<Vector3> candidates = Pool.Get<List<Vector3>>();
                    try
                    {
                        foreach (Transform point in points)
                        {
                            if (point == null) continue;
                            if (!Navigator.GetNearestNavmeshPosition(point.position, out Vector3 snapped, EntrySnap)) continue;
                            if (Mathf.Abs(snapped.y - point.position.y) > EntrySnap * 2f) continue;
                            Vector3 near = seat != null ? NearBody(vehicle, seat.transform.position, snapped) : snapped;
                            if (near != snapped && Navigator.GetNearestNavmeshPosition(near, out Vector3 close, EntryGap * 2f) && !InsideBody(vehicle, close))
                                snapped = close;
                            candidates.Add(snapped);
                        }
                        candidates.Sort((a, b) => FlatDistance(a, bot).CompareTo(FlatDistance(b, bot)));
                        foreach (Vector3 candidate in candidates)
                        {
                            if (FlatDistance(candidate, bot) > EntryReach && !Navigator.HasCompletePathTo(candidate)) continue;
                            entry = candidate;
                            return true;
                        }
                        return false;
                    }
                    finally
                    {
                        Pool.FreeUnmanaged(ref candidates);
                    }
                }

                private const float EntrySnap = 1.5f;

                private const float EntryGap = 0.25f;

                private static Vector3 NearBody(BaseVehicle vehicle, Vector3 seat, Vector3 point)
                {
                    Transform transform = vehicle.transform;
                    Vector3 from = transform.InverseTransformPoint(point), to = transform.InverseTransformPoint(seat);
                    to.y = from.y;
                    float length = Vector3.Distance(from, to);
                    if (length < 0.1f) return point;
                    Vector3 direction = (to - from) / length;
                    Vector3 best = from;
                    for (float d = 0.1f; d <= length; d += 0.1f)
                    {
                        Vector3 probe = from + direction * d;
                        if (InsideBox(vehicle.bounds, probe, EntryGap)) break;
                        best = probe;
                    }
                    return best == from ? point : transform.TransformPoint(best);
                }

                private static bool InsideBody(BaseVehicle vehicle, Vector3 world)
                    => InsideBox(vehicle.bounds, vehicle.transform.InverseTransformPoint(world), EntryGap * 0.5f);

                private static bool InsideBox(Bounds box, Vector3 local, float gap)
                    => local.x > box.min.x - gap && local.x < box.max.x + gap && local.z > box.min.z - gap && local.z < box.max.z + gap;

                private Vector3 ApproachPoint(BaseVehicle vehicle)
                {
                    Vector3 center = vehicle.transform.position;
                    return Navigator != null && Navigator.GetNearestNavmeshPosition(center, out Vector3 point, BoardDistance) ? point : center;
                }

                private const float ShoreStep = 4f;

                private bool FindShore(BaseVehicle boat, out Vector3 shore)
                {
                    shore = boat.transform.position;
                    if (Navigator == null) return false;
                    Vector3 toBot = Owner.transform.position - shore;
                    toBot.y = 0f;
                    float length = toBot.magnitude;
                    if (length < 0.1f) return false;
                    toBot /= length;
                    for (float d = 0f; d <= Mathf.Min(length, BoatReach); d += ShoreStep)
                    {
                        if (!Navigator.GetNearestNavmeshPosition(boat.transform.position + toBot * d, out Vector3 point, ShoreStep)) continue;
                        if (!Navigator.HasCompletePathTo(point)) continue;
                        shore = point;
                        return true;
                    }
                    return false;
                }

                public string TripBlockReason()
                {
                    if (!_hasTrip) return "no trip assigned";
                    if (!Owner.IsValid()) return "bot is missing";

                    BaseVehicle vehicle = FindVehicle();
                    if (vehicle == null) return $"no suitable vehicle within {SearchRadius:0} m";
                    if (PickVehicle() == null) return $"no navmesh path to {vehicle.ShortPrefabName}";
                    return null;
                }

                protected override void EnterState()
                {
                    base.EnterState();
                    _vehicle = PickVehicle();
                    if (_vehicle == null) { _hasTrip = false; return; }

                    float toVehicle = Vector3.Distance(Owner.transform.position, _vehicle.transform.position);

                    if (FlatDistance(Owner.transform.position, _approach) <= EntryReach)
                    {
                        Note(string.Format("{0}: trip assigned - {1} nearby ({2:0} m), mounting",
                            Debug.Id(Owner), _vehicle.ShortPrefabName, toVehicle));
                        SetPhase(Phase.Board);
                        return;
                    }

                    SetPhase(Phase.Walk);
                    Note(string.Format("{0}: trip assigned - walking toward {1}, distance {2:0} m",
                        Debug.Id(Owner), _vehicle.ShortPrefabName, toVehicle));
                    base.SetTarget(_approach);
                }

                protected override void LeaveState()
                {
                    base.LeaveState();
                    Cleanup();
                }

                protected override ResponseFromUpdateState UpdateState(float delta)
                {
                    if (!Owner.IsValid()) return ResponseFromUpdateState.Failure;

                    switch (_phase)
                    {
                        case Phase.Walk:   return TickWalk(delta);
                        case Phase.Board:  return TickBoard();
                        case Phase.Drive:  return TickDrive();
                        default:           return ResponseFromUpdateState.Completed;
                    }
                }

                private ResponseFromUpdateState TickWalk(float delta)
                {
                    ResponseFromUpdateState response = base.UpdateState(delta);
                    if (_vehicle == null || _vehicle.IsDestroyed)
                    {
                        Note(string.Format("{0}: vehicle disappeared on the way", Debug.Id(Owner)));
                        return ResponseFromUpdateState.Failure;
                    }

                    float now = UnityEngine.Time.time;
                    if (FlatDistance(Owner.transform.position, _approach) <= EntryReach)
                    {
                        Stop();
                        SetPhase(Phase.Board);
                        return ResponseFromUpdateState.NONE;
                    }
                    if (modeRouter == FSM.IRouterState.ModeRouter.Finish)
                    {
                        if (_finalStepSince < 0f)
                        {
                            _finalStepSince = now;
                            Navigator?.SetDestination(_approach, Owner.speedNavigatorNormal, 0.5f);
                        }
                        else if (now - _finalStepSince > FinalStepTime)
                        {
                            Stop();
                            SetPhase(Phase.Board);
                        }
                        return ResponseFromUpdateState.NONE;
                    }
                    if (now >= _nextEntryCheck && !(_vehicle is BaseBoat))
                    {
                        _nextEntryCheck = now + 1f;
                        if (FlatDistance(_vehicle.transform.position, _entryFrom) > EntryReach && FindEntry(_vehicle, out Vector3 entry))
                        {
                            _entryFrom = _vehicle.transform.position;
                            _approach = entry;
                            base.SetTarget(_approach);
                        }
                    }

                    if (IsStuck)
                    {
                        if (Vector3.Distance(Owner.transform.position, _vehicle.transform.position) <= BoardDistance * 2.5f)
                        {
                            Stop();
                            SetPhase(Phase.Board);
                            return ResponseFromUpdateState.NONE;
                        }
                        Note(string.Format("{0}: cannot reach vehicle ({1})",
                            Debug.Id(Owner), IsStuck ? StuckReasonLatched : "no route"));
                        return ResponseFromUpdateState.Failure;
                    }
                    if (Stalled(FlatDistance(Owner.transform.position, _approach)))
                    {
                        Note(string.Format("{0}: cannot reach vehicle (no progress for {1:0} s)", Debug.Id(Owner), NoProgressGiveUp));
                        return ResponseFromUpdateState.Failure;
                    }
                    return response;
                }

                private ResponseFromUpdateState TickBoard()
                {
                    BaseCustomNpc bot = Owner;
                    string error = Board(bot, _vehicle, out _pilot);
                    if (error != null)
                    {
                        Note(string.Format("{0}: failed to mount - {1}", Debug.Id(bot), error));
                        return ResponseFromUpdateState.Failure;
                    }

                    Navigator?.Pause();
                    OnPilotBoarded(_pilot);
                    if (_pilot is AirVehicleController air) LandNear(air, _trip);
                    else
                    {
                        Vector3 destination = _trip;
                        if (_pilot is BoatVehicleController) TryOpenWaterNear(_trip, BoatDestinationClearance, BoatDestinationSearch, out destination);
                        if (destination != _trip)
                            Note(string.Format("{0}: boat heads for open water at {1}, {2:0} m from the target point", Debug.Id(Owner), destination,
                                Vector3.Distance(destination, _trip)));
                        _destination = destination;
                        _pilot.DriveTo(destination);
                    }
                    _timeLimit = TimeLimit(Owner.transform.position, _trip);
                    SetPhase(Phase.Drive);
                    return ResponseFromUpdateState.NONE;
                }

                protected virtual float BoatDestinationClearance => 15f;
                protected virtual float BoatDestinationSearch => 80f;

                protected virtual float LandingSearchRadius => 80f;

                private void LandNear(AirVehicleController air, Vector3 point)
                {
                    float clearance = Mathf.Max(5f, Mathf.Max(_vehicle.bounds.extents.x, _vehicle.bounds.extents.z) + 1f);
                    if (!FindLandingSpot(point, LandingSearchRadius, clearance, out Vector3 spot))
                        Note(string.Format("{0}: no landing spot within {1:0} m of {2} - landing at the point itself", Debug.Id(Owner), LandingSearchRadius, point));
                    air.LandAt(spot);
                }

                private ResponseFromUpdateState TickAir(AirVehicleController air)
                {
                    if (air.Landed) return EndTrip("landed");
                    if (UnityEngine.Time.time - _phaseSince <= _timeLimit) return ResponseFromUpdateState.NONE;
                    if (!_landingOnTimeout)
                    {
                        _landingOnTimeout = true;
                        _phaseSince = UnityEngine.Time.time;
                        Note(string.Format("{0}: trip exceeded {1:0} s - landing where we are", Debug.Id(Owner), _timeLimit));
                        LandNear(air, Owner.transform.position);
                        return ResponseFromUpdateState.NONE;
                    }
                    return EndTrip($"could not land in {_timeLimit:0} s");
                }

                private bool Stopped()
                {
                    if (_vehicle == null || _vehicle.IsDestroyed) return true;
                    Vector3 velocity = _vehicle.GetWorldVelocity();
                    velocity.y = 0f;
                    return velocity.magnitude < StoppedSpeed;
                }

                private bool ReadyToLeave() => Stopped() || UnityEngine.Time.time - _haltedAt >= LeaveWait;

                private ResponseFromUpdateState TickDrive()
                {
                    if (_pilot == null || _pilot.Bot == null) return EndTrip("pilot dismounted");
                    if (_pilot is AirVehicleController air) return TickAir(air);
                    if (_pilot.Arrived)
                    {
                        if (_haltedAt < 0f) _haltedAt = UnityEngine.Time.time;
                        if (!ReadyToLeave()) return ResponseFromUpdateState.NONE;
                        return EndTrip("arrived");
                    }

                    if (_pilot.RouteVersion != _bestRoute)
                    {
                        _bestRoute = _pilot.RouteVersion;
                        if (_bestLeft < float.MaxValue) _bestLeft = RemainingPath();
                    }
                    if (Stalled(RemainingPath())) return EndTrip($"no progress along the route for {NoProgressGiveUp:0} s");
                    if (UnityEngine.Time.time - _phaseSince > _timeLimit) return EndTrip($"trip exceeded {_timeLimit:0} s");
                    return ResponseFromUpdateState.NONE;
                }

                private bool Stalled(float left)
                {
                    float now = UnityEngine.Time.time;
                    if (left < _bestLeft - ProgressStep)
                    {
                        _bestLeft = left;
                        _bestAt = now;
                    }
                    return now - _bestAt > NoProgressGiveUp;
                }

                private float RemainingPath()
                {
                    Vector3 pos = Owner.transform.position;
                    IReadOnlyList<Vector3> route = _pilot.Route;
                    if (route.Count == 0) return FlatDistance(pos, _trip);
                    int next = _pilot.NextIndex;
                    float left = FlatDistance(pos, route[next]);
                    for (int i = next; i + 1 < route.Count; i++) left += FlatDistance(route[i], route[i + 1]);
                    return left + FlatDistance(route[route.Count - 1], _trip);
                }

                private static float FlatDistance(Vector3 a, Vector3 b) => Vector2.Distance(new Vector2(a.x, a.z), new Vector2(b.x, b.z));

                private ResponseFromUpdateState EndTrip(string why)
                {
                    float left = Vector3.Distance(Owner.transform.position, _trip);
                    bool nearTarget = left < GiveUpDistance;
                    Note(string.Format("{0}: {1}, {2:0} m from target - dismounting{3}", Debug.Id(Owner), why, left,
                        nearTarget && left > 15f ? ", continuing on foot" : ""));
                    Cleanup();
                    return nearTarget ? ResponseFromUpdateState.Completed : ResponseFromUpdateState.Failure;
                }

                private void SetPhase(Phase phase)
                {
                    _phase = phase;
                    _phaseSince = UnityEngine.Time.time;
                    _bestLeft = float.MaxValue;
                    _finalStepSince = -1f;
                    _haltedAt = -1f;
                }

                private void Cleanup()
                {
                    if (_pilot != null)
                    {
                        _pilot.Release("trip finished");
                        _pilot = null;
                    }
                    Navigator?.Resume();
                    _vehicle = null;
                    _picked = null;
                    _pickedUntil = 0f;
                    _hasTrip = false;
                    _landingOnTimeout = false;
                    SetPhase(Phase.Leave);
                }
            }

            public abstract class SeatedFireState : FSM.AttackState
            {
                public override string Name => "Ride";
                protected override bool canAimDirection => true;
                protected override bool CanAimingWeaponFire => true;
                protected override float GetDamageScaleToEnemy() => 1f;

                private float _nextSearch;
                private BasePlayer _target;

                protected abstract bool CanFireSeated { get; }
                protected virtual bool AimsForwardWhenIdle => true;
                protected abstract BasePlayer FindSeatedTarget();
                protected abstract bool CanAttackSeated(BasePlayer target);
                protected abstract int SeatedWeaponSlot();
                protected virtual float SeatedGunRange => 60f;
                protected virtual void OnSeatedEngage(BasePlayer target) { }

                protected override void Start()
                {
                    _nextSearch = 0f;
                    _target = null;
                }
                protected override void OnDestroy()
                {
                    _target = null;
                    base.OnDestroy();
                }
                protected override void EnterState()
                {
                    base.EnterState();
                    _nextSearch = 0f;
                    _target = null;
                    Navigator?.Stop();
                    Navigator?.Pause();
                }
                protected override void LeaveState()
                {
                    base.LeaveState();
                    StopAttack();
                    _target = null;
                    CurrentEnemy = default;
                    if (Owner.IsValid() && !Owner.isMounted && Navigator != null && Navigator.IsPaused) Navigator.Resume();
                }
                protected override bool CanEnterState() => Owner.IsValid() && Owner.IsAlive() && Owner.isMounted;
                protected override ResponseFromUpdateState UpdateState(float delta)
                {
                    if (!Owner.IsValid() || !Owner.isMounted) return ResponseFromUpdateState.Completed;
                    if (Navigator != null && !Navigator.IsPaused) Navigator.Pause();
                    if (!CanFireSeated)
                    {
                        if (IsDown) StopAttack();
                        if (AimsForwardWhenIdle) AimForward();
                        return ResponseFromUpdateState.NONE;
                    }
                    if (UnityEngine.Time.time >= _nextSearch)
                    {
                        _nextSearch = UnityEngine.Time.time + 0.5f;
                        _target = FindSeatedTarget();
                        if (_target != null) OnSeatedEngage(_target);
                    }
                    if (_target == null || !_target.IsAlive() || !CanAttackSeated(_target))
                    {
                        _target = null;
                        if (IsDown) StopAttack();
                        AimForward();
                        return ResponseFromUpdateState.NONE;
                    }
                    if (Owner.GetMounted() is PTBoatTurret turret)
                    {
                        FireMountedGun(turret, _target);
                        return ResponseFromUpdateState.NONE;
                    }
                    if (!CurrentEnemy.IsValid() || CurrentEnemy.Enemy != _target)
                        CurrentEnemy = new EnemyInfo(_target, false, true, -1, FSM.IAttackState.PersonalityBot.Aggressive);
                    if (!CurrentWeapon)
                    {
                        int slot = SeatedWeaponSlot();
                        if (slot < 0) return ResponseFromUpdateState.NONE;
                        CurrentWeapon = Owner.EquipWeapon(slot, false);
                        if (!CurrentWeapon) return ResponseFromUpdateState.NONE;
                    }
                    Owner.SetAimDirection((AimPosition(_target) - Owner.eyes.position).normalized);
                    Owner.modelState.onground = true;
                    if (!IsDown && !IsCooldown) DownTrigger();
                    return ResponseFromUpdateState.NONE;
                }
                private float _burstAt = float.NegativeInfinity, _shotAt = float.NegativeInfinity;

                private void FireMountedGun(PTBoatTurret gun, BasePlayer target)
                {
                    if (gun.muzzle == null || Owner.InSafeZone()) return;
                    Vector3 muzzle = gun.muzzle.position;
                    Vector3 aim = AimPosition(target);
                    Vector3 toTarget = aim - muzzle;
                    float range = gun.aiMaxAttackDistance;
                    if (toTarget.sqrMagnitude < 0.01f || toTarget.sqrMagnitude > range * range) return;
                    Vector3 direction = toTarget.normalized;
                    gun.aimDir = Vector3.RotateTowards(gun.aimDir, AimConeUtil.GetModifiedAimConeDirection(gun.aiAccuracy, direction), MathF.PI * 7f / 240f, 0f);
                    float now = UnityEngine.Time.time;
                    if (now - _burstAt > PTBoatTurret.ai_burst_length + PTBoatTurret.ai_time_between_bursts && ClearShot(muzzle, aim, gun)) _burstAt = now;
                    if (now < _burstAt + PTBoatTurret.ai_burst_length && now - _shotAt >= PTBoatTurret.ai_fire_rate
                        && Vector3.Dot(gun.muzzle.forward, direction) >= 0.9f)
                    {
                        _shotAt = now;
                        gun.FireGuns();
                    }
                    foreach (BaseEntity child in gun.children)
                        if (child is BaseProjectile projectile && projectile.primaryMagazine.contents <= 0) projectile.ServerReload();
                }

                private static bool ClearShot(Vector3 from, Vector3 to, BaseEntity gun)
                {
                    Vector3 delta = to - from;
                    float distance = delta.magnitude;
                    if (distance < 0.1f) return true;
                    List<RaycastHit> hits = Pool.Get<List<RaycastHit>>();
                    GamePhysics.TraceAll(new Ray(from, delta / distance), 0f, hits, distance, 1218519297, QueryTriggerInteraction.Ignore);
                    bool clear = true;
                    foreach (RaycastHit hit in hits)
                    {
                        BaseEntity entity = hit.GetEntity();
                        if (entity != null && (entity == gun || gun.HasEntityInParents(entity))) continue;
                        clear = false;
                        break;
                    }
                    Pool.FreeUnmanaged(ref hits);
                    return clear;
                }

                private void AimForward()
                {
                    BaseMountable mounted = Owner.GetMounted();
                    if (mounted != null) Owner.SetAimDirection(mounted.transform.forward);
                }
                private static Vector3 AimPosition(BasePlayer target)
                {
                    if (target.IsSleeping() || target.IsWounded()) return target.transform.position + Vector3.up * 0.1f;
                    return target.eyes != null ? target.eyes.position - Vector3.up * 0.15f : target.CenterPoint();
                }
            }

            public class Parachutist : MonoBehaviour
            {
                private const float AirborneHeight = 3f;
                private const float AirborneNavSnap = 10f;
                private const float ChuteLandStep = 0.1f, ChuteLandHeight = 1.3f;
                private const float ParachuteGap = 8f;
                private const float WalkDownDepth = 1f;
                private const float ElevatedSupport = 2f;
                private static readonly float[] GroundRings = { 3f, 6f, 9f, 12f, 20f, 30f, 40f };
                private const float SteerTurnAngle = 10f, SteerForwardAngle = 45f;
                private static int _jumpClearMask, _chuteLandMask;
                private static readonly List<Parachute> _parachuteBuffer = new List<Parachute>();
                private static readonly List<Vector3> _walkDownCorners = new List<Vector3>();
                private static readonly List<Parachute> _botParachutes = new List<Parachute>();

                private BaseCustomNpc _bot;
                private Parachute _parachute;
                private ulong _skin;
                private int _jumps;
                private float _jumpedAt;
                private bool _landing;
                private bool _settle;
                private Func<bool> _useNavMesh;
                private bool _steer;
                private Vector3 _steerTo;
                private InputState _input;
                private float _sinkSpeed;

                public static Parachutist Of(BaseCustomNpc bot) => bot != null ? bot.GetComponent<Parachutist>() : null;

                public ulong Skin => _skin;

                public bool IsParachuting => _bot != null && _parachute != null && !_parachute.IsDestroyed && _bot.isMounted && _bot.GetMounted() != null
                                             && _bot.GetMounted().VehicleParent() == _parachute;

                public bool IsAirborne => _bot != null && _bot.IsValid() && !_bot.IsDestroyed && Hangs(_bot.transform.position, out _, out _);

                public static Parachutist Jump(BaseCustomNpc bot, ulong skin, BaseVehicle from = null, List<Vector3> land = null, bool leftSide = false,
                    Func<bool> useNavMesh = null)
                {
                    if (bot == null || !bot.IsValid() || bot.IsDestroyed || !bot.IsAlive()) return null;
                    Parachutist chute = bot.GetComponent<Parachutist>() ?? bot.gameObject.AddComponent<Parachutist>();
                    chute._bot = bot;
                    if (!chute.IsParachuting) chute.DoJump(skin, from, land, leftSide, useNavMesh);
                    return chute;
                }

                private void DoJump(ulong skin, BaseVehicle from, List<Vector3> land, bool leftSide, Func<bool> useNavMesh)
                {
                    _skin = skin;
                    _jumps++;
                    _landing = true;
                    _useNavMesh = useNavMesh;
                    BaseVehicle vehicle = _bot.isMounted ? _bot.GetMountedVehicle() : null;
                    if (vehicle == null && from != null && !from.IsDestroyed) vehicle = from;
                    ReleaseRoles(_bot, null, "parachute jump");
                    if (_bot.isMounted) _bot.DismountSafely();
                    Vector3 position = JumpPoint(vehicle, land, leftSide);
                    _bot.transform.position = position;
                    _bot.ServerPosition = position;
                    Quaternion rotation = _bot.eyes != null ? _bot.eyes.rotation : _bot.transform.rotation;
                    Vector3 away = vehicle != null ? position - vehicle.transform.position : Vector3.zero;
                    away.y = 0f;
                    if (away.sqrMagnitude > 1f)
                    {
                        away.Normalize();
                        Vector3 course = away;
                        if (NearestLand(land, away, out Vector3 shore) && Vector3.Dot(shore, away) >= 0f) course = shore;
                        rotation = Quaternion.LookRotation(course);
                    }
                    Parachute parachute = GameManager.server.CreateEntity(VehicleCore.PrefabParachute, position, rotation) as Parachute;
                    if (parachute == null) return;
                    parachute.skinID = skin;
                    parachute.enableSaving = false;
                    parachute.Spawn();
                    parachute.SetHealth(parachute.MaxHealth());
                    if (parachute.mountPoints != null && parachute.mountPoints.Count > 0)
                    {
                        BaseMountable mountable = parachute.mountPoints[0].mountable;
                        if (mountable != null)
                        {
                            mountable.pitchClamp = new Vector2(-89f, 89f);
                            mountable.yawClamp = new Vector2(-180f, 180f);
                            _bot.navigator?.Pause();
                            mountable.MountPlayer(_bot);
                        }
                    }
                    if (_bot.isMounted)
                    {
                        _parachute = parachute;
                        _jumpedAt = UnityEngine.Time.time;
                        IgnoreBotParachutes(parachute);
                        _bot.SendNetworkUpdate();
                        if (!_bot.IsInvoking(CheckChuteLanding)) _bot.InvokeRepeating(CheckChuteLanding, ChuteLandStep, ChuteLandStep);
                    }
                    else
                    {
                        parachute.Kill();
                    }
                }

                private static void IgnoreBotParachutes(Parachute parachute)
                {
                    Collider[] own = parachute.GetComponentsInChildren<Collider>(true);
                    for (int i = _botParachutes.Count - 1; i >= 0; i--)
                    {
                        Parachute other = _botParachutes[i];
                        if (other == null || other.IsDestroyed)
                        {
                            _botParachutes.RemoveAt(i);
                            continue;
                        }
                        foreach (Collider theirs in other.GetComponentsInChildren<Collider>(true))
                            foreach (Collider mine in own)
                                if (!theirs.isTrigger && !mine.isTrigger) Physics.IgnoreCollision(mine, theirs);
                    }
                    _botParachutes.Add(parachute);
                }

                public void SteerTo(Vector3 point)
                {
                    _steerTo = point;
                    _steer = true;
                }

                public void SinkAt(float speed) => _sinkSpeed = Mathf.Max(0f, speed);

                private void FixedUpdate()
                {
                    if (_sinkSpeed <= 0f || _parachute == null || _parachute.IsDestroyed || _parachute.rigidBody == null || !IsParachuting) return;
                    Rigidbody body = _parachute.rigidBody;
                    Vector3 velocity = body.linearVelocity;
                    if (velocity.y > -_sinkSpeed) body.linearVelocity = new Vector3(velocity.x, -_sinkSpeed, velocity.z);
                }

                private void Steer()
                {
                    if (!_steer || _bot.GetHeldEntity() != null || _parachute == null) return;
                    BaseMountable seat = _bot.GetMounted();
                    if (seat == null) return;
                    Vector3 forward = _parachute.transform.forward;
                    forward.y = 0f;
                    Vector3 toTarget = _steerTo - _parachute.transform.position;
                    toTarget.y = 0f;
                    if (forward.sqrMagnitude < 0.01f || toTarget.sqrMagnitude < 1f) return;
                    float angle = Vector3.SignedAngle(forward, toTarget, Vector3.up);
                    int buttons = 0;
                    if (Mathf.Abs(angle) < SteerForwardAngle) buttons |= (int)BUTTON.FORWARD;
                    if (angle > SteerTurnAngle) buttons |= (int)BUTTON.RIGHT;
                    else if (angle < -SteerTurnAngle) buttons |= (int)BUTTON.LEFT;
                    _input ??= new InputState();
                    _input.previous.buttons = _input.current.buttons;
                    _input.current.buttons = buttons;
                    seat.PlayerServerInput(_input, _bot);
                }

                public bool Hangs(Vector3 position, out Vector3 ground, out float height)
                {
                    ground = position;
                    height = 0f;
                    if (!_landing || _bot == null || _bot.isMounted) return false;
                    if (!StandsOnSomething(_bot, position))
                    {
                        ground = CoreEx.GroundPosition(position);
                        height = position.y - Mathf.Max(ground.y, WaterSystem.OceanLevel);
                        if (height > AirborneHeight) return true;
                    }
                    _landing = false;
                    return false;
                }

                private static int _standMask;
                public static bool StandsOnSomething(BaseCustomNpc bot, Vector3 position)
                {
                    if (bot.IsInWater) return true;
                    if (_standMask == 0)
                        _standMask = LayerMask.GetMask("Terrain", "World", "Construction", "Deployed", "Default", "Tree", "Vehicle Large", "Vehicle Detailed", "Vehicle World");
                    return Physics.Raycast(position + Vector3.up * 0.5f, Vector3.down, AirborneHeight + 0.5f, _standMask, QueryTriggerInteraction.Ignore);
                }

                public void CheckAirborne(Vector3 position, Action rejump = null)
                {
                    if (!Hangs(position, out Vector3 ground, out float height))
                    {
                        if (_settle && _bot != null && !_bot.isMounted && !IsParachuting)
                        {
                            _settle = false;
                            if (!_bot.IsInWater && position.y - TerrainMeta.HeightMap.GetHeight(position) >= ElevatedSupport) PlaceOnLanding(position, true);
                        }
                        return;
                    }
                    _settle = false;
                    if (_jumps == 1 && height > 15f)
                    {
                        float flown = UnityEngine.Time.time - _jumpedAt;
                        if (rejump != null) rejump();
                        else DoJump(_skin, null, null, false, _useNavMesh);
                        if (IsParachuting) return;
                    }
                    bool overSea = ground.y <= WaterSystem.OceanLevel;
                    if (overSea) ground.y = WaterSystem.OceanLevel;
                    PlaceOnLanding(ground, !overSea);
                }

                private void PlaceOnLanding(Vector3 ground, bool support)
                {
                    if (!UsesNavMesh)
                    {
                        _bot.transform.position = ground;
                        _bot.ServerPosition = ground;
                        return;
                    }
                    if (support && GroundBelowSupport(_bot, ground, out Vector3 lower))
                    {
                        if (WalksDownFrom(ground, lower, out Vector3 deck))
                        {
                            ground = deck;
                        }
                        else
                        {
                            ground = lower;
                        }
                    }
                    else if (_bot.navigator != null && _bot.navigator.GetNearestNavmeshPosition(ground, out Vector3 walkable, AirborneNavSnap)) ground = walkable;
                    MoveBot(_bot, ground);
                }

                private bool UsesNavMesh => _useNavMesh == null || _useNavMesh();

                private static bool NearestLand(List<Vector3> land, Vector3 dir, out Vector3 shore)
                {
                    shore = dir;
                    if (land == null || land.Count == 0) return false;
                    float best = float.MinValue;
                    foreach (Vector3 candidate in land)
                    {
                        float dot = Vector3.Dot(candidate, dir);
                        if (dot <= best) continue;
                        best = dot;
                        shore = candidate;
                    }
                    return true;
                }

                private Vector3 JumpPoint(BaseVehicle vehicle, List<Vector3> land, bool leftSide)
                {
                    if (_jumpClearMask == 0)
                        _jumpClearMask = LayerMask.GetMask("Terrain", "World", "Construction", "Tree", "Vehicle Large", "Vehicle Detailed", "Vehicle World");
                    Vector3 from = vehicle != null ? vehicle.transform.position : _bot.transform.position;
                    Vector3 side = vehicle != null ? vehicle.transform.right : _bot.transform.right;
                    side.y = 0f;
                    side = side.sqrMagnitude > 0.001f ? side.normalized : Vector3.right;
                    float reach = 10f;
                    if (vehicle != null)
                    {
                        Vector3 extents = vehicle.bounds.extents;
                        reach = Mathf.Max(reach, Mathf.Max(extents.x, extents.z) + 5f);
                    }
                    float sign = leftSide ? -1f : 1f;
                    bool landSide = false;
                    if (NearestLand(land, side, out Vector3 right) && NearestLand(land, -side, out Vector3 left))
                    {
                        float toRight = Vector3.Dot(right, side), toLeft = Vector3.Dot(left, -side);
                        if (Mathf.Abs(toRight - toLeft) > 0.05f)
                        {
                            sign = toRight > toLeft ? 1f : -1f;
                            landSide = true;
                        }
                    }
                    for (int i = 0; i < 6; i++)
                    {
                        bool own = landSide ? i < 3 : i % 2 == 0;
                        int step = landSide ? i % 3 : i / 2;
                        Vector3 candidate = from + Vector3.up * 5f + side * ((own ? sign : -sign) * (reach + ParachuteGap * step));
                        if (!Physics.CheckSphere(candidate, 3f, _jumpClearMask, QueryTriggerInteraction.Ignore) && !ParachuteNear(candidate)) return candidate;
                    }
                    return from + Vector3.up * 5f + side * (sign * reach);
                }

                private void CheckChuteLanding()
                {
                    if (_bot == null || !_bot.IsValid() || _bot.IsDestroyed || !_bot.IsAlive() || !IsParachuting)
                    {
                        if (_bot == null) return;
                        _bot.CancelInvoke(CheckChuteLanding);
                        if (_bot.IsValid() && !_bot.IsDestroyed && _bot.IsAlive() && !_bot.isMounted) _settle = true;
                        return;
                    }
                    Steer();
                    if (_chuteLandMask == 0) _chuteLandMask = LayerMask.GetMask("Terrain", "World", "Construction", "Tree");
                    Vector3 position = _bot.transform.position;
                    bool near = Physics.SphereCast(position + Vector3.up, 0.5f, Vector3.down, out RaycastHit below, 0.5f + ChuteLandHeight,
                        _chuteLandMask, QueryTriggerInteraction.Ignore);
                    if (!near && _parachute != null && _parachute.rigidBody != null)
                    {
                        Vector3 drift = _parachute.rigidBody.linearVelocity;
                        drift.y = 0f;
                        float run = drift.magnitude * ChuteLandStep * 2f + 0.5f;
                        if (drift.sqrMagnitude > 0.25f)
                            near = Physics.Raycast(position + Vector3.up * 0.3f, drift.normalized, out below, run, _chuteLandMask, QueryTriggerInteraction.Ignore);
                    }
                    if (!near) return;
                    Vector3 ground = CoreEx.GroundPosition(position);
                    if (ground.y > position.y + 0.5f || position.y - ground.y > ChuteLandHeight + 1f
                        || WaterLevel.Test(ground + Vector3.up * 0.2f, true, true, _bot)) return;
                    BaseMountable seat = _bot.GetMounted();
                    if (seat == null) return;
                    seat.DismountPlayer(_bot, true);
                    if (_bot.isMounted) return;
                    _bot.CancelInvoke(CheckChuteLanding);
                    _steer = false;
                    PlaceOnLanding(ground, true);
                }

                public static bool GroundBelowSupport(BaseCustomNpc bot, Vector3 at, out Vector3 point)
                {
                    point = at;
                    if (bot == null || bot.navigator == null || at.y - TerrainMeta.HeightMap.GetHeight(at) < ElevatedSupport) return false;
                    float best = float.MaxValue;
                    foreach (float radius in GroundRings)
                    {
                        for (int i = 0; i < 12; i++)
                        {
                            Vector3 top = CoreEx.GroundPosition(at + Quaternion.Euler(0f, i * 30f, 0f) * Vector3.forward * radius);
                            if (top.y > at.y - ElevatedSupport + 0.5f) continue;
                            if (!bot.navigator.GetNearestNavmeshPosition(top, out Vector3 nav, 2f) || Mathf.Abs(nav.y - top.y) > 1f) continue;
                            if (CoreEx.DepthOver(nav) > 0.3f || CoreEx.InSafeZone(nav)) continue;
                            float distance = CoreEx.DistanceFlat(at, nav);
                            if (distance >= best) continue;
                            best = distance;
                            point = nav;
                        }
                        if (best < float.MaxValue) return true;
                    }
                    return false;
                }

                private bool WalksDownFrom(Vector3 at, Vector3 foot, out Vector3 deck)
                {
                    deck = at;
                    if (!(_bot.navigator is NavigatorNpc nav)) return false;
                    _walkDownCorners.Clear();
                    if (!nav.ProbeWorldPath(at, foot, ElevatedSupport - 0.5f, _walkDownCorners, out deck, out _, out _)
                        || Mathf.Abs(deck.y - at.y) > 1f || _walkDownCorners.Count == 0) return false;
                    Vector3 previous = deck;
                    foreach (Vector3 corner in _walkDownCorners)
                    {
                        float length = Vector3.Distance(previous, corner);
                        for (float d = 0f; d < length; d += 1f)
                            if (CoreEx.DepthOver(Vector3.Lerp(previous, corner, d / length)) >= WalkDownDepth) return false;
                        previous = corner;
                    }
                    return CoreEx.DepthOver(previous) < WalkDownDepth;
                }

                private static bool ParachuteNear(Vector3 point)
                {
                    foreach (Parachute own in _botParachutes)
                        if (own != null && !own.IsDestroyed && (own.transform.position - point).sqrMagnitude < ParachuteGap * ParachuteGap) return true;
                    _parachuteBuffer.Clear();
                    BaseEntity.Query.Server.GetInSphere(point, ParachuteGap, _parachuteBuffer);
                    bool near = false;
                    foreach (Parachute other in _parachuteBuffer)
                        if (other != null && !other.IsDestroyed) near = true;
                    _parachuteBuffer.Clear();
                    return near;
                }

                public void KillParachute()
                {
                    if (_parachute != null && !_parachute.IsDestroyed)
                    {
                        _parachute.DismountAllPlayers();
                        _parachute.Kill();
                    }
                    _parachute = null;
                }

                private void OnDestroy()
                {
                    if (_bot != null) _bot.CancelInvoke(CheckChuteLanding);
                    KillParachute();
                }
            }

            public class AttackHeliAim
            {
                private const float RocketLeadMaxTime = 6f;
                private static ItemDefinition _rocketSpeedFor;
                private static float _rocketSpeed = 30f;
                private BasePlayer _leadTarget;
                private Vector3 _leadPosition, _leadVelocity;
                private float _leadAt;

                public Vector3 RocketLead(AttackHelicopter heli, AttackHelicopterRockets rockets, BasePlayer target)
                {
                    Vector3 position = target.transform.position;
                    float now = UnityEngine.Time.time;
                    if (_leadTarget != target || now - _leadAt > 2f) _leadVelocity = Vector3.zero;
                    else if (now - _leadAt >= 0.2f)
                    {
                        Vector3 velocity = (position - _leadPosition) / (now - _leadAt);
                        velocity.y = 0f;
                        if (velocity.sqrMagnitude > 40f * 40f) velocity = Vector3.zero;
                        _leadVelocity = Vector3.Lerp(_leadVelocity, velocity, 0.6f);
                    }
                    if (_leadTarget != target || now - _leadAt >= 0.2f)
                    {
                        _leadTarget = target;
                        _leadPosition = position;
                        _leadAt = now;
                    }
                    if (_leadVelocity.sqrMagnitude < 0.25f) return position;
                    Vector3 to = position - heli.transform.position;
                    float distance = to.magnitude;
                    if (distance < 1f) return position;
                    float speed = Mathf.Max(5f, RocketSpeed(rockets));
                    float time = Mathf.Min(RocketLeadMaxTime, distance / speed);
                    Vector3 lead = position + _leadVelocity * time;
                    time = Mathf.Min(RocketLeadMaxTime, Vector3.Distance(heli.transform.position, lead) / speed);
                    lead = position + _leadVelocity * time;
                    lead.y = position.y + TerrainMeta.HeightMap.GetHeight(lead) - TerrainMeta.HeightMap.GetHeight(position);
                    return lead;
                }

                public static ItemDefinition NextRocket(AttackHelicopterRockets rockets)
                {
                    if (rockets?.inventory == null || rockets.owner == null) return null;
                    List<Item> ammo = Pool.Get<List<Item>>();
                    rockets.inventory.FindAmmo(ammo, AmmoTypes.ROCKET);
                    rockets.owner.FilterServerProjectileAmmo(ammo);
                    ItemDefinition next = null;
                    for (int i = ammo.Count - 1; i >= 0 && next == null; i--)
                        if (ammo[i].amount > 0) next = ammo[i].info;
                    Pool.FreeUnmanaged(ref ammo);
                    return next;
                }

                public static float RocketSpeed(AttackHelicopterRockets rockets)
                {
                    ItemDefinition ammo = NextRocket(rockets);
                    if (ammo == null) return _rocketSpeed;
                    if (ammo == _rocketSpeedFor) return _rocketSpeed;
                    _rocketSpeedFor = ammo;
                    ServerProjectile projectile = ammo.GetComponent<ItemModProjectile>()?.projectileObject?.Get()?.GetComponent<ServerProjectile>();
                    _rocketSpeed = projectile != null && projectile.speed > 1f ? projectile.speed : 30f;
                    return _rocketSpeed;
                }

                public static bool InTurretSector(AttackHelicopter heli, Vector3 from, BasePlayer player)
                {
                    Vector3 to = player.CenterPoint() - from;
                    if (to.sqrMagnitude < 0.01f) return false;
                    Vector3 local = heli.transform.InverseTransformDirection(to.normalized);
                    float pitch = Mathf.Asin(Mathf.Clamp(-local.y, -1f, 1f)) * Mathf.Rad2Deg;
                    float yaw = Mathf.Atan2(local.x, local.z) * Mathf.Rad2Deg;
                    return pitch >= heli.turretPitchClamp.x - 2f && pitch <= heli.turretPitchClamp.y + 2f
                           && yaw >= heli.turretYawClamp.x - 2f && yaw <= heli.turretYawClamp.y + 2f;
                }

                public static BasePlayer PickGunnerTarget(AttackHelicopter heli, Vector3 from, BasePlayer current, float range, Func<BasePlayer, bool> isTarget)
                {
                    bool keep = current != null && isTarget(current);
                    if (keep && InTurretSector(heli, from, current)) return current;
                    BasePlayer best = null, bestOutside = null;
                    float bestDistance = range, bestOutsideDistance = range;
                    foreach (BasePlayer player in BasePlayer.activePlayerList)
                    {
                        if (player == null || player == current) continue;
                        float distance = Vector3.Distance(from, player.transform.position);
                        if (distance > bestOutsideDistance && distance > bestDistance) continue;
                        if (!isTarget(player)) continue;
                        if (InTurretSector(heli, from, player))
                        {
                            if (distance > bestDistance) continue;
                            best = player;
                            bestDistance = distance;
                        }
                        else if (distance <= bestOutsideDistance)
                        {
                            bestOutside = player;
                            bestOutsideDistance = distance;
                        }
                    }
                    return best ?? (keep ? current : bestOutside);
                }
            }

            #endregion
        }
    }
