            public override void DismountObject()
            {
                BaseVehicle vehicle = GetMountedVehicle();
                if (vehicle != null && vehicle.GetParentEntity() is BaseVehicle root) vehicle = root;
                if (vehicle != null && !(vehicle is Parachute))
                {
                    LastDismountVehicle = vehicle;
                    LastDismountTime = UnityEngine.Time.time;
                    Invoke(LandAfterDismount, 0f);
                }
                base.DismountObject();
