            private const float DismountLandRange = 2f;

            private void LandAfterDismount()
            {
                if (IsDestroyed || !IsAlive() || isMounted || HasParent() || navigator == null) return;
                Vector3 position = ServerPosition;
                if (!navigator.TryNearestWalkable(position, DismountLandRange, out Vector3 walkable)) return;
                float drop = position.y - walkable.y;
                if (drop < 0.2f || Vector3Ex.Distance2D(position, walkable) > 1f || WaterLevel.Test(walkable + Vector3.up * 0.2f, true, true, this)) return;
                ServerPosition = walkable;
            }

            public void DismountSafely()
            {
                BaseMountable seat = GetMounted();
                if (seat == null) return;
                if (seat.GetDismountPosition(this, out Vector3 point, true) && seat.Distance(point) <= DismountPointReach)
                {
                    seat.DismountPlayer(this);
                    return;
                }
                BaseEntity vehicle = seat.VehicleParent();
                if (vehicle == null) vehicle = seat;
                if (!FindSpotBesideVehicle(vehicle, out Vector3 spot))
                {
                    seat.DismountPlayer(this);
                    return;
                }
                seat.DismountPlayer(this, true);
                if (isMounted) return;
                transform.rotation = Quaternion.Euler(0f, transform.eulerAngles.y, 0f);
                HelperVehicles.MoveBot(this, spot);
            }

            private const float DismountPointReach = 10f;
            private static readonly float[] DismountRings = { 0.6f, 1.5f, 3f, 5f };
            private const int DismountBlockMask = 1537286401;

            private bool FindSpotBesideVehicle(BaseEntity vehicle, out Vector3 spot)
            {
                spot = ServerPosition;
                if (navigator == null || vehicle == null) return false;
                Vector3 centre = vehicle.transform.position, seated = ServerPosition;
                float side = Mathf.Max(vehicle.bounds.extents.x, vehicle.bounds.extents.z);
                float heading = vehicle.transform.eulerAngles.y;
                foreach (float ring in DismountRings)
                    for (int angle = 0; angle < 360; angle += 30)
                    {
                        Vector3 probe = centre + Quaternion.Euler(0f, heading + 90f + angle, 0f) * Vector3.forward * (side + ring);
                        if (!navigator.TryNearestWalkable(probe, 1.5f, out Vector3 found) || Mathf.Abs(found.y - seated.y) > 3f) continue;
                        if (GamePhysics.CheckCapsule(found + Vector3.up * 0.5f, found + Vector3.up * 1.3f, 0.5f, DismountBlockMask)) continue;
                        spot = found;
                        return true;
                    }
                return false;
            }
