            private BaseCorpse GetCorpse(PlayerFlags flagsOnDeath, Vector3 posOnDeath, Quaternion rotOnDeath, List<TriggerBase> triggersOnDeath, bool forceServerSide)
            {
                bool lockedWear = inventory.containerWear.IsLocked();
                bool lockedBelt = inventory.containerBelt.IsLocked();
                bool lockedMain = inventory.containerMain.IsLocked();

                BaseCorpse corpse;
                DeadCorpse Corpse = ConfigNPC.GetDeadCorpse();
                if(Corpse != DeadCorpse.PlayerCorpse)
                {
                    if(lockedWear) inventory.containerWear.SetLocked(false);
                    else ClearContainerIfDead(inventory.containerWear);
                    if(lockedBelt) inventory.containerBelt.SetLocked(false);
                    else ClearContainerIfDead(inventory.containerBelt);
                    if(lockedMain) inventory.containerMain.SetLocked(false);
                    else ClearContainerIfDead(inventory.containerMain);
                }
                else
                {
                    inventory.containerWear.SetLocked(false);
                    inventory.containerBelt.SetLocked(false);
                    inventory.containerMain.SetLocked(false);
                }
                switch (Corpse)
                {
                    case DeadCorpse.NpcCorpse: corpse = CreateNPCPlayerCorpse(flagsOnDeath, lockedWear, lockedBelt, lockedMain); break;
                    case DeadCorpse.PlayerCorpse: corpse = CreatePlayerCorpse(flagsOnDeath, posOnDeath, rotOnDeath, lockedWear, lockedBelt, lockedMain, forceServerSide); break;
                    default: corpse = null; break;
                }

                if (corpse != null && !CollectionEx.IsNullOrEmpty(triggersOnDeath))
                {
                    foreach (TriggerBase item2 in triggersOnDeath)
                    {
                        if (item2 is TriggerParent triggerParent)
                        {
                            triggerParent.ForceParentEarly(corpse);
                        }
                    }
                }
                if (!corpse)
                {
                    DroppedBackpack(inventory.containerWear, inventory.containerBelt, inventory.containerMain);
                }
                return corpse;
            }
