            public void SetLookAngles(Vector3 direction)
            {
                if(!this.IsValid() || direction == Vector3.zero) return;
                ApplyLookDirection(direction);
            }

            private const float LookYawMinHorizontal = 0.087f;

            private void ApplyLookDirection(Vector3 direction)
            {
                float length = direction.magnitude;
                if (length < 0.0001f) return;
                float horizontal = Mathf.Sqrt(direction.x * direction.x + direction.z * direction.z);
                bool hasYaw = horizontal >= length * LookYawMinHorizontal;
                Quaternion look;
                if (hasYaw)
                {
                    look = Quaternion.LookRotation(direction, Vector3.up);
                }
                else
                {
                    float pitch = -Mathf.Asin(Mathf.Clamp(direction.y / length, -1f, 1f)) * Mathf.Rad2Deg;
                    look = Quaternion.Euler(pitch, viewAngles.y, 0f);
                }
                Vector3 previousAngles = viewAngles;
                base.eyes.rotation = look;
                viewAngles = look.eulerAngles;
                if (hasYaw) ServerRotation = Quaternion.Euler(0f, viewAngles.y, 0f);
                if (viewAngles != previousAngles) base.transform.hasChanged = true;
                _lastPositionUpdateTime = UnityEngine.Time.time;
            }

