            public void SleepNpc(Vector3 position, Quaternion rotation)
            {
                if(!this.IsValid() || !IsAlive()) return;
                navigator?.Stop();
                navigator?.Pause();
                if(GetHeldEntity() != null) EquipWeapon(-1);
                if(navigator == null || !navigator.Warp(position))
                {
                    transform.position = position;
                    ServerPosition = position;
                }
                SetLookAngles(rotation * Vector3.forward);
                if(modelState.ducked) Ducked = false;
                if(!IsNpcSleeping) SetPlayerFlag(PlayerFlags.Sleeping, true);
                SendNetworkUpdateImmediate();
            }

            public void WakeNpc()
            {
                if(!IsNpcSleeping) return;
                SetPlayerFlag(PlayerFlags.Sleeping, false);
                if(navigator != null && navigator.IsPaused) navigator.Resume();
                SendNetworkUpdateImmediate();
            }

