            public float WaterFactorNoWaves()
            {
                CapsuleCollider cc = playerCollider;
                if(cc == null) return WaterFactor();
                Vector3 center = cc.transform.TransformPoint(cc.center);
                float radius = cc.radius;
                float half = (cc.height <= 2f * radius) ? 0f : (cc.height * 0.5f - radius);
                Vector3 start = center - cc.transform.up * half;
                Vector3 end = center + cc.transform.up * half;
                return WaterLevel.Factor(start, end, radius, waves: false, volumes: true, this);
            }
            protected virtual void UpdateNpcModelState()
            {
                float factor = WaterFactorNoWaves();
                bool wasSwimming = modelState.waterLevel > 0f;
                bool isSwimming = wasSwimming ? factor >= ModelSwimExitFactor : factor >= ModelSwimEnterFactor;
                bool update = false;
                if(isSwimming)
                {
                    float waterLevel = Mathf.Max(factor, ModelSwimWaterLevelFloor);
                    if(modelState.waterLevel < waterLevel)
                    {
                        modelState.waterLevel = waterLevel;
                        update = true;
                    }
                }
                else if(modelState.waterLevel != 0)
                {
                    modelState.waterLevel = 0;
                    update = true;
                }

                if(IsSwimming()) _lastSwimTime = UnityEngine.Time.time;
                bool swimmingNow = IsInWater;
                if(swimmingNow != _wasSwimmingGame)
                {
                    _wasSwimmingGame = swimmingNow;
                    if(swimmingNow) UnequipIfNotUsableInWater();
                }

                if(modelState.ducked && !IsDucked())
                {
                    Ducked = true;
                    update = true;
                }
                else if(!modelState.ducked && IsDucked())
                {
                    Ducked = false;
                    update = true;
                }

                bool isOnLadder = navigator?.IsOnLadder ?? false;
                if(isOnLadder != modelState.onLadder)
                {
                    modelState.onLadder = isOnLadder;
                    update = true;
                }

                if(update) SendNetworkUpdate();
            }
            protected virtual void UnequipIfNotUsableInWater()
            {
                BaseEntity held = GetHeldEntity();
                if (held is BaseProjectile && held is not Speargun) EquipWeapon(-1);
            }
            public virtual void InitNPC()
            {
                IsInitBot = true;

                InvokeRepeatingFixedTime(UpdateModelStateTick);
                if (ConfigNPC.MetabolismEnabled())
                {
                    float interval = ConVar.Server.metabolismtick;
                    InvokeRepeating(MetabolismTick, interval, interval);
                }
            }
            protected virtual void MetabolismTick()
            {
                if (metabolism == null || !IsAlive()) return;
                float dt = ConVar.Server.metabolismtick;
                metabolism.ServerUpdate(this, dt);
                if (IsGod()) return;
                var m = metabolism;
                if (m.temperature.value < -20f)
                    Hurt(Mathf.InverseLerp(1f, -50f, m.temperature.value) * dt * 1f, DamageType.Cold);
                else if (m.temperature.value < -10f)
                    Hurt(Mathf.InverseLerp(1f, -50f, m.temperature.value) * dt * 0.3f, DamageType.Cold);
                else if (m.temperature.value < 1f)
                    Hurt(Mathf.InverseLerp(1f, -50f, m.temperature.value) * dt * 0.1f, DamageType.Cold);
                if (m.temperature.value > 60f)
                    Hurt(Mathf.InverseLerp(60f, 200f, m.temperature.value) * dt * 5f, DamageType.Heat);
                if (m.bleeding.value > 0f)
                {
                    float bleedAmt = dt * (1f / 3f);
                    Hurt(bleedAmt, DamageType.Bleeding);
                    m.bleeding.Subtract(bleedAmt);
                }
                if (m.poison.value > 0f)
                    Hurt(m.poison.value * dt * 0.1f, DamageType.Poison);
                if (ConVar.Server.radiation && m.radiation_poison.value > 0f)
                {
                    float radAmt = (1f + Mathf.Clamp01(m.radiation_poison.value / 25f) * 5f) * (dt / 5f);
                    Hurt(radAmt, DamageType.Radiation);
                    m.radiation_poison.Subtract(radAmt);
                }
                if (m.oxygen.value < 0.5f)
                {
                    Hurt(Mathf.InverseLerp(0.5f, 0f, m.oxygen.value) * dt * 20f * 0.99f, DamageType.Drowned, null, useProtection: false);
                }
            }
