            public virtual AttackEntity EquipWeapon(int slotNum, bool skipDeployDelay = false)
            {
                if ((slotNum < 0 || slotNum > 5) || inventory == null || inventory.containerBelt == null)
                {
                    if(modelState.aiming)
                    {
                        modelState.aiming = false;
                        SendNetworkUpdateImmediate();
                    }
                    UpdateActiveItem(default);
                    return null;
                }

                Item slot = inventory.containerBelt.GetSlot(slotNum);
                if (slot == null)
                {
                    if(modelState.aiming)
                    {
                        modelState.aiming = false;
                        SendNetworkUpdateImmediate();
                    }
                    UpdateActiveItem(default);
                    return null;
                }

                UpdateActiveItem(slot.uid);

                AttackEntity component = slot.GetHeldEntity() as AttackEntity;
                if (component != null)
                {
                    if (skipDeployDelay)
                    {
                        component.ResetAttackCooldown();
                    }
                }
                else if(modelState.aiming)
                {
                    modelState.aiming = false;
                    SendNetworkUpdateImmediate();
                }

                return component;
            }
