            private static bool IsAboard(BaseEntity entity, BaseVehicle vehicle)
            {
                if (entity == null) return false;
                if (entity == vehicle || entity.HasEntityInParents(vehicle)) return true;
                if (entity is not BasePlayer occupant || !occupant.isMounted || occupant.GetMountedVehicle() is not BaseVehicle seat) return false;
                return seat == vehicle || seat.HasEntityInParents(vehicle);
            }

            private bool WeaponFire(BaseProjectile weapon, float damageModifier, Action<BaseCombatEntity, bool> onHit)
            {
                if (!weapon.IsValid() || weapon.HasAttackCooldown())
                {
                    return false;
                }

                bool flag = this.IsValid();
                if (weapon.primaryMagazine.contents <= 0)
                {
                    weapon.SignalBroadcast(Signal.DryFire);
                    SignalBroadcast(Signal.DryFire);
                    weapon.StartAttackCooldownRaw(1f);
                    return false;
                }

                weapon.ModifyAmmoCount(-1);
                if (weapon.primaryMagazine.contents < 0)
                {
                    weapon.SetAmmoCount(0);
                }

                bool flag2 = flag && IsNpc;

                weapon.StartAttackCooldownRaw(weapon.repeatDelay);
                Vector3 vector = flag ? eyes.position : weapon.MuzzlePoint.transform.position;
                Vector3 inputVec = weapon.MuzzlePoint.transform.forward;

                ItemModProjectile ammoInfo = weapon.primaryMagazine.ammoType.GetComponent<ItemModProjectile>();
                weapon.SignalBroadcast(Signal.Attack, string.Empty, null, weapon.GetAttackEffect(), weapon.maxAttackEffectDistance);
                Projectile component = ammoInfo.projectileObject.Get().GetComponent<Projectile>();
                float num = ammoInfo.projectileVelocity;
                bool flag3 = weapon.GetParentEntity() is BasePlayer;
                BaseVehicle ownVehicle = flag && isMounted ? GetMountedVehicle() : null;
                if (ownVehicle != null && ownVehicle.GetParentEntity() is BaseVehicle rootVehicle) ownVehicle = rootVehicle;
                if (flag && weapon.useOwnerForward)
                {
                    inputVec = eyes.BodyForward();
                }

                for (int i = 0; i < ammoInfo.numProjectiles; i++)
                {
                    Vector3 vector2 = (!flag2) ? AimConeUtil.GetModifiedAimConeDirection(ammoInfo.projectileSpread + weapon.GetAimCone(), inputVec) : AimConeUtil.GetModifiedAimConeDirection(ammoInfo.projectileSpread + weapon.GetAimCone() + weapon.GetAIAimcone(), inputVec);
                    float radius = weapon.GetOverrideProjectileThickness(component);
                    List<RaycastHit> obj = Pool.Get<List<RaycastHit>>();
                    Ray ray = new Ray(vector, vector2);
                    GamePhysics.TraceAll(ray, radius, obj, 300f, 1220225793, QueryTriggerInteraction.Ignore, this);
                    float distanceOverride = 0f;
                    for (int j = 0; j < obj.Count && damageModifier != 0f; j++)
                    {
                        RaycastHit hit = obj[j];
                        BaseEntity entity = RaycastHitEx.GetEntity(hit);
                        if (flag3)
                        {
                            if (entity != null && (entity == weapon || entity.EqualNetID(weapon)))
                            {
                                continue;
                            }
                        }
                        else if (entity != null && weapon.HasEntityInParents(entity))
                        {
                            continue;
                        }
                        if (ownVehicle != null && IsAboard(entity, ownVehicle)) continue;

                        if (entity is BasePlayer basePlayer && basePlayer.GetActiveShield() is Shield foundShield && foundShield.RaycastAgainstColliders(ray, 300f))
                        {
                            Vector3 vector3 = weapon.transform.InverseTransformPoint(foundShield.transform.position);
                            Vector3 vector4 = weapon.transform.InverseTransformPoint(basePlayer.CenterPoint());
                            if (vector3.sqrMagnitude < vector4.sqrMagnitude)
                            {
                                continue;
                            }
                        }

                        ColliderInfo component2 = hit.collider.GetComponent<ColliderInfo>();
                        if (component2 != null && !component2.HasFlag(ColliderInfo.Flags.Shootable))
                        {
                            continue;
                        }

                        BaseCombatEntity baseCombatEntity = entity as BaseCombatEntity;
                        if (baseCombatEntity == null || entity == this || entity.EqualNetID(this) || !entity.IsVisible(vector, hit.point, 300f))
                        {
                            continue;
                        }

                        HitInfo info = new HitInfo();
                        weapon.AssignInitiator(info);
                        info.Weapon = weapon;
                        info.WeaponPrefab = weapon.gameManager.FindPrefab(weapon.PrefabName).GetComponent<AttackEntity>();
                        info.IsPredicting = false;
                        info.DoHitEffects = component.doHitEffects;
                        info.DidHit = true;
                        info.ProjectileVelocity = vector2 * 300f;
                        info.PointStart = weapon.MuzzlePoint.position;
                        info.PointEnd = hit.point;
                        info.HitPositionWorld = hit.point;
                        info.HitNormalWorld = hit.normal;
                        info.HitEntity = entity;
                        info.UseProtection = true;
                        distanceOverride = hit.distance;
                        component.CalculateDamage(info, weapon.GetProjectileModifier(), 1f);
                        info.damageTypes.ScaleAll(weapon.GetDamageScale() * damageModifier * (flag2 ? weapon.npcDamageScale : weapon.turretDamageScale));
                        float num2 = num > 0f ? (hit.distance / num) : 0f;
                        if (num2 > 0.2f)
                        {
                            Invoke(delegate
                            {
                                ProcessHit(info, ammoInfo, onHit);
                            }, num2);
                        }
                        else
                        {
                            ProcessHit(info, ammoInfo, onHit);
                        }

                        if (!(entity != null) || entity.ShouldBlockProjectiles())
                        {
                            break;
                        }
                    }

                    Pool.FreeUnmanaged(ref obj);
                    Vector3 vector5 = (flag && isMounted) ? (vector2 * 6f) : Vector3.zero;
                    weapon.CreateProjectileEffectClientside(ammoInfo.GetOverrideProjectile(this).resourcePath, vector + vector5, vector2 * num, Random.Range(1, 100), null, weapon.IsSilenced(), true, null, distanceOverride);
                }
                return true;

                static void ProcessHit(HitInfo hitInfo, ItemModProjectile itemModProjectile, Action<BaseCombatEntity, bool> onHit)
                {
                    if (hitInfo.Weapon.IsValid() && hitInfo.HitEntity.IsValid())
                    {
                        BaseCombatEntity target = (BaseCombatEntity)hitInfo.HitEntity;
                        float healthBefore = target.Health();
                        hitInfo.HitEntity.OnAttacked(hitInfo);
                        onHit?.Invoke(target, target.Health() < healthBefore);
                        itemModProjectile.ServerProjectileHit(hitInfo);
                        itemModProjectile.ServerProjectileHitEntity(hitInfo);
                        Shield shield = hitInfo.HitEntity as Shield;
                        if (hitInfo.HitEntity is BasePlayer || hitInfo.HitEntity is BaseNpc || shield != null)
                        {
                            hitInfo.HitPositionLocal = hitInfo.HitEntity.transform.InverseTransformPoint(hitInfo.HitPositionWorld);
                            hitInfo.HitNormalLocal = hitInfo.HitEntity.transform.InverseTransformDirection(hitInfo.HitNormalWorld);
                            hitInfo.HitMaterial = StringPool.Get((shield != null) ? shield.GetHitMaterialString() : "Flesh");
                            Effect.server.ImpactEffect(hitInfo);
                        }
                    }
                }
            }
