            public static TPlayer CreateCustomPlayer<TPlayer, TBrain, TNavigator>(IConfigNPC config, Vector3 spawnPos, Quaternion spawnRot, ulong fixedId = 0)
                where TPlayer : BaseCustomNpc
                where TBrain : BaseBrainCustomNpc
                where TNavigator : MonoBehaviour, INavigator
            {
                TPlayer customPlayer = null;
                if(config != null && UserIdPool.Instance?.TryGetUserId(config.IsPreferFemale(), config.GetIndexModel(), out ulong userId, fixedId) == true)
                {
                    Quaternion bodyRot = Quaternion.Euler(0f, spawnRot.eulerAngles.y, 0f);
                    BasePlayer player = GameManager.server.CreateEntity(PrefabCustomNpc, spawnPos, bodyRot, false) as BasePlayer;
                    customPlayer = player.gameObject.AddComponent<TPlayer>();
                    CopySerializableFields(player, customPlayer);
                    customPlayer.prefabID = player.prefabID;
                    DestroyImmediate(player, true);
                    customPlayer.ApplyNpcFaction();
                    customPlayer.ConfigNPC = config;
                    customPlayer.enableSaving = false;
                    customPlayer.canTriggerParent = false;
                    customPlayer.userID.Set(userId);
                    customPlayer.UserIDString = userId.ToString();
                    UserIdPool.Instance?.SetOwner(userId, customPlayer);
                    customPlayer.gameObject.AwakeFromInstantiate();
                    customPlayer.brain = customPlayer.gameObject.AddComponent<TBrain>();
                    customPlayer.navigator = customPlayer.gameObject.AddComponent<TNavigator>();
                    customPlayer.UpdateNetworkGroup();
                }
                return customPlayer;
            }
            private static void CopySerializableFields<T>(T src, T dst)
            {
                if (src == null)
                {
                    Debug.LogWarning<T>("Source object is null. Skipping copy.[{0}]", typeof(T).Name);
                    return;
                }
                FieldInfo[] srcFields = typeof(T).GetFields(BindingFlags.Public | BindingFlags.Instance);
                foreach (FieldInfo field in srcFields)
                {
                    object value = field.GetValue(src);
                    field.SetValue(dst, value);
                }
            }

