        public class BaseBrainCustomNpc : EntityComponent<BaseCustomNpc>
        {
            #region Fields And Properties
            public IFSM StateMachine;
            private INavigator _navigator;
            private HashSet<BaseEntity> nearestEntities;
            private HashSet<BaseCombatEntity> aggressiveEntities;
            private int layerFindNearestEntities = -1;
            private float _maxDistanceForFoundEntitiesMemorization_x2 = -1;
            public BaseCustomNpc CustomNpc => baseEntity as BaseCustomNpc;
            protected virtual bool CanUseFindNearestEntities => false;
            protected virtual bool CanUseStates => false;
            protected virtual int OverlayLayerFindNearestEntities => LayerMask.GetMask("Player (Server)", "AI");
            private float RadiusFindNearestEntities => CustomNpc?.ConfigNPC.RadiusFindNearestEntities() ?? 0f;
            private float MaxDistanceForFoundEntitiesMemorization => CustomNpc?.ConfigNPC.MaxDistanceForFoundEntitiesMemorization() ?? 0f;
            public INavigator Navigator => CustomNpc.IsValid() ? _navigator ??= gameObject.GetComponent<INavigator>() : null;
            #endregion

            #region UnityCallback
            #endregion

            #region Override Methods
            public override void InitShared()
            {
                base.InitShared();

                nearestEntities ??= Pool.Get<HashSet<BaseEntity>>();
                aggressiveEntities ??= Pool.Get<HashSet<BaseCombatEntity>>();
            }
            public override void DestroyShared()
            {
                CancelInvoke(StartTickComponents);
                CancelInvoke(MoveTick);
                CancelInvoke(BrainTick);
                if(nearestEntities != null) Pool.FreeUnmanaged(ref nearestEntities);
                if(aggressiveEntities != null) Pool.FreeUnmanaged(ref aggressiveEntities);

                base.DestroyShared();
            }
            #endregion

            #region Methods
            public virtual void InitNPC()
            {
                layerFindNearestEntities = OverlayLayerFindNearestEntities;
                if(MaxDistanceForFoundEntitiesMemorization > 0) _maxDistanceForFoundEntitiesMemorization_x2 = MaxDistanceForFoundEntitiesMemorization * MaxDistanceForFoundEntitiesMemorization;

                if (Navigator != null)
                {
                    Navigator.Init(CustomNpc);
                    Invoke(StartTickComponents, 0.1f);
                }
                else
                {
                    Debug.LogError<BaseBrainCustomNpc>("Failed to set up navigation for the npc {0}[{1}]", CustomNpc.displayName, CustomNpc.UserIDString);
                    Invoke(baseEntity.AdminKill, 0.1f);
                }
            }
            private void StartTickComponents()
            {
                float num1 = CustomNpc.ConfigNPC.DeltaTickMove();
                float num2 = CustomNpc.ConfigNPC.DeltaTickBrain();
                CancelInvoke(MoveTick);
                CancelInvoke(BrainTick);
                InvokeRepeating(MoveTick, num1, num1);
                InvokeRepeating(BrainTick, num2, num2);
            }
            protected virtual void MoveTick()
            {
                try
                {
                    if (!baseEntity.IsValid() || !CustomNpc.IsAlive() || CustomNpc.IsNpcSleeping) return;
                    float delta = CustomNpc.ConfigNPC.DeltaTickMove();
                    Vector3 before = CustomNpc.ServerPosition;
                    Navigator?.Think(delta);
                    if (CustomNpc.ServerPosition != before) CustomNpc.MarkMoved();
                }
                catch (Exception ex)
                {
                    Debug.LogError<BaseBrainCustomNpc>("MoveTick: {0}", ex);
                }
            }
            protected virtual void BrainTick()
            {
                try
                {
                    if (CustomNpc.IsValid() && CustomNpc.IsNpcSleeping) return;
                    UpdateAggressiveList();
                    if(CanUseFindNearestEntities) FindNearestEntities();
                    if(CanUseStates) UpdateState();
                }
                catch (Exception ex)
                {
                    Debug.LogError<BaseBrainCustomNpc>("BrainTick: {0}", ex);
                }
            }
            private void UpdateAggressiveList()
            {
                if(aggressiveEntities != null && aggressiveEntities.Count > 0)
                {
                    List<BaseCombatEntity> list = Pool.Get<List<BaseCombatEntity>>();
                    list.AddRange(aggressiveEntities);
                    foreach(var entity in list) if(!entity.IsValid() || !entity.IsAlive()) aggressiveEntities.Remove(entity);
                    Pool.FreeUnmanaged(ref list);
                }
            }
            private static readonly int MovingLayers = LayerMask.GetMask("Player (Server)", "AI");
            protected virtual float WorldLayersScanInterval => 1f;
            private float _nextWorldLayersScan;
            private void FindNearestEntities()
            {
                if(nearestEntities == null) return;
                List<BaseEntity> entities = Pool.Get<List<BaseEntity>>();
                try
                {
                    int mask = layerFindNearestEntities;
                    float now = UnityEngine.Time.time;
                    if(now >= _nextWorldLayersScan) _nextWorldLayersScan = now + WorldLayersScanInterval;
                    else mask &= MovingLayers;
                    Vector3 position = transform.position;
                    foreach(var entity in nearestEntities)
                        if(entity != null && (_maxDistanceForFoundEntitiesMemorization_x2 <= 0
                                              || (entity.transform.position - position).sqrMagnitude <= _maxDistanceForFoundEntitiesMemorization_x2))
                            entities.Add(entity);
                    nearestEntities.Clear();
                    if(mask != 0) Vis.Entities(position, RadiusFindNearestEntities, entities, mask, QueryTriggerInteraction.Ignore);

                    foreach(var entity in entities)
                    {
                        if(entity == null || entity == baseEntity) continue;
                        if(CanAddNearestEntity(entity)) nearestEntities.Add(entity);
                    }
                }
                finally
                {
                    Pool.FreeUnmanaged(ref entities);
                }
            }
            public NearestEntityEnumerator<T> GetNearestEntity<T>(Func<T, bool> func) where T : BaseEntity
                => new NearestEntityEnumerator<T>(nearestEntities, func);
            public struct NearestEntityEnumerator<T> where T : BaseEntity
            {
                private HashSet<BaseEntity>.Enumerator _inner;
                private readonly Func<T, bool> _filter;
                private readonly bool _hasSource;
                private T _current;

                public NearestEntityEnumerator(HashSet<BaseEntity> source, Func<T, bool> filter)
                {
                    _inner = source != null ? source.GetEnumerator() : default;
                    _filter = filter;
                    _hasSource = source != null;
                    _current = null;
                }
                public NearestEntityEnumerator<T> GetEnumerator() => this;
                public T Current => _current;
                public bool MoveNext()
                {
                    if(!_hasSource) return false;
                    while(_inner.MoveNext())
                    {
                        if(_inner.Current is T result && result != null && (_filter == null || _filter.Invoke(result)))
                        {
                            _current = result;
                            return true;
                        }
                    }
                    _current = null;
                    return false;
                }
            }
            protected virtual bool CanAddNearestEntity(BaseEntity entity)
            {
                if(entity is BaseCombatEntity && (_maxDistanceForFoundEntitiesMemorization_x2 <= 0 || (entity.transform.position - transform.position).sqrMagnitude <= _maxDistanceForFoundEntitiesMemorization_x2)) return true;
                return false;
            }
            protected virtual void UpdateState()
            {
                if(StateMachine.IsValid())
                {
                    StateMachine.Update();
                }
            }
            public override string ToString()
            {
                return $"{CustomNpc?.displayName}[{CustomNpc?.UserIDString}]";
            }

            public virtual void OnAttackEnemy(BaseCombatEntity enemy)
            {
                if(aggressiveEntities != null && enemy != null) aggressiveEntities.Add(enemy);
            }
            public bool IsAggressiveFrom(BaseCombatEntity enemy)
            {
                if(aggressiveEntities != null && enemy != null) return aggressiveEntities.Contains(enemy);
                return false;
            }
            public float PercentHeal()
            {
                return baseEntity.Health() / baseEntity.MaxHealth();
            }
            #endregion
        }

    }
    #endregion

    #region Base State Machine
    public partial class NPCsController
    {
        public interface IFSM
        {
            BaseCustomNpc Owner { get; }
            bool IsValid { get; }
            string CurrentStateName { get; }
            void Update();
            void ActivateState(FSM.IStatePlayerNpc state);
            bool IsActive(FSM.IStatePlayerNpc state);
            void SetIdleState();
            FSM.IStatePlayerNpc GetCurrentState();
        }
        public abstract class FSM : IFSM, Pool.IPooled
        {
            #region Fields And Properties
            private BaseCustomNpc _owner;
            private IdleState _idleState;
            private TurretEscapeState _turretEscapeState;
            private IStatePlayerNpc currentState;
            private float lastUpdate;
            private bool isPool;

            public BaseCustomNpc Owner => _owner;
            private bool isInitFSM => _idleState.IsValid();
            public BaseStatePlayerNpc RootIdleState => _idleState;
            public bool IsValid => !isPool;
            string IFSM.CurrentStateName => (bool)this ? currentState.Name : "";
            #endregion

            public static IFSM GetPoolFSM<T>(BaseCustomNpc owner) where T : FSM, new()
            {
                return Pool.Get<T>().StartFSM(owner);
            }
            public static void SetPoolFSM<T>(ref IFSM obj) where T : FSM, new()
            {
                T _obj = obj as T;
                SetPoolFSM<T>(ref _obj);
                obj = null;
            }
            public static void SetPoolFSM<T>(ref T obj) where T : FSM, new()
            {
                if(obj != null) Pool.Free<T>(ref obj);
            }

            #region Methods
            private IFSM StartFSM(BaseCustomNpc owner)
            {
                _owner = owner;
                try
                {
                    Start();
                }
                catch (Exception ex)
                {
                    Debug.LogError<FSM>("StartFSM[{0}]: {1}", GetType().Name, ex);
                }
                return this;
            }
            void Pool.IPooled.EnterPool()
            {
                try
                {
                    OnDestroy();
                    BaseStatePlayerNpc.SetPoolState(ref _idleState);
                    BaseStatePlayerNpc.SetPoolState(ref _turretEscapeState);
                }
                catch (Exception ex)
                {
                    Debug.LogError<FSM>("EnterPool[{0}]: {1}", GetType().Name, ex);
                }
                finally
                {
                    isPool = true;
                    currentState = null;
                    _owner = null;
                    _idleState = null;
                    _turretEscapeState = null;
                    _crawling = false;
                    _crawlPickAt = 0f;
                }
            }
            void Pool.IPooled.LeavePool()
            {
                isPool = false;
                lastUpdate = UnityEngine.Time.realtimeSinceStartup;
            }

            void IFSM.ActivateState(IStatePlayerNpc state)
            {
                BlackBox.NoteState(_owner, this, currentState, state);
                if(currentState.IsValid())
                {
                    currentState.LeaveState();
                }

                if(state.IsValid())
                {
                    currentState = state;
                    state.EnterState();
                }
                else currentState = null;
            }
            bool IFSM.IsActive(IStatePlayerNpc state)
            {
                return currentState.IsValid() && currentState == state;
            }
            void IFSM.Update()
            {
                if(!Owner.IsValid() || !Owner.IsAlive() || !IsValid) return;
                if(Owner.IfIncapacitated())
                {
                    SetIdleState();
                    TickCrawl();
                    return;
                }
                if(_crawling) StopCrawl();
                try
                {
                    if(!isInitFSM)
                    {
                        _idleState = BaseStatePlayerNpc.GetPoolState<IdleState>(this);
                        if(!isInitFSM)
                        {
                            Debug.LogWarning<FSM>("Update[{0}]: No idle state", GetType().Name);
                            return;
                        }
                        InitFSM(_idleState);
                        ((IFSM)this).ActivateState(_idleState);
                        return;
                    }
                    TryStartTurretEscape();
                    TickState(Time.realtimeSinceStartup - lastUpdate);
                }
                catch (Exception ex)
                {
                    Debug.LogError<FSM>("Update[{0}]: {1}", GetType().Name, ex);
                }
                finally
                {
                    lastUpdate = Time.realtimeSinceStartup;
                }
            }
            private const float CrawlRepick = 5f;
            private const float CrawlStep = 10f;
            private const float CrawlThreatRange = 80f;
            private static readonly int CrawlCoverMask = LayerMask.GetMask("World", "Construction", "Terrain", "Deployed", "Default");
            private bool _crawling;
            private float _crawlPickAt;
            private void TickCrawl()
            {
                if(!Owner.IsCrawling() || Owner.IsSwimming())
                {
                    if(_crawling) StopCrawl();
                    return;
                }
                float now = UnityEngine.Time.time;
                if(now < _crawlPickAt) return;
                _crawlPickAt = now + CrawlRepick;
                INavigator navigator = Owner.GetComponent<INavigator>();
                if(navigator == null || !TryCrawlPoint(navigator, out Vector3 point)) return;
                _crawling = navigator.SetDestination(point, NavigationSpeed.Slow);
            }
            private void StopCrawl()
            {
                _crawling = false;
                _crawlPickAt = 0f;
                Owner.GetComponent<INavigator>()?.Stop();
            }
            private bool TryCrawlPoint(INavigator navigator, out Vector3 point)
            {
                point = Vector3.zero;
                Vector3 from = Owner.transform.position;
                BaseEntity threat = Owner.lastAttacker;
                bool hasThreat = threat != null && !threat.IsDestroyed && threat != Owner
                                 && Vector3.Distance(threat.transform.position, from) < CrawlThreatRange;
                Vector3 away = hasThreat ? from - threat.transform.position : UnityEngine.Random.insideUnitSphere;
                away.y = 0f;
                if(away.sqrMagnitude < 0.01f) away = Owner.transform.forward;
                away.Normalize();
                Vector3 eye = hasThreat ? threat.transform.position + Vector3.up * 1.5f : Vector3.zero;
                float bestScore = float.MinValue;
                for(int i = 0; i < 7; i++)
                {
                    Vector3 dir = Quaternion.Euler(0f, (i - 3) * 30f, 0f) * away;
                    if(!navigator.GetNearestNavmeshPosition(from + dir * CrawlStep, out Vector3 candidate, 3f)) continue;
                    if(WaterLevel.Test(candidate + Vector3.up * 0.3f, waves: false, volumes: false)) continue;
                    float score = hasThreat ? Vector3.Distance(candidate, threat.transform.position) : 0f;
                    if(hasThreat && Physics.Linecast(eye, candidate + Vector3.up * 0.5f, CrawlCoverMask, QueryTriggerInteraction.Ignore)) score += CrawlStep;
                    score -= Mathf.Abs(i - 3) * 0.5f;
                    if(score <= bestScore) continue;
                    bestScore = score;
                    point = candidate;
                }
                return bestScore > float.MinValue;
            }
            public void SetIdleState()
            {
                if(IsValid && currentState != null && currentState is not IdleState && _idleState != null && _idleState.IsValid && this is IFSM ifsm) ifsm.ActivateState(_idleState);
            }
            private void TickState(float delta)
            {
                if(currentState.IsValid()) currentState.TickState(delta);
            }
            private void TryStartTurretEscape()
            {
                if(currentState is not BaseStatePlayerNpc state || !state.YieldsToTurretEscape) return;
                if(_owner.brain == null || _owner.brain.StateMachine != this) return;
                if(_owner.isMounted) return;
                if(_turretEscapeState != null && UnityEngine.Time.time < _turretEscapeState.RetryAfter) return;
                if(!_owner.IsExposedToMonumentTurret) return;
                if(_turretEscapeState == null)
                {
                    _turretEscapeState = BaseStatePlayerNpc.GetPoolState<TurretEscapeState>(this);
                    _turretEscapeState.AddCompletedTransfer(_idleState);
                    _turretEscapeState.AddFailureTransfer(_idleState);
                }
                ((IFSM)this).ActivateState(_turretEscapeState);
            }

            protected abstract void Start();
            protected abstract void InitFSM(BaseStatePlayerNpc idleState);
            protected abstract void OnDestroy();

            IStatePlayerNpc IFSM.GetCurrentState()
            {
                return currentState;
            }
            #endregion

            public static implicit operator bool(FSM fsm)
            {
                return fsm != null && fsm.IsValid && fsm.isInitFSM && fsm.currentState.IsValid();
            }

            #region FSM Core - IdleState, AttackState
            public class IdleState : BaseStatePlayerNpc
            {
                public override string Name => "Idle";
                public override bool YieldsToTurretEscape => true;

                protected override void Start()
                {
                }

                protected override void OnDestroy()
                {
                }

                protected override void EnterState()
                {
                }

                protected override void LeaveState()
                {
                }

                protected override bool CanEnterState()
                {
                    return true;
                }

                protected override ResponseFromUpdateState UpdateState(float delta)
                {
                    return ResponseFromUpdateState.Success;
                }
            }

            public class TurretEscapeState : RouterState
            {
                public const float RetryDelay = 5f;
                private const float ZoneExitMargin = 6f;
                private const float ExitSampleRadius = 4f;
                private int _variant;
                private Vector3 _exit;

                public float RetryAfter { get; private set; }
                public override string Name => "TurretEscape";
                public override bool YieldsToTurretEscape => false;
                protected override BaseEntity GetChaseEnemy => null;
                protected override float MinDistanceMovedEnemyForAddPoint => 0f;

                protected override void OnDestroy()
                {
                    _variant = 0;
                    _exit = Vector3.zero;
                    RetryAfter = 0f;
                    base.OnDestroy();
                }
                protected override void EnterState()
                {
                    base.EnterState();
                    _variant = 0;
                    _exit = Vector3.zero;
                    bool picked = PickExit();
                }
                protected override bool CanEnterState() => Owner.IsValid() && Owner.IsExposedToMonumentTurret;
                protected override ResponseFromUpdateState UpdateState(float delta)
                {
                    base.UpdateState(delta);
                    if (!Owner.IsHostile()) return ResponseFromUpdateState.Completed;
                    bool moving = modeRouter == IRouterState.ModeRouter.Moved && !IsStuck;
                    if (!Owner.IsExposedToMonumentTurret)
                    {
                        if (!moving || !HelperSafeZones.IsInTurretRange(Owner.transform.position, HelperSafeZones.TurretMargin))
                            return ResponseFromUpdateState.Completed;
                        return ResponseFromUpdateState.NONE;
                    }
                    if (moving) return ResponseFromUpdateState.NONE;
                    ResetStuck();
                    _variant++;
                    if (PickExit()) return ResponseFromUpdateState.NONE;
                    RetryAfter = UnityEngine.Time.time + RetryDelay;
                    return ResponseFromUpdateState.Failure;
                }

                private bool PickExit()
                {
                    Vector3 pos = Owner.transform.position;
                    for (; _variant < HelperSafeZones.EscapeVariantCount; _variant++)
                    {
                        if (!HelperSafeZones.TryGetEscapePoint(pos, out Vector3 exit, ZoneExitMargin, _variant)) return false;
                        if (Navigator == null || !Navigator.GetNearestNavmeshPosition(exit, out Vector3 onMesh, ExitSampleRadius)) continue;
                        if (HelperSafeZones.IsWayBlocked(pos, onMesh)) continue;
                        _exit = onMesh;
                        SetTarget(onMesh, NavigationSpeed.Fast);
                        if (!IsStuck) return true;
                        ResetStuck();
                    }
                    return false;
                }
            }

            public interface IAttackState
            {
                void OnAttack(BaseCombatEntity enemy);

                [JsonConverter(typeof(StringEnumConverter))]
                public enum PersonalityBot
                {
                    Unknown, Friendly, Defensive, Aggressive,
                }

                public enum TypeEnemy
                {
                    Unknown, NPC, Player, Animal, Turret, Tank
                }
            }
            public abstract class AttackState : BaseStatePlayerNpc
            {
                #region Fields And Properties
                public WeaponInfo CurrentWeapon;
                public EnemyInfo CurrentEnemy;
                private readonly int layerVisibleEnemy = LayerMask.GetMask("Default", "Player (Server)", "AI", "World", "Terrain", "Vehicle Large", "Vehicle World", "Vehicle Detailed", "Prevent Movement", "Tree", "Deployed", "Construction");
                private TimeSince timerDown;
                private TimeSince timerCooldown;

                private BaseEntity currentMeleeTarget;
                private BaseMelee currentMelee;
                private float currentMeleeRate;
                private AttackEntity _drawWeapon;
                private float _drawStartTime;

                protected virtual float TimeDown => 1f;
                protected virtual float TimeCooldown => 1f;
                protected virtual int OverrideLayerVisibleEnemy => layerVisibleEnemy;
                public bool IsDown => Owner.IsInvoking(OnDown);
                protected bool IsCooldown => timerCooldown <= TimeCooldown;
                protected abstract bool canAimDirection { get; }
                protected abstract bool CanAimingWeaponFire { get; }
                protected virtual bool AimAtHead => false;
                #endregion

                protected override void OnDestroy()
                {
                    CurrentWeapon = null;
                    CurrentEnemy = null;
                    currentMeleeTarget = null;
                    currentMelee = null;
                    currentMeleeRate = 0f;
                    _drawWeapon = null;
                    _drawStartTime = 0f;
                    if(IsDown) Owner.CancelInvoke(OnDown);
                    if (Owner.IsInvoking(ServerMeleeAttack)) Owner.CancelInvoke(ServerMeleeAttack);
                }

                protected override void EnterState()
                {
                    timerDown = 0;
                    timerCooldown = 0;
                    _drawWeapon = null;
                }
                protected override void LeaveState()
                {
                    if(IsDown) Owner.CancelInvoke(OnDown);
                    if (Owner.IsInvoking(ServerMeleeAttack)) Owner.CancelInvoke(ServerMeleeAttack);
                    currentMeleeTarget = null;
                    currentMelee = null;
                    currentMeleeRate = 0;
                    _drawWeapon = null;
                }

                protected bool DownTrigger()
                {
                    if(IsDown)
                    {
                        Owner?.CancelInvoke(OnDown);
                    }
                    if(CanUseDown())
                    {
                        timerDown = 0;
                        Owner?.InvokeRepeating(OnDown, 0f, 0.03f);
                        return true;
                    }
                    return false;
                }
                protected void StopAttack()
                {
                    if(IsDown)
                    {
                        Owner.CancelInvoke(OnDown);
                        timerDown = TimeDown + 1;
                    }
                    timerCooldown = 0;
                }

                private void OnDown()
                {
                    if(!CurrentWeapon.HasAttackCooldown()) UseAttack();
                    float holdLimit = Mathf.Max(TimeDown, CurrentWeapon.DrawTime + DrawHoldMargin);
                    if(!CanUseDown() || !CurrentWeapon.HasAmmoMagazine || timerDown > holdLimit || !CurrentWeapon.HasModeDown())
                    {
                        timerCooldown = 0;
                        timerDown = TimeDown + 1;
                        Owner?.CancelInvoke(OnDown);
                        if(CurrentWeapon && !CurrentWeapon.IsReloading && !CurrentWeapon.HasAmmoMagazine && (CurrentWeapon.HasAmmoInventory || Owner.ConfigNPC.CanUseAmmoInventory()))
                        {
                            CurrentWeapon.Reload();
                        }
                        return;
                    }
                }
                private bool CanUseDown()
                {
                    if(!CurrentWeapon || CurrentWeapon.IsReloading || !Owner.CanAttack()) return false;

                    return true;
                }
                private void UseAttack()
                {
                    if(!CurrentEnemy) return;
                    bool ranged = !CurrentWeapon.IsMelee;
                    if(ranged && !CanContinueFire())
                    {
                        StopAttack();
                        return;
                    }
                    bool atHead = ranged && AimAtHead;
                    if(canAimDirection) Owner.SetAimDirection(((atHead ? CurrentEnemy.HeadPoint : CurrentEnemy.CenterPoint) - Owner.eyes.position).normalized);
                    if(!IsWeaponDrawn()) return;
                    if(ServerUseWeapon(GetDamageScaleToEnemy()))
                    {
                        _drawWeapon = null;
                        if(ranged) OnAttackDelivered();
                    }
                }
                private const float DrawHoldMargin = 0.25f;
                private bool IsWeaponDrawn()
                {
                    float drawTime = CurrentWeapon.DrawTime;
                    if(drawTime <= 0f || CurrentWeapon.Ammo <= 0) return true;
                    if(_drawWeapon != CurrentWeapon.Weapon || !Owner.modelState.aiming)
                    {
                        _drawWeapon = CurrentWeapon.Weapon;
                        _drawStartTime = UnityEngine.Time.time;
                        Owner.StateWeaponFire(true);
                        return false;
                    }
                    return UnityEngine.Time.time - _drawStartTime >= drawTime;
                }
                public bool ServerUseWeapon(float rateDamage = 1f)
                {
                    if(!CurrentWeapon) return false;
                    if(!CurrentWeapon.IsMelee)
                    {
                        Owner.StateWeaponFire(CanAimingWeaponFire);
                        return Owner.WeaponFire(CurrentWeapon.Weapon as BaseProjectile, rateDamage, _onHitLanded ??= OnHitLanded);
                    }
                    if(Owner.IsInvoking(ServerMeleeAttack)) return false;
                    AttackMelee(rateDamage);
                    return true;
                }
                protected virtual void OnAttackDelivered() { }
                protected virtual void OnHitLanded(BaseCombatEntity target, bool hurt) { }
                private Action<BaseCombatEntity, bool> _onHitLanded;
                protected virtual bool CanContinueFire() => true;
                protected abstract float GetDamageScaleToEnemy();
                private void AttackMelee(float rateDamage)
                {
                    if (CurrentWeapon.Weapon is BaseMelee melee)
                    {
                        if(Owner.modelState.aiming)
                        {
                            Owner.modelState.aiming = false;
                            Owner.SendNetworkUpdateImmediate();
                        }
                        melee.StartAttackCooldown(melee.repeatDelay * 2f);
                        Owner.SignalBroadcast(BaseEntity.Signal.Attack, string.Empty);

                        if (melee.swingEffect.isValid) Effect.server.Run(melee.swingEffect.resourcePath, Owner.transform.position, Vector3.forward, Owner.net.connection);
                        if (Owner.IsInvoking(ServerMeleeAttack)) Owner.CancelInvoke(ServerMeleeAttack);

                        currentMeleeTarget = CurrentEnemy.Enemy;
                        currentMelee = melee;
                        currentMeleeRate = rateDamage;

                        Owner.Invoke(ServerMeleeAttack, CurrentWeapon.AiMeleeStrikeDelay());
                    }
                }
                private void ServerMeleeAttack()
                {
                    if(!CurrentWeapon || CurrentWeapon.Weapon != currentMelee || currentMeleeTarget != CurrentEnemy.Enemy || !CurrentWeapon.HasUseDistance(CurrentEnemy.Distance(Owner))) return;
                    if(currentMeleeTarget.IsSafeZone()) return;

                    Vector3 vector = Owner.eyes.BodyForward();

                    float num = 0f;
                    if(currentMelee.damageTypes != null)
                    {
                        foreach (DamageTypeEntry damageType in currentMelee.damageTypes) num += damageType.amount;
                    }
                    HitInfo info = new HitInfo(Owner, currentMeleeTarget, DamageType.Slash, num * currentMelee.npcDamageScale * currentMeleeRate);
                    info.Weapon = currentMelee;
                    info.CanGather = !(currentMeleeTarget is BasePlayer or BaseNpc);
                    BaseCombatEntity target = CurrentEnemy.Enemy;
                    float healthBefore = target.Health();
                    currentMeleeTarget.OnAttacked(info);
                    OnAttackDelivered();
                    OnHitLanded(target, target.Health() < healthBefore);
                    HitInfo obj2 = Pool.Get<HitInfo>();
                    obj2.HitEntity = currentMeleeTarget;
                    obj2.HitPositionWorld = currentMeleeTarget.CenterPoint();
                    obj2.HitNormalWorld = -vector;
                    if (currentMeleeTarget is BaseNpc || currentMeleeTarget is BasePlayer || (currentMeleeTarget is BaseNPC2 npc2 && !npc2.IsAnimal))
                    {
                        obj2.HitMaterial = StringPool.Get("Flesh");
                    }
                    else
                    {
                        obj2.HitMaterial = StringPool.Get(currentMeleeTarget.gameObject.GetComponent<Collider>() is Collider collider && collider.sharedMaterial != null ? collider.sharedMaterial.GetName() : "generic");
                    }

                    currentMelee.ServerUse_OnHit(obj2);
                    Effect.server.ImpactEffect(obj2);
                    Pool.Free(ref obj2);
                    currentMeleeTarget = null;
                    currentMelee = null;
                    currentMeleeRate = 0f;
                }

                public struct WeaponInfo
                {
                    private const float min_distance_attack_melee = 0.25f;
                    private const float max_distance_attack_melee = 2f;
                    private const float min_distance_attack_weapon = 0.25f;
                    private const float max_distance_attack_weapon = 25f;
                    public static float DefaultRangedMaxDistance => max_distance_attack_weapon;
                    private TimeSince reloadTimer;
                    public BaseCustomNpc Owner { get; private set; }
                    public AttackEntity Weapon { get; private set; }
                    public readonly bool IsMelee => Weapon is BaseMelee;
                    public bool HasAmmoInventory => IsValid() && (IsMelee || Owner.HasAmmoForWeapon(Weapon));
                    public bool HasAmmoMagazine => IsValid() && (IsMelee || Weapon.AmmoFraction() > 0);
                    public bool HasAmmo => HasAmmoMagazine || HasAmmoInventory;
                    public bool IsReloading => IsValid() && (Weapon.ServerIsReloading() || reloadTimer < GetTimerReload());
                    public readonly float DrawTime => Weapon switch
                    {
                        CompoundBowWeapon => 1.5f,
                        BowWeapon => 1f,
                        _ => 0f,
                    };
                    public int Ammo => IsValid() && Weapon is BaseProjectile weapon ? weapon.primaryMagazine.contents : 0;

                    private WeaponInfo(AttackEntity weapon)
                    {
                        if (weapon == null)
                        {
                            Owner = null;
                            Weapon = null;
                            reloadTimer = ReloadLongAgo;
                            return;
                        }

                        Weapon = weapon;
                        Owner = Weapon.GetOwnerPlayer() as BaseCustomNpc;
                        reloadTimer = ReloadLongAgo;
                    }
                    private const float ReloadLongAgo = 1000f;

                    private bool IsValid()
                    {
                        bool valid1 = Owner.IsValid();
                        bool valid2 = Weapon.IsValid() && Weapon.GetParentEntity() != null && Weapon.GetItem() != null;
                        if(!valid1 && Owner != null) Owner = null;
                        if(!valid2 && Weapon != null) Weapon = null;
                        return valid1 && valid2 && Owner.GetHeldEntity() == Weapon
                            && (!Owner.IsSwimming() || IsMelee || Weapon.CanBeUsedInWater());
                    }
                    public readonly bool HasUseDistance(float distance) => distance >= MinDistanceAttack() && distance <= MaxDistanceAttack();
                    public readonly float MinDistanceAttack()
                    {
                        return IsMelee ? min_distance_attack_melee : min_distance_attack_weapon;
                    }
                    public readonly float MaxDistanceAttack()
                    {
                        return IsMelee ? max_distance_attack_melee : max_distance_attack_weapon;
                    }
                    public bool HasModeDown()
                    {
                        return IsValid() && !IsMelee;
                    }
                    public void Reload()
                    {
                        if(!IsValid()) return;
                        if(Weapon is BaseProjectile weapon)
                        {
                            if(Owner.modelState.aiming)
                            {
                                Owner.modelState.aiming = false;
                                Owner.SendNetworkUpdateImmediate();
                            }
                            if (Owner.ConfigNPC.CanUseAmmoInventory())
                            {
                                if (!weapon.ServerTryReload(Owner.inventory))
                                {
                                    Owner.SignalBroadcast(BaseEntity.Signal.DryFire);
                                    weapon.SignalBroadcast(BaseEntity.Signal.DryFire);
                                    Owner.SendNetworkUpdateImmediate();
                                    weapon.SendNetworkUpdateImmediate();
                                    return;
                                }
                            }
                            else
                            {
                                Weapon.ServerReload();
                            }
                            if (Weapon is CompoundBowWeapon compoundBow) compoundBow.stringHoldTimeStart = UnityEngine.Time.time;
                            reloadTimer = 0;

                            Weapon.UpdateShieldState(true);
                            if(weapon.sendReloadSignalFromServer)
                            {
                                Owner.SignalBroadcast(Weapon is BowWeapon ? BaseEntity.Signal.Attack : BaseEntity.Signal.Reload);
                                Owner.SendNetworkUpdateImmediate();
                            }
                            else
                            {
                                Weapon.SignalBroadcast(Weapon is BowWeapon ? BaseEntity.Signal.Attack : BaseEntity.Signal.Reload);
                                Weapon.SendNetworkUpdateImmediate();
                            }
                        }

                    }
                    private readonly float GetTimerReload() => Weapon switch
                    {
                        Speargun => 3f,
                        CrossbowWeapon => 6f,
                        MiniCrossbow => 10,
                        CompoundBowWeapon => 4,
                        BowWeapon => 2,
                        BaseProjectile weapon => weapon.reloadTime,
                        _ => 10f,
                    };
                    public bool HasAttackCooldown()
                    {
                        return !IsValid() || Weapon.HasAttackCooldown();
                    }

                    public float AiMeleeStrikeDelay()
                    {
                        return Weapon switch
                        {
                            BaseMelee melee => AiMeleeStrikeDelay(melee),
                            _ => 0
                        };
                    }
                    private float AiMeleeStrikeDelay(BaseMelee melee)
                    {
                        return melee.ShortPrefabName switch
                        {
                            "salvaged_cleaver.entity" => 0.5f,
                            _ => melee.aiStrikeDelay,
                        };
                    }

                    public static implicit operator WeaponInfo(AttackEntity weapon)
                    {
                        return new(weapon);
                    }
                    public static implicit operator bool(WeaponInfo info)
                    {
                        return info.IsValid();
                    }
                }
                public struct EnemyInfo
                {
                    #region Fields And Properties
                    private readonly int layerVisibleEnemy;
                    private IAttackState.PersonalityBot _personalityAttackMode;

                    public BaseCombatEntity Enemy { get; private set; }
                    public IAttackState.PersonalityBot PersonalityAttackMode => _personalityAttackMode;
                    public IAttackState.TypeEnemy TypeEnemy => GetTypeEnemy();
                    public Vector3 Position => IsValid() ? Enemy.transform.position : Vector3.zero;
                    public Vector3 CenterPoint => IsValid() ? Enemy.CenterPoint() : Vector3.zero;
                    public Vector3 HeadPoint => !IsValid() ? Vector3.zero
                        : Enemy is BasePlayer player && player.eyes != null ? player.eyes.position : Enemy.CenterPoint();
                    #endregion

                    public EnemyInfo(BaseCombatEntity enemy, bool isNoise, bool isVisible, int layerVisibleEnemy = -1, IAttackState.PersonalityBot personality = default)
                    {
                        if(GetTypeEnemy(enemy) != IAttackState.TypeEnemy.Unknown)
                        {
                            Enemy = enemy;
                            this.layerVisibleEnemy = layerVisibleEnemy;
                            _personalityAttackMode = personality;
                        }
                        else
                        {
                            Enemy = null;
                            this.layerVisibleEnemy = -1;
                            _personalityAttackMode = IAttackState.PersonalityBot.Unknown;
                        }
                    }

                    public bool IsValid()
                    {
                        bool valid = Enemy.IsValid() && Enemy.IsAlive();
                        if(!valid && Enemy != null) Enemy = null;
                        return valid;
                    }
                    public float Distance(BaseCustomNpc owner)
                    {
                        if(!owner.IsValid() || !IsValid()) return float.MaxValue;
                        return Vector3.Distance(Enemy.transform.position, owner.transform.position);
                    }
                    public bool CanVisibleFrom(BaseCustomNpc owner) => CanVisibleFrom(owner, out _);
                    public bool CanVisibleFrom(BaseCustomNpc owner, out bool headOnly)
                    {
                        headOnly = false;
                        if(!owner.IsValid() || !IsValid()) return false;
                        if(Enemy is BasePlayer player) return owner.CanSeePlayerEnemy(player, layerVisibleEnemy, out headOnly);
                        return owner.CanSeeEnemy(Enemy, layerVisibleEnemy);
                    }
                    public bool IsTargetInFieldOfView(BaseCustomNpc owner)
                    {
                        return owner.IsValid() && IsValid() && owner.IsTargetInFieldOfView(Enemy);
                    }
                    private IAttackState.TypeEnemy GetTypeEnemy()
                    {
                        return GetTypeEnemy(Enemy);
                    }
                    public bool IsSafeZone()
                    {
                        return IsValid() && Enemy.IsSafeZone();
                    }
                    public static IAttackState.TypeEnemy GetTypeEnemy(BaseCombatEntity enemy)
                    {
                        if(!enemy.IsValid() || !enemy.IsAlive()) return IAttackState.TypeEnemy.Unknown;
                        return enemy switch
                        {
                            BaseAnimalNPC => IAttackState.TypeEnemy.Animal,
                            BaseNPC2 npc => npc.IsAnimal ? IAttackState.TypeEnemy.Animal : IAttackState.TypeEnemy.NPC,
                            NPCPlayer => IAttackState.TypeEnemy.NPC,
                            BasePlayer player => player.IsNpc ? IAttackState.TypeEnemy.NPC : IAttackState.TypeEnemy.Player,
                            AutoTurret => IAttackState.TypeEnemy.Turret,
                            BradleyAPC => IAttackState.TypeEnemy.Tank,
                            _ => IAttackState.TypeEnemy.Unknown,
                        };
                    }
                    public override bool Equals(object obj)
                    {
                        if (obj is EnemyInfo other)
                        {
                            return Enemy == other.Enemy;
                        }
                        return false;
                    }
                    public override int GetHashCode()
                    {
                        return HashCode.Combine(Enemy);
                    }

                    public static implicit operator EnemyInfo(BaseCombatEntity enemy)
                    {
                        return new(enemy, false, false);
                    }

                    public static implicit operator bool(EnemyInfo info)
                    {
                        return info.IsValid();
                    }

                    public static bool operator ==(EnemyInfo left, EnemyInfo right)
                    {
                        return left.Equals(right);
                    }

                    public static bool operator !=(EnemyInfo left, EnemyInfo right)
                    {
                        return !left.Equals(right);
                    }
                }

            }
            #endregion

            #region FSM Core - IRouterState, RouterState, IStatePlayerNpc, BaseStatePlayerNpc, ListTransfer, TransferState
            public interface IRouterState
            {
                bool IsStuck { get; }
                void OnStuck();
                bool IsObstacleBlocking(BaseEntity obstacle);
                void ResetStuck();
                bool CanSwimAhead(Vector3 entryPoint, float depth, float distance);
                bool PrefersSwimShortcut { get; }

                bool CanPassHazardTrigger(Vector3 hazardCenter);

                public enum ModeRouter
                {
                    Idle, FindRoute, Moved, Stuck, Finish, NotFinish
                }
            }
            public abstract class RouterState : BaseStatePlayerNpc, IRouterState
            {
                #region Fields And Properties
                protected IRouterState.ModeRouter modeRouter;
                private bool isStuck;
                private NavigationSpeed _speed;
                private Vector3 _destination;
                private int _warpsSeen;
                private int? _pendingWarpAtTickStart;
                private bool _warpWaitedFullTick;

                public bool IsStuck => isStuck;
                protected abstract BaseEntity GetChaseEnemy { get; }
                protected abstract float MinDistanceMovedEnemyForAddPoint { get; }
                protected virtual float RadiusSphere => 1.5f;
                protected virtual bool RequireTargetLos => false;
                private const float RouterArrivalMin = 1f;
                private const float NavArrivalMin = 0.5f;
                protected float RouterArrival => Mathf.Max(RouterArrivalMin, RadiusSphere);
                public override bool YieldsToTurretEscape => HasTickTransfers;
                #endregion

                protected override void Start()
                {
                    _speed = Owner.speedNavigatorNormal;
                }
                protected override void OnDestroy()
                {
                    isStuck = false;
                    _destination = Vector3.zero;
                    if (ParentFSM?.GetCurrentState() == this) Stop();
                    else modeRouter = IRouterState.ModeRouter.Idle;
                }

                protected override void EnterState()
                {
                    isStuck = false;
                }
                protected override void LeaveState()
                {
                    isStuck = false;
                    Stop();
                }

                protected override ResponseFromUpdateState UpdateState(float delta)
                {
                    if (!IsStuck)
                        UpdateRouter();
                    else if (Navigator.Moving) Navigator.Stop();
                    return ResponseFromUpdateState.NONE;
                }

                protected override void BeforeStateTick()
                {
                    int? pendingWarp = modeRouter == IRouterState.ModeRouter.Moved && Navigator != null &&
                        Navigator.WarpCount != _warpsSeen ? Navigator.WarpCount : (int?)null;
                    _warpWaitedFullTick = pendingWarp.HasValue && pendingWarp == _pendingWarpAtTickStart;
                    _pendingWarpAtTickStart = pendingWarp;
                }

                protected override void AfterStateTick()
                {
                    if (!_pendingWarpAtTickStart.HasValue || Navigator == null ||
                        modeRouter != IRouterState.ModeRouter.Moved || Navigator.WarpCount == _warpsSeen ||
                        Navigator.WarpCount != _pendingWarpAtTickStart.Value)
                    {
                        _pendingWarpAtTickStart = null;
                        _warpWaitedFullTick = false;
                        return;
                    }
                    if (_warpWaitedFullTick)
                    {
                        HandleRouterWarp("after state tick");
                        _pendingWarpAtTickStart = null;
                        _warpWaitedFullTick = false;
                    }
                }

                private void HandleRouterWarp(string source)
                {
                    if (modeRouter != IRouterState.ModeRouter.Moved || Navigator == null || Navigator.WarpCount == _warpsSeen) return;
                    _warpsSeen = Navigator.WarpCount;
                    if (Navigator.Moving)
                    {
                        return;
                    }
                    MoveTo(_destination);
                }

                private void UpdateChaseEnemy()
                {
                    var enemy = GetChaseEnemy;
                    float dist = MinDistanceMovedEnemyForAddPoint;
                    if (enemy.IsValid() && dist > 0 && _destination != Vector3.zero &&
                        Vector3.Distance(_destination, enemy.transform.position) > dist)
                    {
                        SetTarget(enemy.transform.position, _speed);
                    }
                }

                private void UpdateRouter()
                {
                    switch (modeRouter)
                    {
                        case IRouterState.ModeRouter.Moved:
                            UpdateChaseEnemy();
                            if (ReachedPosition(_destination))
                            {
                                FinishCallback();
                                return;
                            }
                            if (Navigator != null && Navigator.ReachedPosition(_destination))
                            {
                                ((IRouterState)this).OnStuck();
                                return;
                            }
                            HandleRouterWarp("router tick");
                            return;

                        default: return;
                    }
                }

                public void SetTarget(Vector3 position, NavigationSpeed? speed = null)
                {
                    _destination = position;
                    _speed = speed ?? Owner.speedNavigatorNormal;
                    IRouterState.ModeRouter before = modeRouter;
                    if (ReachedPosition(_destination))
                    {
                        FinishCallback();
                        return;
                    }
                    MoveTo(_destination);
                }

                public void Stop()
                {
                    Navigator?.Stop();
                    modeRouter = IRouterState.ModeRouter.Idle;
                }

                private void MoveTo(Vector3 position)
                {
                    if (RefuseSafeZoneTarget(position)) return;
                    float navArrival = Mathf.Max(NavArrivalMin, RouterArrival - NavigatorNpc.FinishSnapRadius);
                    bool move = Navigator.SetDestination(position, _speed, navArrival, RequireTargetLos);
                    _warpsSeen = Navigator.WarpCount;
                    modeRouter = move ? IRouterState.ModeRouter.Moved : IRouterState.ModeRouter.Idle;
                }

                private bool RefuseSafeZoneTarget(Vector3 position)
                {
                    if (!Owner.IsValid() || !Owner.AvoidSafeZonesNow) return false;
                    if (!HelperSafeZones.IsTargetBlocked(Owner.transform.position, position)) return false;
                    StuckReasonLatched = StuckReason.SafeZone;
                    Navigator?.Stop();
                    isStuck = true;
                    modeRouter = IRouterState.ModeRouter.Stuck;
                    return true;
                }

                private void FinishCallback()
                {
                    Navigator?.Stop();
                    modeRouter = IRouterState.ModeRouter.Finish;
                }

                void IRouterState.OnStuck()
                {
                    StuckReasonLatched = Navigator != null ? Navigator.LastStuckReason : StuckReason.None;
                    Navigator?.Stop();
                    isStuck = true;
                    modeRouter = IRouterState.ModeRouter.Stuck;
                }

                public virtual bool IsObstacleBlocking(BaseEntity obstacle)
                {
                    if (Owner != null && Owner.PassesBuilding(obstacle)) return false;
                    BuildingPrivlidge tc = obstacle is DecayEntity de && de.buildingID != 0
                        ? BuildingManager.server.GetBuilding(de.buildingID)?.GetDominatingBuildingPrivilege()
                        : null;
                    if (tc == null) return false;
                    ulong botId = Owner.IsValid() ? Owner.userID : 0UL;
                    return botId != 0UL && !tc.IsAuthed(botId);
                }

                public bool ReachedPosition(Vector3 position)
                {
                    if (Navigator == null || !Navigator.ReachedPosition(position)) return false;
                    return (Owner.transform.position - position).sqrMagnitude <= RouterArrival * RouterArrival;
                }

                public void ResetStuck()
                {
                    isStuck = false;
                    StuckReasonLatched = StuckReason.None;
                }

                protected StuckReason StuckReasonLatched { get; private set; }

                protected const float MaxTargetWaterDepth = 1.2f;
                protected static bool IsPointTooDeep(Vector3 point, float maxDepth = MaxTargetWaterDepth)
                {
                    var water = WaterLevel.GetWaterInfo(point, waves: false, volumes: false);
                    return water.isValid && water.surfaceLevel - point.y > maxDepth;
                }

                public virtual bool CanPassHazardTrigger(Vector3 hazardCenter) => true;

                public virtual bool CanSwimAhead(Vector3 entryPoint, float depth, float distance) => true;

                public virtual bool PrefersSwimShortcut => false;


            }

            public interface IStatePlayerNpc
            {
                bool IsValid { get; }
                string Name { get; }
                bool HasTask { get; }
                bool WantsCrouch { get; }
                float TimerState { get; }
                void EnterState();
                void LeaveState();
                void TickState(float delta);
                void AddCompletedTransfer(TransferState transfer);
                void AddFailureTransfer(TransferState transfer);
                void AddTickTransfer(TransferState transfer);
                void AddCompletedTransfer(IStatePlayerNpc state, Func<bool> evaluate);
                void AddFailureTransfer(IStatePlayerNpc state, Func<bool> evaluate);
                void AddTickTransfer(IStatePlayerNpc state, Func<bool> evaluate);
                void RemoveTickTransfer(IStatePlayerNpc target);
                void RemoveCompletedTransfer(IStatePlayerNpc target);
                void RemoveFailureTransfer(IStatePlayerNpc target);
            }
            public abstract class BaseStatePlayerNpc : IStatePlayerNpc, Pool.IPooled
            {
                #region Fields And Properties
                private BaseCustomNpc _owner;
                private BaseBrainCustomNpc _brain;
                private INavigator _navigator;
                private ListTransfer completedTransfers;
                private ListTransfer failureTransfers;
                private ListTransfer tickTransfers;
                private Debug.TimeSince timerState;
                private bool isPool;
                protected Debug.TimeSince phraseTime;

                public IFSM ParentFSM { get; private set; }
                public bool WantsCrouch { get; set; }
                public float TimerState => timerState.TotalSeconds;
                protected virtual float MinStateDwell => 0f;
                public BaseCustomNpc Owner => _owner ??= ParentFSM.IsValid() ? ParentFSM.Owner : null;
                public BaseBrainCustomNpc Brain => _brain ??= Owner.IsValid() ? Owner.GetComponent<BaseBrainCustomNpc>() : null;
                public INavigator Navigator => _navigator ??= Owner.IsValid() ? Owner.GetComponent<INavigator>() : null;
                public abstract string Name { get; }
                public virtual bool IsValid => !isPool && Owner.IsValid() && Brain != null && Navigator != null;
                public bool HasTask => CanEnterState();
                public virtual bool YieldsToTurretEscape => false;
                protected bool HasTickTransfers => tickTransfers != null && tickTransfers.Count > 0;
                #endregion

                #region Override Methods
                public static T GetPoolState<T>(IFSM parentFSM) where T : BaseStatePlayerNpc, new()
                {
                    return Pool.Get<T>().InitState(parentFSM) as T;
                }
                public static void SetPoolState<T>(ref T obj) where T : BaseStatePlayerNpc, new()
                {
                    if(obj) Pool.Free(ref obj);
                    obj = null;
                }
                private IStatePlayerNpc InitState(IFSM parentFSM)
                {
                    ParentFSM = parentFSM;

                    try
                    {
                        Start();
                    }
                    catch (Exception ex)
                    {
                        Debug.LogError<BaseStatePlayerNpc>("InitState[{0}]: {1}", GetType().Name, ex);
                    }

                    return this;
                }
                void Pool.IPooled.EnterPool()
                {
                    try
                    {
                        OnDestroy();
                    }
                    catch (Exception ex)
                    {
                        Debug.LogError<BaseStatePlayerNpc>("EnterPool[{0}]: {1}", GetType().Name, ex);
                    }
                    finally
                    {
                        isPool = true;
                        _owner = null;
                        _brain = null;
                        _navigator = null;
                        ParentFSM = null;
                        tickTransfers?.Clear();
                        completedTransfers?.Clear();
                        failureTransfers?.Clear();
                        phraseTime = 0;
                    }

                }
                void Pool.IPooled.LeavePool()
                {
                    isPool = false;
                    tickTransfers ??= Pool.Get<ListTransfer>();
                    completedTransfers ??= Pool.Get<ListTransfer>();
                    failureTransfers ??= Pool.Get<ListTransfer>();
                }
                #endregion

                #region Methods
                void IStatePlayerNpc.TickState(float delta)
                {
                    if (Navigator == null || !Brain) return;
                    ResponseFromUpdateState mode;
                    try
                    {
                        BeforeStateTick();
                        mode = UpdateState(delta);
                    }
                    catch (Exception ex)
                    {
                        Debug.LogError<BaseStatePlayerNpc>("TickState[{0}]: {1}", GetType().Name, ex);
                        mode = ResponseFromUpdateState.Failure;
                    }

                    switch (mode)
                    {
                        case ResponseFromUpdateState.Completed: if(!TransfersState(completedTransfers, "task completed")) goto default;
                                                        else break;
                        case ResponseFromUpdateState.Failure: if(!TransfersState(failureTransfers, "state failed")) goto default;
                                                        else break;
                        default:
                            if (MinStateDwell > 0f && timerState.TotalSeconds < MinStateDwell) break;
                            TransfersState(tickTransfers, "intercepted by another state"); break;
                    }
                    if (ParentFSM?.GetCurrentState() == this)
                    {
                        try
                        {
                            AfterStateTick();
                        }
                        catch (Exception ex)
                        {
                            Debug.LogError<BaseStatePlayerNpc>("AfterStateTick[{0}]: {1}", GetType().Name, ex);
                        }
                    }
                }
                public void AddTickTransfer(TransferState transfer)
                {
                    if(transfer != null && transfer.transferState != null) tickTransfers.Add(transfer);
                }
                public void AddCompletedTransfer(TransferState transfer)
                {
                    if(transfer != null && transfer.transferState != null) completedTransfers.Add(transfer);
                }
                public void AddFailureTransfer(TransferState transfer)
                {
                    if(transfer != null && transfer.transferState != null) failureTransfers.Add(transfer);
                }
                public void RemoveTickTransfer(IStatePlayerNpc target) => RemoveFromList(tickTransfers, target);
                public void RemoveCompletedTransfer(IStatePlayerNpc target) => RemoveFromList(completedTransfers, target);
                public void RemoveFailureTransfer(IStatePlayerNpc target) => RemoveFromList(failureTransfers, target);

                private static void RemoveFromList(ListTransfer list, IStatePlayerNpc target)
                {
                    if (list == null || target == null) return;
                    for (int i = list.Count - 1; i >= 0; i--)
                    {
                        if (list[i]?.transferState == target)
                        {
                            list[i].Reset();
                            list.RemoveAt(i);
                        }
                    }
                }
                void IStatePlayerNpc.EnterState()
                {
                    WantsCrouch = false;
                    try
                    {
                        EnterState();
                    }
                    catch (Exception ex)
                    {
                        Debug.LogError<BaseStatePlayerNpc>("EnterState[{0}]: {1}", GetType().Name, ex);
                    }
                    finally
                    {
                        timerState = 0;
                    }
                }
                void IStatePlayerNpc.LeaveState()
                {
                    try
                    {
                        LeaveState();
                    }
                    catch (Exception ex)
                    {
                        Debug.LogError<BaseStatePlayerNpc>("LeaveState[{0}]: {1}", GetType().Name, ex);
                    }
                }
                private bool TransfersState(ListTransfer transfers, string kind)
                {
                    if(transfers == null) return false;
                    foreach(var item in transfers)
                    {
                        if(item.Evaluate() && ParentFSM.IsValid())
                        {
                            ParentFSM.ActivateState(item.transferState);
                            return true;
                        }
                    }
                    return false;
                }
                protected abstract void Start();
                protected abstract void OnDestroy();
                protected abstract void EnterState();
                protected abstract void LeaveState();
                protected abstract bool CanEnterState();
                protected virtual void BeforeStateTick() { }
                protected virtual void AfterStateTick() { }
                protected abstract ResponseFromUpdateState UpdateState(float delta);
                public void AddCompletedTransfer(IStatePlayerNpc state, Func<bool> evaluate)
                {
                    AddCompletedTransfer(new TransferState(state, evaluate));
                }
                public void AddFailureTransfer(IStatePlayerNpc state, Func<bool> evaluate)
                {
                    AddFailureTransfer(new TransferState(state, evaluate));
                }
                public void AddTickTransfer(IStatePlayerNpc state, Func<bool> evaluate)
                {
                    AddTickTransfer(new TransferState(state, evaluate));
                }
                protected void TrySayPhrase(string phrase, float cooldown = 30f)
                {
                    if (string.IsNullOrEmpty(phrase)) return;
                    if (phraseTime.TotalSeconds < cooldown) return;
                    phraseTime = 0;
                    OnSayPhrase(phrase);
                }
                protected virtual void OnSayPhrase(string phrase) { }

                public virtual object CanUseDoor(Door door, BaseLock lockEntity, CardReader reader)
                {
                    if (Owner != null && Owner.PassesDoor(door, lockEntity, reader)) return true;
                    if (reader != null) return null;
                    if (lockEntity != null && lockEntity.IsLocked()) return null;
                    return door.canNpcOpen ? (object)true : null;
                }

                public virtual object OpenDoor(Door door, BaseLock lockEntity, CardReader reader)
                {
                    bool passes = Owner != null && Owner.PassesDoor(door, lockEntity, reader);
                    if (reader != null && !passes) return null;
                    if (lockEntity != null && lockEntity.IsLocked() && !passes) return null;
                    if (!door.IsOpen())
                    {
                        door.SetOpen(true);
                        if (door.GetComponentInChildren<TriggerLadder>(true) != null)
                            BuildingNavigation.NoteBlockChange(door.buildingID);
                    }
                    return true;
                }
                #endregion

                public static implicit operator bool(BaseStatePlayerNpc state)
                {
                    return state != null && state.IsValid;
                }

                public enum ResponseFromUpdateState
                {
                    NONE, Completed, Failure, Success
                }
            }

            public class ListTransfer : List<TransferState>
            {
                public new void Clear()
                {
                    foreach(var item in this) item?.Reset();
                    base.Clear();
                }
            }
            public class TransferState
            {
                public IStatePlayerNpc transferState { get; private set; }
                public Func<bool> evaluate { get; private set; }
                public TransferState(IStatePlayerNpc transferState, Func<bool> evaluate)
                {
                    this.transferState = transferState;
                    this.evaluate = evaluate;
                }

                public virtual bool Evaluate()
                {
                    if(!transferState.IsValid()) return false;
                    if(evaluate == null) return transferState.HasTask;
                    else return evaluate.Invoke();
                }

                public virtual void Reset()
                {
                    transferState = null;
                    evaluate = null;
                }

                public static implicit operator TransferState(BaseStatePlayerNpc transferState)
                {
                    return new(transferState, null);
                }
            }
            #endregion
        }

        #region Behavior States - выделены из FSM-ядра

        public sealed class TargetSearchCache
        {
            private readonly float _interval;
            private readonly Func<BaseCombatEntity> _search;
            private BaseCombatEntity _target;
            private float _nextSearchTime;

            public TargetSearchCache(float interval, Func<BaseCombatEntity> search)
            {
                _interval = interval;
                _search = search;
            }

            public BaseCombatEntity GetOrSearch()
            {
                if (UnityEngine.Time.time < _nextSearchTime && (_target == null || _target.IsValid()))
                    return _target;
                _nextSearchTime = UnityEngine.Time.time + _interval;
                return _target = _search();
            }

            public void Reset()
            {
                _target = null;
                _nextSearchTime = 0f;
            }
        }

        public abstract class BattleFsmState : FSM.AttackState, FSM.IRouterState, FSM.IAttackState
        {
            #region Fields And Properties
            private readonly Dictionary<BaseEntity, float> _abandonedTargets = new();
            protected virtual float AbandonBanDuration => 0f;
            protected IFSM _combatFSM;
            protected TimeSince _aggressorTimer;
            protected TimeSince _lastHitTimer = 999f;
            protected TimeSince _forgetTimer = 999f;
            protected TimeSince _hpProgressTimer = 999f;
            protected TimeSince _noAttackTimer;
            protected float _bestEnemyDistance = float.MaxValue;
            protected float _lastTargetHealth;
            private int _harmlessHits;
            private const int HarmlessHitsToAbandon = 10;
            protected TimeSince _hearingTickTimer;
            protected float _nextWeaponSearchTime;
            protected const float WeaponSearchInterval = 1f;
            private bool _wasSwimming;
            private Vector3 _lastVisiblePos;
            private Vector3 _lastNoisePos;
            private Vector3 _lastNoiseInitiatorPos;
            private bool _hasLastVisible;
            private bool _hasLastNoise;
            private bool _visibleCalculated;
            private bool _visibleCachedValue;
            private bool _lineOfSightCalculated;
            private bool _lineOfSightCachedValue;
            private bool _lineOfSightHeadOnly;
            private bool _enemySafeZoneCalculated;
            private bool _enemySafeZoneCachedValue;
            private bool _lastVisibleReached;

            public const float CoverTriggerWindow = 2f;
            public const float CoverHoldWindow = 6f;
            public const float CoverExposedGrace = 1f;
            public const float CoverDuckDuration = 1.5f;
            public const float CoverPeekDuration = 1f;
            public virtual float MaxChaseDistance => 200f;
            public virtual float AggressorTimeout => 60f;
            public virtual float ForgetTimeout => 20f;
            public virtual float EngagementHpTimeout => 15f;
            public virtual float NoAttackTimeout => 25f;
            public const float NoAttackApproachEpsilon = 2f;
            public virtual float HearingRange => 40f;
            public const float HearingTickInterval = 0.5f;
            public const float SensorMaxAge = 5f;
            public virtual Rust.Ai.Gen2.NpcNoiseIntensity HearingIntensityThreshold => Rust.Ai.Gen2.NpcNoiseIntensity.Medium;
            public virtual bool UseSensors => true;
            public virtual bool UseCover => true;
            public virtual bool UseFlee => true;
            public virtual bool UseSearch => true;
            public virtual bool CoverPriorityAboveFlee => false;
            public virtual bool UseReposition => true;
            public const float RepositionIntervalMin = 2f;
            public const float RepositionIntervalMax = 4.5f;
            public const float RepositionDistanceMin = 4f;
            public const float RepositionDistanceMax = 8f;
            public const float RepositionVehicleRadius = 8f;
            public virtual bool WantsArmedCombat => true;
            public virtual bool CanEnterWithoutVisibility => false;
            public virtual bool CanHearOutsideBrainRadius => false;
            public virtual bool HearsMovementNoise => false;
            public virtual bool ReactsToAITargeting => false;
            public const float MovementNoiseSpeedThreshold = 3f;
            public const float MovementNoiseCloseRange = 8f;
            public const float MovementNoiseFarRange = 20f;
            public const float MovementNoiseCloseSpeedThreshold = 2f;
            public virtual float DuckChance => 0f;
            public const float DuckRollInterval = 0.75f;
            private float _nextDuckRollTime;

            public bool HasLastVisible => _hasLastVisible;
            public bool HasLastNoise => _hasLastNoise;
            public Vector3 LastVisiblePos => _lastVisiblePos;
            public Vector3 LastNoisePos => _lastNoisePos;
            public Vector3 LastNoiseInitiatorPos => _lastNoiseInitiatorPos;
            public float TimeSinceLastHit => (float)_lastHitTimer;
            public bool IsUnderFire => (float)_lastHitTimer < CoverTriggerWindow;
            public const float TouchRange = 2.5f;
            public const float FreshContactWindow = 1f;
            private BaseCombatEntity _freshContactEnemy;
            private float _freshContactTime;
            public bool IsInFreshContact => CurrentEnemy.IsValid() && _freshContactEnemy == CurrentEnemy.Enemy
                && UnityEngine.Time.time - _freshContactTime < FreshContactWindow;
            public string CombatStateName => string.IsNullOrEmpty(_combatFSM?.CurrentStateName) ? "-" : _combatFSM.CurrentStateName;

            protected override bool canAimDirection => true;
            protected override bool CanAimingWeaponFire => true;
            protected override float GetDamageScaleToEnemy() => 1f;
            #endregion

            #region IRouterState - делегация активному подсостоянию CombatFSM
            bool FSM.IRouterState.IsStuck => (_combatFSM?.GetCurrentState() as FSM.IRouterState)?.IsStuck ?? false;
            void FSM.IRouterState.OnStuck() => (_combatFSM?.GetCurrentState() as FSM.IRouterState)?.OnStuck();
            bool FSM.IRouterState.CanSwimAhead(Vector3 entryPoint, float depth, float distance)
                => (_combatFSM?.GetCurrentState() as FSM.IRouterState)?.CanSwimAhead(entryPoint, depth, distance) ?? true;
            bool FSM.IRouterState.PrefersSwimShortcut => (_combatFSM?.GetCurrentState() as FSM.IRouterState)?.PrefersSwimShortcut ?? false;
            void FSM.IRouterState.ResetStuck() => (_combatFSM?.GetCurrentState() as FSM.IRouterState)?.ResetStuck();
            bool FSM.IRouterState.IsObstacleBlocking(BaseEntity obstacle) => (_combatFSM?.GetCurrentState() as FSM.IRouterState)?.IsObstacleBlocking(obstacle) ?? false;
            bool FSM.IRouterState.CanPassHazardTrigger(Vector3 hazardCenter) => (_combatFSM?.GetCurrentState() as FSM.IRouterState)?.CanPassHazardTrigger(hazardCenter) ?? true;
            #endregion

            protected override void Start()
            {
                _combatFSM = FSM.GetPoolFSM<CombatFSM>(Owner);
                ((CombatFSM)_combatFSM).ParentBattle = this;
            }
            protected override void OnDestroy()
            {
                _abandonedTargets.Clear();
                FSM.SetPoolFSM<CombatFSM>(ref _combatFSM);
                ResetSensors();
                _lastHitTimer = 999f;
                _unreachableEnemyId = 0;
                _unreachableUntil = 0f;
                ResetVisibilityCache();
                base.OnDestroy();
            }
            protected override void EnterState()
            {
                base.EnterState();
                (_combatFSM as CombatFSM)?.OnBattleEnter();
                _aggressorTimer = 0;
                _forgetTimer = 0;
                _hpProgressTimer = 0;
                _noAttackTimer = 0;
                _bestEnemyDistance = float.MaxValue;
                _lastTargetHealth = CurrentEnemy.Enemy.IsValid() ? CurrentEnemy.Enemy.Health() : 0f;
                _harmlessHits = 0;
                _wasSwimming = Owner.IsValid() && Owner.IsInWater;
                if (WantsArmedCombat) CurrentWeapon = Owner.EquipWeapon(GetWeaponSlot(), false);
                OnEnterBattle();
            }
            protected override void LeaveState()
            {
                _combatFSM?.SetIdleState();
                Navigator?.ClearFacingDirectionOverride();
                if (CurrentWeapon) Owner.EquipWeapon(-1);
                if (Owner.IsValid())
                {
                    WantsCrouch = false;
                    Owner.SetAimDirection(Owner.eyes.BodyForward());
                }
                ResetSensors();
                OnLeaveBattle();
                base.LeaveState();
            }
            protected override bool CanEnterState()
            {
                if (!Owner.IsValid() || Owner.IsSafeZone()) return false;
                if (CurrentEnemy.IsValid()) return true;
                BaseCombatEntity enemy = FindBattleEnemy();
                if (enemy == null && UseSensors)
                {
                    if (CanHearOutsideBrainRadius) enemy = FindEnemyByNoise();
                    if (enemy == null && HearsMovementNoise) enemy = FindMovingEnemy();
                    if (enemy == null && ReactsToAITargeting) enemy = FindAITargetingMe();
                }
                if (enemy == null) return false;
                bool visible = true;
                if (UseSensors)
                {
                    visible = CanPerceive(enemy);
                    if (!visible)
                    {
                        if (!CanEnterWithoutVisibility) return false;
                        if (!TryCaptureNoiseFrom(enemy) && !TryCaptureMovementNoise(enemy)) return false;
                    }
                }
                CurrentEnemy = new EnemyInfo(enemy, false, visible, OverrideLayerVisibleEnemy, FSM.IAttackState.PersonalityBot.Aggressive);
                ResetVisibilityCache();
                return CurrentEnemy;
            }
            protected override FSM.BaseStatePlayerNpc.ResponseFromUpdateState UpdateState(float delta)
            {
                ResetVisibilityCache();
                if (Owner.IsSafeZone()) return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                if (!CurrentEnemy.IsValid()) { CurrentEnemy = default; return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed; }
                if (IsEnemyInSafeZoneNow())
                {
                    OnAbandonEnemy(CurrentEnemy.Enemy, AbandonReason.SafeZone);
                    CurrentEnemy = default;
                    return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                }
                if (Owner.IsExposedToMonumentTurret)
                {
                    OnAbandonEnemy(CurrentEnemy.Enemy, AbandonReason.SafeZone);
                    CurrentEnemy = default;
                    return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                }
                if (IsTargetInTurretRange(CurrentEnemy.Enemy) && (Brain == null || !Brain.IsAggressiveFrom(CurrentEnemy.Enemy)))
                {
                    OnAbandonEnemy(CurrentEnemy.Enemy, AbandonReason.SafeZone);
                    CurrentEnemy = default;
                    return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                }
                if (CurrentEnemy.Distance(Owner) > MaxChaseDistance) { OnAbandonEnemy(CurrentEnemy.Enemy, AbandonReason.TooFar); CurrentEnemy = default; return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed; }
                if ((float)_aggressorTimer > AggressorTimeout) { OnAbandonEnemy(CurrentEnemy.Enemy, AbandonReason.Aggressor); CurrentEnemy = default; return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed; }
                if ((float)_forgetTimer > ForgetTimeout) { OnAbandonEnemy(CurrentEnemy.Enemy, AbandonReason.Forget); CurrentEnemy = default; return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed; }
                if (WantsArmedCombat && NoAttackTimeout > 0)
                {
                    float distToEnemy = CurrentEnemy.Distance(Owner);
                    if (distToEnemy < _bestEnemyDistance - NoAttackApproachEpsilon)
                    {
                        _bestEnemyDistance = distToEnemy;
                        _noAttackTimer = 0;
                    }
                    bool closingOnHidden = EngagementHpTimeout > 0
                        && _combatFSM?.GetCurrentState() is CombatFSM.ChaseEnemyState chase && chase.IsClosingInOnHiddenTarget;
                    if (_combatFSM?.GetCurrentState() is CombatFSM.SearchEnemyState || Owner.IsInWater || closingOnHidden) _noAttackTimer = 0;
                    else if ((float)_noAttackTimer > NoAttackTimeout)
                    {
                        OnAbandonEnemy(CurrentEnemy.Enemy, AbandonReason.NoAttack);
                        CurrentEnemy = default;
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                }
                if (_harmlessHits >= HarmlessHitsToAbandon)
                {
                    OnAbandonEnemy(CurrentEnemy.Enemy, AbandonReason.NoHpProgress);
                    CurrentEnemy = default;
                    return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                }
                if (EngagementHpTimeout > 0 && CurrentEnemy.Enemy.IsValid())
                {
                    float curHp = CurrentEnemy.Enemy.Health();
                    if (curHp < _lastTargetHealth - 0.1f)
                    {
                        _lastTargetHealth = curHp;
                        _hpProgressTimer = 0;
                    }
                    else if (!WantsArmedCombat
                             || _combatFSM?.GetCurrentState() is CombatFSM.SearchEnemyState or CombatFSM.FleeState)
                    {
                        _hpProgressTimer = 0;
                    }
                    else if ((float)_hpProgressTimer > EngagementHpTimeout)
                    {
                        OnAbandonEnemy(CurrentEnemy.Enemy, AbandonReason.NoHpProgress);
                        CurrentEnemy = default;
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                }
                bool swimmingNow = Owner.IsValid() && Owner.IsInWater;
                bool waterStateChanged = swimmingNow != _wasSwimming;
                if (waterStateChanged)
                {
                    _wasSwimming = swimmingNow;
                    _nextWeaponSearchTime = 0f;
                }
                if (WantsArmedCombat && (waterStateChanged || !CurrentWeapon || !CurrentWeapon.HasAmmo)
                    && UnityEngine.Time.time >= _nextWeaponSearchTime)
                {
                    _nextWeaponSearchTime = UnityEngine.Time.time + WeaponSearchInterval;
                    int slot = GetWeaponSlot();
                    CurrentWeapon = Owner.EquipWeapon(slot, false);
                    if (!CurrentWeapon && swimmingNow) _nextWeaponSearchTime = UnityEngine.Time.time + WeaponSearchInterval * 10f;
                }
                if (UseSensors)
                {
                    UpdateVisibility();
                    UpdateHearing();
                }
                _combatFSM?.Update();
                UpdateThreatFacing();
                if (WantsArmedCombat) TryAttack();
                return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.NONE;
            }
            private void UpdateThreatFacing()
            {
                if (!Owner.IsValid() || !CurrentEnemy.IsValid() || Navigator == null) return;
                bool retreating = _combatFSM?.GetCurrentState() is CombatFSM.FleeState or CombatFSM.CoverState;
                if (retreating && (!WantsArmedCombat || AlwaysFlee || !CurrentWeapon))
                {
                    Navigator.ClearFacingDirectionOverride();
                    return;
                }
                bool freshContact = IsInFreshContact;
                if (Navigator.Moving && (!freshContact || retreating)) return;
                if (!UseSensors || freshContact || IsEnemyVisibleNow())
                {
                    Navigator.SetFacingDirectionEntity(CurrentEnemy.Enemy, CurrentWeapon && !CurrentWeapon.IsMelee && AimAtHead);
                    return;
                }
                Vector3 lookPos;
                if (_hasLastVisible) lookPos = _lastVisiblePos;
                else if (_hasLastNoise) lookPos = _lastNoiseInitiatorPos;
                else return;
                Vector3 dir = Vector3Ex.Direction2D(lookPos, Owner.transform.position);
                if (dir.sqrMagnitude > 0.001f) Navigator.SetFacingDirectionOverride(dir);
            }
            void FSM.IAttackState.OnAttack(BaseCombatEntity enemy)
            {
                _lastHitTimer = 0;
                if (!enemy.IsValid() || !enemy.IsAlive()) return;
                OnAttackedBy(enemy);
                if (!CanTargetBattleEnemy(enemy)) return;
                if (CurrentEnemy.IsValid() && _combatFSM != null && _combatFSM.GetCurrentState() is CombatFSM.FleeState)
                {
                    if (CurrentEnemy.Enemy == enemy)
                    {
                        _aggressorTimer = 0;
                        _forgetTimer = 0;
                        _noAttackTimer = 0;
                    }
                    MarkFreshContact(enemy);
                    return;
                }
                bool shouldSwitch = !CurrentEnemy || CurrentEnemy.Enemy == enemy || ShouldSwitchTarget(enemy);
                if (shouldSwitch)
                {
                    _aggressorTimer = 0;
                    _forgetTimer = 0;
                    _hpProgressTimer = 0;
                    _noAttackTimer = 0;
                    _bestEnemyDistance = float.MaxValue;
                    _lastTargetHealth = enemy.Health();
                    _harmlessHits = 0;
                    if (!CurrentEnemy) ResetSensors();
                    bool visible = CanPerceive(enemy);
                    CurrentEnemy = new EnemyInfo(enemy, true, visible, OverrideLayerVisibleEnemy, FSM.IAttackState.PersonalityBot.Aggressive);
                    ResetVisibilityCache();
                    Vector3 enemyPos = enemy.transform.position;
                    _lastVisiblePos = enemyPos;
                    _lastNoisePos = enemyPos;
                    _lastNoiseInitiatorPos = enemyPos;
                    _hasLastVisible = true;
                    _lastVisibleReached = false;
                    _hasLastNoise = true;
                }
                MarkFreshContact(enemy);
            }
            private void MarkFreshContact(BaseCombatEntity attacker)
            {
                if (!CurrentEnemy.IsValid() || CurrentEnemy.Enemy != attacker) return;
                _freshContactEnemy = attacker;
                _freshContactTime = UnityEngine.Time.time;
            }
            protected bool CanPerceive(BaseCombatEntity enemy)
            {
                if (!enemy.IsValid() || !Owner.IsValid()) return false;
                if (!Owner.IsTargetInFieldOfView(enemy) && !IsInTouchRange(enemy)) return false;
                return enemy is BasePlayer p ? Owner.CanSeePlayerEnemy(p, OverrideLayerVisibleEnemy) : Owner.CanSeeEnemy(enemy, OverrideLayerVisibleEnemy);
            }
            protected bool IsInTouchRange(BaseEntity entity)
            {
                if (!entity.IsValid() || !Owner.IsValid()) return false;
                return (entity.transform.position - Owner.transform.position).sqrMagnitude <= TouchRange * TouchRange;
            }
            public const float TargetSwitchDistanceRatio = 0.7f;
            protected const float SmallTargetSize = 0.7f;
            protected const float SmallTargetAttackDistance = 10f;
            protected const float NoWeaponChaseDistance = 2f;
            public virtual float GetMaxAttackDistance()
            {
                if (!CurrentWeapon) return NoWeaponChaseDistance;
                float maxDist = CurrentWeapon.MaxDistanceAttack();
                if (CurrentWeapon.IsMelee || !CurrentEnemy.IsValid()) return maxDist;
                Bounds b = CurrentEnemy.Enemy.bounds;
                float size = Mathf.Max(b.size.x, Mathf.Max(b.size.y, b.size.z));
                return size < SmallTargetSize ? Mathf.Min(maxDist, SmallTargetAttackDistance) : maxDist;
            }
            public virtual float GetPotentialFireDistance()
            {
                float current = GetMaxAttackDistance();
                if (CurrentWeapon && !CurrentWeapon.IsMelee) return current;
                ItemContainer belt = Owner.IsValid() ? Owner.inventory?.containerBelt : null;
                if (belt?.itemList == null) return current;
                float best = current;
                for (int i = 0; i < belt.itemList.Count; i++)
                {
                    Item item = belt.itemList[i];
                    if (item?.GetHeldEntity() is not AttackEntity weapon || weapon is BaseMelee) continue;
                    if (!Owner.HasAmmoForWeapon(weapon) && weapon is BaseProjectile bp && bp.AmmoFraction() <= 0f) continue;
                    if (!CanUseAsFirearm(item)) continue;
                    if (FSM.AttackState.WeaponInfo.DefaultRangedMaxDistance > best) best = FSM.AttackState.WeaponInfo.DefaultRangedMaxDistance;
                }
                return best;
            }
            protected virtual bool CanUseAsFirearm(Item item) => true;
            protected virtual bool ShouldSwitchTarget(BaseCombatEntity candidate)
            {
                if (!CurrentEnemy.IsValid()) return true;
                if (CurrentEnemy.Enemy == candidate) return false;
                if (!CurrentEnemy.Enemy.IsValid() || !CurrentEnemy.Enemy.IsAlive()) return true;
                float currentDist = CurrentEnemy.Distance(Owner);
                if (currentDist > MaxChaseDistance) return true;
                float candidateDist = candidate.Distance(Owner);
                return candidateDist < currentDist * TargetSwitchDistanceRatio;
            }

            public bool IsTargetInTurretRange(BaseEntity target) =>
                target.IsValid() && Owner.IsValid() && Owner.MonumentTurretsShootWhenHostile
                && HelperSafeZones.IsInTurretRange(target.transform.position);
            public virtual bool CanChaseEnemy()
            {
                if (!CurrentEnemy.IsValid()) return false;
                if (IsEnemyInSafeZoneNow()) return false;
                if (IsTargetInTurretRange(CurrentEnemy.Enemy)) return false;
                if (CurrentEnemy.Distance(Owner) >= MaxChaseDistance) return false;
                if (!WantsArmedCombat) return false;
                if (AlwaysFlee) return false;
                if (ShouldForceFlee()) return false;
                if (IsWoundedToFlee) return false;
                if (!Owner.IsInWater && IsEnemySwimming() && !HasWaterCapableWeapon()) return false;
                if (IsCurrentEnemyUnreachable) return false;
                if (!UseSensors) return true;
                return IsEnemyVisibleNow() || (_hasLastVisible && !_lastVisibleReached);
            }
            public void MarkLastVisibleReached() => _lastVisibleReached = true;
            public bool IsWoundedToFlee => UseFlee && Brain != null && Brain.PercentHeal() < CombatFSM.FleeState.FleeHealthPercent;
            public virtual bool CanSearchEnemy()
            {
                if (!UseSensors || !UseSearch) return false;
                if (!CurrentEnemy.IsValid()) return false;
                if (IsEnemyInSafeZoneNow()) return false;
                if (IsTargetInTurretRange(CurrentEnemy.Enemy)) return false;
                if (CurrentEnemy.Distance(Owner) >= MaxChaseDistance) return false;
                if ((float)_aggressorTimer > AggressorTimeout) return false;
                if (IsEnemyVisibleNow()) return false;
                if (ShouldForceFlee() || IsWoundedToFlee) return false;
                if (IsInFreshContact) return false;
                return _hasLastVisible || _hasLastNoise;
            }
            public virtual bool HasWaterCapableWeapon()
            {
                ItemContainer belt = Owner.IsValid() ? Owner.inventory?.containerBelt : null;
                if (belt == null) return false;
                for (int i = 0; i < belt.capacity; i++)
                {
                    if (belt.GetSlot(i)?.GetHeldEntity() is not AttackEntity attack) continue;
                    if (attack is BaseMelee || attack is Speargun) return true;
                }
                return false;
            }
            public bool IsEnemySwimming()
                => CurrentEnemy.IsValid() && CurrentEnemy.Enemy is BasePlayer enemyPlayer && enemyPlayer.IsSwimming();
            public virtual bool ShouldForceFlee() => false;
            public virtual bool AlwaysFlee => false;
            public virtual bool IsEnemyVisibleNow()
            {
                if (_visibleCalculated) return _visibleCachedValue;
                _visibleCalculated = true;
                _visibleCachedValue = CurrentEnemy.IsValid()
                    && (CurrentEnemy.IsTargetInFieldOfView(Owner) || IsInTouchRange(CurrentEnemy.Enemy))
                    && HasLineOfSightNow();
                return _visibleCachedValue;
            }
            public bool HasLineOfSightNow()
            {
                if (_lineOfSightCalculated) return _lineOfSightCachedValue;
                _lineOfSightCalculated = true;
                _lineOfSightHeadOnly = false;
                _lineOfSightCachedValue = CurrentEnemy.IsValid() && CurrentEnemy.CanVisibleFrom(Owner, out _lineOfSightHeadOnly);
                return _lineOfSightCachedValue;
            }
            protected override bool AimAtHead => HasLineOfSightNow() && _lineOfSightHeadOnly;
            protected const float BurstRangeSlack = 1f;
            protected override bool CanContinueFire()
            {
                float dist = CurrentEnemy.Distance(Owner);
                float maxDist = GetMaxAttackDistance() + BurstRangeSlack;
                if (dist > maxDist)
                {
                    return false;
                }
                if (!IsEnemyVisibleNow())
                {
                    return false;
                }
                return true;
            }
            private void ResetVisibilityCache()
            {
                _visibleCalculated = false;
                _lineOfSightCalculated = false;
                _enemySafeZoneCalculated = false;
            }
            public bool IsEnemyInSafeZoneNow()
            {
                if (_enemySafeZoneCalculated) return _enemySafeZoneCachedValue;
                _enemySafeZoneCalculated = true;
                _enemySafeZoneCachedValue = CurrentEnemy.IsSafeZone();
                return _enemySafeZoneCachedValue;
            }
            protected virtual void TryAttack()
            {
                if (_combatFSM?.GetCurrentState() is CombatFSM.CoverState cover && !cover.WantsFireNow) return;
                if (!CurrentEnemy || !CurrentWeapon || !CurrentWeapon.HasAmmo || IsCooldown) return;
                float distAttack = CurrentEnemy.Distance(Owner);
                if (distAttack < CurrentWeapon.MinDistanceAttack() || distAttack > GetMaxAttackDistance()
                    || !IsEnemyVisibleNow() || IsEnemyInSafeZoneNow())
                {
                    WantsCrouch = false;
                    return;
                }
                if (DuckChance > 0f && Owner.IsValid() && _combatFSM?.GetCurrentState() is not (CombatFSM.CoverState or CombatFSM.RepositionState)
                    && UnityEngine.Time.time >= _nextDuckRollTime)
                {
                    WantsCrouch = Random.value * 100f < DuckChance;
                    _nextDuckRollTime = UnityEngine.Time.time + Mathf.Max(0.05f, DuckRollInterval);
                }
                DownTrigger();
            }
            protected virtual void OnEnterBattle() { }
            protected virtual void OnLeaveBattle() { }
            public virtual void OnEnterSearch() { }
            protected enum AbandonReason
            {
                TooFar,
                Aggressor,
                Forget,
                NoHpProgress,
                NoAttack,
                SafeZone
            }
            protected virtual void OnAbandonEnemy(BaseCombatEntity enemy, AbandonReason reason)
            {
                if (AbandonBanDuration <= 0f) return;
                if (reason != AbandonReason.Forget && reason != AbandonReason.NoHpProgress && reason != AbandonReason.NoAttack) return;
                if (!enemy.IsValid() || !enemy.IsAlive()) return;
                PruneAbandoned();
                _abandonedTargets[enemy] = UnityEngine.Time.time + AbandonBanDuration;
            }
            private void PruneAbandoned()
            {
                if (_abandonedTargets.Count == 0) return;
                float now = UnityEngine.Time.time;
                List<BaseEntity> stale = null;
                foreach (var kv in _abandonedTargets)
                    if (now >= kv.Value || !kv.Key.IsValid()) (stale ??= new List<BaseEntity>()).Add(kv.Key);
                if (stale != null) for (int i = 0; i < stale.Count; i++) _abandonedTargets.Remove(stale[i]);
            }
            protected bool IsAbandonBlacklisted(BaseEntity entity)
            {
                if (entity == null || !_abandonedTargets.TryGetValue(entity, out float until)) return false;
                if (UnityEngine.Time.time >= until)
                {
                    _abandonedTargets.Remove(entity);
                    return false;
                }
                return true;
            }

            public void AbandonEnemyUnreachable(string why, bool notVisible = false)
            {
                if (!CurrentEnemy.IsValid()) return;
                _unreachableEnemyId = CurrentEnemy.Enemy.IsValid() ? CurrentEnemy.Enemy.net.ID.Value : 0;
                _unreachableUntil = UnityEngine.Time.time + UnreachableMemory;
                OnAbandonEnemy(CurrentEnemy.Enemy, AbandonReason.NoAttack);
                CurrentEnemy = default;
            }

            public void AbandonEnemyLost(string why)
            {
                if (!CurrentEnemy.IsValid()) return;
                OnAbandonEnemy(CurrentEnemy.Enemy, AbandonReason.Forget);
                CurrentEnemy = default;
            }

            private const float UnreachableMemory = 30f;
            private ulong _unreachableEnemyId;
            private float _unreachableUntil;

            public bool IsCurrentEnemyUnreachable =>
                CurrentEnemy.IsValid() && CurrentEnemy.Enemy.IsValid()
                && CurrentEnemy.Enemy.net.ID.Value == _unreachableEnemyId
                && UnityEngine.Time.time < _unreachableUntil;
            protected virtual void OnAttackedBy(BaseCombatEntity enemy)
            {
                if (enemy == null || !_abandonedTargets.Remove(enemy)) return;
                OnAbandonBanRemoved(enemy);
            }
            protected virtual void OnAbandonBanRemoved(BaseCombatEntity enemy) { }

            public abstract bool CanTargetBattleEnemy(BaseCombatEntity entity);
            public abstract BaseCombatEntity FindBattleEnemy();
            public abstract int GetWeaponSlot();

            private void ResetSensors()
            {
                _lastVisiblePos = Vector3.zero;
                _lastNoisePos = Vector3.zero;
                _lastNoiseInitiatorPos = Vector3.zero;
                _hasLastVisible = false;
                _lastVisibleReached = false;
                _hasLastNoise = false;
                _hearingTickTimer = 0;
                _freshContactEnemy = null;
                _freshContactTime = 0f;
            }
            protected override void OnAttackDelivered() => _noAttackTimer = 0;
            protected override void OnHitLanded(BaseCombatEntity target, bool hurt)
            {
                if (target == CurrentEnemy.Enemy) _harmlessHits = hurt ? 0 : _harmlessHits + 1;
            }
            private void UpdateVisibility()
            {
                if (!IsEnemyVisibleNow()) return;
                _lastVisiblePos = CurrentEnemy.Position;
                _hasLastVisible = true;
                _lastVisibleReached = false;
                _forgetTimer = 0;
            }
            private void UpdateHearing()
            {
                if ((float)_hearingTickTimer < HearingTickInterval) return;
                _hearingTickTimer = 0;
                if (!CurrentEnemy.IsValid()) return;
                bool gotNoise = TryCaptureNoiseFrom(CurrentEnemy.Enemy);
                if (!gotNoise) TryCaptureMovementNoise(CurrentEnemy.Enemy);
            }

            protected bool TryCaptureNoiseFrom(BaseCombatEntity enemy)
            {
                if (!enemy.IsValid()) return false;
                Rust.Ai.Gen2.NpcNoiseManager manager = SingletonComponent<Rust.Ai.Gen2.NpcNoiseManager>.Instance;
                if (manager == null) return false;
                List<Rust.Ai.Gen2.NpcNoiseEvent> list = Pool.Get<List<Rust.Ai.Gen2.NpcNoiseEvent>>();
                manager.GetNoisesAround(Owner.transform.position, HearingRange, list);
                bool hasBest = false;
                Rust.Ai.Gen2.NpcNoiseEvent best = default;
                double now = UnityEngine.Time.timeAsDouble;
                for (int i = 0; i < list.Count; i++)
                {
                    Rust.Ai.Gen2.NpcNoiseEvent ev = list[i];
                    if (ev.Initiator != enemy) continue;
                    if ((int)ev.Intensity < (int)HearingIntensityThreshold) continue;
                    if (now - ev.EventTime > SensorMaxAge) continue;
                    if (!hasBest || ev.EventTime > best.EventTime)
                    {
                        best = ev;
                        hasBest = true;
                    }
                }
                Pool.FreeUnmanaged(ref list);
                if (hasBest)
                {
                    _lastNoisePos = best.NoisePosition;
                    _lastNoiseInitiatorPos = best.GuessedInitiatorPosition;
                    _hasLastNoise = true;
                }
                return hasBest;
            }

            protected bool TryCaptureMovementNoise(BaseCombatEntity enemy)
            {
                if (!HearsMovementNoise) return false;
                BasePlayer best = FindLoudestMovingPlayer(enemy);
                if (best == null) return false;
                Vector3 bp = best.transform.position;
                _lastNoisePos = bp;
                _lastNoiseInitiatorPos = bp;
                _hasLastNoise = true;
                return true;
            }

            protected virtual BaseCombatEntity FindMovingEnemy()
            {
                if (!HearsMovementNoise) return null;
                return FindLoudestMovingPlayer(null);
            }

            private BasePlayer FindLoudestMovingPlayer(BaseCombatEntity onlyThis)
            {
                if (Brain == null) return null;
                BasePlayer best = null;
                float bestSqr = float.MaxValue;
                Vector3 pos = Owner.transform.position;
                float closeRangeSqr = MovementNoiseCloseRange * MovementNoiseCloseRange;
                float farRangeSqr = MovementNoiseFarRange * MovementNoiseFarRange;
                float closeThreshold = MovementNoiseCloseSpeedThreshold;
                float farThreshold = MovementNoiseSpeedThreshold;
                foreach (BasePlayer p in Brain.GetNearestEntity<BasePlayer>(null))
                {
                    if (!p.IsValid() || !p.IsAlive() || p == Owner) continue;
                    if (onlyThis != null && p != onlyThis) continue;
                    float sqr = (p.transform.position - pos).sqrMagnitude;
                    if (sqr > farRangeSqr) continue;
                    float threshold = sqr <= closeRangeSqr ? closeThreshold : farThreshold;
                    if (p.estimatedSpeed < threshold) continue;
                    if (onlyThis == null && !CanTargetBattleEnemy(p)) continue;
                    if (sqr < bestSqr)
                    {
                        bestSqr = sqr;
                        best = p;
                    }
                }
                return best;
            }

            protected virtual BaseCombatEntity FindAITargetingMe()
            {
                if (Brain == null) return null;
                BaseCombatEntity best = null;
                float bestSqr = float.MaxValue;
                Vector3 pos = Owner.transform.position;
                foreach (BaseCombatEntity cand in Brain.GetNearestEntity<BaseCombatEntity>(null))
                {
                    if (!cand.IsValid() || !cand.IsAlive() || cand == Owner) continue;
                    if (cand.Distance(Owner) > MaxChaseDistance) continue;
                    if (!IsAITargetingMe(cand)) continue;
                    if (!CanTargetBattleEnemy(cand)) continue;
                    float sqr = (cand.transform.position - pos).sqrMagnitude;
                    if (sqr >= bestSqr) continue;
                    bestSqr = sqr;
                    best = cand;
                }
                return best;
            }
            protected bool IsAITargetingMe(BaseCombatEntity cand)
            {
                if (cand is global::HumanNPC human)
                {
                    List<BaseEntity> targets = human.Brain?.Senses?.Memory?.Targets;
                    return targets != null && targets.Contains(Owner);
                }
                if (cand is BaseNPC2 npc2)
                {
                    return npc2.TryGetCurrentAITarget(out BaseEntity senseTarget) && senseTarget == Owner;
                }
                return false;
            }

            protected virtual BaseCombatEntity FindEnemyByNoise()
            {
                Rust.Ai.Gen2.NpcNoiseManager manager = SingletonComponent<Rust.Ai.Gen2.NpcNoiseManager>.Instance;
                if (manager == null) return null;
                List<Rust.Ai.Gen2.NpcNoiseEvent> list = Pool.Get<List<Rust.Ai.Gen2.NpcNoiseEvent>>();
                manager.GetNoisesAround(Owner.transform.position, HearingRange, list);
                BaseCombatEntity best = null;
                double bestTime = -1;
                double now = UnityEngine.Time.timeAsDouble;
                for (int i = 0; i < list.Count; i++)
                {
                    Rust.Ai.Gen2.NpcNoiseEvent ev = list[i];
                    if ((int)ev.Intensity < (int)HearingIntensityThreshold) continue;
                    if (now - ev.EventTime > SensorMaxAge) continue;
                    BaseCombatEntity cand = ev.Initiator as BaseCombatEntity;
                    if (!cand.IsValid() || !cand.IsAlive() || cand == Owner) continue;
                    if (cand.Distance(Owner) > MaxChaseDistance) continue;
                    if (!CanTargetBattleEnemy(cand)) continue;
                    if (ev.EventTime > bestTime)
                    {
                        bestTime = ev.EventTime;
                        best = cand;
                    }
                }
                Pool.FreeUnmanaged(ref list);
                return best;
            }
        }

        public class CombatFSM : FSM
        {
            public const float StateDwell = 0.5f;
            public BattleFsmState ParentBattle;
            protected ChaseEnemyState _chaseState;
            protected CoverState _coverState;
            protected FleeState _fleeState;
            protected SearchEnemyState _searchState;
            protected RepositionState _repositionState;

            protected override void Start()
            {
                _chaseState = FSM.BaseStatePlayerNpc.GetPoolState<ChaseEnemyState>(this);
                _coverState = FSM.BaseStatePlayerNpc.GetPoolState<CoverState>(this);
                _fleeState = FSM.BaseStatePlayerNpc.GetPoolState<FleeState>(this);
                _searchState = FSM.BaseStatePlayerNpc.GetPoolState<SearchEnemyState>(this);
                _repositionState = FSM.BaseStatePlayerNpc.GetPoolState<RepositionState>(this);
            }
            public virtual void OnBattleEnter()
            {
                _repositionState?.OnBattleEnter();
            }
            protected override void InitFSM(FSM.BaseStatePlayerNpc idleState)
            {
                BattleFsmState battle = ParentBattle;
                bool useFlee = battle?.UseFlee ?? false;
                bool useCover = battle?.UseCover ?? false;
                bool useSearch = battle?.UseSearch ?? false;
                bool useReposition = (battle?.UseReposition ?? false) && _repositionState != null;
                bool coverAbove = battle?.CoverPriorityAboveFlee ?? false;

                if (useReposition) idleState.AddTickTransfer(_repositionState, _repositionState.CanScatter);
                AddThreatTransfers(idleState, useFlee, useCover, coverAbove);
                idleState.AddTickTransfer(_chaseState);
                if (useSearch) idleState.AddTickTransfer(_searchState);
                if (useReposition)
                {
                    idleState.AddTickTransfer(_repositionState);
                    if (useFlee) _repositionState.AddTickTransfer(_fleeState);
                    _repositionState.AddCompletedTransfer(idleState);
                    _repositionState.AddFailureTransfer(idleState);
                }

                AddThreatTransfers(_chaseState, useFlee, useCover, coverAbove);
                _chaseState.AddCompletedTransfer(idleState);
                _chaseState.AddFailureTransfer(idleState);

                if (useCover)
                {
                    if (useFlee && !coverAbove) _coverState.AddTickTransfer(_fleeState);
                    _coverState.AddCompletedTransfer(idleState);
                    _coverState.AddFailureTransfer(idleState);
                }
                if (useFlee)
                {
                    if (useCover && coverAbove) _fleeState.AddTickTransfer(_coverState);
                    _fleeState.AddCompletedTransfer(idleState);
                    _fleeState.AddFailureTransfer(idleState);
                }
                if (useSearch)
                {
                    AddThreatTransfers(_searchState, useFlee, useCover, coverAbove);
                    _searchState.AddTickTransfer(_chaseState);
                    _searchState.AddCompletedTransfer(idleState);
                    _searchState.AddFailureTransfer(idleState);
                }
            }
            private void AddThreatTransfers(FSM.BaseStatePlayerNpc source, bool useFlee, bool useCover, bool coverAbove)
            {
                if (coverAbove)
                {
                    if (useCover) source.AddTickTransfer(_coverState);
                    if (useFlee) source.AddTickTransfer(_fleeState);
                }
                else
                {
                    if (useFlee) source.AddTickTransfer(_fleeState);
                    if (useCover) source.AddTickTransfer(_coverState);
                }
            }
            protected override void OnDestroy()
            {
                FSM.BaseStatePlayerNpc.SetPoolState(ref _chaseState);
                FSM.BaseStatePlayerNpc.SetPoolState(ref _coverState);
                FSM.BaseStatePlayerNpc.SetPoolState(ref _fleeState);
                FSM.BaseStatePlayerNpc.SetPoolState(ref _searchState);
                FSM.BaseStatePlayerNpc.SetPoolState(ref _repositionState);
                ParentBattle = null;
            }

            public class ChaseEnemyState : FSM.RouterState
            {
                private const float ChaseStopDistanceMul = 0.9f;
                private float _cooldown;
                private Vector3 _shoreTarget;
                private Vector3 _firePosition;
                private int _firePositionAttempts;
                private ulong _firePositionEnemyId;
                private bool _closingOnHiddenLogged;
                private bool _closingOnHidden;
                public bool IsClosingInOnHiddenTarget => _closingOnHidden && !IsStuck && modeRouter == FSM.IRouterState.ModeRouter.Moved;
                private float LastVisibleArrival => RouterArrival + MinDistanceMovedEnemyForAddPoint;
                private static readonly float[] FirePosRingMul = { 0.75f, 0.55f };
                private const int FirePosDirections = 12;
                private const float FirePosNavSampleRadius = 4f;
                private const float FirePosEyeHeight = 1.6f;
                private const float FirePosMaxDetour = 80f;
                private const int FirePosPathChecks = 4;
                private const int FirePosMaxAttempts = 2;
                private const float AbandonMinDistance = 12f;
                private static readonly int FirePosObstacleMask = LayerMask.GetMask("Default", "Deployed", "Construction", "Terrain", "World", "Vehicle World", "Vehicle Large", "Vehicle Detailed");

                public override string Name => "Chase Enemy";
                protected override float MinStateDwell => CombatFSM.StateDwell;
                protected override BaseEntity GetChaseEnemy
                {
                    get
                    {
                        BattleFsmState parent = ((CombatFSM)ParentFSM)?.ParentBattle;
                        if (parent == null || !parent.CurrentEnemy) return null;
                        if (Owner.IsInWater && IsHelplessInWater(parent)) return null;
                        if (_firePosition != Vector3.zero) return null;
                        if (parent.UseSensors && !parent.IsEnemyVisibleNow()) return null;
                        return parent.CurrentEnemy.Enemy;
                    }
                }
                public override bool CanSwimAhead(Vector3 entryPoint, float depth, float distance)
                {
                    BattleFsmState parent = ((CombatFSM)ParentFSM)?.ParentBattle;
                    if (parent == null || !parent.CurrentEnemy) return true;
                    if (IsHelplessInWater(parent))
                    {
                        return false;
                    }
                    return true;
                }
                private bool IsHelplessInWater(BattleFsmState parent)
                    => !parent.HasWaterCapableWeapon() || (Owner.IsInWater && !parent.CurrentWeapon);
                protected override float MinDistanceMovedEnemyForAddPoint => 2f;
                private bool IsCooldown => UnityEngine.Time.time < _cooldown;

                protected override void OnDestroy()
                {
                    _cooldown = 0f;
                    _closingOnHiddenLogged = false;
                    _closingOnHidden = false;
                    _shoreTarget = Vector3.zero;
                    _firePosition = Vector3.zero;
                    _firePositionAttempts = 0;
                    _firePositionEnemyId = 0;
                    base.OnDestroy();
                }
                protected override void LeaveState()
                {
                    _shoreTarget = Vector3.zero;
                    _firePosition = Vector3.zero;
                    _closingOnHiddenLogged = false;
                    _closingOnHidden = false;
                    Navigator?.ClearFacingDirectionOverride();
                    base.LeaveState();
                }
                private static readonly float[] ShoreProbeRadii = { 6f, 12f, 20f, 32f };
                private const int ShoreProbeDirections = 8;
                private const float ShoreSnapRadius = 4f;
                private const float ShoreSearchFailCooldown = 3f;
                private const float WaterRefusalCooldown = 5f;
                private bool TryGetShorePoint(out Vector3 shore)
                {
                    shore = Vector3.zero;
                    if (Navigator == null || !Owner.IsValid())
                    {
                        return false;
                    }
                    Vector3 botPos = Owner.transform.position;
                    int offMesh = 0, tooDeep = 0;
                    for (int r = 0; r < ShoreProbeRadii.Length; r++)
                    {
                        float radius = ShoreProbeRadii[r];
                        for (int i = 0; i < ShoreProbeDirections; i++)
                        {
                            float angle = i * (360f / ShoreProbeDirections);
                            Vector3 probe = botPos + Quaternion.Euler(0f, angle, 0f) * Vector3.forward * radius;
                            HelperMap.ToGroundPoint(ref probe);
                            if (!Navigator.GetNearestNavmeshPosition(probe, out Vector3 candidate, ShoreSnapRadius)) { offMesh++; continue; }
                            if (IsPointTooDeep(candidate)) { tooDeep++; continue; }
                            shore = candidate;
                            return true;
                        }
                    }
                    return false;
                }
                private bool TryFindFirePosition(BattleFsmState parent, float fireRange, out Vector3 result)
                {
                    result = Vector3.zero;
                    if (Navigator == null || !Owner.IsValid() || !parent.CurrentEnemy.IsValid()) return false;
                    Vector3 botPos = Owner.transform.position;
                    Vector3 enemyPos = parent.CurrentEnemy.Position;
                    Vector3 enemyEye = parent.CurrentEnemy.CenterPoint;

                    Vector3[] best = new Vector3[FirePosPathChecks];
                    float[] bestDist = new float[FirePosPathChecks];
                    for (int i = 0; i < FirePosPathChecks; i++) bestDist[i] = float.MaxValue;
                    int offMesh = 0, tooDeep = 0, noLos = 0, tooFar = 0;

                    for (int r = 0; r < FirePosRingMul.Length; r++)
                    {
                        float radius = fireRange * FirePosRingMul[r];
                        for (int i = 0; i < FirePosDirections; i++)
                        {
                            float angle = i * (360f / FirePosDirections);
                            Vector3 candidate = enemyPos + Quaternion.Euler(0f, angle, 0f) * Vector3.forward * radius;
                            HelperMap.ToGroundPoint(ref candidate);
                            if (!Navigator.GetNearestNavmeshPosition(candidate, out Vector3 sampled, FirePosNavSampleRadius)) { offMesh++; continue; }
                            if (IsPointTooDeep(sampled)) { tooDeep++; continue; }
                            float toBot = Vector3.Distance(sampled, botPos);
                            if (toBot > FirePosMaxDetour) { tooFar++; continue; }
                            Vector3 eye = sampled + Vector3.up * FirePosEyeHeight;
                            Vector3 diff = enemyEye - eye;
                            float d = diff.magnitude;
                            if (d < 0.1f) continue;
                            if (Physics.Raycast(eye, diff / d, d, FirePosObstacleMask, QueryTriggerInteraction.Ignore)) { noLos++; continue; }
                            for (int k = 0; k < FirePosPathChecks; k++)
                            {
                                if (toBot >= bestDist[k]) continue;
                                for (int m = FirePosPathChecks - 1; m > k; m--) { bestDist[m] = bestDist[m - 1]; best[m] = best[m - 1]; }
                                bestDist[k] = toBot; best[k] = sampled;
                                break;
                            }
                        }
                    }

                    for (int k = 0; k < FirePosPathChecks; k++)
                    {
                        if (bestDist[k] == float.MaxValue) break;
                        if (!Navigator.HasCompleteDryPathTo(best[k])) continue;
                        result = best[k];
                        return true;
                    }
                    return false;
                }
                protected override bool CanEnterState()
                {
                    if (IsCooldown) return false;
                    BattleFsmState parent = ((CombatFSM)ParentFSM)?.ParentBattle;
                    if (parent == null || !parent.CurrentEnemy) return false;
                    if (parent.IsEnemyInSafeZoneNow()) return false;
                    if (ParentFSM?.GetCurrentState() is SearchEnemyState
                        && !parent.IsEnemyVisibleNow()) return false;
                    float enterDist = parent.GetMaxAttackDistance();
                    if (parent.CurrentEnemy.Distance(Owner) <= enterDist)
                    {
                        if (parent.UseSensors || parent.HasLineOfSightNow()) return false;
                    }
                    return parent.CanChaseEnemy();
                }
                protected override FSM.BaseStatePlayerNpc.ResponseFromUpdateState UpdateState(float delta)
                {
                    base.UpdateState(delta);
                    _closingOnHidden = false;
                    BattleFsmState parent = ((CombatFSM)ParentFSM)?.ParentBattle;
                    if (parent == null || !parent.CurrentEnemy)
                    {
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                    }
                    if (IsStuck)
                    {
                        StuckReason stuckReason = StuckReasonLatched;
                        float enemyDist = parent.CurrentEnemy.Distance(Owner);
                        float fireRange = parent.GetPotentialFireDistance();
                        bool waterRefusal = stuckReason == StuckReason.DeepWaterAhead || stuckReason == StuckReason.SwimObstacle;
                        Stop();
                        ResetStuck();
                        _shoreTarget = Vector3.zero;

                        bool hiddenInRange = enemyDist <= fireRange && !parent.UseSensors && !parent.HasLineOfSightNow();
                        if (enemyDist <= fireRange && !hiddenInRange)
                        {
                            if (waterRefusal) _cooldown = UnityEngine.Time.time + WaterRefusalCooldown;
                            return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                        }

                        if (enemyDist < AbandonMinDistance)
                        {
                            _cooldown = UnityEngine.Time.time + 5f;
                            return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                        }

                        ulong stuckEnemyId = parent.CurrentEnemy.Enemy.IsValid() ? parent.CurrentEnemy.Enemy.net.ID.Value : 0;
                        if (stuckEnemyId != _firePositionEnemyId)
                        {
                            _firePositionEnemyId = stuckEnemyId;
                            _firePositionAttempts = 0;
                        }
                        if (Owner.IsInWater)
                        {
                            return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                        }
                        if (_firePositionAttempts < FirePosMaxAttempts && TryFindFirePosition(parent, fireRange, out Vector3 firePos))
                        {
                            _firePositionAttempts++;
                            _firePosition = firePos;
                            SetTarget(_firePosition, NavigationSpeed.Fast);
                            return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.NONE;
                        }

                        parent.AbandonEnemyUnreachable(string.Format(hiddenInRange
                                ? "unreachable ({0}), target at {1:0.0}m within weapon range {2:0.0}m but not visible, no firing position reachable by land"
                                : "unreachable ({0}), target at {1:0.0}m with weapon range {2:0.0}m, no firing position reachable by land",
                            stuckReason, enemyDist, fireRange), hiddenInRange);
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                    bool useSensors = parent.UseSensors;
                    bool visibleNow = parent.IsEnemyVisibleNow();
                    bool canFireFromHere = useSensors ? visibleNow : parent.HasLineOfSightNow();
                    float dist = parent.CurrentEnemy.Distance(Owner);
                    float maxDist = parent.GetMaxAttackDistance();
                    float stopDist = maxDist * ChaseStopDistanceMul;
                    if (dist <= stopDist && canFireFromHere)
                    {
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                    if (_firePosition != Vector3.zero)
                    {
                        if (modeRouter == FSM.IRouterState.ModeRouter.Finish)
                        {
                            _firePosition = Vector3.zero;
                            Stop();
                            return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                        }
                        if (modeRouter == FSM.IRouterState.ModeRouter.Idle) SetTarget(_firePosition, NavigationSpeed.Fast);
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.NONE;
                    }
                    if (!parent.CanChaseEnemy())
                    {
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                    bool helplessInWater = IsHelplessInWater(parent);
                    if (helplessInWater && Owner.IsInWater)
                    {
                        if (_shoreTarget == Vector3.zero)
                        {
                            if (!TryGetShorePoint(out _shoreTarget))
                            {
                                _shoreTarget = Vector3.zero;
                                _cooldown = UnityEngine.Time.time + ShoreSearchFailCooldown;
                                return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                            }
                            SetTarget(_shoreTarget, NavigationSpeed.Fast);
                            return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.NONE;
                        }
                        bool navIdle = modeRouter == FSM.IRouterState.ModeRouter.Idle
                                    || modeRouter == FSM.IRouterState.ModeRouter.Finish
                                    || modeRouter == FSM.IRouterState.ModeRouter.Stuck;
                        if (navIdle)
                        {
                            _shoreTarget = Vector3.zero;
                            ResetStuck();
                        }
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.NONE;
                    }
                    _shoreTarget = Vector3.zero;
                    if (helplessInWater && parent.IsEnemySwimming())
                    {
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                    if (!canFireFromHere && !useSensors && dist <= maxDist)
                    {
                        _closingOnHidden = true;
                        if (!_closingOnHiddenLogged)
                        {
                            _closingOnHiddenLogged = true;
                        }
                    }
                    else _closingOnHiddenLogged = false;
                    bool goingToLastVisible = useSensors && parent.HasLastVisible && !visibleNow;
                    Vector3 target = goingToLastVisible ? parent.LastVisiblePos : parent.CurrentEnemy.Position;
                    if (useSensors && !visibleNow && parent.HasLastVisible && modeRouter == FSM.IRouterState.ModeRouter.Finish
                        && (parent.LastVisiblePos - Owner.transform.position).sqrMagnitude <= LastVisibleArrival * LastVisibleArrival)
                    {
                        parent.MarkLastVisibleReached();
                        if (parent.CanSearchEnemy())
                        {
                            return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                        }
                        if (parent.IsInFreshContact)
                        {
                            return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                        }
                        parent.AbandonEnemyLost(string.Format("reached last visible position {0}, target is absent and search is not available (search enabled={1})",
                            parent.LastVisiblePos, parent.UseSearch));
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                    if (visibleNow) Navigator?.SetFacingDirectionEntity(parent.CurrentEnemy.Enemy);
                    else
                    {
                        Vector3 dir = Vector3Ex.Direction2D(target, Owner.transform.position);
                        if (dir.sqrMagnitude > 0.01f) Navigator?.SetFacingDirectionOverride(dir.normalized);
                        else Navigator?.ClearFacingDirectionOverride();
                    }
                    if (modeRouter == FSM.IRouterState.ModeRouter.Idle
                        || (modeRouter == FSM.IRouterState.ModeRouter.Finish && (target - Owner.transform.position).sqrMagnitude > RouterArrival * RouterArrival))
                        SetTarget(target, NavigationSpeed.Fast);
                    return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.NONE;
                }
            }

            public class CoverState : FSM.RouterState
            {
                private const float CoverHealthPercent = 0.5f;
                private static readonly float[] CoverSearchRadii = { 6f, 12f, 18f };
                private const float CoverNavMeshSampleRadius = 5f;
                private const int CoverCandidateSteps = 12;
                private const float CoverEyeHeight = 1.6f;
                private const float CoverMinEnemyDistance = 5f;
                private const float CoverNearRingBonus = 0.35f;
                private const float CoverFailureCooldownMin = 4f;
                private const float CoverFailureCooldownMax = 20f;
                private const int CoverFailureStreakMax = 3;
                private static readonly int CoverObstacleMask = LayerMask.GetMask("Default", "Deployed", "Construction", "Terrain", "World", "Vehicle World", "Vehicle Large", "Vehicle Detailed");
                private TimeSince _holdTimer;
                private TimeSince _approachTimer;
                private const float CoverApproachTimeout = 8f;
                private float _cooldown;
                private int _failureStreak;
                private ulong _lastEnemyId;
                private bool _atCover;
                private TimeSince _phaseTimer;
                private bool _peekPhase;
                private TimeSince _exposedTimer;
                private bool _wantsFire;

                public override string Name => "Cover";
                protected override float MinStateDwell => CombatFSM.StateDwell;
                public bool WantsFireNow => _wantsFire;
                protected override BaseEntity GetChaseEnemy => null;
                protected override float MinDistanceMovedEnemyForAddPoint => 0f;
                private bool IsCooldown => UnityEngine.Time.time < _cooldown;

                protected override void OnDestroy()
                {
                    _cooldown = 0f;
                    _failureStreak = 0;
                    _lastEnemyId = 0;
                    base.OnDestroy();
                }
                protected override void EnterState()
                {
                    base.EnterState();
                    _atCover = false;
                    _peekPhase = false;
                    _wantsFire = false;
                    _approachTimer = 0;
                }
                protected override void LeaveState()
                {
                    _atCover = false;
                    _wantsFire = false;
                    BattleFsmState parent = ((CombatFSM)ParentFSM)?.ParentBattle;
                    if (parent != null) parent.WantsCrouch = false;
                    Navigator?.ClearFacingDirectionOverride();
                    base.LeaveState();
                }
                protected override bool CanEnterState()
                {
                    if (IsCooldown) return false;
                    BattleFsmState parent = ((CombatFSM)ParentFSM)?.ParentBattle;
                    if (parent == null || !parent.UseCover || !parent.CurrentEnemy.IsValid()) return false;
                    ulong enemyId = parent.CurrentEnemy.Enemy.IsValid() ? parent.CurrentEnemy.Enemy.net.ID.Value : 0;
                    if (enemyId != _lastEnemyId)
                    {
                        _failureStreak = 0;
                        _lastEnemyId = enemyId;
                    }
                    if (parent.CurrentEnemy.Distance(Owner) < CoverMinEnemyDistance) return false;
                    if (parent.IsUnderFire && !IsEnemyHoldingMelee(parent)) return true;
                    float? hp = Brain?.PercentHeal();
                    return hp.HasValue && hp.Value < CoverHealthPercent && parent.IsEnemyVisibleNow();
                }
                protected override FSM.BaseStatePlayerNpc.ResponseFromUpdateState UpdateState(float delta)
                {
                    base.UpdateState(delta);
                    BattleFsmState parent = ((CombatFSM)ParentFSM)?.ParentBattle;
                    if (parent == null || !parent.CurrentEnemy) return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    float enemyDist = parent.CurrentEnemy.Distance(Owner);
                    if (enemyDist < CoverMinEnemyDistance)
                    {
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                    if (IsStuck)
                    {
                        ApplyFailureBackoff();
                        ResetStuck();
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                    }
                    if (!_atCover && modeRouter == FSM.IRouterState.ModeRouter.Idle && !Navigator.Moving)
                    {
                        if (!TryMoveToCover(parent))
                        {
                            ApplyFailureBackoff();
                            return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                        }
                        _approachTimer = 0;
                    }
                    if (!_atCover && (float)_approachTimer > CoverApproachTimeout)
                    {
                        ApplyFailureBackoff();
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                    }
                    if (!_atCover && modeRouter == FSM.IRouterState.ModeRouter.Finish)
                    {
                        _atCover = true;
                        _holdTimer = 0;
                        _phaseTimer = 0;
                        _peekPhase = false;
                        _exposedTimer = 0;
                        _failureStreak = 0;
                        parent.WantsCrouch = true;
                    }
                    if (_atCover)
                    {
                        Navigator?.SetFacingDirectionEntity(parent.CurrentEnemy.Enemy);
                        if (parent.IsUnderFire)
                        {
                            if ((float)_exposedTimer > BattleFsmState.CoverExposedGrace)
                            {
                                _atCover = false;
                                _wantsFire = false;
                                return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                            }
                        }
                        else _exposedTimer = 0;
                        UpdateCoverPose(parent);
                        if ((float)_holdTimer > BattleFsmState.CoverHoldWindow) return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                    else _wantsFire = false;
                    return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.NONE;
                }
                private void UpdateCoverPose(BattleFsmState parent)
                {
                    if (_peekPhase)
                    {
                        if ((float)_phaseTimer > BattleFsmState.CoverPeekDuration) { _peekPhase = false; _phaseTimer = 0; }
                    }
                    else
                    {
                        if ((float)_phaseTimer > BattleFsmState.CoverDuckDuration) { _peekPhase = true; _phaseTimer = 0; }
                    }
                    bool stand = _peekPhase && HasStandingLos(parent);
                    parent.WantsCrouch = !stand;
                    _wantsFire = stand;
                }
                private bool HasStandingLos(BattleFsmState parent)
                {
                    if (!parent.CurrentEnemy) return false;
                    Vector3 eye = Owner.transform.position + Vector3.up * CoverEyeHeight;
                    Vector3 enemyEye = parent.CurrentEnemy.CenterPoint;
                    Vector3 diff = enemyEye - eye;
                    float dist = diff.magnitude;
                    if (dist < 0.1f) return true;
                    return !Physics.Raycast(eye, diff / dist, dist, CoverObstacleMask, QueryTriggerInteraction.Ignore);
                }
                private static bool IsEnemyHoldingMelee(BattleFsmState parent)
                    => parent.CurrentEnemy.Enemy is BasePlayer player && player.GetHeldEntity() is BaseMelee;
                private void ApplyFailureBackoff()
                {
                    int streak = Mathf.Min(_failureStreak, CoverFailureStreakMax);
                    float cooldown = Mathf.Min(CoverFailureCooldownMax, CoverFailureCooldownMin * (1 << streak));
                    _cooldown = UnityEngine.Time.time + cooldown;
                    _failureStreak++;
                }
                private bool TryMoveToCover(BattleFsmState parent)
                {
                    Vector3 myPos = Owner.transform.position;
                    Vector3 enemyEye = parent.CurrentEnemy.CenterPoint;
                    Vector3 fromEnemy = myPos - parent.CurrentEnemy.Position;
                    fromEnemy.y = 0;
                    if (fromEnemy.sqrMagnitude < 0.01f) fromEnemy = Vector3.forward;
                    else fromEnemy.Normalize();

                    Vector3 bestPoint = Vector3.zero;
                    float bestScore = float.MinValue;
                    float farthestRadius = CoverSearchRadii[CoverSearchRadii.Length - 1];
                    int offMesh = 0, tooDeep = 0, notBlocking = 0, safeZone = 0;
                    bool avoidSafeZones = Owner.AvoidSafeZonesNow;
                    for (int r = 0; r < CoverSearchRadii.Length; r++)
                    {
                        float radius = CoverSearchRadii[r];
                        for (int i = 0; i < CoverCandidateSteps; i++)
                        {
                            float angle = i * (360f / CoverCandidateSteps);
                            Vector3 dir = Quaternion.Euler(0, angle, 0) * fromEnemy;
                            Vector3 candidate = myPos + dir * radius;
                            HelperMap.ToGroundPoint(ref candidate);
                            if (Navigator == null || !Navigator.GetNearestNavmeshPosition(candidate, out Vector3 sampled, CoverNavMeshSampleRadius)) { offMesh++; continue; }
                            if (IsPointTooDeep(sampled)) { tooDeep++; continue; }
                            if (avoidSafeZones && HelperSafeZones.IsWayBlocked(myPos, sampled)) { safeZone++; continue; }

                            Vector3 candidateEye = sampled + Vector3.up * CoverEyeHeight;
                            Vector3 diff = enemyEye - candidateEye;
                            float dist = diff.magnitude;
                            if (dist < 0.1f) continue;
                            bool blocked = Physics.Raycast(candidateEye, diff / dist, dist, CoverObstacleMask, QueryTriggerInteraction.Ignore);
                            if (!blocked) { notBlocking++; continue; }

                            float score = Vector3.Dot(dir, fromEnemy) - radius / farthestRadius * CoverNearRingBonus;
                            if (score > bestScore)
                            {
                                bestScore = score;
                                bestPoint = sampled;
                            }
                        }
                    }
                    if (bestPoint == Vector3.zero)
                    {
                        return false;
                    }
                    SetTarget(bestPoint, NavigationSpeed.Fast);
                    return true;
                }
            }

            public class FleeState : FSM.RouterState
            {
                public const float FleeHealthPercent = 0.3f;
                private const float FleeDistance = 30f;
                private const float FleeSafeDistance = 50f;
                private const float FleeRepathInterval = 4f;
                private const int FleeCandidateCount = 5;
                private const float FleeCandidateSpread = 180f;
                private const int FleeFullCircleCandidates = 8;
                private const float FleeShortPassDistanceMul = 0.5f;
                private const float FleeEyeHeight = 1.6f;
                private const float FleeNavMeshSampleRadius = 5f;
                private const float FleeLosBlockedBonus = 0.5f;
                private const int FleeVerifiedCandidates = 3;
                private const float FleeFailureCooldown = 4f;
                private const float FleeFailedPointRadius = 3f;
                private static readonly int FleeObstacleMask = LayerMask.GetMask("Default", "Deployed", "Construction", "Terrain", "World", "Vehicle World", "Vehicle Large", "Vehicle Detailed");
                private TimeSince _repathTimer;
                private float _cooldown;
                private Vector3 _lastFailedPoint;
                private float _failedPointCooldown;
                private Vector3 _currentTarget;
                private readonly Vector3[] _topPoints = new Vector3[FleeVerifiedCandidates];
                private readonly float[] _topScores = new float[FleeVerifiedCandidates];
                private int _topCount;

                public override string Name => "Flee";
                protected override float MinStateDwell => CombatFSM.StateDwell;
                protected override BaseEntity GetChaseEnemy => null;
                protected override float MinDistanceMovedEnemyForAddPoint => 0f;
                private bool IsCooldown => UnityEngine.Time.time < _cooldown;

                protected override void OnDestroy()
                {
                    _cooldown = 0f;
                    _failedPointCooldown = 0f;
                    _lastFailedPoint = Vector3.zero;
                    _currentTarget = Vector3.zero;
                    base.OnDestroy();
                }
                protected override void EnterState()
                {
                    base.EnterState();
                    _repathTimer = FleeRepathInterval + 1f;
                }
                protected override void LeaveState()
                {
                    Navigator?.ClearFacingDirectionOverride();
                    base.LeaveState();
                }
                protected override bool CanEnterState()
                {
                    if (IsCooldown) return false;
                    BattleFsmState parent = ((CombatFSM)ParentFSM)?.ParentBattle;
                    if (parent == null || !parent.UseFlee || !parent.CurrentEnemy.IsValid()) return false;
                    if (parent.AlwaysFlee) return true;
                    if (parent.CurrentEnemy.Distance(Owner) >= FleeSafeDistance) return false;
                    if (parent.ShouldForceFlee()) return true;
                    if (parent.IsCurrentEnemyUnreachable && parent.IsUnderFire)
                    {
                        return true;
                    }
                    float? hp = Brain?.PercentHeal();
                    return hp.HasValue && hp.Value < FleeHealthPercent;
                }
                protected override FSM.BaseStatePlayerNpc.ResponseFromUpdateState UpdateState(float delta)
                {
                    base.UpdateState(delta);
                    BattleFsmState parent = ((CombatFSM)ParentFSM)?.ParentBattle;
                    if (parent == null || !parent.CurrentEnemy)
                    {
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                    if (IsStuck)
                    {
                        _lastFailedPoint = _currentTarget;
                        _failedPointCooldown = UnityEngine.Time.time + FleeFailureCooldown;
                        _cooldown = UnityEngine.Time.time + FleeFailureCooldown;
                        ResetStuck();
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                    }
                    if (!parent.AlwaysFlee && !parent.ShouldForceFlee() && parent.CurrentEnemy.Distance(Owner) >= FleeSafeDistance)
                    {
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                    if ((float)_repathTimer >= FleeRepathInterval)
                    {
                        _repathTimer = 0;
                        TryFleeFrom(parent);
                    }
                    return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.NONE;
                }
                private void TryFleeFrom(BattleFsmState parent)
                {
                    Vector3 myPos = Owner.transform.position;
                    Vector3 enemyPos = parent.CurrentEnemy.Position;
                    Vector3 enemyEye = parent.CurrentEnemy.CenterPoint;
                    Vector3 fromEnemy = myPos - enemyPos;
                    fromEnemy.y = 0;
                    if (fromEnemy.sqrMagnitude < 0.01f) fromEnemy = Vector3.forward;
                    else fromEnemy.Normalize();

                    Vector3 bestPoint = Vector3.zero;
                    float bestScore = float.MinValue;

                    Vector3 target;
                    if (!SampleFleePass(myPos, enemyEye, fromEnemy, FleeCandidateCount, FleeCandidateSpread, FleeDistance, ref bestPoint, ref bestScore, out target)
                        && !SampleFleePass(myPos, enemyEye, fromEnemy, FleeCandidateCount, FleeCandidateSpread, FleeDistance * FleeShortPassDistanceMul, ref bestPoint, ref bestScore, out target)
                        && !SampleFleePass(myPos, enemyEye, fromEnemy, FleeFullCircleCandidates, 360f, FleeDistance, ref bestPoint, ref bestScore, out target))
                    {
                        target = bestPoint;
                    }

                    bool blind = target == Vector3.zero;
                    if (blind)
                    {
                        Vector3 fallback = myPos + fromEnemy * FleeDistance;
                        HelperMap.ToGroundPoint(ref fallback);
                        target = fallback;
                    }
                    _currentTarget = target;
                    SetTarget(target, NavigationSpeed.Fast);
                }
                private bool SampleFleePass(Vector3 myPos, Vector3 enemyEye, Vector3 fromEnemy, int count, float spread, float distance, ref Vector3 bestPoint, ref float bestScore, out Vector3 verified)
                {
                    verified = Vector3.zero;
                    if (count < 1) return false;
                    _topCount = 0;
                    bool avoidSafeZones = Owner.AvoidSafeZonesNow;
                    float stepAngle = count > 1 ? spread / (count - 1) : 0f;
                    float startAngle = -spread * 0.5f;
                    for (int i = 0; i < count; i++)
                    {
                        float angle = startAngle + i * stepAngle;
                        Vector3 dir = Quaternion.Euler(0, angle, 0) * fromEnemy;
                        Vector3 candidate = myPos + dir * distance;
                        HelperMap.ToGroundPoint(ref candidate);
                        if (Navigator == null || !Navigator.GetNearestNavmeshPosition(candidate, out Vector3 sampled, FleeNavMeshSampleRadius)) continue;
                        if (IsPointTooDeep(sampled)) continue;
                        if (IsRecentlyFailed(sampled)) continue;
                        if (avoidSafeZones && HelperSafeZones.IsWayBlocked(myPos, sampled)) continue;

                        Vector3 sampledEye = sampled + Vector3.up * FleeEyeHeight;
                        Vector3 diff = enemyEye - sampledEye;
                        float distToEnemy = diff.magnitude;
                        bool losBlocked = distToEnemy > 0.1f
                            && Physics.Raycast(sampledEye, diff / distToEnemy, distToEnemy, FleeObstacleMask, QueryTriggerInteraction.Ignore);

                        float alignment = Vector3.Dot((sampled - myPos).normalized, fromEnemy);
                        float score = alignment + distToEnemy * 0.01f + (losBlocked ? FleeLosBlockedBonus : 0f);
                        if (score > bestScore)
                        {
                            bestScore = score;
                            bestPoint = sampled;
                        }
                        PushTopCandidate(sampled, score);
                    }
                    for (int i = 0; i < _topCount; i++)
                    {
                        if (Navigator == null || !Navigator.HasCompletePathTo(_topPoints[i], false)) continue;
                        verified = _topPoints[i];
                        return true;
                    }
                    return false;
                }
                private void PushTopCandidate(Vector3 point, float score)
                {
                    int pos = _topCount;
                    while (pos > 0 && _topScores[pos - 1] < score) pos--;
                    if (pos >= _topPoints.Length) return;
                    for (int i = Mathf.Min(_topCount, _topPoints.Length - 1); i > pos; i--)
                    {
                        _topPoints[i] = _topPoints[i - 1];
                        _topScores[i] = _topScores[i - 1];
                    }
                    _topPoints[pos] = point;
                    _topScores[pos] = score;
                    if (_topCount < _topPoints.Length) _topCount++;
                }
                private bool IsRecentlyFailed(Vector3 point)
                {
                    if (_lastFailedPoint == Vector3.zero || UnityEngine.Time.time >= _failedPointCooldown) return false;
                    return (point - _lastFailedPoint).sqrMagnitude <= FleeFailedPointRadius * FleeFailedPointRadius;
                }
            }

            public class SearchEnemyState : FSM.RouterState
            {
                private const float ScanDuration = 6f;
                private const float ScanArcAngle = 90f;
                private const float RotationSpeed = 6f;
                private const float ScanNetUpdateInterval = 0.1f;
                private float _nextScanNetUpdate;
                private const float SearchNavMeshSampleRadius = 15f;
                private int _failedWaypointMask;
                private int _visitedWaypointMask;
                private bool _routeExhausted;
                private const float SearchSnapshotSoftShiftSqr = 25f;
                private const float SearchAreaPatrolRadius = 10f;
                private const int SearchAreaPatrolCount = 3;
                private const float EmptyRouteRetryInterval = 2f;
                private float _nextEmptyRouteRetry;
                private readonly Vector3[] _waypoints = new Vector3[3];
                private readonly string[] _waypointSource = new string[3];
                private readonly Vector3[] _snapshot = new Vector3[2];
                private int _waypointCount;
                private int _currentIndex;
                private Vector3 _targetPosition;
                private Vector3 _routedPosition;
                private const float SearchRerouteShiftSqr = 1f;
                private Vector3 _rawTargetDirection;
                private Vector3 _smoothedDirection;
                private Vector3 _scanCenterDirection;
                private bool _isScanning;
                private float _scanProgress;
                private int _scanRestartCount;
                private BaseCombatEntity _lastEnemy;
                private float _cooldown;
                private bool IsCooldown => UnityEngine.Time.time < _cooldown;

                public override string Name => "Search Enemy";
                protected override float MinStateDwell => CombatFSM.StateDwell;
                protected override BaseEntity GetChaseEnemy => null;
                protected override float MinDistanceMovedEnemyForAddPoint => 0f;

                protected override void OnDestroy()
                {
                    _cooldown = 0f;
                    Clear();
                    base.OnDestroy();
                }
                protected override void EnterState()
                {
                    base.EnterState();
                    if (Owner.IsValid() && !Owner.modelState.aiming)
                    {
                        Owner.modelState.aiming = true;
                        Owner.SendNetworkUpdateImmediate();
                    }
                    ((CombatFSM)ParentFSM)?.ParentBattle?.OnEnterSearch();
                }
                protected override void LeaveState()
                {
                    if (Owner.IsValid() && Owner.modelState.aiming)
                    {
                        Owner.modelState.aiming = false;
                        Owner.SendNetworkUpdateImmediate();
                    }
                    Clear();
                    Navigator?.ClearFacingDirectionOverride();
                    base.LeaveState();
                }
                protected override bool CanEnterState()
                {
                    if (IsCooldown) return false;
                    BattleFsmState parent = ((CombatFSM)ParentFSM)?.ParentBattle;
                    return parent != null && parent.CanSearchEnemy();
                }
                protected override FSM.BaseStatePlayerNpc.ResponseFromUpdateState UpdateState(float delta)
                {
                    BattleFsmState parent = ((CombatFSM)ParentFSM)?.ParentBattle;
                    if (parent == null || !parent.CurrentEnemy.IsValid())
                    {
                        Stop();
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                    }
                    if (!parent.CanSearchEnemy())
                    {
                        Stop();
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                    if (IsStuck)
                    {
                        Stop();
                        ResetStuck();
                        _failedWaypointMask |= 1 << _currentIndex;
                        if (HasUsableWaypoint())
                        {
                            StartScanning(delta);
                            return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.NONE;
                        }
                        _cooldown = UnityEngine.Time.time + 5f;
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                    }
                    base.UpdateState(delta);
                    UpdateEnemyContext(parent);
                    if (_waypointCount == 0)
                    {
                        _cooldown = UnityEngine.Time.time + EmptyRouteRetryInterval;
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                    if (_routeExhausted)
                    {
                        Stop();
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                    if (_isScanning)
                    {
                        UpdateScanMode(delta);
                        Owner.SetLookAngles(_smoothedDirection);
                        if (UnityEngine.Time.time >= _nextScanNetUpdate)
                        {
                            _nextScanNetUpdate = UnityEngine.Time.time + ScanNetUpdateInterval;
                            Owner.SendNetworkUpdate();
                        }
                    }
                    else if (_targetPosition != Vector3.zero)
                    {
                        if (modeRouter == FSM.IRouterState.ModeRouter.Finish)
                        {
                            if (IsTargetRerouted())
                            {
                                RouteToTarget("arrived at outdated point");
                            }
                            else
                            {
                                Stop();
                                StartScanning(delta);
                            }
                        }
                        else if (modeRouter == FSM.IRouterState.ModeRouter.Idle)
                        {
                            UpdateRawDirection();
                            SmoothDirection(delta);
                            Navigator.SetFacingDirectionOverride(_smoothedDirection);
                            if (Vector3.Dot(_rawTargetDirection, _smoothedDirection) > 0.6f)
                            {
                                SetTarget(_targetPosition, NavigationSpeed.Normal);
                                _routedPosition = _targetPosition;
                            }
                        }
                        else
                        {
                            Navigator.ClearFacingDirectionOverride();
                            if (modeRouter == FSM.IRouterState.ModeRouter.Moved && IsTargetRerouted())
                                RouteToTarget("point moved while walking");
                        }
                    }
                    else
                    {
                        Navigator.ClearFacingDirectionOverride();
                        if (modeRouter != FSM.IRouterState.ModeRouter.Idle) Stop();
                        MoveToNextWaypoint();
                    }
                    return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.NONE;
                }
                private void Clear()
                {
                    _waypointCount = 0;
                    _currentIndex = 0;
                    for (int i = 0; i < _waypoints.Length; i++) _waypoints[i] = Vector3.zero;
                    for (int i = 0; i < _snapshot.Length; i++) _snapshot[i] = Vector3.zero;
                    _targetPosition = Vector3.zero;
                    _routedPosition = Vector3.zero;
                    _rawTargetDirection = Vector3.zero;
                    _smoothedDirection = Vector3.zero;
                    _scanCenterDirection = Vector3.zero;
                    _isScanning = false;
                    _scanProgress = 0f;
                    _nextScanNetUpdate = 0f;
                    _failedWaypointMask = 0;
                    _visitedWaypointMask = 0;
                    _routeExhausted = false;
                    _nextEmptyRouteRetry = 0f;
                    _scanRestartCount = 0;
                    _lastEnemy = null;
                }
                private void UpdateEnemyContext(BattleFsmState parent)
                {
                    BaseCombatEntity enemy = parent.CurrentEnemy.Enemy;
                    Vector3 w0 = parent.HasLastVisible ? parent.LastVisiblePos : Vector3.zero;
                    Vector3 w1 = parent.HasLastNoise ? parent.LastNoiseInitiatorPos : Vector3.zero;
                    if (_waypointCount == 0 && UnityEngine.Time.time < _nextEmptyRouteRetry) return;
                    bool enemyChanged = _lastEnemy != enemy;
                    bool presenceChanged = (w0 == Vector3.zero) != (_snapshot[0] == Vector3.zero)
                                        || (w1 == Vector3.zero) != (_snapshot[1] == Vector3.zero);
                    bool softShift = (w0 - _snapshot[0]).sqrMagnitude > SearchSnapshotSoftShiftSqr
                                  || (w1 - _snapshot[1]).sqrMagnitude > SearchSnapshotSoftShiftSqr;
                    if (!enemyChanged && !presenceChanged && !softShift) return;
                    _lastEnemy = enemy;
                    _snapshot[0] = w0;
                    _snapshot[1] = w1;
                    if (_waypointCount > 0 && !enemyChanged && !presenceChanged)
                    {
                        RefreshRealWaypoints(w0, w1);
                        return;
                    }
                    Vector3 center = w0 != Vector3.zero ? w0 : w1;
                    _waypointCount = 0;
                    _failedWaypointMask = 0;
                    _visitedWaypointMask = 0;
                    _routeExhausted = false;
                    BuildRoute(w0, w1, center);
                    _currentIndex = 0;
                    _targetPosition = _waypointCount > 0 ? _waypoints[0] : Vector3.zero;
                    _isScanning = false;
                    _scanProgress = 0f;
                    if (_waypointCount == 0) _nextEmptyRouteRetry = UnityEngine.Time.time + EmptyRouteRetryInterval;
                }
                private void BuildRoute(Vector3 w0, Vector3 w1, Vector3 center)
                {
                    AddRoutePoints(w0, w1, center, allowDeep: false);
                    if (_waypointCount == 0) AddRoutePoints(w0, w1, center, allowDeep: true);
                }
                private void AddRoutePoints(Vector3 w0, Vector3 w1, Vector3 center, bool allowDeep)
                {
                    TryAddWaypoint(w0, "Visible", allowDeep);
                    TryAddWaypoint(w1, "NoiseInitiator", allowDeep);
                    if (_waypointCount < _waypoints.Length && center != Vector3.zero) TryAddAreaPatrol(center, allowDeep);
                }
                private void RefreshRealWaypoints(Vector3 w0, Vector3 w1)
                {
                    for (int i = 0; i < _waypointCount; i++)
                    {
                        Vector3 raw;
                        if (_waypointSource[i] == "Visible") raw = w0;
                        else if (_waypointSource[i] == "NoiseInitiator") raw = w1;
                        else continue;
                        if (raw == Vector3.zero) continue;
                        if (Navigator == null || !Navigator.GetNearestNavmeshPosition(raw, out Vector3 sampled, SearchNavMeshSampleRadius)) continue;
                        _waypoints[i] = sampled;
                        if (i == _currentIndex) _targetPosition = sampled;
                    }
                }
                private void TryAddWaypoint(Vector3 raw, string source, bool allowDeep)
                {
                    if (raw == Vector3.zero) return;
                    if (Navigator == null || !Navigator.GetNearestNavmeshPosition(raw, out Vector3 sampled, SearchNavMeshSampleRadius)) return;
                    if (!allowDeep && IsPointTooDeep(sampled)) return;
                    for (int i = 0; i < _waypointCount; i++)
                        if ((_waypoints[i] - sampled).sqrMagnitude < 0.01f) return;
                    _waypointSource[_waypointCount] = source;
                    _waypoints[_waypointCount++] = sampled;
                }
                private void TryAddAreaPatrol(Vector3 center, bool allowDeep)
                {
                    int limit = Mathf.Min(SearchAreaPatrolCount, _waypoints.Length - _waypointCount);
                    if (limit <= 0) return;
                    float startAngle = Random.Range(0f, 360f);
                    for (int i = 0; i < limit; i++)
                    {
                        float angle = startAngle + i * (360f / limit);
                        Vector3 offset = Quaternion.Euler(0, angle, 0) * Vector3.forward * SearchAreaPatrolRadius;
                        Vector3 candidate = center + offset;
                        HelperMap.ToGroundPoint(ref candidate);
                        if (Navigator == null || !Navigator.GetNearestNavmeshPosition(candidate, out Vector3 sampled, SearchNavMeshSampleRadius)) continue;
                        if (!allowDeep && IsPointTooDeep(sampled)) continue;
                        _waypointSource[_waypointCount] = "Patrol";
                        _waypoints[_waypointCount++] = sampled;
                    }
                }
                private bool HasUsableWaypoint()
                {
                    for (int i = 0; i < _waypointCount; i++)
                    {
                        int bit = 1 << i;
                        if ((_failedWaypointMask & bit) == 0 && (_visitedWaypointMask & bit) == 0) return true;
                    }
                    return false;
                }
                private bool IsTargetRerouted()
                    => _routedPosition != Vector3.zero && (_targetPosition - _routedPosition).sqrMagnitude > SearchRerouteShiftSqr;
                private void RouteToTarget(string reason)
                {
                    SetTarget(_targetPosition, NavigationSpeed.Normal);
                    _routedPosition = _targetPosition;
                }
                private void MoveToNextWaypoint()
                {
                    if (_waypointCount == 0) return;
                    bool reached = _routedPosition != Vector3.zero && !IsTargetRerouted();
                    if (reached) _visitedWaypointMask |= 1 << _currentIndex;
                    int next = -1;
                    for (int i = reached ? 1 : 0; i <= _waypointCount; i++)
                    {
                        int idx = (_currentIndex + i) % _waypointCount;
                        int bit = 1 << idx;
                        if ((_failedWaypointMask & bit) != 0 || (_visitedWaypointMask & bit) != 0) continue;
                        next = idx;
                        break;
                    }
                    if (next < 0)
                    {
                        _routeExhausted = true;
                        _isScanning = false;
                        _scanProgress = 0f;
                        return;
                    }
                    _currentIndex = next;
                    _targetPosition = _waypoints[_currentIndex];
                    _isScanning = false;
                    _scanProgress = 0f;
                    _scanRestartCount = 0;
                }
                private void StartScanning(float delta)
                {
                    Navigator.ClearFacingDirectionOverride();
                    _scanCenterDirection = Owner.eyes.BodyForward();
                    _isScanning = true;
                    _scanProgress = 0f;
                    UpdateScanDirection();
                    SmoothDirection(delta);
                    _scanRestartCount++;
                }
                private void UpdateScanMode(float delta)
                {
                    _scanProgress = Mathf.Clamp01(_scanProgress + delta / ScanDuration);
                    UpdateScanDirection();
                    SmoothDirection(delta);
                    if (_scanProgress >= 1f) MoveToNextWaypoint();
                }
                private void UpdateRawDirection()
                {
                    _rawTargetDirection = Vector3Ex.Direction2D(_targetPosition, Owner.transform.position).normalized;
                }
                private void UpdateScanDirection()
                {
                    float angleOffset = Mathf.Lerp(-ScanArcAngle, ScanArcAngle, _scanProgress);
                    Quaternion yawOffset = Quaternion.Euler(0f, angleOffset, 0f);
                    Vector3 dir = yawOffset * _scanCenterDirection;
                    dir.y = 0f;
                    _rawTargetDirection = dir.normalized;
                }
                private void SmoothDirection(float delta)
                {
                    _smoothedDirection = Vector3.Slerp(_smoothedDirection, _rawTargetDirection, Mathf.Min(RotationSpeed * delta, 1f)).normalized;
                }
            }

            public class RepositionState : FSM.RouterState
            {
                private const float FirstDelayMin = 1f;
                private const float FirstDelayMax = 2.5f;
                public const float MaxDashTime = 4f;
                private const float FailRetryDelay = 1.5f;
                private const float ScatterWindow = 10f;
                private const float ScatterClearance = 12f;
                private const float ScatterMaxLength = 12f;
                private const float MinEnemyDistance = 6f;
                private const float NavSnapRadius = 2.5f;
                private const float MaxHeightDelta = 2f;
                private const float MaxSlope = 0.35f;
                private const float MaxGroundDrop = 2.5f;
                private const float MaxWaterDepth = 0.4f;
                private const float EyeHeight = 1.6f;
                private const float RunHeight = 1f;
                private static readonly float[] MidAngles = { 0f, 20f, -20f };
                private static readonly float[] CloseAngles = { 40f, 20f, 60f };
                private static readonly float[] FarAngles = { -20f, 0f, -35f };
                private static readonly float[] ScatterAngles = { 0f, 35f, -35f, 70f, -70f };
                private static readonly int ObstacleMask = LayerMask.GetMask("Default", "Deployed", "Construction", "Terrain", "World", "Tree", "Vehicle World", "Vehicle Large", "Vehicle Detailed", "Prevent Movement");
                private static readonly int LineOfFireMask = LayerMask.GetMask("Default", "Deployed", "Construction", "Terrain", "World", "Tree", "Vehicle World", "Vehicle Large", "Vehicle Detailed");
                private static readonly int GroundMask = LayerMask.GetMask("Terrain", "World", "Default", "Construction");

                private float _readyTime;
                private float _retryTime;
                private float _lastEndTime = -999f;
                private bool _scatterChecked;
                private float _scatterRetryAt;
                private bool _failed;
                private bool _done;
                private int _side;
                private Vector3 _target;
                private TimeSince _dashTimer;

                public override string Name => "Reposition";
                protected override float MinStateDwell => CombatFSM.StateDwell;
                protected override BaseEntity GetChaseEnemy => null;
                protected override float MinDistanceMovedEnemyForAddPoint => 0f;
                protected override float RadiusSphere => 1f;
                private BattleFsmState Parent => (ParentFSM as CombatFSM)?.ParentBattle;

                public override bool CanPassHazardTrigger(Vector3 hazardCenter) => false;
                public override bool CanSwimAhead(Vector3 entryPoint, float depth, float distance) => false;

                public void OnBattleEnter()
                {
                    _readyTime = UnityEngine.Time.time + Random.Range(FirstDelayMin, FirstDelayMax);
                    _retryTime = 0f;
                    _lastEndTime = -999f;
                    _scatterChecked = false;
                    _scatterRetryAt = 0f;
                }
                protected override void OnDestroy()
                {
                    _readyTime = 0f;
                    _retryTime = 0f;
                    _lastEndTime = -999f;
                    _scatterChecked = false;
                    _scatterRetryAt = 0f;
                    _failed = false;
                    _done = false;
                    _side = 0;
                    _target = Vector3.zero;
                    base.OnDestroy();
                }
                protected override void EnterState()
                {
                    base.EnterState();
                    _failed = false;
                    _done = false;
                    _dashTimer = 0;
                    BattleFsmState parent = Parent;
                    if (parent != null) parent.WantsCrouch = false;
                    if (_target != Vector3.zero) SetTarget(_target, NavigationSpeed.Fast);
                }
                protected override void LeaveState()
                {
                    float now = UnityEngine.Time.time;
                    _lastEndTime = now;
                    _readyTime = now + (_failed ? FailRetryDelay : Random.Range(BattleFsmState.RepositionIntervalMin, BattleFsmState.RepositionIntervalMax));
                    if (_failed) _retryTime = _readyTime;
                    _target = Vector3.zero;
                    Navigator?.ClearFacingDirectionOverride();
                    base.LeaveState();
                }
                public bool CanScatter()
                {
                    if (_scatterChecked) return false;
                    BattleFsmState parent = Parent;
                    if (parent == null || !Owner.IsValid() || Navigator == null) return false;
                    float now = UnityEngine.Time.time;
                    if (parent.TimerState >= ScatterWindow)
                    {
                        _scatterChecked = true;
                        return false;
                    }
                    if (now < _scatterRetryAt) return false;
                    _scatterRetryAt = now + 1f;
                    if (!parent.UseReposition || !IsShootingEnemy(parent) || Owner.isMounted || Owner.IsInWater) return false;
                    if (!parent.CanChaseEnemy()) return false;
                    if (!FindDismountedVehicle(BattleFsmState.RepositionVehicleRadius, out Vector3 vehiclePos))
                    {
                        _scatterChecked = true;
                        return false;
                    }
                    if (Navigator.IsOnLayerSurface(Owner.transform.position) || !TryPickDash(parent, true, vehiclePos)) return false;
                    _scatterChecked = true;
                    return true;
                }
                protected override bool CanEnterState()
                {
                    BattleFsmState parent = Parent;
                    if (parent == null || !Owner.IsValid() || Navigator == null) return false;
                    float now = UnityEngine.Time.time;
                    if (now < _retryTime) return false;
                    if (now < _readyTime && !(parent.IsUnderFire && now >= _lastEndTime + Mathf.Max(1.5f, BattleFsmState.RepositionIntervalMin * 0.75f))) return false;
                    if (!parent.UseReposition || !parent.WantsArmedCombat || !IsShootingEnemy(parent)) return false;
                    if (Owner.isMounted || Owner.IsInWater) return false;
                    if (!parent.CurrentWeapon || parent.CurrentWeapon.IsMelee) return false;
                    if (!parent.IsEnemyVisibleNow()) return false;
                    if (parent.CurrentEnemy.Distance(Owner) > parent.GetMaxAttackDistance()) return false;
                    if (!parent.CanChaseEnemy()) return false;
                    if (Navigator.IsOnLayerSurface(Owner.transform.position) || !TryPickDash(parent, false, Vector3.zero))
                    {
                        _retryTime = now + FailRetryDelay;
                        return false;
                    }
                    return true;
                }
                protected override FSM.BaseStatePlayerNpc.ResponseFromUpdateState UpdateState(float delta)
                {
                    base.UpdateState(delta);
                    BattleFsmState parent = Parent;
                    if (parent == null || !parent.CurrentEnemy.IsValid() || !Owner.IsValid())
                    {
                        _failed = true;
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                    }
                    if (IsStuck)
                    {
                        ResetStuck();
                        _failed = true;
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                    }
                    if (Owner.IsInWater || modeRouter == FSM.IRouterState.ModeRouter.Idle)
                    {
                        Stop();
                        _failed = true;
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                    }
                    if (modeRouter == FSM.IRouterState.ModeRouter.Finish || (float)_dashTimer > MaxDashTime)
                    {
                        Stop();
                        _done = true;
                        return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    }
                    if (parent.IsEnemyVisibleNow()) Navigator?.SetFacingDirectionEntity(parent.CurrentEnemy.Enemy);
                    else if (parent.HasLastVisible)
                    {
                        Vector3 dir = Vector3Ex.Direction2D(parent.LastVisiblePos, Owner.transform.position);
                        if (dir.sqrMagnitude > 0.001f) Navigator?.SetFacingDirectionOverride(dir);
                    }
                    return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.NONE;
                }
                private static bool IsShootingEnemy(BattleFsmState parent)
                    => parent.CurrentEnemy.IsValid() && parent.CurrentEnemy.TypeEnemy != FSM.IAttackState.TypeEnemy.Animal;
                private bool FindDismountedVehicle(float radius, out Vector3 center)
                {
                    center = Vector3.zero;
                    BaseVehicle vehicle = Owner.LastDismountVehicle;
                    if (radius <= 0f || vehicle == null || vehicle.IsDestroyed) return false;
                    if (UnityEngine.Time.time - Owner.LastDismountTime > ScatterWindow + 10f) return false;
                    center = vehicle.CenterPoint();
                    return (center - Owner.transform.position).sqrMagnitude <= radius * radius;
                }
                private bool TryPickDash(BattleFsmState parent, bool scatter, Vector3 vehiclePos)
                {
                    Vector3 myPos = Owner.transform.position;
                    Vector3 enemyPos = parent.CurrentEnemy.Position;
                    Vector3 enemyEye = parent.CurrentEnemy.CenterPoint;
                    Vector3 toEnemy = enemyPos - myPos;
                    toEnemy.y = 0f;
                    float enemyDist = toEnemy.magnitude;
                    if (enemyDist < 0.1f) return false;
                    toEnemy /= enemyDist;
                    Vector3 right = new Vector3(toEnemy.z, 0f, -toEnemy.x);
                    float fireRange = parent.GetMaxAttackDistance();
                    float minLen = BattleFsmState.RepositionDistanceMin;
                    float maxLen = BattleFsmState.RepositionDistanceMax;
                    float minEnemy = Mathf.Min(MinEnemyDistance, enemyDist);
                    float maxEnemy = Mathf.Max(enemyDist, fireRange * 0.95f);
                    bool onTerrain = Mathf.Abs(myPos.y - TerrainMeta.HeightMap.GetHeight(myPos)) < 1f;

                    Vector3 away = Vector3.zero;
                    float scatterLen = 0f;
                    float[] angles;
                    if (scatter)
                    {
                        away = myPos - vehiclePos;
                        away.y = 0f;
                        float fromVehicle = away.magnitude;
                        away = fromVehicle > 0.1f ? away / fromVehicle : -toEnemy;
                        scatterLen = Mathf.Clamp(ScatterClearance - fromVehicle, minLen, ScatterMaxLength);
                        angles = ScatterAngles;
                    }
                    else
                    {
                        _side = _side == 0 ? (Random.value < 0.5f ? -1 : 1) : (Random.value < 0.75f ? -_side : _side);
                        angles = enemyDist < Mathf.Max(MinEnemyDistance + 2f, fireRange * 0.35f) ? CloseAngles
                            : enemyDist > fireRange * 0.75f ? FarAngles : MidAngles;
                    }

                    Vector3 best1 = Vector3.zero, best2 = Vector3.zero;
                    float score1 = float.MinValue, score2 = float.MinValue;
                    int offMesh = 0, steep = 0, wet = 0, range = 0, blocked = 0, drop = 0;
                    int sides = scatter ? 1 : 2;
                    for (int s = 0; s < sides; s++)
                    {
                        int side = s == 0 ? _side : -_side;
                        for (int a = 0; a < angles.Length; a++)
                        {
                            Vector3 dir;
                            float len;
                            if (scatter)
                            {
                                dir = Quaternion.Euler(0f, angles[a], 0f) * away;
                                len = scatterLen;
                            }
                            else
                            {
                                float rad = angles[a] * Mathf.Deg2Rad;
                                dir = right * (side * Mathf.Cos(rad)) - toEnemy * Mathf.Sin(rad);
                                len = Random.Range(minLen, maxLen);
                            }
                            Vector3 probe = myPos + dir * len;
                            probe.y = onTerrain ? TerrainMeta.HeightMap.GetHeight(probe) : myPos.y;
                            if (!Navigator.GetNearestNavmeshPosition(probe, out Vector3 point, NavSnapRadius)) { offMesh++; continue; }
                            Vector3 flat = point - myPos;
                            flat.y = 0f;
                            float flatLen = flat.magnitude;
                            if (flatLen < minLen * 0.6f) { offMesh++; continue; }
                            if (Mathf.Abs(point.y - myPos.y) > Mathf.Max(MaxHeightDelta, flatLen * MaxSlope)) { steep++; continue; }
                            if (IsPointTooDeep(point, MaxWaterDepth)) { wet++; continue; }
                            float enemyAfter = Vector3.Distance(point, enemyPos);
                            if (enemyAfter < minEnemy || (!scatter && enemyAfter > maxEnemy)) { range++; continue; }
                            if (!IsRunClear(myPos, point)) { blocked++; continue; }
                            if (!IsGroundContinuous(myPos, point)) { drop++; continue; }

                            Vector3 eye = point + Vector3.up * EyeHeight;
                            Vector3 diff = enemyEye - eye;
                            float d = diff.magnitude;
                            bool lineOfFire = d < 0.1f || !Physics.Raycast(eye, diff / d, d, LineOfFireMask, QueryTriggerInteraction.Ignore);
                            float score = scatter
                                ? 1f - Mathf.Abs(angles[a]) / 140f + (lineOfFire ? 0.5f : 0f) - 0.6f * Mathf.Max(0f, Vector3.Dot(dir, toEnemy))
                                : (s == 0 ? 0.4f : 0f) + (a == 0 ? 0.2f : a == 1 ? 0.1f : 0f) + (lineOfFire ? 0.8f : 0f);
                            score += Random.value * 0.15f;
                            if (score > score1)
                            {
                                score2 = score1; best2 = best1;
                                score1 = score; best1 = point;
                            }
                            else if (score > score2)
                            {
                                score2 = score; best2 = point;
                            }
                        }
                    }
                    int noPath = 0;
                    for (int k = 0; k < 2; k++)
                    {
                        Vector3 candidate = k == 0 ? best1 : best2;
                        if (candidate == Vector3.zero) break;
                        if (!Navigator.HasCompleteDryPathTo(candidate)) { noPath++; continue; }
                        _target = candidate;
                        return true;
                    }
                    _target = Vector3.zero;
                    return false;
                }
                private static bool IsRunClear(Vector3 from, Vector3 to)
                {
                    Vector3 a = from + Vector3.up * RunHeight;
                    Vector3 b = to + Vector3.up * RunHeight;
                    Vector3 diff = b - a;
                    float d = diff.magnitude;
                    if (d < 0.1f) return true;
                    return !Physics.SphereCast(a, 0.3f, diff / d, out _, d, ObstacleMask, QueryTriggerInteraction.Ignore);
                }
                private static bool IsGroundContinuous(Vector3 from, Vector3 to)
                {
                    for (int i = 1; i <= 3; i++)
                    {
                        Vector3 p = Vector3.Lerp(from, to, i * 0.25f);
                        if (!Physics.Raycast(p + Vector3.up * 1.5f, Vector3.down, out RaycastHit hit, 1.5f + MaxGroundDrop, GroundMask, QueryTriggerInteraction.Ignore))
                            return false;
                        if (IsPointTooDeep(hit.point, MaxWaterDepth)) return false;
                    }
                    return true;
                }
            }
        }

        public abstract class MinerFsmStateBase : FSM.RouterState
        {
            #region Fields And Properties
            protected float _actionCooldown;
            protected BaseEntity _target;
            protected BaseEntity _pendingTarget;
            protected BaseEntity _strikeTarget;
            protected BaseMelee _strikeMelee;
            protected float _strikePendingTime;
            protected float _nextIdleRetryTime;
            protected Vector3 _lastSuccessPos;
            protected BaseEntity _deferredTarget;
            protected float _nextSmartPickupCheck;
            protected float _lastProgressHealth;
            protected BaseCombatEntity _meleeProgressTarget;
            protected int _hitsWithoutProgress;
            private BaseEntity _reachChecked;
            private float _reachCheckedTime;
            private bool _reachCheckedResult;
            protected Vector3 _approachPoint;

            protected const float AttackDistance = 0.5f;
            protected override float RadiusSphere => 0.3f;
            protected const float MiningCooldown = 0.5f;
            protected const float TargetBlacklistTTL = 900f;
            public virtual float MaxMiningRadius => 30f;
            protected const float ClusterBonusRadius = 20f;
            protected const float HomeBonusRadius = 50f;
            protected const float SmartPickupRadius = 3f;
            protected const float SmartPickupInterval = 0.5f;
            protected virtual bool UseSmartPickup => true;
            protected const int HitsBeforeBailOut = 10;
            protected const float FacingApproachRange = 3f;
            protected bool HasPendingStrike => _strikeMelee != null;
            protected bool IsActionCooldown => UnityEngine.Time.time < _actionCooldown;
            public BaseEntity CurrentMiningTarget => _target;

            public override string Name => "Miner";
            protected override BaseEntity GetChaseEnemy => null;
            protected override float MinDistanceMovedEnemyForAddPoint => 0f;
            #endregion

            #region Override Methods
            protected override void OnDestroy()
            {
                _target = null;
                _pendingTarget = null;
                _strikeTarget = null;
                _strikeMelee = null;
                _actionCooldown = 0f;
                _strikePendingTime = 0f;
                _nextIdleRetryTime = 0f;
                _lastSuccessPos = Vector3.zero;
                _deferredTarget = null;
                _nextSmartPickupCheck = 0f;
                _meleeProgressTarget = null;
                _lastProgressHealth = 0f;
                _hitsWithoutProgress = 0;
                _reachChecked = null;
                _reachCheckedTime = 0f;
                _reachCheckedResult = false;
                _approachPoint = Vector3.zero;
                base.OnDestroy();
            }
            protected override void EnterState()
            {
                base.EnterState();
                _target = _pendingTarget.IsValid() ? _pendingTarget : FindReachableMiningTarget();
                _pendingTarget = null;
                if (_target.IsValid()) GoToTarget(_target);
            }
            protected override void LeaveState()
            {
                _target = null;
                _pendingTarget = null;
                if (Owner.IsValid()) Owner.GetHeldEntity()?.ToggleHeldEntity(false);
                _strikeTarget = null;
                _strikeMelee = null;
                _deferredTarget = null;
                if (Owner.IsValid()) Owner.EquipWeapon(-1);
                Navigator?.ClearFacingDirectionOverride();
                base.LeaveState();
            }
            protected override bool CanEnterState()
            {
                _pendingTarget = null;
                if (!Owner.IsValid() || Owner.IsSwimming() || Owner.IsSafeZone()) return false;
                if (Owner.inventory.containerMain.IsFull()) return false;
                _pendingTarget = FindReachableMiningTarget();
                return _pendingTarget != null;
            }
            protected override FSM.BaseStatePlayerNpc.ResponseFromUpdateState UpdateState(float delta)
            {
                if (Owner.IsSwimming()) return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                if (Owner.IsSafeZone())
                {
                    if (_target.IsValid()) Owner.BlacklistTarget(_target, UnreachableBlacklistTTL);
                    return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                }
                if (HasPendingStrike)
                {
                    if (UnityEngine.Time.time >= _strikePendingTime) ExecuteStrike();
                    return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.NONE;
                }
                if (Owner.inventory.containerMain.IsFull()) return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                base.UpdateState(delta);
                if (!_target.IsValid())
                {
                    if (_deferredTarget.IsValid() && !IsStuckBlacklisted(_deferredTarget) && IsTargetReachable(_deferredTarget))
                    {
                        _target = _deferredTarget;
                        _deferredTarget = null;
                    }
                    else
                    {
                        _deferredTarget = null;
                        _target = FindReachableMiningTarget();
                    }
                    if (!_target.IsValid()) return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                    GoToTarget(_target);
                }
                else if (IsStuck)
                {
                    if (_target.IsValid())
                        Owner?.BlacklistTarget(_target, StuckReasonLatched == StuckReason.SafeZone ? UnreachableBlacklistTTL : TargetBlacklistTTL);
                    _target = null;
                    ResetStuck();
                }
                else if (modeRouter == FSM.IRouterState.ModeRouter.Finish || IsAtApproachPoint())
                {
                    if (!IsActionCooldown) PerformAction(_target);
                }
                else if (modeRouter == FSM.IRouterState.ModeRouter.Idle)
                {
                    if (UnityEngine.Time.time >= _nextIdleRetryTime)
                    {
                        GoToTarget(_target);
                        _nextIdleRetryTime = UnityEngine.Time.time + 1f;
                    }
                }
                if (UseSmartPickup && _target.IsValid() && modeRouter == FSM.IRouterState.ModeRouter.Moved
                    && UnityEngine.Time.time >= _nextSmartPickupCheck)
                {
                    _nextSmartPickupCheck = UnityEngine.Time.time + SmartPickupInterval;
                    BaseEntity nearby = FindSmartPickupTarget();
                    if (nearby.IsValid() && nearby != _target && nearby != _deferredTarget && IsTargetReachable(nearby))
                    {
                        _deferredTarget = _target;
                        _target = nearby;
                        GoToTarget(_target);
                    }
                }
                if (_target.IsValid() && GetDistanceToEdge(_target) <= FacingApproachRange)
                {
                    Vector3 aimDir = GetAimPoint(_target) - Owner.eyes.position;
                    if (aimDir.sqrMagnitude > 0.01f)
                        Navigator?.SetFacingDirectionOverride(aimDir.normalized);
                }
                else
                    Navigator?.ClearFacingDirectionOverride();
                return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.NONE;
            }
            #endregion

            #region Methods
            protected abstract BaseEntity FindMiningTarget();
            protected BaseEntity FindReachableMiningTarget()
            {
                for (int i = 0; i < MaxUnreachableSkips; i++)
                {
                    BaseEntity candidate = FindMiningTarget();
                    if (!candidate.IsValid()) return null;
                    if (IsTargetInSafeZone(candidate))
                    {
                        Owner?.BlacklistTarget(candidate, TargetBlacklistTTL);
                        ResetTargetCache();
                        continue;
                    }
                    if (IsTargetReachable(candidate)) return candidate;
                    Owner?.BlacklistTarget(candidate, UnreachableBlacklistTTL);
                    ResetTargetCache();
                }
                return null;
            }
            protected bool IsTargetReachable(BaseEntity target)
            {
                if (!target.IsValid()) return false;
                if (Navigator == null) return true;
                if (target == _reachChecked && UnityEngine.Time.time < _reachCheckedTime + ReachRecheckInterval)
                    return _reachCheckedResult;
                _reachChecked = target;
                _reachCheckedTime = UnityEngine.Time.time;
                _reachCheckedResult = Navigator.TryNearestWalkable(ApproachGoal(target), GetReachRadius(target), out Vector3 stand)
                                      && Navigator.CanReachPoint(stand);
                return _reachCheckedResult;
            }
            protected virtual void ResetTargetCache() { }
            protected virtual float GetReachRadius(BaseEntity target) => GetActionRange(target);
            protected const int MaxUnreachableSkips = 3;
            protected const float UnreachableBlacklistTTL = 120f;
            protected const float ReachRecheckInterval = 1f;
            protected bool IsStuckBlacklisted(BaseEntity entity)
            {
                return Owner.IsValid() && Owner.IsTargetBlacklisted(entity);
            }
            protected virtual Vector3 GetTargetAnchor(BaseEntity target, Vector3 fromPos)
            {
                if (target is TreeEntity || target is ResourceEntity) return target.transform.position;
                return target.ClosestPoint(fromPos);
            }
            protected virtual Vector3 GetAimPoint(BaseEntity target)
            {
                if (target is TreeEntity || target is ResourceEntity) return target.transform.position + Vector3.up * 1.5f;
                return target.ClosestPoint(Owner.eyes.position);
            }
            protected virtual float GetActionRange(BaseEntity target)
            {
                if (target is TreeEntity || target is ResourceEntity) return 2.0f;
                if (target is LootContainer || target is BaseCorpse) return 1.5f;
                if (target is CollectibleEntity || target is DroppedItem) return 1.5f;
                return Mathf.Max(AttackDistance, 1.0f);
            }
            protected Vector3 GetApproachPosition(BaseEntity target)
            {
                Vector3 goal = ApproachGoal(target);
                if (Navigator != null && Navigator.TryNearestWalkable(goal, GetReachRadius(target), out Vector3 stand))
                    goal = stand;
                return goal;
            }
            private Vector3 ApproachGoal(BaseEntity target)
            {
                if (target is TreeEntity) return GetTreeStandPoint(target);
                if (StandsBesideTarget(target)) return GetSmallTargetStandPoint(target);
                return target.transform.position;
            }
            protected virtual bool StandsBesideTarget(BaseEntity target)
            {
                if (target is CollectibleEntity) return true;
                return target is LootContainer loot && (IsBarrelOrSign(loot) || loot.ShortPrefabName.Contains("trash-pile"));
            }
            protected const float SmallTargetStandGap = 0.5f;
            private const float SmallTargetProbeReach = 4f;
            protected Vector3 GetSmallTargetStandPoint(BaseEntity target)
            {
                Vector3 pivot = target.transform.position;
                Vector3 dir = Owner.transform.position - pivot;
                dir.y = 0f;
                if (dir.sqrMagnitude < 0.01f)
                {
                    dir = Owner.eyes.BodyForward();
                    dir.y = 0f;
                }
                dir = dir.sqrMagnitude < 0.0001f ? Vector3.forward : dir.normalized;
                Vector3 side = target.ClosestPoint(target.CenterPoint() + dir * SmallTargetProbeReach) - pivot;
                side.y = 0f;
                float distance = Mathf.Max(0f, Vector3.Dot(side, dir)) + SmallTargetStandGap;
                Vector3 stand = pivot + dir * distance;
                HelperMap.ToGroundPoint(ref stand);
                return stand;
            }
            protected void GoToTarget(BaseEntity target)
            {
                _approachPoint = GetApproachPosition(target);
                SetTarget(_approachPoint);
            }
            protected const float ApproachArrival = 0.5f;
            protected bool IsAtApproachPoint()
            {
                Vector3 delta = Owner.transform.position - _approachPoint;
                if (Mathf.Abs(delta.y) > 1.8f) return false;
                delta.y = 0f;
                return delta.sqrMagnitude <= ApproachArrival * ApproachArrival;
            }
            protected const float TreeProbeHeight = 1.2f;
            protected const float TreeProbeReach = 4f;
            protected const float TreeStandGap = 0.6f;
            protected const float TreeFallbackOffset = 0.7f;
            protected Vector3 GetTreeStandPoint(BaseEntity tree)
            {
                Vector3 pivot = tree.transform.position;
                Vector3 dir = Owner.transform.position - pivot;
                dir.y = 0f;
                dir = dir.sqrMagnitude < 0.01f ? Owner.eyes.BodyForward() : dir.normalized;
                Vector3 axis = pivot + Vector3.up * Mathf.Clamp(tree.bounds.size.y * 0.5f, 0.3f, TreeProbeHeight);
                float distance = TreeFallbackOffset;
                if (Physics.Raycast(axis + dir * TreeProbeReach, -dir, out RaycastHit hit, TreeProbeReach, Layers.Mask.Tree, QueryTriggerInteraction.Ignore)
                    && hit.GetEntity() == tree)
                {
                    Vector3 surface = hit.point - axis;
                    surface.y = 0f;
                    distance = surface.magnitude + TreeStandGap;
                }
                Vector3 stand = pivot + dir * distance;
                HelperMap.ToGroundPoint(ref stand);
                return stand;
            }
            protected float GetDistanceToEdge(BaseEntity target)
            {
                if (!target.IsValid()) return float.MaxValue;
                Vector3 ownerPos = Owner.transform.position;
                Vector3 anchor = GetTargetAnchor(target, ownerPos);
                return Vector3.Distance(ownerPos, anchor);
            }
            protected virtual bool CanMineWithCurrentTools(BaseEntity entity)
            {
                if (entity is CollectibleEntity || entity is DroppedItem) return true;
                if (entity is LootContainer loot && !IsBarrelOrSign(loot)) return true;
                if (entity is BaseCorpse) return true;
                return FindMeleeSlot(entity) >= 0;
            }
            protected virtual float GetTargetTypeWeight(BaseEntity entity)
            {
                if (entity is CollectibleEntity) return 1.0f;
                if (entity is DroppedItem) return 1.5f;
                if (entity is BaseCorpse) return 1.8f;
                if (entity is LootContainer loot) return IsBarrelOrSign(loot) ? 1.5f : 2.0f;
                if (entity is TreeEntity) return 0.7f;
                if (entity is ResourceEntity) return 0.9f;
                return 0.5f;
            }
            protected virtual float ComputeTargetScore(BaseEntity entity)
            {
                float weight = GetTargetTypeWeight(entity);
                float distance = Owner.Distance(entity);
                float score = weight / (1f + distance / 10f);
                if (_lastSuccessPos != Vector3.zero)
                {
                    float clusterDist = Vector3.Distance(_lastSuccessPos, entity.transform.position);
                    if (clusterDist <= ClusterBonusRadius)
                        score += 0.3f * (1f - clusterDist / ClusterBonusRadius);
                }
                Vector3? home = GetHomePoint();
                if (home.HasValue)
                {
                    float homeDist = Vector3.Distance(home.Value, entity.transform.position);
                    if (homeDist <= HomeBonusRadius)
                        score += 0.2f * (1f - homeDist / HomeBonusRadius);
                }
                float freeFraction = GetFreeInventoryFraction();
                if (freeFraction < 0.3f && (entity is TreeEntity || entity is ResourceEntity))
                    score *= 0.5f;
                if (HasActiveRequired() && MatchesRequired(entity)) score *= 5f;
                return score;
            }
            protected float GetFreeInventoryFraction()
            {
                ItemContainer c = Owner?.inventory?.containerMain;
                if (c == null || c.capacity <= 0) return 1f;
                int used = c.itemList?.Count ?? 0;
                return (float)(c.capacity - used) / c.capacity;
            }
            protected virtual Vector3? GetHomePoint() => null;
            protected virtual BaseEntity FindSmartPickupTarget() => null;
            protected virtual void OnPickupCollectible(CollectibleEntity entity) { }
            protected virtual void OnPickupDropped(DroppedItem entity) { }
            protected virtual void OnLootCorpse(LootableCorpse corpse) { }
            protected virtual void OnLootContainer(LootContainer loot) { }
            protected virtual void OnMiningTree(TreeEntity tree) { }
            protected virtual void OnMiningOre(BaseEntity entity) { }
            protected virtual void OnBreakingBarrel(BaseEntity entity) { }
            protected virtual void OnButcherCorpse(BaseCorpse corpse) { }
            protected virtual bool ShouldButcherCorpse(BaseCorpse corpse) => false;

            protected static bool IsBarrelOrSign(LootContainer loot)
            {
                if (loot == null) return false;
                string name = loot.ShortPrefabName;
                return name.Contains("loot_barrel") || name.Contains("loot-barrel") || name.Contains("oil_barrel") || name.Contains("roadsign") || loot is NaturalBeehive;
            }

            protected int FindKnifeSlot()
            {
                if (Owner?.inventory?.containerBelt == null) return -1;
                for (int i = 0; i < 6; i++)
                {
                    Item item = Owner.inventory.containerBelt.GetSlot(i);
                    if (item?.GetHeldEntity() is BaseMelee && item.info.shortname.Contains("knife")) return i;
                }
                return -1;
            }

            protected int FindMeleeSlot(BaseEntity entity)
            {
                if (Owner?.inventory?.containerBelt == null) return -1;
                bool preferHatchet = entity is TreeEntity || EntityYieldsWood(entity);
                for (int i = 0; i < 6; i++)
                {
                    Item item = Owner.inventory.containerBelt.GetSlot(i);
                    if (item?.GetHeldEntity() is BaseMelee melee && TryFuelTool(melee))
                    {
                        bool isHatchet = item.info.shortname.Contains("hatchet") || item.info.shortname.Contains("chainsaw");
                        bool isPickaxe = item.info.shortname.Contains("pickaxe") || item.info.shortname.Contains("jackhammer");
                        if (preferHatchet && isHatchet) return i;
                        if (!preferHatchet && isPickaxe) return i;
                    }
                }
                for (int i = 0; i < 6; i++)
                {
                    if (Owner.inventory.containerBelt.GetSlot(i)?.GetHeldEntity() is BaseMelee melee && TryFuelTool(melee)) return i;
                }
                return -1;
            }
            protected static bool EntityYieldsWood(BaseEntity entity)
            {
                if (entity is not ResourceEntity res) return false;
                ResourceDispenser disp = res.GetComponent<ResourceDispenser>();
                if (disp == null) return false;
                return ContainsWoodItem(disp.containedItems) || ContainsWoodItem(disp.finishBonus);
            }
            private static bool ContainsWoodItem(List<ItemAmount> items)
            {
                if (items == null) return false;
                for (int i = 0; i < items.Count; i++)
                {
                    if (items[i]?.itemDef != null && items[i].itemDef.shortname == "wood") return true;
                }
                return false;
            }

            protected virtual bool CanActOnTarget(BaseEntity entity) => entity.IsValid() && !IsTargetInSafeZone(entity);
            protected bool IsTargetInSafeZone(BaseEntity entity) => entity.IsValid()
                && HelperSafeZones.IsPointInside(entity.transform.position, HelperSafeZones.DefaultMargin,
                    !Owner.IsValid() || Owner.MonumentTurretsShootWhenHostile);

            protected virtual void PerformAction(BaseEntity entity)
            {
                if (!CanActOnTarget(entity)) { _target = null; return; }
                if (entity is CollectibleEntity collectible)
                {
                    Owner.SignalBroadcast(BaseEntity.Signal.Gesture, "pickup_item", null);
                    collectible.DoPickup(Owner, false);
                    OnPickupCollectible(collectible);
                    _lastSuccessPos = entity.transform.position;
                    _actionCooldown = UnityEngine.Time.time + MiningCooldown;
                    _target = null;
                }
                else if (entity is DroppedItem dropped && dropped.item != null)
                {
                    if (!ShouldTakeItem(dropped.item)) { Owner?.BlacklistTarget(entity, TargetBlacklistTTL); _target = null; return; }
                    Owner.SignalBroadcast(BaseEntity.Signal.Gesture, "pickup_item", null);
                    bool moved = dropped.item.MoveToContainer(Owner.inventory.containerMain);
                    if (!moved) { Owner?.BlacklistTarget(entity, TargetBlacklistTTL); _target = null; return; }
                    OnPickupDropped(dropped);
                    _lastSuccessPos = entity.transform.position;
                    _actionCooldown = UnityEngine.Time.time + MiningCooldown;
                    _target = null;
                }
                else if (entity is BaseCorpse corpse)
                {
                    if (ShouldButcherCorpse(corpse))
                    {
                        int knifeSlot = FindKnifeSlot();
                        if (knifeSlot < 0) { Owner?.BlacklistTarget(entity, TargetBlacklistTTL); _target = null; return; }
                        Owner.EquipWeapon(knifeSlot, false);
                        if (Owner.GetHeldEntity() is BaseMelee knife && !knife.HasAttackCooldown())
                        {
                            InitMeleeAttack(corpse, knife);
                            OnButcherCorpse(corpse);
                        }
                    }
                    else if (corpse is LootableCorpse lootable)
                    {
                        Owner.SignalBroadcast(BaseEntity.Signal.Gesture, "pickup_item", null);
                        bool any = TransferCorpseItems(lootable);
                        if (!any) { Owner?.BlacklistTarget(entity, TargetBlacklistTTL); _target = null; return; }
                        OnLootCorpse(lootable);
                        _lastSuccessPos = entity.transform.position;
                        _actionCooldown = UnityEngine.Time.time + MiningCooldown;
                        _target = null;
                    }
                    else
                    {
                        Owner?.BlacklistTarget(entity, TargetBlacklistTTL);
                        _target = null;
                        return;
                    }
                }
                else if (entity is LootContainer loot && !IsBarrelOrSign(loot))
                {
                    if (loot.inventory == null) { Owner?.BlacklistTarget(entity, TargetBlacklistTTL); _target = null; return; }
                    Owner.SignalBroadcast(BaseEntity.Signal.Gesture, "pickup_item", null);
                    loot.ClientRPC(RpcTarget.NetworkGroup("PickupSound"));
                    bool any = TransferContainerItems(loot.inventory);
                    if (loot.inventory.IsEmpty()) loot.Kill();
                    else if (!any) { Owner?.BlacklistTarget(entity, TargetBlacklistTTL); _target = null; return; }
                    OnLootContainer(loot);
                    _lastSuccessPos = entity.transform.position;
                    _actionCooldown = UnityEngine.Time.time + MiningCooldown;
                    _target = null;
                }
                else
                {
                    int slot = FindMeleeSlot(entity);
                    if (slot < 0) { _target = null; return; }
                    Owner.EquipWeapon(slot, false);
                    if (Owner.GetHeldEntity() is BaseMelee melee && !melee.HasAttackCooldown())
                    {
                        InitMeleeAttack(entity, melee);
                        if (entity is TreeEntity tree) OnMiningTree(tree);
                        else if (entity is LootContainer lc && IsBarrelOrSign(lc)) OnBreakingBarrel(entity);
                        else OnMiningOre(entity);
                    }
                }
            }

            protected virtual bool ConsumesToolFuel(BaseMelee tool) => false;
            protected bool TryFuelTool(BaseMelee tool)
            {
                if (tool is not Chainsaw chainsaw || chainsaw.ammo > 0 || !ConsumesToolFuel(tool)) return true;
                if (chainsaw.fuelType == null || Owner?.inventory == null) return false;
                chainsaw.ammo += Owner.inventory.Take(null, chainsaw.fuelType.itemid, chainsaw.maxAmmo);
                return chainsaw.ammo > 0;
            }
            protected void TickToolFuel(BaseMelee tool)
            {
                if (tool is not Chainsaw chainsaw) return;
                if (chainsaw.ammo > 0) chainsaw.ammo--;
                if (!TryFuelTool(chainsaw)) chainsaw.SetEngineStatus(false, BaseEntity.FlagsUpdateMode.SendNetworkUpdate);
            }
            protected void InitMeleeAttack(BaseEntity target, BaseMelee melee)
            {
                melee.ToggleHeldEntity(true);
                melee.StartAttackCooldown(melee.repeatDelay * 2f);
                Owner.SignalBroadcast(BaseEntity.Signal.Attack, string.Empty);
                if (melee.swingEffect.isValid)
                    Effect.server.Run(melee.swingEffect.resourcePath, Owner.transform.position, Vector3.forward, Owner.net?.connection);
                _strikeTarget = target;
                _strikeMelee = melee;
                _strikePendingTime = UnityEngine.Time.time + melee.aiStrikeDelay;
                if (target is BaseCombatEntity combat)
                {
                    if (_meleeProgressTarget != combat)
                    {
                        _meleeProgressTarget = combat;
                        _lastProgressHealth = combat.Health();
                        _hitsWithoutProgress = 0;
                    }
                }
            }

            protected void ExecuteStrike()
            {
                BaseMelee melee = _strikeMelee;
                BaseEntity target = _strikeTarget;
                _strikeMelee = null;
                _strikeTarget = null;
                if (!target.IsValid() || !melee.IsValid()) return;
                float damage = 0f;
                if (melee.damageTypes != null)
                {
                    for (int i = 0; i < melee.damageTypes.Count; i++) damage += melee.damageTypes[i].amount;
                }
                HitInfo info = Pool.Get<HitInfo>();
                info.Init(Owner, target, DamageType.Slash, damage * melee.npcDamageScale, target.transform.position);
                info.Weapon = melee;
                info.CanGather = true;
                target.OnAttacked(info);
                Pool.Free(ref info);
                HitInfo impact = Pool.Get<HitInfo>();
                impact.HitEntity = target;
                impact.HitPositionWorld = target.CenterPoint();
                impact.HitNormalWorld = -Owner.eyes.BodyForward();
                impact.HitMaterial = StringPool.Get("generic");
                melee.ServerUse_OnHit(impact);
                Effect.server.ImpactEffect(impact);
                Pool.Free(ref impact);
                if (ConsumesToolFuel(melee)) TickToolFuel(melee);
                _lastSuccessPos = target.IsValid() ? target.transform.position : Owner.transform.position;
                if (_meleeProgressTarget.IsValid() && _meleeProgressTarget == target)
                {
                    float nowHealth = _meleeProgressTarget.Health();
                    if (nowHealth < _lastProgressHealth - 0.1f)
                    {
                        _lastProgressHealth = nowHealth;
                        _hitsWithoutProgress = 0;
                    }
                    else
                    {
                        _hitsWithoutProgress++;
                        if (_hitsWithoutProgress >= HitsBeforeBailOut)
                        {
                            Owner?.BlacklistTarget(_meleeProgressTarget, TargetBlacklistTTL);
                            _meleeProgressTarget = null;
                            _hitsWithoutProgress = 0;
                            _target = null;
                        }
                    }
                }
                if (!target.IsValid()) { _target = null; _meleeProgressTarget = null; _hitsWithoutProgress = 0; }
            }

            protected bool TransferContainerItems(ItemContainer from)
            {
                if (from?.itemList == null) return false;
                bool anyMoved = false;
                for (int i = from.itemList.Count - 1; i >= 0; i--)
                {
                    Item item = from.itemList[i];
                    if (item == null) continue;
                    if (!ShouldTakeItem(item)) continue;
                    if (item.MoveToContainer(Owner.inventory.containerMain)) anyMoved = true;
                }
                return anyMoved;
            }

            protected bool TransferCorpseItems(LootableCorpse corpse)
            {
                if (corpse?.containers == null) return false;
                bool anyMoved = false;
                for (int c = 0; c < corpse.containers.Length; c++)
                {
                    ItemContainer container = corpse.containers[c];
                    if (container?.itemList == null) continue;
                    for (int i = container.itemList.Count - 1; i >= 0; i--)
                    {
                        Item item = container.itemList[i];
                        if (item == null) continue;
                        if (!ShouldTakeItem(item)) continue;
                        if (item.MoveToContainer(Owner.inventory.containerMain)) anyMoved = true;
                    }
                }
                return anyMoved;
            }

            protected virtual bool ShouldTakeItem(Item item) => item != null;
            protected virtual bool MatchesRequired(BaseEntity entity) => false;
            protected virtual bool HasActiveRequired() => false;
            #endregion
        }

        public abstract class MetabolismFsmStateBase : FSM.RouterState
        {
            public enum MetabolismDemand { Health, Calories, Hydration }

            #region Fields And Properties
            private const float FleeRecalcInterval = 4f;
            private const float FleeRetryInterval = 0.3f;
            private const float FleeStuckCooldown = 3f;
            private const float FleeFailedDirDot = 0.8f;
            private const float FleeDistance = 50f;
            private static readonly float[] FleeCandidateAngles = { 0f, -30f, 30f, -60f, 60f };
            private const float FleeShortPassMul = 0.5f;
            private const float FleeNavMeshSampleRadius = 5f;
            private const float ScanThreatRangeSq = 2500f;
            private const float ThreatWeightRange = 10f;
            private const float AggressorFreshWindow = 20f;

            private float _fleeRecalcTimer;
            private Vector3 _lastFleeDir;
            private Vector3 _failedFleeDir;
            private float _failedDirCooldown;
            private readonly Dictionary<BaseCombatEntity, float> _lastHitFrom = new();

            protected float _consumeCooldown;
            protected bool IsCooldown => UnityEngine.Time.time < _consumeCooldown;
            private float _lastProgressTime;
            private float _reentryBlockUntil;
            private bool _consumedThisVisit;
            private readonly float[] _demandRetryTime = new float[8];
            private const float DemandRetryInterval = 5f;

            private void MarkDemandUnavailable(MetabolismDemand demand)
            {
                int idx = (int)demand;
                if (idx >= 0 && idx < _demandRetryTime.Length) _demandRetryTime[idx] = UnityEngine.Time.time + DemandRetryInterval;
            }
            private Item _beltSwapVictim;
            private int _beltSwapSlot = -1;
            private int _usableScanNeeds = -1;
            private bool _hasUsableItem;

            public override string Name => "Metabolism";
            protected override BaseEntity GetChaseEnemy => null;
            protected override float MinDistanceMovedEnemyForAddPoint => 0f;
            public override bool YieldsToTurretEscape => false;

            protected virtual float HealHpThreshold => 0.7f;
            protected virtual float HealHpTarget => 0.95f;
            protected const float CaloriesThreshold = 100f;
            protected const float CaloriesTarget = 300f;
            protected const float HydrationThreshold = 100f;
            protected const float HydrationTarget = 150f;
            private const float TargetCeilingMargin = 0.5f;
            protected float EffectiveCaloriesTarget => Owner?.metabolism != null
                ? Mathf.Max(0f, Mathf.Min(CaloriesTarget, Owner.metabolism.GetMaxCalories() - TargetCeilingMargin)) : 0f;
            protected float EffectiveHydrationTarget => Owner?.metabolism != null
                ? Mathf.Max(0f, Mathf.Min(HydrationTarget, Owner.metabolism.hydration.max - TargetCeilingMargin)) : 0f;
            protected const float ConsumeCooldown = 5f;
            protected const float NoOpCooldown = 1f;
            protected const float NoProgressTimeout = 20f;
            protected const float ReentryCooldown = 60f;
            #endregion

            #region Override Methods
            protected override void OnDestroy()
            {
                ResetFleeState();
                _lastHitFrom.Clear();
                _consumeCooldown = 0f;
                _lastProgressTime = 0f;
                _reentryBlockUntil = 0f;
                _consumedThisVisit = false;
                _usableScanNeeds = -1;
                _nextSafeZoneExit = 0f;
                _safeZoneExitVariant = 0;
                _safeZoneExitTarget = Vector3.zero;
                RestoreBeltSwap();
                base.OnDestroy();
            }
            protected override void EnterState()
            {
                base.EnterState();
                _lastProgressTime = UnityEngine.Time.time;
                _consumedThisVisit = false;
                _usableScanNeeds = -1;
                _nextSafeZoneExit = 0f;
                _safeZoneExitVariant = 0;
                _safeZoneExitTarget = Vector3.zero;
                for (int i = 0; i < _demandRetryTime.Length; i++) _demandRetryTime[i] = 0f;
                if (Owner.IsValid()) Owner.EquipWeapon(-1);
                ResetFleeState();
                TryFlee();
                OnFleeEntered();
            }
            protected override void LeaveState()
            {
                if (Owner.IsValid()) Owner.EquipWeapon(-1);
                RestoreBeltSwap();
                Navigator?.ClearFacingDirectionOverride();
                base.LeaveState();
            }
            protected override bool CanEnterState()
            {
                if (UnityEngine.Time.time < _reentryBlockUntil) return false;
                if (!Owner.IsValid() || Owner.IsSwimming()) return false;
                if (NeedsHeal() && HasItemFor(MetabolismDemand.Health)) return true;
                if (NeedsEat() && HasItemFor(MetabolismDemand.Calories)) return true;
                if (NeedsDrink() && HasItemFor(MetabolismDemand.Hydration)) return true;
                return false;
            }
            protected override FSM.BaseStatePlayerNpc.ResponseFromUpdateState UpdateState(float delta)
            {
                if (Owner.IsSwimming())
                {
                    return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                }
                base.UpdateState(delta);
                int needs = (NeedsHealMore() ? 1 : 0) | (NeedsEatMore() ? 2 : 0) | (NeedsDrinkMore() ? 4 : 0);
                if (needs == 0)
                {
                    return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed;
                }
                if (!IsCooldown || needs != _usableScanNeeds)
                {
                    _usableScanNeeds = needs;
                    _hasUsableItem = HasAnyUsableItem();
                }
                if (!_hasUsableItem)
                {
                    bool didSomething = _consumedThisVisit;
                    return didSomething
                        ? FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Completed
                        : FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                }
                if (!IsCooldown)
                {
                    bool ok = TryConsumeBest();
                    if (ok) { _lastProgressTime = UnityEngine.Time.time; _consumedThisVisit = true; _usableScanNeeds = -1; }
                    _consumeCooldown = UnityEngine.Time.time + (ok ? ConsumeCooldown : NoOpCooldown);
                }
                if (NoProgressTimeout > 0 && UnityEngine.Time.time - _lastProgressTime > NoProgressTimeout)
                {
                    _reentryBlockUntil = UnityEngine.Time.time + ReentryCooldown;
                    return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.Failure;
                }
                if (Owner.IsHostile() && (Owner.IsSafeZone() || Owner.IsExposedToMonumentTurret)) UpdateLeaveSafeZone();
                else OnFleeUpdate(delta);
                if (IsStuck) ResetStuck();
                return FSM.BaseStatePlayerNpc.ResponseFromUpdateState.NONE;
            }
            #endregion

            #region Methods
            protected virtual bool NeedsHeal()
            {
                if (Owner == null) return false;
                float max = Owner.MaxHealth();
                return max > 0 && Owner.Health() < max * HealHpThreshold;
            }
            protected virtual bool NeedsEat() => Owner?.metabolism != null && Owner.metabolism.calories.value < CaloriesThreshold;
            protected virtual bool NeedsDrink() => Owner?.metabolism != null && Owner.metabolism.hydration.value < HydrationThreshold;

            protected bool NeedsHealMore()
            {
                if (Owner == null) return false;
                float max = Owner.MaxHealth();
                return max > 0 && Owner.Health() < max * HealHpTarget;
            }
            protected bool NeedsEatMore() => Owner?.metabolism != null && Owner.metabolism.calories.value < EffectiveCaloriesTarget;
            protected bool NeedsDrinkMore() => Owner?.metabolism != null && Owner.metabolism.hydration.value < EffectiveHydrationTarget;

            protected virtual void OnFleeEntered() { }
            protected virtual void OnFleeStuck(Vector3 direction, float cooldown) { }
            protected virtual void OnFleeTarget(Vector3 direction, Vector3 point) { }

            private void ResetFleeState()
            {
                _fleeRecalcTimer = 0f;
                _lastFleeDir = Vector3.zero;
                _failedFleeDir = Vector3.zero;
                _failedDirCooldown = 0f;
            }

            public void NoteAttacker(BaseCombatEntity enemy)
            {
                if (!enemy.IsValid()) return;
                PruneAttackers();
                _lastHitFrom[enemy] = UnityEngine.Time.time;
            }
            protected virtual void OnFleeUpdate(float delta)
            {
                if (IsStuck && _lastFleeDir != Vector3.zero)
                {
                    _failedFleeDir = _lastFleeDir;
                    _failedDirCooldown = UnityEngine.Time.time + FleeStuckCooldown;
                    _lastFleeDir = Vector3.zero;
                    OnFleeStuck(_failedFleeDir, FleeStuckCooldown);
                }
                if (!Owner.IsSafeZone()) TryFlee();
            }
            private void TryFlee()
            {
                if (UnityEngine.Time.time < _fleeRecalcTimer) return;
                Vector3 dir = CalcFleeDirection();
                if (dir == Vector3.zero)
                {
                    _fleeRecalcTimer = UnityEngine.Time.time + FleeRetryInterval;
                    return;
                }
                _fleeRecalcTimer = UnityEngine.Time.time + FleeRecalcInterval;
                if (IsFailedDirection(dir)) return;
                if (dir == _lastFleeDir && modeRouter == FSM.IRouterState.ModeRouter.Moved) return;
                _lastFleeDir = dir;
                if (!PickFleePoint(dir, out Vector3 pos)) return;
                SetTarget(pos, NPCsController.NavigationSpeed.Fast);
                OnFleeTarget(dir, pos);
            }
            private bool PickFleePoint(Vector3 dir, out Vector3 point)
            {
                point = Vector3.zero;
                Vector3 origin = Owner.transform.position;
                Vector3 fallback = Vector3.zero;
                bool avoidSafeZones = Owner.AvoidSafeZonesNow;
                for (int pass = 0; pass < 2; pass++)
                {
                    float distance = pass == 0 ? FleeDistance : FleeDistance * FleeShortPassMul;
                    for (int i = 0; i < FleeCandidateAngles.Length; i++)
                    {
                        Vector3 candidateDir = Quaternion.Euler(0f, FleeCandidateAngles[i], 0f) * dir;
                        Vector3 candidate = origin + candidateDir * distance;
                        HelperMap.ToGroundPoint(ref candidate);
                        if (Navigator == null || !Navigator.GetNearestNavmeshPosition(candidate, out Vector3 sampled, FleeNavMeshSampleRadius)) continue;
                        if (IsPointTooDeep(sampled)) continue;
                        if (avoidSafeZones && HelperSafeZones.IsWayBlocked(origin, sampled)) continue;
                        if (fallback == Vector3.zero) fallback = sampled;
                        if (!Navigator.HasCompletePathTo(sampled, false)) continue;
                        point = sampled;
                        return true;
                    }
                }
                if (fallback != Vector3.zero) { point = fallback; return true; }
                Vector3 raw = origin + dir * FleeDistance;
                HelperMap.ToGroundPoint(ref raw);
                if (avoidSafeZones && HelperSafeZones.IsWayBlocked(origin, raw)) return false;
                point = raw;
                return true;
            }
            private Vector3 CalcFleeDirection()
            {
                Vector3 escape = Vector3.zero;
                Vector3 ownerPos = Owner.transform.position;
                BaseCombatEntity battleEnemy = GetBattleThreat(out Vector3 battlePos);
                if (battlePos != Vector3.zero) AddEscape(ref escape, ownerPos, battlePos, 1f);
                foreach (BaseCombatEntity enemy in Brain.GetNearestEntity<BaseCombatEntity>(e => e.IsValid() && e.IsAlive() && Brain.IsAggressiveFrom(e)))
                {
                    if (enemy == battleEnemy) continue;
                    if (!IsFreshAggressor(enemy)) continue;
                    Vector3 enemyPos = enemy.transform.position;
                    if ((enemyPos - ownerPos).sqrMagnitude > ScanThreatRangeSq) continue;
                    AddEscape(ref escape, ownerPos, enemyPos, 0f);
                }
                escape.y = 0f;
                if (escape.sqrMagnitude < 0.01f) return Vector3.zero;
                return escape.normalized;
            }
            private static void AddEscape(ref Vector3 escape, Vector3 ownerPos, Vector3 threatPos, float minWeight)
            {
                Vector3 dir = threatPos - ownerPos;
                dir.y = 0f;
                float dist = dir.magnitude;
                if (dist < 0.01f) return;
                float weight = Mathf.Max(minWeight, Mathf.Clamp01(ThreatWeightRange / dist));
                escape -= dir / dist * weight;
            }
            protected virtual BaseCombatEntity GetBattleThreat(out Vector3 pos)
            {
                pos = Vector3.zero;
                return null;
            }
            protected static BaseCombatEntity ReadThreat(BattleFsmState battle, ref Vector3 pos)
            {
                if (battle == null || !battle.IsValid) return null;
                if (battle.CurrentEnemy.IsValid())
                {
                    pos = battle.CurrentEnemy.Position;
                    return battle.CurrentEnemy.Enemy;
                }
                if (battle.HasLastVisible && battle.TimeSinceLastHit < AggressorFreshWindow) pos = battle.LastVisiblePos;
                return null;
            }
            private bool IsFreshAggressor(BaseCombatEntity enemy)
            {
                return _lastHitFrom.TryGetValue(enemy, out float last) && UnityEngine.Time.time - last <= AggressorFreshWindow;
            }
            private bool IsFailedDirection(Vector3 dir)
            {
                if (_failedFleeDir == Vector3.zero || UnityEngine.Time.time >= _failedDirCooldown) return false;
                return Vector3.Dot(dir, _failedFleeDir) >= FleeFailedDirDot;
            }
            private void PruneAttackers()
            {
                if (_lastHitFrom.Count == 0) return;
                float now = UnityEngine.Time.time;
                List<BaseCombatEntity> stale = null;
                foreach (var kv in _lastHitFrom)
                    if (now - kv.Value > AggressorFreshWindow || !kv.Key.IsValid()) (stale ??= new List<BaseCombatEntity>()).Add(kv.Key);
                if (stale != null) for (int i = 0; i < stale.Count; i++) _lastHitFrom.Remove(stale[i]);
            }

            private const float SafeZoneExitRecalcInterval = 4f;
            private const float SafeZoneExitMargin = 6f;
            private const float SafeZoneExitSampleRadius = 4f;
            private float _nextSafeZoneExit;
            private int _safeZoneExitVariant;
            private Vector3 _safeZoneExitTarget;

            private void UpdateLeaveSafeZone()
            {
                if (IsStuck)
                {
                    _safeZoneExitVariant++;
                    ResetStuck();
                }
                else if (UnityEngine.Time.time < _nextSafeZoneExit) return;
                _nextSafeZoneExit = UnityEngine.Time.time + SafeZoneExitRecalcInterval;
                Vector3 pos = Owner.transform.position;
                if (!HelperSafeZones.TryGetEscapePoint(pos, out Vector3 exit, SafeZoneExitMargin, _safeZoneExitVariant)) return;
                if (Navigator != null && Navigator.GetNearestNavmeshPosition(exit, out Vector3 onMesh, SafeZoneExitSampleRadius)) exit = onMesh;
                if (modeRouter == FSM.IRouterState.ModeRouter.Moved && (exit - _safeZoneExitTarget).sqrMagnitude < 4f) return;
                _safeZoneExitTarget = exit;
                SetTarget(exit, NavigationSpeed.Fast);
                if (IsStuck)
                {
                    _safeZoneExitVariant++;
                    _nextSafeZoneExit = UnityEngine.Time.time + SafeZoneExitRetryInterval;
                }
            }
            private const float SafeZoneExitRetryInterval = 1f;

            protected bool HasItemFor(MetabolismDemand demand)
            {
                return ScanContainerForDemand(Owner?.inventory?.containerBelt, demand)
                    || ScanContainerForDemand(Owner?.inventory?.containerMain, demand);
            }
            protected bool HasAnyUsableItem()
            {
                return ScanContainerAnyDemand(Owner?.inventory?.containerBelt)
                    || ScanContainerAnyDemand(Owner?.inventory?.containerMain);
            }
            private bool ScanContainerForDemand(ItemContainer container, MetabolismDemand demand)
            {
                if (container?.itemList == null) return false;
                for (int i = 0; i < container.itemList.Count; i++)
                {
                    Item item = container.itemList[i];
                    if (item != null && ItemMatchesDemand(item, demand)) return true;
                }
                return false;
            }
            private bool ScanContainerAnyDemand(ItemContainer container)
            {
                if (container?.itemList == null) return false;
                bool nh = NeedsHealMore(), ne = NeedsEatMore(), nd = NeedsDrinkMore();
                for (int i = 0; i < container.itemList.Count; i++)
                {
                    Item item = container.itemList[i];
                    if (item == null) continue;
                    if (nh && ItemMatchesDemand(item, MetabolismDemand.Health)) return true;
                    if (ne && ItemMatchesDemand(item, MetabolismDemand.Calories)) return true;
                    if (nd && ItemMatchesDemand(item, MetabolismDemand.Hydration)) return true;
                }
                return false;
            }

            protected virtual bool ItemMatchesDemand(Item item, MetabolismDemand demand)
            {
                if (item?.info == null) return false;
                ItemModConsumable consumable = item.info.ItemModConsumable;
                if (consumable == null) return false;
                return consumable.GetIfType(DemandToType(demand)) > 0f;
            }

            protected virtual bool TryConsumeBest()
            {
                if (Owner?.inventory?.containerBelt == null) return false;
                if (NeedsHealMore() && TryUseFor(MetabolismDemand.Health)) return true;
                if (NeedsDrinkMore() && TryUseFor(MetabolismDemand.Hydration)) return true;
                if (NeedsEatMore() && TryUseFor(MetabolismDemand.Calories)) return true;
                return false;
            }

            protected virtual bool TryUseFor(MetabolismDemand demand)
            {
                int demandIdx = (int)demand;
                if (demandIdx >= 0 && demandIdx < _demandRetryTime.Length && UnityEngine.Time.time < _demandRetryTime[demandIdx]) return false;
                if (Owner.metabolism != null && !Owner.metabolism.CanConsume())
                {
                    return false;
                }
                float deficit = GetDeficit(demand);
                if (deficit <= 0f) return false;
                Item bestItem = null;
                float bestAmount = -1f;
                bool bestNeedsBeltMove = false;
                PickBestCandidate(Owner.inventory?.containerBelt, demand, deficit, ref bestItem, ref bestAmount, ref bestNeedsBeltMove, fromBelt: true);
                PickBestCandidate(Owner.inventory?.containerMain, demand, deficit, ref bestItem, ref bestAmount, ref bestNeedsBeltMove, fromBelt: false);
                if (bestItem == null)
                {
                    MarkDemandUnavailable(demand);
                    return false;
                }
                if (bestNeedsBeltMove && !MoveItemToBelt(bestItem))
                {
                    bestItem = null;
                    bestAmount = -1f;
                    bestNeedsBeltMove = false;
                    PickBestCandidate(Owner.inventory?.containerBelt, demand, deficit, ref bestItem, ref bestAmount, ref bestNeedsBeltMove, fromBelt: true, allowBeltMove: false);
                    PickBestCandidate(Owner.inventory?.containerMain, demand, deficit, ref bestItem, ref bestAmount, ref bestNeedsBeltMove, fromBelt: false, allowBeltMove: false);
                    if (bestItem == null)
                    {
                        return false;
                    }
                }
                return UseItemForDemand(bestItem, demand);
            }

            protected virtual float GetDeficit(MetabolismDemand demand)
            {
                if (Owner == null) return 0f;
                return demand switch
                {
                    MetabolismDemand.Health => Mathf.Max(0f, Owner.MaxHealth() * HealHpTarget - Owner.Health()),
                    MetabolismDemand.Calories => Mathf.Max(0f, EffectiveCaloriesTarget - (Owner.metabolism?.calories.value ?? 0f)),
                    MetabolismDemand.Hydration => Mathf.Max(0f, EffectiveHydrationTarget - (Owner.metabolism?.hydration.value ?? 0f)),
                    _ => 0f
                };
            }

            protected virtual float GetItemDemandAmount(Item item, MetabolismDemand demand)
            {
                if (item?.info == null) return 0f;
                ItemModConsumable consumable = item.info.ItemModConsumable;
                if (consumable == null) return 0f;
                return consumable.GetIfType(DemandToType(demand));
            }

            private static MetabolismAttribute.Type DemandToType(MetabolismDemand demand) => demand switch
            {
                MetabolismDemand.Health => MetabolismAttribute.Type.Health,
                MetabolismDemand.Calories => MetabolismAttribute.Type.Calories,
                MetabolismDemand.Hydration => MetabolismAttribute.Type.Hydration,
                _ => MetabolismAttribute.Type.Health
            };

            private void PickBestCandidate(ItemContainer container, MetabolismDemand demand, float deficit,
                ref Item bestItem, ref float bestAmount, ref bool bestNeedsBeltMove, bool fromBelt, bool allowBeltMove = true)
            {
                if (container?.itemList == null) return;
                for (int i = 0; i < container.itemList.Count; i++)
                {
                    Item item = container.itemList[i];
                    if (item == null) continue;
                    if (!ItemMatchesDemand(item, demand)) continue;
                    float amt = GetItemDemandAmount(item, demand);
                    if (amt <= 0f) continue;
                    bool isMedicalTool = item.IsMedicalTool();
                    bool needsBeltMove = isMedicalTool && !fromBelt;
                    if (needsBeltMove && !allowBeltMove) continue;
                    if (!IsBetterCandidate(amt, deficit, bestAmount)) continue;
                    bestItem = item;
                    bestAmount = amt;
                    bestNeedsBeltMove = needsBeltMove;
                }
            }

            private static bool IsBetterCandidate(float amount, float deficit, float currentBest)
            {
                if (currentBest < 0f) return true;
                bool curCovers = currentBest >= deficit;
                bool newCovers = amount >= deficit;
                if (newCovers && !curCovers) return true;
                if (!newCovers && curCovers) return false;
                if (newCovers && curCovers) return amount < currentBest;
                return amount > currentBest;
            }

            protected bool MoveItemToBelt(Item item)
            {
                if (item == null) return false;
                ItemContainer belt = Owner?.inventory?.containerBelt;
                if (belt == null) return false;
                bool moved = item.TryMoveItemToFreeBeltSlot(belt, out int freeSlot);
                if (freeSlot >= 0) return moved;
                if (_beltSwapVictim != null) return false;
                ItemContainer main = Owner?.inventory?.containerMain;
                if (main == null) return false;
                for (int slot = belt.capacity - 1; slot >= 0; slot--)
                {
                    Item victim = belt.GetSlot(slot);
                    if (victim == null || victim.IsMedicalTool()) continue;
                    if (!victim.MoveToContainer(main)) continue;
                    if (item.MoveToContainer(belt, slot))
                    {
                        _beltSwapVictim = victim;
                        _beltSwapSlot = slot;
                        return true;
                    }
                    victim.MoveToContainer(belt, slot);
                    return false;
                }
                return false;
            }

            private void RestoreBeltSwap()
            {
                Item victim = _beltSwapVictim;
                int slot = _beltSwapSlot;
                _beltSwapVictim = null;
                _beltSwapSlot = -1;
                if (victim == null || !victim.IsValid() || victim.parent == null) return;
                ItemContainer belt = Owner?.inventory?.containerBelt;
                ItemContainer main = Owner?.inventory?.containerMain;
                if (belt == null || slot < 0 || slot >= belt.capacity) return;
                Item occupant = belt.GetSlot(slot);
                if (occupant != null && (main == null || !occupant.MoveToContainer(main))) return;
                victim.MoveToContainer(belt, slot);
            }

            private bool UseItemForDemand(Item item, MetabolismDemand demand)
            {
                if (demand == MetabolismDemand.Health && item.IsMedicalTool())
                {
                    Owner.UpdateActiveItem(item.uid);
                    if (Owner.GetHeldEntity() is MedicalTool held && !held.HasAttackCooldown())
                    {
                        held.ServerUse();
                        OnConsumed(demand, item);
                        return true;
                    }
                    return false;
                }
                if (item.info.TryGetComponent<ItemModConsume>(out var modConsume) && modConsume.CanDoAction(item, Owner))
                {
                    modConsume.DoAction(item, Owner);
                    OnConsumed(demand, item);
                    return true;
                }
                return false;
            }

            protected virtual void OnConsumed(MetabolismDemand demand, Item item) { }
            #endregion
        }

        #endregion

    }
    #endregion

