            #region Память опасных мест

            private struct HazardMark
            {
                public Vector3 Pos;
                public float Radius;
                public float Until;
            }
            private const int HazardMemoryCapacity = 8;
            private const float HazardMemoryTtl = 120f;
            private const float HazardMemoryPadding = 1.5f;
            private const float HazardMergeFactor = 0.75f;
            private readonly HazardMark[] _hazardMemory = new HazardMark[HazardMemoryCapacity];
            private int _hazardMemoryCount;

            protected void RememberHazard(Vector3 pos, float radius)
            {
                float now = UnityEngine.Time.time;
                float r = radius + HazardMemoryPadding;
                for(int i = 0; i < _hazardMemoryCount; i++)
                {
                    if((_hazardMemory[i].Pos - pos).sqrMagnitude > Mathf.Pow(Mathf.Max(_hazardMemory[i].Radius, r) * HazardMergeFactor, 2f)) continue;
                    _hazardMemory[i].Pos = Vector3.Lerp(_hazardMemory[i].Pos, pos, 0.5f);
                    _hazardMemory[i].Radius = Mathf.Max(_hazardMemory[i].Radius, r);
                    _hazardMemory[i].Until = now + HazardMemoryTtl;
                    return;
                }
                int slot;
                if(_hazardMemoryCount < HazardMemoryCapacity) slot = _hazardMemoryCount++;
                else
                {
                    slot = 0;
                    for(int i = 1; i < _hazardMemoryCount; i++)
                        if(_hazardMemory[i].Until < _hazardMemory[slot].Until) slot = i;
                }
                _hazardMemory[slot] = new HazardMark { Pos = pos, Radius = r, Until = now + HazardMemoryTtl };
            }

            protected bool IsInsideRememberedHazard(Vector3 pos)
            {
                float now = UnityEngine.Time.time;
                for(int i = 0; i < _hazardMemoryCount; i++)
                {
                    if(_hazardMemory[i].Until <= now) continue;
                    Vector3 d = _hazardMemory[i].Pos - pos; d.y = 0f;
                    if(d.sqrMagnitude <= _hazardMemory[i].Radius * _hazardMemory[i].Radius) return true;
                }
                return false;
            }

            private bool HazardOnSegment(Vector3 from, Vector3 to, out HazardMark hit)
            {
                hit = default;
                float now = UnityEngine.Time.time;
                for(int i = _hazardMemoryCount - 1; i >= 0; i--)
                {
                    if(_hazardMemory[i].Until <= now)
                    {
                        _hazardMemory[i] = _hazardMemory[--_hazardMemoryCount];
                        continue;
                    }
                    if(CoreEx.DistanceFlatToSegment(_hazardMemory[i].Pos, from, to) > _hazardMemory[i].Radius) continue;
                    hit = _hazardMemory[i];
                    return true;
                }
                return false;
            }

            private bool TryDetourAroundHazard(Vector3 from, Vector3 to)
            {
                if(_hazardMemoryCount == 0) return false;
                HazardMark mark = default;
                if(!PathCrossesHazard(_navProbe, from, to, ref mark)) return false;

                Vector3 dir = to - from; dir.y = 0f;
                if(dir.sqrMagnitude < 0.01f) return false;
                dir.Normalize();
                Vector3 side = new Vector3(-dir.z, 0f, dir.x);
                float off = mark.Radius + HazardDetourExtra;
                for(int s = 0; s < 2; s++)
                {
                    Vector3 cand = mark.Pos + (s == 0 ? side : -side) * off;
                    if(!_rustAgent.SamplePositionTyped(cand, out var hit, HazardDetourSampleRadius)) continue;
                    if(HazardOnSegment(from, hit.position, out _) || HazardOnSegment(hit.position, to, out _)) continue;
                    if(!IsDetourLegClear(from, hit.position) || !IsDetourLegClear(hit.position, to)) continue;
                    var detour = PathNode.GetPool(hit.position, NodeHint.NavMesh);
                    detour.IsTransition = true;
                    _path.Insert(_path.CurrentIndex, detour);
                    int prevIdx = _path.CurrentIndex - 1;
                    if(prevIdx >= 0 && _path[prevIdx] != null) _path[prevIdx].Hint |= NodeHint.NavMesh;
                    HaltMovement();
                    return true;
                }
                return false;
            }
            private bool PathCrossesHazard(RustNavMeshPath path, Vector3 from, Vector3 to, ref HazardMark mark)
            {
                var corners = path.corners;
                for(int i = 0; i + 1 < corners.Count; i++)
                    if(HazardOnSegment(_rustAgent.NavToWorldSpace(corners[i]), _rustAgent.NavToWorldSpace(corners[i + 1]), out mark)) return true;
                return corners.Count < 2 && HazardOnSegment(from, to, out mark);
            }
            private bool IsDetourLegClear(Vector3 from, Vector3 to)
            {
                HazardMark mark = default;
                return _rustAgent.CalculatePathTyped(from, to, _navDetourProbe)
                       && _navDetourProbe.status == NavMeshPathStatus.PathComplete
                       && !PathCrossesHazard(_navDetourProbe, from, to, ref mark);
            }
            private const float HazardDetourExtra = 2f;
            private const float HazardDetourSampleRadius = 4f;
            private readonly RustNavMeshPath _navDetourProbe = new RustNavMeshPath();

