            private const float WatchdogBlindWarnAfter = 20f;
            private WatchdogBlindReason _blindReason;
            private float _blindSince;
            private bool _blindWarned;
            private float _lastThinkTime;
            private NavigationType _seenType;
            private float _seenTypeSince;

            public bool SetDestination(Vector3 target, NavigationSpeed speed, float finishArrival = -1f, bool requireFinishLos = false)
            {
                if(_customNpc == null) return false;
                _finishArrival = finishArrival >= 0f ? Mathf.Max(FinishArrivalMin, finishArrival) : ArrivalDistanceDirect;
                _finishRequireLos = requireFinishLos;
                if(_layerPlanActive && _type == NavigationType.Moving && _path != null && _path.CurrentIndex < _path.Count
                   && Vector3.Distance(target, _layerPlanGoal) <= LayerPlanSameGoal)
                {
                    currentSpeedFraction = GetSpeedFraction(speed);
                    return true;
                }
                _watchdogPos = _customNpc.ServerPosition; _watchdogTime = UnityEngine.Time.time;
                OnSetDestination(target);
                currentSpeedFraction = GetSpeedFraction(speed);
                _lastStuckReason = StuckReason.None;
                StartMoved(target, currentSpeedFraction);
                return true;
            }
            public bool HasCompletePathTo(Vector3 target) => HasCompletePathTo(target, true);

            public bool HasCompletePathTo(Vector3 target, bool allowDetour)
            {
                if(_customNpc == null || _rustAgent == null) return false;
                if(!GetNearestNavMeshPosition(_customNpc.ServerPosition, out Vector3 start, NavMeshSnapRadius)) return false;
                return IsPathCompleteChained(start, target, null, out _, maxDetours: allowDetour ? PathChainMaxDetours : 0);
            }

            private const int PathChainMaxSegments = 24;
            private const float PathChainMinGain = 25f;

            private const int PathChainMaxDetours = 3;
            private const int PathDetourDirections = 8;
            private static readonly float[] PathDetourRanges = { 200f, 120f, 60f };
            private const float PathDetourSnapRadius = 10f;
            private const float PathDetourMinEscape = 20f;
            private const int PathDetourMaxPerRoute = 10;
            private const float PathDetourMemoRadius = 5f;

            private readonly RustNavMeshPath _detourProbe = new RustNavMeshPath();
            private int _routeDetourCount;
            private bool _hasFailedDetour;
            private Vector3 _failedDetourStall, _failedDetourTarget;

            private enum PathDetourEnd { Complete, Arrived, Partial }

            private struct PathDetour
            {
                public Vector3 Probe, EscapeTarget, EscapeEnd, ResumeEnd;
                public float Gain;
                public PathDetourEnd End;
            }

            private bool FindPathDetour(Vector3 stall, Vector3 target, RustNavMeshPath buffer, string source,
                                        out PathDetour detour, out int queries)
            {
                detour = default;
                queries = 0;
                bool found = false;
                Vector3 forward = target - stall;
                forward.y = 0f;
                forward = forward.sqrMagnitude > 0.0001f ? forward.normalized : Vector3.forward;
                float initialLeft = Vector3.Distance(stall, target);
                for(int i = 1; i < PathDetourDirections; i++)
                {
                    int step = (i + 1) / 2;
                    if((i & 1) == 0) step = -step;
                    Vector3 direction = Quaternion.AngleAxis(360f * step / PathDetourDirections, Vector3.up) * forward;
                    for(int r = 0; r < PathDetourRanges.Length; r++)
                    {
                        Vector3 probe = stall + direction * PathDetourRanges[r];
                        probe.y = TerrainMeta.HeightMap.GetHeight(probe);
                        if(!_rustAgent.SamplePositionTyped(probe, out var hit, PathDetourSnapRadius)) continue;
                        queries++;
                        if(!_rustAgent.CalculatePathTyped(stall, hit.position, buffer) || buffer.corners.Count == 0) continue;
                        Vector3 escape = _rustAgent.PathEndWorld(buffer, hit.position, out _);
                        if(Vector3Ex.Distance2D(stall, escape) < PathDetourMinEscape) continue;
                        queries++;
                        if(!_rustAgent.CalculatePathTyped(escape, target, buffer)) break;
                        PathDetourEnd end;
                        Vector3 resume;
                        if(buffer.status == NavMeshPathStatus.PathComplete)
                        {
                            end = PathDetourEnd.Complete;
                            resume = target;
                        }
                        else
                        {
                            if(buffer.status != NavMeshPathStatus.PathPartial || buffer.corners.Count == 0) break;
                            resume = _rustAgent.PathEndWorld(buffer, target, out bool copied);
                            if(copied) break;
                            end = Vector3.Distance(resume, target) <= FinishArrivalMin ? PathDetourEnd.Arrived : PathDetourEnd.Partial;
                        }
                        float gain = initialLeft - Vector3.Distance(resume, target);
                        if(end != PathDetourEnd.Partial || (gain >= PathChainMinGain && (!found || gain > detour.Gain)))
                        {
                            detour = new PathDetour
                            {
                                Probe = probe, EscapeTarget = hit.position, EscapeEnd = escape, ResumeEnd = resume,
                                Gain = gain, End = end
                            };
                            found = true;
                        }
                        break;
                    }
                    if(found && detour.End != PathDetourEnd.Partial) break;
                }
                return found;
            }

            private bool TryInsertPathDetour(Vector3 stall, float partialProgress)
            {
                if(_routeDetourCount >= PathDetourMaxPerRoute || _path == null || !_path.HasPath) return false;
                int first = _path.CurrentIndex;
                int targetIndex = first;
                while(targetIndex < _path.Count && _path[targetIndex] != null && _path[targetIndex].IsTransition) targetIndex++;
                if(targetIndex >= _path.Count || _path[targetIndex] == null) return false;
                Vector3 target = _path[targetIndex].Position;
                if(_hasFailedDetour && Vector3.Distance(stall, _failedDetourStall) < PathDetourMemoRadius
                   && Vector3.Distance(target, _failedDetourTarget) < PathDetourMemoRadius) return false;
                if(!FindPathDetour(stall, target, _detourProbe, "walk", out PathDetour detour, out _))
                {
                    _hasFailedDetour = true;
                    _failedDetourStall = stall;
                    _failedDetourTarget = target;
                    return false;
                }
                for(int i = targetIndex - 1; i >= first; i--)
                {
                    var node = _path[i];
                    _path.RemoveAt(i);
                    PathNode.SetPool(ref node);
                }
                var transit = PathNode.GetPool(detour.EscapeEnd, NodeHint.NavMesh);
                transit.IsTransition = true;
                _path.Insert(first, transit);
                _path.CurrentIndex = first;
                int previous = first - 1;
                if(previous >= 0 && _path[previous] != null) _path[previous].Hint |= NodeHint.NavMesh;
                _routeDetourCount++;
                HaltMovement();
                return true;
            }

            private bool IsPathCompleteChained(Vector3 start, Vector3 target, List<Vector3> cornersWorld = null)
                => IsPathCompleteChained(start, target, cornersWorld, out _);

            private readonly RustNavMeshPath _chainProbe = new RustNavMeshPath();

            private bool IsPathCompleteChained(Vector3 start, Vector3 target, List<Vector3> cornersWorld, out int segments,
                                               int maxSegments = PathChainMaxSegments, int maxDetours = PathChainMaxDetours)
            {
                ChainEnd end = ChainPath(start, target, cornersWorld, out segments, out _, maxSegments, maxDetours);
                return end == ChainEnd.Complete || end == ChainEnd.Arrived;
            }

            private enum ChainEnd
            {
                Complete,
                Arrived,
                Gate,
                QueryLimit,
                DeadEnd,
                Failed,
            }

            private ChainEnd ChainPath(Vector3 start, Vector3 target, List<Vector3> cornersWorld, out int segments, out Vector3 reached,
                                       int maxSegments = PathChainMaxSegments, int maxDetours = PathChainMaxDetours)
            {
                cornersWorld?.Clear();
                segments = 0;
                reached = start;
                if(_rustAgent == null) return ChainEnd.Failed;
                Vector3 from = start;
                string end = "query limit";
                ChainEnd result = ChainEnd.QueryLimit;
                int detours = 0;
                for(int ordinary = 0; ordinary < maxSegments; ordinary++)
                {
                    segments++;
                    if(!_rustAgent.CalculatePathTyped(from, target, _chainProbe)) { end = "query failed"; result = ChainEnd.Failed; break; }
                    if(cornersWorld != null) _rustAgent.AddCornersWorld(_chainProbe, cornersWorld);
                    if(_chainProbe.status == NavMeshPathStatus.PathComplete)
                    {
                        end = "complete";
                        result = ChainEnd.Complete;
                        from = target;
                        break;
                    }
                    if(_chainProbe.corners.Count == 0) { end = "no corners"; result = ChainEnd.Failed; break; }
                    Vector3 stop = _rustAgent.PathEndWorld(_chainProbe, target, out bool copiedEnd);
                    if(copiedEnd)
                    {
                        if(cornersWorld != null && cornersWorld.Count > 0) cornersWorld[cornersWorld.Count - 1] = stop;
                        result = ChainEnd.DeadEnd;
                        from = stop;
                        break;
                    }
                    float left = Vector3.Distance(stop, target);
                    if(left <= FinishArrivalMin && !EndsWithSheerDrop(_chainProbe))
                    {
                        result = ChainEnd.Arrived;
                        from = stop;
                        break;
                    }
                    if(left > Vector3.Distance(from, target) - PathChainMinGain)
                    {
                        if(detours < maxDetours)
                        {
                            bool found = FindPathDetour(stop, target, _chainProbe, "chain", out PathDetour detour, out int queries);
                            segments += queries;
                            if(found)
                            {
                                detours++;
                                segments++;
                                if(!_rustAgent.CalculatePathTyped(stop, detour.EscapeTarget, _chainProbe)
                                   || _chainProbe.corners.Count == 0)
                                {
                                    end = "detour escape query failed";
                                    result = ChainEnd.Failed;
                                    from = stop;
                                    break;
                                }
                                if(cornersWorld != null)
                                {
                                    _rustAgent.AddCornersWorld(_chainProbe, cornersWorld);
                                    cornersWorld[cornersWorld.Count - 1] = detour.EscapeEnd;
                                }
                                segments++;
                                if(!_rustAgent.CalculatePathTyped(detour.EscapeEnd, target, _chainProbe)
                                   || _chainProbe.corners.Count == 0)
                                {
                                    end = "detour resume query failed";
                                    result = ChainEnd.Failed;
                                    from = detour.EscapeEnd;
                                    break;
                                }
                                if(cornersWorld != null) _rustAgent.AddCornersWorld(_chainProbe, cornersWorld);
                                from = detour.ResumeEnd;
                                if(detour.End == PathDetourEnd.Complete || detour.End == PathDetourEnd.Arrived)
                                {
                                    end = detour.End == PathDetourEnd.Complete ? "detour complete" : "detour arrived";
                                    result = detour.End == PathDetourEnd.Complete ? ChainEnd.Complete : ChainEnd.Arrived;
                                    break;
                                }
                                continue;
                            }
                        }
                        result = ChainEnd.DeadEnd;
                        from = stop;
                        break;
                    }
                    from = stop;
                }
                reached = from;
                return result;
            }
            private const float SheerDropRise = 1f;

            private bool EndsWithSheerDrop(RustNavMeshPath path)
            {
                if(path?.corners == null || path.corners.Count < 2 || _rustAgent == null) return false;
                Vector3 last = _rustAgent.NavToWorldSpace(path.corners[path.corners.Count - 1]);
                Vector3 prev = _rustAgent.NavToWorldSpace(path.corners[path.corners.Count - 2]);
                float rise = Mathf.Abs(last.y - prev.y);
                return rise > SheerDropRise && rise > Vector3Ex.Distance2D(last, prev) * 1.5f;
            }

            public bool ReachedPosition(Vector3 pos)
            {
                return _customNpc != null && _type == NavigationType.Finish;
            }
            public bool GetNearestNavmeshPosition(Vector3 target, out Vector3 position, float maxRange)
            {
                return GetNearestNavMeshPosition(target, out position, maxRange);
            }
            public bool Warp(Vector3 position)
            {
                if(_customNpc == null) return false;
                bool onNavMesh = GetNearestNavMeshPosition(position, out var snapped, 1f);
                Vector3 finalPos = onNavMesh ? snapped : position;
                BlackBox.NoteWarp(_customNpc, _customNpc.transform.position, finalPos, _lastStuckReason);
                ClearPathAndState();
                _type = NavigationType.None;
                _lastStuckReason = StuckReason.None;
                _customNpc.transform.position = finalPos;
                _customNpc.ServerPosition = finalPos;
                if(_rustAgent != null && onNavMesh) _rustAgent.Warp(finalPos);
                _guard?.Invalidate();
                _warpCount++;
                return onNavMesh;
            }
            private int _warpCount;
            public int WarpCount => _warpCount;
            protected void StartMoved(Vector3 target, float speedFraction)
            {
                ClearPathAndState();
                _nextSafeZoneProbe = 0f;
                bool navStart = GetNearestNavMeshPosition(_customNpc.transform.position, out var start, 1f);
                bool navFinish = GetNearestNavMeshPosition(target, out var finish, NavigatorNpc.FinishSnapRadius);
                if(navStart) _customNpc.transform.position = start;
                PathNode bot_position = PathNode.GetPool(start, navStart ? NodeHint.NavMesh : NodeHint.None);
                PathNode finish_position = PathNode.GetPool(finish, navFinish ? NodeHint.NavMesh : NodeHint.None);
                _path.Add(bot_position);
                _path.Add(finish_position);
                _path.CurrentIndex = 0;

                BuildRoute(start, finish);
                _type = _path.IsFindingPath ? NavigationType.FindingPath : NavigationType.Moving;
                _skipFirstNodeOnReady = true;
            }
            protected void TryBuildOutOfZone(Vector3 start, Vector3 finish)
            {
                bool calcOk = _rustAgent != null && _rustAgent.CalculatePathTyped(start, finish, _navProbe);
                if(calcOk && _navProbe.status == NavMeshPathStatus.PathComplete) return;

                if(calcOk && _navProbe.status == NavMeshPathStatus.PathPartial)
                {
                    var corners = _navProbe.corners;
                    if(corners != null && corners.Count >= 2)
                    {
                        Vector3 lastCorner = _rustAgent.NavToWorldSpace(corners[corners.Count - 1]);
                        _path.Insert(1, PathNode.GetPool(lastCorner, NodeHint.NavMesh));
                        return;
                    }
                }

                if(_rustAgent != null && _rustAgent.SamplePositionTyped(finish, out var hit, 30f))
                {
                    _path.Insert(1, PathNode.GetPool(hit.position, NodeHint.NavMesh));
                }
            }
            protected void HaltMovement()
            {
                if(_isPathJumpActive && _customNpc != null)
                {
                    _customNpc.ServerPosition = _jumpFinish;
                    SetAirborne(false);
                }
                _isPathJumpActive = false;
                _jumpProgress = 0f;
                LandObstacleJump();
                ResetLayerPerStep();
                _climbFacingDir = Vector3.zero;
                _isOnLadderActive = false;
                _navMeshStepDispatched = false;
                _navMeshPartialLeg = false;
                _navLegCorners.Clear();
                _navLegIdx = 0;
                _directNode = null;
            }

