            private bool SameLayerRouteWalked(LayerSearchState state, Vector3 goal, out Vector3 walkedFrom)
            {
                walkedFrom = Vector3.zero;
                for(int i = 0; i < _searchWalked.Count; i++)
                {
                    var walk = _searchWalked[i];
                    if(walk.Layer != state.Layer || walk.Handle != state.Handle) continue;
                    if((walk.Goal - goal).sqrMagnitude > LayerSearchGoalSnap * LayerSearchGoalSnap) continue;
                    if(Mathf.Abs(walk.Enter.y - state.Enter.y) > LayerSearchVisitRise) continue;
                    if(Vector3Ex.Distance2D(walk.Enter, state.Enter) > LayerSearchSameRouteRadius) continue;
                    walkedFrom = walk.Enter;
                    return true;
                }
                return false;
            }

            private bool IsSearchVisited(HelperNavLayers.INavLayer layer, object handle, Vector3 enter)
            {
                Vector3Int cell = LayerSearchCell(enter, IsAgentLayer(layer));
                for(int i = 0; i < _searchVisited.Count; i++)
                {
                    var visit = _searchVisited[i];
                    if(visit.Layer == layer && visit.Handle == handle && visit.Cell == cell) return true;
                }
                return false;
            }

            protected HelperNavLayers.WorldNavLayer WorldLayer()
            {
                if(_worldLayer == null) _worldLayer = new HelperNavLayers.WorldNavLayer(_navProbe);
                _worldLayer.Agent = _rustAgent;
                return _worldLayer;
            }

            protected bool TryBuildLayeredRoute(Vector3 from, Vector3 to, int insertAt, out Vector3 stopWorld,
                                                NavLayerInsert mode = NavLayerInsert.MidRoute)
            {
                stopWorld = from;
                if(_path == null || _rustAgent == null) return false;
                Vector3Int fromCell = LayerPlanCell(from), toCell = LayerPlanCell(to);
                if(UnityEngine.Time.time < _layerPlanFailUntil && fromCell == _layerPlanFailFrom && toCell == _layerPlanFailTo)
                {
                    if(!_layerPlanFailLogged)
                    {
                        _layerPlanFailLogged = true;
                    }
                    return false;
                }
                if(PlanLayeredRoute(from, to, insertAt, mode, out stopWorld, out bool searchFailed)) return true;
                if(searchFailed)
                {
                    _layerPlanFailFrom = fromCell;
                    _layerPlanFailTo = toCell;
                    _layerPlanFailUntil = UnityEngine.Time.time + LayerPlanRetryDelay;
                    _layerPlanFailLogged = false;
                }
                return false;
            }

            private bool WorldLeads(Vector3 from, Vector3 to, float minGain, out HelperSavedNavMesh.NavPathResult result, out Vector3 stop,
                                    bool goalIsFinal = true)
            {
                result = WorldLayer().Route(_rustAgent, from, to, null, out stop, out _);
                if(result == HelperSavedNavMesh.NavPathResult.Complete)
                {
                    if(!CrossesMonumentGate(out Vector3 gate)) return true;
                    result = HelperSavedNavMesh.NavPathResult.Partial;
                    stop = gate;
                    return false;
                }
                if(result != HelperSavedNavMesh.NavPathResult.Partial) return false;
                float left = Vector3Ex.Distance2D(stop, to);
                if(goalIsFinal && left <= HandoverUnderGoalRadius && Mathf.Abs(stop.y - to.y) > HandoverUnderGoalRise) return false;
                return Vector3Ex.Distance2D(from, to) - left >= minGain;
            }

            private readonly List<Vector3> _gateProbe = new List<Vector3>();

            private bool WorldPathLeads(Vector3 from, Vector3 to)
            {
                if(!IsPathCompleteChained(from, to, _gateProbe)) return false;
                var store = HelperSavedNavMesh.Instance;
                return store == null || !HelperSavedNavMesh.UseInNavigator || !store.CrossesGate(_gateProbe, out _);
            }

            private bool ChainWorldLeg(Vector3 stop, Vector3 goal, ref int queries, out ChainEnd end, out Vector3 reached)
            {
                end = ChainWorldPath(stop, goal, Mathf.Min(PathChainMaxSegments, LayerSearchMaxQueries - queries),
                                     out int segments, out reached);
                queries += segments;
                return end == ChainEnd.Complete || end == ChainEnd.Arrived;
            }

            private ChainEnd ChainWorldPath(Vector3 from, Vector3 goal, int maxSegments, out int segments, out Vector3 reached)
            {
                ChainEnd end = ChainPath(from, goal, _gateProbe, out segments, out reached, maxSegments, 0);
                if(end != ChainEnd.Complete && end != ChainEnd.Arrived) return end;
                var store = HelperSavedNavMesh.Instance;
                if(store == null || !HelperSavedNavMesh.UseInNavigator || !store.CrossesGate(_gateProbe, out Vector3 gate)) return end;
                reached = gate;
                return ChainEnd.Gate;
            }

            private bool CrossesMonumentGate(out Vector3 gate)
            {
                gate = Vector3.zero;
                var store = HelperSavedNavMesh.Instance;
                if(store == null || !HelperSavedNavMesh.UseInNavigator || _rustAgent == null) return false;
                _gateProbe.Clear();
                _rustAgent.AddCornersWorld(_navProbe, _gateProbe);
                return store.CrossesGate(_gateProbe, out gate);
            }

            private void CloseLayerPlan(LayerPlanOutcome outcome)
            {
                if(!_layerPlanActive) return;
                _layerPlanActive = false;
            }

            private enum LayerPlanOutcome
            {
                Arrived,
                Stuck,
                Reset,
                Replaced,
            }

            private static Vector3Int LayerPlanCell(Vector3 point)
                => new Vector3Int(Mathf.FloorToInt(point.x / LayerPlanFailCell), Mathf.FloorToInt(point.y / LayerPlanFailCell), Mathf.FloorToInt(point.z / LayerPlanFailCell));

            private bool PlanLayeredRoute(Vector3 from, Vector3 to, int insertAt, NavLayerInsert mode, out Vector3 stopWorld, out bool searchFailed)
            {
                stopWorld = from;
                searchFailed = false;
                if((to - from).sqrMagnitude <= HandoverAnchorRadius * HandoverAnchorRadius) return false;
                if(mode == NavLayerInsert.MidRoute)
                {
                    if(!_path.HasPath) return false;
                    if(_savedNavInsertCount >= MaxNavLayerInsertsPerRoute)
                    {
                        return false;
                    }
                }
                insertAt = Mathf.Clamp(insertAt, 1, _path.Count);

                bool fromOnWorld = OnWorldMesh(from, out Vector3 fromWorld);
                bool toOnWorld = OnWorldMesh(to, out Vector3 toWorld);
                if(fromOnWorld && toOnWorld && WorldPathLeads(fromWorld, toWorld)) return false;

                if(!SearchLayeredRoute(from, to, acceptPartial: true))
                {
                    searchFailed = true;
                    return false;
                }

                if(_searchLegs.Count == 1 && _searchLegs[0].Agent && !_searchStartRescue) return false;

                bool partialRoute = _searchPartial;
                if(CommitSearchLegs(mode, insertAt, to, out stopWorld)) return true;
                if(partialRoute) searchFailed = true;
                return false;
            }

            private bool SearchLayeredRoute(Vector3 from, Vector3 to, bool acceptPartial = false)
            {
                _searchCount = 0;
                _searchVisited.Clear();
                _searchWalked.Clear();
                _searchLegs.Clear();
                _searchPartial = false;
                _searchStartRescue = false;
                if(_rustAgent == null) return false;

                bool toOnWorld = OnWorldMesh(to, out _);
                var goalSpot = SurfaceLayerAt(to, out var goalArea);
                if(!toOnWorld && !goalSpot.IsValid)
                {
                    return false;
                }

                int layers = LayerCount();
                for(int i = 0; i < layers; i++)
                {
                    var layer = LayerByIndex(i);
                    if(layer == null || !layer.Enabled) continue;
                    if(!SurfaceOf(layer, from, out object handle, out Vector3 onMesh)) continue;
                    TryAddSearchState(-1, layer, handle, onMesh, from, 0f);
                }
                if(_searchCount == 0)
                {
                    RescueLayeredStart(from, layers);
                    _searchStartRescue = _searchCount > 0;
                }
                if(_searchCount == 0)
                {
                    return false;
                }

                int expansions = 0, queries = 0;
                var bestPartial = new LayerPartial { Index = -1, Left = float.MaxValue };
                float startLeft = Vector3.Distance(from, to);
                int exitRoot = -1;
                Vector3 exitTried = Vector3.zero;
                bool exitsDone = false;
                bool entriesDone = false;
                while(expansions < LayerSearchMaxExpansions && queries < LayerSearchMaxQueries)
                {
                    int best = -1;
                    float bestScore = float.MaxValue;
                    for(int i = 0; i < _searchCount; i++)
                    {
                        var candidate = _searchStates[i];
                        if(!candidate.Open) continue;
                        float score = candidate.Cost + LayerSearchGoalWeight * Vector3.Distance(candidate.Enter, to);
                        if(score >= bestScore) continue;
                        bestScore = score;
                        best = i;
                    }
                    if(best < 0)
                    {
                        if(bestPartial.Index >= 0 && !ChainStopped(bestPartial.End)) break;
                        int worldBranches = CountAgentStates();
                        string reason = worldBranches > 0
                            ? $"no open branches left, all {worldBranches} game navmesh branches are dead ends"
                            : "no open branches left, no game navmesh branch";
                        if(!exitsDone && exitRoot >= 0)
                        {
                            exitsDone = true;
                            if(ExpandTowardBuildingExits(exitRoot, _searchStates[exitRoot], to, exitTried, reason, ref queries) > 0) continue;
                        }
                        if(!entriesDone && goalSpot.Handle is HelperBuildingNavMesh.BuildingNav)
                        {
                            entriesDone = true;
                            if(ExpandTowardBuildingEntries(goalSpot, to, reason, ref queries) > 0) continue;
                        }
                        break;
                    }

                    var state = _searchStates[best];
                    state.Open = false;
                    bool agentLeg = IsAgentLayer(state.Layer);

                    bool goalHere = state.Layer.Sample(state.Handle, to, out Vector3 goalOnLayer)
                                    && (goalOnLayer - to).sqrMagnitude <= LayerSearchGoalSnap * LayerSearchGoalSnap;
                    if(!goalHere && !state.Layer.TryNearestSurface(state.Handle, to, out goalOnLayer))
                    {
                        continue;
                    }
                    bool wantsExits = WantsBuildingExits(state, goalHere);
                    if(wantsExits && exitRoot < 0)
                    {
                        exitRoot = best;
                        exitTried = goalOnLayer;
                    }
                    if((goalOnLayer - state.Enter).sqrMagnitude <= HandoverAnchorRadius * HandoverAnchorRadius && !goalHere)
                    {
                        if(wantsExits && !exitsDone)
                        {
                            exitsDone = true;
                            ExpandTowardBuildingExits(best, state, to, goalOnLayer, "ends where the bot entered it", ref queries);
                        }
                        continue;
                    }
                    if(!agentLeg && SameLayerRouteWalked(state, goalOnLayer, out Vector3 walkedFrom))
                    {
                        continue;
                    }

                    expansions++;
                    queries++;
                    var result = state.Layer.Route(state.Handle, state.Enter, goalOnLayer,
                                                   agentLeg ? null : _navLayerSteps, out Vector3 stop, out string error);
                    if(!agentLeg && result == HelperSavedNavMesh.NavPathResult.Complete)
                        _searchWalked.Add(new LayerWalk { Layer = state.Layer, Handle = state.Handle, Enter = state.Enter, Goal = goalOnLayer });
                    if(agentLeg && result == HelperSavedNavMesh.NavPathResult.Complete && CrossesMonumentGate(out Vector3 gate))
                    {
                        result = HelperSavedNavMesh.NavPathResult.Partial;
                        stop = gate;
                    }
                    if(result == HelperSavedNavMesh.NavPathResult.None)
                    {
                        if(wantsExits && !exitsDone)
                        {
                            exitsDone = true;
                            ExpandTowardBuildingExits(best, state, to, goalOnLayer, "no route there", ref queries);
                        }
                        continue;
                    }
                    bool chained = false, chainTried = false;
                    ChainEnd chainEnd = ChainEnd.QueryLimit;
                    Vector3 chainReached = stop;
                    int chainQueries = 0;
                    if(agentLeg && result == HelperSavedNavMesh.NavPathResult.Partial
                       && Vector3.Distance(state.Enter, goalOnLayer) - Vector3.Distance(stop, goalOnLayer) >= PathChainMinGain
                       && queries < LayerSearchMaxQueries)
                    {
                        chainTried = true;
                        int queriesBefore = queries;
                        chained = ChainWorldLeg(stop, goalOnLayer, ref queries, out chainEnd, out chainReached);
                        chainQueries = queries - queriesBefore;
                    }
                    if(chained)
                    {
                        result = HelperSavedNavMesh.NavPathResult.Complete;
                        stop = goalOnLayer;
                    }
                    if(goalHere && result == HelperSavedNavMesh.NavPathResult.Complete)
                    {
                        BuildSearchLegs(best, goalOnLayer);
                        return true;
                    }

                    if(acceptPartial && agentLeg && result == HelperSavedNavMesh.NavPathResult.Partial && HasLayerAncestor(best))
                    {
                        Vector3 reach = chainTried ? chainReached : stop;
                        float left = Vector3.Distance(reach, to);
                        if(Vector3.Distance(state.Enter, to) - left >= PathChainMinGain && left < bestPartial.Left
                           && startLeft - left >= LayerPartialMinGain)
                        {
                            bool cut = !chainTried || (chainEnd == ChainEnd.QueryLimit && chainQueries < PathChainMaxSegments);
                            bestPartial = new LayerPartial
                            {
                                Index = best,
                                Goal = goalOnLayer,
                                ChainFrom = reach,
                                ChainLeft = cut ? PathChainMaxSegments - chainQueries : 0,
                                ChainQueries = chainQueries,
                                End = chainEnd,
                                Left = left,
                            };
                        }
                    }

                    float gain = Vector3.Distance(state.Enter, to) - Vector3.Distance(stop, to);
                    if(agentLeg && result != HelperSavedNavMesh.NavPathResult.Complete && gain < HandoverMinWorldGain)
                    {
                        continue;
                    }

                    int points = CollectSearchPoints(agentLeg, chained ? _chainProbe : _navProbe) ? _handoverPoints.Count : 0;
                    int probes = 0, added = 0, statesBefore = _searchCount;
                    float walkedBefore = chained && points > 0 ? Vector3.Distance(state.Enter, _handoverPoints[0]) : 0f;
                    if(points > 0) added = ProbeRouteForTransitions(best, state, to, walkedBefore, ref queries, out probes);

                    if(wantsExits && !exitsDone && !HasAgentStateFrom(statesBefore))
                    {
                        exitsDone = true;
                        ExpandTowardBuildingExits(best, state, to, goalOnLayer, $"route {result}, no game navmesh branch", ref queries);
                    }
                }

                if(bestPartial.Index >= 0 && TakePartialRoute(ref bestPartial, to, ref queries))
                {
                    _searchPartial = true;
                    return true;
                }

                return false;
            }

            private bool TakePartialRoute(ref LayerPartial candidate, Vector3 to, ref int queries)
            {
                if(candidate.ChainLeft > 0)
                {
                    candidate.End = ChainWorldPath(candidate.ChainFrom, candidate.Goal, candidate.ChainLeft, out int segments, out Vector3 reached);
                    candidate.ChainQueries += segments;
                    candidate.ChainLeft = 0;
                    queries += segments;
                    candidate.Left = Vector3.Distance(reached, to);
                }
                BuildSearchLegs(candidate.Index, candidate.Goal);
                if(_searchLegs.Count >= 2) return true;
                _searchLegs.Clear();
                return false;
            }

            private static bool ChainStopped(ChainEnd end) => end == ChainEnd.DeadEnd || end == ChainEnd.Failed;

            private bool HasLayerAncestor(int index)
            {
                for(int i = _searchStates[index].Parent; i >= 0; i = _searchStates[i].Parent)
                    if(!IsAgentLayer(_searchStates[i].Layer)) return true;
                return false;
            }

            private static bool WantsBuildingExits(LayerSearchState state, bool goalHere)
                => !goalHere && state.Parent < 0 && state.Handle is HelperBuildingNavMesh.BuildingNav;

            private bool HasAgentStateFrom(int first)
            {
                for(int i = first; i < _searchCount; i++)
                    if(IsAgentLayer(_searchStates[i].Layer)) return true;
                return false;
            }

            private int CountAgentStates()
            {
                int count = 0;
                for(int i = 0; i < _searchCount; i++)
                    if(IsAgentLayer(_searchStates[i].Layer)) count++;
                return count;
            }

            private int ExpandTowardBuildingExits(int parent, LayerSearchState state, Vector3 to, Vector3 tried, string first, ref int queries)
            {
                var nav = (HelperBuildingNavMesh.BuildingNav)state.Handle;
                var exits = HelperBuildingNavMesh.Instance.GroundExits(nav);
                _exitPending.Clear();
                for(int i = 0; i < exits.Count; i++)
                {
                    Vector3 exit = exits[i];
                    if((exit - tried).sqrMagnitude <= LayerSearchGoalSnap * LayerSearchGoalSnap) continue;
                    if((exit - state.Enter).sqrMagnitude <= HandoverAnchorRadius * HandoverAnchorRadius) continue;
                    _exitPending.Add(exit);
                }

                int added = 0, tries = 0, skipped = 0;
                bool leadsOut = false;
                while(!leadsOut && tries < LayerSearchMaxExitTries && _exitPending.Count > 0
                      && queries < LayerSearchMaxQueries && _searchCount < LayerSearchMaxStates)
                {
                    int pick = 0;
                    float pickDistance = Vector3Ex.Distance2D(_exitPending[0], to);
                    for(int i = 1; i < _exitPending.Count; i++)
                    {
                        float distance = Vector3Ex.Distance2D(_exitPending[i], to);
                        if(distance >= pickDistance) continue;
                        pickDistance = distance;
                        pick = i;
                    }
                    Vector3 exit = _exitPending[pick];
                    _exitPending[pick] = _exitPending[_exitPending.Count - 1];
                    _exitPending.RemoveAt(_exitPending.Count - 1);
                    tries++;

                    int statesBefore = _searchCount, probes = 0;
                    queries++;
                    var result = state.Layer.Route(state.Handle, state.Enter, exit, _navLayerSteps, out Vector3 stop, out string error);
                    if(result != HelperSavedNavMesh.NavPathResult.None && CollectSearchPoints(false, null))
                        added += ProbeRouteForTransitions(parent, state, to, 0f, ref queries, out probes);
                    leadsOut = HasAgentStateFrom(statesBefore);
                    if(!leadsOut)
                        for(int i = _exitPending.Count - 1; i >= 0; i--)
                        {
                            if(Vector3Ex.Distance2D(_exitPending[i], exit) > LayerSearchExitFailRadius) continue;
                            _exitPending[i] = _exitPending[_exitPending.Count - 1];
                            _exitPending.RemoveAt(_exitPending.Count - 1);
                            skipped++;
                        }
                }

                return added;
            }

            private int ExpandTowardBuildingEntries(LayerSpot goalSpot, Vector3 to, string first, ref int queries)
            {
                var nav = (HelperBuildingNavMesh.BuildingNav)goalSpot.Handle;
                var layer = goalSpot.Layer;
                var world = WorldLayer();
                int root = -1;
                for(int i = 0; i < _searchCount; i++)
                {
                    if(_searchStates[i].Parent >= 0 || !IsAgentLayer(_searchStates[i].Layer)) continue;
                    root = i;
                    break;
                }
                var exits = HelperBuildingNavMesh.Instance.GroundExits(nav);
                bool goalOnLayer = layer.Sample(nav, to, out Vector3 goal)
                                   && (goal - to).sqrMagnitude <= LayerSearchGoalSnap * LayerSearchGoalSnap;

                _exitText.Clear();
                _exitPending.Clear();
                int added = 0, tries = 0, skipped = 0;
                if(root >= 0 && goalOnLayer)
                    for(int i = 0; i < exits.Count; i++) _exitPending.Add(exits[i]);
                while(added == 0 && tries < LayerSearchMaxExitTries && _exitPending.Count > 0
                      && queries < LayerSearchMaxQueries && _searchCount < LayerSearchMaxStates)
                {
                    int pick = 0;
                    float pickDistance = Vector3Ex.Distance2D(_exitPending[0], to);
                    for(int i = 1; i < _exitPending.Count; i++)
                    {
                        float distance = Vector3Ex.Distance2D(_exitPending[i], to);
                        if(distance >= pickDistance) continue;
                        pickDistance = distance;
                        pick = i;
                    }
                    Vector3 exit = _exitPending[pick];
                    _exitPending[pick] = _exitPending[_exitPending.Count - 1];
                    _exitPending.RemoveAt(_exitPending.Count - 1);
                    tries++;

                    queries++;
                    var inside = layer.Route(nav, exit, goal, _navLayerSteps, out Vector3 stop, out string error);
                    if(inside != HelperSavedNavMesh.NavPathResult.Complete)
                    {
                    }
                    else if(!OnWorldMesh(exit, out Vector3 exitWorld)) _exitText.Append("no game navmesh at it");
                    else
                    {
                        var rootState = _searchStates[root];
                        queries++;
                        var outside = world.Route(world.Agent, rootState.Enter, exitWorld, null, out Vector3 worldStop, out _);
                        bool reaches = outside == HelperSavedNavMesh.NavPathResult.Complete && !CrossesMonumentGate(out _);
                        string chainNote = "";
                        if(!reaches && outside == HelperSavedNavMesh.NavPathResult.Partial
                           && Vector3.Distance(rootState.Enter, exitWorld) - Vector3.Distance(worldStop, exitWorld) >= PathChainMinGain
                           && queries < LayerSearchMaxQueries)
                        {
                            int queriesBefore = queries;
                            reaches = ChainWorldLeg(worldStop, exitWorld, ref queries, out ChainEnd chainEnd, out Vector3 chainReached);
                            chainNote = $", chain {chainEnd} after {queries - queriesBefore} queries, reached {chainReached.ToString("0.0")}";
                        }
                        if(!reaches)
                            _exitText.Append("game navmesh from ").Append(rootState.Enter.ToString("0.0")).Append(' ').Append(outside)
                                     .Append(" break ").Append(worldStop.ToString("0.0")).Append(chainNote);
                        else if(!TryAddSearchState(root, layer, nav, exit, exitWorld,
                                                   rootState.Cost + Vector3.Distance(rootState.Enter, exitWorld) + LayerSearchSwitchPenalty))
                            _exitText.Append("house reached, spot already taken");
                        else
                        {
                            added++;
                            _exitText.Append("house and game navmesh lead there").Append(chainNote).Append(", entry taken");
                        }
                    }
                    if(added > 0) break;
                    for(int i = _exitPending.Count - 1; i >= 0; i--)
                    {
                        if(Vector3Ex.Distance2D(_exitPending[i], exit) > LayerSearchExitFailRadius) continue;
                        _exitPending[i] = _exitPending[_exitPending.Count - 1];
                        _exitPending.RemoveAt(_exitPending.Count - 1);
                        skipped++;
                    }
                }

                return added;
            }

            private int ProbeRouteForTransitions(int parent, LayerSearchState state, Vector3 to, float walkedBefore, ref int queries, out int probes)
            {
                probes = 0;
                int added = 0, worldChecks = 0;
                _searchCandidates.Clear();
                if(_handoverPoints.Count == 0) return 0;
                int layers = LayerCount();
                Vector3 previous = _handoverPoints[0];
                float walked = walkedBefore, lastProbe = float.NegativeInfinity;
                for(int i = 0; i < _handoverPoints.Count; i++)
                {
                    Vector3 point = _handoverPoints[i];
                    walked += Vector3.Distance(previous, point);
                    previous = point;
                    bool key = i == _handoverPoints.Count - 1 || (i < _handoverKey.Count && _handoverKey[i]);
                    if(!key && walked - lastProbe < LayerSearchProbeSpacing) continue;
                    if(!key && probes >= LayerSearchMaxProbes) continue;
                    lastProbe = walked;
                    probes++;
                    for(int k = 0; k < layers; k++)
                    {
                        var layer = LayerByIndex(k);
                        if(layer == null || !layer.Enabled) continue;
                        if(!SurfaceOf(layer, point, out object handle, out Vector3 onMesh)) continue;
                        if(layer == state.Layer && handle == state.Handle) continue;
                        if(IsAgentLayer(layer))
                        {
                            Vector3Int cell = LayerSearchCell(onMesh, true);
                            bool edge = i == _handoverPoints.Count - 1;
                            bool seen = false;
                            for(int c = 0; c < _searchCandidates.Count; c++)
                            {
                                if(_searchCandidates[c].Cell != cell) continue;
                                if(edge && (_searchCandidates[c].OnMesh - onMesh).sqrMagnitude > HandoverAnchorRadius * HandoverAnchorRadius) continue;
                                seen = true;
                                break;
                            }
                            if(seen) continue;
                            _searchCandidates.Add(new LayerCandidate
                            {
                                OnMesh = onMesh,
                                OnParent = point,
                                Cost = state.Cost + walked + LayerSearchSwitchPenalty,
                                Cell = cell,
                                Edge = edge,
                            });
                            continue;
                        }
                        if(!TryAddSearchState(parent, layer, handle, onMesh, point, state.Cost + walked + LayerSearchSwitchPenalty)) continue;
                        added++;
                        if(_searchCount >= LayerSearchMaxStates) break;
                    }
                    if(_searchCount >= LayerSearchMaxStates) break;
                }

                var world = WorldLayer();
                for(int c = 0; c < _searchCandidates.Count && worldChecks < LayerSearchMaxWorldChecks
                                && queries < LayerSearchMaxQueries && _searchCount < LayerSearchMaxStates; c++)
                {
                    var candidate = _searchCandidates[c];
                    bool apart = false;
                    if(IsSearchVisited(world, world.Agent, candidate.OnMesh))
                    {
                        bool outOfBudget = false;
                        if(!candidate.Edge || JoinsWorldStateInCell(world, candidate.OnMesh, ref queries, out outOfBudget))
                        {
                            continue;
                        }
                        apart = true;
                        if(queries >= LayerSearchMaxQueries)
                        {
                            continue;
                        }
                    }
                    worldChecks++;
                    queries++;
                    bool leads = WorldLeads(candidate.OnMesh, to, HandoverMinWorldGain, out var result, out Vector3 stop, goalIsFinal: false);
                    bool taken;
                    if(apart)
                    {
                        taken = leads;
                        if(taken) AddSearchState(parent, world, world.Agent, candidate.OnMesh, candidate.OnParent, candidate.Cost);
                    }
                    else taken = leads && TryAddSearchState(parent, world, world.Agent, candidate.OnMesh, candidate.OnParent, candidate.Cost);
                    if(taken) added++;
                }
                return added;
            }

            private int LayerCount() => 3;

            private HelperNavLayers.INavLayer LayerByIndex(int index)
            {
                if(index == 0) return BuildingLayer();
                if(index == 1) return HelperNavLayers.SavedNavLayer.Instance;
                return index == 2 ? WorldLayer() : null;
            }

            private static bool IsAgentLayer(HelperNavLayers.INavLayer layer) => layer is HelperNavLayers.WorldNavLayer;

            private bool SurfaceOf(HelperNavLayers.INavLayer layer, Vector3 point, out object handle, out Vector3 onMesh)
            {
                handle = null;
                onMesh = point;
                bool world = layer is HelperNavLayers.WorldNavLayer;
                if(!layer.Probe(point, world ? HandoverWorldSnap : NavLayerMargin, out handle, out var coverage, out onMesh)) return false;
                if(coverage != HelperNavLayers.NavCoverage.OnSurface) return false;
                return !world || Mathf.Abs(onMesh.y - point.y) <= HandoverMaxDrop;
            }

            private void RescueLayeredStart(Vector3 from, int layers)
            {
                for(int i = 0; i < layers; i++)
                {
                    var layer = LayerByIndex(i);
                    if(layer == null || !layer.Enabled || layer is HelperNavLayers.WorldNavLayer) continue;
                    if(!layer.Probe(from, LayerStartRescueMargin, out object handle, out var coverage, out Vector3 onMesh)
                       || coverage != HelperNavLayers.NavCoverage.OnSurface) continue;
                    TryAddLayerStartRescue(layer, handle, from, onMesh);
                }
                if(_searchCount > 0) return;

                var world = WorldLayer();
                if(world.Enabled
                   && world.Probe(from, LayerStartRescueMargin, out object worldHandle, out var worldCoverage, out Vector3 onWorld)
                   && worldCoverage == HelperNavLayers.NavCoverage.OnSurface)
                    TryAddLayerStartRescue(world, worldHandle, from, onWorld);
            }

            private void TryAddLayerStartRescue(HelperNavLayers.INavLayer layer, object handle, Vector3 from, Vector3 onMesh)
            {
                float drop = from.y - onMesh.y;
                if(onMesh.y > from.y + 0.3f || drop > LayerStartRescueMargin || Vector3Ex.Distance2D(from, onMesh) > 1f) return;
                if(layer is HelperNavLayers.WorldNavLayer && !WorldStartRescueSameFloor(from, onMesh)) return;
                float distance = Vector3.Distance(from, onMesh);
                if(!TryAddSearchState(-1, layer, handle, onMesh, from, distance)) return;
                if(UnityEngine.Time.time < _layerStartRescueLogAt) return;
                _layerStartRescueLogAt = UnityEngine.Time.time + 10f;
            }

            private static bool WorldStartRescueSameFloor(Vector3 from, Vector3 onMesh)
            {
                if(Mathf.Abs(from.y - onMesh.y) <= HandoverMaxDrop) return true;
                var hits = Physics.RaycastAll(from + Vector3.up * 0.3f, Vector3.down,
                    LayerStartRescueMargin + 0.3f + HandoverMaxDrop, _groundPullMask, QueryTriggerInteraction.Ignore);
                float nearest = float.MaxValue;
                float floorY = float.PositiveInfinity;
                for(int i = 0; i < hits.Length; i++)
                {
                    var hit = hits[i];
                    if(hit.collider == null || hit.distance >= nearest) continue;
                    var entity = hit.collider.ToBaseEntity();
                    if(entity is BuildingBlock
                       || (hit.collider.gameObject.layer == _deployedLayer && entity is DecayEntity)) continue;
                    nearest = hit.distance;
                    floorY = hit.point.y;
                }
                return Mathf.Abs(floorY - onMesh.y) <= HandoverMaxDrop;
            }

            private bool CollectSearchPoints(bool agentLeg, RustNavMeshPath agentPath)
            {
                if(!agentLeg)
                {
                    CollectHandoverPoints();
                    return _handoverPoints.Count > 0;
                }
                _gateProbe.Clear();
                _rustAgent.AddCornersWorld(agentPath, _gateProbe);
                _handoverPoints.Clear();
                _handoverKey.Clear();
                if(_gateProbe.Count == 0) return false;
                Vector3 previous = _gateProbe[0];
                AddHandoverPoint(previous, true);
                for(int i = 1; i < _gateProbe.Count && _handoverPoints.Count < HandoverMaxPoints; i++)
                {
                    AddHandoverLeg(previous, _gateProbe[i]);
                    previous = _gateProbe[i];
                }
                return _handoverPoints.Count > 0;
            }

            private bool TryAddSearchState(int parent, HelperNavLayers.INavLayer layer, object handle, Vector3 enter, Vector3 enterOuter, float cost)
            {
                if(IsSearchVisited(layer, handle, enter)) return false;
                AddSearchState(parent, layer, handle, enter, enterOuter, cost);
                return true;
            }

            private void AddSearchState(int parent, HelperNavLayers.INavLayer layer, object handle, Vector3 enter, Vector3 enterOuter, float cost)
            {
                _searchVisited.Add(new LayerVisit { Layer = layer, Handle = handle, Cell = LayerSearchCell(enter, IsAgentLayer(layer)) });

                LayerSearchState state;
                if(_searchCount < _searchStates.Count) state = _searchStates[_searchCount];
                else
                {
                    state = new LayerSearchState();
                    _searchStates.Add(state);
                }
                _searchCount++;
                state.Layer = layer;
                state.Handle = handle;
                state.Enter = enter;
                state.EnterOuter = enterOuter;
                state.Cost = cost;
                state.Parent = parent;
                state.Open = true;
            }

            private bool JoinsWorldStateInCell(HelperNavLayers.WorldNavLayer world, Vector3 point, ref int queries, out bool outOfBudget)
            {
                outOfBudget = false;
                Vector3Int cell = LayerSearchCell(point, true);
                for(int i = 0; i < _searchCount; i++)
                {
                    var state = _searchStates[i];
                    if(state.Layer != world || !ReferenceEquals(state.Handle, world.Agent)) continue;
                    if(LayerSearchCell(state.Enter, true) != cell) continue;
                    if(queries >= LayerSearchMaxQueries)
                    {
                        outOfBudget = true;
                        return true;
                    }
                    queries++;
                    if(world.Route(world.Agent, point, state.Enter, null, out _, out _) == HelperSavedNavMesh.NavPathResult.Complete) return true;
                }
                return false;
            }

            private static Vector3Int LayerSearchCell(Vector3 point, bool world)
            {
                float side = world ? LayerSearchWorldCell : LayerSearchVisitCell;
                float rise = world ? LayerSearchWorldRise : LayerSearchVisitRise;
                return new Vector3Int(Mathf.FloorToInt(point.x / side),
                                      Mathf.FloorToInt(point.y / rise),
                                      Mathf.FloorToInt(point.z / side));
            }

            private void BuildSearchLegs(int index, Vector3 finishOnLayer)
            {
                _searchLegs.Clear();
                Vector3 exit = finishOnLayer;
                while(index >= 0 && _searchLegs.Count < LayerSearchMaxLegs)
                {
                    var state = _searchStates[index];
                    _searchLegs.Add(new LayerLeg
                    {
                        Layer = state.Layer,
                        Handle = state.Handle,
                        Agent = IsAgentLayer(state.Layer),
                        From = state.Enter,
                        To = exit,
                    });
                    exit = state.EnterOuter;
                    index = state.Parent;
                }
                _searchLegs.Reverse();
            }

            private bool CommitSearchLegs(NavLayerInsert mode, int insertAt, Vector3 to, out Vector3 stopWorld)
            {
                stopWorld = to;
                int index = insertAt;
                int budget = NavLayerMaxNodes;
                int last = _searchLegs.Count - 1;
                if(_searchStartRescue)
                {
                    InsertHandoverNode(_searchLegs[0].From, ref index, layerLeg: true);
                    _path[index - 1].IsLayerStartRescue = true;
                    budget--;
                }
                for(int i = 0; i <= last; i++)
                {
                    var leg = _searchLegs[i];
                    if(leg.Agent)
                    {
                        if(i < last) InsertHandoverNode(leg.To, ref index, layerLeg: false);
                        continue;
                    }

                    var route = leg.Layer.Route(leg.Handle, leg.From, leg.To, _navLayerSteps, out _, out string error);
                    if(route != HelperSavedNavMesh.NavPathResult.Complete
                       || !LayLayerSteps(leg.Layer, leg.Handle, leg.From, leg.To, ref index, budget, out int nodes, mergeFinish: i == last))
                    {
                        RemoveLaidNodes(insertAt, ref index);
                        return false;
                    }
                    budget -= nodes;
                    if(budget <= 0 && i < last)
                    {
                        RemoveLaidNodes(insertAt, ref index);
                        return false;
                    }
                    if(i < last && _searchLegs[i + 1].Agent) InsertHandoverNode(_searchLegs[i + 1].From, ref index, layerLeg: true);
                }

                var finish = _searchLegs[last];
                bool reachesTarget = !finish.Agent;
                return CommitLayeredRoute(mode, insertAt, index, reachesTarget, to,
                                          new LayerSpot { Layer = finish.Layer, Handle = finish.Handle },
                                          _searchLegs.Count > 1, reachesTarget, out stopWorld);
            }

            private bool CommitLayeredRoute(NavLayerInsert mode, int insertAt, int endIndex, bool reachesTarget, Vector3 to,
                                            LayerSpot spot, bool exit, bool entry, out Vector3 stopWorld)
            {
                stopWorld = to;
                if(reachesTarget && endIndex < _path.Count && _path[endIndex] != null)
                {
                    _path[endIndex].IsLayer = true;
                    _path[endIndex].LayerLeg = true;
                }
                CloseLayerPlan(LayerPlanOutcome.Replaced);
                _layerPlanActive = true;
                _layerPlanGoal = to;
                if(mode != NavLayerInsert.MidRoute) return true;
                _savedNavInsertCount++;
                _path.CurrentIndex = insertAt;
                HaltMovement();
                return true;
            }

            private bool OnWorldMesh(Vector3 point, out Vector3 onWorld)
            {
                onWorld = point;
                if(_rustAgent == null || !_rustAgent.SamplePositionTyped(point, out var hit, HandoverWorldSnap)) return false;
                if(Mathf.Abs(hit.position.y - point.y) > HandoverMaxDrop) return false;
                onWorld = hit.position;
                return true;
            }

            private LayerSpot SurfaceLayerAt(Vector3 point, out LayerSpot inArea)
            {
                inArea = default;
                for(int i = 0; i < 2; i++)
                {
                    HelperNavLayers.INavLayer layer = i == 0 ? BuildingLayer() : HelperNavLayers.SavedNavLayer.Instance;
                    if(layer == null || !layer.Enabled) continue;
                    if(!layer.Probe(point, NavLayerMargin, out object handle, out var coverage, out _)) continue;
                    if(coverage == HelperNavLayers.NavCoverage.OnSurface)
                        return new LayerSpot { Layer = layer, Handle = handle };
                    if(coverage == HelperNavLayers.NavCoverage.InArea && !inArea.IsValid)
                        inArea = new LayerSpot { Layer = layer, Handle = handle };
                }
                return default;
            }

            public bool TryNearestWalkable(Vector3 point, float radius, out Vector3 walkable)
            {
                walkable = point;
                if(_rustAgent != null && _rustAgent.SamplePositionTyped(point, out var hit, radius))
                {
                    if(HelperDoorTraps.IsInside(hit.position)) return false;
                    walkable = hit.position;
                    return true;
                }
                float bestSqr = radius * radius;
                bool found = false;
                for(int i = 0; i < 2; i++)
                {
                    HelperNavLayers.INavLayer layer = i == 0 ? BuildingLayer() : HelperNavLayers.SavedNavLayer.Instance;
                    if(layer == null || !layer.Enabled) continue;
                    if(!layer.Probe(point, NavLayerMargin, out object handle, out _, out _)) continue;
                    if(!layer.TryNearestSurface(handle, point, out Vector3 onMesh)) continue;
                    float sqr = (onMesh - point).sqrMagnitude;
                    if(sqr > bestSqr || HelperDoorTraps.IsInside(onMesh)) continue;
                    bestSqr = sqr;
                    walkable = onMesh;
                    found = true;
                }
                return found;
            }

            public bool HasWorldPath(Vector3 from, Vector3 to)
            {
                if(_rustAgent == null) return false;
                return _rustAgent.SamplePositionTyped(from, out var fromHit, NavMeshSnapRadius)
                       && _rustAgent.SamplePositionTyped(to, out var toHit, NavMeshSnapRadius)
                       && IsPathCompleteChained(fromHit.position, toHit.position);
            }

            public bool TryWorldPathEnd(Vector3 from, Vector3 to, out Vector3 reached)
            {
                reached = from;
                if(_rustAgent == null || !_rustAgent.SamplePositionTyped(from, out var fromHit, NavMeshSnapRadius)
                   || !_rustAgent.SamplePositionTyped(to, out var toHit, NavMeshSnapRadius)) return false;
                ChainEnd end = ChainPath(fromHit.position, toHit.position, null, out _, out reached);
                return end == ChainEnd.Complete || end == ChainEnd.Arrived;
            }

            public bool IsOnLayerSurface(Vector3 point) => SurfaceLayerAt(point, out _).IsValid;

            public bool HasRouteTo(Vector3 target)
            {
                if(_customNpc == null) return false;
                return HasRouteBetween(_customNpc.ServerPosition, target, out bool world) && world;
            }

            public bool HasRouteBetween(Vector3 from, Vector3 to, out bool world)
            {
                world = false;
                if(_customNpc == null || _rustAgent == null) return false;
                bool fromOnLayer = SurfaceLayerAt(from, out _).IsValid;
                Vector3 searchFrom = from;
                string reason;
                if(!OnWorldMesh(to, out Vector3 toWorld)) reason = "target off game navmesh";
                else if(GetNearestNavMeshPosition(from, out Vector3 start, NavMeshSnapRadius))
                {
                    ChainEnd end = ChainPath(start, toWorld, null, out _, out Vector3 reached);
                    if(end == ChainEnd.Complete || end == ChainEnd.Arrived)
                    {
                        world = true;
                        return true;
                    }
                    bool progressed = Vector3.Distance(start, toWorld) - Vector3.Distance(reached, toWorld) >= PathChainMinGain;
                    if(end == ChainEnd.DeadEnd && (progressed || !fromOnLayer))
                    {
                        searchFrom = reached;
                        reason = $"game navmesh dead end {Vector3.Distance(reached, to):0.0} m from target";
                    }
                    else if(!fromOnLayer) return false;
                    else reason = $"start on layer surface, game navmesh chain {end}";
                }
                else if(!fromOnLayer) return false;
                else reason = "start on layer surface off game navmesh";
                if(!SearchLayeredRoute(searchFrom, to)) return false;
                world = _searchLegs.Count > 0 && _searchLegs[_searchLegs.Count - 1].Agent;
                return true;
            }

            public bool CanReachPoint(Vector3 point)
            {
                if(SurfaceLayerAt(point, out _).IsValid) return true;
                return HasCompletePathTo(point);
            }

            public bool ProbeWorldPath(Vector3 from, Vector3 to, float snapRadius, List<Vector3> corners,
                                       out Vector3 snappedFrom, out Vector3 snappedTo, out string error)
            {
                corners?.Clear();
                snappedFrom = from;
                snappedTo = to;
                error = null;
                if(_rustAgent == null) { error = "bot has no navmesh agent"; return false; }
                if(!_rustAgent.SamplePositionTyped(from, out var fromHit, snapRadius)) { error = "start is not on game navmesh"; return false; }
                if(!_rustAgent.SamplePositionTyped(to, out var toHit, snapRadius)) { error = "finish is not on game navmesh"; return false; }
                snappedFrom = fromHit.position;
                snappedTo = toHit.position;
                return IsPathCompleteChained(snappedFrom, snappedTo, corners);
            }

            private const float ReturnCacheCell = 2f;
            private const float ReturnCacheLife = 600f;
            private const int ReturnCacheTrim = 4096;
            private static readonly Dictionary<(Vector3Int, Vector3Int), float> _returnOkUntil = new Dictionary<(Vector3Int, Vector3Int), float>();
            private static readonly List<(Vector3Int, Vector3Int)> _returnTrimBuf = new List<(Vector3Int, Vector3Int)>();

            private static Vector3Int ReturnCacheKey(Vector3 p) => new Vector3Int(Mathf.FloorToInt(p.x / ReturnCacheCell),
                Mathf.FloorToInt(p.y / ReturnCacheCell), Mathf.FloorToInt(p.z / ReturnCacheCell));

            public bool CanReturnFrom(Vector3 point, Vector3 to)
            {
                if(_customNpc == null || _rustAgent == null) return false;
                if(HasWorldPath(point, to)) return true;

                var cell = (ReturnCacheKey(point), ReturnCacheKey(to));
                float now = UnityEngine.Time.time;
                if(_returnOkUntil.TryGetValue(cell, out float until) && until > now) return true;

                bool ok = SearchLayeredRoute(point, to);
                if(!ok)
                {
                    return false;
                }
                if(_returnOkUntil.Count >= ReturnCacheTrim)
                {
                    _returnTrimBuf.Clear();
                    foreach(var kv in _returnOkUntil)
                        if(kv.Value <= now) _returnTrimBuf.Add(kv.Key);
                    for(int i = 0; i < _returnTrimBuf.Count; i++) _returnOkUntil.Remove(_returnTrimBuf[i]);
                }
                _returnOkUntil[cell] = now + ReturnCacheLife;
                return true;
            }

            private void CollectHandoverPoints()
            {
                _handoverPoints.Clear();
                _handoverKey.Clear();
                if(_navLayerSteps.Count == 0) return;
                Vector3 previous = _navLayerSteps[0].Position;
                AddHandoverPoint(previous, true);
                for(int i = 1; i < _navLayerSteps.Count && _handoverPoints.Count < HandoverMaxPoints; i++)
                {
                    var step = _navLayerSteps[i];
                    if((step.Hint & ~NodeHint.NavMesh) != NodeHint.None)
                    {
                        previous = step.Position;
                        AddHandoverPoint(previous, true);
                        continue;
                    }
                    var waypoints = step.Waypoints;
                    if(waypoints != null)
                        for(int k = 0; k < waypoints.Count; k++)
                        {
                            AddHandoverLeg(previous, waypoints[k]);
                            previous = waypoints[k];
                        }
                    AddHandoverLeg(previous, step.Position);
                    previous = step.Position;
                }
            }

            private void AddHandoverLeg(Vector3 from, Vector3 to)
            {
                float distance = Vector3.Distance(from, to);
                if(distance < NavLayerDedupe) return;
                int pieces = Mathf.Max(1, Mathf.CeilToInt(distance / HandoverScanStep));
                for(int i = 1; i <= pieces && _handoverPoints.Count < HandoverMaxPoints; i++)
                    AddHandoverPoint(Vector3.Lerp(from, to, (float)i / pieces), i == pieces);
            }

            private void AddHandoverPoint(Vector3 point, bool key)
            {
                if(_handoverPoints.Count >= HandoverMaxPoints) return;
                _handoverPoints.Add(point);
                _handoverKey.Add(key);
            }

            private void InsertHandoverNode(Vector3 onWorld, ref int index, bool layerLeg)
            {
                var node = PathNode.GetPool(onWorld, NodeHint.NavMesh);
                node.IsLayer = true;
                node.LayerLeg = layerLeg;
                _path.Insert(index++, node);
            }

            private void RemoveLaidNodes(int first, ref int end)
            {
                for(int i = end - 1; i >= first; i--)
                {
                    var node = _path[i];
                    _path.RemoveAt(i);
                    PathNode.SetPool(ref node);
                }
                end = first;
            }

            protected bool TryInsertLayeredRouteAhead(Vector3 botPos)
            {
                if(_path == null || !_path.HasPath) return false;
                int first = Mathf.Max(0, _path.CurrentIndex);
                int target = first;
                Vector3 finish = _path.FinishNode.Position;
                while(target < _path.Count - 1 && _path[target] != null
                      && (_path[target].IsTransition
                          || (Vector3Ex.Distance2D(_path[target].Position, finish) <= HandoverUnderGoalRadius
                              && finish.y - _path[target].Position.y > HandoverUnderGoalRise))) target++;
                if(target >= _path.Count || _path[target] == null) return false;
                if(!TryBuildLayeredRoute(botPos, _path[target].Position, target, out _)) return false;
                for(int i = target - 1; i >= first; i--)
                {
                    var node = _path[i];
                    _path.RemoveAt(i);
                    PathNode.SetPool(ref node);
                }
                _path.CurrentIndex = first;
                return true;
            }

            public bool TryBuildLayeredRoute(HelperNavLayers.INavLayer layer, Vector3 from, Vector3 to, int insertAt,
                                             out Vector3 stopWorld)
            {
                stopWorld = from;
                if(layer == null || !layer.Enabled || _path == null) return false;
                if(!layer.Probe(from, NavLayerMargin, out object handle, out var coverage, out _)) return false;
                if(coverage == HelperNavLayers.NavCoverage.None) return false;
                if(!layer.Contains(handle, to, NavLayerMargin)) return false;
                if(!InsertLayerRoute(layer, handle, from, to, insertAt, out stopWorld)) return false;

                _explicitLayer = layer;
                _explicitLayerVersion = (layer as HelperNavLayers.INavLayerVersioned)?.Version ?? 0;
                _explicitGoal = to;
                return true;
            }

            public bool HasExplicitLayerRoute => _explicitLayer != null;

            public bool RefreshExplicitLayerRoute(NavigationSpeed speed)
            {
                if(_explicitLayer == null || _customNpc == null) return false;
                if(!(_explicitLayer is HelperNavLayers.INavLayerVersioned versioned)) return false;
                int version = versioned.Version;
                if(version == _explicitLayerVersion) return false;

                var layer = _explicitLayer;
                Vector3 goal = _explicitGoal;

                if(!SetDestination(goal, speed, _finishArrival, _finishRequireLos)) return false;
                return TryBuildLayeredRoute(layer, _customNpc.ServerPosition, goal, 1, out _);
            }

            protected bool RelayExplicitLayerRoute(float speedFraction)
            {
                if(_explicitLayer == null || _customNpc == null) return false;
                var layer = _explicitLayer;
                Vector3 goal = _explicitGoal;
                StartMoved(goal, speedFraction);
                return TryBuildLayeredRoute(layer, _customNpc.ServerPosition, goal, 1, out _);
            }

            private bool InsertLayerRoute(HelperNavLayers.INavLayer layer, object handle, Vector3 start, Vector3 finish,
                                          int insertAt, out Vector3 stopWorld)
            {
                if(layer.Route(handle, start, finish, _navLayerSteps, out stopWorld, out string error) != HelperSavedNavMesh.NavPathResult.Complete)
                {
                    return false;
                }
                int index = insertAt;
                return LayLayerSteps(layer, handle, start, finish, ref index, NavLayerMaxNodes, out _);
            }

            private bool LayLayerSteps(HelperNavLayers.INavLayer layer, object handle, Vector3 start, Vector3 finish,
                                       ref int index, int budget, out int inserted, bool mergeFinish = true)
            {
                inserted = 0;
                if(_navLayerSteps.Count < 2 || budget <= 0) return false;

                int last = _navLayerSteps.Count - 1;
                Vector3 previousPos = start;
                for(int i = 1; i <= last; i++)
                {
                    var step = _navLayerSteps[i];
                    bool layerLeg = step.Node == null || !step.Node.IsNavMesh;
                    var waypoints = step.Waypoints;
                    if(waypoints != null)
                        for(int k = 0; k < waypoints.Count; k++)
                        {
                            Vector3 point = waypoints[k];
                            if((point - previousPos).sqrMagnitude < NavLayerDedupe * NavLayerDedupe) continue;
                            if((point - step.Position).sqrMagnitude < NavLayerDedupe * NavLayerDedupe) continue;
                            InsertLayerLeg(layer, handle, previousPos, point, ref index, ref inserted, budget, layerLeg);
                            InsertLayerPoint(point, ref index, ref inserted, budget, layerLeg);
                            previousPos = point;
                        }

                    bool mergeWithFinish = mergeFinish && i == last && step.Hint == NodeHint.None
                                           && (step.Position - finish).sqrMagnitude < NavLayerFinishMerge * NavLayerFinishMerge;

                    if(step.Hint == NodeHint.None) InsertLayerLeg(layer, handle, previousPos, mergeWithFinish ? finish : step.Position, ref index, ref inserted, budget, layerLeg, mergeWithFinish);
                    if(mergeWithFinish) break;

                    if(inserted >= budget) break;

                    var previous = _navLayerSteps[i - 1].Node;
                    var next = i < last ? _navLayerSteps[i + 1].Node : null;
                    var laid = PathNode.GetPool(step.Node, previous, next, _path.NavMeshAreaMask);
                    laid.IsLayer = true;
                    laid.LayerLeg = layerLeg;
                    _path.Insert(index++, laid);
                    inserted++;
                    previousPos = step.Position;
                }
                if(inserted == 0) return false;

                layer.MarkRoute(_customNpc, handle, _navLayerSteps.Count - 1, inserted);
                return true;
            }

            private void InsertLayerLeg(HelperNavLayers.INavLayer layer, object handle, Vector3 from, Vector3 to,
                                        ref int index, ref int inserted, int budget, bool layerLeg, bool approach = false)
            {
                float distance = Vector3.Distance(from, to);
                float split = approach ? distance - NavLayerApproach : distance;
                if(split > NavLayerLegStep)
                {
                    int pieces = Mathf.CeilToInt(split / NavLayerLegStep);
                    for(int i = 1; i < pieces; i++)
                    {
                        Vector3 point = Vector3.Lerp(from, to, split * i / (pieces * distance));
                        if(layer.Sample(handle, point, out Vector3 onMesh)) point = onMesh;
                        InsertLayerPoint(point, ref index, ref inserted, budget, layerLeg);
                    }
                }
                if(!approach || distance <= NavLayerApproach + NavLayerDedupe) return;

                Vector3 last = Vector3.Lerp(from, to, split / distance);
                if(layer.Sample(handle, last, out Vector3 lastOnMesh)) last = lastOnMesh;
                InsertLayerPoint(last, ref index, ref inserted, budget, layerLeg);
            }

            private void InsertLayerPoint(Vector3 point, ref int index, ref int inserted, int budget, bool layerLeg)
            {
                if(inserted >= budget) return;
                var node = PathNode.GetPool(point, NodeHint.None);
                node.IsGraph = true;
                node.IsLayer = true;
                node.LayerLeg = layerLeg;
                _path.Insert(index++, node);
                inserted++;
            }

            #endregion

            protected void ClearPathAndState()
            {
                CloseLayerPlan(LayerPlanOutcome.Reset);
                HaltMovement();
                _path?.Reset();
                _skipFirstNodeOnReady = false;
                ClearLayerState();
                _explicitLayer = null;
                _explicitLayerVersion = 0;
                _swimRescueActive = false;
                _swimRescueResume = null;
                _swimRescueWaitUntil = 0f;
                _islandWalkActive = false;
                _islandWalkResume = null;
                _stallStart = UnityEngine.Time.time;
                _stallLastPos = _customNpc != null ? _customNpc.ServerPosition : Vector3.zero;
                _lastThinkPos = _stallLastPos;
                _watchdogPos = _stallLastPos;
                _watchdogTime = UnityEngine.Time.time;
                _pause = false;
                if(IsInvoking(Resume)) CancelInvoke(Resume);
            }
            public void Stop()
            {
                ClearPathAndState();
                _type = NavigationType.None;
                _lastStuckReason = StuckReason.None;
            }
            private void FinishNavigation()
            {
                if(_swimRescueActive)
                {
                    _swimRescueActive = false;
                    Vector3? resume = _swimRescueResume;
                    _swimRescueResume = null;
                    if(resume.HasValue && _customNpc != null)
                    {
                        StartMoved(resume.Value, currentSpeedFraction);
                        return;
                    }
                }
                if(_islandWalkActive)
                {
                    _islandWalkActive = false;
                    _islandWalkFrom = null;
                    Vector3? resume = _islandWalkResume;
                    _islandWalkResume = null;
                    if(resume.HasValue && _customNpc != null)
                    {
                        StartMoved(resume.Value, currentSpeedFraction);
                        return;
                    }
                }
                CloseLayerPlan(LayerPlanOutcome.Arrived);
                HaltMovement();
                _type = NavigationType.Finish;
                _lastStuckReason = StuckReason.None;
                _unreachableStreak = 0;
            }
            private void TryEscalateStuck()
            {
                NavGuardPolicy policy = Guard.Policy;
                if(_swimRescueActive)
                {
                    _swimRescueActive = false;
                    _swimRescueResume = null;
                    _swimRescueBlockedUntil = UnityEngine.Time.time + SwimRescueFailCooldown;
                }
                if(_lastStuckReason == StuckReason.PathPartialUnreachable || _lastStuckReason == StuckReason.PathPlanningFailed)
                    _unreachableStreak++;
                else _unreachableStreak = 0;
                bool swimRecover = _customNpc != null && _customNpc.IsSwimming();
                float onMeshProbe = swimRecover ? 0.15f : 0.6f;
                float recoverRadius = Guard.ClampRadius(swimRecover ? OffMeshWarpRecoverRadiusSwim : OffMeshWarpRecoverRadius);
                bool offMeshRecover = policy.WarpRecover && _customNpc != null && _rustAgent != null
                                      && UnityEngine.Time.time >= _offMeshWarpUntil
                                      && !_rustAgent.SamplePositionTyped(_customNpc.ServerPosition, out _, onMeshProbe);
                bool repeatWarp = _customNpc != null && UnityEngine.Time.time - _lastWarpAt < WarpRepeatWindow
                                  && Vector3Ex.Distance2D(_customNpc.ServerPosition, _lastWarpFrom) < WarpRepeatRadius;
                bool repeatBlocked = false;
                if(offMeshRecover)
                {
                    float recoverMaxDepth = CanSwimFloat() ? WadeDepth : float.PositiveInfinity;
                    Vector3? resumeFinish = _path?.FinishNode?.Position;
                    if(TryFindWarpPoint(_customNpc.ServerPosition, recoverRadius, recoverMaxDepth, resumeFinish, out Vector3 recoverTarget, out WarpCandidateRank recoverRank,
                                        requireSight: policy.WarpNeedsSight)
                       && !(swimRecover && recoverRank == WarpCandidateRank.DryUnverified)
                       && !RejectRepeatWarp(repeatWarp, recoverTarget, recoverRank, resumeFinish, ref repeatBlocked))
                    {
                        if(swimRecover && TrySwimRescue(recoverTarget, resumeFinish, recoverRank)) return;
                        RememberWarp(resumeFinish);
                        _offMeshWarpUntil = UnityEngine.Time.time + OffMeshWarpCooldown;
                        Warp(recoverTarget);
                        if(resumeFinish.HasValue)
                        {
                            _lastStuckReason = StuckReason.None;
                            StartMoved(resumeFinish.Value, currentSpeedFraction);
                        }
                        return;
                    }
                }
                bool offMeshRescue = policy.WarpRescue && _customNpc != null && _rustAgent != null
                                     && UnityEngine.Time.time >= _offMeshWarpUntil
                                     && !_rustAgent.SamplePositionTyped(_customNpc.ServerPosition, out _, 0.6f);
                if(offMeshRescue)
                {
                    Vector3? resumeFinish = _path?.FinishNode?.Position;
                    if(TryFindWarpPoint(_customNpc.ServerPosition, Guard.ClampRadius(OffMeshWarpRescueRadius), OffMeshWarpRescueMaxDepth, resumeFinish, out Vector3 rescueTarget, out WarpCandidateRank rescueRank,
                                        requireSight: policy.WarpNeedsSight)
                       && !(swimRecover && rescueRank == WarpCandidateRank.DryUnverified)
                       && !RejectRepeatWarp(repeatWarp, rescueTarget, rescueRank, resumeFinish, ref repeatBlocked))
                    {
                        if(swimRecover && TrySwimRescue(rescueTarget, resumeFinish, rescueRank)) return;
                        RememberWarp(resumeFinish);
                        _offMeshWarpUntil = UnityEngine.Time.time + OffMeshWarpCooldown;
                        Warp(rescueTarget);
                        if(resumeFinish.HasValue)
                        {
                            _lastStuckReason = StuckReason.None;
                            StartMoved(resumeFinish.Value, currentSpeedFraction);
                        }
                        return;
                    }
                }
                bool swimTrapped = swimRecover && policy.SelfWalkEscape && !offMeshRecover && !offMeshRescue
                                   && _customNpc != null && _rustAgent != null && UnityEngine.Time.time >= _swimTrappedUntil
                                   && (_lastStuckReason == StuckReason.PathPartialUnreachable
                                       || _lastStuckReason == StuckReason.PathPlanningFailed);
                if(swimTrapped)
                {
                    _swimTrappedUntil = UnityEngine.Time.time + OffMeshWarpCooldown;
                    Vector3? finish = _path?.FinishNode?.Position;
                    if(TryFindSwimShore(_customNpc.ServerPosition, true, out Vector3 shore, out WarpCandidateRank shoreRank, out _))
                    {
                        if(!RejectRepeatWarp(repeatWarp, shore, shoreRank, finish, ref repeatBlocked) && TrySwimRescue(shore, finish, shoreRank))
                        {
                            if(!_swimRescueActive) _swimTrappedUntil = 0f;
                            _unreachableStreak = 0;
                            return;
                        }
                    }
                }
                bool trappedCandidate = (policy.WarpIslandEscape || policy.SelfWalkEscape)
                                        && !offMeshRecover && !offMeshRescue
                                        && _customNpc != null && _rustAgent != null
                                        && UnityEngine.Time.time >= _offMeshWarpUntil
                                        && (_lastStuckReason == StuckReason.PathPartialUnreachable
                                            || _lastStuckReason == StuckReason.PathPlanningFailed);
                if(trappedCandidate)
                {
                    Vector3 trappedPos = _customNpc.ServerPosition;
                    bool underTerrain = trappedPos.y < TerrainHeightAt(trappedPos) - TrappedUnderTerrainDepth
                                        || IsCoveredFromAbove(trappedPos);
                    if(underTerrain || _unreachableStreak >= IslandStuckStreak)
                    {
                        Vector3? finish = _path?.FinishNode?.Position;
                        if(!IsWarpTargetConnected(trappedPos, finish))
                        {
                            if(TryIslandEscape(trappedPos, finish, underTerrain, policy, true)) return;
                        }
                        else _unreachableStreak = 0;
                    }
                }
                if(offMeshRecover || offMeshRescue)
                {
                    if(swimRecover && !repeatBlocked)
                    {
                        Vector3 swimFrom = _customNpc.ServerPosition;
                        bool lowShore = TryFindSwimShore(swimFrom, true, out Vector3 shore, out WarpCandidateRank shoreRank, out float shoreRadius);
                        if(lowShore && TrySwimRescue(shore, null, shoreRank)) return;
                        if(lowShore || TryFindSwimShore(swimFrom, false, out shore, out shoreRank, out shoreRadius))
                        {
                            BlackBox.NoteRescue(_customNpc, BlackBoxKind.SwimRescue, "straight to the shore", swimFrom, shore);
                            _offMeshWarpUntil = UnityEngine.Time.time + OffMeshWarpCooldown;
                            _lastStuckReason = StuckReason.None;
                            _unreachableStreak = 0;
                            StartMoved(shore, currentSpeedFraction);
                            return;
                        }
                    }
                    _offMeshWarpUntil = UnityEngine.Time.time + OffMeshWarpCooldown;
                    if(_lastStuckReason != StuckReason.NoConnectedNavmesh)
                    {
                        _lastStuckReason = StuckReason.NoConnectedNavmesh;
                    }
                }
                BlackBox.NoteStuck(_customNpc, _lastStuckReason, true);
                HaltMovement();
                _type = NavigationType.Stuck;
                var router = _customNpc?.brain?.StateMachine?.GetCurrentState() as FSM.IRouterState;
                router?.OnStuck();
            }
            private bool TryIslandEscape(Vector3 trappedPos, Vector3? finish, bool underTerrain, NavGuardPolicy policy, bool allowSelfWalk)
            {
                float radius = 0f;
                for(int i = 0; i < IslandEscapeRadii.Length; i++)
                {
                    radius = Guard.ClampRadius(IslandEscapeRadii[i]);
                    if(!TryFindWarpPoint(trappedPos, radius, OffMeshWarpRescueMaxDepth, finish,
                                         out Vector3 escapeTarget, out WarpCandidateRank escapeRank,
                                         requireSight: false)) continue;
                    if(escapeRank != WarpCandidateRank.DryConnected && escapeRank != WarpCandidateRank.WetConnected) continue;
                    bool downhill = escapeTarget.y <= trappedPos.y + IslandSelfClimb;
                    bool safeDrop = trappedPos.y - escapeTarget.y <= IslandSelfDescend
                                    || escapeRank == WarpCandidateRank.WetConnected;
                    bool clearWay = IsOnSolidGround(escapeTarget)
                        && !Physics.Linecast(trappedPos + Vector3.up * 0.3f, escapeTarget + Vector3.up * 0.3f,
                                             SelfWalkBlockMask, QueryTriggerInteraction.Ignore)
                        && !Physics.Linecast(trappedPos + Vector3.up * 1.2f, escapeTarget + Vector3.up * 1.2f,
                                             SelfWalkBlockMask, QueryTriggerInteraction.Ignore);
                    bool walkFailed = _islandWalkFrom.HasValue
                        && (trappedPos - _islandWalkFrom.Value).sqrMagnitude <= IslandWalkRetryRadius * IslandWalkRetryRadius;
                    if(allowSelfWalk && policy.SelfWalkEscape && !walkFailed && UnityEngine.Time.time >= _islandSelfWalkUntil && downhill && safeDrop && clearWay)
                    {
                        _islandSelfWalkUntil = UnityEngine.Time.time + IslandSelfWalkGrace;
                        _offMeshWarpUntil = UnityEngine.Time.time + IslandSelfWalkGrace;
                        BlackBox.NoteRescue(_customNpc, BlackBoxKind.Escape, "walking off an isolated navmesh", trappedPos, escapeTarget);
                        _lastStuckReason = StuckReason.None;
                        StartMoved(escapeTarget, currentSpeedFraction);
                        _islandWalkActive = true;
                        _islandWalkResume = finish;
                        _islandWalkFrom = trappedPos;
                        return true;
                    }
                    _islandSelfWalkUntil = 0f;
                    if(!policy.WarpIslandEscape)
                    {
                        _offMeshWarpUntil = UnityEngine.Time.time + IslandEscapeFailCooldown;
                        if(_lastStuckReason != StuckReason.NoConnectedNavmesh)
                        {
                            _lastStuckReason = StuckReason.NoConnectedNavmesh;
                        }
                        return false;
                    }
                    _offMeshWarpUntil = UnityEngine.Time.time + OffMeshWarpCooldown;
                    _unreachableStreak = 0;
                    Warp(escapeTarget);
                    _islandSelfWalkUntil = 0f;
                    _islandWalkFrom = null;
                    if(finish.HasValue)
                    {
                        _lastStuckReason = StuckReason.None;
                        StartMoved(finish.Value, currentSpeedFraction);
                    }
                    return true;
                }
                _offMeshWarpUntil = UnityEngine.Time.time + IslandEscapeFailCooldown;
                if(_lastStuckReason != StuckReason.NoConnectedNavmesh)
                {
                    _lastStuckReason = StuckReason.NoConnectedNavmesh;
                }
                return false;
            }
            private float SwimShoreMaxY(Vector3 botPos)
            {
                var info = WaterLevel.GetWaterInfo(botPos, waves: false, volumes: true, _customNpc);
                return info.isValid && info.overallDepth > 0f ? info.surfaceLevel + SwimExitMaxAboveWater : float.PositiveInfinity;
            }
            private bool TryFindSwimShore(Vector3 botPos, bool lowShore, out Vector3 shore, out WarpCandidateRank rank, out float radius)
            {
                float maxY = lowShore ? SwimShoreMaxY(botPos) : float.PositiveInfinity;
                for(int i = 0; i < SwimShoreRings; i++)
                {
                    radius = SwimShoreRadius(i);
                    if(!TryFindWarpPoint(botPos, radius, RescueMaxWaterDepth, null, out shore, out rank, requireSight: false, maxY: maxY)) continue;
                    if(rank == WarpCandidateRank.DryConnected) return true;
                }
                shore = botPos;
                rank = WarpCandidateRank.None;
                radius = SwimShoreRadius(SwimShoreRings - 1);
                return false;
            }
            private const int LayerEscapeMaxTries = 3;

            private bool TryLayerEscape(Vector3 pos)
            {
                if(!SurfaceLayerAt(pos, out _).IsValid) return false;
                int tries = 0;
                for(int i = 0; i < WarpConnectivityDirections && tries < LayerEscapeMaxTries; i++)
                {
                    float ang = Mathf.PI * 2f * i / WarpConnectivityDirections;
                    Vector3 probe = pos + new Vector3(Mathf.Cos(ang), 0f, Mathf.Sin(ang)) * WarpConnectivityProbeRange;
                    if(!_rustAgent.SamplePositionTyped(probe, out var hit, WarpConnectivitySampleRadius)) continue;
                    Vector3 ground = hit.position;
                    if(!IsOnSolidGround(ground) || !IsWarpTargetConnected(ground, null)) continue;
                    tries++;
                    if(!SearchLayeredRoute(pos, ground)) continue;
                    _lastStuckReason = StuckReason.None;
                    StartMoved(ground, currentSpeedFraction);
                    if(_layerPlanActive)
                    {
                        return true;
                    }
                    Stop();
                }
                return false;
            }

            public bool TryEscapeTrap()
            {
                if(_customNpc == null || _rustAgent == null || _path == null) return false;
                Vector3 pos = _customNpc.ServerPosition;
                if(_customNpc.IsSwimming())
                {
                    if(!TryFindSwimShore(pos, true, out Vector3 shore, out WarpCandidateRank rank, out float radius)) return false;
                    if(TrySwimRescue(shore, null, rank) && _swimRescueActive) return true;
                    _lastStuckReason = StuckReason.None;
                    StartMoved(shore, currentSpeedFraction);
                    return true;
                }
                if(IsWarpTargetConnected(pos, null)) return false;
                bool underTerrain = pos.y < TerrainHeightAt(pos) - TrappedUnderTerrainDepth || IsCoveredFromAbove(pos);
                if(TryLayerEscape(pos)) return true;
                return TryIslandEscape(pos, null, underTerrain, Guard.Policy, false);
            }
            private enum WarpCandidateRank
            {
                None = 0,
                DryUnverified = 1,
                WetConnected = 2,
                DryConnected = 3,
            }
            private bool RejectRepeatWarp(bool repeatWarp, Vector3 target, WarpCandidateRank rank, Vector3? goal, ref bool blocked)
            {
                if(goal.HasValue && _rescueGoalCount >= RescueGoalMaxRepeats
                   && UnityEngine.Time.time - _rescueGoalSince < RescueGoalWindow
                   && Vector3.Distance(goal.Value, _rescueGoal) < RescueGoalSame)
                {
                    blocked = true;
                    return true;
                }
                if(!repeatWarp) return false;
                if(_warpRepeatCount == 0 && rank == WarpCandidateRank.DryConnected
                   && Vector3Ex.Distance2D(target, _lastWarpFrom) >= WarpRepeatRadius) return false;
                blocked = true;
                return true;
            }
            private void RememberWarp(Vector3? goal)
            {
                Vector3 pos = _customNpc.ServerPosition;
                float now = UnityEngine.Time.time;
                bool repeat = now - _lastWarpAt < WarpRepeatWindow
                              && Vector3Ex.Distance2D(pos, _lastWarpFrom) < WarpRepeatRadius;
                _warpRepeatCount = repeat ? _warpRepeatCount + 1 : 0;
                _lastWarpFrom = pos;
                _lastWarpAt = now;
                if(!goal.HasValue) return;
                if(now - _rescueGoalSince < RescueGoalWindow && Vector3.Distance(goal.Value, _rescueGoal) < RescueGoalSame)
                {
                    _rescueGoalCount++;
                    return;
                }
                _rescueGoal = goal.Value;
                _rescueGoalCount = 1;
                _rescueGoalSince = now;
            }
            private bool TrySwimRescue(Vector3 shore, Vector3? resume, WarpCandidateRank rank)
            {
                if(!HelperWaterNavMesh.Enabled || _customNpc == null || _path == null) return false;
                float now = UnityEngine.Time.time;
                if(now < _swimRescueBlockedUntil) return false;
                Vector3 botPos = _customNpc.ServerPosition;
                float shoreMaxY = SwimShoreMaxY(botPos);
                if(shore.y > shoreMaxY)
                {
                    return false;
                }

                var state = HelperWaterNavMesh.Instance.EnsureCorridor(botPos, shore, out string error);
                if(state == HelperWaterNavMesh.CorridorState.Pending)
                {
                    if(_swimRescueWaitUntil <= 0f) _swimRescueWaitUntil = now + SwimRescueMaxWait;
                    if(now < _swimRescueWaitUntil)
                    {
                        return true;
                    }
                    _swimRescueWaitUntil = 0f;
                    return false;
                }
                _swimRescueWaitUntil = 0f;
                if(state == HelperWaterNavMesh.CorridorState.Failed)
                {
                    return false;
                }

                var layer = HelperNavLayers.WaterNavLayer.Instance;
                if(!layer.Probe(botPos, NavLayerMargin, out object handle, out var coverage, out _)
                   || coverage != HelperNavLayers.NavCoverage.OnSurface)
                {
                    return false;
                }

                ClearPathAndState();
                _path.Add(PathNode.GetPool(botPos, NodeHint.None));
                _path.Add(PathNode.GetPool(shore, NodeHint.NavMesh));
                _path.CurrentIndex = 0;
                if(!InsertLayerRoute(layer, handle, botPos, shore, 1, out _))
                {
                    ClearPathAndState();
                    return false;
                }
                _type = NavigationType.Moving;
                _skipFirstNodeOnReady = true;
                RememberWarp(resume);
                _offMeshWarpUntil = now + OffMeshWarpCooldown;
                _lastStuckReason = StuckReason.None;
                _swimRescueActive = true;
                _swimRescueResume = resume;
                BlackBox.NoteRescue(_customNpc, BlackBoxKind.SwimRescue, "along the water navmesh", botPos, shore);
                return true;
            }
            private bool TrySwimToFinish()
            {
                if(!HelperWaterNavMesh.Enabled || _customNpc == null || _path?.FinishNode == null) return false;
                if(_lastStuckReason != StuckReason.PathPlanningFailed && _lastStuckReason != StuckReason.PathPartialUnreachable
                   && _lastStuckReason != StuckReason.Stall) return false;
                if(_customNpc.IsInWater || _customNpc.isMounted || UnityEngine.Time.time < _swimToFinishBlockedUntil) return false;

                Vector3 botPos = _customNpc.ServerPosition;
                Vector3 finish = _path.FinishNode.Position;
                if(!FindWaterCrossing(botPos, finish, out Vector3 entry, out float depth, out float entryDistance, out Vector3? farWater)) return false;

                var router = _customNpc.brain?.StateMachine?.GetCurrentState() as FSM.IRouterState;
                if(router != null && !router.CanSwimAhead(entry, depth, entryDistance)) return false;

                if(SwimTowards(finish, depth, entryDistance, farWater)) return true;

                _swimToFinishBlockedUntil = UnityEngine.Time.time + SwimRescueFailCooldown;
                return TryWalkToWaterEdge(botPos, entry, entryDistance, finish);
            }
            private bool SwimTowards(Vector3 finish, float depth, float entryDistance, Vector3? farWater)
            {
                Vector3 goal = farWater ?? finish;
                return TrySwimRescue(goal, farWater.HasValue ? finish : null, farWater.HasValue ? WarpCandidateRank.DryConnected : WarpCandidateRank.WetConnected);
            }
            private bool TickSwimShortcut()
            {
                if(_customNpc == null || _type != NavigationType.Moving || _swimRescueActive || _path?.FinishNode == null) return false;
                float now = UnityEngine.Time.time;
                if(now < _nextSwimShortcutProbe) return false;
                _nextSwimShortcutProbe = now + SwimShortcutProbeInterval;
                if(!HelperWaterNavMesh.Enabled || _customNpc.IsInWater || _customNpc.isMounted) return false;

                var router = _customNpc.brain?.StateMachine?.GetCurrentState() as FSM.IRouterState;
                if(router == null || !router.PrefersSwimShortcut) return false;

                Vector3 botPos = _customNpc.ServerPosition;
                Vector3 finish = _path.FinishNode.Position;
                if(Vector3.Distance(finish, _swimShortcutGoal) < RescueGoalSame && now < _swimShortcutWalkUntil) return false;
                if(!FindWaterCrossing(botPos, finish, out Vector3 entry, out float depth, out float entryDistance, out Vector3? farWater)) return false;
                if(!router.CanSwimAhead(entry, depth, entryDistance)) return false;

                _swimShortcutGoal = finish;
                if(WalkIsShortEnough(botPos, finish))
                {
                    _swimShortcutWalkUntil = now + SwimShortcutWalkRecheck;
                    return false;
                }
                if(SwimTowards(finish, depth, entryDistance, farWater) || TryWalkToWaterEdge(botPos, entry, entryDistance, finish)) return true;

                _swimShortcutWalkUntil = now + SwimRescueFailCooldown;
                return false;
            }
            private bool WalkIsShortEnough(Vector3 botPos, Vector3 finish)
            {
                if(!GetNearestNavMeshPosition(botPos, out Vector3 start, NavMeshSnapRadius)) return false;
                ChainEnd end = ChainPath(start, finish, _swimShortcutCorners, out _, out _);
                if(end != ChainEnd.Complete && end != ChainEnd.Arrived) return false;
                float walk = 0f;
                Vector3 prev = start;
                foreach(Vector3 corner in _swimShortcutCorners)
                {
                    walk += Vector3Ex.Distance2D(prev, corner);
                    prev = corner;
                }
                return walk <= Vector3Ex.Distance2D(botPos, finish) * SwimShortcutDetourFactor + SwimShortcutDetourSlack;
            }
            private bool TryWalkToWaterEdge(Vector3 botPos, Vector3 entry, float entryDistance, Vector3 finish)
            {
                if(Vector3.Distance(_swimEdgeGoal, finish) < RescueGoalSame) return false;
                Vector3 dir = entry - botPos;
                dir.y = 0f;
                Vector3 shallow = botPos + dir.normalized * Mathf.Max(0f, entryDistance - DeepWaterProbeStep);
                if(!GetNearestNavMeshPosition(shallow, out Vector3 edge, SwimEdgeSnapRadius) || Vector3Ex.Distance2D(edge, botPos) < 2f) return false;

                _swimEdgeGoal = finish;
                _lastStuckReason = StuckReason.None;
                StartMoved(edge, currentSpeedFraction);
                return true;
            }
            private static bool FindWaterCrossing(Vector3 from, Vector3 to, out Vector3 entry, out float depth, out float entryDistance, out Vector3? farWater)
            {
                entry = Vector3.zero;
                depth = 0f;
                entryDistance = 0f;
                farWater = null;
                Vector3 dir = to - from;
                dir.y = 0f;
                float length = dir.magnitude;
                if(length < 1f || length > HelperWaterNavMesh.MaxRescueDistance) return false;
                dir /= length;

                bool inWater = false;
                Vector3 lastDeep = from;
                for(float d = DeepWaterProbeStep; d <= length; d += DeepWaterProbeStep)
                {
                    Vector3 probe = from + dir * d;
                    float deep = WaterDepthAt(probe);
                    if(!inWater)
                    {
                        if(d > SwimToFinishEntryReach) return false;
                        if(deep < DeepWaterSwimDepth) continue;
                        inWater = true;
                        entry = probe;
                        depth = deep;
                        entryDistance = d;
                        lastDeep = probe;
                        continue;
                    }
                    if(deep >= DeepWaterSwimDepth)
                    {
                        lastDeep = probe;
                        continue;
                    }
                    if(deep >= 1f) continue;
                    farWater = new Vector3(lastDeep.x, TerrainHeightAt(lastDeep), lastDeep.z);
                    return true;
                }
                return inWater;
            }
            private static float WaterDepthAt(Vector3 point)
            {
                float ground = TerrainHeightAt(point);
                var water = WaterLevel.GetWaterInfo(new Vector3(point.x, ground + 0.05f, point.z), waves: false, volumes: false);
                return water.isValid ? water.surfaceLevel - ground : 0f;
            }
            private struct WarpCandidate
            {
                public Vector3 Pos;
                public bool Dry;
                public float DistSqr;
            }
            private readonly List<WarpCandidate> _warpCandidates = new List<WarpCandidate>(RescueDryProbeDirections * 2 + 1);
            private readonly List<Vector3> _warpFailedIslands = new List<Vector3>(WarpConnectivityMaxChecks);
            private const float WarpFailedIslandReach = WarpConnectivityProbeRange * 0.5f;
            private bool OnFailedIsland(Vector3 candidate)
            {
                for(int i = 0; i < _warpFailedIslands.Count; i++)
                {
                    Vector3 failed = _warpFailedIslands[i];
                    if((failed - candidate).sqrMagnitude > WarpFailedIslandReach * WarpFailedIslandReach) continue;
                    if(_rustAgent.CalculatePathTyped(failed, candidate, _navProbe)
                       && _navProbe.status == NavMeshPathStatus.PathComplete) return true;
                }
                return false;
            }
            private bool TryFindWarpPoint(Vector3 botPos, float radius, float maxWaterDepth, Vector3? finish, out Vector3 result, out WarpCandidateRank rank,
                                          bool requireSight = true, float maxY = float.PositiveInfinity)
            {
                result = botPos;
                rank = WarpCandidateRank.None;
                if(_rustAgent == null) return false;
                _warpCandidates.Clear();
                AddWarpCandidate(botPos, botPos, radius, maxWaterDepth, requireSight, maxY);
                for(int i = 0; i < RescueDryProbeDirections; i++)
                {
                    float ang = Mathf.PI * 2f * i / RescueDryProbeDirections;
                    Vector3 dir = new Vector3(Mathf.Cos(ang), 0f, Mathf.Sin(ang));
                    for(int ring = 1; ring <= 2; ring++)
                        AddWarpCandidate(botPos + dir * (radius * 0.5f * ring), botPos, radius, maxWaterDepth, requireSight, maxY);
                }
                if(_warpCandidates.Count == 0) return false;
                for(int i = 1; i < _warpCandidates.Count; i++)
                {
                    WarpCandidate cur = _warpCandidates[i];
                    int j = i - 1;
                    while(j >= 0 && (cur.Dry != _warpCandidates[j].Dry ? cur.Dry : cur.DistSqr < _warpCandidates[j].DistSqr))
                    {
                        _warpCandidates[j + 1] = _warpCandidates[j];
                        j--;
                    }
                    _warpCandidates[j + 1] = cur;
                }
                int checks = 0;
                _warpFailedIslands.Clear();
                for(int i = 0; i < _warpCandidates.Count; i++)
                {
                    WarpCandidate c = _warpCandidates[i];
                    if(c.Dry && rank < WarpCandidateRank.DryUnverified)
                    {
                        result = c.Pos;
                        rank = WarpCandidateRank.DryUnverified;
                    }
                    if(checks >= WarpConnectivityMaxChecks) continue;
                    if(OnFailedIsland(c.Pos)) continue;
                    checks++;
                    if(!IsWarpTargetConnected(c.Pos, finish))
                    {
                        _warpFailedIslands.Add(c.Pos);
                        continue;
                    }
                    if(c.Dry)
                    {
                        result = c.Pos;
                        rank = WarpCandidateRank.DryConnected;
                        return true;
                    }
                    if(rank < WarpCandidateRank.WetConnected)
                    {
                        result = c.Pos;
                        rank = WarpCandidateRank.WetConnected;
                    }
                }
                return rank != WarpCandidateRank.None;
            }
            private void AddWarpCandidate(Vector3 origin, Vector3 botPos, float radius, float maxWaterDepth, bool requireSight, float maxY)
            {
                if(!_rustAgent.SamplePositionTyped(origin, out var hit, radius)) return;
                Vector3 pos = hit.position;
                float distSqr = (pos - botPos).sqrMagnitude;
                if(distSqr > radius * radius) return;
                if(pos.y > maxY) return;
                if(!IsWarpDepthWithin(pos, maxWaterDepth)) return;
                if(pos.y < TerrainHeightAt(pos) - TrappedUnderTerrainDepth || IsCoveredFromAbove(pos)) return;
                bool dry = IsWarpDepthWithin(pos, RescueMaxWaterDepth);
                if(!dry && CanSwimFloat() && botPos.y - pos.y > WarpMaxUnderwaterDrop) return;
                if(requireSight && IsWallBetween(botPos, pos)) return;
                for(int i = 0; i < _warpCandidates.Count; i++)
                    if((_warpCandidates[i].Pos - pos).sqrMagnitude < 0.25f) return;
                _warpCandidates.Add(new WarpCandidate { Pos = pos, Dry = dry, DistSqr = distSqr });
            }
            private static bool IsWallBetween(Vector3 from, Vector3 to)
            {
                Vector3 a = from + Vector3.up * WarpSightUp;
                Vector3 b = to + Vector3.up * WarpSightUp;
                return Physics.Linecast(a, b, _defaultGraphNodeLosMask, QueryTriggerInteraction.Ignore);
            }

            private const float WarpSightUp = 0.5f;

            private bool IsWarpTargetConnected(Vector3 candidate, Vector3? finish)
            {
                if(_rustAgent == null) return false;
                if(finish.HasValue && IsPathCompleteChained(candidate, finish.Value, null, out _, maxDetours: 0))
                {
                    return true;
                }
                for(int i = 0; i < WarpConnectivityDirections; i++)
                {
                    float ang = Mathf.PI * 2f * i / WarpConnectivityDirections;
                    Vector3 probe = candidate + new Vector3(Mathf.Cos(ang), 0f, Mathf.Sin(ang)) * WarpConnectivityProbeRange;
                    if(!_rustAgent.SamplePositionTyped(probe, out var hit, WarpConnectivitySampleRadius)) continue;
                    if((hit.position - candidate).sqrMagnitude < WarpConnectivityMinEscape * WarpConnectivityMinEscape) continue;
                    if(!IsOnSolidGround(hit.position)) continue;
                    if(_rustAgent.CalculatePathTyped(candidate, hit.position, _navProbe)
                       && _navProbe.status == NavMeshPathStatus.PathComplete)
                    {
                        return true;
                    }
                }
                return false;
            }
            private static bool IsOnSolidGround(Vector3 pos)
            {
                return Physics.Raycast(pos + Vector3.up * 0.5f, Vector3.down, out RaycastHit hit, 2f,
                                       TerrainOnlyMask, QueryTriggerInteraction.Ignore)
                       && hit.collider != null && hit.collider.CompareTag("Main Terrain");
            }
            private static bool IsCoveredFromAbove(Vector3 pos)
            {
                return Physics.Raycast(pos + Vector3.up * OverheadProbeHeight, Vector3.down, out _,
                                       OverheadProbeHeight - OverheadProbeClearance, OverheadProbeMask, QueryTriggerInteraction.Ignore);
            }
            protected bool GetNearestNavMeshPosition(Vector3 pos, out Vector3 pos2, float range)
            {
                bool result = false;
                if (_rustAgent != null && _rustAgent.SamplePositionTyped(pos, out var hit, range))
                {
                    pos2 = hit.position;
                    result = true;
                }
                else pos2 = pos;
                return result;
            }
            protected float GetSpeedFraction(NavigationSpeed speed)
            {
                return speed switch
                {
                    NavigationSpeed.Fast => FastSpeedFraction,
                    NavigationSpeed.Normal => NormalSpeedFraction,
                    NavigationSpeed.Slow => SlowSpeedFraction,
                    NavigationSpeed.Slowest => SlowestSpeedFraction,
                    _ => 1f,
                };
            }

            protected virtual bool HasSwimFins()
            {
                if(_customNpc == null || _customNpc.inventory == null) return false;
                var wear = _customNpc.inventory.containerWear;
                if(wear == null) return false;
                foreach(var item in wear.itemList)
                {
                    if(item == null || item.info == null) continue;
                    if(item.info.shortname == "diving.fins" && item.condition > 0f) return true;
                }
                return false;
            }
            protected virtual float CalculateSpeed(bool swim, bool canSubmerge, bool isClimb)
            {
                float speed = SpeedBase * currentSpeedFraction;
                if(_customNpc != null && _customNpc.IsCrawling()) speed = Mathf.Min(speed, BasePlayer.crawlSpeed);

                if(swim)
                {
                    float fins = HasSwimFins() ? SwimFinsSpeedMultiplier : 1f;
                    speed *= SwimSpeedFraction * fins;
                }

                if(_customNpc != null && _customNpc.Ducked) speed = Mathf.Min(speed * CrouchSpeedFraction, BasePlayer.crouchSpeed);

                if(isClimb) speed *= ClimbSpeedFraction;

                _lastStepSpeed = speed;
                return speed;
            }

            #region Keep apart
            private static readonly List<BaseCustomNpc> ApartBots = new List<BaseCustomNpc>();
            public const float ApartRadius = 1.4f;
            private const float ApartSpeed = 2f;
            private const float ApartFloorGap = 1.8f;

            private Vector3 ApartPush(Vector3 me)
            {
                Vector3 push = Vector3.zero;
                for(int i = ApartBots.Count - 1; i >= 0; i--)
                {
                    BaseCustomNpc other = ApartBots[i];
                    if(other == null || other.IsDestroyed) { ApartBots.RemoveAt(i); continue; }
                    if(other == _customNpc || other.IsDead() || other.isMounted || other.HasParent()) continue;
                    Vector3 away = me - other.ServerPosition;
                    if(Mathf.Abs(away.y) > ApartFloorGap) continue;
                    away.y = 0f;
                    float dist = away.magnitude;
                    if(dist >= ApartRadius) continue;
                    if(dist < 0.05f)
                    {
                        Vector3 side = _customNpc.transform.right;
                        side.y = 0f;
                        away = _customNpc.net.ID.Value > other.net.ID.Value ? side : -side;
                    }
                    push += away.normalized * (1f - dist / ApartRadius);
                }
                return push;
            }

            private void StepApart(float delta)
            {
                if(_customNpc == null || !_customNpc.KeepsApart || _customNpc.isMounted || _customNpc.HasParent()) return;
                Vector3 pos = _customNpc.ServerPosition;
                Vector3 push = ApartPush(pos);
                if(push.sqrMagnitude < 1e-4f) return;
                Vector3 to = pos + Vector3.ClampMagnitude(push, 1f) * (ApartSpeed * delta);
                if(!TryNearestWalkable(to, 0.3f, out Vector3 walkable) || Mathf.Abs(walkable.y - pos.y) > 0.5f) return;
                if(Physics.Linecast(pos + Vector3.up * 0.6f, walkable + Vector3.up * 0.6f, SelfWalkBlockMask, QueryTriggerInteraction.Ignore)) return;
                _customNpc.ServerPosition = walkable;
            }

            private bool FinishTakenByNeighbour(Vector3 botPos, Vector3 target)
            {
                if(_customNpc == null || !_customNpc.KeepsApart || Vector3Ex.Distance2D(botPos, target) > _finishArrival + ApartRadius) return false;
                foreach(BaseCustomNpc other in ApartBots)
                {
                    if(other == null || other == _customNpc || other.IsDestroyed || other.IsDead() || other.isMounted || other.HasParent()) continue;
                    Vector3 at = other.ServerPosition;
                    if(Mathf.Abs(at.y - target.y) <= ApartFloorGap && Vector3Ex.Distance2D(at, target) < ApartRadius) return true;
                }
                return false;
            }
            #endregion

            public void Think(float delta)
            {
                Vector3 before = _customNpc != null ? _customNpc.ServerPosition : Vector3.zero;
                int warps = _warpCount;
                ThinkStep(delta);
                if(_warpCount != warps) return;
                KeepOutOfDamageTrigger(before);
                KeepOnSupport(before);
            }
            private void ThinkStep(float delta)
            {
                if(_customNpc == null || _customNpc.IsDestroyed || _customNpc.IsDead())
                {
                    CloseDoorPassesOnDestroy();
                    return;
                }
                TickInterruptedDoorPasses();
                if(_path == null) return;

                TrackWatchdogBlindWindow();

                if(_pause)
                {
                    if(_isPathJumpActive && _path.HasPath && _path.CurrentNode != null)
                    {
                        TickJump(_path.CurrentNode, delta);
                        return;
                    }
                    if(_obstacleJumpActive)
                    {
                        TickObstacleJump(delta);
                        return;
                    }
                    StepApart(delta);
                    TryApplyOverrideFacing();
                    return;
                }

                Vector3 botPos = _customNpc.ServerPosition;
                if(CheckIdleWatchdog(botPos)) return;

                if(TickObstacleReaction(delta)) { ApplyFacing(_path?.CurrentNode); return; }

                if(TickHazardReaction()) { ApplyFacing(_path?.CurrentNode); return; }

                if(TickSwimShortcut()) { ApplyFacing(_path?.CurrentNode); return; }
                if(TickDeepWaterReaction()) { ApplyFacing(_path?.CurrentNode); return; }

                if(TickSafeZoneReaction()) { ApplyFacing(_path?.CurrentNode); return; }
                if(TickDoorTrapReaction()) { ApplyFacing(_path?.CurrentNode); return; }

                if(_type == NavigationType.None || _type == NavigationType.Stuck || _type == NavigationType.Finish)
                {
                    StepApart(delta);
                    TryApplyOverrideFacing();
                    return;
                }

                if(_path.IsFindingPath)
                {
                    _type = NavigationType.FindingPath;
                    StepApart(delta);
                    _stallStart = UnityEngine.Time.time;
                    _stallLastPos = _customNpc.ServerPosition;
                    return;
                }
                if(_type == NavigationType.FindingPath) _type = NavigationType.Moving;

                if(TryRebuildOnGraphVersion()) return;

                float thinkJumpSqr = (botPos - _lastThinkPos).sqrMagnitude;
                _lastThinkPos = botPos;
                if(thinkJumpSqr >= TeleportDetectSqr && _path.HasPath)
                {
                    Vector3? resumeFinish = _path.FinishNode?.Position;
                    if(resumeFinish.HasValue)
                    {
                        StartMoved(resumeFinish.Value, currentSpeedFraction);
                    }
                    else
                    {
                        ClearPathAndState();
                        _type = NavigationType.None;
                        _lastStuckReason = StuckReason.None;
                    }
                    return;
                }

                if(!_path.HasPath)
                {
                    if(CheckFinishArrived(botPos))
                    {
                        FinishNavigation();
                        return;
                    }
                    _lastStuckReason = StuckReason.PathPlanningFailed;
                    OnStuck();
                    return;
                }

                if(_skipFirstNodeOnReady)
                {
                    _skipFirstNodeOnReady = false;
                    ResetPerStepState();
                    bool skipped = false;
                    if(_path.Count > 1 && _path.CurrentNode != _path.FinishNode)
                        skipped = _path.TryNextNode(out _);
                }

                PathNode currentNode = _path.CurrentNode;
                if(currentNode == null)
                {
                    _lastStuckReason = StuckReason.Other;
                    OnStuck();
                    return;
                }

                {
                    int sIdx = _path.CurrentIndex - 1;
                    if(sIdx >= 0 && sIdx < _path.Count)
                    {
                        var sPrev = _path[sIdx];
                        if(sPrev != null && sPrev.IsStuckPoint)
                        {
                            _lastStuckReason = StuckReason.PathPartialUnreachable;
                            OnStuck();
                            return;
                        }
                    }
                }

                if((botPos - _stallLastPos).sqrMagnitude >= StallEpsSqr)
                {
                    _stallStart = UnityEngine.Time.time;
                    _stallLastPos = botPos;
                }
                else if(UnityEngine.Time.time - _stallStart > StallTimeout && UnityEngine.Time.time >= _stuckCooldownUntil)
                {
                    if(CheckFinishArrived(botPos))
                    {
                        FinishNavigation();
                        return;
                    }
                    _stuckCooldownUntil = UnityEngine.Time.time + StuckCooldown;
                    _lastStuckReason = StuckReason.Stall;
                    OnStuck();
                    return;
                }

                _rustAgent?.TryOpenDoors();

                bool swim = IsSwimming(botPos, out float swimSurfaceY, out bool canSubmerge);

                bool isFinishNode = currentNode == _path.FinishNode;
                if(isFinishNode && CheckFinishArrived(botPos))
                {
                    FinishNavigation();
                    return;
                }
                if(isFinishNode && swim && !canSubmerge
                   && Vector3Ex.Distance2D(botPos, currentNode.Position) <= FinishTolerance
                   && currentNode.Position.y < swimSurfaceY + SwimSurfaceOffset - ArrivalDistanceDirect)
                {
                    FinishNavigation();
                    return;
                }

                int prevIdx = _path.CurrentIndex - 1;
                PathNode prevNode = prevIdx >= 0 ? _path[prevIdx] : null;

                bool prevNav = prevNode != null && prevNode.Hint.HasFlag(NodeHint.NavMesh);
                bool currNav = currentNode.Hint.HasFlag(NodeHint.NavMesh);

                if(swim)
                {
                    if(currentNode.LayerLeg)
                    {
                        _navMeshStepDispatched = false;
                        _navMeshPartialLeg = false;
                        TickDirect(currentNode, delta, swim: true, swimSurfaceY, canSubmerge);
                    }
                    else if(_rustAgent != null && _rustAgent.SamplePositionTyped(botPos, out _, NavMeshSnapRadius))
                    {
                        TickNavMesh(currentNode, delta, swim, swimSurfaceY, canSubmerge);
                    }
                    else
                    {
                        _navMeshStepDispatched = false;
                        _navMeshPartialLeg = false;
                        TickDirect(currentNode, delta, swim: true, swimSurfaceY, canSubmerge);
                    }
                }
                else if(prevNode != null && prevNode.Hint.HasFlag(NodeHint.OpenDoor))
                {
                    TickDoor(currentNode, delta);
                }
                else if(prevNode != null && prevNode.Hint.HasFlag(NodeHint.CloseDoor))
                {
                    TickCloseDoor(prevNode, currentNode, delta);
                }
                else if(prevNode != null && prevNode.Hint.HasFlag(NodeHint.Jump))
                {
                    TickJump(currentNode, delta);
                }
                else if(currentNode.LayerLeg)
                {
                    TickDirect(currentNode, delta, false, 0f, false);
                }
                else if(prevNav && currNav)
                {
                    if(Vector3.Distance(botPos, currentNode.Position) < 1.5f)
                        TickDirect(currentNode, delta, false, 0f, false);
                    else
                        TickNavMesh(currentNode, delta, swim, swimSurfaceY, canSubmerge);
                }
                else if(prevNav && !currNav)
                {
                    if(TryEnsureTransition(prevNode, currentNode))
                    {
                        ApplyFacing(_path.CurrentNode);
                        return;
                    }
                    bool strandedFwd = (botPos - currentNode.Position).sqrMagnitude >= StrandedDistSqr;
                    if(strandedFwd
                       || (!currentNode.IsGraph && !currentNode.IsTransition
                           && (prevNode.Position - currentNode.Position).sqrMagnitude >= 4f))
                    {
                        _lastStuckReason = StuckReason.PathPlanningFailed;
                        OnStuck();
                        return;
                    }
                    TickDirect(currentNode, delta, false, 0f, false);
                }
                else if(!prevNav && currNav)
                {
                    if(_rustAgent != null && _rustAgent.SamplePositionTyped(botPos, out _, NavMeshSnapRadius))
                    {
                        TickNavMesh(currentNode, delta, swim, swimSurfaceY, canSubmerge);
                    }
                    else if(prevNode != null)
                    {
                        if(TryEnsureTransition(prevNode, currentNode))
                        {
                            ApplyFacing(_path.CurrentNode);
                            return;
                        }
                        bool strandedBwd = (botPos - currentNode.Position).sqrMagnitude >= StrandedDistSqr;
                        if(strandedBwd
                           || (!currentNode.IsGraph && !currentNode.IsTransition
                               && (prevNode.Position - currentNode.Position).sqrMagnitude >= 4f))
                        {
                            _lastStuckReason = StuckReason.PathPlanningFailed;
                            OnStuck();
                            return;
                        }
                        TickDirect(currentNode, delta, false, 0f, false);
                    }
                    else
                    {
                        TickDirect(currentNode, delta, false, 0f, false);
                    }
                }
                else
                {
                    bool strandedElse = (botPos - currentNode.Position).sqrMagnitude >= StrandedDistSqr;
                    if(strandedElse
                       || (!currentNode.IsGraph && !currentNode.IsTransition
                           && (botPos - currentNode.Position).sqrMagnitude >= 4f))
                    {
                        if(!strandedElse && TryEnsureTransition(prevNode, currentNode))
                        {
                            ApplyFacing(_path.CurrentNode);
                            return;
                        }
                        _lastStuckReason = StuckReason.PathPlanningFailed;
                        OnStuck();
                        return;
                    }
                    TickDirect(currentNode, delta, false, 0f, false);
                }

                ApplyFacing(currentNode);
            }
            private void TickDirect(PathNode currentNode, float delta, bool swim, float swimSurfaceY, bool canSubmerge)
            {
                if(_customNpc == null) return;

                _directNode = currentNode;
                Vector3 current = _customNpc.ServerPosition;
                Vector3 target = currentNode.Position;
                int prevIdx = _path.CurrentIndex - 1;
                PathNode prevNodeLocal = prevIdx >= 0 ? _path[prevIdx] : null;
                bool isClimb = prevNodeLocal != null && prevNodeLocal.Hint.HasFlag(NodeHint.Climb);

                if(swim && !canSubmerge)
                {
                    target.y = swimSurfaceY + SwimSurfaceOffset;
                }

                bool climbActive = isClimb && Vector3Ex.Distance2D(current, target) < ClimbDelayDistance;
                _isOnLadderActive = climbActive;
                float moveStep = CalculateSpeed(swim, canSubmerge, climbActive) * delta;

                Vector3 next = Vector3.MoveTowards(current, target, moveStep);

                if(swim && !canSubmerge)
                {
                    next.y = Mathf.MoveTowards(current.y, swimSurfaceY + SwimSurfaceOffset, SwimVerticalSpeed * delta);
                    float floor = SwimFloorAt(current, next, swimSurfaceY);
                    if(next.y < floor) next.y = floor;
                }

                if(swim && IsSwimStepBlocked(current, next, target, swimSurfaceY)) return;

                _customNpc.ServerPosition = next;
                if(!swim && !isClimb) StepApart(delta);

                float arrivalDist;
                if(isClimb || currentNode.IsLayerStartRescue || (swim && canSubmerge))
                    arrivalDist = Vector3.Distance(_customNpc.ServerPosition, target);
                else
                    arrivalDist = Vector3Ex.Distance2D(_customNpc.ServerPosition, target);

                if(arrivalDist <= ArrivalDistanceDirect)
                {
                    AdvanceStep();
                }
            }
            private const float StepSupportReach = 2.5f;
            private const float FallMaxDrop = 20f;
            private static readonly int StepSupportMask = Path._physFloorMask | LayerMask.GetMask("Transparent");

            private void KeepOnSupport(Vector3 before)
            {
                if(_customNpc == null || _customNpc.IsDestroyed || _customNpc.IsDead() || _customNpc.isMounted || _customNpc.HasParent()) return;
                Vector3 pos = _customNpc.ServerPosition;
                if((pos - before).sqrMagnitude < 1e-6f || _isPathJumpActive || _obstacleJumpActive || IsOnLadderSegment() || _customNpc.IsSwimming()) return;
                if(_navMeshStepDispatched) return;
                float top = Mathf.Max(before.y, pos.y) + 0.5f;
                if(Physics.CheckCapsule(new Vector3(pos.x, top, pos.z), pos - Vector3.up * StepSupportReach, 0.3f, StepSupportMask, QueryTriggerInteraction.Ignore)) return;
                if(_rustAgent != null && _rustAgent.SamplePositionTyped(pos, out var navHit, StepSupportReach)
                   && navHit.position.y <= pos.y + 0.5f && navHit.position.y >= pos.y - StepSupportReach) return;
                HelperNavLayers.INavLayer building = HelperNavLayers.BuildingNavLayer.Instance;
                if(building != null && building.Enabled && building.Probe(pos, NavLayerMargin, out object buildingHandle, out _, out _)
                   && building.TryNearestSurface(buildingHandle, pos, out Vector3 floor)
                   && floor.y <= pos.y + 1f && floor.y >= pos.y - StepSupportReach && Vector3Ex.Distance2D(floor, pos) <= 1.5f) return;
                float landY = float.NegativeInfinity;
                if(Physics.Raycast(pos + Vector3.up * 0.3f, Vector3.down, out RaycastHit hit, FallMaxDrop + 0.3f, StepSupportMask, QueryTriggerInteraction.Ignore))
                    landY = hit.point.y;
                Vector3 swimAt = new Vector3(pos.x, WaterLevel.GetWaterLevel(pos, false) + SwimSurfaceOffset, pos.z);
                if(swimAt.y > landY && swimAt.y < pos.y && WaterLevel.Test(swimAt, false, true, _customNpc)) landY = swimAt.y;
                bool falls = landY > float.NegativeInfinity && pos.y - landY <= FallMaxDrop;
                HaltMovement();
                HelperVehicles.MoveBot(_customNpc, falls ? new Vector3(pos.x, landY, pos.z) : before);
                _lastStuckReason = StuckReason.Other;
                OnStuck();
            }
            private const float SwimObstacleProbeInterval = 0.25f;
            private const float SwimObstacleProbeDistance = 0.6f;
            private const float SwimObstacleProbeMinRange = 1f;
            private const float SwimClimbableNormalY = 0.5f;
            private float _nextSwimObstacleProbe;
            private bool _swimObstacleBlocked;
            private bool IsSwimStepBlocked(Vector3 current, Vector3 next, Vector3 target, float surfaceY)
            {
                if(UnityEngine.Time.time < _nextSwimObstacleProbe) return _swimObstacleBlocked;
                _nextSwimObstacleProbe = UnityEngine.Time.time + SwimObstacleProbeInterval;
                Vector3 step = next - current;
                step.y = 0f;
                float stepLen = step.magnitude;
                if(stepLen < 0.001f || Vector3Ex.Distance2D(current, target) <= SwimObstacleProbeMinRange)
                {
                    _swimObstacleBlocked = false;
                    return false;
                }
                Vector3 dir = step / stepLen;
                _swimObstacleBlocked = Physics.Raycast(current, dir, out RaycastHit hit, Mathf.Max(stepLen, SwimObstacleProbeDistance),
                    Path._physFloorMask, QueryTriggerInteraction.Ignore)
                    && hit.normal.y < SwimClimbableNormalY
                    && !ClimbableLedgeTop(new Vector3(hit.point.x + dir.x * SwimLedgeProbeInset, current.y, hit.point.z + dir.z * SwimLedgeProbeInset),
                                          hit.point.y, surfaceY, out _);
                return _swimObstacleBlocked;
            }
            private const float SwimLedgeProbeInset = 0.3f;
            private static bool ClimbableLedgeTop(Vector3 at, float minY, float surfaceY, out float top)
            {
                top = minY;
                float fromY = surfaceY + SwimExitMaxAboveWater + 0.1f;
                if(fromY <= minY) return false;
                if(!Physics.Raycast(new Vector3(at.x, fromY, at.z), Vector3.down, out RaycastHit hit, fromY - minY + 0.05f,
                                    Path._physFloorMask, QueryTriggerInteraction.Ignore)) return false;
                if(hit.normal.y < SwimClimbableNormalY) return false;
                top = hit.point.y;
                return true;
            }
            private float SwimFloorAt(Vector3 current, Vector3 next, float surfaceY)
            {
                float floor = TerrainHeightAt(next);
                if(!ClimbableLedgeTop(next, floor, surfaceY, out float top) || top <= floor) return floor;
                if(top > current.y && Physics.Raycast(current + Vector3.up * 0.1f, Vector3.up, top - current.y,
                                                      Path._physFloorMask, QueryTriggerInteraction.Ignore)) return floor;
                return top;
            }
            private void TickNavMesh(PathNode currentNode, float delta, bool swim, float surfaceY, bool canSubmerge)
            {
                if(_customNpc == null || _rustAgent == null) return;
                Vector3 botPos = _customNpc.ServerPosition;
                if(!_navMeshStepDispatched)
                {
                    if(!_rustAgent.SamplePositionTyped(botPos, out var startHit, NavMeshSnapRadius))
                    {
                        _lastStuckReason = StuckReason.Other;
                        OnStuck();
                        return;
                    }
                    if(!_rustAgent.SamplePositionTyped(currentNode.Position, out var targetHit, 5f))
                    {
                        _lastStuckReason = StuckReason.PathPlanningFailed;
                        OnStuck();
                        return;
                    }
                    if(!_rustAgent.CalculatePathTyped(startHit.position, targetHit.position, _navProbe))
                    {
                        _lastStuckReason = StuckReason.PathPlanningFailed;
                        OnStuck();
                        return;
                    }
                    if(TryDetourAroundHazard(startHit.position, targetHit.position)) return;
                    if(_navProbe.status == NavMeshPathStatus.PathPartial)
                    {
                        int nextIdxFb = _path.CurrentIndex + 1;
                        PathNode nextFb = nextIdxFb < _path.Count ? _path[nextIdxFb] : null;
                        bool isGraphPath = (currentNode != null && currentNode.IsGraph && !currentNode.IsLayer)
                                        || (nextFb != null && nextFb.IsGraph && !nextFb.IsLayer);
                        if(isGraphPath)
                        {
                            TickDirect(currentNode, delta, false, 0f, false);
                            return;
                        }
                        var corners = _navProbe.corners;
                        Vector3 lastCorner = corners != null && corners.Count >= 1 ? _rustAgent.PathEndWorld(_navProbe, targetHit.position, out _) : startHit.position;
                        float partialProgress = Vector3Ex.Distance2D(startHit.position, currentNode.Position) - Vector3Ex.Distance2D(lastCorner, currentNode.Position);
                        if(TryGraphSwitchOnPartial(currentNode, startHit.position, partialProgress)) return;
                        if(partialProgress < PartialMinProgress && UnityEngine.Time.time >= _islandSelfWalkUntil)
                        {
                            if(TryInsertPathDetour(startHit.position, partialProgress)) return;
                            _lastStuckReason = StuckReason.PathPartialUnreachable;
                            OnStuck();
                            return;
                        }
                        if((lastCorner - startHit.position).sqrMagnitude > 2.25f
                           && (lastCorner - currentNode.Position).sqrMagnitude > 0.25f
                           && !currentNode.IsTransition)
                        {
                            var t = PathNode.GetPool(lastCorner, NodeHint.NavMesh);
                            t.IsTransition = true;
                            _path.Insert(_path.CurrentIndex, t);
                            int pIdx = _path.CurrentIndex - 1;
                            if(pIdx >= 0 && _path[pIdx] != null) _path[pIdx].Hint |= NodeHint.NavMesh;
                            HaltMovement();
                            return;
                        }
                        BeginNavLeg();
                        _navMeshPartialLeg = true;
                        _partialLegTarget = lastCorner;
                        return;
                    }
                    if(_navProbe.status != NavMeshPathStatus.PathComplete)
                    {
                        _lastStuckReason = StuckReason.PathPlanningFailed;
                        OnStuck();
                        return;
                    }
                    BeginNavLeg();
                    _navMeshPartialLeg = false;
                }
                WalkNavLeg(delta, swim, surfaceY, canSubmerge);

                if(_navMeshPartialLeg && Vector3Ex.Distance2D(_customNpc.ServerPosition, _partialLegTarget) <= 1.5f)
                {
                    _navMeshStepDispatched = false;
                    _navMeshPartialLeg = false;
                }

                if(Vector3Ex.Distance2D(_customNpc.ServerPosition, currentNode.Position) <= ArrivalDistanceDirect)
                    AdvanceStep();
            }
            private void BeginNavLeg()
            {
                _navLegCorners.Clear();
                _rustAgent.AddCornersWorld(_navProbe, _navLegCorners);
                _navLegIdx = _navLegCorners.Count > 1 ? 1 : 0;
                _navLegCorner = _navLegCorners.Count > 0 ? _navLegCorners[_navLegIdx] : _customNpc.ServerPosition;
                _navMeshStepDispatched = true;
                _nextSafeZoneProbe = 0f;
                _nextDeepWaterProbe = 0f;
            }
            private void WalkNavLeg(float delta, bool swim, float surfaceY, bool canSubmerge)
            {
                if(_navLegCorners.Count == 0) return;
                float step = CalculateSpeed(swim, canSubmerge, false) * delta;
                Vector3 pos = _customNpc.ServerPosition;
                while(step > 0f && _navLegIdx < _navLegCorners.Count)
                {
                    Vector3 corner = _navLegCorners[_navLegIdx];
                    _navLegCorner = corner;
                    Vector3 flat = corner - pos; flat.y = 0f;
                    float d = flat.magnitude;
                    if(d <= step) { pos.x = corner.x; pos.z = corner.z; step -= d; _navLegIdx++; }
                    else { pos += flat / d * step; step = 0f; }
                }
                SnapNavLegToGround(ref pos, delta);
                if(swim && !canSubmerge)
                    pos.y = Mathf.MoveTowards(_customNpc.ServerPosition.y, surfaceY + SwimSurfaceOffset, SwimVerticalSpeed * delta);
                if(swim && IsSwimObstacleAhead(_customNpc.ServerPosition, pos, out RaycastHit swimHit))
                {
                    if(UnityEngine.Time.time >= _nextSwimObstacleStuck)
                    {
                        _nextSwimObstacleStuck = UnityEngine.Time.time + SwimObstacleStuckInterval;
                        _lastStuckReason = StuckReason.SwimObstacle;
                        (_customNpc.brain?.StateMachine?.GetCurrentState() as FSM.IRouterState)?.OnStuck();
                    }
                    return;
                }
                _customNpc.ServerPosition = pos;
                if(!swim) StepApart(delta);
            }
            private bool TickDeepWaterReaction()
            {
                if(_customNpc == null || _type != NavigationType.Moving) return false;
                if(!Guard.Policy.DeepWaterStop) return false;
                if(_customNpc.IsInWater) return false;
                if(UnityEngine.Time.time < _nextDeepWaterProbe) return false;
                _nextDeepWaterProbe = UnityEngine.Time.time + DeepWaterProbeInterval;
                if(!IsDeepWaterAhead(out Vector3 entry, out float depth, out float distance)) return false;

                var router = _customNpc.brain?.StateMachine?.GetCurrentState() as FSM.IRouterState;
                if(router == null || router.CanSwimAhead(entry, depth, distance)) return false;

                HaltMovement();
                _type = NavigationType.Stuck;
                _lastStuckReason = StuckReason.DeepWaterAhead;
                router.OnStuck();
                return true;
            }
            private bool IsDeepWaterAhead(out Vector3 entry, out float depth, out float distance)
            {
                entry = Vector3.zero; depth = 0f; distance = 0f;
                Vector3 from = _customNpc.ServerPosition;
                Vector3 to;
                if(_navMeshStepDispatched && _navLegIdx < _navLegCorners.Count) to = _navLegCorners[_navLegIdx];
                else
                {
                    PathNode node = _path?.CurrentNode;
                    if(node == null) return false;
                    to = node.Position;
                    if(!_navMeshStepDispatched && node != _directNode && node.Hint.HasFlag(NodeHint.NavMesh) && !node.LayerLeg)
                        return IsDeepWaterAt(from, to, out entry, out depth, out distance);
                }
                if(to == Vector3.zero) return false;
                Vector3 dir = to - from; dir.y = 0f;
                float legLen = dir.magnitude;
                if(legLen < 0.01f) return false;
                dir /= legLen;
                float scan = Mathf.Min(legLen, DeepWaterScanDistance);
                for(float d = DeepWaterProbeStep; d <= scan; d += DeepWaterProbeStep)
                {
                    float deep = DepthAtGround(from + dir * d, out Vector3 probe);
                    if(deep < DeepWaterSwimDepth) continue;
                    entry = probe; depth = deep; distance = d;
                    return true;
                }
                return false;
            }
            private static bool IsDeepWaterAt(Vector3 from, Vector3 point, out Vector3 entry, out float depth, out float distance)
            {
                entry = Vector3.zero; depth = 0f;
                distance = Vector3Ex.Distance2D(from, point);
                if(distance < 0.01f || distance > DeepWaterScanDistance) return false;
                float deep = DepthAtGround(point, out Vector3 probe);
                if(deep < DeepWaterSwimDepth) return false;
                entry = probe; depth = deep;
                return true;
            }
            private static float DepthAtGround(Vector3 point, out Vector3 ground)
            {
                ground = point;
                var water = WaterLevel.GetWaterInfo(point, waves: false, volumes: false);
                if(!water.isValid) return 0f;
                HelperMap.ToGroundPoint(ref ground);
                return water.surfaceLevel - ground.y;
            }
            private bool TickSafeZoneReaction()
            {
                if(_customNpc == null || _type != NavigationType.Moving || _path == null || !_path.HasPath) return false;
                if(!_customNpc.AvoidSafeZonesNow) return false;
                if(UnityEngine.Time.time < _nextSafeZoneProbe) return false;
                _nextSafeZoneProbe = UnityEngine.Time.time + SafeZoneProbeInterval;
                if(HelperSafeZones.Count == 0) return false;
                if(!FindSafeZoneAhead(out Vector3 entry)) return false;

                HaltMovement();
                _type = NavigationType.Stuck;
                _lastStuckReason = StuckReason.SafeZone;
                (_customNpc.brain?.StateMachine?.GetCurrentState() as FSM.IRouterState)?.OnStuck();
                return true;
            }
            private bool TickDoorTrapReaction()
            {
                if(_customNpc == null || _type != NavigationType.Moving || HelperDoorTraps.Count == 0) return false;
                Vector3 botPos = _customNpc.ServerPosition;
                if(!HelperDoorTraps.IsInside(botPos, out Vector3 trapCenter)) return false;
                if(!Guard.Policy.WarpHazardPush || !TryFindHazardExit(botPos, trapCenter, Guard.ClampRadius(HazardPushMaxDist), out Vector3 exit))
                    return false;
                HaltMovement();
                Warp(exit);
                ReportDamageTrigger();
                return true;
            }
            private void KeepOutOfDamageTrigger(Vector3 before)
            {
                if(_customNpc == null || _customNpc.IsDestroyed || _customNpc.IsDead()) return;
                Vector3 pos = _customNpc.ServerPosition;
                if((pos - before).sqrMagnitude < 1e-6f) return;
                string what;
                if(HelperDoorTraps.Count > 0 && HelperDoorTraps.IsInside(pos) && !HelperDoorTraps.IsInside(before)) what = "a door damage trigger";
                else if(_customNpc.health < _customNpc.MaxHealth() * HazardCareHealthShare
                        && IsInsideHurtTrigger(pos, out Vector3 hazardCenter, out float hazardRadius, out _, out string hazardKind, out bool hazardMobile, out float crossingDamage)
                        && crossingDamage >= _customNpc.health * HazardCrossHealthShare
                        && !IsInsideHurtTrigger(before, out _, out _, out _, out _, out _, out _))
                {
                    if(!hazardMobile) RememberHazard(hazardCenter, hazardRadius);
                    what = $"{hazardKind} costing {crossingDamage:0} of health {_customNpc.health:0}";
                }
                else return;
                Vector3 back = _isPathJumpActive ? _jumpStart : _obstacleJumpActive ? _obstacleJumpStart : before;
                if(_isPathJumpActive || _obstacleJumpActive)
                {
                    _isPathJumpActive = false;
                    _obstacleJumpActive = false;
                    SetAirborne(false);
                }
                HaltMovement();
                _customNpc.ServerPosition = back;
                ReportDamageTrigger();
            }
            private void ReportDamageTrigger()
            {
                _type = NavigationType.Stuck;
                _lastStuckReason = StuckReason.DamageTrigger;
                (_customNpc.brain?.StateMachine?.GetCurrentState() as FSM.IRouterState)?.OnStuck();
            }
            private bool FindSafeZoneAhead(out Vector3 entry)
            {
                entry = Vector3.zero;
                Vector3 origin = _customNpc.ServerPosition;
                Vector3 from = origin;
                if(_navMeshStepDispatched)
                {
                    for(int i = _navLegIdx; i < _navLegCorners.Count; i++)
                    {
                        Vector3 corner = _navLegCorners[i];
                        if(HelperSafeZones.SegmentEnters(origin, from, corner, out entry)) return true;
                        from = corner;
                    }
                }
                int last = _path.Count - 1;
                for(int i = Mathf.Max(0, _path.CurrentIndex); i <= last; i++)
                {
                    PathNode node = _path[i];
                    if(node == null) continue;
                    Vector3 to = node.Position;
                    if(i == last && HelperSafeZones.IsTargetBlocked(origin, to))
                    {
                        entry = to;
                        return true;
                    }
                    bool navMeshLeg = node.Hint.HasFlag(NodeHint.NavMesh) && !node.LayerLeg;
                    if(HelperSafeZones.SegmentEnters(origin, navMeshLeg ? to : from, to, out entry)) return true;
                    from = to;
                }
                return false;
            }
            public bool HasCompleteDryPathTo(Vector3 target)
            {
                if(_customNpc == null || _rustAgent == null) return false;
                if(!GetNearestNavMeshPosition(_customNpc.ServerPosition, out Vector3 start, NavMeshSnapRadius)) return false;
                if(!IsPathCompleteChained(start, target, _dryPathCorners)) return false;
                var corners = _dryPathCorners;
                if(corners.Count == 0) return true;
                for(int i = 0; i < corners.Count; i++)
                {
                    Vector3 a = corners[i];
                    if(IsDeepAt(a)) return false;
                    if(i + 1 >= corners.Count) break;
                    Vector3 b = corners[i + 1];
                    float len = Vector3.Distance(a, b);
                    for(float d = DryPathProbeStep; d < len; d += DryPathProbeStep)
                        if(IsDeepAt(Vector3.Lerp(a, b, d / len))) return false;
                }
                return true;
            }
            private readonly List<Vector3> _dryPathCorners = new List<Vector3>();
            private static bool IsDeepAt(Vector3 point) => CoreEx.DepthOver(point) >= DeepWaterSwimDepth;
            private bool IsSwimObstacleAhead(Vector3 from, Vector3 to, out RaycastHit hit)
            {
                hit = default;
                Vector3 dir = to - from; dir.y = 0f;
                float step = dir.magnitude;
                if(step < 0.001f) return false;
                dir /= step;
                if(CoreEx.DepthOver(to) < CoreEx.DepthOver(from) - SwimShoreApproachEpsilon) return false;
                Vector3 origin = from + Vector3.up * SwimObstacleProbeHeight;
                if(!Physics.SphereCast(origin, SwimObstacleProbeRadius, dir, out hit, step,
                       SwimObstacleMask, QueryTriggerInteraction.Ignore)) return false;
                return Vector3.Angle(hit.normal, Vector3.up) >= SwimObstacleMinSlope;
            }
            private void SnapNavLegToGround(ref Vector3 pos, float delta)
            {
                if(_rustAgent == null) return;
                if(!_rustAgent.SamplePositionTyped(pos, out var hit, 2.5f)) return;
                float navY = hit.position.y;
                if(navY > pos.y) { pos.y = navY; return; }
                if(pos.y - navY > SnapCoveredProbeMinDrop && IsCoveredFromAbove(new Vector3(pos.x, navY, pos.z))) return;
                float snapFloor = float.NegativeInfinity;
                if(CanSwimFloat())
                {
                    var snapWater = WaterLevel.GetWaterInfo(pos, waves: false, volumes: true, _customNpc);
                    if(snapWater.isValid) snapFloor = snapWater.surfaceLevel - WadeDepth;
                }
                pos.y = Mathf.Max(Mathf.Max(navY, snapFloor), pos.y - 8f * delta);
            }
            private void TickJump(PathNode currentNode, float delta)
            {
                if(_customNpc == null) return;
                if(!_isPathJumpActive)
                {
                    _jumpStart = _customNpc.ServerPosition;
                    _jumpFinish = currentNode.Position;
                    _jumpProgress = 0f;
                    _isPathJumpActive = true;
                    SetAirborne(true);
                }
                _jumpProgress = Mathf.Clamp01(_jumpProgress + delta / JumpDuration);
                _customNpc.ServerPosition = EvaluateJumpArc(_jumpStart, _jumpFinish, JumpArcHeight, _jumpProgress);
                if(_jumpProgress >= 1f)
                {
                    _isPathJumpActive = false;
                    SetAirborne(false);
                    AdvanceStep();
                }
            }
            public void SetFacingDirectionEntity(BaseEntity entity, bool aimAtHead = false)
            {
                _overrideFacingMode = OverrideFacingDirectionMode.Entity;
                _facingDirectionEntity = entity;
                _facingAimAtHead = aimAtHead;
            }
            public void SetFacingDirectionOverride(Vector3 direction)
            {
                _overrideFacingMode = OverrideFacingDirectionMode.Direction;
                _facingDirectionOverride = direction;
            }
            public void ClearFacingDirectionOverride()
            {
                _overrideFacingMode = OverrideFacingDirectionMode.None;
                _facingDirectionEntity = null;
            }
            private bool TryApplyOverrideFacing()
            {
                if(_customNpc == null || _overrideFacingMode == OverrideFacingDirectionMode.None) return false;
                if(_overrideFacingMode == OverrideFacingDirectionMode.Direction)
                {
                    if(_facingDirectionOverride.sqrMagnitude > 0.001f)
                        _customNpc.SetLookAngles(_facingDirectionOverride);
                }
                else if(_facingDirectionEntity != null && _facingDirectionEntity.IsValid())
                {
                    Vector3 point = _facingAimAtHead && _facingDirectionEntity is BasePlayer player && player.eyes != null
                        ? player.eyes.position
                        : _facingDirectionEntity.CenterPoint();
                    Vector3 d = point - _customNpc.eyes.position;
                    if(d.sqrMagnitude > 0.001f) _customNpc.SetLookAngles(d);
                }
                return true;
            }
            private void ApplyFacing(PathNode currentNode)
            {
                if(_customNpc == null || currentNode == null) return;
                if(TryApplyOverrideFacing()) return;
                Vector3 botPos = _customNpc.ServerPosition;
                int prevIdx = _path.CurrentIndex - 1;
                PathNode prevNode = prevIdx >= 0 ? _path[prevIdx] : null;
                bool climbing = prevNode != null && prevNode.Hint.HasFlag(NodeHint.Climb);
                if(climbing)
                {
                    if(_climbFacingDir == Vector3.zero)
                    {
                        var ladder = prevNode.Entity as Collider;
                        if(ladder != null)
                        {
                            Vector3 outDir = Vector3Ex.Direction2D(botPos, ladder.bounds.center);
                            if(outDir.sqrMagnitude > 0.001f) _climbFacingDir = -outDir;
                        }
                        if(_climbFacingDir == Vector3.zero)
                        {
                            Vector3 fromPos = prevNode.Position;
                            Vector3 d = Vector3Ex.Direction2D(currentNode.Position, fromPos);
                            if(d.sqrMagnitude > 0.001f) _climbFacingDir = d;
                        }
                    }
                    if(_climbFacingDir != Vector3.zero) _customNpc.SetLookAngles(_climbFacingDir);
                    return;
                }
                _climbFacingDir = Vector3.zero;

                bool navFacing = _navMeshStepDispatched && _navLegCorners.Count > 0;
                Vector3 facingTarget = navFacing ? _navLegCorner : currentNode.Position;
                Vector3 fd = Vector3Ex.Direction2D(facingTarget, botPos);
                if(fd.sqrMagnitude > 0.001f) _customNpc.SetLookAngles(fd);
            }
            private void ResetPerStepState(bool interruptDoorPass = true)
            {
                _navMeshStepDispatched = false;
                _navMeshPartialLeg = false;
                if(_isPathJumpActive) SetAirborne(false);
                _isPathJumpActive = false;
                ResetLayerPerStep(interruptDoorPass);
                _jumpProgress = 0f;
                _climbFacingDir = Vector3.zero;
            }
            protected void AdvanceStep()
            {
                ResetPerStepState(false);
                if(_path != null && _path.TryNextNode(out _))
                {
                    _stallStart = UnityEngine.Time.time;
                    _stallLastPos = _customNpc != null ? _customNpc.ServerPosition : Vector3.zero;
                }
            }
            private bool CheckFinishArrived(Vector3 botPos)
            {
                if(_path == null || _path.FinishNode == null) return false;
                Vector3 target = _path.FinishNode.Position;
                float dist3d = Vector3.Distance(botPos, target);
                if(_swimRescueActive || _islandWalkActive) return dist3d <= ArrivalDistanceDirect;
                if(dist3d > _finishArrival) return FinishTakenByNeighbour(botPos, target);
                return !_finishRequireLos || HasLineOfSightToFinish(botPos, target);
            }
            private bool HasLineOfSightToFinish(Vector3 botPos, Vector3 target)
            {
                Vector3 origin = botPos + Vector3.up * EyeHeight;
                Vector3 to = target + Vector3.up * 0.5f;
                return !Physics.Linecast(origin, to, out _, Path._physObstacleMask, QueryTriggerInteraction.Ignore);
            }
            private bool IsSwimming(Vector3 botPos, out float surfaceY, out bool canSubmerge)
            {
                surfaceY = 0f;
                canSubmerge = false;
                if(_customNpc == null) return false;
                var info = WaterLevel.GetWaterInfo(botPos, waves: false, volumes: true, _customNpc);
                if(!info.isValid || info.overallDepth <= WadeDepth) return false;
                surfaceY = info.surfaceLevel;
                canSubmerge = !CanSwimFloat();
                return true;
            }
            private bool IsWarpDepthWithin(Vector3 pos, float maxDepth)
            {
                if(_customNpc == null) return false;
                var info = WaterLevel.GetWaterInfo(pos, waves: false, volumes: true, _customNpc);
                if(!info.isValid) return true;
                return info.surfaceLevel - pos.y <= maxDepth;
            }
            private bool CanSwimFloat()
            {
                if(_customNpc == null || _customNpc.inventory == null) return true;
                var wear = _customNpc.inventory.containerWear;
                if(wear == null) return true;
                foreach(var item in wear.itemList)
                {
                    if(item == null || item.info == null) continue;
                    if((item.info.shortname == "diving.tank" || item.info.shortname == "diving.tank.double") && item.condition > 0f)
                        return false;
                }
                return true;
            }
            private bool TryEnsureTransition(PathNode prev, PathNode current)
            {
                if(prev == null || current == null) return false;
                if(prev.IsTransition || current.IsTransition) return false;
                if(_customNpc == null) return false;

                Vector3 botPos = _customNpc.ServerPosition;
                if((botPos - current.Position).sqrMagnitude < 4f) return false;

                NavMeshHit hb = default;
                bool botOnMesh = _rustAgent != null && _rustAgent.SamplePositionTyped(botPos, out hb, 1f);
                if(!botOnMesh && _rustAgent != null && _rustAgent.SamplePositionTyped(botPos, out hb, 3f)) botOnMesh = true;
                Vector3 startSnap = botOnMesh ? hb.position : botPos;

                if(!botOnMesh)
                {
                    if(TryGraphFallback(botPos, current)) return true;
                    return false;
                }

                bool ok = _rustAgent != null && _rustAgent.CalculatePathTyped(startSnap, current.Position, _navProbe);

                if(ok && _navProbe.status == NavMeshPathStatus.PathComplete) return false;

                if(ok && _navProbe.status == NavMeshPathStatus.PathPartial)
                {
                    var corners = _navProbe.corners;
                    if(corners != null && corners.Count >= 2)
                    {
                        Vector3 last = _rustAgent.NavToWorldSpace(corners[corners.Count - 1]);
                        if((last - botPos).sqrMagnitude > 0.25f && (last - current.Position).sqrMagnitude > 0.25f)
                        {
                            var t = PathNode.GetPool(last, NodeHint.NavMesh);
                            t.IsTransition = true;
                            _path.Insert(_path.CurrentIndex, t);
                            int pIdx = _path.CurrentIndex - 1;
                            if(pIdx >= 0 && _path[pIdx] != null) _path[pIdx].Hint |= NodeHint.NavMesh;
                            HaltMovement();
                            return true;
                        }
                    }
                }

                if(TryGraphFallback(botPos, current)) return true;

                return false;
            }

            private bool CheckIdleWatchdog(Vector3 botPos)
            {
                if(_type != NavigationType.Moving || _path.IsFindingPath || IsPaused)
                { _watchdogPos = botPos; _watchdogTime = UnityEngine.Time.time; return false; }
                if((botPos - _watchdogPos).sqrMagnitude >= WatchdogStuckDist * WatchdogStuckDist)
                { _watchdogPos = botPos; _watchdogTime = UnityEngine.Time.time; return false; }
                float window = WatchdogWindow;
                if(UnityEngine.Time.time - _watchdogTime < window) return false;
                if(CheckFinishArrived(botPos)) { FinishNavigation(); return true; }
                _lastStuckReason = StuckReason.Stall;
                _watchdogPos = botPos; _watchdogTime = UnityEngine.Time.time;
                OnStuck();
                return true;
            }
            private void TrackWatchdogBlindWindow()
            {
                float now = UnityEngine.Time.time;
                _lastThinkTime = now;
                if(_seenType != _type) { _seenType = _type; _seenTypeSince = now; }

                WatchdogBlindReason reason = WatchdogBlindReason.None;
                if(_type == NavigationType.Moving || _type == NavigationType.FindingPath)
                {
                    if(_pause) reason = WatchdogBlindReason.Paused;
                    else if(_path.IsFindingPath) reason = WatchdogBlindReason.PathFinding;
                }
                if(reason != _blindReason)
                {
                    _blindReason = reason;
                    _blindSince = now;
                    _blindWarned = false;
                }
                if(reason == WatchdogBlindReason.None || _blindWarned || now - _blindSince < WatchdogBlindWarnAfter) return;
                _blindWarned = true;
                Debug.LogWarning("[MyNav] {0}: idle watchdog blind for {1:F0}s ({2}), type={3} pos={4} fsm={5} stuck={6} agentStopped={7} | {8}",
                    Debug.Id(_customNpc), now - _blindSince, DescribeBlindReason(reason), _type, _customNpc.ServerPosition,
                    CurrentStateName(), _lastStuckReason, _rustAgent != null ? _rustAgent.isStopped.ToString() : "-",
                    reason == WatchdogBlindReason.Paused ? DescribePauseState(now) : DescribePathState());
            }
            private static string DescribeBlindReason(WatchdogBlindReason reason)
                => reason == WatchdogBlindReason.Paused ? "paused" : reason == WatchdogBlindReason.PathFinding ? "path-finding" : "none";
            private string CurrentStateName() => _customNpc?.brain?.StateMachine?.GetCurrentState()?.Name ?? "-";
            private string DescribePauseState(float now)
            {
                if(!_pause) return "pause: off";
                return string.Format("pause: on {0:F1}s, last set {1:F1}s ago, duration {2}, resume pending={3}",
                    now - _pauseStart, now - _pauseSetAt,
                    _pauseDuration > 0f ? _pauseDuration.ToString("F1") + "s" : "0 (until Resume)", IsInvoking(Resume));
            }
            private string DescribePathState()
            {
                PathNode finish = _path.Count > 0 ? _path[_path.Count - 1] : null;
                return string.Format("path: finding={0} hasPath={1} count={2} idx={3} finish={4} task={5}",
                    _path.IsFindingPath, _path.HasPath, _path.Count, _path.CurrentIndex,
                    finish != null ? finish.Position.ToString() : "-", _path.DescribeFindTask());
            }
            private static string DescribePathNode(PathNode node)
            {
                if(node == null) return "-";
                return node.Position + " " + node.Hint + (node.IsGraph ? " graph" : "") + (node.IsLayer ? " layer" : "")
                       + (node.IsTransition ? " transition" : "") + (node.IsStuckPoint ? " stuck-point" : "");
            }
            public string DescribeNavState()
            {
                if(_customNpc == null || _path == null) return "navigator is not initialized";
                float now = UnityEngine.Time.time;
                Vector3 botPos = _customNpc.ServerPosition;
                int idx = _path.CurrentIndex;
                PathNode current = idx >= 0 && idx < _path.Count ? _path[idx] : null;
                PathNode prev = idx >= 1 && idx - 1 < _path.Count ? _path[idx - 1] : null;
                string typeAge = _seenType == _type ? (now - _seenTypeSince).ToString("F1") + "s" : "not seen by Think";
                string blind = _blindReason == WatchdogBlindReason.None ? "none"
                    : string.Format("{0} {1:F0}s{2}", DescribeBlindReason(_blindReason), now - _blindSince, _blindWarned ? " (warned)" : "");
                return string.Format("{0} fsm={1} type={2} ({3}) moving={4} think {5:F1}s ago walkBuildings={6} pos={7}\n"
                                     + "  {8} | {9}\n"
                                     + "  cur={10} prev={11} | stuck={12} doorPhase={13} ladder={14} agentStopped={15} agentHasPath={16}"
                                     + " | step v={17:F2}m/s, watchdog {18:F1}s of {19:F1}s window, moved {20:F2}m of {21}m | blind: {22}",
                    Debug.Id(_customNpc), CurrentStateName(), _type, typeAge, Moving, now - _lastThinkTime, WalkBuildings, botPos,
                    DescribePauseState(now), DescribePathState(),
                    DescribePathNode(current), DescribePathNode(prev), _lastStuckReason, _doorPhase, IsOnLadderSegment(),
                    _rustAgent != null ? _rustAgent.isStopped.ToString() : "-", _rustAgent != null ? _rustAgent.hasPath.ToString() : "-",
                    _lastStepSpeed, now - _watchdogTime, WatchdogWindow, (botPos - _watchdogPos).magnitude, WatchdogStuckDist, blind);
            }
            protected void OnStuck()
            {
                if(UnityEngine.Time.time - _lastOnStuckTime < OnStuckThrottle) return;
                _lastOnStuckTime = UnityEngine.Time.time;
                BlackBox.NoteStuck(_customNpc, _lastStuckReason, false);
                if(_path?.FinishNode == null) { TryEscalateStuck(); return; }
                CloseLayerPlan(LayerPlanOutcome.Stuck);

                if(TryRecoverStuck())
                {
                    _lastStuckReason = StuckReason.None;
                    return;
                }

                if(TrySwimToFinish()) return;

                TryEscalateStuck();
            }
            private static float TerrainHeightAt(Vector3 pos)
                => TerrainMeta.HeightMap != null ? TerrainMeta.HeightMap.GetHeight(pos) : 0f;
            private void SetAirborne(bool airborne)
            {
                if(_customNpc == null) return;
                if(_customNpc.modelState != null) _customNpc.modelState.onground = !airborne;
                _customNpc.SendModelState(true);
            }
            private static Vector3 EvaluateJumpArc(Vector3 start, Vector3 finish, float height, float t)
            {
                Vector3 p = Vector3.Lerp(start, finish, t);
                p.y += height * Mathf.Sin(t * Mathf.PI);
                return p;
            }
            protected bool IsOnLadderSegment()
            {
                if(_isOnLadderActive) return true;
                if(_path == null) return false;
                int prevIdx = _path.CurrentIndex - 1;
                PathNode prev = (prevIdx >= 0 && prevIdx < _path.Count) ? _path[prevIdx] : null;
                if(prev != null && prev.Hint.HasFlag(NodeHint.Climb)) return true;
                var cur = _path.CurrentNode;
                return cur != null && cur.Hint.HasFlag(NodeHint.Climb);
            }
            public void Pause(float duration = 0)
            {
                if(duration < 0) return;
                if(!_pause) { _pause = true; _pauseStart = UnityEngine.Time.time; }
                _pauseSetAt = UnityEngine.Time.time;
                _pauseDuration = duration;
                if(IsInvoking(Resume)) CancelInvoke(Resume);
                if(duration > 0) Invoke(Resume, duration);
            }
            public void Resume()
            {
                if(IsInvoking(Resume)) CancelInvoke(Resume);
                if(!_pause) return;
                float paused = Mathf.Max(0f, UnityEngine.Time.time - _pauseStart);
                _stallStart += paused;
                _doorPhaseEnterTime += paused;
                _stuckCooldownUntil += paused;
                _offMeshWarpUntil += paused;
                _watchdogTime += paused;
                _pause = false;
            }
