            #region Маршрут по зонам графа: построение, обходы, двери

            protected void BuildRoute(Vector3 start, Vector3 finish)
            {
                var startZone = FindStartZone(start);
                if(TryBuildLayeredRoute(start, finish, 1, out _, NavLayerInsert.NewRoute))
                {
                }
                else if(startZone != null && startZone.Contains(finish))
                {
                    TryBuildSameZone(startZone, start, finish);
                }
                else if(startZone != null)
                {
                    TryBuildExitFromZone(startZone, start, finish);
                }
                else
                {
                    TryBuildOutOfZone(start, finish);
                }
            }

            protected bool TryGraphFallback(Vector3 botPos, PathNode current)
            {
                if(current == null) return false;
                if(TryBuildLayeredRoute(botPos, current.Position, _path?.CurrentIndex ?? 0, out _)) return true;
                var zone = FindStartZone(botPos);
                if(zone != null && zone.Contains(current.Position)
                   && TryInsertGraphChainBefore(zone, botPos, current.Position)) return true;
                return false;
            }

            protected bool TryGraphSwitchOnPartial(PathNode currentNode, Vector3 startPos, float progress)
            {
                if(progress < PartialMinProgress && currentNode != null && !currentNode.IsLayer
                   && TryInsertLayeredRouteAhead(startPos)) return true;

                var zone = FindStartZone(startPos);
                if(zone != null && _path.FinishNode != null && zone.Contains(_path.FinishNode.Position))
                {
                    if(TryInsertGraphChainBefore(zone, startPos, _path.FinishNode.Position)) return true;
                }
                return false;
            }

            private bool TryRecoverStuckByGraph()
            {
                if(_path?.FinishNode == null) return false;
                Vector3 botPos = _customNpc != null ? _customNpc.ServerPosition : Vector3.zero;
                Vector3 finish = _path.FinishNode.Position;

                if(_lastStuckReason == StuckReason.PathPartialUnreachable) return false;

                if(!(_path.CurrentNode?.LayerLeg ?? false) && TryInsertLayeredRouteAhead(botPos))
                {
                    _lastStuckReason = StuckReason.None;
                    return true;
                }

                var zone = FindStartZone(botPos);
                if(zone == null || !zone.Contains(finish))
                {
                    return false;
                }
                if(!TryInsertGraphChainBefore(zone, botPos, finish))
                {
                    return false;
                }
                return true;
            }

            protected bool TickHazardReaction()
            {
                if(_customNpc == null || _type != NavigationType.Moving || _path == null || _path.FinishNode == null) return false;
                if(UnityEngine.Time.time < _hazardReactUntil) return false;
                if(UnityEngine.Time.time < _nextHazardProbe) return false;
                _nextHazardProbe = UnityEngine.Time.time + HazardProbeInterval;

                Vector3 botPos = _customNpc.ServerPosition;
                if(!IsInsideHurtTrigger(botPos, out Vector3 hazardCenter, out float hazardRadius,
                                        out string hazardName, out string hazardKind, out bool hazardMobile, out float crossingDamage)) return false;

                Vector3 finish = _path.FinishNode.Position;
                NavGuardPolicy policy = Guard.Policy;
                Vector3 exitPoint = botPos;
                bool haveExit = policy.WarpHazardPush
                                && TryFindHazardExit(botPos, hazardCenter, Guard.ClampRadius(HazardPushMaxDist), out exitPoint);
                var zone = FindStartZone(botPos);

                if(hazardKind == "BeeTriggerHurt")
                {
                    if(TryFleeFromSwarm(botPos, hazardCenter)) return true;
                    _hazardReactUntil = UnityEngine.Time.time + HazardNoExitCooldown;
                    return false;
                }

                if(!hazardMobile) RememberHazard(hazardCenter, hazardRadius);

                if(!haveExit)
                {
                    _hazardReactUntil = UnityEngine.Time.time + HazardNoExitCooldown;
                    return false;
                }

                if(zone != null)
                {
                    Warp(exitPoint);
                    _hazardReactUntil = UnityEngine.Time.time + HazardReactCooldown;
                    if(BuildHazardGraphDetour(zone, _customNpc.ServerPosition, finish)) return true;
                    HaltMovement();
                    _type = NavigationType.Stuck;
                    _lastStuckReason = StuckReason.Other;
                    (_customNpc.brain?.StateMachine?.GetCurrentState() as FSM.IRouterState)?.OnStuck();
                    return true;
                }

                var router = _customNpc.brain?.StateMachine?.GetCurrentState() as FSM.IRouterState;
                bool survives = crossingDamage < _customNpc.health * HazardCrossHealthShare;
                bool canPass = (router == null || router.CanPassHazardTrigger(hazardCenter)) && survives;
                if(canPass)
                {
                    return false;
                }
                _hazardReactUntil = UnityEngine.Time.time + HazardReactCooldown;
                Warp(exitPoint);
                HaltMovement();
                _type = NavigationType.Stuck;
                _lastStuckReason = StuckReason.Other;
                router?.OnStuck();
                return true;
            }

            private bool TryFleeFromSwarm(Vector3 botPos, Vector3 swarmPos)
            {
                if(_rustAgent == null || _customNpc == null) return false;
                Vector3 away = botPos - swarmPos; away.y = 0f;
                if(away.sqrMagnitude < 0.01f) away = _customNpc.transform.forward;
                away.Normalize();

                Vector3 best = Vector3.zero;
                bool haveBest = false, bestWet = false;
                for(int i = 0; i < SwarmFleeDirections && !bestWet; i++)
                {
                    float step = ((i + 1) / 2) * (360f / SwarmFleeDirections);
                    float ang = (i % 2 == 0 ? step : -step) * Mathf.Deg2Rad;
                    Vector3 dir = new Vector3(
                        away.x * Mathf.Cos(ang) - away.z * Mathf.Sin(ang), 0f,
                        away.x * Mathf.Sin(ang) + away.z * Mathf.Cos(ang));
                    Vector3 probe = botPos + dir * SwarmFleeDistance;
                    if(!_rustAgent.SamplePositionTyped(probe, out var hit, SwarmFleeSampleRadius)) continue;
                    if((hit.position - swarmPos).sqrMagnitude < SwarmBreakRange * SwarmBreakRange) continue;
                    if(!_rustAgent.CalculatePathTyped(botPos, hit.position, _navProbe)
                       || _navProbe.status != NavMeshPathStatus.PathComplete) continue;
                    var wi = WaterLevel.GetWaterInfo(hit.position, waves: false, volumes: true, _customNpc);
                    bool wet = wi.isValid && wi.surfaceLevel - hit.position.y > SwarmWaterDepth;
                    if(!haveBest || (wet && !bestWet))
                    {
                        best = hit.position; haveBest = true; bestWet = wet;
                    }
                }
                if(!haveBest) return false;

                _hazardReactUntil = UnityEngine.Time.time + SwarmFleeCooldown;
                StartMoved(best, 1f);
                return true;
            }
            private const float SwarmBreakRange = 18f;
            private const float SwarmFleeDistance = 24f;
            private const float SwarmFleeSampleRadius = 6f;
            private const int SwarmFleeDirections = 8;
            private const float SwarmWaterDepth = 1.2f;
            private const float SwarmFleeCooldown = 6f;

            private const float HazardNoExitCooldown = 0.5f;

            protected void ClearLayerState()
            {
                _hasLastGraphInsert = false;
                _graphInsertCount = 0;
                _savedNavInsertCount = 0;
                _routeDetourCount = 0;
                _hasFailedDetour = false;
                _failedDetourStall = default;
                _failedDetourTarget = default;
            }
            protected void ResetGraphLatches()
            {
                _hasUnreachableTarget = false;
                _hasLastGraphInsert = false;
                _graphInsertCount = 0;
                _savedNavInsertCount = 0;
            }

            protected void OnSetDestination(Vector3 target)
            {
                if(_hasUnreachableTarget && (target - _unreachableTarget).sqrMagnitude >= UnreachableTargetTolSqr)
                    _hasUnreachableTarget = false;
            }

            protected void ResetLayerPerStep(bool interruptDoorPass = true)
            {
                if(interruptDoorPass) InterruptDoorPass("path reset");
                _doorPhase = 0;
            }

            private void InterruptDoorPass(string reason)
            {
                if(_openedDoorPass == null) return;
                _openedDoorPass.Reason = reason;
                if(_interruptedDoorPasses == null) _interruptedDoorPasses = new List<DoorPass>();
                _interruptedDoorPasses.Add(_openedDoorPass);
                _openedDoorPass = null;
            }

            private DoorPass ResumeDoorPass(Door door)
            {
                if(_openedDoorPass != null && _openedDoorPass.Door == door) return _openedDoorPass;
                InterruptDoorPass("another door passage");
                if(_interruptedDoorPasses == null) return null;
                for(int i = _interruptedDoorPasses.Count - 1; i >= 0; i--)
                {
                    DoorPass pass = _interruptedDoorPasses[i];
                    if(pass.Door != door) continue;
                    _interruptedDoorPasses.RemoveAt(i);
                    _openedDoorPass = pass;
                    return pass;
                }
                return null;
            }

            private void ForgetDoorPass(Door door)
            {
                if(_openedDoorPass != null && _openedDoorPass.Door == door) _openedDoorPass = null;
                if(_interruptedDoorPasses == null) return;
                for(int i = _interruptedDoorPasses.Count - 1; i >= 0; i--)
                    if(_interruptedDoorPasses[i].Door == door) _interruptedDoorPasses.RemoveAt(i);
            }

            private bool HasUpcomingDoorPass(Door door)
            {
                if((_type != NavigationType.Moving && _type != NavigationType.FindingPath) ||
                    _path == null || !_path.HasPath) return false;
                int start = Math.Max(0, _path.CurrentIndex - 1);
                int end = Math.Min(_path.Count - 1, start + 4);
                for(int i = start; i < end; i++)
                {
                    PathNode node = _path[i];
                    if(node != null && node.Door == door &&
                        (node.Hint.HasFlag(NodeHint.OpenDoor) || node.Hint.HasFlag(NodeHint.CloseDoor))) return true;
                }
                return false;
            }

            private bool IsClearOfDoorPass(DoorPass pass)
            {
                Vector3 offset = _customNpc.ServerPosition - pass.Center;
                if(offset.x * offset.x + offset.z * offset.z <= 2.25f) return false;
                Vector3 body = Quaternion.Inverse(pass.Rotation) * (offset + Vector3.up * 0.9f);
                return Mathf.Abs(body.x) > pass.Extents.x + 0.4f ||
                    Mathf.Abs(body.y) > pass.Extents.y + 0.9f || Mathf.Abs(body.z) > pass.Extents.z + 0.4f;
            }

            private bool IsDoorwayOccupied(Door door)
            {
                if(door == null || !door.IsValid()) return false;
                OBB bounds = door.WorldSpaceBounds();
                Quaternion toLocal = Quaternion.Inverse(bounds.rotation);
                List<BasePlayer> players = Pool.Get<List<BasePlayer>>();
                Vis.Entities(bounds.position, bounds.extents.magnitude + DoorwayBodyMargin, players, DoorwayBodyMask, QueryTriggerInteraction.Ignore);
                bool occupied = false;
                foreach(BasePlayer player in players)
                {
                    if(player == null || player == _customNpc || player.IsDestroyed || !player.IsAlive()) continue;
                    Vector3 body = toLocal * (player.transform.position + Vector3.up * 0.9f - bounds.position);
                    if(Mathf.Abs(body.x) > bounds.extents.x + DoorwayBodyMargin || Mathf.Abs(body.y) > bounds.extents.y + 0.9f
                       || Mathf.Abs(body.z) > bounds.extents.z + DoorwayBodyMargin) continue;
                    occupied = true;
                    break;
                }
                Pool.FreeUnmanaged(ref players);
                return occupied;
            }

            private const float DoorwayBodyMargin = 0.5f;
            private static readonly int DoorwayBodyMask = LayerMask.GetMask("Player (Server)");

            private bool CloseInterruptedDoorPass(DoorPass pass, string reason)
            {
                Door door = pass.Door;
                if(door == null || !door.IsValid() || !door.IsOpen()) return true;
                bool hatch = IsLadderHatch(door);
                if(Interface.CallHook("OnNpcClosingDoor", _customNpc, door) == null && door != null && door.IsValid())
                    door.SetOpen(false);
                if(door == null || !door.IsValid()) return true;
                if(hatch) BuildingNavigation.NoteBlockChange(door.buildingID);
                if(door.IsOpen()) return false;
                return true;
            }

            private void TickInterruptedDoorPasses()
            {
                if(_interruptedDoorPasses == null || _interruptedDoorPasses.Count == 0) return;
                for(int i = _interruptedDoorPasses.Count - 1; i >= 0; i--)
                {
                    if(i >= _interruptedDoorPasses.Count) continue;
                    DoorPass pass = _interruptedDoorPasses[i];
                    Door door = pass.Door;
                    if(door == null || !door.IsValid()) { _interruptedDoorPasses.RemoveAt(i); continue; }
                    if(!door.IsOpen())
                    {
                        if(pass.Opened || UnityEngine.Time.time >= pass.OpenUntil) _interruptedDoorPasses.RemoveAt(i);
                        continue;
                    }
                    pass.Opened = true;
                    if(UnityEngine.Time.time < pass.NextCloseAttempt) continue;
                    if((_path != null && _path.IsFindingPath) || HasUpcomingDoorPass(door) || !IsClearOfDoorPass(pass) || IsDoorwayOccupied(door)) continue;
                    _interruptedDoorPasses.RemoveAt(i);
                    pass.CloseAttempts++;
                    pass.NextCloseAttempt = UnityEngine.Time.time + 1f;
                    if(!CloseInterruptedDoorPass(pass, pass.Reason))
                    {
                        if(pass.CloseAttempts < 3) _interruptedDoorPasses.Add(pass);
                    }
                }
            }

            internal void CloseDoorPassesOnDestroy()
            {
                _doorPassesDestroyed = true;
                InterruptDoorPass("bot destroyed");
                if(_interruptedDoorPasses == null) return;
                while(_interruptedDoorPasses.Count > 0)
                {
                    int i = _interruptedDoorPasses.Count - 1;
                    DoorPass pass = _interruptedDoorPasses[i];
                    _interruptedDoorPasses.RemoveAt(i);
                    CloseInterruptedDoorPass(pass, "bot destroyed");
                }
            }

            private void OnDestroy()
            {
                CloseDoorPassesOnDestroy();
                ApartBots.Remove(_customNpc);
                _path?.Reset();
            }

            protected void TickDoor(PathNode currentNode, float delta)
            {
                if(_customNpc == null) return;
                int prevIdxDoor = _path.CurrentIndex - 1;
                PathNode prevNodeDoor = prevIdxDoor >= 0 ? _path[prevIdxDoor] : null;
                Door door = prevNodeDoor?.Door ?? currentNode.Door;
                if(door == null || !door.IsValid()) { AdvanceStep(); return; }

                switch(_doorPhase)
                {
                    case 0:
                        {
                            if(!door.IsOpen() && _customNpc.IsDoorBlocked(door.net.ID)) { OnStuck(); return; }
                            bool wasOpen = door.IsOpen();
                            DoorPass resumedPass = ResumeDoorPass(door);
                            _doorPassWasOpen = wasOpen && resumedPass == null;
                            _doorPassDoor = door;
                            if(wasOpen)
                            {
                                _doorPhase = 2;
                                break;
                            }
                            PressButton button = prevNodeDoor?.Entity as PressButton;
                            CardReader reader = button == null ? prevNodeDoor?.Entity as CardReader : null;
                            bool readerPowered = reader != null && reader.IsPowered();
                            if(reader != null && !readerPowered) reader = null;
                            BaseLock lockEntity = (button == null && reader == null) ? door.GetSlot(BaseEntity.Slot.Lock) as BaseLock : null;

                            if(_openedDoorPass == null)
                            {
                                OBB bounds = door.WorldSpaceBounds();
                                _openedDoorPass = new DoorPass
                                {
                                    Door = door, Center = bounds.position, Rotation = bounds.rotation, Extents = bounds.extents
                                };
                            }
                            DoorPass requestedPass = _openedDoorPass;
                            requestedPass.Opened = false;
                            requestedPass.OpenUntil = UnityEngine.Time.time + DoorOpenTimeout;
                            var fsmState = _customNpc.brain?.StateMachine?.GetCurrentState() as FSM.BaseStatePlayerNpc;
                            object hookResult = fsmState?.OpenDoor(door, lockEntity, reader);
                            if(hookResult == null)
                                hookResult = Interface.CallHook("OnNpcOpeningDoor", _customNpc, door, lockEntity, reader, button);
                            requestedPass.Opened = door != null && door.IsValid() && door.IsOpen();
                            if(_doorPassesDestroyed)
                            {
                                CloseInterruptedDoorPass(requestedPass, "bot destroyed");
                                return;
                            }
                            if(_openedDoorPass != requestedPass) return;
                            if(door == null || !door.IsValid()) { ForgetDoorPass(door); AdvanceStep(); return; }
                            if(hookResult == null)
                            {
                                if(!requestedPass.Opened) ForgetDoorPass(door);
                                _customNpc.MarkDoorBlocked(door.net.ID);
                                OnStuck();
                                return;
                            }

                            if(reader != null && reader.swipeEffect.isValid && reader.audioPosition != null)
                            {
                                Effect.server.Run(reader.swipeEffect.resourcePath, reader.audioPosition.position, Vector3.up);
                                _customNpc.Server_StartGesture(GestureCollection.Instance.GestureConvarNameToGesture("wave"), BasePlayer.GestureStartSource.ServerAction);
                            }

                            if(door.IsOpen() && door.GetComponentInChildren<TriggerLadder>(true) != null)
                            {
                                _doorPhase = 2;
                                Pause(DoorOpenedPause);
                                break;
                            }

                            _doorPhase = 1;
                            _doorPhaseEnterTime = UnityEngine.Time.time;
                            break;
                        }
                    case 1:
                        {
                            if(door.IsOpen())
                            {
                                if(_openedDoorPass != null && _openedDoorPass.Door == door) _openedDoorPass.Opened = true;
                                _doorPhase = 2;
                                Pause(DoorOpenedPause);
                            }
                            else if(UnityEngine.Time.time - _doorPhaseEnterTime > DoorOpenTimeout)
                            {
                                OnStuck();
                                return;
                            }
                            break;
                        }
                    case 2:
                        {
                            if(!door.IsOpen())
                            {
                                _doorPhase = 1;
                                _doorPhaseEnterTime = UnityEngine.Time.time;
                                break;
                            }
                            if(StepDoorSegment(prevNodeDoor, currentNode, delta))
                            {
                                AdvanceStep();
                            }
                            break;
                        }
                }
            }

            protected void TickCloseDoor(PathNode prevNode, PathNode currentNode, float delta)
            {
                if(_customNpc == null) return;
                Door door = prevNode?.Door ?? currentNode.Door;
                if(StepDoorSegment(prevNode, currentNode, delta))
                {
                    _isOnLadderActive = false;
                    _customNpc.ServerPosition = currentNode.Position;
                    if(door != null) ResumeDoorPass(door);
                    bool hatch = door != null && door.IsValid() && IsLadderHatch(door);
                    bool leaveOpen = hatch && door == _doorPassDoor && _doorPassWasOpen && _openedDoorPass == null;
                    if(leaveOpen)
                    {
                        ForgetDoorPass(door);
                        AdvanceStep();
                        return;
                    }
                    if(door != null && door.IsValid() && door.IsOpen() && IsDoorwayOccupied(door))
                    {
                        InterruptDoorPass("doorway occupied");
                        AdvanceStep();
                        return;
                    }
                    if(door != null && door.IsValid())
                    {
                        if(Interface.CallHook("OnNpcClosingDoor", _customNpc, door) == null)
                            door.SetOpen(false);
                        if (hatch)
                            BuildingNavigation.NoteBlockChange(door.buildingID);
                    }
                    if(door == null || !door.IsValid() || !door.IsOpen()) ForgetDoorPass(door);
                    else InterruptDoorPass("close deferred");
                    Pause(CloseDoorPause);
                    AdvanceStep();
                }
            }

            private static bool IsLadderHatch(Door door) => door.GetComponentInChildren<TriggerLadder>(true) != null;

            private const float DoorStepRise = 0.3f;

            private bool StepDoorSegment(PathNode prevNode, PathNode currentNode, float delta)
            {
                bool climb = prevNode != null && prevNode.Hint.HasFlag(NodeHint.Climb);
                _isOnLadderActive = climb;
                Vector3 current = _customNpc.ServerPosition;
                bool vertical = climb || Mathf.Abs(currentNode.Position.y - current.y) > DoorStepRise;
                float moveStep = CalculateSpeed(false, false, climb) * delta;
                _customNpc.ServerPosition = Vector3.MoveTowards(current, currentNode.Position, moveStep);
                float dist = vertical ? Vector3.Distance(_customNpc.ServerPosition, currentNode.Position)
                                      : Vector3Ex.Distance2D(_customNpc.ServerPosition, currentNode.Position);
                if(dist > ArrivalDistanceDirect) return false;
                return true;
            }

            #endregion

            #region Методы работы с зонами графа

            private bool CanNearestNode(Vector3 from, IAIPathNode node)
            {
                if(node.LinkedDoor != null || node.IsWaypointOnly) return false;
                Vector3 delta = node.Position - from;
                float dist = delta.magnitude;
                if(dist > 0.01f)
                {
                    float h = PlayerCapsuleHeight / 2f;
                    Vector3 dir = delta / dist;
                    Vector3 bottom = from + Vector3.up * (h + 0.3f);
                    Vector3 top = from + Vector3.up * (h - PlayerCapsuleRadius + 0.3f);
                    if(Physics.CapsuleCast(bottom, top, PlayerCapsuleRadius, dir, dist, GraphNodeLosMask, QueryTriggerInteraction.Ignore))
                        return false;
                }
                return true;
            }
            private HelperNavGraph.NavGraphNode FindZoneNode(HelperNavGraph.NavGraph graph, Vector3 from, float radius, out bool viaNavmesh)
            {
                var node = FindZoneNodeInner(graph, from, radius, FloorInsertYTol, out viaNavmesh);
                if(node != null) return node;
                return FindZoneNodeInner(graph, from, radius, float.PositiveInfinity, out viaNavmesh);
            }
            private HelperNavGraph.NavGraphNode FindZoneNodeInner(HelperNavGraph.NavGraph graph, Vector3 from, float radius, float yTol, out bool viaNavmesh)
            {
                viaNavmesh = false;
                if(graph == null) return null;
                float fromY = from.y;
                if(_rustAgent != null && _rustAgent.SamplePositionTyped(from, out var hb, NavMeshSnapRadius))
                {
                    Vector3 snap = hb.position;
                    if(graph.TryGetNearestNode(from, radius, out var nmNode,
                           (f, n) => n.LinkedDoor == null && !n.IsWaypointOnly
                                     && Mathf.Abs(n.Position.y - fromY) <= yTol
                                     && _rustAgent.CalculatePathTyped(snap, n.Position, _navProbe)
                                     && _navProbe.status == NavMeshPathStatus.PathComplete))
                    {
                        viaNavmesh = true;
                        return nmNode;
                    }
                }
                if(graph.TryGetNearestNode(from, radius, out var losNode,
                       (f, n) => Mathf.Abs(n.Position.y - fromY) <= yTol && CanNearestNode(f, n)))
                    return losNode;
                return null;
            }
            protected HelperNavGraph.NavGraphZone FindStartZone(Vector3 pos)
            {
                HelperNavGraph.NavGraphZone best = null;
                float bestVolume = float.MaxValue;
                foreach(var zone in _enterZones)
                {
                    if(zone == null || zone.Graph == null) continue;
                    if(!zone.Contains(pos)) continue;
                    var bc = zone.Box;
                    float volume = bc != null ? bc.size.x * bc.size.y * bc.size.z : float.MaxValue;
                    if(volume < bestVolume)
                    {
                        bestVolume = volume;
                        best = zone;
                    }
                }
                return best;
            }
            private void TryBuildSameZone(HelperNavGraph.NavGraphZone zone, Vector3 start, Vector3 finish)
            {
                if(_rustAgent != null && _rustAgent.CalculatePathTyped(start, finish, _navProbe) && _navProbe.status == NavMeshPathStatus.PathComplete)
                {
                    var corners = _navProbe.corners;
                    if(corners != null && corners.Count > 0)
                    {
                        Vector3 last = _rustAgent.NavToWorldSpace(corners[corners.Count - 1]);
                        if((last - finish).sqrMagnitude < 0.5f * 0.5f) return;
                    }
                }
                if(_hasUnreachableTarget && (finish - _unreachableTarget).sqrMagnitude < UnreachableTargetTolSqr) return;

                zone.Graph.EnsureBridgesSync();
                var nodeStart = FindZoneNode(zone.Graph, start, 20f, out bool startViaNavmesh);
                var nodeFinish = FindZoneNode(zone.Graph, finish, 20f, out bool finishViaNavmesh);
                if(nodeStart == null || nodeFinish == null) return;
                _path.InsertPath(1, nodeStart, nodeFinish, startViaNavmesh, finishViaNavmesh);
            }

            private void TryBuildExitFromZone(HelperNavGraph.NavGraphZone zone, Vector3 start, Vector3 finish)
            {
                Vector3 navFinish = finish;
                bool finishOffMesh = false;
                if(_rustAgent != null && _rustAgent.SamplePositionTyped(finish, out var fh, ExitFinishSnapRadius))
                {
                    navFinish = fh.position;
                    finishOffMesh = (navFinish - finish).sqrMagnitude > FinishSnapRadius * FinishSnapRadius;
                }

                bool calcOk = _rustAgent != null && _rustAgent.CalculatePathTyped(start, navFinish, _navProbe);
                var calcStatus = calcOk ? _navProbe.status : NavMeshPathStatus.PathInvalid;
                if(calcOk && calcStatus == NavMeshPathStatus.PathComplete && !finishOffMesh)
                {
                    return;
                }
                if(_hasUnreachableTarget && (finish - _unreachableTarget).sqrMagnitude < UnreachableTargetTolSqr)
                {
                    return;
                }

                zone.Graph.EnsureBridgesSync();
                var bridge = ChooseExitBridge(zone, navFinish);
                var nodeStart = FindZoneNode(zone.Graph, start, 20f, out bool startViaNavmesh);
                if(bridge == null) return;
                if(nodeStart == null) return;
                if(finishOffMesh)
                    _path.Insert(_path.Count - 1, PathNode.GetPool(navFinish, NodeHint.NavMesh));
                _path.InsertPath(1, nodeStart, bridge, startViaNavmesh, false);
            }
            private IAIPathNode ChooseExitBridge(HelperNavGraph.NavGraphZone zone, Vector3 finish)
            {
                var bridges = zone.Graph.BridgeNodes;
                if(bridges == null || bridges.Count == 0) return null;

                _buffBridges.Clear();
                for(int i = 0; i < bridges.Count; i++)
                {
                    var n = bridges[i];
                    if(n == null) continue;
                    if(!zone.Contains(n.Position)) continue;
                    _buffBridges.Add(n);
                }
                if(_buffBridges.Count == 0) return null;

                _buffBridges.Sort((a, b) =>
                {
                    float da = (a.Position - finish).sqrMagnitude;
                    float db = (b.Position - finish).sqrMagnitude;
                    return da.CompareTo(db);
                });

                int probeCount = Mathf.Min(_buffBridges.Count, BridgeProbeLimit);
                for(int i = 0; i < probeCount; i++)
                {
                    var b = _buffBridges[i];
                    if(_rustAgent == null || !_rustAgent.CalculatePathTyped(b.Position, finish, _navProbe)) continue;
                    if(_navProbe.status == NavMeshPathStatus.PathComplete) return b;
                }
                for(int i = 0; i < probeCount; i++)
                {
                    var b = _buffBridges[i];
                    if(_rustAgent == null || !_rustAgent.CalculatePathTyped(b.Position, finish, _navProbe)) continue;
                    if(_navProbe.status != NavMeshPathStatus.PathPartial) continue;
                    var corners = _navProbe.corners;
                    if(corners == null || corners.Count == 0) continue;
                    Vector3 last = _rustAgent.NavToWorldSpace(corners[corners.Count - 1]);
                    if(!zone.Contains(last)) return b;
                }
                return _buffBridges[0];
            }
            private bool TryInsertGraphChainBefore(HelperNavGraph.NavGraphZone zone, Vector3 from, Vector3 to)
            {
                if(_hasUnreachableTarget && (to - _unreachableTarget).sqrMagnitude < UnreachableTargetTolSqr)
                {
                    return false;
                }
                if(_graphInsertCount >= MaxGraphInsertsPerRoute)
                {
                    _hasUnreachableTarget = true;
                    _unreachableTarget = to;
                    return false;
                }
                zone.Graph.EnsureBridgesSync();
                var nodeStart = FindZoneNode(zone.Graph, from, 20f, out bool startViaNavmesh);
                var nodeFinish = FindZoneNode(zone.Graph, to, 20f, out bool finishViaNavmesh);
                if(nodeStart == null || nodeFinish == null)
                {
                    return false;
                }
                if(nodeStart == nodeFinish || (nodeStart.Position - nodeFinish.Position).sqrMagnitude < 0.01f)
                {
                    return false;
                }
                if(_hasLastGraphInsert
                   && (nodeStart.Position - _lastGraphInsertFrom).sqrMagnitude < 0.01f
                   && (nodeFinish.Position - _lastGraphInsertTo).sqrMagnitude < 0.01f)
                {
                    _hasUnreachableTarget = true;
                    _unreachableTarget = to;
                    return false;
                }
                _hasLastGraphInsert = true;
                _lastGraphInsertFrom = nodeStart.Position;
                _lastGraphInsertTo = nodeFinish.Position;
                _graphInsertCount++;
                int insertAt = _path.CurrentIndex;
                int backIdx = Mathf.Max(0, insertAt - 1);
                _path.CurrentIndex = backIdx;
                _path.InsertPath(insertAt, nodeStart, nodeFinish, startViaNavmesh, finishViaNavmesh);
                HaltMovement();
                _type = NavigationType.FindingPath;
                return true;
            }

            private bool IsInsideHurtTrigger(Vector3 botPos, out Vector3 hazardCenter, out float hazardRadius,
                                             out string hazardName, out string hazardKind, out bool hazardMobile, out float crossingDamage)
            {
                hazardCenter = botPos;
                hazardRadius = HazardProbeRadius;
                hazardName = "?";
                hazardKind = "?";
                hazardMobile = false;
                crossingDamage = 0f;
                for(int h = 0; h < _hazardProbeHeights.Length; h++)
                {
                    Vector3 c = botPos + Vector3.up * _hazardProbeHeights[h];
                    int n = Physics.OverlapSphereNonAlloc(c, HazardProbeRadius, _probeColliders, _hurtTriggerMask, QueryTriggerInteraction.Collide);
                    for(int i = 0; i < n; i++)
                    {
                        var col = _probeColliders[i];
                        if(col == null) continue;
                        if(!(col.GetComponentInParent<IHurtTrigger>() is Component hurt)) continue;
                        if(hurt is TriggerHurtNotChild notChild && NotChildDamagePerSecond(notChild) < HarmlessDamagePerSecond) continue;
                        Bounds b = col.bounds;
                        hazardCenter = b.center;
                        hazardRadius = Mathf.Clamp(Mathf.Max(b.extents.x, b.extents.z), HazardProbeRadius, HazardMaxRadius);
                        hazardName = col.name;
                        hazardKind = hurt.GetType().Name;
                        hazardMobile = col.attachedRigidbody != null || hurt.GetComponentInParent<BaseVehicle>() != null;
                        crossingDamage = CrossingDamage(hurt, col);
                        return true;
                    }
                }
                return false;
            }

            private float CrossingDamage(Component hurt, Collider collider)
            {
                float narrow;
                if(collider is BoxCollider box)
                {
                    Vector3 size = Vector3.Scale(box.size, box.transform.lossyScale);
                    narrow = Mathf.Min(Mathf.Abs(size.x), Mathf.Abs(size.z));
                }
                else narrow = 2f * Mathf.Min(collider.bounds.extents.x, collider.bounds.extents.z);
                float length = Mathf.Max(1f, narrow);
                float seconds = length / Mathf.Max(0.5f, CalculateSpeed(false, false, false));
                switch(hurt)
                {
                    case TriggerHurtEx ex:
                        if(!ex.damageEnabled) return 0f;
                        return DamageSum(ex.damageOnEnter) + DamageSum(ex.damageOnMove) * length + DamageSum(ex.damageOnTimer) * seconds + DamageSum(ex.damageOnLeave);
                    case TriggerHurtNotChild notChild:
                        return NotChildDamagePerSecond(notChild) * seconds;
                    case CrushTrigger crush:
                        if(!crush.includeNPCs && _customNpc.IsNpc) return 0f;
                        return crush.DamagePerSecond * seconds;
                    case TriggerHurt timed:
                        return timed.DamagePerSecond * seconds;
                }
                return 0f;
            }

            public static float NotChildDamagePerSecond(TriggerHurtNotChild trigger, BaseCustomNpc npc)
            {
                if(trigger.ignoreNPC && npc.IsNpc) return 0f;
                float source = trigger.UseSourceEntityDamageMultiplier && trigger.hurtTiggerUser != null ? trigger.hurtTiggerUser.GetDamageMultiplier(npc) : 1f;
                return trigger.DamagePerSecond * trigger.npcMultiplier * source;
            }

            private float NotChildDamagePerSecond(TriggerHurtNotChild trigger) => NotChildDamagePerSecond(trigger, _customNpc);

            public const float HarmlessDamagePerSecond = 0.5f;

            private static float DamageSum(List<DamageTypeEntry> damage)
            {
                float sum = 0f;
                if(damage != null) foreach(DamageTypeEntry entry in damage) sum += entry.amount;
                return sum;
            }
            private const float HazardMaxRadius = 6f;

            private bool TryFindHazardExit(Vector3 botPos, Vector3 hazardCenter, float maxDist, out Vector3 exit)
            {
                exit = botPos;
                if(_rustAgent == null || maxDist < HazardPushStep) return false;
                Vector3 primary = botPos - hazardCenter; primary.y = 0f;
                if(primary.sqrMagnitude < 0.01f && _path?.CurrentNode != null)
                {
                    primary = botPos - _path.CurrentNode.Position; primary.y = 0f;
                }
                float baseAng = primary.sqrMagnitude > 0.01f ? Mathf.Atan2(primary.z, primary.x) : 0f;

                bool found = false;
                float bestSqr = float.MaxValue;
                for(int d = 0; d < HazardExitDirections; d++)
                {
                    float ang = baseAng + Mathf.PI * 2f * d / HazardExitDirections;
                    Vector3 dir = new Vector3(Mathf.Cos(ang), 0f, Mathf.Sin(ang));
                    for(float dist = HazardPushStep; dist <= maxDist; dist += HazardPushStep)
                    {
                        Vector3 probe = botPos + dir * dist;
                        if(!_rustAgent.SamplePositionTyped(probe, out var hit, NavMeshSnapRadius)) continue;
                        if(IsInsideHurtTrigger(hit.position, out _, out _, out _, out _, out _, out _)) continue;
                        if(HelperDoorTraps.IsInside(hit.position)) continue;
                        if(IsInsideRememberedHazard(hit.position)) continue;
                        if(IsWallBetween(botPos, hit.position)) continue;
                        float sqr = (hit.position - botPos).sqrMagnitude;
                        if(sqr < bestSqr) { bestSqr = sqr; exit = hit.position; found = true; }
                        break;
                    }
                }
                return found;
            }

            private bool BuildHazardGraphDetour(HelperNavGraph.NavGraphZone zone, Vector3 start, Vector3 finish)
            {
                if(zone?.Graph == null || _customNpc == null) return false;
                ClearPathAndState();
                bool navStart = GetNearestNavMeshPosition(start, out var s, NavMeshSnapRadius);
                Vector3 startPos = navStart ? s : start;
                bool navFinish = GetNearestNavMeshPosition(finish, out var f, FinishSnapRadius);
                Vector3 finishPos = navFinish ? f : finish;
                _path.Add(PathNode.GetPool(startPos, navStart ? NodeHint.NavMesh : NodeHint.None));
                _path.Add(PathNode.GetPool(finishPos, navFinish ? NodeHint.NavMesh : NodeHint.None));
                _path.CurrentIndex = 0;

                zone.Graph.EnsureBridgesSync();
                var nodeStart = FindZoneNode(zone.Graph, startPos, 20f, out bool startViaNavmesh);
                if(nodeStart == null) return false;
                IAIPathNode nodeTo;
                bool toViaNavmesh = false;
                if(zone.Contains(finishPos))
                    nodeTo = FindZoneNode(zone.Graph, finishPos, 20f, out toViaNavmesh);
                else
                    nodeTo = ChooseExitBridge(zone, finishPos);
                if(nodeTo == null) return false;
                if(nodeStart == nodeTo || (nodeStart.Position - nodeTo.Position).sqrMagnitude < 0.01f) return false;
                _path.InsertPath(1, nodeStart, nodeTo, startViaNavmesh, toViaNavmesh);
                _type = _path.IsFindingPath ? NavigationType.FindingPath : NavigationType.Moving;
                return true;
            }

            protected virtual void OnEnterNavZone(HelperNavGraph.NavGraphZone zone)
            {
                if (zone == null) return;
                _enterZones.RemoveAll(z => z == null);
                if (_enterZones.Contains(zone)) return;
                _enterZones.Add(zone);
            }
            protected virtual void OnLeaveNavZone(HelperNavGraph.NavGraphZone zone)
            {
                if (zone == null) return;
                _enterZones.Remove(zone);
            }
            #endregion
            #region Поля пробы препятствий

            private static readonly int _obstacleProbeMask = LayerMask.GetMask("Deployed", "Construction");
            private static readonly int _obstacleZoneMask = LayerMask.GetMask("Deployed", "Construction", "Terrain", "World", "Default");
            private static readonly int _deployedLayer = LayerMask.NameToLayer("Deployed");
            private const float ObstacleProbeRadius = 0.25f;
            private const float ObstacleProbeForward = 0.35f;
            private static readonly float[] _obstacleZoneHeights = { 0.25f, 0.7f, 1.15f, 1.6f };
            private const float ObstacleJumpForward = 0.6f;
            private const float ObstacleJumpMaxUp = 1.4f;
            private const float CrouchPauseDuration = 0.5f;
            private const float StandPushStep = 0.3f;
            private static readonly int _groundPullMask = LayerMask.GetMask("Construction", "Deployed", "Terrain", "World", "Default");
            private const float GroundPullMin = 0.15f;
            private const float GroundDropHigh = 1f;
            private const float GroundPullMaxDist = 4f;
            private const float GroundPullSpeed = 6f;
            private const float HatchCloseRadius = 1.5f;
            private readonly ObstacleProbeResult _obstacleProbe = new ObstacleProbeResult();
            private readonly bool[] _probeBlocked = new bool[4];
            private readonly bool[] _probeKindScratch = new bool[4];
            private bool _obstacleJumpActive;
            private Vector3 _obstacleJumpStart, _obstacleJumpFinish;
            private float _obstacleJumpProgress;
            private ObstacleProbeKind _lastObstacleKind = ObstacleProbeKind.None;
            private BaseEntity _lastObstacleEntity;
            private Collider _lastObstacleCollider;
            private int _lastSimpleGraphVersion;

            public BaseEntity LastObstacleEntity => _lastObstacleEntity;
            #endregion

            #region Реакции на препятствия построек и графовые перепланирования

            private ObstacleProbeResult ProbeObstacleZones(Vector3 atPos)
            {
                for(int i = 0; i < 4; i++)
                {
                    Vector3 c = atPos + Vector3.up * _obstacleZoneHeights[i];
                    _probeBlocked[i] = ZoneBlocked(c);
                    _obstacleProbe.Centers[i] = c;
                }
                _obstacleProbe.Kind = ClassifyObstacle(_probeBlocked);
                return _obstacleProbe;
            }

            protected bool TickObstacleReaction(float delta)
            {
                if(_customNpc == null) return false;
                bool inBuildZone = BuildingNavigation.TryGetZoneContaining(_customNpc.ServerPosition, out _, out _, out bool isSimple) && isSimple;

                Vector3 probePos = _customNpc.ServerPosition;
                if(_type == NavigationType.Moving && _path != null && _path.CurrentNode != null)
                {
                    Vector3 fwd = _path.CurrentNode.Position - probePos; fwd.y = 0f;
                    if(fwd.sqrMagnitude > 0.01f) probePos += fwd.normalized * ObstacleProbeForward;
                }

                bool swimming = _customNpc.IsSwimming();
                bool onLadder = IsOnLadderSegment();
                bool stateWantsCrouch = (_customNpc.brain?.StateMachine?.GetCurrentState()?.WantsCrouch) ?? false;
                ObstacleProbeResult probe = default;
                bool probed = false;
                if(!swimming && !onLadder)
                {
                    probe = ProbeObstacleZones(probePos);
                    probed = true;
                    bool overhang = probe.Kind == ObstacleProbeKind.CrouchOver;
                    bool wantCrouch = overhang || stateWantsCrouch;
                    bool wasCrouched = _customNpc.Ducked;
                    _customNpc.Ducked = wantCrouch;
                    if(overhang && !wasCrouched && !_obstacleJumpActive && !_isPathJumpActive
                       && (inBuildZone || FindStartZone(_customNpc.ServerPosition) != null))
                        Pause(CrouchPauseDuration);
                }
                else if(_customNpc.Ducked) _customNpc.Ducked = false;

                if(!inBuildZone)
                {
                    LandObstacleJump();
                    return false;
                }
                if(_obstacleJumpActive) { TickObstacleJump(delta); return true; }
                if(_isPathJumpActive || onLadder) return false;

                if(!probed) { probe = ProbeObstacleZones(probePos); probed = true; }
                if(probe.Kind != _lastObstacleKind)
                {
                    _lastObstacleKind = probe.Kind;
                }
                if(IsOnSlopeBlock()) return false;
                switch(probe.Kind)
                {
                    case ObstacleProbeKind.StepLow:
                        if(!TryStepUp(_customNpc.ServerPosition) && _type != NavigationType.Moving && TryResolveStandingObstacle()) return true;
                        break;
                    case ObstacleProbeKind.JumpMid:
                        if(_type == NavigationType.Moving && TryStartObstacleJump()) return true;
                        if(!TryStepUp(_customNpc.ServerPosition) && _type != NavigationType.Moving && TryResolveStandingObstacle()) return true;
                        break;
                    case ObstacleProbeKind.Wall:
                        if(_type == NavigationType.Moving && _path != null && _path.HasPath)
                        {
                            var router = _customNpc.brain?.StateMachine?.GetCurrentState() as FSM.IRouterState;
                            if(router != null && _lastObstacleEntity != null && !router.IsObstacleBlocking(_lastObstacleEntity)) break;
                            _lastStuckReason = StuckReason.ObstacleBlocked;
                            HaltMovement();
                            _type = NavigationType.Stuck;
                            router?.OnStuck();
                        }
                        break;
                }
                if(IsOnDeployed() && !_probeBlocked[0] && TickGroundPull(delta)) return true;
                return false;
            }

            protected bool TryRecoverStuck()
            {
                if(TryCloseBlockingHatch())
                {
                    return true;
                }
                return TryRecoverStuckByGraph();
            }

            protected bool TryRebuildOnGraphVersion()
            {
                if(!BuildingNavigation.TryGetZoneContaining(_customNpc.ServerPosition, out _, out uint bid, out _)) return false;
                int sgv = BuildingNavigation.GetSimpleGraphVersion(bid);
                if(sgv == _lastSimpleGraphVersion) return false;

                bool firstSync = _lastSimpleGraphVersion == 0;
                _lastSimpleGraphVersion = sgv;
                if(firstSync || !_path.HasPath || _path.FinishNode == null) return false;

                ResetGraphLatches();
                if(HasExplicitLayerRoute)
                {
                    bool relaid = RelayExplicitLayerRoute(currentSpeedFraction);
                    return true;
                }
                StartMoved(_path.FinishNode.Position, currentSpeedFraction);
                return true;
            }

            #endregion

            #region Методы пробы и реакций

            private ObstacleProbeKind ProbeKindAt(Vector3 atPos)
            {
                for(int i = 0; i < 4; i++)
                    _probeKindScratch[i] = ZoneBlocked(atPos + Vector3.up * _obstacleZoneHeights[i]);
                return ClassifyObstacle(_probeKindScratch);
            }
            private static ObstacleProbeKind ClassifyObstacle(bool[] z)
            {
                bool s1 = z[0], s2 = z[1], s3 = z[2], s4 = z[3];
                if(s3 && s4 && (s1 || s2)) return ObstacleProbeKind.Wall;
                if((s3 || s4) && !s2) return ObstacleProbeKind.CrouchOver;
                if((s2 || s3) && !s4) return ObstacleProbeKind.JumpMid;
                if(s1 && !s2 && !s3) return ObstacleProbeKind.StepLow;
                return ObstacleProbeKind.None;
            }
            private bool ZoneBlocked(Vector3 center)
            {
                int n = Physics.OverlapSphereNonAlloc(center, ObstacleProbeRadius, _probeColliders, _obstacleZoneMask, QueryTriggerInteraction.Ignore);
                for(int i = 0; i < n; i++)
                {
                    var col = _probeColliders[i];
                    if(col == null) continue;
                    if((_obstacleProbeMask & (1 << col.gameObject.layer)) == 0) { _lastObstacleEntity = null; _lastObstacleCollider = col; return true; }
                    var ent = col.ToBaseEntity();
                    if(IsObstacle(ent)) { _lastObstacleEntity = ent; _lastObstacleCollider = col; return true; }
                }
                return false;
            }
            private static bool IsObstacle(BaseEntity ent)
            {
                if(ent == null) return true;
                switch(ent)
                    {
                        case Door:
                        {
                            return (ent?.ShortPrefabName) switch
                            {
                                "floor.ladder.hatch" => true,
                                "floor.triangle.ladder.hatch" => true,
                                "floor.ladder.hatch.toptier" => true,
                                _ => false
                            };
                        }
                        case BuildingBlock:
                        {
                            return (ent?.ShortPrefabName) switch
                            {
                                "wall" => false,
                                "wall.half" => false,
                                "wall.low" => false,
                                "wall.frame" => false,
                                "wall.doorway" => false,
                                "wall.window" => false,
                                _ => true
                            };
                        }
                        default: return true;
                    }
            }
            private bool GroundCast(out RaycastHit hit)
            {
                hit = default;
                if(_customNpc == null) return false;
                Vector3 origin = _customNpc.ServerPosition + Vector3.up * _obstacleZoneHeights[0];
                return Physics.SphereCast(origin, 0.1f, Vector3.down, out hit, 0.5f, _obstacleProbeMask, QueryTriggerInteraction.Ignore);
            }
            private bool IsOnSlopeBlock()
            {
                if(!GroundCast(out var hit)) return false;
                string sn = hit.collider.ToBaseEntity()?.ShortPrefabName;
                if(string.IsNullOrEmpty(sn)) return false;
                return sn.IndexOf("stair", StringComparison.Ordinal) >= 0
                    || sn.IndexOf("ramp", StringComparison.Ordinal) >= 0
                    || sn.IndexOf("steps", StringComparison.Ordinal) >= 0;
            }
            private bool IsOnDeployed()
            {
                if(!GroundCast(out var hit)) return false;
                return hit.collider.gameObject.layer == _deployedLayer;
            }
            private bool TryStartObstacleJump()
            {
                if(_path == null || _path.CurrentNode == null) return false;
                Vector3 pos = _customNpc.ServerPosition;
                Vector3 dir = _path.CurrentNode.Position - pos; dir.y = 0f;
                if(dir.sqrMagnitude < 0.01f) return false;
                dir.Normalize();
                Vector3 ahead = pos + dir * ObstacleJumpForward;
                Vector3 from = new Vector3(ahead.x, pos.y + ObstacleJumpMaxUp + 0.5f, ahead.z);
                if(!Physics.Raycast(from, Vector3.down, out var hit, ObstacleJumpMaxUp + 1.0f, Path._physFloorMask, QueryTriggerInteraction.Ignore))
                    return false;
                Vector3 finish = hit.point;
                float up = finish.y - pos.y;
                if(up <= 0.05f || up > ObstacleJumpMaxUp) return false;
                ObstacleProbeKind landKind = ProbeKindAt(finish);
                if(landKind == ObstacleProbeKind.Wall || landKind == ObstacleProbeKind.CrouchOver) return false;
                _obstacleJumpStart = pos;
                _obstacleJumpFinish = finish;
                _obstacleJumpProgress = 0f;
                _obstacleJumpActive = true;
                SetAirborne(true);
                return true;
            }
            private void LandObstacleJump()
            {
                if(!_obstacleJumpActive) return;
                _obstacleJumpActive = false;
                if(_customNpc != null) _customNpc.ServerPosition = _obstacleJumpFinish;
                SetAirborne(false);
            }
            private void TickObstacleJump(float delta)
            {
                _obstacleJumpProgress = Mathf.Clamp01(_obstacleJumpProgress + delta / JumpDuration);
                _customNpc.ServerPosition = EvaluateJumpArc(_obstacleJumpStart, _obstacleJumpFinish, JumpArcHeight, _obstacleJumpProgress);
                if(_obstacleJumpProgress >= 1f)
                {
                    _obstacleJumpActive = false;
                    SetAirborne(false);
                    _stallStart = UnityEngine.Time.time;
                }
            }
            private bool TickGroundPull(float delta)
            {
                Vector3 pos = _customNpc.ServerPosition;
                Vector3 origin = _obstacleProbe.Centers[0];
                if(!Physics.SphereCast(origin, ObstacleProbeRadius, Vector3.down, out var hit, GroundPullMaxDist, _groundPullMask, QueryTriggerInteraction.Ignore))
                    return false;
                float dist = pos.y - hit.point.y;
                if(dist <= GroundPullMin) return false;
                if(dist > GroundDropHigh)
                {
                    _obstacleJumpStart = pos;
                    _obstacleJumpFinish = hit.point;
                    _obstacleJumpProgress = 0f;
                    _obstacleJumpActive = true;
                    SetAirborne(true);
                    return true;
                }
                pos.y = Mathf.MoveTowards(pos.y, hit.point.y, GroundPullSpeed * delta);
                _customNpc.ServerPosition = pos;
                return false;
            }
            private bool TryStepUp(Vector3 pos)
            {
                float stepMax = _obstacleZoneHeights[1] + ObstacleProbeRadius;
                Vector3 from = new Vector3(pos.x, pos.y + stepMax + 0.3f, pos.z);
                if(Physics.Raycast(from, Vector3.down, out var hit, stepMax + 0.5f, Path._physFloorMask, QueryTriggerInteraction.Ignore)
                   && hit.point.y > pos.y + 0.05f && hit.point.y - pos.y <= stepMax)
                {
                    pos.y = hit.point.y;
                    _customNpc.ServerPosition = pos;
                    _stallStart = UnityEngine.Time.time;
                    return true;
                }
                return false;
            }
            private bool TryResolveStandingObstacle()
            {
                if(_lastObstacleCollider == null) return false;
                Vector3 pos = _customNpc.ServerPosition;
                Vector3 closest = _lastObstacleCollider is MeshCollider _mc && !_mc.convex
                    ? _lastObstacleCollider.ClosestPointOnBounds(pos)
                    : _lastObstacleCollider.ClosestPoint(pos);
                Vector3 outDir = pos - closest; outDir.y = 0f;
                if(outDir.sqrMagnitude < 0.0001f) return false;
                outDir.Normalize();

                float stepMax = _obstacleZoneHeights[1] + ObstacleProbeRadius;
                Vector3 inward = closest - outDir * 0.15f;
                Vector3 from = new Vector3(inward.x, pos.y + stepMax + 0.3f, inward.z);
                if(Physics.Raycast(from, Vector3.down, out var hit, stepMax + 0.5f, Path._physFloorMask, QueryTriggerInteraction.Ignore)
                   && hit.point.y > pos.y + 0.05f && hit.point.y - pos.y <= stepMax)
                {
                    Vector3 onTop = new Vector3(inward.x, hit.point.y, inward.z);
                    if(ProbeKindAt(onTop) == ObstacleProbeKind.None)
                    {
                        _customNpc.ServerPosition = onTop;
                        _stallStart = UnityEngine.Time.time;
                        return true;
                    }
                }
                Vector3 pushed = pos + outDir * StandPushStep;
                if(ProbeKindAt(pushed) == ObstacleProbeKind.None)
                {
                    _customNpc.ServerPosition = pushed;
                    _stallStart = UnityEngine.Time.time;
                    return true;
                }
                return false;
            }
            private bool TryCloseBlockingHatch()
            {
                if(_customNpc == null) return false;
                int count = Physics.OverlapSphereNonAlloc(_customNpc.ServerPosition, HatchCloseRadius, _probeColliders, _obstacleProbeMask, QueryTriggerInteraction.Ignore);
                for(int i = 0; i < count; i++)
                {
                    if(!(_probeColliders[i]?.ToBaseEntity() is Door door) || !door.IsValid()) continue;
                    if(door.ShortPrefabName.IndexOf("hatch", StringComparison.Ordinal) < 0) continue;
                    if(!door.IsOpen() || door.GetComponentInChildren<TriggerLadder>(true) == null) continue;
                    if(!door.canNpcOpen) return false;
                    if(Interface.CallHook("OnNpcClosingDoor", _customNpc, door) == null)
                        door.SetOpen(false);
                    BuildingNavigation.NoteBlockChange(door.buildingID);
                    Pause(CloseDoorPause);
                    _stallStart = UnityEngine.Time.time;
                    return true;
                }
                return false;
            }
            #endregion

            #region Защита навигации - меры спасения и политика места

            public enum NavPlace
            {
                World,
                Monument,
                Building,
            }

            public struct NavGuardPolicy
            {
                public NavPlace Place;
                public bool WarpRecover;
                public bool WarpRescue;
                public bool WarpIslandEscape;
                public bool WarpHazardPush;
                public bool WarpNeedsSight;
                public float WarpMaxDistance;
                public bool SelfWalkEscape;
                public bool DeepWaterStop;
            }

            protected sealed class NavGuard
            {
                private readonly NavigatorNpc _nav;

                private const float BuildingMargin = 1.5f;
                private const float ConstructionProbe = 2.5f;
                private static readonly int ConstructionMask = LayerMask.GetMask("Construction");
                private const float PlaceCacheTime = 0.25f;
                private const float PlaceCacheMove = 1f;
                private static readonly Collider[] ConstructionHits = new Collider[4];

                private NavPlace _place;
                private Vector3 _placePos = Vector3.positiveInfinity;
                private float _placeUntil;

                public NavGuard(NavigatorNpc nav) { _nav = nav; }

                public NavPlace Place
                {
                    get
                    {
                        Vector3 pos = _nav._customNpc != null ? _nav._customNpc.ServerPosition : Vector3.zero;
                        if(UnityEngine.Time.time < _placeUntil
                           && (pos - _placePos).sqrMagnitude < PlaceCacheMove * PlaceCacheMove) return _place;
                        _place = Detect(pos);
                        _placePos = pos;
                        _placeUntil = UnityEngine.Time.time + PlaceCacheTime;
                        return _place;
                    }
                }

                public NavGuardPolicy Policy => PolicyFor(Place);

                public void Invalidate() => _placeUntil = 0f;

                public static NavGuardPolicy PolicyFor(NavPlace place)
                {
                    switch(place)
                    {
                        case NavPlace.Building:
                            return new NavGuardPolicy
                            {
                                Place = place,
                                WarpRecover = false,
                                WarpRescue = false,
                                WarpIslandEscape = false,
                                WarpHazardPush = true,
                                WarpNeedsSight = true,
                                WarpMaxDistance = 2f,
                                SelfWalkEscape = true,
                                DeepWaterStop = false,
                            };
                        case NavPlace.Monument:
                            return new NavGuardPolicy
                            {
                                Place = place,
                                WarpRecover = true,
                                WarpRescue = true,
                                WarpIslandEscape = true,
                                WarpHazardPush = true,
                                WarpNeedsSight = true,
                                WarpMaxDistance = 6f,
                                SelfWalkEscape = true,
                                DeepWaterStop = true,
                            };
                        default:
                            return new NavGuardPolicy
                            {
                                Place = NavPlace.World,
                                WarpRecover = true,
                                WarpRescue = true,
                                WarpIslandEscape = true,
                                WarpHazardPush = true,
                                WarpNeedsSight = true,
                                WarpMaxDistance = float.PositiveInfinity,
                                SelfWalkEscape = true,
                                DeepWaterStop = true,
                            };
                    }
                }

                public float ClampRadius(float radius)
                {
                    float max = Policy.WarpMaxDistance;
                    return float.IsPositiveInfinity(max) ? radius : Mathf.Min(radius, max);
                }

                public static NavPlace Detect(Vector3 pos)
                {
                    var buildStore = HelperBuildingNavMesh.Instance;
                    if(buildStore != null && buildStore.TryGetNavAt(pos, out _, BuildingMargin)) return NavPlace.Building;
                    if(BuildingNavigation.TryGetZoneContaining(pos, out _, out _, out bool isSimple) && isSimple)
                        return NavPlace.Building;
                    if(HasConstructionAround(pos)) return NavPlace.Building;

                    var savedStore = HelperSavedNavMesh.Instance;
                    if(savedStore != null && savedStore.TryGetInstanceAt(pos, out _)) return NavPlace.Monument;
                    if(HelperMonuments.Instance != null && HelperMonuments.Instance.HasMonument(pos)) return NavPlace.Monument;

                    return NavPlace.World;
                }

                private static bool HasConstructionAround(Vector3 pos)
                {
                    int count = Physics.OverlapSphereNonAlloc(pos + Vector3.up * 0.5f, ConstructionProbe,
                                                              ConstructionHits, ConstructionMask, QueryTriggerInteraction.Ignore);
                    for(int i = 0; i < count; i++)
                    {
                        if(ConstructionHits[i] == null) continue;
                        if(ConstructionHits[i].GetComponentInParent<BuildingBlock>() != null) return true;
                    }
                    return false;
                }
            }

            private NavGuard _guard;
            protected NavGuard Guard => _guard ?? (_guard = new NavGuard(this));

            public static NavGuardPolicy PolicyAt(Vector3 pos) => NavGuard.PolicyFor(NavGuard.Detect(pos));

            #endregion
        }
        #endregion

