        public sealed class Path : List<PathNode>, Pool.IPooled
        {
            #region Fields And Properties
            private const int size_max = 500;
            private Task findPath;
            private CancellationTokenSource _pathTokenSource;
            private int _currentIndex;
            private bool isPool;
            public int CurrentIndex
            {
                get => _currentIndex;
                set => _currentIndex = value;
            }
            public bool HasPath => IsValid() && !IsFindingPath && Count > 1;
            public PathNode CurrentNode => HasPath && _currentIndex >= 0 && _currentIndex < Count ? this[_currentIndex] : default;
            public PathNode FinishNode => !HasPath ? default : this[Count - 1];
            public bool IsFindingPath => findPath != null && !findPath.IsCompleted;
            public string DescribeFindTask()
            {
                if(findPath == null) return "none";
                string token = _pathTokenSource == null ? "none" : _pathTokenSource.IsCancellationRequested ? "cancelled" : "live";
                return findPath.Status + ", token " + token;
            }

            public BaseCustomNpc OwnerNpc { get; set; }

            public int NavMeshAreaMask = -1;
            #endregion

            #region Override Methods
            public static Path GetPool()
            {
                return Pool.Get<Path>();
            }
            public static void SetPool(ref Path path)
            {
                Pool.Free(ref path);
            }
            void Pool.IPooled.EnterPool()
            {
                isPool = true;
                Reset();
                OwnerNpc = null;
            }
            void Pool.IPooled.LeavePool()
            {
                isPool = false;
                Reset();
            }
            #endregion

            #region Methods
            public bool IsValid()
            {
                return !isPool;
            }

            public void Reset()
            {
                CancelFindPath();
                Clear();
                _currentIndex = -1;
            }
            private void CancelFindPath()
            {
                if (_pathTokenSource != null)
                {
                    PluginTask.CancelTask(_pathTokenSource);
                    PluginTask.RemoveToken(_pathTokenSource);
                    _pathTokenSource = null;
                }
                findPath = null;
            }
            private new void Clear()
            {
                foreach(var item in this)
                {
                    var _item = item;
                    Pool.Free(ref _item);
                }
                base.Clear();
            }
            public void Insert(IAIPathNode start, IAIPathNode finish)
            {
                if(!HasPath || _currentIndex < 0) return;
                InsertPath(_currentIndex + 1, start, finish);
            }
            public void InsertPath(int index, IAIPathNode start, IAIPathNode finish, bool startViaNavmesh = false, bool finishViaNavmesh = false)
            {
                CancelFindPath();
                bool startValid = start?.IsValid() == true;
                bool finishValid = finish?.IsValid() == true;
                bool samePos = start.Position == finish.Position;
                if(startValid && finishValid)
                {
                    if(samePos)
                    {
                        return;
                    }
                    _pathTokenSource = new CancellationTokenSource();
                    var cts = _pathTokenSource;
                    var token = cts.Token;
                    findPath = PluginTask.Run(async () => await FindPathAsync(index, start, finish, startViaNavmesh, finishViaNavmesh, cts, token), cts);
                }
            }
            public bool TryNextNode(out PathNode node)
            {
                node = null;

                if(HasPath && _currentIndex >= 0)
                {
                    int index = _currentIndex + 1;
                    if(index >= 0 && index < Count)
                    {
                        _currentIndex = index;
                        node = CurrentNode;
                    }
                }

                return node != null && node.IsValid();
            }

            public new void Add(PathNode node)
            {
                if(IsValid() && Count < size_max && node?.IsValid() == true)
                {
                    base.Add(node);
                }
            }
            #endregion

            #region Finding Path
            private async Task FindPathAsync(int index, IAIPathNode start, IAIPathNode finish, bool startViaNavmesh, bool finishViaNavmesh, CancellationTokenSource cts, CancellationToken token)
            {
                List<IAIPathNode> resultNodes = null;
                float totalDistance = 0f;
                bool linksExactFinish = false;

                string errorLog = null;
                try
                {
                    bool hasAnyLinks = false;
                    var edgesEnum = start.Edges;
                    if (edgesEnum != null) hasAnyLinks = edgesEnum.GetEnumerator().MoveNext();
                    if (!hasAnyLinks)
                    {
                        var linkedEnum = start.Linked;
                        if (linkedEnum != null) hasAnyLinks = linkedEnum.GetEnumerator().MoveNext();
                    }

                    if (hasAnyLinks)
                    {
                        var (linksOk, linksNodes, linksDist, linksExact) = await FindPathByLinksAsync(start, finish, token);
                        if (token.IsCancellationRequested) goto WriteResult;
                        if (linksOk) { resultNodes = linksNodes; totalDistance = linksDist; linksExactFinish = linksExact; }
                    }

                    WriteResult:
                    Debug.Log<Path>("Path built: {0} nodes, distance {1:F1}m", resultNodes?.Count ?? 0, totalDistance);
                }
                catch (System.Exception ex)
                {
                    errorLog = $"FindPathAsync exception: {ex}";
                }
                if (errorLog != null)
                    await PluginTask.NextTickAsync(() => { Debug.LogError<Path>("{0}", errorLog); return true; });
                await PluginTask.NextTickAsync(() =>
                {
                    if (!token.IsCancellationRequested && resultNodes != null)
                    {
                        int insertStart = index;
                        int lastResultPathIdx = -1;
                        for (int i = 0; i < resultNodes.Count; i++)
                        {
                            var node = resultNodes[i];
                            var prevNode = i == 0 ? null : resultNodes[i - 1];
                            var nextNode = i + 1 < resultNodes.Count ? resultNodes[i + 1] : null;
                            Insert(index, PathNode.GetPool(node, prevNode, nextNode, NavMeshAreaMask));
                            if(((i == 0 && startViaNavmesh) || (i == resultNodes.Count - 1 && finishViaNavmesh))
                               && this[index] != null)
                                this[index].Hint |= NodeHint.NavMesh;
                            lastResultPathIdx = index;
                            index ++;
                            PathNode.AppendWaypoints(this, ref index, node, nextNode);
                        }
                        int inserted = index - insertStart;
                        if (_currentIndex < 0) _currentIndex = 0;
                        else if (insertStart <= _currentIndex) _currentIndex += inserted;
                        if (OwnerNpc != null && insertStart >= 0 && insertStart < Count
                            && _currentIndex >= 0 && _currentIndex < Count && _currentIndex != insertStart
                            && this[insertStart] != null && this[_currentIndex] != null)
                        {
                            Vector3 botP = OwnerNpc.ServerPosition;
                            if ((this[insertStart].Position - botP).sqrMagnitude < (this[_currentIndex].Position - botP).sqrMagnitude)
                                _currentIndex = insertStart;
                        }

                        if (!linksExactFinish && lastResultPathIdx >= 0 && lastResultPathIdx < Count && this[lastResultPathIdx] != null)
                        {
                            this[lastResultPathIdx].IsStuckPoint = true;
                        }
                    }
                    if (_pathTokenSource == cts)
                    {
                        findPath = null;
                        PluginTask.RemoveToken(cts);
                        cts.Dispose();
                        _pathTokenSource = null;
                    }
                    return true;
                });
            }

            #endregion

            #region Static Path Search (links)

            private const float HeuristicWeight = 2f;
            private const float QuantizeY = 0.25f;
            private const int AStarLinksMaxVisited = 2000;
            private const int AStarLinksExtendedMaxVisited = 8000;
            private const float AStarRetryFinishDistanceThreshold = 10f;

            internal static readonly int _physObstacleMask = LayerMask.GetMask("Default", "Deployed", "Trigger", "Construction", "Terrain", "World", "Vehicle World", "Vehicle Large", "Vehicle Detailed", "Prevent Movement", "Transparent");
            internal static readonly int _physFloorMask = LayerMask.GetMask("Default", "Deployed", "Construction", "Terrain", "World", "Vehicle World", "Vehicle Large", "Vehicle Detailed");

            private static float Heuristic(IAIPathNode from, IAIPathNode to)
            {
                return Vector3.Distance(from.Position, to.Position) * HeuristicWeight;
            }

            private static Vector3 QuantizePos(Vector3 p)
            {
                float s = HelperMap.PointMapNode.StepSize;
                return new Vector3(
                    Mathf.Round(p.x / s) * s,
                    Mathf.Round(p.y / QuantizeY) * QuantizeY,
                    Mathf.Round(p.z / s) * s);
            }

            internal bool CanUseDoorEdge(IAIPathNode sourceNode, IAIPathNode targetNode)
            {
                if (sourceNode == null || targetNode == null) return false;
                Door door = targetNode.LinkedDoor;
                if (!door.IsValid()) return false;
                if (door.IsOpen()) return true;
                BaseCustomNpc npc = OwnerNpc;
                if (npc == null) return false;
                if (!npc.CanOpenDoors) return false;
                if (npc.IsDoorBlocked(door.net.ID)) return false;
                CardReader reader = sourceNode.LinkedReader;
                if (reader != null && reader.IsValid() && !reader.IsPowered()) return false;
                PressButton button = sourceNode.LinkedButton;
                if (button != null && !button.IsValid()) button = null;
                BaseLock lockEntity = (button == null && reader == null) ? door.GetSlot(BaseEntity.Slot.Lock) as BaseLock : null;

                var fsmState = npc.brain?.StateMachine?.GetCurrentState() as FSM.BaseStatePlayerNpc;
                object result = fsmState?.CanUseDoor(door, lockEntity, reader);
                if (result == null)
                    result = Interface.CallHook("CanNpcUseDoor", npc, door, lockEntity, reader, button);
                return result != null;
            }

            private async Task<(bool Result, List<IAIPathNode> Nodes, float Distance, bool ExactFinish)> FindPathByLinksAsync(
                IAIPathNode start,
                IAIPathNode finish,
                CancellationToken token)
            {
                var phase1 = await FindPathByLinksAsyncCore(start, finish, token, AStarLinksMaxVisited);
                if (token.IsCancellationRequested || phase1.ExactFinish)
                    return (phase1.Result, phase1.Nodes, phase1.Distance, phase1.ExactFinish);

                float bestDist = phase1.Result && phase1.Nodes != null && phase1.Nodes.Count > 0
                    ? Vector3.Distance(phase1.Nodes[phase1.Nodes.Count - 1].Position, finish.Position)
                    : float.PositiveInfinity;
                if (bestDist <= AStarRetryFinishDistanceThreshold)
                    return (phase1.Result, phase1.Nodes, phase1.Distance, phase1.ExactFinish);

                var phase2 = await FindPathByLinksAsyncCore(start, finish, token, AStarLinksExtendedMaxVisited);
                return (phase2.Result, phase2.Nodes, phase2.Distance, phase2.ExactFinish);
            }

            private async Task<(bool Result, List<IAIPathNode> Nodes, float Distance, bool ExactFinish)> FindPathByLinksAsyncCore(
                IAIPathNode start,
                IAIPathNode finish,
                CancellationToken token,
                int maxVisited)
            {
                const int BatchSize = 16;

                var openList = new AStarNodeList();
                var openMap = new Dictionary<Vector3, AStarNode>();
                var visited = new HashSet<Vector3>();
                AStarNode bestReachable = null;
                int visitedCount = 0;

                var batch = new List<AStarNode>(BatchSize);
                var batchLinks = new List<(int BatchIdx, IAIPathNode Neighbor, float Cost)>(BatchSize * 12);

                openList.Add(new AStarNode(0f, Heuristic(start, finish), null, start));
                openMap[QuantizePos(start.Position)] = openList[0];

                while (openList.Count > 0 && !token.IsCancellationRequested && visitedCount < maxVisited)
                {
                    batch.Clear();
                    while (openList.Count > 0 && batch.Count < BatchSize)
                    {
                        var candidate = openList[0];
                        openList.RemoveAt(0);
                        var qpos = QuantizePos(candidate.Node.Position);
                        openMap.Remove(qpos);
                        if (visited.Add(qpos))
                        {
                            batch.Add(candidate);
                            visitedCount++;
                            if (bestReachable == null || candidate.H < bestReachable.H)
                                bestReachable = candidate;
                        }
                    }

                    if (batch.Count == 0) continue;

                    AStarNode finishNode = null;
                    foreach (var n in batch)
                    {
                        if (n.Satisfies(finish)) { finishNode = n; break; }
                    }
                    if (finishNode != null)
                    {
                        var nodes = ReconstructLinkPath(finishNode);
                        if (nodes.Count == 0 || nodes[nodes.Count - 1] != finish)
                            nodes.Add(finish);
                        return (true, nodes, ComputeLinkPathDist(nodes), true);
                    }

                    batchLinks.Clear();
                    if (token.IsCancellationRequested) return (false, null, 0f, false);
                    await PluginTask.NextTickAsync(() =>
                    {
                        for (int i = 0; i < batch.Count; i++)
                        {
                            var fromPos = batch[i].Node.Position;
                            var edges = batch[i].Node.Edges;
                            if (edges != null)
                            {
                                foreach (var edge in edges)
                                {
                                    if (edge.Target?.IsValid() != true) continue;
                                    if (edge.Hint.HasFlag(NodeHint.OpenDoor) && edge.Target.LinkedDoor.IsValid())
                                    {
                                        if (!CanUseDoorEdge(batch[i].Node, edge.Target)) continue;
                                    }
                                    float cost = edge.Cost > 0f ? edge.Cost : Vector3.Distance(fromPos, edge.Target.Position);
                                    batchLinks.Add((i, edge.Target, cost));
                                }
                            }
                            var links = batch[i].Node.Linked;
                            if (links != null)
                            {
                                foreach (var neighbor in links)
                                {
                                    if (neighbor?.IsValid() != true) continue;
                                    batchLinks.Add((i, neighbor, Vector3.Distance(fromPos, neighbor.Position)));
                                }
                            }
                        }
                        return true;
                    });

                    if (token.IsCancellationRequested) return (false, null, 0f, false);

                    bool needsSort = false;
                    foreach (var (batchIdx, neighbor, cost) in batchLinks)
                    {
                        var qpos = QuantizePos(neighbor.Position);
                        if (visited.Contains(qpos)) continue;

                        float newG = batch[batchIdx].G + cost;
                        if (openMap.TryGetValue(qpos, out var existing))
                        {
                            if (newG < existing.G)
                            {
                                existing.Update(newG, existing.H, batch[batchIdx], neighbor);
                                needsSort = true;
                            }
                        }
                        else
                        {
                            var newNode = new AStarNode(newG, Heuristic(neighbor, finish), batch[batchIdx], neighbor);
                            openList.Add(newNode);
                            openMap[qpos] = newNode;
                            needsSort = true;
                        }
                    }
                    if (needsSort) openList.AStarNodeSort();
                }

                if (bestReachable != null
                    && Vector3.Distance(bestReachable.Node.Position, start.Position) > HelperMap.PointMapNode.StepSize)
                {
                    var nodes = ReconstructLinkPath(bestReachable);
                    return (true, nodes, ComputeLinkPathDist(nodes), false);
                }

                return (false, null, 0f, false);
            }

            private static List<IAIPathNode> ReconstructLinkPath(AStarNode leaf)
            {
                var path = new List<IAIPathNode>();
                for (var cur = leaf; cur != null; cur = cur.Parent)
                    path.Add(cur.Node);
                path.Reverse();
                return path;
            }

            private static float ComputeLinkPathDist(List<IAIPathNode> path)
            {
                float dist = 0f;
                for (int i = 1; i < path.Count; i++)
                    dist += Vector3.Distance(path[i - 1].Position, path[i].Position);
                return dist;
            }

            #endregion

            public static implicit operator bool(Path path)
            {
                return path != null && path.IsValid();
            }

        }
        public sealed class PathNode : Pool.IPooled
        {
            public Vector3 Position = Vector3.zero;
            public NodeHint Hint = NodeHint.None;
            public Component Entity = null;
            public Door Door = null;
            public bool IsGraph = false;
            public bool IsTransition = false;
            public bool IsStuckPoint = false;
            public bool IsLayer = false;
            public bool LayerLeg = false;
            public bool IsLayerStartRescue = false;
            private bool _isPool = false;

            void Pool.IPooled.EnterPool()
            {
                Position = Vector3.zero;
                Hint = NodeHint.None;
                Entity = null;
                Door = null;
                IsGraph = false;
                IsTransition = false;
                IsStuckPoint = false;
                IsLayer = false;
                LayerLeg = false;
                IsLayerStartRescue = false;
                _isPool = true;
            }

            void Pool.IPooled.LeavePool()
            {
                _isPool = false;
            }

            private const float NavMeshSnapRadius = 3f;

            private static Vector3 SnapToNavMesh(Vector3 pos, int areaMask)
            {
                if(Rust.Ai.Gen2.RustNavMeshHelpers.SamplePosition(pos, out var hit, NavMeshSnapRadius, areaMask))
                    return hit.position;
                return pos;
            }

            public static PathNode GetPool(IAIPathNode node, IAIPathNode nodePrev, IAIPathNode nodeNext, int navMeshAreaMask)
            {
                var _node = Pool.Get<PathNode>();
                _node.Position = node.Position;
                _node.Hint = NodeHint.None;
                _node.IsGraph = true;
                if(nodeNext != null)
                {
                    bool hintFromEdge = false;
                    if(node.Edges != null)
                    {
                        foreach(var edge in node.Edges)
                        {
                            hintFromEdge = true;
                            if(edge.Target == nodeNext)
                            {
                                _node.Hint = edge.Hint;
                                break;
                            }
                        }
                    }
                    if(!hintFromEdge) _node.Hint = node.Hint;
                }
                NodeHint hint = _node.Hint;
                if(hint.HasFlag(NodeHint.OpenDoor))
                {
                    if(nodeNext?.LinkedDoor is Door door) _node.Door = door;
                    if(node.LinkedButton != null) _node.Entity = node.LinkedButton;
                    else if(node.LinkedReader != null) _node.Entity = node.LinkedReader;
                }
                else if(hint.HasFlag(NodeHint.CloseDoor))
                {
                    if(node.LinkedDoor is Door doorOwn) _node.Door = doorOwn;
                    else if(nodePrev?.LinkedDoor is Door doorPrev) _node.Door = doorPrev;
                }
                if(hint.HasFlag(NodeHint.Climb) && _node.Entity == null) _node.Entity = node.LinkedLadderTrigger;
                bool navOut = false, navIn = false;
                if(node.Edges != null)
                {
                    foreach(var edge in node.Edges)
                    {
                        if(edge.Target == nodeNext && edge.Hint.HasFlag(NodeHint.NavMesh)) { navOut = true; break; }
                    }
                }
                if(!navOut && nodePrev?.Edges != null)
                {
                    foreach(var edge in nodePrev.Edges)
                    {
                        if(edge.Target == node && edge.Hint.HasFlag(NodeHint.NavMesh)) { navIn = true; break; }
                    }
                }
                if(navOut || navIn) _node.Position = SnapToNavMesh(node.Position, navMeshAreaMask);
                return _node;
            }

            public static PathNode GetPool(Vector3 position, NodeHint hint = NodeHint.None)
            {
                var _node = Pool.Get<PathNode>();
                _node.Position = position;
                _node.Hint = hint;
                return _node;
            }

            public static void AppendWaypoints(Path path, ref int index, IAIPathNode node, IAIPathNode nodeNext)
            {
                if(path == null || node?.Edges == null || nodeNext == null) return;
                foreach(var edge in node.Edges)
                {
                    if(edge.Target != nodeNext) continue;
                    if(edge.Waypoints != null)
                    {
                        bool snap = edge.Hint.HasFlag(NodeHint.NavMesh);
                        int areaMask = path.NavMeshAreaMask;
                        foreach(var point in edge.Waypoints)
                        {
                            Vector3 pos = snap ? SnapToNavMesh(point, areaMask) : point;
                            var wp = GetPool(pos, node.Hint);
                            wp.IsGraph = true;
                            path.Insert(index, wp);
                            index ++;
                        }
                    }
                    return;
                }
            }
            public static void SetPool(ref PathNode node)
            {
                Pool.Free(ref node);
                node = null;
            }

            public bool IsValid() => !_isPool;

        }

        #endregion
        [JsonConverter(typeof(StringEnumConverter))]
        public enum NavigationSpeed
        {
            Slowest,
            Slow,
            Normal,
            Fast
        }

    }

    #region User Id Pool register
    public partial class NPCsController
    {
        public class UserIdPool
        {
            private const ulong GenderSeed = 4332UL;
            private const ulong ModelSeed = 4333UL;
            public const int ModelsPerGender = 4;

            private readonly ulong _idRangeMin;
            private readonly ulong _idRangeMax;
            private readonly HashSet<ulong> usedIds = new();
            private readonly HashSet<ulong> reservedIds = new();
            private readonly Dictionary<ulong, BaseCustomNpc> _idOwners = new();

            public static UserIdPool Instance { get; private set; }

            private UserIdPool(ulong rangeMin, ulong rangeMax)
            {
                _idRangeMin = rangeMin;
                _idRangeMax = rangeMax;
            }

            public static void OnInitPlugin(ulong rangeMin, ulong rangeMax) => Instance = new UserIdPool(rangeMin, rangeMax);
            public static void OnUnloadPlugin() => Instance = null;

            public bool TryGetUserId(bool preferFemale, int preferredModel, out ulong userId, ulong fixedId = 0)
            {
                if (fixedId != 0)
                {
                    if (!usedIds.Contains(fixedId))
                    {
                        reservedIds.Remove(fixedId);
                        usedIds.Add(fixedId);
                        userId = fixedId;
                        return true;
                    }
                    reservedIds.Remove(fixedId);
                }
                preferredModel = preferredModel == 0 ? Random.Range(0, ModelsPerGender) : Mathf.Clamp(preferredModel - 1, 0, ModelsPerGender - 1);

                ulong rangeCount = _idRangeMax - _idRangeMin + 1;
                ulong start = (ulong)(Random.value * rangeCount) % rangeCount;
                for (ulong k = 0; k < rangeCount; k++)
                {
                    ulong id = _idRangeMin + ((start + k) % rangeCount);
                    if (usedIds.Contains(id) || reservedIds.Contains(id)) continue;
                    if (IsFemale(id) != preferFemale) continue;
                    if (GetModelIndex(id) != preferredModel) continue;

                    usedIds.Add(id);
                    userId = id;
                    return true;
                }

                userId = 0;
                return false;
            }

            public void DieUserId(ulong userId)
            {
                usedIds.Remove(userId);
                reservedIds.Add(userId);
                _idOwners.Remove(userId);
            }

            public void ReserveUserId(ulong userId) => reservedIds.Add(userId);

            public void SetOwner(ulong userId, BaseCustomNpc owner) => _idOwners[userId] = owner;

            public void ReleaseUserId(ulong userId)
            {
                usedIds.Remove(userId);
                reservedIds.Remove(userId);
                _idOwners.Remove(userId);
            }

            public void ReleaseUserId(BaseCustomNpc owner)
            {
                if (owner == null) return;
                ulong id = owner.userID;
                if (_idOwners.TryGetValue(id, out BaseCustomNpc registered) && registered != null && registered != owner)
                {
                    return;
                }
                ReleaseUserId(id);
            }

            public static bool IsFemale(ulong userId)
                => GetFloatBasedOnUserID(userId, GenderSeed) > 0.5f;

            public static int GetModelIndex(ulong userId)
                => (int)(GetFloatBasedOnUserID(userId, ModelSeed) * ModelsPerGender);

            private static float GetFloatBasedOnUserID(ulong steamId, ulong seed)
            {
                Random.State prevState = Random.state;
                Random.InitState((int)(seed + steamId));
                float result = Random.Range(0f, 1f);
                Random.state = prevState;
                return result;
            }
        }
    }
