        public class RustLocalization
        {
            private Dictionary<string, Dictionary<string, string>> localizationRust = new();
            private readonly object _lock = new();
            public static RustLocalization Instance { get; private set; }
            public static void OnInitPlugin()
            {
                Instance = new();
                Instance.Init();
            }
            public static void OnUnloadPlugin()
            {
                Instance = null;
            }

            private async void Init()
            {
                var cts = PluginTask.Token;
                if (cts.IsCancellationRequested) return;

                var (languages, localizationData) = await PluginTask.NextTickAsync(() =>
                {
                    var langs = NPCsController.Instance.lang.GetLanguages();
                    if (langs == null || langs.Length == 0) return (null, null);
                    return (new List<string>(langs),
                            new List<KeyValuePair<string, Dictionary<string, string>>>(GetLocalization()));
                });

                if (languages == null || cts.IsCancellationRequested) return;

                await PluginTask.Run(() =>
                {
                    foreach (var langue in localizationData)
                    {
                        if (cts.IsCancellationRequested) break;
                        lock (_lock)
                        {
                            if (!localizationRust.ContainsKey(langue.Key))
                            {
                                if (languages.Exists(x => x.ToLower() == langue.Key)) localizationRust.Add(langue.Key, langue.Value);
                            }
                            else
                            {
                                foreach (var token in langue.Value)
                                {
                                    if (!localizationRust[langue.Key].ContainsKey(token.Key)) localizationRust[langue.Key].Add(token.Key, token.Value);
                                }
                            }
                        }
                    }
                });
            }

            public string GetLangText(string langueUser, Translate.Phrase phrase)
            {
                lock (_lock)
                {
                    return localizationRust.TryGetValue(langueUser, out var langPhrase) && langPhrase.TryGetValue(phrase.token, out string text) ? text : phrase.english;
                }
            }
            private IEnumerable<KeyValuePair<string, Dictionary<string, string>>> GetLocalization()
            {
                foreach (var item in UnityEngine.AssetBundle.GetAllLoadedAssetBundles())
                {
                    if (item?.name == "shared/content.bundle")
                    {
                        var names = FileSystem.FindAll("assets/localization/");
                        if (names != null)
                        {
                            foreach (var name in names)
                            {
                                string[] parts = name.Split(new[] { '/' }, System.StringSplitOptions.RemoveEmptyEntries);
                                string language = "";
                                if (parts.Length >= 3) language = parts[2];
                                if (!string.IsNullOrEmpty(language) && language != "editor" && item.LoadAsset<UnityEngine.TextAsset>(name) is UnityEngine.TextAsset textAsset)
                                {
                                    yield return new KeyValuePair<string, Dictionary<string, string>>(language, JsonConvert.DeserializeObject<Dictionary<string, string>>(textAsset.text));
                                }
                            }
                            yield break;
                        }
                    }
                }
            }
        }
        public class HelperRoads
        {
            public enum RoadKind { Default, Main, Side, Trail, Rail }

            private static List<PathList> GetRoadPathList(RoadKind kind)
            {
                var path = TerrainMeta.Path;
                if (path == null) return null;
                switch (kind)
                {
                    case RoadKind.Main: return path.MainRoads;
                    case RoadKind.Side: return path.SideRoads;
                    case RoadKind.Trail: return path.TrailRoads;
                    case RoadKind.Rail: return path.Rails;
                    default: return path.Roads;
                }
            }

            public static bool TryGetRandomRoadPoint(float cycle, out Vector3 result)
                => TryGetRandomRoadPoint(cycle, RoadKind.Default, out result);

            public static bool TryGetRandomRoadPoint(float cycle, RoadKind kind, out Vector3 result)
            {
                result = Vector3.zero;
                int areaMask = 1 << NavMesh.GetAreaFromName("Walkable");
                var roads = GetRoadPathList(kind);
                if (roads == null || roads.Count == 0) roads = TerrainMeta.Path?.Roads;
                if (roads == null || roads.Count == 0) return false;

                while (cycle > 0)
                {
                    cycle--;

                    Vector3 position = roads.GetRandom().Path.Points.GetRandom();
                    HelperMap.ToGroundPoint(ref position);
                    if (Rust.Ai.Gen2.RustNavMeshHelpers.SamplePosition(position, out var hit, 2f, areaMask))
                    {
                        position = hit.position;
                    }
                    else continue;

                    bool noMonuments = true;
                    bool noPlayers = Physics.OverlapSphere(position, 50f, LayerMask.GetMask("Player (Server)", "Player Movement")).Length == 0;

                    foreach (var monument in HelperMonuments.Instance.allMonuments)
                    {
                        if (monument.IsInBounds(position))
                        {
                            noMonuments = false;
                            break;
                        }
                        if (Vector3.Distance(monument.transform.position, position) <= monument.Bounds.size.x || Vector3.Distance(monument.transform.position, position) <= 40f)
                        {
                            noMonuments = false;
                            break;
                        }
                    }

                    if (noMonuments && noPlayers)
                    {
                        result = position;
                        break;
                    }
                }

                return result != Vector3.zero;
            }

            public static bool CheckRoad(Vector3 position)
            {
                return HelperMap.DoCheckSphereTag(position, 3f, GameObjectTag.Road, "World");
            }
        }
        public class HelperMonuments
        {
            public static HelperMonuments Instance;
            private readonly object _lock = new();
            public readonly Dictionary<MonumentInfo, List<Collider>> monumentsPreventBuilding = new();
            public readonly List<MonumentInfo> allMonuments = new();
            public readonly Dictionary<MonumentInfo, Bounds> monumentBoundsCache = new();
            public readonly HashSet<MonumentInfo> noObbMonuments = new();
            public bool IsInitMonuments => allMonuments.Count > 1;

            public static void OnInitPlugin()
            {
                Instance = new();
                ServerObjectForPlugin.Instance?.Invoke(Instance.Create, 0.1f);
            }
            public static void OnUnloadPlugin()
            {
                Instance = null;
            }

            private async void Create()
            {
                var token = PluginTask.Token;
                if (token.IsCancellationRequested) return;

                var colliderData = await PluginTask.NextTickAsync(() =>
                {
                    if (TerrainMeta.Path.Monuments?.Count > 0) allMonuments.AddRange(TerrainMeta.Path.Monuments);
                    var data = new List<(MonumentInfo monument, Collider collider)>();
                    foreach (var monument in allMonuments)
                    {
                        var colliders = monument.GetComponentsInChildren<Collider>();
                        if (colliders == null) continue;
                        foreach (var collider in colliders)
                            if (collider.gameObject.name.IndexOf("prevent_building", StringComparison.OrdinalIgnoreCase) >= 0)
                                data.Add((monument, collider));
                    }
                    return data;
                });

                if (token.IsCancellationRequested) return;

                await PluginTask.Run(() =>
                {
                    foreach (var (monument, collider) in colliderData)
                    {
                        if (token.IsCancellationRequested) return;
                        lock (_lock)
                        {
                            if (!monumentsPreventBuilding.TryGetValue(monument, out var list))
                            {
                                list = new List<Collider>();
                                monumentsPreventBuilding.Add(monument, list);
                            }
                            list.Add(collider);
                        }
                    }
                });

                if (token.IsCancellationRequested) return;

                lock (_lock)
                {
                    monumentBoundsCache.Clear();
                    noObbMonuments.Clear();
                    foreach (var monument in allMonuments)
                    {
                        Bounds wb;
                        bool usedPreventBuilding = false;
                        if (monumentsPreventBuilding.TryGetValue(monument, out var cols) && cols.Count > 0)
                        {
                            wb = cols[0].bounds;
                            for (int i = 1; i < cols.Count; i++) wb.Encapsulate(cols[i].bounds);
                            if (wb.extents.magnitude > 500f)
                                wb = new Bounds(wb.center, Vector3.one * 500f);
                            usedPreventBuilding = wb.extents != Vector3.zero;
                        }
                        else
                        {
                            wb = GetWorldBounds(monument);
                        }
                        if (wb.extents == Vector3.zero) continue;
                        monumentBoundsCache[monument] = wb;
                        if (usedPreventBuilding) noObbMonuments.Add(monument);
                    }
                }
            }

            public bool TryGetMonumentBoundsForGraph(MonumentInfo monument, out Bounds wb, out bool useIsInBounds)
            {
                useIsInBounds = !noObbMonuments.Contains(monument);
                return monumentBoundsCache.TryGetValue(monument, out wb);
            }

            public bool IsInsideMonument(MonumentInfo monument, Vector3 position)
            {
                if (monument == null) return false;
                if (monument.Bounds.size != Vector3.zero && monument.IsInBounds(position)) return true;
                if (!noObbMonuments.Contains(monument) || !monumentBoundsCache.TryGetValue(monument, out var wb) || !wb.Contains(position)) return false;
                if (!monumentsPreventBuilding.TryGetValue(monument, out var colliders)) return false;
                foreach (Collider collider in colliders)
                    if (collider != null && InsideCollider(collider, position)) return true;
                return false;
            }

            private static bool InsideCollider(Collider collider, Vector3 position)
            {
                if (collider is not BoxCollider box) return collider.bounds.Contains(position);
                Vector3 local = box.transform.InverseTransformPoint(position) - box.center, half = box.size * 0.5f;
                return Mathf.Abs(local.x) <= half.x && Mathf.Abs(local.y) <= half.y && Mathf.Abs(local.z) <= half.z;
            }

            public bool HasMonument(Vector3 position)
            {
                foreach (var monument in allMonuments)
                    if (IsInsideMonument(monument, position)) return true;
                return false;
            }
            public bool TryGetNearestMonument(Vector3 position, out MonumentInfo monument)
            {
                monument = null;
                float distance = float.MaxValue;
                foreach (var m in allMonuments)
                {
                    if (!IsInsideMonument(m, position)) continue;
                    float d = Vector3.Distance(position, m.transform.position);
                    if (d < distance) { distance = d; monument = m; }
                }
                return monument != null;
            }
            private static Bounds GetWorldBounds(MonumentInfo monument)
            {
                var t = monument.transform;
                var ext = monument.Bounds.extents;
                var wb = new Bounds(t.TransformPoint(monument.Bounds.center), Vector3.zero);
                for (int sx = -1; sx <= 1; sx += 2)
                for (int sy = -1; sy <= 1; sy += 2)
                for (int sz = -1; sz <= 1; sz += 2)
                    wb.Encapsulate(t.TransformPoint(monument.Bounds.center + new Vector3(ext.x * sx, ext.y * sy, ext.z * sz)));
                return wb;
            }
        }

        public class HelperPrefabs
        {
            public static HelperPrefabs Instance;

            public readonly HashSet<string> registeredPrefabs = new HashSet<string>();

            public readonly Dictionary<string, List<GameObject>> instances = new Dictionary<string, List<GameObject>>();

            public static void OnInitPlugin()
            {
                Instance = new HelperPrefabs();
            }

            public static void OnUnloadPlugin()
            {
                Instance = null;
            }

            public bool Register(string shortname)
            {
                if (string.IsNullOrEmpty(shortname)) return false;
                if (!registeredPrefabs.Add(shortname)) return false;
                ScanInstancesFor(shortname);
                return true;
            }

            public bool Unregister(string shortname)
            {
                if (string.IsNullOrEmpty(shortname)) return false;
                if (!registeredPrefabs.Remove(shortname)) return false;
                instances.Remove(shortname);
                return true;
            }

            public void ScanAllRegistered()
            {
                instances.Clear();
                foreach (string name in registeredPrefabs) ScanInstancesFor(name);
            }

            private Dictionary<string, List<GameObject>> _staticPrefabCache;

            public void InvalidateStaticCache() => _staticPrefabCache = null;

            public void ScanInstancesFor(string shortname)
            {
                if (string.IsNullOrEmpty(shortname)) return;
                if (!instances.TryGetValue(shortname, out var list))
                {
                    list = new List<GameObject>();
                    instances[shortname] = list;
                }
                else
                {
                    list.Clear();
                }
                FindInstances(shortname, list);
            }

            public void FindInstances(string shortname, List<GameObject> result)
            {
                if (string.IsNullOrEmpty(shortname) || result == null) return;
                int before = result.Count;
                foreach (BaseNetworkable be in BaseNetworkable.serverEntities)
                {
                    if (be == null) continue;
                    if (!string.Equals(be.ShortPrefabName, shortname, StringComparison.OrdinalIgnoreCase)) continue;
                    if (be.gameObject == null) continue;
                    result.Add(be.gameObject);
                }
                if (result.Count > before) return;
                if (_staticPrefabCache == null) BuildStaticPrefabCache();
                if (_staticPrefabCache != null && _staticPrefabCache.TryGetValue(shortname, out var cached))
                {
                    result.AddRange(cached);
                }
            }

            private void BuildStaticPrefabCache()
            {
                _staticPrefabCache = new Dictionary<string, List<GameObject>>(StringComparer.OrdinalIgnoreCase);
                if (World.SpawnedPrefabs == null) return;
                foreach (var kv in World.SpawnedPrefabs)
                {
                    var hs = kv.Value;
                    if (hs == null) continue;
                    foreach (GameObject go in hs)
                    {
                        if (go == null) continue;
                        string name = go.name;
                        if (string.IsNullOrEmpty(name)) continue;
                        int paren = name.IndexOf('(');
                        if (paren > 0) name = name.Substring(0, paren).Trim();
                        int slash = name.LastIndexOf('/');
                        if (slash >= 0 && slash + 1 < name.Length) name = name.Substring(slash + 1);
                        if (name.EndsWith(".prefab", StringComparison.OrdinalIgnoreCase))
                            name = name.Substring(0, name.Length - 7);
                        if (string.IsNullOrEmpty(name)) continue;
                        if (!_staticPrefabCache.TryGetValue(name, out var bucket))
                        {
                            bucket = new List<GameObject>();
                            _staticPrefabCache[name] = bucket;
                        }
                        bucket.Add(go);
                    }
                }
            }

            public static string ExtractShortPrefabName(GameObject go)
            {
                if (go == null) return null;
                BaseEntity be = go.GetComponentInParent<BaseEntity>();
                if (be != null && !string.IsNullOrEmpty(be.ShortPrefabName)) return be.ShortPrefabName;
                Transform root = go.transform.root;
                if (root == null) return null;
                string name = root.gameObject.name;
                if (string.IsNullOrEmpty(name)) return null;
                int paren = name.IndexOf('(');
                if (paren > 0) name = name.Substring(0, paren).Trim();
                int slash = name.LastIndexOf('/');
                if (slash >= 0 && slash + 1 < name.Length) name = name.Substring(slash + 1);
                if (name.EndsWith(".prefab", System.StringComparison.OrdinalIgnoreCase))
                    name = name.Substring(0, name.Length - 7);
                return name;
            }
        }

