        public class AStarNode
        {
            public AStarNode Parent;
            public float G;
            public float H;
            public IAIPathNode Node;

            public float F => G + H;

            public AStarNode(float g, float h, AStarNode parent, IAIPathNode node)
            {
                G = g;
                H = h;
                Parent = parent;
                Node = node;
            }

            public void Update(float g, float h, AStarNode parent, IAIPathNode node)
            {
                G = g;
                H = h;
                Parent = parent;
                Node = node;
            }

            public bool Satisfies(IAIPathNode node) => Vector3.Distance(Node.Position, node.Position) <= 2f;

            public static bool operator <(AStarNode lhs, AStarNode rhs) => lhs.F < rhs.F;
            public static bool operator >(AStarNode lhs, AStarNode rhs) => lhs.F > rhs.F;
        }
        public class AStarNodeList : List<AStarNode>
        {
            private class AStarNodeComparer : IComparer<AStarNode>
            {
                int IComparer<AStarNode>.Compare(AStarNode lhs, AStarNode rhs)
                {
                    if (lhs < rhs) return -1;
                    if (lhs > rhs) return  1;
                    return 0;
                }
            }

            private readonly AStarNodeComparer comparer = new AStarNodeComparer();

            public void AStarNodeSort() => Sort(comparer);
        }

        public struct MinMax
        {
            [JsonProperty(RU ? "Минимум" : "Min")]
            private float min;

            [JsonProperty(RU ? "Максимум" : "Max")]
            private float max;

            public MinMax(float min, float max)
            {
                this.min = Mathf.Min(min, max);
                this.max = Mathf.Max(min, max);
            }

            [JsonIgnore]
            public float Min
            {
                get => Mathf.Min(min, max);
                set => min = value;
            }

            [JsonIgnore]
            public float Max
            {
                get => Mathf.Max(min, max);
                set => max = value;
            }

            public float GetRandomFloat() => Core.Random.Range(Min, Max);

            public int GetRandomInt() => Mathf.RoundToInt(GetRandomFloat());

            public float GetAverage() => (min + max) / 2;

            public bool CanChance_0_100()
            {
                return Core.Random.Range(0.001f, 100f) <= Core.Random.Range(Mathf.Clamp(Min, 0f, 100f), Mathf.Clamp(Max, 0f, 100f));
            }
            public bool CanChance_0_1()
            {
                return Core.Random.Range(0.001f, 1f) <= Core.Random.Range(Mathf.Clamp(Min, 0f, 1f), Mathf.Clamp(Max, 0f, 1f));
            }

            public override string ToString()
            {
                return $"{Min} - {Max}";
            }

            public static implicit operator MinMax(float value) => new MinMax(value, value);
        }
    }
