    #region Saved NavMesh - сохранённые навмеши монументов и префабов
    public partial class NPCsController
    {
        public static class HelperNavGraph
        {
            public const float GridStep = 1f;

            private const float LinkedEntitySearchRadius = 1.5f;

            private static readonly BaseEntity[] _linkedEntityBuffer = new BaseEntity[64];

            public static string GetKey(MonumentInfo monument)
            {
                var name = monument != null ? monument.name ?? string.Empty : string.Empty;
                int dot = name.LastIndexOf('.');
                if (dot > 0) name = name.Substring(0, dot);
                int slash = name.LastIndexOf('/');
                if (slash >= 0) name = name.Substring(slash + 1);
                return name;
            }

            public static int CountInstancesForKey(string key)
            {
                if (string.IsNullOrEmpty(key) || HelperMonuments.Instance == null) return 0;
                int count = 0;
                foreach (var monument in HelperMonuments.Instance.allMonuments)
                    if (monument != null && GetKey(monument) == key) count++;
                return count;
            }

            public class NavGraph
            {
                private const int ChunkCells = 8;
                private static readonly float ChunkSize = ChunkCells * GridStep;
                private static readonly int _bridgeAreaMask = 1 << UnityEngine.AI.NavMesh.GetAreaFromName("Walkable");
                private const float BridgeSampleRadius = 1f;

                private readonly List<IAIPathNode> _nodes;
                private readonly Dictionary<long, List<NavGraphNode>> _chunks;
                private List<IAIPathNode> _bridgeNodes;
                public volatile bool BridgesReady;

                public IReadOnlyList<IAIPathNode> Nodes => _nodes;
                public IReadOnlyList<IAIPathNode> BridgeNodes => _bridgeNodes;
                public int Count => _nodes.Count;

                public NavGraph(List<NavGraphNode> nodes)
                {
                    _nodes = new List<IAIPathNode>(nodes.Count);
                    _chunks = new Dictionary<long, List<NavGraphNode>>(nodes.Count / (ChunkCells * ChunkCells) + 1);
                    foreach (var node in nodes)
                    {
                        _nodes.Add(node);
                        long ck = ChunkKey(node.Position);
                        if (!_chunks.TryGetValue(ck, out var bucket))
                        {
                            bucket = new List<NavGraphNode>();
                            _chunks[ck] = bucket;
                        }
                        bucket.Add(node);
                    }
                }

                public void GetNodesInRadius(Vector3 pos, float radius, List<NavGraphNode> result)
                {
                    float rsqr = radius * radius;
                    int cx0 = ToChunk(pos.x - radius), cx1 = ToChunk(pos.x + radius);
                    int cz0 = ToChunk(pos.z - radius), cz1 = ToChunk(pos.z + radius);
                    for (int cx = cx0; cx <= cx1; cx++)
                    for (int cz = cz0; cz <= cz1; cz++)
                    {
                        if (!_chunks.TryGetValue(ChunkKey(cx, cz), out var bucket)) continue;
                        foreach (var node in bucket)
                            if ((node.Position - pos).sqrMagnitude <= rsqr)
                                result.Add(node);
                    }
                }

                public bool TryGetNearestNode(Vector3 pos, float radius, out NavGraphNode result, Func<Vector3, IAIPathNode, bool> canNode)
                {
                    result = null;
                    float rsqr = radius * radius;
                    float dist = rsqr;
                    int cx0 = ToChunk(pos.x - radius), cx1 = ToChunk(pos.x + radius);
                    int cz0 = ToChunk(pos.z - radius), cz1 = ToChunk(pos.z + radius);
                    for (int cx = cx0; cx <= cx1; cx++)
                    for (int cz = cz0; cz <= cz1; cz++)
                    {
                        if (!_chunks.TryGetValue(ChunkKey(cx, cz), out var bucket)) continue;
                        foreach (var node in bucket)
                        {
                            float num = (node.Position - pos).sqrMagnitude;
                            if (num <= rsqr && num < dist && (canNode == null || canNode(pos, node)))
                            {
                                result = node;
                                dist = num;
                            }
                        }
                    }
                    return result != null;
                }

                public void EnsureBridgesSync()
                {
                    if (BridgesReady) return;
                    var list = new List<IAIPathNode>(_nodes.Count / 4);
                    for (int i = 0; i < _nodes.Count; i++)
                    {
                        var n = _nodes[i];
                        if (n == null) continue;
                        if (n.IsNavMesh || (ShouldSampleForBridge(n) && Rust.Ai.Gen2.RustNavMeshHelpers.SamplePosition(n.Position, out _, BridgeSampleRadius, _bridgeAreaMask)))
                            list.Add(n);
                    }
                    _bridgeNodes = list;
                    BridgesReady = true;
                }

                public void SeedBridgesIncremental(NavGraph oldGraph,
                    Dictionary<NavGraphNode, NavGraphNode> cloneMap, HashSet<NavGraphNode> relinkSet)
                {
                    var list = new List<IAIPathNode>();
                    var oldBridges = oldGraph?.BridgeNodes;
                    if (oldBridges != null)
                        for (int i = 0; i < oldBridges.Count; i++)
                        {
                            var n = oldBridges[i] as NavGraphNode;
                            if (n == null) continue;
                            if (!cloneMap.TryGetValue(n, out var clone)) continue;
                            if (relinkSet.Contains(clone)) continue;
                            list.Add(clone);
                        }
                    foreach (var n in relinkSet)
                        if (n.IsNavMesh || (ShouldSampleForBridge(n) && Rust.Ai.Gen2.RustNavMeshHelpers.SamplePosition(n.Position, out _, BridgeSampleRadius, _bridgeAreaMask)))
                            list.Add(n);
                    _bridgeNodes = list;
                    BridgesReady = true;
                }

                private static bool ShouldSampleForBridge(IAIPathNode n)
                {
                    var mn = n as NavGraphNode;
                    return mn == null || mn.Role == NodeRole.Unknown || mn.Role == NodeRole.Street;
                }

                private static int ToChunk(float v) => Mathf.FloorToInt(v / ChunkSize);
                private static long ChunkKey(Vector3 pos) => ChunkKey(ToChunk(pos.x), ToChunk(pos.z));
                private static long ChunkKey(int cx, int cz) => ((long)cx << 32) | (uint)cz;
            }

            public class NavGraphZone : FacepunchBehaviour
            {
                public string Key;
                public NavGraph Graph;
                private BoxCollider _box;
                public BoxCollider Box => _box != null ? _box : (_box = GetComponent<BoxCollider>());

                public bool Contains(Vector3 worldPos)
                {
                    var bc = Box;
                    if (bc == null) return false;
                    Vector3 local = bc.transform.InverseTransformPoint(worldPos) - bc.center;
                    Vector3 half = bc.size * 0.5f;
                    return Mathf.Abs(local.x) <= half.x
                        && Mathf.Abs(local.y) <= half.y
                        && Mathf.Abs(local.z) <= half.z;
                }

                private void OnTriggerEnter(Collider other)
                {
                    if (other == null) return;
                    other.gameObject.SendMessageUpwards("OnEnterNavZone", this, SendMessageOptions.DontRequireReceiver);
                }

                private void OnTriggerExit(Collider other)
                {
                    if (other == null) return;
                    other.gameObject.SendMessageUpwards("OnLeaveNavZone", this, SendMessageOptions.DontRequireReceiver);
                }
            }

            public static void SyncBotsAlreadyInside(NavGraphZone zone)
            {
                if (zone == null) return;
                var boxT = zone.transform;
                var box = zone.Box;
                if (box == null) return;
                var halfExtents = box.size * 0.5f;
                var hits = Physics.OverlapBox(boxT.position, halfExtents, boxT.rotation, ~0, QueryTriggerInteraction.Collide);
                for (int i = 0; i < hits.Length; i++)
                {
                    var bot = hits[i].gameObject.GetComponentInParent<BaseCustomNpc>();
                    if (bot != null) bot.gameObject.SendMessage("OnEnterNavZone", zone, SendMessageOptions.DontRequireReceiver);
                }
            }

            public sealed class NavGraphNode : IAIPathNode
            {
                private readonly List<PathEdge> _edges = new List<PathEdge>();
                public Vector3 Position { get; }
                public NodeHint Hint => NodeHint.None;
                public bool Straightaway => false;

                public NavGraphNode(Vector3 position)
                {
                    Position = position;
                }

                public IEnumerable<IAIPathNode> Linked => System.Array.Empty<IAIPathNode>();
                public IEnumerable<PathEdge> Edges => _edges;
                public bool IsValid() => true;

                public Door LinkedDoor { get; private set; }
                public PressButton LinkedButton { get; private set; }
                public CardReader LinkedReader { get; private set; }
                public Collider LinkedLadderTrigger { get; private set; }

                public bool IsWaypointOnly { get; set; }
                public bool IsNavMesh { get; set; }
                public NodeRole Role { get; set; }
                public bool IsNoAutoLink { get; set; }

                public void BindLinkedEntity(string type, BaseEntity ent)
                {
                    if (string.IsNullOrEmpty(type) || ent == null) return;
                    switch (type.ToLowerInvariant())
                    {
                        case "door":   LinkedDoor   = ent as Door;        break;
                        case "button": LinkedButton = ent as PressButton; break;
                        case "reader": LinkedReader = ent as CardReader;  break;
                    }
                }

                public void BindLadderTrigger(Collider c) { LinkedLadderTrigger = c; }

                public void AddEdge(PathEdge edge)
                {
                    if (edge.Target == null) return;
                    _edges.Add(edge);
                }

                public void RemoveEdgesTo(HashSet<IAIPathNode> targets)
                {
                    if (targets == null || targets.Count == 0) return;
                    _edges.RemoveAll(e => targets.Contains(e.Target));
                }

                public void AddLink(IAIPathNode link)
                {
                    if (link == null) return;
                    _edges.Add(new PathEdge(link, NodeHint.None, null, Vector3.Distance(Position, link.Position)));
                }
            }

