            }

            public static Component FindLinkedObject(string typeLower, Vector3 worldPos)
            {
                if (string.IsNullOrEmpty(typeLower)) return null;
                if (typeLower == "ladder")
                {
                    var hits = Physics.OverlapSphere(worldPos, LinkedEntitySearchRadius, ~0, QueryTriggerInteraction.Collide);
                    Collider best = null;
                    float bestSqr = float.MaxValue;
                    for (int i = 0; i < hits.Length; i++)
                    {
                        Collider c = hits[i];
                        if (c == null) continue;
                        string nm = c.gameObject.name ?? string.Empty;
                        if (c.GetComponent<TriggerLadder>() == null && nm.IndexOf("Ladder", StringComparison.OrdinalIgnoreCase) < 0) continue;
                        float sqr = (c.transform.position - worldPos).sqrMagnitude;
                        if (sqr < bestSqr) { bestSqr = sqr; best = c; }
                    }
                    return best;
                }

                var hitsEnt = Physics.OverlapSphere(worldPos, LinkedEntitySearchRadius, ~0, QueryTriggerInteraction.Ignore);
                BaseEntity bestEnt = null;
                float bestEntSqr = float.MaxValue;
                for (int i = 0; i < hitsEnt.Length; i++)
                {
                    Collider c = hitsEnt[i];
                    if (c == null) continue;
                    BaseEntity e = c.gameObject.ToBaseEntity();
                    if (!e.IsValid())
                    {
                        e = c.gameObject.GetComponentInParent<BaseEntity>();
                        if (!e.IsValid()) continue;
                    }
                    if (!MatchesLinkedType(typeLower, e)) continue;
                    float sqr = (e.transform.position - worldPos).sqrMagnitude;
                    if (sqr < bestEntSqr) { bestEntSqr = sqr; bestEnt = e; }
                }
                if (bestEnt != null) return bestEnt;

                int count = BaseEntity.Query.Server.GetInSphere(worldPos, LinkedEntitySearchRadius, _linkedEntityBuffer, null);
                for (int i = 0; i < count; i++)
                {
                    BaseEntity e = _linkedEntityBuffer[i];
                    _linkedEntityBuffer[i] = null;
                    if (!e.IsValid() || !MatchesLinkedType(typeLower, e)) continue;
                    float sqr = (e.transform.position - worldPos).sqrMagnitude;
                    if (sqr < bestEntSqr) { bestEntSqr = sqr; bestEnt = e; }
                }
                return bestEnt;
            }

            private static bool MatchesLinkedType(string typeLower, BaseEntity e) => typeLower switch
            {
                "door"   => e is Door,
                "button" => e is PressButton,
                "reader" => e is CardReader,
                _ => false,
            };
        }

