            #region Жизненный цикл и реестр

            public static void OnInitPlugin() => Instance = new HelperSavedNavMesh();

            public static void OnUnloadPlugin()
            {
                Instance?.UnregisterAll();
                Instance = null;
                _routeMarks.Clear();
            }

            public IEnumerable<SavedNavMesh> All => _meshes.Values;

            public bool TryGet(string key, out SavedNavMesh mesh)
            {
                mesh = null;
                return !string.IsNullOrEmpty(key) && _meshes.TryGetValue(key, out mesh) && mesh.IsReady;
            }

            public SavedNavMesh Register(string key, bool isPrefab, IntPtr handle, NavMeshFile description)
            {
                if (string.IsNullOrEmpty(key)) return null;
                if (_meshes.TryGetValue(key, out var old))
                {
                    if (old.Handle == handle) old.DetachHandle();
                    old.Dispose();
                }
                description ??= new NavMeshFile();
                description.Key = key;
                description.Kind = isPrefab ? KindPrefab : KindMonument;
                var mesh = new SavedNavMesh(key, isPrefab, handle, description);
                _meshes[key] = mesh;
                mesh.FindInstances();
                return mesh;
            }

            public SavedNavMesh RegisterGraph(string key, bool isPrefab, NavMeshFile description)
                => Register(key, isPrefab, IntPtr.Zero, description);

            public bool Unregister(string key)
            {
                if (string.IsNullOrEmpty(key) || !_meshes.TryGetValue(key, out var mesh)) return false;
                mesh.Dispose();
                _meshes.Remove(key);
                return true;
            }

            public void UnregisterAll()
            {
                foreach (var mesh in _meshes.Values) mesh.Dispose();
                _meshes.Clear();
            }

            public bool TryGetInstanceAt(Vector3 world, out SavedNavInstance instance, float margin = 0f)
            {
                instance = null;
                float bestArea = float.MaxValue;
                foreach (var mesh in _meshes.Values)
                {
                    if (!mesh.IsReady) continue;
                    if (!mesh.IsValid && mesh.Nodes.Count == 0) continue;
                    float area = mesh.LocalBounds.size.x * mesh.LocalBounds.size.z;
                    if (area >= bestArea) continue;
                    for (int i = 0; i < mesh.Instances.Count; i++)
                    {
                        var inst = mesh.Instances[i];
                        if (!inst.IsAlive || !inst.Contains(world, margin)) continue;
                        instance = inst;
                        bestArea = area;
                        break;
                    }
                }
                return instance != null;
            }

            #endregion

            #region Диск

            public static string GetDirectory(bool isPrefab) => System.IO.Path.Combine(Interface.Oxide.DataDirectory,
                (isPrefab ? PrefabFolder : MonumentFolder).Replace('/', System.IO.Path.DirectorySeparatorChar));
            public static string GetNativePath(string key, bool isPrefab) => System.IO.Path.Combine(GetDirectory(isPrefab), key + ".navmesh");
            public static string GetDescriptionPath(string key, bool isPrefab) => System.IO.Path.Combine(GetDirectory(isPrefab), key + ".json");

            public sealed class DiskLoadSummary
            {
                public int Total;

                public int Loaded;

                public int WithNative;

                public int NoInstances;

                public readonly List<(string Key, bool IsPrefab, string Error)> Failures = new List<(string Key, bool IsPrefab, string Error)>();

                public int Failed => Failures.Count;
            }

            public const int DiskLoadAlreadyRunning = -1;

            public bool IsDiskLoading => _diskLoading;
            private bool _diskLoading;

            public int LoadAllFromDisk(Action<DiskLoadSummary> onDone = null)
            {
                if (_diskLoading) return DiskLoadAlreadyRunning;
                var queue = new Queue<(string Key, bool IsPrefab)>();
                EnqueueFolder(queue, false);
                EnqueueFolder(queue, true);
                if (queue.Count == 0) return 0;

                var plugin = NPCsController.Instance;
                if (plugin == null) return 0;
                var summary = new DiskLoadSummary { Total = queue.Count };
                _diskLoading = true;
                Timer loadTimer = null;
                loadTimer = plugin.timer.Every(0.2f, () =>
                {
                    if (Instance != this) { _diskLoading = false; loadTimer?.Destroy(); return; }
                    if (queue.Count == 0)
                    {
                        loadTimer?.Destroy();
                        _diskLoading = false;
                        onDone?.Invoke(summary);
                        return;
                    }
                    var item = queue.Dequeue();
                    if (TryLoadFromDisk(item.Key, item.IsPrefab, out string error, out bool noInstances))
                    {
                        summary.Loaded++;
                        if (TryGet(item.Key, out var loadedMesh) && loadedMesh.IsValid) summary.WithNative++;
                    }
                    else if (noInstances) summary.NoInstances++;
                    else
                    {
                        summary.Failures.Add((item.Key, item.IsPrefab, error));
                        Debug.LogWarning<HelperSavedNavMesh>("NavMesh [{0}] not loaded: {1}", item.Key, error);
                    }
                });
                return summary.Total;
            }

            private static void EnqueueFolder(Queue<(string Key, bool IsPrefab)> queue, bool isPrefab)
            {
                string dir = GetDirectory(isPrefab);
                if (!System.IO.Directory.Exists(dir)) return;
                try
                {
                    foreach (string file in System.IO.Directory.GetFiles(dir, "*.json"))
                        queue.Enqueue((System.IO.Path.GetFileNameWithoutExtension(file), isPrefab));
                }
                catch (Exception ex)
                {
                    Debug.LogError<HelperSavedNavMesh>("Scan [{0}] failed: {1}", dir, ex.Message);
                }
            }

            public bool TryLoadFromDisk(string key, bool isPrefab, out string error) => TryLoadFromDisk(key, isPrefab, out error, out _);

            public bool TryLoadFromDisk(string key, bool isPrefab, out string error, out bool noInstances)
            {
                error = null;
                noInstances = false;
                string descriptionPath = GetDescriptionPath(key, isPrefab);
                if (!System.IO.File.Exists(descriptionPath)) { error = "no description (.json): it holds the transition graph"; return false; }

                NavMeshFile description;
                try { description = JsonConvert.DeserializeObject<NavMeshFile>(System.IO.File.ReadAllText(descriptionPath)); }
                catch (Exception ex) { error = "description is unreadable: " + ex.Message; return false; }
                if (description == null) { error = "the description is empty"; return false; }
                if (description.Format > FileFormat) { error = $"description format {description.Format} is newer than supported {FileFormat}"; return false; }

                if (CountInstances(key, isPrefab) == 0) { noInstances = true; error = "no instances on the map"; return false; }

                string nativePath = GetNativePath(key, isPrefab);
                IntPtr handle = IntPtr.Zero;
                if (System.IO.File.Exists(nativePath))
                {
                    if (description.Build == null)
                        Debug.LogWarning<HelperSavedNavMesh>("NavMesh [{0}]: {1}.navmesh is present but the description has no build info - taking the graph only, the surface comes from the game navmesh", key, key);
                    else
                    {
                        try
                        {
                            handle = Rust.Ai.Gen2.Nav.RecastWrapper.LoadNavMesh(nativePath, out IntPtr blob, out _, 0);
                            if (blob != IntPtr.Zero) Rust.Ai.Gen2.Nav.RecastWrapper.FreeManagedBlob(blob);
                        }
                        catch (Exception ex)
                        {
                            handle = IntPtr.Zero;
                            Debug.LogWarning<HelperSavedNavMesh>("LoadNavMesh [{0}]: {1}", key, ex.Message);
                        }
                        if (handle == IntPtr.Zero)
                            Debug.LogWarning<HelperSavedNavMesh>("NavMesh [{0}] failed to load - the key works as a graph over the game navmesh", key);
                    }
                }

                if (handle != IntPtr.Zero) Register(key, isPrefab, handle, description);
                else RegisterGraph(key, isPrefab, description);
                return true;
            }

            public static int CountInstances(string key, bool isPrefab)
            {
                if (string.IsNullOrEmpty(key)) return 0;
                if (isPrefab)
                {
                    if (HelperPrefabs.Instance == null) return 0;
                    var roots = new List<GameObject>();
                    HelperPrefabs.Instance.FindInstances(key, roots);
                    return roots.Count;
                }
                if (HelperMonuments.Instance == null) return 0;
                int count = 0;
                foreach (var monument in HelperMonuments.Instance.allMonuments)
                    if (monument != null && string.Equals(HelperNavGraph.GetKey(monument), key, StringComparison.OrdinalIgnoreCase)) count++;
                return count;
            }

            public static bool WriteNative(string key, bool isPrefab, IntPtr handle, in Rust.Ai.Gen2.Nav.NavMeshBuildParams buildParams,
                Vector3 localMin, Vector3 localMax, out string error)
            {
                error = null;
                if (handle == IntPtr.Zero) { error = "navmesh is not built"; return false; }
                try
                {
                    System.IO.Directory.CreateDirectory(GetDirectory(isPrefab));
                    if (!Rust.Ai.Gen2.Nav.RecastWrapper.SaveNavMesh(GetNativePath(key, isPrefab), handle, in buildParams, in localMin, in localMax,
                            IntPtr.Zero, 0, Rust.Ai.Gen2.Nav.NavMeshConstants.NavSaveCompressLZ4, 1))
                    {
                        error = "SaveNavMesh returned false";
                        return false;
                    }
                    return true;
                }
                catch (Exception ex) { error = ex.Message; return false; }
            }

            public static bool WriteDescription(NavMeshFile description, bool isPrefab, out string error)
            {
                error = null;
                if (description == null || string.IsNullOrEmpty(description.Key)) { error = "empty description"; return false; }
                try
                {
                    System.IO.Directory.CreateDirectory(GetDirectory(isPrefab));
                    description.Kind = isPrefab ? KindPrefab : KindMonument;
                    description.Format = FileFormat;
                    System.IO.File.WriteAllText(GetDescriptionPath(description.Key, isPrefab),
                        JsonConvert.SerializeObject(description, Newtonsoft.Json.Formatting.Indented));
                    return true;
                }
                catch (Exception ex) { error = ex.Message; return false; }
            }

            #endregion

            #region Общие расчёты

            public static float HintCost(NodeHint hint, float length)
            {
                float mult = 1f;
                if ((hint & NodeHint.Jump) != 0) mult = 2.5f;
                else if ((hint & NodeHint.Climb) != 0) mult = 2f;
                else if ((hint & (NodeHint.OpenDoor | NodeHint.CloseDoor)) != 0) mult = 1.5f;
                float cost = Mathf.Max(0.05f, length) * mult;
                if ((hint & NodeHint.OpenDoor) != 0) cost += DoorCostPenalty;
                return cost;
            }

            public static float PathLength(IReadOnlyList<Vector3> points)
            {
                float length = 0f;
                if (points == null) return length;
                for (int i = 1; i < points.Count; i++) length += Vector3.Distance(points[i - 1], points[i]);
                return length;
            }

            public string Describe()
            {
                if (_meshes.Count == 0) return RU ? "Разметки монументов не загружено." : "No monument markup is loaded.";
                int own = 0;
                foreach (var m in _meshes.Values) if (m.IsValid) own++;
                var sb = new System.Text.StringBuilder(RU
                    ? $"Размеченных целей: {_meshes.Count}, из них со своим навмешем {own}; у остальных поверхность даёт штатный навмеш игры Gen2\n"
                    : $"Marked targets: {_meshes.Count}, {own} with an own navmesh; the rest take the surface from the game's Gen2 navmesh\n");
                foreach (var mesh in _meshes.Values)
                {
                    int edges = 0;
                    for (int i = 0; i < mesh.Nodes.Count; i++) edges += mesh.Nodes[i].Out?.Count ?? 0;
                    sb.Append($"  {mesh.Key} ({mesh.Description.Kind}, {mesh.SurfaceName}): ")
                      .Append(RU
                          ? $"экземпляров {mesh.Instances.Count}, узлов {mesh.Nodes.Count}, рёбер {edges}, дверных проёмов {mesh.GateCount}"
                          : $"instances {mesh.Instances.Count}, nodes {mesh.Nodes.Count}, edges {edges}, door gates {mesh.GateCount}");
                    var b = mesh.Description.Build;
                    if (mesh.IsValid && b != null)
                        sb.Append(RU
                            ? $", тайлов {b.TilesBuilt} из {b.TilesX * b.TilesZ}, полигонов {b.Polys}, сборка {b.BuildId}"
                            : $", tiles {b.TilesBuilt} of {b.TilesX * b.TilesZ}, polys {b.Polys}, build {b.BuildId}");
                    int unbound = mesh.CountUnbound();
                    if (unbound > 0) sb.Append(RU ? $", не найдено привязок {unbound}" : $", unbound links {unbound}");
                    for (int i = 0; i < mesh.Instances.Count && i < 3; i++)
                    {
                        var instance = mesh.Instances[i];
                        if (!instance.IsAlive) continue;
                        Vector3 position = instance.Root.position;
                        sb.Append($"\n    #{instance.Index} ({position.x:0.0} {position.y:0.0} {position.z:0.0})");
                    }
                    sb.Append('\n');
                }
                return sb.ToString().TrimEnd();
            }

            public string DescribePoint(Vector3 world)
            {
                if (!TryGetInstanceAt(world, out var inst)) return RU ? "Точка не попадает ни в одну размеченную область монумента." : "The point is outside every mapped monument area.";
                Vector3 local = inst.WorldToLocal(world);
                var sb = new System.Text.StringBuilder($"[{inst.Mesh.Key}] #{inst.Index} ({inst.Mesh.Description.Kind}, {inst.Mesh.SurfaceName}), ");
                sb.Append(RU ? $"в осях ({local.x:0.00} {local.y:0.00} {local.z:0.00})" : $"local ({local.x:0.00} {local.y:0.00} {local.z:0.00})");
                if (inst.TrySample(world, out Vector3 hit))
                    sb.Append(RU ? $"; поверхность в {Vector3.Distance(hit, world):0.00} м" : $"; surface at {Vector3.Distance(hit, world):0.00} m");
                else
                    sb.Append(RU ? "; поверхности рядом нет" : "; no surface nearby");

                SavedNavNode nearest = null;
                float bestSqr = float.MaxValue;
                for (int i = 0; i < inst.Nodes.Length; i++)
                {
                    float sqr = (inst.Nodes[i].Position - world).sqrMagnitude;
                    if (sqr < bestSqr) { bestSqr = sqr; nearest = inst.Nodes[i]; }
                }
                if (nearest != null)
                    sb.Append(RU
                        ? $"; ближайший узел {nearest.Id} в {Mathf.Sqrt(bestSqr):0.0} м ({nearest.Auto ?? "руками"}, {(nearest.OnMesh ? "на навмеше" : nearest.IsNavMesh ? "на навмеше игры" : "вне навмеша")}, рёбер {nearest.EdgeList.Count})"
                        : $"; nearest node {nearest.Id} at {Mathf.Sqrt(bestSqr):0.0} m ({nearest.Auto ?? "manual"}, {(nearest.OnMesh ? "on navmesh" : nearest.IsNavMesh ? "on game navmesh" : "off navmesh")}, edges {nearest.EdgeList.Count})");
                return sb.ToString();
            }

            public bool CrossesGate(List<Vector3> path, out Vector3 gateWorld)
            {
                gateWorld = Vector3.zero;
                if (path == null || path.Count < 2) return false;
                var pathBounds = new Bounds(path[0], Vector3.zero);
                for (int i = 1; i < path.Count; i++) pathBounds.Encapsulate(path[i]);
                foreach (var mesh in _meshes.Values)
                {
                    if (!mesh.IsReady || mesh.IsValid || mesh.GateCount == 0) continue;
                    float radius = mesh.LocalBounds.extents.magnitude + GateSearchMargin;
                    for (int i = 0; i < mesh.Instances.Count; i++)
                    {
                        var instance = mesh.Instances[i];
                        if (!instance.IsAlive) continue;
                        if (pathBounds.SqrDistance(instance.LocalToWorld(mesh.LocalBounds.center)) > radius * radius) continue;
                        if (instance.GateCut(path, out gateWorld) >= 0) return true;
                    }
                }
                return false;
            }

            #endregion

            public readonly struct RouteHop
            {
                public readonly int From;
                public readonly int To;
                public readonly NodeHint Hint;
                public readonly bool Surface;
                public readonly float Cost;

                public RouteHop(int from, int to, NodeHint hint, bool surface, float cost)
                {
                    From = from;
                    To = to;
                    Hint = hint;
                    Surface = surface;
                    Cost = cost;
                }
            }

            public static bool TrySampleMonumentSurface(Vector3 world, Vector3 extents, out Vector3 hitWorld)
            {
                var store = Instance;
                if (store != null && store.TryGetInstanceAt(world, out var instance) && instance.IsAlive)
                    return instance.TrySample(world, extents, out hitWorld);
                return NavSurface.SampleWorld(world, extents, out hitWorld);
            }

            public sealed class NavSurface
            {
                private readonly Dictionary<long, float> _cost = new Dictionary<long, float>();

                internal void ResetCache() => _cost.Clear();
                internal bool TryGetCost(long key, out float cost) => _cost.TryGetValue(key, out cost);
                internal void SetCost(long key, float cost) => _cost[key] = cost;

                private readonly SavedNavInstance _instance;

                private static Rust.Ai.Gen2.RustNavMeshPath _path;
                private static readonly List<Vector3> _world = new List<Vector3>();

                internal NavSurface(SavedNavInstance instance) { _instance = instance; }

                public bool OwnMesh => _instance != null && _instance.Mesh.IsValid;

                public bool Ready => _instance != null && _instance.Root != null && _instance.Mesh.IsReady;

                public bool Sample(Vector3 local, Vector3 extents, out Vector3 hitLocal)
                {
                    hitLocal = local;
                    if (_instance == null) return false;
                    if (OwnMesh) return _instance.Mesh.SampleLocal(local, extents, out hitLocal, out _);
                    if (!SampleWorld(_instance.LocalToWorld(local), extents, out Vector3 hitWorld)) return false;
                    hitLocal = _instance.WorldToLocal(hitWorld);
                    return true;
                }

                private const float GameSurfaceSnapMin = 0.75f;

                internal static bool SampleWorld(Vector3 world, Vector3 extents, out Vector3 hitWorld)
                {
                    hitWorld = world;
                    float flat = Mathf.Max(Mathf.Max(extents.x, extents.z), GameSurfaceSnapMin);
                    float radius = Mathf.Max(flat, extents.y);
                    if (!Rust.Ai.Gen2.RustNavMeshHelpers.SamplePosition(world, out UnityEngine.AI.NavMeshHit hit, radius, WalkableMask)) return false;
                    Vector3 delta = hit.position - world;
                    if (Mathf.Abs(delta.y) > extents.y) return false;
                    if (delta.x * delta.x + delta.z * delta.z > flat * flat) return false;
                    hitWorld = hit.position;
                    return true;
                }

                public NavPathResult FindPath(Vector3 fromLocal, Vector3 toLocal, List<Vector3> cornersLocal, Vector3 extents)
                {
                    cornersLocal?.Clear();
                    if (_instance == null) return NavPathResult.None;
                    if (OwnMesh) return _instance.Mesh.FindPathLocal(fromLocal, toLocal, cornersLocal, extents);
                    if (!SampleWorld(_instance.LocalToWorld(fromLocal), extents, out Vector3 startWorld)) return NavPathResult.StartOffMesh;
                    if (!SampleWorld(_instance.LocalToWorld(toLocal), extents, out Vector3 endWorld)) return NavPathResult.EndOffMesh;

                    _path ??= new Rust.Ai.Gen2.RustNavMeshPath();
                    if (!Rust.Ai.Gen2.RustNavMeshHelpers.CalculatePath(startWorld, endWorld, WalkableMask, _path)) return NavPathResult.None;
                    if (_path.status == UnityEngine.AI.NavMeshPathStatus.PathInvalid) return NavPathResult.None;
                    _world.Clear();
                    PluginExtension.AddCornersWorld(_path, startWorld, _world);
                    if (_world.Count == 0) return NavPathResult.None;

                    int keep = _instance.GateCut(_world, out _);
                    bool blocked = keep >= 0;
                    int count = blocked ? keep : _world.Count;
                    if (cornersLocal != null)
                        for (int i = 0; i < count; i++) cornersLocal.Add(_instance.WorldToLocal(_world[i]));
                    if (blocked) return NavPathResult.Partial;
                    bool partial = _path.status != UnityEngine.AI.NavMeshPathStatus.PathComplete
                                   || (_world[_world.Count - 1] - endWorld).sqrMagnitude > CompleteGap * CompleteGap;
                    return partial ? NavPathResult.Partial : NavPathResult.Complete;
                }
            }

            public sealed class SavedNavMesh
            {
                public readonly string Key;
                public readonly bool IsPrefab;
                public IntPtr Handle { get; private set; }
                public NavMeshFile Description { get; private set; }
                public Bounds LocalBounds { get; private set; }
                public readonly List<SavedNavInstance> Instances = new List<SavedNavInstance>();

                public bool IsValid => Handle != IntPtr.Zero;
                public bool IsReady => !_disposed;
                public string SurfaceName => IsValid
                    ? "own navmesh"
                    : "game navmesh";
                public IReadOnlyList<NavMeshFileNode> Nodes => _nodes;
                public int GateCount => _gateLocal.Length;
                public IReadOnlyList<Vector3> GateLocal => _gateLocal;

                private NavMeshFileNode[] _nodes = Array.Empty<NavMeshFileNode>();
                private Vector3[] _nodeLocal = Array.Empty<Vector3>();
                private Vector3[] _gateLocal = Array.Empty<Vector3>();
                private readonly Dictionary<int, int> _idToIndex = new Dictionary<int, int>();
                private int[][] _nearest;
                private readonly List<Vector3> _probe = new List<Vector3>();
                private bool _disposed;

                internal SavedNavMesh(string key, bool isPrefab, IntPtr handle, NavMeshFile description)
                {
                    Key = key;
                    IsPrefab = isPrefab;
                    Handle = handle;
                    SetDescription(description);
                }

                public void SetDescription(NavMeshFile description)
                {
                    Description = description ?? new NavMeshFile { Key = Key };
                    var build = Description.Build;
                    if (build != null)
                    {
                        Vector3 min = build.LocalMin.ToVector(), max = build.LocalMax.ToVector();
                        LocalBounds = new Bounds((min + max) * 0.5f, max - min);
                    }

                    var list = new List<NavMeshFileNode>();
                    _idToIndex.Clear();
                    if (Description.Nodes != null)
                    {
                        for (int i = 0; i < Description.Nodes.Count; i++)
                        {
                            var node = Description.Nodes[i];
                            if (node == null) continue;
                            if (_idToIndex.ContainsKey(node.Id))
                            {
                                Debug.LogWarning<HelperSavedNavMesh>("NavMesh [{0}]: duplicate node id {1} skipped", Key, node.Id);
                                continue;
                            }
                            _idToIndex[node.Id] = list.Count;
                            list.Add(node);
                        }
                    }
                    _nodes = list.ToArray();
                    _nodeLocal = new Vector3[_nodes.Length];
                    for (int i = 0; i < _nodes.Length; i++) _nodeLocal[i] = _nodes[i].LocalPos.ToVector();
                    BuildGates();
                    if (build == null) LocalBounds = BoundsFromNodes();

                    ClearSurfaceCaches();
                    _nearest = null;
                    for (int i = 0; i < Instances.Count; i++) Instances[i].BuildNodes();
                }

                private const float NodeBoundsMargin = 8f;

                private Bounds BoundsFromNodes()
                {
                    if (_nodeLocal.Length == 0) return new Bounds(Vector3.zero, Vector3.zero);
                    var bounds = new Bounds(_nodeLocal[0], Vector3.zero);
                    for (int i = 1; i < _nodeLocal.Length; i++) bounds.Encapsulate(_nodeLocal[i]);
                    bounds.Expand(NodeBoundsMargin * 2f);
                    return bounds;
                }

                private void BuildGates()
                {
                    var gates = new List<Vector3>();
                    for (int i = 0; i < _nodes.Length; i++)
                    {
                        var outs = _nodes[i].Out;
                        if (outs == null) continue;
                        for (int k = 0; k < outs.Count; k++)
                        {
                            var link = outs[k];
                            if (link == null || ((NodeHint)link.Hint & NodeHint.OpenDoor) == 0) continue;
                            if (!_idToIndex.TryGetValue(link.To, out int gate)) continue;
                            Vector3 point = _nodeLocal[gate];
                            bool known = false;
                            for (int g = 0; g < gates.Count; g++)
                                if ((gates[g] - point).sqrMagnitude < 0.01f) { known = true; break; }
                            if (!known) gates.Add(point);
                        }
                    }
                    _gateLocal = gates.ToArray();
                }

                private void ClearSurfaceCaches()
                {
                    for (int i = 0; i < Instances.Count; i++) Instances[i].Surface.ResetCache();
                }

                public void FindInstances()
                {
                    Instances.Clear();
                    if (IsPrefab)
                    {
                        var roots = new List<GameObject>();
                        HelperPrefabs.Instance?.FindInstances(Key, roots);
                        for (int i = 0; i < roots.Count; i++)
                            if (roots[i] != null) Instances.Add(new SavedNavInstance(this, roots[i].transform, null, Instances.Count));
                    }
                    else if (HelperMonuments.Instance != null)
                    {
                        foreach (var monument in HelperMonuments.Instance.allMonuments)
                            if (monument != null && string.Equals(HelperNavGraph.GetKey(monument), Key, StringComparison.OrdinalIgnoreCase))
                                Instances.Add(new SavedNavInstance(this, monument.transform, monument, Instances.Count));
                    }
                    for (int i = 0; i < Instances.Count; i++) Instances[i].BuildNodes();
                }

                public int CountUnbound()
                {
                    int count = 0;
                    for (int i = 0; i < Instances.Count; i++) count += Instances[i].UnboundEntities;
                    return count;
                }

                public bool TryGetIndex(int id, out int index) => _idToIndex.TryGetValue(id, out index);

                public Vector3 NodeLocal(int index) => _nodeLocal[index];

                internal void DetachHandle() => Handle = IntPtr.Zero;

                internal void Dispose()
                {
                    _disposed = true;
                    Instances.Clear();
                    if (Handle == IntPtr.Zero) return;
                    try { Rust.Ai.Gen2.Nav.RecastWrapper.DestroyNavMesh(Handle); }
                    catch (Exception ex) { Debug.LogError<HelperSavedNavMesh>("DestroyNavMesh [{0}]: {1}", Key, ex.Message); }
                    Handle = IntPtr.Zero;
                }

                public bool SampleLocal(Vector3 local, Vector3 extents, out Vector3 hit, out ulong polyRef)
                {
                    hit = local;
                    polyRef = 0;
                    if (!IsValid) return false;
                    if (!Rust.Ai.Gen2.Nav.RecastWrapper.SamplePosition(Handle, in local, in extents, out hit, out polyRef, includeGatedDoorPolys: 0, allowNpcDoors: 0)) return false;
                    return polyRef != 0;
                }

                public NavPathResult FindPathLocal(Vector3 from, Vector3 to, List<Vector3> corners, Vector3 extents)
                {
                    corners?.Clear();
                    if (!SampleLocal(from, extents, out Vector3 start, out ulong startRef)) return NavPathResult.StartOffMesh;
                    if (!SampleLocal(to, extents, out Vector3 end, out _)) return NavPathResult.EndOffMesh;

                    var status = Rust.Ai.Gen2.Nav.RecastWrapper.FindPath(Handle, ref startRef, in start, in end, _pathBuf, out int length,
                        _polyBuf, out _, PathIterations, allowNpcDoors: 0);
                    if (((uint)status & (uint)Rust.Ai.Gen2.Nav.DtStatus.Failure) != 0u || length <= 0) return NavPathResult.None;

                    if (corners != null)
                        for (int i = 0; i < length; i++) corners.Add(_pathBuf[i]);
                    bool partial = (status & Rust.Ai.Gen2.Nav.DtStatus.PartialResult) == Rust.Ai.Gen2.Nav.DtStatus.PartialResult
                                   || (_pathBuf[length - 1] - end).sqrMagnitude > CompleteGap * CompleteGap;
                    return partial ? NavPathResult.Partial : NavPathResult.Complete;
                }

                public float LinkLength(int from, int to, HelperNavGraph.EditorLink link)
                {
                    Vector3 prev = _nodeLocal[from];
                    float length = 0f;
                    if (link?.Waypoints != null)
                        for (int i = 0; i < link.Waypoints.Count; i++)
                        {
                            Vector3 w = link.Waypoints[i].ToVector();
                            length += Vector3.Distance(prev, w);
                            prev = w;
                        }
                    return length + Vector3.Distance(prev, _nodeLocal[to]);
                }

                #region Маршрут (A* по графу переходов поверх навмеша)

                private float[] _g = Array.Empty<float>();
                private float[] _hopCost = Array.Empty<float>();
                private int[] _parent = Array.Empty<int>();
                private NodeHint[] _parentHint = Array.Empty<NodeHint>();
                private bool[] _parentSurface = Array.Empty<bool>();
                private byte[] _state = Array.Empty<byte>();
                private float[] _toGoal = Array.Empty<float>();
                private (float F, int Idx)[] _heap = new (float, int)[64];
                private int _heapCount;
                private int _routeCount;
                private Vector3 _routeStart, _routeGoal;
                private readonly List<(int Idx, float Cost)> _attachStart = new List<(int, float)>();
                private readonly List<(int Idx, float Cost)> _attachGoal = new List<(int, float)>();
                private readonly List<(int Idx, float SqrDist)> _candidates = new List<(int, float)>();
                private readonly List<int> _chain = new List<int>();
                private static readonly Comparison<(int Idx, float SqrDist)> BySqrDist = (a, b) => a.SqrDist.CompareTo(b.SqrDist);

                public NavPathResult Route(NavSurface surface, Vector3 fromLocal, Vector3 toLocal, List<RouteHop> hops, out Vector3 startLocal, out Vector3 goalLocal, out Vector3 stopLocal, out string error, List<Vector3> partialCorners = null)
                {
                    hops.Clear();
                    partialCorners?.Clear();
                    error = null;
                    startLocal = fromLocal;
                    goalLocal = toLocal;
                    stopLocal = fromLocal;
                    if (surface == null || !surface.Ready) { error = "the surface is not ready"; return NavPathResult.None; }
                    Vector3 extents = QueryExtents;
                    if (!surface.Sample(fromLocal, extents, out startLocal)) { error = "start is off the navmesh"; return NavPathResult.None; }
                    if (!surface.Sample(toLocal, extents, out goalLocal)) { error = "goal is off the navmesh"; return NavPathResult.None; }
                    stopLocal = startLocal;

                    int queries = 1;
                    NavPathResult direct = surface.FindPath(startLocal, goalLocal, _probe, extents);
                    if (direct == NavPathResult.Complete)
                    {
                        hops.Add(new RouteHop(StartIndex, GoalIndex, NodeHint.None, true, PathLength(_probe)));
                        stopLocal = goalLocal;
                        return NavPathResult.Complete;
                    }

                    bool directPartial = direct == NavPathResult.Partial && _probe.Count > 0;
                    if (directPartial)
                    {
                        stopLocal = _probe[_probe.Count - 1];
                        if (partialCorners != null)
                            for (int i = 0; i < _probe.Count; i++) partialCorners.Add(_probe[i]);
                    }

                    int n = _nodes.Length;
                    if (n == 0)
                    {
                        error = $"no direct path ({direct}) and the navmesh has no transition graph";
                        return directPartial ? NavPathResult.Partial : NavPathResult.None;
                    }

                    AttachSurface(surface, startLocal, _attachStart, ref queries);
                    AttachSurface(surface, goalLocal, _attachGoal, ref queries);
                    if (_attachStart.Count == 0) { error = $"no graph node is reachable from the start (direct path: {direct})"; return directPartial ? NavPathResult.Partial : NavPathResult.None; }
                    bool goalAttached = _attachGoal.Count > 0;

                    PrepareSearch(n, startLocal, goalLocal);
                    for (int i = 0; i < _attachGoal.Count; i++) _toGoal[_attachGoal[i].Idx] = _attachGoal[i].Cost;

                    int startIdx = n, goalIdx = n + 1;
                    _g[startIdx] = 0f;
                    _state[startIdx] = 1;
                    HeapPush(Heuristic(startIdx), startIdx);

                    bool reached = false, budget = false;
                    int expansions = 0;
                    int bestIdx = -1;
                    float bestH = float.MaxValue;
                    while (_heapCount > 0 && expansions < RouteMaxExpansions)
                    {
                        int cur = HeapPop().Idx;
                        if (_state[cur] == 2) continue;
                        if (cur == goalIdx) { reached = true; break; }
                        _state[cur] = 2;
                        expansions++;

                        if (cur == startIdx)
                        {
                            for (int i = 0; i < _attachStart.Count; i++) Relax(startIdx, _attachStart[i].Idx, _attachStart[i].Cost, NodeHint.None, true);
                            continue;
                        }

                        float h = Heuristic(cur);
                        if (h < bestH) { bestH = h; bestIdx = cur; }

                        var node = _nodes[cur];
                        if (node.Out != null)
                        {
                            for (int i = 0; i < node.Out.Count; i++)
                            {
                                var link = node.Out[i];
                                if (link == null || !_idToIndex.TryGetValue(link.To, out int target)) continue;
                                NodeHint hint = (NodeHint)link.Hint;
                                Relax(cur, target, HintCost(hint, LinkLength(cur, target, link)), hint, false);
                            }
                        }

                        if (!node.OnMesh) continue;
                        if (_toGoal[cur] >= 0f) Relax(cur, goalIdx, _toGoal[cur], NodeHint.None, true);

                        int[] near = Nearest(cur);
                        for (int k = 0; k < near.Length; k++)
                        {
                            int other = near[k];
                            if (_state[other] == 2) continue;
                            if (!TrySurfaceCost(surface, cur, other, ref queries, out float cost)) { budget = true; break; }
                            if (cost >= 0f) Relax(cur, other, cost, NodeHint.None, true);
                        }
                        if (budget) break;
                    }

                    if (!reached)
                    {
                        if (!goalAttached) error = $"no graph node reaches the goal (direct path: {direct})";
                        else if (budget) error = $"native query budget ({RouteMaxSurfaceQueries}) exhausted - a repeated request uses the link cache";
                        else if (expansions >= RouteMaxExpansions) error = $"A* expansion limit ({RouteMaxExpansions}) exhausted";
                        else error = $"the goal is not connected to the start (direct path: {direct})";
                        bool directCloser = directPartial && (bestIdx < 0 || Vector3.Distance(stopLocal, goalLocal) <= bestH);
                        if (bestIdx < 0 || directCloser) return directPartial ? NavPathResult.Partial : NavPathResult.None;
                        BuildChain(bestIdx, n, hops);
                        stopLocal = _nodeLocal[bestIdx];
                        partialCorners?.Clear();
                        return NavPathResult.Partial;
                    }

                    BuildChain(goalIdx, n, hops);
                    stopLocal = goalLocal;
                    return NavPathResult.Complete;
                }

                private void BuildChain(int last, int n, List<RouteHop> hops)
                {
                    _chain.Clear();
                    for (int i = last; i != -1; i = _parent[i]) _chain.Add(i);
                    _chain.Reverse();
                    for (int i = 1; i < _chain.Count; i++)
                    {
                        int to = _chain[i];
                        hops.Add(new RouteHop(MapIndex(_chain[i - 1], n), MapIndex(to, n), _parentHint[to], _parentSurface[to], _hopCost[to]));
                    }
                }

                private static int MapIndex(int idx, int n) => idx == n ? StartIndex : idx == n + 1 ? GoalIndex : idx;

                private void PrepareSearch(int n, Vector3 start, Vector3 goal)
                {
                    int total = n + 2;
                    if (_g.Length < total)
                    {
                        _g = new float[total];
                        _hopCost = new float[total];
                        _parent = new int[total];
                        _parentHint = new NodeHint[total];
                        _parentSurface = new bool[total];
                        _state = new byte[total];
                        _toGoal = new float[total];
                    }
                    for (int i = 0; i < total; i++)
                    {
                        _g[i] = float.MaxValue;
                        _hopCost[i] = 0f;
                        _parent[i] = -1;
                        _parentHint[i] = NodeHint.None;
                        _parentSurface[i] = false;
                        _state[i] = 0;
                        _toGoal[i] = -1f;
                    }
                    _heapCount = 0;
                    _routeCount = n;
                    _routeStart = start;
                    _routeGoal = goal;
                }

                private void Relax(int from, int to, float cost, NodeHint hint, bool surface)
                {
                    if (_state[to] == 2) return;
                    float g = _g[from] + cost;
                    if (g >= _g[to]) return;
                    _g[to] = g;
                    _hopCost[to] = cost;
                    _parent[to] = from;
                    _parentHint[to] = hint;
                    _parentSurface[to] = surface;
                    _state[to] = 1;
                    HeapPush(g + Heuristic(to), to);
                }

                private float Heuristic(int idx)
                {
                    if (idx == _routeCount + 1) return 0f;
                    Vector3 p = idx == _routeCount ? _routeStart : _nodeLocal[idx];
                    return Vector3.Distance(p, _routeGoal);
                }

                private void HeapPush(float f, int idx)
                {
                    if (_heapCount == _heap.Length) Array.Resize(ref _heap, _heapCount * 2);
                    int i = _heapCount++;
                    _heap[i] = (f, idx);
                    while (i > 0)
                    {
                        int parent = (i - 1) / 2;
                        if (_heap[parent].F <= _heap[i].F) break;
                        (_heap[parent], _heap[i]) = (_heap[i], _heap[parent]);
                        i = parent;
                    }
                }

                private (float F, int Idx) HeapPop()
                {
                    var top = _heap[0];
                    _heap[0] = _heap[--_heapCount];
                    int i = 0;
                    while (true)
                    {
                        int left = 2 * i + 1, right = left + 1, min = i;
                        if (left < _heapCount && _heap[left].F < _heap[min].F) min = left;
                        if (right < _heapCount && _heap[right].F < _heap[min].F) min = right;
                        if (min == i) break;
                        (_heap[min], _heap[i]) = (_heap[i], _heap[min]);
                        i = min;
                    }
                    return top;
                }

                private void AttachSurface(NavSurface surface, Vector3 point, List<(int Idx, float Cost)> result, ref int queries)
                {
                    result.Clear();
                    _candidates.Clear();
                    float range2 = SurfaceLinkRange * SurfaceLinkRange;
                    for (int i = 0; i < _nodes.Length; i++)
                    {
                        if (!_nodes[i].OnMesh) continue;
                        float sqr = (_nodeLocal[i] - point).sqrMagnitude;
                        if (sqr <= range2) _candidates.Add((i, sqr));
                    }
                    _candidates.Sort(BySqrDist);
                    int limit = Mathf.Min(SurfaceNeighbors, _candidates.Count);
                    Vector3 extents = QueryExtents;
                    for (int k = 0; k < limit; k++)
                    {
                        int idx = _candidates[k].Idx;
                        queries++;
                        if (surface.FindPath(point, _nodeLocal[idx], _probe, extents) == NavPathResult.Complete)
                            result.Add((idx, PathLength(_probe)));
                    }
                }

                private int[] Nearest(int index)
                {
                    if (_nearest == null || _nearest.Length != _nodes.Length) _nearest = new int[_nodes.Length][];
                    var cached = _nearest[index];
                    if (cached != null) return cached;

                    _candidates.Clear();
                    float range2 = SurfaceLinkRange * SurfaceLinkRange;
                    Vector3 p = _nodeLocal[index];
                    for (int i = 0; i < _nodes.Length; i++)
                    {
                        if (i == index || !_nodes[i].OnMesh) continue;
                        float sqr = (_nodeLocal[i] - p).sqrMagnitude;
                        if (sqr <= range2) _candidates.Add((i, sqr));
                    }
                    _candidates.Sort(BySqrDist);
                    var result = new int[Mathf.Min(SurfaceNeighbors, _candidates.Count)];
                    for (int k = 0; k < result.Length; k++) result[k] = _candidates[k].Idx;
                    _nearest[index] = result;
                    return result;
                }

                private bool TrySurfaceCost(NavSurface surface, int a, int b, ref int queries, out float cost)
                {
                    long key = a < b ? ((long)a << 32) | (uint)b : ((long)b << 32) | (uint)a;
                    if (surface.TryGetCost(key, out cost)) return true;
                    if (queries >= RouteMaxSurfaceQueries) return false;
                    queries++;
                    cost = surface.FindPath(_nodeLocal[a], _nodeLocal[b], _probe, NodeExtents) == NavPathResult.Complete ? PathLength(_probe) : -1f;
                    surface.SetCost(key, cost);
                    return true;
                }

                #endregion
            }

            public sealed class SavedNavInstance
            {
                public readonly SavedNavMesh Mesh;
                public readonly Transform Root;
                public readonly MonumentInfo Monument;
                public readonly int Index;
                public Matrix4x4 ToWorld { get; private set; }
                public Matrix4x4 ToLocal { get; private set; }
                public SavedNavNode[] Nodes { get; private set; } = Array.Empty<SavedNavNode>();
                public int UnboundEntities { get; private set; }

                private readonly List<RouteHop> _hops = new List<RouteHop>();
                private readonly List<Vector3> _probe = new List<Vector3>();
                private readonly List<Vector3> _partialCorners = new List<Vector3>();

                public bool IsAlive => Root != null && Mesh.IsReady;

                public NavSurface Surface { get; }

                private Vector3[] _gateWorld = Array.Empty<Vector3>();

                internal SavedNavInstance(SavedNavMesh mesh, Transform root, MonumentInfo monument, int index)
                {
                    Mesh = mesh;
                    Root = root;
                    Monument = monument;
                    Index = index;
                    Surface = new NavSurface(this);
                    ToWorld = Matrix4x4.TRS(root.position, root.rotation, Vector3.one);
                    ToLocal = ToWorld.inverse;
                    Vector3 scale = root.lossyScale;
                    if (Mathf.Abs(scale.x - 1f) > 0.01f || Mathf.Abs(scale.y - 1f) > 0.01f || Mathf.Abs(scale.z - 1f) > 0.01f)
                        Debug.LogWarning<HelperSavedNavMesh>("NavMesh [{0}] #{1}: object scale {2} - the navmesh is built unscaled and will not fit exactly", mesh.Key, index, scale);
                }

                public Vector3 WorldToLocal(Vector3 world) => ToLocal.MultiplyPoint3x4(world);
                public Vector3 LocalToWorld(Vector3 local) => ToWorld.MultiplyPoint3x4(local);

                public bool Contains(Vector3 world, float margin = 0f)
                {
                    Bounds bounds = Mesh.LocalBounds;
                    if (margin > 0f) bounds.Expand(margin * 2f);
                    return bounds.Contains(WorldToLocal(world));
                }

                public bool TrySample(Vector3 world, out Vector3 hitWorld) => TrySample(world, QueryExtents, out hitWorld);

                public bool TrySample(Vector3 world, Vector3 extents, out Vector3 hitWorld)
                {
                    hitWorld = world;
                    if (!Surface.Sample(WorldToLocal(world), extents, out Vector3 hit)) return false;
                    hitWorld = LocalToWorld(hit);
                    return true;
                }

                internal int GateCut(List<Vector3> path, out Vector3 gateWorld)
                {
                    gateWorld = Vector3.zero;
                    if (_gateWorld.Length == 0 || path == null || path.Count < 2) return -1;
                    for (int i = 1; i < path.Count; i++)
                    {
                        for (int g = 0; g < _gateWorld.Length; g++)
                        {
                            if (!PassesGate(path[i - 1], path[i], _gateWorld[g])) continue;
                            gateWorld = _gateWorld[g];
                            return i;
                        }
                    }
                    return -1;
                }

                private static bool PassesGate(Vector3 a, Vector3 b, Vector3 gate)
                {
                    if (NearGate(a, gate)) return (a.x - gate.x) * (b.x - gate.x) + (a.z - gate.z) * (b.z - gate.z) < 0f;
                    return NearGate(ClosestOnSegment(a, b, gate), gate);
                }

                private static bool NearGate(Vector3 point, Vector3 gate)
                {
                    if (Mathf.Abs(point.y - gate.y) > GateHeight) return false;
                    float dx = point.x - gate.x, dz = point.z - gate.z;
                    return dx * dx + dz * dz <= GateRadius * GateRadius;
                }

                private static Vector3 ClosestOnSegment(Vector3 a, Vector3 b, Vector3 point)
                {
                    Vector3 ab = b - a;
                    float lengthSqr = ab.sqrMagnitude;
                    if (lengthSqr < 1e-6f) return a;
                    float t = Mathf.Clamp01(Vector3.Dot(point - a, ab) / lengthSqr);
                    return a + ab * t;
                }

                public bool TryNearestSurface(Vector3 world, out Vector3 hitWorld)
                {
                    hitWorld = world;
                    if (!IsAlive) return false;
                    Bounds bounds = Mesh.LocalBounds;
                    Vector3 probe = bounds.ClosestPoint(WorldToLocal(world));
                    float limit = Mathf.Max(bounds.size.x, bounds.size.z);
                    float height = Mathf.Max(bounds.size.y, QueryExtents.y);
                    for (float half = NearestSurfaceExtent; ; half *= 3f)
                    {
                        float size = Mathf.Min(half, limit);
                        if (Surface.Sample(probe, new Vector3(size, height, size), out Vector3 hit))
                        {
                            hitWorld = LocalToWorld(hit);
                            return true;
                        }
                        if (size >= limit) return false;
                    }
                }

                private const float NearestSurfaceExtent = 4f;

                public NavPathResult FindPath(Vector3 fromWorld, Vector3 toWorld, List<Vector3> cornersWorld)
                {
                    var result = Surface.FindPath(WorldToLocal(fromWorld), WorldToLocal(toWorld), _probe, QueryExtents);
                    cornersWorld.Clear();
                    for (int i = 0; i < _probe.Count; i++) cornersWorld.Add(LocalToWorld(_probe[i]));
                    return result;
                }

                public NavPathResult TryBuildRoute(Vector3 fromWorld, Vector3 toWorld, List<PathStep> steps, out Vector3 stopWorld, out string error)
                {
                    steps.Clear();
                    stopWorld = fromWorld;
                    if (!IsAlive) { error = "the instance is gone or the navmesh is destroyed"; return NavPathResult.None; }
                    var result = Mesh.Route(Surface, WorldToLocal(fromWorld), WorldToLocal(toWorld), _hops, out Vector3 startLocal, out Vector3 goalLocal, out Vector3 stopLocal, out error, _partialCorners);
                    if (result == NavPathResult.None) { steps.Clear(); return NavPathResult.None; }
                    stopWorld = LocalToWorld(stopLocal);

                    var startNode = new SavedNavNode(this, LocalToWorld(startLocal));
                    var goalNode = new SavedNavNode(this, LocalToWorld(goalLocal));
                    steps.Add(new PathStep(startNode, NodeHint.None, null, 0f));
                    if (result == NavPathResult.Partial && _hops.Count == 0 && _partialCorners.Count > 1)
                    {
                        var corners = new List<Vector3>(_partialCorners.Count);
                        for (int i = 0; i < _partialCorners.Count; i++) corners.Add(LocalToWorld(_partialCorners[i]));
                        steps.Add(new PathStep(new SavedNavNode(this, stopWorld), NodeHint.None, corners, HelperSavedNavMesh.PathLength(corners)));
                        return result;
                    }
                    for (int i = 0; i < _hops.Count; i++)
                    {
                        var hop = _hops[i];
                        SavedNavNode target = hop.To == GoalIndex ? goalNode : Nodes[hop.To];
                        List<Vector3> waypoints = null;
                        if (hop.Surface)
                        {
                            Vector3 fromLocal = hop.From == StartIndex ? startLocal : Mesh.NodeLocal(hop.From);
                            Vector3 toLocal = hop.To == GoalIndex ? goalLocal : Mesh.NodeLocal(hop.To);
                            if (Surface.FindPath(fromLocal, toLocal, _probe, QueryExtents) != NavPathResult.None && _probe.Count > 0)
                            {
                                waypoints = new List<Vector3>(_probe.Count);
                                for (int k = 0; k < _probe.Count; k++) waypoints.Add(LocalToWorld(_probe[k]));
                            }
                        }
                        else if (hop.From >= 0)
                        {
                            var edges = Nodes[hop.From].EdgeList;
                            for (int k = 0; k < edges.Count; k++)
                            {
                                if (edges[k].Target != target) continue;
                                if (edges[k].Waypoints != null) waypoints = new List<Vector3>(edges[k].Waypoints);
                                break;
                            }
                        }
                        steps.Add(new PathStep(target, hop.Hint, waypoints, hop.Cost));
                    }
                    return result;
                }

                public void BuildNodes()
                {
                    var source = Mesh.Nodes;
                    var nodes = new SavedNavNode[source.Count];
                    for (int i = 0; i < source.Count; i++)
                        nodes[i] = new SavedNavNode(this, source[i], LocalToWorld(source[i].LocalPos.ToVector()));

                    for (int i = 0; i < source.Count; i++)
                    {
                        var outs = source[i].Out;
                        if (outs == null) continue;
                        for (int k = 0; k < outs.Count; k++)
                        {
                            var link = outs[k];
                            if (link == null || !Mesh.TryGetIndex(link.To, out int j)) continue;
                            NodeHint hint = (NodeHint)link.Hint;
                            List<Vector3> waypoints = null;
                            if (link.Waypoints != null && link.Waypoints.Count > 0)
                            {
                                waypoints = new List<Vector3>(link.Waypoints.Count);
                                for (int w = 0; w < link.Waypoints.Count; w++) waypoints.Add(LocalToWorld(link.Waypoints[w].ToVector()));
                            }
                            nodes[i].AddEdge(new PathEdge(nodes[j], hint, waypoints, HintCost(hint, Mesh.LinkLength(i, j, link))));
                        }
                    }
                    Nodes = nodes;
                    var gates = Mesh.GateLocal;
                    _gateWorld = new Vector3[gates.Count];
                    for (int i = 0; i < gates.Count; i++) _gateWorld[i] = LocalToWorld(gates[i]);
                    BindEntities();
                }

                public int BindEntities()
                {
                    int unbound = 0;
                    var source = Mesh.Nodes;
                    for (int i = 0; i < Nodes.Length && i < source.Count; i++)
                    {
                        var entities = source[i].LinkedEntities;
                        if (entities == null) continue;
                        for (int k = 0; k < entities.Count; k++)
                        {
                            var entity = entities[k];
                            if (entity == null || string.IsNullOrEmpty(entity.Type)) continue;
                            string type = entity.Type.ToLowerInvariant();
                            Component found = HelperNavGraph.FindLinkedObject(type, LocalToWorld(entity.LocalPos.ToVector()));
                            if (found == null) { unbound++; continue; }
                            Nodes[i].Bind(type, found);
                        }
                    }
                    UnboundEntities = unbound;
                    return unbound;
                }
            }

            public sealed class SavedNavNode : IAIPathNode
            {
                private readonly List<PathEdge> _edges = new List<PathEdge>();

                public readonly SavedNavInstance Owner;
                public readonly int Id;
                public readonly bool OnMesh;
                public readonly string Auto;

                public Vector3 Position { get; }
                public bool Straightaway => false;
                public IEnumerable<IAIPathNode> Linked => Array.Empty<IAIPathNode>();
                public NodeHint Hint => NodeHint.None;
                public IEnumerable<PathEdge> Edges => _edges;
                public IReadOnlyList<PathEdge> EdgeList => _edges;
                public Door LinkedDoor { get; private set; }
                public PressButton LinkedButton { get; private set; }
                public CardReader LinkedReader { get; private set; }
                public Collider LinkedLadderTrigger { get; private set; }
                public bool IsWaypointOnly => false;
                public bool IsNavMesh { get; }

                internal SavedNavNode(SavedNavInstance owner, NavMeshFileNode source, Vector3 position)
                {
                    Owner = owner;
                    Id = source.Id;
                    OnMesh = source.OnMesh;
                    IsNavMesh = source.OnGameMesh;
                    Auto = source.Auto;
                    Position = position;
                }

                internal SavedNavNode(SavedNavInstance owner, Vector3 position)
                {
                    Owner = owner;
                    Id = -1;
                    OnMesh = true;
                    Position = position;
                }

                public bool IsValid() => Owner != null && Owner.IsAlive;

                public void AddLink(IAIPathNode link) => AddEdge(new PathEdge(link, NodeHint.None, null, link == null ? 0f : Vector3.Distance(Position, link.Position)));

                public void AddEdge(PathEdge edge)
                {
                    if (edge.Target != null) _edges.Add(edge);
                }

                internal void Bind(string typeLower, Component found)
                {
                    switch (typeLower)
                    {
                        case "door": LinkedDoor = found as Door; break;
                        case "button": LinkedButton = found as PressButton; break;
                        case "reader": LinkedReader = found as CardReader; break;
                        case "ladder": LinkedLadderTrigger = found as Collider; break;
                    }
                }
            }
        }

        public static class HelperNavLayers
        {
            public enum NavCoverage
            {
                None,
                InArea,
                OnSurface,
            }

            public interface INavLayer
            {
                string Name { get; }
                bool Enabled { get; }
                bool Probe(Vector3 world, float margin, out object handle, out NavCoverage coverage, out Vector3 onMesh);
                bool Contains(object handle, Vector3 world, float margin);
                bool Sample(object handle, Vector3 world, out Vector3 onMesh);
                bool TryNearestSurface(object handle, Vector3 world, out Vector3 onMesh);
                HelperSavedNavMesh.NavPathResult Route(object handle, Vector3 from, Vector3 to, List<PathStep> steps,
                                                       out Vector3 stopWorld, out string error);
                string Describe(object handle);
                void MarkRoute(BasePlayer npc, object handle, int steps, int nodes);
            }

            public sealed class WorldNavLayer : INavLayer
            {
                private const float ArrivalTolerance = 0.5f;
                private const float DefaultSnapRadius = 1f;

                private readonly RustNavMeshPath _probe;

                public RustNavMeshAgent Agent { get; set; }

                public WorldNavLayer(RustNavMeshPath probe)
                {
                    _probe = probe;
                }

                public string Name => "world";
                public bool Enabled => Agent != null;

                public bool Probe(Vector3 world, float margin, out object handle, out NavCoverage coverage, out Vector3 onMesh)
                {
                    handle = null;
                    onMesh = world;
                    coverage = NavCoverage.None;
                    if (Agent == null) return false;
                    handle = Agent;
                    if (!Agent.SamplePositionTyped(world, out var hit, margin > 0f ? margin : DefaultSnapRadius))
                    {
                        coverage = NavCoverage.InArea;
                        return true;
                    }
                    onMesh = hit.position;
                    coverage = NavCoverage.OnSurface;
                    return true;
                }

                public bool Contains(object handle, Vector3 world, float margin) => Agent != null;

                public bool Sample(object handle, Vector3 world, out Vector3 onMesh)
                {
                    onMesh = world;
                    var agent = handle as RustNavMeshAgent ?? Agent;
                    if (agent == null || !agent.SamplePositionTyped(world, out var hit, DefaultSnapRadius)) return false;
                    onMesh = hit.position;
                    return true;
                }

                public bool TryNearestSurface(object handle, Vector3 world, out Vector3 onMesh)
                {
                    onMesh = world;
                    var agent = handle as RustNavMeshAgent ?? Agent;
                    if (agent == null || !agent.SamplePositionTyped(world, out var hit, NearestSurfaceRadius)) return false;
                    onMesh = hit.position;
                    return true;
                }

                private const float NearestSurfaceRadius = 30f;

                public HelperSavedNavMesh.NavPathResult Route(object handle, Vector3 from, Vector3 to, List<PathStep> steps,
                                                              out Vector3 stopWorld, out string error)
                {
                    steps?.Clear();
                    stopWorld = from;
                    var agent = handle as RustNavMeshAgent ?? Agent;
                    if (agent == null || _probe == null)
                    {
                        error = "no navmesh agent";
                        return HelperSavedNavMesh.NavPathResult.None;
                    }
                    if (!agent.CalculatePathTyped(from, to, _probe))
                    {
                        error = "the game navmesh failed to calculate a path";
                        return HelperSavedNavMesh.NavPathResult.None;
                    }
                    var corners = _probe.corners;
                    if (corners == null || corners.Count == 0)
                    {
                        error = "the game navmesh returned an empty path";
                        return HelperSavedNavMesh.NavPathResult.None;
                    }
                    stopWorld = agent.PathEndWorld(_probe, to, out _);
                    if (_probe.status == NavMeshPathStatus.PathInvalid)
                    {
                        error = "the game navmesh found no path";
                        return HelperSavedNavMesh.NavPathResult.None;
                    }
                    bool complete = _probe.status == NavMeshPathStatus.PathComplete
                                    && (stopWorld - to).sqrMagnitude < ArrivalTolerance * ArrivalTolerance;
                    error = complete ? null : "the game navmesh stops short of the goal";
                    return complete ? HelperSavedNavMesh.NavPathResult.Complete : HelperSavedNavMesh.NavPathResult.Partial;
                }

                public string Describe(object handle) => "game navmesh";

                public void MarkRoute(BasePlayer npc, object handle, int steps, int nodes) { }
            }

            public sealed class WorldNavNode : IAIPathNode
            {
                public Vector3 Position { get; }
                public WorldNavNode(Vector3 position) { Position = position; }
                public bool Straightaway => false;
                public IEnumerable<IAIPathNode> Linked => Array.Empty<IAIPathNode>();
                public NodeHint Hint => NodeHint.None;
                public bool IsValid() => true;
                public void AddLink(IAIPathNode link) { }
            }

            public sealed class SavedNavLayer : INavLayer
            {
                public static readonly SavedNavLayer Instance = new SavedNavLayer();

                public string Name => "monument";
                public bool Enabled => HelperSavedNavMesh.UseInNavigator && HelperSavedNavMesh.Instance != null;

                public bool Probe(Vector3 world, float margin, out object handle, out NavCoverage coverage, out Vector3 onMesh)
                {
                    handle = null;
                    coverage = NavCoverage.None;
                    onMesh = world;
                    var store = HelperSavedNavMesh.Instance;
                    if (store == null || !HelperSavedNavMesh.UseInNavigator) return false;
                    if (!store.TryGetInstanceAt(world, out var instance, margin)) return false;
                    handle = instance;
                    coverage = instance.TrySample(world, out onMesh) ? NavCoverage.OnSurface : NavCoverage.InArea;
                    return true;
                }

                public bool Contains(object handle, Vector3 world, float margin)
                    => handle is HelperSavedNavMesh.SavedNavInstance instance && instance.Contains(world, margin);

                public bool Sample(object handle, Vector3 world, out Vector3 onMesh)
                {
                    onMesh = world;
                    return handle is HelperSavedNavMesh.SavedNavInstance instance && instance.TrySample(world, out onMesh);
                }

                public bool TryNearestSurface(object handle, Vector3 world, out Vector3 onMesh)
                {
                    onMesh = world;
                    return handle is HelperSavedNavMesh.SavedNavInstance instance && instance.TryNearestSurface(world, out onMesh);
                }

                public HelperSavedNavMesh.NavPathResult Route(object handle, Vector3 from, Vector3 to, List<PathStep> steps,
                                                              out Vector3 stopWorld, out string error)
                {
                    stopWorld = from;
                    if (!(handle is HelperSavedNavMesh.SavedNavInstance instance))
                    {
                        steps?.Clear();
                        error = "no navmesh instance passed";
                        return HelperSavedNavMesh.NavPathResult.None;
                    }
                    if (steps == null)
                    {
                        return instance.TryBuildRoute(from, to, _spare, out stopWorld, out error);
                    }
                    return instance.TryBuildRoute(from, to, steps, out stopWorld, out error);
                }

                public string Describe(object handle)
                    => handle is HelperSavedNavMesh.SavedNavInstance instance ? $"[{instance.Mesh.Key}] #{instance.Index}" : "-";

                public void MarkRoute(BasePlayer npc, object handle, int steps, int nodes)
                {
                    if (handle is HelperSavedNavMesh.SavedNavInstance instance) HelperSavedNavMesh.MarkRoute(npc, instance, steps, nodes);
                }

                private readonly List<PathStep> _spare = new List<PathStep>();
            }

            public interface INavLayerVersioned
            {
                int Version { get; }
            }

            public sealed class BuildingNavLayer : INavLayer, INavLayerVersioned
            {
                public static readonly BuildingNavLayer Instance = new BuildingNavLayer(null);

                private readonly HelperBuildingNavMesh.BuildingNav _pinned;

                private readonly List<PathStep> _spare = new List<PathStep>();

                private readonly Func<IAIPathNode, IAIPathNode, bool> _canUseDoor;

                public BuildingNavLayer(HelperBuildingNavMesh.BuildingNav nav, Func<IAIPathNode, IAIPathNode, bool> canUseDoor = null)
                {
                    _pinned = nav;
                    _canUseDoor = canUseDoor;
                }

                public string Name => "building";

                public bool Enabled => _pinned != null
                    ? _pinned.IsValid
                    : HelperBuildingNavMesh.UseInNavigator && HelperBuildingNavMesh.IsRunning;

                public int Version => _pinned != null && _pinned.IsValid ? _pinned.Version : 0;

                public bool Probe(Vector3 world, float margin, out object handle, out NavCoverage coverage, out Vector3 onMesh)
                {
                    handle = null;
                    coverage = NavCoverage.None;
                    onMesh = world;
                    var store = HelperBuildingNavMesh.Instance;
                    if (store == null) return false;

                    var nav = _pinned;
                    if (nav != null)
                    {
                        if (!nav.IsValid || !store.Contains(nav, world, margin)) return false;
                    }
                    else
                    {
                        if (!HelperBuildingNavMesh.UseInNavigator) return false;
                        if (!store.TryGetNavAt(world, out nav, margin)) return false;
                    }

                    handle = nav;
                    coverage = store.TrySample(nav, world, out onMesh) ? NavCoverage.OnSurface : NavCoverage.InArea;
                    return true;
                }

                public bool Contains(object handle, Vector3 world, float margin)
                    => handle is HelperBuildingNavMesh.BuildingNav nav
                       && HelperBuildingNavMesh.Instance.Contains(nav, world, margin);

                public bool Sample(object handle, Vector3 world, out Vector3 onMesh)
                {
                    onMesh = world;
                    return handle is HelperBuildingNavMesh.BuildingNav nav
                           && HelperBuildingNavMesh.Instance.TrySample(nav, world, out onMesh);
                }

                public bool TryNearestSurface(object handle, Vector3 world, out Vector3 onMesh)
                {
                    onMesh = world;
                    return handle is HelperBuildingNavMesh.BuildingNav nav
                           && HelperBuildingNavMesh.Instance.TryNearestSurface(nav, world, out onMesh);
                }

                public HelperSavedNavMesh.NavPathResult Route(object handle, Vector3 from, Vector3 to, List<PathStep> steps,
                                                              out Vector3 stopWorld, out string error)
                {
                    stopWorld = from;
                    if (!(handle is HelperBuildingNavMesh.BuildingNav nav))
                    {
                        steps?.Clear();
                        error = "no building navmesh passed";
                        return HelperSavedNavMesh.NavPathResult.None;
                    }
                    return HelperBuildingNavMesh.Instance.TryBuildRoute(nav, from, to, steps ?? _spare, out stopWorld, out error, _canUseDoor);
                }

                public string Describe(object handle)
                    => handle is HelperBuildingNavMesh.BuildingNav nav ? $"building={nav.BuildingID} v{nav.Version}" : "-";

                public void MarkRoute(BasePlayer npc, object handle, int steps, int nodes) { }
            }

            public sealed class WaterNavLayer : INavLayer
            {
                public static readonly WaterNavLayer Instance = new WaterNavLayer();

                private readonly List<PathStep> _spare = new List<PathStep>();

                public string Name => "water";

                public bool Enabled => HelperWaterNavMesh.Enabled && HelperWaterNavMesh.Instance.IsReady;

                public bool Probe(Vector3 world, float margin, out object handle, out NavCoverage coverage, out Vector3 onMesh)
                {
                    handle = null;
                    coverage = NavCoverage.None;
                    onMesh = world;
                    var store = HelperWaterNavMesh.Instance;
                    if (!Enabled || !store.HasMeshAt(world)) return false;
                    handle = store;
                    coverage = store.TrySampleColumn(world, out onMesh) ? NavCoverage.OnSurface : NavCoverage.InArea;
                    return true;
                }

                public bool Contains(object handle, Vector3 world, float margin)
                    => handle is HelperWaterNavMesh store && store.HasMeshAt(world);

                public bool Sample(object handle, Vector3 world, out Vector3 onMesh)
                {
                    onMesh = world;
                    return handle is HelperWaterNavMesh store && store.TrySample(world, out onMesh);
                }

                public bool TryNearestSurface(object handle, Vector3 world, out Vector3 onMesh)
                {
                    onMesh = world;
                    return handle is HelperWaterNavMesh store && store.TrySampleColumn(world, out onMesh);
                }

                public HelperSavedNavMesh.NavPathResult Route(object handle, Vector3 from, Vector3 to, List<PathStep> steps,
                                                              out Vector3 stopWorld, out string error)
                {
                    stopWorld = from;
                    if (!(handle is HelperWaterNavMesh store))
                    {
                        steps?.Clear();
                        error = "no water navmesh passed";
                        return HelperSavedNavMesh.NavPathResult.None;
                    }
                    return store.TryRoute(from, to, steps ?? _spare, out stopWorld, out error);
                }

                public string Describe(object handle)
                    => handle is HelperWaterNavMesh store ? $"tiles {store.TileCount}" : "-";

                public void MarkRoute(BasePlayer npc, object handle, int steps, int nodes) { }
            }
        }

