            public sealed class RecastNode : IAIPathNode
            {
                private readonly List<PathEdge> _edges = new List<PathEdge>();
                private readonly Door _door;

                public Vector3 Position { get; }
                public NodeRole Role { get; }
                public NodeHint Hint => NodeHint.None;
                public bool Straightaway => false;
                public IEnumerable<IAIPathNode> Linked => Array.Empty<IAIPathNode>();
                public IEnumerable<PathEdge> Edges => _edges;
                public int EdgeCount => _edges.Count;
                public Door LinkedDoor => _door;
                public bool IsWaypointOnly { get; }
                public bool IsNavMesh { get; }
                public bool IsOffMesh { get; }
                public Collider LinkedLadderTrigger { get; set; }

                public RecastNode(Vector3 position, NodeRole role, Door door = null, bool waypointOnly = false, bool unityNavMesh = false, bool offMesh = false)
                {
                    Position = position;
                    Role = role;
                    _door = door;
                    IsWaypointOnly = waypointOnly;
                    IsNavMesh = unityNavMesh;
                    IsOffMesh = offMesh;
                }

                public bool IsValid() => ReferenceEquals(_door, null) || (_door != null && !_door.IsDestroyed);

                public void AddLink(IAIPathNode link) => AddEdge(new PathEdge(link, NodeHint.None, null, link == null ? 0f : Vector3.Distance(Position, link.Position)));

                public void AddEdge(PathEdge edge)
                {
                    if (edge.Target == null) return;
                    _edges.Add(edge);
                }

                public void ClearEdges() => _edges.Clear();

                public void LinkTo(RecastNode target, NodeHint hint) => LinkTo(target, hint, target == null ? 0f : Vector3.Distance(Position, target.Position));

                public void LinkTo(RecastNode target, NodeHint hint, float cost)
                {
                    if (target == null) return;
                    _edges.Add(new PathEdge(target, hint, null, cost));
                }
            }

