            private HelperBuildingNavMesh()
            {
                GeomMask = (1 << (int)Rust.Layer.Default)
                         | (1 << (int)Rust.Layer.Deployed)
                         | (1 << (int)Rust.Layer.Vehicle_World)
                         | (1 << (int)Rust.Layer.World)
                         | (1 << (int)Rust.Layer.Construction)
                         | (1 << (int)Rust.Layer.Transparent)
                         | (1 << (int)Rust.Layer.Tree);

                CarveMask = 1 << (int)Rust.Layer.Construction;

                WalkMask = (1 << (int)Rust.Layer.Construction)
                         | (1 << (int)Rust.Layer.Deployed)
                         | (1 << (int)Rust.Layer.World)
                         | (1 << (int)Rust.Layer.Default);
            }

            public static void OnInitPlugin()
            {
                _pluginReady = true;
                ApplyEnabled();
            }

            public static void OnUnloadPlugin()
            {
                _pluginReady = false;
                _instance?.Stop();
                _instance?.DestroyAll();
                _instance = null;
                _watch.Clear();
                _anchors.Clear();
                _movedTo.Clear();
            }

            private bool _running;
            private Timer _dropGoneTimer;
            private Timer _hatchWatchTimer;
            private Timer _scanTimer;
            private Timer _watchCheckTimer;

            private void Start()
            {
                if (_running) return;
                _running = true;
                var plugin = NPCsController.Instance;
                _dropGoneTimer = plugin?.timer.Every(DropGoneStep, () => DropGoneNavs());
                _hatchWatchTimer = plugin?.timer.Every(HatchWatchStep, WatchHatches);
                _watchCheckTimer = plugin?.timer.Every(WatchCheckStep, CheckWatches);
                foreach (uint id in _watch.Keys) QueueAutoBuild(id);
                if (AutoBuild)
                    _scanTimer = plugin?.timer.Once(AutoBuildScanDelay, () => { _scanTimer = null; QueueAllBuildings(); });
            }

            private void Stop()
            {
                if (!_running) return;
                _running = false;
                int freed = _navs.Count;
                _dropGoneTimer?.Destroy();
                _dropGoneTimer = null;
                _hatchWatchTimer?.Destroy();
                _hatchWatchTimer = null;
                _scanTimer?.Destroy();
                _scanTimer = null;
                _watchCheckTimer?.Destroy();
                _watchCheckTimer = null;
                _doorLeakLogged.Clear();
                _leafBoundsByPrefab.Clear();
                _doorNoPolysLogged.Clear();
                _doorAxisLogged.Clear();
                DestroyAll();
                _meshCache.Clear();
            }

            public int Count => _navs.Count;

            public IEnumerable<BuildingNav> All => _navs.Values;

            public IEnumerable<uint> Ids => _navs.Keys;

            public bool TryGet(uint buildingID, out BuildingNav nav)
            {
                nav = null;
                return _navs.TryGetValue(buildingID, out nav) && nav.IsValid;
            }

            public BuildReport LastBuildReport(uint buildingID)
                => _reports.TryGetValue(buildingID, out var report) ? report : null;

            public bool Contains(BuildingNav nav, Vector3 world, float margin = 0f)
            {
                if (nav == null || !nav.IsValid) return false;
                Bounds bounds = nav.Bounds;
                if (margin > 0f) bounds.Expand(margin * 2f);
                return bounds.Contains(world);
            }

            public bool TryGetNavAt(Vector3 world, out BuildingNav nav, float margin = 0f)
            {
                nav = null;
                float bestArea = float.MaxValue;
                foreach (var candidate in _navs.Values)
                {
                    if (!candidate.IsValid || !Contains(candidate, world, margin)) continue;
                    float area = candidate.Bounds.size.x * candidate.Bounds.size.z;
                    if (area >= bestArea) continue;
                    bestArea = area;
                    nav = candidate;
                }
                return nav != null;
            }

            public bool TrySample(BuildingNav nav, Vector3 world, out Vector3 onMesh)
            {
                onMesh = world;
                if (LinkSidesToWorld)
                    return SampleWorldNavmesh(world, WorldSnapRadius, out onMesh)
                           && Mathf.Abs(onMesh.y - world.y) <= SampleExtents.y;
                if (nav == null || !nav.IsValid) return false;
                Vector3 extents = SampleExtents;
                if (!RecastWrapper.SamplePosition(nav.Handle, in world, in extents, out Vector3 hit, out _, includeGatedDoorPolys: 0, allowNpcDoors: 0)) return false;
                if (hit == Vector3.zero) return false;
                onMesh = hit;
                return true;
            }

            public bool TryNearestSurface(BuildingNav nav, Vector3 world, out Vector3 onMesh)
            {
                onMesh = world;
                if (nav == null || !nav.IsValid) return false;
                if (LinkSidesToWorld)
                    return SampleWorldNavmesh(nav.Bounds.ClosestPoint(world), Mathf.Max(nav.Bounds.size.x, nav.Bounds.size.z), out onMesh);
                Vector3 probe = nav.Bounds.ClosestPoint(world);
                float limit = Mathf.Max(nav.Bounds.size.x, nav.Bounds.size.z);
                float height = Mathf.Max(nav.Bounds.size.y, SampleExtents.y);
                for (float half = NearestSurfaceExtent; ; half *= 3f)
                {
                    float size = Mathf.Min(half, limit);
                    Vector3 extents = new Vector3(size, height, size);
                    if (RecastWrapper.SamplePosition(nav.Handle, in probe, in extents, out Vector3 hit, out _, includeGatedDoorPolys: 0, allowNpcDoors: 0) && hit != Vector3.zero)
                    {
                        onMesh = hit;
                        return true;
                    }
                    if (size >= limit) return false;
                }
            }

            private const float NearestSurfaceExtent = 2f;

            private const float ExitProbeStep = 2f;
            private const int ExitMaxProbes = 64;
            private const float ExitSampleXZ = 1f;
            private const float ExitMergeRadius = 4f;
            private const float ExitWorldSnap = 1f;
            private const float ExitWorldDrop = 0.6f;

            public IReadOnlyList<Vector3> GroundExits(BuildingNav nav)
            {
                if (nav == null || !nav.IsValid) return Array.Empty<Vector3>();
                if (nav.ExitsVersion == nav.Version) return nav.Exits;
                nav.ExitsVersion = nav.Version;
                nav.Exits.Clear();
                int probes = 0;

                Bounds bounds = nav.Bounds;
                float perimeter = 2f * (bounds.size.x + bounds.size.z);
                if (perimeter > 0f)
                {
                    float step = Mathf.Max(ExitProbeStep, perimeter / ExitMaxProbes);
                    Vector3 min = bounds.min, max = bounds.max;
                    ProbeExitEdge(nav, new Vector3(min.x, 0f, min.z), new Vector3(max.x, 0f, min.z), step, ref probes);
                    ProbeExitEdge(nav, new Vector3(max.x, 0f, min.z), new Vector3(max.x, 0f, max.z), step, ref probes);
                    ProbeExitEdge(nav, new Vector3(max.x, 0f, max.z), new Vector3(min.x, 0f, max.z), step, ref probes);
                    ProbeExitEdge(nav, new Vector3(min.x, 0f, max.z), new Vector3(min.x, 0f, min.z), step, ref probes);
                }
                for (int i = 0; i < nav.Entries.Count; i++)
                {
                    var entry = nav.Entries[i];
                    if (entry.Kind == EntryKind.OpenDoor || entry.Outside == null) continue;
                    probes++;
                    Vector3 outside = entry.Outside.Position;
                    if (Mathf.Abs(outside.y - GroundHeight(nav, outside)) <= GroundLevelSlack) AddGroundExit(nav, outside);
                }
                return nav.Exits;
            }

            private static void ProbeExitEdge(BuildingNav nav, Vector3 from, Vector3 to, float step, ref int probes)
            {
                float length = Vector3.Distance(from, to);
                int pieces = Mathf.Max(1, Mathf.CeilToInt(length / step));
                for (int i = 0; i < pieces; i++)
                {
                    probes++;
                    if (SampleGroundSurface(nav, Vector3.Lerp(from, to, (float)i / pieces), out Vector3 onMesh)) AddGroundExit(nav, onMesh);
                }
            }

            private static bool SampleGroundSurface(BuildingNav nav, Vector3 point, out Vector3 onMesh)
            {
                point.y = GroundHeight(nav, point);
                if (LinkSidesToWorld)
                    return SampleWorldNavmesh(point, ExitSampleXZ, out onMesh) && Mathf.Abs(onMesh.y - point.y) <= GroundLevelSlack;
                onMesh = point;
                Vector3 extents = new Vector3(ExitSampleXZ, GroundLevelSlack, ExitSampleXZ);
                if (!RecastWrapper.SamplePosition(nav.Handle, in point, in extents, out Vector3 hit, out _, includeGatedDoorPolys: 0, allowNpcDoors: 0)) return false;
                if (hit == Vector3.zero) return false;
                onMesh = hit;
                return true;
            }

            private static float GroundHeight(BuildingNav nav, Vector3 point)
                => TerrainMeta.HeightMap != null ? TerrainMeta.HeightMap.GetHeight(point) : nav.Bounds.min.y + HeightPadDown;

            private static void AddGroundExit(BuildingNav nav, Vector3 point)
            {
                for (int i = 0; i < nav.Exits.Count; i++)
                {
                    Vector3 known = nav.Exits[i];
                    if (Mathf.Abs(known.y - point.y) <= GroundLevelSlack && Vector3Ex.Distance2D(known, point) <= ExitMergeRadius) return;
                }
                if (!SampleWorldNavmesh(point, ExitWorldSnap, out Vector3 world) || Mathf.Abs(world.y - point.y) > ExitWorldDrop) return;
                nav.Exits.Add(point);
            }

            public bool Remove(uint buildingID)
            {
                CancelRebuild(buildingID);
                _rebuildQueued.Remove(buildingID);
                if (!_navs.TryGetValue(buildingID, out var nav)) return false;
                DestroyNav(nav);
                _navs.Remove(buildingID);
                _reports.Remove(buildingID);
                _dirtyTiles.Remove(buildingID);
                _rebuildWhole.Remove(buildingID);
                return true;
            }

            public void DestroyAll()
            {
                _rebuildStepTimer?.Destroy();
                _rebuildStepTimer = null;
                if (_rebuildJob != null) CancelRebuild(_rebuildJob.Target.BuildingID);
                _rebuildQueue.Clear();
                _rebuildQueued.Clear();
                foreach (var nav in _navs.Values) DestroyNav(nav);
                _navs.Clear();
                _reports.Clear();
                _dirtyTiles.Clear();
                _rebuildWhole.Clear();
                _dirtyTimer?.Destroy();
                _dirtyTimer = null;
                ClearAutoQueue();
            }

            private static void DestroyNav(BuildingNav nav)
            {
                if (nav == null || nav.Handle == IntPtr.Zero) return;
                try { RecastWrapper.DestroyNavMesh(nav.Handle); }
                catch (Exception e) { Debug.LogWarning<HelperBuildingNavMesh>("DestroyNavMesh: {0}", e.Message); }
                nav.Handle = IntPtr.Zero;
            }

            #endregion

            #region Подписки аддонов

            private static readonly Dictionary<uint, HashSet<object>> _watch = new Dictionary<uint, HashSet<object>>();
            private static readonly Dictionary<uint, BuildingBlock> _anchors = new Dictionary<uint, BuildingBlock>();
            private static readonly Dictionary<uint, uint> _movedTo = new Dictionary<uint, uint>();

            private const float WatchCheckStep = 2.5f;

            private static readonly List<uint> _watchIdBuf = new List<uint>();
            private static readonly List<object> _watchSubBuf = new List<object>();

            public static int WatchedCount => _watch.Count;

            public static void Watch(uint buildingID, object subscriber, BuildingBlock anchor = null)
            {
                if (buildingID == 0 || subscriber == null) return;
                buildingID = ResolveWatchID(buildingID);
                if (!_watch.TryGetValue(buildingID, out var subs)) { subs = new HashSet<object>(); _watch[buildingID] = subs; }
                subs.Add(subscriber);

                if (anchor != null && !anchor.IsDestroyed)
                {
                    if (anchor.buildingID != buildingID)
                        Debug.LogWarning<HelperBuildingNavMesh>("Watch: anchor block {0} belongs to building {1}, not {2} - anchor ignored",
                            anchor.net != null ? anchor.net.ID.Value : 0UL, anchor.buildingID, buildingID);
                    else if (!IsLiveAnchor(buildingID))
                        _anchors[buildingID] = anchor;
                }

                ApplyEnabled();
                _instance?.QueueAutoBuild(buildingID);
            }

            public static void Unwatch(uint buildingID, object subscriber)
            {
                if (subscriber == null) return;
                if (RemoveSubscriber(ResolveWatchID(buildingID), subscriber)) ApplyEnabled();
            }

            public static void UnwatchAll(object subscriber)
            {
                if (subscriber == null) return;
                var affected = Pool.Get<List<uint>>();
                foreach (var kv in _watch)
                    if (kv.Value.Contains(subscriber)) affected.Add(kv.Key);
                bool dropped = false;
                for (int i = 0; i < affected.Count; i++)
                    if (RemoveSubscriber(affected[i], subscriber)) dropped = true;
                Pool.FreeUnmanaged(ref affected);
                if (dropped) ApplyEnabled();
            }

            public static bool IsWatched(uint buildingID) => buildingID != 0 && _watch.ContainsKey(ResolveWatchID(buildingID));

            public static string DescribeSubscribers(out int count)
            {
                var seen = new HashSet<object>();
                var sb = new System.Text.StringBuilder();
                foreach (var subs in _watch.Values)
                    foreach (var s in subs)
                    {
                        if (!seen.Add(s)) continue;
                        if (sb.Length > 0) sb.Append(", ");
                        sb.Append(s is Plugin p ? p.Name : s.GetType().Name);
                    }
                count = seen.Count;
                return sb.ToString();
            }

            private static uint ResolveWatchID(uint buildingID)
            {
                if (_watch.ContainsKey(buildingID)) return buildingID;
                return _movedTo.TryGetValue(buildingID, out uint now) ? now : buildingID;
            }

            private static bool IsLiveAnchor(uint buildingID)
                => _anchors.TryGetValue(buildingID, out var anchor) && anchor != null && !anchor.IsDestroyed;

            private static bool RemoveSubscriber(uint buildingID, object subscriber)
            {
                if (!_watch.TryGetValue(buildingID, out var subs) || !subs.Remove(subscriber) || subs.Count > 0) return false;
                DropWatch(buildingID);
                return true;
            }

            private static void DropWatch(uint buildingID)
            {
                _watch.Remove(buildingID);
                _anchors.Remove(buildingID);
                if (_movedTo.Count > 0)
                {
                    var stale = Pool.Get<List<uint>>();
                    foreach (var kv in _movedTo)
                        if (kv.Value == buildingID) stale.Add(kv.Key);
                    for (int i = 0; i < stale.Count; i++) _movedTo.Remove(stale[i]);
                    Pool.FreeUnmanaged(ref stale);
                }
                var store = _instance;
                if (store == null) return;
                store.Dequeue(buildingID);
                store.Remove(buildingID);
            }

            private static void MoveWatch(uint from, uint to)
            {
                if (!_watch.TryGetValue(from, out var subs)) return;
                _watch.Remove(from);
                _anchors.TryGetValue(from, out var anchor);
                _anchors.Remove(from);

                if (_watch.TryGetValue(to, out var into))
                    foreach (var s in subs) into.Add(s);
                else
                    _watch[to] = into = subs;
                if (anchor != null && !anchor.IsDestroyed && !IsLiveAnchor(to)) _anchors[to] = anchor;

                _movedTo.Remove(to);
                var redirect = Pool.Get<List<uint>>();
                foreach (var kv in _movedTo)
                    if (kv.Value == from) redirect.Add(kv.Key);
                for (int i = 0; i < redirect.Count; i++) _movedTo[redirect[i]] = to;
                Pool.FreeUnmanaged(ref redirect);
                _movedTo[from] = to;

                var store = _instance;
                if (store != null && store._running)
                {
                    store.Dequeue(from);
                    store.Remove(from);
                    if (store._navs.TryGetValue(to, out var destinationNav))
                    {
                        InvalidateRebuild(destinationNav);
                        store._rebuildWhole.Add(to);
                        store.ArmDirtyTimer();
                    }
                    else store.QueueAutoBuild(to);
                }
            }

            private void CheckWatches()
            {
                if (_watch.Count == 0) return;
                _watchIdBuf.Clear();
                foreach (uint id in _watch.Keys) _watchIdBuf.Add(id);
                bool dropped = false;
                for (int i = 0; i < _watchIdBuf.Count; i++)
                {
                    uint id = _watchIdBuf[i];
                    if (!_watch.TryGetValue(id, out var subs)) continue;
                    if (DropUnloadedSubscribers(id, subs)) { dropped = true; continue; }

                    if (!_anchors.TryGetValue(id, out var anchor)) continue;
                    if (anchor == null || anchor.IsDestroyed) { _anchors.Remove(id); continue; }
                    uint now = anchor.buildingID;
                    if (now != 0 && now != id) MoveWatch(id, now);
                }
                if (dropped) ApplyEnabled();
            }

            private static bool DropUnloadedSubscribers(uint buildingID, HashSet<object> subs)
            {
                _watchSubBuf.Clear();
                foreach (var s in subs)
                    if (s is Plugin p && !p.IsLoaded) _watchSubBuf.Add(s);
                for (int i = 0; i < _watchSubBuf.Count; i++)
                {
                    Debug.LogWarning<HelperBuildingNavMesh>("plugin {0} was unloaded without UnwatchAll - its subscription to building {1} removed",
                        ((Plugin)_watchSubBuf[i]).Name, buildingID);
                    if (RemoveSubscriber(buildingID, _watchSubBuf[i])) return true;
                }
                return false;
            }

            private void DropUnwatched()
            {
                if (!_running) return;
                _dropBuf.Clear();
                foreach (uint id in _navs.Keys)
                    if (!_watch.ContainsKey(id)) _dropBuf.Add(id);
                for (int i = 0; i < _dropBuf.Count; i++) Remove(_dropBuf[i]);
                int freed = _dropBuf.Count;

                _dropBuf.Clear();
                for (int i = 0; i < _autoQueue.Count; i++)
                    if (!_watch.ContainsKey(_autoQueue[i])) _dropBuf.Add(_autoQueue[i]);
                for (int i = 0; i < _dropBuf.Count; i++) Dequeue(_dropBuf[i]);
            }

            #endregion

            #region Автосборка

            public static bool AutoBuild = false;
            public static int AutoBuildMinBlocks = 4;
            public static int AutoBuildMaxNavs = 200;
            public const float AutoBuildStep = 0.5f;
            public const float AutoBuildDelay = 6f;
            private const float AutoBuildScanDelay = 15f;

            private readonly List<uint> _autoQueue = new List<uint>();
            private readonly HashSet<uint> _autoQueued = new HashSet<uint>();
            private Timer _autoTimer;

            public void QueueAutoBuild(uint buildingID)
            {
                if (!_running || buildingID == 0) return;
                if (_navs.ContainsKey(buildingID)) return;
                if (!_watch.ContainsKey(buildingID) && AutoBuildMaxNavs > 0 && _navs.Count >= AutoBuildMaxNavs) return;
                if (!_autoQueued.Add(buildingID)) return;
                _autoQueue.Add(buildingID);
                ArmAutoTimer(AutoBuildDelay);
            }

            private void Dequeue(uint buildingID)
            {
                if (_autoQueued.Remove(buildingID)) _autoQueue.Remove(buildingID);
            }

            public int QueueAllBuildings()
            {
                if (!_running) return 0;
                int queued = 0, total = 0;
                foreach (var building in BuildingManager.server.buildingDictionary.Values)
                {
                    total++;
                    if (!HasEnoughBlocks(building)) continue;
                    int before = _autoQueue.Count;
                    QueueAutoBuild(building.ID);
                    if (_autoQueue.Count > before) queued++;
                }
                return queued;
            }

            private static bool HasEnoughBlocks(BuildingManager.Building building)
                => building != null && building.HasBuildingBlocks() && building.buildingBlocks.Count >= AutoBuildMinBlocks;

            private void ArmAutoTimer(float delay)
            {
                if (_autoTimer != null) return;
                _autoTimer = NPCsController.Instance?.timer.Once(delay, PumpAutoQueue);
            }

            private void PumpAutoQueue()
            {
                _autoTimer = null;
                int overLimit = 0;
                while (_autoQueue.Count > 0)
                {
                    uint id = _autoQueue[0];
                    _autoQueue.RemoveAt(0);
                    _autoQueued.Remove(id);

                    if (!_running) { ClearAutoQueue(); return; }
                    if (_navs.ContainsKey(id)) continue;
                    var building = BuildingManager.server.GetBuilding(id);
                    bool watched = _watch.ContainsKey(id);
                    if (watched)
                    {
                        if (building == null || !building.HasBuildingBlocks()) continue;
                    }
                    else
                    {
                        if (AutoBuildMaxNavs > 0 && _navs.Count >= AutoBuildMaxNavs) { overLimit++; continue; }
                        if (!HasEnoughBlocks(building)) continue;
                    }

                    var nav = QueueInitialRebuild(id, out string err);
                    if (nav == null)
                        Debug.LogWarning<HelperBuildingNavMesh>("queued build for building {0} ({1}) failed: {2}",
                            id, watched ? "watched" : "map scan", err);
                    break;
                }
                if (overLimit > 0)
                    Debug.LogWarning<HelperBuildingNavMesh>(
                        "map scan: {0} navmeshes built - limit reached (AutoBuildMaxNavs), {1} buildings without subscription dropped from the queue",
                        _navs.Count, overLimit);
                if (_autoQueue.Count > 0) ArmAutoTimer(AutoBuildStep);
            }

            private void ClearAutoQueue()
            {
                _autoQueue.Clear();
                _autoQueued.Clear();
                _autoTimer?.Destroy();
                _autoTimer = null;
            }

            public int DropGoneNavs()
            {
                _dropBuf.Clear();
                foreach (uint id in _navs.Keys)
                {
                    var building = BuildingManager.server.GetBuilding(id);
                    if (building == null || !building.HasBuildingBlocks()) _dropBuf.Add(id);
                }
                for (int i = 0; i < _dropBuf.Count; i++) Remove(_dropBuf[i]);
                return _dropBuf.Count;
            }

            private readonly List<uint> _dropBuf = new List<uint>();

            private const float DropGoneStep = 30f;

            private bool DropIfGone(uint buildingID, BuildingBlock removed)
            {
                var building = BuildingManager.server.GetBuilding(buildingID);
                if (building != null && building.buildingBlocks.Count > (building.buildingBlocks.Contains(removed) ? 1 : 0)) return false;
                if (!Remove(buildingID)) return false;
                return true;
            }

            #endregion

            #region Слежение за изменениями постройки

            public const float DirtyDelay = 1.2f;

            private readonly Dictionary<uint, HashSet<Vector2Int>> _dirtyTiles = new Dictionary<uint, HashSet<Vector2Int>>();

            private readonly HashSet<uint> _rebuildWhole = new HashSet<uint>();

            private Timer _dirtyTimer;

            public static void MarkDirty(uint buildingID, BuildingBlock changedBlock, bool added)
            {
                var store = _instance;
                if (store == null || !store._running || changedBlock == null) return;
                if (!store._navs.TryGetValue(buildingID, out var nav) || nav.Handle == IntPtr.Zero)
                {
                    if (added && (_watch.ContainsKey(buildingID) || AutoBuild)) store.QueueAutoBuild(buildingID);
                    return;
                }
                if (!added && store.DropIfGone(buildingID, changedBlock)) return;

                Bounds b = changedBlock.WorldSpaceBounds().ToBounds();

                if (added && !(nav.Bounds.Contains(b.min) && nav.Bounds.Contains(b.max)))
                {
                    InvalidateRebuild(nav);
                    store._rebuildWhole.Add(buildingID);
                    store.ArmDirtyTimer();
                    return;
                }

                if (!nav.Bounds.Intersects(b)) return;
                store.MarkTilesInBounds(nav, b);
                store.ArmDirtyTimer();
            }

            public static bool AffectsBuildingNav(BaseEntity entity)
                => entity is DecayEntity || entity is BaseLadder;

            public static void NoteGeometryChanged(BaseEntity entity)
            {
                var store = _instance;
                if (store == null || !store._running || store._navs.Count == 0) return;
                if (entity == null || entity.isClient) return;

                if (!AffectsBuildingNav(entity)) return;

                Bounds b = entity.WorldSpaceBounds().ToBounds();
                if (HasHurtZone(entity)) b.Expand(HurtZonePad * 2f);
                bool any = false;
                foreach (var nav in store._navs.Values)
                {
                    if (nav.Handle == IntPtr.Zero || !nav.Bounds.Intersects(b)) continue;
                    store.MarkTilesInBounds(nav, b);
                    any = true;
                }
                if (any) store.ArmDirtyTimer();
            }

            public int TouchAllTiles()
            {
                foreach (var nav in _navs.Values)
                {
                    if (nav.Handle == IntPtr.Zero) continue;
                    MarkTilesInBounds(nav, nav.Bounds);
                }
                _dirtyTimer?.Destroy();
                _dirtyTimer = null;
                return RebuildDirtyTiles();
            }

            private void ArmDirtyTimer()
            {
                _dirtyTimer?.Destroy();
                _dirtyTimer = NPCsController.Instance?.timer.Once(DirtyDelay, () => RebuildDirtyTiles());
            }

            private void MarkTilesInBounds(BuildingNav nav, Bounds b)
            {
                InvalidateRebuild(nav);
                if (!_dirtyTiles.TryGetValue(nav.BuildingID, out var set))
                    _dirtyTiles[nav.BuildingID] = set = new HashSet<Vector2Int>();

                Bounds expanded = ExpandTileBounds(nav, b);
                float side = nav.Params.tileSize * nav.Params.cellSize;

                int x0 = Mathf.FloorToInt((expanded.min.x - nav.Bounds.min.x) / side);
                int x1 = Mathf.FloorToInt((expanded.max.x - nav.Bounds.min.x) / side);
                int y0 = Mathf.FloorToInt((expanded.min.z - nav.Bounds.min.z) / side);
                int y1 = Mathf.FloorToInt((expanded.max.z - nav.Bounds.min.z) / side);

                for (int ty = Mathf.Max(0, y0); ty <= Mathf.Min(nav.TileNum.y - 1, y1); ty++)
                    for (int tx = Mathf.Max(0, x0); tx <= Mathf.Min(nav.TileNum.x - 1, x1); tx++)
                        set.Add(new Vector2Int(tx, ty));
            }

            private const double RebuildFrameBudgetMs = 3d;
            private const float RebuildStepDelay = 0.01f;
            private readonly Queue<uint> _rebuildQueue = new Queue<uint>();
            private readonly HashSet<uint> _rebuildQueued = new HashSet<uint>();
            private Timer _rebuildStepTimer;
            private Vector3[] _rebuildVerts = new Vector3[8192];
            private int[] _rebuildTris = new int[24576];
            private RebuildJob _rebuildJob;

            private sealed class RebuildJob
            {
                public BuildingNav Target, Staged;
                public int Revision;
                public BuildReport Report;
                public IEnumerator Steps;
                public double CpuMs;
                public bool Published;
                public readonly Dictionary<long, int> EdgeUse = new Dictionary<long, int>();
                public readonly List<(Vector3 mid, Vector3 outward)> Edges = new List<(Vector3, Vector3)>();
                public readonly HashSet<long> Taken = new HashSet<long>();
            }

            private static void InvalidateRebuild(BuildingNav nav) => nav.GeometryRevision++;

            private void CancelRebuild(uint buildingID)
            {
                RebuildJob job = _rebuildJob;
                if (job == null || job.Target.BuildingID != buildingID) return;
                _rebuildJob = null;
                (job.Steps as IDisposable)?.Dispose();
                DestroyNav(job.Staged);
            }

            private void QueueRebuild(uint id)
            {
                if (_rebuildQueued.Add(id)) _rebuildQueue.Enqueue(id);
            }

            private int RebuildDirtyTiles()
            {
                _dirtyTimer = null;
                foreach (uint id in _rebuildWhole) QueueRebuild(id);
                int tiles = 0;
                foreach (var pair in _dirtyTiles)
                {
                    tiles += pair.Value.Count;
                    QueueRebuild(pair.Key);
                }
                _rebuildWhole.Clear();
                _dirtyTiles.Clear();
                ArmRebuildStep();
                return tiles;
            }

            private void ArmRebuildStep()
            {
                if (!_running || _rebuildStepTimer != null) return;
                if (_rebuildJob == null && _rebuildQueue.Count == 0) return;
                _rebuildStepTimer = NPCsController.Instance?.timer.Once(RebuildStepDelay, AdvanceRebuild);
            }

            private void AdvanceRebuild()
            {
                _rebuildStepTimer = null;
                if (!_running) return;
                long frameStart = System.Diagnostics.Stopwatch.GetTimestamp();
                double elapsed;
                do
                {
                    if (_rebuildJob != null && (_rebuildJob.Target.GeometryRevision != _rebuildJob.Revision
                        || !_navs.TryGetValue(_rebuildJob.Target.BuildingID, out var current)
                        || !ReferenceEquals(current, _rebuildJob.Target)))
                        CancelRebuild(_rebuildJob.Target.BuildingID);
                    if (_rebuildJob == null)
                    {
                        while (_rebuildQueue.Count > 0)
                        {
                            uint id = _rebuildQueue.Dequeue();
                            if (!_rebuildQueued.Remove(id) || _dirtyTiles.ContainsKey(id) || _rebuildWhole.Contains(id)) continue;
                            if (!_navs.TryGetValue(id, out var target) || target.Handle == IntPtr.Zero) continue;
                            var job = new RebuildJob { Target = target, Revision = target.GeometryRevision,
                                Report = new BuildReport { BuildingID = id } };
                            job.Steps = BuildRebuildStages(job);
                            _rebuildJob = job;
                            break;
                        }
                        if (_rebuildJob == null) break;
                    }
                    RebuildJob active = _rebuildJob;
                    long sliceStart = System.Diagnostics.Stopwatch.GetTimestamp();
                    bool more = false;
                    try { more = active.Steps.MoveNext(); }
                    catch (Exception e)
                    {
                        active.Report.Notes.Add("staged rebuild failed: " + e.Message);
                        Debug.LogWarning<HelperBuildingNavMesh>("building {0} staged rebuild failed: {1}", active.Target.BuildingID, e);
                    }
                    double sliceMs = (System.Diagnostics.Stopwatch.GetTimestamp() - sliceStart) * 1000d / System.Diagnostics.Stopwatch.Frequency;
                    active.CpuMs += sliceMs;
                    if (!more)
                    {
                        active.Report.BuildMs = (long)Math.Ceiling(active.CpuMs);
                        _reports[active.Target.BuildingID] = active.Report;
                        if (!active.Published)
                            Debug.LogWarning<HelperBuildingNavMesh>(active.Target.Empty
                                ? "building {0} rebuild was not published; navigation remains unavailable"
                                : "building {0} rebuild was not published; the previous navmesh stays in use", active.Target.BuildingID);
                        CancelRebuild(active.Target.BuildingID);
                    }
                    elapsed = (System.Diagnostics.Stopwatch.GetTimestamp() - frameStart) * 1000d / System.Diagnostics.Stopwatch.Frequency;
                } while (elapsed < RebuildFrameBudgetMs);
                ArmRebuildStep();
            }

            private IEnumerator BuildRebuildStages(RebuildJob job)
            {
                uint id = job.Target.BuildingID;
                var building = BuildingManager.server.GetBuilding(id);
                if (building == null || !building.HasBuildingBlocks()) yield break;
                var nav = new BuildingNav { BuildingID = id, Params = MakeParams(), Bounds = CalcBounds(building) };
                job.Staged = nav;
                BuildReport report = job.Report;
                report.Bounds = nav.Bounds;
                nav.Handle = RecastWrapper.CreateEmptyNavMesh(in nav.Params, nav.Bounds.min, nav.Bounds.max);
                if (!nav.IsValid) yield break;
                nav.TileNum = CalcTileNum(nav);
                report.TileNum = nav.TileNum;
                yield return null;
                if (BuildMesh)
                    for (int ty = 0; ty < nav.TileNum.y; ty++)
                        for (int tx = 0; tx < nav.TileNum.x; tx++)
                        {
                            IEnumerator tileSteps = BuildTileStages(nav, tx, ty, report);
                            try { while (tileSteps.MoveNext()) yield return null; }
                            finally { (tileSteps as IDisposable)?.Dispose(); }
                        }
                if (BuildMesh && (report.TilesBuilt == 0 || report.TilesFailed > 0)) yield break;
                CollectDoorsOfBuilding(nav, building);
                AssertHatchStates(nav, report);
                AssertDoorApertures(nav);
                yield return null;
                if (BuildLinks)
                {
                    SyncDoors(nav);
                    report.LinksBuilt = true;
                    ComputeDoorLinks(nav, report);
                    yield return null;
                    ComputeClimbLinks(nav, report);
                    yield return null;
                    ComputeEntries(nav, report);
                    yield return null;
                    for (int ty = 0; ty < nav.TileNum.y; ty++)
                        for (int tx = 0; tx < nav.TileNum.x; tx++)
                        {
                            if (GetTilePolys(nav, tx, ty, out int polys))
                                for (int p = 0; p < polys; p++)
                                {
                                    if (PolyAreaBuffer[p] == DoorApertureArea) continue;
                                    ForEachPolyEdge(p, (a, b) =>
                                    {
                                        long key = EdgeKey(a, b);
                                        job.EdgeUse.TryGetValue(key, out int count);
                                        job.EdgeUse[key] = count + 1;
                                    });
                                }
                            yield return null;
                        }
                    for (int ty = 0; ty < nav.TileNum.y; ty++)
                        for (int tx = 0; tx < nav.TileNum.x; tx++)
                        {
                            if (GetTilePolys(nav, tx, ty, out int polys))
                                for (int p = 0; p < polys; p++)
                                {
                                    if (PolyAreaBuffer[p] == DoorApertureArea) continue;
                                    Vector3 centre = PolyCentre(p);
                                    ForEachPolyEdge(p, (a, b) =>
                                    {
                                        if (job.EdgeUse.TryGetValue(EdgeKey(a, b), out int used) && used != 1) return;
                                        Vector3 mid = (a + b) * 0.5f;
                                        Vector3 outward = mid - centre; outward.y = 0f;
                                        if (outward.sqrMagnitude < 0.0001f) return;
                                        job.Edges.Add((mid, outward.normalized));
                                        report.JumpEdges++;
                                    });
                                }
                            yield return null;
                        }
                    for (int i = 0; i < job.Edges.Count && nav.Jumps.Count < JumpMaxLinks; i++)
                    {
                        Vector3 mid = job.Edges[i].mid;
                        long cell = CellKey(mid, JumpEdgeCell);
                        if (job.Taken.Contains(cell)) report.JumpSkipDuplicate++;
                        else if (TryFindJumpLanding(nav, mid, job.Edges[i].outward, out Vector3 landing, out float gap, report))
                        {
                            job.Taken.Add(cell);
                            float rise = landing.y - mid.y;
                            var from = new RecastNode(mid, NodeRole.Floor);
                            var to = new RecastNode(landing, NodeRole.Floor);
                            float cost = gap + Mathf.Abs(rise);
                            from.LinkTo(to, NodeHint.Jump, cost);
                            bool twoWay = -rise <= JumpMaxRise + JumpRiseSlack && (rise > -JumpSameLevelRise || HasStandingRoom(landing));
                            if (twoWay) to.LinkTo(from, NodeHint.Jump, cost);
                            nav.Jumps.Add(new JumpLink { From = from, To = to, Gap = gap, Rise = rise, TwoWay = twoWay });
                        }
                        yield return null;
                    }
                }
                bool hatchChanged;
                do
                {
                    AssertHatchStates(nav, null);
                    AssertDoorApertures(nav);
                    nav.Route.Version = -1;
                    IEnumerator warm = WarmRouteMemo(nav);
                    try { while (warm.MoveNext()) yield return null; }
                    finally { (warm as IDisposable)?.Dispose(); }
                    hatchChanged = false;
                    foreach (var door in nav.Doors.Values)
                        if (door.IsHatch && door.Gate?.LinkedDoor != null && !door.Gate.LinkedDoor.IsDestroyed
                            && door.Gate.LinkedDoor.IsOpen() != door.IsOpen) { hatchChanged = true; break; }
                } while (hatchChanged);
                if (job.Target.GeometryRevision != job.Revision) yield break;
                BuildingNav targetNav = job.Target;
                IntPtr previousHandle = targetNav.Handle;
                targetNav.Handle = nav.Handle;
                nav.Handle = previousHandle;
                targetNav.Bounds = nav.Bounds;
                targetNav.Params = nav.Params;
                targetNav.TileNum = nav.TileNum;
                targetNav.Doors.Clear(); foreach (var pair in nav.Doors) targetNav.Doors.Add(pair.Key, pair.Value);
                targetNav.FloorPoints.Clear(); foreach (var pair in nav.FloorPoints) targetNav.FloorPoints.Add(pair.Key, pair.Value);
                targetNav.Entries.Clear(); targetNav.Entries.AddRange(nav.Entries);
                targetNav.Climbs.Clear(); targetNav.Climbs.AddRange(nav.Climbs);
                targetNav.Jumps.Clear(); targetNav.Jumps.AddRange(nav.Jumps);
                targetNav.Exits.Clear(); targetNav.ExitsVersion = -1;
                targetNav.Route.Version = -1;
                targetNav.FlagsStamp++;
                targetNav.Version++;
                AdoptRouteMemo(nav, targetNav);
                targetNav.Empty = false;
                job.Published = true;
                OnBuildingNavRebuilt?.Invoke(id);
            }

            #endregion

            #region Конвейер сборки

            public static NavMeshBuildParams MakeParams()
            {
                var p = new NavMeshBuildParams(true);
                p.cellSize = CellSize;
                p.cellHeight = CellHeight;
                p.agentHeight = EffectiveAgentHeight;
                p.agentRadius = AgentRadius;
                p.agentMaxClimb = AgentMaxClimb;
                p.agentMaxSlope = AgentMaxSlope;
                p.tileSize = TileVoxels;
                p.partitionType = PartitionType;
                p.maxNodes = MaxNodes;
                p.minRegionSizeMeters = MinRegionSizeMeters;
                p.filterLowHangingObstacles = FilterLowHangingObstacles;
                p.filterLedgeSpans = FilterLedgeSpans;
                p.filterWalkableLowHeightSpans = FilterWalkableLowHeightSpans;
                p.buildDetailMesh = BuildDetailMesh;
                return p;
            }

            public BuildingNav BuildNavFor(uint buildingID, out string err) => BuildNavFor(buildingID, out err, out _);

            public BuildingNav BuildNavFor(uint buildingID, out string err, out BuildReport report)
            {
                err = null;
                report = new BuildReport { BuildingID = buildingID };
                if (!_running)
                {
                    err = DisabledText;
                    return null;
                }

                var building = BuildingManager.server.GetBuilding(buildingID);
                if (building == null || !building.HasBuildingBlocks())
                {
                    err = $"building {buildingID} not found";
                    return null;
                }

                CancelRebuild(buildingID);
                _rebuildQueued.Remove(buildingID);
                _rebuildWhole.Remove(buildingID);
                if (_navs.TryGetValue(buildingID, out var old)) { DestroyNav(old); _navs.Remove(buildingID); }

                var sw = System.Diagnostics.Stopwatch.StartNew();

                var nav = new BuildingNav { BuildingID = buildingID, Params = MakeParams(), Bounds = CalcBounds(building) };
                report.Bounds = nav.Bounds;

                try { nav.Handle = RecastWrapper.CreateEmptyNavMesh(in nav.Params, nav.Bounds.min, nav.Bounds.max); }
                catch (Exception e)
                {
                    err = "native Recast is unavailable (" + e.GetType().Name + ": " + e.Message + ")";
                    return null;
                }
                if (!nav.IsValid) { err = "CreateEmptyNavMesh = 0"; return null; }

                nav.TileNum = CalcTileNum(nav);
                report.TileNum = nav.TileNum;
                if (BuildMesh)
                    for (int ty = 0; ty < nav.TileNum.y; ty++)
                        for (int tx = 0; tx < nav.TileNum.x; tx++)
                            BuildTile(nav, tx, ty, report);

                sw.Stop();
                report.BuildMs = sw.ElapsedMilliseconds;

                if (BuildMesh && report.TilesBuilt == 0)
                {
                    DestroyNav(nav);
                    err = $"no tile was built (empty {report.TilesEmpty}, failed {report.TilesFailed})";
                    return null;
                }

                _navs[buildingID] = nav;
                _reports[buildingID] = report;
                nav.Version++;
                _dirtyTiles.Remove(buildingID);

                CollectDoorsOfBuilding(nav, building);

                AssertHatchStates(nav, report);
                AssertDoorApertures(nav);

                if (BuildLinks) ComputeLinks(nav, report);

                OnBuildingNavRebuilt?.Invoke(buildingID);
                return nav;
            }

            public int RebuildTiles(BuildingNav nav, ICollection<Vector2Int> tiles, out BuildReport report)
            {
                report = new BuildReport { BuildingID = nav?.BuildingID ?? 0u };
                if (nav == null || !nav.IsValid || tiles == null || tiles.Count == 0) return 0;

                report.Bounds = nav.Bounds;
                report.TileNum = nav.TileNum;

                int done = 0;
                foreach (var coord in tiles)
                {
                    bool removed = false;
                    try { removed = RecastWrapper.RemoveTileFromNavMesh(nav.Handle, coord.x, coord.y); }
                    catch (Exception e) { report.Notes.Add($"RemoveTileFromNavMesh({coord.x},{coord.y}): {e.Message}"); }
                    if (!removed) report.Notes.Add($"tile ({coord.x},{coord.y}) was not removed before the rebuild - overlaps are possible");

                    BuildTile(nav, coord.x, coord.y, report);
                    done++;
                }

                AssertHatchStates(nav, report);
                AssertDoorApertures(nav);

                if (BuildLinks) ComputeLinks(nav, report);

                nav.Version++;
                OnBuildingNavRebuilt?.Invoke(nav.BuildingID);
                return done;
            }

            public BuildReport ComputeLinks(BuildingNav nav)
            {
                var report = new BuildReport { BuildingID = nav?.BuildingID ?? 0u };
                ComputeLinks(nav, report);
                if (nav != null && nav.IsValid)
                {
                    nav.Version++;
                    OnBuildingNavRebuilt?.Invoke(nav.BuildingID);
                }
                return report;
            }

            private const float HatchWatchStep = 1f;

            private static readonly ulong[] _gateRefBuf = new ulong[64];
            private static readonly Vector3[] _gateOwnerBuf = new Vector3[1];

            private void WatchHatches()
            {
                foreach (var nav in _navs.Values)
                {
                    if (!nav.IsValid) continue;
                    foreach (var d in nav.Doors.Values)
                    {
                        if (!d.IsHatch) continue;
                        Door door = d.Gate != null ? d.Gate.LinkedDoor : null;
                        if (door == null || door.IsDestroyed || door.IsOpen() == d.IsOpen) continue;
                        int polys = AssertHatchState(nav, d, door);
                    }
                }
            }

            private static int AssertHatchState(BuildingNav nav, DoorLink d, Door door)
            {
                d.IsOpen = door.IsOpen();
                return SetHatchWalk(nav, d, !d.IsOpen);
            }

            private void AssertHatchStates(BuildingNav nav, BuildReport report)
            {
                if (nav == null || !nav.IsValid) return;
                foreach (var d in nav.Doors.Values)
                {
                    if (!d.IsHatch) continue;
                    Door door = d.Gate != null ? d.Gate.LinkedDoor : null;
                    if (door == null || door.IsDestroyed) continue;
                    EnsureHatchShape(d, door);
                    AssertHatchState(nav, d, door);
                    if (report == null) continue;
                    if (d.HasOpening) report.HatchesGated++;
                    else
                    {
                        report.HatchesNoOpening++;
                        if (d.CapOutline == null) report.HatchesNoFrame++;
                    }
                }
            }

            private void SetHatchesWalkable(BuildingNav nav, bool walkable)
            {
                if (nav == null || !nav.IsValid) return;
                foreach (var d in nav.Doors.Values)
                {
                    if (!d.IsHatch) continue;
                    Door door = d.Gate != null ? d.Gate.LinkedDoor : null;
                    if (door == null || door.IsDestroyed) continue;
                    EnsureHatchShape(d, door);
                    SetHatchWalk(nav, d, walkable);
                }
            }

            private static int SetHatchWalk(BuildingNav nav, DoorLink d, bool walkable)
            {
                if (!d.IsHatch || !d.HasOpening || nav == null || !nav.IsValid) return -1;
                nav.FlagsStamp++;
                ushort walk = RecastWrapper.POLYFLAGS_WALK;
                Vector3 center = d.GateBoxCenter, half = d.GateBoxHalf;
                RecastWrapper.SetPolyFlagsInObb(nav.Handle, in center, in half, d.GateBoxAxis.x, d.GateBoxAxis.y, RecastWrapper.RC_AREA_DOOR,
                    walkable ? walk : (ushort)0, walkable ? (ushort)0 : walk, in center, _gateOwnerBuf, 0, _gateRefBuf, _gateRefBuf.Length,
                    out int refCount);
                return refCount;
            }

            private void AssertDoorApertures(BuildingNav nav)
            {
                if (nav == null || !nav.IsValid || !BuildMesh) return;
                int reclosed = RecastWrapper.ResetPolyFlagsForArea(nav.Handle, DoorApertureArea, DoorClosedSet, DoorClosedClear);
                int walls = 0, gated = 0, byLeaf = 0, polys = 0, noPolys = 0, overVoid = 0, leaking = 0;
                foreach (var d in nav.Doors.Values)
                {
                    if (d.IsHatch) continue;
                    Door door = d.Gate != null ? d.Gate.LinkedDoor : null;
                    if (door == null || door.IsDestroyed) continue;
                    walls++;
                    if (!DoorGateBox || !d.HasOpening) continue;
                    gated++;
                    if (d.OpeningByLeaf) byLeaf++;
                    int inBox = CountDoorAperturePolys(nav, d);
                    if (inBox > 0) polys += inBox;
                    else
                    {
                        noPolys++;
                        if (!DoorFaceHasFloor(d, door, 1) || !DoorFaceHasFloor(d, door, -1)) overVoid++;
                        else if (_doorNoPolysLogged.Add(d.DoorId))
                            Debug.LogWarning<HelperBuildingNavMesh>("building={0}: door {1} net={2} - no doorway polygons although there is floor on both faces (gate {3}, doorway volume centre {4})",
                                nav.BuildingID, door.ShortPrefabName, d.DoorId, d.Position, d.GateBoxCenter);
                    }
                    if (!DoorwayLeaks(nav, d, out float leakPath, out float leakStraight)) continue;
                    leaking++;
                    if (_doorLeakLogged.Add(d.DoorId))
                        Debug.LogWarning<HelperBuildingNavMesh>("building={0}: door {1} net={2} - the navmesh path goes straight through the doorway: {3:0.00} m between points {4:0.00} m apart on its sides - the doorway volume did not close it",
                            nav.BuildingID, door.ShortPrefabName, d.DoorId, leakPath, leakStraight);
                }
            }

            private static bool DoorFaceHasFloor(DoorLink d, Door door, int face)
            {
                var normal = new Vector3(-d.GateBoxAxis.y, 0f, d.GateBoxAxis.x);
                float off = d.GateBoxHalf.z - HatchGatePad + DoorLeakProbeOut;
                Vector3 from = new Vector3(d.GateBoxCenter.x, d.Position.y + 0.5f, d.GateBoxCenter.z) + normal * (off * face);
                int n = Physics.RaycastNonAlloc(from, Vector3.down, _doorFloorHits, 0.5f + DoorBaseSlack, GeomMask, QueryTriggerInteraction.Ignore);
                for (int i = 0; i < n; i++)
                {
                    Collider c = _doorFloorHits[i].collider;
                    if (c != null && !OwnDoorPart(c, door)) return true;
                }
                return false;
            }

            private static readonly HashSet<ulong> _doorNoPolysLogged = new HashSet<ulong>();

            private static int CountDoorAperturePolys(BuildingNav nav, DoorLink d)
            {
                if (d.IsHatch || !d.HasOpening || nav == null || !nav.IsValid) return -1;
                Vector3 center = d.GateBoxCenter, half = d.GateBoxHalf;
                RecastWrapper.SetPolyFlagsInObb(nav.Handle, in center, in half, d.GateBoxAxis.x, d.GateBoxAxis.y, DoorApertureArea,
                    DoorClosedSet, DoorClosedClear, in center, _gateOwnerBuf, 0, _gateRefBuf, _gateRefBuf.Length, out int refCount);
                return refCount;
            }

            private static bool DoorwayLeaks(BuildingNav nav, DoorLink d, out float path, out float straight)
            {
                path = straight = 0f;
                if (!d.HasOpening || d.Gate == null || nav == null || !nav.IsValid) return false;
                Vector3 along = new Vector3(d.GateBoxAxis.x, 0f, d.GateBoxAxis.y);
                Vector3 normal = new Vector3(-along.z, 0f, along.x);
                float off = d.GateBoxHalf.z - HatchGatePad + DoorLeakProbeOut;
                Vector3 mid = new Vector3(d.GateBoxCenter.x, d.Position.y, d.GateBoxCenter.z);
                Vector3 a = mid + normal * off, b = mid - normal * off;
                Vector3 extents = new Vector3(DoorLeakProbeOut, AgentMaxClimb + 0.1f, DoorLeakProbeOut);
                if (!RecastWrapper.SamplePosition(nav.Handle, in a, in extents, out Vector3 sa, out ulong startRef, includeGatedDoorPolys: 0, allowNpcDoors: 0)
                    || sa == Vector3.zero || startRef == 0UL) return false;
                if (!RecastWrapper.SamplePosition(nav.Handle, in b, in extents, out Vector3 sb, out _, includeGatedDoorPolys: 0, allowNpcDoors: 0)
                    || sb == Vector3.zero) return false;
                straight = Vector3.Distance(sa, sb);

                DtStatus status = RecastWrapper.FindPath(nav.Handle, ref startRef, in sa, in sb, _pathBuf, out int len,
                    _pathPolyBuf, out _, PathIterations, allowNpcDoors: 0);
                if (((uint)status & (uint)DtStatus.Failure) != 0u || len <= 0) return false;
                if ((status & DtStatus.PartialResult) == DtStatus.PartialResult
                    || (_pathBuf[len - 1] - sb).sqrMagnitude > DoorLeakProbeOut * DoorLeakProbeOut) return false;
                for (int i = 1; i < len; i++) path += Vector3.Distance(_pathBuf[i - 1], _pathBuf[i]);
                return path <= straight + DoorLeakSlack;
            }

            private static readonly HashSet<ulong> _doorLeakLogged = new HashSet<ulong>();

            private static bool IsWindowInsert(BaseEntity insert)
            {
                if (insert == null || insert.IsDestroyed) return false;
                string name = insert.ShortPrefabName ?? string.Empty;
                return name.Contains("bars") || name.Contains("glass") || name.Contains("window.paintable");
            }

            public static BuildingBlock FindWindowOfInsert(BaseEntity insert, uint buildingID)
            {
                if (!IsWindowInsert(insert)) return null;
                BaseEntity parent = insert.GetParentEntity();
                if (parent != null) return parent is BuildingBlock block && IsWindowBlock(block) ? block : null;
                var building = BuildingManager.server.GetBuilding(buildingID);
                if (building == null || building.buildingBlocks == null) return null;

                Vector3 position = insert.transform.position;
                BuildingBlock nearest = null;
                float nearestDistance = float.PositiveInfinity;
                foreach (BuildingBlock window in building.buildingBlocks)
                {
                    if (!IsWindowBlock(window)) continue;
                    Vector3 delta = position - window.transform.position;
                    if (delta.x * delta.x + delta.z * delta.z > 0.6f * 0.6f || Mathf.Abs(delta.y) > 2f) continue;
                    float distance = delta.sqrMagnitude;
                    if (distance >= nearestDistance) continue;
                    nearest = window;
                    nearestDistance = distance;
                }
                return nearest;
            }

            public static bool IsWindowBlock(BuildingBlock block)
            {
                if (block == null || block.IsDestroyed) return false;
                string name = block.ShortPrefabName ?? string.Empty;
                return name.Contains("window") && !name.Contains("bars") && !name.Contains("glass");
            }

            private void ComputeLinks(BuildingNav nav, BuildReport report)
            {
                if (nav == null || !nav.IsValid) return;
                SyncDoors(nav);
                nav.Jumps.Clear();
                report.LinksBuilt = true;
                ComputeDoorLinks(nav, report);
                ComputeClimbLinks(nav, report);
                ComputeEntries(nav, report);
                ComputeJumpLinks(nav, report);
            }

            private static Bounds CalcBounds(BuildingManager.Building building)
            {
                var blocks = building.buildingBlocks;
                Vector3 min = new Vector3(float.MaxValue, float.MaxValue, float.MaxValue);
                Vector3 max = new Vector3(float.MinValue, float.MinValue, float.MinValue);

                for (int i = 0; i < blocks.Count; i++)
                {
                    var b = blocks[i];
                    if (b == null) continue;
                    Bounds wb = b.WorldSpaceBounds().ToBounds();
                    min = Vector3.Min(min, wb.min);
                    max = Vector3.Max(max, wb.max);
                }

                min -= new Vector3(BuildingPad, 0f, BuildingPad);
                max += new Vector3(BuildingPad, HeightPadUp, BuildingPad);

                if (IncludeTerrain)
                {
                    float lowest = min.y;
                    var probes = new[]
                    {
                        new Vector3(min.x, 0f, min.z), new Vector3(max.x, 0f, min.z),
                        new Vector3(min.x, 0f, max.z), new Vector3(max.x, 0f, max.z),
                        new Vector3((min.x + max.x) * 0.5f, 0f, (min.z + max.z) * 0.5f)
                    };
                    for (int i = 0; i < probes.Length; i++)
                    {
                        float h = TerrainMeta.HeightMap != null ? TerrainMeta.HeightMap.GetHeight(probes[i]) : min.y;
                        if (h < lowest) lowest = h;
                    }
                    min.y = lowest - HeightPadDown;
                }
                else
                {
                    min.y -= HeightPadDown;
                }

                if (!float.IsNaN(ClipMinY)) min.y = Mathf.Max(min.y, ClipMinY);
                if (!float.IsNaN(ClipMaxY)) max.y = Mathf.Min(max.y, ClipMaxY);

                return new Bounds((min + max) * 0.5f, max - min);
            }

            public static Vector2Int CalcTileNum(BuildingNav nav)
            {
                int cx = (int)((nav.Bounds.max.x - nav.Bounds.min.x) / nav.Params.cellSize + 0.5f);
                int cz = (int)((nav.Bounds.max.z - nav.Bounds.min.z) / nav.Params.cellSize + 0.5f);
                int x = (int)(((float)cx + nav.Params.tileSize - 1f) / nav.Params.tileSize);
                int y = (int)(((float)cz + nav.Params.tileSize - 1f) / nav.Params.tileSize);
                return new Vector2Int(Mathf.Max(1, x), Mathf.Max(1, y));
            }

            public static Bounds CalcTileBounds(BuildingNav nav, int tx, int ty)
            {
                float side = nav.Params.tileSize * nav.Params.cellSize;
                Vector3 lo = new Vector3(nav.Bounds.min.x + tx * side, nav.Bounds.min.y, nav.Bounds.min.z + ty * side);
                Vector3 hi = new Vector3(nav.Bounds.min.x + (tx + 1) * side, nav.Bounds.max.y, nav.Bounds.min.z + (ty + 1) * side);
                return new Bounds((lo + hi) * 0.5f, hi - lo);
            }

            public static Bounds ExpandTileBounds(BuildingNav nav, Bounds b)
            {
                float border = Mathf.Max(BorderMeters(nav.Params.agentRadius, nav.Params.cellSize),
                                         BorderMeters(WorldAgentRadius, WorldCellSize));
                b.min -= new Vector3(border, 0f, border);
                b.max += new Vector3(border, 0f, border);
                return b;
            }

            private static float BorderMeters(float agentRadius, float cellSize)
                => (Mathf.CeilToInt(agentRadius / cellSize) + 3) * cellSize;

            private const float WorldAgentRadius = 0.5f;
            private const float WorldCellSize = 1f / 3f;

            private IEnumerator BuildTileStages(BuildingNav nav, int tx, int ty, BuildReport report)
            {
                Bounds tileBounds = CalcTileBounds(nav, tx, ty);
                Bounds geomBounds = ExpandTileBounds(nav, tileBounds);

                Vector3 gmin = Vector3.Max(geomBounds.min, nav.Bounds.min);
                Vector3 gmax = Vector3.Min(geomBounds.max, nav.Bounds.max);
                if (gmax.x <= gmin.x || gmax.z <= gmin.z) { report.TilesEmpty++; yield break; }
                geomBounds.SetMinMax(gmin, gmax);

                DropDoorsInBounds(nav, tileBounds);

                _verts.Clear();
                _tris.Clear();
                CollectGeometry(nav, geomBounds, _verts, _tris, report);
                ClipGeometryByHeight(_verts, _tris);
                if (_verts.Count == 0 || _tris.Count < 3)
                {
                    report.TilesEmpty++;
                    report.Notes.Add($"[tile {tx},{ty}] empty: no geometry ({_verts.Count} verts, {_tris.Count / 3} tris)");
                    yield break;
                }

                report.Verts += _verts.Count;
                report.Tris += _tris.Count / 3;

                for (int i = 0; i + 2 < _tris.Count; i += 3)
                {
                    Vector3 a = _verts[_tris[i]], b = _verts[_tris[i + 1]], c = _verts[_tris[i + 2]];
                    Vector3 n = Vector3.Cross(b - a, c - a);
                    if (n.sqrMagnitude < 1e-8f) continue;
                    float ny = n.normalized.y;
                    if (Mathf.Abs(ny) < 0.7f) continue;
                    int y = Mathf.RoundToInt((a.y + b.y + c.y) / 3f);
                    if (ny > 0f)
                    {
                        report.FlatTrisByY[y] = report.FlatTrisByY.TryGetValue(y, out int u) ? u + 1 : 1;
                        RememberFloorPoint(nav, (a + b + c) / 3f);
                    }
                    else report.DownTrisByY[y] = report.DownTrisByY.TryGetValue(y, out int d) ? d + 1 : 1;
                }

                int vertexCount = _verts.Count, indexCount = _tris.Count;
                if (_rebuildVerts.Length < vertexCount) _rebuildVerts = new Vector3[Mathf.NextPowerOfTwo(vertexCount)];
                if (_rebuildTris.Length < indexCount) _rebuildTris = new int[Mathf.NextPowerOfTwo(indexCount)];
                Vector3[] ownedVerts = _rebuildVerts;
                int[] ownedTris = _rebuildTris;
                _verts.CopyTo(ownedVerts);
                _tris.CopyTo(ownedTris);

                float loY = float.MaxValue, hiY = float.MinValue;
                for (int i = 0; i < _verts.Count; i++)
                {
                    float y = _verts[i].y;
                    if (y < loY) loY = y;
                    if (y > hiY) hiY = y;
                }
                if (loY > hiY) { report.TilesEmpty++; yield break; }

                float ch = nav.Params.cellHeight;
                loY -= ch * 2f;
                hiY += ch * 2f;
                loY = nav.Bounds.min.y + Mathf.Floor((loY - nav.Bounds.min.y) / ch) * ch;
                if (Mathf.CeilToInt((hiY - loY) / ch) > MaxSpanHeight) { report.TilesTooTall++; report.TilesFailed++; yield break; }

                var vertPin = default(System.Runtime.InteropServices.GCHandle);
                var triPin = default(System.Runtime.InteropServices.GCHandle);

                IntPtr hf = IntPtr.Zero, chf = IntPtr.Zero, pm = IntPtr.Zero, dm = IntPtr.Zero, data = IntPtr.Zero;
                try
                {
                    yield return null;
                    vertPin = System.Runtime.InteropServices.GCHandle.Alloc(ownedVerts, System.Runtime.InteropServices.GCHandleType.Pinned);
                    triPin = System.Runtime.InteropServices.GCHandle.Alloc(ownedTris, System.Runtime.InteropServices.GCHandleType.Pinned);
                    IntPtr vp = vertPin.AddrOfPinnedObject();
                    IntPtr tp = triPin.AddrOfPinnedObject();
                    Vector3 bmin = new Vector3(tileBounds.min.x, loY, tileBounds.min.z);
                    Vector3 bmax = new Vector3(tileBounds.max.x, hiY, tileBounds.max.z);

                    hf = RecastWrapper.CreateHeightFieldRaw(in nav.Params, vp, vertexCount, tp, indexCount / 3, in bmin, in bmax, triAreaOverrides: IntPtr.Zero);
                    if (hf == IntPtr.Zero) { report.TilesFailed++; report.Notes.Add($"[tile {tx},{ty}] CreateHeightFieldRaw = 0"); yield break; }

                    yield return null;
                    int volumes = CollectTileVolumes(nav, geomBounds);
                    chf = RecastWrapper.CreateCompactHeightField(in nav.Params, hf, volumes > 0 ? _tileVolumes : null, volumes);
                    if (chf == IntPtr.Zero) { report.TilesFailed++; report.Notes.Add($"[tile {tx},{ty}] CreateCompactHeightField = 0"); yield break; }

                    yield return null;
                    pm = RecastWrapper.CreatePolymesh(in nav.Params, chf);
                    if (pm == IntPtr.Zero)
                    {
                        report.TilesEmpty++;
                        report.Notes.Add($"[tile {tx},{ty}] CreatePolymesh = 0 " + "(no walkable regions)");
                        yield break;
                    }

                    yield return null;
                    if (nav.Params.buildDetailMesh)
                    {
                        dm = RecastWrapper.CreateDetailPolymesh(in nav.Params, pm, chf,
                            ConVar.RustNav.detailSampleDistMult, ConVar.RustNav.detailSampleMaxErrorMult);
                        if (dm == IntPtr.Zero) { report.TilesFailed++; report.Notes.Add($"[tile {tx},{ty}] CreateDetailPolymesh = 0"); yield break; }
                    }

                    yield return null;
                    data = RecastWrapper.CreateNavData(in nav.Params, tx, ty, pm, dm, out int dataSize);
                    if (data == IntPtr.Zero) { report.TilesFailed++; report.Notes.Add($"[tile {tx},{ty}] CreateNavData = 0"); yield break; }

                    yield return null;
                    if (!RecastWrapper.AddPrebuiltTileToNavMesh(nav.Handle, tx, ty, data, dataSize))
                    {
                        RecastWrapper.FreeTileData(data);
                        data = IntPtr.Zero;
                        report.TilesFailed++;
                        yield break;
                    }

                    data = IntPtr.Zero;
                    report.TilesBuilt++;
                    yield break;
                }
                finally
                {
                    if (data != IntPtr.Zero) RecastWrapper.FreeTileData(data);
                    if (dm != IntPtr.Zero) RecastWrapper.FreeDetailPolymesh(dm);
                    if (pm != IntPtr.Zero) RecastWrapper.FreePolymesh(pm);
                    if (chf != IntPtr.Zero) RecastWrapper.FreeCompactHeightField(chf);
                    if (hf != IntPtr.Zero) RecastWrapper.FreeHeightField(hf);
                    if (vertPin.IsAllocated) vertPin.Free();
                    if (triPin.IsAllocated) triPin.Free();
                }
            }

            private bool BuildTile(BuildingNav nav, int tx, int ty, BuildReport report)
            {
                Bounds tileBounds = CalcTileBounds(nav, tx, ty);
                Bounds geomBounds = ExpandTileBounds(nav, tileBounds);

                Vector3 gmin = Vector3.Max(geomBounds.min, nav.Bounds.min);
                Vector3 gmax = Vector3.Min(geomBounds.max, nav.Bounds.max);
                if (gmax.x <= gmin.x || gmax.z <= gmin.z) { report.TilesEmpty++; return false; }
                geomBounds.SetMinMax(gmin, gmax);

                DropDoorsInBounds(nav, tileBounds);

                _verts.Clear();
                _tris.Clear();
                CollectGeometry(nav, geomBounds, _verts, _tris, report);
                ClipGeometryByHeight(_verts, _tris);
                if (_verts.Count == 0 || _tris.Count < 3)
                {
                    report.TilesEmpty++;
                    report.Notes.Add($"[tile {tx},{ty}] empty: no geometry ({_verts.Count} verts, {_tris.Count / 3} tris)");
                    return false;
                }

                report.Verts += _verts.Count;
                report.Tris += _tris.Count / 3;

                for (int i = 0; i + 2 < _tris.Count; i += 3)
                {
                    Vector3 a = _verts[_tris[i]], b = _verts[_tris[i + 1]], c = _verts[_tris[i + 2]];
                    Vector3 n = Vector3.Cross(b - a, c - a);
                    if (n.sqrMagnitude < 1e-8f) continue;
                    float ny = n.normalized.y;
                    if (Mathf.Abs(ny) < 0.7f) continue;
                    int y = Mathf.RoundToInt((a.y + b.y + c.y) / 3f);
                    if (ny > 0f)
                    {
                        report.FlatTrisByY[y] = report.FlatTrisByY.TryGetValue(y, out int u) ? u + 1 : 1;
                        RememberFloorPoint(nav, (a + b + c) / 3f);
                    }
                    else report.DownTrisByY[y] = report.DownTrisByY.TryGetValue(y, out int d) ? d + 1 : 1;
                }

                if (_vertArr.Length < _verts.Count) _vertArr = new Vector3[Mathf.NextPowerOfTwo(_verts.Count)];
                if (_triArr.Length < _tris.Count) _triArr = new int[Mathf.NextPowerOfTwo(_tris.Count)];
                _verts.CopyTo(_vertArr);
                _tris.CopyTo(_triArr);

                float loY = float.MaxValue, hiY = float.MinValue;
                for (int i = 0; i < _verts.Count; i++)
                {
                    float y = _verts[i].y;
                    if (y < loY) loY = y;
                    if (y > hiY) hiY = y;
                }
                if (loY > hiY) { report.TilesEmpty++; return false; }

                float ch = nav.Params.cellHeight;
                loY -= ch * 2f;
                hiY += ch * 2f;
                loY = nav.Bounds.min.y + Mathf.Floor((loY - nav.Bounds.min.y) / ch) * ch;
                if (Mathf.CeilToInt((hiY - loY) / ch) > MaxSpanHeight) { report.TilesTooTall++; report.TilesFailed++; return false; }

                var vertPin = System.Runtime.InteropServices.GCHandle.Alloc(_vertArr, System.Runtime.InteropServices.GCHandleType.Pinned);
                var triPin = System.Runtime.InteropServices.GCHandle.Alloc(_triArr, System.Runtime.InteropServices.GCHandleType.Pinned);

                IntPtr hf = IntPtr.Zero, chf = IntPtr.Zero, pm = IntPtr.Zero, dm = IntPtr.Zero, data = IntPtr.Zero;
                try
                {
                    IntPtr vp = vertPin.AddrOfPinnedObject();
                    IntPtr tp = triPin.AddrOfPinnedObject();
                    Vector3 bmin = new Vector3(tileBounds.min.x, loY, tileBounds.min.z);
                    Vector3 bmax = new Vector3(tileBounds.max.x, hiY, tileBounds.max.z);

                    hf = RecastWrapper.CreateHeightFieldRaw(in nav.Params, vp, _verts.Count, tp, _tris.Count / 3, in bmin, in bmax, triAreaOverrides: IntPtr.Zero);
                    if (hf == IntPtr.Zero) { report.TilesFailed++; report.Notes.Add($"[tile {tx},{ty}] CreateHeightFieldRaw = 0"); return false; }

                    int volumes = CollectTileVolumes(nav, geomBounds);
                    chf = RecastWrapper.CreateCompactHeightField(in nav.Params, hf, volumes > 0 ? _tileVolumes : null, volumes);
                    if (chf == IntPtr.Zero) { report.TilesFailed++; report.Notes.Add($"[tile {tx},{ty}] CreateCompactHeightField = 0"); return false; }

                    pm = RecastWrapper.CreatePolymesh(in nav.Params, chf);
                    if (pm == IntPtr.Zero)
                    {
                        report.TilesEmpty++;
                        report.Notes.Add($"[tile {tx},{ty}] CreatePolymesh = 0 " + "(no walkable regions)");
                        return false;
                    }

                    if (nav.Params.buildDetailMesh)
                    {
                        dm = RecastWrapper.CreateDetailPolymesh(in nav.Params, pm, chf,
                            ConVar.RustNav.detailSampleDistMult, ConVar.RustNav.detailSampleMaxErrorMult);
                        if (dm == IntPtr.Zero) { report.TilesFailed++; report.Notes.Add($"[tile {tx},{ty}] CreateDetailPolymesh = 0"); return false; }
                    }

                    data = RecastWrapper.CreateNavData(in nav.Params, tx, ty, pm, dm, out int dataSize);
                    if (data == IntPtr.Zero) { report.TilesFailed++; report.Notes.Add($"[tile {tx},{ty}] CreateNavData = 0"); return false; }

                    if (!RecastWrapper.AddPrebuiltTileToNavMesh(nav.Handle, tx, ty, data, dataSize))
                    {
                        RecastWrapper.FreeTileData(data);
                        data = IntPtr.Zero;
                        report.TilesFailed++;
                        return false;
                    }

                    data = IntPtr.Zero;
                    report.TilesBuilt++;
                    return true;
                }
                catch (Exception e)
                {
                    report.Notes.Add($"BuildTile({tx},{ty}): {e.GetType().Name}: {e.Message}");
                    Debug.LogWarning<HelperBuildingNavMesh>("BuildTile({0},{1}): {2}: {3}", tx, ty, e.GetType().Name, e.Message);
                    report.TilesFailed++;
                    return false;
                }
                finally
                {
                    if (data != IntPtr.Zero) RecastWrapper.FreeTileData(data);
                    if (dm != IntPtr.Zero) RecastWrapper.FreeDetailPolymesh(dm);
                    if (pm != IntPtr.Zero) RecastWrapper.FreePolymesh(pm);
                    if (chf != IntPtr.Zero) RecastWrapper.FreeCompactHeightField(chf);
                    if (hf != IntPtr.Zero) RecastWrapper.FreeHeightField(hf);
                    vertPin.Free();
                    triPin.Free();
                }
            }

            private NavMeshBuildVolume[] _tileVolumes = new NavMeshBuildVolume[4];

            private int CollectTileVolumes(BuildingNav nav, Bounds geomBounds)
            {
                int count = 0;
                for (int i = 0; i < _deployVolumes.Count; i++)
                {
                    if (count == _tileVolumes.Length) Array.Resize(ref _tileVolumes, count * 2);
                    _tileVolumes[count++] = _deployVolumes[i];
                }
                for (int pass = 0; pass < 2; pass++)
                {
                    bool hatches = pass == 0;
                    if (!hatches && !DoorGateBox) break;
                    foreach (var d in nav.Doors.Values)
                    {
                        if (d.IsHatch != hatches || !d.HasOpening || !d.OpeningBounds.Intersects(geomBounds)) continue;
                        Door door = d.Gate != null ? d.Gate.LinkedDoor : null;
                        if (door == null || door.IsDestroyed) continue;
                        if (count == _tileVolumes.Length) Array.Resize(ref _tileVolumes, count * 2);
                        _tileVolumes[count++] = d.OpeningVolume;
                    }
                }
                return count;
            }

            private const float FloorPointStep = 0.5f;

            private static void RememberFloorPoint(BuildingNav nav, Vector3 p)
            {
                long kx = (long)Mathf.Floor(p.x / FloorPointStep);
                long ky = (long)Mathf.Floor(p.y / FloorPointStep);
                long kz = (long)Mathf.Floor(p.z / FloorPointStep);
                long key = (kx & 0x1FFFFF) | ((ky & 0x1FFFFF) << 21) | ((kz & 0x1FFFFF) << 42);
                if (!nav.FloorPoints.ContainsKey(key)) nav.FloorPoints[key] = p;
            }

            public static bool GetTilePolys(BuildingNav nav, int tx, int ty, out int polyCount)
            {
                polyCount = 0;
                if (nav == null || !nav.IsValid) return false;
                Array.Clear(PolyBuffer, 0, PolyBuffer.Length);
                return RecastWrapper.GetTilePolysEx(nav.Handle, tx, ty, PolyBuffer, PolyAreaBuffer, PolyFlagBuffer, MaxPolysPerTile, out polyCount);
            }

            public static int CountPolys(BuildingNav nav)
            {
                if (nav == null || !nav.IsValid) return 0;
                int total = 0;
                for (int ty = 0; ty < nav.TileNum.y; ty++)
                    for (int tx = 0; tx < nav.TileNum.x; tx++)
                        if (GetTilePolys(nav, tx, ty, out int c)) total += c;
                return total;
            }

            #endregion

            #region Сбор геометрии (коллайдеры + террейн)

            private readonly List<Vector3> _verts = new List<Vector3>(8192);
            private readonly List<int> _tris = new List<int>(24576);
            private Vector3[] _vertArr = new Vector3[8192];
            private int[] _triArr = new int[24576];
            private static readonly Collider[] _colBuf = new Collider[4096];
            private readonly Dictionary<Mesh, MeshData> _meshCache = new Dictionary<Mesh, MeshData>();
            private struct MeshData { public Vector3[] Verts; public int[] Tris; }

            public static readonly Vector3[] PolyBuffer = new Vector3[MaxPolysPerTile * VertsPerPoly];
            private static readonly byte[] PolyAreaBuffer = new byte[MaxPolysPerTile];
            private static readonly ushort[] PolyFlagBuffer = new ushort[MaxPolysPerTile];
            private static readonly Vector3[] _pathBuf = new Vector3[RecastWrapper.MAX_PATH_SIZE];
            private static readonly ulong[] _pathPolyBuf = new ulong[RecastWrapper.MAX_PATH_SIZE];

            private static readonly int[] BoxTris =
            {
                7, 4, 3, 7, 6, 4, 4, 6, 5, 4,
                5, 0, 4, 5, 1, 4, 1, 0, 5, 6,
                2, 5, 2, 1, 6, 7, 3, 6, 3, 2,
                0, 1, 3, 0, 3, 7
            };

            private static readonly Vector3[] _boxVerts = new Vector3[8];

            private readonly HashSet<BaseEntity> _blocksWithMesh = new HashSet<BaseEntity>();
            private static readonly List<ulong> _doorDropBuf = new List<ulong>();

            private static void ClipGeometryByHeight(List<Vector3> verts, List<int> tris)
            {
                if (float.IsNaN(ClipMinY) && float.IsNaN(ClipMaxY)) return;

                float lo = float.IsNaN(ClipMinY) ? float.MinValue : ClipMinY;
                float hi = float.IsNaN(ClipMaxY) ? float.MaxValue : ClipMaxY;

                int write = 0;
                for (int i = 0; i + 2 < tris.Count; i += 3)
                {
                    float ya = verts[tris[i]].y, yb = verts[tris[i + 1]].y, yc = verts[tris[i + 2]].y;
                    if (Mathf.Max(ya, Mathf.Max(yb, yc)) < lo) continue;
                    if (Mathf.Min(ya, Mathf.Min(yb, yc)) > hi) continue;
                    tris[write] = tris[i];
                    tris[write + 1] = tris[i + 1];
                    tris[write + 2] = tris[i + 2];
                    write += 3;
                }
                tris.RemoveRange(write, tris.Count - write);
            }

            private void CollectGeometry(BuildingNav nav, Bounds bounds, List<Vector3> verts, List<int> tris, BuildReport report)
            {
                if (IncludeTerrain)
                {
                    int before = tris.Count;
                    AddTerrain(bounds, verts, tris, report);
                    report.TrisTerrain += (tris.Count - before) / 3;
                }

                _deployVolumes.Clear();
                int n = Physics.OverlapBoxNonAlloc(bounds.center, bounds.extents, _colBuf, Quaternion.identity, GeomMask, QueryTriggerInteraction.Ignore);
                if (n >= _colBuf.Length) report.Notes.Add($"the collider buffer is full ({_colBuf.Length}) - the tile geometry may be incomplete");

                _blocksWithMesh.Clear();
                _deckDone.Clear();
                _deckCovered.Clear();
                _gateDone.Clear();
                for (int i = 0; i < n; i++)
                {
                    var c = _colBuf[i];
                    if (c == null || !(c is MeshCollider mcc) || mcc.sharedMesh == null) continue;
                    var e = c.gameObject.ToBaseEntity();
                    if (e is BuildingBlock) _blocksWithMesh.Add(e);
                }

                for (int i = 0; i < n; i++)
                {
                    var col = _colBuf[i];
                    if (col == null) continue;
                    var ent = col.gameObject.ToBaseEntity();
                    if (ent != null && (ent.isClient || ent.IsDestroyed)) continue;
                    if (ent is TreeEntity tree && !tree.IncludeInNavmesh) continue;
                    if (ent is DebrisEntity) continue;

                    if (ent is Door door)
                    {
                        RegisterDoor(nav, door);

                        ulong gateId = door.net?.ID.Value ?? 0UL;
                        if (_gateDone.Add(gateId) && nav.Doors.TryGetValue(gateId, out var gateLink))
                        {
                            if (gateLink.IsHatch)
                            {
                                EnsureHatchShape(gateLink, door);
                                AddHatchCap(gateLink, door, verts, tris);
                            }
                            else EnsureDoorShape(gateLink, door);
                        }
                        string dn = door.ShortPrefabName ?? "?";
                        var cur = report.DoorShapes.TryGetValue(dn, out var ds) ? ds : (0, 0, Vector3.zero);
                        bool doorMesh = col is MeshCollider dmc && dmc.sharedMesh != null;
                        Vector3 size = col.bounds.size;
                        Vector3 big = new Vector3(Mathf.Max(cur.Item3.x, size.x), Mathf.Max(cur.Item3.y, size.y), Mathf.Max(cur.Item3.z, size.z));
                        report.DoorShapes[dn] = doorMesh ? (cur.Item1 + 1, cur.Item2, big) : (cur.Item1, cur.Item2 + 1, big);

                        continue;
                    }

                    bool isBlock = ent is BuildingBlock;
                    if (isBlock && TryGetStairKind(ent.ShortPrefabName ?? string.Empty, out ClimbKind stairKind)
                        && (StairDeck || (StairDeckSpiral && stairKind == ClimbKind.Spiral)))
                    {
                        if (_deckDone.Add(ent) && AddStairDeck(nav, (BuildingBlock)ent, verts, tris, report)) _deckCovered.Add(ent);
                        if (_deckCovered.Contains(ent)) continue;
                    }

                    if (isBlock)
                    {
                        report.ColBlocks++;
                        string pn = ent.ShortPrefabName ?? "?";
                        var cur = report.BlockShapes.TryGetValue(pn, out var s) ? s : (0, 0);
                        bool isMesh = col is MeshCollider mc2 && mc2.sharedMesh != null;
                        report.BlockShapes[pn] = isMesh ? (cur.Item1 + 1, cur.Item2) : (cur.Item1, cur.Item2 + 1);
                    }
                    bool spiralTrim = isBlock && SpiralPathWidth > 0f
                                      && TryGetStairKind(ent.ShortPrefabName ?? string.Empty, out ClimbKind trimKind)
                                      && trimKind == ClimbKind.Spiral;
                    if (spiralTrim && col is MeshCollider trimMesh && trimMesh.sharedMesh != null)
                        AddSpiralMesh(trimMesh, ((BuildingBlock)ent).transform.position, verts, tris, report);
                    else
                        AddCollider(col, verts, tris, isBlock && _blocksWithMesh.Contains(ent), report);

                    if (!isBlock && ent != null && !(ent is BaseLadder)) AddDeployVolume(col, report);
                }

                if (HurtZoneCut) CollectHurtVolumes(bounds, report);
            }

            public static bool HurtZoneCut = true;

            private static readonly int HurtZoneMask = LayerMask.GetMask("Trigger");
            private static readonly Collider[] _hurtBuf = new Collider[512];

            private const float HurtVolumeBodyReach = 1.6f;

            private const float HurtZonePad = 2f;

            private static bool IsStaticHurtSource(BaseEntity e)
                => e is DecayEntity && !(e is BuildingBlock) && !(e is BaseOven) && !e.IsDestroyed && !e.isClient;

            private static bool HasHurtZone(BaseEntity e)
                => IsStaticHurtSource(e) && e.GetComponentInChildren<IHurtTrigger>() != null;

            private void CollectHurtVolumes(Bounds bounds, BuildReport report)
            {
                int n = Physics.OverlapBoxNonAlloc(bounds.center, bounds.extents, _hurtBuf, Quaternion.identity, HurtZoneMask, QueryTriggerInteraction.Collide);
                if (n >= _hurtBuf.Length) report.Notes.Add($"the trigger buffer is full ({_hurtBuf.Length}) - damage zones of the tile may be incomplete");
                for (int i = 0; i < n; i++)
                {
                    var col = _hurtBuf[i];
                    if (col == null || !col.isTrigger || col.attachedRigidbody != null) continue;
                    if (col.GetComponentInParent<IHurtTrigger>() == null) continue;
                    BaseEntity ent = col.gameObject.ToBaseEntity();
                    if (!IsStaticHurtSource(ent)) continue;
                    if (!HurtZoneOutline(col, out float lo, out float hi)) continue;

                    _deployVolumes.Add(MakeVolume(_deployOutline, lo - HurtVolumeBodyReach, hi, DeployVolumeArea));
                    report.HurtVolumes++;
                }
            }

            private static bool HurtZoneOutline(Collider col, out float lo, out float hi)
            {
                lo = float.MaxValue;
                hi = float.MinValue;
                _deployCorners.Clear();
                if (col is BoxCollider box)
                {
                    Matrix4x4 m = col.transform.localToWorldMatrix * Matrix4x4.Translate(box.center);
                    Vector3 half = box.size * 0.5f;
                    for (int i = 0; i < 8; i++)
                    {
                        Vector3 w = m.MultiplyPoint3x4(new Vector3((i & 1) == 0 ? -half.x : half.x, (i & 2) == 0 ? -half.y : half.y, (i & 4) == 0 ? -half.z : half.z));
                        if (w.y < lo) lo = w.y;
                        if (w.y > hi) hi = w.y;
                        _deployCorners.Add(new Vector2(w.x, w.z));
                    }
                }
                else
                {
                    Bounds b = col.bounds;
                    lo = b.min.y;
                    hi = b.max.y;
                    _deployCorners.Add(new Vector2(b.min.x, b.min.z));
                    _deployCorners.Add(new Vector2(b.max.x, b.min.z));
                    _deployCorners.Add(new Vector2(b.max.x, b.max.z));
                    _deployCorners.Add(new Vector2(b.min.x, b.max.z));
                }
                ConvexHull(_deployCorners, _deployOutline);
                return _deployOutline.Count >= 3 && _deployOutline.Count <= MaxVolumeVerts;
            }

            private readonly List<NavMeshBuildVolume> _deployVolumes = new List<NavMeshBuildVolume>();
            private static readonly List<Vector2> _deployCorners = new List<Vector2>(8);
            private static readonly List<Vector2> _deployOutline = new List<Vector2>(8);

            private const int DeployVolumeArea = 0;

            private const float DeployVolumeTopKeep = 0.15f;

            private const float DeployVolumeBelow = 0.1f;

            private void AddDeployVolume(Collider col, BuildReport report)
            {
                if (!(col is BoxCollider box)) return;
                Transform t = col.transform;
                if (Mathf.Abs(t.right.y) < DeployUprightCos && Mathf.Abs(t.up.y) < DeployUprightCos && Mathf.Abs(t.forward.y) < DeployUprightCos) return;

                Matrix4x4 m = t.localToWorldMatrix * Matrix4x4.Translate(box.center);
                Vector3 half = box.size * 0.5f;
                float lo = float.MaxValue, hi = float.MinValue;
                _deployCorners.Clear();
                for (int i = 0; i < 8; i++)
                {
                    Vector3 w = m.MultiplyPoint3x4(new Vector3((i & 1) == 0 ? -half.x : half.x, (i & 2) == 0 ? -half.y : half.y, (i & 4) == 0 ? -half.z : half.z));
                    if (w.y < lo) lo = w.y;
                    if (w.y > hi) hi = w.y;
                    _deployCorners.Add(new Vector2(w.x, w.z));
                }
                if (hi - lo < EffectiveAgentHeight) return;
                ConvexHull(_deployCorners, _deployOutline);
                if (_deployOutline.Count < 3 || _deployOutline.Count > MaxVolumeVerts) return;
                _deployVolumes.Add(MakeVolume(_deployOutline, lo - DeployVolumeBelow, hi - DeployVolumeTopKeep, DeployVolumeArea));
                report.DeployVolumes++;
            }

            private static readonly float DeployUprightCos = Mathf.Cos(10f * Mathf.Deg2Rad);

            #region Настил марша

            private const float DeckFlatDot = 0.9f;
            private const float DeckMinTri = 0.01f;
            private const float DeckLevelStep = 0.06f;
            private const float DeckMinLevelArea = 0.04f;
            private const int DeckMinLevels = 3;
            public static bool StairDeck = false;

            public static bool DoorGateBox = true;

            public static bool InsideBlockCull = true;

            public static float DoorGateThickness = 0f;

            public static float DoorGateHeight = 0f;

            public static bool StairDeckSpiral = false;

            private const float DeckWidth = 1.3f;
            public static float DeckWidthSpiral = 0.9f;
            private const float DeckMinUseful = 0.7f;
            private const float DeckSideClear = 0.02f;
            private const float DeckLift = 0.08f;
            private const float DeckRunout = 0.7f;

            private static readonly HashSet<BaseEntity> _deckDone = new HashSet<BaseEntity>();
            private static readonly HashSet<ulong> _gateDone = new HashSet<ulong>();
            private static readonly HashSet<BaseEntity> _deckCovered = new HashSet<BaseEntity>();
            private static readonly Dictionary<int, TreadLevel> _treadLevels = new Dictionary<int, TreadLevel>();
            private static readonly List<TreadLevel> _treadSorted = new List<TreadLevel>();
            private static readonly List<TreadLevel> _treadPool = new List<TreadLevel>();

            private sealed class TreadLevel
            {
                public float Area;
                public Vector3 Sum;
                public readonly List<Vector3> Points = new List<Vector3>();
                public Vector3 Center => Sum / Mathf.Max(Area, 1e-4f);
            }

            private bool AddStairDeck(BuildingNav nav, BuildingBlock b, List<Vector3> verts, List<int> tris, BuildReport report)
            {
                if (!CollectTreadChain(b)) return false;

                float widthCap = TryGetStairKind(b.ShortPrefabName ?? string.Empty, out ClimbKind deckKind)
                                 && deckKind == ClimbKind.Spiral ? DeckWidthSpiral : DeckWidth;

                int made = 0;
                for (int i = 0; i + 1 < _treadSorted.Count; i++)
                    if (AddDeckSegment(_treadSorted[i].Center, _treadSorted[i + 1].Center, _treadSorted[i], widthCap, verts, tris)) made++;

                Vector3 lo = _treadSorted[0].Center, loNext = _treadSorted[1].Center;
                Vector3 hi = _treadSorted[_treadSorted.Count - 1].Center, hiPrev = _treadSorted[_treadSorted.Count - 2].Center;
                float yBot = b.WorldSpaceBounds().position.y - b.bounds.size.y * 0.5f;
                float yTop = yBot + b.bounds.size.y;
                if (AddDeckRunout(lo, loNext, yBot, _treadSorted[0], widthCap, verts, tris)) made++;
                if (AddDeckRunout(hi, hiPrev, yTop, _treadSorted[_treadSorted.Count - 1], widthCap, verts, tris)) made++;

                report.DeckBlocks++;
                report.DeckSegments += made;
                return made > 0;
            }

            private bool CollectTreadChain(BuildingBlock b)
            {
                _treadSorted.Clear();
                if (b == null || b.IsDestroyed) return false;

                _treadLevels.Clear();
                OBB footprint = b.WorldSpaceBounds();
                Quaternion toLocal = Quaternion.Inverse(footprint.rotation);
                var cols = b.GetComponentsInChildren<MeshCollider>(true);
                for (int ci = 0; ci < cols.Length; ci++)
                {
                    var mesh = cols[ci].sharedMesh;
                    if (mesh == null || !mesh.isReadable) continue;
                    if (!_meshCache.TryGetValue(mesh, out var cached))
                    {
                        cached = new MeshData { Verts = mesh.vertices, Tris = mesh.triangles };
                        _meshCache[mesh] = cached;
                    }

                    Transform ct = cols[ci].transform;
                    var mv = cached.Verts;
                    var mt = cached.Tris;
                    for (int ti = 0; ti + 2 < mt.Length; ti += 3)
                    {
                        Vector3 p0 = ct.TransformPoint(mv[mt[ti]]);
                        Vector3 p1 = ct.TransformPoint(mv[mt[ti + 1]]);
                        Vector3 p2 = ct.TransformPoint(mv[mt[ti + 2]]);
                        Vector3 cross = Vector3.Cross(p1 - p0, p2 - p0);
                        float len = cross.magnitude;
                        if (len < 1e-6f) continue;
                        if (cross.y / len < DeckFlatDot) continue;
                        float area = len * 0.5f;
                        if (area < DeckMinTri) continue;

                        Vector3 center = (p0 + p1 + p2) / 3f;
                        Vector3 local = toLocal * (center - footprint.position);
                        if (Mathf.Abs(local.x) > footprint.extents.x || Mathf.Abs(local.z) > footprint.extents.z) continue;
                        int key = Mathf.RoundToInt(center.y / DeckLevelStep);
                        if (!_treadLevels.TryGetValue(key, out var level))
                        {
                            level = new TreadLevel();
                            _treadLevels[key] = level;
                        }
                        level.Area += area;
                        level.Sum += center * area;
                        level.Points.Add(center);
                    }
                }

                _treadPool.Clear();
                foreach (var kv in _treadLevels)
                    if (kv.Value.Area >= DeckMinLevelArea) _treadPool.Add(kv.Value);
                if (_treadPool.Count < DeckMinLevels) return false;
                _treadPool.Sort((x, y) => x.Center.y.CompareTo(y.Center.y));

                _treadSorted.Clear();
                var cur = _treadPool[0];
                _treadPool.RemoveAt(0);
                _treadSorted.Add(cur);
                while (_treadPool.Count > 0)
                {
                    int best = -1;
                    float bestCost = float.MaxValue;
                    Vector3 from = cur.Center;
                    for (int i = 0; i < _treadPool.Count; i++)
                    {
                        Vector3 d = _treadPool[i].Center - from;
                        if (d.y < -DeckLevelStep) continue;
                        float cost = new Vector2(d.x, d.z).sqrMagnitude + d.y * d.y;
                        if (cost >= bestCost) continue;
                        bestCost = cost;
                        best = i;
                    }
                    if (best < 0) break;
                    cur = _treadPool[best];
                    _treadPool.RemoveAt(best);
                    _treadSorted.Add(cur);
                }
                return _treadSorted.Count >= DeckMinLevels;
            }

            private static bool AddDeckSegment(Vector3 from, Vector3 to, TreadLevel level, float widthCap, List<Vector3> verts, List<int> tris)
            {
                Vector3 flat = to - from;
                flat.y = 0f;
                if (flat.sqrMagnitude < 1e-4f) return false;
                Vector3 right = Vector3.Cross(Vector3.up, flat.normalized);
                float half = DeckHalfWidth(level, right, widthCap);
                AddDeckQuad(from + Vector3.up * DeckLift, to + Vector3.up * DeckLift, right, half, verts, tris);
                return true;
            }

            private static bool AddDeckRunout(Vector3 edge, Vector3 inner, float floorY, TreadLevel level, float widthCap, List<Vector3> verts, List<int> tris)
            {
                Vector3 flat = edge - inner;
                flat.y = 0f;
                if (flat.sqrMagnitude < 1e-4f) return false;
                flat.Normalize();
                Vector3 outer = edge + flat * DeckRunout;
                outer.y = floorY;
                Vector3 right = Vector3.Cross(Vector3.up, flat);
                float half = DeckHalfWidth(level, right, widthCap);
                AddDeckQuad(edge + Vector3.up * DeckLift, outer + Vector3.up * DeckLift, right, half, verts, tris);
                return true;
            }

            private static float DeckHalfWidth(TreadLevel level, Vector3 right, float widthCap)
            {
                float min = float.MaxValue, max = float.MinValue;
                Vector3 c = level.Center;
                for (int i = 0; i < level.Points.Count; i++)
                {
                    float d = Vector3.Dot(level.Points[i] - c, right);
                    if (d < min) min = d;
                    if (d > max) max = d;
                }
                float span = max > min ? max - min : widthCap;
                return Mathf.Clamp(span - DeckSideClear * 2f, Mathf.Min(DeckMinUseful, widthCap), widthCap) * 0.5f;
            }

            private static void AddDeckQuad(Vector3 from, Vector3 to, Vector3 right, float half, List<Vector3> verts, List<int> tris)
            {
                int b = verts.Count;
                verts.Add(from - right * half);
                verts.Add(to - right * half);
                verts.Add(to + right * half);
                verts.Add(from + right * half);
                tris.Add(b); tris.Add(b + 1); tris.Add(b + 2);
                tris.Add(b); tris.Add(b + 2); tris.Add(b + 3);
            }

            #endregion

            private static void AddTerrain(Bounds bounds, List<Vector3> verts, List<int> tris, BuildReport report)
            {
                var heightMap = TerrainMeta.HeightMap;
                if (heightMap == null) return;
                var alphaMap = TerrainMeta.AlphaMap;

                float x0 = Mathf.Floor(bounds.min.x / TerrainStep) * TerrainStep;
                float z0 = Mathf.Floor(bounds.min.z / TerrainStep) * TerrainStep;
                int nx = Mathf.CeilToInt((bounds.max.x - x0) / TerrainStep);
                int nz = Mathf.CeilToInt((bounds.max.z - z0) / TerrainStep);
                if (nx <= 0 || nz <= 0) return;

                var grid = new int[(nx + 1) * (nz + 1)];
                var inside = new bool[(nx + 1) * (nz + 1)];

                for (int iz = 0; iz <= nz; iz++)
                {
                    for (int ix = 0; ix <= nx; ix++)
                    {
                        Vector3 p = new Vector3(x0 + ix * TerrainStep, 0f, z0 + iz * TerrainStep);
                        float h = heightMap.GetHeight(p);
                        int slot = iz * (nx + 1) + ix;

                        if (p.x < bounds.min.x || p.x > bounds.max.x || p.z < bounds.min.z || p.z > bounds.max.z)
                        { grid[slot] = -1; report.OutPoints++; continue; }

                        if (h < -1f) { grid[slot] = -1; report.LowPoints++; continue; }

                        if (alphaMap != null && alphaMap.GetAlpha(p) < 0.1f) { grid[slot] = -1; report.AlphaPoints++; continue; }

                        p.y = h;

                        if (InsideBlockCull && IsInsideConstruction(p)) { inside[slot] = true; report.InsideBlockPoints++; }
                        if (UseCarve && IsCarved(p)) { grid[slot] = -1; report.CarvedPoints++; continue; }
                        if (UseRing && !NearConstruction(p)) { grid[slot] = -1; report.FarPoints++; continue; }
                        grid[slot] = verts.Count;
                        verts.Add(p);
                    }
                }

                for (int iz = 0; iz < nz; iz++)
                {
                    for (int ix = 0; ix < nx; ix++)
                    {
                        int sa = iz * (nx + 1) + ix, sb = (iz + 1) * (nx + 1) + ix;
                        int sc = iz * (nx + 1) + ix + 1, sd = (iz + 1) * (nx + 1) + ix + 1;
                        int a = grid[sa], b = grid[sb], c = grid[sc], d = grid[sd];

                        if (a >= 0 && b >= 0 && c >= 0 && !(inside[sa] && inside[sb] && inside[sc]))
                        { tris.Add(a); tris.Add(b); tris.Add(c); }
                        if (c >= 0 && b >= 0 && d >= 0 && !(inside[sc] && inside[sb] && inside[sd]))
                        { tris.Add(c); tris.Add(b); tris.Add(d); }
                    }
                }
            }

            private const float InsideBlockReach = 0.05f;
            private const float InsideBlockEpsSqr = 1e-4f;
            private static readonly Collider[] _insideBlockBuf = new Collider[16];

            public static bool IsInsideConstruction(Vector3 groundPoint)
            {
                int n = Physics.OverlapSphereNonAlloc(groundPoint, InsideBlockReach, _insideBlockBuf,
                                                      CarveMask, QueryTriggerInteraction.Ignore);
                for (int i = 0; i < n; i++)
                {
                    var c = _insideBlockBuf[i];
                    if (c == null) continue;
                    if (c is MeshCollider mesh && !mesh.convex) continue;
                    if ((c.ClosestPoint(groundPoint) - groundPoint).sqrMagnitude < InsideBlockEpsSqr) return true;
                }
                return false;
            }

            public static bool IsCarved(Vector3 groundPoint)
            {
                return Physics.CheckBox(
                    groundPoint + new Vector3(0f, CarveProbeHeight * 0.5f, 0f),
                    new Vector3(CarvePad, CarveProbeHeight * 0.5f, CarvePad),
                    Quaternion.identity, CarveMask, QueryTriggerInteraction.Ignore);
            }

            public static bool NearConstruction(Vector3 groundPoint)
            {
                return Physics.CheckBox(
                    groundPoint + new Vector3(0f, RingProbeHeight * 0.5f, 0f),
                    new Vector3(RingWidth, RingProbeHeight * 0.5f, RingWidth),
                    Quaternion.identity, CarveMask, QueryTriggerInteraction.Ignore);
            }

            private static void DropDoorsInBounds(BuildingNav nav, Bounds b)
            {
                if (nav.Doors.Count == 0) return;
                _doorDropBuf.Clear();
                foreach (var kv in nav.Doors) if (b.Contains(kv.Value.Position)) _doorDropBuf.Add(kv.Key);
                for (int i = 0; i < _doorDropBuf.Count; i++) nav.Doors.Remove(_doorDropBuf[i]);
            }

            private static void CollectDoorsOfBuilding(BuildingNav nav, BuildingManager.Building building)
            {
                var ents = building?.decayEntities;
                if (ents == null) return;
                for (int i = 0; i < ents.Count; i++)
                    if (ents[i] is Door door && door != null && !door.IsDestroyed) RegisterDoor(nav, door);
            }

            private static void SyncDoors(BuildingNav nav)
            {
                if (nav.Doors.Count > 0)
                {
                    _doorDropBuf.Clear();
                    foreach (var kv in nav.Doors)
                    {
                        Door door = kv.Value.Gate != null ? kv.Value.Gate.LinkedDoor : null;
                        if (door == null || door.IsDestroyed) _doorDropBuf.Add(kv.Key);
                    }
                    for (int i = 0; i < _doorDropBuf.Count; i++) nav.Doors.Remove(_doorDropBuf[i]);
                }
                CollectDoorsOfBuilding(nav, BuildingManager.server.GetBuilding(nav.BuildingID));
            }

            private static void RegisterDoor(BuildingNav nav, Door door)
            {
                ulong id = door.net?.ID.Value ?? 0UL;
                if (id == 0UL || nav.Doors.ContainsKey(id)) return;

                bool hatch = IsHatchLeaf(door);

                Vector3 center = door.WorldSpaceBounds().position;
                if (!hatch) TryGetDoorPassage(door, out center, out _);
                Vector3 gate = center;
                if (!hatch)
                {
                    gate = FloorUnderDoor(center, door, out Collider ownHit, out float ownHitY, out bool atBase, out float strayY);
                }

                nav.Doors[id] = new DoorLink
                {
                    DoorId = id,
                    Gate = new RecastNode(gate, NodeRole.Door, door, waypointOnly: true),
                    IsHatch = hatch,
                    IsOpen = door.IsOpen()
                };
            }

            public static float SpiralPathWidth = 0f;

            private const float SpiralFlatDot = 0.7f;

            private void AddSpiralMesh(MeshCollider mc, Vector3 axis, List<Vector3> verts, List<int> tris, BuildReport report)
            {
                var mesh = mc.sharedMesh;
                if (!mesh.isReadable) { report.ColUnreadable++; return; }
                if (!_meshCache.TryGetValue(mesh, out var md))
                {
                    md = new MeshData { Verts = mesh.vertices, Tris = mesh.triangles };
                    _meshCache[mesh] = md;
                }

                Matrix4x4 m = mc.transform.localToWorldMatrix;
                int start = verts.Count;
                for (int i = 0; i < md.Verts.Length; i++) verts.Add(m.MultiplyPoint3x4(md.Verts[i]));

                float minR = float.MaxValue, maxR = float.MinValue;
                for (int i = 0; i + 2 < md.Tris.Length; i += 3)
                {
                    if (!SpiralTread(verts, start, md, i, axis, out float r)) continue;
                    if (r < minR) minR = r;
                    if (r > maxR) maxR = r;
                }

                bool trim = maxR > minR;
                float half = SpiralPathWidth * 0.5f, mid = trim ? (minR + maxR) * 0.5f : 0f;

                for (int i = 0; i + 2 < md.Tris.Length; i += 3)
                {
                    if (trim && SpiralTread(verts, start, md, i, axis, out float r) && Mathf.Abs(r - mid) > half)
                        continue;
                    tris.Add(start + md.Tris[i]);
                    tris.Add(start + md.Tris[i + 1]);
                    tris.Add(start + md.Tris[i + 2]);
                    report.TrisMesh++;
                }
            }

            private static bool SpiralTread(List<Vector3> verts, int start, MeshData md, int i, Vector3 axis, out float radius)
            {
                radius = 0f;
                Vector3 a = verts[start + md.Tris[i]], b = verts[start + md.Tris[i + 1]], c = verts[start + md.Tris[i + 2]];
                Vector3 n = Vector3.Cross(b - a, c - a);
                if (n.sqrMagnitude < 1e-8f || n.normalized.y < SpiralFlatDot) return false;
                Vector3 centre = (a + b + c) / 3f;
                radius = new Vector2(centre.x - axis.x, centre.z - axis.z).magnitude;
                return true;
            }

            private void AddCollider(Collider col, List<Vector3> verts, List<int> tris, bool blockWithMesh, BuildReport report)
            {
                var t = col.transform;

                if (col is MeshCollider mc)
                {
                    if (!IncludeMeshes) return;
                    var mesh = mc.sharedMesh;
                    if (mesh == null) return;
                    if (!mesh.isReadable) { report.ColUnreadable++; return; }
                    if (!_meshCache.TryGetValue(mesh, out var md))
                    {
                        md = new MeshData { Verts = mesh.vertices, Tris = mesh.triangles };
                        _meshCache[mesh] = md;
                    }
                    Matrix4x4 m = t.localToWorldMatrix;
                    int start = verts.Count;
                    for (int i = 0; i < md.Verts.Length; i++) verts.Add(m.MultiplyPoint3x4(md.Verts[i]));
                    for (int i = 0; i < md.Tris.Length; i++) tris.Add(start + md.Tris[i]);
                    report.TrisMesh += md.Tris.Length / 3;
                    return;
                }

                if (!IncludePrimitives) return;

                if (blockWithMesh && SkipBlockPrimitives) return;

                Vector3 center, size;
                if (col is BoxCollider bc) { center = bc.center; size = bc.size; }
                else if (col is SphereCollider sc) { center = sc.center; size = Vector3.one * sc.radius * 2f; }
                else if (col is CapsuleCollider cc)
                {
                    center = cc.center;
                    float d = cc.radius * 2f;
                    if (cc.direction == 0) size = new Vector3(cc.height, d, d);
                    else if (cc.direction == 2) size = new Vector3(d, d, cc.height);
                    else size = new Vector3(d, cc.height, d);
                }
                else return;

                AddBox(t.localToWorldMatrix * Matrix4x4.Translate(center), size, verts, tris);
                report.TrisBox += BoxTris.Length / 3;

                Vector3 world = Vector3.Scale(size, t.lossyScale);
                if (world.x > BigPrimSize && world.y > BigPrimSize && world.z > BigPrimSize)
                {
                    string key = col.gameObject.name;
                    if (report.BigPrimitives.TryGetValue(key, out var prev))
                        report.BigPrimitives[key] = (prev.Count + 1, Vector3.Max(prev.Size, world), col.gameObject.layer);
                    else
                        report.BigPrimitives[key] = (1, world, col.gameObject.layer);
                }
            }

            private static void EnsureDoorShape(DoorLink d, Door door)
            {
                if (d.ShapeReady) return;
                d.ShapeReady = true;
                d.HasOpening = false;
                d.OpeningByLeaf = false;
                d.OpeningOutline = null;
                if (door == null || door.IsDestroyed) return;

                OBB dob = door.WorldSpaceBounds();
                Vector3 dsize = dob.extents * 2f;
                float baseY = door.transform.position.y;
                Vector3 normal;
                float thick;
                Vector3 center;
                if (TryGetDoorAxis(door, out normal, out float wallThick, out BuildingBlock host))
                {
                    thick = wallThick;
                    center = door.transform.position;
                    center += normal * Vector3.Dot(host.WorldSpaceBounds().position - center, normal);
                    Vector3 own = door.bounds.extents.x <= door.bounds.extents.z ? door.transform.right : door.transform.forward;
                    own.y = 0f;
                    if (own.sqrMagnitude > 1e-4f && Mathf.Abs(Vector3.Dot(own.normalized, normal)) < DoorAxisAgree && _doorAxisLogged.Add(d.DoorId))
                        Debug.LogWarning<HelperBuildingNavMesh>("door {0} net={1}: the doorway block {2} gives the wall normal {3}, the door itself {4} - the doorway volume follows the block",
                            door.ShortPrefabName, d.DoorId, host.ShortPrefabName, normal, own.normalized);
                }
                else
                {
                    d.OpeningByLeaf = true;
                    normal = dob.rotation * (dsize.x <= dsize.z ? Vector3.right : Vector3.forward);
                    normal.y = 0f;
                    if (normal.sqrMagnitude < 1e-4f) normal = Vector3.forward;
                    normal.Normalize();
                    thick = Mathf.Min(Mathf.Min(dsize.x, dsize.z), DoorHostThickness);
                    center = dob.position;
                }
                if (DoorGateThickness > 0f) thick = Mathf.Min(thick, DoorGateThickness);
                float halfThick = Mathf.Max(thick, DoorVolumeMinThickness) * 0.5f;
                float halfLen = Mathf.Max(Mathf.Max(dsize.x, dsize.z), DoorMinWidth) * 0.5f + AgentRadius + CellSize;

                float hmin = baseY - DoorBaseSlack;
                float hmax = DoorGateHeight > 0f
                    ? baseY + DoorGateHeight
                    : Mathf.Min(dob.position.y + dob.extents.y, baseY + DoorVolumeMaxRise);
                hmax = Mathf.Max(hmax, baseY + DoorBaseSlack);

                Vector3 along = new Vector3(normal.z, 0f, -normal.x);
                _doorOutline.Clear();
                for (int k = 0; k < 4; k++)
                {
                    float sa = k == 0 || k == 3 ? 1f : -1f, sn = k < 2 ? 1f : -1f;
                    Vector3 corner = center + along * (halfLen * sa) + normal * (halfThick * sn);
                    _doorOutline.Add(new Vector2(corner.x, corner.z));
                }
                float area2 = 0f;
                for (int i = 0; i < _doorOutline.Count; i++)
                {
                    Vector2 p = _doorOutline[i], q = _doorOutline[(i + 1) % _doorOutline.Count];
                    area2 += p.x * q.y - q.x * p.y;
                }
                if (area2 < 0f) _doorOutline.Reverse();

                float xMin = float.MaxValue, xMax = float.MinValue, zMin = float.MaxValue, zMax = float.MinValue;
                for (int i = 0; i < _doorOutline.Count; i++)
                {
                    Vector2 p = _doorOutline[i];
                    if (p.x < xMin) xMin = p.x;
                    if (p.x > xMax) xMax = p.x;
                    if (p.y < zMin) zMin = p.y;
                    if (p.y > zMax) zMax = p.y;
                }
                var bounds = new Bounds();
                bounds.SetMinMax(new Vector3(xMin, hmin, zMin), new Vector3(xMax, hmax, zMax));

                d.OpeningVolume = MakeVolume(_doorOutline, hmin, hmax, DoorApertureArea);
                d.OpeningOutline = _doorOutline.ToArray();
                d.OpeningBounds = bounds;
                d.OpeningCells = 0;
                d.GateBoxCenter = new Vector3(center.x, (hmin + hmax) * 0.5f, center.z);
                d.GateBoxHalf = new Vector3(halfLen + HatchGatePad, (hmax - hmin) * 0.5f + HatchGatePad, halfThick + HatchGatePad);
                d.GateBoxAxis = new Vector2(along.x, along.z);
                d.HasOpening = true;
            }

            private static readonly List<Vector2> _doorOutline = new List<Vector2>();
            private static readonly HashSet<ulong> _doorAxisLogged = new HashSet<ulong>();
            private const float DoorAxisAgree = 0.9f;

            private static readonly List<MeshCollider> _capCols = new List<MeshCollider>();
            private static readonly List<Vector2> _capPts = new List<Vector2>();
            private static readonly List<Vector2> _capHull = new List<Vector2>();
            private static readonly Comparison<Vector2> _byXThenY = (p, q) => p.x != q.x ? p.x.CompareTo(q.x) : p.y.CompareTo(q.y);

            private static void AddHatchCap(DoorLink d, Door hatch, List<Vector3> verts, List<int> tris)
            {
                if (d.CapOutline != null && d.CapOutline.Length >= 3)
                {
                    AddCapPolygon(d.CapOutline, d.CapTop, verts, tris);
                    return;
                }
                OBB ob = hatch.WorldSpaceBounds();
                AddBox(Matrix4x4.TRS(ob.position, ob.rotation, Vector3.one), ob.extents * 2f, verts, tris);
            }

            private static void AddCapPolygon(Vector2[] outline, float top, List<Vector3> verts, List<int> tris)
            {
                int start = verts.Count;
                for (int i = 0; i < outline.Length; i++) verts.Add(new Vector3(outline[i].x, top, outline[i].y));
                bool flip = Vector3.Cross(verts[start + 1] - verts[start], verts[start + 2] - verts[start]).y < 0f;
                for (int i = 1; i + 1 < outline.Length; i++)
                {
                    tris.Add(start);
                    tris.Add(start + (flip ? i + 1 : i));
                    tris.Add(start + (flip ? i : i + 1));
                }
            }

            private bool TryFrameOutline(BuildingBlock frame, out float top)
            {
                _capCols.Clear();
                _capPts.Clear();
                _capHull.Clear();
                frame.GetComponentsInChildren(false, _capCols);
                top = float.MinValue;
                for (int i = 0; i < _capCols.Count; i++)
                {
                    var mc = _capCols[i];
                    if (mc == null || !mc.enabled || mc.isTrigger || ((1 << mc.gameObject.layer) & GeomMask) == 0) continue;
                    var mesh = mc.sharedMesh;
                    if (mesh == null || !mesh.isReadable) continue;
                    if (!_meshCache.TryGetValue(mesh, out var md))
                    {
                        md = new MeshData { Verts = mesh.vertices, Tris = mesh.triangles };
                        _meshCache[mesh] = md;
                    }
                    Matrix4x4 m = mc.transform.localToWorldMatrix;
                    for (int k = 0; k < md.Verts.Length; k++)
                    {
                        Vector3 w = m.MultiplyPoint3x4(md.Verts[k]);
                        _capPts.Add(new Vector2(w.x, w.z));
                        if (w.y > top) top = w.y;
                    }
                }
                _capCols.Clear();
                if (_capPts.Count < 3) return false;

                ConvexHull(_capPts, _capHull);
                return _capHull.Count >= 3;
            }

            public const float HatchProbeStep = 0.1f;
            private const float HatchPlateTol = 0.15f;
            private const float HatchProbeUp = 1.5f;
            private const float HatchSeedRadius = 0.75f;
            private const int HatchMinOpeningCells = 16;
            private const float HatchMaxOpeningShare = 0.7f;
            private const float HatchVolumeHalfHeight = 0.25f;
            private const float HatchGateHalfHeight = 0.5f;
            private const float HatchGatePad = 0.2f;
            private const int MaxVolumeVerts = 8;

            private static readonly List<Collider> _hatchCols = new List<Collider>();
            private static readonly List<Collider> _hatchFrameCols = new List<Collider>();
            private static bool[] _hatchGrid = new bool[1024];
            private static int[] _hatchLabel = new int[1024];
            private static readonly List<int> _hatchQueue = new List<int>();
            private static readonly List<Vector2> _hatchOutline = new List<Vector2>();
            private static readonly float[] _volumeXyz = new float[MaxVolumeVerts * 3];
            private static readonly NavMeshBuildVolume[] _volumeScratch = new NavMeshBuildVolume[1];
            private static readonly long VolumeVertsOffset = ResolveVolumeVertsOffset();

            private void EnsureHatchShape(DoorLink d, Door hatch)
            {
                if (d.ShapeReady) return;
                d.ShapeReady = true;
                d.CapOutline = null;
                d.HasOpening = false;
                d.OpeningCells = 0;
                d.OpeningOutline = null;

                var frame = FindDoorHost(hatch);
                if (frame == null || !TryFrameOutline(frame, out float top))
                {
                    return;
                }
                d.CapOutline = _capHull.ToArray();
                d.CapTop = top;
                FindHatchOpening(d, hatch, frame, top);
            }

            private static void FindHatchOpening(DoorLink d, Door hatch, BuildingBlock frame, float top)
            {
                _hatchCols.Clear();
                _hatchFrameCols.Clear();
                hatch.GetComponentsInChildren(false, _hatchCols);
                for (int i = _hatchCols.Count - 1; i >= 0; i--)
                    if (_hatchCols[i] == null || UnderAnimator(_hatchCols[i].transform, hatch.transform)) _hatchCols.RemoveAt(i);
                frame.GetComponentsInChildren(false, _hatchFrameCols);

                Vector3 right = frame.transform.right;
                right.y = 0f;
                if (right.sqrMagnitude < 1e-6f) right = Vector3.right;
                right.Normalize();
                Vector3 fwd = Vector3.Cross(right, Vector3.up);

                Vector2 c2 = Vector2.zero;
                for (int i = 0; i < _capHull.Count; i++) c2 += _capHull[i];
                c2 /= _capHull.Count;
                Vector3 origin = new Vector3(c2.x, top, c2.y);

                float uMin = float.MaxValue, uMax = float.MinValue, vMin = float.MaxValue, vMax = float.MinValue;
                for (int i = 0; i < _capHull.Count; i++)
                {
                    Vector3 off = new Vector3(_capHull[i].x, top, _capHull[i].y) - origin;
                    float u = Vector3.Dot(off, right), v = Vector3.Dot(off, fwd);
                    if (u < uMin) uMin = u;
                    if (u > uMax) uMax = u;
                    if (v < vMin) vMin = v;
                    if (v > vMax) vMax = v;
                }

                float step = HatchProbeStep;
                int nu = Mathf.Max(1, Mathf.CeilToInt((uMax - uMin) / step));
                int nv = Mathf.Max(1, Mathf.CeilToInt((vMax - vMin) / step));
                int total = nu * nv;
                if (_hatchGrid.Length < total)
                {
                    _hatchGrid = new bool[Mathf.NextPowerOfTwo(total)];
                    _hatchLabel = new int[_hatchGrid.Length];
                }

                int inFrame = 0;
                for (int j = 0; j < nv; j++)
                    for (int i = 0; i < nu; i++)
                    {
                        Vector3 p = origin + right * (uMin + (i + 0.5f) * step) + fwd * (vMin + (j + 0.5f) * step);
                        bool inHull = InsideHull(_capHull, p.x, p.z);
                        if (inHull) inFrame++;
                        _hatchGrid[j * nu + i] = inHull && !HatchPlateAt(p, top);
                        _hatchLabel[j * nu + i] = 0;
                    }
                _hatchCols.Clear();
                _hatchFrameCols.Clear();

                Vector3 seed = hatch.WorldSpaceBounds().position - origin;
                float su = Vector3.Dot(seed, right), sv = Vector3.Dot(seed, fwd);
                int bestLabel = 0, bestSize = 0, label = 0;
                float bestSqr = float.MaxValue;
                for (int start = 0; start < total; start++)
                {
                    if (!_hatchGrid[start] || _hatchLabel[start] != 0) continue;
                    label++;
                    int size = 0;
                    float nearSqr = float.MaxValue;
                    _hatchQueue.Clear();
                    _hatchQueue.Add(start);
                    _hatchLabel[start] = label;
                    for (int q = 0; q < _hatchQueue.Count; q++)
                    {
                        int cell = _hatchQueue[q];
                        int ci = cell % nu, cj = cell / nu;
                        size++;
                        float du = uMin + (ci + 0.5f) * step - su, dv = vMin + (cj + 0.5f) * step - sv;
                        float sqr = du * du + dv * dv;
                        if (sqr < nearSqr) nearSqr = sqr;
                        if (ci > 0) HatchGrow(cell - 1, label);
                        if (ci < nu - 1) HatchGrow(cell + 1, label);
                        if (cj > 0) HatchGrow(cell - nu, label);
                        if (cj < nv - 1) HatchGrow(cell + nu, label);
                    }
                    if (nearSqr < bestSqr - 1e-6f || (Mathf.Abs(nearSqr - bestSqr) <= 1e-6f && size > bestSize))
                    {
                        bestSqr = nearSqr;
                        bestSize = size;
                        bestLabel = label;
                    }
                }

                string reject = null;
                if (bestLabel == 0) reject = "no cells without the plate";
                else if (bestSqr > HatchSeedRadius * HatchSeedRadius) reject = $"nearest opening cells {Mathf.Sqrt(bestSqr):0.00} m from the hatch center";
                else if (bestSize < HatchMinOpeningCells) reject = $"opening too small ({bestSize} cells)";
                else if (bestSize > HatchMaxOpeningShare * inFrame) reject = $"opening covers {bestSize} of {inFrame} frame cells";
                if (reject != null)
                {
                    return;
                }

                float grow = AgentRadius + CellSize;
                for (int k = 0; k < 8; k++)
                {
                    float a = k * 45f * Mathf.Deg2Rad, ca = Mathf.Cos(a), sa = Mathf.Sin(a);
                    float support = float.MinValue;
                    for (int cell = 0; cell < total; cell++)
                    {
                        if (_hatchLabel[cell] != bestLabel) continue;
                        float cu = uMin + (cell % nu + 0.5f) * step, cv = vMin + (cell / nu + 0.5f) * step;
                        float s = cu * ca + cv * sa;
                        if (s > support) support = s;
                    }
                    _dopSupport[k] = support + step * 0.5f * (Mathf.Abs(ca) + Mathf.Abs(sa)) + grow;
                }

                _hatchOutline.Clear();
                float uLo = float.MaxValue, uHi = float.MinValue, vLo = float.MaxValue, vHi = float.MinValue;
                for (int k = 0; k < 8; k++)
                {
                    int k2 = (k + 1) % 8;
                    float a1 = k * 45f * Mathf.Deg2Rad, a2 = k2 * 45f * Mathf.Deg2Rad;
                    float c1 = Mathf.Cos(a1), s1 = Mathf.Sin(a1), cc = Mathf.Cos(a2), s2 = Mathf.Sin(a2);
                    float det = c1 * s2 - s1 * cc;
                    float u = (_dopSupport[k] * s2 - _dopSupport[k2] * s1) / det;
                    float v = (c1 * _dopSupport[k2] - cc * _dopSupport[k]) / det;
                    Vector3 w = origin + right * u + fwd * v;
                    var p = new Vector2(w.x, w.z);
                    if (_hatchOutline.Count > 0 && (p - _hatchOutline[_hatchOutline.Count - 1]).sqrMagnitude < 1e-4f) continue;
                    _hatchOutline.Add(p);
                    if (u < uLo) uLo = u;
                    if (u > uHi) uHi = u;
                    if (v < vLo) vLo = v;
                    if (v > vHi) vHi = v;
                }
                if (_hatchOutline.Count > 1 && (_hatchOutline[0] - _hatchOutline[_hatchOutline.Count - 1]).sqrMagnitude < 1e-4f)
                    _hatchOutline.RemoveAt(_hatchOutline.Count - 1);
                if (_hatchOutline.Count < 3)
                {
                    return;
                }
                float area2 = 0f;
                for (int i = 0; i < _hatchOutline.Count; i++)
                {
                    Vector2 p = _hatchOutline[i], q = _hatchOutline[(i + 1) % _hatchOutline.Count];
                    area2 += p.x * q.y - q.x * p.y;
                }
                if (area2 < 0f) _hatchOutline.Reverse();

                d.OpeningVolume = MakeVolume(_hatchOutline, top - HatchVolumeHalfHeight, top + HatchVolumeHalfHeight, RecastWrapper.RC_AREA_DOOR);
                d.OpeningOutline = _hatchOutline.ToArray();
                d.OpeningCells = bestSize;

                float xMin = float.MaxValue, xMax = float.MinValue, zMin = float.MaxValue, zMax = float.MinValue;
                for (int i = 0; i < _hatchOutline.Count; i++)
                {
                    Vector2 p = _hatchOutline[i];
                    if (p.x < xMin) xMin = p.x;
                    if (p.x > xMax) xMax = p.x;
                    if (p.y < zMin) zMin = p.y;
                    if (p.y > zMax) zMax = p.y;
                }
                var bounds = new Bounds();
                bounds.SetMinMax(new Vector3(xMin, top - HatchVolumeHalfHeight, zMin), new Vector3(xMax, top + HatchVolumeHalfHeight, zMax));
                d.OpeningBounds = bounds;

                d.GateBoxCenter = origin + right * ((uLo + uHi) * 0.5f) + fwd * ((vLo + vHi) * 0.5f);
                d.GateBoxHalf = new Vector3((uHi - uLo) * 0.5f + HatchGatePad, HatchGateHalfHeight, (vHi - vLo) * 0.5f + HatchGatePad);
                d.GateBoxAxis = new Vector2(right.x, right.z);
                d.HasOpening = true;
            }

            private static readonly float[] _dopSupport = new float[8];

            private static void HatchGrow(int cell, int label)
            {
                if (!_hatchGrid[cell] || _hatchLabel[cell] != 0) return;
                _hatchLabel[cell] = label;
                _hatchQueue.Add(cell);
            }

            private static bool UnderAnimator(Transform t, Transform root)
            {
                if (t == null || t == root) return false;
                for (Transform p = t.parent; p != null; p = p.parent)
                {
                    if (p.GetComponent<UnityEngine.Animator>() != null) return true;
                    if (p == root) break;
                }
                return false;
            }

            private static bool HatchPlateAt(Vector3 p, float top)
            {
                var ray = new Ray(new Vector3(p.x, top + HatchProbeUp, p.z), Vector3.down);
                float dist = HatchProbeUp + HatchPlateTol + 0.5f;
                float best = float.MinValue;
                HighestHit(_hatchCols, ray, dist, ref best);
                HighestHit(_hatchFrameCols, ray, dist, ref best);
                return best >= top - HatchPlateTol;
            }

            private static NavMeshBuildVolume MakeVolume(List<Vector2> outline, float hmin, float hmax, int area)
            {
                int n = Mathf.Min(outline.Count, MaxVolumeVerts);
                Array.Clear(_volumeXyz, 0, _volumeXyz.Length);
                for (int i = 0; i < n; i++)
                {
                    _volumeXyz[i * 3] = outline[i].x;
                    _volumeXyz[i * 3 + 2] = outline[i].y;
                }
                _volumeScratch[0] = default(NavMeshBuildVolume);
                _volumeScratch[0].nverts = n;
                _volumeScratch[0].hmin = hmin;
                _volumeScratch[0].hmax = hmax;
                _volumeScratch[0].area = area;
                var pin = System.Runtime.InteropServices.GCHandle.Alloc(_volumeScratch, System.Runtime.InteropServices.GCHandleType.Pinned);
                try
                {
                    IntPtr at = System.Runtime.InteropServices.Marshal.UnsafeAddrOfPinnedArrayElement(_volumeScratch, 0);
                    System.Runtime.InteropServices.Marshal.Copy(_volumeXyz, 0, new IntPtr(at.ToInt64() + VolumeVertsOffset), _volumeXyz.Length);
                }
                finally { pin.Free(); }
                return _volumeScratch[0];
            }

            private static long ResolveVolumeVertsOffset()
            {
                try { return System.Runtime.InteropServices.Marshal.OffsetOf(typeof(NavMeshBuildVolume), "verts").ToInt64(); }
                catch (Exception) { return 0L; }
            }

            private static void HighestHit(List<Collider> cols, Ray ray, float dist, ref float best)
            {
                for (int i = 0; i < cols.Count; i++)
                {
                    var c = cols[i];
                    if (c == null || !c.enabled || c.isTrigger || ((1 << c.gameObject.layer) & GeomMask) == 0) continue;
                    if (c.Raycast(ray, out RaycastHit hit, dist) && hit.point.y > best) best = hit.point.y;
                }
            }

            private static bool InsideHull(List<Vector2> hull, float x, float z)
            {
                for (int i = 0; i < hull.Count; i++)
                {
                    Vector2 a = hull[i], b = hull[(i + 1) % hull.Count];
                    if ((b.x - a.x) * (z - a.y) - (b.y - a.y) * (x - a.x) < 0f) return false;
                }
                return true;
            }

            private static void ConvexHull(List<Vector2> pts, List<Vector2> hull)
            {
                hull.Clear();
                pts.Sort(_byXThenY);
                for (int pass = 0; pass < 2; pass++)
                {
                    int floor = hull.Count;
                    for (int i = 0; i < pts.Count; i++)
                    {
                        Vector2 p = pts[pass == 0 ? i : pts.Count - 1 - i];
                        while (hull.Count >= floor + 2)
                        {
                            Vector2 a = hull[hull.Count - 2], b = hull[hull.Count - 1];
                            if ((b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x) > 1e-6f) break;
                            hull.RemoveAt(hull.Count - 1);
                        }
                        hull.Add(p);
                    }
                    hull.RemoveAt(hull.Count - 1);
                }
            }

            private static void AddBox(Matrix4x4 m, Vector3 size, List<Vector3> verts, List<int> tris)
            {
                Vector3 h = size * 0.5f;
                _boxVerts[0] = new Vector3(-h.x, -h.y, -h.z);
                _boxVerts[1] = new Vector3(h.x, -h.y, -h.z);
                _boxVerts[2] = new Vector3(h.x, -h.y, h.z);
                _boxVerts[3] = new Vector3(-h.x, -h.y, h.z);
                _boxVerts[4] = new Vector3(-h.x, h.y, -h.z);
                _boxVerts[5] = new Vector3(h.x, h.y, -h.z);
                _boxVerts[6] = new Vector3(h.x, h.y, h.z);
                _boxVerts[7] = new Vector3(-h.x, h.y, h.z);

                int start = verts.Count;
                for (int i = 0; i < 8; i++) verts.Add(m.MultiplyPoint3x4(_boxVerts[i]));
                for (int i = 0; i < BoxTris.Length; i++) tris.Add(start + BoxTris[i]);
            }

            #endregion

            #region Проходимость точки

            private static readonly Collider[] _fitBuf = new Collider[16];

            private const float FootingRise = 0.3f;
            private const float FootingDrop = 0.6f;

            public static bool AgentFits(Vector3 p)
            {
                float h = EffectiveAgentHeight;
                if (Physics.Raycast(p + Vector3.up * 0.1f, Vector3.up, out RaycastHit up, h, GeomMask, QueryTriggerInteraction.Ignore)
                    && up.distance + 0.1f < h)
                    return false;

                Vector3 knee = p + Vector3.up * 0.3f;
                for (int i = 0; i < 8; i++)
                {
                    float ang = i * (360f / 8f) * Mathf.Deg2Rad;
                    Vector3 dir = new Vector3(Mathf.Cos(ang), 0f, Mathf.Sin(ang));
                    if (Physics.Raycast(knee, dir, out RaycastHit side, AgentRadius * 2f, GeomMask, QueryTriggerInteraction.Ignore)
                        && side.distance < AgentRadius)
                        return false;
                }

                return HasFooting(p);
            }

            public static bool HasFooting(Vector3 p)
            {
                for (int i = 0; i < 8; i++)
                {
                    float ang = i * (360f / 8f) * Mathf.Deg2Rad;
                    var probe = new Vector3(p.x + Mathf.Cos(ang) * AgentRadius, p.y + FootingRise, p.z + Mathf.Sin(ang) * AgentRadius);
                    if (!Physics.Raycast(probe, Vector3.down, out RaycastHit floor, FootingRise + FootingDrop, GeomMask, QueryTriggerInteraction.Ignore))
                        return false;
                    if (Mathf.Abs(floor.point.y - p.y) > AgentMaxClimb) return false;
                }
                return true;
            }

            public static bool OverlapAt(Vector3 pos, float radius, out Collider blocker)
            {
                blocker = null;
                Vector3 bottom = pos + Vector3.up * (radius + 0.05f);
                Vector3 top = pos + Vector3.up * Mathf.Max(EffectiveAgentHeight - radius, radius + 0.1f);

                int n = Physics.OverlapCapsuleNonAlloc(bottom, top, radius, _fitBuf, WalkMask, QueryTriggerInteraction.Ignore);
                for (int i = 0; i < n; i++)
                {
                    if (_fitBuf[i] == null) continue;
                    blocker = _fitBuf[i];
                    return true;
                }
                return false;
            }

            #endregion

            #region Граф: двери и люки

            private static readonly List<Vector3> _sideBuf = new List<Vector3>();
            private static readonly List<Vector3> _sideDirBuf = new List<Vector3>();

            private void ComputeDoorLinks(BuildingNav nav, BuildReport report)
            {
                SetHatchesWalkable(nav, false);
                try { ComputeDoorSides(nav, report); }
                finally { AssertHatchStates(nav, null); }
            }

            private void ComputeDoorSides(BuildingNav nav, BuildReport report)
            {
                Vector3 extents = new Vector3(DoorSampleXZ, DoorSampleY, DoorSampleXZ);

                foreach (var d in nav.Doors.Values)
                {
                    d.Gate.ClearEdges();
                    d.Gate.LinkedLadderTrigger = null;
                    d.SideA = d.SideB = null;
                    d.ExtraSides?.Clear();

                    if (d.IsHatch)
                    {
                        Vector3 hatchExtents = new Vector3(DoorSampleXZ, HatchSampleY, DoorSampleXZ);
                        Vector3 aboveExtents = d.HasOpening ? new Vector3(HatchOpenSampleXZ, HatchSampleY, HatchOpenSampleXZ) : hatchExtents;
                        Vector3 aboveProbe = d.Position + Vector3.up * HatchUp;
                        bool hasAbove = SampleSide(nav, aboveProbe, aboveExtents, out Vector3 above);
                        Door leaf = d.Gate != null ? d.Gate.LinkedDoor : null;
                        Vector3 ring = above;
                        bool ringBlocked = hasAbove && d.HasOpening && !HatchTopExitClear(d, above, leaf);
                        if (ringBlocked) { hasAbove = false; report.HatchTopBlocked++; }
                        bool onLid = false;
                        if (!hasAbove && d.HasOpening && SampleSide(nav, aboveProbe, hatchExtents, out above, includeGated: true))
                        {
                            hasAbove = onLid = true;
                            report.HatchTopOnLid++;
                        }
                        if (hasAbove) d.SideA = new RecastNode(above, NodeRole.Floor);
                        Vector3 belowProbe = d.Position + Vector3.down * HatchDown;
                        if (SampleSide(nav, belowProbe, hatchExtents, out Vector3 below)
                            || SampleSide(nav, belowProbe, hatchExtents, out below, includeGated: true))
                            d.SideB = new RecastNode(below, NodeRole.Floor);
                    }
                    else
                    {
                        if (TryGeometricSides(d)) report.DoorSidesByGeometry++;
                        else FindSidesAround(nav, d, extents);
                    }

                    if (d.SideA != null) { AddDoorEdges(d, d.SideA); CountSideSurface(d.SideA, report); }
                    if (d.SideB != null) { AddDoorEdges(d, d.SideB); CountSideSurface(d.SideB, report); }
                    if (!d.IsHatch)
                    {
                        AddPassageSides(nav, d, report);
                        AddLoftSides(nav, d, report);
                    }

                    if (d.IsHatch)
                    {
                        Collider ladderCol = null;
                        Door hatch = d.Gate != null ? d.Gate.LinkedDoor : null;
                        if (hatch != null && !hatch.IsDestroyed)
                        {
                            var trigger = hatch.GetComponentInChildren<TriggerLadder>(true);
                            if (trigger != null) ladderCol = trigger.GetComponent<Collider>();
                        }
                        if (d.Gate != null) d.Gate.LinkedLadderTrigger = ladderCol;
                        if (d.SideB != null) d.SideB.LinkedLadderTrigger = ladderCol;
                    }

                    if (d.IsHatch && (d.SideA != null || d.SideB != null)) report.HatchesLinked++;

                    if (d.SideA == null && d.SideB == null && (d.ExtraSides == null || d.ExtraSides.Count == 0))
                    {
                        report.DoorsWithoutSides++;
                        Vector3 floor = FloorUnderDoor(d.Position, d.Gate != null ? d.Gate.LinkedDoor : null);
                        bool legit = !AgentFits(floor);
                        if (legit) report.DoorsWithoutSidesLegit++;
                        NoteLostDoor(nav, d, floor, legit, report);
                    }
                }
                LinkStackedHatches(nav, report);
            }

            private static void LinkStackedHatches(BuildingNav nav, BuildReport report)
            {
                foreach (var d in nav.Doors.Values)
                {
                    if (!d.IsHatch || d.SideB == null || d.Gate == null) continue;
                    foreach (var lower in nav.Doors.Values)
                    {
                        if (lower == d || !lower.IsHatch || !lower.HasOpening || lower.SideA == null || lower.Gate == null) continue;
                        Vector3 gate = lower.Gate.Position;
                        if (Mathf.Abs(d.SideB.Position.y - gate.y) > HatchStackRise || Vector3Ex.Distance2D(d.SideB.Position, gate) > HatchStackXZ) continue;
                        if (Vector3Ex.Distance2D(lower.SideA.Position, gate) < HatchStackXZ) break;
                        Collider ladder = d.SideB.LinkedLadderTrigger;
                        d.Gate.ClearEdges();
                        if (d.SideA != null) d.Gate.LinkTo(d.SideA, NodeHint.CloseDoor | (d.SideA.Position.y < d.Gate.Position.y ? NodeHint.Climb : NodeHint.None));
                        d.SideB = new RecastNode(lower.SideA.Position, NodeRole.Floor) { LinkedLadderTrigger = ladder };
                        AddDoorEdges(d, d.SideB);
                        report.HatchesStacked++;
                        break;
                    }
                }
            }

            private const float HatchStackXZ = 0.5f;
            private const float HatchStackRise = 0.5f;

            private static bool HatchTopExitClear(DoorLink d, Vector3 side, Door hatch)
            {
                if (hatch == null || hatch.IsDestroyed) return true;
                return LadderExitClear(new Vector3(d.Position.x, d.CapTop, d.Position.z), side, hatch, false);
            }

            private static void NoteLostDoor(BuildingNav nav, DoorLink d, Vector3 floor, bool legit, BuildReport report)
            {
                if (report.LostDoors.Count >= LostSamples) return;

                Vector3 p = d.Position;
                string near = "none within 5 m";
                float[] radii = { DoorSampleXZ, 1f, 2f, 5f };
                for (int i = 0; i < radii.Length; i++)
                {
                    Vector3 ext = new Vector3(radii[i], Mathf.Max(radii[i], DoorSampleY), radii[i]);
                    if (!RecastWrapper.SamplePosition(nav.Handle, in p, in ext, out Vector3 hit, out _, includeGatedDoorPolys: 0, allowNpcDoors: 0)) continue;
                    if (hit == Vector3.zero) continue;
                    near = $"nearest navmesh at {Vector3.Distance(p, hit):0.00} m (probe radius {radii[i]:0.##} m), {p.y - hit.y:0.00} m below the doorway";
                    break;
                }

                report.LostDoors.Add(new LostDoor
                {
                    Position = p,
                    Floor = floor,
                    IsHatch = d.IsHatch,
                    IsOpen = d.IsOpen,
                    AboveBoundsMin = p.y - nav.Bounds.min.y,
                    Nearest = near,
                    Legit = legit
                });
            }

            private static BuildingBlock FindDoorHost(Door door)
            {
                if (door == null) return null;
                bool hatch = IsHatchLeaf(door);
                Vector3 at = door.WorldSpaceBounds().position;
                int count = Physics.OverlapSphereNonAlloc(at, DoorHostRadius, _doorHostBuf,
                                                          1 << (int)Rust.Layer.Construction, QueryTriggerInteraction.Ignore);
                BuildingBlock best = null;
                float bestSqr = float.MaxValue;
                for (int i = 0; i < count; i++)
                {
                    var hit = _doorHostBuf[i];
                    var block = hit == null ? null
                        : (hit.gameObject.ToBaseEntity() as BuildingBlock) ?? hit.GetComponentInParent<BuildingBlock>();
                    _doorHostBuf[i] = null;
                    if (block == null || block.IsDestroyed) continue;
                    string pn = block.ShortPrefabName ?? string.Empty;
                    if (!pn.Contains("doorway") && !pn.Contains("frame") && !pn.Contains("hatch")) continue;
                    if (pn.Contains("floor") != hatch) continue;
                    float sqr = (block.transform.position - at).sqrMagnitude;
                    if (sqr >= bestSqr) continue;
                    bestSqr = sqr;
                    best = block;
                }
                return best;
            }

            private static bool TryGetDoorAxis(Door door, out Vector3 axis, out float thickness) => TryGetDoorAxis(door, out axis, out thickness, out _);

            private static bool TryGetDoorAxis(Door door, out Vector3 axis, out float thickness, out BuildingBlock host)
            {
                axis = Vector3.forward;
                thickness = DoorHostThickness;
                host = FindDoorHost(door);
                if (host == null) return false;

                OBB obb = host.WorldSpaceBounds();
                Vector3 e = obb.extents;
                bool alongX = e.x <= e.z;
                axis = obb.rotation * (alongX ? Vector3.right : Vector3.forward);
                thickness = Mathf.Max(2f * (alongX ? e.x : e.z), DoorHostThickness);
                axis.y = 0f;
                if (axis.sqrMagnitude < 1e-4f) return false;
                axis.Normalize();
                return true;
            }

            private static bool TryGeometricSides(DoorLink d)
            {
                if (!TryGetDoorAxis(d.Gate?.LinkedDoor, out Vector3 axis, out float thickness)) return false;

                Vector3 origin = d.Position;
                float offset = thickness * 0.5f + AgentRadius + DoorSideClear;
                if (!TryGeometricSide(origin + axis * offset, origin, out Vector3 a)) return false;
                if (!TryGeometricSide(origin - axis * offset, origin, out Vector3 b)) return false;

                d.SideA = new RecastNode(a, NodeRole.Floor);
                d.SideB = new RecastNode(b, NodeRole.Floor);
                return true;
            }

            private const float DoorSampleXZNarrow = 0.3f;

            private static bool OnProbeFace(Vector3 p, Vector3 origin, Vector3 dir, Vector3 axis, float thickness)
            {
                float along = Vector3.Dot(dir, axis);
                if (Mathf.Abs(along) < DoorAxisAlign) return true;
                return Vector3.Dot(p - origin, axis) * Mathf.Sign(along) > thickness * 0.5f;
            }

            private static bool SideReachableFromDoorway(Vector3 origin, Vector3 side, Door door)
                => StepClimbProfile(origin, side, origin.y, door) && !PassageRayBlocked(origin, origin.y, side, door);

            private static bool StepClimbProfile(Vector3 from, Vector3 to, float startY, Door door)
            {
                Vector3 flat = new Vector3(to.x - from.x, 0f, to.z - from.z);
                int steps = Mathf.Max(1, Mathf.CeilToInt(flat.magnitude / PassageProfileStep));
                float stepLen = flat.magnitude / steps;
                int mask = GeomMask | (1 << (int)Rust.Layer.Terrain);
                float y = startY, gap = 0f;
                for (int i = 0; i <= steps; i++)
                {
                    Vector3 at = from + flat * (i / (float)steps);
                    Vector3 top = new Vector3(at.x, y + AgentMaxClimb + 0.05f, at.z);
                    int n = Physics.RaycastNonAlloc(top, Vector3.down, _doorFloorHits, AgentMaxClimb + DoorSampleY + 0.1f, mask, QueryTriggerInteraction.Ignore);
                    float best = float.MaxValue, hitY = 0f;
                    for (int k = 0; k < n; k++)
                    {
                        var h = _doorFloorHits[k];
                        if (h.collider == null || OwnDoorPart(h.collider, door) || h.normal.y < 0.5f) continue;
                        if (h.distance >= best) continue;
                        best = h.distance;
                        hitY = h.point.y;
                    }
                    if (best == float.MaxValue)
                    {
                        gap += stepLen;
                        if (gap > DoorProfileGapMax) return false;
                        continue;
                    }
                    gap = 0f;
                    y = hitY;
                }
                return Mathf.Abs(y - to.y) <= AgentMaxClimb;
            }

            private const float DoorProfileGapMax = 0.8f;

            private static bool TryGeometricSide(Vector3 probe, Vector3 origin, out Vector3 result)
            {
                result = probe;
                if (!Physics.Raycast(probe + Vector3.up * SideDropStart, Vector3.down, out RaycastHit hit,
                                     DoorFloorProbe + SideDropStart, GeomMask, QueryTriggerInteraction.Ignore))
                    return false;
                if (Mathf.Abs(hit.point.y - origin.y) > AgentMaxClimb) return false;

                result = hit.point;
                return AgentFits(result) && !OverlapAt(result + Vector3.up * AgentRadius, AgentRadius, out _);
            }

            private const float SideDropStart = 0.5f;

            private static bool TryDoorSideInDirection(BuildingNav nav, Vector3 origin, Vector3 probe, Vector3 dir, Vector3 extents,
                                                       bool hasAxis, Vector3 doorAxis, float wallThick, Door leaf, out Vector3 side)
            {
                if (!SampleSide(nav, probe, extents, out side)) return false;
                Vector3 narrow = new Vector3(DoorSampleXZNarrow, extents.y, DoorSampleXZNarrow);
                if (hasAxis && !OnProbeFace(side, origin, dir, doorAxis, wallThick)
                    && !(SampleSide(nav, probe, narrow, out side) && OnProbeFace(side, origin, dir, doorAxis, wallThick))) return false;
                return SideReachableFromDoorway(origin, side, leaf);
            }

            private static void FindSidesAround(BuildingNav nav, DoorLink d, Vector3 extents)
            {
                _sideBuf.Clear();
                _sideDirBuf.Clear();

                Vector3 origin = d.Position;
                Door leaf = d.Gate != null ? d.Gate.LinkedDoor : null;
                bool hasAxis = TryGetDoorAxis(leaf, out Vector3 doorAxis, out float wallThick);

                for (int i = 0; i < DoorProbeDirs; i++)
                {
                    float ang = i * (360f / DoorProbeDirs) * Mathf.Deg2Rad;
                    Vector3 dir = new Vector3(Mathf.Cos(ang), 0f, Mathf.Sin(ang));
                    Vector3 probe = origin + dir * DoorApproach;
                    if (!TryDoorSideInDirection(nav, origin, probe, dir, extents, hasAxis, doorAxis, wallThick, leaf, out Vector3 p))
                    {
                        Vector3 lowProbe = new Vector3(probe.x, origin.y + (AgentMaxClimb - extents.y) * 0.5f, probe.z);
                        Vector3 lowExtents = new Vector3(extents.x, (extents.y + AgentMaxClimb) * 0.5f, extents.z);
                        if (!TryDoorSideInDirection(nav, origin, lowProbe, dir, lowExtents, hasAxis, doorAxis, wallThick, leaf, out p)) continue;
                    }
                    _sideBuf.Add(p);
                    _sideDirBuf.Add(dir);
                }

                int bestA = -1, bestB = -1;
                for (int pass = 0; pass < 2 && bestA < 0; pass++)
                {
                    float minDist = pass == 0 ? DoorSideClear : 0f;
                    float bestScore = float.MaxValue;

                    for (int i = 0; i < _sideBuf.Count; i++)
                    {
                        if ((_sideBuf[i] - origin).magnitude < minDist) continue;
                        for (int j = i + 1; j < _sideBuf.Count; j++)
                        {
                            if ((_sideBuf[j] - origin).magnitude < minDist) continue;
                            if (Vector3.Dot(_sideDirBuf[i], _sideDirBuf[j]) > -DoorOppositeDot) continue;
                            float through = DistancePointToSegmentSqr(origin, _sideBuf[i], _sideBuf[j]);
                            if (through > DoorThroughRadius * DoorThroughRadius) continue;

                            float score = through;
                            if (hasAxis)
                            {
                                float align = Mathf.Abs(Vector3.Dot(_sideDirBuf[i], doorAxis));
                                if (align < DoorAxisAlign) continue;
                                float si = Vector3.Dot(_sideBuf[i] - origin, doorAxis), sj = Vector3.Dot(_sideBuf[j] - origin, doorAxis);
                                if (si * sj >= 0f || Mathf.Abs(si) <= wallThick * 0.5f || Mathf.Abs(sj) <= wallThick * 0.5f) continue;
                                score = (1f - align) * DoorAxisWeight + through;
                            }
                            if (score >= bestScore) continue;
                            bestScore = score;
                            bestA = i; bestB = j;
                        }
                    }
                }

                if (bestA >= 0)
                {
                    d.SideA = new RecastNode(_sideBuf[bestA], NodeRole.Floor);
                    d.SideB = new RecastNode(_sideBuf[bestB], NodeRole.Floor);
                    return;
                }

                if (_sideBuf.Count > 0)
                {
                    int one = 0;
                    if (hasAxis)
                        for (int i = 0; i < _sideBuf.Count; i++)
                            if (Mathf.Abs(Vector3.Dot(_sideBuf[i] - origin, doorAxis)) > wallThick * 0.5f) { one = i; break; }
                    d.SideA = new RecastNode(_sideBuf[one], NodeRole.Floor);
                }
            }

            private static bool TryGetDoorPassage(Door door, out Vector3 centre, out float halfWidth)
            {
                Bounds own = door.bounds;
                bool thinX = own.extents.x <= own.extents.z;
                Vector3 local = own.center;
                halfWidth = thinX ? own.extents.z : own.extents.x;
                bool leaf = TryGetLeafLocalBounds(door, out Bounds lb);
                if (leaf)
                {
                    if (thinX) { local.z = lb.center.z; halfWidth = lb.extents.z; }
                    else { local.x = lb.center.x; halfWidth = lb.extents.x; }
                }
                centre = door.transform.TransformPoint(local);
                return leaf;
            }

            private static bool TryGetLeafLocalBounds(Door door, out Bounds local)
            {
                local = default;
                if (door.navGateIsGate)
                {
                    local = door.navGateApertureRawLocal;
                    return local.size.sqrMagnitude > 1e-4f;
                }
                uint prefab = door.prefabID;
                if (_leafBoundsByPrefab.TryGetValue(prefab, out local)) return local.size.sqrMagnitude > 1e-4f;
                if (door.IsOpen() || door.IsBusy()) return false;

                bool any = false;
                Matrix4x4 toLocal = door.transform.worldToLocalMatrix;
                _leafColBuf.Clear();
                door.GetComponentsInChildren(true, _leafColBuf);
                for (int i = 0; i < _leafColBuf.Count; i++)
                {
                    Collider col = _leafColBuf[i];
                    if (col == null || col.isTrigger || !IsLeafPart(col.transform, door.transform)) continue;
                    Bounds b = ColliderBoundsIn(col, toLocal);
                    if (any) local.Encapsulate(b);
                    else { local = b; any = true; }
                }
                _leafColBuf.Clear();
                if (!any) local = default;
                _leafBoundsByPrefab[prefab] = local;
                return any;
            }

            private static bool IsLeafPart(Transform t, Transform root)
            {
                string[] bones = Door.NavGateLeafBoneNames;
                for (Transform x = t; x != null && x != root; x = x.parent)
                {
                    string name = x.name;
                    if (string.Equals(name, "gate", StringComparison.OrdinalIgnoreCase)) return true;
                    for (int i = 0; i < bones.Length; i++)
                        if (string.Equals(name, bones[i], StringComparison.OrdinalIgnoreCase)) return true;
                }
                return false;
            }

            private static Bounds ColliderBoundsIn(Collider col, Matrix4x4 toLocal)
            {
                Bounds src;
                Matrix4x4 m;
                if (col is BoxCollider box)
                {
                    src = new Bounds(box.center, box.size);
                    m = toLocal * col.transform.localToWorldMatrix;
                }
                else if (col is MeshCollider mc && mc.sharedMesh != null)
                {
                    src = mc.sharedMesh.bounds;
                    m = toLocal * col.transform.localToWorldMatrix;
                }
                else
                {
                    src = col.bounds;
                    m = toLocal;
                }
                Vector3 c = src.center, e = src.extents;
                var result = new Bounds(m.MultiplyPoint3x4(c), Vector3.zero);
                for (int i = 0; i < 8; i++)
                {
                    var corner = new Vector3((i & 1) == 0 ? -e.x : e.x, (i & 2) == 0 ? -e.y : e.y, (i & 4) == 0 ? -e.z : e.z);
                    result.Encapsulate(m.MultiplyPoint3x4(c + corner));
                }
                return result;
            }

            private static readonly Dictionary<uint, Bounds> _leafBoundsByPrefab = new Dictionary<uint, Bounds>();
            private static readonly List<Collider> _leafColBuf = new List<Collider>();

            private void AddPassageSides(BuildingNav nav, DoorLink d, BuildReport report)
            {
                Door door = d.Gate != null ? d.Gate.LinkedDoor : null;
                if (door == null || door.IsDestroyed) return;
                if (!TryGetDoorAxis(door, out Vector3 normal, out float thickness)) return;
                TryGetDoorPassage(door, out _, out float halfWidth);
                var along = new Vector3(normal.z, 0f, -normal.x);
                Vector3 origin = d.Position;
                float offset = thickness * 0.5f + AgentRadius + DoorSideClear;
                float reach = Mathf.Max(0f, halfWidth - AgentRadius);
                int before = d.ExtraSides != null ? d.ExtraSides.Count : 0;
                for (int face = -1; face <= 1; face += 2)
                {
                    int added = 0;
                    for (int k = 0; k < PassageProbes && added < PassageMaxExtra; k++)
                    {
                        float t = -1f + 2f * k / (PassageProbes - 1);
                        Vector3 probe = origin + along * (reach * t) + normal * (offset * face);
                        if (!SampleSide(nav, probe, PassageSampleExtents, out Vector3 p)) continue;
                        if (Vector3.Dot(p - origin, normal) * face < thickness * 0.5f) continue;
                        if (ReachableFromFace(nav, d, p, origin, normal, face)) continue;
                        Vector3 inner = origin + along * Mathf.Clamp(Vector3.Dot(p - origin, along), -reach, reach);
                        Vector3 edge = inner + normal * ((thickness * 0.5f + PassageEdgeOut) * face);
                        if (!StepProfileWalkable(edge, p, origin.y, door)) continue;
                        if (PassageRayBlocked(inner, origin.y, p, door)) continue;
                        if (d.ExtraSides == null) d.ExtraSides = new List<RecastNode>();
                        var side = new RecastNode(p, NodeRole.Floor);
                        d.ExtraSides.Add(side);
                        AddDoorEdges(d, side);
                        CountSideSurface(side, report);
                        added++;
                    }
                }
                int extra = (d.ExtraSides != null ? d.ExtraSides.Count : 0) - before;
                if (extra <= 0) return;
            }

            private void AddLoftSides(BuildingNav nav, DoorLink d, BuildReport report)
            {
                Door door = d.Gate != null ? d.Gate.LinkedDoor : null;
                if (door == null || door.IsDestroyed) return;
                if (!TryGetDoorAxis(door, out Vector3 normal, out float thickness)) return;
                TryGetDoorPassage(door, out _, out float halfWidth);
                var along = new Vector3(normal.z, 0f, -normal.x);
                Vector3 origin = d.Position;
                float offset = thickness * 0.5f + AgentRadius + DoorSideClear;
                float reach = Mathf.Max(0f, halfWidth - AgentRadius);
                var extents = new Vector3(PassageSampleExtents.x, (DoorLoftMaxRise - AgentMaxClimb) * 0.5f, PassageSampleExtents.z);
                float probeY = origin.y + (DoorLoftMaxRise + AgentMaxClimb) * 0.5f;
                int before = d.ExtraSides != null ? d.ExtraSides.Count : 0;
                string rejected = null;
                for (int face = -1; face <= 1; face += 2)
                {
                    int added = 0;
                    for (int k = 0; k < PassageProbes && added < PassageMaxExtra; k++)
                    {
                        float t = -1f + 2f * k / (PassageProbes - 1);
                        Vector3 probe = origin + along * (reach * t) + normal * (offset * face);
                        probe.y = probeY;
                        if (!SampleSide(nav, probe, extents, out Vector3 p)) continue;
                        float rise = p.y - origin.y;
                        if (rise <= AgentMaxClimb || rise > DoorLoftMaxRise) continue;
                        if (Vector3.Dot(p - origin, normal) * face < thickness * 0.5f) continue;
                        if (SurfaceUnder(p) != JumpSurface.Construction) continue;
                        if (ReachableFromFace(nav, d, p, origin, normal, face)) continue;
                        Vector3 inner = origin + along * Mathf.Clamp(Vector3.Dot(p - origin, along), -reach, reach);
                        Vector3 edge = inner + normal * ((thickness * 0.5f + PassageEdgeOut) * face);
                        if (!StepProfileWalkable(edge, p, p.y, door)) { rejected = rejected ?? $"{p} (no half-ceiling surface from the wall face)"; continue; }
                        if (PassageRayBlocked(inner, p.y, p, door)) { rejected = rejected ?? $"{p} (blocked between the doorway and the point)"; continue; }
                        if (d.ExtraSides == null) d.ExtraSides = new List<RecastNode>();
                        var side = new RecastNode(p, NodeRole.Floor);
                        d.ExtraSides.Add(side);
                        AddDoorEdges(d, side);
                        CountSideSurface(side, report);
                        added++;
                    }
                }
            }

            private const float DoorLoftMaxRise = 1.6f;

            private bool ReachableFromFace(BuildingNav nav, DoorLink d, Vector3 p, Vector3 origin, Vector3 normal, int face)
            {
                if (FaceSideReaches(nav, d.SideA, p, origin, normal, face)) return true;
                if (FaceSideReaches(nav, d.SideB, p, origin, normal, face)) return true;
                if (d.ExtraSides != null)
                    for (int i = 0; i < d.ExtraSides.Count; i++)
                        if (FaceSideReaches(nav, d.ExtraSides[i], p, origin, normal, face)) return true;
                return false;
            }

            private bool FaceSideReaches(BuildingNav nav, RecastNode side, Vector3 p, Vector3 origin, Vector3 normal, int face)
            {
                if (side == null || Vector3.Dot(side.Position - origin, normal) * face <= 0f) return false;
                float straight = Vector3.Distance(side.Position, p);
                if (straight <= PassageSameSpot) return true;
                if (FindPathRaw(nav, side.Position, p, _passagePath, out _) != HelperSavedNavMesh.NavPathResult.Complete) return false;
                return PathLength(_passagePath) <= straight * PassageDetour + 1f;
            }

            private static bool StepProfileWalkable(Vector3 from, Vector3 to, float startY, Door door)
            {
                Vector3 flat = new Vector3(to.x - from.x, 0f, to.z - from.z);
                int steps = Mathf.Max(1, Mathf.CeilToInt(flat.magnitude / PassageProfileStep));
                float y = startY;
                for (int i = 0; i <= steps; i++)
                {
                    Vector3 at = from + flat * (i / (float)steps);
                    Vector3 top = new Vector3(at.x, y + AgentMaxClimb + 0.05f, at.z);
                    int n = Physics.RaycastNonAlloc(top, Vector3.down, _doorFloorHits, 2f * AgentMaxClimb + 0.1f, GeomMask, QueryTriggerInteraction.Ignore);
                    float best = float.MaxValue, hitY = 0f;
                    for (int k = 0; k < n; k++)
                    {
                        var h = _doorFloorHits[k];
                        if (h.collider == null || OwnDoorPart(h.collider, door) || h.normal.y < 0.5f) continue;
                        if (h.distance >= best) continue;
                        best = h.distance;
                        hitY = h.point.y;
                    }
                    if (best == float.MaxValue) return false;
                    y = hitY;
                }
                return Mathf.Abs(y - to.y) <= AgentMaxClimb;
            }

            private static bool PassageRayBlocked(Vector3 from, float startY, Vector3 to, Door door)
                => PassageRayHits(from, startY, to, PassageRayLow, door) || PassageRayHits(from, startY, to, PassageRayRise, door);

            private static bool PassageRayHits(Vector3 from, float startY, Vector3 to, float rise, Door door)
            {
                Vector3 a = new Vector3(from.x, startY + rise, from.z);
                Vector3 b = to + Vector3.up * rise;
                Vector3 dir = b - a;
                float len = dir.magnitude;
                if (len < 1e-3f) return false;
                int n = Physics.RaycastNonAlloc(a, dir / len, _doorFloorHits, len, GeomMask, QueryTriggerInteraction.Ignore);
                for (int i = 0; i < n; i++)
                {
                    Collider c = _doorFloorHits[i].collider;
                    if (c != null && !OwnDoorPart(c, door)) return true;
                }
                return false;
            }

            private const float PassageRayLow = 0.45f, PassageRayRise = 0.9f;

            private const float PassageProfileStep = 0.1f;
            private const float PassageEdgeOut = 0.05f;

            private const int PassageProbes = 5;
            private const int PassageMaxExtra = 2;
            private static readonly Vector3 PassageSampleExtents = new Vector3(0.35f, 1.2f, 0.35f);
            private const float PassageDetour = 2f;
            private const float PassageSameSpot = 0.3f;
            private readonly List<Vector3> _passagePath = new List<Vector3>();

            private static Vector3 FloorUnderDoor(Vector3 doorCenter, Door door) => FloorUnderDoor(doorCenter, door, out _, out _, out _, out _);

            private static Vector3 FloorUnderDoor(Vector3 doorCenter, Door door, out Collider ownHit, out float ownHitY,
                                                  out bool atBase, out float strayY)
            {
                ownHit = null;
                ownHitY = 0f;
                atBase = false;
                strayY = float.NaN;
                Vector3 from = doorCenter + Vector3.up * 0.2f;
                bool anchored = door != null && !IsHatchLeaf(door);
                float baseY = anchored ? door.transform.position.y : 0f;
                float probe = anchored ? Mathf.Max(DoorFloorProbe, from.y - baseY + DoorBaseSlack) : DoorFloorProbe;
                int mask = (1 << (int)Rust.Layer.Construction) | (1 << (int)Rust.Layer.Terrain) | (1 << (int)Rust.Layer.World);
                int n = Physics.RaycastNonAlloc(from, Vector3.down, _doorFloorHits, probe, mask, QueryTriggerInteraction.Ignore);

                float best = float.MaxValue, ownBest = float.MaxValue, strayBest = float.MaxValue;
                Vector3 floor = doorCenter;
                for (int i = 0; i < n; i++)
                {
                    var h = _doorFloorHits[i];
                    if (h.collider == null) continue;
                    if (OwnDoorPart(h.collider, door))
                    {
                        if (h.distance < ownBest) { ownBest = h.distance; ownHit = h.collider; ownHitY = h.point.y; }
                        continue;
                    }
                    if (anchored && Mathf.Abs(h.point.y - baseY) > DoorBaseSlack)
                    {
                        if (h.distance < strayBest) { strayBest = h.distance; strayY = h.point.y; }
                        continue;
                    }
                    if (h.distance >= best) continue;
                    best = h.distance;
                    floor = h.point;
                }
                if (ownHit != null && ownBest > best) ownHit = null;
                if (anchored && best == float.MaxValue)
                {
                    atBase = true;
                    floor = new Vector3(doorCenter.x, baseY, doorCenter.z);
                }
                else strayY = float.NaN;
                return floor;
            }

            private static bool IsHatchLeaf(Door door) =>
                Mathf.Abs(door.transform.up.y) < 0.5f || (door.ShortPrefabName ?? string.Empty).Contains("hatch");

            private static bool OwnDoorPart(Collider c, Door door) => door != null && c.transform.IsChildOf(door.transform);

            private static readonly RaycastHit[] _doorFloorHits = new RaycastHit[16];

            private static bool SampleSide(BuildingNav nav, Vector3 probe, Vector3 extents, out Vector3 result, bool includeGated = false)
            {
                result = Vector3.zero;
                if (LinkSidesToWorld)
                {
                    float radius = Mathf.Max(extents.x, extents.z);
                    if (SampleWorldNavmesh(probe, radius, out Vector3 world) && Mathf.Abs(world.y - probe.y) <= extents.y)
                    {
                        result = world;
                        return true;
                    }
                }
                if (!RecastWrapper.SamplePosition(nav.Handle, in probe, in extents, out Vector3 hit, out _,
                        includeGatedDoorPolys: includeGated ? 1 : 0, allowNpcDoors: 0)) return false;
                if (hit == Vector3.zero) return false;
                result = hit;
                return true;
            }

            private static void CountSideSurface(RecastNode side, BuildReport report)
            {
                if (SampleWorldNavmesh(side.Position, SideOnWorldProbe, out Vector3 world)
                    && Mathf.Abs(world.y - side.Position.y) <= SideOnWorldRise) report.DoorSidesOnWorld++;
                else report.DoorSidesOnOwn++;
            }

            private const float SideOnWorldProbe = 0.5f;
            private const float SideOnWorldRise = 0.3f;

            private static void AddDoorEdges(DoorLink d, RecastNode side)
            {
                NodeHint climb = d.IsHatch && side.Position.y < d.Gate.Position.y ? NodeHint.Climb : NodeHint.None;
                side.LinkTo(d.Gate, NodeHint.OpenDoor | climb);
                d.Gate.LinkTo(side, NodeHint.CloseDoor | climb);
            }

            private static float DistancePointToSegmentSqr(Vector3 point, Vector3 a, Vector3 b)
            {
                Vector3 ab = b - a;
                float len = ab.sqrMagnitude;
                if (len < 1e-6f) return (point - a).sqrMagnitude;
                float t = Mathf.Clamp01(Vector3.Dot(point - a, ab) / len);
                return (point - (a + ab * t)).sqrMagnitude;
            }

            #endregion

            #region Граф: лестницы - вертикальные переходы поверх навмеша

            private const float LandingSampleXZ = 0.6f;
            private const float LandingLevelSlack = 0.6f;
            private const float LadderFootRise = 0.3f;
            private static readonly Vector3 TreadSampleExtents = new Vector3(0.3f, 0.2f, 0.3f);
            private const float StairPathSlack = 2f;
            private const float StairPathExtra = 1.5f;
            private const float LadderApproach = 0.7f;
            private const float LadderFootDrop = 1.8f;
            private const float LadderTopDrop = 1.8f;
            private const float LadderLandingReach = 1.5f;
            private const float LadderLandingSide = 0.8f;
            private const float LandingLayerStep = 0.6f;
            private const float LandingSameLevel = 0.3f;
            private const float LadderStackGap = 0.6f;
            private const float LadderStackOverlap = 0.5f;
            private const float LadderStackXZ = 0.6f;
            private const float LadderSideReach = 1.2f;
            private const float LadderSideOverlap = 0.3f;
            private const float LadderRungStep = 0.6f;
            private const float LadderClimbOffset = 0.1f;
            private const float LadderStepOffRise = 0.4f;

            public static float SpiralTurnDeg = 180f;

            private static readonly List<BaseLadder> _ladderBuf = new List<BaseLadder>();
            private static readonly List<ClimbLink> _ladderLinks = new List<ClimbLink>();
            private static readonly List<int> _ladderGroup = new List<int>();
            private static readonly List<bool> _ladderLanded = new List<bool>();
            private readonly List<Vector3> _stairProbe = new List<Vector3>();

            public static bool TryGetStairKind(string prefab, out ClimbKind kind)
            {
                switch (prefab)
                {
                    case "block.stair.spiral":
                    case "block.stair.spiral.triangle": kind = ClimbKind.Spiral; return true;
                    case "block.stair.lshape":          kind = ClimbKind.LShape; return true;
                    case "block.stair.ushape":          kind = ClimbKind.UShape; return true;
                    default:                            kind = ClimbKind.Spiral; return false;
                }
            }

            private void ComputeClimbLinks(BuildingNav nav, BuildReport report)
            {
                nav.Climbs.Clear();

                var building = BuildingManager.server.GetBuilding(nav.BuildingID);
                if (building != null)
                {
                    var blocks = building.buildingBlocks;
                    for (int i = 0; i < blocks.Count; i++)
                    {
                        var b = blocks[i];
                        if (b == null || b.IsDestroyed) continue;
                        if (!TryGetStairKind(b.ShortPrefabName ?? string.Empty, out ClimbKind kind)) continue;
                        CheckStairDeck(nav, b, kind, report);
                    }
                }

                BuildWallLadders(nav, report);
            }

            private void CheckStairDeck(BuildingNav nav, BuildingBlock b, ClimbKind kind, BuildReport report)
            {
                if (!CollectTreadChain(b)) { report.StairNoTreads++; return; }

                int count = _treadSorted.Count, onMesh = 0;
                float walk = 0f;
                Vector3 firstBare = _treadSorted[0].Center;
                bool haveBare = false;
                Vector3 bottom = Vector3.zero, top = Vector3.zero;
                bool bottomOn = false, topOn = false;
                int lowOn = -1, highOn = -1;
                Vector3 lowHit = Vector3.zero, highHit = Vector3.zero;
                _bareTreads.Clear();
                for (int i = 0; i < count; i++)
                {
                    if (i > 0) walk += Vector3.Distance(_treadSorted[i - 1].Center, _treadSorted[i].Center);
                    Vector3 toward = count > 1 ? _treadSorted[i == 0 ? 1 : i - 1].Center : _treadSorted[i].Center;
                    if (TryTreadOnMesh(nav, _treadSorted[i], toward, out Vector3 hit))
                    {
                        onMesh++;
                        if (lowOn < 0) { lowOn = i; lowHit = hit; }
                        highOn = i;
                        highHit = hit;
                        if (i == 0) { bottom = hit; bottomOn = true; }
                        if (i == count - 1) { top = hit; topOn = true; }
                    }
                    else
                    {
                        _bareTreads.Add(i);
                        if (!haveBare) { haveBare = true; firstBare = _treadSorted[i].Center; }
                    }
                }
                float rise = _treadSorted[count - 1].Center.y - _treadSorted[0].Center.y;

                bool bottomByDoor = false, topByDoor = false;
                if (!bottomOn && lowOn >= 0 && TryDoorSideOnFlight(nav, _treadSorted[0].Center, lowHit, out Vector3 viaBottom))
                {
                    bottom = viaBottom;
                    bottomOn = bottomByDoor = true;
                }
                if (!topOn && highOn >= 0 && TryDoorSideOnFlight(nav, _treadSorted[count - 1].Center, highHit, out Vector3 viaTop))
                {
                    top = viaTop;
                    topOn = topByDoor = true;
                }

                var path = bottomOn && topOn
                    ? FindPathRaw(nav, bottom, top, _stairProbe, out _)
                    : HelperSavedNavMesh.NavPathResult.None;
                float length = path == HelperSavedNavMesh.NavPathResult.None ? 0f : PathLength(_stairProbe);
                float limit = walk * StairPathSlack + StairPathExtra;
                if (path == HelperSavedNavMesh.NavPathResult.Complete && length <= limit) { report.StairDecks++; return; }

                report.StairBroken++;
                string ends = !(bottomOn && topOn) ? string.Empty
                    : $", path between the ends {bottom} -> {top}: {path} {length:0.0} m for a flight of {walk:0.0} m (limit {limit:0.0})"
                      + (bottomByDoor ? ", bottom end from the door side" : string.Empty) + (topByDoor ? ", top end from the door side" : string.Empty);
                string inner = bottomOn && topOn ? string.Empty : StairInnerText(nav, lowOn, highOn, lowHit, highHit);
                string doors = (bottomOn ? string.Empty : StairEndDoorText(nav, "bottom", _treadSorted[0].Center))
                               + (topOn ? string.Empty : StairEndDoorText(nav, "top", _treadSorted[count - 1].Center));
                string what = $"a walkable deck: treads on the navmesh {onMesh} of {count}{StairBareText()}{ends}{inner}{doors}";
                NoteLostClimb(kind, haveBare ? firstBare : _treadSorted[0].Center, rise, what, report);
            }

            private static string StairBareText()
            {
                if (_bareTreads.Count == 0) return string.Empty;
                string text = ", bare treads";
                int shown = Mathf.Min(_bareTreads.Count, StairBareShown);
                for (int i = 0; i < shown; i++) text += (i == 0 ? " #" : ", #") + (_bareTreads[i] + 1);
                if (_bareTreads.Count > shown) text += ", ...";
                return text;
            }

            private string StairInnerText(BuildingNav nav, int lowOn, int highOn, Vector3 lowHit, Vector3 highHit)
            {
                if (lowOn < 0 || highOn <= lowOn) return string.Empty;
                float walk = 0f;
                for (int i = lowOn + 1; i <= highOn; i++) walk += Vector3.Distance(_treadSorted[i - 1].Center, _treadSorted[i].Center);
                var path = FindPathRaw(nav, lowHit, highHit, _stairProbe, out _);
                float length = path == HelperSavedNavMesh.NavPathResult.None ? 0f : PathLength(_stairProbe);
                float limit = walk * StairPathSlack + StairPathExtra;
                string reached = path == HelperSavedNavMesh.NavPathResult.Partial && _stairProbe.Count > 0
                    ? $", reached {_stairProbe[_stairProbe.Count - 1]}" : string.Empty;
                return $", path between the outermost treads on the navmesh #{lowOn + 1} {lowHit} -> #{highOn + 1} {highHit}: "
                       + $"{path} {length:0.0} m for {walk:0.0} m (limit {limit:0.0}){reached}";
            }

            private static string StairEndDoorText(BuildingNav nav, string end, Vector3 tread)
            {
                DoorLink best = null;
                float bestSqr = StairEndDoorXZ * StairEndDoorXZ;
                foreach (var d in nav.Doors.Values)
                {
                    if (d.Gate == null) continue;
                    Vector3 delta = d.Gate.Position - tread;
                    if (Mathf.Abs(delta.y) > StairEndDoorY) continue;
                    float sqr = delta.x * delta.x + delta.z * delta.z;
                    if (sqr > bestSqr) continue;
                    bestSqr = sqr;
                    best = d;
                }
                if (best == null) return $", {end} end: no doorway within {StairEndDoorXZ:0.0} m";
                Door door = best.Gate.LinkedDoor;
                return $", {end} end at doorway net={best.DoorId} {(door != null ? door.ShortPrefabName : "?")}"
                       + $" ({Mathf.Sqrt(bestSqr):0.00} m, gate {best.Gate.Position}, sides {(best.SideA != null ? best.SideA.Position.ToString() : "none")}"
                       + $" / {(best.SideB != null ? best.SideB.Position.ToString() : "none")}{StairTreadInDoorwayText(best, tread)})";
            }

            private static string StairTreadInDoorwayText(DoorLink d, Vector3 tread)
            {
                if (d.IsHatch || !d.HasOpening) return string.Empty;
                Vector3 along = new Vector3(d.GateBoxAxis.x, 0f, d.GateBoxAxis.y);
                Vector3 normal = new Vector3(-along.z, 0f, along.x);
                Vector3 off = tread - d.GateBoxCenter;
                float across = Mathf.Abs(off.x * normal.x + off.z * normal.z);
                float lengthwise = Mathf.Abs(off.x * along.x + off.z * along.z);
                float halfThick = d.GateBoxHalf.z - HatchGatePad, halfLen = d.GateBoxHalf.x - HatchGatePad;
                bool inside = across <= halfThick && lengthwise <= halfLen
                              && tread.y >= d.OpeningBounds.min.y && tread.y <= d.OpeningBounds.max.y;
                return $", tread centre {across:0.00} m from the wall plane (doorway volume half thickness {halfThick:0.00} m) - "
                       + (inside ? "inside the doorway volume" : "outside the doorway volume");
            }

            private bool TryDoorSideOnFlight(BuildingNav nav, Vector3 tread, Vector3 laidHit, out Vector3 side)
            {
                side = Vector3.zero;
                DoorLink best = null;
                float bestSqr = StairEndDoorXZ * StairEndDoorXZ;
                foreach (var d in nav.Doors.Values)
                {
                    if (d.IsHatch || d.Gate == null) continue;
                    Vector3 delta = d.Gate.Position - tread;
                    if (Mathf.Abs(delta.y) > StairEndDoorY) continue;
                    float sqr = delta.x * delta.x + delta.z * delta.z;
                    if (sqr > bestSqr) continue;
                    bestSqr = sqr;
                    best = d;
                }
                if (best == null) return false;
                if (SideReachesTread(nav, best.SideA, laidHit, ref side)) return true;
                if (SideReachesTread(nav, best.SideB, laidHit, ref side)) return true;
                if (best.ExtraSides != null)
                    for (int i = 0; i < best.ExtraSides.Count; i++)
                        if (SideReachesTread(nav, best.ExtraSides[i], laidHit, ref side)) return true;
                return false;
            }

            private bool SideReachesTread(BuildingNav nav, RecastNode node, Vector3 laidHit, ref Vector3 side)
            {
                if (node == null) return false;
                float straight = Vector3.Distance(node.Position, laidHit);
                if (FindPathRaw(nav, node.Position, laidHit, _passagePath, out _) != HelperSavedNavMesh.NavPathResult.Complete) return false;
                if (PathLength(_passagePath) > straight * PassageDetour + 1f) return false;
                side = node.Position;
                return true;
            }

            private static readonly List<int> _bareTreads = new List<int>();
            private const int StairBareShown = 8;
            private const float StairEndDoorXZ = 1.2f;
            private const float StairEndDoorY = 0.8f;

            private static bool TryTreadOnMesh(BuildingNav nav, TreadLevel level, Vector3 toward, out Vector3 hit)
            {
                hit = Vector3.zero;
                _treadOrder.Clear();
                for (int i = 0; i < level.Points.Count; i++) _treadOrder.Add(level.Points[i]);
                _treadOrder.Sort((a, b) => (a - toward).sqrMagnitude.CompareTo((b - toward).sqrMagnitude));

                Vector3 extents = TreadSampleExtents;
                for (int i = 0; i < _treadOrder.Count; i++)
                {
                    Vector3 p = _treadOrder[i];
                    if (!RecastWrapper.SamplePosition(nav.Handle, in p, in extents, out Vector3 h, out _, includeGatedDoorPolys: 0, allowNpcDoors: 0) || h == Vector3.zero) continue;
                    hit = h;
                    return true;
                }
                return false;
            }

            private static readonly List<Vector3> _treadOrder = new List<Vector3>();

            private static void BuildLadderShaft(ClimbLink link, Vector3 axis, float yBot, float yTop)
            {
                int segs = Mathf.Max(1, Mathf.CeilToInt((yTop - yBot) / LadderRungStep));
                for (int i = 0; i <= segs; i++)
                {
                    var p = new Vector3(axis.x, Mathf.Lerp(yBot, yTop, i / (float)segs), axis.z);
                    link.Shaft.Add(new RecastNode(p, NodeRole.Stair, waypointOnly: true, offMesh: true));
                }
            }

            private static void BuildWallLadders(BuildingNav nav, BuildReport report)
            {
                _ladderBuf.Clear();
                _ladderLinks.Clear();
                float radius = new Vector2(nav.Bounds.extents.x, nav.Bounds.extents.z).magnitude;
                BaseEntity.Query.Server.GetInSphere(nav.Bounds.center, radius, _ladderBuf,
                    BaseEntity.Query.DistanceCheckType.Bounds);

                var seen = new HashSet<ulong>();
                for (int i = 0; i < _ladderBuf.Count; i++)
                {
                    var ladder = _ladderBuf[i];
                    if (ladder == null || ladder.IsDestroyed || ladder.net == null) continue;
                    if (!seen.Add(ladder.net.ID.Value)) continue;

                    var trigger = ladder.GetComponentInChildren<TriggerLadder>(true);
                    var col = trigger != null ? trigger.GetComponent<Collider>() : null;
                    Bounds wb = col != null ? col.bounds : ladder.WorldSpaceBounds().ToBounds();

                    float yFoot = wb.min.y;
                    float yBot = yFoot + LadderFootRise;
                    float yTop = wb.max.y;
                    if (yTop - yBot < 0.5f) { report.ClimbDegenerate++; continue; }

                    Vector3 face = LadderClimbFace(ladder, col, wb, out Vector3 across);
                    var axis = new Vector3(face.x, yBot, face.z);
                    float split = Mathf.Max(yBot + LandingLevelSlack, yTop - LadderTopDrop);
                    FindLandings(nav, axis, across, yFoot - LadderFootDrop, yTop + LandingLevelSlack, split, ladder, _landingLevels);
                    DoorLink topDoor = FindLadderDoor(nav, axis, across, yTop, ladder);
                    float doorFloor = topDoor != null ? topDoor.Gate.Position.y - LandingSameLevel : float.MaxValue;

                    int bottomAt = -1, topAt = -1;
                    for (int k = 0; k < _landingLevels.Count; k++)
                    {
                        LadderLanding level = _landingLevels[k];
                        if (level.Point.y >= doorFloor) continue;
                        if (level.Point.y < split)
                        {
                            if (bottomAt < 0 || level.DistSqr < _landingLevels[bottomAt].DistSqr) bottomAt = k;
                        }
                        else topAt = k;
                    }

                    var link = new ClimbLink
                    {
                        Kind = ClimbKind.WallLadder,
                        SourceId = ladder.net.ID.Value,
                        Source = ladder,
                        Anchor = axis,
                        Height = yTop - yBot,
                        Bottom = bottomAt >= 0 ? new RecastNode(_landingLevels[bottomAt].Point, NodeRole.Floor) : null,
                        Top = topAt >= 0 ? new RecastNode(_landingLevels[topAt].Point, NodeRole.Floor) : null,
                        TopDoor = topDoor,
                    };
                    for (int k = 0; k < _landingLevels.Count; k++)
                    {
                        if (k == bottomAt || k == topAt || _landingLevels[k].Point.y >= doorFloor) continue;
                        link.MidLandings.Add(new RecastNode(_landingLevels[k].Point, NodeRole.Floor));
                    }
                    _landingLevels.Clear();

                    BuildLadderShaft(link, axis, yBot, yTop);

                    if (link.Bottom != null) link.Bottom.LinkedLadderTrigger = col;
                    if (link.Top != null) link.Top.LinkedLadderTrigger = col;
                    for (int s = 0; s < link.MidLandings.Count; s++) link.MidLandings[s].LinkedLadderTrigger = col;
                    for (int s = 0; s < link.Shaft.Count; s++) link.Shaft[s].LinkedLadderTrigger = col;

                    _ladderLinks.Add(link);
                }

                StackWallLadders(report);
                AddLandedLadders(nav, report);
            }

            private static void StackWallLadders(BuildReport report)
            {
                _ladderGroup.Clear();
                for (int i = 0; i < _ladderLinks.Count; i++) _ladderGroup.Add(i);

                for (int i = 0; i < _ladderLinks.Count; i++)
                {
                    var lower = _ladderLinks[i];
                    if (lower.Shaft.Count == 0) continue;
                    float lowerTop = lower.Anchor.y + lower.Height;

                    for (int j = 0; j < _ladderLinks.Count; j++)
                    {
                        if (i == j) continue;
                        var upper = _ladderLinks[j];
                        if (upper.Shaft.Count == 0) continue;

                        float gap = upper.Anchor.y - LadderFootRise - lowerTop;
                        if (gap < -LadderStackOverlap || gap > LadderStackGap) continue;
                        float dx = upper.Anchor.x - lower.Anchor.x, dz = upper.Anchor.z - lower.Anchor.z;
                        if (dx * dx + dz * dz > LadderStackXZ * LadderStackXZ) continue;

                        LinkChain(lower.Shaft[lower.Shaft.Count - 1], upper.Shaft[0], ChainHint(lower.Kind));
                        lower.StackedUp = true;
                        upper.StackedDown = true;
                        report.ClimbStacked++;
                        _ladderGroup[LadderGroupRoot(i)] = LadderGroupRoot(j);
                    }
                }

                for (int i = 0; i < _ladderLinks.Count; i++)
                {
                    var a = _ladderLinks[i];
                    if (a.Shaft.Count == 0) continue;
                    for (int j = i + 1; j < _ladderLinks.Count; j++)
                    {
                        var b = _ladderLinks[j];
                        if (b.Shaft.Count == 0) continue;
                        float dx = b.Anchor.x - a.Anchor.x, dz = b.Anchor.z - a.Anchor.z;
                        if (dx * dx + dz * dz > LadderSideReach * LadderSideReach) continue;
                        float lo = Mathf.Max(a.Shaft[0].Position.y, b.Shaft[0].Position.y);
                        float hi = Mathf.Min(a.Shaft[a.Shaft.Count - 1].Position.y, b.Shaft[b.Shaft.Count - 1].Position.y);
                        if (hi - lo < LadderSideOverlap) continue;
                        if (LinkSideRungs(a, b, lo, hi) == 0) continue;

                        a.SideLinked = true;
                        b.SideLinked = true;
                        report.ClimbSideLinked++;
                        _ladderGroup[LadderGroupRoot(i)] = LadderGroupRoot(j);
                    }
                }
            }

            private static int LinkSideRungs(ClimbLink a, ClimbLink b, float lo, float hi)
            {
                int links = 0;
                NodeHint hint = ChainHint(a.Kind);
                const float slack = 0.05f;
                for (int i = 0; i < a.Shaft.Count; i++)
                {
                    RecastNode rung = a.Shaft[i];
                    float y = rung.Position.y;
                    if (y < lo - slack || y > hi + slack) continue;

                    RecastNode best = null;
                    float bestDy = float.MaxValue;
                    for (int k = 0; k < b.Shaft.Count; k++)
                    {
                        float dy = Mathf.Abs(b.Shaft[k].Position.y - y);
                        if (dy >= bestDy) continue;
                        bestDy = dy;
                        best = b.Shaft[k];
                    }
                    if (best == null || bestDy > LadderRungStep * 0.5f + slack) continue;
                    if (!SideRungsClear(rung.Position, best.Position, a.Source, b.Source)) continue;

                    LinkChain(rung, best, hint);
                    links++;
                }
                return links;
            }

            private static bool SideRungsClear(Vector3 from, Vector3 to, BaseEntity ladderA, BaseEntity ladderB)
            {
                for (int h = 0; h < 2; h++)
                {
                    Vector3 lift = Vector3.up * (h == 0 ? LadderExitLow : LadderExitHigh);
                    Vector3 a = from + lift, d = to + lift - a;
                    float len = d.magnitude;
                    if (len < 1e-3f) continue;
                    int n = Physics.RaycastNonAlloc(a, d / len, _ladderHits, len, WalkMask, QueryTriggerInteraction.Ignore);
                    for (int i = 0; i < n; i++)
                    {
                        var c = _ladderHits[i].collider;
                        if (c != null && !OwnLadderPart(c, ladderA) && !OwnLadderPart(c, ladderB)) return false;
                    }
                }
                return true;
            }

            private static int LadderGroupRoot(int i)
            {
                while (_ladderGroup[i] != i)
                {
                    _ladderGroup[i] = _ladderGroup[_ladderGroup[i]];
                    i = _ladderGroup[i];
                }
                return i;
            }

            private static void AddLandedLadders(BuildingNav nav, BuildReport report)
            {
                _ladderLanded.Clear();
                for (int i = 0; i < _ladderLinks.Count; i++) _ladderLanded.Add(false);
                for (int i = 0; i < _ladderLinks.Count; i++)
                {
                    var l = _ladderLinks[i];
                    if (l.Bottom != null || l.Top != null || l.TopDoor != null) _ladderLanded[LadderGroupRoot(i)] = true;
                }

                for (int i = 0; i < _ladderLinks.Count; i++)
                {
                    var link = _ladderLinks[i];
                    if (!_ladderLanded[LadderGroupRoot(i)]) { report.ClimbNone++; continue; }
                    if (link.Bottom == null && !link.StackedDown && !link.SideLinked) report.ClimbNoBottom++;
                    if (link.Top == null && link.TopDoor == null && !link.StackedUp && !link.SideLinked) report.ClimbNoTop++;
                    if (link.TopDoor != null)
                    {
                        report.ClimbDoorTop++;
                    }

                    AddClimbChain(link);
                    nav.Climbs.Add(link);
                }
                _ladderLinks.Clear();
            }

            private static DoorLink FindLadderDoor(BuildingNav nav, Vector3 axis, Vector3 across, float yTop, BaseEntity ladder)
            {
                DoorLink best = null;
                float bestDist = float.MaxValue;
                foreach (var d in nav.Doors.Values)
                {
                    if (d.IsHatch || d.Gate == null) continue;
                    RecastNode inner = d.SideA != null ? d.SideA : d.SideB;
                    if (inner == null || (d.SideA != null && d.SideB != null)) continue;

                    Vector3 g = d.Gate.Position;
                    if (g.y < yTop - LadderTopDrop || g.y > yTop + LandingLevelSlack) continue;
                    float dx = g.x - axis.x, dz = g.z - axis.z;
                    float dist = dx * dx + dz * dz;
                    if (dist > LadderLandingReach * LadderLandingReach || dist >= bestDist) continue;
                    if (Mathf.Abs(dx * across.x + dz * across.z) > LadderLandingSide) continue;
                    if (dx * (inner.Position.x - g.x) + dz * (inner.Position.z - g.z) <= 0f) continue;
                    if (!LadderDoorClear(new Vector3(axis.x, g.y, axis.z), g, ladder, d.Gate.LinkedDoor)) continue;

                    best = d;
                    bestDist = dist;
                }
                return best;
            }

            private static bool LadderDoorClear(Vector3 end, Vector3 gate, BaseEntity ladder, BaseEntity door)
            {
                if (Blocked(end + Vector3.up * LadderExitLow, gate + Vector3.up * LadderExitLow, ladder, door)) return false;
                if (Blocked(end + Vector3.up * LadderExitHigh, gate + Vector3.up * LadderExitHigh, ladder, door)) return false;
                return !Blocked(end - Vector3.up * 0.5f, new Vector3(end.x, gate.y + LadderExitHigh, end.z), ladder, door);
            }

            internal static void LinkDoorTop(ClimbLink link)
            {
                DoorLink d = link.TopDoor;
                if (d == null || d.Gate == null || link.Shaft.Count == 0) return;
                RecastNode rung = StepOffRung(link, d.Gate.Position.y);
                rung.LinkTo(d.Gate, NodeHint.OpenDoor | NodeHint.Climb);
                d.Gate.LinkTo(rung, NodeHint.CloseDoor | NodeHint.Climb);
                if (d.Gate.LinkedLadderTrigger == null) d.Gate.LinkedLadderTrigger = rung.LinkedLadderTrigger;
            }

            private struct LadderLanding
            {
                public Vector3 Point;
                public float DistSqr;
            }

            private static readonly List<LadderLanding> _landingHits = new List<LadderLanding>();
            private static readonly List<LadderLanding> _landingLevels = new List<LadderLanding>();
            private static readonly Comparison<LadderLanding> _landingByHeight = (a, b) => a.Point.y.CompareTo(b.Point.y);

            private static void FindLandings(BuildingNav nav, Vector3 axis, Vector3 across, float yLow, float yHigh, float split,
                                             BaseEntity ladder, List<LadderLanding> levels)
            {
                levels.Clear();
                _landingHits.Clear();
                int layers = Mathf.Max(1, Mathf.CeilToInt((yHigh - yLow) / LandingLayerStep));
                float layer = (yHigh - yLow) / layers;
                var extents = new Vector3(LandingSampleXZ, layer * 0.5f, LandingSampleXZ);

                for (int l = 0; l < layers; l++)
                {
                    float y = yLow + layer * (l + 0.5f);
                    int before = _landingHits.Count;
                    for (int ring = 0; ring < 2 && _landingHits.Count == before; ring++)
                    {
                        float radius = LadderApproach + ring * 0.5f;
                        for (int i = 0; i < DoorProbeDirs; i++)
                        {
                            float ang = i * (360f / DoorProbeDirs) * Mathf.Deg2Rad;
                            var probe = new Vector3(axis.x + Mathf.Cos(ang) * radius, y, axis.z + Mathf.Sin(ang) * radius);
                            if (!SampleSide(nav, probe, extents, out Vector3 hit)) continue;
                            if (hit.y < yLow || hit.y > yHigh) continue;

                            float d = new Vector2(hit.x - axis.x, hit.z - axis.z).sqrMagnitude;
                            if (d > LadderLandingReach * LadderLandingReach) continue;
                            if (Mathf.Abs((hit.x - axis.x) * across.x + (hit.z - axis.z) * across.z) > LadderLandingSide) continue;
                            if (!LadderExitClear(new Vector3(axis.x, hit.y, axis.z), hit, ladder, hit.y >= split)) continue;

                            _landingHits.Add(new LadderLanding { Point = hit, DistSqr = d });
                        }
                    }
                }

                _landingHits.Sort(_landingByHeight);
                int start = 0;
                while (start < _landingHits.Count)
                {
                    float levelY = _landingHits[start].Point.y;
                    LadderLanding best = _landingHits[start];
                    int next = start + 1;
                    for (; next < _landingHits.Count && _landingHits[next].Point.y - levelY <= LandingSameLevel; next++)
                        if (_landingHits[next].DistSqr < best.DistSqr) best = _landingHits[next];
                    levels.Add(best);
                    start = next;
                }
                _landingHits.Clear();
            }

            private const float LadderSupportProbe = 1.2f;
            private const float LadderExitLow = 0.35f, LadderExitHigh = 0.9f;
            private static readonly RaycastHit[] _ladderHits = new RaycastHit[16];

            private static Vector3 LadderClimbFace(BaseEntity ladder, Collider col, Bounds wb, out Vector3 across)
            {
                across = ladder.transform.right;
                Vector3 center = wb.center;
                Vector3 depth = ladder.transform.forward;
                float half = 0f;
                if (col is BoxCollider box)
                {
                    Vector3 size = Vector3.Scale(box.size, box.transform.lossyScale);
                    center = box.transform.TransformPoint(box.center);
                    bool xThin = Mathf.Abs(size.x) <= Mathf.Abs(size.z);
                    depth = xThin ? box.transform.right : box.transform.forward;
                    half = (xThin ? Mathf.Abs(size.x) : Mathf.Abs(size.z)) * 0.5f;
                }
                depth.y = 0f;
                if (depth.sqrMagnitude < 1e-6f) return center;
                depth.Normalize();
                across = Vector3.Cross(Vector3.up, depth);

                float front = SupportDistance(ladder, center, depth);
                float back = SupportDistance(ladder, center, -depth);
                Vector3 toWall = front <= back ? depth : -depth;
                return center - toWall * (half + LadderClimbOffset);
            }

            private static float SupportDistance(BaseEntity ladder, Vector3 from, Vector3 dir)
            {
                int n = Physics.RaycastNonAlloc(from, dir, _ladderHits, LadderSupportProbe, WalkMask, QueryTriggerInteraction.Ignore);
                float best = float.MaxValue;
                for (int i = 0; i < n; i++)
                {
                    var h = _ladderHits[i];
                    if (h.collider == null || OwnLadderPart(h.collider, ladder)) continue;
                    if (h.distance < best) best = h.distance;
                }
                return best;
            }

            private static bool LadderExitClear(Vector3 end, Vector3 landing, BaseEntity ladder, bool top)
            {
                if (Blocked(end + Vector3.up * LadderExitLow, landing + Vector3.up * LadderExitLow, ladder)) return false;
                if (Blocked(end + Vector3.up * LadderExitHigh, landing + Vector3.up * LadderExitHigh, ladder)) return false;
                if (top && Blocked(end - Vector3.up * 0.5f, new Vector3(end.x, landing.y + LadderExitHigh, end.z), ladder)) return false;
                return true;
            }

            private static bool OwnLadderPart(Collider c, BaseEntity ladder) => c.transform.IsChildOf(ladder.transform);

            private static bool Blocked(Vector3 a, Vector3 b, BaseEntity ladder, BaseEntity ignore = null)
            {
                Vector3 d = b - a;
                float len = d.magnitude;
                if (len < 1e-3f) return false;
                int n = Physics.RaycastNonAlloc(a, d / len, _ladderHits, len, WalkMask, QueryTriggerInteraction.Ignore);
                for (int i = 0; i < n; i++)
                {
                    var c = _ladderHits[i].collider;
                    if (c == null || OwnLadderPart(c, ladder)) continue;
                    if (ignore != null && c.transform.IsChildOf(ignore.transform)) continue;
                    return true;
                }
                return false;
            }

            private static void AddClimbChain(ClimbLink link)
            {
                NodeHint hint = ChainHint(link.Kind);
                if (link.Shaft.Count == 0)
                {
                    if (link.Bottom != null && link.Top != null) LinkChain(link.Bottom, link.Top, hint);
                    return;
                }
                for (int i = 0; i + 1 < link.Shaft.Count; i++) LinkChain(link.Shaft[i], link.Shaft[i + 1], hint);
                if (link.Bottom != null) LinkChain(link.Bottom, StepOffRung(link, link.Bottom.Position.y), hint);
                if (link.Top != null) LinkChain(StepOffRung(link, link.Top.Position.y), link.Top, hint);
                for (int i = 0; i < link.MidLandings.Count; i++)
                    LinkChain(link.MidLandings[i], StepOffRung(link, link.MidLandings[i].Position.y), hint);
                if (link.TopDoor != null) LinkDoorTop(link);
            }

            private static RecastNode StepOffRung(ClimbLink link, float landingY)
            {
                float want = landingY + LadderStepOffRise;
                RecastNode best = link.Shaft[0];
                for (int i = 1; i < link.Shaft.Count; i++)
                    if (Mathf.Abs(link.Shaft[i].Position.y - want) < Mathf.Abs(best.Position.y - want)) best = link.Shaft[i];
                return best;
            }

            private static NodeHint ChainHint(ClimbKind kind)
            {
                return kind == ClimbKind.WallLadder ? NodeHint.Climb : NodeHint.None;
            }

            private static void LinkChain(RecastNode a, RecastNode b, NodeHint hint)
            {
                a.LinkTo(b, hint);
                b.LinkTo(a, hint);
            }

            private static void NoteLostClimb(ClimbKind kind, Vector3 probe, float rise, string what, BuildReport report)
            {
                if (report.LostClimbs.Count >= LostSamples) return;
                report.LostClimbs.Add(new LostClimb { Kind = kind, Probe = probe, Rise = rise, What = what });
            }

            #endregion

            #region Граф: входы с земли и стыки с навмешем игры

            private void ComputeEntries(BuildingNav nav, BuildReport report)
            {
                nav.Entries.Clear();

                var building = BuildingManager.server.GetBuilding(nav.BuildingID);
                if (building == null) return;

                var path = new List<Vector3>();
                var blocks = building.buildingBlocks;

                for (int i = 0; i < blocks.Count; i++)
                {
                    var b = blocks[i];
                    if (b == null) continue;

                    string pn = b.ShortPrefabName ?? string.Empty;
                    if (TryGetStairKind(pn, out _)) continue;

                    EntryKind kind;
                    if (pn.Contains("steps")) kind = EntryKind.Steps;
                    else if (pn.Contains("ramp")) kind = EntryKind.Ramp;
                    else if (pn.Contains("stair")) kind = EntryKind.Stair;
                    else continue;
                    report.EntryCandidates++;

                    OBB obb = b.WorldSpaceBounds();
                    bool alongX = obb.extents.x >= obb.extents.z;
                    Vector3 axis = alongX ? obb.rotation * Vector3.right : obb.rotation * Vector3.forward;
                    float half = (alongX ? obb.extents.x : obb.extents.z) + EntryEndPad;

                    Vector3 wide = alongX ? obb.rotation * Vector3.forward : obb.rotation * Vector3.right;
                    float wideHalf = (alongX ? obb.extents.z : obb.extents.x) * 0.6f;

                    EntryTrial pair = PickEntryPair(nav, obb, axis, half, wide, wideHalf, path, null);
                    if (pair.Stage == EntryTrialStage.NoSide) { report.EntrySkipNoSide++; continue; }
                    if (pair.Stage == EntryTrialStage.Flat) { report.EntrySkipFlat++; continue; }
                    if (pair.Stage == EntryTrialStage.NoPath) { report.EntrySkipNoPath++; continue; }

                    var outNode = new RecastNode(pair.Outside, NodeRole.Street);
                    var inNode = new RecastNode(pair.Inside, NodeRole.Floor);
                    float len = pair.Length;
                    outNode.LinkTo(inNode, NodeHint.None, len);
                    inNode.LinkTo(outNode, NodeHint.None, len);
                    nav.Entries.Add(new EntryLink { Outside = outNode, Inside = inNode, Kind = kind, PathLength = len });
                }

                foreach (var d in nav.Doors.Values)
                {
                    if (!d.IsOpen || d.IsHatch || d.SideA == null || d.SideB == null) continue;
                    if (FindPathRaw(nav, d.SideA.Position, d.SideB.Position, path, out _) != HelperSavedNavMesh.NavPathResult.Complete) continue;
                    nav.Entries.Add(new EntryLink
                    {
                        Outside = d.SideA,
                        Inside = d.SideB,
                        Kind = EntryKind.OpenDoor,
                        PathLength = PathLength(path)
                    });
                }
            }

            private const float EntrySweepPad = 1.5f;
            private const float EntrySweepStep = 0.25f;
            private const float EntrySweepXZ = 0.12f;
            private const float EntrySweepY = 1.2f;

            private enum EntryTrialStage
            {
                NoSide,
                Flat,
                NoPath,
                Entry
            }

            private struct EntryTrial
            {
                public EntryTrialStage Stage;
                public int K;
                public Vector3 ProbeA, ProbeC;
                public bool MissA, MissC;
                public Vector3 A, C;
                public bool OutsideA;
                public Vector3 Outside, Inside;
                public float Rise;
                public bool PathTried;
                public HelperSavedNavMesh.NavPathResult Path;
                public string Error;
                public int Points;
                public Vector3 Last;
                public float Gap;
                public float Length;
            }

            private EntryTrial PickEntryPair(BuildingNav nav, OBB obb, Vector3 axis, float half, Vector3 wide, float wideHalf,
                List<Vector3> path, System.Text.StringBuilder sb)
            {
                Vector3 extents = new Vector3(EntrySampleXZ, EntrySampleY, EntrySampleXZ);
                EntryTrial best = default;
                for (int k = -1; k <= 1; k++)
                {
                    EntryTrial t = ProbeEntryPair(nav, obb, axis, half, wide, wideHalf, k, extents, path, sb != null);
                    bool better = k == -1 || t.Stage > best.Stage;
                    if (better) best = t;
                    if (sb != null) AppendEntryPair(t, better && t.Stage == EntryTrialStage.Entry, sb);
                    else if (best.Stage == EntryTrialStage.Entry) break;
                }
                return best;
            }

            private EntryTrial ProbeEntryPair(BuildingNav nav, OBB obb, Vector3 axis, float half, Vector3 wide, float wideHalf, int k,
                Vector3 extents, List<Vector3> path, bool pathWhenFlat)
            {
                var t = new EntryTrial { K = k, Gap = -1f };
                Vector3 shift = wide * (k * wideHalf);
                t.ProbeA = obb.position + axis * half + shift;
                t.ProbeC = obb.position - axis * half + shift;
                t.MissA = !SampleSide(nav, t.ProbeA, extents, out Vector3 a);
                t.MissC = !SampleSide(nav, t.ProbeC, extents, out Vector3 c);
                t.A = a;
                t.C = c;
                if (t.MissA || t.MissC)
                {
                    t.Stage = EntryTrialStage.NoSide;
                    return t;
                }

                t.OutsideA = a.y <= c.y;
                t.Outside = t.OutsideA ? a : c;
                t.Inside = t.OutsideA ? c : a;
                t.Rise = t.Inside.y - t.Outside.y;
                bool flat = t.Rise < EntryMinRise;
                if (!flat || pathWhenFlat)
                {
                    t.PathTried = true;
                    t.Path = FindPathRaw(nav, t.Outside, t.Inside, path, out string error);
                    t.Error = error;
                    t.Points = path.Count;
                    t.Length = PathLength(path);
                    if (t.Path != HelperSavedNavMesh.NavPathResult.Complete && path.Count > 0)
                    {
                        t.Last = path[path.Count - 1];
                        t.Gap = Vector3.Distance(t.Last, t.Inside);
                    }
                }

                if (flat) t.Stage = EntryTrialStage.Flat;
                else if (t.Path != HelperSavedNavMesh.NavPathResult.Complete) t.Stage = EntryTrialStage.NoPath;
                else t.Stage = EntryTrialStage.Entry;
                return t;
            }

            private struct EntrySweep
            {
                public bool Has;
                public float FirstOff, FirstH, LastOff, LastH;
                public float Rise => LastH - FirstH;
            }

            public string ExplainEntries(BuildingNav nav)
            {
                if (nav == null || !nav.IsValid) return "building navmesh not built";
                var building = BuildingManager.server.GetBuilding(nav.BuildingID);
                if (building == null) return $"building {nav.BuildingID} not found";

                var sb = new System.Text.StringBuilder();
                sb.Append($"Ground entries of building {nav.BuildingID}: surface {(LinkSidesToWorld ? "game navmesh" : "own building navmesh")}, " +
                          $"recorded entries {nav.Entries.Count}; EntryEndPad {EntryEndPad:0.00}, EntryMinRise {EntryMinRise:0.00}, " +
                          $"EntrySampleXZ {EntrySampleXZ:0.00}, EntrySampleY {EntrySampleY:0.00}\n");

                var path = new List<Vector3>();
                int candidates = 0;
                var blocks = building.buildingBlocks;
                for (int i = 0; i < blocks.Count; i++)
                {
                    var b = blocks[i];
                    if (b == null) continue;

                    string pn = b.ShortPrefabName ?? string.Empty;
                    if (TryGetStairKind(pn, out _)) continue;
                    EntryKind kind;
                    if (pn.Contains("steps")) kind = EntryKind.Steps;
                    else if (pn.Contains("ramp")) kind = EntryKind.Ramp;
                    else if (pn.Contains("stair")) kind = EntryKind.Stair;
                    else continue;
                    candidates++;

                    ExplainEntryCandidate(nav, b, kind, path, sb);
                }
                if (candidates == 0) sb.Append("  no candidates (no steps / ramp / stair blocks)\n");
                return sb.ToString().TrimEnd();
            }

            private void ExplainEntryCandidate(BuildingNav nav, BuildingBlock b, EntryKind kind, List<Vector3> path, System.Text.StringBuilder sb)
            {
                OBB obb = b.WorldSpaceBounds();
                Vector3 euler = b.transform.rotation.eulerAngles;
                bool alongX = obb.extents.x >= obb.extents.z;
                bool tie = Mathf.Abs(obb.extents.x - obb.extents.z) < 0.01f;
                Vector3 right = obb.rotation * Vector3.right;
                Vector3 forward = obb.rotation * Vector3.forward;
                float half = (alongX ? obb.extents.x : obb.extents.z) + EntryEndPad;
                float wideHalf = (alongX ? obb.extents.z : obb.extents.x) * 0.6f;

                sb.Append($"[{kind}] {b.ShortPrefabName} #{(b.net != null ? b.net.ID.Value : 0UL)}: pos {EntryVec(b.transform.position)}, yaw {euler.y:0.0}, " +
                          $"rotation ({euler.x:0.0}, {euler.y:0.0}, {euler.z:0.0}); bounds centre {EntryVec(obb.position)}, extents {EntryVec(obb.extents)}; " +
                          $"alongX {(alongX ? "yes" : "no")}{(tie ? " (tie x = z)" : string.Empty)}, half {half:0.00}, wideHalf {wideHalf:0.00}\n");

                string nameA = alongX ? "right" : "forward";
                string nameB = alongX ? "forward" : "right";
                float extRight = obb.extents.x, extForward = obb.extents.z;
                EntryTrial trialA = alongX
                    ? TryEntryAxis(nav, obb, right, extRight, forward, extForward, "A", nameA, path, sb)
                    : TryEntryAxis(nav, obb, forward, extForward, right, extRight, "A", nameA, path, sb);
                EntryTrial trialB = alongX
                    ? TryEntryAxis(nav, obb, forward, extForward, right, extRight, "B", nameB, path, sb)
                    : TryEntryAxis(nav, obb, right, extRight, forward, extForward, "B", nameB, path, sb);

                EntrySweep sweepRight = SweepEntryAxis(nav, obb, right, extRight, "right", sb);
                EntrySweep sweepForward = SweepEntryAxis(nav, obb, forward, extForward, "forward", sb);

                sb.Append($"  => variant A ({nameA}): {DescribeEntryTrial(trialA)}, variant B ({nameB}): {DescribeEntryTrial(trialB)}; " +
                          $"likely cause: {EntryCause(trialA, trialB, alongX ? sweepRight : sweepForward, alongX ? sweepForward : sweepRight, nameA, nameB, tie)}\n");
            }

            private EntryTrial TryEntryAxis(BuildingNav nav, OBB obb, Vector3 axis, float axisExtent, Vector3 wide, float wideExtent,
                string label, string axisName, List<Vector3> path, System.Text.StringBuilder sb)
            {
                float half = axisExtent + EntryEndPad;
                float wideHalf = wideExtent * 0.6f;
                sb.Append($"  variant {label}: ends along {axisName} {EntryVec(axis)}, half {half:0.00}; " +
                          $"pairs of ends with one shift across, k * {wideHalf:0.00} for k = -1, 0, +1\n");
                return PickEntryPair(nav, obb, axis, half, wide, wideHalf, path, sb);
            }

            private static void AppendEntryPair(EntryTrial t, bool accepted, System.Text.StringBuilder sb)
            {
                sb.Append($"    k={t.K:+0;-0;0}: +end {EntryVec(t.ProbeA)} -> {(t.MissA ? "none" : EntryVec(t.A))}; " +
                          $"-end {EntryVec(t.ProbeC)} -> {(t.MissC ? "none" : EntryVec(t.C))}\n");
                if (t.Stage == EntryTrialStage.NoSide)
                {
                    sb.Append($"      no surface at {DescribeEntryMiss(t)} => no side\n");
                    return;
                }

                sb.Append($"      outside {(t.OutsideA ? "a (+end)" : "c (-end)")}, rise {t.Rise:0.00} {(t.Rise >= EntryMinRise ? ">=" : "<")} " +
                          $"EntryMinRise {EntryMinRise:0.00}; path outside -> inside: ");
                if (!t.PathTried) sb.Append("not searched");
                else if (t.Path == HelperSavedNavMesh.NavPathResult.Complete)
                    sb.Append($"Complete, points {t.Points}, length {t.Length:0.00} m");
                else
                    sb.Append($"{t.Path}{(t.Error != null ? " (" + t.Error + ")" : string.Empty)}, points {t.Points}" +
                              (t.Gap >= 0f ? $", last {EntryVec(t.Last)} is {t.Gap:0.00} m from inside, walked {t.Length:0.00} m" : string.Empty));
                sb.Append($" => {EntryStageName(t.Stage)}{(accepted ? ", accepted by the build" : string.Empty)}\n");
            }

            private static string EntryStageName(EntryTrialStage stage)
            {
                if (stage == EntryTrialStage.NoSide) return "no side";
                if (stage == EntryTrialStage.Flat) return "flat";
                if (stage == EntryTrialStage.NoPath) return "no path";
                return "ENTRY";
            }

            private static EntrySweep SweepEntryAxis(BuildingNav nav, OBB obb, Vector3 axis, float extent, string axisName, System.Text.StringBuilder sb)
            {
                var sweep = new EntrySweep();
                Vector3 dir = new Vector3(axis.x, 0f, axis.z);
                if (dir.sqrMagnitude < 1e-6f)
                {
                    sb.Append($"  sweep {axisName}: the axis is vertical, skipped\n");
                    return sweep;
                }
                dir.Normalize();

                Vector3 extents = new Vector3(EntrySweepXZ, EntrySweepY, EntrySweepXZ);
                int n = Mathf.CeilToInt((extent + EntrySweepPad) / EntrySweepStep - 0.001f);
                sb.Append($"  sweep {axisName} {EntryVec(dir)}, y {obb.position.y - EntrySweepY:0.00}..{obb.position.y + EntrySweepY:0.00}, " +
                          $"offset:height");

                var runs = new System.Text.StringBuilder();
                bool inRun = false;
                float runOff = 0f, runH = 0f, prevOff = 0f, prevH = 0f;
                for (int k = -n; k <= n; k++)
                {
                    float off = k * EntrySweepStep;
                    bool ok = SampleSide(nav, obb.position + dir * off, extents, out Vector3 hit);
                    sb.Append(ok ? $" {off:+0.00;-0.00;0.00}:{hit.y:0.00}" : $" {off:+0.00;-0.00;0.00}:-");
                    if (ok)
                    {
                        if (!sweep.Has) { sweep.Has = true; sweep.FirstOff = off; sweep.FirstH = hit.y; }
                        sweep.LastOff = off;
                        sweep.LastH = hit.y;
                        if (!inRun) { inRun = true; runOff = off; runH = hit.y; }
                        prevOff = off;
                        prevH = hit.y;
                        continue;
                    }
                    if (!inRun) continue;
                    inRun = false;
                    runs.Append($" [{runOff:+0.00;-0.00;0.00}..{prevOff:+0.00;-0.00;0.00}: {runH:0.00} -> {prevH:0.00}]");
                }
                if (inRun) runs.Append($" [{runOff:+0.00;-0.00;0.00}..{prevOff:+0.00;-0.00;0.00}: {runH:0.00} -> {prevH:0.00}]");
                sb.Append('\n');

                if (!sweep.Has) sb.Append("    no navmesh along this axis\n");
                else sb.Append($"    covered{runs}; height {sweep.FirstH:0.00} at {sweep.FirstOff:+0.00;-0.00;0.00} -> {sweep.LastH:0.00} at " +
                               $"{sweep.LastOff:+0.00;-0.00;0.00}: change toward +{axisName} {sweep.Rise:+0.00;-0.00;0.00} m\n");
                return sweep;
            }

            private static string DescribeEntryTrial(EntryTrial t)
            {
                if (t.Stage == EntryTrialStage.NoSide) return $"no side (pair k={t.K:+0;-0;0}: {DescribeEntryMiss(t)})";
                if (t.Stage == EntryTrialStage.Flat)
                    return $"flat (pair k={t.K:+0;-0;0}: rise {t.Rise:0.00} < {EntryMinRise:0.00}, path {t.Path})";
                if (t.Stage == EntryTrialStage.NoPath)
                    return $"no path (pair k={t.K:+0;-0;0}: rise {t.Rise:0.00}, path {t.Path}{(t.Gap >= 0f ? $", {t.Gap:0.00} m short" : string.Empty)})";
                return $"ENTRY (pair k={t.K:+0;-0;0}: rise {t.Rise:0.00}, path {t.Length:0.00} m)";
            }

            private static string DescribeEntryMiss(EntryTrial t)
                => t.MissA && t.MissC ? "both ends" : t.MissA ? "+end (a)" : "-end (c)";

            private static string EntryCause(EntryTrial a, EntryTrial b, EntrySweep sweepA, EntrySweep sweepB, string nameA, string nameB, bool tie)
            {
                if (a.Stage == EntryTrialStage.Entry)
                    return "none on this candidate: the chosen axis gives an entry";
                if (b.Stage == EntryTrialStage.Entry)
                    return $"wrong end axis: the climb runs along {nameB}, ComputeEntries picks {nameA}" +
                           (tie ? " (extents tie x = z, alongX falls to right)" : string.Empty);

                if (!sweepA.Has && !sweepB.Has)
                    return $"no navmesh along either axis within +-{EntrySweepY:0.0} m of the block centre height";
                bool climbA = sweepA.Has && (!sweepB.Has || Mathf.Abs(sweepA.Rise) >= Mathf.Abs(sweepB.Rise));
                EntryTrial t = climbA ? a : b;
                EntrySweep s = climbA ? sweepA : sweepB;
                string axisName = climbA ? nameA : nameB;
                if (Mathf.Abs(s.Rise) < EntryMinRise)
                    return $"the sweep shows no climb along either axis (largest change {s.Rise:+0.00;-0.00;0.00} m along {axisName}): " +
                           "within the sweep window the navmesh around the block is one level";

                string where = $"the sweep climbs along {axisName} ({s.Rise:+0.00;-0.00;0.00} m, {(climbA ? "the chosen axis" : "not the chosen axis")}); ";
                if (t.Stage == EntryTrialStage.NoSide)
                    return where + $"on that axis no pair finds a surface at both ends within the end sample box " +
                           $"(pair k={t.K:+0;-0;0}: none at {DescribeEntryMiss(t)})";
                if (t.Stage == EntryTrialStage.Flat)
                    return where + $"on that axis no pair of end probes climbs {EntryMinRise:0.00} m " +
                           $"(pair k={t.K:+0;-0;0}: rise {t.Rise:0.00})";
                return where + $"on that axis pair k={t.K:+0;-0;0} climbs {t.Rise:0.00} m but the path is {t.Path}" +
                       (t.Gap >= 0f ? $", {t.Gap:0.00} m short of the upper end" : string.Empty) + " - the navmesh breaks on the climb";
            }

            private static string EntryVec(Vector3 v) => $"({v.x:0.00}, {v.y:0.00}, {v.z:0.00})";

            public static float PathLength(List<Vector3> path)
            {
                float len = 0f;
                for (int i = 1; i < path.Count; i++) len += Vector3.Distance(path[i - 1], path[i]);
                return len;
            }

            public static bool SampleWorldNavmesh(Vector3 from, float radius, out Vector3 result)
            {
                result = Vector3.zero;
                if (!Rust.Ai.Gen2.RustNavMeshHelpers.SamplePosition(
                        from, out UnityEngine.AI.NavMeshHit hit, radius, Rust.Ai.Gen2.RustNavMeshHelpers.AllAreas))
                    return false;

                result = hit.position;
                return true;
            }

            #endregion

            #region Граф: прыжки через разрывы навмеша

            public static float JumpMaxDist = 3f;
            public static float JumpMinGap = 0.7f;
            public static float JumpMaxRise = 1.5f;
            private static float JumpRiseSlack => 2f * CellHeight;
            public static float JumpMaxDrop = 3f;
            public static float JumpDetourFactor = 4f;
            private const float JumpProbeStep = 0.25f;
            private const float JumpEdgeCell = 1.5f;
            private const int JumpMaxLinks = 64;
            private const float JumpSameLevelRise = 0.5f;
            private const float JumpStandHeight = 1.8f;
            private static readonly int JumpSightMask = LayerMask.GetMask("Terrain", "World", "Default", "Construction");

            private readonly Dictionary<long, int> _jumpEdgeUse = new Dictionary<long, int>();
            private readonly List<(Vector3 mid, Vector3 outward)> _jumpEdges = new List<(Vector3, Vector3)>();
            private readonly HashSet<long> _jumpTaken = new HashSet<long>();
            private readonly List<Vector3> _jumpPath = new List<Vector3>();

            public string ExplainStairAt(BuildingNav nav, Vector3 axis, float halfRise)
            {
                if (nav == null || !nav.IsValid) return (RU ? "навмеш постройки не собран" : "building navmesh not built");
                var sb = new System.Text.StringBuilder();
                sb.Append((RU ? $"Лестница у {axis}: по высоте {axis.y - halfRise:0.00}...{axis.y + halfRise:0.00} м, " : $"Stairs at {axis}: height {axis.y - halfRise:0.00}...{axis.y + halfRise:0.00} m, ") +
                          (RU ? $"рост агента {EffectiveAgentHeight:0.00}, радиус {AgentRadius:0.00}\n" : $"agent height {EffectiveAgentHeight:0.00}, radius {AgentRadius:0.00}\n"));

                Vector3 tight = new Vector3(0.2f, 0.15f, 0.2f);
                float[] radii = { 0.45f, 0.75f, 1.05f };
                const int dirs = 16;
                for (float h = axis.y - halfRise; h <= axis.y + halfRise + 0.001f; h += StairProbeStep)
                {
                    int steps = 0, onMesh = 0;
                    Vector3 firstBare = Vector3.zero;
                    bool haveBare = false;
                    for (int r = 0; r < radii.Length; r++)
                        for (int k = 0; k < dirs; k++)
                        {
                            float ang = k * Mathf.PI * 2f / dirs;
                            Vector3 top = new Vector3(axis.x + Mathf.Cos(ang) * radii[r], h + 0.25f, axis.z + Mathf.Sin(ang) * radii[r]);
                            if (!Physics.Raycast(top, Vector3.down, out RaycastHit hit, 0.45f, GeomMask, QueryTriggerInteraction.Ignore)) continue;
                            if (hit.normal.y < 0.7f) continue;
                            steps++;
                            Vector3 tread = hit.point;
                            if (RecastWrapper.SamplePosition(nav.Handle, in tread, in tight, out Vector3 m, out _, includeGatedDoorPolys: 0, allowNpcDoors: 0) && m != Vector3.zero)
                                onMesh++;
                            else if (!haveBare) { haveBare = true; firstBare = tread; }
                        }
                    if (steps == 0) { sb.Append((RU ? $"  y={h:0.00}: проступей нет\n" : $"  y={h:0.00}: no treads\n")); continue; }
                    sb.Append((RU ? $"  y={h:0.00}: проступей {steps}, с полотном {onMesh}" : $"  y={h:0.00}: treads {steps}, on navmesh {onMesh}"));
                    if (haveBare && onMesh < steps)
                        sb.Append((RU ? $"; голая {firstBare} - {DescribeBareTread(firstBare)}" : $"; uncovered {firstBare} - {DescribeBareTread(firstBare)}"));
                    sb.Append('\n');
                }
                return sb.ToString();
            }

            private const float StairProbeStep = 0.15f;

            private static string DescribeBareTread(Vector3 p)
            {
                float h = EffectiveAgentHeight;
                float headroom = Physics.Raycast(p + Vector3.up * 0.05f, Vector3.up, out RaycastHit up, 5f, GeomMask,
                                                 QueryTriggerInteraction.Ignore) ? up.distance + 0.05f : 5f;
                float clear = float.MaxValue;
                string blocker = "—";
                Vector3 knee = p + Vector3.up * 0.3f;
                for (int i = 0; i < 8; i++)
                {
                    float ang = i * Mathf.PI / 4f;
                    var dir = new Vector3(Mathf.Cos(ang), 0f, Mathf.Sin(ang));
                    if (!Physics.Raycast(knee, dir, out RaycastHit side, 3f, GeomMask, QueryTriggerInteraction.Ignore)) continue;
                    if (side.distance >= clear) continue;
                    clear = side.distance;
                    var ent = side.collider.ToBaseEntity() ?? side.collider.GetComponentInParent<BaseEntity>();
                    blocker = ent != null ? ent.ShortPrefabName : side.collider.name;
                }
                if (clear == float.MaxValue) clear = 3f;
                bool footing = HasFooting(p);
                var why = new List<string>();
                if (headroom < h) why.Add((RU ? $"низко: просвет {headroom:0.00} < {h:0.00}" : $"low: clearance {headroom:0.00} < {h:0.00}"));
                if (clear < AgentRadius) why.Add((RU ? $"тесно: до '{blocker}' {clear:0.00} < радиуса {AgentRadius:0.00}" : $"narrow: distance to '{blocker}' {clear:0.00} < agent radius {AgentRadius:0.00}"));
                if (!footing) why.Add((RU ? "нет опоры по кругу радиусом агента (ступень уже агента или уступ выше шага)" : "no footing within agent radius (tread narrower than agent or rise exceeds step height)"));
                if (why.Count == 0) why.Add((RU ? $"физически годна (просвет {headroom:0.00}, до '{blocker}' {clear:0.00}) - срезано эрозией или регион мал" : $"physically suitable (clearance {headroom:0.00}, distance to '{blocker}' {clear:0.00}) - removed by erosion or region too small"));
                return string.Join("; ", why);
            }

            public string ExplainJumpsAt(BuildingNav nav, Vector3 point, float radius)
            {
                if (nav == null || !nav.IsValid) return (RU ? "навмеш постройки не собран" : "building navmesh not built");
                var report = new BuildReport { BuildingID = nav.BuildingID };
                CollectNavmeshEdges(nav, report);

                var sb = new System.Text.StringBuilder();
                sb.Append((RU ? $"Кромки навмеша в {radius:0.#} м от {point} (всего у дома {_jumpEdges.Count}):\n" : $"Navmesh edges within {radius:0.#} m of {point} (total building edges {_jumpEdges.Count}):\n"));

                int shown = 0;
                float r2 = radius * radius;
                for (int i = 0; i < _jumpEdges.Count && shown < 12; i++)
                {
                    Vector3 mid = _jumpEdges[i].mid;
                    if ((mid - point).sqrMagnitude > r2) continue;
                    shown++;

                    var before = new BuildReport { BuildingID = nav.BuildingID };
                    bool ok = TryFindJumpLanding(nav, mid, _jumpEdges[i].outward, out Vector3 landing, out float gap, before);
                    string verdict = ok
                        ? (RU ? $"ПРЫЖОК есть -> {landing} (разрыв {gap:0.0} м, перепад {landing.y - mid.y:+0.0;-0.0} м)" : $"JUMP available -> {landing} (gap {gap:0.0} m, height difference {landing.y - mid.y:+0.0;-0.0} m)")
                        : DescribeJumpRefusal(before);
                    sb.Append((RU ? $"  {mid} (на {SurfaceUnder(mid)}, простор {(HasStandingRoom(mid) ? "в полный рост" : "низко")}): {verdict}\n" : $"  {mid} (on {SurfaceUnder(mid)}, clearance {(HasStandingRoom(mid) ? "standing" : "low")}): {verdict}\n"));
                }
                if (shown == 0) sb.Append((RU ? "  кромок рядом нет - навмеш здесь сплошной, разрыва нет\n" : "  no edges nearby - continuous navmesh here, no gap\n"));
                return sb.ToString();
            }

            public static string DescribeJump(JumpLink j)
            {
                if (j?.From == null || j.To == null) return "—";
                Vector3 a = j.From.Position, b = j.To.Position;
                string arc = JumpArcBlocker(a, b, JumpBodyProbeRadius, out string what)
                    ? (RU ? $"дуга толщиной бота: {what}" : $"arc with bot thickness: {what}") : (RU ? "дуга толщиной бота чиста" : "arc with bot thickness is clear");
                return (RU ? $"края: {DescribeJumpEnd(a)} -> {DescribeJumpEnd(b)}; {arc}" : $"ends: {DescribeJumpEnd(a)} -> {DescribeJumpEnd(b)}; {arc}");
            }

            private const float JumpBodyProbeRadius = 0.14f;

            private static string DescribeJumpEnd(Vector3 p)
                => IsInsideSolid(p) ? (RU ? $"{SurfaceUnder(p)}, ВНУТРИ блока" : $"{SurfaceUnder(p)}, INSIDE block") : SurfaceUnder(p).ToString();

            private static bool IsInsideSolid(Vector3 p)
                => IsInsideConstruction(p) || IsInsideConstruction(p + Vector3.up * JumpArcFootLift)
                   || IsInsideDeployable(p + Vector3.up * JumpArcFootLift);

            private static bool IsInsideDeployable(Vector3 p)
            {
                int n = Physics.OverlapSphereNonAlloc(p, InsideBlockReach, _insideBlockBuf, 1 << (int)Rust.Layer.Deployed, QueryTriggerInteraction.Ignore);
                bool inside = false;
                for (int i = 0; i < n; i++)
                {
                    var c = _insideBlockBuf[i];
                    _insideBlockBuf[i] = null;
                    if (inside || c == null || (c is MeshCollider mesh && !mesh.convex)) continue;
                    if ((c.ClosestPoint(p) - p).sqrMagnitude >= InsideBlockEpsSqr) continue;
                    inside = c.GetComponentInParent<DecayEntity>() != null;
                }
                return inside;
            }

            private static string DescribeJumpRefusal(BuildReport r)
            {
                var parts = new List<string>();
                if (r.JumpSkipOutside > 0) parts.Add((RU ? $"поверхность не та ({r.JumpSkipOutside})" : $"wrong surface ({r.JumpSkipOutside})"));
                if (r.JumpSkipRise > 0) parts.Add((RU ? $"перепад не по силам ({r.JumpSkipRise})" : $"height difference too large ({r.JumpSkipRise})"));
                if (r.JumpSkipLowRoom > 0) parts.Add((RU ? $"низко, не выпрямиться ({r.JumpSkipLowRoom})" : $"low clearance, cannot stand ({r.JumpSkipLowRoom})"));
                if (r.JumpSkipInside > 0) parts.Add((RU ? $"край внутри тела постройки ({r.JumpSkipInside})" : $"edge inside building geometry ({r.JumpSkipInside})"));
                if (r.JumpSkipDeployCut > 0) parts.Add((RU ? $"вырез под деплоем, не разрыв ({r.JumpSkipDeployCut})" : $"deployable cutout, not a gap ({r.JumpSkipDeployCut})"));
                if (r.JumpSkipDoorway > 0) parts.Add((RU ? $"дверной проём, не разрыв ({r.JumpSkipDoorway})" : $"doorway, not a gap ({r.JumpSkipDoorway})"));
                if (r.JumpSkipBlocked > 0) parts.Add((RU ? $"преграда на дуге ({r.JumpSkipBlocked})" : $"arc blocked ({r.JumpSkipBlocked})"));
                if (r.JumpSkipReachable > 0) parts.Add((RU ? $"и так дойдёт пешком ({r.JumpSkipReachable})" : $"already reachable on foot ({r.JumpSkipReachable})"));
                return parts.Count == 0
                    ? (RU ? "площадки на той стороне нет вовсе (навмеша за разрывом не нашлось)" : "no landing area on the other side (no navmesh beyond gap)")
                    : (RU ? "нет прыжка: " : "no jump: ") + string.Join(", ", parts);
            }

            public enum WindowEntryKind
            {
                NotWindow,
                NoInside,
                Narrow,
                NoGround,
                DirectJump,
                NeedsLadder,
                TooHigh
            }

            public struct WindowAssessment
            {
                public BaseEntity Insert;
                public bool OpenWithoutInsert;
                public float SillY, HeadY, HalfWidth;
                public Vector3 NearNormal, Center;
                public bool HasInsideLanding;
                public Vector3 InsideLanding;
                public float NearGroundY, Rise;
                public WindowEntryKind Kind;
                public Vector3 LadderSupport;
                public float LadderYaw;
            }

            public const float LadderReach = 2.6f;

            public static bool TryAssessWindow(uint buildingID, BuildingBlock window, Vector3 fromPos, out WindowAssessment result)
            {
                result = new WindowAssessment { Kind = WindowEntryKind.NotWindow, NearGroundY = float.NaN, Rise = float.NaN };
                if (!IsWindowBlock(window) || !Instance.TryGet(buildingID, out BuildingNav nav)) return false;

                result.Insert = FindWindowInsert(window);
                result.Center = window.WorldSpaceBounds().ToBounds().center;
                Vector3 normal = window.transform.right;
                normal.y = 0f;
                normal.Normalize();
                if (Vector3.Dot(fromPos - result.Center, normal) < 0f) normal = -normal;
                result.NearNormal = normal;

                MeasureWindowOpening(window, out result.SillY, out result.HeadY, out float halfLeft, out float halfRight,
                    out bool open, result.Insert);
                result.HalfWidth = Mathf.Min(halfLeft, halfRight);
                result.OpenWithoutInsert = open && halfLeft + halfRight >= 0.7f - 0.0001f;
                result.HasInsideLanding = TryFindWindowLanding(nav, result.Center, -normal, result.SillY, out result.InsideLanding);
                if (TryFindWindowLanding(nav, result.Center, normal, result.SillY, out Vector3 nearLanding))
                    result.NearGroundY = nearLanding.y;
                else
                {
                    Vector3 probe = result.Center + normal * 0.9f;
                    probe.y = result.SillY;
                    if (Physics.Raycast(probe, Vector3.down, out RaycastHit hit, 6f, WalkMask, QueryTriggerInteraction.Ignore))
                        result.NearGroundY = hit.point.y;
                }
                result.Rise = result.SillY - result.NearGroundY;

                if (!result.HasInsideLanding) result.Kind = WindowEntryKind.NoInside;
                else if (!result.OpenWithoutInsert) result.Kind = WindowEntryKind.Narrow;
                else if (float.IsNaN(result.NearGroundY)) result.Kind = WindowEntryKind.NoGround;
                else if (result.Rise <= JumpMaxRise) result.Kind = WindowEntryKind.DirectJump;
                else if (result.Rise <= LadderReach)
                {
                    result.Kind = WindowEntryKind.NeedsLadder;
                    result.LadderSupport = new Vector3(result.Center.x + normal.x * 0.27f, result.NearGroundY,
                        result.Center.z + normal.z * 0.27f);
                    result.LadderYaw = Quaternion.LookRotation(-normal).eulerAngles.y;
                }
                else result.Kind = WindowEntryKind.TooHigh;
                return true;
            }

            private static void MeasureWindowOpening(BuildingBlock block, out float sillY, out float headY,
                out float halfLeft, out float halfRight, out bool open, BaseEntity ignoredInsert = null)
            {
                Vector3 center = block.WorldSpaceBounds().ToBounds().center;
                Vector3 normal = block.transform.right;
                normal.y = 0f;
                normal.Normalize();
                Vector3 along = block.transform.forward;
                along.y = 0f;
                along.Normalize();
                float baseY = block.transform.position.y;
                sillY = headY = halfLeft = halfRight = 0f;
                float runStart = 0f;
                bool inRun = false;
                for (int h = 0; h <= 52; h++)
                {
                    float y = baseY + 0.4f + h * 0.05f;
                    bool rayOpen = WindowRayOpen(center, normal, y, ignoredInsert);
                    if (rayOpen && !inRun) { runStart = y; inRun = true; }
                    if (inRun && (!rayOpen || h == 52))
                    {
                        float end = rayOpen ? y : y - 0.05f;
                        float start = Mathf.Max(runStart, baseY + 0.8f);
                        if (end - start > headY - sillY) { sillY = start; headY = end; }
                        inRun = false;
                    }
                }
                open = headY - sillY >= 0.9f - 0.0001f && (ignoredInsert != null || !HasWindowInsert(block));
                if (!open) return;
                float midY = (sillY + headY) * 0.5f;
                if (!WindowRayOpen(center, normal, midY, ignoredInsert)) return;
                for (int w = 1; w <= 24; w++)
                {
                    float offset = w * 0.05f;
                    if (!WindowRayOpen(center - along * offset, normal, midY, ignoredInsert)) break;
                    halfLeft = offset;
                }
                for (int w = 1; w <= 24; w++)
                {
                    float offset = w * 0.05f;
                    if (!WindowRayOpen(center + along * offset, normal, midY, ignoredInsert)) break;
                    halfRight = offset;
                }
            }

            private static RaycastHit[] _windowHits = new RaycastHit[64];

            private static bool WindowRayOpen(Vector3 center, Vector3 normal, float y, BaseEntity ignoredInsert = null)
            {
                Vector3 origin = center - normal * 1.2f;
                origin.y = y;
                while (true)
                {
                    int count = Physics.RaycastNonAlloc(origin, normal, _windowHits, 2.4f, WalkMask, QueryTriggerInteraction.Ignore);
                    for (int i = 0; i < count; i++)
                    {
                        Collider collider = _windowHits[i].collider;
                        if (collider == null || collider.GetComponentInParent<BaseLadder>() != null) continue;
                        if (ignoredInsert != null && collider.transform.IsChildOf(ignoredInsert.transform)) continue;
                        return false;
                    }
                    if (count < _windowHits.Length) return true;
                    Array.Resize(ref _windowHits, _windowHits.Length * 2);
                }
            }

            private static bool HasWindowInsert(BuildingBlock block) => FindWindowInsert(block) != null;

            private static BaseEntity FindWindowInsert(BuildingBlock block)
            {
                List<BaseEntity> entities = Pool.Get<List<BaseEntity>>();
                try
                {
                    block.GetComponentsInChildren<BaseEntity>(true, entities);
                    for (int i = 0; i < entities.Count; i++)
                    {
                        BaseEntity child = entities[i];
                        if (IsWindowInsert(child) && child.GetParentEntity() == block) return child;
                    }
                    entities.Clear();
                    Vis.Entities(block.transform.position + Vector3.up, 1.2f, entities, -1, QueryTriggerInteraction.Ignore);
                    for (int i = 0; i < entities.Count; i++)
                    {
                        BaseEntity insert = entities[i];
                        if (IsWindowInsert(insert) && FindWindowOfInsert(insert, block.buildingID) == block) return insert;
                    }
                    return null;
                }
                finally
                {
                    Pool.FreeUnmanaged(ref entities);
                }
            }

            private static bool TryFindWindowLanding(BuildingNav nav, Vector3 center, Vector3 normal, float sillY, out Vector3 landing)
            {
                landing = Vector3.zero;
                float lowY = sillY - JumpMaxRise - 0.2f;
                float highY = sillY - 0.3f;
                Vector3 extents = new Vector3(0.35f, 0.05f, 0.35f);
                Vector3 probe = center + normal * 0.9f;
                int samples = Mathf.CeilToInt((highY - lowY) / 0.05f);
                for (int h = 0; h <= samples; h++)
                {
                    probe.y = Mathf.Max(lowY, highY - h * 0.05f);
                    if (!RecastWrapper.SamplePosition(nav.Handle, in probe, in extents, out Vector3 hit, out _,
                        includeGatedDoorPolys: 0, allowNpcDoors: 0)) continue;
                    if (hit.y < lowY || hit.y > highY || Vector3.Dot(hit - center, normal) <= 0f) continue;
                    landing = hit;
                    return true;
                }
                return false;
            }

            private void ComputeJumpLinks(BuildingNav nav, BuildReport report)
            {
                if (nav == null || !nav.IsValid) return;

                CollectNavmeshEdges(nav, report);
                _jumpTaken.Clear();

                for (int i = 0; i < _jumpEdges.Count && nav.Jumps.Count < JumpMaxLinks; i++)
                {
                    Vector3 mid = _jumpEdges[i].mid;
                    Vector3 outward = _jumpEdges[i].outward;

                    long cell = CellKey(mid, JumpEdgeCell);
                    if (_jumpTaken.Contains(cell)) { report.JumpSkipDuplicate++; continue; }

                    if (!TryFindJumpLanding(nav, mid, outward, out Vector3 landing, out float gap, report)) continue;

                    _jumpTaken.Add(cell);

                    float rise = landing.y - mid.y;
                    var from = new RecastNode(mid, NodeRole.Floor);
                    var to = new RecastNode(landing, NodeRole.Floor);
                    float cost = gap + Mathf.Abs(rise);

                    from.LinkTo(to, NodeHint.Jump, cost);
                    bool twoWay = -rise <= JumpMaxRise + JumpRiseSlack && (rise > -JumpSameLevelRise || HasStandingRoom(landing));
                    if (twoWay) to.LinkTo(from, NodeHint.Jump, cost);

                    nav.Jumps.Add(new JumpLink { From = from, To = to, Gap = gap, Rise = rise, TwoWay = twoWay });
                }
            }

            private void CollectNavmeshEdges(BuildingNav nav, BuildReport report)
            {
                _jumpEdges.Clear();
                _jumpEdgeUse.Clear();

                for (int ty = 0; ty < nav.TileNum.y; ty++)
                    for (int tx = 0; tx < nav.TileNum.x; tx++)
                    {
                        if (!GetTilePolys(nav, tx, ty, out int polys)) continue;
                        for (int p = 0; p < polys; p++)
                        {
                            if (PolyAreaBuffer[p] == DoorApertureArea) continue;
                            ForEachPolyEdge(p, (a, b) =>
                            {
                                long key = EdgeKey(a, b);
                                _jumpEdgeUse.TryGetValue(key, out int used);
                                _jumpEdgeUse[key] = used + 1;
                            });
                        }
                    }

                for (int ty = 0; ty < nav.TileNum.y; ty++)
                    for (int tx = 0; tx < nav.TileNum.x; tx++)
                    {
                        if (!GetTilePolys(nav, tx, ty, out int polys)) continue;
                        for (int p = 0; p < polys; p++)
                        {
                            if (PolyAreaBuffer[p] == DoorApertureArea) continue;
                            Vector3 centre = PolyCentre(p);
                            ForEachPolyEdge(p, (a, b) =>
                            {
                                if (_jumpEdgeUse.TryGetValue(EdgeKey(a, b), out int used) && used != 1) return;
                                Vector3 mid = (a + b) * 0.5f;
                                Vector3 outward = mid - centre; outward.y = 0f;
                                if (outward.sqrMagnitude < 0.0001f) return;
                                _jumpEdges.Add((mid, outward.normalized));
                                report.JumpEdges++;
                            });
                        }
                    }
            }

            private static void ForEachPolyEdge(int poly, Action<Vector3, Vector3> action)
            {
                int start = poly * VertsPerPoly;
                int count = 0;
                for (int v = 0; v < VertsPerPoly; v++)
                {
                    if (PolyBuffer[start + v] == Vector3.zero) break;
                    count++;
                }
                if (count < 3) return;
                for (int v = 0; v < count; v++)
                    action(PolyBuffer[start + v], PolyBuffer[start + (v + 1) % count]);
            }

            private static Vector3 PolyCentre(int poly)
            {
                int start = poly * VertsPerPoly;
                Vector3 sum = Vector3.zero;
                int count = 0;
                for (int v = 0; v < VertsPerPoly; v++)
                {
                    Vector3 p = PolyBuffer[start + v];
                    if (p == Vector3.zero) break;
                    sum += p;
                    count++;
                }
                return count > 0 ? sum / count : Vector3.zero;
            }

            private static long EdgeKey(Vector3 a, Vector3 b)
            {
                long ka = VertexKey(a), kb = VertexKey(b);
                long lo = Math.Min(ka, kb), hi = Math.Max(ka, kb);
                return lo * 31L + hi;
            }

            private static long VertexKey(Vector3 v)
                => ((long)Mathf.RoundToInt(v.x * 100f) & 0x1FFFFF)
                   | (((long)Mathf.RoundToInt(v.y * 100f) & 0x1FFFFF) << 21)
                   | (((long)Mathf.RoundToInt(v.z * 100f) & 0x1FFFFF) << 42);

            private static long CellKey(Vector3 v, float cell)
                => ((long)Mathf.FloorToInt(v.x / cell) & 0x1FFFFF)
                   | (((long)Mathf.FloorToInt(v.y / cell) & 0x1FFFFF) << 21)
                   | (((long)Mathf.FloorToInt(v.z / cell) & 0x1FFFFF) << 42);

            private bool TryFindJumpLanding(BuildingNav nav, Vector3 edge, Vector3 outward, out Vector3 landing,
                                            out float gap, BuildReport report)
            {
                landing = edge;
                gap = 0f;

                if (IsInsideSolid(edge)) { report.JumpSkipInside++; return false; }

                bool edgeRoom = HasStandingRoom(edge);

                for (float dist = JumpMinGap; dist <= JumpMaxDist; dist += JumpProbeStep)
                {
                    Vector3 probe = edge + outward * dist;
                    Vector3 extents = SampleExtents;
                    extents.y = Mathf.Max(JumpMaxDrop, JumpMaxRise) + 0.5f;
                    if (!RecastWrapper.SamplePosition(nav.Handle, in probe, in extents, out Vector3 hit, out _, includeGatedDoorPolys: 0, allowNpcDoors: 0)
                        || hit == Vector3.zero) continue;

                    float flat = Vector3.Distance(new Vector3(hit.x, 0f, hit.z), new Vector3(edge.x, 0f, edge.z));
                    if (flat < JumpMinGap || flat > JumpMaxDist) continue;

                    JumpVeto veto = CheckJumpPair(nav, edge, hit, edgeRoom, out string blocker);
                    if (veto != JumpVeto.None)
                    {
                        switch (veto)
                        {
                            case JumpVeto.Rise: report.JumpSkipRise++; break;
                            case JumpVeto.Inside: report.JumpSkipInside++; break;
                            case JumpVeto.Surface: report.JumpSkipOutside++; break;
                            case JumpVeto.LowRoom: report.JumpSkipLowRoom++; break;
                            case JumpVeto.DeployCut: report.JumpSkipDeployCut++; break;
                            case JumpVeto.Doorway: report.JumpSkipDoorway++; break;
                            case JumpVeto.Blocked:
                                report.JumpSkipBlocked++;
                                if (!JumpPathBlocker(edge, hit, 0f, out _)) report.NoteJumpSlip(edge, hit, blocker);
                                break;
                        }
                        continue;
                    }

                    if (FindPathRaw(nav, edge, hit, _jumpPath, out _) == HelperSavedNavMesh.NavPathResult.Complete
                        && PathLength(_jumpPath) <= flat * JumpDetourFactor)
                    { report.JumpSkipReachable++; continue; }

                    landing = PullLandingToEdge(nav, edge, hit, edgeRoom);
                    gap = Vector3.Distance(new Vector3(landing.x, 0f, landing.z), new Vector3(edge.x, 0f, edge.z));
                    if (gap < JumpMinGap) { report.JumpSkipReachable++; continue; }
                    return true;
                }
                return false;
            }

            private enum JumpVeto { None, Rise, Inside, Surface, LowRoom, DeployCut, Doorway, Blocked }

            private static JumpVeto CheckJumpPair(BuildingNav nav, Vector3 edge, Vector3 hit, bool edgeRoom, out string blocker)
            {
                blocker = null;
                float rise = hit.y - edge.y;
                if (rise > JumpMaxRise + JumpRiseSlack || -rise > JumpMaxDrop) return JumpVeto.Rise;

                if (IsInsideSolid(hit)) return JumpVeto.Inside;

                JumpSurface surfA = SurfaceUnder(edge), surfB = SurfaceUnder(hit);
                if (surfA == JumpSurface.None || surfB == JumpSurface.None
                    || (surfA == JumpSurface.Terrain && surfB == JumpSurface.Terrain))
                    return JumpVeto.Surface;

                bool level = Mathf.Abs(rise) <= JumpSameLevelRise;
                if (rise > -JumpSameLevelRise && !edgeRoom) return JumpVeto.LowRoom;
                if (level && !HasStandingRoom(hit)) return JumpVeto.LowRoom;

                if (level && IsDeployBetween(edge, hit)) return JumpVeto.DeployCut;

                if (IsDoorwayBetween(nav, edge, hit)) return JumpVeto.Doorway;

                if (JumpPathBlocker(edge, hit, JumpArcProbeRadius, out blocker)) return JumpVeto.Blocked;

                return JumpVeto.None;
            }

            private const float JumpEdgePullStep = 0.1f;

            private static readonly List<Vector3> _pullBuf = new List<Vector3>();

            private static Vector3 PullLandingToEdge(BuildingNav nav, Vector3 edge, Vector3 landing, bool edgeRoom)
            {
                Vector3 toEdge = edge - landing; toEdge.y = 0f;
                float span = toEdge.magnitude;
                if (span < JumpEdgePullStep) return landing;
                toEdge /= span;

                _pullBuf.Clear();
                Vector3 extents = SampleExtents;
                for (float moved = JumpEdgePullStep; moved < span - JumpMinGap; moved += JumpEdgePullStep)
                {
                    Vector3 probe = landing + toEdge * moved;
                    if (!RecastWrapper.SamplePosition(nav.Handle, in probe, in extents, out Vector3 hit, out _, includeGatedDoorPolys: 0, allowNpcDoors: 0)
                        || hit == Vector3.zero) break;
                    if (Mathf.Abs(hit.y - landing.y) > AgentMaxClimb) break;
                    if (IsInsideSolid(hit)) break;
                    if (Vector3.Distance(new Vector3(hit.x, 0f, hit.z), new Vector3(edge.x, 0f, edge.z)) < JumpMinGap) continue;
                    _pullBuf.Add(hit);
                }

                for (int i = _pullBuf.Count - 1; i >= 0; i--)
                    if (CheckJumpPair(nav, edge, _pullBuf[i], edgeRoom, out _) == JumpVeto.None) return _pullBuf[i];
                return landing;
            }

            private enum JumpSurface
            {
                None,
                Terrain,
                Deployable,
                Construction,
            }

            private const float SurfaceProbeDown = 0.5f;
            private static readonly RaycastHit[] _surfaceHits = new RaycastHit[8];
            private static JumpSurface SurfaceUnder(Vector3 p)
            {
                const float lift = 0.2f;
                int count = Physics.RaycastNonAlloc(p + Vector3.up * lift, Vector3.down, _surfaceHits,
                                                    SurfaceProbeDown + lift, GeomMask | (1 << (int)Rust.Layer.Terrain),
                                                    QueryTriggerInteraction.Ignore);
                Collider surface = null;
                float nearest = float.MaxValue;
                for (int i = 0; i < count; i++)
                {
                    RaycastHit h = _surfaceHits[i];
                    if (h.distance >= nearest || h.collider.gameObject.ToBaseEntity() is DebrisEntity) continue;
                    surface = h.collider;
                    nearest = h.distance;
                }
                if (surface == null) return JumpSurface.None;

                int layer = surface.gameObject.layer;
                if (layer == (int)Rust.Layer.Construction) return JumpSurface.Construction;
                if (layer == (int)Rust.Layer.Terrain) return JumpSurface.Terrain;
                if (layer == (int)Rust.Layer.Deployed)
                    return surface.GetComponentInParent<DecayEntity>() != null
                        ? JumpSurface.Deployable : JumpSurface.None;
                return JumpSurface.None;
            }

            private const int JumpArcSteps = 8;
            private const float JumpArcHeight = 0.5f;
            private const float JumpArcFootLift = 0.15f;

            private const float JumpArcProbeRadius = 0.08f;
            private static readonly int JumpArcSweepMask = LayerMask.GetMask("World", "Default", "Construction");

            private static bool JumpArcBlocker(Vector3 from, Vector3 to, float radius, out string what)
            {
                what = null;
                float head = EffectiveAgentHeight;
                Vector3 prevFoot = ArcPoint(from, to, 0f) + Vector3.up * JumpArcFootLift;
                Vector3 prevHead = prevFoot + Vector3.up * head;
                for (int i = 1; i <= JumpArcSteps; i++)
                {
                    float t = (float)i / JumpArcSteps;
                    Vector3 foot = ArcPoint(from, to, t) + Vector3.up * JumpArcFootLift;
                    Vector3 headPt = foot + Vector3.up * head;
                    if (ArcSegmentHit(prevFoot, foot, radius, out RaycastHit hit))
                    {
                        what = $"'{HitName(hit)}' at feet, arc fraction {t:0.00}";
                        return true;
                    }
                    if (t > JumpHeadSkipEnds && t < 1f - JumpHeadSkipEnds && ArcSegmentHit(prevHead, headPt, radius, out hit))
                    {
                        what = $"'{HitName(hit)}' at head, arc fraction {t:0.00}";
                        return true;
                    }
                    prevFoot = foot;
                    prevHead = headPt;
                }
                return false;
            }

            private static bool JumpPathBlocker(Vector3 from, Vector3 to, float radius, out string what)
                => Mathf.Abs(to.y - from.y) <= JumpSameLevelRise
                    ? JumpArcBlocker(from, to, radius, out what)
                    : JumpCornerBlocker(from, to, radius, out what);

            private static bool JumpCornerBlocker(Vector3 from, Vector3 to, float radius, out string what)
            {
                what = null;
                Vector3 low = from.y <= to.y ? from : to, high = from.y <= to.y ? to : from;
                Vector3 corner = new Vector3(low.x, high.y, low.z);
                Vector3 feet = Vector3.up * JumpArcFootLift, head = Vector3.up * AgentHeightCrouch;
                if (ArcSegmentHit(low + feet, corner + feet, radius, out RaycastHit hit))
                {
                    what = $"'{HitName(hit)}' at feet, rising over the lower edge";
                    return true;
                }
                if (ArcSegmentHit(corner + feet, high + feet, radius, out hit))
                {
                    what = $"'{HitName(hit)}' at feet, over the upper edge";
                    return true;
                }
                if (ArcSegmentHit(corner + head, high + head, radius, out hit))
                {
                    what = $"'{HitName(hit)}' at head, over the upper floor";
                    return true;
                }
                return false;
            }

            private static bool ArcSegmentHit(Vector3 a, Vector3 b, float radius, out RaycastHit hit)
            {
                if (radius <= 0f) return Physics.Linecast(a, b, out hit, JumpSightMask, QueryTriggerInteraction.Ignore);
                if (Physics.Linecast(a, b, out hit, 1 << (int)Rust.Layer.Terrain, QueryTriggerInteraction.Ignore)) return true;
                Vector3 d = b - a;
                float len = d.magnitude;
                if (len < 0.0001f) return false;
                return Physics.SphereCast(a, radius, d / len, out hit, len, JumpArcSweepMask, QueryTriggerInteraction.Ignore);
            }

            private static string HitName(RaycastHit hit)
            {
                if (hit.collider == null) return "-";
                var ent = hit.collider.ToBaseEntity() ?? hit.collider.GetComponentInParent<BaseEntity>();
                return ent != null ? ent.ShortPrefabName : hit.collider.name;
            }

            private const float JumpHeadSkipEnds = 0.2f;

            private const float DeployProbeSkipEnds = 0.2f;
            private const float DeployProbeUp = 0.35f;

            private const float DoorwayNearJump = 1.2f;

            private static bool IsDoorwayBetween(BuildingNav nav, Vector3 a, Vector3 b)
            {
                if (nav == null || nav.Doors.Count == 0) return false;
                Vector3 mid = (a + b) * 0.5f;
                foreach (var d in nav.Doors.Values)
                {
                    if (d?.Gate == null) continue;
                    Vector3 g = d.Gate.Position;
                    if (Mathf.Abs(g.y - mid.y) <= EffectiveAgentHeight)
                    {
                        float dx = g.x - mid.x, dz = g.z - mid.z;
                        if (dx * dx + dz * dz <= DoorwayNearJump * DoorwayNearJump) return true;
                    }
                    if (ArcCrossesDoorway(d, a, b)) return true;
                }
                return false;
            }

            private static bool ArcCrossesDoorway(DoorLink d, Vector3 a, Vector3 b)
            {
                if (d.IsHatch || !d.HasOpening) return false;
                Vector3 c = d.GateBoxCenter;
                Vector3 half = d.GateBoxHalf;
                var along = new Vector3(d.GateBoxAxis.x, 0f, d.GateBoxAxis.y);
                var across = new Vector3(-along.z, 0f, along.x);
                float sa = Vector3.Dot(a - c, across), sb = Vector3.Dot(b - c, across);
                if ((sa > half.z && sb > half.z) || (sa < -half.z && sb < -half.z)) return false;
                float t = Mathf.Abs(sa - sb) > 1e-4f ? Mathf.Clamp01(sa / (sa - sb)) : 0f;
                Vector3 p = ArcPoint(a, b, t);
                if (Mathf.Abs(Vector3.Dot(p - c, along)) > half.x) return false;
                return Mathf.Abs(p.y - c.y) <= half.y;
            }

            private static bool IsDeployBetween(Vector3 a, Vector3 b)
            {
                Vector3 lift = Vector3.up * DeployProbeUp;
                Vector3 from = Vector3.Lerp(a, b, DeployProbeSkipEnds) + lift;
                Vector3 to = Vector3.Lerp(a, b, 1f - DeployProbeSkipEnds) + lift;
                if (!Physics.Linecast(from, to, out RaycastHit hit,
                                      1 << (int)Rust.Layer.Deployed, QueryTriggerInteraction.Ignore)) return false;
                return hit.collider.GetComponentInParent<DecayEntity>() != null;
            }

            private static Vector3 ArcPoint(Vector3 start, Vector3 finish, float t)
            {
                Vector3 p = Vector3.Lerp(start, finish, t);
                p.y += JumpArcHeight * Mathf.Sin(t * Mathf.PI);
                return p;
            }

            private static bool HasStandingRoom(Vector3 p)
            {
                const float lift = 0.1f;
                return !(Physics.Raycast(p + Vector3.up * lift, Vector3.up, out RaycastHit hit,
                                         JumpStandHeight, GeomMask, QueryTriggerInteraction.Ignore)
                         && hit.distance + lift < JumpStandHeight);
            }

            #endregion

            #region Запросы: путь по поверхности

            private HelperSavedNavMesh.NavPathResult FindWorldPathRaw(Vector3 from, Vector3 to, List<Vector3> corners, out string error)
            {
                error = null;
                if (!SampleWorldNavmesh(from, WorldSnapRadius, out Vector3 s))
                {
                    error = "the start is off the game navmesh";
                    return HelperSavedNavMesh.NavPathResult.StartOffMesh;
                }
                if (!SampleWorldNavmesh(to, WorldSnapRadius, out Vector3 e))
                {
                    error = "the end is off the game navmesh";
                    return HelperSavedNavMesh.NavPathResult.EndOffMesh;
                }

                _worldPath ??= new Rust.Ai.Gen2.RustNavMeshPath();
                if (!Rust.Ai.Gen2.RustNavMeshHelpers.CalculatePath(s, e, Rust.Ai.Gen2.RustNavMeshHelpers.AllAreas, _worldPath))
                {
                    error = "the game navmesh returned no path";
                    return HelperSavedNavMesh.NavPathResult.None;
                }

                var got = _worldPath.corners;
                if (corners != null)
                    for (int i = 0; i < got.Count; i++) corners.Add(got[i].Value);

                if (_worldPath.status == UnityEngine.AI.NavMeshPathStatus.PathComplete)
                    return HelperSavedNavMesh.NavPathResult.Complete;
                return got.Count > 0 ? HelperSavedNavMesh.NavPathResult.Partial : HelperSavedNavMesh.NavPathResult.None;
            }

            private const float WorldSnapRadius = 1.5f;
            private Rust.Ai.Gen2.RustNavMeshPath _worldPath;

            public HelperSavedNavMesh.NavPathResult FindPathRaw(BuildingNav nav, Vector3 from, Vector3 to, List<Vector3> corners, out string error)
            {
                error = null;
                corners?.Clear();
                if (LinkSidesToWorld) return FindWorldPathRaw(from, to, corners, out error);
                if (nav == null || !nav.IsValid)
                {
                    error = "the building navmesh is not built";
                    return HelperSavedNavMesh.NavPathResult.None;
                }

                Vector3 extents = Vector3.one * SampleExtent;
                if (!RecastWrapper.SamplePosition(nav.Handle, in from, in extents, out Vector3 s, out ulong startRef, includeGatedDoorPolys: 0, allowNpcDoors: 0))
                {
                    error = "the start is off the navmesh";
                    return HelperSavedNavMesh.NavPathResult.StartOffMesh;
                }
                if (!RecastWrapper.SamplePosition(nav.Handle, in to, in extents, out Vector3 e, out _, includeGatedDoorPolys: 0, allowNpcDoors: 0))
                {
                    error = "the end is off the navmesh";
                    return HelperSavedNavMesh.NavPathResult.EndOffMesh;
                }

                DtStatus status = RecastWrapper.FindPath(nav.Handle, ref startRef, in s, in e, _pathBuf, out int len,
                    _pathPolyBuf, out _, PathIterations, allowNpcDoors: 0);
                if (((uint)status & (uint)DtStatus.Failure) != 0u)
                {
                    error = "the native search returned " + status;
                    return HelperSavedNavMesh.NavPathResult.None;
                }
                if (len <= 0)
                {
                    error = "empty path";
                    return HelperSavedNavMesh.NavPathResult.None;
                }

                if (corners != null) for (int i = 0; i < len; i++) corners.Add(_pathBuf[i]);

                if ((status & DtStatus.PartialResult) == DtStatus.PartialResult)
                {
                    error = "partial path";
                    return HelperSavedNavMesh.NavPathResult.Partial;
                }
                return HelperSavedNavMesh.NavPathResult.Complete;
            }

            #endregion

            #region Запросы: маршрут по графу (A* поверх навмеша)

            private const int RouteMaxIterations = 512;

            private readonly List<RecastNode> _routeGraph = new List<RecastNode>();
            private readonly Dictionary<RecastNode, int> _routeIndex = new Dictionary<RecastNode, int>();
            private readonly Dictionary<long, float> _routeCost = new Dictionary<long, float>();
            public static bool RouteMemoEnabled = true;
            private RouteMemo _routeMemo;
            private int _routeGraphCount;
            private int _routeStartIdx;
            private int _routeStartRing;
            private readonly List<(int idx, float sqrDist)> _routeRingOrder = new List<(int, float)>();
            private readonly List<Vector3> _routeProbe = new List<Vector3>();
            private readonly List<(int idx, float sqrDist)> _routeNear = new List<(int, float)>();
            private readonly List<(int idx, float sqrDist)> _routeNearOrder = new List<(int, float)>();
            private readonly List<int> _routeChain = new List<int>();

            internal struct RouteVisit
            {
                public float G;
                public float F;
                public int Parent;
                public NodeHint Hint;
                public bool Opened;
                public bool Closed;
            }

            private RouteVisit[] _routeVisits = new RouteVisit[64];

            private static void CollectGraphNodes(BuildingNav nav, List<RecastNode> list)
            {
                list.Clear();
                foreach (var d in nav.Doors.Values)
                {
                    if (d.Gate == null || !d.Gate.IsValid()) continue;
                    list.Add(d.Gate);
                    if (d.SideA != null) list.Add(d.SideA);
                    if (d.SideB != null) list.Add(d.SideB);
                    if (d.ExtraSides != null)
                        for (int i = 0; i < d.ExtraSides.Count; i++) list.Add(d.ExtraSides[i]);
                }
                for (int i = 0; i < nav.Jumps.Count; i++)
                {
                    var j = nav.Jumps[i];
                    if (j.From != null) list.Add(j.From);
                    if (j.To != null) list.Add(j.To);
                }
                for (int i = 0; i < nav.Climbs.Count; i++)
                {
                    var c = nav.Climbs[i];
                    if (!c.IsValid()) continue;
                    if (c.Bottom != null) list.Add(c.Bottom);
                    if (c.Top != null) list.Add(c.Top);
                    for (int k = 0; k < c.MidLandings.Count; k++) list.Add(c.MidLandings[k]);
                    for (int k = 0; k < c.Shaft.Count; k++) list.Add(c.Shaft[k]);
                }
            }

            private static bool IsOnOurNavmesh(RecastNode node) => !node.IsOffMesh && ReferenceEquals(node.LinkedDoor, null) && !node.IsNavMesh;

            public int CountGraphNodes(BuildingNav nav)
            {
                if (nav == null || !nav.IsValid) return 0;
                CollectGraphNodes(nav, _routeGraph);
                return _routeGraph.Count;
            }

            public bool TryGetRouteNodes(BuildingNav nav, out List<RecastNode> nodes)
            {
                nodes = new List<RecastNode>();
                if (nav == null || !nav.IsValid) return false;
                CollectGraphNodes(nav, _routeGraph);
                for (int i = 0; i < _routeGraph.Count; i++)
                    if (IsOnOurNavmesh(_routeGraph[i])) nodes.Add(_routeGraph[i]);
                return nodes.Count > 0;
            }

            private static bool OnRecastMesh(BuildingNav nav, Vector3 point)
            {
                if (LinkSidesToWorld)
                    return SampleWorldNavmesh(point, WorldSnapRadius, out Vector3 world)
                           && Mathf.Abs(world.y - point.y) <= SampleExtents.y;
                if (nav == null || !nav.IsValid) return false;
                Vector3 extents = SampleExtents;
                return RecastWrapper.SamplePosition(nav.Handle, in point, in extents, out Vector3 hit, out _, includeGatedDoorPolys: 0, allowNpcDoors: 0)
                       && hit != Vector3.zero;
            }

            public HelperSavedNavMesh.NavPathResult TryBuildRoute(BuildingNav nav, Vector3 from, Vector3 to, List<PathStep> steps,
                                                                  out Vector3 stopWorld, out string error,
                                                                  Func<IAIPathNode, IAIPathNode, bool> canUseDoor = null)
            {
                steps?.Clear();
                stopWorld = from;
                error = null;
                if (nav == null || !nav.IsValid)
                {
                    error = "the building navmesh is not built";
                    return HelperSavedNavMesh.NavPathResult.None;
                }

                bool startOutside = !OnRecastMesh(nav, from);
                bool goalOutside = !OnRecastMesh(nav, to);

                var start = new RecastNode(from, NodeRole.Floor, unityNavMesh: startOutside);
                var goal = new RecastNode(to, NodeRole.Floor, unityNavMesh: goalOutside);

                var direct = FindPathRaw(nav, from, to, _routeProbe, out string directError);
                if (direct == HelperSavedNavMesh.NavPathResult.Complete)
                {
                    if (steps != null)
                    {
                        steps.Add(new PathStep(start, NodeHint.None, null, 0f));
                        steps.Add(new PathStep(goal, NodeHint.NavMesh, new List<Vector3>(_routeProbe), PathLength(_routeProbe)));
                    }
                    stopWorld = to;
                    return HelperSavedNavMesh.NavPathResult.Complete;
                }

                bool directPartial = direct == HelperSavedNavMesh.NavPathResult.Partial && _routeProbe.Count > 0;
                Vector3 directStop = from;
                List<Vector3> directCorners = null;
                if (directPartial)
                {
                    directStop = _routeProbe[_routeProbe.Count - 1];
                    directCorners = new List<Vector3>(_routeProbe);
                }

                string directReason = $"{direct}" + (directError == null ? string.Empty : $" ({directError})");

                CollectGraphNodes(nav, _routeGraph);
                if (_routeGraph.Count == 0)
                {
                    error = "the building has no links - the transition graph was not built";
                    return FinishPartial(steps, start, directPartial, directStop, directCorners, ref stopWorld);
                }

                int startIdx = _routeGraph.Count;
                int goalIdx = startIdx + 1;
                _routeMemo = SyncRouteMemo(nav);
                _routeGraphCount = startIdx;
                _routeStartIdx = startIdx;
                _routeStartRing = 0;
                _routeRingOrder.Clear();
                _routeGraph.Add(start);
                _routeGraph.Add(goal);

                _routeIndex.Clear();
                for (int i = 0; i < _routeGraph.Count; i++) _routeIndex[_routeGraph[i]] = i;

                _routeCost.Clear();
                if (_routeVisits.Length < _routeGraph.Count) _routeVisits = new RouteVisit[_routeGraph.Count * 2];
                for (int i = 0; i < _routeGraph.Count; i++) _routeVisits[i] = new RouteVisit { Parent = -1 };

                _routeVisits[startIdx].G = 0f;
                _routeVisits[startIdx].F = Vector3.Distance(from, to);
                _routeVisits[startIdx].Opened = true;

                int iterations = 0;
                bool reached = false;
                int bestIdx = -1;
                float bestH = float.MaxValue;

                while (iterations++ < RouteMaxIterations)
                {
                    int cur = -1;
                    float best = float.MaxValue;
                    for (int i = 0; i < _routeGraph.Count; i++)
                    {
                        if (!_routeVisits[i].Opened || _routeVisits[i].Closed) continue;
                        if (_routeVisits[i].F >= best) continue;
                        best = _routeVisits[i].F;
                        cur = i;
                    }
                    if (cur < 0) break;
                    if (cur == goalIdx) { reached = true; break; }

                    _routeVisits[cur].Closed = true;

                    if (cur != startIdx)
                    {
                        var node = _routeGraph[cur];
                        if (!node.IsWaypointOnly)
                        {
                            float h = Vector3.Distance(node.Position, to);
                            if (h < bestH) { bestH = h; bestIdx = cur; }
                        }
                    }

                    RelaxNeighbours(nav, cur, goalIdx, to, canUseDoor);
                }

                if (!reached)
                {
                    error = (_routeVisits[goalIdx].Parent >= 0 ? "the route did not converge" : "the goal is not connected to the start")
                            + $" (direct navmesh path: {directReason})";

                    if (bestIdx >= 0)
                    {
                        BuildRouteChain(nav, bestIdx, steps);
                        stopWorld = _routeGraph[bestIdx].Position;
                        return HelperSavedNavMesh.NavPathResult.Partial;
                    }
                    return FinishPartial(steps, start, directPartial, directStop, directCorners, ref stopWorld);
                }

                BuildRouteChain(nav, goalIdx, steps);
                stopWorld = to;
                return HelperSavedNavMesh.NavPathResult.Complete;
            }

            public sealed class ReachQuery : IDisposable
            {
                internal BuildingNav Nav;
                internal Vector3 From, To;
                internal int Version, Flags, Iterations;
                internal bool WorldSides, MemoEnabled;
                internal int Neighbours, ProbeLimit;
                internal IEnumerator Work;
                internal int Result = -1;
                internal readonly List<RecastNode> _routeGraph = new List<RecastNode>();
                internal readonly Dictionary<RecastNode, int> _routeIndex = new Dictionary<RecastNode, int>();
                internal readonly Dictionary<long, float> _routeCost = new Dictionary<long, float>();
                internal RouteMemo _routeMemo;
                internal int _routeGraphCount, _routeStartIdx, _routeStartRing;
                internal readonly List<(int idx, float sqrDist)> _routeRingOrder = new List<(int, float)>();
                internal readonly List<Vector3> _routeProbe = new List<Vector3>();
                internal readonly List<(int idx, float sqrDist)> _routeNear = new List<(int, float)>();
                internal readonly List<(int idx, float sqrDist)> _routeNearOrder = new List<(int, float)>();
                internal RouteVisit[] _routeVisits;
                public void Dispose() { (Work as IDisposable)?.Dispose(); Work = null; }
            }

            private int _reachBudgetFrame = -1;
            private double _reachBudgetSpent;
            private const double ReachFrameBudgetMs = 3d;

            public int StepReachability(BuildingNav nav, Vector3 from, Vector3 to, ref ReachQuery query)
            {
                if (nav == null || !nav.IsValid)
                {
                    query?.Dispose(); query = null;
                    return -1;
                }
                if (query == null || query.Nav != nav || query.Version != nav.Version || query.Flags != nav.FlagsStamp
                    || query.Iterations != PathIterations || query.WorldSides != LinkSidesToWorld || query.MemoEnabled != RouteMemoEnabled
                    || query.Neighbours != RouteNavNeighbors || query.ProbeLimit != RouteNavProbeLimit
                    || (query.From - from).sqrMagnitude > 0.0001f || (query.To - to).sqrMagnitude > 0.0001f)
                {
                    query?.Dispose();
                    query = new ReachQuery { Nav = nav, From = from, To = to, Version = nav.Version, Flags = nav.FlagsStamp,
                        Iterations = PathIterations, WorldSides = LinkSidesToWorld, MemoEnabled = RouteMemoEnabled,
                        Neighbours = RouteNavNeighbors, ProbeLimit = RouteNavProbeLimit };
                    query.Work = ReachStages(query);
                }
                if (query.Result >= 0) return query.Result;
                if (_reachBudgetFrame != Time.frameCount) { _reachBudgetFrame = Time.frameCount; _reachBudgetSpent = 0d; }
                if (_reachBudgetSpent >= ReachFrameBudgetMs) return -1;
                long started = System.Diagnostics.Stopwatch.GetTimestamp();
                double elapsed = 0d;
                try
                {
                    do
                    {
                        if (!query.Work.MoveNext())
                        {
                            if (query.Result < 0) query.Result = 0;
                            query.Dispose();
                            break;
                        }
                        elapsed = (System.Diagnostics.Stopwatch.GetTimestamp() - started) * 1000d / System.Diagnostics.Stopwatch.Frequency;
                    } while (_reachBudgetSpent + elapsed < ReachFrameBudgetMs);
                }
                finally
                {
                    _reachBudgetSpent += (System.Diagnostics.Stopwatch.GetTimestamp() - started) * 1000d / System.Diagnostics.Stopwatch.Frequency;
                }
                return query.Result;
            }

            private IEnumerator ReachStages(ReachQuery query)
            {
                BuildingNav nav = query.Nav;
                if (FindPathRaw(nav, query.From, query.To, query._routeProbe, out _) == HelperSavedNavMesh.NavPathResult.Complete)
                { query.Result = 1; yield break; }
                yield return null;
                CollectGraphNodes(nav, query._routeGraph);
                if (query._routeGraph.Count == 0) yield break;
                query._routeMemo = ReachSyncRouteMemo(query, nav);
                int start = query._routeGraph.Count, goal = start + 1;
                query._routeGraphCount = start;
                query._routeStartIdx = start;
                query._routeGraph.Add(new RecastNode(query.From, NodeRole.Floor, unityNavMesh: !OnRecastMesh(nav, query.From)));
                query._routeGraph.Add(new RecastNode(query.To, NodeRole.Floor, unityNavMesh: !OnRecastMesh(nav, query.To)));
                for (int i = 0; i < query._routeGraph.Count; i++) query._routeIndex[query._routeGraph[i]] = i;
                query._routeVisits = new RouteVisit[query._routeGraph.Count];
                for (int i = 0; i < query._routeVisits.Length; i++) query._routeVisits[i] = new RouteVisit { Parent = -1 };
                query._routeVisits[start].Opened = true;
                query._routeVisits[start].F = Vector3.Distance(query.From, query.To);
                yield return null;
                if (query._routeMemo.Ring == null)
                {
                    bool[] ring = new bool[start];
                    var ringNodes = new List<int>();
                    IReadOnlyList<Vector3> exits = GroundExits(nav);
                    for (int i = 0; i < start; i++)
                    {
                        RecastNode node = query._routeGraph[i];
                        if (IsOnOurNavmesh(node) && IsGroundRingPoint(nav, node.Position, exits)) { ring[i] = true; ringNodes.Add(i); }
                        yield return null;
                    }
                    query._routeMemo.RingNodes.Clear(); query._routeMemo.RingNodes.AddRange(ringNodes);
                    query._routeMemo.Ring = ring;
                }
                for (int iteration = 0; iteration < RouteMaxIterations; iteration++)
                {
                    int cur = -1; float best = float.MaxValue;
                    for (int i = 0; i < query._routeGraph.Count; i++)
                    {
                        if (!query._routeVisits[i].Opened || query._routeVisits[i].Closed || query._routeVisits[i].F >= best) continue;
                        best = query._routeVisits[i].F; cur = i;
                    }
                    if (cur < 0) yield break;
                    if (cur == goal) { query.Result = 1; yield break; }
                    query._routeVisits[cur].Closed = true;
                    IEnumerator neighbours = RelaxReachNeighbours(query, nav, cur, goal, query.To, null);
                    try { while (neighbours.MoveNext()) yield return null; }
                    finally { (neighbours as IDisposable)?.Dispose(); }
                    yield return null;
                }
            }

            private float ReachNavCost(ReachQuery query, BuildingNav nav, int a, int b)
            {
                long key = a < b ? ((long)a << 20) | (uint)b : ((long)b << 20) | (uint)a;
                Dictionary<long, float> costs = RouteMemoEnabled && !LinkSidesToWorld && a < query._routeGraphCount && b < query._routeGraphCount
                    ? query._routeMemo.Costs : query._routeCost;
                if (costs.TryGetValue(key, out float cached)) return cached;

                float cost = -1f;
                if (FindPathRaw(nav, query._routeGraph[a].Position, query._routeGraph[b].Position, query._routeProbe, out _) == HelperSavedNavMesh.NavPathResult.Complete)
                    cost = PathLength(query._routeProbe);

                costs[key] = cost;
                return cost;
            }

            private void ReachTryOpen(ReachQuery query, int from, int to, float cost, NodeHint hint, Vector3 goalPos)
            {
                float g = query._routeVisits[from].G + cost;
                if (query._routeVisits[to].Opened && g >= query._routeVisits[to].G) return;

                query._routeVisits[to].G = g;
                query._routeVisits[to].F = g + Vector3.Distance(query._routeGraph[to].Position, goalPos);
                query._routeVisits[to].Parent = from;
                query._routeVisits[to].Hint = hint;
                query._routeVisits[to].Opened = true;
                query._routeVisits[to].Closed = false;
            }

            private int[] ReachNearNodes(ReachQuery query, int idx)
            {
                RouteMemo memo = query._routeMemo;
                if (memo.Near == null) memo.Near = new int[query._routeGraphCount][];
                if (memo.Near[idx] != null) return memo.Near[idx];
                Vector3 at = query._routeGraph[idx].Position;
                query._routeNearOrder.Clear();
                for (int i = 0; i < query._routeGraphCount; i++)
                    if (i != idx && IsOnOurNavmesh(query._routeGraph[i])) query._routeNearOrder.Add((i, (query._routeGraph[i].Position - at).sqrMagnitude));
                query._routeNearOrder.Sort((a, b) => a.sqrDist.CompareTo(b.sqrDist));
                int[] near = new int[query._routeNearOrder.Count];
                for (int i = 0; i < near.Length; i++) near[i] = query._routeNearOrder[i].idx;
                return memo.Near[idx] = near;
            }

            private RouteMemo ReachSyncRouteMemo(ReachQuery query, BuildingNav nav)
            {
                RouteMemo memo = nav.Route;
                bool same = memo.Version == nav.Version && memo.PathIterations == PathIterations && memo.WorldSides == LinkSidesToWorld
                            && memo.Nodes.Count == query._routeGraph.Count;
                for (int i = 0; same && i < query._routeGraph.Count; i++)
                    same = memo.Nodes[i] == query._routeGraph[i];
                if (!same)
                {
                    memo.Nodes.Clear();
                    memo.Nodes.AddRange(query._routeGraph);
                    memo.Costs.Clear();
                    memo.Ring = null;
                    memo.RingNodes.Clear();
                    memo.Near = null;
                    memo.Version = nav.Version;
                    memo.PathIterations = PathIterations;
                    memo.WorldSides = LinkSidesToWorld;
                }
                else if (memo.FlagsStamp != nav.FlagsStamp) memo.Costs.Clear();
                memo.FlagsStamp = nav.FlagsStamp;
                return memo;
            }

            private bool ReachOnGroundRing(ReachQuery query, BuildingNav nav, int idx)
            {
                if (idx == query._routeStartIdx)
                {
                    if (query._routeStartRing == 0)
                        query._routeStartRing = IsGroundRingPoint(nav, query._routeGraph[idx].Position, GroundExits(nav)) ? 1 : 2;
                    return query._routeStartRing == 1;
                }
                if (idx >= query._routeGraphCount) return false;
                return query._routeMemo.Ring[idx];
            }

            private IEnumerator RelaxReachNeighbours(ReachQuery query, BuildingNav nav, int cur, int goalIdx, Vector3 goalPos, Func<IAIPathNode, IAIPathNode, bool> canUseDoor)
            {
                var node = query._routeGraph[cur];

                foreach (var e in node.Edges)
                {
                    if (e.Target == null) continue;
                    if (!(e.Target is RecastNode target) || !query._routeIndex.TryGetValue(target, out int idx)) continue;
                    if (canUseDoor != null && (e.Hint & NodeHint.OpenDoor) != 0 && target.LinkedDoor.IsValid() && !canUseDoor(node, target)) continue;
                    ReachTryOpen(query, cur, idx, e.Cost, e.Hint, goalPos);
                }

                if (!IsOnOurNavmesh(node))
                {
                    yield break;
                }

                if (ReachOnGroundRing(query, nav, cur))
                {
                    if (query._routeRingOrder.Count == 0)
                    {

                        List<int> ring = query._routeMemo.RingNodes;
                        for (int i = 0; i < ring.Count; i++)
                            query._routeRingOrder.Add((ring[i], (query._routeGraph[ring[i]].Position - goalPos).sqrMagnitude));
                        query._routeRingOrder.Sort((a, b) => a.sqrDist.CompareTo(b.sqrDist));
                    }
                    int ringOpened = 0;
                    for (int k = 0; k < query._routeRingOrder.Count && ringOpened < RouteNavNeighbors; k++)
                    {
                        int idx = query._routeRingOrder[k].idx;
                        if (idx == cur || query._routeVisits[idx].Closed) continue;
                        float cost = ReachNavCost(query, nav, cur, idx);
                    yield return null;
                        if (cost < 0f) continue;
                        ringOpened++;
                        ReachTryOpen(query, cur, idx, cost, NodeHint.NavMesh, goalPos);
                    }
                }

                query._routeNear.Clear();
                if (RouteMemoEnabled && cur < query._routeGraphCount)
                {
                    int[] near = ReachNearNodes(query, cur);
                    var goalNode = query._routeGraph[goalIdx];
                    bool goalLeft = goalIdx != cur && !query._routeVisits[goalIdx].Closed && IsOnOurNavmesh(goalNode);
                    float goalSqr = goalLeft ? (goalNode.Position - node.Position).sqrMagnitude : 0f;
                    for (int k = 0; k < near.Length && query._routeNear.Count < RouteNavProbeLimit; k++)
                    {
                        int i = near[k];
                        if (query._routeVisits[i].Closed) continue;
                        float sqr = (query._routeGraph[i].Position - node.Position).sqrMagnitude;
                        if (goalLeft && goalSqr <= sqr)
                        {
                            query._routeNear.Add((goalIdx, goalSqr));
                            goalLeft = false;
                        }
                        query._routeNear.Add((i, sqr));
                    }
                    if (goalLeft) query._routeNear.Add((goalIdx, goalSqr));
                }
                else
                {
                    for (int i = 0; i < query._routeGraph.Count; i++)
                    {
                        if (i == cur || query._routeVisits[i].Closed) continue;
                        var other = query._routeGraph[i];
                        if (!IsOnOurNavmesh(other)) continue;
                        query._routeNear.Add((i, (other.Position - node.Position).sqrMagnitude));
                    }
                    query._routeNear.Sort((a, b) => a.sqrDist.CompareTo(b.sqrDist));
                }

                int opened = 0, probes = 0;
                bool goalTried = false;
                for (int k = 0; k < query._routeNear.Count && opened < RouteNavNeighbors && probes < RouteNavProbeLimit; k++)
                {
                    int idx = query._routeNear[k].idx;
                    probes++;
                    float cost = ReachNavCost(query, nav, cur, idx);
                    yield return null;
                    if (idx == goalIdx) goalTried = true;
                    if (cost < 0f) continue;
                    opened++;
                    ReachTryOpen(query, cur, idx, cost, NodeHint.NavMesh, goalPos);
                }

                if (!goalTried && goalIdx < query._routeGraph.Count && !query._routeVisits[goalIdx].Closed)
                {
                    float cost = ReachNavCost(query, nav, cur, goalIdx);
                    yield return null;
                    if (cost >= 0f) ReachTryOpen(query, cur, goalIdx, cost, NodeHint.NavMesh, goalPos);
                }
            }

            private const int RouteWarmPairLimit = 8192;

            private IEnumerator WarmRouteMemo(BuildingNav nav)
            {
                if (!RouteMemoEnabled || LinkSidesToWorld) yield break;
                var query = new ReachQuery { Nav = nav };
                CollectGraphNodes(nav, query._routeGraph);
                query._routeGraphCount = query._routeGraph.Count;
                RouteMemo memo = ReachSyncRouteMemo(query, nav);
                query._routeMemo = memo;
                var eligible = new List<int>();
                for (int i = 0; i < query._routeGraphCount; i++)
                {
                    if (IsOnOurNavmesh(query._routeGraph[i])) eligible.Add(i);
                    yield return null;
                }
                int warmed = 0;
                for (int a = 0; a < eligible.Count && warmed < RouteWarmPairLimit; a++)
                    for (int b = a + 1; b < eligible.Count && warmed < RouteWarmPairLimit; b++)
                    {
                        ReachNavCost(query, nav, eligible[a], eligible[b]);
                        warmed++;
                        yield return null;
                    }
                bool[] ring = new bool[query._routeGraphCount];
                var ringNodes = new List<int>();
                IReadOnlyList<Vector3> exits = GroundExits(nav);
                for (int i = 0; i < eligible.Count; i++)
                {
                    int index = eligible[i];
                    if (IsGroundRingPoint(nav, query._routeGraph[index].Position, exits)) { ring[index] = true; ringNodes.Add(index); }
                    ReachNearNodes(query, index);
                    yield return null;
                }
                memo.RingNodes.Clear(); memo.RingNodes.AddRange(ringNodes); memo.Ring = ring;
            }

            private static void AdoptRouteMemo(BuildingNav source, BuildingNav target)
            {
                RouteMemo from = source.Route, to = target.Route;
                to.Nodes.Clear(); to.Nodes.AddRange(from.Nodes);
                to.Costs.Clear(); foreach (var pair in from.Costs) to.Costs.Add(pair.Key, pair.Value);
                to.Ring = from.Ring; to.Near = from.Near;
                to.RingNodes.Clear(); to.RingNodes.AddRange(from.RingNodes);
                to.Version = target.Version; to.FlagsStamp = target.FlagsStamp;
                to.PathIterations = from.PathIterations; to.WorldSides = from.WorldSides;
            }

            private BuildingNav QueueInitialRebuild(uint id, out string error)
            {
                error = null;
                var building = BuildingManager.server.GetBuilding(id);
                if (!_running || building == null || !building.HasBuildingBlocks()) { error = "building unavailable"; return null; }
                var nav = new BuildingNav { BuildingID = id, Params = MakeParams(), Bounds = CalcBounds(building), Empty = true };
                try { nav.Handle = RecastWrapper.CreateEmptyNavMesh(in nav.Params, nav.Bounds.min, nav.Bounds.max); }
                catch (Exception e) { error = "native Recast is unavailable: " + e.Message; return null; }
                if (nav.Handle == IntPtr.Zero) { error = "CreateEmptyNavMesh = 0"; return null; }
                nav.TileNum = CalcTileNum(nav);
                _navs[id] = nav;
                QueueRebuild(id); ArmRebuildStep();
                return nav;
            }

            private static HelperSavedNavMesh.NavPathResult FinishPartial(List<PathStep> steps, RecastNode start, bool directPartial,
                                                                          Vector3 directStop, List<Vector3> directCorners, ref Vector3 stopWorld)
            {
                if (!directPartial) return HelperSavedNavMesh.NavPathResult.None;
                stopWorld = directStop;
                if (steps != null)
                {
                    steps.Clear();
                    steps.Add(new PathStep(start, NodeHint.None, null, 0f));
                    steps.Add(new PathStep(new RecastNode(directStop, NodeRole.Floor), NodeHint.NavMesh,
                        directCorners, PathLength(directCorners)));
                }
                return HelperSavedNavMesh.NavPathResult.Partial;
            }

            private static bool StartsTransition(NodeHint hint)
                => (hint & (NodeHint.OpenDoor | NodeHint.CloseDoor | NodeHint.Climb | NodeHint.Jump)) != 0;

            private void BuildRouteChain(BuildingNav nav, int last, List<PathStep> steps)
            {
                _routeChain.Clear();
                for (int i = last; i >= 0; i = _routeVisits[i].Parent) _routeChain.Add(i);
                _routeChain.Reverse();
                if (steps == null || _routeChain.Count == 0) return;

                steps.Clear();
                steps.Add(new PathStep(_routeGraph[_routeChain[0]], NodeHint.None, null, 0f));
                for (int i = 1; i < _routeChain.Count; i++)
                {
                    var node = _routeGraph[_routeChain[i]];
                    var prev = _routeGraph[_routeChain[i - 1]];
                    NodeHint hint = _routeVisits[_routeChain[i]].Hint;
                    float cost = _routeVisits[_routeChain[i]].G - _routeVisits[_routeChain[i - 1]].G;

                    if (hint.HasFlag(NodeHint.NavMesh) && cost < 0.05f && i < _routeChain.Count - 1
                        && !StartsTransition(_routeVisits[_routeChain[i + 1]].Hint)) continue;

                    List<Vector3> waypoints = null;
                    if (hint.HasFlag(NodeHint.NavMesh)
                        && FindPathRaw(nav, prev.Position, node.Position, _routeProbe, out _) == HelperSavedNavMesh.NavPathResult.Complete)
                        waypoints = new List<Vector3>(_routeProbe);

                    steps.Add(new PathStep(node, hint, waypoints, cost));
                }
            }

            private void RelaxNeighbours(BuildingNav nav, int cur, int goalIdx, Vector3 goalPos, Func<IAIPathNode, IAIPathNode, bool> canUseDoor)
            {
                var node = _routeGraph[cur];

                foreach (var e in node.Edges)
                {
                    if (e.Target == null) continue;
                    if (!(e.Target is RecastNode target) || !_routeIndex.TryGetValue(target, out int idx)) continue;
                    if (canUseDoor != null && (e.Hint & NodeHint.OpenDoor) != 0 && target.LinkedDoor.IsValid() && !canUseDoor(node, target)) continue;
                    TryOpen(cur, idx, e.Cost, e.Hint, goalPos);
                }

                if (!IsOnOurNavmesh(node))
                {
                    return;
                }

                if (OnGroundRing(nav, cur))
                {
                    if (_routeRingOrder.Count == 0)
                    {
                        EnsureGroundRing(nav);
                        List<int> ring = _routeMemo.RingNodes;
                        for (int i = 0; i < ring.Count; i++)
                            _routeRingOrder.Add((ring[i], (_routeGraph[ring[i]].Position - goalPos).sqrMagnitude));
                        _routeRingOrder.Sort((a, b) => a.sqrDist.CompareTo(b.sqrDist));
                    }
                    int ringOpened = 0;
                    for (int k = 0; k < _routeRingOrder.Count && ringOpened < RouteNavNeighbors; k++)
                    {
                        int idx = _routeRingOrder[k].idx;
                        if (idx == cur || _routeVisits[idx].Closed) continue;
                        float cost = NavCost(nav, cur, idx);
                        if (cost < 0f) continue;
                        ringOpened++;
                        TryOpen(cur, idx, cost, NodeHint.NavMesh, goalPos);
                    }
                }

                _routeNear.Clear();
                if (RouteMemoEnabled && cur < _routeGraphCount)
                {
                    int[] near = NearNodes(cur);
                    var goalNode = _routeGraph[goalIdx];
                    bool goalLeft = goalIdx != cur && !_routeVisits[goalIdx].Closed && IsOnOurNavmesh(goalNode);
                    float goalSqr = goalLeft ? (goalNode.Position - node.Position).sqrMagnitude : 0f;
                    for (int k = 0; k < near.Length && _routeNear.Count < RouteNavProbeLimit; k++)
                    {
                        int i = near[k];
                        if (_routeVisits[i].Closed) continue;
                        float sqr = (_routeGraph[i].Position - node.Position).sqrMagnitude;
                        if (goalLeft && goalSqr <= sqr)
                        {
                            _routeNear.Add((goalIdx, goalSqr));
                            goalLeft = false;
                        }
                        _routeNear.Add((i, sqr));
                    }
                    if (goalLeft) _routeNear.Add((goalIdx, goalSqr));
                }
                else
                {
                    for (int i = 0; i < _routeGraph.Count; i++)
                    {
                        if (i == cur || _routeVisits[i].Closed) continue;
                        var other = _routeGraph[i];
                        if (!IsOnOurNavmesh(other)) continue;
                        _routeNear.Add((i, (other.Position - node.Position).sqrMagnitude));
                    }
                    _routeNear.Sort((a, b) => a.sqrDist.CompareTo(b.sqrDist));
                }

                int opened = 0, probes = 0;
                bool goalTried = false;
                for (int k = 0; k < _routeNear.Count && opened < RouteNavNeighbors && probes < RouteNavProbeLimit; k++)
                {
                    int idx = _routeNear[k].idx;
                    probes++;
                    float cost = NavCost(nav, cur, idx);
                    if (idx == goalIdx) goalTried = true;
                    if (cost < 0f) continue;
                    opened++;
                    TryOpen(cur, idx, cost, NodeHint.NavMesh, goalPos);
                }

                if (!goalTried && goalIdx < _routeGraph.Count && !_routeVisits[goalIdx].Closed)
                {
                    float cost = NavCost(nav, cur, goalIdx);
                    if (cost >= 0f) TryOpen(cur, goalIdx, cost, NodeHint.NavMesh, goalPos);
                }
            }

            private void TryOpen(int from, int to, float cost, NodeHint hint, Vector3 goalPos)
            {
                float g = _routeVisits[from].G + cost;
                if (_routeVisits[to].Opened && g >= _routeVisits[to].G) return;

                _routeVisits[to].G = g;
                _routeVisits[to].F = g + Vector3.Distance(_routeGraph[to].Position, goalPos);
                _routeVisits[to].Parent = from;
                _routeVisits[to].Hint = hint;
                _routeVisits[to].Opened = true;
                _routeVisits[to].Closed = false;
            }

            private float NavCost(BuildingNav nav, int a, int b)
            {
                long key = a < b ? ((long)a << 20) | (uint)b : ((long)b << 20) | (uint)a;
                Dictionary<long, float> costs = RouteMemoEnabled && !LinkSidesToWorld && a < _routeGraphCount && b < _routeGraphCount
                    ? _routeMemo.Costs : _routeCost;
                if (costs.TryGetValue(key, out float cached)) return cached;

                float cost = -1f;
                if (FindPathRaw(nav, _routeGraph[a].Position, _routeGraph[b].Position, _routeProbe, out _) == HelperSavedNavMesh.NavPathResult.Complete)
                    cost = PathLength(_routeProbe);

                costs[key] = cost;
                return cost;
            }

            private RouteMemo SyncRouteMemo(BuildingNav nav)
            {
                RouteMemo memo = nav.Route;
                bool same = memo.Version == nav.Version && memo.PathIterations == PathIterations && memo.WorldSides == LinkSidesToWorld
                            && memo.Nodes.Count == _routeGraph.Count;
                for (int i = 0; same && i < _routeGraph.Count; i++)
                    same = memo.Nodes[i] == _routeGraph[i];
                if (!same)
                {
                    memo.Nodes.Clear();
                    memo.Nodes.AddRange(_routeGraph);
                    memo.Costs.Clear();
                    memo.Ring = null;
                    memo.RingNodes.Clear();
                    memo.Near = null;
                    memo.Version = nav.Version;
                    memo.PathIterations = PathIterations;
                    memo.WorldSides = LinkSidesToWorld;
                }
                else if (memo.FlagsStamp != nav.FlagsStamp) memo.Costs.Clear();
                memo.FlagsStamp = nav.FlagsStamp;
                return memo;
            }

            private int[] NearNodes(int idx)
            {
                RouteMemo memo = _routeMemo;
                if (memo.Near == null) memo.Near = new int[_routeGraphCount][];
                if (memo.Near[idx] != null) return memo.Near[idx];
                Vector3 at = _routeGraph[idx].Position;
                _routeNearOrder.Clear();
                for (int i = 0; i < _routeGraphCount; i++)
                    if (i != idx && IsOnOurNavmesh(_routeGraph[i])) _routeNearOrder.Add((i, (_routeGraph[i].Position - at).sqrMagnitude));
                _routeNearOrder.Sort((a, b) => a.sqrDist.CompareTo(b.sqrDist));
                int[] near = new int[_routeNearOrder.Count];
                for (int i = 0; i < near.Length; i++) near[i] = _routeNearOrder[i].idx;
                return memo.Near[idx] = near;
            }

            private bool OnGroundRing(BuildingNav nav, int idx)
            {
                if (idx == _routeStartIdx)
                {
                    if (_routeStartRing == 0)
                        _routeStartRing = IsGroundRingPoint(nav, _routeGraph[idx].Position, GroundExits(nav)) ? 1 : 2;
                    return _routeStartRing == 1;
                }
                if (idx >= _routeGraphCount) return false;
                EnsureGroundRing(nav);
                return _routeMemo.Ring[idx];
            }

            private void EnsureGroundRing(BuildingNav nav)
            {
                RouteMemo memo = _routeMemo;
                if (memo.Ring != null) return;
                memo.Ring = new bool[_routeGraphCount];
                IReadOnlyList<Vector3> exits = GroundExits(nav);
                for (int i = 0; i < _routeGraphCount; i++)
                {
                    RecastNode node = _routeGraph[i];
                    if (!IsOnOurNavmesh(node) || !IsGroundRingPoint(nav, node.Position, exits)) continue;
                    memo.Ring[i] = true;
                    memo.RingNodes.Add(i);
                }
            }

            private bool IsGroundRingPoint(BuildingNav nav, Vector3 point, IReadOnlyList<Vector3> exits)
            {
                int nearest = -1;
                float best = float.MaxValue;
                for (int i = 0; i < exits.Count; i++)
                {
                    float dx = exits[i].x - point.x, dz = exits[i].z - point.z;
                    float d = dx * dx + dz * dz;
                    if (d >= best) continue;
                    best = d;
                    nearest = i;
                }
                return nearest >= 0 && FindPathRaw(nav, point, exits[nearest], null, out _) == HelperSavedNavMesh.NavPathResult.Complete;
            }

            #endregion
        }

        #endregion

        #region Water NavMesh - навмеш по дну для спасения пловца (Recast)

        public class HelperWaterNavMesh
        {
            private static HelperWaterNavMesh _instance;

            public static HelperWaterNavMesh Instance => _instance ??= new HelperWaterNavMesh();
            internal static HelperWaterNavMesh Existing => _instance;

            public static bool Enabled = true;

            #region Параметры

            public static float CellSize = 0.5f;
            public static float CellHeight = 0.25f;
            public static float AgentRadius = 0.5f;
            public static float AgentHeight = 1.8f;
            public static float AgentMaxClimb = 1f;
            public static float AgentMaxSlope = 60f;
            public static float TileVoxels = 64f;
            public static float MinRegionSizeMeters = 4f;
            public static int MaxNodes = 2048;
            public static int PathIterations = 2048;

            public static float MaxRescueDistance = 150f;
            public static float TileLifetime = 600f;

            private const float CorridorMargin = 16f;
            private const float TerrainStep = 1f;
            private const float ColliderPadDown = 5f, ColliderPadUp = 30f;
            private const float BuildStep = 0.05f;
            private const double BuildBudgetMs = 6d;
            private const float EvictStep = 30f;
            private static readonly Vector3 SampleExtents = new Vector3(1.5f, 2f, 1.5f);
            private const float ShoreColumnAboveWater = 1.5f;
            private const float ColumnPadDown = 2f;
            private const float ColumnPadUp = 0.5f;
            private const float SwimBandBelow = 1.4f, SwimBandAbove = 0.8f;
            private const float CompleteGap = 1f;
            private const int MaxSpanHeight = 8191;

            private static readonly int GeomMask = LayerMask.GetMask("Default", "Deployed", "World", "Construction", "Transparent", "Tree");

            #endregion

            public enum CorridorState
            {
                Ready,
                Pending,
                Failed,
            }

            private sealed class WaterTile
            {
                public int X, Y;
                public bool Built;
                public bool HasMesh;
                public float LastUse;
            }

            private IntPtr _handle = IntPtr.Zero;
            private NavMeshBuildParams _params;
            private Bounds _bounds;
            private Vector2Int _tileNum;
            private readonly Dictionary<long, WaterTile> _tiles = new Dictionary<long, WaterTile>();
            private readonly Queue<WaterTile> _queue = new Queue<WaterTile>();
            private Timer _buildTimer, _evictTimer;
            private readonly List<long> _evictBuf = new List<long>();

            private readonly List<Vector3> _verts = new List<Vector3>(8192);
            private readonly List<int> _tris = new List<int>(24576);
            private Vector3[] _vertArr = new Vector3[8192];
            private int[] _triArr = new int[24576];
            private int[] _grid = new int[4096];
            private static readonly Collider[] _colBuf = new Collider[2048];
            private readonly Dictionary<Mesh, MeshData> _meshCache = new Dictionary<Mesh, MeshData>();
            private struct MeshData { public Vector3[] Verts; public int[] Tris; }
            private Vector3[] _worldVerts = new Vector3[4096];
            private int[] _vertRemap = new int[4096];

            private int RemapVertex(int local)
            {
                int index = _vertRemap[local];
                if (index >= 0) return index;
                index = _verts.Count;
                _verts.Add(_worldVerts[local]);
                _vertRemap[local] = index;
                return index;
            }
            private static readonly Vector3[] _pathBuf = new Vector3[RecastWrapper.MAX_PATH_SIZE];
            private static readonly ulong[] _pathPolyBuf = new ulong[RecastWrapper.MAX_PATH_SIZE];
            private static readonly Vector3[] _boxVerts = new Vector3[8];
            private static readonly int[] BoxTris =
            {
                7, 4, 3, 7, 6, 4, 4, 6, 5, 4,
                5, 0, 4, 5, 1, 4, 1, 0, 5, 6,
                2, 5, 2, 1, 6, 7, 3, 6, 3, 2,
                0, 1, 3, 0, 3, 7
            };

            public static void OnUnloadPlugin()
            {
                _instance?.DestroyAll();
                _instance = null;
            }

            public int TileCount => _tiles.Count;

            public bool IsReady => _handle != IntPtr.Zero;

            private float TileSide => _params.tileSize * _params.cellSize;

            private static long Key(int x, int y) => ((long)x << 32) | (uint)y;

            public CorridorState EnsureCorridor(Vector3 from, Vector3 to, out string error)
            {
                error = null;
                float distance = Vector3Ex.Distance2D(from, to);
                if (distance > MaxRescueDistance)
                {
                    error = $"the shore is {distance:0} m away, beyond the {MaxRescueDistance:0} m limit";
                    return CorridorState.Failed;
                }
                if (!EnsureNavMesh(out error)) return CorridorState.Failed;

                float side = TileSide;
                int x0 = Mathf.Max(0, Mathf.FloorToInt((Mathf.Min(from.x, to.x) - CorridorMargin - _bounds.min.x) / side));
                int x1 = Mathf.Min(_tileNum.x - 1, Mathf.FloorToInt((Mathf.Max(from.x, to.x) + CorridorMargin - _bounds.min.x) / side));
                int y0 = Mathf.Max(0, Mathf.FloorToInt((Mathf.Min(from.z, to.z) - CorridorMargin - _bounds.min.z) / side));
                int y1 = Mathf.Min(_tileNum.y - 1, Mathf.FloorToInt((Mathf.Max(from.z, to.z) + CorridorMargin - _bounds.min.z) / side));
                if (x0 > x1 || y0 > y1)
                {
                    error = "the corridor is outside the map";
                    return CorridorState.Failed;
                }

                float now = UnityEngine.Time.realtimeSinceStartup;
                bool ready = true;
                for (int y = y0; y <= y1; y++)
                    for (int x = x0; x <= x1; x++)
                    {
                        long key = Key(x, y);
                        if (!_tiles.TryGetValue(key, out var tile))
                        {
                            tile = new WaterTile { X = x, Y = y };
                            _tiles[key] = tile;
                            _queue.Enqueue(tile);
                        }
                        tile.LastUse = now;
                        if (!tile.Built) ready = false;
                    }
                if (!ready) StartBuildWave();
                return ready ? CorridorState.Ready : CorridorState.Pending;
            }

            public bool HasMeshAt(Vector3 world)
            {
                if (_handle == IntPtr.Zero) return false;
                float side = TileSide;
                int x = Mathf.FloorToInt((world.x - _bounds.min.x) / side);
                int y = Mathf.FloorToInt((world.z - _bounds.min.z) / side);
                return _tiles.TryGetValue(Key(x, y), out var tile) && tile.Built && tile.HasMesh;
            }

            public bool TrySample(Vector3 world, out Vector3 onMesh) => SampleRef(world, SampleExtents, out onMesh, out _);

            private bool SampleShoreColumn(Vector3 world, out Vector3 onMesh)
            {
                float ground = TerrainMeta.HeightMap != null ? TerrainMeta.HeightMap.GetHeight(world) : world.y;
                var water = WaterLevel.GetWaterInfo(new Vector3(world.x, ground + 0.05f, world.z), waves: false, volumes: false);
                float lo = Mathf.Min(ground, world.y) - ColumnPadDown;
                float hi = Mathf.Max(Mathf.Max(ground, world.y), water.isValid ? water.surfaceLevel : ground) + ShoreColumnAboveWater;
                Vector3 center = new Vector3(world.x, (lo + hi) * 0.5f, world.z);
                Vector3 extents = new Vector3(SampleExtents.x, (hi - lo) * 0.5f, SampleExtents.z);
                return SampleRef(center, extents, out onMesh, out _);
            }

            public bool TrySampleColumn(Vector3 world, out Vector3 onMesh) => SampleColumnRef(world, out onMesh, out _);

            private bool SampleColumnRef(Vector3 world, out Vector3 onMesh, out ulong polyRef)
            {
                float ground = TerrainMeta.HeightMap != null ? TerrainMeta.HeightMap.GetHeight(world) : world.y;
                float lo = Mathf.Min(ground, world.y) - ColumnPadDown;
                float hi = Mathf.Max(ground, world.y) + ColumnPadUp;
                Vector3 center = new Vector3(world.x, (lo + hi) * 0.5f, world.z);
                Vector3 extents = new Vector3(SampleExtents.x, (hi - lo) * 0.5f, SampleExtents.z);
                return SampleRef(center, extents, out onMesh, out polyRef);
            }

            private bool SampleRef(Vector3 world, Vector3 extents, out Vector3 onMesh, out ulong polyRef)
            {
                onMesh = world;
                polyRef = 0;
                if (_handle == IntPtr.Zero) return false;
                if (!RecastWrapper.SamplePosition(_handle, in world, in extents, out Vector3 hit, out polyRef, includeGatedDoorPolys: 0, allowNpcDoors: 0) || polyRef == 0) return false;
                onMesh = hit;
                return true;
            }

            public HelperSavedNavMesh.NavPathResult TryRoute(Vector3 from, Vector3 to, List<PathStep> steps, out Vector3 stopWorld, out string error)
            {
                steps.Clear();
                stopWorld = from;
                error = null;
                if (_handle == IntPtr.Zero)
                {
                    error = "the water navmesh is not created";
                    return HelperSavedNavMesh.NavPathResult.None;
                }
                if (!SampleColumnRef(from, out Vector3 start, out ulong startRef))
                {
                    error = "no water navmesh under the bot";
                    return HelperSavedNavMesh.NavPathResult.StartOffMesh;
                }
                if (!SampleRef(to, SampleExtents, out Vector3 end, out _) && !SampleShoreColumn(to, out end))
                {
                    error = "the shore point is off the water navmesh";
                    return HelperSavedNavMesh.NavPathResult.EndOffMesh;
                }

                DtStatus status = RecastWrapper.FindPath(_handle, ref startRef, in start, in end, _pathBuf, out int length,
                    _pathPolyBuf, out _, PathIterations, allowNpcDoors: 0);
                if (((uint)status & (uint)DtStatus.Failure) != 0u || length <= 0)
                {
                    error = "the native search returned " + status;
                    return HelperSavedNavMesh.NavPathResult.None;
                }

                var corners = new List<Vector3>(length);
                for (int i = 0; i < length; i++) corners.Add(_pathBuf[i]);
                stopWorld = corners[length - 1];
                steps.Add(new PathStep(new HelperNavLayers.WorldNavNode(start), NodeHint.None, null, 0f));
                steps.Add(new PathStep(new HelperNavLayers.WorldNavNode(stopWorld), NodeHint.None, corners, HelperSavedNavMesh.PathLength(corners)));

                bool partial = (status & DtStatus.PartialResult) == DtStatus.PartialResult
                               || (stopWorld - end).sqrMagnitude > CompleteGap * CompleteGap;
                if (!partial) return HelperSavedNavMesh.NavPathResult.Complete;
                error = $"the seabed path stops at {stopWorld}, {Vector3.Distance(stopWorld, end):0.0} m short of the shore";
                return HelperSavedNavMesh.NavPathResult.Partial;
            }

            #region Навмеш и сборка тайлов

            private static NavMeshBuildParams MakeParams()
            {
                var p = new NavMeshBuildParams(true);
                p.cellSize = CellSize;
                p.cellHeight = CellHeight;
                p.agentHeight = AgentHeight;
                p.agentRadius = AgentRadius;
                p.agentMaxClimb = AgentMaxClimb;
                p.agentMaxSlope = AgentMaxSlope;
                p.tileSize = TileVoxels;
                p.partitionType = NavMeshBuildParams.EPartitionType.Watershed;
                p.maxNodes = MaxNodes;
                p.minRegionSizeMeters = MinRegionSizeMeters;
                p.filterLowHangingObstacles = true;
                p.filterLedgeSpans = false;
                p.filterWalkableLowHeightSpans = true;
                p.buildDetailMesh = true;
                return p;
            }

            private bool EnsureNavMesh(out string error)
            {
                error = null;
                if (_handle != IntPtr.Zero) return true;
                Vector3 size = TerrainMeta.Size;
                if (size.x <= 0f || size.z <= 0f)
                {
                    error = "the map is not loaded yet";
                    return false;
                }
                _params = MakeParams();
                _bounds = new Bounds(TerrainMeta.Position + size * 0.5f, size);
                try { _handle = RecastWrapper.CreateEmptyNavMesh(in _params, _bounds.min, _bounds.max); }
                catch (Exception e)
                {
                    _handle = IntPtr.Zero;
                    error = "native Recast is unavailable (" + e.GetType().Name + ": " + e.Message + ")";
                    return false;
                }
                if (_handle == IntPtr.Zero)
                {
                    error = "CreateEmptyNavMesh = 0";
                    return false;
                }
                int cx = (int)(size.x / _params.cellSize + 0.5f);
                int cz = (int)(size.z / _params.cellSize + 0.5f);
                _tileNum = new Vector2Int(Mathf.Max(1, (int)((cx + _params.tileSize - 1f) / _params.tileSize)),
                                          Mathf.Max(1, (int)((cz + _params.tileSize - 1f) / _params.tileSize)));
                _evictTimer = NPCsController.Instance?.timer.Every(EvictStep, EvictStale);
                return true;
            }

            private void StartBuildWave()
            {
                if (_buildTimer != null || _queue.Count == 0) return;
                _buildTimer = NPCsController.Instance?.timer.Every(BuildStep, BuildQueued);
            }

            private void BuildQueued()
            {
                if (_handle == IntPtr.Zero) { StopBuildWave(); return; }
                var sw = System.Diagnostics.Stopwatch.StartNew();
                while (_queue.Count > 0)
                {
                    var tile = _queue.Dequeue();
                    if (tile.Built || !_tiles.TryGetValue(Key(tile.X, tile.Y), out var live) || live != tile) continue;
                    bool? mesh = BuildTile(tile.X, tile.Y);
                    tile.Built = true;
                    tile.HasMesh = mesh == true;
                    if (sw.Elapsed.TotalMilliseconds >= BuildBudgetMs) break;
                }
                if (_queue.Count > 0) return;

                StopBuildWave();
            }

            private readonly double[] _wavePartMs = new double[4];

            private static double MsSince(long startTicks)
                => (System.Diagnostics.Stopwatch.GetTimestamp() - startTicks) * 1000d / System.Diagnostics.Stopwatch.Frequency;

            private void StopBuildWave()
            {
                _buildTimer?.Destroy();
                _buildTimer = null;
            }

            private void EvictStale()
            {
                if (_handle == IntPtr.Zero || _tiles.Count == 0) return;
                float now = UnityEngine.Time.realtimeSinceStartup;
                _evictBuf.Clear();
                foreach (var kv in _tiles)
                    if (kv.Value.Built && now - kv.Value.LastUse > TileLifetime) _evictBuf.Add(kv.Key);
                if (_evictBuf.Count == 0) return;
                for (int i = 0; i < _evictBuf.Count; i++)
                {
                    var tile = _tiles[_evictBuf[i]];
                    if (tile.HasMesh)
                    {
                        try { RecastWrapper.RemoveTileFromNavMesh(_handle, tile.X, tile.Y); }
                        catch (Exception e) { Debug.LogWarning<HelperWaterNavMesh>("RemoveTileFromNavMesh({0},{1}): {2}", tile.X, tile.Y, e.Message); }
                    }
                    _tiles.Remove(_evictBuf[i]);
                }
                if (_tiles.Count == 0) _meshCache.Clear();
            }

            private void DestroyAll()
            {
                StopBuildWave();
                _evictTimer?.Destroy();
                _evictTimer = null;
                if (_handle != IntPtr.Zero)
                {
                    try { RecastWrapper.DestroyNavMesh(_handle); }
                    catch (Exception e) { Debug.LogWarning<HelperWaterNavMesh>("DestroyNavMesh: {0}", e.Message); }
                    _handle = IntPtr.Zero;
                }
                _tiles.Clear();
                _queue.Clear();
                _meshCache.Clear();
            }

            private bool? BuildTile(int tx, int ty)
            {
                float side = TileSide;
                Vector3 lo = new Vector3(_bounds.min.x + tx * side, _bounds.min.y, _bounds.min.z + ty * side);
                Vector3 hi = new Vector3(lo.x + side, _bounds.max.y, lo.z + side);
                float border = (Mathf.CeilToInt(_params.agentRadius / _params.cellSize) + 3) * _params.cellSize;
                Vector3 gmin = new Vector3(lo.x - border, lo.y, lo.z - border);
                Vector3 gmax = new Vector3(hi.x + border, hi.y, hi.z + border);

                _verts.Clear();
                _tris.Clear();
                long part = System.Diagnostics.Stopwatch.GetTimestamp();
                bool terrain = AddTerrain(gmin, gmax, out float groundLo, out float groundHi);
                if (!terrain) return false;
                AddColliders(gmin, gmax, groundLo - ColliderPadDown, groundHi + ColliderPadUp);
                if (_verts.Count == 0 || _tris.Count < 3) return false;
                part = System.Diagnostics.Stopwatch.GetTimestamp();
                try { return BuildTileNative(tx, ty, lo, hi); }
                finally { _wavePartMs[3] += MsSince(part); }
            }

            private bool? BuildTileNative(int tx, int ty, Vector3 lo, Vector3 hi)
            {

                if (_vertArr.Length < _verts.Count) _vertArr = new Vector3[Mathf.NextPowerOfTwo(_verts.Count)];
                if (_triArr.Length < _tris.Count) _triArr = new int[Mathf.NextPowerOfTwo(_tris.Count)];
                _verts.CopyTo(_vertArr);
                _tris.CopyTo(_triArr);

                float loY = float.MaxValue, hiY = float.MinValue;
                for (int i = 0; i < _verts.Count; i++)
                {
                    float y = _verts[i].y;
                    if (y < loY) loY = y;
                    if (y > hiY) hiY = y;
                }
                float ch = _params.cellHeight;
                loY -= ch * 2f;
                hiY += ch * 2f;
                loY = _bounds.min.y + Mathf.Floor((loY - _bounds.min.y) / ch) * ch;
                if (Mathf.CeilToInt((hiY - loY) / ch) > MaxSpanHeight) return null;

                var vertPin = System.Runtime.InteropServices.GCHandle.Alloc(_vertArr, System.Runtime.InteropServices.GCHandleType.Pinned);
                var triPin = System.Runtime.InteropServices.GCHandle.Alloc(_triArr, System.Runtime.InteropServices.GCHandleType.Pinned);
                IntPtr hf = IntPtr.Zero, chf = IntPtr.Zero, pm = IntPtr.Zero, dm = IntPtr.Zero, data = IntPtr.Zero;
                try
                {
                    Vector3 bmin = new Vector3(lo.x, loY, lo.z);
                    Vector3 bmax = new Vector3(hi.x, hiY, hi.z);
                    hf = RecastWrapper.CreateHeightFieldRaw(in _params, vertPin.AddrOfPinnedObject(), _verts.Count,
                        triPin.AddrOfPinnedObject(), _tris.Count / 3, in bmin, in bmax, triAreaOverrides: IntPtr.Zero);
                    if (hf == IntPtr.Zero) return null;
                    chf = RecastWrapper.CreateCompactHeightField(in _params, hf, volumes: null, volumeCount: 0);
                    if (chf == IntPtr.Zero) return null;
                    pm = RecastWrapper.CreatePolymesh(in _params, chf);
                    if (pm == IntPtr.Zero) return false;
                    dm = RecastWrapper.CreateDetailPolymesh(in _params, pm, chf,
                        ConVar.RustNav.detailSampleDistMult, ConVar.RustNav.detailSampleMaxErrorMult);
                    if (dm == IntPtr.Zero) return null;
                    data = RecastWrapper.CreateNavData(in _params, tx, ty, pm, dm, out int dataSize);
                    if (data == IntPtr.Zero) return null;
                    if (!RecastWrapper.AddPrebuiltTileToNavMesh(_handle, tx, ty, data, dataSize)) return null;
                    data = IntPtr.Zero;
                    return true;
                }
                catch (Exception e)
                {
                    Debug.LogWarning<HelperWaterNavMesh>("BuildTile({0},{1}): {2}: {3}", tx, ty, e.GetType().Name, e.Message);
                    return null;
                }
                finally
                {
                    if (data != IntPtr.Zero) RecastWrapper.FreeTileData(data);
                    if (dm != IntPtr.Zero) RecastWrapper.FreeDetailPolymesh(dm);
                    if (pm != IntPtr.Zero) RecastWrapper.FreePolymesh(pm);
                    if (chf != IntPtr.Zero) RecastWrapper.FreeCompactHeightField(chf);
                    if (hf != IntPtr.Zero) RecastWrapper.FreeHeightField(hf);
                    vertPin.Free();
                    triPin.Free();
                }
            }

            private bool AddTerrain(Vector3 min, Vector3 max, out float groundLo, out float groundHi)
            {
                groundLo = float.MaxValue;
                groundHi = float.MinValue;
                var heightMap = TerrainMeta.HeightMap;
                if (heightMap == null) return false;
                var alphaMap = TerrainMeta.AlphaMap;

                float x0 = Mathf.Floor(min.x / TerrainStep) * TerrainStep;
                float z0 = Mathf.Floor(min.z / TerrainStep) * TerrainStep;
                int nx = Mathf.CeilToInt((max.x - x0) / TerrainStep);
                int nz = Mathf.CeilToInt((max.z - z0) / TerrainStep);
                if (nx <= 0 || nz <= 0) return false;
                int count = (nx + 1) * (nz + 1);
                if (_grid.Length < count) _grid = new int[Mathf.NextPowerOfTwo(count)];

                for (int iz = 0; iz <= nz; iz++)
                    for (int ix = 0; ix <= nx; ix++)
                    {
                        Vector3 p = new Vector3(x0 + ix * TerrainStep, 0f, z0 + iz * TerrainStep);
                        int slot = iz * (nx + 1) + ix;
                        if (alphaMap != null && alphaMap.GetAlpha(p) < 0.1f) { _grid[slot] = -1; continue; }
                        p.y = heightMap.GetHeight(p);
                        if (p.y < groundLo) groundLo = p.y;
                        if (p.y > groundHi) groundHi = p.y;
                        _grid[slot] = _verts.Count;
                        _verts.Add(p);
                    }

                for (int iz = 0; iz < nz; iz++)
                    for (int ix = 0; ix < nx; ix++)
                    {
                        int a = _grid[iz * (nx + 1) + ix], b = _grid[(iz + 1) * (nx + 1) + ix];
                        int c = _grid[iz * (nx + 1) + ix + 1], d = _grid[(iz + 1) * (nx + 1) + ix + 1];
                        if (a >= 0 && b >= 0 && c >= 0) { _tris.Add(a); _tris.Add(b); _tris.Add(c); }
                        if (c >= 0 && b >= 0 && d >= 0) { _tris.Add(c); _tris.Add(b); _tris.Add(d); }
                    }
                return _tris.Count >= 3;
            }

            private void AddColliders(Vector3 min, Vector3 max, float lowY, float highY)
            {
                Vector3 center = new Vector3((min.x + max.x) * 0.5f, (lowY + highY) * 0.5f, (min.z + max.z) * 0.5f);
                Vector3 half = new Vector3((max.x - min.x) * 0.5f, (highY - lowY) * 0.5f, (max.z - min.z) * 0.5f);
                int n = Physics.OverlapBoxNonAlloc(center, half, _colBuf, Quaternion.identity, GeomMask, QueryTriggerInteraction.Ignore);
                var waterMap = TerrainMeta.WaterMap;
                for (int i = 0; i < n; i++)
                {
                    var col = _colBuf[i];
                    if (col == null) continue;
                    var ent = col.gameObject.ToBaseEntity();
                    if (ent != null && (ent.isClient || ent.IsDestroyed)) continue;
                    if (ent is TreeEntity tree && !tree.IncludeInNavmesh) continue;
                    int triStart = _tris.Count;
                    AddCollider(col, min, max, lowY, highY);
                    if (waterMap == null || _tris.Count == triStart) continue;
                    Bounds b = col.bounds;
                    float water = waterMap.GetHeight(b.center);
                    if (b.max.y < water - SwimBandBelow || b.min.y > water + SwimBandAbove) continue;
                    ExtrudeSwimBand(waterMap, triStart, _tris.Count, lowY);
                }
            }

            private void ExtrudeSwimBand(TerrainWaterMap waterMap, int triFrom, int triTo, float floorY)
            {
                _bandTris.Clear();
                _bandEdgeUse.Clear();
                for (int t = triFrom; t + 2 < triTo; t += 3)
                {
                    int ia = _tris[t], ib = _tris[t + 1], ic = _tris[t + 2];
                    Vector3 a = _verts[ia], b = _verts[ib], c = _verts[ic];
                    float lo = Mathf.Min(a.y, Mathf.Min(b.y, c.y));
                    float hi = Mathf.Max(a.y, Mathf.Max(b.y, c.y));
                    float water = waterMap.GetHeight((a + b + c) / 3f);
                    if (hi < water - SwimBandBelow || lo > water + SwimBandAbove) continue;
                    _bandTris.Add(t);
                    CountBandEdge(ia, ib);
                    CountBandEdge(ib, ic);
                    CountBandEdge(ic, ia);
                }
                for (int k = 0; k < _bandTris.Count; k++)
                {
                    int t = _bandTris[k];
                    int ia = _tris[t], ib = _tris[t + 1], ic = _tris[t + 2];
                    if (_bandEdgeUse[EdgeKey(ia, ib)] == 1) AddDropWall(ia, ib, floorY);
                    if (_bandEdgeUse[EdgeKey(ib, ic)] == 1) AddDropWall(ib, ic, floorY);
                    if (_bandEdgeUse[EdgeKey(ic, ia)] == 1) AddDropWall(ic, ia, floorY);
                }
            }

            private readonly List<int> _bandTris = new List<int>();
            private readonly Dictionary<long, int> _bandEdgeUse = new Dictionary<long, int>();

            private static long EdgeKey(int ia, int ib) => ia < ib ? ((long)ia << 32) | (uint)ib : ((long)ib << 32) | (uint)ia;

            private void CountBandEdge(int ia, int ib)
            {
                long key = EdgeKey(ia, ib);
                _bandEdgeUse.TryGetValue(key, out int used);
                _bandEdgeUse[key] = used + 1;
            }

            private void AddDropWall(int ia, int ib, float floorY)
            {
                Vector3 a = _verts[ia], b = _verts[ib];
                if (a.y <= floorY && b.y <= floorY) return;
                int first = _verts.Count;
                _verts.Add(a);
                _verts.Add(b);
                _verts.Add(new Vector3(b.x, floorY, b.z));
                _verts.Add(new Vector3(a.x, floorY, a.z));
                _tris.Add(first); _tris.Add(first + 1); _tris.Add(first + 2);
                _tris.Add(first); _tris.Add(first + 2); _tris.Add(first + 3);
            }

            private void AddCollider(Collider col, Vector3 min, Vector3 max, float lowY, float highY)
            {
                var t = col.transform;
                if (col is MeshCollider mc)
                {
                    var mesh = mc.sharedMesh;
                    if (mesh == null || !mesh.isReadable) return;
                    if (!_meshCache.TryGetValue(mesh, out var md))
                    {
                        md = new MeshData { Verts = mesh.vertices, Tris = mesh.triangles };
                        _meshCache[mesh] = md;
                    }
                    Matrix4x4 m = t.localToWorldMatrix;
                    int count = md.Verts.Length;
                    if (_worldVerts.Length < count) _worldVerts = new Vector3[Mathf.NextPowerOfTwo(count)];
                    if (_vertRemap.Length < count) _vertRemap = new int[Mathf.NextPowerOfTwo(count)];
                    for (int i = 0; i < count; i++)
                    {
                        _worldVerts[i] = m.MultiplyPoint3x4(md.Verts[i]);
                        _vertRemap[i] = -1;
                    }
                    var tris = md.Tris;
                    for (int i = 0; i + 2 < tris.Length; i += 3)
                    {
                        Vector3 va = _worldVerts[tris[i]], vb = _worldVerts[tris[i + 1]], vc = _worldVerts[tris[i + 2]];
                        if (Mathf.Max(va.x, Mathf.Max(vb.x, vc.x)) < min.x || Mathf.Min(va.x, Mathf.Min(vb.x, vc.x)) > max.x) continue;
                        if (Mathf.Max(va.z, Mathf.Max(vb.z, vc.z)) < min.z || Mathf.Min(va.z, Mathf.Min(vb.z, vc.z)) > max.z) continue;
                        if (Mathf.Max(va.y, Mathf.Max(vb.y, vc.y)) < lowY || Mathf.Min(va.y, Mathf.Min(vb.y, vc.y)) > highY) continue;
                        _tris.Add(RemapVertex(tris[i]));
                        _tris.Add(RemapVertex(tris[i + 1]));
                        _tris.Add(RemapVertex(tris[i + 2]));
                    }
                    return;
                }

                Vector3 c, size;
                if (col is BoxCollider bc) { c = bc.center; size = bc.size; }
                else if (col is SphereCollider sc) { c = sc.center; size = Vector3.one * sc.radius * 2f; }
                else if (col is CapsuleCollider cc)
                {
                    c = cc.center;
                    float d = cc.radius * 2f;
                    if (cc.direction == 0) size = new Vector3(cc.height, d, d);
                    else if (cc.direction == 2) size = new Vector3(d, d, cc.height);
                    else size = new Vector3(d, cc.height, d);
                }
                else return;

                Matrix4x4 box = t.localToWorldMatrix * Matrix4x4.Translate(c);
                Vector3 h = size * 0.5f;
                _boxVerts[0] = new Vector3(-h.x, -h.y, -h.z);
                _boxVerts[1] = new Vector3(h.x, -h.y, -h.z);
                _boxVerts[2] = new Vector3(h.x, -h.y, h.z);
                _boxVerts[3] = new Vector3(-h.x, -h.y, h.z);
                _boxVerts[4] = new Vector3(-h.x, h.y, -h.z);
                _boxVerts[5] = new Vector3(h.x, h.y, -h.z);
                _boxVerts[6] = new Vector3(h.x, h.y, h.z);
                _boxVerts[7] = new Vector3(-h.x, h.y, h.z);
                int first = _verts.Count;
                for (int i = 0; i < 8; i++) _verts.Add(box.MultiplyPoint3x4(_boxVerts[i]));
                for (int i = 0; i < BoxTris.Length; i++) _tris.Add(first + BoxTris[i]);
            }

            #endregion
        }

        #endregion

        private readonly Dictionary<ulong, Vector3> _savedNavPicks = new Dictionary<ulong, Vector3>();
        private const float SavedNavDrawTime = 30f;

        private static string DescribeWorldPath(Vector3 from, Vector3 to)
        {
            int mask = 1 << NavMesh.GetAreaFromName("Walkable");
            int type = BaseCustomNpc.NavAgentTypeID;
            if (!HelperMap.SampleNavTyped(from, 2f, type, mask, out Vector3 onFrom))
                return RU ? $"Навмеша игры нет у точки начала {from} (радиус 2 м)." : $"No game navmesh near the start {from} (2 m).";
            if (!HelperMap.SampleNavTyped(to, 2f, type, mask, out Vector3 onTo))
                return RU ? $"Навмеша игры нет у точки конца {to} (радиус 2 м)." : $"No game navmesh near the end {to} (2 m).";

            var path = new RustNavMeshPath();
            if (!HelperMap.CalculateNavPathTyped(onFrom, onTo, type, mask, path))
                return RU ? "Навмеш игры путь не считал." : "The game navmesh failed to calculate a path.";

            var corners = new List<Vector3>();
            PluginExtension.AddCornersWorld(path, onFrom, corners);
            float length = 0f;
            for (int i = 1; i < corners.Count; i++) length += Vector3.Distance(corners[i - 1], corners[i]);
            Vector3 stop = corners.Count > 0 ? corners[corners.Count - 1] : onFrom;
            float gain = Vector3.Distance(onFrom, onTo) - Vector3.Distance(stop, onTo);

            return RU
                ? $"Навмеш игры {onFrom} → {onTo}: {path.status}, углов {corners.Count}, длина {length:0.0} м, конец в {stop}, "
                  + $"до цели осталось {Vector3.Distance(stop, onTo):0.0} м (продвижение {gain:0.0} м)"
                : $"Game navmesh {onFrom} → {onTo}: {path.status}, corners {corners.Count}, length {length:0.0} m, ends at {stop}, "
                  + $"{Vector3.Distance(stop, onTo):0.0} m left (gain {gain:0.0} m)";
        }

        private static string DescribeGen2NavmeshAt(Vector3 at)
        {
            int mask = 1 << UnityEngine.AI.NavMesh.GetAreaFromName("Walkable");
            string hit = Rust.Ai.Gen2.RustNavMeshHelpers.SamplePosition(at, out UnityEngine.AI.NavMeshHit h, 5f, mask)
                ? (RU ? $"навмеш в {Vector3.Distance(at, h.position):0.00} м ({h.position})" : $"navmesh at {Vector3.Distance(at, h.position):0.00} m ({h.position})")
                : (RU ? "навмеша нет в 5 м" : "no navmesh within 5 m");
            return RU
                ? $"Штатный навмеш игры Gen2, точка {at}: {hit}\n  типов агента у Gen2 нет — сетка одна на всех"
                : $"Game Gen2 navmesh at {at}: {hit}\n  Gen2 has no agent types — a single mesh for everyone";
        }

        private static void ReplySavedNavReload(IPlayer requester, HelperSavedNavMesh.DiskLoadSummary summary, float startedAt)
        {
            float secs = UnityEngine.Time.realtimeSinceStartup - startedAt;
            string en = $"Markup reloaded from disk in {secs:0} s: loaded {summary.Loaded} of {summary.Total} ({summary.WithNative} with an own navmesh), "
                        + $"not on the map {summary.NoInstances}, failed {summary.Failed}. State: npcnav list";
            string text = RU
                ? $"Разметка перечитана с диска за {secs:0} с: загружено {summary.Loaded} из {summary.Total} (со своим навмешем {summary.WithNative}), "
                  + $"нет на карте {summary.NoInstances}, с ошибкой {summary.Failed}. Состояние: npcnav list"
                : en;
            string failures = null;
            if (summary.Failed > 0)
            {
                var sb = new System.Text.StringBuilder("Markup keys that failed to load:");
                for (int i = 0; i < summary.Failures.Count; i++)
                {
                    var failure = summary.Failures[i];
                    sb.Append("\n  [").Append(failure.Key).Append(']').Append(failure.IsPrefab ? " (prefab)" : string.Empty)
                      .Append(": ").Append(failure.Error);
                }
                sb.Append("\nRetry one key: npcnav reload <key> [prefab]");
                failures = sb.ToString();
            }
            if (requester != null && (requester.IsServer || requester.IsConnected))
                requester.Reply(failures == null ? text : text + "\n" + failures);
        }

        [Command("npcnav")]
        private void CmdSavedNavMesh(IPlayer iPlayer, string _, string[] args)
        {
            if (!iPlayer.IsServer && !IsAdmin(iPlayer.Id)) { iPlayer.Reply(RU ? "Только для админов." : "Admins only."); return; }
            string sub = args.Length > 0 ? args[0].ToLowerInvariant() : "help";
            if (sub == "navstate")
            {
                iPlayer.Reply(DescribeNavigatorStates(args.Length > 1 ? string.Join(" ", args, 1, args.Length - 1) : null));
                return;
            }
            var store = HelperSavedNavMesh.Instance;
            if (store == null) { iPlayer.Reply(RU ? "Хранилище навмешей не готово." : "The navmesh store is not ready."); return; }
            var player = iPlayer.Object as BasePlayer;

            switch (sub)
            {
                case "list":
                    iPlayer.Reply(store.Describe());
                    return;

                case "reload":
                {
                    if (args.Length > 1)
                    {
                        string key = args[1];
                        bool isPrefab = args.Length > 2 ? args[2].Equals("prefab", StringComparison.OrdinalIgnoreCase)
                                                        : store.TryGet(key, out var existing) && existing.IsPrefab;
                        iPlayer.Reply(store.TryLoadFromDisk(key, isPrefab, out string error)
                            ? (RU ? $"Навмеш [{key}] перечитан с диска." : $"NavMesh [{key}] reloaded from disk.")
                            : (RU ? $"Навмеш [{key}] не загружен: {error}" : $"NavMesh [{key}] not loaded: {error}"));
                        return;
                    }
                    if (store.IsDiskLoading)
                    {
                        iPlayer.Reply(RU ? "Чтение разметки с диска уже идёт — дождись итога. Состояние: npcnav list"
                                         : "Reading markup from disk is already in progress - wait for the summary. State: npcnav list");
                        return;
                    }
                    store.UnregisterAll();
                    float startedAt = UnityEngine.Time.realtimeSinceStartup;
                    int queued = store.LoadAllFromDisk(summary => ReplySavedNavReload(iPlayer, summary, startedAt));
                    if (queued <= 0)
                    {
                        iPlayer.Reply(RU ? "Читать нечего: на диске нет описей разметки. Навмеши сняты, состояние: npcnav list"
                                         : "Nothing to reload: there are no markup descriptions on disk. Navmeshes are unloaded, state: npcnav list");
                        return;
                    }
                    iPlayer.Reply(RU ? $"Навмеши перечитываются с диска: ключей {queued}, по одному за тик; итог придёт ответом сюда же. Состояние: npcnav list"
                                     : $"Navmeshes are being reloaded from disk: {queued} keys, one per tick; the summary comes back here. State: npcnav list");
                    return;
                }

                case "rebind":
                {
                    int unbound = 0;
                    foreach (var mesh in store.All)
                        for (int i = 0; i < mesh.Instances.Count; i++) unbound += mesh.Instances[i].BindEntities();
                    iPlayer.Reply(RU ? $"Привязки обновлены, не найдено объектов: {unbound}." : $"Links rebound, objects not found: {unbound}.");
                    return;
                }

                case "use":
                {
                    if (args.Length > 1) HelperSavedNavMesh.UseInNavigator = !args[1].Equals("off", StringComparison.OrdinalIgnoreCase)
                                                                              && !args[1].Equals("выкл", StringComparison.OrdinalIgnoreCase);
                    iPlayer.Reply(RU
                        ? $"Монументный слой в навигации: {(HelperSavedNavMesh.UseInNavigator ? "да" : "нет")}. Слой даёт переходы графа — двери, кардридеры, кнопки, лестницы; поверхность под ними у каждой цели своя: собран свой навмеш — по нему, нет — по штатному навмешу игры Gen2. Переключить: npcnav use on|off"
                        : $"Monument layer in navigation: {(HelperSavedNavMesh.UseInNavigator ? "yes" : "no")}. The layer adds graph transitions — doors, card readers, buttons, ladders; the surface is per target: an own navmesh if it is built, the game's Gen2 navmesh otherwise.");
                    return;
                }

                case "buildings":
                {
                    if (args.Length > 1)
                    {
                        string mode = args[1].ToLowerInvariant();
                        if (mode == "on" || mode == "вкл") HelperBuildingNavMesh.ManualEnabled = true;
                        else if (mode == "off" || mode == "выкл") HelperBuildingNavMesh.ManualEnabled = false;
                        else if (mode == "scan" || mode == "обход")
                        {
                            if (!HelperBuildingNavMesh.IsRunning)
                            {
                                iPlayer.Reply(RU ? "Система навмешей построек не работает — обходить карту некому. Включить: npcnav buildings on"
                                                 : "The building navmesh system is not running, so there is nothing to scan with. Turn on: npcnav buildings on");
                                return;
                            }
                            int queued = HelperBuildingNavMesh.Instance.QueueAllBuildings();
                            iPlayer.Reply(RU ? $"Обход карты: в очередь сборки поставлено построек {queued} (от {HelperBuildingNavMesh.AutoBuildMinBlocks} блоков, потолок навмешей {HelperBuildingNavMesh.AutoBuildMaxNavs}), собираются по одной. Состояние: npcnav buildings"
                                             : $"Map scan: {queued} buildings queued for build (from {HelperBuildingNavMesh.AutoBuildMinBlocks} blocks, navmesh limit {HelperBuildingNavMesh.AutoBuildMaxNavs}), built one at a time. State: npcnav buildings");
                            return;
                        }
                        else { iPlayer.Reply(RU ? "Формат: npcnav buildings [on|off|scan]" : "Usage: npcnav buildings [on|off|scan]"); return; }
                    }
                    int built = HelperBuildingNavMesh.IsRunning ? HelperBuildingNavMesh.Instance.Count : 0;
                    string subscribers = HelperBuildingNavMesh.DescribeSubscribers(out int subscriberCount);
                    iPlayer.Reply(RU
                        ? $"Навмеш построек {(HelperBuildingNavMesh.IsRunning ? "работает" : "не работает")}: построек под подпиской {HelperBuildingNavMesh.WatchedCount}, подписчиков {subscriberCount}{(subscriberCount > 0 ? $" ({subscribers})" : "")}, включён вручную — {(HelperBuildingNavMesh.ManualEnabled ? "да" : "нет")}, собрано навмешей {built}.\n"
                          + "Вручную: npcnav buildings on|off; обойти все постройки карты: npcnav buildings scan"
                        : $"Building navmesh is {(HelperBuildingNavMesh.IsRunning ? "running" : "not running")}: watched buildings {HelperBuildingNavMesh.WatchedCount}, subscribers {subscriberCount}{(subscriberCount > 0 ? $" ({subscribers})" : "")}, manual mode {(HelperBuildingNavMesh.ManualEnabled ? "on" : "off")}, navmeshes built {built}.\n"
                          + "Manual mode: npcnav buildings on|off; scan all map buildings: npcnav buildings scan");
                    return;
                }

                case "at":
                {
                    Vector3 at;
                    if (TryParseSavedNavVector(args, 1, out Vector3 parsed)) at = parsed;
                    else if (player != null) at = player.transform.position;
                    else { iPlayer.Reply(RU ? "Формат: npcnav at <x> <y> <z>" : "Usage: npcnav at <x> <y> <z>"); return; }
                    iPlayer.Reply(store.DescribePoint(at));
                    return;
                }

                case "agents":
                {
                    Vector3 at;
                    if (TryParseSavedNavVector(args, 1, out Vector3 agentsAt)) at = agentsAt;
                    else if (player != null) at = player.transform.position;
                    else at = Vector3.zero;
                    iPlayer.Reply(DescribeGen2NavmeshAt(at));
                    return;
                }

                case "from":
                {
                    if (player == null) { iPlayer.Reply(RU ? "Точки прицелом — из игры. Из консоли: npcnav route x1 y1 z1 x2 y2 z2" : "Aim points work in game. From console: npcnav route x1 y1 z1 x2 y2 z2"); return; }
                    if (!TryAimSavedNav(player, out Vector3 from)) { iPlayer.Reply(RU ? "Наведись на точку начала." : "Aim at the start point."); return; }
                    _savedNavPicks[player.userID] = from;
                    Debug.DrawSphere(player, SavedNavDrawTime, Color.green, from, 0.3f);
                    iPlayer.Reply(RU ? $"Начало: {from}. Теперь npcnav to" : $"Start: {from}. Now npcnav to");
                    return;
                }

                case "to":
                {
                    if (player == null) { iPlayer.Reply(RU ? "Точки прицелом — из игры." : "Aim points work in game."); return; }
                    if (!_savedNavPicks.TryGetValue(player.userID, out Vector3 from)) { iPlayer.Reply(RU ? "Сначала npcnav from" : "Run npcnav from first"); return; }
                    if (!TryAimSavedNav(player, out Vector3 to)) { iPlayer.Reply(RU ? "Наведись на точку конца." : "Aim at the end point."); return; }
                    iPlayer.Reply(CheckSavedNavRoute(store, from, to, player));
                    return;
                }

                case "route":
                {
                    if (!TryParseSavedNavVector(args, 1, out Vector3 from) || !TryParseSavedNavVector(args, 4, out Vector3 to))
                    { iPlayer.Reply(RU ? "Формат: npcnav route x1 y1 z1 x2 y2 z2" : "Usage: npcnav route x1 y1 z1 x2 y2 z2"); return; }
                    iPlayer.Reply(CheckSavedNavRoute(store, from, to, player));
                    return;
                }

                case "world":
                {
                    if (!TryParseSavedNavVector(args, 1, out Vector3 worldFrom) || !TryParseSavedNavVector(args, 4, out Vector3 worldTo))
                    { iPlayer.Reply(RU ? "Формат: npcnav world x1 y1 z1 x2 y2 z2" : "Usage: npcnav world x1 y1 z1 x2 y2 z2"); return; }
                    iPlayer.Reply(DescribeWorldPath(worldFrom, worldTo));
                    return;
                }

                default:
                    iPlayer.Reply(RU
                        ? "Разметка монументов и префабов (свой навмеш там, где он собран, иначе штатный навмеш игры Gen2):\n"
                          + "  npcnav list — что загружено\n" +
                          "  npcnav reload [ключ] [prefab] — перечитать с диска (без ключа — всё)\n" +
                          "  npcnav rebind — заново найти двери, кардридеры, кнопки и лестницы\n" +
                          "  npcnav at [x y z] — экземпляр и ближайший узел под точкой\n" +
                          "  npcnav agents [x y z] — что навмеш игры видит в точке\n" +
                          "  npcnav from → npcnav to — путь и маршрут между точками прицелом\n" +
                          "  npcnav route x1 y1 z1 x2 y2 z2 — то же координатами\n" +
                          "  npcnav use on|off — участвует ли монументный слой в навигации\n" +
                          "  npcnav buildings [on|off|scan] — система навмешей построек: состояние, ручное включение, разовый обход карты (без подписок аддонов не работает)\n" +
                          $"  npcnav navstate [часть имени] — внутреннее состояние навигатора ботов (не больше {NavStateMaxBots}): пауза, поиск пути, ноды, сторож простоя"
                        : "Monument and prefab markup (an own navmesh where it is built, the game's Gen2 navmesh otherwise):\n"
                          + "  npcnav list — what is loaded\n" +
                          "  npcnav reload [key] [prefab] — reload from disk (no key — everything)\n" +
                          "  npcnav rebind — find doors, card readers, buttons and ladders again\n" +
                          "  npcnav at [x y z] — instance and nearest node at a point\n" +
                          "  npcnav from → npcnav to — path and route between aimed points\n" +
                          "  npcnav route x1 y1 z1 x2 y2 z2 — the same by coordinates\n" +
                          "  npcnav use on|off — whether the monument layer takes part in navigation\n" +
                          "  npcnav buildings [on|off|scan] — building navmesh system: state, manual mode, one-off map scan (idle without addon subscriptions)\n" +
                          $"  npcnav navstate [part of name] — internal navigator state of bots (up to {NavStateMaxBots}): pause, path search, nodes, idle watchdog");
                    return;
            }
        }

        private const int NavStateMaxBots = 10;

        private static string DescribeNavigatorStates(string nameFilter)
        {
            var sb = new System.Text.StringBuilder();
            int total = 0, shown = 0;
            foreach (BaseNetworkable net in BaseNetworkable.serverEntities)
            {
                if (net is not BaseCustomNpc npc || npc.IsDestroyed || npc.navigator == null) continue;
                if (nameFilter != null
                    && (npc.displayName == null || npc.displayName.IndexOf(nameFilter, StringComparison.OrdinalIgnoreCase) < 0)
                    && npc.UserIDString != nameFilter) continue;
                total++;
                if (shown >= NavStateMaxBots) continue;
                shown++;
                sb.Append('\n');
                if (npc.navigator is NavigatorNpc nav) sb.Append(nav.DescribeNavState());
                else sb.Append($"{Debug.Id(npc)} navigator={npc.navigator.GetType().Name} moving={npc.navigator.Moving} "
                               + $"paused={npc.navigator.IsPaused} stuck={npc.navigator.LastStuckReason}");
            }
            if (total == 0)
                return nameFilter == null
                    ? (RU ? "Ботов с навигатором нет." : "There are no bots with a navigator.")
                    : (RU ? $"Ботов с навигатором по «{nameFilter}» не найдено." : $"No bots with a navigator match \"{nameFilter}\".");
            string head = RU
                ? $"Состояние навигатора: ботов {shown} из {total}{(nameFilter != null ? $" по «{nameFilter}»" : "")}"
                : $"Navigator state: {shown} of {total} bots{(nameFilter != null ? $" matching \"{nameFilter}\"" : "")}";
            return head + sb.ToString();
        }

        private static bool TryParseSavedNavVector(string[] args, int offset, out Vector3 value)
        {
            value = Vector3.zero;
            if (args == null || args.Length < offset + 3) return false;
            var style = System.Globalization.NumberStyles.Float;
            var culture = System.Globalization.CultureInfo.InvariantCulture;
            if (!float.TryParse(args[offset], style, culture, out float x)
                || !float.TryParse(args[offset + 1], style, culture, out float y)
                || !float.TryParse(args[offset + 2], style, culture, out float z)) return false;
            value = new Vector3(x, y, z);
            return true;
        }

        private static bool TryAimSavedNav(BasePlayer player, out Vector3 point)
        {
            point = Vector3.zero;
            if (player == null) return false;
            int mask = LayerMask.GetMask("Construction", "Deployed", "Default", "Terrain", "World");
            if (!Physics.Raycast(player.eyes.HeadRay(), out RaycastHit hit, 150f, mask, QueryTriggerInteraction.Ignore)) return false;
            point = hit.point;
            return true;
        }

        private static string CheckSavedNavRoute(HelperSavedNavMesh store, Vector3 from, Vector3 to, BasePlayer draw)
        {
            if (!store.TryGetInstanceAt(from, out var inst))
                return RU ? "Начало не попадает ни в одну размеченную область монумента." : "The start is outside every mapped monument area.";
            if (!inst.Contains(to))
                return RU ? $"Конец за пределами навмеша [{inst.Mesh.Key}]: маршрут строится внутри одного экземпляра." : $"The end is outside navmesh [{inst.Mesh.Key}]: a route stays inside one instance.";

            var corners = new List<Vector3>();
            var steps = new List<PathStep>();
            var sb = new System.Text.StringBuilder($"[{inst.Mesh.Key}] #{inst.Index} ({inst.Mesh.SurfaceName}): ");

            var direct = inst.FindPath(from, to, corners);
            sb.Append(RU ? $"путь по поверхности — {direct}" : $"surface path — {direct}");
            if (corners.Count > 1) sb.Append(RU ? $", {HelperSavedNavMesh.PathLength(corners):0.0} м" : $", {HelperSavedNavMesh.PathLength(corners):0.0} m");
            sb.Append('\n');

            var route = inst.TryBuildRoute(from, to, steps, out Vector3 stopWorld, out string error);
            if (route != HelperSavedNavMesh.NavPathResult.Complete)
            {
                if (route == HelperSavedNavMesh.NavPathResult.Partial)
                    sb.Append(RU
                        ? $"маршрут частичный: шагов {steps.Count - 1}, обрыв на {stopWorld} ({error})"
                        : $"partial route: steps {steps.Count - 1}, break at {stopWorld} ({error})");
                else sb.Append(RU ? $"маршрут не построен: {error}" : $"route failed: {error}");
                if (draw != null && corners.Count > 1)
                    for (int i = 1; i < corners.Count; i++) Debug.DrawLine(draw, SavedNavDrawTime, Color.yellow, corners[i - 1], corners[i]);
                if (draw != null && steps.Count > 1) DrawSavedNavRoute(draw, steps);
                return sb.ToString();
            }

            int surface = 0, doors = 0, climbs = 0, jumps = 0, seams = 0, doorsMissing = 0, controlsMissing = 0;
            float cost = 0f;
            for (int i = 1; i < steps.Count; i++)
            {
                var step = steps[i];
                cost += step.StepCost;
                if ((step.Hint & NodeHint.OpenDoor) != 0)
                {
                    doors++;
                    if (step.LinkedDoor == null) doorsMissing++;
                    if (steps[i - 1].Node is HelperSavedNavMesh.SavedNavNode side && side.Id >= 0 && inst.Mesh.TryGetIndex(side.Id, out int sideIdx))
                    {
                        var ents = inst.Mesh.Nodes[sideIdx].LinkedEntities;
                        bool wantsControl = false;
                        if (ents != null)
                            for (int k = 0; k < ents.Count; k++)
                                if (ents[k] != null && (ents[k].Type == "reader" || ents[k].Type == "button")) wantsControl = true;
                        if (wantsControl && side.LinkedReader == null && side.LinkedButton == null) controlsMissing++;
                    }
                }
                else if ((step.Hint & NodeHint.Climb) != 0) climbs++;
                else if ((step.Hint & NodeHint.Jump) != 0) jumps++;
                else if ((step.Hint & NodeHint.NavMesh) != 0) seams++;
                else if ((step.Hint & NodeHint.CloseDoor) == 0) surface++;
            }
            sb.Append(RU
                ? $"маршрут: шагов {steps.Count - 1}, стоимость {cost:0.0}; по поверхности {surface}, дверей {doors}, лестниц {climbs}, прыжков {jumps}, швов {seams}"
                : $"route: steps {steps.Count - 1}, cost {cost:0.0}; surface {surface}, doors {doors}, ladders {climbs}, jumps {jumps}, seams {seams}");
            if (doorsMissing > 0) sb.Append(RU ? $"; створка не найдена у {doorsMissing} дверей" : $"; door leaf not found for {doorsMissing} doors");
            if (controlsMissing > 0) sb.Append(RU ? $"; кардридер или кнопка не найдены у {controlsMissing} дверей" : $"; card reader or button not found for {controlsMissing} doors");

            if (draw != null) DrawSavedNavRoute(draw, steps);
            return sb.ToString();
        }

        private static void DrawSavedNavRoute(BasePlayer player, List<PathStep> steps)
        {
            if (player == null || steps.Count == 0) return;
            Vector3 prev = steps[0].Position;
            Debug.DrawSphere(player, SavedNavDrawTime, Color.green, prev, 0.35f);
            for (int i = 1; i < steps.Count; i++)
            {
                var step = steps[i];
                Color color = SavedNavHintColor(step.Hint);
                if (step.Waypoints != null)
                    for (int k = 0; k < step.Waypoints.Count; k++)
                    {
                        Debug.DrawLine(player, SavedNavDrawTime, color, prev, step.Waypoints[k]);
                        prev = step.Waypoints[k];
                    }
                Debug.DrawLine(player, SavedNavDrawTime, color, prev, step.Position);
                prev = step.Position;
            }
            Debug.DrawSphere(player, SavedNavDrawTime, Color.red, prev, 0.35f);
        }

        private static Color SavedNavHintColor(NodeHint hint)
        {
            if ((hint & (NodeHint.OpenDoor | NodeHint.CloseDoor)) != 0) return new Color(1f, 0.6f, 0f);
            if ((hint & NodeHint.Climb) != 0) return Color.green;
            if ((hint & NodeHint.Jump) != 0) return Color.magenta;
            if ((hint & NodeHint.NavMesh) != 0) return Color.cyan;
            return Color.yellow;
        }
    }
