        #region MethodsAPI

        public void PlayVoiceFile<T>(BasePlayer initiator, BasePlayer target, string fileName) where T : Plugin
        {
            if (!TryGetCachedVoice(typeof(T).Name, fileName, out var cached)) return;
            SoundVoice playback = BeginVoice(initiator, cached);
            playback?.PlaySounds(initiator, target);
        }
        public void PlayVoiceFile<T>(BasePlayer initiator, Vector3 position, float radius, string fileName) where T : Plugin
        {
            if (radius <= 0f || position == Vector3.zero) return;
            if (BaseNetworkable.GetConnectionsWithin(position, radius).Count == 0) return;
            if (!TryGetCachedVoice(typeof(T).Name, fileName, out var cached)) return;
            SoundVoice playback = BeginVoice(initiator, cached);
            playback?.PlaySounds(initiator, position, radius);
        }

        public bool IsVoicePlaying(BasePlayer source)
            => source?.net != null && _activeVoices.TryGetValue(source.net.ID.Value, out SoundVoice voice) && voice.IsPlaying;

        private SoundVoice BeginVoice(BasePlayer initiator, SoundVoice cached)
        {
            if (initiator?.net == null) return null;
            ulong id = initiator.net.ID.Value;
            if (_activeVoices.TryGetValue(id, out SoundVoice previous)) previous.StopStream();
            _voiceScratch.Clear();
            foreach (var kv in _activeVoices)
                if (kv.Key != id && !kv.Value.IsPlaying) _voiceScratch.Add(kv.Key);
            for (int i = 0; i < _voiceScratch.Count; i++) _activeVoices.Remove(_voiceScratch[i]);
            SoundVoice playback = cached.CreatePlayback();
            _activeVoices[id] = playback;
            return playback;
        }

        private bool TryGetCachedVoice(string owner, string name, out SoundVoice voice)
        {
            string key = owner + FolderPhrases + name;
            if (!_voiceCache.TryGetValue(key, out voice))
            {
                TryLoadSoundFile(owner, name, out voice);
                _voiceCache[key] = voice;
            }
            return voice != null;
        }

        #endregion

        #region Hooks
        private void OnPlayerVoice(BasePlayer player, ArraySegment<byte> data)
        {
            if (recordedPlayers.TryGetValue(player, out var soundVoice) && soundVoice.IsRecord)
            {
                soundVoice.AddVoicePacket(data.ToArray());
            }
        }

        private void OnPlayerDisconnected(BasePlayer player)
        {
            CloseRecUI(player);
            recordedPlayers.Remove(player);
        }
        #endregion

        #region Commands
        [Command("close_rec")]
        private void CloseRec(IPlayer pl, string command, string[] args)
        {
            if (pl.Object is BasePlayer player && recordedPlayers.ContainsKey(player))
            {
                CloseRecUI(player);
                recordedPlayers.Remove(player);
            }
        }
        public void Cmd_RecVoice<T>(IPlayer pl, string[] args) where T : Plugin
        {
            if (pl.Object is BasePlayer player)
            {
                if (args?.Length is int length)
                {
                    SoundVoice soundVoice;
                    if(length == 0)
                    {
                        if (!recordedPlayers.ContainsKey(player))
                        {
                            recordedPlayers[player] = new SoundVoice();
                            OpenRecUIPanel(player, typeof(T).Name);
                        }
                        else
                        {
                            CloseRecUI(player);
                            recordedPlayers.Remove(player);
                        }
                        return;
                    }
                    switch (args[0].ToLower())
                    {
                        case "start":
                            {
                                if (!recordedPlayers.ContainsKey(player))
                                {
                                    recordedPlayers[player] = new SoundVoice();
                                    OpenRecUIPanel(player, typeof(T).Name);
                                }
                                soundVoice = recordedPlayers[player];

                                if (!soundVoice.IsRecord)
                                {
                                    soundVoice.IsRecord = true;
                                    pl.Reply(GetLangText(player.UserIDString, "record_start"));
                                }
                                else pl.Reply(GetLangText(player.UserIDString, "record"));
                                return;
                            }
                        case "stop":
                            {
                                if (recordedPlayers.ContainsKey(player))
                                {
                                    soundVoice = recordedPlayers[player];
                                    if (soundVoice.IsRecord)
                                    {
                                        pl.Reply(GetLangText(player.UserIDString, "record_stop"));
                                        soundVoice.IsRecord = false;
                                        return;
                                    }
                                }
                                pl.Reply(GetLangText(player.UserIDString, "not_record"));
                                return;
                            }
                        case "replay":
                            {
                                if (length == 1)
                                {
                                    if (recordedPlayers.ContainsKey(player))
                                    {
                                        soundVoice = recordedPlayers[player];
                                        if (soundVoice.IsRecord)
                                        {
                                            pl.Reply(GetLangText(player.UserIDString, "record_stop"));
                                            soundVoice.IsRecord = false;
                                        }
                                        if (soundVoice.HasSounds)
                                        {
                                            soundVoice.TestPlaySounds(player);
                                            pl.Reply(GetLangText(player.UserIDString, "play_current_voices"));
                                        }
                                        else
                                        {
                                            pl.Reply(GetLangText(player.UserIDString, "not_recorded_voices"));
                                        }
                                        return;
                                    }
                                    pl.Reply(GetLangText(player.UserIDString, "not_record"));
                                }
                                else if (length == 2)
                                {
                                    if (TryLoadSoundFile<T>(args[1], out soundVoice))
                                    {
                                        soundVoice.TestPlaySounds(player);
                                        pl.Reply(GetLangText(player.UserIDString, "play_name_voices", args[1]));
                                    }
                                    else pl.Reply(GetLangText(player.UserIDString, "not_name_file", args[1]));
                                }
                                else pl.Reply(GetLangText(player.UserIDString, "args_error"));

                                return;
                            }
                        case "save":
                            {
                                if (length == 2)
                                {
                                    if (ExistsFile<T>(args[1]))
                                    {
                                        ChatMessage(player, "exists_name_file", args[1]);
                                        return;
                                    }
                                    if (recordedPlayers.ContainsKey(player))
                                    {
                                        soundVoice = recordedPlayers[player];
                                        if (soundVoice.IsRecord)
                                        {
                                            soundVoice.IsRecord = false;
                                            pl.Reply(GetLangText(player.UserIDString, "record_stopped"));
                                        }
                                        if (soundVoice.HasSounds)
                                        {
                                            SaveSoundFile<T>(args[1], soundVoice);
                                            pl.Reply(GetLangText(player.UserIDString, "save_name_voices", args[1]));
                                        }
                                        else
                                        {
                                            pl.Reply(GetLangText(player.UserIDString, "not_recorded_voices"));
                                        }
                                        recordedPlayers.Remove(player);
                                        return;
                                    }
                                    else pl.Reply(GetLangText(player.UserIDString, "not_record"));
                                }
                                else pl.Reply(GetLangText(player.UserIDString, "args_error"));

                                return;
                            }
                        case "clear":
                            {
                                if (recordedPlayers.ContainsKey(player))
                                {
                                    soundVoice = recordedPlayers[player];
                                    if (soundVoice.IsRecord)
                                    {
                                        pl.Reply(GetLangText(player.UserIDString, "record_stopped"));
                                        soundVoice.IsRecord = false;
                                    }
                                    soundVoice.Sounds.Clear();
                                    soundVoice.timePlay = 0f;
                                    pl.Reply(GetLangText(player.UserIDString, "clear_record"));
                                }
                                else pl.Reply(GetLangText(player.UserIDString, "not_record"));
                                return;
                            }
                        case "remove":
                            {
                                if (recordedPlayers.ContainsKey(player))
                                {
                                    soundVoice = recordedPlayers[player];
                                    if (soundVoice.IsRecord)
                                    {
                                        pl.Reply(GetLangText(player.UserIDString, "record_stopped"));
                                        soundVoice.IsRecord = false;
                                    }
                                    recordedPlayers.Remove(player);
                                    pl.Reply(GetLangText(player.UserIDString, "remove_current_voices"));
                                }
                                return;
                            }
                        case "delete":
                            {
                                if (length == 2)
                                {
                                    if (ExistsFile<T>(args[1]))
                                    {
                                        DeleteFile<T>(args[1]);
                                        pl.Reply(GetLangText(player.UserIDString, "delete_name_voices", args[1]));
                                    }
                                    else pl.Reply(GetLangText(player.UserIDString, "not_name_file", args[1]));
                                }
                                else pl.Reply(GetLangText(player.UserIDString, "args_error"));
                                return;
                            }
                        case "load":
                            {
                                if (recordedPlayers.TryGetValue(player, out var current) && current.HasSounds)
                                {
                                    pl.Reply(GetLangText(player.UserIDString, "contents_current_voices"));
                                    return;
                                }
                                if (length == 2)
                                {
                                    if (ExistsFile<T>(args[1]))
                                    {
                                        if (TryLoadSoundFile<T>(args[1], out soundVoice))
                                        {
                                            recordedPlayers[player] = soundVoice;
                                            pl.Reply(GetLangText(player.UserIDString, "load_name_voices", args[1]));
                                            goto case "start";
                                        }
                                        else
                                        {
                                            pl.Reply(GetLangText(player.UserIDString, "not_load_name_file", args[1]));
                                        }
                                    }
                                    else pl.Reply(GetLangText(player.UserIDString, "not_name_file", args[1]));
                                }
                                else pl.Reply(GetLangText(player.UserIDString, "args_error"));
                                return;
                            }
                        default:
                            {
                                Debug.LogWarning("Command not found [{0}]", args[0]);
                                return;
                            }
                    }
                }
                else
                {
                    Debug.LogWarning("Not enough arguments");
                }
            }
        }
        #endregion

        #region Data
        protected bool ExistsFile(string owner, string name) => Interface.Oxide.DataFileSystem.ExistsDatafile(owner + FolderPhrases + name);
        protected void DeleteFile(string owner, string name)
        {
            _voiceCache.Remove(owner + FolderPhrases + name);
            if (ExistsFile(owner, name)) Interface.Oxide.DataFileSystem.DeleteDataFile(owner + FolderPhrases + name);
        }
        protected bool TryLoadSoundFile(string owner, string name, out SoundVoice soundVoice)
        {
            soundVoice = null;
            try
            {
                if (ExistsFile(owner, name))
                {
                    soundVoice = Interface.Oxide.DataFileSystem.ReadObject<SoundVoice>(owner + FolderPhrases + name);
                }
                else
                {
                    Debug.LogWarning("File {0} not found", name);
                }
            }
            catch (Exception ex)
            {
                Debug.LogError("TryLoadSoundFile: {0}", ex);
            }
            return soundVoice != null;
        }
        protected void SaveSoundFile(string owner, string name, SoundVoice soundVoice)
        {
            _voiceCache.Remove(owner + FolderPhrases + name);
            Interface.Oxide.DataFileSystem.WriteObject(owner + FolderPhrases + name, soundVoice);
        }

        protected bool ExistsFile<T>(string name) where T : Plugin => ExistsFile(typeof(T).Name, name);
        protected void DeleteFile<T>(string name) where T : Plugin => DeleteFile(typeof(T).Name, name);
        protected bool TryLoadSoundFile<T>(string name, out SoundVoice soundVoice) where T : Plugin => TryLoadSoundFile(typeof(T).Name, name, out soundVoice);
        protected void SaveSoundFile<T>(string name, SoundVoice soundVoice) where T : Plugin => SaveSoundFile(typeof(T).Name, name, soundVoice);

        protected List<string> ListSoundFiles(string owner)
        {
            var result = new List<string>();
            try
            {
                string dir = owner + "/Phrases";
                string abs = System.IO.Path.Combine(Interface.Oxide.DataFileSystem.Directory, dir);
                if (!System.IO.Directory.Exists(abs)) return result;
                string[] files = System.IO.Directory.GetFiles(abs, "*.json", System.IO.SearchOption.AllDirectories);
                for (int i = 0; i < files.Length; i++)
                {
                    string rel = files[i].Substring(abs.Length).TrimStart('\\', '/');
                    rel = rel.Substring(0, rel.Length - 5);
                    result.Add(rel.Replace('\\', '/'));
                }
                result.Sort(System.StringComparer.OrdinalIgnoreCase);
            }
            catch (Exception ex)
            {
                Debug.LogError("ListSoundFiles: {0}", ex);
            }
            return result;
        }
        public sealed class SoundVoice
        {
            [JsonIgnore]
            private const string prefabPlayer = "assets/prefabs/player/player.prefab";
            public float timePlay;
            public List<byte[]> Sounds = new();
            [JsonIgnore]
            private BasePlayer initiatorBotPlayer;
            [JsonIgnore]
            private bool _isRecord = false;
            [JsonIgnore]
            private float _lastVoiceTime;
            private const float VoiceGapCap = 0.5f;
            [JsonIgnore] private BasePlayer _playSource;
            [JsonIgnore] private BasePlayer _playTarget;
            [JsonIgnore] private Vector3 _playPosition;
            [JsonIgnore] private float _playRadius;
            [JsonIgnore] private NetworkableId _playId;
            [JsonIgnore] private int _playIndex;
            [JsonIgnore] private UnityAction _playOnSend;
            [JsonIgnore]
            public bool IsRecord
            {
                get => _isRecord;
                set
                {
                    _isRecord = value;
                    if (value) _lastVoiceTime = 0f;
                }
            }

            [JsonIgnore]
            public bool HasSounds => Sounds?.Count > 0;

            private static int PacketsPerSecond => Instance?.GeneralConfiguration?._controller?.VoicePacketsPerSecond ?? 9;

            [JsonIgnore]
            public bool IsPlaying => _playSource != null && _playSource.IsValid() && _playSource.IsInvoking(SendNextChunk);

            public SoundVoice CreatePlayback() => new SoundVoice { timePlay = timePlay, Sounds = Sounds };

            public void StopStream()
            {
                if (_playSource != null && _playSource.IsValid() && _playSource.IsInvoking(SendNextChunk)) _playSource.CancelInvoke(SendNextChunk);
                _playSource = null;
            }

            public void AddVoicePacket(byte[] data)
            {
                if (_isRecord)
                {
                    float now = UnityEngine.Time.realtimeSinceStartup;
                    if (_lastVoiceTime > 0f)
                    {
                        float gap = now - _lastVoiceTime;
                        if (gap > 0f) timePlay += Mathf.Min(gap, VoiceGapCap);
                    }
                    _lastVoiceTime = now;
                }
                Sounds.Add(data);
            }

            public void TestPlaySounds(BasePlayer target)
            {
                if (initiatorBotPlayer) initiatorBotPlayer.AdminKill();
                Vector3 pos = target.ServerPosition;
                pos.y = TerrainMeta.HeightMap.GetHeight(pos) - 3f;
                initiatorBotPlayer = GameManager.server.CreateEntity(prefabPlayer, pos) as BasePlayer;
                if (initiatorBotPlayer) initiatorBotPlayer.Spawn();
                float playbackSeconds = Sounds.Count / (float)PacketsPerSecond;
                float killDelay = Mathf.Max(timePlay, playbackSeconds) + 1f;
                PlaySounds(initiatorBotPlayer, target, Vector3.zero, 0, () => initiatorBotPlayer.Invoke(initiatorBotPlayer.AdminKill, killDelay));
            }

            public void StopPlayback()
            {
                StopStream();
                if (initiatorBotPlayer) { initiatorBotPlayer.AdminKill(); initiatorBotPlayer = null; }
            }
            public void PlaySounds(BasePlayer initiator, BasePlayer target)
            {
                PlaySounds(initiator, target, Vector3.zero, 0, null);
            }
            public void PlaySounds(BasePlayer initiator, Vector3 position, float radius)
            {
                PlaySounds(initiator, null, position, radius, null);
            }
            private void PlaySounds(BasePlayer initiator, BasePlayer target, Vector3 position, float radius, UnityAction onSend)
            {
                if (HasSounds && initiator)
                {
                    if (initiator.IsInvoking(SendNextChunk)) initiator.CancelInvoke(SendNextChunk);
                    _playSource = initiator;
                    _playId = initiator.net.ID;
                    _playTarget = target;
                    _playPosition = position;
                    _playRadius = radius;
                    _playOnSend = onSend;
                    _playIndex = 0;
                    float interval = 1f / PacketsPerSecond;
                    initiator.InvokeRepeating(SendNextChunk, interval, interval);
                }
            }
            private void SendNextChunk()
            {
                if (_playSource == null || !HasSounds) return;
                if (_playIndex < Sounds.Count)
                {
                    byte[] data = Sounds[_playIndex];
                    if (_playTarget) SendToTarget(_playId, data, _playTarget);
                    else SendToPosition(_playId, data, _playPosition, _playRadius);
                    _playIndex++;
                }
                if (_playIndex >= Sounds.Count)
                {
                    _playSource.CancelInvoke(SendNextChunk);
                    _playOnSend?.Invoke();
                }
            }
            private void SendToPosition(NetworkableId initiator, byte[] data, Vector3 position, float radius)
            {
                if (position != Vector3.zero && radius > 0)
                {
                    NetWrite netWrite = Net.sv.StartWrite();
                    netWrite.PacketID(Message.Type.VoiceData);
                    netWrite.EntityID(initiator);
                    netWrite.BytesWithSize(data);
                    netWrite.Send(new SendInfo(BaseNetworkable.GetConnectionsWithin(position, radius))
                    {
                        priority = Priority.Immediate
                    });
                }
            }
            private void SendToTarget(NetworkableId initiator, byte[] data, BasePlayer target)
            {
                if (target.IsValid() && !target.IsNpc && target.userID.IsSteamId() && target.IsAlive() && target.IsConnected)
                {
                    NetWrite netWrite = Net.sv.StartWrite();
                    netWrite.PacketID(Message.Type.VoiceData);
                    netWrite.EntityID(initiator);
                    netWrite.BytesWithSize(data);
                    netWrite.Send(new SendInfo(target.Connection)
                    {
                        priority = Priority.Immediate
                    });
                }
            }

        }
        #endregion

        #region GUI

        #region GUI: Session helpers
        private bool TryGetRecSession(IPlayer pl, out BasePlayer player, out RecUiSession session)
        {
            player = pl?.Object as BasePlayer;
            session = null;
            return player != null && recSessions.TryGetValue(player, out session);
        }
        private static string JoinArgs(string[] args) => (args == null || args.Length == 0) ? string.Empty : string.Join(" ", args).Trim();
        private static string FormatTime(float seconds)
        {
            if (seconds < 0f) seconds = 0f;
            int total = Mathf.FloorToInt(seconds);
            return $"{total / 60}:{total % 60:00}";
        }
        private void StartPulse(BasePlayer admin, RecUiSession session)
        {
            StopPulse(session);
            session.PulseTimer = timer.Every(0.5f, () =>
            {
                if (admin == null || !admin.IsConnected || !recSessions.ContainsKey(admin)
                    || !recordedPlayers.TryGetValue(admin, out var sv) || !sv.IsRecord)
                {
                    StopPulse(session);
                    return;
                }
                session.PulseBright = !session.PulseBright;
                DrawIndicator(admin, session);
            });
        }
        private void StopPulse(RecUiSession session)
        {
            if (session?.PulseTimer != null)
            {
                session.PulseTimer.Destroy();
                session.PulseTimer = null;
            }
        }
        #endregion

        #region GUI: Panel build
        private static CuiRectTransformComponent RecRect(string anchorMin, string anchorMax, string offsetMin = "0 0", string offsetMax = "0 0")
            => new CuiRectTransformComponent { AnchorMin = anchorMin, AnchorMax = anchorMax, OffsetMin = offsetMin, OffsetMax = offsetMax };

        private static CuiElement RecElement(string parent, string name, string destroy, params ICuiComponent[] components)
        {
            var el = new CuiElement { Parent = parent, Name = name, DestroyUi = destroy };
            for (int i = 0; i < components.Length; i++) el.Components.Add(components[i]);
            return el;
        }

        private static string RecEscape(string s) => s == null ? null : s.Replace('<', '‹').Replace('>', '›');

        internal void UnloadRec()
        {
            var keys = new List<BasePlayer>(recSessions.Keys);
            for (int i = 0; i < keys.Count; i++) CloseRecUI(keys[i]);
        }

        internal void OpenRecUIPanel(BasePlayer admin, string ownerPlugin)
        {
            if (admin == null) return;
            if (!recSessions.TryGetValue(admin, out var session))
            {
                session = new RecUiSession();
                recSessions[admin] = session;
            }
            session.OwnerPlugin = ownerPlugin;
            session.SelectedFile = null;
            session.Search = string.Empty;

            string owner = ownerPlugin;
            container.Clear();

            container.Add(RecElement(UI_layer, layer_rec, layer_rec,
                RecRect("0 0", "1 1"),
                new CuiNeedsCursorComponent()));

            container.Add(RecElement(layer_rec, layer_panel, layer_panel,
                RecRect("0.5 0.5", "0.5 0.5", "-362 -242", "362 242"),
                new CuiImageComponent { Color = "0.09 0.075 0.06 0.985", Sprite = "assets/content/ui/ui.background.tile.psd", Material = "assets/icons/greyout.mat", ImageType = UnityEngine.UI.Image.Type.Tiled }));

            const string header = "rec.header";
            container.Add(RecElement(layer_panel, header, header,
                RecRect("0 1", "1 1", "0 -41", "0 0"),
                new CuiImageComponent { Color = "0.16 0.135 0.10 1", Sprite = "assets/content/ui/ui.background.tile.psd", Material = "assets/icons/greyout.mat", ImageType = UnityEngine.UI.Image.Type.Tiled }));
            container.Add(RecElement(header, header + ".title", header + ".title",
                RecRect("0 0", "1 1", "15 0", "-161 0"),
                new CuiTextComponent { Text = GetLangText(admin.UserIDString, "rec_ui_title"), FontSize = 13, Align = TextAnchor.MiddleLeft, Color = "0.95 0.92 0.86 1" }));
            container.Add(RecElement(header, header + ".owner", header + ".owner",
                RecRect("0 0", "1 1", "150 0", "-40 0"),
                new CuiTextComponent { Text = $"/ {owner}", FontSize = 9, Align = TextAnchor.MiddleLeft, Color = "0.5 0.46 0.4 1" }));
            string headerClose = header + ".close";
