        internal void CloseRecUI(BasePlayer admin)
        {
            if (admin == null) return;
            if (recSessions.TryGetValue(admin, out var session))
            {
                StopPulse(session);
                session.PlayingVoice?.StopPlayback();
                recSessions.Remove(admin);
            }
            CuiHelper.DestroyUi(admin, layer_rec);
        }
        #endregion

        #region GUI: Sub-layer draw
        private const float RecRowH = 36f, RecRowPad = 5f, RecViewportH = 347f;

        private List<string> GetFilteredSoundFiles(RecUiSession session)
        {
            var files = ListSoundFiles(session.OwnerPlugin);
            if (!string.IsNullOrEmpty(session.Search))
            {
                var filtered = new List<string>();
                for (int i = 0; i < files.Count; i++)
                {
                    if (files[i].IndexOf(session.Search, StringComparison.OrdinalIgnoreCase) >= 0) filtered.Add(files[i]);
                }
                files = filtered;
            }
            return files;
        }

        private void RedrawRow(BasePlayer admin, RecUiSession session, List<string> files, int idx)
        {
            if (idx < 0 || idx >= files.Count) return;
            container.Clear();
            AddPhraseRow(session, sub_list + ".sv.bg", files[idx], idx, admin.UserIDString);
            CuiHelper.AddUi(admin, container);
        }

        private void SelectPhrase(BasePlayer admin, RecUiSession session, string name)
        {
            StopRecordingIfActive(admin, session);
            string oldSel = session.SelectedFile;
            session.SelectedFile = name;
            if (oldSel != name)
            {
                var files = GetFilteredSoundFiles(session);
                int oldIdx = oldSel == null ? -1 : files.IndexOf(oldSel);
                int newIdx = files.IndexOf(name);
                if (oldIdx >= 0) RedrawRow(admin, session, files, oldIdx);
                if (newIdx >= 0) RedrawRow(admin, session, files, newIdx);
            }
            DrawMeta(admin, session);
        }

        private void ClearSelection(BasePlayer admin, RecUiSession session)
        {
            string old = session.SelectedFile;
            if (old == null) return;
            session.SelectedFile = null;
            var files = GetFilteredSoundFiles(session);
            int oldIdx = files.IndexOf(old);
            if (oldIdx >= 0) RedrawRow(admin, session, files, oldIdx);
            DrawMeta(admin, session);
        }

        private void StopRecordingIfActive(BasePlayer admin, RecUiSession session)
        {
            if (recordedPlayers.TryGetValue(admin, out var rec) && rec.IsRecord)
            {
                rec.IsRecord = false;
                StopPulse(session);
                DrawIndicator(admin, session);
                DrawRecControls(admin, session);
            }
        }

        private void DrawList(BasePlayer admin, RecUiSession session)
        {
            var files = GetFilteredSoundFiles(session);

            float contentH = Mathf.Max(files.Count * (RecRowH + RecRowPad), RecViewportH);

            container.Clear();

            container.Add(RecElement(layer_left, sub_count, sub_count,
                RecRect("1 1", "1 1", "-48 -28", "-9 -7"),
                new CuiTextComponent { Text = files.Count.ToString(), FontSize = 9, Align = TextAnchor.MiddleRight, Color = "0.55 0.5 0.42 1" }));

            container.Add(RecElement(layer_left, sub_list, sub_list,
                RecRect("0 0", "1 1", "7 7", "-7 -64"),
                new CuiImageComponent { Color = "0.08 0.07 0.05 0.6", Sprite = "assets/content/ui/ui.background.tile.psd", Material = "assets/icons/greyout.mat", ImageType = UnityEngine.UI.Image.Type.Tiled }));
            string scroll = sub_list + ".sv";
            container.Add(RecElement(sub_list, scroll, scroll,
                RecRect("0 0", "1 1"),
                new CuiImageComponent { Color = "0.08 0.07 0.05 0.5", Sprite = "assets/content/ui/ui.background.tile.psd", Material = "assets/icons/greyout.mat", ImageType = UnityEngine.UI.Image.Type.Tiled },
                new CuiScrollViewComponent
                {
                    Horizontal = false, Vertical = true,
                    MovementType = UnityEngine.UI.ScrollRect.MovementType.Clamped,
                    ScrollSensitivity = 24f, Inertia = true, DecelerationRate = 0.135f,
                    ContentTransform = new CuiRectTransform { AnchorMin = "0 1", AnchorMax = "1 1", OffsetMin = $"0 -{contentH}", OffsetMax = "0 0" },
                    VerticalScrollbar = new CuiScrollbar { AutoHide = false, Size = 5, HandleColor = "0.50 0.16 0.13 1", HighlightColor = "0.65 0.22 0.17 1", PressedColor = "0.80 0.28 0.20 1", TrackColor = "0.04 0.04 0.04 0.6" },
                }));

            string backdrop = scroll + ".bg";
            container.Add(RecElement(scroll, backdrop, backdrop,
                RecRect("0 1", "1 1", $"0 -{contentH}", "0 0"),
                new CuiImageComponent { Color = "0.09 0.08 0.06 0.35", Sprite = "assets/content/ui/ui.background.tile.psd", Material = "assets/icons/greyout.mat", ImageType = UnityEngine.UI.Image.Type.Tiled }));

            if (files.Count == 0)
            {
                container.Add(RecElement(backdrop, backdrop + ".empty", backdrop + ".empty",
                    RecRect("0 1", "1 1", "9 -37", "-9 -7"),
                    new CuiTextComponent { Text = GetLangText(admin.UserIDString, "rec_ui_empty"), FontSize = 9, Align = TextAnchor.MiddleCenter, Color = "0.5 0.46 0.4 1" }));
            }
            else
            {
                for (int i = 0; i < files.Count; i++) AddPhraseRow(session, backdrop, files[i], i, admin.UserIDString);
            }

            CuiHelper.AddUi(admin, container);
        }

        private void AddPhraseRow(RecUiSession session, string parent, string name, int idx, string userId)
        {
            float yTop = -idx * (RecRowH + RecRowPad);
            float yBot = yTop - RecRowH;
            string rowName = $"{parent}.r{idx}";
            bool selected = session.SelectedFile == name;

            int samples = 0;
            float dur = 0f;
            if (TryLoadSoundFile(session.OwnerPlugin, name, out var sv))
            {
                samples = sv.Sounds?.Count ?? 0;
                dur = sv.timePlay;
            }

            container.Add(RecElement(parent, rowName, rowName,
                RecRect("0 1", "1 1", $"3 {yBot}", $"-3 {yTop}"),
                new CuiButtonComponent
                {
                    Color = selected ? "0.79 0.39 0.18 1" : (idx % 2 == 0 ? "0.18 0.16 0.12 1" : "0.12 0.105 0.08 1"),
                    HighlightedColor = "0.85 0.42 0.20 0.40", PressedColor = "0.85 0.42 0.20 0.50", FadeDuration = 0.08f,
                    Command = $"recui_select {name}",
                    Sprite = "assets/content/ui/ui.background.tile.psd", Material = "assets/icons/greyout.mat", ImageType = UnityEngine.UI.Image.Type.Tiled
                }));

            string play = rowName + ".play";
            container.Add(RecElement(rowName, play, play,
                RecRect("0 0.5", "0 0.5", "7 -12", "29 12"),
                new CuiButtonComponent { Color = "0.06 0.05 0.04 1", HighlightedColor = "0.79 0.39 0.18 1", Command = $"recui_playfile {name}", Sprite = "assets/content/ui/ui.background.tile.psd", Material = "assets/icons/greyout.mat", ImageType = UnityEngine.UI.Image.Type.Tiled }));
            container.Add(RecElement(play, play + ".text", play + ".text",
                RecRect("0 0", "1 1"),
                new CuiTextComponent { Text = ">", FontSize = 12, Align = TextAnchor.MiddleCenter, Color = "0.85 0.55 0.3 1" }));

            string sampLabel = GetLangText(userId, "rec_ui_samples", samples);
            container.Add(RecElement(rowName, rowName + ".text", rowName + ".text",
                RecRect("0 0", "1 1", "36 0", "-7 0"),
                new CuiTextComponent { Text = $"{RecEscape(name)}   <color=#8a8072>· {sampLabel} · {FormatTime(dur)}</color>", FontSize = 10, Align = TextAnchor.MiddleLeft, Color = "0.93 0.9 0.85 1" }));
        }

        private void DrawIndicator(BasePlayer admin, RecUiSession session)
        {
            recordedPlayers.TryGetValue(admin, out var sv);
