            float t = sv?.timePlay ?? 0f;

            string ringColor = recording ? "0.85 0.28 0.23 0.14" : "0.16 0.14 0.11 0.7";
            string dotColor = recording
                ? (session.PulseBright ? "0.9 0.34 0.28 1" : "0.9 0.34 0.28 0.38")
                : "0.42 0.39 0.33 1";
            string stateText = recording ? GetLangText(admin.UserIDString, "rec_ui_recording") : GetLangText(admin.UserIDString, "rec_ui_idle");
            string stateColor = recording ? "0.86 0.42 0.35 1" : "0.61 0.57 0.51 1";
            string ringName = sub_indicator + ".ring";

            container.Clear();
            container.Add(RecElement(layer_right, sub_indicator, sub_indicator,
                RecRect("0 1", "1 1", "15 -89", "-15 -36")));
            container.Add(RecElement(sub_indicator, ringName, ringName,
                RecRect("0 0.5", "0 0.5", "0 -22", "44 22"),
                new CuiImageComponent { Color = ringColor }));
            container.Add(RecElement(ringName, ringName + ".dot", ringName + ".dot",
                RecRect("0.5 0.5", "0.5 0.5", "-7 -7", "7 7"),
                new CuiImageComponent { Color = dotColor }));
            container.Add(RecElement(sub_indicator, sub_indicator + ".state", sub_indicator + ".state",
                RecRect("0 0.5", "1 1", "53 0", "0 -1"),
                new CuiTextComponent { Text = stateText, FontSize = 10, Align = TextAnchor.LowerLeft, Color = stateColor }));
            container.Add(RecElement(sub_indicator, sub_indicator + ".time", sub_indicator + ".time",
                RecRect("0 0", "1 0.5", "53 1", "0 1"),
                new CuiTextComponent { Text = FormatTime(t), FontSize = 17, Align = TextAnchor.UpperLeft, Color = recording ? "0.95 0.92 0.86 1" : "0.55 0.5 0.42 1" }));
            CuiHelper.AddUi(admin, container);
