        #region GUI: Commands
        [Command("recui_toggle")]
        private void CmdRecUiToggle(IPlayer pl, string command, string[] args)
        {
            if (!TryGetRecSession(pl, out var player, out var session)) return;
            if (!recordedPlayers.TryGetValue(player, out var sv))
            {
                sv = new SoundVoice();
                recordedPlayers[player] = sv;
            }
            if (!sv.IsRecord)
            {
                session.PlayingVoice?.StopPlayback();
                ClearSelection(player, session);
                sv.Sounds.Clear();
                sv.timePlay = 0f;
                sv.IsRecord = true;
                StartPulse(player, session);
            }
            else
            {
                sv.IsRecord = false;
                StopPulse(session);
            }
            DrawIndicator(player, session);
            DrawRecControls(player, session);
        }

        [Command("recui_replay")]
        private void CmdRecUiReplay(IPlayer pl, string command, string[] args)
        {
            if (!TryGetRecSession(pl, out var player, out var session)) return;
            if (!recordedPlayers.TryGetValue(player, out var sv)) { ChatMessage(player, "not_recorded_voices"); return; }
            if (sv.IsRecord)
            {
                sv.IsRecord = false;
                StopPulse(session);
                DrawIndicator(player, session);
                DrawRecControls(player, session);
            }
            if (sv.HasSounds)
            {
                session.PlayingVoice?.StopPlayback();
                sv.TestPlaySounds(player);
                session.PlayingVoice = sv;
                ChatMessage(player, "play_current_voices");
            }
            else ChatMessage(player, "not_recorded_voices");
        }

        [Command("recui_save")]
        private void CmdRecUiSave(IPlayer pl, string command, string[] args)
        {
            if (!TryGetRecSession(pl, out var player, out var session)) return;
            string name = JoinArgs(args);
            string owner = session.OwnerPlugin;
            if (string.IsNullOrWhiteSpace(name)) { ChatMessage(player, "rec_ui_enter_name"); return; }
            if (ExistsFile(owner, name)) { ChatMessage(player, "exists_name_file", name); return; }
            if (!recordedPlayers.TryGetValue(player, out var sv) || !sv.HasSounds) { ChatMessage(player, "not_recorded_voices"); return; }
            if (sv.IsRecord) { sv.IsRecord = false; StopPulse(session); }
            SaveSoundFile(owner, name, sv);
            session.SelectedFile = name;
            ChatMessage(player, "save_name_voices", name);
            DrawIndicator(player, session);
            DrawRecControls(player, session);
            DrawList(player, session);
            DrawMeta(player, session);
        }

        [Command("recui_playfile")]
        private void CmdRecUiPlayFile(IPlayer pl, string command, string[] args)
        {
            if (!TryGetRecSession(pl, out var player, out var session)) return;
            string name = JoinArgs(args);
            if (string.IsNullOrEmpty(name)) return;
            string owner = session.OwnerPlugin;
            if (TryLoadSoundFile(owner, name, out var sv))
            {
                session.PlayingVoice?.StopPlayback();
                sv.TestPlaySounds(player);
                session.PlayingVoice = sv;
                ChatMessage(player, "play_name_voices", name);
            }
            else ChatMessage(player, "not_name_file", name);
            SelectPhrase(player, session, name);
        }

        [Command("recui_select")]
        private void CmdRecUiSelect(IPlayer pl, string command, string[] args)
        {
            if (!TryGetRecSession(pl, out var player, out var session)) return;
            string name = JoinArgs(args);
            if (string.IsNullOrEmpty(name)) return;
            SelectPhrase(player, session, name);
        }

        [Command("recui_rename")]
        private void CmdRecUiRename(IPlayer pl, string command, string[] args)
        {
            if (!TryGetRecSession(pl, out var player, out var session)) return;
            string oldName = session.SelectedFile;
            string newName = JoinArgs(args);
            string owner = session.OwnerPlugin;
            if (string.IsNullOrEmpty(oldName)) { ChatMessage(player, "rec_ui_select_first"); return; }
            if (string.IsNullOrWhiteSpace(newName)) { ChatMessage(player, "rec_ui_enter_name"); return; }
            if (oldName == newName) return;
            if (ExistsFile(owner, newName)) { ChatMessage(player, "exists_name_file", newName); return; }
            if (!TryLoadSoundFile(owner, oldName, out var sv)) { ChatMessage(player, "not_name_file", oldName); return; }
            SaveSoundFile(owner, newName, sv);
            DeleteFile(owner, oldName);
            session.SelectedFile = newName;
            ChatMessage(player, "rec_ui_renamed", oldName, newName);
            DrawList(player, session);
            DrawMeta(player, session);
        }

        [Command("recui_delete")]
        private void CmdRecUiDelete(IPlayer pl, string command, string[] args)
        {
            if (!TryGetRecSession(pl, out var player, out var session)) return;
            string name = session.SelectedFile;
            string owner = session.OwnerPlugin;
            if (string.IsNullOrEmpty(name)) { ChatMessage(player, "rec_ui_select_first"); return; }
            if (ExistsFile(owner, name))
            {
                DeleteFile(owner, name);
                ChatMessage(player, "delete_name_voices", name);
            }
            else ChatMessage(player, "not_name_file", name);
            session.SelectedFile = null;
            DrawList(player, session);
            DrawMeta(player, session);
        }

        [Command("recui_search")]
        private void CmdRecUiSearch(IPlayer pl, string command, string[] args)
        {
            if (!TryGetRecSession(pl, out var player, out var session)) return;
            session.Search = JoinArgs(args);
            DrawList(player, session);
        }
        #endregion

        [Command("npcslog")]
        private void CmdNpcsLog(IPlayer iPlayer, string _, string[] args)
        {
            if (!IsAdmin(iPlayer.Id)) { iPlayer.Reply(RU ? "Только для админов." : "Admins only."); return; }
            if (args.Length == 0 || args[0].Equals("clear", StringComparison.OrdinalIgnoreCase))
            {
                Debug.SetFilter(null);
                iPlayer.Reply(RU ? "Фильтр логов снят - идут все." : "Log filter cleared - showing all logs.");
                return;
            }
            string filter = string.Join(" ", args);
            Debug.SetFilter(filter);
            iPlayer.Reply(RU ? $"Фильтр логов: '{filter}' - показываются только строки с этой подстрокой (Log/LogTest; Error/Warning идут всегда)." : $"Log filter: '{filter}' - showing only lines containing this substring (Log/LogTest; Error/Warning always shown).");
        }

        #endregion
    }
    #endregion

    #region Diagnostics report
    public partial class NPCsController
    {
        #region Fields And Properties
        private static readonly string[] KnownFamilyPlugins =
        {
            "RoamingNPCs", "RNPCsManagerAddon", "CourierNPCs", "CNPCsDeliveryAddon", "PersonalNPC", "PNPCAddonHeli", "PNPCAddonCar",
            "PNPCAddonBoat", "PNPCAddonBuilder", "PNPCAddonHunter", "PNPCAddonRaid", "HeliPilots", "BoatDrivers", "BikeDrivers",
            "TrafficDrivers", "NavMeshEditor"
        };
        private const string ReportFolder = "NPCsController";
        private static readonly System.Globalization.CultureInfo ReportCulture = System.Globalization.CultureInfo.InvariantCulture;
        private const int FpsWindow = 300;
        private static readonly int[] _fpsSamples = new int[FpsWindow];
        private static int _fpsHead, _fpsCount;
        private Timer _fpsTimer;
        private const int FrameworkLogTail = 256 * 1024;
        private const int FrameworkLogMaxLines = 40;
        private const int ReportConfigLimit = 256 * 1024;
        #endregion

        #region Commands
        [Command("npcsreport")]
        private void CmdNpcsReport(IPlayer iPlayer, string _, string[] args)
        {
            if (!iPlayer.IsServer && !IsAdmin(iPlayer.Id)) { iPlayer.Reply(RU ? "Только для админов." : "Admins only."); return; }
            bool full = args.Length > 0 && args[0] == "full";
            var summary = new ReportSummary();
            string path;
            try
            {
                path = WriteDiagnosticsReport(iPlayer, full, summary);
            }
            catch (Exception ex)
            {
                Debug.LogError("npcsreport failed: {0}", ex);
                iPlayer.Reply(RU ? $"Отчёт не записан: {ex.Message}" : $"Report not written: {ex.Message}");
                return;
            }
            iPlayer.Reply(RU
                ? $"Отчёт записан: {path}\nОшибок {summary.Errors}, предупреждений {summary.Warnings}, ботов {summary.Bots}, событий транспорта {summary.Events}{(full ? "; в отчёте конфиги - проверьте их перед отправкой" : "")}"
                : $"Report written: {path}\nErrors {summary.Errors}, warnings {summary.Warnings}, bots {summary.Bots}, vehicle events {summary.Events}{(full ? "; configs are included - check them before sharing" : "")}");
        }
        #endregion

        #region Report
        private sealed class ReportSummary
        {
            public int Errors, Warnings, Bots, Events;
        }

        private sealed class ReportBot
        {
            public BaseCustomNpc Npc;
            public string Owner;
            public string State;
            public string Battle;
            public bool Swimming, Mounted, Wounded, OnNavmesh;
        }

        private string WriteDiagnosticsReport(IPlayer requester, bool full, ReportSummary summary)
        {
            DateTime utc = DateTime.UtcNow;
            float now = UnityEngine.Time.realtimeSinceStartup;
            var sb = new System.Text.StringBuilder(256 * 1024);
            BasePlayer admin = requester?.Object as BasePlayer;
            List<ReportBot> bots = CollectReportBots();
            summary.Bots = bots.Count;

            ReportLine(sb, "NPCs Controller diagnostics report");
            ReportLine(sb, "Generated: {0:yyyy-MM-dd HH:mm:ss} UTC (server local {1:yyyy-MM-dd HH:mm:ss})", utc, utc.ToLocalTime());
            ReportLine(sb, "Requested by: {0}{1}", requester == null || requester.IsServer ? "server console" : requester.Name + " (" + requester.Id + ")",
                full ? ", mode full (configs included)" : "");
            ReportLine(sb, "Times below are UTC. Counters 'N/M' mean 'since controller load / last hour'.");

            RunReportSection(sb, "1. Server", () => AppendServerSection(sb, utc, now));
            RunReportSection(sb, "2. Plugins", () => AppendPluginsSection(sb, bots));
            RunReportSection(sb, "3. Errors and warnings", () => AppendErrorsSection(sb, summary));
            RunReportSection(sb, "4. Bots", () => AppendBotsSection(sb, bots, now));
            RunReportSection(sb, "5. Navigation", () => AppendNavigationSection(sb));
            RunReportSection(sb, "6. Vehicle events", () => summary.Events = AppendEventsSection(sb, utc, now));
            RunReportSection(sb, "7. Bot cards", () => AppendBotCards(sb, bots, admin, utc, now));
            RunReportSection(sb, "8. Black box: global timeline", () => BlackBox.AppendGlobal(sb, utc, now));
            if (full) RunReportSection(sb, "9. Configs of family plugins", () => AppendConfigsSection(sb));

            string folder = System.IO.Path.Combine(Interface.Oxide.LogDirectory, ReportFolder);
            System.IO.Directory.CreateDirectory(folder);
            string path = System.IO.Path.Combine(folder, "report-" + utc.ToString("yyyy-MM-dd-HH-mm-ss", ReportCulture) + ".txt");
            System.IO.File.WriteAllText(path, sb.ToString());
            return path;
        }

        private static void RunReportSection(System.Text.StringBuilder sb, string title, Action section)
        {
            sb.Append('\n').Append("=== ").Append(title).Append(" ===\n");
            try
            {
                section();
            }
            catch (Exception ex)
            {
                ReportLine(sb, "[section failed: {0}]", ex);
            }
        }

        private static void ReportLine(System.Text.StringBuilder sb, string format, params object[] args) => sb.AppendFormat(ReportCulture, format, args).Append('\n');
        private static void ReportLine(System.Text.StringBuilder sb, string text) => sb.Append(text).Append('\n');
        private static string ReportPos(Vector3 p) => string.Format(ReportCulture, "({0:0.0}, {1:0.0}, {2:0.0})", p.x, p.y, p.z);
        private static string ReportDuration(float seconds)
        {
            TimeSpan span = TimeSpan.FromSeconds(Mathf.Max(0f, seconds));
            return span.Days > 0
                ? string.Format(ReportCulture, "{0}d {1:00}:{2:00}:{3:00}", span.Days, span.Hours, span.Minutes, span.Seconds)
                : string.Format(ReportCulture, "{0:00}:{1:00}:{2:00}", span.Hours, span.Minutes, span.Seconds);
        }
        private static void ReportIndented(System.Text.StringBuilder sb, string indent, string text)
        {
            if (string.IsNullOrEmpty(text)) return;
            foreach (string line in text.Split('\n'))
            {
                string trimmed = line.TrimEnd('\r');
                if (trimmed.Length > 0) sb.Append(indent).Append(trimmed).Append('\n');
            }
        }
        private static string ReportCounts(Dictionary<string, int> counts)
        {
            if (counts.Count == 0) return "-";
            var keys = new List<string>(counts.Keys);
            keys.Sort((a, b) => counts[b] != counts[a] ? counts[b].CompareTo(counts[a]) : string.CompareOrdinal(a, b));
            var sb = new System.Text.StringBuilder();
            for (int i = 0; i < keys.Count; i++)
            {
                if (i > 0) sb.Append(", ");
                sb.Append(keys[i]).Append(' ').Append(counts[keys[i]].ToString(ReportCulture));
            }
            return sb.ToString();
        }
        private static void CountKey(Dictionary<string, int> counts, string key)
        {
            counts.TryGetValue(key, out int count);
            counts[key] = count + 1;
        }
        private static Type FindLoadedType(string fullName)
        {
            foreach (Assembly assembly in AppDomain.CurrentDomain.GetAssemblies())
            {
                try
                {
                    Type type = assembly.GetType(fullName, false);
                    if (type != null) return type;
                }
                catch (Exception)
                {
                }
            }
            return null;
        }
        private static object ReadStaticMember(Type type, string name)
        {
            if (type == null) return null;
            const BindingFlags flags = BindingFlags.Public | BindingFlags.Static;
            PropertyInfo property = type.GetProperty(name, flags);
            if (property != null) return property.GetValue(null);
            FieldInfo field = type.GetField(name, flags);
            return field?.GetValue(null);
        }
        private static object ReadMember(object target, string name)
        {
            if (target == null) return null;
            PropertyInfo property = target.GetType().GetProperty(name, BindingFlags.Public | BindingFlags.Instance);
            return property?.GetValue(target);
        }

        private static List<ReportBot> CollectReportBots()
        {
            var bots = new List<ReportBot>();
            foreach (BaseNetworkable net in BaseNetworkable.serverEntities)
            {
                if (net is not BaseCustomNpc npc || npc.IsDestroyed) continue;
                try
                {
                    var bot = new ReportBot { Npc = npc, Owner = BlackBox.OwnerOf(npc) };
                    FSM.IStatePlayerNpc state = npc.brain?.StateMachine?.GetCurrentState();
                    bot.State = state?.Name ?? "-";
                    bot.Battle = state is BattleFsmState battle ? battle.CombatStateName : null;
                    bot.Swimming = npc.IsSwimming();
                    bot.Mounted = npc.isMounted;
                    bot.Wounded = npc.IfIncapacitated();
                    bot.OnNavmesh = npc.navigator != null && npc.navigator.GetNearestNavmeshPosition(npc.transform.position, out _, 1f);
                    bots.Add(bot);
                }
                catch (Exception)
                {
                }
            }
            bots.Sort((a, b) =>
            {
                int byOwner = string.CompareOrdinal(a.Owner, b.Owner);
                return byOwner != 0 ? byOwner : string.CompareOrdinal(a.Npc.displayName, b.Npc.displayName);
            });
            return bots;
        }

        #region 1. Server
        private static void AppendServerSection(System.Text.StringBuilder sb, DateTime utc, float now)
        {
            ReportLine(sb, "Framework: {0}", DescribeFramework());
            ReportLine(sb, "Rust: {0}", DescribeRustBuild());
            ReportLine(sb, "Map: level '{0}', size {1}, seed {2}, procedural {3}, name '{4}', url '{5}'", ConVar.Server.level, World.Size, World.Seed,
                World.Procedural ? "yes" : "no", World.Name ?? "", World.Url ?? "");
            ReportLine(sb, "Players: online {0}, sleeping {1}, max {2}", BasePlayer.activePlayerList.Count, BasePlayer.sleepingPlayerList.Count,
                ConVar.Server.maxplayers);
            int min = int.MaxValue, sum = 0;
            for (int i = 0; i < _fpsCount; i++)
            {
                int fps = _fpsSamples[i];
                if (fps < min) min = fps;
                sum += fps;
            }
            ReportLine(sb, "FPS: now {0}, last {1} s: min {2}, avg {3:0.0}", Performance.current.frameRate, _fpsCount, _fpsCount > 0 ? min : 0,
                _fpsCount > 0 ? (float)sum / _fpsCount : 0f);
            ReportLine(sb, "Memory: managed heap {0} MB, process {1} MB", System.GC.GetTotalMemory(false) / (1024 * 1024), Performance.current.memoryUsageSystem);
            ReportLine(sb, "Uptime: {0}", ReportDuration(now));
            ReportLine(sb, "Network entities: {0}", BaseNetworkable.serverEntities.Count);
            ReportLine(sb, "Report time: {0:yyyy-MM-dd HH:mm:ss} UTC", utc);
        }

        private static string DescribeFramework()
        {
            string oxide = OxideMod.Version.ToString();
            Type carbon = FindLoadedType("Carbon.Community");
            if (carbon == null) return "Oxide " + oxide;
            string version = null;
            try
            {
                version = ReadStaticMember(FindLoadedType("Carbon.Components.Analytics"), "Version") as string;
            }
            catch (Exception)
            {
            }
            if (string.IsNullOrEmpty(version))
            {
                var info = carbon.Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>();
                version = info != null ? info.InformationalVersion : carbon.Assembly.GetName().Version.ToString();
            }
            return "Carbon " + version + " (Oxide API " + oxide + ")";
        }

        private static string DescribeRustBuild()
        {
            string build = "?", changeset = "?", branch = "?", protocol = "?";
            try
            {
                object current = ReadStaticMember(FindLoadedType("Facepunch.BuildInfo"), "Current");
                object desc = ReadMember(current, "Build");
                object scm = ReadMember(current, "Scm");
                build = ReadMember(desc, "Number") as string ?? build;
                changeset = ReadMember(scm, "ChangeId") as string ?? changeset;
                branch = ReadMember(scm, "Branch") as string ?? branch;
                protocol = ReadStaticMember(FindLoadedType("Rust.Protocol"), "printable") as string ?? protocol;
            }
            catch (Exception)
            {
            }
            return string.Format(ReportCulture, "build {0}, changeset {1}, branch {2}, protocol (network.save.report) {3}", build, changeset, branch, protocol);
        }
        #endregion

        #region 2. Plugins
        private void AppendPluginsSection(System.Text.StringBuilder sb, List<ReportBot> bots)
        {
            ReportLine(sb, "NPCs Controller {0} by {1}, file {2}", Version, Author, Filename);
            ReportLine(sb, "VersionGuard: {0}", DescribeVersionGuard());

            var botsByOwner = new Dictionary<string, int>();
            foreach (ReportBot bot in bots) CountKey(botsByOwner, bot.Owner);
            HashSet<string> owners = FamilyOwnerNames(bots);

            var family = new List<Plugin>();
            var others = new List<Plugin>();
            var loaded = new HashSet<string>();
            int core = 0;
            foreach (Plugin plugin in plugins.GetAll())
            {
                if (plugin == null) continue;
                loaded.Add(plugin.Name);
                if (plugin.IsCorePlugin) { core++; continue; }
                if (plugin == this) continue;
                if (IsFamilyPlugin(plugin, owners)) family.Add(plugin);
                else others.Add(plugin);
            }
            family.Sort((a, b) => string.CompareOrdinal(a.Name, b.Name));
            others.Sort((a, b) => string.CompareOrdinal(a.Name, b.Name));

            ReportLine(sb, "Family plugins loaded ({0}):", family.Count);
            foreach (Plugin plugin in family)
            {
                botsByOwner.TryGetValue(plugin.Name, out int count);
                ReportLine(sb, "  [family] {0} {1} by {2}{3}", plugin.Name, plugin.Version, plugin.Author, count > 0 ? string.Format(ReportCulture, ", bots {0}", count) : "");
            }

            ReportLine(sb, "Known family plugins:");
            string pluginDir = Interface.Oxide.PluginDirectory;
            foreach (string name in KnownFamilyPlugins)
            {
                string file = System.IO.Path.Combine(pluginDir, name + ".cs");
                bool onDisk = System.IO.File.Exists(file);
                int mentions = LogCapture.CountMentions(name);
                string mentioned = mentions > 0 ? string.Format(ReportCulture, ", captured error/warning lines mention it: {0} (section 3)", mentions) : "";
                if (loaded.Contains(name))
                {
                    Plugin plugin = plugins.Find(name);
                    ReportLine(sb, "  {0}: loaded {1}{2}", name, plugin?.Version.ToString() ?? "?", mentioned);
                }
                else if (onDisk)
                {
                    var info = new System.IO.FileInfo(file);
                    ReportLine(sb, "  {0}: NOT LOADED, file present ({1} KB, modified {2:yyyy-MM-dd HH:mm:ss} UTC){3}", name, info.Length / 1024,
                        info.LastWriteTimeUtc, mentioned);
                }
                else ReportLine(sb, "  {0}: not installed{1}", name, mentioned);
            }

            List<string> stale = FindUnloadedControllerPlugins(pluginDir, loaded);
            ReportLine(sb, "Other plugin files that mention NPCsController but are not loaded ({0}){1}", stale.Count, stale.Count > 0 ? ":" : "");
            foreach (string line in stale) ReportLine(sb, "  {0}", line);

            ReportLine(sb, "Other loaded plugins ({0}, core plugins {1}):", others.Count, core);
            foreach (Plugin plugin in others) ReportLine(sb, "  {0} {1} by {2}", plugin.Name, plugin.Version, plugin.Author);
        }

        private static string ReadFileHead(string path)
        {
            var buffer = new char[16 * 1024];
            using (var reader = new System.IO.StreamReader(path)) return new string(buffer, 0, reader.ReadBlock(buffer, 0, buffer.Length));
        }
        private string DescribeVersionGuard()
        {
            string folder = System.IO.Path.Combine(Interface.Oxide.DataDirectory, VersionGuardFolder);
            string saved = System.IO.Path.Combine(folder, Name + ".cs");
            string marker = System.IO.Path.Combine(folder, "restore.txt");
            string text;
            if (!System.IO.File.Exists(saved)) text = "no saved copy in data/" + VersionGuardFolder;
            else if (!TryReadInfoVersion(ReadFileHead(saved), out VersionNumber savedVersion)) text = "saved copy has no readable version";
            else if (savedVersion > Version) text = string.Format(ReportCulture, "saved copy {0} is NEWER than the loaded {1} - a restore is pending or was refused", savedVersion, Version);
            else if (savedVersion < Version) text = string.Format(ReportCulture, "saved copy {0} is older than the loaded {1}", savedVersion, Version);
            else text = string.Format(ReportCulture, "saved copy {0} - same as loaded", savedVersion);
            if (System.IO.File.Exists(marker))
                text += string.Format(ReportCulture, "; restore marker '{0}' written {1:yyyy-MM-dd HH:mm:ss} UTC", System.IO.File.ReadAllText(marker).Trim(),
                    System.IO.File.GetLastWriteTimeUtc(marker));
            if (_superseded) text += "; this load stands down for a newer version";
            return text;
        }

        private static HashSet<string> FamilyOwnerNames(List<ReportBot> bots)
        {
            var owners = new HashSet<string>();
            foreach (ReportBot bot in bots) owners.Add(bot.Owner);
            foreach (CoreHost host in VehicleCore.AllHosts)
                if (host?.Plugin != null) owners.Add(host.Plugin.Name);
            BlackBox.CollectOwners(owners);
            owners.Remove(nameof(NPCsController));
            return owners;
        }

        private static bool IsFamilyPlugin(Plugin plugin, HashSet<string> owners)
        {
            if (Array.IndexOf(KnownFamilyPlugins, plugin.Name) >= 0 || owners.Contains(plugin.Name)) return true;
            try
            {
                Type type = plugin.GetType();
                Assembly own = typeof(NPCsController).Assembly;
                if (type.Assembly != own)
                {
                    string ownName = own.GetName().Name;
                    foreach (AssemblyName reference in type.Assembly.GetReferencedAssemblies())
                        if (reference.Name == ownName) return true;
                }
                return UsesControllerTypes(type, 0);
            }
            catch (Exception)
            {
                return false;
            }
        }
        private static bool UsesControllerTypes(Type type, int depth)
        {
            for (Type current = type.BaseType; current != null; current = current.BaseType)
                if (IsControllerType(current)) return true;
            foreach (Type contract in type.GetInterfaces())
                if (IsControllerType(contract)) return true;
            if (depth >= 4) return false;
            foreach (Type nested in type.GetNestedTypes(BindingFlags.Public | BindingFlags.NonPublic))
                if (UsesControllerTypes(nested, depth + 1)) return true;
            return false;
        }
        private static bool IsControllerType(Type type)
        {
            if (type.IsGenericType) type = type.GetGenericTypeDefinition();
            for (Type current = type; current != null; current = current.DeclaringType)
                if (current == typeof(NPCsController)) return true;
            return false;
        }

        private static List<string> FindUnloadedControllerPlugins(string pluginDir, HashSet<string> loaded)
        {
            var result = new List<string>();
            if (string.IsNullOrEmpty(pluginDir) || !System.IO.Directory.Exists(pluginDir)) return result;
            foreach (string file in System.IO.Directory.GetFiles(pluginDir, "*.cs"))
            {
                string name = System.IO.Path.GetFileNameWithoutExtension(file);
                if (loaded.Contains(name) || Array.IndexOf(KnownFamilyPlugins, name) >= 0) continue;
                try
                {
                    if (!ReadFileHead(file).Contains(nameof(NPCsController))) continue;
                    var info = new System.IO.FileInfo(file);
                    result.Add(string.Format(ReportCulture, "{0}.cs ({1} KB, modified {2:yyyy-MM-dd HH:mm:ss} UTC)", name, info.Length / 1024, info.LastWriteTimeUtc));
                }
                catch (Exception ex)
                {
                    result.Add(name + ".cs (cannot read: " + ex.Message + ")");
                }
            }
            return result;
        }
        #endregion

        #region 3. Errors
        private static void AppendErrorsSection(System.Text.StringBuilder sb, ReportSummary summary)
        {
            LogCapture.Append(sb, out summary.Errors, out summary.Warnings);
            AppendFrameworkLogScan(sb);
        }

        private static void AppendFrameworkLogScan(System.Text.StringBuilder sb)
        {
            string dir = Interface.Oxide.LogDirectory;
            if (string.IsNullOrEmpty(dir) || !System.IO.Directory.Exists(dir))
            {
                ReportLine(sb, "Framework log folder not found: {0}", dir ?? "-");
                return;
            }
            var files = new List<System.IO.FileInfo>();
            foreach (string file in System.IO.Directory.GetFiles(dir))
            {
                var info = new System.IO.FileInfo(file);
                string extension = info.Extension.ToLowerInvariant();
                if (extension == ".txt" || extension == ".log") files.Add(info);
            }
            files.Sort((a, b) => b.LastWriteTimeUtc.CompareTo(a.LastWriteTimeUtc));
            string[] names = LogCapture.Names;
            for (int i = 0; i < files.Count && i < 2; i++)
            {
                System.IO.FileInfo info = files[i];
                var found = new List<string>();
                try
                {
                    using (var stream = new System.IO.FileStream(info.FullName, System.IO.FileMode.Open, System.IO.FileAccess.Read,
                               System.IO.FileShare.ReadWrite | System.IO.FileShare.Delete))
                    {
                        if (stream.Length > FrameworkLogTail) stream.Seek(-FrameworkLogTail, System.IO.SeekOrigin.End);
                        using (var reader = new System.IO.StreamReader(stream))
                        {
                            string line;
                            while ((line = reader.ReadLine()) != null)
                            {
                                if (!LogCapture.Mentions(line, names) || !LooksLikeFailure(line)) continue;
                                found.Add(line.Length > 400 ? line.Substring(0, 400) + " ..." : line);
                                if (found.Count > FrameworkLogMaxLines) found.RemoveAt(0);
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    ReportLine(sb, "Framework log {0}: cannot read ({1})", info.Name, ex.Message);
                    continue;
                }
                ReportLine(sb, "Framework log {0} (modified {1:yyyy-MM-dd HH:mm:ss} UTC, last {2} KB scanned): {3} lines mention family plugins with an error{4}",
                    info.Name, info.LastWriteTimeUtc, Math.Min(info.Length, FrameworkLogTail) / 1024, found.Count, found.Count > 0 ? " (newest last):" : "");
                foreach (string line in found) ReportLine(sb, "  {0}", line);
            }
        }
        private static bool LooksLikeFailure(string line)
            => line.IndexOf("error", StringComparison.OrdinalIgnoreCase) >= 0 || line.IndexOf("fail", StringComparison.OrdinalIgnoreCase) >= 0
               || line.IndexOf("exception", StringComparison.OrdinalIgnoreCase) >= 0 || line.IndexOf("missing", StringComparison.OrdinalIgnoreCase) >= 0
               || line.IndexOf("unable", StringComparison.OrdinalIgnoreCase) >= 0 || line.IndexOf("could not", StringComparison.OrdinalIgnoreCase) >= 0;
        #endregion

        #region 4. Bots
        private static void AppendBotsSection(System.Text.StringBuilder sb, List<ReportBot> bots, float now)
        {
            ReportLine(sb, "Controller bots alive: {0}", bots.Count);
            var owners = new List<string>();
            var byOwner = new Dictionary<string, List<ReportBot>>();
            foreach (ReportBot bot in bots)
            {
                if (!byOwner.TryGetValue(bot.Owner, out List<ReportBot> list))
                {
                    byOwner[bot.Owner] = list = new List<ReportBot>();
                    owners.Add(bot.Owner);
                }
                list.Add(bot);
            }
            var counted = new HashSet<string>();
            BlackBox.CollectOwners(counted);
            foreach (string owner in counted)
                if (!byOwner.ContainsKey(owner) && BlackBox.HasBotCounters(owner)) owners.Add(owner);
            owners.Sort(string.CompareOrdinal);

            foreach (string owner in owners)
            {
                byOwner.TryGetValue(owner, out List<ReportBot> list);
                list ??= new List<ReportBot>();
                var states = new Dictionary<string, int>();
                var battle = new Dictionary<string, int>();
                int swimming = 0, mounted = 0, wounded = 0, offMesh = 0;
                foreach (ReportBot bot in list)
                {
                    CountKey(states, bot.State);
                    if (bot.Battle != null) CountKey(battle, bot.Battle);
                    if (bot.Swimming) swimming++;
                    if (bot.Mounted) mounted++;
                    if (bot.Wounded) wounded++;
                    if (!bot.Mounted && !bot.Swimming && !bot.OnNavmesh) offMesh++;
                }
                ReportLine(sb, "--- {0}: alive {1}", owner, list.Count);
                if (list.Count > 0)
                {
                    ReportLine(sb, "  top states: {0}", ReportCounts(states));
                    ReportLine(sb, "  battle substates: {0}", ReportCounts(battle));
                    ReportLine(sb, "  swimming {0}, mounted {1}, wounded {2}, on foot without game navmesh within 1 m {3}", swimming, mounted, wounded, offMesh);
                }
                BlackBox.AppendBotCounters(sb, owner, now);
            }
        }
        #endregion

        #region 5. Navigation
        private static void AppendNavigationSection(System.Text.StringBuilder sb)
        {
            ReportLine(sb, "Game navmesh: Gen2, ready {0}", IsGameNavmeshReady() ? "yes" : "NO");
            ReportLine(sb, "Monuments known: {0}, roads known: {1}", HelperMonuments.Instance?.allMonuments.Count ?? 0, TerrainMeta.Path?.Roads?.Count ?? 0);
            HelperSavedNavMesh store = HelperSavedNavMesh.Instance;
            if (store == null) ReportLine(sb, "Saved monument/prefab navmeshes: store not ready");
            else
            {
                ReportLine(sb, "Saved monument/prefab navmeshes: used in navigation {0}, reading from disk {1}", HelperSavedNavMesh.UseInNavigator ? "yes" : "no",
                    store.IsDiskLoading ? "yes" : "no");
                ReportIndented(sb, "  ", store.Describe());
            }
            HelperWaterNavMesh water = HelperWaterNavMesh.Existing;
            ReportLine(sb, "Water navmesh (swim rescue): enabled {0}, native mesh {1}, tiles cached {2}", HelperWaterNavMesh.Enabled ? "yes" : "no",
                water != null && water.IsReady ? "created" : "not created", water?.TileCount ?? 0);
            string subscribers = HelperBuildingNavMesh.DescribeSubscribers(out int subscriberCount);
            ReportLine(sb, "Building navmeshes: running {0}, watched buildings {1}, subscribers {2}{3}, manual mode {4}, built {5}",
                HelperBuildingNavMesh.IsRunning ? "yes" : "no", HelperBuildingNavMesh.WatchedCount, subscriberCount,
                subscriberCount > 0 ? " (" + subscribers + ")" : "", HelperBuildingNavMesh.ManualEnabled ? "on" : "off",
                HelperBuildingNavMesh.IsRunning ? HelperBuildingNavMesh.Instance.Count : 0);
            ReportLine(sb, "Navigator state of every bot: see its card in section 7.");
        }
        #endregion

        #region 6. Vehicle events
        private static int AppendEventsSection(System.Text.StringBuilder sb, DateTime utc, float now)
        {
            int active = 0;
            var hosts = new List<CoreHost>();
            foreach (CoreHost host in VehicleCore.AllHosts)
                if (host?.Plugin != null && !host.IsUnloading) hosts.Add(host);
            hosts.Sort((a, b) => string.CompareOrdinal(a.Plugin.Name, b.Plugin.Name));
            if (hosts.Count == 0) ReportLine(sb, "No driver plugin is running the vehicle events core.");
            foreach (CoreHost host in hosts)
            {
                ReportLine(sb, "--- {0} {1}", host.Plugin.Name, host.Plugin.Version);
                int managers = 0;
                foreach (MonoBehaviour behaviour in host.HostObjects)
                {
                    if (behaviour == null || behaviour is not IDiagnosticsReport report) continue;
                    managers++;
                    active += report.AppendDiagnostics(sb);
                }
                if (managers == 0) ReportLine(sb, "  no event manager");
            }
            BlackBox.AppendEvents(sb, utc, now);
            return active;
        }

        internal interface IDiagnosticsReport
        {
            int AppendDiagnostics(System.Text.StringBuilder sb);
        }
        #endregion

        #region 7. Bot cards
        private static void AppendBotCards(System.Text.StringBuilder sb, List<ReportBot> bots, BasePlayer admin, DateTime utc, float now)
        {
            ReportBot looked = FindLookedAtBot(admin, bots);
            if (admin != null)
                ReportLine(sb, "Bot the admin is looking at: {0}", looked != null
                    ? string.Format(ReportCulture, "{0} net {1} [{2}]", Debug.Id(looked.Npc), BlackBox.NetId(looked.Npc), looked.Owner)
                    : "none (no bot under the crosshair within 50 m)");
            if (bots.Count == 0)
            {
                ReportLine(sb, "No controller bots alive.");
                return;
            }
            if (looked != null)
            {
                ReportLine(sb, "--- Looked-at bot ---");
                AppendBotCard(sb, looked, utc, now);
            }
            string owner = null;
            for (int index = 0; index < bots.Count; index++)
            {
                ReportBot bot = bots[index];
                if (bot.Owner != owner)
                {
                    owner = bot.Owner;
                    int count = 0;
                    for (int i = index; i < bots.Count && bots[i].Owner == owner; i++) count++;
                    ReportLine(sb, "--- {0} ({1}) ---", owner, count);
                }
                if (bot != looked) AppendBotCard(sb, bot, utc, now);
                else ReportLine(sb, "* {0} net {1}: card above (looked-at bot)", Debug.Id(bot.Npc), BlackBox.NetId(bot.Npc));
            }
        }

        private static ReportBot FindLookedAtBot(BasePlayer admin, List<ReportBot> bots)
        {
            if (admin == null) return null;
            int mask = LayerMask.GetMask("Player (Server)", "Construction", "Deployed", "World", "Terrain", "Default", "Tree", "Vehicle Detailed", "Vehicle World");
            if (!Physics.Raycast(admin.eyes.HeadRay(), out RaycastHit hit, 50f, mask, QueryTriggerInteraction.Ignore) || hit.GetEntity() is not BaseCustomNpc seen)
                return null;
            foreach (ReportBot bot in bots)
                if (bot.Npc == seen) return bot;
            return null;
        }

        private static void AppendBotCard(System.Text.StringBuilder sb, ReportBot bot, DateTime utc, float now)
        {
            BaseCustomNpc npc = bot.Npc;
            try
            {
                Vector3 position = npc.transform.position;
                string monument = HelperMonuments.Instance != null && HelperMonuments.Instance.TryGetNearestMonument(position, out MonumentInfo near)
                    ? ", monument " + ReportMonumentName(near) : "";
                BlackBox.Trace trace = npc.DiagnosticsTrace;
                ReportLine(sb, "* {0} net {1} [{2}] type {3}, config name '{4}'{5}", Debug.Id(npc), BlackBox.NetId(npc), bot.Owner, npc.GetType().Name,
                    npc.ConfigNPC?.GetName() ?? "-", trace != null ? ", up " + ReportDuration(now - trace.SpawnedAt) : "");
                ReportLine(sb, "  pos {0} grid {1}{2} | HP {3:0}/{4:0} | state {5}{6} | enemy {7}", ReportPos(position), MapHelper.PositionToString(position),
                    monument, npc.Health(), npc.MaxHealth(), bot.State, bot.Battle != null ? " (" + bot.Battle + ")" : "", DescribeEnemy(npc));
                BaseMountable seat = npc.GetMounted();
                BaseVehicle vehicle = npc.GetMountedVehicle();
                Item active = npc.GetActiveItem();
                ReportLine(sb, "  mounted {0} | swimming {1} | wounded {2} | game navmesh within 1 m {3} | hostile {4} | safe zone {5} | item {6}",
                    seat != null ? seat.ShortPrefabName + (vehicle != null && vehicle != seat ? " on " + vehicle.ShortPrefabName : "") : "no",
                    bot.Swimming ? "yes" : "no", npc.IsWounded() ? "wounded" : npc.IsIncapacitated() ? "incapacitated" : "no", bot.OnNavmesh ? "yes" : "no",
                    npc.IsHostile() ? "yes" : "no", npc.InSafeZone() ? "yes" : "no", active?.info?.shortname ?? "-");
                if (npc.navigator is NavigatorNpc navigator) ReportIndented(sb, "  nav: ", navigator.DescribeNavState());
                else if (npc.navigator != null)
                    ReportLine(sb, "  nav: {0} moving {1} paused {2} stuck {3}", npc.navigator.GetType().Name, npc.navigator.Moving, npc.navigator.IsPaused,
                        npc.navigator.LastStuckReason);
                else ReportLine(sb, "  nav: none");
                if (trace != null && trace.LastStuckAt >= 0f)
                    ReportLine(sb, "  last stuck: {0} {1:0} s ago", trace.LastStuck, now - trace.LastStuckAt);
                if (trace != null) BlackBox.AppendTrace(sb, trace, utc, now);
                else ReportLine(sb, "  black box: empty");
            }
            catch (Exception ex)
            {
                ReportLine(sb, "  [card failed: {0}]", ex.Message);
            }
        }

        private static string DescribeEnemy(BaseCustomNpc npc)
        {
            if (npc.brain?.StateMachine?.GetCurrentState() is not FSM.AttackState attack || !attack.CurrentEnemy.IsValid()) return "-";
            BaseCombatEntity enemy = attack.CurrentEnemy.Enemy;
            return string.Format(ReportCulture, "{0} at {1:0} m", ReportEntityName(enemy), Vector3.Distance(enemy.transform.position, npc.transform.position));
        }
        internal static string ReportEntityName(BaseEntity entity)
        {
            if (entity == null) return "-";
            if (entity is BasePlayer player) return (player is BaseCustomNpc ? "bot " : player.IsNpc ? "npc " : "player ") + player.displayName + "#" + player.UserIDString;
            return entity.ShortPrefabName;
        }
        private static string ReportMonumentName(MonumentInfo monument)
        {
            string english = monument.displayPhrase?.english;
            return !string.IsNullOrEmpty(english) ? english : System.IO.Path.GetFileNameWithoutExtension(monument.name);
        }
        #endregion

        #region 9. Configs
        private void AppendConfigsSection(System.Text.StringBuilder sb)
        {
            ReportLine(sb, "Configs of the controller and known family plugins only.");
            var names = new List<string> { Name };
            var sorted = new List<string>(KnownFamilyPlugins);
            sorted.Sort(string.CompareOrdinal);
            names.AddRange(sorted);
            foreach (string name in names)
            {
                string file = System.IO.Path.Combine(Interface.Oxide.ConfigDirectory, name + ".json");
                if (!System.IO.File.Exists(file)) continue;
                string text = System.IO.File.ReadAllText(file);
                ReportLine(sb, "----- {0}.json ({1} KB) -----", name, text.Length / 1024);
                if (text.Length > ReportConfigLimit) text = text.Substring(0, ReportConfigLimit) + "\n[... truncated ...]";
                sb.Append(text).Append('\n');
            }
        }
        #endregion

        private void SampleFps()
        {
            _fpsSamples[_fpsHead] = Performance.current.frameRate;
            _fpsHead = (_fpsHead + 1) % FpsWindow;
            if (_fpsCount < FpsWindow) _fpsCount++;
        }
        #endregion

        #region Black box
        internal enum BlackBoxKind : byte
        {
            Spawn, State, Battle, SubState, Stuck, Escalation, Warp, SwimRescue, Escape, Death, Removed,
            EventStart, EventEnd, EventRemoved, EventFailed, VehicleTeleport, VehicleRetake, VehicleReplan
        }

        internal static class BlackBox
        {
            public const int BotCapacity = 30;
            public const int GlobalCapacity = 500;
            public const int EventCapacity = 50;
            private const int PoolLimit = 512;

            internal struct Entry
            {
                public float Time, First;
                public int Repeat;
                public BlackBoxKind Kind;
                public ulong Id;
                public int Code;
                public string Owner, Subject, A, B;
                public Vector3 Position;
                public float Value;
            }

            internal sealed class Ring
            {
                public readonly Entry[] Items;
                public int Head, Count;
                public Ring(int capacity) => Items = new Entry[capacity];
                public int IndexOf(int order) => (Head - Count + order + Items.Length) % Items.Length;
                public int Newest(int back) => (Head - 1 - back + Items.Length) % Items.Length;
                public void Add(Entry entry)
                {
                    Items[Head] = entry;
                    Head = (Head + 1) % Items.Length;
                    if (Count < Items.Length) Count++;
                }
                public void Clear()
                {
                    Array.Clear(Items, 0, Items.Length);
                    Head = Count = 0;
                }
            }

            internal sealed class Trace
            {
                public readonly Ring Events = new Ring(BotCapacity);
                public Stats Stats;
                public float SpawnedAt;
                public StuckReason LastStuck;
                public float LastStuckAt = -1f;
            }

            internal sealed class Counter
            {
                public int Total;
                private readonly int[] _count = new int[60];
                private readonly int[] _minute = new int[60];
                public void Add(float now)
                {
                    int minute = (int)(now / 60f);
                    int slot = minute % 60;
                    if (_minute[slot] != minute)
                    {
                        _minute[slot] = minute;
                        _count[slot] = 0;
                    }
                    _count[slot]++;
                    Total++;
                }
                public int LastHour(float now)
                {
                    int minute = (int)(now / 60f), sum = 0;
                    for (int i = 0; i < 60; i++)
                        if (minute - _minute[i] < 60) sum += _count[i];
                    return sum;
                }
            }

            internal sealed class Stats
            {
                public readonly string Owner;
                public readonly Counter[] ByKind = new Counter[KindCount];
                public readonly Counter[] StuckBy = new Counter[ReasonCount];
                public readonly Counter[] EscalationBy = new Counter[ReasonCount];
                public readonly Counter[] DeathsBy = new Counter[DamageCount];
                public Stats(string owner) => Owner = owner;
                public static void Count(Counter[] set, int index, float now)
                {
                    if (index < 0 || index >= set.Length) return;
                    (set[index] ??= new Counter()).Add(now);
                }
            }

            private static readonly int KindCount = Enum.GetValues(typeof(BlackBoxKind)).Length;
            private static readonly int ReasonCount = Enum.GetValues(typeof(StuckReason)).Length;
            private static readonly int DamageCount = Enum.GetValues(typeof(DamageType)).Length;
            private static readonly Ring _global = new Ring(GlobalCapacity);
            private static readonly Ring _events = new Ring(EventCapacity);
            private static readonly Dictionary<string, Stats> _stats = new();
            private static readonly Stack<Trace> _pool = new();
            private static readonly Dictionary<Type, string> _ownerByType = new();

            #region Запись
            internal static ulong NetId(BaseNetworkable entity) => entity != null && entity.net != null ? entity.net.ID.Value : 0UL;

            internal static string OwnerOf(BaseCustomNpc npc)
            {
                if (npc is CrewNpc crew)
                {
                    string host = crew.Host?.Plugin?.Name;
                    if (!string.IsNullOrEmpty(host)) return host;
                }
                Type type = npc.GetType();
                if (_ownerByType.TryGetValue(type, out string owner)) return owner;
                Type plugin = null;
                for (Type current = type; current != null; current = current.DeclaringType)
                    if (typeof(Plugin).IsAssignableFrom(current)) plugin = current;
                owner = plugin != null ? plugin.Name : type.Name;
                _ownerByType[type] = owner;
                return owner;
            }
            private static Stats StatsOf(string owner)
            {
                if (owner == null) return null;
                if (_stats.TryGetValue(owner, out Stats stats)) return stats;
                _stats[owner] = stats = new Stats(owner);
                LogCapture.AddName(owner);
                return stats;
            }
            private static Trace TraceOf(BaseCustomNpc npc)
            {
                if (npc == null || npc.DiagnosticsClosed) return null;
                Trace trace = npc.DiagnosticsTrace;
                if (trace != null) return trace;
                trace = _pool.Count > 0 ? _pool.Pop() : new Trace();
                trace.Stats = StatsOf(OwnerOf(npc));
                trace.SpawnedAt = UnityEngine.Time.realtimeSinceStartup;
                npc.DiagnosticsTrace = trace;
                return trace;
            }
            private static Entry Make(BlackBoxKind kind, BaseCustomNpc npc, string owner, string a, string b, int code, Vector3 position, float value)
            {
                float now = UnityEngine.Time.realtimeSinceStartup;
                return new Entry
                {
                    Time = now, First = now, Repeat = 1, Kind = kind, Id = NetId(npc), Code = code, Owner = owner, Subject = npc != null ? npc.displayName : null,
                    A = a, B = b, Position = position, Value = value
                };
            }
            private static bool Same(in Entry entry, BlackBoxKind kind, ulong id, int code, string a, string b)
                => entry.Kind == kind && entry.Id == id && entry.Code == code && string.Equals(entry.A, a) && string.Equals(entry.B, b);
            private static void Push(Ring ring, Entry entry, bool pingPong)
            {
                if (ring.Count > 0)
                {
                    Entry[] items = ring.Items;
                    int last = ring.Newest(0);
                    if (Same(items[last], entry.Kind, entry.Id, entry.Code, entry.A, entry.B))
                    {
                        items[last].Repeat++;
                        items[last].Time = entry.Time;
                        items[last].Position = entry.Position;
                        items[last].Value = entry.Value;
                        return;
                    }
                    if (pingPong && ring.Count > 1)
                    {
                        int previous = ring.Newest(1);
                        if (Same(items[previous], entry.Kind, entry.Id, entry.Code, entry.A, entry.B)
                            && Same(items[last], entry.Kind, entry.Id, entry.Code, entry.B, entry.A))
                        {
                            items[previous].Repeat++;
                            items[previous].Time = entry.Time;
                            return;
                        }
                    }
                }
                ring.Add(entry);
            }
            private static void PushFailure(Ring ring, Entry entry)
            {
                Entry[] items = ring.Items;
                for (int i = 0; i < ring.Count; i++)
                {
                    int index = ring.IndexOf(i);
                    if (items[index].Kind != entry.Kind || items[index].Code != entry.Code || !string.Equals(items[index].Owner, entry.Owner)
                        || !string.Equals(items[index].Subject, entry.Subject) || !string.Equals(items[index].A, entry.A)) continue;
                    items[index].Repeat++;
                    items[index].Time = entry.Time;
                    return;
                }
                ring.Add(entry);
            }

            internal static void NoteState(BaseCustomNpc npc, FSM fsm, FSM.IStatePlayerNpc from, FSM.IStatePlayerNpc to)
            {
                Trace trace = TraceOf(npc);
                if (trace == null) return;
                BlackBoxKind kind = ReferenceEquals(npc.brain?.StateMachine, fsm) ? BlackBoxKind.State : fsm is CombatFSM ? BlackBoxKind.Battle : BlackBoxKind.SubState;
                Push(trace.Events, Make(kind, npc, null, from?.Name, to?.Name, 0, npc.transform.position, 0f), true);
            }
            internal static void NoteStuck(BaseCustomNpc npc, StuckReason reason, bool escalation)
            {
                if (npc == null) return;
                Trace trace = TraceOf(npc);
                float now = UnityEngine.Time.realtimeSinceStartup;
                Entry entry = Make(escalation ? BlackBoxKind.Escalation : BlackBoxKind.Stuck, npc, trace?.Stats?.Owner, null, null, (int)reason,
                    npc.transform.position, 0f);
                if (trace != null)
                {
                    trace.LastStuck = reason;
                    trace.LastStuckAt = now;
                    Push(trace.Events, entry, false);
                    if (trace.Stats != null) Stats.Count(escalation ? trace.Stats.EscalationBy : trace.Stats.StuckBy, (int)reason, now);
                }
                if (escalation) Push(_global, entry, false);
            }
            internal static void NoteWarp(BaseCustomNpc npc, Vector3 from, Vector3 to, StuckReason reason)
                => NoteBot(npc, BlackBoxKind.Warp, null, (int)reason, to, Vector3.Distance(from, to));
            internal static void NoteRescue(BaseCustomNpc npc, BlackBoxKind kind, string how, Vector3 from, Vector3 to)
                => NoteBot(npc, kind, how, 0, to, Vector3.Distance(from, to));
            private static void NoteBot(BaseCustomNpc npc, BlackBoxKind kind, string a, int code, Vector3 position, float value)
            {
                if (npc == null) return;
                Trace trace = TraceOf(npc);
                Entry entry = Make(kind, npc, trace?.Stats?.Owner ?? OwnerOf(npc), a, null, code, position, value);
                if (trace != null)
                {
                    Push(trace.Events, entry, false);
                    if (trace.Stats != null) Stats.Count(trace.Stats.ByKind, (int)kind, entry.Time);
                }
                Push(_global, entry, false);
            }
            internal static void NoteSpawn(BaseCustomNpc npc)
            {
                Trace trace = TraceOf(npc);
                if (trace != null) Push(trace.Events, Make(BlackBoxKind.Spawn, npc, null, null, null, 0, npc.transform.position, 0f), false);
            }
            internal static void Rebind(BaseCustomNpc npc)
            {
                Trace trace = npc?.DiagnosticsTrace;
                if (trace != null) trace.Stats = StatsOf(OwnerOf(npc));
            }
            internal static void NoteDeath(BaseCustomNpc npc, HitInfo info)
            {
                if (npc == null) return;
                DamageType damage = info != null ? info.damageTypes.GetMajorityDamageType() : npc.lastDamage;
                if (info != null && info.damageTypes.Total() <= 0f) damage = npc.lastDamage;
                BaseEntity killer = info?.Initiator ?? npc.lastAttacker;
                string by = killer is BasePlayer player ? player.displayName : killer != null ? killer.ShortPrefabName : null;
                NoteBot(npc, BlackBoxKind.Death, by, (int)damage, npc.transform.position, 0f);
                Stats stats = npc.DiagnosticsTrace?.Stats;
                if (stats != null) Stats.Count(stats.DeathsBy, (int)damage, UnityEngine.Time.realtimeSinceStartup);
            }
            internal static void Release(BaseCustomNpc npc)
            {
                if (npc == null) return;
                npc.DiagnosticsClosed = true;
                Trace trace = npc.DiagnosticsTrace;
                npc.DiagnosticsTrace = null;
                if (trace == null) return;
                if (trace.Stats != null && npc.IsAlive()) Stats.Count(trace.Stats.ByKind, (int)BlackBoxKind.Removed, UnityEngine.Time.realtimeSinceStartup);
                trace.Events.Clear();
                trace.Stats = null;
                trace.LastStuck = StuckReason.None;
                trace.LastStuckAt = -1f;
                if (_pool.Count < PoolLimit) _pool.Push(trace);
            }
            internal static void NoteEvent(string owner, BlackBoxKind kind, string name, int number, string reason, BaseVehicle vehicle, float value)
            {
                Entry entry = Make(kind, null, owner, reason, vehicle != null ? vehicle.ShortPrefabName : null, number,
                    vehicle != null ? vehicle.transform.position : Vector3.zero, value);
                entry.Subject = name;
                entry.Id = NetId(vehicle);
                if (kind == BlackBoxKind.EventFailed) PushFailure(_events, entry);
                else
                {
                    Push(_global, entry, false);
                    if (kind == BlackBoxKind.EventStart || kind == BlackBoxKind.EventEnd || kind == BlackBoxKind.EventRemoved) Push(_events, entry, false);
                }
                Stats stats = StatsOf(owner);
                if (stats != null) Stats.Count(stats.ByKind, (int)kind, entry.Time);
            }
            internal static void Clear()
            {
                _global.Clear();
                _events.Clear();
                _stats.Clear();
                _pool.Clear();
                _ownerByType.Clear();
            }
            #endregion

            #region Отчёт
            internal static void CollectOwners(HashSet<string> owners)
            {
                foreach (string owner in _stats.Keys) owners.Add(owner);
            }
            internal static bool HasBotCounters(string owner)
            {
                if (!_stats.TryGetValue(owner, out Stats stats)) return false;
                foreach (Counter counter in stats.StuckBy) if (counter != null) return true;
                for (int kind = (int)BlackBoxKind.Warp; kind <= (int)BlackBoxKind.Removed; kind++)
                    if (stats.ByKind[kind] != null) return true;
                return false;
            }
            private static string CounterText(Counter counter, float now)
                => counter == null ? "0/0" : string.Format(ReportCulture, "{0}/{1}", counter.Total, counter.LastHour(now));
            private static string ReasonCounters(Counter[] set, float now)
            {
                var sb = new System.Text.StringBuilder();
                for (int i = 0; i < set.Length; i++)
                {
                    if (set[i] == null) continue;
                    if (sb.Length > 0) sb.Append(", ");
                    sb.Append(((StuckReason)i).ToString()).Append(' ').Append(CounterText(set[i], now));
                }
                return sb.Length > 0 ? sb.ToString() : "-";
            }
            internal static void AppendBotCounters(System.Text.StringBuilder sb, string owner, float now)
            {
                if (!_stats.TryGetValue(owner, out Stats stats))
                {
                    ReportLine(sb, "  counters: none recorded");
                    return;
                }
                ReportLine(sb, "  stuck knocks by reason: {0}", ReasonCounters(stats.StuckBy, now));
                ReportLine(sb, "  escalations to the state by reason: {0}", ReasonCounters(stats.EscalationBy, now));
                ReportLine(sb, "  warps {0}, swim rescues {1}, island escapes on foot {2}, removed alive {3}", CounterText(stats.ByKind[(int)BlackBoxKind.Warp], now),
                    CounterText(stats.ByKind[(int)BlackBoxKind.SwimRescue], now), CounterText(stats.ByKind[(int)BlackBoxKind.Escape], now),
                    CounterText(stats.ByKind[(int)BlackBoxKind.Removed], now));
                var deaths = new System.Text.StringBuilder();
                for (int i = 0; i < stats.DeathsBy.Length; i++)
                {
                    if (stats.DeathsBy[i] == null) continue;
                    if (deaths.Length > 0) deaths.Append(", ");
                    deaths.Append(((DamageType)i).ToString()).Append(' ').Append(CounterText(stats.DeathsBy[i], now));
                }
                ReportLine(sb, "  deaths {0}{1}", CounterText(stats.ByKind[(int)BlackBoxKind.Death], now), deaths.Length > 0 ? " (" + deaths + ")" : "");
            }
            internal static void AppendEvents(System.Text.StringBuilder sb, DateTime utc, float now)
            {
                ReportLine(sb, "Vehicle event counters (since load / last hour):");
                var owners = new List<string>();
                foreach (var pair in _stats)
                    for (int kind = (int)BlackBoxKind.EventStart; kind <= (int)BlackBoxKind.VehicleReplan; kind++)
                        if (pair.Value.ByKind[kind] != null) { owners.Add(pair.Key); break; }
                owners.Sort(string.CompareOrdinal);
                if (owners.Count == 0) ReportLine(sb, "  none");
                foreach (string owner in owners)
                {
                    Counter[] by = _stats[owner].ByKind;
                    ReportLine(sb, "  {0}: started {1}, ended {2}, removed {3}, start failures {4}, teleports {5}, pilot retakes {6}, route rebuilds {7}", owner,
                        CounterText(by[(int)BlackBoxKind.EventStart], now), CounterText(by[(int)BlackBoxKind.EventEnd], now),
                        CounterText(by[(int)BlackBoxKind.EventRemoved], now), CounterText(by[(int)BlackBoxKind.EventFailed], now),
                        CounterText(by[(int)BlackBoxKind.VehicleTeleport], now), CounterText(by[(int)BlackBoxKind.VehicleRetake], now),
                        CounterText(by[(int)BlackBoxKind.VehicleReplan], now));
                }
                ReportLine(sb, "Recent event starts and ends ({0} of up to {1}, newest last):", _events.Count, EventCapacity);
                AppendRing(sb, _events, "  ", utc, now, true);
            }
            internal static void AppendGlobal(System.Text.StringBuilder sb, DateTime utc, float now)
            {
                ReportLine(sb, "Escalations, warps, rescues, deaths and vehicle events of all bots ({0} of up to {1}, newest last). State changes are only in the bot cards.",
                    _global.Count, GlobalCapacity);
                AppendRing(sb, _global, "  ", utc, now, true);
            }
            internal static void AppendTrace(System.Text.StringBuilder sb, Trace trace, DateTime utc, float now)
            {
                ReportLine(sb, "  black box ({0} of up to {1}, newest last):", trace.Events.Count, BotCapacity);
                AppendRing(sb, trace.Events, "    ", utc, now, false);
            }
            private static void AppendRing(System.Text.StringBuilder sb, Ring ring, string indent, DateTime utc, float now, bool withSubject)
            {
                for (int i = 0; i < ring.Count; i++)
                {
                    Entry entry = ring.Items[ring.IndexOf(i)];
                    sb.Append(indent).Append(Clock(entry.First, utc, now));
                    if (entry.Repeat > 1) sb.AppendFormat(ReportCulture, " x{0} until {1}", entry.Repeat, Clock(entry.Time, utc, now));
                    sb.Append("  ");
                    AppendEntry(sb, entry, withSubject);
                    sb.Append('\n');
                }
            }
            private static string Clock(float time, DateTime utc, float now) => (utc - TimeSpan.FromSeconds(Mathf.Max(0f, now - time))).ToString("HH:mm:ss", ReportCulture);
            private static void AppendEntry(System.Text.StringBuilder sb, Entry e, bool withSubject)
            {
                bool vehicleEvent = e.Kind >= BlackBoxKind.EventStart;
                if (withSubject)
                {
                    if (vehicleEvent) sb.AppendFormat(ReportCulture, "[{0}] {1} #{2} ", e.Owner ?? "?", e.Subject ?? "?", e.Code);
                    else sb.AppendFormat(ReportCulture, "[{0}] {1} net {2} ", e.Owner ?? "?", e.Subject ?? "?", e.Id);
                }
                switch (e.Kind)
                {
                    case BlackBoxKind.Spawn:
                        sb.AppendFormat(ReportCulture, "spawned at {0}", ReportPos(e.Position));
                        break;
                    case BlackBoxKind.State:
                    case BlackBoxKind.Battle:
                    case BlackBoxKind.SubState:
                        sb.AppendFormat(ReportCulture, "{0} {1} -> {2}", e.Kind == BlackBoxKind.State ? "state" : e.Kind == BlackBoxKind.Battle ? "battle" : "sub-state",
                            e.A ?? "-", e.B ?? "-");
                        break;
                    case BlackBoxKind.Stuck:
                    case BlackBoxKind.Escalation:
                        sb.AppendFormat(ReportCulture, "{0} {1} at {2}", e.Kind == BlackBoxKind.Stuck ? "stuck" : "stuck escalated to the state", (StuckReason)e.Code,
                            ReportPos(e.Position));
                        break;
                    case BlackBoxKind.Warp:
                        sb.AppendFormat(ReportCulture, "warp {0:0.0} m to {1} (stuck reason before: {2})", e.Value, ReportPos(e.Position), (StuckReason)e.Code);
                        break;
                    case BlackBoxKind.SwimRescue:
                    case BlackBoxKind.Escape:
                        sb.AppendFormat(ReportCulture, "{0}: {1}, {2:0.0} m to {3}", e.Kind == BlackBoxKind.SwimRescue ? "swim rescue" : "island escape", e.A ?? "-",
                            e.Value, ReportPos(e.Position));
                        break;
                    case BlackBoxKind.Death:
                        sb.AppendFormat(ReportCulture, "died: {0}{1} at {2}", (DamageType)e.Code, e.A != null ? " by " + e.A : "", ReportPos(e.Position));
                        break;
                    case BlackBoxKind.EventStart:
                        sb.AppendFormat(ReportCulture, "started, vehicle {0} net {1} at {2}", e.B ?? "-", e.Id, ReportPos(e.Position));
                        break;
                    case BlackBoxKind.EventEnd:
                    case BlackBoxKind.EventRemoved:
                        sb.AppendFormat(ReportCulture, "{0} after {1}: {2}; vehicle {3} at {4}", e.Kind == BlackBoxKind.EventEnd ? "ended" : "removed",
                            ReportDuration(e.Value), e.A ?? "-", e.B ?? "-", ReportPos(e.Position));
                        break;
                    case BlackBoxKind.EventFailed:
                        sb.AppendFormat(ReportCulture, "start failed: {0}", e.A ?? "-");
                        break;
                    case BlackBoxKind.VehicleTeleport:
                        sb.AppendFormat(ReportCulture, "vehicle teleported {0:0} m to {1}: {2}", e.Value, ReportPos(e.Position), e.A ?? "-");
                        break;
                    case BlackBoxKind.VehicleRetake:
                        sb.AppendFormat(ReportCulture, "pilot took the wheel again (attempt {0:0}) at {1}", e.Value, ReportPos(e.Position));
                        break;
                    case BlackBoxKind.VehicleReplan:
                        sb.AppendFormat(ReportCulture, "route piece rebuilt (rebuild {0:0} of the run) at {1}", e.Value, ReportPos(e.Position));
                        break;
                    default:
                        sb.Append(e.Kind.ToString());
                        break;
                }
            }
            #endregion
        }
        #endregion

        #region Log capture
        internal static class LogCapture
        {
            private const int ErrorCapacity = 100;
            private const int WarningCapacity = 50;
            private const int MessageLimit = 3000;
            private const int StackLines = 15;

            private sealed class Line
            {
                public DateTime First, Last;
                public UnityEngine.LogType Type;
                public string Message, Stack;
                public int Repeat;
            }
            private sealed class Lines
            {
                public readonly Line[] Items;
                public int Head, Count, Seen;
                public Lines(int capacity) => Items = new Line[capacity];
                public Line Newest => Count > 0 ? Items[(Head - 1 + Items.Length) % Items.Length] : null;
                public void Add(Line line)
                {
                    Items[Head] = line;
                    Head = (Head + 1) % Items.Length;
                    if (Count < Items.Length) Count++;
                }
            }

            private static readonly object _lock = new object();
            private static readonly Lines _errors = new Lines(ErrorCapacity);
            private static readonly Lines _warnings = new Lines(WarningCapacity);
            private static volatile string[] _names = BuildNames();
            private static bool _hooked;

            public static string[] Names => _names;

            private static string[] BuildNames()
            {
                var names = new List<string> { nameof(NPCsController) };
                names.AddRange(KnownFamilyPlugins);
                return names.ToArray();
            }
            public static void AddName(string name)
            {
                if (string.IsNullOrEmpty(name) || name.Length < 4) return;
                lock (_lock)
                {
                    string[] current = _names;
                    if (Array.IndexOf(current, name) >= 0) return;
                    var next = new string[current.Length + 1];
                    Array.Copy(current, next, current.Length);
                    next[current.Length] = name;
                    _names = next;
                }
            }

            public static void Start()
            {
                if (_hooked) return;
                UnityEngine.Application.logMessageReceivedThreaded += OnLog;
                _hooked = true;
            }
            public static void Stop()
            {
                if (!_hooked) return;
                UnityEngine.Application.logMessageReceivedThreaded -= OnLog;
                _hooked = false;
                lock (_lock)
                {
                    Array.Clear(_errors.Items, 0, _errors.Items.Length);
                    Array.Clear(_warnings.Items, 0, _warnings.Items.Length);
                    _errors.Head = _errors.Count = _errors.Seen = 0;
                    _warnings.Head = _warnings.Count = _warnings.Seen = 0;
                    _names = BuildNames();
                }
            }

            public static bool Mentions(string text, string[] names)
            {
                if (string.IsNullOrEmpty(text)) return false;
                foreach (string name in names)
                    if (text.IndexOf(name, StringComparison.Ordinal) >= 0) return true;
                return false;
            }
            private static bool IsCompileFailure(string message)
                => message.IndexOf("Error while compiling", StringComparison.OrdinalIgnoreCase) >= 0
                   || message.IndexOf("Failed compiling", StringComparison.OrdinalIgnoreCase) >= 0
                   || message.IndexOf("Failed to compile", StringComparison.OrdinalIgnoreCase) >= 0;

            private static void OnLog(string message, string stack, UnityEngine.LogType type)
            {
                try
                {
                    bool warning = type == UnityEngine.LogType.Warning;
                    if (!warning && type != UnityEngine.LogType.Error && type != UnityEngine.LogType.Exception && type != UnityEngine.LogType.Assert) return;
                    if (string.IsNullOrEmpty(message) || message.IndexOf(" Test log]: ", StringComparison.Ordinal) >= 0) return;
                    string[] names = _names;
                    if (!Mentions(message, names) && !Mentions(stack, names) && !IsCompileFailure(message)) return;
                    DateTime now = DateTime.UtcNow;
                    if (message.Length > MessageLimit) message = message.Substring(0, MessageLimit) + " ...";
                    lock (_lock)
                    {
                        Lines lines = warning ? _warnings : _errors;
                        lines.Seen++;
                        Line last = lines.Newest;
                        if (last != null && last.Type == type && last.Message == message)
                        {
                            last.Repeat++;
                            last.Last = now;
                            return;
                        }
                        lines.Add(new Line { First = now, Last = now, Type = type, Message = message, Stack = TrimStack(stack), Repeat = 1 });
                    }
                }
                catch (Exception)
                {
                }
            }
            private static string TrimStack(string stack)
            {
                if (string.IsNullOrEmpty(stack)) return null;
                int index = -1;
                for (int i = 0; i < StackLines; i++)
                {
                    index = stack.IndexOf('\n', index + 1);
                    if (index < 0) return stack.TrimEnd();
                }
                return stack.Substring(0, index) + "\n...";
            }

            public static int CountMentions(string name)
            {
                int count = 0;
                lock (_lock)
                {
                    foreach (Lines lines in new[] { _errors, _warnings })
                        for (int i = 0; i < lines.Count; i++)
                        {
                            Line line = lines.Items[(lines.Head - lines.Count + i + lines.Items.Length) % lines.Items.Length];
                            if (line.Message.IndexOf(name, StringComparison.Ordinal) >= 0 || (line.Stack?.IndexOf(name, StringComparison.Ordinal) ?? -1) >= 0) count++;
                        }
                }
                return count;
            }

            public static void Append(System.Text.StringBuilder sb, out int errors, out int warnings)
            {
                var errorLines = new List<Line>();
                var warningLines = new List<Line>();
                int errorsSeen, warningsSeen;
                lock (_lock)
                {
                    Copy(_errors, errorLines);
                    Copy(_warnings, warningLines);
                    errorsSeen = _errors.Seen;
                    warningsSeen = _warnings.Seen;
                }
                errors = errorsSeen;
                warnings = warningsSeen;
                ReportLine(sb, "Captured since the controller loaded: lines that mention NPCsController or a family plugin, and plugin compile failures.");
                ReportLine(sb, "Errors and exceptions: {0} seen, last {1} kept (newest last):", errorsSeen, errorLines.Count);
                foreach (Line line in errorLines) AppendLine(sb, line);
                ReportLine(sb, "Warnings: {0} seen, last {1} kept (newest last):", warningsSeen, warningLines.Count);
                foreach (Line line in warningLines) AppendLine(sb, line);
            }
            private static void Copy(Lines lines, List<Line> into)
            {
                for (int i = 0; i < lines.Count; i++)
                {
                    Line line = lines.Items[(lines.Head - lines.Count + i + lines.Items.Length) % lines.Items.Length];
                    into.Add(new Line { First = line.First, Last = line.Last, Type = line.Type, Message = line.Message, Stack = line.Stack, Repeat = line.Repeat });
                }
            }
            private static void AppendLine(System.Text.StringBuilder sb, Line line)
            {
                sb.AppendFormat(ReportCulture, "[{0:yyyy-MM-dd HH:mm:ss}] {1}", line.First, line.Type);
                if (line.Repeat > 1) sb.AppendFormat(ReportCulture, " x{0} until {1:HH:mm:ss}", line.Repeat, line.Last);
                sb.Append(": ");
                string[] text = line.Message.Split('\n');
                sb.Append(text[0].TrimEnd('\r')).Append('\n');
                for (int i = 1; i < text.Length; i++)
                    if (text[i].Trim().Length > 0) sb.Append("    ").Append(text[i].TrimEnd('\r')).Append('\n');
                if (!string.IsNullOrEmpty(line.Stack)) ReportIndented(sb, "    | ", line.Stack);
            }
        }
        #endregion
    }
    #endregion

    #region Building Navigation
    public partial class NPCsController
    {
        public static class BuildingNavigation
        {
            #region Fields And Properties

            private static readonly Dictionary<uint, SimpleBuildGraph> _simpleGraphs = new Dictionary<uint, SimpleBuildGraph>();
            private static readonly Dictionary<uint, int> _simpleGraphVersionById = new Dictionary<uint, int>();
            public static int GetSimpleGraphVersion(uint buildingID)
                => _simpleGraphVersionById.TryGetValue(buildingID, out var v) ? v : 0;
            private static void BumpSimpleGraphVersion(uint buildingID)
                => _simpleGraphVersionById[buildingID] = GetSimpleGraphVersion(buildingID) + 1;
            private const float SimpleLinkRange = 3.5f;
            private const float SimpleFloorEdgeClearance = 0.5f;
            private const float SimpleFloorGridStep = 0.95f;
            private const float SimpleBlockLinkRange = 2f;
            private const float SimpleIncrementalRelinkRadius = 7f;
            private const float SimpleLinkProbeUp = 0.4f;
            private const float SimpleDoorSearchRadius = 1.6f;
            private const float SimpleHatchSearchRadius = 1.2f;
            private const float SimpleHatchFrameOffset = 1.0f;
            private const float SimpleHatchNodeUp = 0.5f;
            private const float SimpleDoorNeighborRange = 2f;
            private const float SimpleBlockFallbackRange = 2f;
            private const float SimpleDoorBlockRadius = 0.35f;
            private const float SimpleSameFloorY = 1.5f;
            private const float SimpleStairStepY = 3.3f;
            private const float StairJointMergeDist = 0.6f;
            private const float SimpleRingPadding = 1.5f;
            private const float SimplePerimeterStep = 3f;
            private const float SimpleNearRing = 1.5f;
            private const float SimpleMidRing = 3f;
            private const float SimpleZonePadding = 6f;
            private const float SimpleStreetBridgeRange = 20f;
            private const float SimpleStreetLinkRange = 5.5f;
            private const float GroundGridStep = 3f;
            private const float GroundHalfSize = 1.5f;
            private const float GroundEdgeStep = 1.5f;
            private const float GroundNeighborRadius = 1.6f;
            private const float GroundNearTerrain = 2.5f;
            private const float PerimeterClearance = 1f;
            private const int PerimeterPushTries = 4;
            private const float GroundProbeRadius = 0.3f;

            private static readonly Dictionary<uint, HashSet<object>> _simpleWatch = new Dictionary<uint, HashSet<object>>();
            private static readonly object _legacyWatchSubscriber = new object();
            private static readonly HashSet<uint> _simpleRebuildPending = new HashSet<uint>();
            private static readonly Dictionary<uint, List<(BuildingBlock block, bool isAdd)>> _incrementalPending
                = new Dictionary<uint, List<(BuildingBlock block, bool isAdd)>>();
            private static bool _simpleRebuildScheduled;
            private static readonly HashSet<BuildingBlock> _pendingBlockEvents = new HashSet<BuildingBlock>();

            #endregion

            #region Methods

            private static HelperNavGraph.NavGraphNode MakeGraphNode(Vector3 pos, NodeRole role = NodeRole.Unknown)
            {
                var n = new HelperNavGraph.NavGraphNode(pos);
                n.Role = role;
                return n;
            }

            public static bool TryGetZoneContaining(Vector3 pos, out HelperNavGraph.NavGraphZone zone, out uint buildingID, out bool isSimple)
            {
                zone = null; buildingID = 0; isSimple = false;
                float bestVol = float.MaxValue;
                foreach (var kv in _simpleGraphs)
                {
                    var z = kv.Value?.Zone;
                    if (z == null || z.Graph == null || !z.Contains(pos)) continue;
                    var bc = z.Box;
                    float vol = bc != null ? bc.size.x * bc.size.y * bc.size.z : float.MaxValue;
                    if (vol < bestVol) { bestVol = vol; zone = z; buildingID = kv.Key; isSimple = true; }
                }
                return zone != null;
            }

            #region Simple building graph

            public static void RebuildSimpleGraphForBuilding(uint buildingID)
            {
                if (buildingID == 0 || ServerObjectForPlugin.Instance == null) return;
                BuildingManager.Building building = BuildingManager.server.GetBuilding(buildingID);
                if (building?.buildingBlocks == null || building.buildingBlocks.Count == 0)
                {
                    _simpleWatch.Remove(buildingID);
                    DestroySimpleGraphForBuilding(buildingID); return;
                }

                var nodes = new List<HelperNavGraph.NavGraphNode>();
                var owner = new Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock>();
                var noAutoLink = new HashSet<HelperNavGraph.NavGraphNode>();
                var doorNodes = new List<HelperNavGraph.NavGraphNode>();
                var hatchBottoms = new List<HelperNavGraph.NavGraphNode>();
                var ladderEnds = new List<HelperNavGraph.NavGraphNode>();
                Vector3 min = Vector3.positiveInfinity, max = Vector3.negativeInfinity;

                var blocks = building.buildingBlocks;
                var groundBlocks = new List<BuildingBlock>();
                for (int i = 0; i < blocks.Count; i++)
                {
                    BuildingBlock bb = blocks[i];
                    if (bb == null || bb.IsDestroyed) continue;
                    Vector3 p = bb.transform.position;
                    min = Vector3.Min(min, p); max = Vector3.Max(max, p);
                    if (IsGroundBlock(bb)) groundBlocks.Add(bb);
                    AddSimpleBlockNodes(bb, nodes, owner, noAutoLink, doorNodes, hatchBottoms);
                }
                if (nodes.Count == 0)
                {
                    DestroySimpleGraphForBuilding(buildingID); return;
                }

                float yaw = DominantFoundationYaw(blocks);
                Quaternion rot = Quaternion.Euler(0f, yaw, 0f);
                Quaternion inv = Quaternion.Inverse(rot);
                Vector3 pivotW = (min + max) * 0.5f;
                Vector3 lmin = Vector3.positiveInfinity, lmax = Vector3.negativeInfinity;
                for (int i = 0; i < blocks.Count; i++)
                {
                    BuildingBlock bb = blocks[i];
                    if (bb == null || bb.IsDestroyed) continue;
                    Vector3 lp = inv * (bb.transform.position - pivotW);
                    lmin = Vector3.Min(lmin, lp); lmax = Vector3.Max(lmax, lp);
                }
                Vector3 zoneCenterW = pivotW + rot * ((lmin + lmax) * 0.5f);
                Vector3 zoneSizeLocal = lmax - lmin;

                var tc = building.GetDominatingBuildingPrivilege();
                if (tc != null)
                {
                    Vector3 gateHalf = zoneSizeLocal * 0.5f + new Vector3(SimpleZonePadding, 2f, SimpleZonePadding);
                    var ownHits = Physics.OverlapBox(zoneCenterW, gateHalf, rot, LayerMask.GetMask("Construction", "Deployed"), QueryTriggerInteraction.Ignore);
                    var ownSeen = new HashSet<ulong>();
                    for (int i = 0; i < ownHits.Length; i++)
                    {
                        var ent = ownHits[i].gameObject.ToBaseEntity();
                        if (ent == null || ent.IsDestroyed || ent.net == null || !(ent is Gate)) continue;
                        if (!ownSeen.Add(ent.net.ID.Value)) continue;
                        if (ent.GetBuildingPrivilege() != tc) continue;
                        Vector3 ep = ent.transform.position;
                        var gd = MakeGraphNode(new Vector3(ep.x, ep.y + 0.1f, ep.z), NodeRole.Gate);
                        gd.BindLinkedEntity("door", (Door)ent);
                        gd.IsNoAutoLink = true;
                        nodes.Add(gd); noAutoLink.Add(gd); doorNodes.Add(gd);
                    }
                    var ladSeen = new HashSet<ulong>();
                    for (int i = 0; i < ownHits.Length; i++)
                    {
                        var ent = ownHits[i].gameObject.ToBaseEntity();
                        if (ent == null || ent.IsDestroyed || ent.net == null || !(ent is BaseLadder bl)) continue;
                        if (!ladSeen.Add(ent.net.ID.Value)) continue;
                        if (ent.GetBuildingPrivilege() != tc) continue;
                        TryAddWallLadder(bl, nodes, noAutoLink, ladderEnds);
                    }
                }

                int walkMask = 1 << UnityEngine.AI.NavMesh.GetAreaFromName("Walkable");
                var groundRing = new List<HelperNavGraph.NavGraphNode>();
                var navmeshRing = new List<HelperNavGraph.NavGraphNode>();
                AddGroundPerimeterRing(groundBlocks, groundRing);
                AddStreetRingOriented(zoneCenterW, zoneSizeLocal, rot, SimpleMidRing, walkMask, navmeshRing);
                nodes.AddRange(groundRing);
                nodes.AddRange(navmeshRing);

                int linkObstacleMask = LayerMask.GetMask("Construction", "Deployed");
                int groundSupportMask = LayerMask.GetMask("Construction", "Terrain", "World");
                float rngSqr = SimpleLinkRange * SimpleLinkRange;
                float blockRngSqr = SimpleBlockLinkRange * SimpleBlockLinkRange;
                float linkCell = SimpleLinkRange;
                var linkGrid = new Dictionary<long, List<int>>();
                for (int i = 0; i < nodes.Count; i++)
                {
                    if (noAutoLink.Contains(nodes[i])) continue;
                    long key = LinkCellKey(nodes[i].Position, linkCell);
                    if (!linkGrid.TryGetValue(key, out var bucket)) { bucket = new List<int>(); linkGrid[key] = bucket; }
                    bucket.Add(i);
                }
                for (int a = 0; a < nodes.Count; a++)
                {
                    if (noAutoLink.Contains(nodes[a])) continue;
                    Vector3 pa = nodes[a].Position;
                    int cx = Mathf.FloorToInt(pa.x / linkCell), cz = Mathf.FloorToInt(pa.z / linkCell);
                    for (int dx = -1; dx <= 1; dx++)
                        for (int dz = -1; dz <= 1; dz++)
                        {
                            if (!linkGrid.TryGetValue(((long)(cx + dx) << 32) ^ (uint)(cz + dz), out var bucket)) continue;
                            for (int bi = 0; bi < bucket.Count; bi++)
                            {
                                int b = bucket[bi];
                                if (b <= a) continue;
                                Vector3 pb = nodes[b].Position;
                                bool bothBlock = nodes[a].Role != NodeRole.Street && nodes[b].Role != NodeRole.Street;
                                if ((pa - pb).sqrMagnitude > (bothBlock ? blockRngSqr : rngSqr)) continue;
                                float yCap = (IsStairEndNode(nodes[a], owner) || IsStairEndNode(nodes[b], owner)) ? SimpleStairStepY : SimpleSameFloorY;
                                if (Mathf.Abs(pa.y - pb.y) > yCap) continue;
                                if (SegmentCrossesDoorway(pa, pb, doorNodes)) continue;
                                if (LinkBlockedByNonHatch(pa + Vector3.up * SimpleLinkProbeUp, pb + Vector3.up * SimpleLinkProbeUp, linkObstacleMask)) continue;
                                if (bothBlock && !HasFloorSupportBetween(pa, pb, groundSupportMask)) continue;
                                nodes[a].AddLink(nodes[b]); nodes[b].AddLink(nodes[a]);
                            }
                        }
                }

                LinkGroundToNavmeshRings(groundRing, navmeshRing, doorNodes, linkObstacleMask);
                LinkNavmeshRing(navmeshRing, doorNodes, linkObstacleMask);
                LinkGroundRing(groundRing, doorNodes, linkObstacleMask);

                for (int h = 0; h < hatchBottoms.Count; h++)
                {
                    var nu = hatchBottoms[h];
                    owner.TryGetValue(nu, out var nuOwner);
                    float fallbackRngSqr = SimpleBlockFallbackRange * SimpleBlockFallbackRange;
                    HelperNavGraph.NavGraphNode floorNode = null; float bestF = fallbackRngSqr;
                    HelperNavGraph.NavGraphNode anyNear = null; float bestAny = fallbackRngSqr;
                    for (int i = 0; i < nodes.Count; i++)
                    {
                        var cand = nodes[i];
                        if (cand == nu || noAutoLink.Contains(cand)) continue;
                        if (!owner.TryGetValue(cand, out var ob) || ob == null) continue;
                        if (Mathf.Abs(cand.Position.y - nu.Position.y) > SimpleSameFloorY) continue;
                        float sq = (cand.Position - nu.Position).sqrMagnitude;
                        if (sq >= fallbackRngSqr) continue;
                        if (LinkBlockedByNonHatch(nu.Position + Vector3.up * SimpleLinkProbeUp, cand.Position + Vector3.up * SimpleLinkProbeUp, linkObstacleMask, nuOwner)) continue;
                        if (sq < bestAny) { bestAny = sq; anyNear = cand; }
                        string osn = ob.ShortPrefabName;
                        if (osn.Contains("stair") || osn.Contains("ramp")) continue;
                        if (sq >= bestF) continue;
                        bestF = sq; floorNode = cand;
                    }
                    var bridge = floorNode ?? anyNear;
                    if (bridge != null)
                    {
                        nu.AddEdge(new PathEdge(bridge, NodeHint.CloseDoor, null, Vector3.Distance(nu.Position, bridge.Position)));
                        bridge.AddLink(nu);
                    }
                }

                for (int l = 0; l < ladderEnds.Count; l++)
                {
                    var le = ladderEnds[l];
                    HelperNavGraph.NavGraphNode floorNode = null; float bestFloor = SimpleBlockFallbackRange * SimpleBlockFallbackRange;
                    HelperNavGraph.NavGraphNode streetNode = null; float bestStreet = rngSqr;
                    for (int i = 0; i < nodes.Count; i++)
                    {
                        var cand = nodes[i];
                        if (cand == le || noAutoLink.Contains(cand)) continue;
                        if (Mathf.Abs(cand.Position.y - le.Position.y) > SimpleSameFloorY) continue;
                        float sq = (cand.Position - le.Position).sqrMagnitude;
                        if (owner.TryGetValue(cand, out var ob) && ob != null)
                        { if (sq < bestFloor) { bestFloor = sq; floorNode = cand; } }
                        else
                        { if (sq < bestStreet) { bestStreet = sq; streetNode = cand; } }
                    }
                    if (floorNode != null) { le.AddLink(floorNode); floorNode.AddLink(le); }
                    if (streetNode != null) { le.AddLink(streetNode); streetNode.AddLink(le); }
                }

                for (int s = 0; s < nodes.Count; s++)
                {
                    var se = nodes[s];
                    if (noAutoLink.Contains(se) || !IsStairEndNode(se, owner)) continue;
                    owner.TryGetValue(se, out var seOwner);
                    float fallbackRngSqr = SimpleBlockFallbackRange * SimpleBlockFallbackRange;
                    HelperNavGraph.NavGraphNode floorNode = null; float bestF = fallbackRngSqr;
                    for (int i = 0; i < nodes.Count; i++)
                    {
                        var cand = nodes[i];
                        if (cand == se || noAutoLink.Contains(cand) || IsStairEndNode(cand, owner)) continue;
                        if (!owner.TryGetValue(cand, out var ob) || ob == null) continue;
                        if (Mathf.Abs(cand.Position.y - se.Position.y) > SimpleSameFloorY) continue;
                        float sq = (cand.Position - se.Position).sqrMagnitude;
                        if (sq >= bestF) continue;
                        if (LinkBlockedByNonHatch(se.Position + Vector3.up * SimpleLinkProbeUp, cand.Position + Vector3.up * SimpleLinkProbeUp, linkObstacleMask, seOwner)) continue;
                        bestF = sq; floorNode = cand;
                    }
                    var bridge = floorNode;
                    if (bridge != null && !HasEdgeTo(se, bridge)) { se.AddLink(bridge); bridge.AddLink(se); }
                }

                for (int d = 0; d < doorNodes.Count; d++)
                    ConnectDoorNode(doorNodes[d], nodes, noAutoLink);

                var graph = new HelperNavGraph.NavGraph(nodes);
                graph.EnsureBridgesSync();
                EnsureSimpleGraphZone(buildingID, zoneCenterW, zoneSizeLocal, rot, graph, nodes, owner, doorNodes.Count);
            }

            private static float TerrainHeightAtXZ(Vector3 p)
                => TerrainMeta.HeightMap != null ? TerrainMeta.HeightMap.GetHeight(p) : p.y;

            private const float MaxTerrainClampRise = 3f;
            private static Vector3 ClampAboveTerrain(Vector3 p)
            {
                float ty = TerrainHeightAtXZ(p);
                if (ty > p.y && ty - p.y <= MaxTerrainClampRise) p.y = ty;
                return p;
            }

            private static void AddSimpleBlockNodes(BuildingBlock bb, List<HelperNavGraph.NavGraphNode> nodes,
                Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock> owner,
                HashSet<HelperNavGraph.NavGraphNode> noAutoLink, List<HelperNavGraph.NavGraphNode> doorNodes,
                List<HelperNavGraph.NavGraphNode> hatchBottoms)
            {
                string sn = bb.ShortPrefabName;
                Transform t = bb.transform;
                Bounds lb = bb.bounds;

                if (sn == "foundation" || sn == "floor" || sn == "floor.frame")
                {
                    Door frameHatch = null;
                    if (sn == "floor.frame" && !FrameHasCover(bb, out frameHatch)) return;
                    Vector3 wc = t.TransformPoint(lb.center);
                    Vector3 nodePos = ClampAboveTerrain(new Vector3(wc.x, wc.y + lb.extents.y + 0.1f, wc.z));
                    if (frameHatch != null) { TryAddHatchLadder(bb, frameHatch, nodePos, nodes, owner, noAutoLink, hatchBottoms); return; }
                    if (FloorBlockedByStair(nodePos, bb)) return;
                    AddFloorGridNodes(bb, lb, t, nodes, owner);
                    return;
                }

                if (sn == "foundation.triangle" || sn == "floor.triangle" || sn == "floor.triangle.frame")
                {
                    Door triHatch = null;
                    if (sn == "floor.triangle.frame" && !FrameHasCover(bb, out triHatch)) return;
                    Vector3 centroidLocal = new Vector3(lb.center.x, lb.center.y, lb.center.z - lb.size.z / 6f);
                    Vector3 wc = t.TransformPoint(centroidLocal);
                    Vector3 nodePos = ClampAboveTerrain(new Vector3(wc.x, wc.y + lb.extents.y + 0.1f, wc.z));
                    if (triHatch != null) { TryAddHatchLadder(bb, triHatch, nodePos, nodes, owner, noAutoLink, hatchBottoms); return; }
                    if (FloorBlockedByStair(nodePos, bb)) return;
                    AddFloorTriangleGridNodes(bb, lb, t, centroidLocal, nodes, owner);
                    return;
                }

                if (sn == "wall.doorway" || sn == "wall.frame")
                {
                    Vector3 wc = t.TransformPoint(lb.center);
                    var nD = MakeGraphNode(new Vector3(wc.x, t.position.y + 0.1f, wc.z), NodeRole.Door);
                    nodes.Add(nD); owner[nD] = bb;
                    Door door = FindDoorNear(bb, wc);
                    if (door != null)
                    {
                        nD.BindLinkedEntity("door", door);
                        nD.IsNoAutoLink = true;
                        noAutoLink.Add(nD);
                        doorNodes.Add(nD);
                    }
                    return;
                }

                if (sn.Contains("stair") || sn.Contains("ramp")
                    || sn.Contains("steps"))
                {
                    Vector3 lp = t.InverseTransformPoint(t.position + Vector3.up * 0.1f);
                    float s4 = lb.size.z / 4f;
                    float s2 = lb.size.z / 2f;
                    float sUp2 = lb.size.y / 2f;
                    float sSpiral = lb.size.z * 0.4f;
                    switch (sn)
                    {
                        case "block.stair.spiral":
                        case "block.stair.spiral.triangle":
                        {
                            var pts = new List<Vector3>
                            {
                                lp + new Vector3(-sSpiral, 0f, 0f),
                                lp + new Vector3(0f, sUp2, sSpiral),
                                lp + new Vector3(sSpiral, 2f * sUp2, 0f),
                            };
                            AddStairChain(bb, pts, nodes, owner, noAutoLink);
                            return;
                        }
                        case "block.stair.lshape":
                        {
                            Vector3 p = lp + Vector3.forward * s2 + Vector3.right * s4;
                            var pts = new List<Vector3> { p };
                            p += Vector3.forward * -s4 + Vector3.up * s4; pts.Add(p);
                            p += Vector3.forward * -s4 + Vector3.up * s4; pts.Add(p);
                            p += Vector3.forward * -s4; pts.Add(p);
                            p += Vector3.right * -s4; pts.Add(p);
                            p += Vector3.right * -s4 + Vector3.up * s4; pts.Add(p);
                            p += Vector3.right * -s4 + Vector3.up * s4; pts.Add(p);
                            AddStairChain(bb, pts, nodes, owner, noAutoLink);
                            return;
                        }
                        case "block.stair.ushape":
                        {
                            Vector3 p = lp + Vector3.forward * s2 + Vector3.right * s4;
                            var pts = new List<Vector3> { p };
                            p += Vector3.forward * -s4 + Vector3.up * s4; pts.Add(p);
                            p += Vector3.forward * -s4 + Vector3.up * s4; pts.Add(p);
                            p += Vector3.forward * -s4; pts.Add(p);
                            p += Vector3.right * -(s4 * 2f); pts.Add(p);
                            p += Vector3.forward * s4; pts.Add(p);
                            p += Vector3.forward * s4 + Vector3.up * s4; pts.Add(p);
                            p += Vector3.forward * s4 + Vector3.up * s4; pts.Add(p);
                            AddStairChain(bb, pts, nodes, owner, noAutoLink);
                            return;
                        }
                        default:
                        {
                            bool alongX = lb.extents.x >= lb.extents.z;
                            float half = (alongX ? lb.extents.x : lb.extents.z) * 0.85f;
                            Vector3 axis = alongX ? Vector3.right : Vector3.forward;
                            Vector3 lo = lb.center - axis * half, hi = lb.center + axis * half;
                            if (sn.Contains("ramp"))
                            {
                                Vector3 rLow = new Vector3(lo.x, 0.2f, lo.z);
                                Vector3 rMid = new Vector3(lb.center.x, 0.475f, lb.center.z);
                                Vector3 rHigh = new Vector3(hi.x, 0.75f, hi.z);
                                AddStairChain(bb, new List<Vector3> { rLow, rMid, rHigh }, nodes, owner, noAutoLink);
                                return;
                            }
                            Vector3 pLow = new Vector3(lo.x, 0.35f, lo.z);
                            Vector3 pMid = new Vector3(lb.center.x, 1.05f, lb.center.z);
                            Vector3 pHigh = new Vector3(hi.x, 1.6f, hi.z);
                            AddStairChain(bb, new List<Vector3> { pLow, pMid, pHigh }, nodes, owner, noAutoLink);
                            return;
                        }
                    }
                }
            }

            private static void AddStairChain(BuildingBlock bb, List<Vector3> localPoints,
                List<HelperNavGraph.NavGraphNode> nodes,
                Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock> owner,
                HashSet<HelperNavGraph.NavGraphNode> noAutoLink)
            {
                var world = new List<Vector3>(localPoints.Count);
                for (int i = 0; i < localPoints.Count; i++) world.Add(bb.transform.TransformPoint(localPoints[i]));
                AddStairChainWorld(bb, world, nodes, owner, noAutoLink);
            }

            private static void AddStairChainWorld(BuildingBlock bb, List<Vector3> worldPoints,
                List<HelperNavGraph.NavGraphNode> nodes,
                Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock> owner,
                HashSet<HelperNavGraph.NavGraphNode> noAutoLink)
            {
                int n = worldPoints.Count;
                if (n == 0) return;
                var chain = new HelperNavGraph.NavGraphNode[n];
                for (int i = 0; i < n; i++)
                {
                    Vector3 wp = ClampAboveTerrain(worldPoints[i]);
                    var existing = (i == 0 || i == n - 1) ? FindNodeNear(wp, nodes, StairJointMergeDist) : null;
                    if (existing != null) chain[i] = existing;
                    else { chain[i] = MakeGraphNode(wp, NodeRole.Stair); nodes.Add(chain[i]); owner[chain[i]] = bb; }
                }
                for (int i = 0; i + 1 < n; i++)
                {
                    chain[i].AddLink(chain[i + 1]); chain[i + 1].AddLink(chain[i]);
                }
                for (int i = 1; i < n - 1; i++) { chain[i].IsNoAutoLink = true; noAutoLink.Add(chain[i]); }
            }

            private static HelperNavGraph.NavGraphNode FindNodeNear(Vector3 pos, List<HelperNavGraph.NavGraphNode> nodes, float dist)
            {
                float d2 = dist * dist;
                for (int i = 0; i < nodes.Count; i++)
                    if ((nodes[i].Position - pos).sqrMagnitude <= d2) return nodes[i];
                return null;
            }

            private static bool HasEdgeTo(HelperNavGraph.NavGraphNode node, HelperNavGraph.NavGraphNode target)
            {
                foreach (var e in node.Edges)
                    if (e.Target == target) return true;
                return false;
            }

            private static void TrySampleStreetNode(Vector3 probe, int walkMask, List<HelperNavGraph.NavGraphNode> streetNodes)
            {
                float gy = TerrainHeightAtXZ(probe);
                if (!Rust.Ai.Gen2.RustNavMeshHelpers.SamplePosition(new Vector3(probe.x, gy + 2f, probe.z), out UnityEngine.AI.NavMeshHit nh, 6f, walkMask)) return;
                if (nh.position.y - gy > GroundNearTerrain) return;
                if (FindNodeNear(nh.position, streetNodes, SimpleRingPadding) != null) return;
                streetNodes.Add(MakeGraphNode(nh.position, NodeRole.Street));
            }

            private static bool IsGroundBlock(BuildingBlock bb)
            {
                string sn = bb.ShortPrefabName;
                if (!IsFoundationLikePrefab(sn) && !sn.Contains("stair")) return false;
                Vector3 centerW = bb.transform.TransformPoint(bb.bounds.center);
                float bottomY = centerW.y - bb.bounds.extents.y;
                float th = TerrainHeightAtXZ(centerW);
                return bottomY - th <= GroundNearTerrain;
            }

            private static bool IsFoundationLikePrefab(string sn)
                => sn.Contains("foundation")
                || sn.Contains("steps")
                || sn.Contains("ramp");

            private static bool IsGroundRingPrefabName(string sn)
                => IsFoundationLikePrefab(sn) || sn.Contains("stair");

            private static void AddGroundPerimeterRing(List<BuildingBlock> ground, List<HelperNavGraph.NavGraphNode> streetNodes)
            {
                if (ground.Count == 0) return;
                float cell = GroundGridStep;
                var centersW = new Vector3[ground.Count];
                var grid = new Dictionary<long, List<int>>();
                for (int i = 0; i < ground.Count; i++)
                {
                    centersW[i] = ground[i].transform.TransformPoint(ground[i].bounds.center);
                    long key = LinkCellKey(centersW[i], cell);
                    if (!grid.TryGetValue(key, out var b)) { b = new List<int>(); grid[key] = b; }
                    b.Add(i);
                }
                var corners = new List<Vector3>(4);
                for (int i = 0; i < ground.Count; i++)
                {
                    var bb = ground[i];
                    Transform tr = bb.transform;
                    GetFootprintCornersLocal(bb, corners);
                    if (corners.Count < 3) continue;
                    Vector3 centerW = centersW[i];
                    int n = corners.Count;
                    for (int k = 0; k < n; k++)
                        ProcessFootprintEdge(tr.TransformPoint(corners[k]), tr.TransformPoint(corners[(k + 1) % n]),
                            centerW, centersW, grid, cell, streetNodes);
                }
            }

            private static void GetFootprintCornersLocal(BuildingBlock bb, List<Vector3> corners)
            {
                corners.Clear();
                Bounds lb = bb.bounds;
                Vector3 c = lb.center;
                float ex = lb.extents.x, ez = lb.extents.z;
                if (bb.ShortPrefabName.Contains("triangle"))
                {
                    corners.Add(new Vector3(c.x - ex, c.y, c.z - ez));
                    corners.Add(new Vector3(c.x + ex, c.y, c.z - ez));
                    corners.Add(new Vector3(c.x,      c.y, c.z + ez));
                    return;
                }
                corners.Add(new Vector3(c.x - ex, c.y, c.z - ez));
                corners.Add(new Vector3(c.x + ex, c.y, c.z - ez));
                corners.Add(new Vector3(c.x + ex, c.y, c.z + ez));
                corners.Add(new Vector3(c.x - ex, c.y, c.z + ez));
            }

            private static void ProcessFootprintEdge(Vector3 aW, Vector3 bW, Vector3 centerW, Vector3[] centersW,
                Dictionary<long, List<int>> grid, float cell, List<HelperNavGraph.NavGraphNode> streetNodes)
            {
                aW.y = 0f; bW.y = 0f; centerW.y = 0f;
                Vector3 edge = bW - aW;
                float len = edge.magnitude;
                if (len < 1e-3f) return;
                Vector3 edgeDir = edge / len;
                Vector3 normal = Vector3.Cross(Vector3.up, edgeDir);
                Vector3 mid = (aW + bW) * 0.5f;
                if (Vector3.Dot(normal, mid - centerW) < 0f) normal = -normal;
                bool inner = HasGroundNeighbor(mid + normal * GroundHalfSize, centersW, grid, cell);
                if (inner) return;
                for (float d = 0f; d <= len + 0.01f; d += GroundEdgeStep)
                    TrySampleGroundNodeWithClearance(aW + edgeDir * Mathf.Min(d, len) + normal * SimpleNearRing, normal, streetNodes);
            }

            private static bool HasGroundNeighbor(Vector3 probe, Vector3[] centersW, Dictionary<long, List<int>> grid, float cell)
            {
                float r2 = GroundNeighborRadius * GroundNeighborRadius;
                int cx = Mathf.FloorToInt(probe.x / cell), cz = Mathf.FloorToInt(probe.z / cell);
                for (int dx = -1; dx <= 1; dx++)
                    for (int dz = -1; dz <= 1; dz++)
                    {
                        if (!grid.TryGetValue(((long)(cx + dx) << 32) ^ (uint)(cz + dz), out var bucket)) continue;
                        for (int bi = 0; bi < bucket.Count; bi++)
                        {
                            Vector3 gc = centersW[bucket[bi]];
                            float ddx = gc.x - probe.x, ddz = gc.z - probe.z;
                            if (ddx * ddx + ddz * ddz <= r2) return true;
                        }
                    }
                return false;
            }

            private static readonly RaycastHit[] _groundPierceHits = new RaycastHit[16];
            private static void TrySampleGroundNodeWithClearance(Vector3 probeXZ, Vector3 dir, List<HelperNavGraph.NavGraphNode> streetNodes)
            {
                int constructionMask = LayerMask.GetMask("Construction");
                int groundMask = LayerMask.GetMask("Construction", "Terrain", "World");
                for (int attempt = 0; attempt <= PerimeterPushTries; attempt++)
                {
                    float top = TerrainHeightAtXZ(probeXZ) + 6f;
                    int n = Physics.SphereCastNonAlloc(new Vector3(probeXZ.x, top, probeXZ.z), GroundProbeRadius, Vector3.down, _groundPierceHits, 12f, groundMask, QueryTriggerInteraction.Ignore);
                    if (n > 1) Array.Sort(_groundPierceHits, 0, n, Comparer<RaycastHit>.Create((a, b) => a.distance.CompareTo(b.distance)));
                    RaycastHit hit = default; bool found = false;
                    for (int hi = 0; hi < n; hi++)
                    {
                        var h = _groundPierceHits[hi];
                        if (h.collider.ToBaseEntity() is BuildingBlock hbb0 && !IsFoundationLikePrefab(hbb0.ShortPrefabName)) continue;
                        hit = h; found = true; break;
                    }
                    if (!found)
                    { probeXZ += dir * GroundEdgeStep; continue; }
                    if (hit.collider.ToBaseEntity() is BuildingBlock hbb)
                    {
                        string hsn = hbb.ShortPrefabName;
                        if (hsn.Contains("steps")
                         || hsn.Contains("ramp"))
                        { probeXZ += dir * GroundEdgeStep; continue; }
                    }
                    Vector3 pos = hit.point + Vector3.up * 0.1f;
                    if (pos.y - TerrainHeightAtXZ(pos) > GroundNearTerrain)
                    { probeXZ += dir * GroundEdgeStep; continue; }
                    if (OverlapsSlopedBlock(pos))
                    { probeXZ += dir * GroundEdgeStep; continue; }
                    if (Physics.Raycast(pos, Vector3.up, PerimeterClearance, constructionMask, QueryTriggerInteraction.Ignore))
                    { probeXZ += dir * GroundEdgeStep; continue; }
                    if (FindNodeNear(pos, streetNodes, SimpleRingPadding) != null)
                        return;
                    streetNodes.Add(MakeGraphNode(pos, NodeRole.Street));
                    return;
                }
            }

            private static readonly Collider[] _slopeOverlap = new Collider[8];
            private static bool OverlapsSlopedBlock(Vector3 pos)
            {
                int n = Physics.OverlapSphereNonAlloc(pos + Vector3.up * 0.5f, GroundProbeRadius + 0.2f, _slopeOverlap,
                    LayerMask.GetMask("Construction"), QueryTriggerInteraction.Ignore);
                for (int i = 0; i < n; i++)
                {
                    if (_slopeOverlap[i].ToBaseEntity() is BuildingBlock bb)
                    {
                        string sn = bb.ShortPrefabName;
                        if (sn.Contains("steps")
                         || sn.Contains("ramp")
                         || sn.Contains("stair"))
                            return true;
                    }
                }
                return false;
            }

            private static void AddStreetRingOriented(Vector3 centerW, Vector3 sizeLocal, Quaternion rot, float pad, int walkMask,
                List<HelperNavGraph.NavGraphNode> streetNodes)
            {
                float hx = sizeLocal.x * 0.5f + pad, hz = sizeLocal.z * 0.5f + pad;
                for (float x = -hx; x <= hx + 0.01f; x += SimplePerimeterStep)
                {
                    TrySampleStreetNode(centerW + rot * new Vector3(x, 0f, -hz), walkMask, streetNodes);
                    TrySampleStreetNode(centerW + rot * new Vector3(x, 0f,  hz), walkMask, streetNodes);
                }
                for (float z = -hz + SimplePerimeterStep; z < hz - 0.01f; z += SimplePerimeterStep)
                {
                    TrySampleStreetNode(centerW + rot * new Vector3(-hx, 0f, z), walkMask, streetNodes);
                    TrySampleStreetNode(centerW + rot * new Vector3( hx, 0f, z), walkMask, streetNodes);
                }
            }

            private static float DominantFoundationYaw(ListHashSet<BuildingBlock> blocks)
            {
                var counts = new Dictionary<int, int>();
                float firstBlockYaw = 0f; bool haveAnyBlock = false;
                for (int i = 0; i < blocks.Count; i++)
                {
                    BuildingBlock bb = blocks[i];
                    if (bb == null || bb.IsDestroyed) continue;
                    if (!haveAnyBlock) { firstBlockYaw = bb.transform.eulerAngles.y; haveAnyBlock = true; }
                    string sn = bb.ShortPrefabName;
                    if (sn == null || !sn.Contains("foundation")
                        || sn.Contains("steps")) continue;
                    int key = Mathf.RoundToInt(bb.transform.eulerAngles.y) % 360; if (key < 0) key += 360;
                    counts.TryGetValue(key, out int c); counts[key] = c + 1;
                }
                if (counts.Count == 0) return firstBlockYaw;
                int bestKey = 0, bestCount = -1;
                foreach (var kv in counts) if (kv.Value > bestCount) { bestCount = kv.Value; bestKey = kv.Key; }
                return bestKey;
            }

            private static void LinkGroundToNavmeshRings(List<HelperNavGraph.NavGraphNode> groundRing,
                List<HelperNavGraph.NavGraphNode> navmeshRing,
                List<HelperNavGraph.NavGraphNode> doorNodes, int obstacleMask)
            {
                float rngSqr = SimpleStreetBridgeRange * SimpleStreetBridgeRange;
                for (int g = 0; g < groundRing.Count; g++)
                {
                    Vector3 pg = groundRing[g].Position;
                    HelperNavGraph.NavGraphNode best = null; float bestSqr = rngSqr;
                    for (int m = 0; m < navmeshRing.Count; m++)
                    {
                        Vector3 pm = navmeshRing[m].Position;
                        float d = (pg - pm).sqrMagnitude;
                        if (d > bestSqr) continue;
                        if (SegmentCrossesDoorway(pg, pm, doorNodes)) continue;
                        if (LinkBlockedByNonHatch(pg + Vector3.up * SimpleLinkProbeUp, pm + Vector3.up * SimpleLinkProbeUp, obstacleMask)) continue;
                        best = navmeshRing[m]; bestSqr = d;
                    }
                    if (best != null) { groundRing[g].AddLink(best); best.AddLink(groundRing[g]); }
                }
            }

            private const int GroundRingMinLinks = 2;
            private static void LinkGroundRing(List<HelperNavGraph.NavGraphNode> groundRing,
                List<HelperNavGraph.NavGraphNode> doorNodes, int obstacleMask)
            {
                float hiSqr = SimpleStreetLinkRange * SimpleStreetLinkRange;
                for (int i = 0; i < groundRing.Count; i++)
                {
                    var a = groundRing[i];
                    int have = 0;
                    for (int j = 0; j < groundRing.Count; j++)
                        if (j != i && HasEdgeTo(a, groundRing[j])) have++;
                    while (have < GroundRingMinLinks)
                    {
                        HelperNavGraph.NavGraphNode best = null; float bestSqr = hiSqr;
                        for (int j = 0; j < groundRing.Count; j++)
                        {
                            if (j == i) continue;
                            var b = groundRing[j];
                            if (HasEdgeTo(a, b)) continue;
                            float d = (a.Position - b.Position).sqrMagnitude;
                            if (d > bestSqr) continue;
                            if (Mathf.Abs(a.Position.y - b.Position.y) > SimpleSameFloorY) continue;
                            if (SegmentCrossesDoorway(a.Position, b.Position, doorNodes)) continue;
                            if (LinkBlockedByNonHatch(a.Position + Vector3.up * SimpleLinkProbeUp, b.Position + Vector3.up * SimpleLinkProbeUp, obstacleMask)) continue;
                            best = b; bestSqr = d;
                        }
                        if (best == null) break;
                        a.AddLink(best); best.AddLink(a);
                        have++;
                    }
                }
            }

            private static void LinkNavmeshRing(List<HelperNavGraph.NavGraphNode> navmeshRing,
                List<HelperNavGraph.NavGraphNode> doorNodes, int obstacleMask)
            {
                float loSqr = SimpleLinkRange * SimpleLinkRange;
                float hiSqr = SimpleStreetLinkRange * SimpleStreetLinkRange;
                for (int i = 0; i < navmeshRing.Count; i++)
                {
                    Vector3 pi = navmeshRing[i].Position;
                    for (int j = i + 1; j < navmeshRing.Count; j++)
                    {
                        Vector3 pj = navmeshRing[j].Position;
                        float d = (pi - pj).sqrMagnitude;
                        if (d <= loSqr || d > hiSqr) continue;
                        if (SegmentCrossesDoorway(pi, pj, doorNodes)) continue;
                        if (LinkBlockedByNonHatch(pi + Vector3.up * SimpleLinkProbeUp, pj + Vector3.up * SimpleLinkProbeUp, obstacleMask)) continue;
                        navmeshRing[i].AddLink(navmeshRing[j]); navmeshRing[j].AddLink(navmeshRing[i]);
                    }
                }
            }

            private static long LinkCellKey(Vector3 p, float cell)
                => ((long)Mathf.FloorToInt(p.x / cell) << 32) ^ (uint)Mathf.FloorToInt(p.z / cell);

            private static readonly RaycastHit[] _linkHits = new RaycastHit[16];
            private const float HatchLinkSameFloorY = 0.5f;
            private static bool LinkBlockedByNonHatch(Vector3 a, Vector3 b, int mask, BuildingBlock ignoreOwner = null)
            {
                bool sameFloor = Mathf.Abs(a.y - b.y) <= HatchLinkSameFloorY;
                Vector3 dir = b - a;
                float dist = dir.magnitude;
                if (dist < 1e-4f) return false;
                dir /= dist;
                int n = Physics.RaycastNonAlloc(a, dir, _linkHits, dist, mask, QueryTriggerInteraction.Ignore);
                for (int i = 0; i < n; i++)
                {
                    var ent = _linkHits[i].collider.ToBaseEntity();
                    if (ent is Door door)
                    {
                        if (sameFloor && door.GetComponentInChildren<TriggerLadder>(true) != null) continue;
                        return true;
                    }
                    if (ent is BuildingBlock bbHit)
                    {
                        if (ignoreOwner != null && bbHit == ignoreOwner) continue;
                        return true;
                    }
                    if (ent is SimpleBuildingBlock) return true;
                }
                return false;
            }

            private const float SupportCheckMinDy = 0.3f;
            private const float SupportProbeDrop = 2.5f;
            private static bool HasFloorSupportBetween(Vector3 a, Vector3 b, int groundMask)
            {
                if (Mathf.Abs(a.y - b.y) < SupportCheckMinDy) return true;
                float horiz = Vector2.Distance(new Vector2(a.x, a.z), new Vector2(b.x, b.z));
                int samples = Mathf.Clamp(Mathf.CeilToInt(horiz / 1.5f), 1, 4);
                for (int i = 1; i <= samples; i++)
                {
                    Vector3 p = Vector3.Lerp(a, b, i / (float)(samples + 1));
                    if (!Physics.Raycast(p + Vector3.up * 0.3f, Vector3.down, SupportProbeDrop + 0.3f, groundMask, QueryTriggerInteraction.Ignore))
                        return false;
                }
                return true;
            }

            private static void ConnectDoorNode(HelperNavGraph.NavGraphNode door, List<HelperNavGraph.NavGraphNode> nodes,
                HashSet<HelperNavGraph.NavGraphNode> noAutoLink)
            {
                float rngSqr = SimpleDoorNeighborRange * SimpleDoorNeighborRange;
                var cands = Pool.Get<List<HelperNavGraph.NavGraphNode>>();
                HelperNavGraph.NavGraphNode near1 = null;
                float best1 = float.MaxValue;
                for (int i = 0; i < nodes.Count; i++)
                {
                    var n = nodes[i];
                    if (n == door || noAutoLink.Contains(n)) continue;
                    if (Mathf.Abs(n.Position.y - door.Position.y) > SimpleSameFloorY) continue;
                    float sq = (n.Position - door.Position).sqrMagnitude;
                    if (sq > rngSqr) continue;
                    cands.Add(n);
                    if (sq < best1) { best1 = sq; near1 = n; }
                }

                HelperNavGraph.NavGraphNode near2 = null;
                if (near1 != null)
                {
                    float best2 = float.MaxValue;
                    for (int i = 0; i < cands.Count; i++)
                    {
                        var n = cands[i];
                        if (n == near1) continue;
                        if (DistancePointToSegmentSqr(door.Position, near1.Position, n.Position) > SimpleDoorBlockRadius * SimpleDoorBlockRadius) continue;
                        float sq = (n.Position - door.Position).sqrMagnitude;
                        if (sq < best2) { best2 = sq; near2 = n; }
                    }
                }

                if (near1 != null) AddDoorEdges(near1, door);
                if (near2 != null) AddDoorEdges(near2, door);
                Pool.FreeUnmanaged(ref cands);
            }

            private static void AddDoorEdges(HelperNavGraph.NavGraphNode neighbor, HelperNavGraph.NavGraphNode door)
            {
                float cost = Vector3.Distance(neighbor.Position, door.Position);
                neighbor.AddEdge(new PathEdge(door, NodeHint.OpenDoor, null, cost));
                door.AddEdge(new PathEdge(neighbor, NodeHint.CloseDoor, null, cost));
            }

            private static Door FindDoorNear(BuildingBlock frame, Vector3 worldPos)
            {
                int mask = LayerMask.GetMask("Construction", "Deployed");
                var hits = Physics.OverlapSphere(worldPos, SimpleDoorSearchRadius, mask, QueryTriggerInteraction.Ignore);
                Door best = null; float bestSqr = float.MaxValue;
                for (int i = 0; i < hits.Length; i++)
                {
                    Collider c = hits[i];
                    if (c == null) continue;
                    Door d = c.gameObject.GetComponent<Door>() ?? c.gameObject.GetComponentInParent<Door>();
                    if (!d.IsValid()) continue;
                    Vector3 ld = frame.transform.InverseTransformPoint(d.transform.position);
                    if (!frame.bounds.Contains(ld)) continue;
                    float sqr = (d.transform.position - worldPos).sqrMagnitude;
                    if (sqr < bestSqr) { bestSqr = sqr; best = d; }
                }
                return best;
            }

            private static bool FrameHasCover(BuildingBlock frame, out Door hatch)
            {
                Bounds lb = frame.bounds;
                Vector3 localCenter = frame.ShortPrefabName.Contains("triangle")
                    ? new Vector3(lb.center.x, lb.center.y, lb.center.z - lb.size.z / 6f)
                    : lb.center;
                Vector3 c = frame.transform.TransformPoint(localCenter);
                hatch = FindHatchNear(c);
                if (hatch != null)
                {
                    Vector3 lh = frame.transform.InverseTransformPoint(hatch.transform.position);
                    if (frame.bounds.Contains(lh)) return true;
                    hatch = null;
                }
                var hits = Physics.OverlapBox(c, new Vector3(0.35f, 0.25f, 0.35f), frame.transform.rotation,
                    LayerMask.GetMask("Construction", "Deployed"), QueryTriggerInteraction.Ignore);
                for (int i = 0; i < hits.Length; i++)
                {
                    var be = hits[i].gameObject.GetComponentInParent<BaseEntity>();
                    if (be != null && be != frame) return true;
                }
                return false;
            }

            private static bool FloorBlockedByStair(Vector3 nodePos, BuildingBlock floor)
            {
                var hits = Physics.OverlapBox(nodePos + Vector3.up * 0.5f, new Vector3(0.4f, 0.45f, 0.4f), Quaternion.identity,
                    LayerMask.GetMask("Construction"), QueryTriggerInteraction.Ignore);
                for (int i = 0; i < hits.Length; i++)
                {
                    var bb = hits[i].gameObject.GetComponentInParent<BuildingBlock>();
                    if (bb == null || bb == floor) continue;
                    string sn = bb.ShortPrefabName;
                    if (sn.Contains("stair") || sn.Contains("ramp")
                        || sn.Contains("steps")) return true;
                }
                return false;
            }

            private static void AddOneFloorNodeWorld(BuildingBlock bb, Vector3 worldPos,
                List<HelperNavGraph.NavGraphNode> nodes, Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock> owner)
            {
                var n = MakeGraphNode(ClampAboveTerrain(worldPos), NodeRole.Floor);
                nodes.Add(n); owner[n] = bb;
            }

            private static void AddFloorGridNodes(BuildingBlock bb, Bounds lb, Transform t,
                List<HelperNavGraph.NavGraphNode> nodes, Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock> owner)
            {
                float cx = Mathf.Max(0.1f, lb.extents.x - SimpleFloorEdgeClearance);
                float cz = Mathf.Max(0.1f, lb.extents.z - SimpleFloorEdgeClearance);
                float topOff = lb.extents.y + 0.1f;
                float step = Mathf.Max(0.1f, SimpleFloorGridStep);
                int n = Mathf.Clamp(Mathf.CeilToInt(2f * Mathf.Max(cx, cz) / step) + 1, 2, 6);
                for (int ix = 0; ix < n; ix++)
                {
                    float fx = -cx + 2f * cx * (ix / (float)(n - 1));
                    for (int iz = 0; iz < n; iz++)
                    {
                        float fz = -cz + 2f * cz * (iz / (float)(n - 1));
                        Vector3 wc = t.TransformPoint(new Vector3(lb.center.x + fx, lb.center.y, lb.center.z + fz));
                        AddOneFloorNodeWorld(bb, new Vector3(wc.x, wc.y + topOff, wc.z), nodes, owner);
                    }
                }
            }

            private static void AddFloorTriangleGridNodes(BuildingBlock bb, Bounds lb, Transform t, Vector3 centroidLocal,
                List<HelperNavGraph.NavGraphNode> nodes, Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock> owner)
            {
                float topY = t.TransformPoint(centroidLocal).y + lb.extents.y + 0.1f;
                float ex = lb.extents.x, ez = lb.extents.z;
                Vector3 c0 = new Vector3(lb.center.x - ex, centroidLocal.y, lb.center.z - ez);
                Vector3 c1 = new Vector3(lb.center.x + ex, centroidLocal.y, lb.center.z - ez);
                Vector3 c2 = new Vector3(lb.center.x,      centroidLocal.y, lb.center.z + ez);

                float sa = Vector3.Distance(c1, c2), sb = Vector3.Distance(c2, c0), sc = Vector3.Distance(c0, c1);
                float perim = sa + sb + sc;
                if (perim < 1e-3f) return;
                Vector3 incenter = (c0 * sa + c1 * sb + c2 * sc) / perim;
                float area = 0.5f * Vector3.Cross(c1 - c0, c2 - c0).magnitude;
                float inradius = 2f * area / perim;
                float k = Mathf.Max(0.05f, (inradius - SimpleFloorEdgeClearance) / Mathf.Max(1e-3f, inradius));
                c0 = incenter + (c0 - incenter) * k;
                c1 = incenter + (c1 - incenter) * k;
                c2 = incenter + (c2 - incenter) * k;

                float maxSide = Mathf.Max(Vector3.Distance(c0, c1), Mathf.Max(Vector3.Distance(c1, c2), Vector3.Distance(c2, c0)));
                int n = Mathf.Clamp(Mathf.CeilToInt(maxSide / Mathf.Max(0.1f, SimpleFloorGridStep)), 1, 6);
                for (int i = 0; i <= n; i++)
                    for (int j = 0; j <= n - i; j++)
                    {
                        int kk = n - i - j;
                        Vector3 p = (c0 * i + c1 * j + c2 * kk) / n;
                        Vector3 w = t.TransformPoint(p);
                        AddOneFloorNodeWorld(bb, new Vector3(w.x, topY, w.z), nodes, owner);
                    }
            }

            private static Door FindHatchNear(Vector3 worldPos)
            {
                int mask = LayerMask.GetMask("Construction", "Deployed");
                var hits = Physics.OverlapSphere(worldPos, SimpleHatchSearchRadius, mask, QueryTriggerInteraction.Ignore);
                Door best = null; float bestSqr = float.MaxValue;
                for (int i = 0; i < hits.Length; i++)
                {
                    Collider c = hits[i];
                    if (c == null) continue;
                    Door d = c.gameObject.GetComponent<Door>() ?? c.gameObject.GetComponentInParent<Door>();
                    if (!d.IsValid() || d.GetComponentInChildren<TriggerLadder>(true) == null) continue;
                    float sqr = (d.transform.position - worldPos).sqrMagnitude;
                    if (sqr < bestSqr) { bestSqr = sqr; best = d; }
                }
                return best;
            }

            private static bool IsDoorBarrierNode(HelperNavGraph.NavGraphNode n)
                => n != null && (n.Role == NodeRole.Gate || n.LinkedDoor != null);

            private static bool SegmentCrossesDoorway(Vector3 a, Vector3 b, List<HelperNavGraph.NavGraphNode> doorNodes)
            {
                float r2 = SimpleDoorBlockRadius * SimpleDoorBlockRadius;
                for (int d = 0; d < doorNodes.Count; d++)
                    if (DistancePointToSegmentSqr(doorNodes[d].Position, a, b) <= r2) return true;
                return false;
            }

            private static float DistancePointToSegmentSqr(Vector3 p, Vector3 a, Vector3 b)
            {
                Vector3 ab = b - a;
                float len2 = ab.sqrMagnitude;
                if (len2 < 1e-6f) return (p - a).sqrMagnitude;
                float t = Mathf.Clamp01(Vector3.Dot(p - a, ab) / len2);
                return (p - (a + ab * t)).sqrMagnitude;
            }

            private static bool IsStairEndNode(HelperNavGraph.NavGraphNode node,
                Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock> owner)
            {
                if (!owner.TryGetValue(node, out var ob) || ob == null) return false;
                string osn = ob.ShortPrefabName;
                return osn.Contains("stair") || osn.Contains("ramp")
                    || osn.Contains("steps");
            }

            private static void TryAddHatchLadder(BuildingBlock bb, Door hatch, Vector3 framePos,
                List<HelperNavGraph.NavGraphNode> nodes,
                Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock> owner,
                HashSet<HelperNavGraph.NavGraphNode> noAutoLink,
                List<HelperNavGraph.NavGraphNode> hatchBottoms)
            {
                if (hatch == null) return;
                float topY = framePos.y;
                float cx = framePos.x, cz = framePos.z;

                Collider ladder = hatch.GetComponentInChildren<TriggerLadder>(true)?.GetComponent<Collider>();
                if (ladder == null)
                {
                    var nPlain = MakeGraphNode(framePos, NodeRole.Floor);
                    nodes.Add(nPlain); owner[nPlain] = bb;
                    return;
                }

                var nHatch = MakeGraphNode(new Vector3(cx, topY + SimpleHatchNodeUp, cz), NodeRole.Ladder);
                nHatch.BindLinkedEntity("door", hatch); nHatch.BindLadderTrigger(ladder); nHatch.IsWaypointOnly = true;
                nHatch.IsNoAutoLink = true;
                nodes.Add(nHatch); owner[nHatch] = bb; noAutoLink.Add(nHatch);

                Vector3 baseXZ = new Vector3(cx, topY, cz);
                Vector3 fwd = bb.transform.forward, rgt = bb.transform.right;
                if (bb.ShortPrefabName.Contains("triangle"))
                {
                    AddHatchFrameNode(baseXZ + fwd * SimpleHatchFrameOffset, nHatch, bb, nodes, owner);
                    AddHatchFrameNode(baseXZ + (-fwd * 0.5f - rgt * 0.866f) * SimpleHatchFrameOffset, nHatch, bb, nodes, owner);
                    AddHatchFrameNode(baseXZ + (-fwd * 0.5f + rgt * 0.866f) * SimpleHatchFrameOffset, nHatch, bb, nodes, owner);
                }
                else
                {
                    Vector3 axis = ChooseClearHatchAxis(baseXZ, hatch, fwd, rgt);
                    AddHatchFrameNode(baseXZ + axis * SimpleHatchFrameOffset, nHatch, bb, nodes, owner);
                    AddHatchFrameNode(baseXZ - axis * SimpleHatchFrameOffset, nHatch, bb, nodes, owner);
                }

                float drop = 3f;
                int floorMask = LayerMask.GetMask("Construction", "World", "Terrain");
                if (Physics.Raycast(new Vector3(cx, topY - 0.5f, cz), Vector3.down, out RaycastHit fhit, 6f, floorMask, QueryTriggerInteraction.Ignore))
                    drop = Mathf.Clamp(topY - fhit.point.y, 0.6f, 6f);
                var nUnder = MakeGraphNode(new Vector3(cx, topY - drop + 0.5f, cz), NodeRole.Ladder);
                nUnder.IsWaypointOnly = true;
                nUnder.BindLinkedEntity("door", hatch);
                nUnder.IsNoAutoLink = true;
                nodes.Add(nUnder); owner[nUnder] = bb; noAutoLink.Add(nUnder); hatchBottoms.Add(nUnder);

                if (!hatch.IsOpen())
                {
                    nUnder.AddEdge(new PathEdge(nHatch, NodeHint.OpenDoor, null, Vector3.Distance(nUnder.Position, nHatch.Position)));
                    nHatch.AddEdge(new PathEdge(nUnder, NodeHint.OpenDoor, null, Vector3.Distance(nHatch.Position, nUnder.Position)));
                    return;
                }

                float yT = nHatch.Position.y, yB = nUnder.Position.y;
                float topLadY = Mathf.Lerp(yT, yB, 0.34f);
                float botLadY = Mathf.Lerp(yT, yB, 0.67f);
                if (yT - yB >= 1.2f)
                {
                    topLadY = Mathf.Min(topLadY + 0.5f, yT - 0.25f);
                    botLadY = Mathf.Min(botLadY + 0.5f, topLadY - 0.25f);
                }
                var nLadTop = MakeGraphNode(new Vector3(cx, topLadY, cz), NodeRole.Ladder);
                nLadTop.BindLadderTrigger(ladder); nLadTop.IsWaypointOnly = true;
                var nLadBot = MakeGraphNode(new Vector3(cx, botLadY, cz), NodeRole.Ladder);
                nLadBot.BindLadderTrigger(ladder); nLadBot.IsWaypointOnly = true;
                nodes.Add(nLadTop); nodes.Add(nLadBot);
                owner[nLadTop] = bb; owner[nLadBot] = bb;
                nLadTop.IsNoAutoLink = true; nLadBot.IsNoAutoLink = true;
                noAutoLink.Add(nLadTop); noAutoLink.Add(nLadBot);

                nHatch.AddEdge(new PathEdge(nLadTop, NodeHint.Climb, null, Vector3.Distance(nHatch.Position, nLadTop.Position)));
                nLadTop.AddEdge(new PathEdge(nHatch, NodeHint.Climb, null, Vector3.Distance(nLadTop.Position, nHatch.Position)));
                nLadTop.AddEdge(new PathEdge(nLadBot, NodeHint.Climb, null, Vector3.Distance(nLadTop.Position, nLadBot.Position)));
                nLadBot.AddEdge(new PathEdge(nLadTop, NodeHint.Climb, null, Vector3.Distance(nLadBot.Position, nLadTop.Position)));
                nLadBot.AddEdge(new PathEdge(nUnder, NodeHint.Climb, null, Vector3.Distance(nLadBot.Position, nUnder.Position)));
                nUnder.AddEdge(new PathEdge(nLadBot, NodeHint.Climb, null, Vector3.Distance(nUnder.Position, nLadBot.Position)));
            }

            private static void TryAddWallLadder(BaseLadder ladder, List<HelperNavGraph.NavGraphNode> nodes,
                HashSet<HelperNavGraph.NavGraphNode> noAutoLink,
                List<HelperNavGraph.NavGraphNode> ladderEnds)
            {
                Collider col = ladder.GetComponentInChildren<TriggerLadder>(true)?.GetComponent<Collider>();
                if (col == null) return;
                Vector3 c = col.bounds.center;
                float yBot = col.bounds.min.y + 0.3f;
                float yTop = col.bounds.max.y;
                if (yTop - yBot < 0.5f) return;

                var nBot = MakeGraphNode(new Vector3(c.x, yBot, c.z), NodeRole.Ladder);
                nBot.BindLadderTrigger(col); nBot.IsWaypointOnly = true;
                var nTop = MakeGraphNode(new Vector3(c.x, yTop, c.z), NodeRole.Ladder);
                nTop.BindLadderTrigger(col); nTop.IsWaypointOnly = true;
                nodes.Add(nBot); nodes.Add(nTop);
                nBot.IsNoAutoLink = true; nTop.IsNoAutoLink = true;
                noAutoLink.Add(nBot); noAutoLink.Add(nTop);

                var chain = new List<HelperNavGraph.NavGraphNode> { nBot };
                float height = yTop - yBot;
                if (height >= 1.2f)
                {
                    int mids = Mathf.Clamp(Mathf.FloorToInt(height), 1, 3);
                    for (int i = 1; i <= mids; i++)
                    {
                        float y = Mathf.Lerp(yBot, yTop, i / (float)(mids + 1));
                        var nm = MakeGraphNode(new Vector3(c.x, y, c.z), NodeRole.Ladder);
                        nm.BindLadderTrigger(col); nm.IsWaypointOnly = true;
                        nm.IsNoAutoLink = true;
                        nodes.Add(nm); noAutoLink.Add(nm);
                        chain.Add(nm);
                    }
                }
                chain.Add(nTop);
                for (int i = 0; i + 1 < chain.Count; i++)
                {
                    chain[i].AddEdge(new PathEdge(chain[i + 1], NodeHint.Climb, null, Vector3.Distance(chain[i].Position, chain[i + 1].Position)));
                    chain[i + 1].AddEdge(new PathEdge(chain[i], NodeHint.Climb, null, Vector3.Distance(chain[i + 1].Position, chain[i].Position)));
                }
                ladderEnds.Add(nBot);
                ladderEnds.Add(nTop);
            }

            private static void AddHatchFrameNode(Vector3 pos, HelperNavGraph.NavGraphNode nHatch, BuildingBlock bb,
                List<HelperNavGraph.NavGraphNode> nodes, Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock> owner)
            {
                var nf = MakeGraphNode(pos, NodeRole.Floor);
                nodes.Add(nf); owner[nf] = bb;
                nf.AddEdge(new PathEdge(nHatch, NodeHint.OpenDoor, null, Vector3.Distance(nf.Position, nHatch.Position)));
                nHatch.AddEdge(new PathEdge(nf, NodeHint.CloseDoor, null, Vector3.Distance(nHatch.Position, nf.Position)));
            }

            private static Vector3 ChooseClearHatchAxis(Vector3 baseXZ, Door hatch, Vector3 fwd, Vector3 rgt)
            {
                if (HatchSideClear(baseXZ + fwd * SimpleHatchFrameOffset, fwd, hatch)
                    && HatchSideClear(baseXZ - fwd * SimpleHatchFrameOffset, -fwd, hatch))
                    return fwd;
                if (HatchSideClear(baseXZ + rgt * SimpleHatchFrameOffset, rgt, hatch)
                    && HatchSideClear(baseXZ - rgt * SimpleHatchFrameOffset, -rgt, hatch))
                    return rgt;
                return fwd;
            }

            private static bool HatchSideClear(Vector3 sidePos, Vector3 outward, Door hatch)
            {
                Vector3 center = new Vector3(sidePos.x, sidePos.y + 1.0f, sidePos.z);
                Quaternion rot = Quaternion.LookRotation(outward, Vector3.up);
                var hits = Physics.OverlapBox(center, new Vector3(0.35f, 0.7f, 0.6f), rot,
                    LayerMask.GetMask("Construction", "Deployed"), QueryTriggerInteraction.Ignore);
                for (int i = 0; i < hits.Length; i++)
                    if (hits[i] != null && hits[i].ToBaseEntity() == hatch) return false;
                return true;
            }

            private static Dictionary<BuildingBlock, List<HelperNavGraph.NavGraphNode>> BuildNodesByBlockIndex(
                Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock> owner)
            {
                var byBlock = new Dictionary<BuildingBlock, List<HelperNavGraph.NavGraphNode>>();
                foreach (var kv in owner)
                {
                    if (kv.Value == null) continue;
                    if (!byBlock.TryGetValue(kv.Value, out var list)) { list = new List<HelperNavGraph.NavGraphNode>(); byBlock[kv.Value] = list; }
                    list.Add(kv.Key);
                }
                return byBlock;
            }

            private static void EnsureSimpleGraphZone(uint buildingID, Vector3 centerW, Vector3 sizeLocal, Quaternion rot, HelperNavGraph.NavGraph graph,
                List<HelperNavGraph.NavGraphNode> nodes, Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock> owner, int doorCount)
            {
                Vector3 size = sizeLocal + new Vector3(SimpleZonePadding * 2f, 4f, SimpleZonePadding * 2f);
                bool created = false;
                if (!_simpleGraphs.TryGetValue(buildingID, out var sg) || sg == null || sg.Zone == null)
                {
                    var go = new GameObject($"NPCsSimpleGraphZone_{buildingID}");
                    go.layer = (int)Rust.Layer.Trigger;
                    go.transform.SetParent(ServerObjectForPlugin.Instance.transform, false);
                    BoxCollider box = go.AddComponent<BoxCollider>();
                    box.isTrigger = true;
                    box.center = Vector3.zero;
                    var zone = go.AddComponent<HelperNavGraph.NavGraphZone>();
                    zone.Key = $"sbuild_{buildingID}";
                    sg = new SimpleBuildGraph { Zone = zone };
                    _simpleGraphs[buildingID] = sg;
                    created = true;
                }
                sg.Zone.transform.SetPositionAndRotation(centerW, rot);
                sg.Zone.GetComponent<BoxCollider>().size = size;
                sg.Zone.Graph = graph;
                sg.Nodes = nodes;
                sg.Owner = owner;
                sg.NodesByBlock = BuildNodesByBlockIndex(owner);
                if (created) HelperNavGraph.SyncBotsAlreadyInside(sg.Zone);
                BumpSimpleGraphVersion(buildingID);
            }

            private static HelperNavGraph.NavGraphNode CloneNodeForRelink(HelperNavGraph.NavGraphNode src)
            {
                var n = MakeGraphNode(src.Position, src.Role);
                n.IsWaypointOnly = src.IsWaypointOnly;
                n.IsNavMesh = src.IsNavMesh;
                n.IsNoAutoLink = src.IsNoAutoLink;
                if (src.LinkedDoor != null) n.BindLinkedEntity("door", src.LinkedDoor);
                if (src.LinkedButton != null) n.BindLinkedEntity("button", src.LinkedButton);
                if (src.LinkedReader != null) n.BindLinkedEntity("reader", src.LinkedReader);
                if (src.LinkedLadderTrigger != null) n.BindLadderTrigger(src.LinkedLadderTrigger);
                return n;
            }

            private static void CloneAllNodesWithEdges(List<HelperNavGraph.NavGraphNode> source,
                out Dictionary<HelperNavGraph.NavGraphNode, HelperNavGraph.NavGraphNode> cloneMap,
                out List<HelperNavGraph.NavGraphNode> clones)
            {
                cloneMap = new Dictionary<HelperNavGraph.NavGraphNode, HelperNavGraph.NavGraphNode>(source.Count);
                clones = new List<HelperNavGraph.NavGraphNode>(source.Count);
                for (int i = 0; i < source.Count; i++)
                {
                    var clone = CloneNodeForRelink(source[i]);
                    cloneMap[source[i]] = clone;
                    clones.Add(clone);
                }
                for (int i = 0; i < source.Count; i++)
                {
                    var src = source[i];
                    var clone = cloneMap[src];
                    foreach (var edge in src.Edges)
                    {
                        var targetNode = edge.Target as HelperNavGraph.NavGraphNode;
                        if (targetNode == null) { clone.AddEdge(new PathEdge(edge.Target, edge.Hint, edge.Waypoints, edge.Cost)); continue; }
                        if (!cloneMap.TryGetValue(targetNode, out var newTarget)) continue;
                        clone.AddEdge(new PathEdge(newTarget, edge.Hint, edge.Waypoints, edge.Cost));
                    }
                }
            }

            private static void RelinkNodeSet(List<HelperNavGraph.NavGraphNode> relinkSet,
                List<HelperNavGraph.NavGraphNode> allDoorNodes, int linkObstacleMask, int groundSupportMask)
            {
                float rngSqr = SimpleLinkRange * SimpleLinkRange;
                float blockRngSqr = SimpleBlockLinkRange * SimpleBlockLinkRange;
                for (int a = 0; a < relinkSet.Count; a++)
                {
                    Vector3 pa = relinkSet[a].Position;
                    for (int b = a + 1; b < relinkSet.Count; b++)
                    {
                        Vector3 pb = relinkSet[b].Position;
                        bool bothBlock = relinkSet[a].Role != NodeRole.Street && relinkSet[b].Role != NodeRole.Street;
                        if ((pa - pb).sqrMagnitude > (bothBlock ? blockRngSqr : rngSqr)) continue;
                        if (Mathf.Abs(pa.y - pb.y) > SimpleSameFloorY) continue;
                        if (SegmentCrossesDoorway(pa, pb, allDoorNodes)) continue;
                        if (LinkBlockedByNonHatch(pa + Vector3.up * SimpleLinkProbeUp, pb + Vector3.up * SimpleLinkProbeUp, linkObstacleMask)) continue;
                        if (bothBlock && !HasFloorSupportBetween(pa, pb, groundSupportMask)) continue;
                        relinkSet[a].AddLink(relinkSet[b]); relinkSet[b].AddLink(relinkSet[a]);
                    }
                }
            }

            private static bool TryCollectClosure(HelperNavGraph.NavGraph graph, Vector3 pos,
                Dictionary<HelperNavGraph.NavGraphNode, HelperNavGraph.NavGraphNode> cloneMap,
                out List<HelperNavGraph.NavGraphNode> closureClones)
            {
                closureClones = new List<HelperNavGraph.NavGraphNode>();
                var candidates = Pool.Get<List<HelperNavGraph.NavGraphNode>>();
                graph.GetNodesInRadius(pos, SimpleIncrementalRelinkRadius + SimpleLinkRange, candidates);
                bool ok = true;
                for (int i = 0; i < candidates.Count; i++)
                {
                    var c = candidates[i];
                    if (c.IsNoAutoLink) { ok = false; break; }
                    if (c.Role == NodeRole.Street) continue;
                    if (cloneMap.TryGetValue(c, out var clone)) closureClones.Add(clone);
                }
                Pool.FreeUnmanaged(ref candidates);
                return ok;
            }

            private static void TryIncrementalAddBlock(uint buildingID, BuildingBlock block)
            {
                if (block == null || block.IsDestroyed || !_simpleGraphs.TryGetValue(buildingID, out var sg)
                    || sg?.Zone?.Graph == null || sg.NodesByBlock == null || sg.Owner == null)
                { RebuildSimpleGraphForBuilding(buildingID); return; }

                if (sg.NodesByBlock.ContainsKey(block)) return;

                string sn = block.ShortPrefabName;
                if (sn != "foundation" && sn != "floor")
                { RebuildSimpleGraphForBuilding(buildingID); return; }

                if (IsGroundBlock(block))
                { RebuildSimpleGraphForBuilding(buildingID); return; }

                Vector3 blockPos = block.transform.position;
                if (sg.Zone != null && !sg.Zone.Contains(blockPos))
                { RebuildSimpleGraphForBuilding(buildingID); return; }

                var newNodes = new List<HelperNavGraph.NavGraphNode>();
                var newOwner = new Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock>();
                var newNoAutoLink = new HashSet<HelperNavGraph.NavGraphNode>();
                var newDoorNodes = new List<HelperNavGraph.NavGraphNode>();
                var newHatchBottoms = new List<HelperNavGraph.NavGraphNode>();
                AddSimpleBlockNodes(block, newNodes, newOwner, newNoAutoLink, newDoorNodes, newHatchBottoms);
                if (newNoAutoLink.Count > 0 || newDoorNodes.Count > 0 || newHatchBottoms.Count > 0)
                { RebuildSimpleGraphForBuilding(buildingID); return; }
                if (newNodes.Count == 0) return;

                var oldGraph = sg.Zone.Graph;
                CloneAllNodesWithEdges(sg.Nodes, out var cloneMap, out var allClones);
                if (!TryCollectClosure(oldGraph, blockPos, cloneMap, out var closureClones))
                { RebuildSimpleGraphForBuilding(buildingID); return; }

                var closureSet = new HashSet<IAIPathNode>();
                for (int i = 0; i < closureClones.Count; i++) closureSet.Add(closureClones[i]);
                for (int i = 0; i < closureClones.Count; i++) closureClones[i].RemoveEdgesTo(closureSet);

                var relinkSet = new List<HelperNavGraph.NavGraphNode>(closureClones.Count + newNodes.Count);
                relinkSet.AddRange(closureClones);
                relinkSet.AddRange(newNodes);

                var allDoorNodes = Pool.Get<List<HelperNavGraph.NavGraphNode>>();
                for (int i = 0; i < allClones.Count; i++)
                    if (IsDoorBarrierNode(allClones[i])) allDoorNodes.Add(allClones[i]);
                int linkObstacleMask = LayerMask.GetMask("Construction", "Deployed");
                int groundSupportMask = LayerMask.GetMask("Construction", "Terrain", "World");
                RelinkNodeSet(relinkSet, allDoorNodes, linkObstacleMask, groundSupportMask);
                Pool.FreeUnmanaged(ref allDoorNodes);

                var finalNodes = new List<HelperNavGraph.NavGraphNode>(allClones.Count + newNodes.Count);
                finalNodes.AddRange(allClones);
                finalNodes.AddRange(newNodes);
                var finalOwner = new Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock>(finalNodes.Count);
                foreach (var kv in sg.Owner)
                    if (cloneMap.TryGetValue(kv.Key, out var oc)) finalOwner[oc] = kv.Value;
                foreach (var kv in newOwner) finalOwner[kv.Key] = kv.Value;

                var newGraph = new HelperNavGraph.NavGraph(finalNodes);
                var relinkHashSet = new HashSet<HelperNavGraph.NavGraphNode>(relinkSet);
                newGraph.SeedBridgesIncremental(oldGraph, cloneMap, relinkHashSet);

                sg.Nodes = finalNodes;
                sg.Owner = finalOwner;
                sg.NodesByBlock = BuildNodesByBlockIndex(finalOwner);
                sg.Zone.Graph = newGraph;
                BumpSimpleGraphVersion(buildingID);
            }

            private static void TryIncrementalRemoveBlock(uint buildingID, BuildingBlock block)
            {
                if (ReferenceEquals(block, null) || !_simpleGraphs.TryGetValue(buildingID, out var sg) || sg?.Zone?.Graph == null
                    || sg.NodesByBlock == null || sg.Owner == null || !sg.NodesByBlock.TryGetValue(block, out var removedNodes) || removedNodes.Count == 0)
                { RebuildSimpleGraphForBuilding(buildingID); return; }

                for (int i = 0; i < removedNodes.Count; i++)
                    if (removedNodes[i].IsNoAutoLink)
                    { RebuildSimpleGraphForBuilding(buildingID); return; }

                if (IsGroundRingPrefabName(block.ShortPrefabName))
                { RebuildSimpleGraphForBuilding(buildingID); return; }

                Vector3 removedPos = removedNodes[0].Position;
                var removedSet = new HashSet<HelperNavGraph.NavGraphNode>(removedNodes);
                var survivors = new List<HelperNavGraph.NavGraphNode>(sg.Nodes.Count);
                for (int i = 0; i < sg.Nodes.Count; i++)
                    if (!removedSet.Contains(sg.Nodes[i])) survivors.Add(sg.Nodes[i]);

                var oldGraph = sg.Zone.Graph;
                CloneAllNodesWithEdges(survivors, out var cloneMap, out var allClones);
                if (!TryCollectClosure(oldGraph, removedPos, cloneMap, out var closureClones))
                { RebuildSimpleGraphForBuilding(buildingID); return; }

                var closureSet = new HashSet<IAIPathNode>();
                for (int i = 0; i < closureClones.Count; i++) closureSet.Add(closureClones[i]);
                for (int i = 0; i < closureClones.Count; i++) closureClones[i].RemoveEdgesTo(closureSet);

                var allDoorNodes = Pool.Get<List<HelperNavGraph.NavGraphNode>>();
                for (int i = 0; i < allClones.Count; i++)
                    if (IsDoorBarrierNode(allClones[i])) allDoorNodes.Add(allClones[i]);
                int linkObstacleMask = LayerMask.GetMask("Construction", "Deployed");
                int groundSupportMask = LayerMask.GetMask("Construction", "Terrain", "World");
                RelinkNodeSet(closureClones, allDoorNodes, linkObstacleMask, groundSupportMask);
                Pool.FreeUnmanaged(ref allDoorNodes);

                var finalOwner = new Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock>(allClones.Count);
                foreach (var kv in sg.Owner)
                    if (!removedSet.Contains(kv.Key) && cloneMap.TryGetValue(kv.Key, out var oc)) finalOwner[oc] = kv.Value;

                var newGraph = new HelperNavGraph.NavGraph(allClones);
                var relinkHashSet = new HashSet<HelperNavGraph.NavGraphNode>(closureClones);
                newGraph.SeedBridgesIncremental(oldGraph, cloneMap, relinkHashSet);

                sg.Nodes = allClones;
                sg.Owner = finalOwner;
                sg.NodesByBlock = BuildNodesByBlockIndex(finalOwner);
                sg.Zone.Graph = newGraph;
                BumpSimpleGraphVersion(buildingID);
            }

            private static void DestroySimpleGraphForBuilding(uint buildingID)
            {
                if (!_simpleGraphs.TryGetValue(buildingID, out var sg)) return;
                _simpleGraphs.Remove(buildingID);
                if (sg?.Zone != null) UnityEngine.Object.Destroy(sg.Zone.gameObject);
                BumpSimpleGraphVersion(buildingID);
            }

            private static void DestroyAllSimpleGraphs()
            {
                foreach (var kv in _simpleGraphs)
                    if (kv.Value?.Zone != null) UnityEngine.Object.Destroy(kv.Value.Zone.gameObject);
                _simpleGraphs.Clear();
            }

            public static void RegisterSimpleGraphWatch(uint buildingID, object subscriber)
            {
                if (buildingID == 0 || subscriber == null) return;
                if (!_simpleWatch.TryGetValue(buildingID, out var subs)) { subs = new HashSet<object>(); _simpleWatch[buildingID] = subs; }
                bool added = subs.Add(subscriber);
                if (!added && _simpleGraphs.ContainsKey(buildingID)) return;
                RebuildSimpleGraphForBuilding(buildingID);
            }

            [Obsolete((RU ? "Передавай subscriber (обычно this вызывающего плагина) - RegisterSimpleGraphWatch(buildingID, this)" : "Pass subscriber (usually this of the calling plugin) - RegisterSimpleGraphWatch(buildingID, this)"))]
            public static void RegisterSimpleGraphWatch(uint buildingID) => RegisterSimpleGraphWatch(buildingID, _legacyWatchSubscriber);

            public static void UnregisterSimpleGraphWatch(uint buildingID, object subscriber)
            {
                if (subscriber == null || !_simpleWatch.TryGetValue(buildingID, out var subs)) return;
                subs.Remove(subscriber);
                if (subs.Count > 0) return;
                _simpleWatch.Remove(buildingID);
                _simpleRebuildPending.Remove(buildingID);
                DestroySimpleGraphForBuilding(buildingID);
            }

            [Obsolete((RU ? "Передавай subscriber (обычно this вызывающего плагина) - UnregisterSimpleGraphWatch(buildingID, this)" : "Pass subscriber (usually this of the calling plugin) - UnregisterSimpleGraphWatch(buildingID, this)"))]
            public static void UnregisterSimpleGraphWatch(uint buildingID) => UnregisterSimpleGraphWatch(buildingID, _legacyWatchSubscriber);

            public static void UnregisterAllForSubscriber(object subscriber)
            {
                if (subscriber == null) return;
                var affected = Pool.Get<List<uint>>();
                foreach (var kv in _simpleWatch)
                    if (kv.Value.Contains(subscriber)) affected.Add(kv.Key);
                for (int i = 0; i < affected.Count; i++)
                    UnregisterSimpleGraphWatch(affected[i], subscriber);
                Pool.FreeUnmanaged(ref affected);
            }

            public static bool IsSimpleGraphWatched(uint buildingID) => _simpleWatch.ContainsKey(buildingID);
            public static uint FindWatchedBuildingIdNear(Vector3 pos)
            {
                var hits = Physics.OverlapSphere(pos, 2f, LayerMask.GetMask("Construction"), QueryTriggerInteraction.Ignore);
                for (int i = 0; i < hits.Length; i++)
                {
                    if (hits[i].gameObject.ToBaseEntity() is BuildingBlock bb && bb.buildingID != 0 && IsSimpleGraphWatched(bb.buildingID))
                        return bb.buildingID;
                }
                return 0;
            }

            [Obsolete((RU ? "Сносит ВСЕ графы построек, а не только свои подписки - используй UnregisterAllForSubscriber(this)" : "Removes ALL building graphs, not only your subscriptions - use UnregisterAllForSubscriber(this)"))]
            public static void ClearSimpleGraphWatch()
            {
                _simpleWatch.Clear();
                _simpleRebuildPending.Clear();
                DestroyAllSimpleGraphs();
            }

            public static void NoteBlockChange(uint buildingID)
            {
                if (buildingID == 0 || !_simpleWatch.ContainsKey(buildingID)) return;
                _simpleRebuildPending.Add(buildingID);
                ScheduleSimpleGraphFlush();
            }

            public static void NoteBlockChange(uint buildingID, BuildingBlock block, bool isAdd)
            {
                if (buildingID == 0 || block == null) return;
                HelperBuildingNavMesh.MarkDirty(buildingID, block, isAdd);
                if (!_simpleWatch.ContainsKey(buildingID)) return;
                if (!_pendingBlockEvents.Add(block)) return;
                if (!_incrementalPending.TryGetValue(buildingID, out var list)) { list = new List<(BuildingBlock, bool)>(); _incrementalPending[buildingID] = list; }
                list.Add((block, isAdd));
                ScheduleSimpleGraphFlush();
            }

            private static void ScheduleSimpleGraphFlush()
            {
                if (_simpleRebuildScheduled) return;
                _simpleRebuildScheduled = true;
                Interface.Oxide.NextTick(() =>
                {
                    _simpleRebuildScheduled = false;
                    var fullIds = Pool.Get<List<uint>>();
                    var incIds = Pool.Get<List<uint>>();
                    var incJobs = Pool.Get<List<(BuildingBlock block, bool isAdd)>>();
                    try
                    {
                        foreach (var id in _simpleRebuildPending) fullIds.Add(id);
                        foreach (var kv in _incrementalPending)
                        {
                            if (_simpleRebuildPending.Contains(kv.Key)) continue;
                            incIds.Add(kv.Key);
                            incJobs.Add(kv.Value.Count == 1 ? kv.Value[0] : (null, false));
                        }

                        for (int i = 0; i < fullIds.Count; i++)
                            if (_simpleWatch.ContainsKey(fullIds[i])) RebuildSimpleGraphForBuilding(fullIds[i]);
                        for (int i = 0; i < incIds.Count; i++)
                        {
                            uint id = incIds[i];
                            if (!_simpleWatch.ContainsKey(id)) continue;
                            var (block, isAdd) = incJobs[i];
                            if (ReferenceEquals(block, null)) { RebuildSimpleGraphForBuilding(id); continue; }
                            if (isAdd) TryIncrementalAddBlock(id, block); else TryIncrementalRemoveBlock(id, block);
                        }
                    }
                    finally
                    {
                        Pool.FreeUnmanaged(ref fullIds);
                        Pool.FreeUnmanaged(ref incIds);
                        Pool.FreeUnmanaged(ref incJobs);
                        _simpleRebuildPending.Clear();
                        _incrementalPending.Clear();
                        _pendingBlockEvents.Clear();
                    }
                });
            }

            #endregion

            #endregion

            #region Nested classes

            public class SimpleBuildGraph
            {
                public HelperNavGraph.NavGraphZone Zone;
                public List<HelperNavGraph.NavGraphNode> Nodes;
                public Dictionary<HelperNavGraph.NavGraphNode, BuildingBlock> Owner;
                public Dictionary<BuildingBlock, List<HelperNavGraph.NavGraphNode>> NodesByBlock;
            }

            #endregion
        }
    }
    #endregion

