        public static class CoreLog
        {
            [System.Diagnostics.Conditional("__DEBUGLOG_DISABLED__")]
            public static void Log(string source, string message, params object[] args) => Debug.Log<VehicleEventsCore>(Tag(source) + message, args);
            public static void LogWarning(string source, string message, params object[] args) => Debug.LogWarning<VehicleEventsCore>(Tag(source) + message, args);
            public static void LogError(string source, string message, params object[] args) => Debug.LogError<VehicleEventsCore>(Tag(source) + message, args);
            private static string Tag(string source) => string.IsNullOrEmpty(source) ? string.Empty : "[" + source + "] ";
        }

        public sealed class CoreHost
        {
            public CovalencePlugin Plugin { get; internal set; }
            public bool IsWipe;
            public bool IsUnloading { get; internal set; }

            private readonly List<MonoBehaviour> _hosts = new();
            internal List<MonoBehaviour> HostObjects => _hosts;
            private readonly List<Action> _onUnload = new();

            private static Oxide.Core.Libraries.Lang LangLib => Interface.Oxide.GetLibrary<Oxide.Core.Libraries.Lang>();

            internal void RegisterHost(MonoBehaviour host)
            {
                if (host != null && !_hosts.Contains(host)) _hosts.Add(host);
            }
            internal void UnregisterHost(MonoBehaviour host) => _hosts.Remove(host);
            public void OnUnload(Action cleanup)
            {
                if (cleanup != null && !_onUnload.Contains(cleanup)) _onUnload.Add(cleanup);
            }

            internal void Unload()
            {
                IsUnloading = true;
                try
                {
                    List<MonoBehaviour> hosts = new List<MonoBehaviour>(_hosts);
                    _hosts.Clear();
                    for (int i = hosts.Count - 1; i >= 0; i--)
                    {
                        if (hosts[i] == null) continue;
                        try
                        {
                            UnityEngine.Object.DestroyImmediate(hosts[i].gameObject);
                        }
                        catch (Exception ex)
                        {
                            CoreLog.LogError(Plugin?.Name, "Unload: failed to destroy {0}: {1}", hosts[i].GetType().Name, ex);
                        }
                    }
                    EventEntities.KillAll(this);
                }
                catch (Exception ex)
                {
                    CoreLog.LogError(Plugin?.Name, "Core unload: {0}", ex);
                }
                foreach (Action cleanup in _onUnload)
                {
                    try
                    {
                        cleanup();
                    }
                    catch (Exception ex)
                    {
                        CoreLog.LogError(Plugin?.Name, "Unload cleanup: {0}", ex);
                    }
                }
                _onUnload.Clear();

                if (Plugin != null)
                {
                    try
                    {
                        Plugin.ClearAllPooledCollection(out string response);
                        CoreLog.Log(Plugin?.Name, response);
                    }
                    catch (Exception ex)
                    {
                        CoreLog.LogError(Plugin?.Name, "Pool cleanup: {0}", ex);
                    }
                }
                Plugin = null;
            }

            public bool IsAdmin(BasePlayer player) => player != null && (player.IsAdmin || NPCsController.IsAdmin(player.UserIDString));

            public string GetMessage(string key, string userId, params object[] args)
            {
                if (string.IsNullOrEmpty(key)) return key;
                string text = Plugin != null ? LangLib.GetMessage(key, Plugin, userId) : key;
                if (string.IsNullOrEmpty(text)) text = key;
                if (args == null || args.Length == 0) return text;
                try
                {
                    return string.Format(text, args);
                }
                catch (FormatException)
                {
                    return text;
                }
            }
        }

        public static class VehicleCore
        {
            public const string PrefabStash = "assets/prefabs/deployable/small stash/small_stash_deployed.prefab";
            public const string PrefabTurret = "assets/content/props/sentry_scientists/sentry.bandit.static.prefab";
            public const string PrefabParachute = "assets/prefabs/misc/parachute/parachute.prefab";
            public const string PrefabExplosive = "assets/prefabs/tools/c4/explosive.timed.deployed.prefab";
            public const string PrefabBackpack = "assets/prefabs/misc/item drop/item_drop_backpack.prefab";

            private static readonly Dictionary<Type, CoreHost> _hosts = new();
            internal static IEnumerable<CoreHost> AllHosts => _hosts.Values;

            public static CoreHost HostFor(CovalencePlugin plugin) => plugin != null ? HostOfPlugin(plugin.GetType()) : null;
            public static CoreHost HostOf<T>() where T : CovalencePlugin => HostOfPlugin(typeof(T));
            public static CoreHost HostOf(Type type)
            {
                Type plugin = null;
                for (Type current = type; current != null; current = current.DeclaringType)
                    if (typeof(CovalencePlugin).IsAssignableFrom(current)) plugin = current;
                return plugin != null ? HostOfPlugin(plugin) : null;
            }
            private static CoreHost HostOfPlugin(Type pluginType)
            {
                if (!_hosts.TryGetValue(pluginType, out CoreHost host)) _hosts[pluginType] = host = new CoreHost();
                return host;
            }

            public static CoreHost Init(CovalencePlugin plugin)
            {
                CoreHost host = HostFor(plugin);
                if (host == null) return null;
                Type type = plugin.GetType();
                List<Type> stale = Pool.Get<List<Type>>();
                foreach (var pair in _hosts)
                    if (pair.Key != type && pair.Key.FullName == type.FullName && pair.Value.IsUnloading) stale.Add(pair.Key);
                foreach (Type old in stale) _hosts.Remove(old);
                Pool.FreeUnmanaged(ref stale);
                host.Plugin = plugin;
                host.IsUnloading = false;
                return host;
            }

            public static void Unload(CovalencePlugin plugin) => HostFor(plugin)?.Unload();

            public static bool IsRealPlayer(BasePlayer player)
                => player != null && !(player is BaseCustomNpc) && !player.IsNpc && ((ulong)player.userID).IsSteamId();

            #region Спавн сущностей

            public static bool IsSpawnBlocked<TVehicle>(Vector3 position, float radius = 3f) where TVehicle : BaseEntity
            {
                List<TVehicle> found = Pool.Get<List<TVehicle>>();
                Vis.Entities(position, radius, found);
                bool blocked = false;
                foreach (TVehicle entity in found)
                {
                    if (entity == null || entity.IsDestroyed) continue;
                    blocked = true;
                    break;
                }
                Pool.FreeUnmanaged(ref found);
                return blocked;
            }

            public static BaseVehicle SpawnVehicle(string prefab, Vector3 position, Quaternion rotation)
            {
                if (string.IsNullOrEmpty(prefab)) return null;
                BaseEntity entity = GameManager.server.CreateEntity(prefab, position, rotation);
                if (entity == null)
                {
                    Debug.LogError<VehicleEventsCore>("Vehicle not created from prefab [{0}]", prefab);
                    return null;
                }
                BaseVehicle vehicle = entity as BaseVehicle;
                if (vehicle == null)
                {
                    Debug.LogError<VehicleEventsCore>("Prefab [{0}] is not a vehicle", prefab);
                    UnityEngine.Object.Destroy(entity.gameObject);
                    return null;
                }
                vehicle.enableSaving = false;
                vehicle.Spawn();
                return vehicle;
            }

            public static StorageContainer SpawnStash(StashContainerSettings cfg, BaseEntity parent)
            {
                if (cfg == null || parent == null || parent.IsDestroyed) return null;
                StorageContainer stash = GameManager.server.CreateEntity(PrefabStash) as StorageContainer;
                if (stash == null) return null;
                stash.enableSaving = false;
                stash.SetParent(parent, true);
                stash.Spawn();
                stash.transform.localPosition = cfg.offset;
                stash.transform.localRotation = Quaternion.Euler(cfg.rotate);
                stash.dropsLoot = false;
                using (var setFlags = stash.StartSetFlags(BaseEntity.FlagsUpdateMode.SendNetworkUpdate_Flags))
                {
                    setFlags.Set(BaseEntity.Flags.Locked, true);
                }
                if (stash.TryGetComponent<DestroyOnGroundMissing>(out var destroyOnGroundMissing)) UnityEngine.Object.DestroyImmediate(destroyOnGroundMissing);
                if (stash.TryGetComponent<GroundWatch>(out var groundWatch)) UnityEngine.Object.DestroyImmediate(groundWatch);
                stash.SendNetworkUpdateImmediate();
                EventEntities.RegisterStash(stash);
                return stash;
            }

            public static T SpawnTurret<T>(LocalPosition localPosition, BaseEntity parent) where T : BaseTurretController
            {
                if (parent == null || parent.IsDestroyed) return null;
                NPCAutoTurret turret = GameManager.server.CreateEntity(PrefabTurret) as NPCAutoTurret;
                if (turret == null) return null;
                turret.enableSaving = false;
                turret.SetParent(parent, true);
                MeshCollider meshCollider = turret.GetComponentInChildren<MeshCollider>();
                if (meshCollider != null) meshCollider.convex = true;
                turret.Spawn();
                turret.transform.localPosition = localPosition.Offset;
                turret.transform.localRotation = Quaternion.Euler(localPosition.Rotate);
                return turret.gameObject.AddComponent<T>();
            }

            #endregion
        }

        public static class CoreEx
        {
            public static void SortRandom<TSource>(List<TSource> source)
            {
                if (source == null) return;
                for (int i = source.Count - 1; i > 0; i--)
                {
                    int j = UnityEngine.Random.Range(0, i + 1);
                    (source[i], source[j]) = (source[j], source[i]);
                }
            }
            public static T GetRandom<T>(IList<T> source)
            {
                if (source == null || source.Count == 0) return default;
                return source[UnityEngine.Random.Range(0, source.Count)];
            }
            public static string ToKms(float ms) => $"{ms * 3.6f:0} km/h";
            public static string ToStringTime(float seconds)
            {
                if (seconds < 0f) seconds = 0f;
                int total = (int)seconds;
                int d = total / 86400;
                int h = total % 86400 / 3600;
                int m = total % 3600 / 60;
                int s = total % 60;
                return d > 0 ? $"days: {d}   time: {h:00}:{m:00}:{s:00}" : $"{h:00}:{m:00}:{s:00}";
            }
            public static float Distance(List<Vector3> source)
            {
                if (source == null || source.Count <= 1) return 0f;
                float result = 0f;
                for (int i = 1; i < source.Count; i++) result += (source[i] - source[i - 1]).magnitude;
                return result;
            }
            public static float Distance(Vector3[] source)
            {
                if (source == null || source.Length <= 1) return 0f;
                float result = 0f;
                for (int i = 1; i < source.Length; i++) result += (source[i] - source[i - 1]).magnitude;
                return result;
            }
            public static int MinDistanceIndex<TSource>(IEnumerable<TSource> source, Func<TSource, float> selector)
            {
                if (source == null || selector == null) return -1;
                int index = 0, result = -1;
                float best = float.MaxValue;
                foreach (TSource item in source)
                {
                    float value = selector(item);
                    if (result < 0 || value < best)
                    {
                        best = value;
                        result = index;
                    }
                    index++;
                }
                return result;
            }
            public static bool CanChance(NPCsController.MinMax chance, float from, float to) => UnityEngine.Random.Range(from, to) <= chance.GetRandomFloat();
            public static float DistanceFlat(Vector3 a, Vector3 b)
            {
                float x = a.x - b.x, z = a.z - b.z;
                return Mathf.Sqrt(x * x + z * z);
            }
            public static float DistanceFlatToSegment(Vector3 p, Vector3 a, Vector3 b)
            {
                float abx = b.x - a.x, abz = b.z - a.z, length = abx * abx + abz * abz;
                float u = length < 0.0001f ? 0f : Mathf.Clamp01(((p.x - a.x) * abx + (p.z - a.z) * abz) / length);
                float dx = a.x + abx * u - p.x, dz = a.z + abz * u - p.z;
                return Mathf.Sqrt(dx * dx + dz * dz);
            }
            public static bool Alive(object component) => component is UnityEngine.Object unityObject ? unityObject != null : component != null;
            public static float WaterDepth(Vector3 position) => Mathf.Max(0f, WaterSystem.OceanLevel - TerrainMeta.HeightMap.GetHeight(position));
            public const float AirSteerDamping = 0.06f;
            public static float DepthOver(Vector3 ground)
            {
                WaterLevel.WaterInfo water = WaterLevel.GetWaterInfo(ground, false, false);
                return water.isValid ? Mathf.Max(0f, water.surfaceLevel - ground.y) : 0f;
            }

            public static Vector3 GroundPosition(Vector3 position)
            {
                position.y = TerrainMeta.HeightMap.GetHeight(position);
                if (Physics.Raycast(position + Vector3.up * 100f, Vector3.down, out RaycastHit hit, 100f, LayerMask.GetMask("Terrain", "World", "Construction"), QueryTriggerInteraction.Ignore))
                    position = hit.point;
                return position;
            }
            private static readonly Collider[] _safeZoneHits = new Collider[32];
            private static int _triggerMask;
            public static bool InSafeZone(Vector3 point, float radius = 3f)
            {
                if (_triggerMask == 0) _triggerMask = LayerMask.GetMask("Trigger");
                int count = Physics.OverlapSphereNonAlloc(point + Vector3.up, radius, _safeZoneHits, _triggerMask, QueryTriggerInteraction.Collide);
                for (int i = 0; i < count; i++)
                    if (_safeZoneHits[i] != null && _safeZoneHits[i].GetComponent<TriggerSafeZone>() != null) return true;
                return false;
            }
            public static void StartEngineNow(BaseVehicle vehicle)
            {
                if (!(vehicle is PlayerHelicopter heli) || heli.IsDestroyed || heli.engineController == null) return;
                if (heli.engineController.IsOn) return;
                if (vehicle.GetFuelSystem() != null && !vehicle.GetFuelSystem().HasFuel()) return;
                heli.engineController.FinishStartingEngine();
            }
            public static void SetBusy(BaseEntity entity, bool busy)
            {
                if (entity == null || entity.IsDestroyed || entity.HasFlag(BaseEntity.Flags.Busy) == busy) return;
                using (var setFlags = entity.StartSetFlags(BaseEntity.FlagsUpdateMode.SendNetworkUpdate_Flags))
                {
                    setFlags.Set(BaseEntity.Flags.Busy, busy);
                }
            }
        }

        #endregion

        #region VehicleEventsCore: реестр своих сущностей

        public static class EventEntities
        {
            private static readonly Dictionary<ulong, KeyValuePair<BaseVehicle, IEventController>> _vehicles = new();
            private static readonly Dictionary<ulong, BaseTurretController> _turrets = new();
            private static readonly Dictionary<ulong, KeyValuePair<StorageContainer, CoreHost>> _stashes = new();
            private static readonly HashSet<CrewNpc> _crew = new();

            public static bool Owns(CoreHost host, CoreHost owner) => host == null || owner == host;

            public static IEnumerable<CrewNpc> CrewOf(CoreHost host)
            {
                foreach (CrewNpc crew in _crew)
                    if (Owns(host, crew != null ? crew.Host : null)) yield return crew;
            }

            private static ulong Id(BaseNetworkable entity) => entity != null && entity.net != null ? entity.net.ID.Value : 0UL;

            #region Транспорт
            public static void RegisterVehicle(BaseVehicle vehicle, IEventController owner)
            {
                ulong id = Id(vehicle);
                if (id != 0UL && owner != null) _vehicles[id] = new KeyValuePair<BaseVehicle, IEventController>(vehicle, owner);
            }
            public static void UnregisterVehicle(BaseVehicle vehicle, IEventController owner)
            {
                ulong id = Id(vehicle);
                if (id != 0UL && _vehicles.TryGetValue(id, out var pair) && (owner == null || pair.Value == owner)) _vehicles.Remove(id);
            }
            public static bool TryGetVehicleOwner(BaseVehicle vehicle, out IEventController owner, CoreHost host = null)
            {
                owner = null;
                ulong id = Id(vehicle);
                if (id == 0UL || !_vehicles.TryGetValue(id, out var pair) || pair.Key != vehicle || !CoreEx.Alive(pair.Value) || !Owns(host, pair.Value.Host)) return false;
                owner = pair.Value;
                return true;
            }
            public static bool TryGetEvent(BaseEntity entity, out IEventController owner, CoreHost host = null)
            {
                owner = null;
                BaseEntity current = entity;
                for (int depth = 0; depth < 5 && current != null; depth++)
                {
                    ulong id = Id(current);
                    if (id != 0UL && _vehicles.TryGetValue(id, out var pair) && CoreEx.Alive(pair.Value))
                    {
                        if (!Owns(host, pair.Value.Host)) return false;
                        owner = pair.Value;
                        return true;
                    }
                    current = current.GetParentEntity();
                }
                return false;
            }
            public static bool IsEventVehicle(BaseEntity entity, CoreHost host = null) => TryGetEvent(entity, out _, host);
            #endregion

            #region Турели
            internal static void RegisterTurret(BaseTurretController turret)
            {
                ulong id = Id(turret != null ? turret.Owner : null);
                if (id != 0UL) _turrets[id] = turret;
            }
            internal static void UnregisterTurret(BaseTurretController turret, ulong id)
            {
                if (id != 0UL && _turrets.TryGetValue(id, out var registered) && registered == turret) _turrets.Remove(id);
            }
            public static bool TryGetTurret(BaseEntity turret, out BaseTurretController controller, CoreHost host = null)
            {
                controller = null;
                ulong id = Id(turret);
                if (id == 0UL || !_turrets.TryGetValue(id, out BaseTurretController found) || found == null || !Owns(host, found.Host)) return false;
                controller = found;
                return true;
            }
            #endregion

            #region Стеши
            internal static void RegisterStash(StorageContainer stash)
            {
                ulong id = Id(stash);
                if (id == 0UL) return;
                TryGetEvent(stash, out IEventController owner);
                _stashes[id] = new KeyValuePair<StorageContainer, CoreHost>(stash, owner?.Host);
            }
            internal static void UnregisterStash(BaseNetworkable stash, CoreHost host = null)
            {
                ulong id = Id(stash);
                if (id != 0UL && _stashes.TryGetValue(id, out var pair) && Owns(host, pair.Value)) _stashes.Remove(id);
            }
            public static bool IsStash(BaseEntity entity, CoreHost host = null)
            {
                ulong id = Id(entity);
                return id != 0UL && _stashes.TryGetValue(id, out var pair) && pair.Key == entity && Owns(host, pair.Value);
            }
            #endregion

            #region Экипаж
            internal static void AddCrew(CrewNpc crew)
            {
                if (crew != null) _crew.Add(crew);
            }
            internal static void RemoveCrew(CrewNpc crew) => _crew.Remove(crew);
            #endregion

            internal static void KillAll(CoreHost host)
            {
                foreach (CrewNpc crew in new List<CrewNpc>(_crew))
                {
                    if (crew != null && !Owns(host, crew.Host)) continue;
                    _crew.Remove(crew);
                    try
                    {
                        if (crew != null) crew.KillImmediate();
                    }
                    catch (Exception ex)
                    {
                        CoreLog.LogError(host?.Plugin?.Name, "Crew unload: {0}", ex);
                    }
                }

                foreach (var pair in new List<KeyValuePair<ulong, BaseTurretController>>(_turrets))
                {
                    BaseTurretController turret = pair.Value;
                    if (turret != null && !Owns(host, turret.Host)) continue;
                    _turrets.Remove(pair.Key);
                    if (turret != null) turret.KillImmediate();
                }

                foreach (var pair in new List<KeyValuePair<ulong, KeyValuePair<StorageContainer, CoreHost>>>(_stashes))
                {
                    if (!Owns(host, pair.Value.Value)) continue;
                    _stashes.Remove(pair.Key);
                    StorageContainer stash = pair.Value.Key;
                    if (stash != null && !stash.IsDestroyed) stash.Kill();
                }

                foreach (var pair in new List<KeyValuePair<ulong, KeyValuePair<BaseVehicle, IEventController>>>(_vehicles))
                {
                    if (pair.Value.Value != null && !Owns(host, pair.Value.Value.Host)) continue;
                    _vehicles.Remove(pair.Key);
                    BaseVehicle vehicle = pair.Value.Key;
                    if (vehicle == null || vehicle.IsDestroyed) continue;
                    try
                    {
                        vehicle.DismountAllPlayers();
                        vehicle.Kill();
                    }
                    catch (Exception ex)
                    {
                        CoreLog.LogError(host?.Plugin?.Name, "Vehicle unload: {0}", ex);
                    }
                }
            }
        }

        public class EventRun
        {
            public readonly IEventController Owner;
            public readonly CoreHost Host;
            public readonly HashSet<ulong> Attackers = new();
            public bool Active;

            public EventRun(IEventController owner)
            {
                Owner = owner;
                Host = owner?.Host;
                Active = true;
            }

            public bool IsCurrent => Active && CoreEx.Alive(Owner) && Owner.CurrentRun == this;

            public void AddAttacker(BasePlayer player)
            {
                if (VehicleCore.IsRealPlayer(player)) Attackers.Add((ulong)player.userID);
            }
            public bool IsAttacker(BasePlayer player) => player != null && Attackers.Contains((ulong)player.userID);
        }

        public interface IEventController
        {
            CoreHost Host { get; }
            bool HasEvent { get; }
            BaseVehicle Vehicle { get; }
            EventRun CurrentRun { get; }
            bool CanUseNavMesh { get; }
            bool CrewLeavesSafeZone { get; }
            bool CrewWalksOutOfSafeZone { get; }
            BaseVehicleSettings GetSettings();
            BaseEventSettings GetEventSettings();
            void SetTarget(BasePlayer target);
            bool IsTarget(BaseCombatEntity target);
            bool SetCompanionMounted(CrewNpc companion);
            void OnCrewDied(CrewNpc crew);
            void OnVehicleKilled(BaseVehicle vehicle);
        }

        #endregion

        #region VehicleEventsCore: менеджер событий

        public abstract class BaseEventsManager<T> : FacepunchBehaviour, IDiagnosticsReport where T : CovalencePlugin
        {
            public enum ModePath
            {
                Record, Generate
            }

            protected List<ModePath> modePaths = new();
            protected readonly List<BaseEventController<T>> eventControllers = new();
            private readonly List<BasePlayer> admins = new();
            public bool IsPause = false;
            public float timerResume = 0;
            public int index = 0;

            protected abstract int maxEvents { get; }
            public abstract float Cooldown { get; }
            protected abstract Color colorMarker { get; }
            protected abstract int sizeMarker { get; }
            protected float AdminOverlayRate => 0.5f;
            public CoreHost Host => VehicleCore.HostOf<T>();

            public bool IsTestMode => eventControllers.Count == 1 && eventControllers[0] != null && eventControllers[0].IsTestController;

            #region UnityCallbacks
            protected virtual void Awake()
            {
                Host.RegisterHost(this);
            }
            protected virtual void Start()
            {
                timerResume = 5f;
            }
            protected virtual void OnDestroy()
            {
                Host.UnregisterHost(this);
                CancelInvoke(DrawAdminOverlay);
                foreach (BaseEventController<T> controller in new List<BaseEventController<T>>(eventControllers))
                {
                    if (controller != null) controller.ShutdownEvent();
                }
                eventControllers.Clear();
                admins.Clear();
            }
            #endregion

            #region Methods
            public void AddController(BaseEventController<T> eventController)
            {
                if (eventController != null && !eventControllers.Contains(eventController)) eventControllers.Add(eventController);
            }
            public void RemoveController(BaseEventController<T> eventController) => eventControllers.Remove(eventController);
            int IDiagnosticsReport.AppendDiagnostics(System.Text.StringBuilder sb)
            {
                ReportLine(sb, "  manager {0}: paused {1}, events {2} (max {3}), restart delay {4:0} s, route modes {5}", GetType().Name, IsPause ? "yes" : "no",
                    eventControllers.Count, maxEvents, Cooldown, modePaths.Count > 0 ? string.Join(", ", modePaths) : "none");
                int active = 0;
                foreach (BaseEventController<T> controller in eventControllers)
                    if (controller is IDiagnosticsReport report) active += report.AppendDiagnostics(sb);
                return active;
            }
            public void StartPause()
            {
                if (IsPause) return;
                IsPause = true;
                timerResume = 0;
                foreach (BaseEventController<T> controller in eventControllers) controller.OnPause();
            }
            public void StopPause()
            {
                if (!IsPause) return;
                IsPause = false;
                foreach (BaseEventController<T> controller in eventControllers) controller.OnResume();
            }
            public ModePath GetTypePath() => CoreEx.GetRandom(modePaths);
            public bool HasTypePath => modePaths.Count > 0;

            public void AdminCommand(IPlayer iPlayer, string command, string[] args, string visibleCommand, string testCommand)
            {
                BasePlayer admin = iPlayer?.Object as BasePlayer;
                CoreHost host = VehicleCore.HostOf<T>();
                if (admin == null || !admin.IsConnected || host == null || !host.IsAdmin(admin)) return;
                if (command == visibleCommand)
                {
                    SetAdminControl(admin);
                    return;
                }
                if (command != testCommand) return;
                string arg = args == null || args.Length == 0 ? "" : args[0];
                if (arg == "start") CreateTestEvent(admin);
                else if (arg == "stop") StopTestEvent(admin);
            }
            public void CreateTestEvent(BasePlayer admin)
            {
                if (admin == null) return;
                if (IsTestMode && !eventControllers[0].IsInitiator(admin))
                {
                    admin.ChatMessage(Host.GetMessage("HasTestEventOtherAdmin", admin.UserIDString));
                    return;
                }
                if (!HasTypePath)
                {
                    admin.ChatMessage(Host.GetMessage("NoRouteModes", admin.UserIDString));
                    Debug.LogWarning<T>("Test event not created: both recorded routes and route generation are disabled");
                    return;
                }
                RemoveAllEvents();
                Interface.Oxide.CallHook("OnTestModeEvent", admin);
                if (!admins.Contains(admin)) admins.Add(admin);
                EnsureOverlay();
                timerResume = 5f;
                SpawnTestEvent(admin);
            }
            protected abstract void SpawnTestEvent(BasePlayer admin);
            public void StopTestEvent(BasePlayer admin)
            {
                if (admin == null) return;
                if (IsTestMode && eventControllers[0].IsInitiator(admin))
                {
                    RemoveAdminControl(admin);
                    RemoveAllEvents();
                    Start();
                }
            }
            protected void RemoveAllEvents()
            {
                foreach (BaseEventController<T> eventController in new List<BaseEventController<T>>(eventControllers))
                {
                    if (eventController != null) DestroyImmediate(eventController);
                }
                eventControllers.Clear();
            }
            protected void CreateEvents<T2>(int num, BasePlayer admin = null) where T2 : BaseEventController<T>
            {
                if (!HasTypePath)
                {
                    Debug.LogWarning<T>("Events not created: both recorded routes and route generation are disabled");
                    return;
                }
                for (index = 0; index < num; index++)
                {
                    T2 eventController = gameObject.AddComponent<T2>();
                    eventController.InitEventController(index + 1, admin);
                }
            }
            public void SetAdminControl(BasePlayer admin)
            {
                if (admin == null) return;
                if (admins.Contains(admin)) RemoveAdminControl(admin);
                else
                {
                    admins.Add(admin);
                    EnsureOverlay();
                }
            }
            public void RemoveAdminControl(BasePlayer admin) => admins.Remove(admin);
            #endregion

            #region AdminOverlay
            private void EnsureOverlay()
            {
                if (admins.Count > 0 && !IsInvoking(DrawAdminOverlay)) InvokeRepeating(DrawAdminOverlay, 0f, AdminOverlayRate);
            }
            private void DrawAdminOverlay()
            {
                if (admins.Count == 0)
                {
                    CancelInvoke(DrawAdminOverlay);
                    return;
                }
                float timer = AdminOverlayRate;
                for (int i = admins.Count - 1; i >= 0; i--)
                {
                    BasePlayer admin = admins[i];
                    if (admin == null || !admin.IsConnected)
                    {
                        admins.RemoveAt(i);
                        continue;
                    }
                    try
                    {
                        foreach (CrewNpc bot in EventEntities.CrewOf(Host))
                        {
                            if (bot == null || !bot.IsAlive() || bot.isMounted) continue;
                            string text = $"<size={sizeMarker}>[{bot.userID}] - {(bot.IsDriver ? "driver" : "companion")} (health={bot.health:0})";
                            if (bot.HasTimedKill()) text += $"\ntimed kill ({bot.GetTimerKill():0})";
                            text += "</size>";
                            SendDrawText(admin, text, bot.transform.position + Vector3.up * 3f, Color.yellow, timer);
                        }
                    }
                    catch (Exception ex)
                    {
                        Debug.LogError<T>("Admin overlay: {0}", ex.Message);
                    }
                }
            }
            public void SendInfoEvent(BaseEventController<T> pluginEvent, string nameEvent, string typeEvent, float timer)
            {
                if (admins.Count == 0 || pluginEvent == null) return;
                foreach (BasePlayer admin in admins)
                {
                    if (admin == null || !admin.IsConnected) continue;
                    Vector3 position = pluginEvent.Vehicle != null ? pluginEvent.Vehicle.transform.position : Vector3.zero;
                    string text = $"<size={sizeMarker}>{nameEvent} #{pluginEvent.number}\n";
                    text += $"[{typeEvent}(id={pluginEvent.VehicleId}, life time={(pluginEvent.HasEvent ? CoreEx.ToStringTime(pluginEvent.LifeTime) : "--")}, distance={(position == Vector3.zero ? "--" : admin.Distance(position).ToString("0"))})]\n";
                    CrewNpc driver = pluginEvent.DriverBot;
                    if (driver != null && driver.IsAlive()) text += $"driver [userid={driver.userID}, health={driver.health:0}]\n";
                    if (pluginEvent.IsChasing && pluginEvent.ChaseTarget != null) text += $"chase: {pluginEvent.ChaseTarget.displayName}\n";
                    text += "</size>";
                    SendDrawText(admin, text, position + Vector3.up * 3f, colorMarker, timer);
                }
            }
            public void SendInfoExplosive(BaseEventController<T> pluginEvent, string nameEvent, float timer)
            {
                if (admins.Count == 0 || pluginEvent == null || !pluginEvent.HasExplosive) return;
                foreach (BasePlayer admin in admins)
                {
                    if (admin == null || !admin.IsConnected) continue;
                    string text = $"<size={sizeMarker}>{nameEvent} #{pluginEvent.number}\nTime Explode [{pluginEvent.GetTimerExplode():0}]</size>";
                    SendDrawText(admin, text, pluginEvent.Explosive.transform.position + Vector3.up * 3f, colorMarker, timer);
                }
            }
            public static void SendDrawText(BasePlayer admin, string text, Vector3 position, Color color, float timer)
            {
                if (admin == null || string.IsNullOrEmpty(text)) return;
                bool isAdmin = admin.IsAdmin;
                if (!isAdmin) admin.SetPlayerFlag(BasePlayer.PlayerFlags.IsAdmin, true);
                try
                {
                    admin.SendConsoleCommand("ddraw.text", timer, color, position, text);
                }
                finally
                {
                    if (!isAdmin) admin.SetPlayerFlag(BasePlayer.PlayerFlags.IsAdmin, false);
                }
            }
            #endregion

            #region StaticMethods
            public static T2 CreateManager<T2>() where T2 : BaseEventsManager<T> => new GameObject("EventsManager").AddComponent<T2>();
            #endregion
        }

        #endregion

        #region VehicleEventsCore: контроллер события

        public abstract class BaseEventController<T> : FacepunchBehaviour, IEventController, IDiagnosticsReport where T : CovalencePlugin
        {
            public enum RouteMode
            {
                None, Points
            }

            protected BaseEventsManager<T> eventManager;
            protected TestUIInfo testUIInfo;
            protected BasePlayer admin;
            protected BaseEventsManager<T>.ModePath modePath;

            #region EventVariable
            public BaseVehicle Vehicle { get; protected set; }
            public HelperVehicles.VehicleControllerBase Pilot { get; protected set; }
            protected IFuelSystem fuelSystem;
            protected BaseMountable mountableDriver;
            protected readonly List<BaseMountable> mountablePassenger = new();
            public CrewNpc DriverBot { get; protected set; }
            protected readonly List<CrewNpc> CompanionBot = new();
            public TimedExplosive Explosive { get; protected set; }
            public readonly List<NPCAutoTurret> Turrets = new();
            protected IItemContainerEntity storage;
            public EventRun CurrentRun { get; private set; }
            #endregion

            #region Route
            protected Vector3[] path;
            protected RouteMode routeMode = RouteMode.None;
            private int _routeDir = 1;
            private int _windowStart;
            private int _windowEnd;
            private readonly List<Vector3> _window = new();
            #endregion

            #region Chase
            private readonly List<BasePlayer> _targets = new();
            protected BasePlayer currentTarget;
            private float _lastAttackedAt = -10000f;
            private bool _chasing;
            #endregion

            private const float timerUpdateInfo = 0.25f;
            public int number;
            public bool HasEvent { get; private set; }
            private float _startedAt;
            private float _explosiveAt;
            private float _waitingSince;
            private int _retakeAttempts;
            private Vector3 _retakePos;
            private int _retakeRescues;
            private Coroutine _boarding;
            private bool _vehicleDying;
            private bool _shutdown;
            private readonly List<BaseVehicle> _detonated = new();
            internal int PilotRetakes { get; private set; }
            private string _stopReason;
            private const string PauseStopReason = "events paused";

            #region Properties
            public bool IsTestController => admin != null;
            public bool HasExplosive => Explosive != null && !Explosive.IsDestroyed;
            public bool IsChasing => _chasing;
            public BasePlayer ChaseTarget => currentTarget;
            public float LifeTime => HasEvent ? UnityEngine.Time.time - _startedAt : 0f;
            public ulong VehicleId => Vehicle != null && Vehicle.net != null ? Vehicle.net.ID.Value : 0UL;
            public CoreHost Host => VehicleCore.HostOf<T>();
            protected bool isInitController => eventManager != null;
            protected bool IsHumanPowered => fuelSystem is HumanFuelSystem;
            protected virtual bool canEngineStart => Vehicle != null && Vehicle.Health() > 0f;

            protected abstract string NameEvent { get; }
            public abstract string TypeEvent { get; }
            protected abstract string NameDriverID { get; }
            protected abstract string[] NamesCompanionID { get; }
            protected abstract CrewSettings Crew { get; }
            protected abstract float RouteSpeedKmh { get; }
            protected abstract BaseVehicleSettings.BaseTargetSettings ChaseSettings { get; }

            protected bool DestroyEventsFromPause => GetEventSettings()?.destroyEventsFromPause ?? true;
            public bool BlockAttackedToNpcEvents => GetEventSettings()?.blockAttackedToNpcEvents ?? true;
            protected virtual bool isAutoFuel => GetSettings()?.fuel?.autoFuel ?? true;
            protected bool removeFuel => GetSettings()?.fuel?.removeFuel ?? true;
            protected int levelFuel => GetSettings()?.fuel?.levelFuel ?? 500;
            protected bool canUseExplosive => GetSettings()?.detonator?.enableDetonator ?? false;
            protected float fuseExplosive => GetSettings()?.detonator?.timer ?? 60f;
            protected Vector3 offsetExplosive => GetSettings()?.detonator?.offset ?? new Vector3(0f, 0.8f, 0f);
            protected virtual bool enableHeadlights => GetSettings()?.Headlights?.enableHeadlights ?? false;
            protected virtual bool headlightsOnlyAtNightMode => GetSettings()?.Headlights?.onlyAtNightMode ?? true;
            protected virtual float timerDelayedInitVehicle => 0f;
            protected virtual bool giveParachute => false;
            public virtual ulong SkinParachute => 0UL;
            public virtual bool CanUseNavMesh => true;
            public bool CrewLeavesSafeZone => true;
            public bool CrewWalksOutOfSafeZone => true;
            public virtual bool CanDisableTurretToEndEvent => false;
            protected int MinPathPoints => 2;
            protected int RouteWindow => 8;
            protected float RouteWindowLength => 150f;
            protected float RouteWindowLead => 60f;
            protected float ChaseStraightDistance => 120f;
            protected virtual float ChaseKeepDistance => 0f;
            protected float RejoinPlanDistance => 40f;
            protected virtual float ChaseSpeedKmh => RouteSpeedKmh;
            protected virtual float RouteAltitude => 0f;
            protected virtual float ChaseAltitude => RouteAltitude;
            protected virtual float RouteAltitudeBand => 0f;
            protected virtual float ChaseAltitudeBand => 0f;
            protected virtual bool BlockAnyNonPlayerDamage => false;
            protected float ChaseAttackDistance => 5f;
            protected bool ChaseEnabled => ChaseSettings != null && ChaseSettings.Enable;
            protected bool isAggressionTime => ChaseSettings != null && UnityEngine.Time.time - _lastAttackedAt < ChaseSettings.TimerAggression;
            #endregion

            #region AbstractMethods
            protected abstract void SetSettingsVehicle();
            protected abstract BaseVehicle SpawnVehicle();
            protected abstract HelperVehicles.VehicleControllerBase AddPilot(CrewNpc driver);
            protected abstract void InitStorage();
            public abstract BaseVehicleSettings GetSettings();
            public abstract BaseEventSettings GetEventSettings();
            #endregion

            #region VirtualMethods
            protected virtual void OnEmptyFuel() => EndEvent();
            protected virtual void GeneratePath()
            {
                KillEventImmediate();
                StartEventToTimer(10f);
            }
            public virtual void InitRouter()
            {
                switch (modePath)
                {
                    case BaseEventsManager<T>.ModePath.Record:
                        CreateEvent();
                        return;
                    case BaseEventsManager<T>.ModePath.Generate:
                        GeneratePath();
                        return;
                    default:
                        KillEventImmediate();
                        StartEventToTimer(10f);
                        return;
                }
            }
            protected bool CanUseSeat(BaseMountable seat) => seat != null;
            protected virtual void OnEventStarted() { }
            protected virtual void OnEventStopped() { }
            protected virtual void OnEventStopped(BaseVehicle vehicle) => OnEventStopped();
            protected virtual void OnVehicleKilling(BaseVehicle vehicle) { }
            protected virtual void OnChaseAttack(BasePlayer target) { }
            protected virtual void OnTickEvent() { }
            protected virtual void OnRouteFinished()
            {
                _routeDir = -_routeDir;
                if (TurnsWhereStopped && Pilot != null && Pilot.Arrived && Vehicle != null && path != null && path.Length > 1
                    && CoreEx.DistanceFlat(Vehicle.transform.position, path[_windowEnd]) > EarlyEndDistance)
                {
                    Vector3 position = Vehicle.transform.position;
                    int index = ResumeIndex(position, out _, out _);
                    while (index + _routeDir >= 0 && index + _routeDir < path.Length && CoreEx.DistanceFlat(path[index], position) < EarlyEndDistance) index += _routeDir;
                    FollowFrom(index);
                    return;
                }
                FollowFrom(_windowEnd);
            }
            private const float EarlyEndDistance = 10f;
            protected virtual bool TurnsWhereStopped => false;
            protected virtual bool IsValidChaseTarget(BasePlayer player)
            {
                if (player == null || !player.IsValid() || !player.IsAlive() || !player.IsConnected || player.IsSleeping()) return false;
                if (player.InSafeZone()) return false;
                if (Vehicle == null || ChaseSettings == null) return false;
                return Vector3.Distance(Vehicle.transform.position, player.transform.position) <= ChaseSettings.DistanceAggression;
            }
            #endregion

            #region UnityCallbacks
            protected virtual void Awake() { }
            protected virtual void OnDestroy()
            {
                ShutdownEvent();
            }
            #endregion

            #region Methods
            public void InitEventController(int number, BasePlayer admin)
            {
                this.number = number;
                this.admin = admin;
                if (admin != null) testUIInfo = new TestUIInfo(admin);
                eventManager = GetComponent<BaseEventsManager<T>>();
                if (isInitController)
                {
                    eventManager.AddController(this);
                    StartEventToTimer(eventManager.timerResume);
                    eventManager.timerResume += 5f;
                    _waitingSince = UnityEngine.Time.time;
                    InvokeRepeating(InfoEventUpdate, 0f, timerUpdateInfo);
                }
                else
                {
                    Debug.LogWarning<T>("{0} #{1} not initialized: no event manager", NameEvent, number);
                    Destroy(this);
                }
            }
            public void ShutdownEvent()
            {
                if (_shutdown) return;
                _shutdown = true;
                CancelInvoke(InfoEventUpdate);
                if (eventManager != null) eventManager.RemoveController(this);
                testUIInfo?.Destroy();
                testUIInfo = null;
                _stopReason = Host.IsUnloading ? "plugin unloading" : "event controller removed";
                KillEventImmediate();
                if (Host.IsUnloading)
                {
                    foreach (BaseVehicle vehicle in _detonated)
                    {
                        if (vehicle != null && !vehicle.IsDestroyed) vehicle.Kill();
                    }
                }
                _detonated.Clear();
            }
            protected void StartEventToTimer(float timer)
            {
                if (_shutdown || Host.IsUnloading) return;
                if (IsInvoking(InvokeStart)) CancelInvoke(InvokeStart);
                Invoke(InvokeStart, Mathf.Max(0.1f, timer));
                _waitingSince = UnityEngine.Time.time;
            }
            protected void SetPath(Vector3[] points)
            {
                path = points;
                routeMode = points != null && points.Length > 0 ? RouteMode.Points : RouteMode.None;
            }
            private bool HasRoute()
            {
                if (routeMode == RouteMode.None && path != null && path.Length > 0) routeMode = RouteMode.Points;
                switch (routeMode)
                {
                    case RouteMode.Points: return path != null && path.Length >= Mathf.Max(1, MinPathPoints);
                    default: return false;
                }
            }
            protected void CreateEvent()
            {
                if (_shutdown) return;
                if (!HasRoute())
                {
                    KillEventImmediate();
                    StartEventToTimer(10f);
                    return;
                }
                BaseVehicle vehicle = null;
                try
                {
                    vehicle = SpawnVehicle();
                }
                catch (Exception ex)
                {
                    Debug.LogError<T>("SpawnVehicle [{0} #{1}]: {2}", NameEvent, number, ex);
                }
                if (vehicle == null || vehicle.IsDestroyed)
                {
                    KillEventImmediate();
                    StartEventToTimer(10f);
                    return;
                }
                Vehicle = vehicle;
                _vehicleDying = false;
                CurrentRun = new EventRun(this);
                EventEntities.RegisterVehicle(Vehicle, this);
                if (timerDelayedInitVehicle > 0f) Invoke(InitVehicle, timerDelayedInitVehicle);
                else InitVehicle();
            }
            protected virtual void InitVehicle()
            {
                if (Vehicle == null || Vehicle.IsDestroyed)
                {
                    KillEventImmediate();
                    StartEventToTimer(10f);
                    return;
                }
                HasEvent = true;
                _startedAt = UnityEngine.Time.time;
                _retakeAttempts = 0;
                _retakeRescues = 0;
                PilotRetakes = 0;
                _retakePos = Vehicle.transform.position;
                mountableDriver = null;
                mountablePassenger.Clear();
                try
                {
                    InitMountPoints();
                }
                catch (Exception ex)
                {
                    Debug.LogError<T>("InitMountPoints [{0} #{1}]: {2}", NameEvent, number, ex);
                    KillEventImmediate();
                    StartEventToTimer(10f);
                    return;
                }
                if (mountableDriver == null)
                {
                    Debug.LogError<T>("Vehicle {0} has no driver seat [{1} #{2}]", Vehicle.ShortPrefabName, NameEvent, number);
                    KillEventImmediate();
                    StartEventToTimer(10f);
                    return;
                }

                fuelSystem = Vehicle.GetFuelSystem();
                if (fuelSystem != null && !IsHumanPowered)
                {
                    int num = fuelSystem.GetFuelAmount();
                    if (num > 0) fuelSystem.RemoveFuel(num);
                    fuelSystem.AddFuel(levelFuel);
                }
                if (enableHeadlights) InvokeRepeating(CheckHeadlights, 1f, 5f);
                try
                {
                    InitStorage();
                }
                catch (Exception ex)
                {
                    Debug.LogError<T>("InitStorage [{0} #{1}]: {2}", NameEvent, number, ex);
                }
                InitBots();
                StopBoarding();
                _boarding = StartCoroutine(BoardCrew(CurrentRun));
            }
            protected virtual void InitMountPoints()
            {
                foreach (BaseVehicle.MountPointInfo mount in Vehicle.allMountPoints) RegisterMountPoint(mount);
            }
            protected void RegisterMountPoint(BaseVehicle.MountPointInfo mount)
            {
                if (mount == null || mount.mountable == null) return;
                CoreEx.SetBusy(mount.mountable, true);
                if (mount.isDriver)
                {
                    if (mountableDriver == null) mountableDriver = mount.mountable;
                }
                else if (CanUseSeat(mount.mountable) && !mountablePassenger.Contains(mount.mountable))
                {
                    if (mount.mountable is PTBoatTurret) mountablePassenger.Insert(0, mount.mountable);
                    else mountablePassenger.Add(mount.mountable);
                }
            }
            protected void InitBots()
            {
                CreateDriver();
                CreateCompanions();
            }
            protected void CreateDriver()
            {
                if (!TryGetDriverSettings(NameDriverID, out DriverSettings driverSettings))
                {
                    Debug.LogError<T>("Driver settings not found for key [{0}]", NameDriverID);
                    return;
                }
                DriverBot = SpawnCrew(driverSettings, true, ResolveLoots(driverSettings));
                if (DriverBot == null) Debug.LogError<T>("Driver not created for key [{0}]", NameDriverID);
            }
            protected void CreateCompanions()
            {
                if (mountablePassenger.Count == 0 || NamesCompanionID == null || NamesCompanionID.Length == 0) return;
                List<string> keys = new List<string>();
                List<CompanionSettings> presets = new List<CompanionSettings>();
                foreach (string name in NamesCompanionID)
                {
                    if (string.IsNullOrEmpty(name) || keys.Contains(name)) continue;
                    if (TryGetCompanionSettings(name, out CompanionSettings companion))
                    {
                        keys.Add(name);
                        presets.Add(companion);
                    }
                    else Debug.LogError<T>("Companion settings not found for key [{0}]", name);
                }
                for (int i = 0; i < mountablePassenger.Count && i < presets.Count; i++)
                {
                    CrewNpc companion = SpawnCrew(presets[i], false, ResolveLoots(presets[i]));
                    if (companion != null) CompanionBot.Add(companion);
                    else Debug.LogError<T>("Companion not created for key [{0}]", keys[i]);
                }
            }
            protected List<LootInfo> ResolveLoots(CompanionSettings settings)
            {
                List<LootInfo> loots = null;
                string nameLoot = settings?.Loots != null && settings.Loots.enableLoot ? CoreEx.GetRandom(settings.Loots.NameContainerID) : null;
                if (!string.IsNullOrEmpty(nameLoot) && TryGetBootLoots(nameLoot, out List<LootInfo> found)) loots = found;
                if ((loots == null || loots.Count == 0) && settings?.Loots != null && settings.Loots.enableLoot)
                    Debug.LogWarning<T>("Loot list is empty for key [{0}]", nameLoot);
                return loots ?? new List<LootInfo>();
            }
            protected CrewNpc SpawnCrew(CompanionSettings settings, bool isDriver, List<LootInfo> loots)
            {
                if (settings == null || Vehicle == null) return null;
                Vector3 position = Vehicle.transform.position + Vector3.up * 1.5f;
                CrewNpc bot = BaseCustomNpc.CreateCustomPlayer<CrewNpc, CrewBrain, NavigatorNpc>(new CrewConfig(settings), position, Vehicle.transform.rotation);
                if (bot == null) return null;
                bot.Spawn();
                if (!bot.IsValid() || bot.IsDestroyed) return null;
                bot.Setup(CurrentRun, settings, isDriver, loots, GetEventSettings());
                bot.BlockAnyNonPlayerDamage = BlockAnyNonPlayerDamage;
                bot.TargetableByNpcs = !BlockAttackedToNpcEvents;
                return bot;
            }
            protected bool TryGetDriverSettings(string name, out DriverSettings settings)
            {
                settings = null;
                return !string.IsNullOrEmpty(name) && Crew?.Drivers != null && Crew.Drivers.TryGetValue(name, out settings) && settings != null;
            }
            protected bool TryGetCompanionSettings(string name, out CompanionSettings settings)
            {
                settings = null;
                return !string.IsNullOrEmpty(name) && Crew?.Companions != null && Crew.Companions.TryGetValue(name, out settings) && settings != null;
            }
            protected bool TryGetBootLoots(string name, out List<LootInfo> loots)
            {
                loots = null;
                return !string.IsNullOrEmpty(name) && Crew?.Loots != null && Crew.Loots.TryGetValue(name, out loots) && loots != null;
            }
            protected void FillStorageLoot(StorageContainer container, BaseStorageLoot cfg)
            {
                if (container == null || container.inventory == null || cfg == null) return;
                container.dropsLoot = cfg.CanDropLoots;
                if (cfg.enableLoot && cfg.NameContainerID != null)
                {
                    string name = CoreEx.GetRandom(cfg.NameContainerID);
                    if (!string.IsNullOrEmpty(name) && TryGetBootLoots(name, out List<LootInfo> loots))
                    {
                        if (loots.Count == 0) Debug.LogWarning<T>("Loot list is empty for key [{0}]", name);
                        else
                        {
                            container.inventory.capacity = Mathf.Max(1, cfg.capacity);
                            int num = 0;
                            foreach (LootInfo loot in loots)
                            {
                                if (num >= cfg.capacity) break;
                                if (loot != null && loot.AddLootToContainerFromChance(container.inventory)) num++;
                            }
                        }
                    }
                }
                if (!container.inventory.IsLocked()) container.inventory.SetLocked(true);
                if (container.IsLocked())
                {
                    using (var setFlags = container.StartSetFlags(BaseEntity.FlagsUpdateMode.SendNetworkUpdate_Flags))
                    {
                        setFlags.Set(BaseEntity.Flags.Locked, false);
                    }
                }
            }
            #endregion

            #region Boarding
            private void StopBoarding()
            {
                if (_boarding != null)
                {
                    StopCoroutine(_boarding);
                    _boarding = null;
                }
            }
            private bool CrewReady(CrewNpc bot) => bot == null || !bot.IsAlive() || bot.IsDestroyed || bot.IsInitBot;
            private IEnumerator BoardCrew(EventRun run)
            {
                float deadline = UnityEngine.Time.time + 5f;
                while (UnityEngine.Time.time < deadline)
                {
                    yield return CoroutineEx.waitForSeconds(0.1f);
                    if (run != CurrentRun || !HasEvent) yield break;
                    bool ready = CrewReady(DriverBot);
                    for (int i = 0; ready && i < CompanionBot.Count; i++) ready = CrewReady(CompanionBot[i]);
                    if (ready) break;
                }
                _boarding = null;
                if (run != CurrentRun || !HasEvent) yield break;
                try
                {
                    OnBoard();
                }
                catch (Exception ex)
                {
                    Debug.LogError<T>("Crew boarding [{0} #{1}]: {2}", NameEvent, number, ex);
                    KillEventImmediate();
                    StartEventToTimer(10f);
                }
            }
            protected void OnBoard()
            {
                if (Vehicle == null || Vehicle.IsDestroyed)
                {
                    KillEventImmediate();
                    StartEventToTimer(10f);
                    return;
                }
                if (DriverBot == null || !DriverBot.IsAlive() || DriverBot.IsDestroyed || !DriverBot.IsInitBot || !TakeControl())
                {
                    _stopReason = "driver did not take the wheel";
                    KillEventImmediate();
                    StartEventToTimer(10f);
                    return;
                }
                DriverBot.OnBoarded();
                foreach (CrewNpc companion in new List<CrewNpc>(CompanionBot))
                {
                    if (companion == null || !companion.IsAlive()) continue;
                    if (!companion.IsInitBot || !MountCompanion(companion))
                        Debug.Log<T>("Companion {0} did not board the vehicle [{1} #{2}] - goes on foot", Debug.Id(companion), NameEvent, number);
                    companion.OnBoarded();
                }
                if (fuelSystem != null) InvokeRepeating(CheckFuel, 2f, 2f);
                StartRoute();
                InvokeRepeating(TickEvent, 0.25f, 0.25f);
                Invoke(CheckEvent, 1f);
                try
                {
                    OnEventStarted();
                }
                catch (Exception ex)
                {
                    Debug.LogError<T>("OnEventStarted [{0} #{1}]: {2}", NameEvent, number, ex);
                }
                BlackBox.NoteEvent(typeof(T).Name, BlackBoxKind.EventStart, NameEvent, number, null, Vehicle, 0f);
            }
            private bool TakeControl()
            {
                if (Pilot != null) return true;
                if (DriverBot == null || !DriverBot.IsAlive() || Vehicle == null || Vehicle.IsDestroyed) return false;
                if (mountableDriver != null) CoreEx.SetBusy(mountableDriver, false);
                HelperVehicles.VehicleControllerBase pilot = null;
                try
                {
                    pilot = AddPilot(DriverBot);
                }
                catch (Exception ex)
                {
                    Debug.LogError<T>("AddPilot [{0} #{1}]: {2}", NameEvent, number, ex);
                }
                if (pilot == null)
                {
                    Debug.LogError<T>("Plugin did not provide a pilot for {0} [{1} #{2}]", Vehicle.ShortPrefabName, NameEvent, number);
                    return false;
                }
                string error = pilot.Take(DriverBot, Vehicle);
                if (error != null)
                {
                    Destroy(pilot);
                    return false;
                }
                DriverBot.EquipWeapon(-1);
                Pilot = pilot;
                ApplyPilotMode();
                return true;
            }
            protected virtual bool MountCompanion(CrewNpc companion)
            {
                if (companion == null || !companion.IsAlive() || companion.IsDestroyed) return false;
                if (companion.isMounted) return true;
                if (Vehicle == null || Vehicle.IsDestroyed) return false;
                foreach (BaseMountable seat in mountablePassenger)
                {
                    if (seat == null || seat.IsDestroyed || seat.GetMounted() != null) continue;
                    companion.navigator?.Pause();
                    CoreEx.SetBusy(seat, false);
                    seat.MountPlayer(companion);
                    if (companion.GetMounted() == seat)
                    {
                        companion.CanDismount = false;
                        if (!CompanionBot.Contains(companion)) CompanionBot.Add(companion);
                        return true;
                    }
                    CoreEx.SetBusy(seat, true);
                }
                return false;
            }
            public virtual bool SetCompanionMounted(CrewNpc companion)
            {
                if (!HasEvent || Pilot == null || Vehicle == null || Vehicle.IsDestroyed) return false;
                return MountCompanion(companion);
            }
            #endregion

            #region Route & Chase
            protected virtual void ApplyPilotMode()
            {
                if (!(Pilot is IEventPilot eventPilot)) return;
                eventPilot.SpeedMs = Mathf.Max(1f, (_chasing ? ChaseSpeedKmh : RouteSpeedKmh) / 3.6f);
                bool chaseAltitude = _chasing && ChaseAltitude > 0f;
                float altitude = chaseAltitude ? ChaseAltitude : RouteAltitude;
                eventPilot.Altitude = Mathf.Max(0f, altitude);
                float band = chaseAltitude ? ChaseAltitudeBand : RouteAltitudeBand;
                if (Pilot is EventAirPilot air) air.AltitudeBand = band;
                else if (Pilot is EventAttackHeliPilot attack) attack.AltitudeBand = band;
            }
            protected void StartRoute()
            {
                if (Pilot == null) return;
                switch (routeMode)
                {
                    case RouteMode.Points:
                        _routeDir = 1;
                        FollowFrom(0);
                        return;
                }
            }
            protected virtual Vector3 RoutePoint(int index, int dir) => path[index];
            protected virtual bool PathByRoad => false;
            protected virtual Vector2 RouteMargin(int index, int dir) => NoMargin;
            private static readonly Vector2 NoMargin = new Vector2(-1f, -1f);
            private readonly List<Vector2> _windowMargins = new();
            private void FollowFrom(int index)
            {
                if (Pilot == null || path == null || path.Length == 0) return;
                int count = path.Length;
                index = Mathf.Clamp(index, 0, count - 1);
                _window.Clear();
                _windowMargins.Clear();
                _windowStart = index;
                _windowEnd = index;
                int size = Mathf.Max(2, RouteWindow);
                float length = 0f;
                for (int i = index; i >= 0 && i < count && (_window.Count < size || length < RouteWindowLength); i += _routeDir)
                {
                    Vector3 point = RoutePoint(i, _routeDir);
                    if (_window.Count > 0) length += CoreEx.DistanceFlat(_window[_window.Count - 1], point);
                    _window.Add(point);
                    _windowMargins.Add(RouteMargin(i, _routeDir));
                    _windowEnd = i;
                }
                if (Pilot is IEventPilot eventPilot) eventPilot.SetPolyline(null);
                Pilot.SetRoute(_window, 0f, true, PathByRoad);
                if (Pilot is EventGroundPilot ground) ground.SetRouteMargins(_windowMargins);
            }
            private void ExtendWindow()
            {
                int count = path.Length;
                int start = _windowEnd + _routeDir;
                if (start < 0 || start >= count) return;
                List<Vector3> next = new List<Vector3>();
                List<Vector2> margins = new List<Vector2>();
                int size = Mathf.Max(2, RouteWindow);
                float length = CoreEx.DistanceFlat(path[_windowEnd], path[start]);
                for (int i = start; i >= 0 && i < count && (next.Count < size || length < RouteWindowLength); i += _routeDir)
                {
                    Vector3 point = RoutePoint(i, _routeDir);
                    if (next.Count > 0) length += CoreEx.DistanceFlat(next[next.Count - 1], point);
                    next.Add(point);
                    margins.Add(RouteMargin(i, _routeDir));
                    _windowEnd = i;
                }
                _window.AddRange(next);
                Pilot.ExtendRoute(next);
                if (Pilot is EventGroundPilot ground) ground.AppendRouteMargins(margins);
            }
            protected void ResumeRoute()
            {
                if (Pilot == null) return;
                switch (routeMode)
                {
                    case RouteMode.Points:
                        if (path == null || path.Length == 0 || Vehicle == null) return;
                        int index = ResumeIndex(Vehicle.transform.position, out float offset, out bool before);
                        if (offset > RejoinPlanDistance)
                        {
                            Vector3 rejoin = RoutePoint(index, _routeDir);
                            _window.Clear();
                            _window.Add(rejoin);
                            _windowStart = _windowEnd = index;
                            if (Pilot is IEventPilot rejoinPilot) rejoinPilot.SetPolyline(null);
                            Pilot.DriveTo(rejoin);
                            if (Pilot is EventGroundPilot rejoinGround) rejoinGround.SetRouteMargins(null);
                            return;
                        }
                        FollowFrom(before && ResumeWithApproach ? index - _routeDir : index);
                        return;
                }
            }
            private int ResumeIndex(Vector3 position, out float offset, out bool before)
            {
                before = false;
                int index = NearestPathIndex(position);
                offset = CoreEx.DistanceFlat(position, path[index]);
                int ahead = index + _routeDir, behind = index - _routeDir;
                float tBehind = 1f, offBehind = float.MaxValue;
                bool hasBehind = behind >= 0 && behind < path.Length && FlatProjection(path[behind], path[index], position, out tBehind, out offBehind);
                if (!hasBehind)
                {
                    tBehind = 1f;
                    offBehind = float.MaxValue;
                }
                if (ahead >= 0 && ahead < path.Length && FlatProjection(path[index], path[ahead], position, out float t, out float off) && t > 0f
                    && (tBehind >= 1f || off < offBehind))
                {
                    offset = Mathf.Min(offset, off);
                    return ahead;
                }
                if (hasBehind && tBehind < 1f) offset = Mathf.Min(offset, offBehind);
                before = hasBehind && tBehind > 0f && tBehind < 1f;
                return index;
            }
            protected virtual bool ResumeWithApproach => false;
            private static bool FlatProjection(Vector3 a, Vector3 b, Vector3 point, out float t, out float distance)
            {
                Vector3 ab = b - a, ap = point - a;
                ab.y = 0f;
                ap.y = 0f;
                t = 0f;
                distance = ap.magnitude;
                if (ab.sqrMagnitude < 0.01f) return false;
                t = Vector3.Dot(ap, ab) / ab.sqrMagnitude;
                distance = (ap - ab * Mathf.Clamp01(t)).magnitude;
                return true;
            }
            protected void ResumeRouteFrom(int index)
            {
                if (routeMode != RouteMode.Points || path == null || path.Length == 0) return;
                if (Pilot == null)
                {
                    _windowStart = _windowEnd = Mathf.Clamp(index, 0, path.Length - 1);
                    return;
                }
                FollowFrom(index);
            }
            protected int RouteDirection => _routeDir;
            protected int NearestRouteIndex(Vector3 position) => routeMode == RouteMode.Points && path != null && path.Length > 0 ? NearestPathIndex(position) : -1;
            protected bool ReplaceRouteAhead(Vector3[] expected, int from, int rejoin, List<Vector3> detour)
            {
                if (routeMode != RouteMode.Points || path == null || !ReferenceEquals(path, expected) || Vehicle == null || Pilot == null) return false;
                if (detour == null || detour.Count < 2 || from < 0 || rejoin < 0 || from >= path.Length || rejoin >= path.Length) return false;
                List<Vector3> result = new List<Vector3>(path.Length + detour.Count);
                int start;
                if (_routeDir > 0)
                {
                    if (rejoin <= from) return false;
                    for (int i = 0; i < from; i++) result.Add(path[i]);
                    start = result.Count;
                    result.AddRange(detour);
                    for (int i = rejoin + 1; i < path.Length; i++) result.Add(path[i]);
                }
                else
                {
                    if (rejoin >= from) return false;
                    for (int i = 0; i < rejoin; i++) result.Add(path[i]);
                    for (int i = detour.Count - 1; i >= 0; i--) result.Add(detour[i]);
                    start = result.Count - 1;
                    for (int i = from + 1; i < path.Length; i++) result.Add(path[i]);
                }
                SetPath(result.ToArray());
                FollowFrom(start);
                return true;
            }
            protected bool RouteAheadOf(Vector3 position, out Vector3 point)
            {
                point = position;
                if (routeMode == RouteMode.Points && path != null && path.Length > 0)
                {
                    int index = NearestPathIndex(position);
                    point = path[Mathf.Clamp(index + _routeDir, 0, path.Length - 1)];
                    return true;
                }
                return false;
            }
            private int NearestPathIndex(Vector3 position)
            {
                int count = path.Length;
                int span = Mathf.Max(2, RouteWindow) * 2;
                int from = Mathf.Clamp(Mathf.Min(_windowStart, _windowEnd) - span, 0, count - 1);
                int to = Mathf.Clamp(Mathf.Max(_windowStart, _windowEnd) + span, 0, count - 1);
                int best = from;
                float bestDistance = float.MaxValue;
                for (int i = from; i <= to; i++)
                {
                    float distance = CoreEx.DistanceFlat(path[i], position);
                    if (distance >= bestDistance) continue;
                    bestDistance = distance;
                    best = i;
                }
                return best;
            }
            private void UpdateRoute()
            {
                if (routeMode != RouteMode.Points || path == null || path.Length == 0 || Pilot == null || Vehicle == null) return;
                int lastIndex = _routeDir > 0 ? path.Length - 1 : 0;
                bool atPathEnd = _windowEnd == lastIndex;
                if (Pilot.Arrived || !Pilot.HasTarget)
                {
                    if (atPathEnd) OnRouteFinished();
                    else FollowFrom(_windowEnd);
                    return;
                }
                if (atPathEnd || _window.Count < 2) return;
                Vector3 position = Vehicle.transform.position;
                int nearest = Mathf.Max(0, CoreEx.MinDistanceIndex(_window, p => CoreEx.DistanceFlat(p, position)));
                if (nearest > 1)
                {
                    _window.RemoveRange(0, nearest - 1);
                    _windowStart += (nearest - 1) * _routeDir;
                    nearest = 1;
                }
                float left = CoreEx.DistanceFlat(position, _window[nearest]);
                for (int i = nearest; i < _window.Count - 1; i++) left += CoreEx.DistanceFlat(_window[i], _window[i + 1]);
                float lead = Mathf.Max(RouteWindowLead, Vehicle.GetSpeed() * 3f);
                if (left < lead) ExtendWindow();
            }
            public void SetTarget(BasePlayer target)
            {
                if (!VehicleCore.IsRealPlayer(target) || !HasEvent) return;
                if (!_targets.Contains(target)) _targets.Add(target);
                _lastAttackedAt = UnityEngine.Time.time;
                if (ChaseEnabled && !_chasing && Pilot != null && IsValidChaseTarget(target)) StartChase();
            }
            public bool IsTarget(BaseCombatEntity target) => target is BasePlayer player && _chasing && currentTarget == player;
            private void StartChase()
            {
                _chasing = true;
                if (Pilot is IEventPilot eventPilot) eventPilot.SetPolyline(null);
                ApplyPilotMode();
            }
            private void EndChase()
            {
                _chasing = false;
                currentTarget = null;
                ApplyPilotMode();
                ResumeRoute();
            }
            private void UpdateChase()
            {
                if (_targets.Count > 0)
                {
                    if (isAggressionTime) _targets.RemoveAll(x => !IsValidChaseTarget(x));
                    else _targets.Clear();
                }
                if (!_chasing)
                {
                    if (_targets.Count > 0 && ChaseEnabled && isAggressionTime) StartChase();
                    else return;
                }
                if (_targets.Count == 0 || !ChaseEnabled)
                {
                    EndChase();
                    return;
                }
                Vector3 position = Vehicle.transform.position;
                currentTarget = _targets[Mathf.Max(0, CoreEx.MinDistanceIndex(_targets, x => Vector3.Distance(position, x.transform.position)))];
                DriveChase(currentTarget);
            }
            private void DriveChase(BasePlayer target)
            {
                if (target == null || Pilot == null) return;
                Vector3 position = Vehicle.transform.position;
                Vector3 targetPosition = target.transform.position;
                float flat = CoreEx.DistanceFlat(position, targetPosition);
                float minDistance = ChaseSettings?.MinDistance ?? 0f;
                if (minDistance > 0f && Vector3.Distance(position, targetPosition) <= minDistance)
                {
                    if (Pilot.HasTarget) Pilot.Halt();
                }
                else if (Pilot.FollowTarget != target)
                {
                    if (Pilot is IEventPilot linePilot) linePilot.SetPolyline(null);
                    if (Pilot is EventBoatPilot boatPilot) boatPilot.ChaseKeep = ChaseKeepDistance;
                    Pilot.Follow(target, ChaseKeepDistance, ChaseStraightDistance);
                }
                if (flat < ChaseAttackDistance) OnChaseAttack(target);
            }
            private void ResetRouteAndChase()
            {
                _targets.Clear();
                currentTarget = null;
                _chasing = false;
                _lastAttackedAt = -10000f;
                _window.Clear();
                _routeDir = 1;
            }
            private void TickEvent()
            {
                if (!HasEvent || Vehicle == null || Vehicle.IsDestroyed || Pilot == null) return;
                try
                {
                    UpdateChase();
                    if (!_chasing) UpdateRoute();
                }
                catch (Exception ex)
                {
                    Debug.LogError<T>("TickEvent [{0} #{1}]: {2}", NameEvent, number, ex);
                }
                if (!HasEvent || Pilot == null) return;
                try
                {
                    OnTickEvent();
                }
                catch (Exception ex)
                {
                    Debug.LogError<T>("OnTickEvent [{0} #{1}]: {2}", NameEvent, number, ex);
                }
            }
            #endregion

            #region End
            public void EndEvent([System.Runtime.CompilerServices.CallerMemberName] string caller = null)
            {
                if (!HasEvent)
                {
                    return;
                }
                NoteStop(BlackBoxKind.EventEnd, caller);
                CancelInvokeEvent();
                StopBoarding();
                if (CanDisableTurretToEndEvent)
                {
                    foreach (NPCAutoTurret turret in Turrets)
                    {
                        if (turret == null || turret.IsDestroyed) continue;
                        using (var setFlags = turret.StartSetFlags(BaseEntity.FlagsUpdateMode.SendNetworkUpdate_Flags))
                        {
                            setFlags.Set(BaseEntity.Flags.On, false);
                        }
                    }
                }
                Turrets.Clear();
                if (CurrentRun != null) CurrentRun.Active = false;

                if (giveParachute && !IsVehicleGrounded()) JumpParachute();
                ReleasePilot("event ended");
                DismountAllEnable();
                if (KeepCrewSeatedOnEnd()) Debug.Log<T>("{0} #{1}: crew stays on board (deep water)", NameEvent, number);
                else DismountCrew();

                BaseVehicle vehicle = Vehicle;
                if (vehicle != null && !vehicle.IsDestroyed && !_vehicleDying && canUseExplosive)
                {
                    vehicle.DismountAllPlayers();
                    Explosive = GameManager.server.CreateEntity(VehicleCore.PrefabExplosive, vehicle.transform.position, Quaternion.identity) as TimedExplosive;
                    if (Explosive != null)
                    {
                        Explosive.enableSaving = false;
                        Explosive.Spawn();
                        Explosive.DoStick(vehicle.transform.position + offsetExplosive, Vector3.up, vehicle, null);
                        Explosive.SetFuse(fuseExplosive);
                        _explosiveAt = UnityEngine.Time.time;
                        _detonated.RemoveAll(x => x == null || x.IsDestroyed);
                        _detonated.Add(vehicle);
                        vehicle.Invoke(() =>
                        {
                            if (vehicle != null && !vehicle.IsDestroyed) vehicle.Kill();
                        }, fuseExplosive);
                        if (DriverBot != null) DriverBot.LeaveVehicle(vehicle, fuseExplosive + 5f);
                        foreach (CrewNpc companion in CompanionBot)
                            if (companion != null) companion.LeaveVehicle(vehicle, fuseExplosive + 5f);
                    }
                }
                else Explosive = null;
                AssignDisperse(vehicle);

                DriverBot = null;
                CompanionBot.Clear();
                if (storage?.inventory != null && storage.inventory.IsLocked()) storage.inventory.SetLocked(false);
                storage = null;
                if (fuelSystem != null && removeFuel && !IsHumanPowered && !_vehicleDying && vehicle != null && !vehicle.IsDestroyed)
                    fuelSystem.RemoveFuel(fuelSystem.GetFuelAmount());
                fuelSystem = null;
                if (vehicle != null) EventEntities.UnregisterVehicle(vehicle, this);
                ReleaseFreeSeats();
                Vehicle = null;
                mountableDriver = null;
                mountablePassenger.Clear();
                ResetRouteAndChase();
                try
                {
                    OnEventStopped(vehicle);
                }
                catch (Exception ex)
                {
                    Debug.LogError<T>("OnEventStopped [{0} #{1}]: {2}", NameEvent, number, ex);
                }
                if (eventManager != null) StartEventToTimer(eventManager.Cooldown);
            }
            public void KillEventImmediate([System.Runtime.CompilerServices.CallerMemberName] string caller = null)
            {
                bool hadEvent = HasEvent;
                NoteStop(hadEvent ? BlackBoxKind.EventRemoved : BlackBoxKind.EventFailed, caller);
                CancelInvokeEvent();
                StopBoarding();
                if (CurrentRun != null) CurrentRun.Active = false;
                Turrets.Clear();
                DismountAllEnable();
                ReleasePilot("event removed");
                ReleaseCrewRoles("event removed");
                foreach (CrewNpc companion in new List<CrewNpc>(CompanionBot))
                {
                    if (companion != null) companion.KillImmediate();
                }
                CompanionBot.Clear();
                if (DriverBot != null) DriverBot.KillImmediate();
                DriverBot = null;
                if (storage is StorageContainer container && container != null && !container.IsDestroyed && EventEntities.IsStash(container, Host))
                {
                    if (Host.IsUnloading) container.Kill();
                    else StorageContainer.DropItems(container);
                }
                storage = null;
                if (Explosive != null && !Explosive.IsDestroyed) Explosive.Kill();
                Explosive = null;
                BaseVehicle vehicle = Vehicle;
                if (vehicle != null)
                {
                    EventEntities.UnregisterVehicle(vehicle, this);
                    if (!vehicle.IsDestroyed && !_vehicleDying)
                    {
                        vehicle.DismountAllPlayers();
                        OnVehicleKilling(vehicle);
                        vehicle.Kill();
                    }
                }
                Vehicle = null;
                fuelSystem = null;
                mountableDriver = null;
                mountablePassenger.Clear();
                ResetRouteAndChase();
                if (hadEvent)
                {
                    try
                    {
                        OnEventStopped(vehicle);
                    }
                    catch (Exception ex)
                    {
                        Debug.LogError<T>("OnEventStopped [{0} #{1}]: {2}", NameEvent, number, ex);
                    }
                }
            }
            private void NoteStop(BlackBoxKind kind, string caller)
            {
                string reason = _stopReason ?? "called from " + (caller ?? "unknown");
                _stopReason = null;
                if (kind == BlackBoxKind.EventFailed && (_shutdown || reason == PauseStopReason)) return;
                BlackBox.NoteEvent(typeof(T).Name, kind, NameEvent, number, reason, Vehicle, LifeTime);
            }
            private void ReleaseCrewRoles(string why)
            {
                if (DriverBot != null && DriverBot.IsValid()) HelperVehicles.ReleaseRoles(DriverBot, null, why);
                foreach (CrewNpc companion in CompanionBot)
                    if (companion != null && companion.IsValid()) HelperVehicles.ReleaseRoles(companion, null, why);
            }
            private void ReleasePilot(string why)
            {
                HelperVehicles.VehicleControllerBase pilot = Pilot;
                Pilot = null;
                if (pilot != null) pilot.Release(why);
            }
            private void ReleaseFreeSeats()
            {
                if (mountableDriver != null && mountableDriver.GetMounted() == null) CoreEx.SetBusy(mountableDriver, false);
                foreach (BaseMountable seat in mountablePassenger)
                    if (seat != null && seat.GetMounted() == null) CoreEx.SetBusy(seat, false);
            }
            private void AssignDisperse(BaseVehicle vehicle)
            {
                List<CrewNpc> crew = new List<CrewNpc>();
                if (DriverBot != null && DriverBot.HasBot) crew.Add(DriverBot);
                foreach (CrewNpc companion in CompanionBot)
                    if (companion != null && companion.HasBot && !crew.Contains(companion)) crew.Add(companion);
                if (crew.Count == 0) return;
                Vector3 center = Vector3.zero;
                if (vehicle != null) center = vehicle.transform.position;
                else
                {
                    foreach (CrewNpc bot in crew) center += bot.transform.position;
                    center /= crew.Count;
                }
                List<KeyValuePair<float, CrewNpc>> bearings = new List<KeyValuePair<float, CrewNpc>>(crew.Count);
                foreach (CrewNpc bot in crew)
                {
                    Vector3 offset = bot.transform.position - center;
                    offset.y = 0f;
                    float bearing = offset.sqrMagnitude > 0.25f ? Mathf.Atan2(offset.x, offset.z) * Mathf.Rad2Deg : UnityEngine.Random.Range(0f, 360f);
                    bearings.Add(new KeyValuePair<float, CrewNpc>(Mathf.Repeat(bearing, 360f), bot));
                }
                bearings.Sort((a, b) => a.Key.CompareTo(b.Key));
                float[] headings = DisperseHeadings(center, bearings, out int dryRays);
                int jumpers = 0;
                foreach (KeyValuePair<float, CrewNpc> pair in bearings)
                    if (pair.Value.IsParachute) jumpers++;
                float spreadStep = jumpers > 1 ? Mathf.Min(90f, 180f / (jumpers - 1)) : 0f;
                int jumper = 0;
                for (int i = 0; i < bearings.Count; i++)
                {
                    CrewNpc bot = bearings[i].Value;
                    bool chute = bot.IsParachute;
                    float spread = chute ? (jumper++ - (jumpers - 1) * 0.5f) * spreadStep : 0f;
                    bot.Disperse(headings[i], vehicle, center, spread, chute, crew);
                }
            }
            private const int DisperseRays = 24;
            private static float[] DisperseHeadings(Vector3 center, List<KeyValuePair<float, CrewNpc>> bearings, out int dryRays)
            {
                int n = bearings.Count;
                float[] result = new float[n];
                float rayStep = 360f / DisperseRays;
                bool[] dry = new bool[DisperseRays];
                dryRays = 0;
                for (int i = 0; i < DisperseRays; i++)
                {
                    Vector3 dir = Quaternion.Euler(0f, i * rayStep, 0f) * Vector3.forward;
                    dry[i] = IsDisperseLand(center + dir * 150f) && IsDisperseLand(center + dir * 250f);
                    if (dry[i]) dryRays++;
                }
                if (dryRays == 0 || dryRays == DisperseRays)
                {
                    float sector = 360f / n;
                    float sx = 0f, sz = 0f;
                    for (int i = 0; i < n; i++)
                    {
                        float d = (bearings[i].Key - i * sector) * Mathf.Deg2Rad;
                        sx += Mathf.Sin(d);
                        sz += Mathf.Cos(d);
                    }
                    float start = sx * sx + sz * sz > 0.0001f ? Mathf.Atan2(sx, sz) * Mathf.Rad2Deg : bearings[0].Key;
                    for (int i = 0; i < n; i++) result[i] = start + i * sector + UnityEngine.Random.Range(-0.2f, 0.2f) * sector;
                    return result;
                }
                int bestRun = 0, bestEnd = 0, run = 0;
                for (int k = 0; k < DisperseRays * 2; k++)
                {
                    int idx = k % DisperseRays;
                    if (dry[idx])
                    {
                        run = 0;
                        continue;
                    }
                    run++;
                    if (run > bestRun && run <= DisperseRays)
                    {
                        bestRun = run;
                        bestEnd = idx;
                    }
                }
                List<float> land = new List<float>(dryRays);
                for (int k = 1; k <= DisperseRays; k++)
                {
                    int idx = (bestEnd + k) % DisperseRays;
                    if (dry[idx]) land.Add(idx * rayStep);
                }
                float[] picks = new float[n];
                for (int k = 0; k < n; k++)
                    picks[k] = land[Mathf.Min(land.Count - 1, Mathf.FloorToInt((k + 0.5f) * land.Count / n))] + UnityEngine.Random.Range(-0.3f, 0.3f) * rayStep;
                int bestShift = 0;
                float bestCost = float.MaxValue;
                for (int shift = 0; shift < n; shift++)
                {
                    float cost = 0f;
                    for (int k = 0; k < n; k++) cost += Mathf.Abs(Mathf.DeltaAngle(bearings[(k + shift) % n].Key, picks[k]));
                    if (cost >= bestCost) continue;
                    bestCost = cost;
                    bestShift = shift;
                }
                for (int k = 0; k < n; k++) result[(k + bestShift) % n] = picks[k];
                return result;
            }
            private static bool IsDisperseLand(Vector3 point)
            {
                Vector3 min = TerrainMeta.Position, size = TerrainMeta.Size;
                if (point.x < min.x + 100f || point.x > min.x + size.x - 100f || point.z < min.z + 100f || point.z > min.z + size.z - 100f) return false;
                point.y = TerrainMeta.HeightMap.GetHeight(point);
                if (point.y < WaterSystem.OceanLevel + 0.5f) return false;
                return WaterLevel.GetOverallWaterDepth(point, waves: false, volumes: false) < 0.3f;
            }
            private void DismountCrew()
            {
                DismountOne(DriverBot);
                foreach (CrewNpc companion in CompanionBot) DismountOne(companion);
            }
            private static void DismountOne(CrewNpc bot)
            {
                if (bot == null || !bot.IsAlive() || bot.IsDestroyed || bot.IsParachute) return;
                bot.CanDismount = true;
                HelperVehicles.ReleaseRoles(bot, null, "event ended");
                if (bot.isMounted) bot.DismountSafely();
                if (!bot.isMounted) bot.GoOnFoot();
            }
            protected bool KeepCrewSeatedOnEnd()
            {
                if (canUseExplosive || !(Vehicle is BaseBoat) || Vehicle.IsDestroyed || _vehicleDying) return false;
                return CoreEx.GroundPosition(Vehicle.transform.position).y < WaterSystem.OceanLevel - CrewNpc.DeepWaterDepth;
            }
            private bool IsVehicleGrounded()
            {
                if (Vehicle == null || Vehicle.IsDestroyed) return false;
                Vector3 position = Vehicle.transform.position;
                return position.y - Mathf.Max(TerrainMeta.HeightMap.GetHeight(position), WaterSystem.OceanLevel) < 3f;
            }
            public void DismountAllEnable()
            {
                if (DriverBot != null) DriverBot.CanDismount = true;
                foreach (CrewNpc companion in CompanionBot)
                    if (companion != null) companion.CanDismount = true;
            }
            public void JumpParachute()
            {
                List<Vector3> land = LandDirections(Vehicle);
                if (DriverBot != null && DriverBot.IsAlive()) DriverBot.JumpParachute(SkinParachute, land, Vehicle);
                foreach (CrewNpc companion in CompanionBot)
                    if (companion != null && companion.IsAlive()) companion.JumpParachute(SkinParachute, land, Vehicle);
            }
            private static List<Vector3> LandDirections(BaseVehicle vehicle)
            {
                if (vehicle == null) return null;
                Vector3 center = vehicle.transform.position;
                List<Vector3> land = new List<Vector3>();
                for (int i = 0; i < DisperseRays; i++)
                {
                    Vector3 dir = Quaternion.Euler(0f, i * 360f / DisperseRays, 0f) * Vector3.forward;
                    if (IsDisperseLand(center + dir * 150f) && IsDisperseLand(center + dir * 250f)) land.Add(dir);
                }
                return land.Count == 0 || land.Count == DisperseRays ? null : land;
            }
            private void CancelInvokeEvent()
            {
                CancelInvoke(CheckEvent);
                CancelInvoke(CheckHeadlights);
                CancelInvoke(CheckFuel);
                CancelInvoke(InitVehicle);
                CancelInvoke(InvokeStart);
                CancelInvoke(TickEvent);
                HasEvent = false;
            }
            public float GetTimerExplode() => fuseExplosive - (UnityEngine.Time.time - _explosiveAt);
            public bool IsInitiator(BasePlayer player) => IsTestController && admin == player;
            #endregion

            #region IEventController
            public void OnCrewDied(CrewNpc crew)
            {
                if (crew == null) return;
                if (crew == DriverBot)
                {
                    if (HasEvent && IsInvoking(CheckEvent))
                    {
                        CancelInvoke(CheckEvent);
                        Invoke(CheckEvent, 0.1f);
                    }
                }
            }
            public void OnVehicleKilled(BaseVehicle vehicle)
            {
                if (vehicle == null || vehicle != Vehicle) return;
                _vehicleDying = true;
                EventEntities.UnregisterVehicle(vehicle, this);
                _stopReason = "vehicle destroyed";
                if (HasEvent) EndEvent();
                else if (_boarding != null)
                {
                    KillEventImmediate();
                    StartEventToTimer(10f);
                }
                _stopReason = null;
                _vehicleDying = false;
            }
            #endregion

            #region InvokeMethods
            public void InvokeStart()
            {
                if (_shutdown) return;
                if (eventManager == null || eventManager.IsPause)
                {
                    return;
                }
                try
                {
                    ResetRouteAndChase();
                    path = null;
                    routeMode = RouteMode.None;
                    SetSettingsVehicle();
                    InitRouter();
                }
                catch (Exception ex)
                {
                    Debug.LogError<T>("Start [{0} #{1}]: {2}", NameEvent, number, ex);
                    KillEventImmediate();
                    StartEventToTimer(10f);
                }
            }
            protected virtual void CheckEvent()
            {
                if (!HasEvent) return;
                try
                {
                    if (Vehicle != null && !Vehicle.IsDestroyed && canEngineStart)
                    {
                        if (DriverBot != null && DriverBot.IsAlive() && Vehicle.IsDriver(DriverBot))
                        {
                            if (EnsurePilot())
                            {
                                Invoke(CheckEvent, 1f);
                                return;
                            }
                            _stopReason = "pilot did not regain control";
                        }
                        else
                        {
                            _stopReason = "driver dead or not at the wheel";
                        }
                    }
                    else
                    {
                        _stopReason = "vehicle gone or its engine cannot start";
                    }
                    EndEvent();
                }
                catch (Exception ex)
                {
                    Invoke(CheckEvent, 1f);
                    Debug.LogError<T>("CheckEvent [{0} #{1}]: {2}", NameEvent, number, ex);
                }
            }
            protected bool EnsurePilot()
            {
                if (Pilot != null) return true;
                Vector3 position = Vehicle.transform.position;
                if ((position - _retakePos).sqrMagnitude >= 900f) _retakeAttempts = 0;
                if (_retakeAttempts >= 3 && !RetakesExhausted()) return false;
                _retakeAttempts++;
                _retakePos = Vehicle.transform.position;
                if (!TakeControl()) return _retakeAttempts < 3 || RetakesExhausted();
                _retakeRescues = 0;
                PilotRetakes++;
                BlackBox.NoteEvent(typeof(T).Name, BlackBoxKind.VehicleRetake, NameEvent, number, null, Vehicle, _retakeAttempts);
                if (!_chasing) ResumeRoute();
                OnPilotRetaken(_retakeAttempts);
                return true;
            }
            protected virtual void OnPilotRetaken(int attempt) { }
            protected virtual bool OnPilotRetakesExhausted() => false;
            private bool RetakesExhausted()
            {
                if (_retakeRescues >= 2) return false;
                bool resumed = false;
                try
                {
                    resumed = OnPilotRetakesExhausted();
                }
                catch (Exception ex)
                {
                    Debug.LogError<T>("OnPilotRetakesExhausted [{0} #{1}]: {2}", NameEvent, number, ex);
                }
                if (!resumed || Vehicle == null || Vehicle.IsDestroyed) return false;
                _retakeRescues++;
                _retakeAttempts = 0;
                _retakePos = Vehicle.transform.position;
                return true;
            }
            protected void ResetRetakes()
            {
                _retakeAttempts = 0;
                _retakePos = Vehicle != null ? Vehicle.transform.position : Vector3.zero;
            }
            private void CheckHeadlights()
            {
                if (Vehicle == null || Vehicle.IsDestroyed || TOD_Sky.Instance == null) return;
                bool on = !headlightsOnlyAtNightMode || TOD_Sky.Instance.IsNight;
                if (Vehicle.HasFlag(BaseEntity.Flags.Reserved5) == on) return;
                using (var setFlags = Vehicle.StartSetFlags(BaseEntity.FlagsUpdateMode.SendNetworkUpdate_Flags))
                {
                    setFlags.Set(BaseEntity.Flags.Reserved5, on);
                }
            }
            private void CheckFuel()
            {
                if (fuelSystem == null || !HasEvent) return;
                if (IsHumanPowered)
                {
                    if (!fuelSystem.HasFuel() && DriverBot != null) DriverBot.Feed();
                    return;
                }
                if (isAutoFuel)
                {
                    int amount = fuelSystem.GetFuelAmount();
                    if (amount < Mathf.Max(1, levelFuel / 5) && levelFuel > amount) fuelSystem.AddFuel(levelFuel - amount);
                    CoreEx.StartEngineNow(Vehicle);
                    return;
                }
                if (fuelSystem.HasFuel())
                {
                    CoreEx.StartEngineNow(Vehicle);
                    return;
                }
                _stopReason = "out of fuel";
                OnEmptyFuel();
                _stopReason = null;
            }
            protected void InfoEventUpdate()
            {
                if (eventManager == null) return;
                float timer = timerUpdateInfo;
                if (HasEvent || HasExplosive)
                {
                    if (Vehicle != null && !Vehicle.IsDestroyed) eventManager.SendInfoEvent(this, NameEvent, TypeEvent, timer);
                    if (HasExplosive) eventManager.SendInfoExplosive(this, NameEvent, timer);
                }
                if (!IsTestController || testUIInfo == null) return;
                try
                {
                    if (admin == null || !admin.IsConnected) return;
                    if (HasEvent && Vehicle != null && !Vehicle.IsDestroyed)
                    {
                        if (routeMode == RouteMode.Points && _window.Count > 0)
                            testUIInfo.DrawPath(_window.ToArray(), Color.white, 0.2f, _window.Count - 1, timer);
                        testUIInfo.SendInfo(GetTestInfo());
                    }
                    else if (!HasEvent)
                    {
                        int dots = (int)((UnityEngine.Time.time - _waitingSince) % 4f);
                        testUIInfo.SendInfo($"{NameEvent} #{number} starting{new string('.', dots)}");
                    }
                }
                catch (Exception ex)
                {
                    Debug.LogError<T>("InfoEventUpdate: {0}", ex.Message);
                }
            }
            public virtual string GetTestInfo()
            {
                string text = $"{NameEvent} #{number} [{TypeEvent}]";
                text += $"\nMove time: {CoreEx.ToStringTime(LifeTime)}";
                if (routeMode == RouteMode.Points) text += $"\nRoute: points {path?.Length ?? 0}, distance {CoreEx.Distance(path):0} m, dir {_routeDir}, window {_windowStart}-{_windowEnd}";
                if (Vehicle != null) text += $"\nVehicle health: {Vehicle.Health():0.0} / {Vehicle.MaxHealth():0.0}\nSpeed: {CoreEx.ToKms(Vehicle.GetSpeed())}";
                text += $"\nMode: {(_chasing ? "chase" : "route")}";
                if (ChaseSettings != null && _targets.Count > 0) text += $"\nTimer aggression: {ChaseSettings.TimerAggression - (UnityEngine.Time.time - _lastAttackedAt):0}";
                text += $"\nCurrent target: {(currentTarget == null ? "null" : currentTarget.displayName)}";
                if (currentTarget != null && Vehicle != null) text += $" distance = {Vector3.Distance(Vehicle.transform.position, currentTarget.transform.position):0.0}";
                if (Pilot != null) text += $"\nPilot: {Pilot.GetType().Name} ({Pilot.Kind}), arrived={Pilot.Arrived}, target={Pilot.HasTarget}";
                else text += "\nPilot: none";
                if (fuelSystem != null) text += $"\nFuel: {fuelSystem.GetFuelAmount()}";
                if (enableHeadlights && Vehicle != null) text += $"\nHeadlights: {Vehicle.HasFlag(BaseEntity.Flags.Reserved5)}";
                text += $"\nCrew: driver={(DriverBot != null && DriverBot.IsAlive() ? "alive" : "none")}, companions={CompanionBot.Count}, attackers={CurrentRun?.Attackers.Count ?? 0}";
                return text;
            }
            int IDiagnosticsReport.AppendDiagnostics(System.Text.StringBuilder sb)
            {
                if (!HasEvent || Vehicle == null)
                {
                    ReportLine(sb, "    #{0} {1} [{2}]: {3}", number, NameEvent, TypeEvent, _shutdown ? "shut down" : _boarding != null ? "crew boarding"
                        : IsInvoking(InvokeStart) ? "waiting to start" : HasExplosive ? "ended, C4 on the vehicle" : "idle");
                    return 0;
                }
                Vector3 position = Vehicle.transform.position;
                int companions = 0;
                foreach (CrewNpc companion in CompanionBot)
                    if (companion != null && companion.HasBot) companions++;
                ReportLine(sb, "    #{0} {1} [{2}]: running {3}, vehicle {4} net {5} at {6} grid {7}, pilot {8}, driver {9}, companions alive {10} of {11}, {12}, pilot retakes {13}",
                    number, NameEvent, TypeEvent, ReportDuration(LifeTime), Vehicle.ShortPrefabName, VehicleId, ReportPos(position), MapHelper.PositionToString(position),
                    Pilot != null ? Pilot.GetType().Name : "NONE", DriverBot != null && DriverBot.HasBot ? Debug.Id(DriverBot) : "none", companions, CompanionBot.Count,
                    _chasing ? "chasing " + ReportEntityName(currentTarget) : "on route", PilotRetakes);
                string info;
                try
                {
                    info = GetTestInfo();
                }
                catch (Exception ex)
                {
                    info = "test info failed: " + ex.Message;
                }
                ReportIndented(sb, "      | ", info);
                return 1;
            }
            #endregion

            #region Пауза менеджера
            public void OnPause()
            {
                if (!DestroyEventsFromPause) return;
                _stopReason = PauseStopReason;
                KillEventImmediate();
            }
            public void OnResume()
            {
                if (DestroyEventsFromPause)
                {
                    if (eventManager == null) return;
                    StartEventToTimer(eventManager.timerResume);
                    eventManager.timerResume += 5f;
                }
                else if (!HasEvent)
                {
                    StartEventToTimer(5f);
                }
            }
            #endregion
        }

        #endregion

        #region VehicleEventsCore: наземное событие

        public sealed class GroundProfile
        {
            public string Noun = "vehicle";
            public float CheckInterval = 1f;
            public float ProgressStep = 5f;
            public float StuckRadius = 15f;
            public float OffRouteDistance = 20f;
            public float ChaseHoldRadius = 30f;
            public float TeleportAfter = 60f;
            public float ReplanAfter = 10f;
            public float TurnRadius;
            public bool LaneSolidOnly;
            public bool ReplanAroundVehicles;
            public float VehicleMargin = 0.4f;
            public float TeleportRetryAfter = 10f;
            public int TeleportRetries = 3;
            public float WholeRouteStep = 10f, WholeRouteReach = 1500f;
            public float[] TeleportSteps = { 20f, 30f, 45f, 60f, 80f };
            public float BoxMargin = 0.4f, BoxBottom = 0.5f, BoxTop = 2f;
            public float ClearAhead = 5f;
            public float FacingAhead = 15f;
            public float ResumeAheadMin = 6f, ResumeAheadSearch = 30f;
            public float DefaultHalfWidth = 1.3f, DefaultHalfLength = 2.3f;
            public float WheelsOffTime = 0.5f;

            public float LegStep = 2.5f;
            public bool LegStepByPoints;
            public float LegMaxGrade = 28f;
            public bool AxisGround = true;
            public float LedgeStep = 0.25f;
            public bool DeckOverWater = true;
            public float WaterDepth = 0.4f;
            public float[] WaterOffsets = { 0f, -2f, 2f, -4f, 4f, -6f, 6f };
            public float LegWheel = 1f, LegCross = 26f, LegMidWheels = 1.5f;
            public float RockCorridor;
            public float SplitCorridor = 1.65f;
            public float CorridorLift = (0.2f + 1.7f) * 0.5f, CorridorHalfHeight = (1.7f - 0.2f) * 0.5f;
            public float BodyHalf;
            public float BodyWheel, BodyCross;
            public bool BlockedOnAxis;
            public float ZoneMargin = -1f;

            public HelperVehicles.RoadClass RoadClasses = HelperVehicles.RoadClass.Main | HelperVehicles.RoadClass.Side;
            public float RoadHalfWidth = 5f;
            public float MinRouteLength = 100f;
            public float SidestepMinRight = 0.3f, OncomingSidestep = 2.5f, SeamSidestep = 2.5f;
            public float SeamReach = GroundRoads.SeamMaxChord;
            public CoreNavLand.LegCheck SeamCheck;
            public int SeamWindowNodes = 8;
            public float SeamWindowLength = float.MaxValue, SeamMinChord = 1f, SeamMaxTurn = 100f, SeamSingleTurn;
            public bool SeamTurnFromRoute = true;
            public float SeamNodeCost = 4f, SeamRoadCost, SeamTurnCost, SeamEasyTurn, SeamSharpCost;
            public float[] SeamBypass = { 4f, 7f, 10f, 14f };
            public float TurnSpotSearch = 60f, TurnSpotHalfWidth = 6f, TurnSpotHalfLength = 6f, TurnSpotLift = 1.5f, TurnSpotHalfHeight = 1f;
            public float TurnSpotSlope = 30f, TurnSpotJunction = 20f;
            public bool TurnSpotLevelArea = true;
            public string[] TurnSpotLayers = { "World", "Construction", "Deployed", "Tree", "Default" };
            private int _turnSpotMask;
            public int TurnSpotMask => _turnSpotMask != 0 ? _turnSpotMask : _turnSpotMask = LayerMask.GetMask(TurnSpotLayers);

            public int GenerateAttempts = 8;
