        public class RouteCandidate
        {
            public List<Vector3> Route;
            public bool OnRoad;
            public int Flaws = int.MaxValue;
            public virtual string Describe() => $"flaws {Flaws}";
        }

        public static class GroundPlacement
        {
            private static int _surfaceMask, _bodyMask;
            private static readonly Collider[] _hits = new Collider[32];
            private static readonly List<WheelCollider> _wheels = new();

            public static bool Ground(Vector3 point, out Vector3 position)
            {
                if (_surfaceMask == 0) _surfaceMask = LayerMask.GetMask("Terrain", "World", "Construction");
                float terrain = TerrainMeta.HeightMap.GetHeight(point);
                float reference = Mathf.Max(point.y, terrain);
                position = new Vector3(point.x, terrain, point.z);
                if (Physics.Raycast(new Vector3(point.x, reference + 4f, point.z), Vector3.down, out RaycastHit hit, reference + 5f - terrain,
                        _surfaceMask, QueryTriggerInteraction.Ignore))
                    position.y = Mathf.Max(position.y, hit.point.y);
                if (position.y > reference + 2f) return false;
                return TerrainMeta.WaterMap == null || TerrainMeta.WaterMap.GetHeight(position) <= position.y + 0.3f;
            }
            public static Vector3 SpawnPoint(Vector3 point, GroundProfile profile)
            {
                if (_surfaceMask == 0) _surfaceMask = LayerMask.GetMask("Terrain", "World", "Construction");
                float ground = TerrainMeta.HeightMap.GetHeight(point);
                if (!profile.SpawnOnSurface) ground = Mathf.Max(point.y, ground);
                else if (Physics.Raycast(point + Vector3.up * 2f, Vector3.down, out RaycastHit hit, 6f, _surfaceMask, QueryTriggerInteraction.Ignore))
                    ground = hit.point.y;
                point.y = ground + 0.5f;
                return point;
            }
            public static bool BodyFits(Vector3 position, Quaternion rotation, float halfWidth, float halfLength, GroundProfile profile,
                                        bool clearAhead, BaseEntity vehicle, BaseEntity driver, List<CrewNpc> crew)
            {
                float halfHeight = Mathf.Max(0.1f, (profile.BoxTop - profile.BoxBottom) * 0.5f);
                Vector3 center = position + Vector3.up * (profile.BoxBottom + halfHeight);
                float width = halfWidth + profile.BoxMargin, length = halfLength + profile.BoxMargin;
                if (!BoxClear(center, new Vector3(width, halfHeight, length), rotation, vehicle, driver, crew)) return false;
                return !clearAhead || AheadClear(position, rotation, halfWidth, halfLength, profile, vehicle, driver, crew);
            }
            public static bool AheadClear(Vector3 position, Quaternion rotation, float halfWidth, float halfLength, GroundProfile profile,
                                          BaseEntity vehicle, BaseEntity driver, List<CrewNpc> crew)
            {
                if (profile.ClearAhead <= 0f) return true;
                float halfHeight = Mathf.Max(0.1f, (profile.BoxTop - profile.BoxBottom) * 0.5f);
                Vector3 center = position + Vector3.up * (profile.BoxBottom + halfHeight);
                float width = halfWidth + profile.BoxMargin, length = halfLength + profile.BoxMargin;
                Vector3 ahead = center + rotation * Vector3.forward * (length + profile.ClearAhead * 0.5f);
                return BoxClear(ahead, new Vector3(width, halfHeight, profile.ClearAhead * 0.5f), rotation, vehicle, driver, crew);
            }
            public static bool BoxClear(Vector3 center, Vector3 half, Quaternion rotation, BaseEntity vehicle, BaseEntity driver, List<CrewNpc> crew)
            {
                if (_bodyMask == 0)
                    _bodyMask = LayerMask.GetMask("World", "Construction", "Deployed", "Tree", "Default", "Vehicle World", "Vehicle Detailed",
                        "Vehicle Large", "Player (Server)");
                int count = Physics.OverlapBoxNonAlloc(center, half, _hits, rotation, _bodyMask, QueryTriggerInteraction.Ignore);
                if (count >= _hits.Length) return false;
                for (int i = 0; i < count; i++)
                {
                    Collider collider = _hits[i];
                    if (collider == null || GroundChecks.IsRoadOrBush(collider.name) || IsOwn(collider, vehicle, driver, crew)) continue;
                    return false;
                }
                return true;
            }
            private static bool IsOwn(Collider collider, BaseEntity vehicle, BaseEntity driver, List<CrewNpc> crew)
            {
                BaseEntity entity = collider.ToBaseEntity();
                for (int depth = 0; depth < 6 && entity != null; depth++)
                {
                    if (entity == vehicle || entity == driver || (crew != null && entity is CrewNpc bot && crew.Contains(bot))) return true;
                    entity = entity.GetParentEntity();
                }
                return false;
            }
            public static void Place(BaseVehicle vehicle, Vector3 position, Quaternion rotation, float wheelsOff, HelperVehicles.VehicleControllerBase pilot)
            {
                Rigidbody body = vehicle.rigidBody;
                if (body != null)
                {
                    body.linearVelocity = Vector3.zero;
                    body.angularVelocity = Vector3.zero;
                }
                vehicle.transform.SetPositionAndRotation(position + Vector3.up * 0.5f, rotation);
                vehicle.SendNetworkUpdateImmediate();
                if (wheelsOff > 0f && vehicle is GroundVehicle) WheelsOff(vehicle, wheelsOff);
                if (pilot is EventGroundPilot ground) ground.ResetManeuver();
            }
            private static void WheelsOff(BaseVehicle vehicle, float time)
            {
                vehicle.GetComponentsInChildren(_wheels);
                List<WheelCollider> off = new List<WheelCollider>(_wheels.Count);
                foreach (WheelCollider wheel in _wheels)
                {
                    if (!wheel.enabled) continue;
                    wheel.enabled = false;
                    off.Add(wheel);
                }
                _wheels.Clear();
                if (off.Count == 0) return;
                vehicle.Invoke(() =>
                {
                    foreach (WheelCollider wheel in off)
                        if (wheel != null) wheel.enabled = true;
                }, time);
            }
        }

        public static class GroundChecks
        {
            public enum Ground { Terrain, Road, Deck, Ledge }

            private const float TopProbe = 60f;
            private static readonly Vector3 FarOrigin = new Vector3(1e6f, 0f, 1e6f);
            private static readonly Collider[] _hits = new Collider[16], _wideHits = new Collider[32];
            private static int _surfaceMask, _obstacleMask, _rockMask, _bodyMask, _solidMask;
            public static int SurfaceMask => _surfaceMask != 0 ? _surfaceMask
                : _surfaceMask = LayerMask.GetMask("Terrain", "World", "Construction", "Deployed", "Default");
            public static int ObstacleMask => _obstacleMask != 0 ? _obstacleMask
                : _obstacleMask = LayerMask.GetMask("World", "Tree", "Construction", "Deployed", "Default");
            public static int RockMask => _rockMask != 0 ? _rockMask : _rockMask = LayerMask.GetMask("World", "Construction");
            public static int BodyMask => _bodyMask != 0 ? _bodyMask
                : _bodyMask = LayerMask.GetMask("Tree", "Default", "Deployed", "Construction");
            public static int SolidMask => _solidMask != 0 ? _solidMask
                : _solidMask = LayerMask.GetMask("World", "Construction", "Deployed", "Default");

            public static bool Leg(Vector3 a, Vector3 b, GroundProfile profile, out Vector3 blockedAt) => Leg(a, b, profile, null, true, out blockedAt);
            public static bool Leg(Vector3 a, Vector3 b, GroundProfile profile, List<Footprint> blockers, bool zones, out Vector3 blockedAt)
            {
                if (blockers != null)
                    for (int i = 0; i < blockers.Count; i++)
                        if (blockers[i].Blocks(a, b))
                        {
                            blockedAt = blockers[i].Center;
                            return false;
                        }
                if (!Clear(a, b, profile, 0f, out blockedAt) || !HelperVehicles.SegmentPassable(a, b, out blockedAt)) return false;
                if (zones && profile.ZoneMargin >= 0f && HelperSafeZones.Count > 0
                    && HelperSafeZones.SegmentEnters(FarOrigin, a, b, out blockedAt, profile.ZoneMargin))
                    return false;
                blockedAt = b;
                return true;
            }
            public static bool Clear(Vector3 a, Vector3 b, GroundProfile profile, float skip, out Vector3 blockedAt)
                => Line(a, b, profile, skip, out blockedAt) && (profile.BodyHalf <= 0f || Body(a, b, profile, skip, out blockedAt));

            #region Линия
            public static bool Line(Vector3 a, Vector3 b, GroundProfile profile, float skip, out Vector3 blockedAt)
            {
                blockedAt = b;
                Vector3 dir = b - a;
                dir.y = 0f;
                float length = dir.magnitude;
                if (length < 0.5f) return true;
                dir /= length;
                Vector3 normal = new Vector3(dir.z, 0f, -dir.x);
                Quaternion rotation = Quaternion.LookRotation(dir, Vector3.up);
                float grade = Mathf.Tan(profile.LegMaxGrade * Mathf.Deg2Rad);
                Vector3 prev = a;
                float prevHeight = TerrainMeta.HeightMap.GetHeight(a), prevAt = 0f;
                for (float d = profile.LegStep; ; d += profile.LegStep)
                {
                    float at = Mathf.Min(d, length);
                    Vector3 p = a + dir * at;
                    float run = profile.LegStepByPoints ? CoreEx.DistanceFlat(prev, p) : at - prevAt;
                    if (run >= 0.5f)
                    {
                        float height = TerrainMeta.HeightMap.GetHeight(p);
                        p.y = height;
                        if (at >= skip && !ProbeClear(p, dir, normal, rotation, run, prevHeight, grade, profile, out blockedAt)) return false;
                        prev = p;
                        prevHeight = height;
                        prevAt = at;
                    }
                    if (at >= length) break;
                }
                blockedAt = b;
                return true;
            }
            private static bool ProbeClear(Vector3 p, Vector3 dir, Vector3 normal, Quaternion rotation, float run, float prevHeight,
                                           float grade, GroundProfile profile, out Vector3 blockedAt)
            {
                blockedAt = p;
                float height = p.y;
                if (profile.AxisGround)
                {
                    Ground centre = GroundAt(p, height, profile);
                    if (centre == Ground.Road || centre == Ground.Deck) return true;
                    if (centre == Ground.Ledge) return false;
                }
                if (Mathf.Abs(height - prevHeight) > grade * run) return false;
                if (profile.RockCorridor > 0f
                    && !AreaClear(new Vector3(p.x, height + profile.CorridorLift, p.z),
                                  new Vector3(profile.RockCorridor, profile.CorridorHalfHeight, profile.LegStep * 0.5f), rotation, RockMask))
                    return false;
                if (WaterAcross(p, normal, profile, ref blockedAt)) return false;
                if (profile.LegWheel > 0f && !WheelsClear(p, dir, normal, run, profile, ref blockedAt)) return false;
                return profile.SplitCorridor <= 0f || SplitCorridorClear(p, dir, normal, rotation, run, height, profile, ref blockedAt);
            }
            private static bool WaterAcross(Vector3 p, Vector3 normal, GroundProfile profile, ref Vector3 blockedAt)
            {
                float[] offsets = profile.WaterOffsets;
                for (int k = 0; offsets != null && k < offsets.Length; k++)
                {
                    Vector3 w = p + normal * offsets[k];
                    w.y = TerrainMeta.HeightMap.GetHeight(w);
                    if (WaterLevel.GetOverallWaterDepth(w, waves: false, volumes: true) <= profile.WaterDepth) continue;
                    BlockedAt(w, profile, ref blockedAt);
                    return true;
                }
                return false;
            }
            private static bool WheelsClear(Vector3 p, Vector3 dir, Vector3 normal, float run, GroundProfile profile, ref Vector3 blockedAt)
            {
                float wheel = profile.LegWheel;
                Vector3 left = p - normal * wheel, right = p + normal * wheel;
                left.y = TerrainMeta.HeightMap.GetHeight(left);
                right.y = TerrainMeta.HeightMap.GetHeight(right);
                if (GroundAt(left, left.y, profile) == Ground.Ledge) return BlockedAt(left, profile, ref blockedAt);
                if (GroundAt(right, right.y, profile) == Ground.Ledge) return BlockedAt(right, profile, ref blockedAt);
                if (run > profile.LegMidWheels)
                {
                    Vector3 half = p - dir * (run * 0.5f);
                    for (int k = -1; k <= 1; k++)
                    {
                        Vector3 q = half + normal * (k * wheel);
                        q.y = TerrainMeta.HeightMap.GetHeight(q);
                        if (GroundAt(q, q.y, profile) == Ground.Ledge) return BlockedAt(q, profile, ref blockedAt);
                    }
                }
                if (Mathf.Abs(left.y - right.y) > Mathf.Tan(profile.LegCross * Mathf.Deg2Rad) * 2f * wheel)
                    return BlockedAt(left.y > right.y ? left : right, profile, ref blockedAt);
                return true;
            }
            private static bool SplitCorridorClear(Vector3 p, Vector3 dir, Vector3 normal, Quaternion rotation, float run, float height,
                                                   GroundProfile profile, ref Vector3 blockedAt)
            {
                float corridor = profile.SplitCorridor;
                Vector3 middle = p - dir * (run * 0.5f);
                for (int side = -1; side <= 1; side += 2)
                {
                    Vector3 edge = middle + normal * (side * corridor);
                    float low = Mathf.Min(height, TerrainMeta.HeightMap.GetHeight(edge));
                    Vector3 centreOfHalf = middle + normal * (side * corridor * 0.5f);
                    centreOfHalf.y = low + profile.CorridorLift;
                    Vector3 half = new Vector3(corridor * 0.5f, profile.CorridorHalfHeight, run * 0.5f);
                    int count = Physics.OverlapBoxNonAlloc(centreOfHalf, half, _wideHits, rotation, ObstacleMask, QueryTriggerInteraction.Ignore);
                    for (int i = 0; i < count; i++)
                    {
                        if (!CoreRoutes.RouteBlocks(_wideHits[i])) continue;
                        BlockedAt(_wideHits[i].ClosestPointOnBounds(centreOfHalf), profile, ref blockedAt);
                        return false;
                    }
                }
                return true;
            }
            private static bool BlockedAt(Vector3 spot, GroundProfile profile, ref Vector3 blockedAt)
            {
                if (!profile.BlockedOnAxis) blockedAt = spot;
                return false;
            }
            #endregion

            #region Кузов
            public static bool Body(Vector3 a, Vector3 b, GroundProfile profile, float skip, out Vector3 blockedAt)
            {
                blockedAt = b;
                Vector3 dir = b - a;
                dir.y = 0f;
                float length = dir.magnitude;
                if (length < 0.5f) return true;
                dir /= length;
                Vector3 normal = new Vector3(dir.z, 0f, -dir.x);
                Quaternion rotation = Quaternion.LookRotation(dir, Vector3.up);
                float step = profile.LegStep, body = profile.BodyHalf;
                for (float d = 0f; d < length - 0.05f; d += step)
                {
                    float run = Mathf.Min(step, length - d);
                    if (d + run <= skip) continue;
                    Vector3 p = a + dir * (d + run * 0.5f);
                    float centre = TerrainMeta.HeightMap.GetHeight(p);
                    p.y = centre;
                    blockedAt = p;
                    if (profile.BodyWheel > 0f && !BodyWheelsClear(p, centre, normal, profile)) return false;
                    float low = Mathf.Min(centre, Mathf.Min(TerrainMeta.HeightMap.GetHeight(p + normal * body),
                                                            TerrainMeta.HeightMap.GetHeight(p - normal * body)));
                    if (AnyRouteBlocker(new Vector3(p.x, low + profile.CorridorLift, p.z),
                                        new Vector3(body, profile.CorridorHalfHeight, run * 0.5f), rotation, BodyMask))
                        return false;
                }
                blockedAt = b;
                return true;
            }
            private static bool BodyWheelsClear(Vector3 p, float centre, Vector3 normal, GroundProfile profile)
            {
                float wheel = profile.BodyWheel;
                float left = TerrainMeta.HeightMap.GetHeight(p - normal * wheel);
                float right = TerrainMeta.HeightMap.GetHeight(p + normal * wheel);
                if (Mathf.Abs(left - right) > Mathf.Tan(profile.BodyCross * Mathf.Deg2Rad) * 2f * wheel) return false;
                return GroundAt(p, centre, profile) != Ground.Ledge && GroundAt(p - normal * wheel, left, profile) != Ground.Ledge
                       && GroundAt(p + normal * wheel, right, profile) != Ground.Ledge;
            }
            #endregion

            #region Поверхность и препятствия
            public static Ground GroundAt(Vector3 p, float terrain, GroundProfile profile)
            {
                if (!Physics.Raycast(new Vector3(p.x, terrain + TopProbe, p.z), Vector3.down, out RaycastHit hit, TopProbe + 0.5f, SurfaceMask,
                                     QueryTriggerInteraction.Ignore) || hit.collider is TerrainCollider)
                    return Ground.Terrain;
                if (IsRoadMesh(hit.collider.name)) return Ground.Road;
                if (hit.point.y - terrain <= profile.LedgeStep || !CoreRoutes.RouteBlocks(hit.collider)) return Ground.Terrain;
                if (profile.DeckOverWater && hit.normal.y >= 0.8f
                    && WaterLevel.GetOverallWaterDepth(p, waves: false, volumes: true) > profile.WaterDepth)
                    return Ground.Deck;
                return Ground.Ledge;
            }
            public static string ObstacleAt(Vector3 point)
            {
                float ground = TerrainMeta.HeightMap.GetHeight(point);
                Vector3 probe = new Vector3(point.x, Mathf.Max(point.y, ground) + 0.5f, point.z);
                int count = Physics.OverlapSphereNonAlloc(probe, 2f, _wideHits, ObstacleMask, QueryTriggerInteraction.Ignore);
                string name = "slope or water";
                float best = float.MaxValue;
                for (int i = 0; i < count; i++)
                {
                    Collider collider = _wideHits[i];
                    _wideHits[i] = null;
                    if (collider == null || !CoreRoutes.RouteBlocks(collider)) continue;
                    float distance = (collider.ClosestPointOnBounds(point) - point).sqrMagnitude;
                    if (distance >= best) continue;
                    best = distance;
                    BaseEntity entity = collider.ToBaseEntity();
                    name = entity != null ? entity.ShortPrefabName : collider.name;
                }
                return name;
            }
            public static bool SolidAt(Vector3 point, GroundProfile profile)
            {
                float ground = TerrainMeta.HeightMap.GetHeight(point);
                return AnyRouteBlocker(new Vector3(point.x, ground + profile.CorridorLift, point.z),
                                       new Vector3(profile.RockCorridor, profile.CorridorHalfHeight, profile.RockCorridor), Quaternion.identity,
                                       SolidMask);
            }
            public static bool LineWet(Vector3 a, Vector3 b, float step, float depth)
            {
                float length = CoreEx.DistanceFlat(a, b);
                step = Mathf.Max(0.1f, step);
                for (float d = 0f; d <= length; d += step)
                {
                    Vector3 p = Vector3.Lerp(a, b, length > 0.01f ? d / length : 1f);
                    p.y = TerrainMeta.HeightMap.GetHeight(p);
                    if (WaterLevel.GetOverallWaterDepth(p, waves: false, volumes: true) > depth) return true;
                }
                return false;
            }
            public static bool AreaClear(Vector3 center, Vector3 half, Quaternion rotation, int mask)
            {
                int count = Physics.OverlapBoxNonAlloc(center, half, _hits, rotation, mask, QueryTriggerInteraction.Ignore);
                if (count >= _hits.Length) return false;
                for (int i = 0; i < count; i++)
                {
                    Collider collider = _hits[i];
                    if (collider == null || IsRoadOrBush(collider.name)) continue;
                    return false;
                }
                return true;
            }
            public static bool AnyRouteBlocker(Vector3 center, Vector3 half, Quaternion rotation, int mask)
            {
                int count = Physics.OverlapBoxNonAlloc(center, half, _hits, rotation, mask, QueryTriggerInteraction.Ignore);
                for (int i = 0; i < count; i++)
                    if (CoreRoutes.RouteBlocks(_hits[i])) return true;
                return false;
            }
            public static bool IsRoadMesh(string name)
                => name.StartsWith("Road Mesh", StringComparison.Ordinal) || name.StartsWith("Rail Mesh", StringComparison.Ordinal);
            public static bool IsRoadOrBush(string name) => IsRoadMesh(name) || name.IndexOf("bush", StringComparison.OrdinalIgnoreCase) >= 0;
            #endregion

            #region Обход сбоку
            private const float BypassSpan = 10f;
            public static bool TryBypass(Vector3 a, Vector3 b, Vector3 blockedAt, float[] offsets, float maxSlope, CoreNavLand.LegCheck check,
                                         Func<Vector3, Vector3, bool> accept, out Vector3 via, out Vector3 via2)
            {
                via = via2 = Vector3.zero;
                Vector3 dir = b - a;
                dir.y = 0f;
                if (dir.sqrMagnitude < 0.25f) return false;
                Vector3 normal = new Vector3(dir.z, 0f, -dir.x).normalized;
                Vector3 along = dir.normalized;
                foreach (float offset in offsets)
                {
                    for (int side = -1; side <= 1; side += 2)
                    {
                        Vector3 p = blockedAt + normal * (offset * side);
                        if (!BypassPoint(ref p, maxSlope)) continue;
                        if (!check(a, p, out _) || !check(p, b, out _) || (accept != null && !accept(p, Vector3.zero))) continue;
                        via = p;
                        return true;
                    }
                }
                foreach (float offset in offsets)
                {
                    for (int side = -1; side <= 1; side += 2)
                    {
                        Vector3 p1 = blockedAt + normal * (offset * side) - along * BypassSpan;
                        Vector3 p2 = blockedAt + normal * (offset * side) + along * BypassSpan;
                        if (!BypassPoint(ref p1, maxSlope) || !BypassPoint(ref p2, maxSlope)) continue;
                        if (!check(a, p1, out _) || !check(p1, p2, out _) || !check(p2, b, out _) || (accept != null && !accept(p1, p2)))
                            continue;
                        via = p1;
                        via2 = p2;
                        return true;
                    }
                }
                return false;
            }
            private static bool BypassPoint(ref Vector3 p, float maxSlope)
            {
                p.y = TerrainMeta.HeightMap.GetHeight(p);
                return p.y >= WaterSystem.OceanLevel + 0.5f && TerrainMeta.HeightMap.GetSlope(p) <= maxSlope;
            }
            #endregion

            #region Стоящая техника
            private const float VehicleInflate = 0.3f, ParkedSpeedSqr = 1f;
            private static readonly BaseEntity[] _vehicleGrid = new BaseEntity[64];
            private static readonly Func<BaseEntity, bool> IsRootVehicle
                = entity => (entity is BaseVehicle && !(entity.GetParentEntity() is BaseVehicle)) || entity is HotAirBalloon;

            public struct Footprint
            {
                public BaseEntity Vehicle;
                public Vector3 Center, Right, Forward;
                public float HalfX, HalfZ, Clearance;

                public float Distance(Vector3 p)
                {
                    Vector3 d = p - Center;
                    float dx = Mathf.Max(0f, Mathf.Abs(d.x * Right.x + d.z * Right.z) - HalfX);
                    float dz = Mathf.Max(0f, Mathf.Abs(d.x * Forward.x + d.z * Forward.z) - HalfZ);
                    return Mathf.Sqrt(dx * dx + dz * dz);
                }
                public float Distance(Vector3 a, Vector3 b)
                {
                    Vector3 da = a - Center, db = b - Center;
                    Vector2 p = new Vector2(da.x * Right.x + da.z * Right.z, da.x * Forward.x + da.z * Forward.z);
                    Vector2 q = new Vector2(db.x * Right.x + db.z * Right.z, db.x * Forward.x + db.z * Forward.z);
                    if (Crosses(p, q)) return 0f;
                    float best = Mathf.Min(Distance(a), Distance(b));
                    for (int corner = 0; corner < 4; corner++)
                    {
                        Vector2 c = new Vector2((corner & 1) == 0 ? HalfX : -HalfX, (corner & 2) == 0 ? HalfZ : -HalfZ);
                        best = Mathf.Min(best, PointToSegment(c, p, q));
                    }
                    return best;
                }
                public bool Blocks(Vector3 a, Vector3 b)
                {
                    float start = Distance(a), closest = Distance(a, b);
                    return start >= Clearance ? closest < Clearance : closest <= 0f || closest < start - 0.05f;
                }
                private bool Crosses(Vector2 p, Vector2 q)
                {
                    float t0 = 0f, t1 = 1f;
                    Vector2 d = q - p;
                    return Clip(-d.x, p.x + HalfX, ref t0, ref t1) && Clip(d.x, HalfX - p.x, ref t0, ref t1)
                           && Clip(-d.y, p.y + HalfZ, ref t0, ref t1) && Clip(d.y, HalfZ - p.y, ref t0, ref t1);
                }
                private static bool Clip(float denominator, float numerator, ref float t0, ref float t1)
                {
                    if (Mathf.Abs(denominator) < 1e-6f) return numerator >= 0f;
                    float t = numerator / denominator;
                    if (denominator < 0f)
                    {
                        if (t > t1) return false;
                        if (t > t0) t0 = t;
                    }
                    else
                    {
                        if (t < t0) return false;
                        if (t < t1) t1 = t;
                    }
                    return true;
                }
                private static float PointToSegment(Vector2 c, Vector2 p, Vector2 q)
                {
                    Vector2 d = q - p;
                    float t = d.sqrMagnitude > 1e-6f ? Mathf.Clamp01(Vector2.Dot(c - p, d) / d.sqrMagnitude) : 0f;
                    return (p + d * t - c).magnitude;
                }
            }

            public static BaseEntity RootVehicle(BaseEntity entity)
            {
                for (int depth = 0; depth < 4 && entity != null && entity.GetParentEntity() is BaseVehicle parent; depth++) entity = parent;
                return entity;
            }
            public static bool IsParked(BaseEntity vehicle) => vehicle.GetWorldVelocity().sqrMagnitude <= ParkedSpeedSqr;
            public static bool VehicleFootprint(BaseEntity vehicle, float clearance, out Footprint footprint)
            {
                footprint = default;
                if (vehicle == null || vehicle.IsDestroyed) return false;
                Transform root = vehicle.transform;
                Quaternion yaw = Quaternion.Euler(0f, root.eulerAngles.y, 0f);
                Vector3 right = yaw * Vector3.right, forward = yaw * Vector3.forward;
                float minX = float.MaxValue, maxX = float.MinValue, minZ = float.MaxValue, maxZ = float.MinValue;
                if (vehicle is HotAirBalloon)
                {
                    if (!EventGroundPilot.BalloonFootprint(vehicle, out Vector3 foot, out Vector3 half)) return false;
                    AddBox(root, root.position, right, forward, foot, half, ref minX, ref maxX, ref minZ, ref maxZ);
                }
                else
                {
                    AddBox(root, root.position, right, forward, vehicle.bounds.center, vehicle.bounds.extents, ref minX, ref maxX, ref minZ, ref maxZ);
                    foreach (BaseEntity child in vehicle.children)
                        if (child is BaseVehicle module && module.bounds.extents.sqrMagnitude > 0.01f)
                            AddBox(module.transform, root.position, right, forward, module.bounds.center, module.bounds.extents, ref minX, ref maxX, ref minZ,
                                ref maxZ);
                }
                if (minX > maxX || (maxX - minX < 0.1f && maxZ - minZ < 0.1f)) return false;
                footprint = new Footprint
                {
                    Vehicle = vehicle, Right = right, Forward = forward, Clearance = clearance,
                    Center = root.position + right * ((minX + maxX) * 0.5f) + forward * ((minZ + maxZ) * 0.5f),
                    HalfX = (maxX - minX) * 0.5f + VehicleInflate, HalfZ = (maxZ - minZ) * 0.5f + VehicleInflate
                };
                return true;
            }
            private static void AddBox(Transform transform, Vector3 origin, Vector3 right, Vector3 forward, Vector3 center, Vector3 extents,
                                       ref float minX, ref float maxX, ref float minZ, ref float maxZ)
            {
                for (int corner = 0; corner < 8; corner++)
                {
                    Vector3 local = center + new Vector3((corner & 1) == 0 ? extents.x : -extents.x, (corner & 2) == 0 ? extents.y : -extents.y,
                                                         (corner & 4) == 0 ? extents.z : -extents.z);
                    Vector3 d = transform.TransformPoint(local) - origin;
                    float x = d.x * right.x + d.z * right.z, z = d.x * forward.x + d.z * forward.z;
                    minX = Mathf.Min(minX, x);
                    maxX = Mathf.Max(maxX, x);
                    minZ = Mathf.Min(minZ, z);
                    maxZ = Mathf.Max(maxZ, z);
                }
            }
            public static void ParkedFootprints(Vector3 around, float radius, float clearance, BaseEntity own, EventGroundPilot pilot, List<Footprint> into)
            {
                if (BaseEntity.Query.Server == null) return;
                Vector3 level = own != null ? own.transform.position : around;
                int count = BaseEntity.Query.Server.GetInSphere(around, radius, _vehicleGrid, IsRootVehicle);
                for (int i = 0; i < count; i++)
                {
                    BaseEntity vehicle = _vehicleGrid[i];
                    if (vehicle == null || vehicle.IsDestroyed || vehicle == own || !IsParked(vehicle) || EventGroundPilot.IsBalloonAloft(vehicle, level)
                        || (pilot != null && pilot.IsLightObstacle(null, vehicle)) || !VehicleFootprint(vehicle, clearance, out Footprint footprint))
                        continue;
                    into.Add(footprint);
                }
                System.Array.Clear(_vehicleGrid, 0, _vehicleGrid.Length);
            }
            #endregion
        }

        public static class GroundRoads
        {
            public const float SeamLength = 18f;
            public const float SeamMaxChord = 35f;
            private const float TurnSpotMaxRise = 3f, TurnGridStep = 5f, TurnGridGrade = 0.325f;
            private const int TurnGridHalf = 2;
            private static readonly float[,] _turnGrid = new float[TurnGridHalf * 2 + 1, TurnGridHalf * 2 + 1];
            private struct RoadPoint
            {
                public float Width;
                public int Road;
            }
            private static readonly Dictionary<HelperVehicles.RoadClass, Dictionary<Vector3, RoadPoint>> _roadPoints = new();

            #region Дороги
            public static List<PathList> Roads(HelperVehicles.RoadClass classes)
            {
                List<PathList> roads = new List<PathList>();
                TerrainPath map = TerrainMeta.Path;
                if (map == null) return roads;
                if (classes == HelperVehicles.RoadClass.All)
                {
                    if (map.Roads != null) roads.AddRange(map.Roads);
                    return roads;
                }
                if ((classes & HelperVehicles.RoadClass.Main) != 0 && map.MainRoads != null) roads.AddRange(map.MainRoads);
                if ((classes & HelperVehicles.RoadClass.Side) != 0 && map.SideRoads != null) roads.AddRange(map.SideRoads);
                if ((classes & HelperVehicles.RoadClass.Trail) != 0 && map.TrailRoads != null) roads.AddRange(map.TrailRoads);
                return roads;
            }
            public static bool RoadPointAt(Vector3 point, HelperVehicles.RoadClass classes, out float width, out int road)
            {
                if (!_roadPoints.TryGetValue(classes, out Dictionary<Vector3, RoadPoint> points))
                {
                    points = new Dictionary<Vector3, RoadPoint>();
                    List<PathList> roads = Roads(classes);
                    for (int r = 0; r < roads.Count; r++)
                    {
                        Vector3[] nodes = roads[r]?.Path?.Points;
                        if (nodes == null) continue;
                        foreach (Vector3 p in nodes)
                            if (!points.TryGetValue(p, out RoadPoint known) || roads[r].Width > known.Width)
                                points[p] = new RoadPoint { Width = roads[r].Width, Road = r };
                    }
                    if (TerrainMeta.Path != null) _roadPoints[classes] = points;
                }
                bool found = points.TryGetValue(point, out RoadPoint at);
                width = at.Width;
                road = found ? at.Road : -1;
                return found;
            }
            public static bool IsSeam(float chord, int roadA, int roadB) => roadA >= 0 && roadB >= 0 ? roadA != roadB : chord > SeamLength;
            public static bool NearCrossRoad(Vector3 point, Vector3 along, List<PathList> roads, float reach)
            {
                if (roads == null) return false;
                float reachSqr = reach * reach;
                foreach (PathList road in roads)
                {
                    Vector3[] points = road?.Path?.Points;
                    if (points == null) continue;
                    for (int i = 0; i + 1 < points.Length; i++)
                    {
                        Vector3 a = points[i], ab = points[i + 1] - a, ap = point - a;
                        ab.y = 0f;
                        ap.y = 0f;
                        float length = ab.sqrMagnitude;
                        if (length < 0.0001f) continue;
                        float t = Mathf.Clamp01(Vector3.Dot(ap, ab) / length);
                        if ((ap - ab * t).sqrMagnitude > reachSqr) continue;
                        float angle = Vector3.Angle(ab, along);
                        if (angle > 50f && angle < 130f) return true;
                    }
                }
                return false;
            }
            private static int RoadOf(Vector3 point, HelperVehicles.RoadClass classes) => RoadPointAt(point, classes, out _, out int road) ? road : -1;
            #endregion

            #region Швы
            public sealed class SeamReport
            {
                public int Failed, Moved, Bypassed;
                public int Left => Failed - Moved - Bypassed;
            }
            public static List<Vector3> RepairSeams(List<Vector3> route, GroundProfile profile, out SeamReport report)
            {
                report = new SeamReport();
                if (route == null || route.Count < 2) return route;
                List<Vector3> result = new List<Vector3>(route);
                List<PathList> roads = Roads(profile.RoadClasses);
                for (int i = 0; i + 1 < result.Count; i++)
                {
                    Vector3 a = result[i], b = result[i + 1];
                    int roadA = RoadOf(a, profile.RoadClasses), roadB = RoadOf(b, profile.RoadClasses);
                    float chord = CoreEx.DistanceFlat(a, b);
                    if (chord > profile.SeamReach || !IsSeam(chord, roadA, roadB) || SeamClear(a, b, profile, out Vector3 blockedAt)) continue;
                    report.Failed++;
                    if (roadA >= 0 && roadB >= 0 && MoveSeam(result, ref i, roads, roadA, roadB, profile)) report.Moved++;
                    else if (BypassSeam(result, ref i, blockedAt, profile)) report.Bypassed++;
                }
                return result;
            }
            private static bool SeamClear(Vector3 a, Vector3 b, GroundProfile profile, out Vector3 blockedAt)
                => profile.SeamCheck != null ? profile.SeamCheck(a, b, out blockedAt) : GroundChecks.Line(a, b, profile, 0f, out blockedAt);
            private sealed class SeamEnd
            {
                public Vector3[] Points;
                public int At, Dir;
                public readonly List<int> Run = new();
                public int Far => Run[Run.Count - 1];
            }
            private static bool MoveSeam(List<Vector3> route, ref int i, List<PathList> roads, int roadA, int roadB, GroundProfile profile)
            {
                SeamEnd a = SeamEndOf(route, i, -1, roads, roadA), b = SeamEndOf(route, i + 1, 1, roads, roadB);
                if (a == null || b == null || !FindSeam(route, i, a, b, profile, out int exitA, out int entryB)) return false;
                SpliceSeam(route, ref i, a, b, exitA, entryB);
                return true;
            }
            private static SeamEnd SeamEndOf(List<Vector3> route, int at, int step, List<PathList> roads, int road)
            {
                Vector3[] points = road < roads.Count ? roads[road]?.Path?.Points : null;
                int index = points != null ? Array.IndexOf(points, route[at]) : -1;
                if (index < 0) return null;
                SeamEnd end = new SeamEnd { Points = points, At = index };
                end.Run.Add(index);
                for (int k = at + step; k >= 0 && k < route.Count; k += step)
                {
                    int next = Array.IndexOf(points, route[k]), last = end.Far;
                    int d = next < 0 ? 0 : step > 0 ? Math.Sign(next - last) : Math.Sign(last - next);
                    if (d == 0 || (end.Dir != 0 && d != end.Dir)) break;
                    end.Dir = d;
                    end.Run.Add(next);
                }
                return end;
            }
            private static bool FindSeam(List<Vector3> route, int i, SeamEnd a, SeamEnd b, GroundProfile profile, out int exitA, out int entryB)
            {
                exitA = entryB = -1;
                List<int> windowA = SeamWindow(a, profile), windowB = SeamWindow(b, profile);
                Vector3 routeIn = i > 0 ? Flat(route[i] - route[i - 1]) : Vector3.zero;
                Vector3 routeOut = i + 2 < route.Count ? Flat(route[i + 2] - route[i + 1]) : Vector3.zero;
                float best = float.MaxValue;
                foreach (int ja in windowA)
                {
                    if ((ja - a.Far) * a.Dir < 0) continue;
                    Vector3 inbound = RoadHeading(a, ja, false, routeIn, profile);
                    foreach (int jb in windowB)
                    {
                        if ((b.Far - jb) * b.Dir < 0 || (ja == a.At && jb == b.At)) continue;
                        float chord = CoreEx.DistanceFlat(a.Points[ja], b.Points[jb]);
                        if (chord > SeamMaxChord || chord < profile.SeamMinChord) continue;
                        Vector3 across = Flat(b.Points[jb] - a.Points[ja]);
                        Vector3 outbound = RoadHeading(b, jb, true, routeOut, profile);
                        if (!SeamTurns(inbound, across, outbound, profile, out float turnIn, out float turnOut)) continue;
                        float cost = SeamCost(a, ja, b, jb, chord, turnIn, turnOut, profile);
                        if (cost >= best || !SeamClear(a.Points[ja], b.Points[jb], profile, out _)) continue;
                        best = cost;
                        exitA = ja;
                        entryB = jb;
                    }
                }
                return exitA >= 0;
            }
            private static List<int> SeamWindow(SeamEnd end, GroundProfile profile)
            {
                List<int> window = new List<int> { end.At };
                if (end.Dir == 0) return window;
                for (int dir = -1; dir <= 1; dir += 2)
                {
                    float walked = 0f;
                    for (int j = end.At + dir; j >= 0 && j < end.Points.Length && Mathf.Abs(j - end.At) <= profile.SeamWindowNodes; j += dir)
                    {
                        walked += CoreEx.DistanceFlat(end.Points[j - dir], end.Points[j]);
                        if (walked > profile.SeamWindowLength) break;
                        window.Add(j);
                    }
                }
                return window;
            }
            private static Vector3 RoadHeading(SeamEnd end, int j, bool leaving, Vector3 route, GroundProfile profile)
            {
                int other = leaving ? j + end.Dir : j - end.Dir;
                if (end.Dir != 0 && other >= 0 && other < end.Points.Length)
                    return Flat(leaving ? end.Points[other] - end.Points[j] : end.Points[j] - end.Points[other]);
                return profile.SeamTurnFromRoute ? route : Vector3.zero;
            }
            private static bool SeamTurns(Vector3 inbound, Vector3 across, Vector3 outbound, GroundProfile profile, out float turnIn,
                                          out float turnOut)
            {
                if (across.sqrMagnitude < profile.SeamSingleTurn * profile.SeamSingleTurn)
                {
                    turnIn = Turn(inbound, outbound);
                    turnOut = 0f;
                }
                else
                {
                    turnIn = Turn(inbound, across);
                    turnOut = Turn(across, outbound);
                }
                return turnIn <= profile.SeamMaxTurn && turnOut <= profile.SeamMaxTurn;
            }
            private static float Turn(Vector3 a, Vector3 b) => a.sqrMagnitude > 0.01f && b.sqrMagnitude > 0.01f ? Vector3.Angle(a, b) : 0f;
            private static float SeamCost(SeamEnd a, int ja, SeamEnd b, int jb, float chord, float turnIn, float turnOut, GroundProfile profile)
            {
                float cost = chord;
                if (profile.SeamRoadCost != 0f)
                    cost = profile.SeamRoadCost * RoadSpan(a.Points, a.At, ja) * (Math.Sign(ja - a.At) == a.Dir ? 1f : -1f) + chord
                           + profile.SeamRoadCost * RoadSpan(b.Points, jb, b.At) * (Math.Sign(b.At - jb) == b.Dir ? 1f : -1f);
                if (profile.SeamNodeCost != 0f) cost += profile.SeamNodeCost * (Mathf.Abs(ja - a.At) + Mathf.Abs(jb - b.At));
                if (profile.SeamTurnCost != 0f) cost += (turnIn + turnOut) * profile.SeamTurnCost;
                if (profile.SeamSharpCost != 0f)
                    cost += (Mathf.Max(0f, turnIn - profile.SeamEasyTurn) + Mathf.Max(0f, turnOut - profile.SeamEasyTurn)) * profile.SeamSharpCost;
                return cost;
            }
            private static float RoadSpan(Vector3[] points, int from, int to)
            {
                float length = 0f;
                for (int j = Mathf.Min(from, to); j < Mathf.Max(from, to); j++) length += CoreEx.DistanceFlat(points[j], points[j + 1]);
                return length;
            }
            private static void SpliceSeam(List<Vector3> route, ref int i, SeamEnd a, SeamEnd b, int exitA, int entryB)
            {
                int dropA = 0, dropB = 0;
                while (dropA + 1 < a.Run.Count && (a.Run[dropA] - exitA) * a.Dir > 0) dropA++;
                while (dropB + 1 < b.Run.Count && (entryB - b.Run[dropB]) * b.Dir > 0) dropB++;
                List<Vector3> joint = new List<Vector3>();
                for (int p = a.Run[dropA] + a.Dir; a.Dir != 0 && (exitA - p) * a.Dir >= 0; p += a.Dir) joint.Add(a.Points[p]);
                int alongA = joint.Count;
                for (int p = entryB; b.Dir != 0 && (b.Run[dropB] - p) * b.Dir > 0; p += b.Dir) joint.Add(b.Points[p]);
                int removeFrom = i - dropA + 1;
                route.RemoveRange(removeFrom, dropA + dropB);
                route.InsertRange(removeFrom, joint);
                i = removeFrom - 1 + alongA;
            }
            private static bool BypassSeam(List<Vector3> route, ref int i, Vector3 blockedAt, GroundProfile profile)
            {
                if (profile.SeamBypass == null || profile.SeamBypass.Length == 0) return false;
                Vector3 a = route[i], b = route[i + 1];
                Vector3 inbound = i > 0 ? a - route[i - 1] : Vector3.zero;
                Vector3 outbound = i + 2 < route.Count ? route[i + 2] - b : Vector3.zero;
                bool Clear(Vector3 from, Vector3 to, out Vector3 at) => SeamClear(from, to, profile, out at);
                bool Gentle(Vector3 v1, Vector3 v2) => GentleTurns(inbound, a, v1, v2, b, outbound, profile.SeamMaxTurn);
                if (!GroundChecks.TryBypass(a, b, blockedAt, profile.SeamBypass, profile.LegMaxGrade, Clear, Gentle, out Vector3 via,
                        out Vector3 via2))
                    return false;
                route.Insert(++i, via);
                if (via2 != Vector3.zero) route.Insert(++i, via2);
                return true;
            }
            private static bool GentleTurns(Vector3 inbound, Vector3 a, Vector3 v1, Vector3 v2, Vector3 b, Vector3 outbound, float maxTurn)
            {
                List<Vector3> legs = new List<Vector3> { inbound, v1 - a };
                if (v2 != Vector3.zero)
                {
                    legs.Add(v2 - v1);
                    legs.Add(b - v2);
                }
                else legs.Add(b - v1);
                legs.Add(outbound);
                for (int k = 0; k + 1 < legs.Count; k++)
                {
                    Vector3 from = legs[k], to = legs[k + 1];
                    from.y = to.y = 0f;
                    if (from.sqrMagnitude < 0.01f || to.sqrMagnitude < 0.01f) continue;
                    if (Vector3.Angle(from, to) > maxTurn) return false;
                }
                return true;
            }
            private static Vector3 Flat(Vector3 v) => new Vector3(v.x, 0f, v.z);
            #endregion

            #region Концы под разворот
            public static List<Vector3> TrimEnds(List<Vector3> route, GroundProfile profile, out int cramped)
            {
                cramped = 0;
                if (route == null || route.Count < 4) return route;
                List<PathList> roads = profile.TurnSpotJunction > 0f ? Roads(profile.RoadClasses) : null;
                int first = TurnSpotIndex(route, 0, 1, profile, roads);
                int last = TurnSpotIndex(route, route.Count - 1, -1, profile, roads);
                if (first < 0) cramped++;
                if (last < 0) cramped++;
                if (first < 0) first = 0;
                if (last < 0) last = route.Count - 1;
                if (first == 0 && last == route.Count - 1) return route;
                List<Vector3> trimmed = last - first >= 2 ? route.GetRange(first, last - first + 1) : null;
                if (trimmed == null || CoreEx.Distance(trimmed) < profile.MinRouteLength)
                {
                    if (first > 0) cramped++;
                    if (last < route.Count - 1) cramped++;
                    return route;
                }
                return trimmed;
            }
            private static int TurnSpotIndex(List<Vector3> route, int end, int step, GroundProfile profile, List<PathList> roads)
            {
                float walked = 0f;
                for (int i = end; i >= 0 && i < route.Count; i += step)
                {
                    if (i != end) walked += CoreEx.DistanceFlat(route[i], route[i - step]);
                    if (walked > profile.TurnSpotSearch) break;
                    int next = i + step;
                    if (next < 0 || next >= route.Count) break;
                    Vector3 along = route[next] - route[i];
                    along.y = 0f;
                    if (along.sqrMagnitude < 0.01f) continue;
                    along.Normalize();
                    if (!TurnSpotClear(route[i], along, profile)) continue;
                    if (roads != null && NearCrossRoad(route[i], along, roads, profile.TurnSpotJunction)) continue;
                    return i;
                }
                return -1;
            }
            private static bool TurnSpotClear(Vector3 point, Vector3 along, GroundProfile profile)
            {
                float terrain = TerrainMeta.HeightMap.GetHeight(point);
                if (profile.TurnSpotLevelArea)
                {
                    if (point.y <= terrain + 1f && !TurnSpotLevel(point, along, profile)) return false;
                }
                else if (TerrainMeta.HeightMap.GetSlope(point) > profile.TurnSpotSlope) return false;
                float ground = Mathf.Max(point.y, terrain);
                return GroundChecks.AreaClear(new Vector3(point.x, ground + profile.TurnSpotLift, point.z),
                    new Vector3(profile.TurnSpotHalfWidth, profile.TurnSpotHalfHeight, profile.TurnSpotHalfLength),
                    Quaternion.LookRotation(along, Vector3.up), profile.TurnSpotMask);
            }
            private static bool TurnSpotLevel(Vector3 point, Vector3 along, GroundProfile profile)
            {
                Vector3 across = new Vector3(along.z, 0f, -along.x);
                float low = float.MaxValue, high = float.MinValue;
                for (int x = -1; x <= 1; x++)
                {
                    for (int z = -1; z <= 1; z++)
                    {
                        Vector3 p = point + across * (x * profile.TurnSpotHalfWidth) + along * (z * profile.TurnSpotHalfLength);
                        float h = TerrainMeta.HeightMap.GetHeight(p);
                        low = Mathf.Min(low, h);
                        high = Mathf.Max(high, h);
                        if (TerrainMeta.HeightMap.GetSlope(p) > profile.TurnSpotSlope) return false;
                    }
                }
                if (high - low > TurnSpotMaxRise) return false;
                int size = TurnGridHalf * 2 + 1;
                for (int x = 0; x < size; x++)
                    for (int z = 0; z < size; z++)
                        _turnGrid[x, z] = TerrainMeta.HeightMap.GetHeight(point + across * ((x - TurnGridHalf) * TurnGridStep)
                                                                          + along * ((z - TurnGridHalf) * TurnGridStep));
                float limit = TurnGridStep * TurnGridGrade;
                for (int x = 0; x < size; x++)
                {
                    for (int z = 0; z < size; z++)
                    {
                        if (x + 1 < size && Mathf.Abs(_turnGrid[x + 1, z] - _turnGrid[x, z]) > limit) return false;
                        if (z + 1 < size && Mathf.Abs(_turnGrid[x, z + 1] - _turnGrid[x, z]) > limit) return false;
                    }
                }
                return true;
            }
            #endregion
        }

        public static class GroundCorners
        {
            private const float CornerAngle = 50f, CornerRoom = 3.5f, CornerInset = 1.5f;
            private const float HairpinAngle = 100f, HairpinRoom = 5f, HairpinInset = 3f;
            private const float CornerLeg = 1f;
            private const float ArcMin = 4f, ArcShrink = 0.75f, ArcStep = 45f, ArcMaxTurn = 150f;
            private const float ReshapeReach = 8f, ReshapeStep = 1.5f, ReshapeGain = 25f, ReshapeDetour = 2f, ReshapePrune = 1.2f;
            private const int ReshapeChecks = 120, ReshapeLimit = 6;
            private const float FrameBudget = 4f;
            private static readonly Collider[] _cornerHits = new Collider[32];

            public sealed class Result
            {
                public int Rounded, Reshaped, Tight;
                public readonly List<Vector3> Spots = new List<Vector3>();
            }
            private sealed class Reshape
            {
                public bool Done;
                public int From;
            }
            private struct ReshapeOption
            {
                public int From, To;
                public bool Direct;
                public Vector3 Point;
                public float Cost;
            }

            public static IEnumerator Round(List<Vector3> route, GroundProfile profile, Result result)
            {
                long deadline = Deadline();
                for (int i = 1; i + 1 < route.Count; i++)
                {
                    if (System.Diagnostics.Stopwatch.GetTimestamp() >= deadline)
                    {
                        yield return null;
                        deadline = Deadline();
                    }
                    if (CornerClear(route[i - 1], route[i], route[i + 1], profile)) continue;
                    Vector3 vertex = route[i];
                    int added = RoundCorner(route, i, profile);
                    if (added > 0)
                    {
                        result.Rounded++;
                        i += added - 1;
                        continue;
                    }
                    if (result.Reshaped < ReshapeLimit)
                    {
                        Reshape reshape = new Reshape();
                        IEnumerator steps = ReshapeCorner(route, i, profile, reshape);
                        while (steps.MoveNext()) yield return null;
                        deadline = Deadline();
                        if (reshape.Done)
                        {
                            result.Reshaped++;
                            i = Mathf.Max(1, reshape.From) - 1;
                            continue;
                        }
                    }
                    result.Tight++;
                    result.Spots.Add(vertex);
                }
            }
            private static bool CornerClear(Vector3 prev, Vector3 at, Vector3 next, GroundProfile profile)
            {
                Vector3 a = prev - at, b = next - at;
                a.y = 0f;
                b.y = 0f;
                if (a.magnitude < CornerLeg || b.magnitude < CornerLeg) return true;
                float turn = 180f - Vector3.Angle(a, b);
                if (turn < CornerAngle) return true;
                Vector3 inside = a.normalized + b.normalized;
                inside = inside.sqrMagnitude > 0.0001f ? inside.normalized : new Vector3(-a.z, 0f, a.x).normalized;
                bool hairpin = turn >= HairpinAngle;
                Vector3 center = at + inside * (hairpin ? HairpinInset : CornerInset);
                float ground = TerrainMeta.HeightMap.GetHeight(center);
                if (GroundChecks.GroundAt(center, ground, profile) == GroundChecks.Ground.Road) return true;
                float radius = hairpin ? HairpinRoom : CornerRoom;
                int count = Physics.OverlapSphereNonAlloc(new Vector3(center.x, ground + 1f, center.z), radius, _cornerHits,
                    GroundChecks.ObstacleMask, QueryTriggerInteraction.Ignore);
                bool clear = true;
                for (int i = 0; i < count; i++)
                {
                    Collider collider = _cornerHits[i];
                    _cornerHits[i] = null;
                    if (!clear || !CoreRoutes.RouteBlocks(collider)) continue;
                    Bounds bounds = collider.bounds;
                    if (bounds.max.y < TerrainMeta.HeightMap.GetHeight(bounds.center) + profile.LedgeStep) continue;
                    clear = false;
                }
                return clear;
            }
            private static float CornerTurn(Vector3 prev, Vector3 at, Vector3 next)
            {
                Vector3 a = at - prev, b = next - at;
                a.y = 0f;
                b.y = 0f;
                return a.magnitude < CornerLeg || b.magnitude < CornerLeg ? 0f : Vector3.Angle(a, b);
            }
            private static IEnumerator ReshapeCorner(List<Vector3> route, int i, GroundProfile profile, Reshape result)
            {
                List<ReshapeOption> options = ReshapeOptions(route, i);
                long deadline = Deadline();
                int checks = 0;
                List<Vector3> blocks = new List<Vector3>();
                foreach (ReshapeOption option in options)
                {
                    if (checks >= ReshapeChecks) break;
                    if (System.Diagnostics.Stopwatch.GetTimestamp() >= deadline)
                    {
                        yield return null;
                        deadline = Deadline();
                    }
                    Vector3 a = route[option.From], b = route[option.To];
                    bool passes = option.Direct
                        ? ReshapeLeg(a, b, profile, blocks, ref checks)
                        : ReshapeLeg(a, option.Point, profile, blocks, ref checks) && ReshapeLeg(option.Point, b, profile, blocks, ref checks);
                    if (!passes) continue;
                    route.RemoveRange(option.From + 1, option.To - option.From - 1);
                    if (!option.Direct) route.Insert(option.From + 1, option.Point);
                    result.Done = true;
                    result.From = option.From;
                    break;
                }
            }
            private static List<ReshapeOption> ReshapeOptions(List<Vector3> route, int i)
            {
                float original = CornerTurn(route[i - 1], route[i], route[i + 1]);
                List<ReshapeOption> options = new List<ReshapeOption>();
                for (int window = 0; window < 4; window++)
                {
                    int from = i - 1 - (window >> 1), to = i + 1 + (window & 1);
                    if (from < 0 || to >= route.Count) continue;
                    bool ground = true;
                    float before = 0f;
                    Vector3 centre = Vector3.zero;
                    for (int k = from; k <= to && ground; k++)
                    {
                        ground = Mathf.Abs(route[k].y - TerrainMeta.HeightMap.GetHeight(route[k])) <= 0.5f;
                        if (k > from) before += CoreEx.DistanceFlat(route[k - 1], route[k]);
                        if (k > from && k < to) centre += route[k];
                    }
                    if (!ground) continue;
                    centre /= to - from - 1;
                    AddReshape(options, route, from, to, true, Vector3.zero, original, before);
                    for (float dx = -ReshapeReach; dx <= ReshapeReach + 0.01f; dx += ReshapeStep)
                    for (float dz = -ReshapeReach; dz <= ReshapeReach + 0.01f; dz += ReshapeStep)
                    {
                        if (dx * dx + dz * dz > ReshapeReach * ReshapeReach) continue;
                        Vector3 point = new Vector3(centre.x + dx, 0f, centre.z + dz);
                        point.y = TerrainMeta.HeightMap.GetHeight(point);
                        AddReshape(options, route, from, to, false, point, original, before);
                    }
                }
                options.Sort((x, y) => x.Cost.CompareTo(y.Cost));
                return options;
            }
            private static bool ReshapeLeg(Vector3 a, Vector3 b, GroundProfile profile, List<Vector3> blocks, ref int checks)
            {
                for (int k = 0; k < blocks.Count; k++)
                {
                    Vector3 block = blocks[k];
                    if (CoreEx.DistanceFlat(block, a) < 2f || CoreEx.DistanceFlat(block, b) < 2f) continue;
                    if (CoreEx.DistanceFlatToSegment(block, a, b) < ReshapePrune) return false;
                }
                checks++;
                if (GroundChecks.Leg(a, b, profile, out Vector3 blockedAt)) return true;
                blocks.Add(blockedAt);
                return false;
            }
            private static void AddReshape(List<ReshapeOption> options, List<Vector3> route, int from, int to, bool direct, Vector3 point,
                                           float original, float before)
            {
                Vector3 a = route[from], b = route[to];
                Vector3 afterA = direct ? b : point, beforeB = direct ? a : point;
                if (CoreEx.DistanceFlat(a, afterA) < 2f * CornerLeg || CoreEx.DistanceFlat(beforeB, b) < 2f * CornerLeg) return;
                float worst = 0f;
                if (from > 0) worst = CornerTurn(route[from - 1], a, afterA);
                if (!direct) worst = Mathf.Max(worst, CornerTurn(a, point, b));
                if (to < route.Count - 1) worst = Mathf.Max(worst, CornerTurn(beforeB, b, route[to + 1]));
                if (worst > original - ReshapeGain) return;
                float length = direct ? CoreEx.DistanceFlat(a, b) : CoreEx.DistanceFlat(a, point) + CoreEx.DistanceFlat(point, b);
                float cost = worst + ReshapeDetour * Mathf.Max(0f, length - before);
                options.Add(new ReshapeOption { From = from, To = to, Direct = direct, Point = point, Cost = cost });
            }
            private static long Deadline()
                => System.Diagnostics.Stopwatch.GetTimestamp() + (long)(FrameBudget * System.Diagnostics.Stopwatch.Frequency / 1000d);
            private static int RoundCorner(List<Vector3> route, int i, GroundProfile profile)
            {
                Vector3 at = route[i];
                if (Mathf.Abs(at.y - TerrainMeta.HeightMap.GetHeight(at)) > 0.5f) return 0;
                Vector3 a = route[i - 1] - at, b = route[i + 1] - at;
                a.y = 0f;
                b.y = 0f;
                float inLength = a.magnitude, outLength = b.magnitude;
                if (inLength < 2f * CornerLeg || outLength < 2f * CornerLeg) return 0;
                a /= inLength;
                b /= outLength;
                float turn = 180f - Vector3.Angle(a, b);
                if (turn < CornerAngle || turn >= ArcMaxTurn) return 0;
                float half = turn * 0.5f * Mathf.Deg2Rad, tan = Mathf.Tan(half), sin = Mathf.Sin(half);
                Vector3 inside = (a + b).normalized;
                int pieces = Mathf.CeilToInt(turn / ArcStep);
                List<Vector3> arc = new List<Vector3>(pieces + 1);
                for (float tangent = Mathf.Min(profile.TurnRadius * tan, inLength - CornerLeg, outLength * 0.5f);
                     tangent / tan >= ArcMin;
                     tangent *= ArcShrink)
                {
                    Vector3 centre = at + inside * (tangent / sin), from = at + a * tangent - centre;
                    float sweep = Vector3.SignedAngle(from, at + b * tangent - centre, Vector3.up);
                    arc.Clear();
                    bool clear = true;
                    for (int k = 0; k <= pieces && clear; k++)
                    {
                        Vector3 p = centre + Quaternion.AngleAxis(sweep * k / pieces, Vector3.up) * from;
                        p.y = TerrainMeta.HeightMap.GetHeight(p);
                        if (k > 0 && !GroundChecks.Leg(arc[k - 1], p, profile, out _)) clear = false;
                        arc.Add(p);
                    }
                    if (!clear) continue;
                    route.RemoveAt(i);
                    route.InsertRange(i, arc);
                    return arc.Count;
                }
                return 0;
            }
        }

        public abstract class BaseGroundEventController<T> : BaseEventController<T> where T : CovalencePlugin
        {
            private GroundProfile _profile;
            protected GroundProfile Profile => _profile ??= CreateProfile() ?? new GroundProfile();
            protected abstract GroundProfile CreateProfile();
            public int Teleports { get; private set; }
            public int Replans { get; private set; }

            #region Хуки наследника
            protected bool HoldsPlace => Pilot is EventGroundPilot ground && ground.Waiting;
            protected IEnumerator RefineReplan(ReplanPiece piece)
            {
                if (Profile.TurnRadius <= 0f) yield break;
                GroundCorners.Result corners = new GroundCorners.Result();
                IEnumerator rounding = GroundCorners.Round(piece.Points, Profile, corners);
                while (rounding.MoveNext()) yield return null;
            }
            public sealed class ReplanPiece
            {
                public List<Vector3> Points;
            }
            #endregion

            #region Ход события
            protected override void OnEventStarted()
            {
                _profile = CreateProfile() ?? new GroundProfile();
                ResetGround();
                Teleports = 0;
                Replans = 0;
                _laneAt = -100f;
                _bodyHalfWidth = _bodyHalfLength = 0f;
                float interval = Mathf.Max(0.1f, Profile.CheckInterval);
                CancelInvoke(CheckGroundProgress);
                InvokeRepeating(CheckGroundProgress, interval, interval);
            }
            protected override void OnEventStopped(BaseVehicle vehicle)
            {
                CancelInvoke(CheckGroundProgress);
                ResetGround();
                StopGenerating();
                ResetQueues();
                base.OnEventStopped(vehicle);
            }
            protected override void OnTickEvent()
            {
                if (Vehicle == null) return;
                if (Pilot is EventGroundPilot ground)
                {
                    _bodyHalfWidth = ground.BodyHalfWidth;
                    _bodyHalfLength = ground.BodyHalfLength;
                }
                TrackFront(Vehicle.transform.position, out _);
                TickQueues();
            }
            protected override bool OnPilotRetakesExhausted()
            {
                if (!HasEvent || Vehicle == null || Vehicle.IsDestroyed) return false;
                return TeleportStuck("pilot let go of the wheel again after 3 retakes", true);
            }
            #endregion

            #region Продвижение
            private enum StandMode
            {
                Route, OffRoute, Chase
            }
            private float _standingSince = -1f;
            private Vector3 _anchor;
            private StandMode _anchorMode;
            private float _anchorFront, _anchorGap;
            private int _anchorEpoch;
            private bool _hasFront;
            private float _front;
            private Vector3 _frontPoint;
            private int _frontSegment;
            private float _frontT;
            private int _frontEpoch, _frontDir;
            private Vector3[] _lengthsFor;
            private float[] _lengths;
            private float _teleportAt;
            private int _teleportFails;
            private float _bodyHalfWidth, _bodyHalfLength;

            protected void RestartStanding() => _standingSince = -1f;
            private float FrontReach => Profile.OffRouteDistance * 2f;

            private void ResetGround()
            {
                _standingSince = -1f;
                _teleportFails = 0;
                ForgetFront();
                StopReplan();
                _replanTried = _replanUnproven = false;
            }
            private void CheckGroundProgress()
            {
                if (!HasEvent || Vehicle == null || Vehicle.IsDestroyed || Pilot == null) return;
                try
                {
                    CheckStanding(Vehicle.transform.position);
                }
                catch (Exception ex)
                {
                    Debug.LogError<T>("Ground progress check [{0} #{1}]: {2}", NameEvent, number, ex);
                }
            }
            private void CheckStanding(Vector3 position)
            {
                if (IsHolding(position))
                {
                    _standingSince = -1f;
                    return;
                }
                bool onRoute = TrackFront(position, out float gap);
                StandMode mode = ModeOf(onRoute);
                bool restarted = _standingSince < 0f;
                if (restarted || Progressed(position, mode, gap))
                {
                    if (!restarted) _replanUnproven = false;
                    Anchor(position, mode, gap);
                    return;
                }
                float now = UnityEngine.Time.time, stood = now - _standingSince;
                if (stood >= Profile.ReplanAfter && ReplanStanding(position, stood)) return;
                if (now < _teleportAt) return;
                TeleportStuck($"made no progress along the route for {stood:0} s", false);
            }
            private bool IsHolding(Vector3 position)
            {
                if (Pilot == null || !Pilot.HasTarget || HoldsPlace) return true;
                if (!IsChasing) return isAggressionTime;
                return ChaseTarget != null && CoreEx.DistanceFlat(position, ChaseTarget.transform.position) <= Profile.ChaseHoldRadius;
            }
            private StandMode ModeOf(bool onRoute) => IsChasing ? StandMode.Chase : onRoute ? StandMode.Route : StandMode.OffRoute;
            private void Anchor(Vector3 position, StandMode mode, float gap)
            {
                _standingSince = UnityEngine.Time.time;
                Rebase(position, mode, gap);
                _teleportAt = _standingSince + Profile.TeleportAfter;
                _teleportFails = 0;
                _replanTried = false;
            }
            private void Rebase(Vector3 position, StandMode mode, float gap)
            {
                _anchor = position;
                _anchorMode = mode;
                _anchorFront = _front;
                _anchorEpoch = _frontEpoch;
                _anchorGap = gap;
            }
            private bool Progressed(Vector3 position, StandMode mode, float gap)
            {
                GroundProfile profile = Profile;
                float radius = profile.StuckRadius;
                bool moved = (position - _anchor).sqrMagnitude > radius * radius;
                if (mode != _anchorMode)
                {
                    if (_anchorMode == StandMode.OffRoute && mode == StandMode.Route) return true;
                    Rebase(position, mode, gap);
                    return false;
                }
                switch (mode)
                {
                    case StandMode.Route:
                        if (_anchorEpoch == _frontEpoch) return _front - _anchorFront >= profile.ProgressStep;
                        Rebase(position, mode, gap);
                        return false;
                    case StandMode.OffRoute:
                        if (gap < float.MaxValue && gap <= _anchorGap - profile.ProgressStep) return true;
                        if (moved) _anchor = position;
                        return false;
                    default:
                        return moved;
                }
            }
            private bool TrackFront(Vector3 position, out float gap)
            {
                gap = float.MaxValue;
                if (IsChasing || routeMode != RouteMode.Points || path == null || path.Length < 2)
                {
                    if (_hasFront) ForgetFront();
                    return false;
                }
                if (!ReferenceEquals(_lengthsFor, path))
                {
                    _lengthsFor = path;
                    _lengths = new float[path.Length];
                    for (int i = 1; i < path.Length; i++) _lengths[i] = _lengths[i - 1] + CoreEx.DistanceFlat(path[i - 1], path[i]);
                    ForgetFront();
                }
                if (RouteDirection != _frontDir)
                {
                    _frontDir = RouteDirection;
                    ForgetFront();
                }
                if (!ProjectOnPath(position, out int segment, out float t, out gap) || gap > Profile.OffRouteDistance) return false;
                float progress = (_lengths[segment] + t * (_lengths[segment + 1] - _lengths[segment])) * _frontDir;
                if (_hasFront && progress <= _front) return true;
                _hasFront = true;
                _front = progress;
                _frontSegment = segment;
                _frontT = t;
                _frontPoint = Vector3.Lerp(path[segment], path[segment + 1], t);
                return true;
            }
            private void ForgetFront()
            {
                _hasFront = false;
                _frontEpoch++;
            }
            private bool ProjectOnPath(Vector3 position, out int segment, out float t, out float offset)
            {
                segment = -1;
                t = 0f;
                offset = float.MaxValue;
                int near = NearestRouteIndex(position);
                if (near < 0) return false;
                for (int i = Mathf.Max(0, near - 1); i <= Mathf.Min(path.Length - 2, near); i++)
                {
                    Vector3 ab = path[i + 1] - path[i], ap = position - path[i];
                    ab.y = 0f;
                    ap.y = 0f;
                    float k = ab.sqrMagnitude > 0.0001f ? Mathf.Clamp01(Vector3.Dot(ap, ab) / ab.sqrMagnitude) : 0f;
                    float distance = (ap - ab * k).magnitude;
                    if (distance >= offset) continue;
                    offset = distance;
                    segment = i;
                    t = k;
                }
                return segment >= 0;
            }
            #endregion

            #region Перестройка куска маршрута
            private static readonly float[] ReplanBands = { 40f, 100f };
            private const float ReplanRejoinAhead = 40f, ReplanClearOf = 15f;
            private const float ReplanReach = 45f, ReplanTurn = 75f, ReplanStartMoved = 3f;
            private const float ReplanRepeatRadius = 15f, ReplanRepeatAfter = 20f;
            private const float ReplanFrameBudget = 4f, ReplanPointSpacing = 0.5f;
            private const float ReplanVehicles = 60f, ParkedAhead = 3f, ParkedTouch = 0.5f;

            private Coroutine _replan;
            private int _replanFinished;
            private bool _replanTried, _replanUnproven;
            private Vector3 _laneSpot;
            private float _laneAt = -100f;

            private sealed class ReplanRun
            {
                public Vector3[] Route;
                public int From, Rejoin, Dir;
                public Vector3 Start, Blocked;
                public float Stood;
                public string Parked;
                public CoreNavLand.LegCheck Check;
                public bool Stopped;
                public bool OnLane => Stood < 0f;
            }

            public void LaneObstacle(Vector3 point)
            {
                if (!CanReplan(false) || !LaneSpotFree(point)) return;
                Vector3 position = Vehicle.transform.position;
                if (CoreEx.DistanceFlat(position, point) > ReplanReach || Profile.LaneSolidOnly && !GroundChecks.SolidAt(point, Profile)) return;
                StartReplan(point, position, -1f, null, ParkedAround(point));
                TakeLaneSpot(point);
            }
            public void ParkedVehicle(BaseEntity vehicle, Vector3 point)
            {
                if (!Profile.ReplanAroundVehicles || vehicle == null || !CanReplan(true) || !LaneSpotFree(point)) return;
                Vector3 position = Vehicle.transform.position;
                if (CoreEx.DistanceFlat(position, point) > ReplanReach) return;
                vehicle = GroundChecks.RootVehicle(vehicle);
                if (!(vehicle is BaseVehicle || vehicle is HotAirBalloon)) return;
                List<GroundChecks.Footprint> blockers = ParkedAround(point);
                if (!blockers.Exists(x => x.Vehicle == vehicle))
                {
                    if (!GroundChecks.VehicleFootprint(vehicle, VehicleClearance, out GroundChecks.Footprint footprint)) return;
                    blockers.Add(footprint);
                }
                StartReplan(point, position, -1f, vehicle.ShortPrefabName, blockers);
                TakeLaneSpot(point);
            }
            private bool LaneSpotFree(Vector3 point)
                => UnityEngine.Time.time - _laneAt >= ReplanRepeatAfter || CoreEx.DistanceFlat(point, _laneSpot) >= ReplanRepeatRadius;
            private void TakeLaneSpot(Vector3 point)
            {
                _laneSpot = point;
                _laneAt = UnityEngine.Time.time;
            }
            private bool ReplanStanding(Vector3 position, float stood)
            {
                if (!CanReplan(Profile.ReplanAroundVehicles)) return false;
                float halfLength = _bodyHalfLength > 0f ? _bodyHalfLength : Profile.DefaultHalfLength;
                Vector3 forward = Vehicle.transform.forward;
                forward.y = 0f;
                bool facing = forward.sqrMagnitude > 0.01f;
                if (facing) forward.Normalize();
                Vector3 blocked = facing ? position + forward * halfLength : position;
                List<GroundChecks.Footprint> blockers = ParkedAround(blocked);
                int parked = blockers != null && facing ? ParkedInFront(blockers, position, forward, halfLength) : -1;
                if (parked < 0 && PathByRoad) return false;
                string name = null;
                if (parked >= 0)
                {
                    blocked = blockers[parked].Center;
                    name = blockers[parked].Vehicle.ShortPrefabName;
                }
                if (StartReplan(blocked, position, stood, name, blockers)) return true;
                _replanTried = true;
                return false;
            }
            private bool CanReplan(bool aroundVehicle)
                => !_replanTried && !_replanUnproven && _replan == null && HasEvent && (!PathByRoad || aroundVehicle) && !IsChasing && !HoldsPlace
                   && Vehicle != null && Pilot != null && routeMode == RouteMode.Points && path != null && path.Length >= 2;
            private bool StartReplan(Vector3 blocked, Vector3 position, float stood, string parked, List<GroundChecks.Footprint> blockers)
            {
                Vector3[] route = path;
                int from = NearestRouteIndex(position);
                int rejoin = from >= 0 ? ReplanRejoin(route, from, blocked, blockers) : -1;
                if (rejoin < 0) return false;
                _replanTried = true;
                HelperVehicles.RememberStuckSpot(blocked);
                GroundProfile profile = Profile;
                bool zones = !PathByRoad;
                LaunchReplan(ReplanRoutine(new ReplanRun
                {
                    Route = route, From = from, Rejoin = rejoin, Dir = RouteDirection, Start = position, Blocked = blocked, Stood = stood,
                    Parked = parked,
                    Check = (Vector3 a, Vector3 b, out Vector3 blockedAt) => GroundChecks.Leg(a, b, profile, blockers, zones, out blockedAt)
                }));
                return true;
            }
            private float VehicleClearance
                => Profile.VehicleMargin + (Profile.BodyHalf > 0f ? Profile.BodyHalf : _bodyHalfWidth > 0f ? _bodyHalfWidth : Profile.DefaultHalfWidth);
            private List<GroundChecks.Footprint> ParkedAround(Vector3 point)
            {
                if (!Profile.ReplanAroundVehicles) return null;
                List<GroundChecks.Footprint> blockers = new List<GroundChecks.Footprint>();
                GroundChecks.ParkedFootprints(point, ReplanVehicles, VehicleClearance, Vehicle, Pilot as EventGroundPilot, blockers);
                return blockers;
            }
            private int ParkedInFront(List<GroundChecks.Footprint> blockers, Vector3 position, Vector3 forward, float halfLength)
            {
                Vector3 tip = position + forward * (halfLength + ParkedAhead);
                float reach = (_bodyHalfWidth > 0f ? _bodyHalfWidth : Profile.DefaultHalfWidth) + ParkedTouch, best = float.MaxValue;
                int found = -1;
                for (int i = 0; i < blockers.Count; i++)
                {
                    if (blockers[i].Distance(position, tip) > reach) continue;
                    float distance = blockers[i].Distance(position);
                    if (distance >= best) continue;
                    best = distance;
                    found = i;
                }
                return found;
            }
            private int ReplanRejoin(Vector3[] route, int from, Vector3 blocked, List<GroundChecks.Footprint> blockers)
            {
                int dir = RouteDirection;
                float along = BlockedAlong(route, from, dir, blocked), walked = 0f;
                for (int i = from + dir; i >= 0 && i < route.Length; i += dir)
                {
                    walked += CoreEx.DistanceFlat(route[i - dir], route[i]);
                    if (walked - along >= ReplanRejoinAhead && CoreEx.DistanceFlat(route[i], blocked) >= ReplanClearOf && !NearParked(blockers, route[i]))
                        return i;
                }
                int last = dir > 0 ? route.Length - 1 : 0;
                return last != from && walked > along && CoreEx.DistanceFlat(route[last], blocked) >= ReplanClearOf ? last : -1;
            }
            private static bool NearParked(List<GroundChecks.Footprint> blockers, Vector3 point)
            {
                if (blockers == null) return false;
                foreach (GroundChecks.Footprint footprint in blockers)
                    if (footprint.Distance(point) < footprint.Clearance) return true;
                return false;
            }
            private static float BlockedAlong(Vector3[] route, int from, int dir, Vector3 blocked)
            {
                float walked = 0f, at = 0f, best = float.MaxValue;
                for (int i = from; i + dir >= 0 && i + dir < route.Length && walked <= ReplanReach * 2f; i += dir)
                {
                    Vector3 ab = route[i + dir] - route[i], ap = blocked - route[i];
                    ab.y = 0f;
                    ap.y = 0f;
                    float leg = ab.magnitude;
                    float t = leg > 0.01f ? Mathf.Clamp01(Vector3.Dot(ap, ab) / (leg * leg)) : 0f;
                    float offset = (ap - ab * t).magnitude;
                    if (offset < best)
                    {
                        best = offset;
                        at = walked + t * leg;
                    }
                    walked += leg;
                }
                return at;
            }
            private IEnumerator ReplanRoutine(ReplanRun run)
            {
                GroundProfile profile = Profile;
                CoreNavLand.Job job = new CoreNavLand.Job
                {
                    From = run.Start, To = run.Route[run.Rejoin], BudgetMs = ReplanFrameBudget, Along = ReplanAlong(run), BandWidths = ReplanBands,
                    Check = run.Check
                };
                IEnumerator building = ReplanSteps(CoreNavLand.Build(job), run);
                while (building.MoveNext()) yield return null;
                if (run.Stopped) yield break;
                if (job.Result.Count == 0)
                {
                    FinishReplan();
                    yield break;
                }
                ReplanPiece piece = new ReplanPiece { Points = new List<Vector3>(job.Result.Count + 2) { run.Start } };
                piece.Points.AddRange(job.Result);
                if (profile.TurnRadius > 0f)
                {
                    int after = run.Rejoin + run.Dir;
                    bool tail = after >= 0 && after < run.Route.Length;
                    if (tail) piece.Points.Add(run.Route[after]);
                    IEnumerator refining = ReplanSteps(RefineReplan(piece), run);
                    while (refining.MoveNext()) yield return null;
                    if (run.Stopped) yield break;
                    if (tail) piece.Points.RemoveAt(piece.Points.Count - 1);
                }
                FinishReplan();
                piece.Points.RemoveAt(0);
                List<Vector3> detour = JoinFromVehicle(piece.Points, run.Start, run.Check);
                if (!ReplaceRouteAhead(run.Route, run.From, run.Rejoin, detour)) yield break;
                Replans++;
                BlackBox.NoteEvent(typeof(T).Name, BlackBoxKind.VehicleReplan, NameEvent, number, null, Vehicle, Replans);
                _replanUnproven = true;
                RestartStanding();
            }
            private static List<Vector3> ReplanAlong(ReplanRun run)
            {
                List<Vector3> along = new List<Vector3> { run.Start };
                for (int i = run.From; ; i += run.Dir)
                {
                    if (CoreEx.DistanceFlat(run.Route[i], along[along.Count - 1]) >= ReplanPointSpacing) along.Add(run.Route[i]);
                    if (i == run.Rejoin) break;
                }
                return along;
            }
            private List<Vector3> JoinFromVehicle(List<Vector3> piece, Vector3 start, CoreNavLand.LegCheck check)
            {
                Vector3 position = Vehicle.transform.position;
                Vector3 heading = Vehicle.transform.forward;
                heading.y = 0f;
                List<Vector3> detour = new List<Vector3> { position };
                int first = 0;
                for (int i = piece.Count - 1; i > 0; i--)
                {
                    Vector3 to = piece[i] - position;
                    to.y = 0f;
                    if (to.magnitude > ReplanReach || Vector3.Angle(heading, to) > ReplanTurn) continue;
                    if (!check(position, piece[i], out _)) continue;
                    first = i;
                    break;
                }
                if (first == 0 && CoreEx.DistanceFlat(start, position) > ReplanStartMoved) detour.Add(start);
                for (int i = first; i < piece.Count; i++)
                    if (CoreEx.DistanceFlat(piece[i], detour[detour.Count - 1]) >= ReplanPointSpacing) detour.Add(piece[i]);
                return detour;
            }
            private IEnumerator ReplanSteps(IEnumerator steps, ReplanRun run)
            {
                while (true)
                {
                    bool more;
                    try { more = steps.MoveNext(); }
                    catch (Exception ex)
                    {
                        if (run.Parked != null) Debug.LogError<T>("{0} #{1}: detour around a parked vehicle on the route failed: {2}", NameEvent, number, ex);
                        else if (run.OnLane) Debug.LogError<T>("{0} #{1}: detour around an obstacle on the off-road line failed: {2}", NameEvent, number, ex);
                        else Debug.LogError<T>("{0} #{1}: replan after standing off-road failed: {2}", NameEvent, number, ex);
                        StopRun(run);
                        yield break;
                    }
                    if (!more) yield break;
                    yield return null;
                    if (!HasEvent || !ReferenceEquals(path, run.Route) || RouteDirection != run.Dir || IsChasing || Vehicle == null)
                    {
                        StopRun(run);
                        yield break;
                    }
                }
            }
            private void StopRun(ReplanRun run)
            {
                FinishReplan();
                run.Stopped = true;
            }
            private void LaunchReplan(IEnumerator routine)
            {
                int finished = _replanFinished;
                Coroutine started = StartCoroutine(routine);
                if (_replanFinished == finished) _replan = started;
            }
            private void FinishReplan()
            {
                _replan = null;
                _replanFinished++;
            }
            private void StopReplan()
            {
                if (_replan == null) return;
                StopCoroutine(_replan);
                FinishReplan();
            }
            #endregion

            #region Перестановка вперёд
            private readonly List<Vector3> _line = new();
            private readonly List<int> _lineIndices = new();
            private readonly List<float> _segmentLengths = new();
            private float _lineLength;
            private readonly List<float> _candidates = new();
            private readonly List<Spot> _teleportSpots = new();
            private struct Spot
            {
                public Vector3 Point, Position;
                public Quaternion Rotation;
                public int Segment;
                public bool Checked, Fits;
            }
            private struct LineCursor
            {
                public int Segment;
                public float Start;
            }

            private bool TeleportStuck(string why, bool exhaustive)
            {
                GroundProfile profile = Profile;
                int last = Mathf.Max(0, profile.TeleportRetries) + 1;
                int from = exhaustive ? 0 : Mathf.Clamp(_teleportFails, 0, last);
                int to = exhaustive ? last : from;
                for (int level = from; level <= to; level++)
                {
                    if (!TeleportAhead(level, out float distance)) continue;
                    Teleports++;
                    BlackBox.NoteEvent(typeof(T).Name, BlackBoxKind.VehicleTeleport, NameEvent, number, why, Vehicle, distance);
                    return true;
                }
                if (exhaustive)
                {
                    return false;
                }
                float now = UnityEngine.Time.time;
                if (++_teleportFails > last)
                {
                    _teleportFails = 0;
                    _teleportAt = now + profile.TeleportAfter;
                }
                else _teleportAt = now + profile.TeleportRetryAfter;
                return false;
            }
            private bool TeleportAhead(int level, out float distance)
            {
                distance = 0f;
                GroundProfile profile = Profile;
                float[] steps = profile.TeleportSteps;
                if (steps == null || steps.Length == 0 || Vehicle == null) return false;
                bool whole = level > profile.TeleportRetries;
                float scale = whole ? 1f : 1 << level;
                float farthest = whole ? Mathf.Max(steps[steps.Length - 1], profile.WholeRouteReach) : steps[steps.Length - 1] * scale;
                Vector3 stuckAt = Vehicle.transform.position;
                if (!BuildTeleportLine(stuckAt, farthest + profile.FacingAhead)) return false;
                FillCandidates(steps, whole, scale, farthest);
                LocateSpots();
                float halfWidth = _bodyHalfWidth > 0f ? _bodyHalfWidth : profile.DefaultHalfWidth;
                float halfLength = _bodyHalfLength > 0f ? _bodyHalfLength : profile.DefaultHalfLength;
                for (int pass = 0; pass < 2; pass++)
                {
                    for (int i = 0; i < _teleportSpots.Count; i++)
                    {
                        Spot spot = _teleportSpots[i];
                        if (pass == 0)
                        {
                            if (CoreRoutes.MonumentAt(spot.Point, CoreLines.ZoneMargin) != null) continue;
                            CheckSpot(ref spot, halfWidth, halfLength, profile);
                            _teleportSpots[i] = spot;
                            if (!spot.Fits || !GroundPlacement.AheadClear(spot.Position, spot.Rotation, halfWidth, halfLength, profile, Vehicle,
                                    DriverBot, CompanionBot))
                                continue;
                        }
                        else
                        {
                            if (!spot.Checked) CheckSpot(ref spot, halfWidth, halfLength, profile);
                            if (!spot.Fits) continue;
                        }
                        GroundPlacement.Place(Vehicle, spot.Position, spot.Rotation, profile.WheelsOffTime, Pilot);
                        distance = CoreEx.DistanceFlat(stuckAt, spot.Position);
                        AfterTeleport(spot.Segment + 1 < _lineIndices.Count ? _lineIndices[spot.Segment + 1] : -1);
                        return true;
                    }
                }
                return false;
            }
            private void CheckSpot(ref Spot spot, float halfWidth, float halfLength, GroundProfile profile)
            {
                spot.Checked = true;
                spot.Fits = GroundPlacement.Ground(spot.Point, out spot.Position)
                            && GroundPlacement.BodyFits(spot.Position, spot.Rotation, halfWidth, halfLength, profile, false, Vehicle, DriverBot,
                                CompanionBot);
            }
            private bool BuildTeleportLine(Vector3 position, float reach)
            {
                _line.Clear();
                _lineIndices.Clear();
                _segmentLengths.Clear();
                _lineLength = 0f;
                bool eventRoute = !IsChasing && routeMode == RouteMode.Points && path != null && path.Length >= 2;
                if (eventRoute) BuildEventLine(position, reach);
                else if (Pilot != null && Pilot.Route != null && Pilot.Route.Count >= 2) BuildPilotLine(position, reach);
                return _line.Count >= 2;
            }
            private void BuildEventLine(Vector3 position, float reach)
            {
                int segment;
                float t;
                if (_hasFront && ReferenceEquals(_lengthsFor, path) && _frontDir == RouteDirection
                    && CoreEx.DistanceFlat(_frontPoint, position) < FrontReach)
                {
                    segment = _frontSegment;
                    t = _frontT;
                }
                else if (!ProjectOnPath(position, out segment, out t, out _)) return;
                int dir = RouteDirection;
                AddLinePoint(Vector3.Lerp(RoutePoint(segment, dir), RoutePoint(segment + 1, dir), t), -1);
                for (int i = dir > 0 ? segment + 1 : segment; i >= 0 && i < path.Length && _lineLength < reach; i += dir)
                    AddLinePoint(RoutePoint(i, dir), i);
            }
            private void BuildPilotLine(Vector3 position, float reach)
            {
                IReadOnlyList<Vector3> route = Pilot.Route;
                int segment = 0;
                float bestT = 0f, best = float.MaxValue;
                for (int i = 0; i + 1 < route.Count; i++)
                {
                    Vector3 ab = route[i + 1] - route[i], ap = position - route[i];
                    ab.y = 0f;
                    ap.y = 0f;
                    float k = ab.sqrMagnitude > 0.0001f ? Mathf.Clamp01(Vector3.Dot(ap, ab) / ab.sqrMagnitude) : 0f;
                    float sqr = (ap - ab * k).sqrMagnitude;
                    if (sqr >= best) continue;
                    best = sqr;
                    segment = i;
                    bestT = k;
                }
                AddLinePoint(Vector3.Lerp(route[segment], route[segment + 1], bestT), -1);
                for (int i = segment + 1; i < route.Count && _lineLength < reach; i++) AddLinePoint(route[i], -1);
            }
            private void AddLinePoint(Vector3 point, int index)
            {
                if (_line.Count > 0)
                {
                    float length = CoreEx.DistanceFlat(_line[_line.Count - 1], point);
                    _segmentLengths.Add(length);
                    _lineLength += length;
                }
                _line.Add(point);
                _lineIndices.Add(index);
            }
            private void FillCandidates(float[] steps, bool whole, float scale, float farthest)
            {
                _candidates.Clear();
                if (whole)
                {
                    float spacing = Mathf.Max(1f, Profile.WholeRouteStep), limit = Mathf.Min(_lineLength, farthest);
                    for (float ahead = steps[0]; ahead < limit; ahead += spacing) _candidates.Add(ahead);
                }
                else
                {
                    foreach (float step in steps)
                        if (step * scale < _lineLength) _candidates.Add(step * scale);
                }
                if (_lineLength < farthest && _lineLength > 1f && (_candidates.Count == 0 || _lineLength - _candidates[_candidates.Count - 1] > 1f))
                    _candidates.Add(_lineLength);
            }
            private void LocateSpots()
            {
                _teleportSpots.Clear();
                LineCursor at = default, facing = default;
                float ahead = Profile.FacingAhead;
                foreach (float distance in _candidates)
                {
                    Vector3 point = Advance(ref at, distance);
                    int segment = Mathf.Min(at.Segment, _line.Count - 2);
                    Vector3 direction = Advance(ref facing, distance + ahead) - point;
                    direction.y = 0f;
                    if (direction.sqrMagnitude <= 1f)
                    {
                        direction = _line[segment + 1] - _line[segment];
                        direction.y = 0f;
                    }
                    Quaternion rotation = direction.sqrMagnitude > 0.01f ? Quaternion.LookRotation(direction.normalized) : Vehicle.transform.rotation;
                    _teleportSpots.Add(new Spot { Point = point, Rotation = rotation, Segment = segment });
                }
            }
            private Vector3 Advance(ref LineCursor cursor, float distance)
            {
                for (; cursor.Segment + 1 < _line.Count; cursor.Segment++)
                {
                    float length = _segmentLengths[cursor.Segment];
                    if (length > 0.01f && cursor.Start + length >= distance)
                        return Vector3.Lerp(_line[cursor.Segment], _line[cursor.Segment + 1], Mathf.Clamp01((distance - cursor.Start) / length));
                    cursor.Start += length;
                }
                return _line[_line.Count - 1];
            }
            private void AfterTeleport(int index)
            {
                StopReplan();
                _replanUnproven = false;
                ResetRetakes();
                if (index >= 0 && !IsChasing) ResumeAhead(index);
                ForgetFront();
                Vector3 position = Vehicle.transform.position;
                bool onRoute = TrackFront(position, out float gap);
                Anchor(position, ModeOf(onRoute), gap);
            }
            private void ResumeAhead(int index)
            {
                Vector3 position = Vehicle.transform.position;
                Vector3 forward = Vehicle.transform.forward;
                forward.y = 0f;
                int dir = RouteDirection, first = index;
                float walked = 0f;
                while (true)
                {
                    Vector3 to = RoutePoint(index, dir) - position;
                    to.y = 0f;
                    if (Vector3.Dot(to, forward) >= Profile.ResumeAheadMin) break;
                    int next = index + dir;
                    if (next < 0 || next >= path.Length) break;
                    walked += CoreEx.DistanceFlat(path[index], path[next]);
                    if (walked > Profile.ResumeAheadSearch)
                    {
                        index = first;
                        break;
                    }
                    index = next;
                }
                ResumeRouteFrom(index);
            }
            #endregion

            #region Маршрут по дорогам
            protected const float MaxLaneOffset = 4f, LaneEdgeGap = 1.7f, SidestepEdgeGap = 0.4f;
            private const float SidestepMinLeft = 0.5f, RecordedSidestep = 2.5f, SeamSidestepMin = 1f;
            private const float LaneTurnFrom = 8f, LaneTurnSpan = 12f;
            private const float LineSpeedRadius = 12f;
            private readonly Dictionary<Vector3, CoreLines.Point[]> _linePoints = new();
            private Vector3[] _roadsFor;
            private float[] _roadHalfWidths;
            private bool[] _roadSeams;

            protected virtual float LaneOffset => 0f;
            private bool LanesEnabled => PathByRoad && modePath == BaseEventsManager<T>.ModePath.Generate && path != null && path.Length >= 2;
            private float LaneBodyHalfWidth => Pilot is EventGroundPilot ground ? ground.BodyHalfWidth : Profile.DefaultHalfWidth;

            protected void UseMonumentLine(CoreLines.Job job)
            {
                _linePoints.Clear();
                if (job?.Lines == null) return;
                foreach (CoreLines.Point[] line in job.Lines)
                    if (line != null && line.Length > 0 && !_linePoints.ContainsKey(line[0].Pos)) _linePoints[line[0].Pos] = line;
            }
            protected void ClearMonumentLine() => _linePoints.Clear();
            protected bool TryGetLinePoint(int index, out CoreLines.Point[] line)
            {
                line = null;
                return _linePoints.Count > 0 && path != null && index >= 0 && index < path.Length && _linePoints.TryGetValue(path[index], out line);
            }
            public float LineSpeedNear(Vector3 position)
            {
                int side = RouteDirection > 0 ? 0 : 1;
                float speed = 0f;
                foreach (CoreLines.Point[] line in _linePoints.Values)
                {
                    CoreLines.Point point = line[Mathf.Min(side, line.Length - 1)];
                    if (point.Speed <= 0f || CoreEx.DistanceFlat(point.Pos, position) > LineSpeedRadius) continue;
                    speed = speed <= 0f ? point.Speed : Mathf.Min(speed, point.Speed);
                }
                return speed;
            }
            protected override Vector3 RoutePoint(int index, int dir)
            {
                Vector3 point = path[index];
                if (_linePoints.Count > 0 && _linePoints.TryGetValue(point, out CoreLines.Point[] line))
                    return dir > 0 || line.Length < 2 ? point : line[1].Pos;
                float offset = LaneOffsetAt(index, dir);
                if (offset <= 0f) return point;
                Vector3 along = path[Mathf.Clamp(index + dir, 0, path.Length - 1)] - path[Mathf.Clamp(index - dir, 0, path.Length - 1)];
                along.y = 0f;
                if (along.sqrMagnitude < 0.01f) return point;
                along.Normalize();
                return point + new Vector3(along.z, 0f, -along.x) * offset;
            }
            protected override Vector2 RouteMargin(int index, int dir)
            {
                if (path == null || index < 0 || index >= path.Length) return base.RouteMargin(index, dir);
                if (_linePoints.Count > 0 && _linePoints.TryGetValue(path[index], out CoreLines.Point[] line))
                {
                    Vector2 clear = line[dir > 0 || line.Length < 2 ? 0 : 1].Clear;
                    return dir > 0 ? clear : new Vector2(clear.y, clear.x);
                }
                if (!PathByRoad || path.Length < 2) return base.RouteMargin(index, dir);
                if (modePath == BaseEventsManager<T>.ModePath.Record) return new Vector2(RecordedSidestep, RecordedSidestep);
                GroundProfile profile = Profile;
                float body = LaneBodyHalfWidth;
                if (IsSeamPoint(index))
                {
                    float half = RoadHalfWidth(index);
                    if (IsSeamPoint(index - 1)) half = Mathf.Min(half, RoadHalfWidth(index - 1));
                    if (IsSeamPoint(index + 1)) half = Mathf.Min(half, RoadHalfWidth(index + 1));
                    float sidestep = Mathf.Clamp(half - body - SidestepEdgeGap, SeamSidestepMin, profile.SeamSidestep);
                    return new Vector2(sidestep, sidestep);
                }
                float road = RoadHalfWidth(index), offset = LaneOffsetAt(index, dir);
                float right = Mathf.Max(profile.SidestepMinRight, road - offset - body - SidestepEdgeGap);
                float left = Mathf.Max(SidestepMinLeft, Mathf.Min(offset + road - body - SidestepEdgeGap, offset + profile.OncomingSidestep));
                return new Vector2(left, right);
            }
            private float LaneOffsetAt(int index, int dir)
            {
                float setting = Mathf.Clamp(LaneOffset, 0f, MaxLaneOffset);
                if (setting <= 0f || !LanesEnabled || IsSeamPoint(index)) return 0f;
                float offset = Mathf.Min(setting, RoadHalfWidth(index) - LaneBodyHalfWidth - LaneEdgeGap);
                bool nearSeam = IsSeamPoint(index - 1) || IsSeamPoint(index + 1);
                float turn = 0f;
                for (int i = index - dir, k = 0; k < 3; i += dir, k++)
                {
                    float at = TurnAt(i, dir);
                    turn = Mathf.Max(turn, nearSeam ? Mathf.Abs(at) : at);
                }
                offset -= Mathf.Clamp01((turn - LaneTurnFrom) / LaneTurnSpan);
                if (nearSeam) offset *= 0.5f;
                return Mathf.Max(0f, offset);
            }
            private float TurnAt(int index, int dir)
            {
                int prev = index - dir, next = index + dir;
                if (index < 0 || index >= path.Length || prev < 0 || prev >= path.Length || next < 0 || next >= path.Length) return 0f;
                Vector3 a = path[index] - path[prev], b = path[next] - path[index];
                a.y = 0f;
                b.y = 0f;
                if (a.sqrMagnitude < 0.01f || b.sqrMagnitude < 0.01f) return 0f;
                return Vector3.SignedAngle(a, b, Vector3.up);
            }
            protected float RoadHalfWidth(int index)
            {
                EnsureRoads();
                return _roadHalfWidths.Length > 0 ? _roadHalfWidths[Mathf.Clamp(index, 0, _roadHalfWidths.Length - 1)] : Profile.RoadHalfWidth;
            }
            protected bool IsSeamPoint(int index)
            {
                if (path == null || index < 0 || index >= path.Length) return false;
                EnsureRoads();
                return _roadSeams[index];
            }
            private void EnsureRoads()
            {
                Vector3[] route = path;
                if (_roadHalfWidths != null && ReferenceEquals(_roadsFor, route)) return;
                _roadsFor = route;
                GroundProfile profile = Profile;
                int count = route?.Length ?? 0, found = 0;
                _roadHalfWidths = new float[count];
                _roadSeams = new bool[count];
                int[] roads = new int[count];
                float lastHalf = -1f;
                for (int i = 0; i < count; i++)
                {
                    roads[i] = -1;
                    if (GroundRoads.RoadPointAt(route[i], profile.RoadClasses, out float width, out int road))
                    {
                        lastHalf = width * 0.5f;
                        roads[i] = road;
                        found++;
                    }
                    _roadHalfWidths[i] = lastHalf;
                }
                for (int i = count - 1; i >= 0; i--)
                    if (_roadHalfWidths[i] < 0f)
                        _roadHalfWidths[i] = i + 1 < count && _roadHalfWidths[i + 1] > 0f ? _roadHalfWidths[i + 1] : profile.RoadHalfWidth;
                for (int i = 0; i + 1 < count; i++)
                    if (GroundRoads.IsSeam(CoreEx.DistanceFlat(route[i], route[i + 1]), roads[i], roads[i + 1]))
                        _roadSeams[i] = _roadSeams[i + 1] = true;
                if (count > 0 && found == 0)
                    Debug.LogWarning<T>("{0} #{1}: lane: route points did not match road points, road width assumed {2:0} m", NameEvent, number,
                        profile.RoadHalfWidth * 2f);
            }
            #endregion

            #region Генерация маршрута
            private const float GenerateRetryAfter = 10f;
            private Coroutine _generating;

            protected virtual bool PrepareGeneration() => true;
            protected abstract IEnumerator GenerateAttempt(RouteCandidate candidate);
            protected virtual RouteCandidate NewCandidate() => new RouteCandidate();
            protected virtual bool MoreAttempts(RouteCandidate best, int attempt) => true;
            protected virtual void OnRouteChosen(RouteCandidate route) { }
            protected abstract CoreLines.Request LineRequest(Vector3[] points, int a, int b);

            public override void InitRouter()
            {
                _profile = CreateProfile() ?? new GroundProfile();
                base.InitRouter();
            }
            protected override void GeneratePath()
            {
                StopGenerating();
                if (GetSettings() == null)
                {
                    Debug.LogWarning<T>("No active {0} settings [{1} #{2}]", Profile.Noun, NameEvent, number);
                    RetryGeneration();
                    return;
                }
                if (!PrepareGeneration())
                {
                    RetryGeneration();
                    return;
                }
                _generating = StartCoroutine(GenerateRoutine());
            }
            private IEnumerator GenerateRoutine()
            {
                ClearMonumentLine();
                GroundProfile profile = Profile;
                int attempts = Mathf.Max(1, profile.GenerateAttempts);
                RouteCandidate best = null;
                long frameFrom = System.Diagnostics.Stopwatch.GetTimestamp();
                for (int attempt = 0; attempt < attempts; attempt++)
                {
                    if (best != null && (best.Flaws <= 0 || !MoreAttempts(best, attempt))) break;
                    if (attempt > 0 && MsSince(frameFrom) >= profile.GenerateFrameBudget)
                    {
                        yield return null;
                        if (!CanContinueGenerating()) yield break;
                        frameFrom = System.Diagnostics.Stopwatch.GetTimestamp();
                    }
                    RouteCandidate candidate = NewCandidate() ?? new RouteCandidate();
                    IEnumerator trying = GenerateAttempt(candidate);
                    while (trying.MoveNext())
                    {
                        yield return null;
                        if (!CanContinueGenerating()) yield break;
                        frameFrom = System.Diagnostics.Stopwatch.GetTimestamp();
                    }
                    if (candidate.Route == null || (best != null && candidate.Flaws >= best.Flaws)) continue;
                    best = candidate;
                }
                if (best == null)
                {
                    _generating = null;
                    RetryGeneration();
                    yield break;
                }
                OnRouteChosen(best);
                Vector3[] points = best.Route.ToArray();
                if (best.OnRoad)
                {
                    CoreLines.Job job = new CoreLines.Job { Points = points };
                    IEnumerator lines = CoreLines.Build(job, LineRequest);
                    while (lines.MoveNext())
                    {
                        yield return null;
                        if (!CanContinueGenerating()) yield break;
                    }
                    UseMonumentLine(job);
                    points = job.Result;
                }
                _generating = null;
                SetPath(points);
                CreateEvent();
            }
            private static double MsSince(long timestamp)
                => (System.Diagnostics.Stopwatch.GetTimestamp() - timestamp) * 1000d / System.Diagnostics.Stopwatch.Frequency;
            private bool CanContinueGenerating() => this != null && isActiveAndEnabled && !HasEvent && GetSettings() != null && eventManager != null
                                                    && !eventManager.IsPause && !IsInvoking(InvokeStart);
            private void StopGenerating()
            {
                if (_generating == null) return;
                StopCoroutine(_generating);
                _generating = null;
            }
            private void RetryGeneration()
            {
                KillEventImmediate();
                StartEventToTimer(GenerateRetryAfter);
            }
            #endregion

            #region Появление транспорта
            protected abstract string SpawnPrefab { get; }
            protected override BaseVehicle SpawnVehicle()
            {
                if (GetSettings() == null || path == null || path.Length == 0) return null;
                Vector3 start = GroundPlacement.SpawnPoint(path[0], Profile);
                if (VehicleCore.IsSpawnBlocked<BaseVehicle>(start))
                {
                    return null;
                }
                Vector3 direction = (path.Length > 1 ? path[1] : path[path.Length - 1]) - path[0];
                direction.y = 0f;
                Quaternion rotation = direction.sqrMagnitude > 0.01f ? Quaternion.LookRotation(direction.normalized) : Quaternion.identity;
                return VehicleCore.SpawnVehicle(SpawnPrefab, start, rotation);
            }
            #endregion

            #region Цель погони у воды
            private const float ChaseWaterInterval = 1f, ChaseWaterMemory = 20f, ChaseWaterStep = 3f;
            private readonly Dictionary<BasePlayer, float> _wetUntil = new(), _wetCheckAt = new();
            private EventRun _wetRun;

            protected override bool IsValidChaseTarget(BasePlayer player)
            {
                if (!base.IsValidChaseTarget(player)) return false;
                if (TerrainMeta.HeightMap.GetHeight(player.transform.position) < WaterSystem.OceanLevel - 1f) return false;
                return !AcrossWater(player);
            }
            private bool AcrossWater(BasePlayer player)
            {
                if (Vehicle == null || player == null) return false;
                if (_wetRun != CurrentRun)
                {
                    _wetRun = CurrentRun;
                    _wetUntil.Clear();
                    _wetCheckAt.Clear();
                }
                float now = UnityEngine.Time.time;
                if (!_wetCheckAt.TryGetValue(player, out float checkAt) || now >= checkAt)
                {
                    _wetCheckAt[player] = now + ChaseWaterInterval;
                    Vector3 from = Vehicle.transform.position, to = player.transform.position;
                    float range = Mathf.Max(ChaseStraightDistance, ChaseSettings != null ? ChaseSettings.DistanceAggression : 0f);
                    if (CoreEx.DistanceFlat(from, to) <= range && GroundChecks.LineWet(from, to, ChaseWaterStep, Profile.WaterDepth))
                        _wetUntil[player] = now + ChaseWaterMemory;
                }
                return _wetUntil.TryGetValue(player, out float until) && now < until;
            }
            #endregion

            #region Очереди
            private readonly TightMonuments _tight;
            private readonly NarrowPassQueue _narrowPass;
            private readonly TurnSpotQueue _turnSpot;
            private static bool _claimsWatched;

            protected BaseGroundEventController()
            {
                _tight = new TightMonuments(this);
                _narrowPass = new NarrowPassQueue(this);
                _turnSpot = new TurnSpotQueue(this);
            }
            private void TickQueues()
            {
                if (!Profile.Queues) return;
                if (!_claimsWatched)
                {
                    _claimsWatched = true;
                    Host.OnUnload(ForgetClaims);
                }
                _narrowPass.Tick();
                _turnSpot.Tick();
            }
            private void ResetQueues()
            {
                _narrowPass.Reset();
                _turnSpot.Reset();
            }
            private static void ForgetClaims()
            {
                _claimsWatched = false;
                NarrowPassQueue.Forget();
                TurnSpotQueue.Forget();
            }
            protected override void OnRouteFinished()
            {
                if (Profile.Queues) _turnSpot.OnRouteFinished();
                base.OnRouteFinished();
            }
            private const int MatchWindow = 40;
            private int ProgressIndex()
            {
                if (path == null || path.Length == 0 || Vehicle == null) return -1;
                int near = NearestRouteIndex(Vehicle.transform.position);
                if (Pilot == null || !Pilot.HasTarget) return near;
                Vector3 next = Pilot.NextPoint;
                int dir = RouteDirection;
                int found = MatchRoutePoint(next, dir, near - MatchWindow, near + MatchWindow);
                if (found < 0) found = MatchRoutePoint(next, dir, 0, path.Length - 1);
                return found >= 0 ? found : near;
            }
            private int MatchRoutePoint(Vector3 point, int dir, int from, int to)
            {
                from = Mathf.Max(0, from);
                to = Mathf.Min(path.Length - 1, to);
                for (int i = from; i <= to; i++)
                    if (CoreEx.DistanceFlat(path[i], point) < 12f && CoreEx.DistanceFlat(RoutePoint(i, dir), point) < 0.05f) return i;
                return -1;
            }

            private sealed class TightMonuments
            {
                private const int TightRun = 3;
                private readonly BaseGroundEventController<T> _owner;
                private Vector3[] _for;
                private readonly HashSet<MonumentInfo> _monuments = new();

                public TightMonuments(BaseGroundEventController<T> owner) => _owner = owner;

                public bool Contains(MonumentInfo monument) => monument != null && Any() && _monuments.Contains(monument);
                public bool Any()
                {
                    Vector3[] path = _owner.path;
                    if (path == null) return false;
                    if (_for != path)
                    {
                        _for = path;
                        _monuments.Clear();
                        float shared = 2f * _owner.Profile.LineBodyHalfWidth;
                        int run = 0, previous = -2;
                        for (int i = 0; i < path.Length; i++)
                        {
                            if (!_owner.TryGetLinePoint(i, out CoreLines.Point[] line)) continue;
                            bool tight = line.Length > 1 && Mathf.Abs(line[0].Offset - line[1].Offset) < shared;
                            run = tight ? (previous == i - 1 ? run + 1 : 1) : 0;
                            previous = i;
                            if (run < TightRun) continue;
                            MonumentInfo at = CoreRoutes.MonumentAt(path[i], CoreLines.ZoneMargin);
                            if (at != null) _monuments.Add(at);
                        }
                    }
                    return _monuments.Count > 0;
                }
            }

            private sealed class NarrowPassQueue
            {
                private const float ClaimAhead = 30f, WaitLimit = 45f, ClaimTtl = 2f;
                private const float OncomingCos = -0.3f;
                private sealed class Claim
                {
                    public BaseGroundEventController<T> Owner;
                    public Vector3 Heading;
                    public float Since, At;
                }
                private static readonly Dictionary<MonumentInfo, List<Claim>> _claims = new();
                private readonly BaseGroundEventController<T> _owner;
                private MonumentInfo _claimed;
                private float _waitSince = -1f;

                public NarrowPassQueue(BaseGroundEventController<T> owner) => _owner = owner;

                public static void Forget() => _claims.Clear();
                public void Reset()
                {
                    Release();
                    _waitSince = -1f;
                }
                public void Tick()
                {
                    if (!(_owner.Pilot is EventGroundPilot pilot) || _owner.Vehicle == null) return;
                    if (!_owner._tight.Any())
                    {
                        Release();
                        StopWaiting(pilot, false);
                        _waitSince = -1f;
                        return;
                    }
                    float now = UnityEngine.Time.time;
                    Vector3 position = _owner.Vehicle.transform.position;
                    MonumentInfo here = _owner.IsChasing ? null : TightMonumentAt(position);
                    MonumentInfo zone = here;
                    Vector3 heading = _owner.Vehicle.transform.forward;
                    if (zone == null && !_owner.IsChasing && pilot.TryGetPointAhead(ClaimAhead, out Vector3 ahead))
                    {
                        MonumentInfo next = TightMonumentAt(ahead);
                        if (next != null)
                        {
                            zone = next;
                            heading = ahead - position;
                        }
                    }
                    heading.y = 0f;
                    if (zone != _claimed) Release();
                    if (zone == null || heading.sqrMagnitude < 0.01f)
                    {
                        StopWaiting(pilot, false);
                        _waitSince = -1f;
                        return;
                    }
                    heading.Normalize();
                    if (here == null && Oncoming(zone, heading) && (_waitSince < 0f || now - _waitSince < WaitLimit))
                    {
                        if (_waitSince < 0f)
                        {
                            _waitSince = now;
                        }
                        pilot.HoldForZone = true;
                        Release();
                        return;
                    }
                    StopWaiting(pilot, true);
                    Take(zone, heading, now);
                }
                private MonumentInfo TightMonumentAt(Vector3 point)
                {
                    MonumentInfo monument = CoreRoutes.MonumentAt(point, CoreLines.ZoneMargin);
                    return monument != null && _owner._tight.Contains(monument) ? monument : null;
                }
                private void StopWaiting(EventGroundPilot pilot, bool log)
                {
                    if (!pilot.HoldForZone) return;
                    pilot.HoldForZone = false;
                    if (!_owner.IsChasing) _owner.ResumeRoute();
                }
                private bool Oncoming(MonumentInfo zone, Vector3 heading)
                {
                    if (!_claims.TryGetValue(zone, out List<Claim> claims)) return false;
                    float now = UnityEngine.Time.time;
                    Claim own = claims.Find(c => c.Owner == _owner);
                    float since = own != null ? own.Since : now;
                    foreach (Claim claim in claims)
                    {
                        if (claim.Owner == _owner || now - claim.At > ClaimTtl || claim.Owner == null || claim.Owner.Vehicle == null)
                            continue;
                        if (Vector3.Dot(claim.Heading, heading) >= OncomingCos) continue;
                        if (claim.Since < since || (claim.Since == since && claim.Owner.number < _owner.number)) return true;
                    }
                    return false;
                }
                private void Take(MonumentInfo zone, Vector3 heading, float now)
                {
                    if (!_claims.TryGetValue(zone, out List<Claim> claims)) _claims[zone] = claims = new List<Claim>();
                    claims.RemoveAll(c => c.Owner == null || now - c.At > ClaimTtl * 5f);
                    Claim own = claims.Find(c => c.Owner == _owner);
                    if (own == null) claims.Add(own = new Claim { Owner = _owner, Heading = heading, Since = now });
                    own.At = now;
                    _claimed = zone;
                }
                private void Release()
                {
                    if (_claimed != null && _claims.TryGetValue(_claimed, out List<Claim> claims)) claims.RemoveAll(c => c.Owner == _owner);
                    _claimed = null;
                }
                private static string MonumentName(MonumentInfo monument)
                {
                    string name = monument.name;
                    int slash = name.LastIndexOf('/');
                    return slash >= 0 ? name.Substring(slash + 1) : name;
                }
            }

            private sealed class TurnSpotQueue
            {
                private const float QueueReach = 90f;
                private const float SpotShare = 25f, HoldAt = 55f, QueueGap = 12f, HoldMin = 10f, HoldStep = 8f, HoldShift = 32f;
                private const float TurnedHold = 60f, FreeDistance = 20f, PassMargin = 3f, StallTime = 6f;
                private const float WaitLimit = 45f, ClaimTtl = 1f;
                private sealed class Claim
                {
                    public BaseGroundEventController<T> Owner;
                    public Vector3 Spot;
                    public float Left, Away, At;
                    public bool Turned, Stalled;
                }
                private static readonly List<Claim> _claims = new();
                private readonly BaseGroundEventController<T> _owner;
                private Vector3 _spot;
                private float _turnedAt = -100f, _awayBest, _awayAt;
                private float _waitSince = -1f;
                private bool _waitDone;
                private Vector3[] _holdFor;
                private int _holdEnd = -1;
                private float _holdDistance;

                public TurnSpotQueue(BaseGroundEventController<T> owner) => _owner = owner;

                public static void Forget() => _claims.Clear();
                public void OnRouteFinished()
                {
                    Vector3[] path = _owner.path;
                    if (path != null && path.Length > 0)
                    {
                        _spot = path[_owner.RouteDirection > 0 ? path.Length - 1 : 0];
                        _turnedAt = _awayAt = UnityEngine.Time.time;
                        _awayBest = 0f;
                    }
                    _waitDone = false;
                }
                public void Reset()
                {
                    Release();
                    if (_owner.Pilot is EventGroundPilot held) held.HoldForTurn = false;
                    _waitDone = false;
                    _turnedAt = -100f;
                }
                public void Tick()
                {
                    if (!(_owner.Pilot is EventGroundPilot pilot) || _owner.Vehicle == null) return;
                    float now = UnityEngine.Time.time;
                    Vector3 position = _owner.Vehicle.transform.position;
                    Approach at = Locate(position, now);
                    if (at.Left > QueueReach)
                    {
                        Release();
                        StopWaiting(pilot, false);
                        _waitDone = false;
                        return;
                    }
                    bool stalled = at.Turned && at.Away > FreeDistance && now - _awayAt > StallTime;
                    Claim own = Take(at.Spot, at.Left, at.Away, at.Turned, stalled, now);
                    BaseGroundEventController<T> first = null;
                    int rank = at.Turned ? 0 : CountAhead(own, at.Spot, at.Left, position, now, out first);
                    if (rank == 0)
                    {
                        StopWaiting(pilot, true);
                        return;
                    }
                    if (pilot.HoldForTurn)
                    {
                        if (now - _waitSince < WaitLimit) return;
                        _waitDone = true;
                        StopWaiting(pilot, false);
                        return;
                    }
                    if (_waitDone || at.Left < HoldMin || at.Left > HoldDistance(at.End) + (rank - 1) * QueueGap) return;
                    pilot.HoldForTurn = true;
                    _waitSince = now;
                }
                private struct Approach
                {
                    public Vector3 Spot;
                    public float Left, Away;
                    public bool Turned;
                    public int End;
                }
                private Approach Locate(Vector3 position, float now)
                {
                    Approach at = new Approach { Spot = Vector3.zero, Left = float.MaxValue, Away = 0f, Turned = false, End = -1 };
                    Vector3[] path = _owner.path;
                    if (!_owner.HasEvent || _owner.IsChasing || _owner.routeMode != RouteMode.Points || path == null || path.Length < 2)
                        return at;
                    at.Away = CoreEx.DistanceFlat(position, _spot);
                    if (now - _turnedAt < TurnedHold && at.Away < QueueReach)
                    {
                        at.Spot = _spot;
                        at.Left = 0f;
                        at.Turned = true;
                        if (at.Away > _awayBest + 1f)
                        {
                            _awayBest = at.Away;
                            _awayAt = now;
                        }
                        return at;
                    }
                    at.End = _owner.RouteDirection > 0 ? path.Length - 1 : 0;
                    at.Spot = path[at.End];
                    if (CoreEx.DistanceFlat(position, at.Spot) <= QueueReach) at.Left = RouteLeft(at.End, position);
                    return at;
                }
                private int CountAhead(Claim own, Vector3 spot, float left, Vector3 position, float now, out BaseGroundEventController<T> first)
                {
                    int rank = 0;
                    first = null;
                    float flat = CoreEx.DistanceFlat(position, spot);
                    foreach (Claim claim in _claims)
                    {
                        if (claim == own || claim.Owner == null || claim.Owner.Vehicle == null || now - claim.At > ClaimTtl) continue;
                        if (CoreEx.DistanceFlat(claim.Spot, spot) > SpotShare) continue;
                        if (claim.Turned)
                        {
                            if (claim.Stalled || claim.Away >= Mathf.Max(FreeDistance, flat - PassMargin)) continue;
                        }
                        else if (claim.Left > left || (claim.Left == left && claim.Owner.number > _owner.number)) continue;
                        rank++;
                        if (first == null || claim.Turned) first = claim.Owner;
                    }
                    return rank;
                }
                private float HoldDistance(int end)
                {
                    Vector3[] path = _owner.path;
                    if (ReferenceEquals(_holdFor, path) && _holdEnd == end) return _holdDistance;
                    _holdFor = path;
                    _holdEnd = end;
                    _holdDistance = HoldAt;
                    GroundProfile profile = _owner.Profile;
                    List<PathList> roads = GroundRoads.Roads(profile.RoadClasses);
                    for (float distance = HoldAt; distance <= HoldAt + HoldShift; distance += HoldStep)
                    {
                        if (!RoutePointBefore(end, distance, out Vector3 point, out Vector3 along)) break;
                        if (along.sqrMagnitude > 0.01f && GroundRoads.NearCrossRoad(point, along, roads, profile.TurnSpotJunction)) continue;
                        _holdDistance = distance;
                        break;
                    }
                    return _holdDistance;
                }
                private bool RoutePointBefore(int end, float distance, out Vector3 point, out Vector3 along)
                {
                    Vector3[] path = _owner.path;
                    int dir = _owner.RouteDirection;
                    point = path[end];
                    along = Vector3.zero;
                    float walked = 0f;
                    for (int i = end; i - dir >= 0 && i - dir < path.Length; i -= dir)
                    {
                        Vector3 a = path[i], b = path[i - dir];
                        float segment = CoreEx.DistanceFlat(a, b);
                        if (walked + segment >= distance)
                        {
                            point = Vector3.Lerp(a, b, segment > 0.01f ? (distance - walked) / segment : 0f);
                            along = a - b;
                            along.y = 0f;
                            along = along.sqrMagnitude > 0.0001f ? along.normalized : Vector3.zero;
                            return true;
                        }
                        walked += segment;
                    }
                    return false;
                }
                private float RouteLeft(int end, Vector3 position)
                {
                    Vector3[] path = _owner.path;
                    int next = _owner.ProgressIndex();
                    int dir = _owner.RouteDirection;
                    if (next < 0 || (end - next) * dir < 0) return CoreEx.DistanceFlat(position, path[end]);
                    float left = CoreEx.DistanceFlat(position, path[next]);
                    for (int i = next; i != end && left <= QueueReach; i += dir) left += CoreEx.DistanceFlat(path[i], path[i + dir]);
                    return left;
                }
                private Claim Take(Vector3 spot, float left, float away, bool turned, bool stalled, float now)
                {
                    _claims.RemoveAll(c => c.Owner == null || now - c.At > ClaimTtl * 5f);
                    Claim own = _claims.Find(c => c.Owner == _owner);
                    if (own == null) _claims.Add(own = new Claim { Owner = _owner });
                    own.Spot = spot;
                    own.Left = left;
                    own.Away = away;
                    own.Turned = turned;
                    own.Stalled = stalled;
                    own.At = now;
                    return own;
                }
                private void Release() => _claims.RemoveAll(c => c.Owner == _owner);
                private void StopWaiting(EventGroundPilot pilot, bool log)
                {
                    if (!pilot.HoldForTurn) return;
                    pilot.HoldForTurn = false;
                    if (!_owner.IsChasing) _owner.ResumeRoute();
                }
            }
            #endregion
        }

        #endregion

        #region VehicleEventsCore: пилоты транспорта

        public interface IEventPilot
        {
            float SpeedMs { get; set; }
            float Altitude { get; set; }
            void SetPolyline(List<Vector3> points);
        }

        public class PilotPolyline
        {
            private readonly List<Vector3> _points = new();

            public void Set(List<Vector3> points)
            {
                _points.Clear();
                if (points != null) _points.AddRange(points);
            }

            public bool TryRoute(Vector3 from, Vector3 target, out List<Vector3> route, out string how)
            {
                route = null;
                how = null;
                if (_points.Count == 0) return false;
                if (CoreEx.DistanceFlat(_points[_points.Count - 1], target) > 1f) return false;
                int nearest = Mathf.Max(0, CoreEx.MinDistanceIndex(_points, p => CoreEx.DistanceFlat(p, from)));
                route = new List<Vector3>(_points.Count - nearest);
                for (int i = nearest; i < _points.Count; i++) route.Add(_points[i]);
                how = "by event points";
                return true;
            }
        }

        public class TargetLead
        {
            private BaseEntity _of;
            private Vector3 _prev;
            private float _prevAt;
            private Vector3 _velocity;

            public float Lead(BaseEntity target, BaseEntity vehicle)
            {
                if (target == null || target.IsDestroyed || vehicle == null)
                {
                    _of = null;
                    return 0f;
                }
                float now = UnityEngine.Time.time;
                Vector3 position = target.transform.position;
                if (!ReferenceEquals(target, _of))
                {
                    _of = target;
                    _prev = position;
                    _prevAt = now;
                    _velocity = Vector3.zero;
                }
                else if (now - _prevAt >= 0.1f)
                {
                    Vector3 v = (position - _prev) / (now - _prevAt);
                    v.y = 0f;
                    if (v.sqrMagnitude < 40f * 40f) _velocity = Vector3.Lerp(_velocity, v, Mathf.Min(1f, (now - _prevAt) / 0.5f));
                    _prev = position;
                    _prevAt = now;
                }
                Vector3 to = position - vehicle.transform.position;
                to.y = 0f;
                return to.sqrMagnitude > 1f ? Vector3.Dot(_velocity, to.normalized) : 0f;
            }
        }

        public class RoutePlan
        {
            private static readonly List<Vector3> NoPoints = new();
            private readonly HelperVehicles.VehicleControllerBase _pilot;
            public RoutePlan(HelperVehicles.VehicleControllerBase pilot) => _pilot = pilot;
            private IReadOnlyList<Vector3> _points => _pilot != null ? _pilot.Route : NoPoints;
            public bool TryGetPointAhead(Vector3 position, float distance, out Vector3 point)
            {
                point = Vector3.zero;
                if (_points.Count < 2) return false;
                int segment = 0;
                float bestT = 0f, bestSqr = float.MaxValue;
                for (int i = 0; i < _points.Count - 1; i++)
                {
                    Vector3 ab = _points[i + 1] - _points[i];
                    ab.y = 0f;
                    Vector3 ap = position - _points[i];
                    ap.y = 0f;
                    float t = ab.sqrMagnitude > 0.0001f ? Mathf.Clamp01(Vector3.Dot(ap, ab) / ab.sqrMagnitude) : 0f;
                    float sqr = (ap - ab * t).sqrMagnitude;
                    if (sqr >= bestSqr) continue;
                    bestSqr = sqr;
                    segment = i;
                    bestT = t;
                }
                Vector3 cursor = Vector3.Lerp(_points[segment], _points[segment + 1], bestT);
                float left = distance;
                for (int i = segment; i < _points.Count - 1; i++)
                {
                    Vector3 from = i == segment ? cursor : _points[i];
                    Vector3 to = _points[i + 1];
                    float length = CoreEx.DistanceFlat(from, to);
                    if (length >= left)
                    {
                        point = Vector3.Lerp(from, to, left / Mathf.Max(0.01f, length));
                        return true;
                    }
                    left -= length;
                }
                point = _points[_points.Count - 1];
                return true;
            }
            public bool TryGetTurn(Transform vehicle, float distance, out float turn)
            {
                turn = 0f;
                if (vehicle == null || !TryGetPointAhead(vehicle.position, distance, out Vector3 point)) return false;
                Vector3 toPoint = point - vehicle.position;
                toPoint.y = 0f;
                Vector3 forward = vehicle.forward;
                forward.y = 0f;
                if (toPoint.sqrMagnitude < 1f || forward.sqrMagnitude < 0.001f) return false;
                turn = Mathf.Clamp01(Vector3.Angle(forward, toPoint) / 90f);
                return true;
            }
        }

        public class EventGroundPilot : HelperVehicles.GroundVehicleController, IEventPilot
        {
            private readonly PilotPolyline _line = new();
            private float _speed;
            public float SpeedMs
            {
                get => _speed;
                set
                {
                    _speed = value;
                    if (_profile != null && _speed > 0f) _profile.CruiseSpeed = _speed;
                }
            }
            public float Altitude { get; set; }
            public void SetPolyline(List<Vector3> points) => _line.Set(points);
            private RoutePlan _plan;
            protected RoutePlan Plan => _plan ??= new RoutePlan(this);
            protected bool FollowingLine { get; private set; }
            protected virtual int EventFanRays => 9;
            private void SyncFan() => FanStraightOnly = SteerToAim && _own;
            protected override void OnAttached()
            {
                PlanLandByFrames = true;
                Tuning ??= new HelperVehicles.VehicleTuning();
                Tuning.FanRays ??= EventFanRays;
                if (SteerToAim && MeasureBody() && _profile != null)
                {
                    _profile.HalfLength = Mathf.Max(1f, BodyHalfLength);
                    _profile.HalfWidth = Mathf.Max(0.5f, BodyHalfWidth);
                }
                if (RamsLightObjects) Rammable = IsLightObstacle;
                if (CarefulManeuvers) ArcSweep = FinalApproachSense = true;
                if (PushesWhenStuck && _vehicle != null) _contacts = _vehicle.gameObject.AddComponent<CoreContactWatch>();
                base.OnAttached();
                SpeedMs = _speed;
                StartEngine();
            }
            protected override void OnReleasing()
            {
                if (_contacts != null) UnityEngine.Object.Destroy(_contacts);
                _contacts = null;
                base.OnReleasing();
                if (_vehicle is GroundVehicle ground && !ground.IsDestroyed && ground.HasFlag(BaseEntity.Flags.On)) ground.engineController?.StopEngine();
            }
            protected override bool OnGiveUp() => true;
            protected override bool PreDriveTick()
            {
                StartEngine();
                if (Waiting)
                {
                    ApplyInput(GetSpeed() > HoldBrakeSpeed ? -1f : 0f, 0f, false);
                    return false;
                }
                UpdateSpeedLimit();
                bool drive = base.PreDriveTick();
                if (drive && _vehicle != null)
                {
                    WatchEscape();
                    BreakRammed();
                    if (ShuffleTick()) return false;
                    PushTick();
                }
                return drive;
            }

            #region Лестница действий у препятствия
            protected bool RamsLightObjects => SteerToAim;
            protected virtual bool CarefulManeuvers => false;
            private const float LightMass = 300f, LightShare = 0.25f, BarrelRamMass = 600f;
            public bool IsLightObstacle(Collider collider, BaseEntity entity)
            {
                if (!RamsLightObjects || _vehicle == null) return false;
                if (entity == null && collider != null) entity = collider.ToBaseEntity();
                if (entity == _vehicle || entity is BasePlayer || entity is RidableHorse) return false;
                if (entity != null && entity.GetParentEntity() == _vehicle) return false;
                Rigidbody own = _vehicle.rigidBody;
                float ownMass = own != null ? own.mass : 0f;
                if (IsRamBarrel(entity, ownMass)) return true;
                Rigidbody body = collider != null ? collider.attachedRigidbody : null;
                if (body != null && body.gameObject.ToBaseEntity() is BaseEntity owner) entity = owner;
                if (entity is BaseVehicle vehicle)
                {
                    if (!(vehicle is Bike) || vehicle.AnyMounted()) return false;
                    body = vehicle.rigidBody;
                }
                else if (entity is HotAirBalloon || entity is Drone || entity is Rust.Ai.Gen2.BaseNPC2 || entity is BaseNpc) return false;
                if (body == null || body.isKinematic || body == own) return false;
                return body.mass <= Mathf.Min(LightMass, ownMass * LightShare);
            }
            private static bool IsRamBarrel(BaseEntity entity, float ownMass) => entity is LootContainer barrel && ownMass >= BarrelRamMass && barrel.MaxHealth() <= 100f
                                                                                  && barrel.ShortPrefabName.IndexOf("barrel", StringComparison.Ordinal) >= 0;
            private const float RamReach = 2f, RamCheckInterval = 0.1f;
            private static readonly Collider[] _ramHits = new Collider[16];
            private static int _ramMask;
            private float _ramCheckAt;
            private void BreakRammed()
            {
                if (_contacts == null || !RamsLightObjects) return;
                float ownMass = _vehicle.rigidBody != null ? _vehicle.rigidBody.mass : 0f;
                if (ownMass < BarrelRamMass) return;
                float now = UnityEngine.Time.time;
                float speed = GetSpeed();
                if (now >= _ramCheckAt)
                {
                    _ramCheckAt = now + RamCheckInterval;
                    if (_ramMask == 0) _ramMask = LayerMask.GetMask("Default", "Tree");
                    Transform t = _vehicle.transform;
                    Vector3 dir = speed < -0.5f ? -t.forward : t.forward;
                    Vector3 center = t.position + dir * (BodyHalfLength + RamReach * 0.5f) + t.up * 0.6f;
                    int count = Physics.OverlapBoxNonAlloc(center, new Vector3(BodyHalfWidth, 0.6f, RamReach * 0.5f + 0.1f), _ramHits, t.rotation, _ramMask, QueryTriggerInteraction.Ignore);
                    for (int i = 0; i < count; i++)
                    {
                        BaseEntity entity = _ramHits[i] != null ? _ramHits[i].ToBaseEntity() : null;
                        if (entity != null && _contacts.Rammed.Count < 8 && !_contacts.Rammed.Contains(entity)) _contacts.Rammed.Add(entity);
                        _ramHits[i] = null;
                    }
                }
                if (_contacts.Rammed.Count == 0) return;
                for (int i = 0; i < _contacts.Rammed.Count; i++)
                {
                    BaseCombatEntity target = _contacts.Rammed[i] as BaseCombatEntity;
                    if (target == null || target.IsDestroyed || target.IsDead() || !IsRamBarrel(target, ownMass)) continue;
                    target.Hurt(target.Health() + 1f, global::Rust.DamageType.Blunt, _vehicle, false);
                }
                _contacts.Rammed.Clear();
            }

            protected bool PushesWhenStuck => SteerToAim;
            protected float PushSpeed => 4f;
            private const float PushInterval = 3f, PushSlowSpeed = 1f, PushStillTime = 1.5f, PushStillMove = 0.6f, ContactFresh = 0.3f;
            public int Pushes { get; private set; }
            private CoreContactWatch _contacts;
            private float _pushAt = -100f, _stillSince;
            private Vector3 _stillFrom;
            private void PushTick()
            {
                if (_contacts == null || _vehicle.rigidBody == null) return;
                float now = UnityEngine.Time.time;
                Transform t = _vehicle.transform;
                Vector3 pos = t.position;
                if ((pos - _stillFrom).sqrMagnitude > PushStillMove * PushStillMove)
                {
                    _stillFrom = pos;
                    _stillSince = now;
                }
                if (now - _pushAt < PushInterval || now - _contacts.At > ContactFresh || now - _stillSince < PushStillTime) return;
                if (Mathf.Abs(GetSpeed()) > PushSlowSpeed || _vehicle.IsFlipped()) return;
                Collider other = _contacts.Other;
                if (other == null || IsOwnCollider(other)) return;
                Vector3 local = t.InverseTransformPoint(_contacts.Point);
                float front = BodyHalfLength * 0.6f;
                Vector3 push;
                string where;
                if (local.y < 0.3f && Mathf.Abs(local.x) < BodyHalfWidth * 0.8f && Mathf.Abs(local.z) < BodyHalfLength * 0.8f)
                {
                    push = Vector3.up;
                    where = "under the chassis";
                }
                else if (local.z < -front)
                {
                    push = Vector3.forward;
                    where = "behind";
                }
                else if (local.z <= front)
                {
                    push = local.x > 0f ? Vector3.left : Vector3.right;
                    where = local.x > 0f ? "on the right" : "on the left";
                }
                else return;
                _pushAt = now;
                Pushes++;
                _vehicle.rigidBody.linearVelocity = t.TransformDirection(push) * PushSpeed;
                HelperVehicles.Note(string.Format("{0}: stuck against {1} {2} - pushed {3:0} m/s away from it (push {4})", Debug.Id(_bot), ContactName(other), where, PushSpeed, Pushes));
            }

            private const float EscapeSideTime = 8f, EscapeSideCost = 4f, EscapeShiftNear = 0.5f;
            private int _escapeSide;
            private float _escapeUntil, _escapeShift;
            private Vector3 _escapePoint;
            private bool EscapeBias => _escapeSide != 0 && UnityEngine.Time.time < _escapeUntil;
            private void WatchEscape()
            {
                if (!EscapeBias) return;
                Transform t = _vehicle.transform;
                Vector3 forward = t.forward;
                forward.y = 0f;
                if (Vector3.Dot(t.position - _escapePoint, forward) > BodyHalfLength + 5f) _escapeSide = 0;
            }
            protected override void OnReverseAborted()
            {
                base.OnReverseAborted();
                float now = UnityEngine.Time.time;
                if (_plannedReverse <= now) return;
                _plannedReverse = 0f;
                RearAborted(now);
            }
            protected override void OnReverseStarted(bool turnStep)
            {
                base.OnReverseStarted(turnStep);
                float until = _reverseUntil;
                _plannedReverse = until;
                if (turnStep || !SteerToAim || _vehicle == null) return;
                Transform t = _vehicle.transform;
                Vector3 nose = t.position + t.forward * (BodyHalfLength + 1f);
                int side;
                if (EscapeBias && CoreEx.DistanceFlat(nose, _escapePoint) < 6f) side = -_escapeSide;
                else if (Mathf.Abs(_shiftTarget) > 0.3f) side = _shiftTarget > 0f ? -1 : 1;
                else side = SideRoom(1) >= SideRoom(-1) ? 1 : -1;
                _escapeSide = side;
                _escapeShift = _shiftTarget;
                _escapePoint = nose;
                _escapeUntil = until + EscapeSideTime;
                HelperVehicles.Note(string.Format("{0}: stuck ahead at shift {1:+0.0;-0.0} m - after reversing, going round on the {2}", Debug.Id(_bot), _shiftTarget, side > 0 ? "right" : "left"));
            }
            private static string ContactName(Collider collider)
            {
                BaseEntity entity = collider.ToBaseEntity();
                return entity != null ? entity.ShortPrefabName : collider.name;
            }
            private float SideRoom(int side)
            {
                Vector3 forward = _vehicle.transform.forward;
                forward.y = 0f;
                if (forward.sqrMagnitude < 0.001f) return 0f;
                return Sense(Quaternion.Euler(0f, 45f * side, 0f) * forward.normalized, 8f).Clear;
            }
            private float EscapeCost(float shift)
            {
                if (!EscapeBias) return 0f;
                if (Mathf.Abs(shift - _escapeShift) < EscapeShiftNear || shift * _escapeSide < -0.01f) return EscapeSideCost;
                return 0f;
            }

            private const float ShuffleWindow = 15f, ShuffleStill = 1.5f, ShuffleStepTime = 1.8f, ShuffleStepMove = 1.5f, ShuffleSpeed = 1.2f,
                ShuffleGrace = 2.5f, ShuffleDoneAngle = 45f, ShuffleDoneClear = 2.5f;
            private const int ShuffleSteps = 8;
            private float _plannedReverse, _rearAbortAt, _shuffleSide, _shuffleStepAt, _shuffleGraceUntil;
            private int _rearAborts, _shuffleLeft;
            private bool _shuffleForward;
            private Vector3 _rearAbortPos, _shuffleStepFrom;
            public int Shuffles { get; private set; }
            public bool Shuffling => _shuffleLeft > 0;
            private void RearAborted(float now)
            {
                Vector3 pos = _vehicle.transform.position;
                if (now - _rearAbortAt > ShuffleWindow || CoreEx.DistanceFlat(pos, _rearAbortPos) > ShuffleStill) _rearAborts = 0;
                if (_rearAborts == 0) _rearAbortPos = pos;
                _rearAborts++;
                _rearAbortAt = now;
                if (_rearAborts < 2 || Shuffling || !SteerToAim || !HasTarget) return;
                _rearAborts = 0;
                float heading = AimHeading();
                _shuffleSide = Mathf.Abs(heading) > 30f ? Mathf.Sign(heading) : SideRoom(1) >= SideRoom(-1) ? 1f : -1f;
                _shuffleLeft = ShuffleSteps;
                _shuffleForward = true;
                _shuffleStepAt = now;
                _shuffleStepFrom = pos;
                Shuffles++;
                _reverseUntil = 0f;
                _turnSteps = 0;
                _escapeAttempts = 0;
                HelperVehicles.Note(string.Format("{0}: boxed in (reverse blocked behind twice), target {1:+0;-0} deg - turning in short moves to the {2} (turn {3})",
                    Debug.Id(_bot), heading, _shuffleSide > 0f ? "right" : "left", Shuffles));
            }
            private float AimHeading()
            {
                Vector3 forward = _vehicle.transform.forward;
                forward.y = 0f;
                Vector3 to = AimAt - _vehicle.transform.position;
                to.y = 0f;
                return forward.sqrMagnitude < 0.001f || to.sqrMagnitude < 0.01f ? 0f : Vector3.SignedAngle(forward, to, Vector3.up);
            }
            private bool ShuffleTick()
            {
                if (!Shuffling) return false;
                float now = UnityEngine.Time.time;
                if (!HasTarget)
                {
                    EndShuffle(now, null);
                    return false;
                }
                Transform t = _vehicle.transform;
                Vector3 forward = t.forward;
                forward.y = 0f;
                if (forward.sqrMagnitude < 0.001f) return false;
                forward.Normalize();
                if (_shuffleForward && Mathf.Abs(AimHeading()) < ShuffleDoneAngle && Sense(forward, ShuffleDoneClear + 1f).Clear >= ShuffleDoneClear)
                {
                    EndShuffle(now, "the way ahead is clear");
                    return false;
                }
                bool blocked = Sense(_shuffleForward ? forward : -forward, 1.5f).Clear <= 0.05f;
                float stepTime = now - _shuffleStepAt;
                if (stepTime > ShuffleStepTime || CoreEx.DistanceFlat(t.position, _shuffleStepFrom) > ShuffleStepMove || (blocked && stepTime > 0.4f))
                {
                    if (--_shuffleLeft <= 0)
                    {
                        EndShuffle(now, "moves used up");
                        return false;
                    }
                    _shuffleForward = !_shuffleForward;
                    _shuffleStepAt = now;
                    _shuffleStepFrom = t.position;
                    ApplyInput(0f, 0f, false);
                    return true;
                }
                float speed = GetSpeed();
                float gas = blocked || Mathf.Abs(speed) >= ShuffleSpeed ? 0f : _shuffleForward ? 1f : -1f;
                ApplyInput(gas, (_shuffleForward ? _shuffleSide : -_shuffleSide) * SteerMaxPerFrame, false);
                return true;
            }
            private void EndShuffle(float now, string why)
            {
                _shuffleLeft = 0;
                _shuffleGraceUntil = now + ShuffleGrace;
                if (why != null) HelperVehicles.Note(string.Format("{0}: short moves ended - {1}", Debug.Id(_bot), why));
            }
            #endregion

            #region Правила скорости событий
            protected bool BoxObstacleAhead()
            {
                Transform t = _vehicle.transform;
                Bounds bounds = _vehicle.bounds;
                Vector3 origin = t.TransformPoint(bounds.center) + t.forward * ObstacleBoxFront(bounds) + t.up * 0.2f;
                Vector3 halfExtents = new Vector3(Mathf.Max(0.3f, bounds.extents.x * 0.9f), Mathf.Max(0.2f, bounds.extents.y * 0.5f), 0.05f);
                if (_boxMask == 0) _boxMask = LayerMask.GetMask("World", "Tree", "Construction", "Vehicle World", "Vehicle Detailed", "Prevent Movement");
                int count = Physics.BoxCastNonAlloc(origin, halfExtents, t.forward, _boxHits, t.rotation, BoxObstacleDistance, _boxMask, QueryTriggerInteraction.Ignore);
                for (int i = 0; i < count; i++)
                {
                    Collider collider = _boxHits[i].collider;
                    if (collider != null && _boxHits[i].distance > 0.05f && !BoxIgnores(collider)) return true;
                }
                return false;
            }
            protected virtual float ObstacleBoxFront(Bounds bounds) => bounds.extents.z;
            private const float BoxObstacleDistance = 5f;
            private static readonly RaycastHit[] _boxHits = new RaycastHit[16];
            private static int _boxMask;
            private bool BoxIgnores(Collider collider)
            {
                if (collider.CompareTag("Main Terrain") || collider.gameObject.layer == 9) return true;
                if (collider.attachedRigidbody != null && collider.attachedRigidbody == _vehicle.rigidBody) return true;
                string name = collider.name;
                if (name == "Road Mesh" || name.Contains("bush") || collider.gameObject.name.Contains("prevent_building")) return true;
                if (IsLightObstacle(collider, null)) return true;
                BaseEntity entity = collider.ToBaseEntity();
                for (int depth = 0; depth < 6 && entity != null; depth++)
                {
                    if (entity == _vehicle) return true;
                    entity = entity.GetParentEntity();
                }
                return false;
            }
            protected float AdaptiveTurn(bool enabled) => enabled && _hasTarget && Plan.TryGetTurn(_vehicle.transform, 15f, out float turn) ? turn : 0f;
            protected virtual float ObstacleSpeedKmh => 10f;
            protected virtual bool AdaptiveSpeed => false;
            protected virtual float LineSpeedAt(Vector3 position) => 0f;
            protected virtual bool BoxIgnoredOnLine => false;
            public bool ObstacleAhead { get; private set; }
            protected float LineSpeed { get; private set; }
            private const float SenseInterval = 0.2f, MinEventSpeed = 1f;
            private float _senseAt, _turn;
            private void UpdateSpeedLimit()
            {
                if (_profile == null || _vehicle == null) return;
                float cruise = _profile.CruiseSpeed;
                float slow = Mathf.Min(cruise, Mathf.Max(MinEventSpeed, ObstacleSpeedKmh / 3.6f));
                float now = UnityEngine.Time.time;
                if (now >= _senseAt)
                {
                    _senseAt = now + SenseInterval;
                    LineSpeed = LineSpeedAt(_vehicle.transform.position);
                    ObstacleAhead = (BoxObstacleAhead() && !(BoxIgnoredOnLine && LineSpeed > 0f && LaneSteering)) || LaneBlocked;
                    _turn = AdaptiveTurn(AdaptiveSpeed);
                }
                float speed = ObstacleAhead ? slow : Mathf.Lerp(cruise, slow, _turn * _turn);
                if (LineSpeed > 0f) speed = Mathf.Min(speed, LineSpeed);
                SpeedLimit = Mathf.Max(MinEventSpeed, speed);
            }
            #endregion

            #region Двигатель и ожидание в очереди
            protected virtual float EngineRetryInterval => 0.5f;
            protected virtual bool EngineCanStart(GroundVehicle vehicle)
                => vehicle.engineController.FuelSystem != null && vehicle.engineController.CanRunEngine();
            private float _engineTryAt;
            private void StartEngine()
            {
                if (!(_vehicle is GroundVehicle vehicle) || vehicle.IsDestroyed || vehicle.engineController == null) return;
                if (vehicle.HasFlag(BaseEntity.Flags.On)) return;
                float now = UnityEngine.Time.time;
                if (now < _engineTryAt) return;
                _engineTryAt = now + EngineRetryInterval;
                if (EngineCanStart(vehicle)) vehicle.engineController.FinishStartingEngine();
            }
            public bool HoldForZone, HoldForTurn;
            public bool Waiting => HoldForZone || HoldForTurn;
            private const float HoldBrakeSpeed = 3f;
            public bool TryGetPointAhead(float distance, out Vector3 point)
            {
                point = Vector3.zero;
                return _vehicle != null && Plan.TryGetPointAhead(_vehicle.transform.position, distance, out point);
            }
            #endregion

            #region Руль по полосе и объезд сдвигом
            protected virtual bool SteerToAim => false;
            protected float SidestepStep => 0.75f;
            protected float SidestepLimit => KeepToRoad && Route.Count > 1 ? RoadCorridor : 8f;
            protected virtual float CorridorMargin => 0.4f;
            protected float TightCorridorMargin => 0.4f;
            private float _tightUntil;
            protected virtual bool LaneSharpSteer => true;
            protected virtual bool SidestepChecksSurface => false;
            protected virtual bool SidestepChecksLedges => false;
            protected virtual bool CorridorTerrainByMap => false;
            private bool DeckUnder(Vector3 p, float level, float terrain)
            {
                if (!Physics.Raycast(new Vector3(p.x, level + 1.5f, p.z), Vector3.down, out RaycastHit hit, 2.5f, SurfaceMask, QueryTriggerInteraction.Ignore)) return false;
                return hit.collider != null && !(hit.collider is TerrainCollider) && !IsOwnCollider(hit.collider) && hit.point.y > terrain + 0.5f;
            }
            private const float LaneGain = 3f, LaneGainLimit = 25f;
            private const float HoldTimeout = 8f, SideMemory = 2f, CorridorStep = 4f;
            private const float BlockedMemory = 2f;
            private const float CurveBrake = 3f, CurveSpanMin = 6f, CurveSpanMax = 20f;
            protected float CurveGrip => 3.5f;
            private static readonly RaycastHit[] _corridorHits = new RaycastHit[32];
            private static readonly List<BaseEntity> _corridorVehicles = new();
            private static readonly BaseEntity[] _moverBuffer = new BaseEntity[16];
            private static readonly Func<BaseEntity, bool> IsBigMover = entity => entity is TravellingVendor || entity is BradleyAPC;
            private static readonly Vector3 BigMoverExtents = new Vector3(1.2f, 0f, 2.8f);
            private readonly List<BaseEntity> _bigMovers = new();
            private float _bigMoversAt;
            private static readonly Vector3[] _corridorPoints = new Vector3[12];
            private static readonly float[] _corridorGround = new float[12];
            private static readonly float[] _corridorAlong = new float[12];
            private static readonly bool[] _corridorDeck = new bool[12];
            private static int _corridorMask, _corridorVehicleMask, _surfaceMask;
            private static int CorridorMask => _corridorMask != 0 ? _corridorMask
                : _corridorMask = LayerMask.GetMask("Terrain", "World", "Construction", "Deployed", "Default", "Tree");
            private static int SurfaceMask => _surfaceMask != 0 ? _surfaceMask
                : _surfaceMask = LayerMask.GetMask("Terrain", "World", "Construction", "Deployed", "Default");
            private static int CorridorVehicleMask => _corridorVehicleMask != 0 ? _corridorVehicleMask
                : _corridorVehicleMask = LayerMask.GetMask("Vehicle Large", "Vehicle Detailed", "Vehicle World");

            public float BodyHalfLength { get; private set; } = 2.3f;
            public float BodyHalfWidth { get; private set; } = 1.3f;
            public float BodySideOffset { get; private set; }
            private float _bodySpan;
            private float CorridorHalfWidth => BodySideOffset != 0f ? _bodySpan : BodyHalfWidth;
            private bool _own;
            private float _ownClear = 30f;
            private float _probeAt, _searchAt;
            private int _laneFrame = -1;
            private float _laneHeading;
            private float _shiftTarget, _shiftNow;
            private int _side;
            private float _sideUntil;
            private bool _holding;
            private float _holdUntil;
            private Vector3 _holdPoint;
            private readonly List<Vector2> _margins = new();
            private Vector3 _marginsFirst;
            private float _noseClear = float.MaxValue;
            private float _curveLimit = float.MaxValue;
            private float _surfaceLift;
            private float _laneBlockedUntil;
            private bool _blockedHasPoint;
            private Vector3 _blockedPoint;
            public float SteerClearance => SteerToAim && _own ? Mathf.Min(_ownClear, _noseClear) : Clearance;
            public bool LaneSteering => SteerToAim && _own;
            public float LaneShift => _shiftTarget;
            public bool LaneBlocked => SteerToAim && UnityEngine.Time.time < _laneBlockedUntil;
            public float CurveLimit => SteerToAim ? _curveLimit : float.MaxValue;

            public void SetRouteMargins(List<Vector2> margins)
            {
                _margins.Clear();
                if (margins != null && margins.Count == Route.Count) _margins.AddRange(margins);
                _marginsFirst = Route.Count > 0 ? Route[0] : Vector3.zero;
            }
            public void AppendRouteMargins(List<Vector2> margins)
            {
                if (margins == null || !MarginsValid(Route.Count - margins.Count))
                {
                    _margins.Clear();
                    return;
                }
                _margins.AddRange(margins);
            }
            private bool MarginsValid(int count) => count > 0 && _margins.Count == count && Route.Count > 0 && Route[0] == _marginsFirst;

            protected override float SteerFor(float headingError, float speed)
                => base.SteerFor(SteerToAim ? LaneHeading(headingError, speed) : headingError, speed);
            protected override float DesiredSpeed(float distance, float headingError, float clear)
            {
                if (!SteerToAim) return base.DesiredSpeed(distance, headingError, clear);
                float heading = LaneHeading(headingError, GetSpeed());
                float limit = _own ? Mathf.Min(_ownClear, _noseClear) : BlockedClear(clear);
                float speed = Mathf.Min(base.DesiredSpeed(distance, heading, limit), _curveLimit);
                return WideShift ? Mathf.Min(speed, ParkedSidestepSpeed) : speed;
            }
            protected override void SendControl(float throttle, float steerDegrees, bool sharpSteer)
            {
                if (SteerToAim && LaneSharpSteer && _own && _laneFrame == UnityEngine.Time.frameCount) sharpSteer = Mathf.Abs(_laneHeading) > 25f;
                base.SendControl(throttle, steerDegrees, sharpSteer);
            }

            protected virtual float LaneAimDistance(float v) => Mathf.Clamp(v * 1.2f, 9f, 22f);
            protected virtual bool NoseOnTurn => true;
            private float LaneHeading(float fanHeading, float speed)
            {
                float heading = LaneHeadingTick(fanHeading, speed);
                SyncFan();
                return heading;
            }
            private float LaneHeadingTick(float fanHeading, float speed)
            {
                if (_laneFrame == UnityEngine.Time.frameCount) return _own ? _laneHeading : fanHeading;
                _laneFrame = UnityEngine.Time.frameCount;
                if (_vehicle == null || _profile == null || !AvoidsObstacles || DistanceToEnd < FinalApproach) return NoLine(fanHeading);
                Vector3 pos = _vehicle.transform.position;
                Vector3 forward = _vehicle.transform.forward;
                forward.y = 0f;
                if (forward.sqrMagnitude < 0.001f) return NoLine(fanHeading);
                forward.Normalize();
                float v = Mathf.Abs(speed);
                float now = UnityEngine.Time.time;
                if (Route.Count < 2)
                {
                    _curveLimit = float.MaxValue;
                    return ChordHeading(fanHeading, pos, forward, now);
                }
                if (!LaneAt(pos, out int seg, out float t, out float lateral, out Vector3 tangent)
                    || Vector3.Dot(forward, tangent) < 0.3f || !NearLine(AimAt, seg, 2.5f))
                    return NoLine(fanHeading);
                bool probe = now >= _probeAt;
                if (probe)
                {
                    _probeAt = now + FanInterval;
                    _curveLimit = LineCurveLimit(seg, t);
                    ProbeLane(pos, forward, v, seg, t, lateral, now);
                }
                if (!_own) return fanHeading;
                _shiftNow = Mathf.MoveTowards(_shiftNow, _shiftTarget, ShiftRate(v) * Mathf.Max(0.02f, TickDelta));
                LinePoint(seg, t, LaneAimDistance(v), out Vector3 aim, out Vector3 right);
                Vector3 to = aim + right * _shiftNow - pos;
                to.y = 0f;
                if (to.sqrMagnitude < 0.01f) return NotOwn(fanHeading);
                _laneHeading = Vector3.SignedAngle(forward, to, Vector3.up)
                               + Mathf.Clamp(LaneGain * (_shiftNow - lateral), -LaneGainLimit, LaneGainLimit);
                if (probe)
                    _noseClear = (NoseOnTurn && Mathf.Abs(_laneHeading) > 10f) || Mathf.Abs(lateral - _shiftNow) > 0.75f ? NoseClear(forward, v) : float.MaxValue;
                return _laneHeading;
            }
            private float NotOwn(float fanHeading)
            {
                _own = false;
                _shiftTarget = _shiftNow = 0f;
                _holding = false;
                _noseClear = float.MaxValue;
                return fanHeading;
            }
            private float NoLine(float fanHeading)
            {
                _curveLimit = float.MaxValue;
                return NotOwn(fanHeading);
            }
            protected virtual bool NoseAlongWheels => false;
            private const float NoseCrawlClear = 4.5f;
            private float NoseClear(Vector3 forward, float v)
            {
                Vector3 dir = forward;
                Vector3 velocity = _vehicle.GetWorldVelocity();
                velocity.y = 0f;
                if (velocity.sqrMagnitude > 9f) dir = velocity.normalized;
                float reach = Mathf.Clamp(v / 0.8f + 4f, 8f, 30f);
                float clear = Sense(dir, reach).Clear;
                if (!NoseAlongWheels || clear >= NoseCrawlClear) return clear;
                float wheels = WheelAngle();
                if (Mathf.Abs(wheels) < 10f) return clear;
                return Mathf.Max(clear, Mathf.Min(Sense(Quaternion.Euler(0f, wheels, 0f) * forward, reach).Clear, NoseCrawlClear));
            }
            private float WheelAngle() => _vehicle switch
            {
                ModularCar car => car.SteerAngle,
                Bike bike => bike.SteerAngle,
                Snowmobile snowmobile => snowmobile.SteerAngle,
                _ => 0f,
            };
            private float BlockedClear(float clear)
            {
                if (!_blockedHasPoint || UnityEngine.Time.time >= _laneBlockedUntil || _vehicle == null) return clear;
                Transform vt = _vehicle.transform;
                Vector3 forward = vt.forward;
                forward.y = 0f;
                if (forward.sqrMagnitude < 0.001f) return clear;
                forward.Normalize();
                Vector3 to = _blockedPoint - vt.position;
                to.y = 0f;
                float ahead = Vector3.Dot(to, forward) - (BodyHalfLength + 0.5f);
                if (ahead < -0.5f)
                {
                    _blockedHasPoint = false;
                    return clear;
                }
                if (Mathf.Abs(Vector3.Dot(to, new Vector3(forward.z, 0f, -forward.x)) - BodySideOffset) > CorridorHalfWidth + CorridorMargin + 0.5f) return clear;
                return Mathf.Min(clear, Mathf.Max(0f, ahead));
            }
            private float LineCurveLimit(int seg, float t)
            {
                IReadOnlyList<Vector3> route = Route;
                float target = CruiseTarget;
                float horizon = target * target / (2f * CurveBrake) + CurveSpanMax;
                float limit = float.MaxValue;
                float along = -t * CoreEx.DistanceFlat(route[seg], route[seg + 1]);
                for (int i = seg; i < route.Count - 1 && along <= horizon; i++)
                {
                    Vector3 outgoing = route[i + 1] - route[i];
                    outgoing.y = 0f;
                    float next = outgoing.magnitude;
                    if (i > 0 && along >= -3f)
                    {
                        Vector3 incoming = route[i] - route[i - 1];
                        incoming.y = 0f;
                        if (incoming.sqrMagnitude > 0.01f && next > 0.1f)
                        {
                            float turn = Vector3.Angle(incoming, outgoing) * Mathf.Deg2Rad;
                            if (turn > 0.05f)
                            {
                                float span = Mathf.Clamp((incoming.magnitude + next) * 0.5f, CurveSpanMin, CurveSpanMax);
                                limit = Mathf.Min(limit, Mathf.Sqrt(CurveGrip * span / turn + 2f * CurveBrake * Mathf.Max(0f, along)));
                            }
                        }
                    }
                    along += next;
                }
                return limit == float.MaxValue ? limit : Mathf.Max(3f, limit);
            }
            private static float ShiftRate(float speed) => Mathf.Clamp(0.4f * speed, 2.5f, 5f);
            private float SteepGrade => Mathf.Tan(ClimbableSlope * Mathf.Deg2Rad);
            private float CruiseTarget => SpeedLimit > 0f ? Mathf.Min(_profile.CruiseSpeed, SpeedLimit) : _profile.CruiseSpeed;
            private float Need(float target) => Mathf.Clamp(target / 0.8f + 3f + target * 0.8f, 6f, 40f);

            private float ChordHeading(float fanHeading, Vector3 pos, Vector3 forward, float now)
            {
                Vector3 toAim = AimAt - pos;
                toAim.y = 0f;
                if (toAim.sqrMagnitude < 1f || Vector3.Angle(forward, toAim) > 90f) return NotOwn(fanHeading);
                Vector3 dir = toAim.normalized;
                if (now >= _probeAt)
                {
                    _probeAt = now + FanInterval;
                    float target = CruiseTarget;
                    float need = Mathf.Min(Need(target), 28f);
                    SenseResult sense = Sense(dir, need + 2f);
                    bool open = sense.Clear >= need - 0.5f && !IsBlocked(dir) && sense.Drop <= DropLimit * 0.6f;
                    if (!open && sense.Vehicle != null && !sense.Vehicle.IsDestroyed && !IsBlocked(dir)
                        && Vector3.Dot(sense.Vehicle.GetWorldVelocity(), dir) > target * 0.7f)
                        open = true;
                    _own = open;
                    _ownClear = sense.Clear;
                    _noseClear = float.MaxValue;
                    _shiftTarget = _shiftNow = 0f;
                    _holding = false;
                }
                if (!_own) return fanHeading;
                _laneHeading = Vector3.SignedAngle(forward, dir, Vector3.up);
                return _laneHeading;
            }

            private const float ParkedSpeed = 1f, ParkedSidestepExtra = 2.5f;
            private const float ParkedCorridorExtra = 0.5f, ParkedSideGrade = 0.27f, ParkedSidestepSpeed = 5f;
            private float _limitLeft = float.MaxValue, _limitRight = float.MaxValue;
            private bool WideShift => _own && (_shiftTarget < -_limitLeft - 0.01f || _shiftTarget > _limitRight + 0.01f
                                               || _shiftNow < -_limitLeft - 0.01f || _shiftNow > _limitRight + 0.01f);
            private float _parkedWideUntil;
            private bool _forceSurface;

            private void ProbeLane(Vector3 pos, Vector3 forward, float v, int seg, float t, float lateral, float now)
            {
                float target = CruiseTarget;
                float front = BodyHalfLength + 0.5f;
                float need = Mathf.Min(Need(target), Mathf.Max(6f, DistanceToEnd - front));
                LaneLimits(seg, out float leftMax, out float rightMax);
                float normalLeft = leftMax, normalRight = rightMax;
                bool wide = now < _parkedWideUntil;
                _forceSurface = wide;
                bool tight = wide || now < _tightUntil;
                float margin = tight ? Mathf.Min(CorridorMargin, TightCorridorMargin) : CorridorMargin;
                float halfBox = CorridorHalfWidth + margin + (wide ? ParkedCorridorExtra : 0f);
                if (wide)
                {
                    leftMax += ParkedSidestepExtra;
                    rightMax += ParkedSidestepExtra;
                }
                _limitLeft = normalLeft;
                _limitRight = normalRight;
                _surfaceLift = SurfaceLift(pos);
                CollectVehicles(pos, front + need + Mathf.Max(need, 20f) + 5f, v);
                if (_holding && (now > _holdUntil || Vector3.Dot(_holdPoint - pos, forward) < -(BodyHalfLength + 1f))) _holding = false;

                float current = Mathf.Clamp(_shiftTarget, -leftMax, rightMax);
                Corridor here = TestCorridor(current, v, seg, t, lateral, front, need, halfBox, target);
                bool avoidHere = EscapeCost(current) > 0f;
                if (here.Open && !avoidHere)
                {
                    if (Mathf.Abs(current) > 0.01f && !_holding)
                    {
                        float step = Mathf.Sign(current) * SidestepStep;
                        for (float back = 0f; Mathf.Abs(back) < Mathf.Abs(current) - 0.01f; back += step)
                        {
                            if (EscapeCost(back) > 0f) continue;
                            Corridor toward = TestCorridor(back, v, seg, t, lateral, front, need, halfBox, target);
                            if (!toward.Open) continue;
                            Choose(back, toward, now);
                            return;
                        }
                    }
                    Choose(current, here, now);
                    return;
                }
                if (!here.Open && here.HasPoint)
                {
                    _holding = true;
                    _holdPoint = here.Point;
                    _holdUntil = now + HoldTimeout;
                }
                if (now < _searchAt)
                {
                    if (here.Open) Choose(current, here, now);
                    else LaneFailed(here, now);
                    return;
                }
                int lefts = Mathf.Min(Mathf.FloorToInt(leftMax / SidestepStep + 0.01f), CandidateLimit);
                int rights = Mathf.Min(Mathf.FloorToInt(rightMax / SidestepStep + 0.01f), CandidateLimit);
                int candidates = 0;
                for (int j = -lefts; j <= rights; j++)
                {
                    float o = j * SidestepStep;
                    if (Mathf.Abs(o - current) < 0.01f) continue;
                    if (_holding && Mathf.Abs(current) > 0.01f && o * current >= 0f
                        && Mathf.Abs(o) < Mathf.Abs(current) - 0.01f) continue;
                    float cost = Mathf.Abs(o - current) + (_side != 0 && now < _sideUntil && o * _side < 0f ? 1.5f : 0f) + EscapeCost(o);
                    int at = candidates++;
                    while (at > 0 && _candidateCost[at - 1] > cost)
                    {
                        _candidateCost[at] = _candidateCost[at - 1];
                        _candidateShift[at] = _candidateShift[at - 1];
                        at--;
                    }
                    _candidateCost[at] = cost;
                    _candidateShift[at] = o;
                }
                for (int c = 0; c < candidates; c++)
                {
                    Corridor candidate = TestCorridor(_candidateShift[c], v, seg, t, lateral, front, need, halfBox, target);
                    if (!candidate.Open) continue;
                    Choose(_candidateShift[c], candidate, now);
                    return;
                }
                if (here.Open)
                {
                    Choose(current, here, now);
                    _searchAt = now + 0.5f;
                    return;
                }
                if (!tight && CorridorMargin > TightCorridorMargin + 0.01f)
                {
                    _tightUntil = now + HoldTimeout;
                    ProbeLane(pos, forward, v, seg, t, lateral, now);
                    return;
                }
                if (!wide && here.Parked)
                {
                    _parkedWideUntil = now + HoldTimeout;
                    ProbeLane(pos, forward, v, seg, t, lateral, now);
                    return;
                }
                LaneFailed(here, now);
                _searchAt = now + 0.5f;
                if (here.HasPoint && (ReportsLaneObstacles || ReportsParkedVehicles))
                {
                    Corridor line = TestCorridor(0f, v, seg, t, 0f, front, need, CorridorHalfWidth + Mathf.Min(CorridorMargin, TightCorridorMargin), target);
                    if (line.Open || !line.HasPoint) return;
                    if (line.Parked)
                    {
                        if (ReportsParkedVehicles && line.Other != null) OnParkedVehicle(line.Other, line.Point);
                    }
                    else if (ReportsLaneObstacles && !line.Vehicle && !line.Ground) OnLaneObstacle(line.Point);
                }
            }
            protected virtual void OnLaneObstacle(Vector3 point) { }
            protected virtual bool ReportsLaneObstacles => false;
            protected virtual void OnParkedVehicle(BaseEntity vehicle, Vector3 point) { }
            protected virtual bool ReportsParkedVehicles => false;
            private void LaneFailed(Corridor here, float now)
            {
                _own = false;
                _laneBlockedUntil = now + BlockedMemory;
                if (!here.HasPoint) return;
                _blockedHasPoint = true;
                _blockedPoint = here.Point;
            }
            protected override float StuckBeforeReverse => UnityEngine.Time.time < _shuffleGraceUntil ? 1e6f : base.StuckBeforeReverse;
            public void ResetManeuver()
            {
                _reverseUntil = 0f;
                _turnSteps = 0;
                _hasWaypoint = false;
                _escapeAttempts = 0;
                _shuffleLeft = 0;
                _rearAborts = 0;
                _plannedReverse = 0f;
                _tightUntil = 0f;
                _own = false;
                _shiftTarget = _shiftNow = 0f;
                _holding = false;
                _laneBlockedUntil = 0f;
                _blockedHasPoint = false;
            }
            private float SurfaceLift(Vector3 pos)
            {
                float terrain = TerrainMeta.HeightMap.GetHeight(pos);
                if (!Physics.Raycast(pos + Vector3.up * 1.5f, Vector3.down, out RaycastHit under, 4f, SurfaceMask, QueryTriggerInteraction.Ignore)
                    || under.collider == null || IsOwnCollider(under.collider) || under.point.y <= terrain)
                    return 0f;
                return Mathf.Min(under.point.y - terrain, 1.5f);
            }
            private const int CandidateLimit = 24;
            private static readonly float[] _candidateCost = new float[CandidateLimit * 2 + 1];
            private static readonly float[] _candidateShift = new float[CandidateLimit * 2 + 1];
            private void Choose(float shift, Corridor corridor, float now)
            {
                _own = true;
                _shiftTarget = shift;
                _ownClear = corridor.SpeedClear;
                if (Mathf.Abs(shift) > 0.01f)
                {
                    _side = shift > 0f ? 1 : -1;
                    _sideUntil = now + SideMemory;
                }
            }

            private struct Corridor
            {
                public bool Open;
                public float SpeedClear;
                public bool HasPoint;
                public Vector3 Point;
                public bool Parked;
                public bool Vehicle, Ground;
                public BaseEntity Other;
            }

            private Corridor TestCorridor(float shift, float v, int seg, float t, float lateral, float front, float need,
                                          float halfBox, float target)
            {
                Corridor result = new Corridor { Open = false, SpeedClear = need };
                float ramp = Mathf.Abs(shift - lateral) * Mathf.Max(v, 4f) / ShiftRate(v) + Mathf.Max(v, 4f) + 4f;
                int n = Mathf.Clamp(Mathf.CeilToInt(need / CorridorStep), 2, _corridorPoints.Length - 1);
                int rough = -1;
                float previousGround = 0f;
                for (int k = 0; k <= n; k++)
                {
                    float s = front + need * k / n;
                    LinePoint(seg, t, s, out Vector3 point, out Vector3 right);
                    float lat = Mathf.Lerp(lateral, shift, Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(s / ramp)));
                    Vector3 p = point + right * (lat + BodySideOffset);
                    float terrain = TerrainMeta.HeightMap.GetHeight(p);
                    bool deck = point.y > terrain + 1f && (!SidestepChecksLedges || DeckUnder(p, point.y, terrain));
                    float ground = deck ? point.y : terrain;
                    if (rough < 0 && k > 0 && !deck && (SidestepChecksSurface || _forceSurface) && Mathf.Abs(lat) >= 0.5f
                        && (WaterLevel.GetOverallWaterDepth(new Vector3(p.x, terrain, p.z), waves: false, volumes: true) > LandWaterLimit
                            || Mathf.Abs(ground - previousGround) > (s - front - _corridorAlong[k - 1]) * SteepGrade
                            || (_forceSurface && Mathf.Abs(TerrainMeta.HeightMap.GetHeight(p + right * halfBox)
                                                           - TerrainMeta.HeightMap.GetHeight(p - right * halfBox)) > 2f * halfBox * ParkedSideGrade)))
                        rough = k;
                    if (rough < 0 && k > 0 && !deck && SidestepChecksLedges && Mathf.Abs(lat) >= 0.5f)
                    {
                        Vector3 edge = p + right * (Mathf.Sign(lat) * (halfBox + 1f));
                        if (WaterLevel.GetOverallWaterDepth(new Vector3(edge.x, TerrainMeta.HeightMap.GetHeight(edge), edge.z), waves: false, volumes: true) > LandWaterLimit)
                            rough = k;
                    }
                    previousGround = ground;
                    if (k == 0 && terrain + _surfaceLift > ground)
                    {
                        ground = terrain + _surfaceLift;
                        deck = true;
                    }
                    _corridorDeck[k] = deck;
                    _corridorGround[k] = ground;
                    p.y = ground + 0.85f;
                    _corridorPoints[k] = p;
                    _corridorAlong[k] = s - front;
                }
                Vector3 first = _corridorPoints[1] - _corridorPoints[0];
                first.y = 0f;
                if (first.sqrMagnitude > 0.01f && IsBlocked(first.normalized))
                {
                    result.SpeedClear = 0f;
                    return result;
                }

                float clear = need;
                Vector3 half = new Vector3(halfBox, 0.65f, 0.05f);
                for (int k = 0; k < n && clear >= need; k++)
                {
                    Vector3 a = _corridorPoints[k], b = _corridorPoints[k + 1];
                    Vector3 segment = b - a;
                    float length = segment.magnitude;
                    if (length < 0.05f) continue;
                    Vector3 dir = segment / length;
                    int count = Physics.BoxCastNonAlloc(a, half, dir, _corridorHits, Quaternion.LookRotation(dir, Vector3.up),
                                                        length, CorridorMask, QueryTriggerInteraction.Ignore);
                    float scale = (_corridorAlong[k + 1] - _corridorAlong[k]) / length;
                    for (int i = 0; i < count; i++)
                    {
                        RaycastHit hit = _corridorHits[i];
                        Collider collider = hit.collider;
                        if (collider == null || IsOwnCollider(collider) || GroundChecks.IsRoadOrBush(collider.name) || IsLightObstacle(collider, null)) continue;
                        float along;
                        Vector3 point;
                        if (hit.distance <= 0f)
                        {
                            if (k > 0 || collider is TerrainCollider) continue;
                            along = 0f;
                            point = a;
                        }
                        else
                        {
                            float face = Vector3.Angle(CorridorTerrainByMap && collider is TerrainCollider ? TerrainMeta.HeightMap.GetNormal(hit.point) : hit.normal, Vector3.up);
                            bool solid = SidestepChecksLedges && !_corridorDeck[k] && !(collider is TerrainCollider);
                            if (face < ClimbableSlope && hit.point.y <= _corridorGround[k] + 0.15f && !solid) continue;
                            float ground = TerrainMeta.HeightMap.GetHeight(hit.point);
                            if (_corridorDeck[k]) ground = Mathf.Max(ground, _corridorGround[k]);
                            if (face < ClimbableSlope && hit.point.y - ground <= 0.3f && !solid) continue;
                            along = _corridorAlong[k] + hit.distance * scale;
                            point = hit.point;
                        }
                        if (along >= clear) continue;
                        clear = along;
                        result.HasPoint = true;
                        result.Point = point;
                        result.Parked = false;
                        result.Vehicle = false;
                        result.Ground = collider is TerrainCollider;
                    }
                }
                if (rough > 0 && _corridorAlong[rough] < clear)
                {
                    clear = _corridorAlong[rough];
                    result.HasPoint = true;
                    result.Point = _corridorPoints[rough];
                    result.Parked = false;
                    result.Vehicle = false;
                    result.Ground = true;
                }

                float follow = need;
                Vector3 lineDir = _corridorPoints[1] - _corridorPoints[0];
                lineDir.y = 0f;
                lineDir = lineDir.sqrMagnitude > 0.0001f ? lineDir.normalized : Vector3.zero;
                for (int i = 0; i < _corridorVehicles.Count; i++)
                {
                    BaseEntity other = _corridorVehicles[i];
                    if (other == null || other.IsDestroyed || IsLightObstacle(null, other)) continue;
                    Transform ot = other.transform;
                    Vector3 center = ot.TransformPoint(other.bounds.center);
                    Vector3 ext = other.bounds.extents;
                    if (other is HotAirBalloon && BalloonFootprint(other, out Vector3 footCenter, out Vector3 footExtents))
                    {
                        center = ot.TransformPoint(footCenter);
                        ext = footExtents;
                    }
                    else if (!(other is BaseVehicle)) ext = Vector3.Max(ext, BigMoverExtents);
                    ext += new Vector3(0.3f, 0f, 0.3f);
                    Vector3 velocity = MoverVelocity(other);
                    velocity.y = 0f;
                    bool leader = Vector3.Dot(velocity, lineDir) >= Mathf.Max(2f, target * 0.7f);
                    for (int k = 0; k <= n; k++)
                    {
                        Vector3 q = _corridorPoints[k];
                        Vector3 tangent = k < n ? _corridorPoints[k + 1] - q : q - _corridorPoints[k - 1];
                        tangent.y = 0f;
                        if (tangent.sqrMagnitude < 0.0001f) continue;
                        tangent.Normalize();
                        Vector3 normal = new Vector3(tangent.z, 0f, -tangent.x);
                        float time = leader ? 0f : _corridorAlong[k] / Mathf.Max(v, 3f);
                        Vector3 d = center + velocity * time - q;
                        d.y = 0f;
                        float alongT = Mathf.Abs(ext.x * Vector3.Dot(ot.right, tangent)) + Mathf.Abs(ext.z * Vector3.Dot(ot.forward, tangent));
                        float acrossT = Mathf.Abs(ext.x * Vector3.Dot(ot.right, normal)) + Mathf.Abs(ext.z * Vector3.Dot(ot.forward, normal));
                        float along = Vector3.Dot(d, tangent);
                        if (Mathf.Abs(Vector3.Dot(d, normal)) > halfBox + acrossT || Mathf.Abs(along) > CorridorStep * 0.5f + alongT) continue;
                        if (k == 0 && along + alongT < 0f) continue;
                        float gap = Mathf.Max(0f, _corridorAlong[k] + along - alongT);
                        if (leader) follow = Mathf.Min(follow, gap);
                        else if (gap < clear)
                        {
                            clear = gap;
                            result.HasPoint = true;
                            result.Point = center + velocity * time;
                            result.Parked = velocity.sqrMagnitude < ParkedSpeed * ParkedSpeed;
                            result.Vehicle = true;
                            result.Ground = false;
                            result.Other = other;
                        }
                        break;
                    }
                }
                result.Open = clear >= need - 0.5f;
                result.SpeedClear = Mathf.Min(clear, follow);
                return result;
            }
            private const float MoversRefresh = 0.5f, MoversMargin = 10f;
            private readonly List<BaseEntity> _movers = new();
            private float _moversAt = float.MinValue, _moversRadius;
            private Vector3 _moversPos;
            private void CollectVehicles(Vector3 pos, float radius, float speed)
            {
                float now = UnityEngine.Time.time;
                if (now - _moversAt > MoversRefresh || Vector3.Distance(pos, _moversPos) + radius > _moversRadius)
                {
                    _moversAt = now;
                    _moversPos = pos;
                    _moversRadius = radius + Mathf.Max(MoversMargin, 2f * Mathf.Abs(speed) * MoversRefresh);
                    _movers.Clear();
                    Vis.Entities(pos, _moversRadius, _movers, CorridorVehicleMask, QueryTriggerInteraction.Ignore);
                    for (int i = _movers.Count - 1; i >= 0; i--)
                    {
                        BaseEntity other = _movers[i];
                        if (other == null || other.IsDestroyed || other == _vehicle || other.GetParentEntity() == _vehicle
                            || !(other is BaseVehicle || other is HotAirBalloon || IsBigMover(other)) || IsBalloonAloft(other, pos))
                            _movers.RemoveAt(i);
                    }
                }
                _corridorVehicles.Clear();
                _corridorVehicles.AddRange(_movers);
                if (now >= _bigMoversAt)
                {
                    _bigMoversAt = now + 1f;
                    _bigMovers.Clear();
                    if (BaseEntity.Query.Server != null)
                    {
                        int count = BaseEntity.Query.Server.GetInSphere(pos, radius + 30f, _moverBuffer, IsBigMover);
                        for (int i = 0; i < count; i++) _bigMovers.Add(_moverBuffer[i]);
                        System.Array.Clear(_moverBuffer, 0, _moverBuffer.Length);
                    }
                }
                for (int i = 0; i < _bigMovers.Count; i++)
                {
                    BaseEntity big = _bigMovers[i];
                    if (big != null && !big.IsDestroyed && !_corridorVehicles.Contains(big)) _corridorVehicles.Add(big);
                }
            }
            public static bool IsBalloonAloft(BaseEntity entity, Vector3 pos)
            {
                if (!(entity is HotAirBalloon)) return false;
                Vector3 at = entity.transform.position;
                return at.y - TerrainMeta.HeightMap.GetHeight(at) > 4f && Mathf.Abs(at.y - pos.y) > 3f;
            }
            private static Vector3 MoverVelocity(BaseEntity entity)
            {
                if (entity is TravellingVendor vendor) return vendor.currLinearVelocity;
                if (entity is BradleyAPC bradley && bradley.myRigidBody != null) return bradley.myRigidBody.linearVelocity;
                return entity.GetWorldVelocity();
            }
            private bool IsOwnCollider(Collider collider)
            {
                if (_vehicle.rigidBody != null && collider.attachedRigidbody == _vehicle.rigidBody) return true;
                if (_vehicle.transform.parent == null && collider.transform.root == _vehicle.transform) return true;
                BaseEntity entity = collider.ToBaseEntity();
                for (int depth = 0; depth < 6 && entity != null; depth++)
                {
                    if (entity == _vehicle || entity == _bot) return true;
                    entity = entity.GetParentEntity();
                }
                return false;
            }
            private void LaneLimits(int seg, out float left, out float right)
            {
                left = right = SidestepLimit;
                if (!MarginsValid(Route.Count)) return;
                float l = float.MaxValue, r = float.MaxValue;
                for (int i = seg; i <= Mathf.Min(seg + 4, _margins.Count - 1); i++)
                {
                    if (_margins[i].x >= 0f) l = Mathf.Min(l, _margins[i].x);
                    if (_margins[i].y >= 0f) r = Mathf.Min(r, _margins[i].y);
                }
                if (l < float.MaxValue) left = l;
                if (r < float.MaxValue) right = r;
            }

            private bool LaneAt(Vector3 pos, out int seg, out float t, out float lateral, out Vector3 tangent)
            {
                seg = 0;
                t = 0f;
                lateral = 0f;
                tangent = Vector3.forward;
                IReadOnlyList<Vector3> route = Route;
                if (route.Count < 2) return false;
                int next = Mathf.Max(1, NextIndex);
                int from = Mathf.Max(0, next - 3), to = Mathf.Min(route.Count - 2, next + 6);
                float best = float.MaxValue;
                for (int i = from; i <= to; i++)
                {
                    float u = Project(pos, route[i], route[i + 1]);
                    Vector3 c = Vector3.Lerp(route[i], route[i + 1], u);
                    float sqr = (c.x - pos.x) * (c.x - pos.x) + (c.z - pos.z) * (c.z - pos.z);
                    if (sqr >= best) continue;
                    best = sqr;
                    seg = i;
                    t = u;
                }
                if (best > 15f * 15f) return false;
                tangent = route[seg + 1] - route[seg];
                tangent.y = 0f;
                if (tangent.sqrMagnitude < 0.0001f) return false;
                tangent.Normalize();
                Vector3 offset = pos - Vector3.Lerp(route[seg], route[seg + 1], t);
                offset.y = 0f;
                lateral = Vector3.Dot(offset, new Vector3(tangent.z, 0f, -tangent.x));
                return true;
            }
            private static float Project(Vector3 p, Vector3 a, Vector3 b)
            {
                float abx = b.x - a.x, abz = b.z - a.z;
                float length = abx * abx + abz * abz;
                if (length < 0.0001f) return 0f;
                return Mathf.Clamp01(((p.x - a.x) * abx + (p.z - a.z) * abz) / length);
            }
            private bool NearLine(Vector3 point, int seg, float tolerance)
            {
                IReadOnlyList<Vector3> route = Route;
                for (int i = Mathf.Max(0, seg - 1); i < Mathf.Min(route.Count - 1, seg + 12); i++)
                {
                    Vector3 c = Vector3.Lerp(route[i], route[i + 1], Project(point, route[i], route[i + 1]));
                    if ((c.x - point.x) * (c.x - point.x) + (c.z - point.z) * (c.z - point.z) <= tolerance * tolerance) return true;
                }
                return false;
            }
            private void LinePoint(int seg, float t, float distance, out Vector3 point, out Vector3 right)
            {
                IReadOnlyList<Vector3> route = Route;
                int i = seg;
                float u = t;
                while (true)
                {
                    Vector3 a = route[i], b = route[i + 1];
                    float length = CoreEx.DistanceFlat(a, b);
                    float left = (1f - u) * length;
                    if (distance <= left || i >= route.Count - 2)
                    {
                        float nu = length > 0.001f ? u + distance / length : 1f;
                        point = nu <= 1f ? Vector3.Lerp(a, b, nu) : b + SegmentDir(i) * (distance - left);
                        right = Vector3.Lerp(NodeRight(i), NodeRight(i + 1), Mathf.Clamp01(nu));
                        right = right.sqrMagnitude > 0.0001f ? right.normalized : SegmentRight(i);
                        return;
                    }
                    distance -= left;
                    i++;
                    u = 0f;
                }
            }
            private Vector3 SegmentDir(int i)
            {
                Vector3 d = Route[i + 1] - Route[i];
                d.y = 0f;
                return d.sqrMagnitude > 0.0001f ? d.normalized : Vector3.forward;
            }
            private Vector3 SegmentRight(int i)
            {
                Vector3 d = SegmentDir(i);
                return new Vector3(d.z, 0f, -d.x);
            }
            private Vector3 NodeRight(int node)
            {
                Vector3 sum = Vector3.zero;
                if (node > 0) sum += SegmentRight(node - 1);
                if (node < Route.Count - 1) sum += SegmentRight(node);
                return sum.sqrMagnitude > 0.0001f ? sum.normalized : SegmentRight(Mathf.Clamp(node, 0, Route.Count - 2));
            }

            private bool MeasureBody()
            {
                if (_vehicle == null) return false;
                Transform root = _vehicle.transform;
                int preventBuilding = LayerMask.NameToLayer("Prevent Building");
                float minX = 0f, maxX = 0f, minZ = 0f, maxZ = 0f;
                bool any = false;
                foreach (Collider c in _vehicle.GetComponentsInChildren<Collider>())
                {
                    if (c == null || c.isTrigger || !c.enabled || c.gameObject.layer == preventBuilding || c.ToBaseEntity() is BasePlayer) continue;
                    Vector3 center, extents;
                    switch (c)
                    {
                        case BoxCollider box: center = box.center; extents = box.size * 0.5f; break;
                        case SphereCollider sphere: center = sphere.center; extents = Vector3.one * sphere.radius; break;
                        case CapsuleCollider capsule:
                            center = capsule.center;
                            extents = Vector3.one * capsule.radius;
                            extents[capsule.direction] = Mathf.Max(capsule.height * 0.5f, capsule.radius);
                            break;
                        case WheelCollider wheel: center = wheel.center; extents = Vector3.one * wheel.radius; break;
                        case MeshCollider mesh when mesh.sharedMesh != null:
                            center = mesh.sharedMesh.bounds.center;
                            extents = mesh.sharedMesh.bounds.extents;
                            break;
                        default: continue;
                    }
                    for (int corner = 0; corner < 8; corner++)
                    {
                        Vector3 local = root.InverseTransformPoint(c.transform.TransformPoint(center + new Vector3(
                            (corner & 1) == 0 ? extents.x : -extents.x,
                            (corner & 2) == 0 ? extents.y : -extents.y,
                            (corner & 4) == 0 ? extents.z : -extents.z)));
                        minX = Mathf.Min(minX, local.x);
                        maxX = Mathf.Max(maxX, local.x);
                        minZ = Mathf.Min(minZ, local.z);
                        maxZ = Mathf.Max(maxZ, local.z);
                        any = true;
                    }
                }
                if (!any) return false;
                BodyHalfWidth = Mathf.Clamp(Mathf.Max(-minX, maxX), 0.4f, 2f);
                BodyHalfLength = Mathf.Clamp(Mathf.Max(-minZ, maxZ), 0.8f, 6f);
                float middle = (minX + maxX) * 0.5f;
                BodySideOffset = Mathf.Abs(middle) >= 0.2f ? middle : 0f;
                _bodySpan = Mathf.Clamp((maxX - minX) * 0.5f, 0.4f, 2f);
                return true;
            }
            #endregion
            protected override List<Vector3> RouteTo(Vector3 target, out string how)
            {
                List<Vector3> route = null;
                how = null;
                FollowingLine = _vehicle != null && _line.TryRoute(_vehicle.transform.position, target, out route, out how);
                if (!FollowingLine) route = base.RouteTo(target, out how);
                return route;
            }
        }

        public sealed class CoreContactWatch : MonoBehaviour
        {
            public float At = -100f;
            public Vector3 Point;
            public Collider Other;
            public readonly List<BaseEntity> Rammed = new();
            private void OnCollisionEnter(Collision collision) => Note(collision);
            private void OnCollisionStay(Collision collision) => Note(collision);
            private void Note(Collision collision)
            {
                if (collision == null || collision.contactCount == 0) return;
                Collider other = collision.collider;
                if (other == null || other is TerrainCollider) return;
                if (GroundChecks.IsRoadMesh(other.name)) return;
                if (other.ToBaseEntity() is LootContainer barrel && Rammed.Count < 8 && !Rammed.Contains(barrel)) Rammed.Add(barrel);
                At = UnityEngine.Time.time;
                Point = collision.GetContact(0).point;
                Other = other;
            }
        }

        public class EventBoatPilot : HelperVehicles.BoatVehicleController, IEventPilot
        {
            protected override bool FlatDistance => true;
            private readonly PilotPolyline _line = new();
            private float _speed;
            public float SpeedMs
            {
                get => _speed;
                set
                {
                    _speed = value;
                    if (_profile != null && _speed > 0f) _profile.CruiseSpeed = _speed;
                }
            }
            public float Altitude { get; set; }
            public void SetPolyline(List<Vector3> points) => _line.Set(points);
            protected override void OnAttached()
            {
                base.OnAttached();
                SpeedMs = _speed;
            }
            private RoutePlan _plan;
            protected RoutePlan Plan => _plan ??= new RoutePlan(this);
            protected override List<Vector3> RouteTo(Vector3 target, out string how)
            {
                if (_vehicle == null || !_line.TryRoute(_vehicle.transform.position, target, out List<Vector3> route, out how))
                    route = base.RouteTo(target, out how);
                return route;
            }

            #region Руль лодки
            private readonly List<Vector3> _shoals = new();
            private readonly List<float> _shoalsUntil = new();
            private const float ShoalMemory = 60f, ShoalAvoidRange = 40f, ShoalPass = 12f;
            private const int ShoalSpots = 4;
            protected override bool PreDriveTick()
            {
                WatchShoal();
                if (!base.PreDriveTick())
                {
                    _pivoting = false;
                    _tight = Tight.None;
                    return false;
                }
                if (ChasePivot())
                {
                    _tight = Tight.None;
                    return false;
                }
                return !TightTurn();
            }

            #region Разворот в тесноте
            private enum Tight { None, Back, Pivot, Deep }
            private Tight _tight;
            private float _tightStarted, _tightCheckAt, _tightStill, _tightCooldown, _tightFromError, _tightKickUntil, _tightGas = 1f;
            private Vector3 _tightFrom, _tightBack, _tightPoint;
            private bool _tightToDeep;
            private const float TightEnter = 100f, TightShoalEnter = 45f, TightLeave = 60f, TightSlow = 2.5f, TightAimAhead = 12f;
            private const float TightBackMin = 3f, TightBackMax = 30f, TightBackTime = 14f, TightBackSpeed = 3f, TightStillTime = 1.5f, TightCooldown = 5f;
            private const float DeepEnough = 3.5f, DeepSpeed = 4.5f, DeepTime = 25f;
            private static readonly float[] DeepRings = { 20f, 30f, 45f, 60f };
            private const float PinSpeed = 0.3f, PinTime = 1.2f, PinTurn = 25f, PinRearMin = 0.25f, PinEndClear = 0.25f, PinProgressTime = 3f, PinPivotTime = 12f;
            private const float PinBackMax = 8f, PinRepeatRange = 6f, PinRepeatTime = 40f;
            private float _pinSince = -1f, _pinLastAt = -100f, _tightBackNeed, _tightRearClear = 4f, _tightBestError, _tightProgressAt;
            private Vector3 _pinAt;
            private int _pinRepeat;
            private bool _tightPinned, _tightConstrained;
            private bool TightTurn()
            {
                Rigidbody body = _vehicle != null ? _vehicle.rigidBody : null;
                if (body == null || _profile == null || !HasTarget || (FollowTarget != null && !FollowTarget.IsDestroyed))
                {
                    _pinSince = -1f;
                    return TightEnd(false);
                }
                Vector3 position = _vehicle.transform.position;
                Vector3 forward = _vehicle.transform.forward;
                forward.y = 0f;
                Vector3 aim = TightAim(position);
                Vector3 to = (_tight != Tight.None && _tightToDeep ? _tightPoint : aim) - position;
                to.y = 0f;
                if (forward.sqrMagnitude < 0.001f || (to.sqrMagnitude < 16f && _tight != Tight.Deep))
                {
                    _pinSince = -1f;
                    return TightEnd(false);
                }
                forward.Normalize();
                float now = UnityEngine.Time.time;
                float error = Vector3.SignedAngle(forward, to, Vector3.up);
                float speed = GetSpeed();
                float yawRate = body.angularVelocity.y * Mathf.Rad2Deg;
                if (_tight == Tight.None)
                {
                    if (now < _tightKickUntil)
                    {
                        if (Vector3.Dot(body.linearVelocity, forward) < KickSpeed)
                        {
                            ApplyInput(1f, Mathf.Clamp((error - yawRate * PivotLead) / PivotFullSteer, -1f, 1f) * SteerMaxPerFrame, false);
                            return true;
                        }
                        _tightKickUntil = 0f;
                        ResetBaseStall();
                    }
                    bool pinned = PinnedFor(now, speed, body);
                    bool shoal = NearShoal(position, out Vector3 shoalSpot);
                    if (now < _tightCooldown || (Mathf.Abs(speed) > TightSlow && !(shoal && speed < 0f))) return false;
                    if (!pinned && Mathf.Abs(error) < (shoal ? TightShoalEnter : TightEnter)) return false;
                    bool room = PivotRoom(position);
                    if (!pinned && room && !shoal && Sense(forward, _profile.HalfLength + 6f).Clear > _profile.HalfLength + 3f) return false;
                    _tightStarted = now;
                    _tightFrom = position;
                    _tightStill = -1f;
                    _tightCheckAt = now + 0.25f;
                    _tightRearClear = 4f;
                    _tightPinned = pinned;
                    _tightConstrained = false;
                    _pinSince = -1f;
                    _tightToDeep = shoal && DeepPoint(position, aim, out _tightPoint);
                    if (_tightToDeep)
                    {
                        to = _tightPoint - position;
                        to.y = 0f;
                        error = Vector3.SignedAngle(forward, to, Vector3.up);
                    }
                    _tightFromError = error;
                    if (pinned) RegisterPin(position, now);
                    if (room && (!pinned || Mathf.Abs(error) >= PinTurn))
                        return TightPivotStart(now, pinned ? "bow pinned, room available" : shoal ? "room near the shoal" : "room available");
                    Vector3 prefer = pinned ? -forward
                        : _tightToDeep && Vector3.Dot(to, forward) < 0f ? to : shoal ? position - shoalSpot : (Vector3.Dot(to, forward) < 0f ? to : -forward);
                    prefer.y = 0f;
                    if (!TightBackDirection(position, forward, prefer.sqrMagnitude > 0.01f ? prefer.normalized : -forward, pinned ? PinRearMin : 2f,
                                            out _tightBack, out float clear))
                    {
                        if (pinned && Mathf.Abs(error) >= PinTurn) return TightPivotStart(now, $"bow pinned, nothing free behind ({clear:0.0} m)", true);
                        _tightCooldown = now + TightCooldown;
                        return false;
                    }
                    _tight = Tight.Back;
                    if (pinned)
                        HelperVehicles.Note(string.Format("{0}: bow pinned (no headway at full throttle {1:0.0} s) - backing off {2:0.0} m, target {3} deg off the bow (clear behind {4:0.0} m, repeat {5})",
                            Debug.Id(_bot), PinTime, _tightBackNeed, error.ToString("+0;-0"), clear, _pinRepeat));
                    else
                        HelperVehicles.Note(string.Format("{0}: target {1} deg off the bow, no room to turn{2} - backing off (clear behind {3:0.0} m)",
                            Debug.Id(_bot), error.ToString("+0;-0"), shoal ? " (shoal)" : "", clear));
                }
                if (_tight == Tight.Back)
                {
                    float moved = CoreEx.DistanceFlat(position, _tightFrom);
                    if (Mathf.Abs(speed) < 0.3f)
                    {
                        if (_tightStill < 0f) _tightStill = now;
                        else if (now - _tightStill > TightStillTime && now - _tightStarted > 1f)
                        {
                            if (_tightPinned && Mathf.Abs(error) >= PinTurn) return TightPivotStart(now, $"cannot reverse (moved {moved:0.0} m)", true);
                            return TightEnd(true, $"cannot reverse (moved {moved:0.0} m)");
                        }
                    }
                    else _tightStill = -1f;
                    if (!_tightToDeep && !_tightPinned && !NearShoal(position, out _) && Mathf.Abs(error) < TightLeave) return TightEnd(true, "target no longer behind");
                    if (now >= _tightCheckAt)
                    {
                        _tightCheckAt = now + 0.25f;
                        SenseResult rear = Sense(-forward, 4f);
                        _tightRearClear = rear.Clear;
                        if (rear.Clear < (_tightPinned ? PinRearMin : Mathf.Max(1.2f, Mathf.Abs(speed) * 0.6f + 0.8f)))
                        {
                            if (PivotRoom(position)) return TightPivotStart(now, $"behind: {rear.What}");
                            if (_tightPinned && Mathf.Abs(error) >= PinTurn) return TightPivotStart(now, $"behind: {rear.What} at {rear.Clear:0.0} m, moved {moved:0.0} m", true);
                            return TightEnd(true, $"behind: {rear.What} at {rear.Clear:0.0} m");
                        }
                        if (_tightPinned)
                        {
                            if (moved >= _tightBackNeed)
                            {
                                if (Mathf.Abs(error) < PinTurn) return TightEnd(true, $"backed off {moved:0.0} m");
                                bool room = PivotRoom(position);
                                return TightPivotStart(now, $"backed off {moved:0.0} m{(room ? "" : ", no full room")}", !room);
                            }
                        }
                        else if (moved >= TightBackMin && PivotRoom(position)) return TightPivotStart(now, $"moved {moved:0} m");
                    }
                    if (moved >= TightBackMax || now - _tightStarted > TightBackTime)
                    {
                        if (PivotRoom(position)) return TightPivotStart(now, $"moved {moved:0} m");
                        if (_tightPinned && Mathf.Abs(error) >= PinTurn) return TightPivotStart(now, $"moved {moved:0} m, no full room", true);
                        return TightEnd(true, $"no room even at {moved:0} m");
                    }
                    float sternError = Vector3.SignedAngle(-forward, _tightBack, Vector3.up);
                    float limit = SteerMaxPerFrame * 0.3f;
                    float backSpeed = _tightPinned ? Mathf.Clamp(_tightRearClear * 1.5f, 0.6f, TightBackSpeed) : TightBackSpeed;
                    ApplyInput(speed < -backSpeed ? 0f : -1f, Mathf.Clamp(-sternError * 0.2f, -limit, limit), false);
                    return true;
                }
                float steerTo = Mathf.Clamp((error - yawRate * PivotLead) / PivotFullSteer, -1f, 1f) * SteerMaxPerFrame;
                if (_tight == Tight.Deep)
                {
                    float depth = BoatDepth(position);
                    if ((depth >= DeepEnough && CoreEx.DistanceFlat(position, _tightFrom) >= 10f) || to.magnitude < 8f)
                        return TightEnd(true, $"at depth {depth:0.0} m");
                    if (now - _tightStarted > DeepTime || Mathf.Abs(error) > 120f) return TightEnd(true, "failed to reach deep water");
                    ApplyInput(speed < DeepSpeed ? 1f : 0f, steerTo, true);
                    return true;
                }
                float along = Vector3.Dot(body.linearVelocity, forward);
                if ((Mathf.Abs(error) < PivotExit && Mathf.Abs(yawRate) < PivotExitYawRate) || now - _tightStarted > (_tightConstrained ? PinPivotTime : PivotMaxTime))
                {
                    HelperVehicles.Note(string.Format("{0}: turned in place {1:+0;-0} deg -> {2:+0;-0} deg in {3:0.0} s{4}", Debug.Id(_bot), _tightFromError, error,
                        now - _tightStarted, _tightConstrained ? " (tight space)" : ""));
                    if (_tightToDeep) return TightDeepStart(now);
                    _tightKickUntil = now + KickTime;
                    return TightEnd(true);
                }
                if (now >= _tightCheckAt)
                {
                    _tightCheckAt = now + (_tightConstrained ? 0.25f : 0.5f);
                    if (!_tightConstrained && !PivotRoom(position))
                    {
                        if (!_tightPinned) return _tightToDeep ? TightDeepStart(now) : TightEnd(true, "room ran out");
                        _tightConstrained = true;
                        _tightBestError = Mathf.Abs(error);
                        _tightProgressAt = now;
                    }
                    if (_tightConstrained)
                    {
                        float ahead = Sense(forward, 2f).Clear, behind = Sense(-forward, 2f).Clear;
                        if (ahead < PinEndClear && behind < PinEndClear) return TightEnd(true, $"boxed in (ahead {ahead:0.0} m, behind {behind:0.0} m)");
                        if (_tightGas > 0f && ahead < PinEndClear) _tightGas = -1f;
                        else if (_tightGas < 0f && behind < PinEndClear) _tightGas = 1f;
                        if (Mathf.Abs(error) < _tightBestError - 10f)
                        {
                            _tightBestError = Mathf.Abs(error);
                            _tightProgressAt = now;
                        }
                        else if (now - _tightProgressAt > PinProgressTime) return TightEnd(true, $"turn blocked at {error:+0;-0} deg");
                    }
                }
                if (_tightGas > 0f && along > PivotForward) _tightGas = -1f;
                else if (_tightGas < 0f && along < -PivotBack) _tightGas = 1f;
                ApplyInput(_tightGas, _tightGas < 0f ? -steerTo : steerTo, true);
                return true;
            }
            private const float PinFloat = 0.5f;
            private bool PinnedFor(float now, float speed, Rigidbody body)
            {
                BaseBoat boat = _vehicle as BaseBoat;
                Vector3 velocity = body.linearVelocity;
                velocity.y = 0f;
                if (DesiredThrottle < 0.5f || Mathf.Abs(speed) >= PinSpeed || velocity.sqrMagnitude >= 0.25f
                    || (boat != null && boat.buoyancy != null && boat.buoyancy.submergedFraction <= PinFloat))
                {
                    _pinSince = -1f;
                    return false;
                }
                if (_pinSince < 0f) _pinSince = now;
                return now - _pinSince >= PinTime;
            }
            private void RegisterPin(Vector3 position, float now)
            {
                _pinRepeat = now - _pinLastAt < PinRepeatTime && CoreEx.DistanceFlat(position, _pinAt) < PinRepeatRange ? _pinRepeat + 1 : 0;
                _pinAt = position;
                _pinLastAt = now;
                _tightBackNeed = Mathf.Min(PinBackMax, Mathf.Clamp(_profile.HalfLength * 0.5f, 1f, 2.5f) * (1f + 0.75f * _pinRepeat));
            }
            private void ResetBaseStall()
            {
                if (_vehicle == null) return;
                _stuckSince = UnityEngine.Time.time;
                _lastPos = _vehicle.transform.position;
                _reverseUntil = 0f;
            }
            private bool TightPivotStart(float now, string why, bool constrained = false)
            {
                Vector3 forward = _vehicle.transform.forward;
                forward.y = 0f;
                _tight = Tight.Pivot;
                _tightStarted = now;
                _tightCheckAt = now + (constrained ? 0.25f : 0.5f);
                _tightConstrained = constrained;
                _tightGas = Vector3.Dot(_vehicle.rigidBody.linearVelocity, forward) > PivotForward || (_tightPinned && constrained) ? -1f : 1f;
                if (constrained)
                {
                    _tightBestError = Mathf.Abs(_tightFromError);
                    _tightProgressAt = now;
                }
                HelperVehicles.Note(string.Format("{0}: turning in place {1}{2} ({3})", Debug.Id(_bot), _tightToDeep ? "toward deep water" : "toward target",
                    constrained ? " in tight space" : "", why));
                return true;
            }
            private bool TightDeepStart(float now)
            {
                _tight = Tight.Deep;
                _tightStarted = now;
                _tightFrom = _vehicle.transform.position;
                HelperVehicles.Note(string.Format("{0}: leaving the shoal for deep water - {1:0} m", Debug.Id(_bot), CoreEx.DistanceFlat(_tightFrom, _tightPoint)));
                return true;
            }
            private bool TightEnd(bool cooldown, string why = null)
            {
                if (_tight != Tight.None && why != null) HelperVehicles.Note(string.Format("{0}: tight-space maneuver cancelled - {1}", Debug.Id(_bot), why));
                if (_tight != Tight.None && cooldown) _tightCooldown = UnityEngine.Time.time + TightCooldown;
                if (_tight != Tight.None) ResetBaseStall();
                _tight = Tight.None;
                _tightConstrained = false;
                return false;
            }
            private Vector3 TightAim(Vector3 position)
            {
                IReadOnlyList<Vector3> route = Route;
                if (route != null && route.Count >= 2 && Plan.TryGetPointAhead(position, TightAimAhead, out Vector3 point)) return point;
                return route != null && route.Count > 0 ? route[route.Count - 1] : AimAt;
            }
            private bool DeepPoint(Vector3 position, Vector3 aim, out Vector3 point)
            {
                point = position;
                float shallow = 1.3f + Mathf.Clamp((_profile.HalfLength - 2.5f) * 0.15f, 0f, 0.7f) + 0.3f;
                Vector3 toAim = aim - position;
                toAim.y = 0f;
                float best = float.MaxValue;
                foreach (float radius in DeepRings)
                {
                    for (int i = 0; i < 16; i++)
                    {
                        Vector3 dir = Quaternion.Euler(0f, i * 22.5f, 0f) * Vector3.forward;
                        Vector3 p = position + dir * radius;
                        if (BoatDepth(p) < DeepEnough) continue;
                        bool clear = true;
                        for (float d = 3f; d < radius && clear; d += 3f) clear = BoatDepth(position + dir * d) >= shallow;
                        if (!clear) continue;
                        float score = toAim.sqrMagnitude > 1f ? Vector3.Angle(dir, toAim) : 0f;
                        if (score >= best) continue;
                        best = score;
                        point = p;
                    }
                    if (best < float.MaxValue) return true;
                }
                return false;
            }
            private static float BoatDepth(Vector3 p)
            {
                p.y = TerrainMeta.HeightMap.GetHeight(p);
                return WaterLevel.GetOverallWaterDepth(p, waves: false, volumes: true);
            }
            public int RecentGroundings(float seconds)
            {
                float since = UnityEngine.Time.time - seconds;
                int count = 0;
                for (int i = _groundings.Count - 1; i >= 0 && _groundings[i] >= since; i--) count++;
                return count;
            }
            private readonly List<float> _groundings = new();
            private bool TightBackDirection(Vector3 position, Vector3 forward, Vector3 prefer, float minClear, out Vector3 best, out float bestClear)
            {
                best = -forward;
                bestClear = 0f;
                float bestScore = float.MinValue;
                float shallow = 1.3f + Mathf.Clamp((_profile.HalfLength - 2.5f) * 0.15f, 0f, 0.7f);
                for (int i = -2; i <= 2; i++)
                {
                    Vector3 dir = Quaternion.Euler(0f, i * 25f, 0f) * -forward;
                    float clear = Sense(dir, 8f).Clear;
                    float score = clear - Vector3.Angle(dir, prefer) * 0.05f - (BoatDepth(position + dir * 8f) >= shallow ? 0f : 6f);
                    if (score <= bestScore) continue;
                    bestScore = score;
                    best = dir;
                    bestClear = clear;
                }
                return bestClear >= minClear;
            }
            #endregion
            private bool _pivoting;
            private float _pivotGas = 1f, _pivotStarted, _pivotCheckAt, _pivotFrom, _kickUntil;
            private const float PivotEnter = 60f, PivotHoldEnter = 35f, PivotExit = 20f, PivotExitYawRate = 20f, PivotMinRange = 4f, PivotMaxRange = 60f, PivotMaxTime = 8f;
            private const float PivotForward = 1.5f, PivotBack = 0.5f, PivotLead = 0.45f, PivotFullSteer = 12f;
            private const float KickSpeed = 1f, KickTime = 1f;
            private bool ChasePivot()
            {
                BaseEntity target = FollowTarget;
                Rigidbody body = _vehicle != null ? _vehicle.rigidBody : null;
                if (body == null || _profile == null || target == null || target.IsDestroyed || ChaseKeep <= 0f) return _pivoting = false;
                Vector3 position = _vehicle.transform.position;
                Vector3 to = target.transform.position - position;
                to.y = 0f;
                Vector3 forward = _vehicle.transform.forward;
                forward.y = 0f;
                float distance = to.magnitude;
                if (distance < PivotMinRange || forward.sqrMagnitude < 0.001f) return _pivoting = false;
                float error = GunAim(Vector3.SignedAngle(forward, to, Vector3.up));
                float yawRate = body.angularVelocity.y * Mathf.Rad2Deg;
                float along = Vector3.Dot(body.linearVelocity, _vehicle.transform.forward);
                float now = UnityEngine.Time.time;
                float steer = Mathf.Clamp((error - yawRate * PivotLead) / PivotFullSteer, -1f, 1f) * SteerMaxPerFrame;
                if (_pivoting && distance > PivotMaxRange)
                {
                    _pivoting = false;
                    _kickUntil = now + KickTime;
                }
                if (!_pivoting && now < _kickUntil)
                {
                    if (along < KickSpeed && distance > ChaseKeep)
                    {
                        ApplyInput(1f, steer, false);
                        return true;
                    }
                    _kickUntil = 0f;
                }
                if (distance > PivotMaxRange) return false;
                if (!_pivoting)
                {
                    if (DesiredThrottle < 0f && along < 0.5f) return false;
                    if (Mathf.Abs(error) < (distance <= ChaseKeep + 1f ? PivotHoldEnter : PivotEnter) || !PivotRoom(position)) return false;
                    _pivoting = true;
                    _pivotStarted = now;
                    _pivotCheckAt = now + 0.5f;
                    _pivotFrom = error;
                    _pivotGas = along > PivotForward ? -1f : 1f;
                }
                else if ((Mathf.Abs(error) < PivotExit && Mathf.Abs(yawRate) < PivotExitYawRate) || now - _pivotStarted > PivotMaxTime)
                {
                    _pivoting = false;
                    HelperVehicles.Note(string.Format("{0}: turned in place toward chase target {1:+0;-0} deg -> {2:+0;-0} deg in {3:0.0} s, {4:0} m to target",
                        Debug.Id(_bot), _pivotFrom, error, now - _pivotStarted, distance));
                    if (distance <= ChaseKeep) return false;
                    _kickUntil = now + KickTime;
                    ApplyInput(1f, steer, false);
                    return true;
                }
                else if (now >= _pivotCheckAt)
                {
                    _pivotCheckAt = now + 0.5f;
                    if (!PivotRoom(position)) return _pivoting = false;
                }
                if (_pivotGas > 0f && along > PivotForward) _pivotGas = -1f;
                else if (_pivotGas < 0f && along < -PivotBack) _pivotGas = 1f;
                ApplyInput(_pivotGas, _pivotGas < 0f ? -steer : steer, true);
                return true;
            }
            private static readonly Collider[] _pivotHits = new Collider[32];
            private static int _pivotMask;
            private bool PivotRoom(Vector3 position)
            {
                if (_pivotMask == 0) _pivotMask = LayerMask.GetMask("World", "Construction", "Deployed", "Default", "Tree", "Vehicle World", "Vehicle Large", "Vehicle Detailed");
                float radius = _profile.HalfLength + 1f;
                float shallow = 1.3f + Mathf.Clamp((_profile.HalfLength - 2.5f) * 0.15f, 0f, 0.7f);
                for (int i = 0; i < 8; i++)
                {
                    Vector3 p = position + Quaternion.Euler(0f, i * 45f, 0f) * Vector3.forward * radius;
                    p.y = TerrainMeta.HeightMap.GetHeight(p);
                    if (WaterLevel.GetOverallWaterDepth(p, waves: false, volumes: true) < shallow) return false;
                }
                Vector3 center = new Vector3(position.x, WaterLevel.GetWaterSurface(position, false, true) - 0.3f, position.z);
                int count = Physics.OverlapBoxNonAlloc(center, new Vector3(radius, 1f, radius), _pivotHits, Quaternion.identity, _pivotMask, QueryTriggerInteraction.Ignore);
                for (int i = 0; i < count; i++)
                {
                    BaseEntity entity = _pivotHits[i] != null ? _pivotHits[i].ToBaseEntity() : null;
                    bool own = false;
                    for (int depth = 0; depth < 6 && entity != null && !own; depth++)
                    {
                        own = entity == _vehicle;
                        entity = entity.GetParentEntity();
                    }
                    if (!own) return false;
                }
                return true;
            }
            private void WatchShoal()
            {
                if (_vehicle == null || _profile == null || Mathf.Abs(GetSpeed()) > 0.6f) return;
                Vector3 position = _vehicle.transform.position;
                float shallow = 1.3f + Mathf.Clamp((_profile.HalfLength - 2.5f) * 0.15f, 0f, 0.7f);
                if (WaterLevel.GetOverallWaterDepth(position, waves: false, volumes: true) >= shallow) return;
                Vector3 forward = _vehicle.transform.forward;
                forward.y = 0f;
                Vector3 spot = position + (forward.sqrMagnitude > 0.001f ? forward.normalized * _profile.HalfLength : Vector3.zero);
                float now = UnityEngine.Time.time, until = now + ShoalMemory;
                if (now - _aground > 3f)
                {
                    if (_groundings.Count >= 16) _groundings.RemoveAt(0);
                    _groundings.Add(now);
                }
                _aground = now;
                for (int i = 0; i < _shoals.Count; i++)
                {
                    if (CoreEx.DistanceFlat(_shoals[i], spot) > 4f) continue;
                    _shoals[i] = spot;
                    _shoalsUntil[i] = until;
                    return;
                }
                if (_shoals.Count >= ShoalSpots)
                {
                    _shoals.RemoveAt(0);
                    _shoalsUntil.RemoveAt(0);
                }
                _shoals.Add(spot);
                _shoalsUntil.Add(until);
            }
            private float _aground = -10f;
            private bool NearShoal(Vector3 position, out Vector3 spot)
            {
                spot = Vector3.zero;
                float best = ShoalAvoidRange, now = UnityEngine.Time.time;
                for (int i = 0; i < _shoals.Count; i++)
                {
                    if (now >= _shoalsUntil[i]) continue;
                    float distance = CoreEx.DistanceFlat(_shoals[i], position);
                    if (distance > best) continue;
                    best = distance;
                    spot = _shoals[i];
                }
                return spot != Vector3.zero;
            }
            private float ShoalHeading(float headingError)
            {
                if (_vehicle == null || _shoals.Count == 0) return headingError;
                Vector3 forward = _vehicle.transform.forward;
                forward.y = 0f;
                if (forward.sqrMagnitude < 0.001f) return headingError;
                float now = UnityEngine.Time.time;
                for (int i = 0; i < _shoals.Count; i++)
                {
                    if (now >= _shoalsUntil[i]) continue;
                    Vector3 to = _shoals[i] - _vehicle.transform.position;
                    to.y = 0f;
                    float distance = to.magnitude;
                    if (distance < 1f || distance > ShoalAvoidRange) continue;
                    float shoalAngle = Vector3.SignedAngle(forward, to, Vector3.up);
                    float gap = Mathf.DeltaAngle(shoalAngle, headingError);
                    float pass = Mathf.Asin(Mathf.Clamp01(ShoalPass / distance)) * Mathf.Rad2Deg;
                    if (Mathf.Abs(gap) < pass) headingError = shoalAngle + (gap >= 0f ? pass : -pass);
                }
                return headingError;
            }
            protected override float SteerDamping => Tuning?.SteerDamping ?? 0.35f;
            protected override bool SteerAlongRoute => false;
            private float _desired;

            public float ChaseKeep { get; set; }
            private const float TurnHoldError = 60f, TurnSteerageSpeed = 4.5f, TurnHoldClear = 10f;
            protected override float DesiredSpeed(float distance, float headingError, float clear)
            {
                headingError = ShoalHeading(LaneHeading(headingError));
                float lead = _followLead.Lead(FollowTarget, _vehicle);
                bool chase = FollowTarget != null && ChaseKeep > 0f;
                float lag = chase && lead > 0.5f ? Mathf.Max(0f, distance - ChaseKeep) : 0f;
                float sense = LaneDirect ? LaneClear : clear;
                bool lane = LaneMode;
                float baseError = chase ? Mathf.Clamp(headingError, -ChaseTurnFrom + 1f, ChaseTurnFrom - 1f)
                    : lane && LaneDirect ? Mathf.Clamp(headingError, -LaneBaseError, LaneBaseError) : headingError;
                _desired = base.DesiredSpeed(distance + 2f * Mathf.Max(0f, lead) + lag, baseError, sense);
                float steerError = chase ? GunAim(headingError) : headingError;
                if (chase && Mathf.Abs(steerError) > ChaseTurnFrom) _desired = Mathf.Min(_desired, ChaseTurnSpeed);
                if (lane) _desired = Mathf.Min(_desired, LaneSpeedLimit(headingError));
                else if (Mathf.Abs(headingError) > TurnHoldError && sense > TurnHoldClear)
                    _desired = Mathf.Max(_desired, Mathf.Min(Mathf.Abs(GetSpeed()) + 0.6f, TurnSteerageSpeed));
                if (chase) _desired = SteerageGas(_desired, steerError);
                else if (lane) _desired = LaneGas(_desired, headingError);
                if (chase && lead <= 0.5f && distance - ChaseKeep < GetSpeed() * CoastPerSpeed) _desired = 0f;
                return _desired;
            }
            private const float CoastPerSpeed = 0.8f;
            private const float ChaseTurnFrom = 30f, ChaseTurnSpeed = 7f, SteerageError = 15f, SteerageMinSpeed = 2.5f;
            private float SteerageGas(float desired, float steerError)
            {
                if (Mathf.Abs(steerError) < SteerageError || desired < SteerageMinSpeed) return desired;
                float speed = GetSpeed();
                if (Mathf.Abs(desired - speed) > 0.5f) return desired;
                return speed > desired && speed > 3.2f ? speed - 0.6f : speed + 0.6f;
            }
            private readonly TargetLead _followLead = new();
            private const float GunOffset = 15f, GunOffsetRange = 40f;
            private BaseEntity _gunSideFor;
            private float _gunSide = 1f;
            private float GunAim(float headingError)
            {
                BaseEntity target = FollowTarget;
                if (!(_vehicle is RHIB) || target == null || target.IsDestroyed || CoreEx.DistanceFlat(_vehicle.transform.position, target.transform.position) > GunOffsetRange)
                {
                    _gunSideFor = null;
                    return headingError;
                }
                if (!ReferenceEquals(_gunSideFor, target))
                {
                    _gunSideFor = target;
                    _gunSide = headingError < -3f ? -1f : 1f;
                }
                return headingError - _gunSide * GunOffset;
            }
            protected override float SteerFor(float headingError, float speed)
            {
                headingError = GunAim(ShoalHeading(LaneHeading(headingError)));
                if (LaneMode) return LaneSteer(headingError, speed, _desired);
                Rigidbody body = _vehicle != null ? _vehicle.rigidBody : null;
                float yawRate = body != null ? body.angularVelocity.y * Mathf.Rad2Deg : 0f;
                if (Mathf.Abs(headingError) < SteerDeadZone && Mathf.Abs(yawRate) < 10f) return 0f;
                float fade = Mathf.Lerp(0.35f, 1f, Mathf.Clamp01(1f - speed / Mathf.Max(1f, _profile.CruiseSpeed * 1.5f)));
                float steer = Mathf.Clamp((headingError * SteerGain - yawRate * SteerDamping) * fade, -SteerMaxPerFrame, SteerMaxPerFrame);
                return _desired - speed < -0.5f && speed > 3f ? -steer : steer;
            }
            private bool LaneMode => FollowTarget == null;
            protected override Vector3 LaneAimOffRoute(Vector3 position, float ahead, Vector3 aim) => Plan.TryGetPointAhead(position, ahead, out Vector3 point) ? point : aim;
            #endregion
        }

        public class EventAirPilot : HelperVehicles.AirVehicleController, IEventPilot
