            private bool _altitudeApplied;
            private float? _tuningAltitude;
            public float Altitude
            {
                get => _altitude;
                set
                {
                    _altitude = Mathf.Max(0f, value);
                    if (_altitude > 0f)
                    {
                        Tuning ??= new HelperVehicles.VehicleTuning();
                        if (!_altitudeApplied)
                        {
                            _tuningAltitude = Tuning.CruiseAltitude;
                            _altitudeApplied = true;
                        }
                        Tuning.CruiseAltitude = _altitude;
                    }
                    else if (_altitudeApplied)
                    {
                        if (Tuning != null) Tuning.CruiseAltitude = _tuningAltitude;
                        _altitudeApplied = false;
                    }
                }
