                        if (!_bandApplied)
                        {
                            _tuningBand = Tuning.AltitudeDeadZone;
                            _bandApplied = true;
                        }
                        Tuning.AltitudeDeadZone = _band;
                    }
                    else if (_bandApplied)
                    {
                        if (Tuning != null) Tuning.AltitudeDeadZone = _tuningBand;
                        _bandApplied = false;
                    }
                }
            }
            public void SetPolyline(List<Vector3> points) => _line.Set(points);
            protected override float CruiseAltitude => base.CruiseAltitude + (_vehicle != null ? CoreEx.WaterDepth(_vehicle.transform.position) : 0f);
