        public static class CoreRoutes
        {
            public static List<Vector3> WithStart(Vector3 start, List<Vector3> route)
            {
                List<Vector3> result = new List<Vector3>(route.Count + 1) { start };
                foreach (Vector3 point in route)
                {
                    if (CoreEx.DistanceFlat(point, result[result.Count - 1]) < 0.5f) continue;
                    result.Add(point);
                }
                return result;
            }
            public static bool LongEnough(Vector3 start, List<Vector3> route, int minPoints, float minLength)
            {
                if (route == null || route.Count + 1 < minPoints) return false;
                float length = route.Count > 0 ? Vector3.Distance(start, route[0]) + CoreEx.Distance(route) : 0f;
                return length >= minLength;
            }
            public static MonumentInfo MonumentAt(Vector3 point, float margin)
            {
                List<MonumentInfo> monuments = TerrainMeta.Path != null ? TerrainMeta.Path.Monuments : null;
                if (monuments == null) return null;
                foreach (MonumentInfo monument in monuments)
                {
                    if (monument == null) continue;
                    Transform t = monument.transform;
                    Vector3 local = Quaternion.Inverse(t.rotation) * (point - t.position) - monument.Bounds.center;
                    Vector3 extents = monument.Bounds.extents;
                    if (Mathf.Abs(local.x) <= extents.x + margin && Mathf.Abs(local.z) <= extents.z + margin) return monument;
                }
                return null;
            }
            public static bool RouteBlocks(Collider collider)
            {
                if (collider == null) return false;
                if (GroundChecks.IsRoadOrBush(collider.name)) return false;
                BaseEntity entity = collider.ToBaseEntity();
                for (int depth = 0; depth < 4 && entity != null; depth++)
                {
                    if (entity is BaseVehicle || entity is BasePlayer || entity.IsNpc) return false;
                    entity = entity.GetParentEntity();
                }
                return true;
            }

            public struct NodeInfo
            {
                public Vector3 position;
                public float radius;
            }
            private static bool CanVisit(List<string> blackList, string name, string prefab)
            {
                if (blackList == null || blackList.Count == 0) return true;
                foreach (string entry in blackList)
                {
                    if (string.IsNullOrEmpty(entry)) continue;
                    string lower = entry.ToLower();
                    if (!string.IsNullOrEmpty(name) && name.Contains(lower)) return false;
                    if (!string.IsNullOrEmpty(prefab) && prefab.Contains(lower)) return false;
                }
                return true;
            }
            public static NodeInfo[] GetMonumentsVisit(int count, List<string> blackList)
            {
                count = Mathf.Max(2, count);
                NodeInfo[] result = null;
                if (TerrainMeta.Path?.Monuments?.Count > 0)
                {
                    List<MonumentInfo> monuments = new List<MonumentInfo>(TerrainMeta.Path.Monuments);
                    monuments.RemoveAll(x => x == null || !CanVisit(blackList, x.name?.ToLower(), x.displayPhrase?.english?.ToLower()));
                    CoreEx.SortRandom(monuments);
                    if (monuments.Count > count) monuments.RemoveRange(count, monuments.Count - count);
                    result = new NodeInfo[monuments.Count];
                    for (int i = 0; i < monuments.Count; i++)
                    {
                        result[i] = new NodeInfo
                        {
                            position = monuments[i].transform.position,
                            radius = Mathf.Max(monuments[i].Bounds.size.x, monuments[i].Bounds.size.z) / 2f
                        };
                    }
                }
                if (result == null || result.Length <= 1)
                {
                    result = new NodeInfo[count];
                    float size = Mathf.Min(TerrainMeta.Size.x, TerrainMeta.Size.z) / 2f;
                    for (int i = 0; i < count; i++)
                    {
                        Vector3 position = UnityEngine.Random.insideUnitSphere * size;
                        position.y = TerrainMeta.HeightMap.GetHeight(position);
                        result[i] = new NodeInfo { position = position, radius = UnityEngine.Random.Range(50f, 100f) };
                    }
                }
                return result;
            }
            public static List<Vector3> MonumentsCircleRoute(NodeInfo[] nodes, float height)
            {
                List<Vector3> route = new List<Vector3>();
                if (nodes == null) return route;
                Vector3 previous = Vector3.zero;
                for (int n = 0; n < nodes.Length; n++)
                {
                    Vector3 center = nodes[n].position;
                    route.Add(HeightPoint(center, height));
                    float radius = Mathf.Max(50f, nodes[n].radius);
                    Vector3 incoming = n == 0 ? -center : center - previous;
                    incoming.y = 0f;
                    float start = incoming.sqrMagnitude > 1f ? Mathf.Atan2(incoming.x, incoming.z) * Mathf.Rad2Deg : 0f;
                    float step = 45f;
                    if (n + 1 < nodes.Length)
                    {
                        Vector3 next = nodes[n + 1].position;
                        if (CoreEx.DistanceFlat(CirclePoint(center, start + 45f, radius), next) < CoreEx.DistanceFlat(CirclePoint(center, start - 45f, radius), next))
                            step = -45f;
                    }
                    for (int i = 0; i < 8; i++)
                    {
                        previous = CirclePoint(center, start + step * i, radius);
                        route.Add(HeightPoint(previous, height));
                    }
                }
                RemoveHairpins(route, 150f);
                return route;
            }
            private static Vector3 CirclePoint(Vector3 center, float angle, float radius) => center + Quaternion.Euler(0f, angle, 0f) * Vector3.forward * radius;
            private static void RemoveHairpins(List<Vector3> route, float angle)
            {
                for (int i = 1; i < route.Count - 1;)
                {
                    Vector3 a = route[i] - route[i - 1];
                    Vector3 b = route[i + 1] - route[i];
                    a.y = 0f;
                    b.y = 0f;
                    if (a.sqrMagnitude > 1f && b.sqrMagnitude > 1f && Vector3.Angle(a, b) > angle)
                    {
                        route.RemoveAt(i);
                        if (i > 1) i--;
                    }
                    else i++;
                }
            }
            public static Vector3 HeightPoint(Vector3 position, float height)
            {
                float ground = TerrainMeta.HeightMap.GetHeight(position);
                if (ground < WaterSystem.OceanLevel) ground = WaterSystem.OceanLevel;
                if (Physics.Raycast(new Vector3(position.x, ground + 200f, position.z), Vector3.down, out RaycastHit hit, 200f,
                        LayerMask.GetMask("World", "Vehicle Detailed", "Vehicle World", "Construction", "Water", "Prevent Movement", "Tree", "Terrain", "Default")))
                    ground = Mathf.Max(ground, hit.point.y);
                return new Vector3(position.x, ground + height, position.z);
            }
            public static List<HelperVehicles.PatrolTarget> PatrolTargets(bool water, List<string> blackList)
            {
                List<HelperVehicles.PatrolTarget> targets = HelperVehicles.CollectPatrolTargets(water);
                targets.RemoveAll(x => x == null || !CanVisit(blackList, x.Name?.ToLower(), null));
                return targets;
            }
        }

        #endregion

        #region VehicleEventsCore: линия через монумент
        public static class CoreLines
        {
            public const float ZoneMargin = 10f;
            private const float Step = 1f, Cell = 0.5f, Reach = 11f, PointStep = 2f, MaxLength = 600f, CacheTime = 1800f, FrameBudget = 3f;
            private const float Margin = 0.45f, TurnMargin = 0.35f;
            private const float SlowSpeed = 3f, FastSpeed = 7f;
            private const float SideGrade = 0.29f, SteepCost = 4f, SteepCostMax = 12f;
            private const sbyte CellFree = 1, CellObstacle = 2;

            public struct Point
            {
                public Vector3 Pos;
                public Vector2 Clear;
                public float Speed, Offset;
            }
            public sealed class Request
            {
                public float Body;
                public float[] Lanes = { 0f };
                public bool Slopes;
                public Func<float[][], bool> Needed;
            }
            public sealed class Job
            {
                public Vector3[] Points, Result;
                public Point[][] Lines;
                public int Sections, Frames;
            }
            private sealed class Plan
            {
                public Point[][] Points;
            }
            private static readonly Dictionary<string, KeyValuePair<float, Point[][]>> _cache = new();
            private static readonly System.Diagnostics.Stopwatch _watch = new System.Diagnostics.Stopwatch();

            public static IEnumerator Build(Job job, Func<Vector3[], int, int, Request> request)
            {
                Vector3[] points = job.Points;
                job.Result = points;
                job.Lines = null;
                if (points == null || points.Length < 2) yield break;
                int count = points.Length;
                bool[] zone = new bool[count];
                bool any = false;
                for (int i = 0; i < count; i++)
                    if (zone[i] = CoreRoutes.MonumentAt(points[i], ZoneMargin) != null) any = true;
                if (!any) yield break;
                List<Vector3> result = new List<Vector3>(count + 64);
                List<Point[]> lines = new List<Point[]>(count + 64);
                void Put(Vector3 point, Point[] line)
                {
                    result.Add(point);
                    lines.Add(line);
                }
                job.Frames = 1;
                _watch.Restart();
                for (int i = 0; i < count;)
                {
                    if (!zone[i])
                    {
                        Put(points[i], null);
                        i++;
                        continue;
                    }
                    int s = i, e = i;
                    while (e + 1 < count && zone[e + 1]) e++;
                    int a = Mathf.Max(0, s - 1), b = Mathf.Min(count - 1, e + 1);
                    if (a == s) Put(points[a], null);
                    Plan plan = new Plan();
                    if (a < b)
                    {
                        IEnumerator planning = PlanSection(points, a, b, request(points, a, b), plan);
                        while (planning.MoveNext())
                        {
                            job.Frames++;
                            yield return null;
                            _watch.Restart();
                        }
                    }
                    if (plan.Points != null && plan.Points.Length > 0)
                    {
                        job.Sections++;
                        foreach (Point[] line in plan.Points) Put(line[0].Pos, line);
                    }
                    else
                    {
                        for (int k = s; k <= e; k++)
                            if (k != a && k != b) Put(points[k], null);
                    }
                    if (b > a) Put(points[b], null);
                    i = b + 1;
                }
                if (job.Sections == 0) yield break;
                job.Result = result.ToArray();
                job.Lines = lines.ToArray();
            }
            private static bool Due() => _watch.Elapsed.TotalMilliseconds > FrameBudget;
            private static IEnumerator PlanSection(Vector3[] points, int a, int b, Request request, Plan plan)
            {
                float length = 0f;
                for (int i = a; i < b; i++) length += CoreEx.DistanceFlat(points[i], points[i + 1]);
                if (length < 4f || length > MaxLength) yield break;
                string key = $"{points[a].x:0.0},{points[a].z:0.0}>{points[b].x:0.0},{points[b].z:0.0}#{b - a}/{request.Body:0.00}";
                foreach (float lane in request.Lanes) key += $"/{lane:0.00}";
                float now = UnityEngine.Time.realtimeSinceStartup;
                if (_cache.TryGetValue(key, out KeyValuePair<float, Point[][]> cached) && now - cached.Key < CacheTime)
                {
                    plan.Points = cached.Value;
                    yield break;
                }
                IEnumerator building = BuildSection(points, a, b, length, request, plan);
                while (building.MoveNext()) yield return building.Current;
                now = UnityEngine.Time.realtimeSinceStartup;
                if (_cache.Count >= 64)
                {
                    List<string> stale = new List<string>();
                    foreach (KeyValuePair<string, KeyValuePair<float, Point[][]>> entry in _cache)
                        if (now - entry.Value.Key >= CacheTime) stale.Add(entry.Key);
                    foreach (string old in stale) _cache.Remove(old);
                }
                _cache[key] = new KeyValuePair<float, Point[][]>(now, plan.Points);
            }
            private static IEnumerator BuildSection(Vector3[] points, int a, int b, float length, Request request, Plan plan)
            {
                plan.Points = Array.Empty<Point[]>();
                int stations = Mathf.CeilToInt(length / Step) + 1;
                Vector3[] at = new Vector3[stations], right = new Vector3[stations], along = new Vector3[stations];
                for (int k = 0; k < stations; k++)
                {
                    float s = Mathf.Min(k * Step, length);
                    at[k] = PolylineAt(points, a, b, s);
                    Vector3 dir = PolylineAt(points, a, b, Mathf.Min(length, s + 1.5f)) - PolylineAt(points, a, b, Mathf.Max(0f, s - 1.5f));
                    dir.y = 0f;
                    along[k] = dir.sqrMagnitude > 0.0001f ? dir.normalized : Vector3.forward;
                    right[k] = new Vector3(along[k].z, 0f, -along[k].x);
                }
                int half = Mathf.RoundToInt(Reach / Cell), cells = half * 2 + 1, directions = request.Lanes.Length;
                int w0 = Cells(request.Body + Margin), w1 = Cells(request.Body + Margin + TurnMargin), wBody = Cells(request.Body);
                sbyte[,] occupied = new sbyte[stations, cells];
                bool[,] steepCell = request.Slopes ? new bool[stations, cells] : null;
                bool[] stripClear = new bool[stations];
                float[] heights = new float[cells];
                bool Obstacle(int k, int c)
                {
                    if (occupied[k, c] == 0)
                        occupied[k, c] = !stripClear[k] && CellBlocked(at[k], right[k], along[k], (c - half) * Cell) ? CellObstacle : CellFree;
                    return occupied[k, c] == CellObstacle;
                }
                bool Free(int k, int c, int w)
                {
                    if (c - w < 0 || c + w >= cells) return false;
                    for (int x = c - w; x <= c + w; x++)
                        if (Obstacle(k, x)) return false;
                    return true;
                }
                bool lanesClear = true;
                for (int k = 0; k < stations; k++)
                {
                    if (Due()) yield return null;
                    float low = float.MaxValue, high = float.MinValue;
                    for (int x = 0; x < cells; x++)
                    {
                        heights[x] = TerrainMeta.HeightMap.GetHeight(at[k] + right[k] * ((x - half) * Cell));
                        low = Mathf.Min(low, heights[x]);
                        high = Mathf.Max(high, heights[x]);
                    }
                    if (steepCell != null)
                    {
                        for (int c = 0; c < cells; c++)
                        {
                            int c0 = Mathf.Max(0, c - 1), c1 = Mathf.Min(cells - 1, c + 1);
                            steepCell[k, c] = Mathf.Abs(heights[c1] - heights[c0]) / ((c1 - c0) * Cell) > SideGrade
                                              && !OnDeck(at[k] + right[k] * ((c - half) * Cell), at[k].y, heights[c]);
                        }
                    }
                    stripClear[k] = BoxClear(new Vector3(at[k].x, (low + high) * 0.5f + 1.1f, at[k].z),
                        new Vector3(Reach + Cell * 0.5f, (high - low) * 0.5f + 0.85f, Step * 0.5f), along[k]);
                    foreach (float lane in request.Lanes)
                        if (!Free(k, half + Mathf.RoundToInt(lane / Cell), w0)) lanesClear = false;
                }
                if (lanesClear) yield break;
                for (int k = 0; k < stations; k++)
                {
                    for (int c = 0; c < cells; c++)
                    {
                        if (occupied[k, c] != 0) continue;
                        if ((c & 7) == 0 && Due()) yield return null;
                        Obstacle(k, c);
                    }
                }
                float Side(int k, int c, int sign, bool steep)
                {
                    for (int d = 1; d <= 4; d++)
                    {
                        int x = c + sign * (w0 + d);
                        if (x < 0 || x >= cells) return 2f;
                        if (Obstacle(k, x) || (steep && steepCell != null && steepCell[k, x])) return (d - 1) * Cell;
                    }
                    return 2f;
                }
                float Steep(int k, int c)
                {
                    if (steepCell == null) return 0f;
                    int count = 0;
                    for (int x = Mathf.Max(0, c - wBody); x <= Mathf.Min(cells - 1, c + wBody); x++)
                        if (steepCell[k, x]) count++;
                    return Mathf.Min(SteepCostMax, count * SteepCost);
                }
                float Local(int k, int c, float lane)
                {
                    float clear = Mathf.Min(Side(k, c, -1, false), Side(k, c, 1, false));
                    return (Free(k, c, w0) ? 0f : 40f) + Steep(k, c) + 4f * Mathf.Max(0f, 1f - clear) + 0.3f * Mathf.Abs((c - half) * Cell - lane);
                }
                int lo = w1, hi = cells - 1 - w1;
                float[,] cost = new float[stations, cells];
                int[,] from = new int[stations, cells];
                int[] cell = new int[stations];
                float[] smooth = new float[stations];
                float[][] lateral = new float[directions][];
                for (int l = 0; l < directions; l++)
                {
                    float lane = request.Lanes[l];
                    for (int c = lo; c <= hi; c++) cost[0, c] = Local(0, c, lane) + 3f * Mathf.Abs((c - half) * Cell - lane);
                    for (int k = 1; k < stations; k++)
                    {
                        if (Due()) yield return null;
                        for (int c = lo; c <= hi; c++)
                        {
                            float best = float.MaxValue;
                            int bestFrom = c;
                            for (int d = -1; d <= 1; d++)
                            {
                                int p = c + d;
                                if (p < lo || p > hi) continue;
                                float step = cost[k - 1, p] + 0.4f * Mathf.Abs(d) + (d != 0 && !Free(k, c, w1) ? 40f : 0f);
                                if (step >= best) continue;
                                best = step;
                                bestFrom = p;
                            }
                            cost[k, c] = best + Local(k, c, lane) + (k == stations - 1 ? 3f * Mathf.Abs((c - half) * Cell - lane) : 0f);
                            from[k, c] = bestFrom;
                        }
                    }
                    int end = lo;
                    for (int c = lo; c <= hi; c++)
                        if (cost[stations - 1, c] < cost[stations - 1, end]) end = c;
                    cell[stations - 1] = end;
                    for (int k = stations - 1; k > 0; k--) cell[k - 1] = from[k, cell[k]];
                    float[] offset = lateral[l] = new float[stations];
                    for (int k = 0; k < stations; k++) offset[k] = (cell[k] - half) * Cell;
                    for (int pass = 0; pass < 2; pass++)
                    {
                        for (int k = 0; k < stations; k++)
                            smooth[k] = k == 0 || k == stations - 1 ? offset[k] : (offset[k - 1] + 2f * offset[k] + offset[k + 1]) * 0.25f;
                        for (int k = 1; k < stations - 1; k++)
                        {
                            int c = Mathf.RoundToInt(smooth[k] / Cell) + half;
                            if (Free(k, c, w0) && Steep(k, c) <= Steep(k, cell[k])) offset[k] = smooth[k];
                        }
                    }
                }
                bool needed = request.Needed != null && request.Needed(lateral);
                for (int l = 0; l < directions && request.Needed == null && !needed; l++)
                    for (int k = 0; k < stations && !needed; k++)
                        needed = Mathf.Abs(lateral[l][k] - request.Lanes[l]) > 0.25f;
                if (!needed) yield break;
                Point Describe(float[] offset, int k, float lane)
                {
                    Vector2 clear = new Vector2(2.5f, 2.5f);
                    float tight = 2f;
                    bool free = true;
                    for (int j = Mathf.Max(0, k - 3); j <= Mathf.Min(stations - 1, k + 3); j++)
                    {
                        int cj = Mathf.Clamp(Mathf.RoundToInt(offset[j] / Cell) + half, lo, hi);
                        tight = Mathf.Min(tight, Mathf.Min(Side(j, cj, -1, false), Side(j, cj, 1, false)));
                        free &= Free(j, cj, w0);
                        if (Mathf.Abs(j - k) > 1) continue;
                        clear.x = Mathf.Min(clear.x, Side(j, cj, -1, true) + Margin);
                        clear.y = Mathf.Min(clear.y, Side(j, cj, 1, true) + Margin);
                    }
                    float slope = Mathf.Abs(offset[Mathf.Min(stations - 1, k + 3)] - offset[Mathf.Max(0, k - 3)]) / 6f;
                    float speed = 0f;
                    if (!free || tight < 1.5f || slope > 0.05f || Mathf.Abs(offset[k] - lane) > 0.3f)
                    {
                        speed = free ? Mathf.Lerp(SlowSpeed, FastSpeed, (tight - 0.3f) / 1.2f) : SlowSpeed;
                        if (slope > 0.15f) speed = Mathf.Min(speed, 4f);
                    }
                    Vector3 pos = at[k] + right[k] * offset[k];
                    pos.y = Mathf.Max(at[k].y, TerrainMeta.HeightMap.GetHeight(pos));
                    return new Point { Pos = pos, Clear = new Vector2(Mathf.Max(0.3f, clear.x), Mathf.Max(0.3f, clear.y)), Speed = speed, Offset = offset[k] };
                }
                List<Point[]> line = new List<Point[]>();
                int stride = Mathf.Max(1, Mathf.RoundToInt(PointStep / Step));
                for (int k = stride; k < stations - 1; k += stride)
                {
                    if (Due()) yield return null;
                    Point[] station = new Point[directions];
                    for (int l = 0; l < directions; l++) station[l] = Describe(lateral[l], k, request.Lanes[l]);
                    line.Add(station);
                }
                plan.Points = line.ToArray();
            }
            private static int Cells(float halfWidth) => Mathf.CeilToInt(halfWidth / Cell + 0.5f) - 1;
            private static Vector3 PolylineAt(Vector3[] points, int a, int b, float distance)
            {
                for (int i = a; i < b; i++)
                {
                    float segment = CoreEx.DistanceFlat(points[i], points[i + 1]);
                    if (distance <= segment || i == b - 1) return Vector3.Lerp(points[i], points[i + 1], segment > 0.01f ? Mathf.Clamp01(distance / segment) : 1f);
                    distance -= segment;
                }
                return points[b];
            }

            private static int _mask, _floorMask;
            private static readonly Collider[] _hits = new Collider[64];
            private static int Mask => _mask != 0 ? _mask : _mask = LayerMask.GetMask("World", "Construction", "Deployed", "Tree", "Default");
            private static int FloorMask => _floorMask != 0 ? _floorMask : _floorMask = LayerMask.GetMask("World", "Construction");
            private static bool CellBlocked(Vector3 at, Vector3 right, Vector3 along, float lateral)
            {
                Vector3 p = at + right * lateral;
                float terrain = TerrainMeta.HeightMap.GetHeight(p);
                Vector3 half = new Vector3(Cell * 0.5f, 0.85f, Step * 0.5f);
                if (BoxClear(new Vector3(p.x, terrain + 1.1f, p.z), half, along)) return false;
                float level = Mathf.Max(at.y, terrain);
                if (!Physics.Raycast(new Vector3(p.x, level + 1f, p.z), Vector3.down, out RaycastHit floor, 2.5f, FloorMask, QueryTriggerInteraction.Ignore)
                    || floor.normal.y <= 0.95f || floor.point.y <= terrain || floor.point.y > level + 0.35f
                    || Mathf.Max(floor.collider.bounds.size.x, floor.collider.bounds.size.z) < 8f)
                    return true;
                return !BoxClear(new Vector3(p.x, floor.point.y + 1.1f, p.z), half, along);
            }
            private static bool BoxClear(Vector3 center, Vector3 half, Vector3 along)
            {
                int count = Physics.OverlapBoxNonAlloc(center, half, _hits, Quaternion.LookRotation(along, Vector3.up), Mask, QueryTriggerInteraction.Ignore);
                if (count >= _hits.Length) return false;
                for (int i = 0; i < count; i++)
                {
                    Collider collider = _hits[i];
                    if (collider == null) continue;
                    if (GroundChecks.IsRoadOrBush(collider.name)) continue;
                    return false;
                }
                return true;
            }
            private static bool OnDeck(Vector3 p, float level, float terrain)
            {
                return Physics.Raycast(new Vector3(p.x, Mathf.Max(level, terrain) + 1.5f, p.z), Vector3.down, out RaycastHit floor, 3f, FloorMask, QueryTriggerInteraction.Ignore)
                       && floor.point.y > terrain + 0.3f;
            }
        }
        #endregion

        #region VehicleEventsCore: бездорожье по навмешу игры
        public static class CoreNavLand
        {
            public delegate bool LegCheck(Vector3 a, Vector3 b, out Vector3 blockedAt);

            public sealed class Job
            {
                public Vector3 From, To;
                public LegCheck Check;
                public float BudgetMs = 4f;
                public bool WholeFallback;
                public List<Vector3> Along;
                public float[] BandWidths;
                public readonly List<Vector3> Result = new List<Vector3>();
                public bool NavFound;
                public bool WholeAStar;
                public string NavEnd = "";
                public float NavLength;
                public int Queries, Cells, Widenings, Checks, Band, Steps;
                public double WorkMs, MaxStepMs, NavMaxMs;
                public float Seconds;
            }

            private const float SnapRadius = 12f;
            private const int ChainMaxQueries = 24;
            private const float ChainMinGain = 25f;
            public static readonly float[] Widths = { 40f, 100f, 200f };
            private static readonly float[] WholeMargin = { 200f };

            private static readonly Rust.Ai.Gen2.RustNavMeshPath _navPath = new Rust.Ai.Gen2.RustNavMeshPath();

            public static string Describe(Job job)
            {
                if (job == null) return "-";
                string time = string.Format("{0} frames, {1:0.0} s, work {2:0} ms, longest step {3:0.0} ms{4}", job.Steps, job.Seconds, job.WorkMs, job.MaxStepMs,
                    job.Queries > 0 ? $" (longest navmesh query {job.NavMaxMs:0.0} ms)" : "");
                System.Text.StringBuilder text = new System.Text.StringBuilder();
                text.Append(job.Queries > 0 ? string.Format("navmesh path {0:0} m ({1} queries, {2})", job.NavLength, job.Queries, job.NavEnd) : job.NavEnd);
                if (job.NavFound)
                {
                    text.AppendFormat(", A* in a band {0:0} m", (job.BandWidths ?? Widths)[0]);
                    if (job.Widenings > 0) text.AppendFormat(" widened {0}x up to {1} m", job.Widenings, job.Band);
                    if (job.WholeAStar) text.Append(" - no way");
                }
                if (job.WholeAStar) text.AppendFormat(", whole A* {0:0} m", WholeMargin[0]);
                if (job.Cells > 0 || job.Checks > 0) text.AppendFormat(", cells {0}, checks {1}", job.Cells, job.Checks);
                if (job.Result.Count == 0) text.Append(", no way");
                return text.Append(", ").Append(time).ToString();
            }

            private sealed class Clock
            {
                public long Started;
                public void Restart() => Started = System.Diagnostics.Stopwatch.GetTimestamp();
                public double Ms => (System.Diagnostics.Stopwatch.GetTimestamp() - Started) * 1000d / System.Diagnostics.Stopwatch.Frequency;
            }

            public static IEnumerator Build(Job job)
            {
                Clock clock = new Clock();
                clock.Restart();
                float startedAt = UnityEngine.Time.realtimeSinceStartup;
                Func<Vector3, Vector3, bool> passable = null;
                if (job.Check != null)
                {
                    LegCheck check = job.Check;
                    passable = (a, b) => check(a, b, out _);
                }

                List<Vector3> corridor = null;
                job.NavEnd = "game navmesh not ready";
                if (job.Along != null && job.Along.Count >= 2)
                {
                    corridor = new List<Vector3>(job.Along);
                    job.NavFound = true;
                    job.NavEnd = string.Format("along the route {0:0} m", CoreEx.Distance(corridor));
                }
                else if (IsGameNavmeshReady())
                {
                    job.NavEnd = "";
                    corridor = new List<Vector3> { job.From };
                    if (!Rust.Ai.Gen2.RustNavMeshHelpers.SamplePosition(job.From, out UnityEngine.AI.NavMeshHit fromHit, SnapRadius, -1)
                        || !Rust.Ai.Gen2.RustNavMeshHelpers.SamplePosition(job.To, out UnityEngine.AI.NavMeshHit toHit, SnapRadius, -1))
                        job.NavEnd = "end off navmesh";
                    else
                    {
                        Vector3 a = fromHit.position, goal = toHit.position;
                        while (job.Queries < ChainMaxQueries)
                        {
                            if (job.Queries > 0 || clock.Ms >= job.BudgetMs)
                            {
                                Account(job, clock);
                                yield return null;
                                clock.Restart();
                            }
                            job.Queries++;
                            double queryStart = clock.Ms;
                            bool queried = Rust.Ai.Gen2.RustNavMeshHelpers.CalculatePath(a, goal, -1, _navPath);
                            job.NavMaxMs = Math.Max(job.NavMaxMs, clock.Ms - queryStart);
                            if (!queried) { job.NavEnd = "query failed"; break; }
                            int count = _navPath.corners.Count;
                            for (int i = 0; i < count; i++)
                            {
                                Vector3 c = _navPath.corners[i].Value;
                                if (CoreEx.DistanceFlat(c, corridor[corridor.Count - 1]) >= 0.5f) corridor.Add(c);
                            }
                            if (_navPath.status == UnityEngine.AI.NavMeshPathStatus.PathComplete) { job.NavFound = true; break; }
                            if (count == 0) { job.NavEnd = "no corners"; break; }
                            Vector3 stop = _navPath.corners[count - 1].Value;
                            if (Vector3.Distance(stop, goal) > Vector3.Distance(a, goal) - ChainMinGain) { job.NavEnd = "dead end"; break; }
                            a = stop;
                        }
                        if (job.NavFound) job.NavEnd = "complete";
                        else if (job.NavEnd.Length == 0) job.NavEnd = "query limit";
                    }
                    if (CoreEx.DistanceFlat(corridor[corridor.Count - 1], job.To) < 0.5f) corridor[corridor.Count - 1] = job.To;
                    else corridor.Add(job.To);
                    job.NavLength = CoreEx.Distance(corridor);
                }

                int[] stats = new int[4];
                if (corridor != null && job.NavFound)
                {
                    IEnumerator steps = HelperVehicles.LandRouteSteps(job.From, job.To, job.BudgetMs, corridor, job.BandWidths ?? Widths, passable, job.Result, stats);
                    while (steps.MoveNext())
                    {
                        Account(job, clock);
                        yield return null;
                        clock.Restart();
                    }
                    job.Cells += stats[0];
                    job.Widenings = stats[1];
                    job.Checks += stats[2];
                    job.Band = stats[3];
                }
                if (job.Result.Count == 0 && (corridor == null || job.WholeFallback))
                {
                    job.WholeAStar = true;
                    IEnumerator steps = HelperVehicles.LandRouteSteps(job.From, job.To, job.BudgetMs, null, WholeMargin, passable, job.Result, stats);
                    while (steps.MoveNext())
                    {
                        Account(job, clock);
                        yield return null;
                        clock.Restart();
                    }
                    job.Cells += stats[0];
                    job.Checks += stats[2];
                }
                Finish(job, clock, startedAt);
            }

            private static void Finish(Job job, Clock clock, float startedAt)
            {
                Account(job, clock);
                job.Seconds = UnityEngine.Time.realtimeSinceStartup - startedAt;
            }

            private static void Account(Job job, Clock clock)
            {
                double ms = clock.Ms;
                job.WorkMs += ms;
                if (ms > job.MaxStepMs) job.MaxStepMs = ms;
                job.Steps++;
            }
        }

        #endregion

        #region VehicleEventsCore: экипаж

        public class CrewNpc : BaseCustomNpc
        {
            public CompanionSettings Settings { get; private set; }
            public bool IsDriver { get; private set; }
            public EventRun Run { get; private set; }
            public IEventController Event => Run != null && CoreEx.Alive(Run.Owner) ? Run.Owner : null;
            public CoreHost Host => Run?.Host;
            public bool CanDismount;
            public bool ExternalWeapon;
            public float MountedRange = 60f;
            public float FootRange = 40f;
            public const float DeepWaterDepth = 1.7f;

            private List<LootInfo> _loots;
            private bool _blockNpcDamage;
            private bool _onFoot;
            private float _killTimerStart;
            private float _nextEngage;

            public bool HasBot => this.IsValid() && !IsDestroyed && IsAlive();
            public bool IsParachute => _chute != null && _chute.IsParachuting;
            public bool IsOnFoot => _onFoot;
            public bool BlockNpcDamage => _blockNpcDamage;
            public bool BlockAnyNonPlayerDamage;
            public bool CanFightMounted => HasBot && isMounted && (IsParachute || (!IsDriver && !ExternalWeapon));

            public override bool ShouldInitContainersFromConfig() => false;

            #region Setup
            public void Setup(EventRun run, CompanionSettings settings, bool isDriver, List<LootInfo> loots, BaseEventSettings eventSettings)
            {
                Run = run;
                Settings = settings;
                if (settings != null) MountedRange = Mathf.Max(0f, settings.mountedFireRange);
                IsDriver = isDriver;
                _loots = loots ?? new List<LootInfo>();
                _blockNpcDamage = eventSettings?.blockDamageNpcEventsIsNotPlayer ?? true;
                TargetableByNpcs = !(eventSettings?.blockAttackedToNpcEvents ?? true);
                CanDismount = false;
                EventEntities.AddCrew(this);
                BlackBox.Rebind(this);

                inventory.Strip();
                if (settings?.clothes != null)
                {
                    foreach (ItemInfo cloth in settings.clothes) cloth?.AddItemToContainer(inventory.containerWear);
                }
                if (!isDriver) GiveBeltWeapons();
                SendNetworkUpdate();
                Feed();
                InvokeRepeating(Feed, 10f, 10f);
            }
            public void Feed()
            {
                if (!HasBot || metabolism == null) return;
                if (metabolism.calories.value < metabolism.calories.max / 2f) metabolism.calories.value = metabolism.calories.max;
                if (metabolism.hydration.value < metabolism.hydration.max / 2f) metabolism.hydration.value = metabolism.hydration.max;
            }
            public void OnBoarded()
            {
                if (!HasBot) return;
                if (!IsInvoking(CheckMounted)) InvokeRepeating(CheckMounted, 2f, 2f);
            }
            private void GiveBeltWeapons()
            {
                if (Settings?.weapons == null) return;
                foreach (ItemInfo weapon in Settings.weapons) weapon?.AddItemToContainer(inventory.containerBelt);
            }
            public void GiveWeapons()
            {
                if (!HasBot) return;
                if (GetWeaponSlot() < 0)
                {
                    inventory.containerBelt.Clear();
                    GiveBeltWeapons();
                }
                Invoke(EquipFirstWeapon, 1f);
            }
            private void EquipFirstWeapon()
            {
                if (HasBot && !ExternalWeapon && (!isMounted || CanFightMounted)) EquipWeapon(GetWeaponSlot());
            }
            public int GetWeaponSlot()
            {
                ItemContainer belt = inventory?.containerBelt;
                if (belt == null) return -1;
                int melee = -1;
                for (int slot = 0; slot < 6; slot++)
                {
                    Item item = belt.GetSlot(slot);
                    if (item == null) continue;
                    BaseEntity held = item.GetHeldEntity();
                    if (held is BaseProjectile) return slot;
                    if (held is AttackEntity && melee < 0) melee = slot;
                }
                return melee;
            }
            #endregion

            #region Targets
            public bool CanAttack(BasePlayer target)
            {
                if (!HasBot || Settings == null) return false;
                if (IsDriver && isMounted && !IsParachute) return false;
                if (!VehicleCore.IsRealPlayer(target) || !target.IsAlive() || target.InSafeZone()) return false;
                if (!Settings.preventAttackToFirst) return true;
                return Run != null && Run.IsAttacker(target);
            }
            public BasePlayer FindTarget(float range, bool requireVisible)
            {
                BasePlayer best = null;
                float bestDistance = range;
                Vector3 from = eyes != null ? eyes.position : transform.position;
                foreach (BasePlayer player in BasePlayer.activePlayerList)
                {
                    if (player == null || player.IsSleeping() || !CanAttack(player)) continue;
                    float distance = Vector3.Distance(from, player.transform.position);
                    if (distance > bestDistance) continue;
                    if (requireVisible && !CanSeeTarget(player)) continue;
                    best = player;
                    bestDistance = distance;
                }
                return best;
            }
            private static int _visibleMask;
            public bool CanSeeTarget(BasePlayer target)
            {
                if (_visibleMask == 0) _visibleMask = LayerMask.GetMask("Player (Server)", "Terrain", "World", "Construction", "Tree", "Deployed", "Default");
                return this.CanSeePlayerEnemy(target, _visibleMask, 0.02f, Mathf.Max(MountedRange, FootRange) + 10f);
            }
            public void OnEngage(BasePlayer target)
            {
                if (target == null || Settings == null || !Settings.CanMovedToTarget) return;
                if (UnityEngine.Time.time < _nextEngage) return;
                _nextEngage = UnityEngine.Time.time + 1f;
                if (Run != null && Run.IsCurrent) Run.Owner.SetTarget(target);
            }
            public void OnAttackedByPlayer(BasePlayer attacker)
            {
                if (!VehicleCore.IsRealPlayer(attacker)) return;
                Run?.AddAttacker(attacker);
                _killTimerStart = UnityEngine.Time.time;
                if (Run != null && Run.IsCurrent) Run.Owner.SetTarget(attacker);
            }
            #endregion

            #region Mount / Foot
            private void CheckMounted()
            {
                if (!HasBot) return;
                if (isMounted) return;
                if (Run != null && Run.IsCurrent && Run.Owner.HasEvent)
                {
                    if (IsDriver) return;
                    if (Run.Owner.SetCompanionMounted(this)) return;
                }
                CancelInvoke(CheckMounted);
                GoOnFoot();
            }
            public void GoOnFoot()
            {
                if (_onFoot || !HasBot) return;
                _onFoot = true;
                CanDismount = true;
                ExternalWeapon = false;
                if (CoreEx.GroundPosition(transform.position).y < WaterSystem.OceanLevel - DeepWaterDepth)
                {
                    if (ShallowNear(CrewAnchor(), transform.position, out Vector3 shallow))
                    {
                        transform.position = shallow;
                        ServerPosition = shallow;
                    }
                    else
                    {
                        KillWithLoot();
                        return;
                    }
                }
                GiveWeapons();
                StartGroundCheck();
                try
                {
                    if (!IsInWater && Event != null && Event.CanUseNavMesh)
                    {
                        Vector3 ground = CoreEx.GroundPosition(transform.position);
                        if (Vector3.Distance(ground, transform.position) > 1.5f) HelperVehicles.MoveBot(this, ground);
                    }
                    else if (!IsInWater)
                    {
                        Vector3 ground = CoreEx.GroundPosition(transform.position);
                        transform.position = ground;
                        ServerPosition = ground;
                    }
                    if (navigator != null && navigator.IsPaused) navigator.Resume();
                }
                catch (Exception ex)
                {
                    Debug.LogError<CrewNpc>("GoOnFoot {0}: {1}", Debug.Id(this), ex.Message);
                }
                float timedKill = Settings?.timedKill ?? 0f;
                if (timedKill > 0f)
                {
                    _killTimerStart = UnityEngine.Time.time;
                    if (!IsInvoking(TimerDead)) InvokeRepeating(TimerDead, 1f, 1f);
                }
            }
            private void TimerDead()
            {
                if (!HasBot || Settings == null) return;
                if (UnityEngine.Time.time - _killTimerStart >= Settings.timedKill) KillWithLoot();
            }
            public bool HasTimedKill() => IsInvoking(TimerDead);
            public float GetTimerKill() => Settings == null ? 0f : Settings.timedKill - (UnityEngine.Time.time - _killTimerStart);

            private BaseEntity _leaveEntity;
            private Vector3 _leaveFrom;
            private float _leaveUntil;
            private float _dangerUntil;
            private BaseEntity _ownVehicle;
            public void LeaveVehicle(BaseEntity vehicle, float time)
            {
                if (!HasBot || vehicle == null) return;
                _leaveEntity = vehicle;
                _ownVehicle = vehicle;
                _leaveFrom = vehicle.transform.position;
                _leaveUntil = UnityEngine.Time.time + time;
                _dangerUntil = _leaveUntil;
            }
            public void StopLeave() => _leaveUntil = 0f;
            public bool WantsLeave => HasBot && UnityEngine.Time.time < _leaveUntil;
            public bool FarFromDanger => CoreEx.DistanceFlat(transform.position, LeaveFrom) >= CrewLeaveState.SafeDistance - 2f;
            public bool CrossesDanger(Vector3 from, Vector3 to)
            {
                if (UnityEngine.Time.time >= _dangerUntil) return false;
                Vector3 c = LeaveFrom;
                Vector2 a = new Vector2(from.x, from.z), b = new Vector2(to.x, to.z), p = new Vector2(c.x, c.z);
                Vector2 ab = b - a;
                float t = ab.sqrMagnitude > 0.01f ? Mathf.Clamp01(Vector2.Dot(p - a, ab) / ab.sqrMagnitude) : 0f;
                float closest = (a + ab * t - p).magnitude;
                return closest < CrewLeaveState.SafeDistance && closest < (a - p).magnitude - 1f;
            }
            public bool IsOwnVehicleHazard(Vector3 hazardCenter)
            {
                BaseEntity vehicle = _ownVehicle;
                if (vehicle == null || vehicle.IsDestroyed) return false;
                Bounds bounds = vehicle.bounds;
                bounds.Expand(4f);
                return bounds.Contains(vehicle.transform.InverseTransformPoint(hazardCenter));
            }

            private bool _disperse;
            private float _disperseRetryAt;
            private bool _disperseOnLanding;
            private float _disperseSpread;
            private List<CrewNpc> _disperseGroup;
            public bool HasFirstStagePoint { get; private set; }
            public Vector3 FirstStagePoint { get; private set; }
            public void SetFirstStagePoint(Vector3 point)
            {
                FirstStagePoint = point;
                HasFirstStagePoint = true;
            }
            public IEnumerable<CrewNpc> DisperseMates()
            {
                if (_disperseGroup == null) yield break;
                foreach (CrewNpc mate in _disperseGroup)
                    if (mate != null && mate != this && mate.HasBot) yield return mate;
            }
            public float DisperseHeading { get; set; }
            public float DisperseBase { get; private set; }
            public Vector3 DisperseCenter { get; private set; }
            public int DisperseStages { get; set; }
            public void Disperse(float heading, BaseEntity vehicle, Vector3 center, float spread = 0f, bool onLanding = false, List<CrewNpc> group = null)
            {
                if (!HasBot) return;
                _disperse = true;
                _disperseRetryAt = 0f;
                if (vehicle != null) _ownVehicle = vehicle;
                DisperseCenter = center;
                DisperseBase = DisperseHeading = Mathf.Repeat(heading, 360f);
                _disperseSpread = spread;
                _disperseOnLanding = onLanding;
                _disperseGroup = group;
                HasFirstStagePoint = false;
                DisperseStages = 0;
            }
            public void AimDisperseOnLanding()
            {
                if (!_disperseOnLanding || isMounted || !StandsOnSomething(transform.position)) return;
                _disperseOnLanding = false;
                Vector3 away = transform.position - DisperseCenter;
                away.y = 0f;
                if (away.magnitude < 30f) return;
                float spread = Mathf.Abs(_disperseSpread);
                Vector3 others = Vector3.zero;
                int count = 0;
                foreach (CrewNpc mate in DisperseMates())
                {
                    others += mate.transform.position;
                    count++;
                }
                if (count > 0)
                {
                    Vector3 offset = transform.position - others / count;
                    offset.y = 0f;
                    float side = Vector3.Cross(away.normalized, offset).y;
                    if (Mathf.Abs(side) > 1f) spread = side > 0f ? spread : -spread;
                    else if (_disperseSpread < 0f) spread = -spread;
                }
                else if (_disperseSpread < 0f) spread = -spread;
                float heading = Mathf.Atan2(away.x, away.z) * Mathf.Rad2Deg + spread;
                foreach (CrewNpc mate in DisperseMates())
                {
                    if (mate._disperseOnLanding || !mate.HasDisperse) continue;
                    float delta = Mathf.DeltaAngle(mate.DisperseBase, heading);
                    if (Mathf.Abs(delta) < 45f) heading = mate.DisperseBase + (delta >= 0f ? 45f : -45f);
                }
                DisperseBase = DisperseHeading = Mathf.Repeat(heading, 360f);
            }
            public bool HasDisperse => _disperse;
            public bool WantsDisperse => _disperse && HasBot && UnityEngine.Time.time >= _disperseRetryAt;
            public void DelayDisperse(float seconds) => _disperseRetryAt = UnityEngine.Time.time + seconds;
            public Vector3 DisperseDirection => Quaternion.Euler(0f, DisperseHeading, 0f) * Vector3.forward;
            public Vector3 LeaveFrom
            {
                get
                {
                    if (_leaveEntity != null && !_leaveEntity.IsDestroyed) _leaveFrom = _leaveEntity.transform.position;
                    return _leaveFrom;
                }
            }
            private void StartGroundCheck()
            {
                if (!IsInvoking(CheckGrounded)) InvokeRepeating(CheckGrounded, 2f, 2f);
            }
            private void CheckGrounded()
            {
                if (!HasBot) return;
                if (isMounted && !IsParachute) return;
                Vector3 position = transform.position;
                if (WaterLevel.Test(position, true, true, this) && position.y < WaterSystem.OceanLevel - DeepWaterDepth)
                {
                    KillWithLoot();
                    return;
                }
                if (InSafeZoneNow)
                {
                    if (AwaitsFootInSafeZone(position)) return;
                    if (HangsInSafeZone(position)) return;
                    if (WalksOutOfSafeZone(position)) return;
                    if (LeaveSafeZone(position)) return;
                    KillWithLoot();
                    return;
                }
                _zoneSince = -1f;
                if (!isMounted) CheckAirborne(position);
                if (!isMounted) CheckSwimming(position);
            }
            private bool AwaitsFootInSafeZone(Vector3 position)
            {
                IEventController owner = Event;
                if (owner == null || (_onFoot && !IsParachute) || (!owner.CrewWalksOutOfSafeZone && !owner.CrewLeavesSafeZone)) return false;
                _zoneSince = -1f;
                return true;
            }
            private bool HangsInSafeZone(Vector3 position)
            {
                IEventController owner = Event;
                if (owner == null || !owner.CrewWalksOutOfSafeZone || isMounted || !_onFoot || !Hangs(position, out _, out _)) return false;
                _zoneSince = -1f;
                CheckAirborne(position);
                return true;
            }
            private const float SwimRescueAfter = 6f, SwimRescueMax = 30f, SwimMoveStep = 2f;
            private static readonly float[] SwimShoreRings = { 6f, 12f, 20f, 30f, 40f };
            private float _swimSince = -1f;
            private Vector3 _swimMark;
            private void CheckSwimming(Vector3 position)
            {
                if (!_onFoot || !IsInWater || IsWading || IsParachute || (brain != null && brain.StateMachine != null && brain.StateMachine.CurrentStateName == "Battle"))
                {
                    _swimSince = -1f;
                    return;
                }
                float now = UnityEngine.Time.time;
                if (_swimSince < 0f)
                {
                    _swimSince = now;
                    _swimMark = position;
                    return;
                }
                bool moving = CoreEx.DistanceFlat(position, _swimMark) >= SwimMoveStep;
                _swimMark = position;
                float swum = now - _swimSince;
                if (swum < SwimRescueAfter || (moving && swum < SwimRescueMax)) return;
                _swimSince = -1f;
                if (!SwimShore(position, out Vector3 shore))
                {
                    _swimSince = now + 24f;
                    return;
                }
                BlackBox.NoteRescue(this, BlackBoxKind.SwimRescue, "crew moved to the shore", position, shore);
                if (Event != null && Event.CanUseNavMesh) HelperVehicles.MoveBot(this, shore);
                else
                {
                    transform.position = shore;
                    ServerPosition = shore;
                }
            }
            private bool SwimShore(Vector3 from, out Vector3 shore, float[] rings = null)
            {
                shore = Vector3.zero;
                bool useNav = Event != null && Event.CanUseNavMesh && navigator != null;
                bool avoid = WantsLeave;
                Vector3 danger = avoid ? LeaveFrom : Vector3.zero;
                Vector3 fallback = Vector3.zero;
                foreach (float radius in rings ?? SwimShoreRings)
                {
                    float best = float.MaxValue;
                    for (int i = 0; i < 16; i++)
                    {
                        Vector3 probe = from + Quaternion.Euler(0f, i * 22.5f, 0f) * Vector3.forward * radius;
                        Vector3 ground = CoreEx.GroundPosition(probe);
                        if (ground.y < WaterSystem.OceanLevel || CoreEx.DepthOver(ground) > 0.3f) continue;
                        if (useNav && !navigator.GetNearestNavmeshPosition(ground, out ground, 4f)) continue;
                        if (useNav && CoreEx.DepthOver(ground) > 0.3f) continue;
                        if (CoreEx.InSafeZone(ground)) continue;
                        if (fallback == Vector3.zero) fallback = ground;
                        if (avoid && CoreEx.DistanceFlat(ground, danger) < CrewLeaveState.SafeDistance) continue;
                        float distance = CoreEx.DistanceFlat(from, ground);
                        if (distance >= best) continue;
                        best = distance;
                        shore = ground;
                    }
                    if (best < float.MaxValue) return true;
                }
                shore = fallback;
                return fallback != Vector3.zero;
            }
            private bool LeaveSafeZone(Vector3 position)
            {
                IEventController owner = Event;
                if (owner == null || !owner.CrewLeavesSafeZone || !_onFoot || IsParachute
                    || (brain != null && brain.StateMachine != null && brain.StateMachine.CurrentStateName == "Battle")) return false;
                if (!SwimShore(position, out Vector3 point, SafeZoneExitRings)) return false;
                if (Event != null && Event.CanUseNavMesh) HelperVehicles.MoveBot(this, point);
                else
                {
                    transform.position = point;
                    ServerPosition = point;
                }
                return true;
            }
            private static readonly float[] SafeZoneExitRings = { 6f, 12f, 20f, 30f, 45f, 60f, 80f, 100f, 125f, 150f };
            public bool InSafeZoneNow => HasPlayerFlag(PlayerFlags.SafeZone) || this.IsSafeZone();
            private bool InBattle => brain != null && brain.StateMachine != null && brain.StateMachine.CurrentStateName == "Battle";
            private const float ZoneWalkMax = 120f, ZoneWalkStall = 20f, ZoneWalkStep = 3f, ZoneEdgeStall = 30f;
            private float _zoneSince = -1f, _zoneMarkAt, _zoneDepth, _zoneDepthAt;
            private Vector3 _zoneMark;
            public float ZoneExitRetryAt;
            public bool WantsZoneExit
            {
                get
                {
                    IEventController owner = Event;
                    return owner != null && owner.CrewWalksOutOfSafeZone && HasBot && _onFoot && !isMounted && !IsParachute
                           && UnityEngine.Time.time >= ZoneExitRetryAt && InSafeZoneNow;
                }
            }
            private bool WalksOutOfSafeZone(Vector3 position)
            {
                IEventController owner = Event;
                if (owner == null || !owner.CrewWalksOutOfSafeZone || !_onFoot || IsParachute || InBattle)
                {
                    _zoneSince = -1f;
                    return false;
                }
                float now = UnityEngine.Time.time;
                float depth = ZoneDepth(position);
                if (_zoneSince < 0f)
                {
                    _zoneSince = _zoneMarkAt = _zoneDepthAt = now;
                    _zoneMark = position;
                    _zoneDepth = depth;
                    return true;
                }
                if (CoreEx.DistanceFlat(position, _zoneMark) >= ZoneWalkStep)
                {
                    _zoneMark = position;
                    _zoneMarkAt = now;
                }
                if (depth <= _zoneDepth - ZoneWalkStep)
                {
                    _zoneDepth = depth;
                    _zoneDepthAt = now;
                }
                if (now - _zoneSince <= ZoneWalkMax && now - _zoneMarkAt <= ZoneWalkStall && now - _zoneDepthAt > ZoneEdgeStall
                    && WalksFullPathOut(out Vector3 exit))
                {
                    _zoneDepthAt = now;
                }
                if (now - _zoneSince <= ZoneWalkMax && now - _zoneMarkAt <= ZoneWalkStall && now - _zoneDepthAt <= ZoneEdgeStall) return true;
                _zoneSince = -1f;
                return false;
            }
            private bool WalksFullPathOut(out Vector3 exit)
            {
                exit = Vector3.zero;
                if (brain == null || brain.StateMachine == null || !(brain.StateMachine.GetCurrentState() is CrewZoneExitState state)) return false;
                exit = state.Exit;
                return exit != Vector3.zero && navigator != null && navigator.HasCompletePathTo(exit);
            }
            private static float ZoneDepth(Vector3 position)
            {
                return HelperSafeZones.TryGetExitPoint(position, out Vector3 edge, 0f, 0) ? CoreEx.DistanceFlat(position, edge) : 0f;
            }
            private static bool ShallowNear(Vector3 from, Vector3 near, out Vector3 spot)
            {
                spot = from;
                bool zoned = false;
                for (float radius = 2f; radius <= 30f; radius += radius < 10f ? 2f : 4f)
                {
                    if (radius > 10f && !zoned) return false;
                    float best = float.MaxValue;
                    for (int i = 0; i < 12; i++)
                    {
                        Vector3 ground = CoreEx.GroundPosition(from + Quaternion.Euler(0f, i * 30f, 0f) * Vector3.forward * radius);
                        if (ground.y < WaterSystem.OceanLevel - (DeepWaterDepth - 0.2f) || CoreEx.DepthOver(ground) >= DeepWaterDepth - 0.2f) continue;
                        if (CoreEx.InSafeZone(ground))
                        {
                            zoned = true;
                            continue;
                        }
                        float distance = CoreEx.DistanceFlat(ground, near);
                        if (distance >= best) continue;
                        best = distance;
                        spot = ground;
                    }
                    if (best < float.MaxValue) return true;
                }
                return false;
            }
            private Vector3 CrewAnchor()
            {
                BaseVehicle vehicle = Event?.Vehicle;
                Vector3 here = transform.position;
                if (vehicle == null || vehicle.IsDestroyed || CoreEx.DistanceFlat(vehicle.transform.position, here) > CrewAnchorRange) return here;
                return vehicle.transform.position;
            }
            private const float CrewAnchorRange = 8f;
            private bool StandsOnSomething(Vector3 position) => HelperVehicles.Parachutist.StandsOnSomething(this, position);
            private static int _bottomMask;
            public bool IsWading
            {
                get
                {
                    if (!HasBot || isMounted || !IsInWater) return false;
                    if (_bottomMask == 0) _bottomMask = LayerMask.GetMask("Terrain", "World", "Construction");
                    Vector3 position = transform.position;
                    if (!Physics.Raycast(position + Vector3.up * 0.5f, Vector3.down, out RaycastHit bottom, 2.5f, _bottomMask, QueryTriggerInteraction.Ignore))
                        return false;
                    WaterLevel.WaterInfo water = WaterLevel.GetWaterInfo(position, false, false);
                    return !water.isValid || water.surfaceLevel - bottom.point.y < DeepWaterDepth;
                }
            }
            private HelperVehicles.Parachutist _chute;
            private bool Hangs(Vector3 position, out Vector3 ground, out float height)
            {
                ground = position;
                height = 0f;
                return _chute != null && _chute.Hangs(position, out ground, out height);
            }
            public bool IsAirborne => HasBot && Hangs(transform.position, out _, out _);
            private void CheckAirborne(Vector3 position) => _chute?.CheckAirborne(position, () => JumpParachute(_chute.Skin));
            #endregion

            #region Parachute
            public void JumpParachute(ulong skin, List<Vector3> land = null, BaseVehicle from = null)
            {
                if (!HasBot || IsParachute) return;
                CanDismount = true;
                ExternalWeapon = false;
                _chute = HelperVehicles.Parachutist.Jump(this, skin, from, land, IsDriver, () => Event != null && Event.CanUseNavMesh);
                if (!IsParachute) return;
                GiveWeapons();
                StartGroundCheck();
            }
            public bool GroundBelowSupport(Vector3 at, out Vector3 point) => HelperVehicles.Parachutist.GroundBelowSupport(this, at, out point);
            #endregion

            #region Death & Loot
            public void KillWithLoot()
            {
                if (!HasBot) return;
                CanDismount = true;
                try
                {
                    if (isMounted) EnsureDismounted();
                    Die();
                }
                catch (Exception ex)
                {
                    Debug.LogError<CrewNpc>("KillWithLoot: {0}", ex.Message);
                }
            }
            public void KillImmediate()
            {
                CanDismount = true;
                if (IsDestroyed) return;
                try
                {
                    if (isMounted) EnsureDismounted();
                }
                catch (Exception ex)
                {
                    Debug.LogError<CrewNpc>("KillImmediate: {0}", ex.Message);
                }
                KillParachute();
                AdminKill();
            }
            private void KillParachute() => _chute?.KillParachute();
            protected override void ClearContainerIfDead(ItemContainer container) => container?.Clear();
            protected override void ApplyLoot(NPCPlayerCorpse corpse)
            {
                if (corpse == null || Settings == null) return;
                try
                {
                    if (!Settings.spawnBagOnDeath)
                    {
                        ItemContainer container = corpse.containers != null && corpse.containers.Length > 0 ? corpse.containers[0] : null;
                        SetLoot(container);
                        return;
                    }
                    List<Item> items = RollLoot();
                    if (items.Count > 0)
                    {
                        DroppedItemContainer backpack = GameManager.server.CreateEntity(VehicleCore.PrefabBackpack, corpse.transform.position, Quaternion.identity) as DroppedItemContainer;
                        if (backpack != null)
                        {
                            backpack.inventory = new ItemContainer();
                            backpack.inventory.ServerInitialize(null, Mathf.Max(1, items.Count));
                            backpack.inventory.GiveUID();
                            foreach (Item item in items)
                            {
                                if (!item.MoveToContainer(backpack.inventory)) item.Remove();
                            }
                            backpack.inventory.SetFlag(ItemContainer.Flag.NoItemInput, true);
                            backpack.enableSaving = false;
                            backpack.ResetRemovalTime();
                            backpack.Spawn();
                        }
                        else foreach (Item item in items) item.Remove();
                    }
                    Interface.Oxide.NextTick(() =>
                    {
                        if (corpse != null && !corpse.IsDestroyed) corpse.Kill();
                    });
                }
                catch (Exception ex)
                {
                    Debug.LogError<CrewNpc>("ApplyLoot: {0}", ex);
                }
            }
            public bool SetLoot(ItemContainer container)
            {
                if (container == null || _loots == null || _loots.Count == 0 || Settings?.Loots == null) return false;
                container.capacity = Mathf.Max(1, Settings.Loots.capacity);
                int num = 0;
                foreach (LootInfo loot in _loots)
                {
                    if (num >= Settings.Loots.capacity) break;
                    if (loot != null && loot.AddLootToContainerFromChance(container)) num++;
                }
                return !container.IsEmpty();
            }
            private List<Item> RollLoot()
            {
                List<Item> items = new List<Item>();
                if (_loots == null || Settings?.Loots == null) return items;
                foreach (LootInfo loot in _loots)
                {
                    if (items.Count >= Settings.Loots.capacity) break;
                    if (loot != null && loot.TryGetChanceItem(out Item item)) items.Add(item);
                }
                return items;
            }
            public override void OnDied(HitInfo info)
            {
                CanDismount = true;
                try
                {
                    Event?.OnCrewDied(this);
                }
                catch (Exception ex)
                {
                    Debug.LogError<CrewNpc>("OnDied: {0}", ex.Message);
                }
                base.OnDied(info);
            }
            public override void DestroyShared()
            {
                EventEntities.RemoveCrew(this);
                CancelInvoke(CheckMounted);
                CancelInvoke(Feed);
                CancelInvoke(TimerDead);
                CancelInvoke(CheckGrounded);
                CancelInvoke(EquipFirstWeapon);
                KillParachute();
                base.DestroyShared();
            }
            #endregion
        }

