        public class CrewFSM : FSM
        {
            private CrewRideState _ride;
            private CrewBattleState _battle;
            private CrewZoneExitState _zoneExit;
            private CrewLeaveState _leave;
            private CrewDisperseState _disperse;

            protected override void Start()
            {
                _ride = BaseStatePlayerNpc.GetPoolState<CrewRideState>(this);
                _battle = BaseStatePlayerNpc.GetPoolState<CrewBattleState>(this);
                _zoneExit = BaseStatePlayerNpc.GetPoolState<CrewZoneExitState>(this);
                _leave = BaseStatePlayerNpc.GetPoolState<CrewLeaveState>(this);
                _disperse = BaseStatePlayerNpc.GetPoolState<CrewDisperseState>(this);
            }
            protected override void InitFSM(BaseStatePlayerNpc idleState)
            {
                idleState.AddTickTransfer(_ride);
                idleState.AddTickTransfer(_battle);
                idleState.AddTickTransfer(_zoneExit);
                idleState.AddTickTransfer(_leave);
                idleState.AddTickTransfer(_disperse);

                _ride.AddCompletedTransfer(idleState);
                _ride.AddFailureTransfer(idleState);

                _battle.AddTickTransfer(_ride);
                _battle.AddCompletedTransfer(idleState);
                _battle.AddFailureTransfer(idleState);

                _zoneExit.AddTickTransfer(_ride);
                _zoneExit.AddTickTransfer(_battle);
                _zoneExit.AddCompletedTransfer(idleState);
                _zoneExit.AddFailureTransfer(idleState);

                _leave.AddTickTransfer(_ride);
                _leave.AddTickTransfer(_battle);
                _leave.AddTickTransfer(_zoneExit);
                _leave.AddCompletedTransfer(idleState);
                _leave.AddFailureTransfer(idleState);

                _disperse.AddTickTransfer(_ride);
                _disperse.AddTickTransfer(_battle);
                _disperse.AddTickTransfer(_zoneExit);
                _disperse.AddTickTransfer(_leave);
                _disperse.AddCompletedTransfer(idleState);
                _disperse.AddFailureTransfer(idleState);
            }
            protected override void OnDestroy()
            {
                BaseStatePlayerNpc.SetPoolState(ref _ride);
                BaseStatePlayerNpc.SetPoolState(ref _battle);
                BaseStatePlayerNpc.SetPoolState(ref _zoneExit);
                BaseStatePlayerNpc.SetPoolState(ref _leave);
                BaseStatePlayerNpc.SetPoolState(ref _disperse);
            }
            public void OnAttackEnemy(BaseCombatEntity enemy)
            {
                if (_battle != null && _battle.IsValid && Owner.IsValid() && !Owner.isMounted && enemy is BasePlayer player && _battle.CanTargetBattleEnemy(player))
                    ((FSM.IAttackState)_battle).OnAttack(enemy);
            }
        }

