        public class CrewZoneExitState : FSM.RouterState
        {
            private const float ExitMargin = 12f, ExitSnap = 8f, RetryDelay = 5f;
            private const int Faces = 4;
            private int _variant;
            private Vector3 _exit;

            public override string Name => "Leave safe zone";
            public Vector3 Exit => _exit;
            protected override BaseEntity GetChaseEnemy => null;
            protected override float MinDistanceMovedEnemyForAddPoint => 0f;
            protected override float RadiusSphere => 3f;
            public override bool CanPassHazardTrigger(Vector3 hazardCenter) => Crew != null && Crew.IsOwnVehicleHazard(hazardCenter);
            private CrewNpc Crew => Owner as CrewNpc;

            protected override void OnDestroy()
            {
                _variant = 0;
                _exit = Vector3.zero;
                base.OnDestroy();
            }
            protected override bool CanEnterState()
            {
                CrewNpc crew = Crew;
                return crew != null && crew.WantsZoneExit && Navigator != null && !crew.IsAirborne;
            }
            protected override void EnterState()
            {
                base.EnterState();
                _variant = 0;
                _exit = Vector3.zero;
                Pick(Crew);
            }
            protected override ResponseFromUpdateState UpdateState(float delta)
            {
                base.UpdateState(delta);
                CrewNpc crew = Crew;
                if (crew == null || !crew.HasBot) return ResponseFromUpdateState.Failure;
                if (!crew.InSafeZoneNow)
                {
                    Stop();
                    return ResponseFromUpdateState.Completed;
                }
                if (_exit != Vector3.zero && modeRouter == FSM.IRouterState.ModeRouter.Moved && Navigator.Moving && !IsStuck) return ResponseFromUpdateState.NONE;
                ResetStuck();
                Stop();
                _variant++;
                if (Pick(crew)) return ResponseFromUpdateState.NONE;
                crew.ZoneExitRetryAt = UnityEngine.Time.time + RetryDelay;
                return ResponseFromUpdateState.Failure;
            }
            private bool Pick(CrewNpc crew)
            {
                if (crew == null) return false;
                Vector3 position = crew.transform.position;
                for (; _variant < Faces * 2; _variant++)
                {
                    if (!HelperSafeZones.TryGetExitPoint(position, out Vector3 exit, ExitMargin, _variant % Faces))
                    {
                        return false;
                    }
                    exit.y = TerrainMeta.HeightMap.GetHeight(exit);
                    if (!Navigator.GetNearestNavmeshPosition(exit, out Vector3 point, ExitSnap) || HelperSafeZones.IsPointInside(point, 2f, false)) continue;
                    if (_variant < Faces && crew.CrossesDanger(position, point)) continue;
                    SetTarget(point, NavigationSpeed.Fast);
                    if (modeRouter != FSM.IRouterState.ModeRouter.Moved || IsStuck)
                    {
                        ResetStuck();
                        continue;
                    }
                    _exit = point;
                    return true;
                }
                return false;
            }
        }

        public class CrewLeaveState : FSM.RouterState
        {
            public const float SafeDistance = 20f;
            private const float MaxTime = 15f;
            private const int LayerChecksPerPick = 4;
            private static readonly float[] Angles = { 0f, 45f, -45f, 90f, -90f, 135f, -135f };
            private Vector3 _point;

            public override string Name => "Leave vehicle";
            protected override BaseEntity GetChaseEnemy => null;
            protected override float MinDistanceMovedEnemyForAddPoint => 0f;
            protected override float RadiusSphere => 2f;
            public override bool CanPassHazardTrigger(Vector3 hazardCenter) => Crew != null && Crew.IsOwnVehicleHazard(hazardCenter);
            public override bool CanSwimAhead(Vector3 entryPoint, float depth, float distance)
            {
                if (CrewDisperseState.CanWade(depth, distance)) return true;
                CrewNpc crew = Crew;
                if (crew == null || _staleSkips >= MaxStaleSkips || !(Navigator is NavigatorNpc nav)) return false;
                Vector3 from = crew.transform.position;
                if (!nav.ProbeWorldPath(from, _point, 2f, _legPath, out _, out _, out _) || _legPath.Count == 0)
                {
                    _legPath.Clear();
                    _legPath.Add(_point);
                }
                _legPath.Insert(0, from);
                float off = CrewDisperseState.OffPath(_legPath, entryPoint);
                if (off <= CrewDisperseState.StaleOffset) return false;
                _staleSkips++;
                return true;
            }
            private static readonly List<Vector3> _legPath = new List<Vector3>();
            private int _staleSkips;
            private const int MaxStaleSkips = 3;
            private CrewNpc Crew => Owner as CrewNpc;

            protected override void OnDestroy()
            {
                _point = Vector3.zero;
                base.OnDestroy();
            }
            protected override bool CanEnterState()
            {
                CrewNpc crew = Crew;
                if (crew == null || !crew.WantsLeave || crew.isMounted || (crew.IsInWater && !crew.IsWading) || Navigator == null) return false;
                if (CoreEx.DistanceFlat(crew.transform.position, crew.LeaveFrom) >= SafeDistance - 2f || crew.IsAirborne) return false;
                if (PickPoint(crew, out _point, out bool cutOff)) return true;
                if (cutOff) Rescue(crew, _point);
                crew.StopLeave();
                return false;
            }
            protected override void EnterState()
            {
                base.EnterState();
                _droppedSince = -1f;
                _staleSkips = 0;
                SetTarget(_point, NavigationSpeed.Fast);
            }
            private float _droppedSince;
            protected override ResponseFromUpdateState UpdateState(float delta)
            {
                base.UpdateState(delta);
                CrewNpc crew = Crew;
                if (crew == null || !crew.HasBot) return ResponseFromUpdateState.Failure;
                if (modeRouter == FSM.IRouterState.ModeRouter.Moved && !Navigator.Moving)
                {
                    if (_droppedSince < 0f) _droppedSince = TimerState;
                    else if (TimerState - _droppedSince >= 1f)
                    {
                        Stop();
                        return ResponseFromUpdateState.Failure;
                    }
                }
                else _droppedSince = -1f;
                if (IsStuck || modeRouter == FSM.IRouterState.ModeRouter.Idle || TimerState > MaxTime)
                {
                    ResetStuck();
                    Stop();
                    if (!crew.FarFromDanger && PickPoint(crew, out Vector3 point, out _, false)) Rescue(crew, point);
                    crew.StopLeave();
                    return ResponseFromUpdateState.Failure;
                }
                if (modeRouter == FSM.IRouterState.ModeRouter.Finish || CoreEx.DistanceFlat(crew.transform.position, crew.LeaveFrom) >= SafeDistance)
                {
                    Stop();
                    crew.StopLeave();
                    return ResponseFromUpdateState.Completed;
                }
                return ResponseFromUpdateState.NONE;
            }
            private bool PickPoint(CrewNpc crew, out Vector3 point, out bool cutOff, bool needPath = true)
            {
                cutOff = false;
                int layerChecks = needPath && Navigator.IsOnLayerSurface(crew.transform.position) ? LayerChecksPerPick : 0;
                Vector3 fallback = Vector3.zero;
                Vector3 from = crew.LeaveFrom;
                Vector3 away = crew.transform.position - from;
                away.y = 0f;
                if (away.sqrMagnitude < 0.25f) away = crew.transform.forward;
                away.y = 0f;
                away = away.sqrMagnitude > 0.001f ? away.normalized : Vector3.forward;
                if (crew.HasDisperse)
                {
                    Vector3 course = crew.DisperseDirection;
                    if (Vector3.Dot(course, away) >= 0f) away = course;
                    else
                    {
                        Vector3 side = Vector3.Cross(Vector3.up, away);
                        away = Vector3.Dot(side, course) >= 0f ? side : -side;
                    }
                }
                for (int ring = 0; ring < Rings.Length; ring++)
                {
                    foreach (float angle in Angles)
                    {
                        Vector3 probe = from + Quaternion.Euler(0f, angle, 0f) * away * Rings[ring];
                        probe.y = TerrainMeta.HeightMap.GetHeight(probe);
                        if (!Navigator.GetNearestNavmeshPosition(probe, out point, RingSnap[ring])) continue;
                        if (CoreEx.DistanceFlat(point, from) < SafeDistance - 2f || IsPointTooDeep(point, 0.5f) || CoreEx.InSafeZone(point)) continue;
                        if (!needPath) return true;
                        if (layerChecks > 0)
                        {
                            layerChecks--;
                            if (Navigator.HasRouteTo(point)) return true;
                        }
                        else if (Navigator.HasCompletePathTo(point, false)) return true;
                        if (!cutOff)
                        {
                            cutOff = true;
                            fallback = point;
                        }
                    }
                }
                point = fallback;
                return false;
            }
            private static readonly float[] Rings = { SafeDistance + 2f, SafeDistance + 10f, SafeDistance + 20f };
            private static readonly float[] RingSnap = { 4f, 6f, 8f };
            private static void Rescue(CrewNpc crew, Vector3 point)
            {
                HelperVehicles.MoveBot(crew, point);
            }
        }

        public class CrewDisperseState : FSM.RouterState
        {
            private const float StageMin = 150f, StageMax = 250f;
            private const float MaxSlope = 35f;
            private const float MonumentMargin = 20f;
            private const float MonumentPassMargin = 10f;
            private const float SafeZoneMargin = 20f;
            private const float MapMargin = 100f;
            private const float NavSnap = 8f;
            private const float ReturnGuardAngle = 60f, ReturnGuardRange = 500f;
            public const float WadeDepth = 1.5f, WadeDistance = 5f;
            public static bool CanWade(float depth, float distance) => depth < WadeDepth && distance <= WadeDistance;
            private const float StageTimeout = 240f;
            private const int MaxFailures = 4;
            private const float RetryDelay = 30f;
            private static readonly float[] Angles = { 0f, 25f, -25f, 50f, -50f, 80f, -80f, 115f, -115f, 150f, -150f, 180f };
            private static readonly float[] NearAngles = { 0f, 25f, -25f, 50f, -50f };
            private static readonly float[] WideAngles = { 80f, -80f, 115f, -115f, 150f, -150f, 180f };
            private const int Passes = 8, FinePass = 6, FinePerTick = 8;
            private const float ShortStage = 50f;
            private static readonly float[] FineStages = { 110f, 140f };
            private static readonly float[] FineAngles = FineCircle();
            private static float[] FineCircle()
            {
                float[] angles = new float[36];
                for (int i = 0; i < angles.Length; i++) angles[i] = i * 10f;
                return angles;
            }
            private static float[] PassAngles(int pass) => pass >= FinePass ? FineAngles : pass >= 4 ? Angles : pass < 2 ? NearAngles : WideAngles;
            private static float PassLength(int pass, float length) => pass >= FinePass ? FineStages[pass - FinePass]
                : pass >= 5 ? ShortStage : pass % 2 == 1 || pass >= 4 ? length * 0.5f : length;
            private bool _pathChecked;

            private const float StageReach = 15f;

            private static readonly float[] ShoreRings = { 6f, 12f, 20f, 30f, 40f };
            private const float WadeTimeout = 30f;
            private const float EscapeWait = 40f;
            private const int LayerChecksPerPick = 4;
            private const float PathWadeDepth = 1f, PathWaterStep = 2f;
            private static readonly List<Vector3> _pathCorners = new List<Vector3>();
            private static int _groundMask;

            private int _try;
            private int _pass;
            private bool _moving;
            private Vector3 _point;
            private float _length;
            private float _nextPick;
            private float _stageAt;
            private int _failures;
            private bool _snapped;
            private bool _wading;
            private Vector3 _shore;
            private float _escapeUntil;
            private bool _escaped;
            private bool _onLayer;
            private int _layerChecks;
            private bool _lowered;

            public override string Name => "Disperse";
            protected override BaseEntity GetChaseEnemy => null;
            protected override float MinDistanceMovedEnemyForAddPoint => 0f;
            protected override float RadiusSphere => 4f;
            public override bool CanPassHazardTrigger(Vector3 hazardCenter) => Crew != null && Crew.IsOwnVehicleHazard(hazardCenter);
            private CrewNpc Crew => Owner as CrewNpc;

            protected override void OnDestroy()
            {
                _moving = false;
                _failures = 0;
                _refusedWater.Clear();
                base.OnDestroy();
            }
            protected override bool CanEnterState()
            {
                CrewNpc crew = Crew;
                return crew != null && crew.WantsDisperse && crew.IsOnFoot && !crew.isMounted && (!crew.IsInWater || crew.IsWading)
                       && (!crew.WantsLeave || crew.FarFromDanger) && Navigator != null && !crew.IsAirborne;
            }
            protected override void EnterState()
            {
                base.EnterState();
                ResetStuck();
                _moving = false;
                _failures = 0;
                _snapped = false;
                _escaped = false;
                _lowered = false;
                _escapeUntil = 0f;
                _nextPick = 0f;
                _droppedSince = -1f;
                CrewNpc crew = Crew;
                _wading = crew != null && crew.IsInWater;
                _shore = Vector3.zero;
                crew?.AimDisperseOnLanding();
                NewPick();
            }
            protected override ResponseFromUpdateState UpdateState(float delta)
            {
                base.UpdateState(delta);
                CrewNpc crew = Crew;
                if (crew == null || !crew.HasBot) return ResponseFromUpdateState.Failure;
                float now = UnityEngine.Time.time;
                if (_escapeUntil > 0f)
                {
                    if (now < _escapeUntil && Navigator.Moving && !IsStuck) return ResponseFromUpdateState.NONE;
                    _escapeUntil = 0f;
                    ResetStuck();
                    _nextPick = now + 1f;
                    NewPick();
                    return ResponseFromUpdateState.NONE;
                }
                if (_moving && NavigatorDropped(now))
                {
                    ResetStuck();
                    Stop();
                    _moving = false;
                    if (++_failures >= MaxFailures) return GiveUp(crew, "navigator path keeps resetting");
                    _wading = crew.IsInWater;
                    _shore = Vector3.zero;
                    _nextPick = now + 1f;
                    NewPick();
                    return ResponseFromUpdateState.NONE;
                }
                if (_wading) return UpdateWading(crew, now);
                if (_moving)
                {
                    bool ended = IsStuck || modeRouter != FSM.IRouterState.ModeRouter.Moved;
                    if (modeRouter == FSM.IRouterState.ModeRouter.Finish || (ended && CoreEx.DistanceFlat(crew.transform.position, _point) < StageReach))
                    {
                        ResetStuck();
                        Stop();
                        _moving = false;
                        _failures = 0;
                        crew.DisperseStages++;
                        crew.DisperseHeading = Mathf.Repeat(crew.DisperseBase + UnityEngine.Random.Range(-20f, 20f), 360f);
                        _nextPick = now + UnityEngine.Random.Range(1f, 4f);
                        NewPick();
                        return ResponseFromUpdateState.NONE;
                    }
                    if (ended || now - _stageAt > StageTimeout)
                    {
                        bool water = IsStuck && StuckReasonLatched == StuckReason.DeepWaterAhead;
                        ResetStuck();
                        Stop();
                        _moving = false;
                        if (++_failures >= MaxFailures) return GiveUp(crew, "stages cannot be completed");
                        if (water && AwayFromWater(crew.transform.position, out float away)) crew.DisperseHeading = away;
                        else crew.DisperseHeading = Mathf.Repeat(crew.DisperseHeading + (UnityEngine.Random.value < 0.5f ? -1f : 1f) * UnityEngine.Random.Range(60f, 100f), 360f);
                        _nextPick = now + 3f;
                        NewPick();
                    }
                    return ResponseFromUpdateState.NONE;
                }
                if (now < _nextPick) return ResponseFromUpdateState.NONE;
                for (int budget = _pass >= FinePass ? FinePerTick : 1; ; )
                {
                    float[] angles = PassAngles(_pass);
                    _pathChecked = false;
                    if (TryCandidate(crew, angles[_try], PassLength(_pass, _length), _pass < 4, _pass < 5, out Vector3 point))
                    {
                        Vector3 to = point - crew.transform.position;
                        to.y = 0f;
                        if (to.sqrMagnitude > 1f) crew.DisperseHeading = Mathf.Repeat(Mathf.Atan2(to.x, to.z) * Mathf.Rad2Deg, 360f);
                        if (crew.DisperseStages == 0) crew.SetFirstStagePoint(point);
                        _point = point;
                        _staleSkips = 0;
                        SetTarget(point, crew.DisperseStages == 0 ? NavigationSpeed.Fast : NavigationSpeed.Normal);
                        _moving = modeRouter == FSM.IRouterState.ModeRouter.Moved;
                        _stageAt = now;
                        if (!_moving)
                        {
                            if (++_failures >= MaxFailures) return GiveUp(crew, "navigator rejects targets");
                            _nextPick = now + 3f;
                            NewPick();
                        }
                        return ResponseFromUpdateState.NONE;
                    }
                    if (++_try >= angles.Length)
                    {
                        if (++_pass >= Passes) break;
                        _try = 0;
                    }
                    if (--budget <= 0 || _pathChecked || _pass < FinePass) return ResponseFromUpdateState.NONE;
                }
                if (!_snapped && SnapToNavMesh(crew))
                {
                    _snapped = true;
                    NewPick();
                    return ResponseFromUpdateState.NONE;
                }
                if (!_lowered && crew.GroundBelowSupport(crew.transform.position, out Vector3 lower))
                {
                    _lowered = true;
                    HelperVehicles.MoveBot(crew, lower);
                    NewPick();
                    return ResponseFromUpdateState.NONE;
                }
                if (!_escaped && Navigator.TryEscapeTrap())
                {
                    _escaped = true;
                    _escapeUntil = now + EscapeWait;
                    return ResponseFromUpdateState.NONE;
                }
                return GiveUp(crew, $"no point in any direction ({RejectSummary()})");
            }
            private ResponseFromUpdateState UpdateWading(CrewNpc crew, float now)
            {
                if (_moving)
                {
                    bool arrived = modeRouter == FSM.IRouterState.ModeRouter.Finish;
                    if (crew.IsInWater && !arrived && !IsStuck && modeRouter == FSM.IRouterState.ModeRouter.Moved && now - _stageAt < WadeTimeout)
                        return ResponseFromUpdateState.NONE;
                    ResetStuck();
                    Stop();
                    _moving = false;
                    if (crew.IsInWater && !arrived) return WadeRescue(crew, now, "did not reach the shore");
                    return EndWading(now);
                }
                if (!crew.IsInWater) return EndWading(now);
                if (now < _nextPick) return ResponseFromUpdateState.NONE;
                if (!PickShore(crew, out _shore))
                {
                    _wading = false;
                    if (!_escaped && Navigator.TryEscapeTrap())
                    {
                        _escaped = true;
                        _escapeUntil = now + EscapeWait;
                        return ResponseFromUpdateState.NONE;
                    }
                    return GiveUp(crew, "in water, no shore nearby");
                }
                _stagePath.Clear();
                SetTarget(_shore, NavigationSpeed.Fast);
                _moving = modeRouter == FSM.IRouterState.ModeRouter.Moved;
                _stageAt = now;
                return _moving ? ResponseFromUpdateState.NONE : WadeRescue(crew, now, "navigator rejected the target");
            }
            private ResponseFromUpdateState EndWading(float now)
            {
                _wading = false;
                _nextPick = now + 1f;
                NewPick();
                return ResponseFromUpdateState.NONE;
            }
            private ResponseFromUpdateState WadeRescue(CrewNpc crew, float now, string why)
            {
                if (_shore != Vector3.zero)
                {
                    HelperVehicles.MoveBot(crew, _shore);
                }
                return EndWading(now);
            }
            private bool PickShore(CrewNpc crew, out Vector3 shore)
            {
                Vector3 from = crew.transform.position;
                shore = Vector3.zero;
                float best = float.MaxValue;
                foreach (float radius in ShoreRings)
                {
                    for (int i = 0; i < 16; i++)
                    {
                        Vector3 probe = from + Quaternion.Euler(0f, i * 22.5f, 0f) * Vector3.forward * radius;
                        probe.y = TerrainMeta.HeightMap.GetHeight(probe);
                        if (!Navigator.GetNearestNavmeshPosition(probe, out Vector3 point, 4f)) continue;
                        if (IsPointTooDeep(point, 0.3f) || crew.CrossesDanger(from, point) || CoreEx.InSafeZone(point)) continue;
                        float distance = CoreEx.DistanceFlat(from, point);
                        if (distance >= best) continue;
                        best = distance;
                        shore = point;
                    }
                    if (best < float.MaxValue) return true;
                }
                return false;
            }
            private static bool AwayFromWater(Vector3 from, out float heading)
            {
                heading = 0f;
                Vector3 wet = Vector3.zero;
                for (int i = 0; i < 16; i++)
                {
                    Vector3 dir = Quaternion.Euler(0f, i * 22.5f, 0f) * Vector3.forward;
                    if (WetAt(from + dir * 10f) || WetAt(from + dir * 25f)) wet += dir;
                }
                if (wet.sqrMagnitude < 0.01f) return false;
                heading = Mathf.Repeat(Mathf.Atan2(-wet.x, -wet.z) * Mathf.Rad2Deg, 360f);
                return true;
            }
            private static bool WetAt(Vector3 p) => WaterDepthAt(p) >= PathWadeDepth;
            private static float WaterDepthAt(Vector3 p)
            {
                if (_groundMask == 0) _groundMask = LayerMask.GetMask("Terrain", "World", "Default", "Construction");
                p.y = TerrainMeta.HeightMap.GetHeight(p);
                if (Physics.Raycast(p + Vector3.up * 100f, Vector3.down, out RaycastHit hit, 100f, _groundMask, QueryTriggerInteraction.Ignore)) p = hit.point;
                WaterLevel.WaterInfo water = WaterLevel.GetWaterInfo(p, false, false);
                return water.isValid ? Mathf.Max(0f, water.surfaceLevel - p.y) : 0f;
            }
            private readonly List<Vector3> _refusedWater = new List<Vector3>();
            private const float RefusedWaterRadius = 3f;
            private const int RefusedWaterMemory = 8;
            private readonly List<Vector3> _stagePath = new List<Vector3>();
            private int _staleSkips;
            private const int MaxStaleSkips = 3;
            public const float StaleOffset = 3f;
            public static float OffPath(List<Vector3> path, Vector3 p)
            {
                if (path.Count == 1) return CoreEx.DistanceFlat(p, path[0]);
                float best = float.MaxValue;
                for (int i = 0; i + 1 < path.Count; i++) best = Mathf.Min(best, CoreEx.DistanceFlatToSegment(p, path[i], path[i + 1]));
                return best;
            }
            public override bool CanSwimAhead(Vector3 entryPoint, float depth, float distance)
            {
                if (CanWade(depth, distance)) return true;
                if (_moving && !_wading && _staleSkips < MaxStaleSkips && _stagePath.Count >= 2)
                {
                    float off = OffPath(_stagePath, entryPoint);
                    if (off > StaleOffset)
                    {
                        _staleSkips++;
                        return true;
                    }
                }
                if (_refusedWater.Count >= RefusedWaterMemory) _refusedWater.RemoveAt(0);
                _refusedWater.Add(entryPoint);
                return false;
            }
            private bool NearRefusedWater(Vector3 p)
            {
                foreach (Vector3 refused in _refusedWater)
                    if (CoreEx.DistanceFlat(refused, p) < RefusedWaterRadius) return true;
                return false;
            }
            private bool PathWet(CrewNpc crew, Vector3 point)
            {
                Vector3 from = crew.transform.position;
                _pathCorners.Clear();
                if (!(Navigator is NavigatorNpc nav) || !nav.ProbeWorldPath(from, point, 2f, _pathCorners, out _, out _, out _) || _pathCorners.Count == 0)
                {
                    _pathCorners.Clear();
                    _pathCorners.Add(point);
                }
                float walked = 0f;
                Vector3 previous = from;
                foreach (Vector3 corner in _pathCorners)
                {
                    float length = CoreEx.DistanceFlat(previous, corner);
                    for (float d = PathWaterStep; d <= length; d += PathWaterStep)
                    {
                        Vector3 q = Vector3.Lerp(previous, corner, d / length);
                        if (WaterDepthAt(q) >= (walked + d > WadeDistance ? PathWadeDepth : WadeDepth) || NearRefusedWater(q)) return true;
                    }
                    walked += length;
                    previous = corner;
                }
                return false;
            }
            private float _droppedSince = -1f;
            private bool NavigatorDropped(float now)
            {
                if (modeRouter != FSM.IRouterState.ModeRouter.Moved || Navigator.Moving)
                {
                    _droppedSince = -1f;
                    return false;
                }
                if (_droppedSince < 0f) _droppedSince = now;
                if (now - _droppedSince < DropWait) return false;
                _droppedSince = -1f;
                return true;
            }
            private const float DropWait = 1f;
            private ResponseFromUpdateState GiveUp(CrewNpc crew, string why)
            {
                crew.DelayDisperse(RetryDelay);
                return ResponseFromUpdateState.Failure;
            }
            private void NewPick()
            {
                _try = 0;
                _pass = 0;
                System.Array.Clear(_rejects, 0, _rejects.Length);
                _length = UnityEngine.Random.Range(StageMin, StageMax);
                _layerChecks = LayerChecksPerPick;
                _onLayer = Owner != null && Navigator != null && Navigator.IsOnLayerSurface(Owner.transform.position);
            }
            private bool SnapToNavMesh(CrewNpc crew)
            {
                Vector3 position = crew.transform.position;
                if (Navigator.GetNearestNavmeshPosition(position, out Vector3 near, 1f) && Mathf.Abs(near.y - position.y) < 1f) return false;
                if (!Navigator.GetNearestNavmeshPosition(position, out near, NavSnap) || (near - position).sqrMagnitude < 0.25f) return false;
                HelperVehicles.MoveBot(crew, near);
                return true;
            }
            private bool TryCandidate(CrewNpc crew, float angle, float length, bool strict, bool margin, out Vector3 point)
            {
                point = Vector3.zero;
                Vector3 from = crew.transform.position;
                Vector3 dir = Quaternion.Euler(0f, crew.DisperseHeading + angle, 0f) * Vector3.forward;
                if (strict && TowardCenter(crew, from, dir)) return Reject(0);
                Vector3 probe = from + dir * length;
                Vector3 min = TerrainMeta.Position, size = TerrainMeta.Size;
                float edge = margin ? MapMargin : 0f;
                if (probe.x < min.x + edge || probe.x > min.x + size.x - edge
                    || probe.z < min.z + edge || probe.z > min.z + size.z - edge) return Reject(1);
                probe.y = TerrainMeta.HeightMap.GetHeight(probe);
                if (probe.y < WaterSystem.OceanLevel + 0.5f || TerrainMeta.HeightMap.GetSlope(probe) > MaxSlope) return Reject(2);
                if (!Navigator.GetNearestNavmeshPosition(probe, out point, NavSnap)) return Reject(3);
                if (IsPointTooDeep(point, 0.3f)) return Reject(2);
                if (NearMonument(from, point)) return Reject(4);
                if (crew.CrossesDanger(from, point)) return Reject(5);
                if (CrossesSafeZone(from, point)) return Reject(6);
                if (strict && (CrossesMonument(from, point) || (crew.DisperseStages == 0 && CrowdsMate(crew, point)))) return Reject(4);
                _pathChecked = true;
                if (Navigator.HasCompleteDryPathTo(point))
                {
                    if (PathWet(crew, point)) return Reject(7);
                    if (CrossesSafeZone(from, _pathCorners)) return Reject(6);
                    _stagePath.Clear();
                    _stagePath.Add(from);
                    _stagePath.AddRange(_pathCorners);
                    return true;
                }
                if (!_onLayer || _layerChecks <= 0) return Reject(3);
                _layerChecks--;
                _stagePath.Clear();
                return Navigator.HasRouteTo(point) || Reject(3);
            }
            private readonly int[] _rejects = new int[8];
            private static readonly string[] RejectNames = { "backward", "map edge", "water/cliff", "no path", "monument", "past C4", "safe zone", "path through water" };
            private bool Reject(int reason)
            {
                _rejects[reason]++;
                return false;
            }
            private string RejectSummary()
            {
                System.Text.StringBuilder sb = new System.Text.StringBuilder();
                for (int i = 0; i < _rejects.Length; i++)
                {
                    if (_rejects[i] == 0) continue;
                    if (sb.Length > 0) sb.Append(", ");
                    sb.Append(RejectNames[i]).Append(' ').Append(_rejects[i]);
                }
                return sb.ToString();
            }
            private static bool CrowdsMate(CrewNpc crew, Vector3 point)
            {
                Vector3 center = crew.DisperseCenter;
                Vector3 own = point - center;
                own.y = 0f;
                if (own.sqrMagnitude < 100f) return false;
                int count = 1;
                foreach (CrewNpc mate in crew.DisperseMates()) count++;
                float separation = Mathf.Clamp(150f / count, 25f, 60f);
                foreach (CrewNpc mate in crew.DisperseMates())
                {
                    if (!mate.HasFirstStagePoint) continue;
                    Vector3 other = mate.FirstStagePoint - center;
                    other.y = 0f;
                    if (other.sqrMagnitude < 100f) continue;
                    if (Vector3.Angle(own, other) < separation) return true;
                }
                return false;
            }
            private static bool TowardCenter(CrewNpc crew, Vector3 from, Vector3 dir)
            {
                Vector3 back = crew.DisperseCenter - from;
                back.y = 0f;
                float distance = back.magnitude;
                if (distance < 5f || distance > ReturnGuardRange) return false;
                return Vector3.Angle(dir, back) < ReturnGuardAngle;
            }
            private static bool NearMonument(Vector3 from, Vector3 point)
            {
                List<MonumentInfo> monuments = TerrainMeta.Path != null ? TerrainMeta.Path.Monuments : null;
                if (monuments == null) return false;
                foreach (MonumentInfo monument in monuments)
                {
                    if (monument == null) continue;
                    float distance = monument.Distance(point);
                    if (distance >= MonumentMargin) continue;
                    float own = monument.Distance(from);
                    if (own < MonumentMargin && distance >= own + LeaveMargin) continue;
                    return true;
                }
                return false;
            }
            private const float LeaveMargin = 10f;
            private static bool CrossesMonument(Vector3 from, Vector3 to)
            {
                List<MonumentInfo> monuments = TerrainMeta.Path != null ? TerrainMeta.Path.Monuments : null;
                if (monuments == null) return false;
                float length = CoreEx.DistanceFlat(from, to);
                foreach (MonumentInfo monument in monuments)
                {
                    if (monument == null) continue;
                    for (float d = 20f; d < length; d += 20f)
                        if (monument.Distance(Vector3.Lerp(from, to, d / length)) < MonumentPassMargin) return true;
                }
                return false;
            }
            private static bool CrossesSafeZone(Vector3 from, List<Vector3> corners)
            {
                if (HelperSafeZones.Count == 0 || corners.Count == 0) return false;
                Vector3 end = corners[corners.Count - 1];
                bool inside = HelperSafeZones.IsPointInside(from, 0f, false);
                float own = inside ? 0f : ZoneClearance(from);
                if (HelperSafeZones.IsPointInside(end, Mathf.Min(SafeZoneMargin, own + LeaveMargin), false) || CoreEx.InSafeZone(end)) return true;
                if (inside) return false;
                float margin = own > SafeZoneMargin ? SafeZoneMargin : own - 1f < ZoneKeep ? Mathf.Max(0f, own - 1f) : Mathf.Max(ZoneKeep, own - ZoneApproach);
                Vector3 previous = from;
                foreach (Vector3 corner in corners)
                {
                    float length = CoreEx.DistanceFlat(previous, corner);
                    for (float d = SafeZoneStep; d < length + SafeZoneStep; d += SafeZoneStep)
                        if (HelperSafeZones.IsPointInside(Vector3.Lerp(previous, corner, length > 0f ? Mathf.Min(1f, d / length) : 1f), margin, false)) return true;
                    previous = corner;
                }
                return false;
            }
            private static readonly List<Vector3> _straight = new List<Vector3>(1);
            private static bool CrossesSafeZone(Vector3 from, Vector3 to)
            {
                _straight.Clear();
                _straight.Add(to);
                return CrossesSafeZone(from, _straight);
            }
            private const float SafeZoneStep = 2f;
            private const float ZoneApproach = 10f, ZoneKeep = 5f;
            private static float ZoneClearance(Vector3 point)
            {
                if (!HelperSafeZones.IsPointInside(point, SafeZoneMargin, false)) return SafeZoneMargin + 1f;
                float low = 0f, high = SafeZoneMargin;
                while (high - low > 0.5f)
                {
                    float middle = (low + high) * 0.5f;
                    if (HelperSafeZones.IsPointInside(point, middle, false)) high = middle;
                    else low = middle;
                }
                return low;
            }
        }

        public class CrewBattleState : BattleFsmState
        {
            public override string Name => "Battle";
            private CrewNpc Crew => Owner as CrewNpc;

            public override bool UseFlee => false;
            public override float MaxChaseDistance => 80f;
            public override float ForgetTimeout => 20f;

            public override bool CanTargetBattleEnemy(BaseCombatEntity entity)
            {
                CrewNpc crew = Crew;
                return crew != null && entity is BasePlayer player && crew.CanAttack(player);
            }
            public override BaseCombatEntity FindBattleEnemy()
            {
                CrewNpc crew = Crew;
                if (crew == null || !crew.HasBot || crew.isMounted) return null;
                BasePlayer target = crew.FindTarget(crew.FootRange, false);
                if (target != null) crew.OnEngage(target);
                return target;
            }
            public override int GetWeaponSlot() => Crew?.GetWeaponSlot() ?? -1;
            protected override bool CanEnterState()
            {
                if (!Owner.IsValid() || Owner.isMounted) return false;
                return base.CanEnterState();
            }
            protected override ResponseFromUpdateState UpdateState(float delta)
            {
                if (!Owner.IsValid() || Owner.isMounted) return ResponseFromUpdateState.Failure;
                return base.UpdateState(delta);
            }
        }

        #endregion

        #region VehicleEventsCore: турели

        public abstract class BaseTurretController : FacepunchBehaviour
        {
            protected BaseTurretSettings settings;
            protected IEventController eventController;
            protected NPCAutoTurret owner;
            private ulong _netId;
            public NPCAutoTurret Owner => owner;
            public CoreHost Host => run?.Host ?? eventController?.Host ?? (EventEntities.TryGetEvent(owner, out IEventController parent) ? parent.Host : null);

            protected virtual void Awake()
            {
                owner = GetComponent<NPCAutoTurret>();
                if (owner == null)
                {
                    Destroy(this);
                    return;
                }
                _netId = owner.net != null ? owner.net.ID.Value : 0UL;
                CoreEx.SetBusy(owner, true);
                if (EventEntities.TryGetTurret(owner, out BaseTurretController previous) && previous != this) Destroy(previous);
                EventEntities.RegisterTurret(this);
            }
            protected virtual void OnDestroy() => EventEntities.UnregisterTurret(this, _netId);

            protected EventRun run;

            public virtual void InitSpawn(BaseTurretSettings settings, IEventController eventController)
            {
                this.settings = settings;
                this.eventController = eventController;
                run = CoreEx.Alive(eventController) ? eventController.CurrentRun : null;
                InvokeRepeating(CheckHealthParent, 2f, 2f);
            }
            public void OnAttacked(BasePlayer attacker)
            {
                if (!VehicleCore.IsRealPlayer(attacker) || run == null) return;
                run.AddAttacker(attacker);
                if (run.IsCurrent) run.Owner.SetTarget(attacker);
            }
            public void ScaleDamage(HitInfo info)
            {
                if (settings != null) info?.damageTypes?.ScaleAll(settings.RateDamage);
            }
            public bool CanTurretTarget(BaseCombatEntity target)
            {
                if (target == null || owner == null || owner.IsDestroyed || settings == null || run == null) return false;
                if (target.Distance(owner) > settings.MaxDistanceForAttack) return false;
                if (run.IsCurrent) return run.Owner.IsTarget(target);
                return target is BasePlayer player && run.IsAttacker(player);
            }
            protected virtual void CheckHealthParent() { }
            public void KillImmediate()
            {
                if (owner != null && !owner.IsDestroyed) owner.Kill();
            }
        }

        #endregion

        #region VehicleEventsCore: хуки ядра

        private object OnEntityTakeDamage(BaseCombatEntity entity, HitInfo info) => VehicleCoreHooks.OnEntityTakeDamage(null, entity, info);
        private object OnTurretTarget(NPCAutoTurret turret, BaseCombatEntity target) => VehicleCoreHooks.OnTurretTarget(null, turret, target);
        private object CanDismountEntity(BasePlayer player, BaseMountable entity) => VehicleCoreHooks.CanDismountEntity(null, player, entity);
        private object CanMountEntity(BasePlayer player, BaseMountable entity) => VehicleCoreHooks.CanMountEntity(null, player, entity);
        private object CanEntityTakeDamage(BaseCombatEntity entity, HitInfo info) => VehicleCoreHooks.CanEntityTakeDamage(null, entity, info);
        private object OnNpcTarget(BaseEntity npc, BaseEntity target) => VehicleCoreHooks.OnNpcTarget(null, npc, target);
        private object OnBotReSpawnNPCTarget(ScientistNPC npc, BasePlayer target) => VehicleCoreHooks.OnBotReSpawnNPCTarget(null, npc, target);

        public static class VehicleCoreHooks
        {
            private const string ShortPrefabExplosive = "explosive.timed.deployed";

            public static object OnEntityTakeDamage(CoreHost host, BaseCombatEntity entity, HitInfo info)
            {
                if (entity == null || info == null || info.damageTypes == null || (host != null && host.IsUnloading)) return null;
                try
                {
                    if (entity is CrewNpc crew)
                    {
                        if (Handles(host, crew.Host)) CrewDamage(crew, info);
                        return null;
                    }
                    if (entity is BasePlayer victim)
                    {
                        if (VehicleCore.IsRealPlayer(victim)) PlayerDamage(host, info);
                        return null;
                    }
                    if (entity is NPCAutoTurret turret && EventEntities.TryGetTurret(turret, out BaseTurretController controller, host))
                    {
                        if (Handles(host, controller.Host)) controller.OnAttacked(info.InitiatorPlayer);
                        return null;
                    }
                    if (entity is BaseVehicle && EventEntities.TryGetEvent(entity, out IEventController owner, host) && owner.HasEvent && Handles(host, owner.Host))
                        VehicleDamage(owner, info);
                }
                catch (Exception ex)
                {
                    CoreLog.LogError(host?.Plugin?.Name, "OnEntityTakeDamage: {0}", ex);
                }
                return null;
            }
            private static bool Handles(CoreHost host, CoreHost owner) => EventEntities.Owns(host, owner) && (owner == null || !owner.IsUnloading);
            private static void CrewDamage(CrewNpc crew, HitInfo info)
            {
                BasePlayer attacker = info.InitiatorPlayer;
                if (VehicleCore.IsRealPlayer(attacker))
                {
                    if (crew.Settings != null) info.damageTypes.ScaleAll(crew.Settings.damageReceiveRate);
                    crew.OnAttackedByPlayer(attacker);
                    return;
                }
                if (!crew.BlockNpcDamage) return;
                if (crew.BlockAnyNonPlayerDamage || attacker != null) info.damageTypes.Clear();
            }
            private static void PlayerDamage(CoreHost host, HitInfo info)
            {
                BaseEntity initiator = info.Initiator;
                if (initiator is CrewNpc crew)
                {
                    if (Handles(host, crew.Host) && crew.Settings != null) info.damageTypes.ScaleAll(crew.Settings.damageHurtRate);
                }
                else if (initiator is NPCAutoTurret turret && EventEntities.TryGetTurret(turret, out BaseTurretController controller, host))
                {
                    if (Handles(host, controller.Host)) controller.ScaleDamage(info);
                }
            }
            private static void VehicleDamage(IEventController owner, HitInfo info)
            {
                BasePlayer attacker = info.InitiatorPlayer;
                bool isPlayer = VehicleCore.IsRealPlayer(attacker);
                if (isPlayer)
                {
                    owner.CurrentRun?.AddAttacker(attacker);
                    owner.SetTarget(attacker);
                }
                bool isExplosiveTimed = info.WeaponPrefab != null && info.WeaponPrefab.ShortPrefabName == ShortPrefabExplosive;
                BaseEventSettings eventSettings = owner.GetEventSettings();
                if (eventSettings != null && eventSettings.blockDamageVehicleIsNotPlayer && !isPlayer && !isExplosiveTimed)
                {
                    info.damageTypes.Clear();
                    return;
                }
                if (!isPlayer && isExplosiveTimed) return;
                BaseVehicleSettings settings = owner.GetSettings();
                if (settings != null) info.damageTypes.ScaleAll(settings.damageReceiveRate);
            }
            public static object OnTurretTarget(CoreHost host, BaseEntity turret, BaseCombatEntity target)
            {
                if (target == null || !target.IsAlive()) return null;
                if (EventEntities.TryGetTurret(turret, out BaseTurretController controller, host) && !controller.CanTurretTarget(target)) return true;
                return null;
            }
            public static object CanDismountEntity(CoreHost host, BasePlayer player, BaseMountable entity)
            {
                if (!(player is CrewNpc crew) || crew.CanDismount || !crew.HasBot || !EventEntities.Owns(host, crew.Host)) return null;
                if (entity == null || entity.IsDestroyed) return null;
                BaseVehicle vehicle = entity.VehicleParent();
                if (vehicle != null && (vehicle.IsDestroyed || vehicle.IsDead())) return null;
                return true;
            }
            public static object CanMountEntity(CoreHost host, BasePlayer player, BaseMountable entity)
            {
                if (entity != null && VehicleCore.IsRealPlayer(player) && EventEntities.IsEventVehicle(entity, host)) return true;
                return null;
            }
            public static void OnEntityKill(CoreHost host, BaseNetworkable entity)
            {
                if (entity == null || (host != null && host.IsUnloading)) return;
                try
                {
                    if (entity is BaseVehicle vehicle && EventEntities.TryGetVehicleOwner(vehicle, out IEventController owner, host))
                    {
                        if (Handles(host, owner.Host)) owner.OnVehicleKilled(vehicle);
                        return;
                    }
                    if (entity is StorageContainer stash) EventEntities.UnregisterStash(stash, host);
                }
                catch (Exception ex)
                {
                    CoreLog.LogError(host?.Plugin?.Name, "OnEntityKill: {0}", ex);
                }
            }
            public static object CanEntityTakeDamage(CoreHost host, BaseCombatEntity entity, HitInfo info)
            {
                if (entity is BaseVehicle && EventEntities.IsEventVehicle(entity, host)) return true;
                return null;
            }
            public static object OnNpcTarget(CoreHost host, BaseEntity npc, BaseEntity target)
            {
                if (target is CrewNpc crew && !crew.TargetableByNpcs && EventEntities.Owns(host, crew.Host)) return true;
                return null;
            }
            public static object OnBotReSpawnNPCTarget(CoreHost host, BaseEntity npc, BasePlayer target)
            {
                if (target is CrewNpc crew && !crew.TargetableByNpcs && EventEntities.Owns(host, crew.Host)) return false;
                return null;
            }
        }

