        public static class CrewImport
        {
            public const string ReserveDataFile = "DriverController/ReserveConfig/config";
            public const string ConfigFileName = "DriverController";
            public static readonly string[] MigratedPlugins = { "HeliPilots", "TrafficDrivers", "BoatDrivers", "BikeDrivers" };
            private const string PendingName = "/ReserveConfig/crewImportPending";

            private class DriverControllerCrew
            {
                [JsonProperty(RU ? "Настройка водителей" : "Drivers settings")]
                public Dictionary<string, DriverSettings> Drivers;
                [JsonProperty(RU ? "Настройка компаньонов" : "Companion settings")]
                public Dictionary<string, CompanionSettings> Companions;
                [JsonProperty(RU ? "Настройка добычи" : "Loot settings")]
                public Dictionary<string, List<LootInfo>> Loots;
            }

            private static JsonSerializerSettings MemberNameSettings => new JsonSerializerSettings { ContractResolver = new CustomContractResolver() };
            private static string _importing;

            public static bool Ensure(Plugin plugin, ref CrewSettings crew, ICollection<string> usedKeys = null)
            {
                string hostName = plugin != null ? plugin.Name : nameof(VehicleEventsCore);
                _importing = hostName;
                bool pending = IsPending(hostName);
                if (crew != null && !pending)
                {
                    crew.Normalize();
                    WarnMissing(crew, usedKeys);
                    return false;
                }
                CrewSettings found = TryImport(hostName, out string source, out bool dcPresent, out bool fromDriverController);
                if (crew != null)
                {
                    crew.Normalize();
                    int changed = 0;
                    if (found != null)
                    {
                        changed = Merge(crew, found);
                        CoreLog.LogWarning(hostName, "Crew supplemented ({0}): untouched default presets added or replaced - {1}", source, changed);
                    }
                    int defaults = AddMissingDefaults(crew, usedKeys);
                    if (defaults > 0)
                        CoreLog.LogWarning(hostName, "Crew supplemented with default DriverController presets for missing keys - {0}", defaults);
                    if (found == null && defaults == 0)
                    {
                        ReportIncomplete(crew, usedKeys, dcPresent, "crew section from previous import");
                        return false;
                    }
                    UpdatePending(hostName, crew, usedKeys, dcPresent, fromDriverController, source ?? "crew section from previous import");
                    return changed + defaults > 0;
                }
                if (found == null)
                {
                    source = "default DriverController presets";
                    found = FromDefaults(usedKeys);
                }
                else if (AddMissingDefaults(found, usedKeys) > 0)
                    source += " + default DriverController presets for missing keys";
                found.Normalize();
                crew = found;
                CoreLog.LogWarning(hostName, "Crew imported ({0}): drivers {1}, companions {2}, loot sets {3}",
                    source, crew.Drivers.Count, crew.Companions.Count, crew.Loots.Count);
                UpdatePending(hostName, crew, usedKeys, dcPresent, fromDriverController, source);
                return true;
            }
            private static void UpdatePending(string hostName, CrewSettings crew, ICollection<string> usedKeys, bool dcPresent, bool fromDriverController, string source)
            {
                if (!fromDriverController && (dcPresent || MissingKeys(crew, usedKeys).Count > 0))
                {
                    SetPending(hostName, true);
                    ReportIncomplete(crew, usedKeys, dcPresent, source);
                    return;
                }
                SetPending(hostName, false);
                WarnMissing(crew, usedKeys);
            }

            #region Источники
            private static CrewSettings TryImport(string hostName, out string source, out bool dcPresent, out bool fromDriverController)
            {
                source = null;
                fromDriverController = true;
                DataFileSystem configs = new DataFileSystem(Interface.Oxide.ConfigDirectory);
                bool hasFile = configs.ExistsDatafile(ConfigFileName);
                bool hasReserve = Interface.Oxide.DataFileSystem.ExistsDatafile(ReserveDataFile);
                dcPresent = hasFile || hasReserve;
                CrewSettings result = hasFile ? FromConfigFile(configs) : null;
                if (result != null)
                {
                    DateTime changed = System.IO.File.GetLastWriteTime(System.IO.Path.Combine(Interface.Oxide.ConfigDirectory, ConfigFileName + ".json"));
                    source = string.Format("config/DriverController.json of {0:yyyy-MM-dd HH:mm}", changed);
                    return result;
                }
                result = hasReserve ? FromReserve() : null;
                if (result != null)
                {
                    source = "DriverController backup (data/DriverController/ReserveConfig/config)";
                    return result;
                }
                fromDriverController = false;
                return FromMigratedPlugins(hostName, configs, out source);
            }

            private static CrewSettings Convert(DriverControllerCrew source)
            {
                if (source == null) return null;
                CrewSettings crew = new CrewSettings
                {
                    Drivers = source.Drivers ?? new Dictionary<string, DriverSettings>(),
                    Companions = source.Companions ?? new Dictionary<string, CompanionSettings>(),
                    Loots = source.Loots ?? new Dictionary<string, List<LootInfo>>()
                };
                return crew.IsEmpty ? null : crew;
            }

            private static CrewSettings FromConfigFile(DataFileSystem configs)
            {
                try
                {
                    return Convert(configs.ReadObject<DriverControllerCrew>(ConfigFileName));
                }
                catch (Exception ex)
                {
                    CoreLog.LogError(_importing, "Crew import: config/DriverController.json cannot be read: {0}", ex.Message);
                    return null;
                }
            }

            private static CrewSettings FromReserve()
            {
                try
                {
                    string json = Interface.Oxide.DataFileSystem.ReadObject<string>(ReserveDataFile);
                    if (string.IsNullOrEmpty(json)) return null;
                    return Convert(JsonConvert.DeserializeObject<DriverControllerCrew>(json, MemberNameSettings));
                }
                catch (Exception ex)
                {
                    CoreLog.LogError(_importing, "Crew import: DriverController backup cannot be read: {0}", ex.Message);
                    return null;
                }
            }

            private static CrewSettings FromMigratedPlugins(string hostName, DataFileSystem configs, out string source)
            {
                source = null;
                CrewSettings merged = null;
                List<string> names = new List<string>();
                foreach (string name in MigratedPlugins)
                {
                    if (name == hostName || IsPending(name)) continue;
                    CrewSettings crew = ReadPluginCrew(configs, name);
                    if (crew == null || crew.IsEmpty) continue;
                    merged ??= new CrewSettings();
                    AddMissing(merged.Drivers, crew.Drivers);
                    AddMissing(merged.Companions, crew.Companions);
                    AddMissing(merged.Loots, crew.Loots);
                    names.Add(name);
                }
                if (merged == null) return null;
                source = "crew section of plugins " + string.Join(", ", names);
                return merged;
            }

            private static CrewSettings ReadPluginCrew(DataFileSystem configs, string name)
            {
                try
                {
                    if (!configs.ExistsDatafile(name)) return null;
                    return configs.ReadObject<Newtonsoft.Json.Linq.JObject>(name)[RU ? CrewSettings.JsonKeyRu : CrewSettings.JsonKeyEn]?.ToObject<CrewSettings>();
                }
                catch (Exception ex)
                {
                    CoreLog.LogWarning(_importing, "Crew import: crew section of {0} cannot be read: {1}", name, ex.Message);
                    return null;
                }
            }

            private static CrewSettings FromDefaults(ICollection<string> usedKeys)
            {
                CrewSettings defaults = CrewSettings.GetDefault();
                if (usedKeys == null || usedKeys.Count == 0) return defaults;
                CrewSettings result = new CrewSettings();
                HashSet<string> loots = new HashSet<string>();
                foreach (var pair in defaults.Drivers)
                {
                    if (!usedKeys.Contains(pair.Key)) continue;
                    result.Drivers[pair.Key] = pair.Value;
                    AddLootKeys(pair.Value, loots);
                }
                foreach (var pair in defaults.Companions)
                {
                    if (!usedKeys.Contains(pair.Key)) continue;
                    result.Companions[pair.Key] = pair.Value;
                    AddLootKeys(pair.Value, loots);
                }
                foreach (var pair in defaults.Loots)
                {
                    if (usedKeys.Contains(pair.Key) || loots.Contains(pair.Key)) result.Loots[pair.Key] = pair.Value;
                }
                return result.IsEmpty ? defaults : result;
            }
            private static int AddMissingDefaults(CrewSettings crew, ICollection<string> usedKeys)
            {
                crew.Normalize();
                List<string> missing = MissingKeys(crew, usedKeys);
                if (missing.Count == 0) return 0;

                CrewSettings defaults = CrewSettings.GetDefault();
                HashSet<string> loots = new HashSet<string>();
                int added = 0;
                foreach (string key in missing)
                {
                    if (defaults.Drivers.TryGetValue(key, out DriverSettings driver) && driver != null)
                    {
                        crew.Drivers[key] = driver;
                        AddLootKeys(driver, loots);
                        added++;
                    }
                    else if (defaults.Companions.TryGetValue(key, out CompanionSettings companion) && companion != null)
                    {
                        crew.Companions[key] = companion;
                        AddLootKeys(companion, loots);
                        added++;
                    }
                    else if (defaults.Loots.TryGetValue(key, out List<LootInfo> loot) && loot != null)
                    {
                        crew.Loots[key] = loot;
                        added++;
                    }
                }
                foreach (string key in loots)
                {
                    if (crew.Loots.ContainsKey(key) || !defaults.Loots.TryGetValue(key, out List<LootInfo> loot) || loot == null) continue;
                    crew.Loots[key] = loot;
                    added++;
                }
                return added;
            }
            private static void AddLootKeys(CompanionSettings settings, HashSet<string> into)
            {
                if (settings?.Loots?.NameContainerID == null) return;
                foreach (string key in settings.Loots.NameContainerID)
                    if (!string.IsNullOrEmpty(key)) into.Add(key);
            }
            #endregion

            #region Дополнение раздела и проверки
            private static void AddMissing<TValue>(Dictionary<string, TValue> target, Dictionary<string, TValue> source)
            {
                if (source == null) return;
                foreach (var pair in source)
                    if (pair.Value != null && !target.ContainsKey(pair.Key)) target[pair.Key] = pair.Value;
            }
            private static int Merge(CrewSettings crew, CrewSettings found)
            {
                CrewSettings defaults = CrewSettings.GetDefault();
                return MergeSection(crew.Drivers, found.Drivers, defaults.Drivers)
                       + MergeSection(crew.Companions, found.Companions, defaults.Companions)
                       + MergeSection(crew.Loots, found.Loots, defaults.Loots);
            }
            private static int MergeSection<TValue>(Dictionary<string, TValue> target, Dictionary<string, TValue> source, Dictionary<string, TValue> defaults)
            {
                if (source == null) return 0;
                int changed = 0;
                foreach (var pair in source)
                {
                    if (pair.Value == null) continue;
                    if (target.TryGetValue(pair.Key, out TValue current) && current != null)
                    {
                        if (!defaults.TryGetValue(pair.Key, out TValue original) || !SameJson(current, original) || SameJson(current, pair.Value)) continue;
                    }
                    target[pair.Key] = pair.Value;
                    changed++;
                }
                return changed;
            }
            private static bool SameJson(object a, object b) => JsonConvert.SerializeObject(a, MemberNameSettings) == JsonConvert.SerializeObject(b, MemberNameSettings);

            private static List<string> MissingKeys(CrewSettings crew, ICollection<string> usedKeys)
            {
                List<string> missing = new List<string>();
                if (usedKeys == null) return missing;
                foreach (string key in usedKeys)
                {
                    if (string.IsNullOrEmpty(key) || missing.Contains(key)) continue;
                    if (crew.Drivers.ContainsKey(key) || crew.Companions.ContainsKey(key) || crew.Loots.ContainsKey(key)) continue;
                    missing.Add(key);
                }
                return missing;
            }
            private static void WarnMissing(CrewSettings crew, ICollection<string> usedKeys)
            {
                List<string> missing = MissingKeys(crew, usedKeys);
                if (missing.Count > 0)
                    CoreLog.LogWarning(_importing, "Crew section has no presets referenced by the config: {0}", string.Join(", ", missing));
            }
            private static void ReportIncomplete(CrewSettings crew, ICollection<string> usedKeys, bool dcPresent, string source)
            {
                List<string> missing = MissingKeys(crew, usedKeys);
                CoreLog.LogError(_importing, "DriverController crew presets were not read ({0}) - crew section taken from: {1}{2}. " +
                                                  "Restore (or fix) config/DriverController.json or data/DriverController/ReserveConfig/config and reload the plugin: " +
                                                  "missing and untouched default presets will be filled in automatically",
                    dcPresent ? "DriverController files exist but cannot be read" : "no DriverController files",
                    source, missing.Count > 0 ? "; no presets for keys: " + string.Join(", ", missing) : string.Empty);
            }
            private static bool IsPending(string pluginName)
            {
                try
                {
                    string file = pluginName + PendingName;
                    return Interface.Oxide.DataFileSystem.ExistsDatafile(file) && Interface.Oxide.DataFileSystem.ReadObject<bool>(file);
                }
                catch (Exception ex)
                {
                    CoreLog.LogWarning(pluginName, "Crew import flag cannot be read - treated as not pending: {0}", ex.Message);
                    return false;
                }
            }
            private static void SetPending(string hostName, bool value)
            {
                string file = hostName + PendingName;
                if (!value && !Interface.Oxide.DataFileSystem.ExistsDatafile(file)) return;
                Interface.Oxide.DataFileSystem.WriteObject(file, value);
            }
            #endregion
        }

        #endregion

        #region VehicleEventsCore: загрузка конфига

        public static class CoreConfig
        {
            public static TConfig Load<TConfig>(Plugin plugin) where TConfig : class
            {
                try
                {
                    return plugin.Config.ReadObject<TConfig>();
                }
                catch (Exception ex)
                {
                    CoreLog.LogError(plugin?.Name, "Config cannot be read ({0}) - default config created (copy of the original file: {1})",
                        ex.Message, Backup(plugin) ?? "not saved");
                    return null;
                }
            }

            private static string Backup(Plugin plugin)
            {
                try
                {
                    string source = plugin.Config.Filename;
                    if (string.IsNullOrEmpty(source) || !System.IO.File.Exists(source)) return null;
                    string folder = System.IO.Path.Combine(Interface.Oxide.DataDirectory, plugin.Name, "ReserveConfig");
                    System.IO.Directory.CreateDirectory(folder);
                    string target = System.IO.Path.Combine(folder, string.Format("config_backup_{0:yyyyMMdd_HHmmss}.json", DateTime.Now));
                    System.IO.File.Copy(source, target, true);
                    return target;
                }
                catch (Exception ex)
                {
                    CoreLog.LogError(plugin?.Name, "Failed to save a copy of the config file: {0}", ex.Message);
                    return null;
                }
            }
        }

        #endregion

        #region VehicleEventsCore: конфиг (имена членов и ключи JSON - как в DriverController)
        public class BaseTurretSettings
        {
            private const int order = 0;

            [JsonProperty(RU ? "Включить турели на транспорте" : "Enable Turrets on Vehicle", Order = order + 10)]
            public bool Enable = true;

            [JsonProperty(RU ? "Отключать турели, при окончании события (когда лут разблокирован)" : "Disable Turrets on Event End", Order = order + 20)]
            public bool CanDisable = true;

            [JsonProperty(RU ? "Максимальная дистанция атаки" : "Maximum Attack Range", Order = order + 30)]
            public float MaxDistanceForAttack = 50f;

            [JsonProperty(RU ? "Множитель урона по игроку" : "Player Damage Multiplier", Order = order + 40)]
            public float RateDamage = 1f;
        }
        public class BaseGeneratePathSettings
        {
            private const int order = 0;

            [JsonProperty(RU ? "Включить генерацию маршрута" : "Enable route generation", Order = order + 10)]
            public bool Enable = true;
        }
        public class BaseVehicleSettings
        {
            private const int order = 500;

            [JsonProperty(RU ? "Активировать это событие?" : "Activate this event?", Order = 0)]
            public bool Enable = true;

            [JsonProperty(!RU ? "Damage receive rate" : "Рейт получаемого урона", Order = order + 30)]
            public float damageReceiveRate = 0.5f;

            [JsonProperty(RU ? "Настройки топлива" : "Fuel settings", Order = order + 60)]
            public FuelSettings fuel = new();

            [JsonProperty(RU ? "Настройка фар транспорта" : "Vehicle headlight settings", Order = order + 70)]
            public HeadlightSettings Headlights = new();
            public virtual bool ShouldSerializeHeadlights() => true;

            [JsonProperty(RU ? "Настройка детонатора" : "Detonator settings", Order = order + 80)]
            public Detonator detonator = new Detonator();

