        public struct CoreItemSetup
        {
            [JsonProperty(RU ? "ShortName или ID предмета" : "Item shortname or ID")]
            private string shortNameOrId;

            [JsonProperty(RU ? "Скин предмета" : "Item skin")]
            private ulong skin;

            public CoreItemSetup(string shortNameOrId, ulong skin)
            {
                this.shortNameOrId = shortNameOrId;
                this.skin = skin;
            }

            public Item CreateItem(int amount, string name = "")
            {
                if(string.IsNullOrEmpty(shortNameOrId)) return null;
                if(amount < 1) amount = 1;
                Item result = null;
                if(int.TryParse(shortNameOrId, out int id)) result = ItemManager.CreateByItemID(id, amount, skin);
                if(result == null) result = ItemManager.CreateByName(shortNameOrId, amount, skin);
                if(result != null && !string.IsNullOrEmpty(name)) result.name = name;
                if(result == null) Debug.LogWarning("Item [{0}] not created", shortNameOrId);
                return result;
            }
        }

