        public class TestUIInfo
        {
            private BasePlayer driver;
            private GuiInfo gui = new();

            public TestUIInfo(BasePlayer driver)
            {
                this.driver = driver;
            }

            public void DrawPath(Vector3[] path, Color color, float radius, int currentIndex, float deltaTime)
            {
                Vector3 startPos = path[0];
                for (int i = 0; i < path.Length; i++)
                {
                    Vector3 from = (i == 0) ? startPos : path[i - 1];
                    Vector3 to = path[i];
                    bool isAdmin = driver.IsAdmin;
                    if(!isAdmin) driver.SetPlayerFlag(BasePlayer.PlayerFlags.IsAdmin, true);
                    driver?.SendConsoleCommand("ddraw.line", deltaTime, Color.blue, from, to);
                    driver?.SendConsoleCommand("ddraw.sphere", deltaTime, currentIndex == i ? Color.yellow : color, to, radius);
                    if(!isAdmin) driver.SetPlayerFlag(BasePlayer.PlayerFlags.IsAdmin, false);
                }
            }
            public void SendInfo(string text) => gui.SendInfo(driver, text);
            public void Destroy() => gui.CloseUI(driver);

            public class GuiInfo
            {
                private CuiTextComponent info;
                private List<CuiElement> infoElement = new();

                public GuiInfo()
                {
                    info = new CuiTextComponent
                    {
                        Align = TextAnchor.UpperLeft,
                        Color = "1 1 1 1",
                        FontSize = 14,
                        VerticalOverflow = VerticalWrapMode.Overflow,
                        Text = ""
                    };
                    infoElement.Add(new CuiElement
                    {
                        Parent = "Hud", Name = "InfoCar", DestroyUi = "InfoCar",
                        Components =
                        {
                            new CuiRectTransformComponent
                            {
                                AnchorMin = "1 1", AnchorMax = "1 1",
                                OffsetMin = "-400 -50", OffsetMax = "0 -50"
                            },
                            info
                        }
                    });
                }
                public void SendInfo(BasePlayer admin, string text)
