        #region VehicleEventsCore: запись маршрутов
        public abstract class RecorderManager : MonoBehaviour
        {
            public static readonly Dictionary<string, string> DefaultMessagesRu = new()
            {
                ["InfoCurrentPath"] = "Создано точек: {0}   Расстояние: {1}m.",
                ["AllPaths"] = "Всего записанных маршрутов: {0}",
                ["SavePath"] = "Маршрут сохранен.",
                ["UndoPath"] = "Маршрут удален ({0} метров)",
                ["ClearPaths"] = "Все маршруты ({0}) удалены.",
                ["StartRec"] = "Запись началась",
                ["StopRec"] = "Запись остановлена: {0} метров.",
                ["PauseRec"] = "Запись на паузе: {0} метров.",
                ["DeletePoint"] = "Удалена точка #{0}",
                ["CurrentPoint"] = "Текущая точка #{0}",
                ["AddPoint"] = "Добавлена точка: {0} метров.",
                ["NoPointBelowOceanLevel"] = "Точка ниже уровня океана не записывается",
                ["NoPointFromGround"] = "Точки на суше для этого транспорта не записываются",
                ["HasTestEventOtherAdmin"] = "Тестовое событие уже запущено другим администратором.",
                ["NoRouteModes"] = "Событие не создано: в конфиге выключены и записанные маршруты, и генерация маршрутов.",
            };
            public static readonly Dictionary<string, string> DefaultMessagesEn = new()
            {
                ["InfoCurrentPath"] = "Created points: {0}   Distance: {1}m.",
                ["AllPaths"] = "Total recorded routes: {0}",
                ["SavePath"] = "Route saved.",
                ["UndoPath"] = "Route deleted ({0} meters)",
                ["ClearPaths"] = "All routes ({0}) deleted.",
                ["StartRec"] = "Recording started",
                ["StopRec"] = "Recording stopped: {0} meters.",
                ["PauseRec"] = "Recording paused: {0} meters.",
                ["DeletePoint"] = "Point #{0} deleted",
                ["CurrentPoint"] = "Current point #{0}",
                ["AddPoint"] = "Point added: {0} meters.",
                ["NoPointBelowOceanLevel"] = "Points below ocean level are not recorded",
                ["NoPointFromGround"] = "Points on land are not recorded for this vehicle",
                ["HasTestEventOtherAdmin"] = "Test event is already running by another administrator.",
                ["NoRouteModes"] = "Event not created: both recorded routes and route generation are disabled in the config.",
            };

            public Dictionary<BasePlayer, BaseRecorderController> components = new();
            public LayerMask LayerMask = LayerMask.GetMask("World", "Prevent Movement", "Terrain");
            private List<Vector3[]> currentRecorders = new();
            protected List<Vector3[]> pathRecorders = new();
            public List<Vector3[]> PathRecords => pathRecorders;
            public bool HasCurrentRecorded => currentRecorders.Count > 0;
            public bool HasRecorded => pathRecorders.Count > 0;
            protected abstract string nameFile { get; }
            public abstract RecorderPathSettings Config { get; }
            public CoreHost Host => VehicleCore.HostOf(GetType());

            protected virtual void Awake()
            {
                Host?.RegisterHost(this);
                LoadDataPaths();
                if (Config != null && Config.Enable) CoreLog.Log(Host?.Plugin?.Name, "Recorded routes found for events: {0}", pathRecorders.Count);
            }
            protected virtual void OnDestroy()
            {
                Host?.UnregisterHost(this);
                foreach (BaseRecorderController recorder in new List<BaseRecorderController>(components.Values))
                {
                    if (recorder != null) Destroy(recorder);
                }
                components.Clear();
            }
            public void CreateRecController<T>(BasePlayer admin) where T : BaseRecorderController
            {
                if (admin == null) return;
                if (components.TryGetValue(admin, out BaseRecorderController existing))
                {
                    if (existing != null)
                    {
                        RemoveRecController(admin);
                        return;
                    }
                    components.Remove(admin);
                }
                T comp = gameObject.AddComponent<T>();
                components[admin] = comp;
                comp.Init(this, admin);
                comp.OpenUI();
            }
            public void RemoveRecController(BasePlayer admin)
            {
                if (admin == null) return;
                if (components.TryGetValue(admin, out BaseRecorderController recorder))
                {
                    components.Remove(admin);
                    if (recorder != null) DestroyImmediate(recorder);
                }
            }
            public void ProcessingCommand(BasePlayer admin, params string[] args)
            {
                int length = args == null ? 0 : args.Length;
                if (length == 0 || admin == null) return;
                string command = args[0];
                if (command == "close")
                {
                    RemoveRecController(admin);
                    return;
                }
                if (!components.TryGetValue(admin, out BaseRecorderController recorder) || recorder == null)
                {
                    components.Remove(admin);
                    return;
                }
                switch (command)
                {
                    case "resume":
                    case "rec": recorder.Recorder(); return;
                    case "stop": recorder.StopRecorder(); return;
                    case "delete": recorder.DeletePoint(); return;
                    case "pause": recorder.PauseRecorder(); return;
                    case "log": recorder.OpenLog(); return;
                    case "undo": Undo(recorder); return;
                    case "save": Save(recorder); return;
                    case "clear": Clear(recorder); return;
                }
            }
            private void Save(BaseRecorderController controller)
            {
                if (!controller.HasPath) return;
                Vector3[] currentPath = controller.path.ToArray();
                currentRecorders.Add(currentPath);
                pathRecorders.Add(currentPath);
                SaveDataPaths();
                controller.Save(controller.Distance);
            }
            private void Undo(BaseRecorderController controller)
            {
                if (currentRecorders.Count == 0) return;
                Vector3[] currentPath = currentRecorders[currentRecorders.Count - 1];
                currentRecorders.Remove(currentPath);
                pathRecorders.Remove(currentPath);
                SaveDataPaths();
                controller.Undo(CoreEx.Distance(currentPath));
            }
            private void Clear(BaseRecorderController controller)
            {
                int count = pathRecorders.Count;
                pathRecorders.Clear();
                SaveDataPaths();
                currentRecorders.Clear();
                controller.Clear(count);
            }
            public abstract string RecordCommandName { get; }
            public abstract string RecordUiCommandName { get; }
            public bool Command(IPlayer iPlayer, string command, string[] args)
            {
                BasePlayer admin = iPlayer?.Object as BasePlayer;
                if (admin == null || !admin.IsConnected || Host == null || !Host.IsAdmin(admin)) return false;
                if (command == RecordCommandName)
                {
                    CreateRecController<EventRecorderController>(admin);
                    return true;
                }
                if (command == RecordUiCommandName)
                {
                    ProcessingCommand(admin, args);
                    return true;
                }
                return false;
            }
            public void LoadDataPaths()
            {
                try
                {
                    if (Interface.Oxide.DataFileSystem.ExistsDatafile(nameFile))
                    {
                        if (Host != null && Host.IsWipe && Config != null && Config.canClearRecFromWipe)
                        {
                            pathRecorders.Clear();
                            SaveDataPaths();
                        }
                        else pathRecorders = Interface.Oxide.DataFileSystem.ReadObject<List<Vector3[]>>(nameFile) ?? new List<Vector3[]>();
                        pathRecorders.RemoveAll(x => x == null || x.Length == 0);
                    }
                    else
                    {
                        Interface.Oxide.DataFileSystem.WriteObject(nameFile, pathRecorders);
                    }
                }
                catch (Exception ex)
                {
                    pathRecorders = new List<Vector3[]>();
                    Debug.LogError<VehicleEventsCore>("Error reading routes file [{0}], delete the file: {1}", nameFile, ex.Message);
                }
            }
            public void SaveDataPaths()
            {
                Interface.Oxide.DataFileSystem.WriteObject(nameFile, pathRecorders);
            }
            public static T Create<T>() where T : RecorderManager
            {
                return new GameObject("RecorderManager").AddComponent<T>();
            }
            public abstract class RecorderPathSettings
            {
                private const int order = 0;
                [JsonIgnore] public abstract bool CanPointFromOcean { get; }
                [JsonIgnore] public abstract bool CanPointFromGround { get; }
                [JsonIgnore] public abstract float Height { get; }
                [JsonIgnore] public abstract float AreaDepth { get; }

                [JsonProperty(RU ? "Включить использование записанных маршрутов?" : "Enable recorded routes usage?", Order = order + 10)]
                public bool Enable;

                [JsonProperty(RU ? "Очищать сохраненные маршруты после вайпа?" : "Clear saved routes after wipe?", Order = order + 20)]
                public bool canClearRecFromWipe;

                [JsonProperty(RU ? "Минимальная дистанция между точками для ее записи в маршрут (используется при записи маршрута)" : "Minimum distance between points to record in route (used when recording route)", Order = order + 30)]
                public float MinDistanceSavePoint;

                [JsonProperty(RU ? "Минимальное количество точек для сохранения (используется при записи маршрута)" : "Minimum number of points to save (used when recording route)", Order = order + 40)]
                public float MinPointsForSave;

                public RecorderPathSettings(bool enable, float minDistanceSavePoint, float minPointsForSave, bool canClearRecFromWipe)
                {
                    Enable = enable;
                    MinDistanceSavePoint = minDistanceSavePoint;
                    MinPointsForSave = minPointsForSave;
                    this.canClearRecFromWipe = canClearRecFromWipe;

                }

                public RecorderPathSettings()
                {
                }

            }
        }
        public sealed class EventRecorderController : BaseRecorderController { }

        public abstract class BaseRecorderController : MonoBehaviour
        {
            public BasePlayer Admin;
            public RecorderManager Manager { get; private set; }
            public List<Vector3> path = new();
            protected GuiRecord guiRecord;
            private int currentPathIndex = -1;
            private bool canRecPoint = true;
            private string response = "";
            public float Distance = 0;
            public float normalHeight;
            public int PathCount => path.Count;
            public bool HasPath => cfg != null && path.Count >= cfg.MinPointsForSave;
            public bool IsRecording => IsInvoking("Rec");
            public bool IsStop => IsInvoking("StopRec");
            public bool IsPause => IsInvoking("Pause");
            public bool IsBusy => IsRecording || IsStop || IsPause;

            protected RecorderManager.RecorderPathSettings cfg => Manager != null ? Manager.Config : null;
            protected LayerMask layerMask => Manager != null ? Manager.LayerMask : (LayerMask)LayerMask.GetMask("World", "Prevent Movement", "Terrain");
            public bool HasCurrentRecorded => Manager != null && Manager.HasCurrentRecorded;
            public bool HasRecorded => Manager != null && Manager.HasRecorded;
            public List<Vector3[]> PathRecords => Manager != null ? Manager.PathRecords : new List<Vector3[]>();

            public void Init(RecorderManager manager, BasePlayer admin)
            {
                Manager = manager;
                Admin = admin;
                normalHeight = cfg != null ? cfg.Height : 0f;
            }
            private void OnDestroy()
            {
                StopInvoking();
                guiRecord?.CloseUI();
                guiRecord?.Destroy();
                guiRecord = null;
            }
            private bool CheckAdmin()
            {
                if (Admin != null && Admin.IsConnected) return true;
                StopInvoking();
                if (Manager != null) Manager.RemoveRecController(Admin);
                else Destroy(this);
                return false;
            }
            protected string GetMessage(string key, params object[] args) => Manager != null && Manager.Host != null ? Manager.Host.GetMessage(key, Admin != null ? Admin.UserIDString : null, args) : key;
            public void OpenUI()
            {
                guiRecord = new GuiRecord(this, Admin);
                guiRecord.OpenUI();
            }
            public void OpenLog()
            {
                guiRecord.UpdateUI_OpenLog();
            }
            public void Save(float distance)
            {
                Reset();
                guiRecord.UpdateUI_Log("SavePath");
            }
            public void Undo(float distance)
            {
                Reset();
                guiRecord.UpdateUI_Log("UndoPath", distance);
            }
            public void Clear(int count)
            {
                Reset();
                guiRecord.UpdateUI_Log("ClearPaths", count);
            }
            public void Reset()
            {
                StopInvoking();
                path.Clear();
                Distance = 0;
                guiRecord.OpenUI();
            }
            public void Recorder()
            {
                int count = PathCount;
                if(IsStop && currentPathIndex < count - 1)
                {
                    path.RemoveRange(currentPathIndex + 1, count - currentPathIndex - 1);
                    Distance = CoreEx.Distance(path);
                }
                StopInvoking();
                InvokeRepeating("Rec", 1, 1);
                guiRecord.UpdateUI("StartRec");
            }
            public void StopRecorder()
            {
                StopInvoking();
                InvokeRepeating("StopRec", 1, 1);
                guiRecord.UpdateUI("StopRec", Distance.ToString("0"));
            }
            public void PauseRecorder()
            {
                StopInvoking();
                InvokeRepeating("Pause", 1, 1);
                guiRecord.UpdateUI("PauseRec", Distance.ToString("0"));
            }
            public void DeletePoint()
            {
                if(IsStop && currentPathIndex >= 0 && currentPathIndex < PathCount)
                {
                    path.RemoveAt(currentPathIndex);
                    Distance = CoreEx.Distance(path);
                    guiRecord.UpdateUI_Point("DeletePoint", currentPathIndex + 1);
                }
            }
            private void Pause()
            {
                if (!CheckAdmin()) return;
                guiRecord.UpdateUI_Pause();
                DrawPath(1);
            }
            private void StopRec()
            {
                if (!CheckAdmin()) return;
                int index = CoreEx.MinDistanceIndex(path, x => (x - Admin.transform.position).magnitude);
                bool canResponse = currentPathIndex != index;
                if(canResponse)
                {
                    currentPathIndex = index;
                    guiRecord.UpdateUI_Log("CurrentPoint", currentPathIndex + 1);
                }
                DrawPath(1);
            }
            private void Rec()
            {
                if (!CheckAdmin()) return;
                bool isPoint = TryGetPoint(Admin.transform.position, out Vector3 point, out response);
                int count = PathCount;
                float _distance = count == 0 ? 0 : (point - path[count - 1]).magnitude;
                canRecPoint = count == 0 || _distance >= cfg.MinDistanceSavePoint;
                if(canRecPoint && isPoint)
                {
                    currentPathIndex = count;
                    path.Add(point);
                    Distance += _distance;
                    response = "";
                    guiRecord.UpdateUI_Point("AddPoint", _distance.ToString("0"));
                }
                if(!string.IsNullOrEmpty(response)) guiRecord.UpdateUI_Log(response);
                DrawPath(1);
            }
            private void StopInvoking()
            {
                CancelInvoke("Rec");
                CancelInvoke("StopRec");
                CancelInvoke("Pause");
            }
            private void DrawPath(float time)
            {
                int count = path.Count;
                if(count > 0)
                {
                    Vector3 startPos = path[0];
                    bool isAdmin = Admin.IsAdmin;
                    if(!isAdmin) Admin.SetPlayerFlag(BasePlayer.PlayerFlags.IsAdmin, true);
                    try
                    {
                        for (int i = 0; i < count; i++)
                        {
                            Vector3 from = (i == 0) ? startPos : path[i - 1];
                            Vector3 to = path[i];
                            Admin?.SendConsoleCommand("ddraw.line", time, Color.blue, from, to);
                            Admin?.SendConsoleCommand("ddraw.sphere", time, currentPathIndex == i ? Color.yellow : Color.white, to, currentPathIndex == i ? 0.6f : 0.3f);
                            if(i == currentPathIndex) Admin?.SendConsoleCommand("ddraw.text", time, Color.blue, to + Vector3.up, $"Point #{i + 1}");
                        }
                    }
                    finally
                    {
                        if(!isAdmin) Admin.SetPlayerFlag(BasePlayer.PlayerFlags.IsAdmin, false);
                    }
                }
            }

            public bool TryGetPoint(Vector3 position, out Vector3 point, out string response)
            {
                point = position;
                response = "";
                float h = TerrainMeta.HeightMap.GetHeight(position);
                point.y = h;
                if(Physics.Raycast(point + Vector3.up * 200f, -Vector3.up, out var hitInfo, 200, layerMask))
                {
                    Vector3 hitPoint = hitInfo.point;
                    if(!CanTest(ref hitPoint, out response)) return false;
                    point = hitPoint + Vector3.up * normalHeight;
                    return true;
                }
                else
                {
                    if(!CanTest(ref point, out response)) return false;
                    point += Vector3.up * normalHeight;

                    return true;
                }
            }
            private bool CanTest(ref Vector3 position, out string response)
            {
                bool test = WaterLevel.Test(position, true, true);
                float oceanLevel = WaterSystem.OceanLevel;
                response = "";
                if(position.y < oceanLevel - cfg.AreaDepth && test)
                {
                    if(cfg.CanPointFromOcean)
                    {
                        position.y = oceanLevel;
                        return true;
                    }
                    else
                    {
                        response = "NoPointBelowOceanLevel";
                        return false;
                    }
                }
                else if(!test && !cfg.CanPointFromGround)
                {
                    response = "NoPointFromGround";
                    return false;
                }
                if(position.y < oceanLevel) position.y = oceanLevel;
                return true;
            }

