                private string GetCommand(string command, params string[] args) => $"{RecordCommand} {command} {string.Join(" ", args)}";
                public void OpenUI()
                {
                    container.Clear();
                    container.AddRange(panelsOwner);
                    UpdateUI(container);
                    AddCounter(container);
                    CuiHelper.AddUi(admin, container);
                }

                public void UpdateUI(string response, params object[] args)
                {
                    container.Clear();
                    bool canLog = AddLog(response, args);
                    if(canLog)
                    {
                        textLogs.Text = GetLogs();
                        container.Add(logsElement);
                    }
                    UpdateUI(container);

                    AddCounter(container);

                    CuiHelper.AddUi(admin, container);
                    if(canLog) CuiHelper.DestroyUi(admin, name + ".logs.text");
                }
                private void UpdateUI(List<CuiElement> _container)
                {
                    if(!recorder.IsRecording)
                    {
                        if(recorder.IsStop)
                        {
                            CuiHelper.DestroyUi(admin, nameButtons + ".button_2");
                            _container.AddRange(buttonRec);
                        }
                        else
                        {
                            if(!recorder.IsPause)
                            {
                                _container.AddRange(buttonRec);
                                if(recorder.HasCurrentRecorded) _container.AddRange(buttonUndo);
                                if(recorder.HasRecorded) _container.AddRange(buttonClear);
                            }
                            else _container.AddRange(buttonResume);
                        }

                        if(recorder.HasPath) _container.AddRange(buttonSave);
                        else
                        {
                            CuiHelper.DestroyUi(admin, nameButtons + ".button_4");
                        }
                        if(recorder.PathCount > 0 && recorder.IsStop) _container.AddRange(buttonDelete);
                        else
                        {
                            CuiHelper.DestroyUi(admin, nameButtons + ".button_3");
                        }
                    }
                    else
                    {
                        CuiHelper.DestroyUi(admin, nameButtons + ".button_3");
                        CuiHelper.DestroyUi(admin, nameButtons + ".button_4");
                        _container.AddRange(buttonPause);
                        _container.AddRange(buttonStop);
                    }
                }
                public void UpdateUI_Point(string response, params object[] args)
                {
                    container.Clear();
                    bool canLog = AddLog(response, args);
                    if(canLog)
                    {
                        textLogs.Text = GetLogs();
                        container.Add(logsElement);
                    }
                    AddCounter(container);

                    CuiHelper.AddUi(admin, container);
                    if(canLog) CuiHelper.DestroyUi(admin, name + ".logs.text");
                }

                public void UpdateUI_Log(string response, params object[] args)
                {
                    if(AddLog(response, args))
                    {
                        container.Clear();
                        textLogs.Text = GetLogs();
                        container.Add(logsElement);

                        CuiHelper.AddUi(admin, container);
                        CuiHelper.DestroyUi(admin, name + ".logs.text");
                    }
                }

                public void UpdateUI_Pause()
                {
                    container.Clear();
                    changeAnimPause = !changeAnimPause;
                    if(changeAnimPause) container.Add(buttonResume[0]);
                    else container.AddRange(buttonResume);
                    CuiHelper.AddUi(admin, container);
                }

                public void UpdateUI_OpenLog()
                {
                    container.Clear();
                    textLogs.Text = GetLogs();
                    container.Add(logsOpen);

                    CuiHelper.AddUi(admin, container);
                }

                private void AddCounter(List<CuiElement> _container)
                {
                    if(recorder.IsBusy) counterPoints.Text = recorder.GetMessage("InfoCurrentPath", recorder.PathCount, recorder.Distance.ToString("0"));
                    else counterPoints.Text = recorder.GetMessage("AllPaths", recorder.PathRecords.Count);
                    _container.Add(panelsOwner[5]);
                }

                private bool AddLog(string log, params object[] args)
                {
                    if(!string.IsNullOrEmpty(log))
                    {
                        int count = logs.Count;
                        if(count >= 100) logs.RemoveAt(count - 1);
                        logs.Insert(0, "[" + DateTime.Now.ToLongTimeString() + "] " + recorder.GetMessage(log, args));
                        return true;
                    }
                    return false;
                }
                private string GetLogs()
                {
                    return string.Join("\n", logs);
                }

                public void CloseUI()
                {
                    CuiHelper.DestroyUi(admin, name);
                }

                public void Destroy()
                {
                    Pool.FreeUnmanaged(ref logs);
                    Pool.FreeUnmanaged(ref container);
                }
                public static CuiRectTransformComponent GetCuiRectTransform(string anchorMin = "0 0", string anchorMax = "1 1", string offsetMin = "0 0", string offsetMax = "0 0")
                {
                    return new()
                    {
                        AnchorMin = anchorMin,
                        AnchorMax = anchorMax,
                        OffsetMin = offsetMin,
                        OffsetMax = offsetMax
                    };
                }
            }

        }
        #endregion
    }

    #region Base work - действия бота с постройкой
    public partial class NPCsController
    {
        [PluginReference]
        private Plugin Friends, Clans;

        public static class HelperAllies
        {
            public static bool IsAlly(ulong ownerId, ulong otherId, BuildingPrivlidge privilege = null)
            {
                if (ownerId == 0 || otherId == 0) return false;
                if (ownerId == otherId) return true;
                if (privilege != null && !privilege.IsDestroyed && privilege.IsAuthed(otherId)) return true;
                return IsTeammate(ownerId, otherId) || IsFriend(ownerId, otherId) || IsClanmate(ownerId, otherId);
            }

            public static bool IsTeammate(ulong a, ulong b)
            {
                RelationshipManager.PlayerTeam team = RelationshipManager.ServerInstance?.FindPlayersTeam(a);
                return team != null && team.members.Contains(b);
            }

            public static bool IsFriend(ulong a, ulong b) => Instance?.Friends?.Call("IsFriend", a.ToString(), b.ToString()) is true;

            public static bool IsClanmate(ulong a, ulong b)
            {
                Plugin clans = Instance?.Clans;
                if (clans == null) return false;
                string sa = a.ToString(), sb = b.ToString();
                return clans.Call("IsMemberOrAlly", sa, sb) is true || clans.Call("IsClanMember", sa, sb) is true;
            }
        }

        public static class HelperBotItems
        {
            public const float LootRange = 2.5f;

            public static bool InLootRange(BaseCustomNpc bot, BaseEntity container)
            {
                if (bot == null || container == null || container.IsDestroyed) return false;
                Vector3 eyes = bot.eyes != null ? bot.eyes.position : bot.transform.position + Vector3.up * 1.5f;
                return Vector3.Distance(container.ClosestPoint(eyes), eyes) <= LootRange;
            }

            public static int GiveToBot(BaseCustomNpc bot, Item item, int amount = int.MaxValue)
            {
                ItemContainer belt = bot?.inventory?.containerBelt, main = bot?.inventory?.containerMain;
                if (item == null || belt == null || main == null) return 0;
                bool toBelt = item.GetHeldEntity() is AttackEntity || item.info.category == ItemCategory.Medical;
                return Move(item, amount, toBelt ? belt : main, toBelt ? main : belt);
            }

            public static int MoveItem(Item item, ItemContainer target, int amount = int.MaxValue) => Move(item, amount, target, null);

            public static int CountOnBot(BaseCustomNpc bot, int itemId)
            {
                if (bot?.inventory == null) return 0;
                return (bot.inventory.containerMain?.GetAmount(itemId, false) ?? 0) + (bot.inventory.containerBelt?.GetAmount(itemId, false) ?? 0);
            }

            private static int Move(Item item, int amount, ItemContainer first, ItemContainer second)
            {
                if (item == null || first == null || amount <= 0) return 0;
                int take = Mathf.Min(amount, item.amount);
                ItemContainer source = item.parent;
                Item part = take < item.amount ? item.SplitItem(take) : item;
                if (part == null) return 0;
                if (!part.MoveToContainer(first) && second != null) part.MoveToContainer(second);
                bool landed = part.parent == first || (second != null && part.parent == second);
                if (landed || !part.IsValid() || part.amount <= 0) return take;
                int left = part.amount;
                if (part != item)
                {
                    item.amount += left;
                    item.MarkDirty();
                    part.Remove();
                }
                else if (part.parent != source && source != null) part.MoveToContainer(source);
                return take - left;
            }

            public static int TakeFrom(BaseCustomNpc bot, List<ItemContainer> sources, int itemId, int amount, bool toMain)
            {
                int moved = 0;
                if (sources == null) return 0;
                for (int s = 0; s < sources.Count && moved < amount; s++)
                {
                    ItemContainer source = sources[s];
                    if (source?.itemList == null) continue;
                    for (int i = source.itemList.Count - 1; i >= 0 && moved < amount; i--)
                    {
                        if (i >= source.itemList.Count) continue;
                        Item item = source.itemList[i];
                        if (item?.info == null || item.info.itemid != itemId) continue;
                        moved += toMain ? MoveItem(item, bot.inventory.containerMain, amount - moved) : GiveToBot(bot, item, amount - moved);
                    }
                }
                return moved;
            }
        }

        public sealed class BotHands
        {
            public const string CreatedMark = "npcscontroller.work-tool";

            public const float DrawSeconds = 0.5f;

            private Item _held;
            private bool _heldCreated;
            private Item _victim;
            private int _victimSlot = -1;
            private bool _borrowed;
            private ItemId _previousActive;
            private float _readyAt;

            public Item Held => _held != null && _held.IsValid() ? _held : null;

            public HeldEntity HeldEntity => Held?.GetHeldEntity() as HeldEntity;

            public bool IsReady => UnityEngine.Time.realtimeSinceStartup >= _readyAt;

            public bool Hold(BaseCustomNpc bot, ItemDefinition def, bool create)
            {
                ItemContainer belt = bot?.inventory?.containerBelt, main = bot?.inventory?.containerMain;
                if (def == null || belt == null || main == null) return false;
                Item held = Held;
                if (held != null && held.info == def && held.parent == belt)
                {
                    if (bot.GetActiveItem() != held) Equip(bot, held);
                    return true;
                }
                if (!_borrowed)
                {
                    _borrowed = true;
                    _previousActive = bot.GetActiveItem()?.uid ?? default;
                }
                PutAway(bot);
                Item item = belt.FindItemByItemID(def.itemid);
                if (item == null)
                {
                    item = main.FindItemByItemID(def.itemid);
                    bool created = false;
                    if (item == null)
                    {
                        if (!create) return false;
                        item = ItemManager.Create(def, 1, 0UL);
                        if (item == null) return false;
                        item.text = CreatedMark;
                        created = true;
                    }
                    if (!PutInBelt(bot, belt, main, item))
                    {
                        if (created) item.Remove();
                        return false;
                    }
                    _heldCreated = created;
                }
                _held = item;
                Equip(bot, item);
                return true;
            }

            public void Release(BaseCustomNpc bot)
            {
                if (!_borrowed && _held == null && _victim == null) return;
                bool alive = bot != null && bot.IsAlive() && bot.inventory?.containerBelt != null;
                Item active = alive ? bot.GetActiveItem() : null;
                bool ours = active == null || active == _held;
                if (alive && active != null && ours) bot.EquipWeapon(-1);
                PutAway(bot);
                if (alive && ours && _previousActive.IsValid)
                {
                    Item previous = bot.inventory.containerBelt.FindItemByUID(_previousActive);
                    if (previous != null) bot.EquipWeapon(previous.position, false);
                }
                _borrowed = false;
                _previousActive = default;
                _readyAt = 0f;
            }

            public static void PurgeCreated(BaseCustomNpc bot)
            {
                if (bot?.inventory == null) return;
                Purge(bot.inventory.containerBelt);
                Purge(bot.inventory.containerMain);
            }

            private static void Purge(ItemContainer container)
            {
                if (container?.itemList == null) return;
                for (int i = container.itemList.Count - 1; i >= 0; i--)
                {
                    if (i >= container.itemList.Count) continue;
                    Item item = container.itemList[i];
                    if (item == null || item.text != CreatedMark) continue;
                    item.RemoveFromContainer();
                    item.Remove();
                }
            }

            private void Equip(BaseCustomNpc bot, Item item)
            {
                bot.EquipWeapon(item.position, false);
                _readyAt = UnityEngine.Time.realtimeSinceStartup + DrawSeconds;
            }

            private bool PutInBelt(BaseCustomNpc bot, ItemContainer belt, ItemContainer main, Item item)
            {
                for (int free = 0; free < belt.capacity; free++)
                    if (belt.GetSlot(free) == null) return item.MoveToContainer(belt, free, false);
                for (int slot = belt.capacity - 1; slot >= 0; slot--)
                {
                    Item victim = belt.GetSlot(slot);
                    if (victim == null || victim.uid == _previousActive) continue;
                    if (item.parent == main)
                    {
                        item.MoveToContainer(belt, slot, false);
                        if (item.parent != belt || item.position != slot) return false;
                    }
                    else
                    {
                        if (!victim.MoveToContainer(main, -1, false)) return false;
                        if (!item.MoveToContainer(belt, slot, false))
                        {
                            victim.MoveToContainer(belt, slot, false);
                            return false;
                        }
                    }
                    _victim = victim;
                    _victimSlot = slot;
                    return true;
                }
                return false;
            }

            private void PutAway(BaseCustomNpc bot)
            {
                Item held = Held;
                bool created = _heldCreated;
                _held = null;
                _heldCreated = false;
                ItemContainer belt = bot?.inventory?.containerBelt, main = bot?.inventory?.containerMain;
                if (held != null)
                {
                    if (bot != null && bot.IsAlive() && bot.GetActiveItem() == held) bot.EquipWeapon(-1);
                    if (created)
                    {
                        held.RemoveFromContainer();
                        held.Remove();
                    }
                    else if (_victim != null && main != null && held.parent == belt) held.MoveToContainer(main, -1, false);
                }
                Item victim = _victim;
                int slot = _victimSlot;
                _victim = null;
                _victimSlot = -1;
                if (victim == null || !victim.IsValid() || belt == null || victim.parent == belt) return;
                if (slot >= 0 && slot < belt.capacity) victim.MoveToContainer(belt, slot, false);
            }
        }

        public static class HelperStandPoint
        {
            public const float EyeHeight = 1.5f;

            private static readonly float[] SurfaceGaps = { 0.6f, 1.2f };
            private static readonly float[] TopDrops = { -0.3f, 1.2f, 2.4f, 3.6f, 4.8f };
            private const int RingDirections = 12;
            private const int RouteChecks = 6;
            private static readonly List<(float score, Vector3 point)> _candidates = new List<(float, Vector3)>();

            public sealed class Search
            {
                public int Sampled, Rejected, Candidates, Routed, Pocket;
                public override string ToString() =>
                    $"on the navmesh {Sampled}, out of reach or ray blocked {Rejected}, in reach {Candidates}, route checks {Routed}, same pocket skipped {Pocket}";
            }

            public static bool TryFind(BaseCustomNpc bot, uint buildingID, BaseEntity target, float reach, out Vector3 point) =>
                TryFind(bot, buildingID, target, reach, out point, out _);

            public static bool TryFind(BaseCustomNpc bot, uint buildingID, BaseEntity target, float reach, out Vector3 point, out Search search)
            {
                point = Vector3.zero;
                search = new Search();
                HelperBuildingNavMesh store = HelperBuildingNavMesh.Instance;
                if (bot == null || target == null || target.IsDestroyed || !store.TryGet(buildingID, out var nav)) return false;
                Vector3 botPos = bot.transform.position;
                _candidates.Clear();
                if (store.TrySample(nav, target.ClosestPoint(botPos), out Vector3 near)) Add(bot, target, reach, near, botPos, search);
                if (store.TryNearestSurface(nav, target.CenterPoint(), out Vector3 surface)) Add(bot, target, reach, surface, botPos, search);
                Vector3 center = target.CenterPoint();
                float top = target.transform.TransformPoint(target.bounds.center + Vector3.up * target.bounds.extents.y).y;
                for (int k = 0; k < RingDirections; k++)
                {
                    float angle = k * Mathf.PI * 2f / RingDirections;
                    Vector3 dir = new Vector3(Mathf.Cos(angle), 0f, Mathf.Sin(angle));
                    float edge = EdgeDistance(target, dir);
                    for (int g = 0; g < SurfaceGaps.Length; g++)
                    {
                        Vector3 flat = center + dir * (edge + SurfaceGaps[g]);
                        for (int d = 0; d < TopDrops.Length; d++)
                            if (store.TrySample(nav, new Vector3(flat.x, top - TopDrops[d], flat.z), out Vector3 hit)) Add(bot, target, reach, hit, botPos, search);
                    }
                }
                search.Candidates = _candidates.Count;
                if (_candidates.Count == 0) return false;
                _candidates.Sort((a, b) => a.score.CompareTo(b.score));
                bool hasFrom = store.TrySample(nav, botPos, out Vector3 from) || store.TryNearestSurface(nav, botPos, out from);
                if (!hasFrom)
                {
                    point = _candidates[0].point;
                    return true;
                }
                for (int i = 0; i < _candidates.Count && search.Routed < RouteChecks; i++)
                {
                    Vector3 candidate = _candidates[i].point;
                    search.Routed++;
                    if (store.TryBuildRoute(nav, from, candidate, null, out _, out _) == HelperSavedNavMesh.NavPathResult.Complete)
                    {
                        point = candidate;
                        return true;
                    }
                    for (int j = _candidates.Count - 1; j > i; j--)
                        if (store.FindPathRaw(nav, candidate, _candidates[j].point, null, out _) == HelperSavedNavMesh.NavPathResult.Complete)
                        {
                            _candidates.RemoveAt(j);
                            search.Pocket++;
                        }
                }
                return false;
            }

            private static float EdgeDistance(BaseEntity target, Vector3 dir)
            {
                Vector3 local = target.transform.InverseTransformDirection(dir);
                Vector3 extents = Vector3.Scale(target.bounds.extents, target.transform.lossyScale);
                float edge = float.MaxValue;
                for (int i = 0; i < 3; i++)
                    if (Mathf.Abs(local[i]) > 0.001f) edge = Mathf.Min(edge, Mathf.Abs(extents[i] / local[i]));
                return edge == float.MaxValue ? 0f : edge;
            }

            private static void Add(BaseCustomNpc bot, BaseEntity target, float reach, Vector3 point, Vector3 botPos, Search search)
            {
                search.Sampled++;
                for (int i = 0; i < _candidates.Count; i++)
                    if ((_candidates[i].point - point).sqrMagnitude < 0.04f) return;
                if (!HelperBaseRepair.TryAim(bot, point + Vector3.up * EyeHeight, target, reach, out _, out _, out _))
                {
                    search.Rejected++;
                    return;
                }
                _candidates.Add(((point - botPos).sqrMagnitude, point));
            }
        }

        public static class HelperBaseRepair
        {
            public const int StrikeMask = 1220225809;
            public const float HealthPerHit = 50f;
            public const float WholeMargin = 1f;
            public const float BodyReach = 0.5f;
            private const float AimInset = 0.25f;

            public static bool CanRepairNow(BaseCombatEntity entity) =>
                NeedsRepair(entity, 1f) && !IsOnCooldown(entity);

            public static bool NeedsRepair(BaseCombatEntity entity, float below)
            {
                if (entity == null || entity.IsDestroyed || !entity.repair.enabled) return false;
                float max = entity.MaxHealth();
                return max > 0f && max - entity.Health() >= WholeMargin && entity.Health() / max < below;
            }

            public static bool IsOnCooldown(BaseCombatEntity entity) => entity.SecondsSinceAttacked <= entity.GetDamageRepairCooldown();

            public static List<ItemAmount> HitCost(BaseCombatEntity entity)
            {
                var result = new List<ItemAmount>();
                float max = entity.MaxHealth(), missing = max - entity.Health();
                if (max <= 0f || missing <= 0f) return result;
                List<ItemAmount> cost = entity.RepairCost(missing / max);
                if (cost == null) return result;
                float share = Mathf.Min(1f, HealthPerHit / missing);
                foreach (ItemAmount amount in cost)
                    if (amount?.itemDef != null) result.Add(new ItemAmount(amount.itemDef, Mathf.Max(1, Mathf.CeilToInt(share * amount.amount))));
                return result;
            }

            public static float StrikeReach(BaseMelee melee) => (melee != null ? melee.maxDistance : 1.5f) + BodyReach;

            public static Vector3 AimPoint(BaseEntity part, Vector3 eyes)
            {
                Vector3 center = part.CenterPoint();
                Vector3 closest = part.ClosestPoint(eyes);
                if ((closest - eyes).sqrMagnitude < 0.0001f) return center;
                return Vector3.MoveTowards(closest, center, AimInset);
            }

            public static bool IsPartOf(BaseEntity hit, BaseEntity target)
            {
                if (hit == null || target == null) return false;
                if (hit == target) return true;
                return hit is BaseCombatEntity part && part.ShouldRepairViaParent() && part.GetRepairableParent() == target;
            }

            public static bool Trace(BaseCustomNpc bot, Vector3 eyes, Vector3 aim, float reach, out BaseEntity entity, out RaycastHit hit)
            {
                entity = null;
                hit = default;
                Vector3 dir = aim - eyes;
                if (dir.sqrMagnitude < 0.0001f) return false;
                List<RaycastHit> hits = Pool.Get<List<RaycastHit>>();
                GamePhysics.TraceAll(new Ray(eyes, dir.normalized), 0f, hits, reach, StrikeMask, QueryTriggerInteraction.Ignore, bot);
                bool any = false;
                for (int i = 0; i < hits.Count; i++)
                {
                    BaseEntity hitEntity = hits[i].GetEntity();
                    if (hitEntity != null && (hitEntity == bot || hitEntity.EqualNetID(bot))) continue;
                    hit = hits[i];
                    entity = hitEntity;
                    any = true;
                    break;
                }
                Pool.FreeUnmanaged(ref hits);
                return any;
            }

            public static bool TryAim(BaseCustomNpc bot, Vector3 eyes, BaseEntity target, float reach, out Vector3 aim, out BaseEntity entity, out RaycastHit hit)
            {
                for (int i = 0; i < 3; i++)
                {
                    aim = i == 0 ? AimPoint(target, eyes) : i == 1 ? FaceCenter(target, eyes) : target.CenterPoint();
                    if (Trace(bot, eyes, aim, reach, out entity, out hit) && IsPartOf(entity, target)) return true;
                }
                aim = AimPoint(target, eyes);
                entity = null;
                hit = default;
                return false;
            }

            public static Vector3 AimFor(BaseCustomNpc bot, BaseMelee melee, BaseEntity target)
            {
                TryAim(bot, bot.eyes.position, target, StrikeReach(melee), out Vector3 aim, out _, out _);
                return aim;
            }

            private static Vector3 FaceCenter(BaseEntity part, Vector3 eyes)
            {
                Bounds bounds = part.bounds;
                Vector3 local = part.transform.InverseTransformPoint(eyes) - bounds.center;
                Vector3 extents = bounds.extents;
                int axis = 0;
                float best = -1f;
                for (int i = 0; i < 3; i++)
                {
                    if (extents[i] < 0.01f) continue;
                    float ratio = Mathf.Abs(local[i]) / extents[i];
                    if (ratio <= best) continue;
                    best = ratio;
                    axis = i;
                }
                Vector3 face = bounds.center;
                face[axis] += Mathf.Sign(local[axis]) * Mathf.Max(0f, extents[axis] - AimInset);
                return part.transform.TransformPoint(face);
            }

            public static bool Reaches(BaseCustomNpc bot, BaseMelee melee, BaseEntity target) =>
                TryAim(bot, bot.eyes.position, target, StrikeReach(melee), out _, out _, out _);

            public static void Swing(BaseCustomNpc bot, BaseMelee melee, Vector3 aim)
            {
                Vector3 dir = aim - bot.eyes.position;
                if (dir.sqrMagnitude > 0.0001f) bot.SetLookAngles(dir);
                melee.StartAttackCooldown(melee.repeatDelay * 2f);
                bot.SignalBroadcast(BaseEntity.Signal.Attack, string.Empty);
                if (melee.swingEffect.isValid) Effect.server.Run(melee.swingEffect.resourcePath, bot.transform.position, Vector3.forward, bot.net?.connection);
            }

            public static bool Strike(BaseCustomNpc bot, Hammer hammer, BaseCombatEntity target, out float restored)
            {
                restored = 0f;
                if (bot == null || hammer == null || target == null || target.IsDestroyed) return false;
                Vector3 eyes = bot.eyes.position;
                if (!TryAim(bot, eyes, target, StrikeReach(hammer), out _, out BaseEntity entity, out RaycastHit hit)) return false;
                float before = target.Health();
                HitInfo info = Pool.Get<HitInfo>();
                info.Initiator = bot;
                info.Weapon = hammer;
                info.WeaponPrefab = hammer;
                info.HitEntity = entity;
                info.PointStart = eyes;
                info.PointEnd = hit.point;
                info.HitPositionWorld = hit.point;
                info.HitNormalWorld = hit.normal;
                Collider collider = hit.GetCollider();
                info.HitMaterial = StringPool.Get(collider != null && collider.sharedMaterial != null ? collider.sharedMaterial.GetName() : "generic");
                Hit(bot, info);
                hammer.StartAttackCooldown(hammer.repeatDelay);
                Pool.Free(ref info);
                restored = target.IsDestroyed ? 0f : target.Health() - before;
                return true;
            }

            public static void Hit(BasePlayer bot, HitInfo info)
            {
                BaseCombatEntity repaired = info.HitEntity as BaseCombatEntity;
                if (repaired != null && repaired.ShouldRepairViaParent() && repaired.GetRepairableParent() is BaseCombatEntity parent) repaired = parent;
                repaired?.DoRepair(bot);
                info.DoDecals = false;
                Effect.server.ImpactEffect(info);
            }

            public static bool PrepareHitResources(BaseCustomNpc bot, BaseCombatEntity target, List<ItemContainer> sources)
            {
                foreach (ItemAmount cost in HitCost(target))
                {
                    int need = Mathf.CeilToInt(cost.amount) - HelperBotItems.CountOnBot(bot, cost.itemDef.itemid);
                    if (need <= 0) continue;
                    need -= HelperBotItems.TakeFrom(bot, sources, cost.itemDef.itemid, need, false);
                    if (need > 0) return false;
                }
                return true;
            }

            public static bool HasHitResources(BaseCustomNpc bot, BaseCombatEntity target, List<ItemContainer> sources)
            {
                foreach (ItemAmount cost in HitCost(target))
                {
                    int have = HelperBotItems.CountOnBot(bot, cost.itemDef.itemid);
                    if (sources != null)
                        foreach (ItemContainer source in sources) have += source?.GetAmount(cost.itemDef.itemid, false) ?? 0;
                    if (have < Mathf.CeilToInt(cost.amount)) return false;
                }
                return true;
            }
        }

        public static class HelperBotMedic
        {
            public const float Reach = 3.5f;

            public static bool NeedsRevive(BasePlayer patient) => patient != null && !patient.IsDestroyed && patient.IsAlive() && patient.IsWounded();

            public static bool InReach(BaseCustomNpc medic, BasePlayer patient) =>
                medic != null && patient != null && (patient.transform.position - medic.transform.position).sqrMagnitude < Reach * Reach;

            public static bool Revive(BaseCustomNpc medic, BasePlayer patient)
            {
                if (!NeedsRevive(patient) || !InReach(medic, patient)) return false;
                patient.StopWounded(medic);
                return true;
            }

            public static bool HealOther(BaseCustomNpc medic, MedicalTool tool, BasePlayer patient)
            {
                if (medic == null || tool == null || patient == null || patient.IsDestroyed || !patient.IsAlive() || !tool.canUseOnOther) return false;
                if (!InReach(medic, patient) || tool.HasAttackCooldown() || !tool.HasItemAmount()) return false;
                if (!((IMedicalToolTarget)patient).IsValidMedicalToolItem(tool.GetOwnerItemDefinition())) return false;
                Vector3 dir = patient.CenterPoint() - medic.eyes.position;
                if (dir.sqrMagnitude > 0.0001f) medic.SetLookAngles(dir);
                tool.GiveEffectsTo(medic, patient);
                tool.UseItemAmount(1);
                tool.StartAttackCooldown(tool.repeatDelay);
                medic.SignalBroadcast(BaseEntity.Signal.Attack, string.Empty);
                return true;
            }
        }

        public static class HelperBotCraft
        {
            public static bool KnowsBlueprint(ulong userId, ItemDefinition def)
            {
                ItemBlueprint bp = def?.Blueprint;
                if (bp == null || !bp.userCraftable) return false;
                if (bp.defaultBlueprint) return true;
                BasePlayer player = BasePlayer.FindByID(userId) ?? BasePlayer.FindSleeping(userId);
                List<int> unlocked = player != null ? player.PersistantPlayerInfo?.unlockedItems : ServerMgr.Instance?.persistance?.GetPlayerInfo(userId)?.unlockedItems;
                return unlocked != null && unlocked.Contains(def.itemid);
            }

            public static bool CanCraftFor(BaseCustomNpc bot, ulong ownerId, ItemBlueprint bp) =>
                bot != null && bp != null && bot.currentCraftLevel >= bp.workbenchLevelRequired && KnowsBlueprint(ownerId, bp.targetItem);

            public static int CraftableAmount(BaseCustomNpc bot, ItemBlueprint bp)
            {
                if (bot?.inventory == null || bp == null) return 0;
                int amount = Mathf.Max(1, bp.targetItem.craftingStackable);
                foreach (ItemAmount ingredient in bp.GetIngredients())
                {
                    int need = Mathf.Max(1, (int)ingredient.amount);
                    amount = Mathf.Min(amount, HelperBotItems.CountOnBot(bot, ingredient.itemid) / need);
                }
                return amount;
            }

            public static bool GatherIngredients(BaseCustomNpc bot, ItemBlueprint bp, int amount, List<ItemContainer> sources)
            {
                bool all = true;
                foreach (ItemAmount ingredient in bp.GetIngredients())
                {
                    int need = (int)ingredient.amount * amount - HelperBotItems.CountOnBot(bot, ingredient.itemid);
                    need -= HelperBotItems.TakeFrom(bot, sources, ingredient.itemid, need, true);
                    if (need > 0) all = false;
                }
                return all;
            }

            public static bool HasIngredients(BaseCustomNpc bot, ItemBlueprint bp, int amount, List<ItemContainer> sources)
            {
                foreach (ItemAmount ingredient in bp.GetIngredients())
                {
                    int have = HelperBotItems.CountOnBot(bot, ingredient.itemid);
                    if (sources != null)
                        foreach (ItemContainer source in sources) have += source?.GetAmount(ingredient.itemid, false) ?? 0;
                    if (have < (int)ingredient.amount * amount) return false;
                }
                return true;
            }

            public static bool Queue(BaseCustomNpc bot, ItemBlueprint bp, int amount) =>
                bot?.inventory?.crafting != null && bot.inventory.crafting.CraftItem(bp, bot, null, amount);

            public static bool IsCrafting(BaseCustomNpc bot) => bot?.inventory?.crafting != null && bot.inventory.crafting.queue.Count > 0;

            public static void Tick(BaseCustomNpc bot, float delta)
            {
                if (IsCrafting(bot)) bot.inventory.crafting.ServerUpdate(delta);
            }

            public static void CancelAll(BaseCustomNpc bot)
            {
                if (IsCrafting(bot)) bot.inventory.crafting.CancelAll();
            }
        }

        public static class HelperBaseDefense
        {
            private static ItemDefinition _lowGradeFuel;
            private static ItemDefinition LowGradeFuel => _lowGradeFuel != null ? _lowGradeFuel : _lowGradeFuel = ItemManager.FindItemDefinition("lowgradefuel");

            public static bool IsDefense(BaseEntity entity) => entity is AutoTurret || entity is GunTrap || entity is FlameTurret;

            public static bool GetCharge(BaseEntity defense, out ItemDefinition ammo, out int loaded)
            {
                ammo = null;
                loaded = 0;
                switch (defense)
                {
                    case AutoTurret turret:
                        BaseProjectile weapon = turret.GetAttachedWeapon();
                        if (weapon?.primaryMagazine == null || turret.inventory == null) return false;
                        ammo = weapon.primaryMagazine.ammoType;
                        loaded = turret.GetTotalAmmo();
                        return ammo != null;
                    case GunTrap trap:
                        ammo = trap.ammoType;
                        loaded = ammo != null && trap.inventory != null ? trap.inventory.GetAmount(ammo.itemid, false) : 0;
                        return ammo != null && trap.inventory != null;
                    case FlameTurret flame:
                        ammo = LowGradeFuel;
                        loaded = ammo != null && flame.inventory != null ? flame.inventory.GetAmount(ammo.itemid, false) : 0;
                        return ammo != null && flame.inventory != null;
                }
                return false;
            }

            public static int Missing(BaseEntity defense, int target, out ItemDefinition ammo)
            {
                if (defense == null || defense.IsDestroyed || !GetCharge(defense, out ammo, out int loaded)) { ammo = null; return 0; }
                return Mathf.Max(0, target - loaded);
            }

            public static int Refill(BaseCustomNpc bot, BaseEntity defense, int target)
            {
                int missing = Missing(defense, target, out ItemDefinition ammo);
                if (missing <= 0 || bot?.inventory == null) return 0;
                ItemContainer into = (defense as StorageContainer)?.inventory ?? (defense as ContainerIOEntity)?.inventory;
                if (into == null) return 0;
                int moved = 0;
                ItemContainer[] from = { bot.inventory.containerMain, bot.inventory.containerBelt };
                foreach (ItemContainer container in from)
                {
                    if (container?.itemList == null) continue;
                    for (int i = container.itemList.Count - 1; i >= 0 && moved < missing; i--)
                    {
                        if (i >= container.itemList.Count) continue;
                        Item item = container.itemList[i];
                        if (item?.info == null || item.info != ammo) continue;
                        moved += HelperBotItems.MoveItem(item, into, missing - moved);
                    }
                }
                if (moved > 0 && defense is AutoTurret turret)
                {
                    turret.Reload();
                    turret.SendNetworkUpdate();
                }
                return moved;
            }
        }
    }
    #endregion
}
namespace Oxide.Plugins.NPCsControllerEx
{
    using Color = UnityEngine.Color;
    using IAIPathNode = Oxide.Plugins.NPCsController.IAIPathNode;
    using NodeHint = Oxide.Plugins.NPCsController.NodeHint;

    public static class HelperMap
    {
        public static readonly int GroundLayers = LayerMask.GetMask("Terrain", "World", "Default", "Construction", "Deployed");
        public const float BodyGroundRayLength = 2f;

        private const float ConnectivityProbeRange = 150f;
        private const int ConnectivityDirections = 4;
        private const float ConnectivityProbeSnap = 30f;
        private const float ConnectivityMinEscape = 50f;
        private static RustNavMeshPath _connectivityPath;

        public static bool IsConnectedToWorld(Vector3 position, int agentTypeID)
        {
            int areaMask = 1 << NavMesh.GetAreaFromName("Walkable");
            if(!SampleNavTyped(position, 2f, agentTypeID, areaMask, out Vector3 start)) return false;
            _connectivityPath ??= new RustNavMeshPath();
            for(int i = 0; i < ConnectivityDirections; i++)
            {
                float angle = Mathf.PI * 2f * i / ConnectivityDirections;
                Vector3 probe = position + new Vector3(Mathf.Cos(angle), 0f, Mathf.Sin(angle)) * ConnectivityProbeRange;
                ToGroundPoint(ref probe);
                if(!SampleNavTyped(probe, ConnectivityProbeSnap, agentTypeID, areaMask, out Vector3 end)) continue;
                if(Vector3Ex.Distance2D(end, start) < ConnectivityMinEscape) continue;
                if(!CalculateNavPathTyped(start, end, agentTypeID, areaMask, _connectivityPath)) continue;
                if(_connectivityPath.status == NavMeshPathStatus.PathComplete) return true;
            }
            return false;
        }

        public static bool SampleNavTyped(Vector3 position, float radius, int agentTypeID, int areaMask, out Vector3 onMesh)
        {
            onMesh = position;
            if(!Rust.Ai.Gen2.RustNavMeshHelpers.SamplePosition(position, out NavMeshHit hit, radius, areaMask)) return false;
            onMesh = hit.position;
            return true;
        }

        public static bool CalculateNavPathTyped(Vector3 from, Vector3 to, int agentTypeID, int areaMask, RustNavMeshPath path)
            => Rust.Ai.Gen2.RustNavMeshHelpers.CalculatePath(from, to, areaMask, path);

        public static bool NavPathCompleteTyped(Vector3 from, Vector3 to, float sampleRadius, int agentTypeID, int areaMask)
        {
            Vector3 onFrom, onTo;
            if(!SampleNavTyped(from, sampleRadius, agentTypeID, areaMask, out onFrom)) return false;
            if(!SampleNavTyped(to, sampleRadius, agentTypeID, areaMask, out onTo)) return false;
            _connectivityPath ??= new RustNavMeshPath();
            if(!CalculateNavPathTyped(onFrom, onTo, agentTypeID, areaMask, _connectivityPath)) return false;
            return _connectivityPath.status == NavMeshPathStatus.PathComplete;
        }

        public static bool TryGetRandomMapPoint(float cycle, out Vector3 result)
        {
            result = Vector3.zero;
            int areaMask = 1 << NavMesh.GetAreaFromName("Walkable");

            while (cycle > 0)
            {
                cycle--;
                Vector3 size = TerrainMeta.Size / 2f;
                float x = Random.Range(-size.x, size.x);
                float z = Random.Range(-size.z, size.z);
                Vector3 position = new Vector3(x, 0, z);
                ToGroundPoint(ref position);
                if (Rust.Ai.Gen2.RustNavMeshHelpers.SamplePosition(position, out var hit, 1f, areaMask))
                {
                    position = hit.position;
                }
                else continue;

                bool noWater = !WaterLevel.Test(position, true, true) && Physics.OverlapSphere(position, 10f, LayerMask.GetMask("Water")).Length == 0;
                bool noMonuments = Physics.OverlapSphere(position, 50f, LayerMask.GetMask("Prevent Building")).Length == 0;
                bool noCupboards = Physics.OverlapSphere(position, 50f, LayerMask.GetMask("Default", "Construction", "Deployed")).Where((x) => x.ToBaseEntity() is BuildingPrivlidge).Count == 0;
                bool noPlayers = Physics.OverlapSphere(position, 50f, LayerMask.GetMask("Player (Server)", "Player Movement")).Length == 0;

                bool noIceAndCliffs = true;

                foreach (var collider in Physics.OverlapSphere(position, 5f, LayerMask.GetMask("Default", "World")))
                {
                    if (collider.name.Contains("ice_sheet") || collider.name.Contains("iceberg") || collider.name.Contains("shore_ice") || collider.name.Contains("cliff") || collider.name.Contains("rocks") || collider.name.Contains("rock_formation"))
                    {
                        noIceAndCliffs = false;
                        break;
                    }
                }

                if (noWater && noCupboards && noMonuments && noPlayers && noIceAndCliffs
                    && IsConnectedToWorld(position, NPCsController.BaseCustomNpc.NavAgentTypeID))
                {
                    result = position;
                    break;
                }
            }

            return result != Vector3.zero;
        }

        public static bool TryGetGroundUnderBody(BasePlayer player, int layerMask, float maxDistance, out Vector3 ground)
        {
            ground = Vector3.zero;
            if (player == null) return false;
            if (!Physics.Raycast(player.GetCenter(), Vector3.down, out var hit, maxDistance, layerMask, QueryTriggerInteraction.Ignore)) return false;
            ground = hit.point;
            return true;
        }

        public static bool TryGetGroundUnderBody(BasePlayer player, out Vector3 ground)
            => TryGetGroundUnderBody(player, GroundLayers, BodyGroundRayLength, out ground);

        public static bool SetHeight(ref Vector3 position, float upHeight, float checkHeight, int layerMask, QueryTriggerInteraction queryTriggerInteraction)
        {
            if (Physics.Raycast(position + Vector3.up * upHeight, Vector3.down, out var hit, checkHeight, layerMask, queryTriggerInteraction))
            {
                position = hit.point;
                return true;
            }
            return false;
        }

        public static void ToGroundPoint(ref Vector3 position, float height = 200f)
        {
            position.y = TerrainMeta.HeightMap.GetHeight(position);
            SetHeight(ref position, height, height, LayerMask.GetMask("Terrain", "World", "Default", "Construction"), QueryTriggerInteraction.Ignore);
        }

        public static bool IsInTerrain(Vector3 position, float radius, float distance = 3f)
        {
            List<RaycastHit> obj = Pool.Get<List<RaycastHit>>();
            GamePhysics.TraceAllUnordered(new Ray(position + Vector3.up * 1f, Vector3.down), radius, obj, distance, LayerMask.GetMask("Terrain", "World", "Default", "Construction", "Prevent Building"), QueryTriggerInteraction.Ignore);
            float terrain_y = -float.MaxValue;
            float col_y = -float.MaxValue;
            foreach (RaycastHit current in obj)
            {
                if (current.GetCollider() is Collider collider)
                {
                    if (collider.gameObject.HasCustomTag(GameObjectTag.BlockBarricadePlacement))
                    {
                        Pool.FreeUnmanaged(ref obj);
                        return false;
                    }

                    if (collider.gameObject.HasCustomTag(GameObjectTag.Road))
                    {
                        Pool.FreeUnmanaged(ref obj);
                        return false;
                    }

                    bool initialContact = current.distance <= 0f;
                    if (collider.CompareTag("Main Terrain"))
                    {
                        float height = initialContact ? TerrainMeta.HeightMap.GetHeight(position) : current.point.y;
                        if (height > terrain_y) terrain_y = height;
                        continue;
                    }
                    float colliderHeight = initialContact ? position.y + 1f : current.point.y;
                    if (colliderHeight > col_y) col_y = colliderHeight;
                }
            }
            Pool.FreeUnmanaged(ref obj);
            return (position.y >= terrain_y - 0.1f) && (terrain_y > col_y + 3);
        }

        public static bool IsOnStaticSupport(Vector3 point, int layerMask)
        {
            if (!Physics.Raycast(point + Vector3.up * 0.25f, Vector3.down, out var hit, 0.75f, layerMask, QueryTriggerInteraction.Ignore)) return false;
            BaseEntity entity = hit.GetEntity();
            return entity == null || entity is BuildingBlock;
        }

        public static bool DoCheckSphereTag(Vector3 position, float radius, GameObjectTag tag, params string[] layers)
        {
            List<Collider> obj = Pool.Get<List<Collider>>();
            GamePhysics.OverlapSphere(position, radius, obj, LayerMask.GetMask(layers), QueryTriggerInteraction.Collide);
            bool flag = false;
            for (int i = 0; i < obj.Count; i++)
            {
                Collider collider = obj[i];
                if (collider != null && collider.gameObject.HasCustomTag(tag))
                {
                    flag = true;
                    break;
                }
            }
            Pool.FreeUnmanaged(ref obj);
            return flag;
        }

        public enum RestorePositionCheck
        {
            Ok,
            ZeroPosition,
            OutOfMapBounds,
            UnderTerrain,
            NoNavmesh,
            Isolated,
        }
        public static RestorePositionCheck CheckRestorePosition(Vector3 position, out float terrainY, float navRadius = 3f, float maxUnderTerrain = 1.5f)
        {
            terrainY = 0f;
            if (position == Vector3.zero) return RestorePositionCheck.ZeroPosition;
            if (TerrainMeta.HeightMap == null) return RestorePositionCheck.Ok;
            Vector3 half = TerrainMeta.Size / 2f;
            if (Mathf.Abs(position.x) > half.x || Mathf.Abs(position.z) > half.z) return RestorePositionCheck.OutOfMapBounds;
            terrainY = TerrainMeta.HeightMap.GetHeight(position);
            if (position.y < terrainY - maxUnderTerrain) return RestorePositionCheck.UnderTerrain;
            int areaMask = 1 << NavMesh.GetAreaFromName("Walkable");
            if (!Rust.Ai.Gen2.RustNavMeshHelpers.SamplePosition(position, out _, navRadius, areaMask)) return RestorePositionCheck.NoNavmesh;
            if (!IsConnectedToWorld(position, NPCsController.BaseCustomNpc.NavAgentTypeID)) return RestorePositionCheck.Isolated;
            return RestorePositionCheck.Ok;
        }

        private static readonly float[] ConnectedNearRadii = { 2f, 4f, 7f, 11f, 16f, 22f, 30f };
        private const float ConnectedNearArcStep = 5f;
        private const int ConnectedNearMaxChecks = 24;

        public static bool TryFindConnectedPointNear(Vector3 position, float maxRadius, out Vector3 point)
        {
            point = Vector3.zero;
            if (TerrainMeta.HeightMap == null) return false;
            int agentTypeID = NPCsController.BaseCustomNpc.NavAgentTypeID;
            int areaMask = 1 << NavMesh.GetAreaFromName("Walkable");
            List<Vector3> tried = Pool.Get<List<Vector3>>();
            int checks = 0;
            bool found = false;
            float bestSqr = float.MaxValue;
            try
            {
                for (int r = 0; r < ConnectedNearRadii.Length && !found && checks < ConnectedNearMaxChecks; r++)
                {
                    float radius = ConnectedNearRadii[r];
                    if (radius > maxRadius) break;
                    int count = Mathf.Clamp(Mathf.CeilToInt(2f * Mathf.PI * radius / ConnectedNearArcStep), 8, 24);
                    for (int i = 0; i < count && checks < ConnectedNearMaxChecks; i++)
                    {
                        float angle = Mathf.PI * 2f * i / count;
                        Vector3 probe = position + new Vector3(Mathf.Cos(angle), 0f, Mathf.Sin(angle)) * radius;
                        ToGroundPoint(ref probe);
                        if (!SampleNavTyped(probe, 2f, agentTypeID, areaMask, out Vector3 onMesh)) continue;
                        bool seen = false;
                        for (int k = 0; k < tried.Count && !seen; k++) seen = (tried[k] - onMesh).sqrMagnitude < 2.25f;
                        if (seen) continue;
                        tried.Add(onMesh);
                        checks++;
                        if (!IsConnectedToWorld(onMesh, agentTypeID)) continue;
                        float sqr = (onMesh - position).sqrMagnitude;
                        if (sqr >= bestSqr) continue;
                        bestSqr = sqr;
                        point = onMesh;
                        found = true;
                    }
                }
            }
            finally
            {
                Pool.FreeUnmanaged(ref tried);
            }
            return found;
        }

        public class PointMapNode : IAIPathNode
        {
            private Vector3 position;
            private readonly bool _valid;
            public NodeHint Hint { get; private set; }

            public PointMapNode(Vector3 position, NodeHint hint = NodeHint.None)
            {
                this.position = position;
                _valid = true;
                Hint = hint;
            }

            private readonly HashSet<IAIPathNode> _linked = new();
            private List<Oxide.Plugins.NPCsController.PathEdge> _edges;
            public Vector3 Position => position;
            public bool Straightaway => false;
            public IEnumerable<IAIPathNode> Linked => _linked;
            public IEnumerable<Oxide.Plugins.NPCsController.PathEdge> Edges => _edges ?? (IEnumerable<Oxide.Plugins.NPCsController.PathEdge>)System.Array.Empty<Oxide.Plugins.NPCsController.PathEdge>();

            public Door LinkedDoor { get; set; }
            public PressButton LinkedButton { get; set; }
            public BaseLock LinkedLock { get; set; }
            public Collider LinkedLadderTrigger { get; set; }

            public void AddLink(IAIPathNode link)
            {
                _linked.Add(link);
            }

            public void AddEdge(Oxide.Plugins.NPCsController.PathEdge edge)
            {
                if (edge.Target == null) return;
                _edges ??= new List<Oxide.Plugins.NPCsController.PathEdge>();
                _edges.Add(edge);
            }

            public bool RemoveEdge(IAIPathNode target)
            {
                if (_edges == null || target == null) return false;
                for (int i = 0; i < _edges.Count; i++)
                {
                    if (ReferenceEquals(_edges[i].Target, target))
                    {
                        _edges.RemoveAt(i);
                        return true;
                    }
                }
                return false;
            }

            public bool IsValid()
            {
                return _valid;
            }

            public const float StepSize = 0.5f;

            public static implicit operator PointMapNode(Vector3 pos)
            {
                return new(pos);
            }
        }
    }

    public static class HelperSafeZones
    {
        public const float DefaultMargin = 3f;
        public const float TurretRangeTolerance = 1f;
        public const float TurretMargin = 4f;
        private const float RefreshInterval = 1f;
        private const float TurretRefreshInterval = 10f;
        private const float TurretSearchPadding = 20f;
        private const float TurretEscapeExtra = 1f;
        private static readonly float[] EscapeAngles = { 0f, 45f, -45f, 90f, -90f, 135f, -135f, 180f };
        private const float Epsilon = 1e-6f;

        public static int EscapeVariantCount => EscapeAngles.Length;

        private struct Zone
        {
            public AutoTurret Turret;
            public bool IsSphere;
            public Vector3 Center;
            public Quaternion Rotation;
            public Quaternion InverseRotation;
            public Vector3 HalfExtents;
            public float Radius;
            public float BoundRadius;
            public float MinY;
            public float MaxY;
        }

        private static readonly List<Zone> _zones = new List<Zone>();
        private static readonly List<Zone> _turrets = new List<Zone>();
        private static readonly List<AutoTurret> _notedTurrets = new List<AutoTurret>();
        private static readonly List<AutoTurret> _turretQuery = new List<AutoTurret>();
        private static float _nextRefresh = float.MinValue;
        private static float _nextTurretRefresh = float.MinValue;
        private static int _sourceCount = -1;

        public static int Count
        {
            get
            {
                Refresh();
                return _zones.Count + _turrets.Count;
            }
        }

        public static void OnUnloadPlugin()
        {
            _zones.Clear();
            _turrets.Clear();
            _notedTurrets.Clear();
            _turretQuery.Clear();
            _nextRefresh = float.MinValue;
            _nextTurretRefresh = float.MinValue;
            _sourceCount = -1;
        }

        public static bool IsPointInside(Vector3 point, float margin = DefaultMargin, bool withTurrets = true)
        {
            Refresh();
            int count = withTurrets ? AreaCount : _zones.Count;
            for (int i = 0; i < count; i++)
            {
                GetArea(i, margin, out Zone area, out float areaMargin);
                if (Contains(area, point, areaMargin) && IsActive(area)) return true;
            }
            return false;
        }

        public static bool IsTargetBlocked(Vector3 origin, Vector3 target, float margin = DefaultMargin)
        {
            Refresh();
            int count = AreaCount;
            for (int i = 0; i < count; i++)
            {
                GetArea(i, margin, out Zone area, out float areaMargin);
                float m = Contains(area, origin, areaMargin) ? 0f : areaMargin;
                if (Contains(area, target, m) && IsActive(area)) return true;
            }
            return false;
        }

        public static bool SegmentEnters(Vector3 origin, Vector3 a, Vector3 b, out Vector3 entry, float margin = DefaultMargin)
        {
            entry = Vector3.zero;
            Refresh();
            float best = float.MaxValue;
            int count = AreaCount;
            for (int i = 0; i < count; i++)
            {
                GetArea(i, margin, out Zone area, out float areaMargin);
                if (!NearSegment(area, a, b, areaMargin) || !IsActive(area)) continue;
                if (Contains(area, origin, 0f)) continue;
                float m = areaMargin > 0f && Contains(area, origin, areaMargin) ? 0f : areaMargin;
                float t = SegmentEntry(area, a, b, m);
                if (t >= 0f && t < best) best = t;
            }
            if (best == float.MaxValue) return false;
            entry = Vector3.Lerp(a, b, best);
            return true;
        }

        public static bool IsWayBlocked(Vector3 origin, Vector3 target, float margin = DefaultMargin)
        {
            return IsTargetBlocked(origin, target, margin) || SegmentEnters(origin, origin, target, out _, margin);
        }

        public static bool IsInTurretRange(Vector3 point, float extra = 0f)
        {
            Refresh();
            for (int i = 0; i < _turrets.Count; i++)
            {
                Zone area = _turrets[i];
                if (Contains(area, point, extra) && IsTurretActive(area.Turret)) return true;
            }
            return false;
        }

        public static AutoTurret FindTurretInRange(Vector3 point, out float distance)
        {
            Refresh();
            distance = 0f;
            AutoTurret best = null;
            float bestSqr = float.MaxValue;
            for (int i = 0; i < _turrets.Count; i++)
            {
                Zone area = _turrets[i];
                if (!Contains(area, point, 0f) || !IsTurretActive(area.Turret)) continue;
                float sqr = (point - area.Center).sqrMagnitude;
                if (sqr >= bestSqr) continue;
                bestSqr = sqr;
                best = area.Turret;
            }
            if (best != null) distance = Mathf.Sqrt(bestSqr);
            return best;
        }

        public static void NoteTurret(AutoTurret turret)
        {
            if (!IsMonumentTurret(turret)) return;
            for (int i = 0; i < _notedTurrets.Count; i++)
            {
                if (ReferenceEquals(_notedTurrets[i], turret)) return;
            }
            _notedTurrets.Add(turret);
            AddTurret(turret);
        }

        public static string DescribeDanger(Vector3 point, float margin = DefaultMargin)
        {
            Refresh();
            const float edge = 0.5f;
            for (int i = 0; i < _zones.Count; i++)
            {
                if (Contains(_zones[i], point, margin + edge)) return "safe zone";
            }
            for (int i = 0; i < _turrets.Count; i++)
            {
                Zone area = _turrets[i];
                if (Contains(area, point, TurretMargin + edge) && IsTurretActive(area.Turret)) return "monument turret range";
            }
            return "safe zone";
        }

        public static bool TryGetEscapePoint(Vector3 point, out Vector3 exit, float zoneMargin, int variant)
        {
            exit = point;
            Refresh();
            if (variant < 0) variant = 0;
            Vector3 start;
            Vector3 dir;
            if (TryGetExitPoint(point, out Vector3 zoneExit, zoneMargin, variant))
            {
                start = zoneExit;
                dir = zoneExit - point;
            }
            else
            {
                if (!TryGetTurretEscapeDirection(point, out dir)) return false;
                dir = Quaternion.Euler(0f, EscapeAngles[variant % EscapeAngles.Length], 0f) * dir;
                start = point;
            }
            dir.y = 0f;
            exit = start;
            if (dir.sqrMagnitude < Epsilon) return true;
            if (PushOutOfTurrets(ref exit, dir.normalized) && TerrainMeta.HeightMap != null)
                exit.y = TerrainMeta.HeightMap.GetHeight(exit);
            return true;
        }

        private static bool TryGetTurretEscapeDirection(Vector3 point, out Vector3 dir)
        {
            dir = Vector3.zero;
            bool inRange = false;
            for (int i = 0; i < _turrets.Count; i++)
            {
                Zone area = _turrets[i];
                if (!Contains(area, point, 0f) || !IsTurretActive(area.Turret)) continue;
                inRange = true;
                Vector3 away = point - area.Center;
                away.y = 0f;
                float distance = away.magnitude;
                if (distance < Epsilon) continue;
                dir += away / distance * (area.Radius - distance + 1f);
            }
            if (!inRange) return false;
            dir.y = 0f;
            if (dir.sqrMagnitude < Epsilon) dir = Vector3.forward;
            dir.Normalize();
            return true;
        }

        private static bool PushOutOfTurrets(ref Vector3 point, Vector3 dir)
        {
            bool pushed = false;
            float margin = TurretMargin + TurretEscapeExtra;
            for (int pass = 0; pass <= _turrets.Count; pass++)
            {
                bool moved = false;
                for (int i = 0; i < _turrets.Count; i++)
                {
                    Zone area = _turrets[i];
                    if (!IsTurretActive(area.Turret)) continue;
                    Vector3 offset = point - area.Center;
                    float radius = area.Radius + margin;
                    float sectionSqr = radius * radius - offset.y * offset.y;
                    if (sectionSqr <= 0f) continue;
                    offset.y = 0f;
                    float c = offset.sqrMagnitude - sectionSqr;
                    if (c >= 0f) continue;
                    float b = Vector3.Dot(offset, dir);
                    point += dir * (-b + Mathf.Sqrt(b * b - c) + 0.1f);
                    moved = true;
                }
                if (!moved) break;
                pushed = true;
            }
            return pushed;
        }

        public static bool TryGetExitPoint(Vector3 point, out Vector3 exit, float margin = DefaultMargin, int variant = 0)
        {
            exit = point;
            Refresh();
            if (variant < 0) variant = 0;
            for (int i = 0; i < _zones.Count; i++)
            {
                Zone zone = _zones[i];
                if (!Contains(zone, point, ExitSearchTolerance)) continue;
                Vector3 world;
                if (zone.IsSphere)
                {
                    Vector3 flat = point - zone.Center;
                    flat.y = 0f;
                    if (flat.sqrMagnitude < Epsilon) flat = Vector3.forward;
                    flat = Quaternion.Euler(0f, 90f * (variant % 4), 0f) * flat.normalized;
                    float dy = point.y - zone.Center.y;
                    float sectionSqr = zone.Radius * zone.Radius - dy * dy;
                    float section = sectionSqr > 0f ? Mathf.Sqrt(sectionSqr) : 0f;
                    world = zone.Center + flat * (section + margin);
                }
                else
                {
                    Vector3 local = zone.InverseRotation * (point - zone.Center);
                    float d0 = zone.HalfExtents.x - local.x, d1 = zone.HalfExtents.x + local.x;
                    float d2 = zone.HalfExtents.z - local.z, d3 = zone.HalfExtents.z + local.z;
                    int face = NthNearestFace(d0, d1, d2, d3, variant % 4);
                    if (face == 0) local.x = zone.HalfExtents.x + margin;
                    else if (face == 1) local.x = -zone.HalfExtents.x - margin;
                    else if (face == 2) local.z = zone.HalfExtents.z + margin;
                    else local.z = -zone.HalfExtents.z - margin;
                    world = zone.Center + zone.Rotation * local;
                }
                exit = new Vector3(world.x, point.y, world.z);
                return true;
            }
            return false;
        }
        private const float ExitSearchTolerance = 1f;

        private static int NthNearestFace(float d0, float d1, float d2, float d3, int n)
        {
            int used = 0;
            int face = 0;
            for (int pass = 0; pass <= n; pass++)
            {
                float best = float.MaxValue;
                for (int f = 0; f < 4; f++)
                {
                    if ((used & (1 << f)) != 0) continue;
                    float d = f == 0 ? d0 : f == 1 ? d1 : f == 2 ? d2 : d3;
                    if (d < best)
                    {
                        best = d;
                        face = f;
                    }
                }
                used |= 1 << face;
            }
            return face;
        }

        private static int AreaCount => _zones.Count + _turrets.Count;

        private static void GetArea(int index, float margin, out Zone area, out float areaMargin)
        {
            if (index < _zones.Count)
            {
                area = _zones[index];
                areaMargin = margin;
                return;
            }
            area = _turrets[index - _zones.Count];
            areaMargin = margin > 0f ? TurretMargin : 0f;
        }
        private static bool IsActive(Zone area) => area.Turret is null || IsTurretActive(area.Turret);

        private static bool IsMonumentTurret(AutoTurret turret) => turret is not null && !turret.IsDestroyed && turret.OwnerID == 0;

        private static bool IsTurretActive(AutoTurret turret) => turret is not null && !turret.IsDestroyed && turret.IsOn();

        private static void AddTurret(AutoTurret turret)
        {
            if (!IsMonumentTurret(turret) || turret.sightRange <= 0f) return;
            for (int i = 0; i < _turrets.Count; i++)
            {
                if (ReferenceEquals(_turrets[i].Turret, turret)) return;
            }
            Zone area = default;
            area.Turret = turret;
            area.IsSphere = true;
            area.Center = turret.eyePos != null ? turret.eyePos.position : turret.transform.position;
            area.Rotation = Quaternion.identity;
            area.InverseRotation = Quaternion.identity;
            area.Radius = turret.sightRange + TurretRangeTolerance;
            area.BoundRadius = area.Radius;
            area.MinY = float.NegativeInfinity;
            area.MaxY = float.PositiveInfinity;
            _turrets.Add(area);
        }

        private static void RefreshTurrets(List<TriggerSafeZone> source, int count)
        {
            _turrets.Clear();
            if (BaseEntity.Query.Server != null)
            {
                for (int i = 0; i < count; i++)
                {
                    TriggerSafeZone trigger = source[i];
                    if (trigger == null) continue;
                    Collider collider = trigger.triggerCollider;
                    if (collider == null || !collider.enabled) continue;
                    Bounds bounds = collider.bounds;
                    _turretQuery.Clear();
                    BaseEntity.Query.Server.GetInSphere(bounds.center, bounds.extents.magnitude + TurretSearchPadding, _turretQuery,
                        BaseEntity.Query.DistanceCheckType.OnlyCenter);
                    for (int j = 0; j < _turretQuery.Count; j++) AddTurret(_turretQuery[j]);
                }
                _turretQuery.Clear();
            }
            for (int i = _notedTurrets.Count - 1; i >= 0; i--)
            {
                AutoTurret turret = _notedTurrets[i];
                if (!IsMonumentTurret(turret))
                {
                    _notedTurrets.RemoveAt(i);
                    continue;
                }
                AddTurret(turret);
            }
        }

        private static void Refresh()
        {
            List<TriggerSafeZone> source = TriggerSafeZone.allSafeZones;
            int count = source != null ? source.Count : 0;
            float now = UnityEngine.Time.time;
            bool sourceChanged = count != _sourceCount;
            if (sourceChanged || now >= _nextTurretRefresh)
            {
                _nextTurretRefresh = now + TurretRefreshInterval;
                RefreshTurrets(source, count);
            }
            if (now < _nextRefresh && !sourceChanged) return;
            _nextRefresh = now + RefreshInterval;
            _sourceCount = count;
            _zones.Clear();
            BaseGameMode mode = BaseGameMode.GetActiveGameMode(true);
            if (mode != null && !mode.safeZone) return;
            for (int i = 0; i < count; i++)
            {
                TriggerSafeZone trigger = source[i];
                if (trigger == null) continue;
                Collider collider = trigger.triggerCollider;
                if (collider == null || !collider.enabled) continue;
                Transform t = collider.transform;
                Vector3 scale = t.lossyScale;
                scale = new Vector3(Mathf.Abs(scale.x), Mathf.Abs(scale.y), Mathf.Abs(scale.z));
                Zone zone = default;
                zone.Rotation = Quaternion.identity;
                if (collider is SphereCollider sphere)
                {
                    zone.IsSphere = true;
                    zone.Center = t.TransformPoint(sphere.center);
                    zone.Radius = sphere.radius * Mathf.Max(scale.x, Mathf.Max(scale.y, scale.z));
                    zone.BoundRadius = zone.Radius;
                }
                else if (collider is BoxCollider box)
                {
                    zone.Center = t.TransformPoint(box.center);
                    zone.Rotation = t.rotation;
                    zone.HalfExtents = Vector3.Scale(box.size * 0.5f, scale);
                    zone.BoundRadius = zone.HalfExtents.magnitude;
                }
                else
                {
                    Bounds bounds = collider.bounds;
                    zone.Center = bounds.center;
                    zone.HalfExtents = bounds.extents;
                    zone.BoundRadius = bounds.extents.magnitude;
                }
                zone.InverseRotation = Quaternion.Inverse(zone.Rotation);
                float pivotY = trigger.transform.position.y;
                zone.MinY = trigger.maxDepth != -1f ? pivotY - trigger.maxDepth : float.NegativeInfinity;
                zone.MaxY = trigger.maxAltitude != -1f ? pivotY + trigger.maxAltitude : float.PositiveInfinity;
                _zones.Add(zone);
            }
        }

        private static bool Contains(Zone zone, Vector3 point, float margin)
        {
            if (point.y < zone.MinY - margin || point.y > zone.MaxY + margin) return false;
            Vector3 offset = point - zone.Center;
            if (zone.IsSphere)
            {
                float r = zone.Radius + margin;
                return offset.sqrMagnitude <= r * r;
            }
            float bound = zone.BoundRadius + margin;
            if (offset.sqrMagnitude > bound * bound) return false;
            Vector3 local = zone.InverseRotation * offset;
            return Mathf.Abs(local.x) <= zone.HalfExtents.x + margin
                && Mathf.Abs(local.y) <= zone.HalfExtents.y + margin
                && Mathf.Abs(local.z) <= zone.HalfExtents.z + margin;
        }

        private static float SegmentEntry(Zone zone, Vector3 a, Vector3 b, float margin)
        {
            Vector3 ab = b - a;
            float lengthSqr = ab.sqrMagnitude;
            if (lengthSqr < Epsilon) return Contains(zone, a, margin) ? 0f : -1f;
            if (!NearSegment(zone, a, b, margin)) return -1f;

            float t0 = 0f, t1 = 1f;
            if (!ClipSlab(a.y, ab.y, zone.MinY - margin, zone.MaxY + margin, ref t0, ref t1)) return -1f;
            if (zone.IsSphere)
            {
                float r = zone.Radius + margin;
                Vector3 f = a - zone.Center;
                float half = Vector3.Dot(f, ab);
                float c = f.sqrMagnitude - r * r;
                float disc = half * half - lengthSqr * c;
                if (disc < 0f) return -1f;
                float root = Mathf.Sqrt(disc);
                t0 = Mathf.Max(t0, (-half - root) / lengthSqr);
                t1 = Mathf.Min(t1, (-half + root) / lengthSqr);
                return t0 <= t1 ? t0 : -1f;
            }
            Vector3 localA = zone.InverseRotation * (a - zone.Center);
            Vector3 localAb = zone.InverseRotation * ab;
            if (!ClipSlab(localA.x, localAb.x, -zone.HalfExtents.x - margin, zone.HalfExtents.x + margin, ref t0, ref t1)) return -1f;
            if (!ClipSlab(localA.y, localAb.y, -zone.HalfExtents.y - margin, zone.HalfExtents.y + margin, ref t0, ref t1)) return -1f;
            if (!ClipSlab(localA.z, localAb.z, -zone.HalfExtents.z - margin, zone.HalfExtents.z + margin, ref t0, ref t1)) return -1f;
            return t0;
        }

        private static bool NearSegment(Zone zone, Vector3 a, Vector3 b, float margin)
        {
            Vector3 ab = b - a;
            float lengthSqr = ab.sqrMagnitude;
            float k = lengthSqr < Epsilon ? 0f : Mathf.Clamp01(Vector3.Dot(zone.Center - a, ab) / lengthSqr);
            float bound = zone.BoundRadius + margin;
            return (a + ab * k - zone.Center).sqrMagnitude <= bound * bound;
        }

        private static bool ClipSlab(float start, float delta, float min, float max, ref float t0, ref float t1)
        {
            if (Mathf.Abs(delta) < Epsilon) return start >= min && start <= max;
            float ta = (min - start) / delta;
            float tb = (max - start) / delta;
            if (ta > tb)
            {
                float swap = ta;
                ta = tb;
                tb = swap;
            }
            if (ta > t0) t0 = ta;
            if (tb < t1) t1 = tb;
            return t0 <= t1;
        }
    }
    public static class HelperDoorTraps
    {
        private const float Margin = 0.5f;
        private static readonly float[] ProbeHeights = { 0.25f, 0.9f, 1.5f };
        private const float OtherHalfSize = 1f;

        private class Trap
        {
            public Door Door;
            public Collider[] Hurts;
            public Bounds Bounds;
        }
        private static readonly List<Trap> _traps = new List<Trap>();

        public static int Count => _traps.Count;

        public static void OnInitPlugin()
        {
            _traps.Clear();
            foreach (BaseNetworkable entity in BaseNetworkable.serverEntities)
            {
                if (entity is not Door door) continue;
                Note(door);
            }
        }

        public static void OnUnloadPlugin() => _traps.Clear();

        public static void Note(Door door)
        {
            if (door == null || door.IsDestroyed) return;
            foreach (Trap known in _traps)
                if (ReferenceEquals(known.Door, door)) return;
            List<Collider> hurts = null;
            foreach (Collider col in door.GetComponentsInChildren<Collider>(true))
            {
                if (col == null || !col.isTrigger || col.GetComponentInParent<IHurtTrigger>(true) == null) continue;
                (hurts ??= new List<Collider>()).Add(col);
            }
            if (hurts == null) return;
            var trap = new Trap { Door = door, Hurts = hurts.ToArray() };
            bool first = true;
            float reach = 0f;
            foreach (Collider col in trap.Hurts)
            {
                Bounds b = ColliderBounds(col);
                if (first) trap.Bounds = b;
                else trap.Bounds.Encapsulate(b);
                first = false;
                reach = Mathf.Max(reach, b.size.x, b.size.y, b.size.z);
            }
            trap.Bounds.Expand((Margin + reach) * 2f);
            trap.Bounds.Encapsulate(trap.Bounds.min - Vector3.up * ProbeHeights[ProbeHeights.Length - 1]);
            _traps.Add(trap);
        }

        public static void Forget(Door door)
        {
            for (int i = _traps.Count - 1; i >= 0; i--)
                if (ReferenceEquals(_traps[i].Door, door)) _traps.RemoveAt(i);
        }

        public static bool AnyNear(Vector3 point, float range)
        {
            float sqr = range * range;
            foreach (Trap trap in _traps)
                if (trap.Bounds.SqrDistance(point) <= sqr) return true;
            return false;
        }

        public static bool IsInside(Vector3 point) => IsInside(point, out _);

        public static bool IsInside(Vector3 point, out Vector3 center)
        {
            center = point;
            foreach (Trap trap in _traps)
            {
                if (trap.Door == null || trap.Door.IsDestroyed || !trap.Bounds.Contains(point)) continue;
                foreach (Collider col in trap.Hurts)
                {
                    if (col == null || !col.enabled || !col.gameObject.activeInHierarchy) continue;
                    foreach (float height in ProbeHeights)
                    {
                        if (!InColliderWithMargin(col, point + Vector3.up * height)) continue;
                        center = trap.Bounds.center;
                        return true;
                    }
                }
            }
            return false;
        }

        private static bool InColliderWithMargin(Collider col, Vector3 point)
        {
            if (col is BoxCollider box)
            {
                Vector3 local = box.transform.InverseTransformPoint(point) - box.center;
                Vector3 scale = box.transform.lossyScale, half = box.size * 0.5f;
                return Mathf.Abs(local.x) <= half.x + Margin / Mathf.Max(0.01f, Mathf.Abs(scale.x))
                       && Mathf.Abs(local.y) <= half.y + Margin / Mathf.Max(0.01f, Mathf.Abs(scale.y))
                       && Mathf.Abs(local.z) <= half.z + Margin / Mathf.Max(0.01f, Mathf.Abs(scale.z));
            }
            return Vector3.Distance(col.transform.position, point) <= OtherHalfSize + Margin;
        }

        private static Bounds ColliderBounds(Collider col)
        {
            if (col is not BoxCollider box) return new Bounds(col.transform.position, Vector3.one * OtherHalfSize * 2f);
            Vector3 half = box.size * 0.5f;
            var bounds = new Bounds(box.transform.TransformPoint(box.center), Vector3.zero);
            for (int i = 0; i < 8; i++)
            {
                var corner = new Vector3((i & 1) == 0 ? -half.x : half.x, (i & 2) == 0 ? -half.y : half.y, (i & 4) == 0 ? -half.z : half.z);
                bounds.Encapsulate(box.transform.TransformPoint(box.center + corner));
            }
            return bounds;
        }
    }
    public class CollectibleHelper
    {
        private const float CellSize = 32f;

        private struct Entry
        {
            public CollectibleEntity Entity;
            public Vector3 Position;
        }

        private static Dictionary<long, List<Entry>> _cells;
        private static Dictionary<CollectibleEntity, long> _cellOf;

        public static void OnInitPlugin()
        {
            _cells = new Dictionary<long, List<Entry>>();
            _cellOf = new Dictionary<CollectibleEntity, long>();
            foreach (BaseNetworkable entity in BaseNetworkable.serverEntities)
                if (entity is CollectibleEntity collectible) Add(collectible);
        }
        public static void OnUnloadPlugin()
        {
            _cells = null;
            _cellOf = null;
        }

        #region Methods
        public static IEnumerable<CollectibleEntity> GetCollectibleEntity(Vector3 position, float radius)
        {
            if (_cells == null || radius <= 0) yield break;
            float num = radius * radius;
            int minX = Cell(position.x - radius), maxX = Cell(position.x + radius), minZ = Cell(position.z - radius), maxZ = Cell(position.z + radius);
            for (int x = minX; x <= maxX; x++)
            {
                for (int z = minZ; z <= maxZ; z++)
                {
                    if (!_cells.TryGetValue(Key(x, z), out List<Entry> cell)) continue;
                    for (int i = 0; i < cell.Count; i++)
                    {
                        Entry entry = cell[i];
                        if (entry.Entity.IsValid() && (position - entry.Entity.transform.position).sqrMagnitude < num) yield return entry.Entity;
                    }
                }
            }
        }
        public static CollectibleEntity GetFirstCollectibleEntity(Vector3 position, float radius)
        {
            foreach (CollectibleEntity collectible in GetCollectibleEntity(position, radius)) return collectible;
            return null;
        }
        public static void OnEntitySpawned(CollectibleEntity entity)
        {
            if (_cells != null && entity != null) Add(entity);
        }
        public static void OnEntityKill(CollectibleEntity entity)
        {
            if (_cellOf == null || entity == null || !_cellOf.TryGetValue(entity, out long key)) return;
            _cellOf.Remove(entity);
            if (!_cells.TryGetValue(key, out List<Entry> cell)) return;
            for (int i = cell.Count - 1; i >= 0; i--)
                if (cell[i].Entity == entity) cell.RemoveAt(i);
        }

        private static void Add(CollectibleEntity entity)
        {
            if (_cellOf.ContainsKey(entity)) return;
            Vector3 position = entity.transform.position;
            long key = Key(Cell(position.x), Cell(position.z));
            if (!_cells.TryGetValue(key, out List<Entry> cell)) _cells[key] = cell = new List<Entry>();
            cell.Add(new Entry { Entity = entity, Position = position });
            _cellOf[entity] = key;
        }

        private static int Cell(float coordinate) => Mathf.FloorToInt(coordinate / CellSize);

        private static long Key(int x, int z) => ((long)x << 32) | (uint)z;
        #endregion
    }
    public static class PluginExtension
    {
        public static bool TryMoveItemToFreeBeltSlot(this Item item, ItemContainer belt, out int slot)
        {
            slot = -1;
            if (item == null || belt == null) return false;
            for (int index = 0; index < belt.capacity; index++)
            {
                if (belt.GetSlot(index) != null) continue;
                slot = index;
                return item.MoveToContainer(belt, index);
            }
            return false;
        }

        public static bool TryGetCurrentAITarget(this BaseNPC2 npc, out BaseEntity target)
        {
            target = null;
            Rust.Ai.Gen2.SenseComponent sense = npc.GetComponent<Rust.Ai.Gen2.SenseComponent>();
            return sense != null && sense.FindTarget(out target);
        }

        public static void ToggleHeldEntity(this HeldEntity tool, bool isEnable)
        {
            if (!tool.IsValid()) return;
            if (tool is Chainsaw chainsaw)
            {
                if (isEnable && !chainsaw.EngineOn()) chainsaw.SetEngineStatus(true, BaseEntity.FlagsUpdateMode.SendNetworkUpdate);
                else if (!isEnable && chainsaw.EngineOn()) chainsaw.SetEngineStatus(false, BaseEntity.FlagsUpdateMode.SendNetworkUpdate);
                return;
            }
            BaseEntity.Flags flag = tool switch
            {
                Jackhammer => BaseEntity.Flags.Reserved8,
                _ => 0,
            };
            if (flag == 0) return;
            bool has = tool.HasFlag(flag);
            if (isEnable && !has) { using var s = tool.StartSetFlags(BaseEntity.FlagsUpdateMode.SendNetworkUpdate); s.Set(flag, true); }
            else if (!isEnable && has) { using var s = tool.StartSetFlags(BaseEntity.FlagsUpdateMode.SendNetworkUpdate); s.Set(flag, false); }
        }
        public static bool IfIncapacitated(this NPCsController.BaseCustomNpc npc)
        {
            return npc.IsWounded() || npc.IsIncapacitated();
        }
        public static bool IsValid(this NPCsController.IFSM fsm)
        {
            return fsm != null && fsm.IsValid;
        }
        public static bool IsValid(this NPCsController.BaseBrainCustomNpc brain)
        {
            return brain != null && brain.baseEntity.IsValid() && brain.baseEntity.IsInitBot;
        }
        public static bool IsValid(this NPCsController.FSM.IStatePlayerNpc state)
        {
            return state != null && state.IsValid;
        }
        public static bool IsValid(this NPCsController.INavigator navigator)
        {
            return navigator != null;
        }
        public static bool CanSeePlayerEnemy(this BasePlayer player, BasePlayer target, int layerMask, float radius = 0.02f, float maxDistance = 200f)
            => player.CanSeePlayerEnemy(target, layerMask, out _, radius, maxDistance);
        public static bool CanSeePlayerEnemy(this BasePlayer player, BasePlayer target, int layerMask, out bool headOnly, float radius = 0.02f, float maxDistance = 200f)
        {
            headOnly = false;
            if(!target.IsValid() || !player.IsValid()) return false;
            if (Physics.SphereCast(player.eyes.position, radius, (target.CenterPoint() - player.eyes.position).normalized, out RaycastHit hitInfo, maxDistance, layerMask, QueryTriggerInteraction.Ignore) && hitInfo.GetEntity() == target) return true;
            if (Physics.SphereCast(player.eyes.position, radius, (target.eyes.position - player.eyes.position).normalized, out hitInfo, maxDistance, layerMask, QueryTriggerInteraction.Ignore) && hitInfo.GetEntity() == target)
            {
                headOnly = true;
                return true;
            }
            return false;
        }
        public static bool CanSeeEnemy(this BasePlayer player, BaseCombatEntity target, int layerMask, float radius = 0.02f, float maxDistance = 200f)
        {
            if(target == null || player == null) return false;
            RaycastHit hitInfo;
            if (Physics.SphereCast(player.eyes.position, radius, (target.CenterPoint() - player.eyes.position).normalized, out hitInfo, maxDistance, layerMask, QueryTriggerInteraction.Ignore) && hitInfo.GetEntity() == target) return true;
            return false;
        }
        private const float FieldOfViewMinHorizontalDistance = 0.3f;
        public static bool IsTargetInFieldOfView(this BasePlayer player, BaseEntity target, float fieldOfViewAngleDegrees = 108, float maxDistance = 300f)
        {
            Vector3 entityPosition = player.eyes.position;
            Vector3 targetPosition = target.CenterPoint();
            Vector3 toTarget = targetPosition - entityPosition;

            float dist = toTarget.sqrMagnitude;
            if (dist <= 0f || dist > maxDistance * maxDistance) return false;

            toTarget.y = 0f;
            if (toTarget.sqrMagnitude < FieldOfViewMinHorizontalDistance * FieldOfViewMinHorizontalDistance) return true;
            Vector3 entityForward = player.eyes.HeadForward();
            entityForward.y = 0f;
            if (entityForward.sqrMagnitude < 0.000001f)
            {
                entityForward = player.transform.forward;
                entityForward.y = 0f;
                if (entityForward.sqrMagnitude < 0.000001f) return true;
            }
            return Vector3.Angle(entityForward, toTarget) <= fieldOfViewAngleDegrees * 0.5f;
        }
        public static bool IsPlayerLivestock(this BaseEntity entity) =>
            entity is Rust.Ai.Gen2.LivestockAnimal livestock
            && (livestock.OwnerID != 0
                || (livestock.BestFamiliarity(out ulong trusted) >= ConVar.Livestock.trustToLead && trusted != 0)
                || !livestock.IsPopulationSpawn());
        private static readonly Dictionary<int, bool> MedicalToolItems = new Dictionary<int, bool>();

        public static bool IsMedicalTool(this Item item)
        {
            ItemDefinition def = item?.info;
            if (def == null) return false;
            if (!MedicalToolItems.TryGetValue(def.itemid, out bool tool))
                MedicalToolItems[def.itemid] = tool = def.GetComponent<ItemModEntity>()?.entityPrefab?.GetEntity() is MedicalTool;
            return tool;
        }

        public static bool IsSafeZone(this BaseEntity entity)
        {
            bool result = entity.InSafeZone();

            if(!result)
            {
                var triggers = Physics.OverlapSphere(entity.transform.position, 0.25f, LayerMask.GetMask("Trigger"), QueryTriggerInteraction.Collide);
                if(triggers != null)
                {
                    foreach(var tr in triggers)
                    {
                        if(tr.HasComponent<TriggerSafeZone>())
                        {
                            result = true;
                            break;
                        }
                    }
                }
            }
            return result;
        }

        public static bool CalculatePathWorld(this RustNavMeshAgent agent, Vector3 startWS, Vector3 endWS, RustNavMeshPath pathNS)
        {
            return agent.CalculatePath(agent.WorldToNavSpace(startWS), agent.WorldToNavSpace(endWS), pathNS);
        }

        public static bool SamplePositionTyped(this RustNavMeshAgent agent, Vector3 worldWS, out NavMeshHit hitWS, float radius)
        {
            hitWS = default;
            return agent != null && agent.SamplePosition(worldWS, out hitWS, radius);
        }

        public static bool CalculatePathTyped(this RustNavMeshAgent agent, Vector3 startWS, Vector3 endWS, RustNavMeshPath pathNS)
            => agent != null && pathNS != null && agent.CalculatePathWorld(startWS, endWS, pathNS);

        public static void AddCornersWorld(this RustNavMeshAgent agent, RustNavMeshPath pathNS, List<Vector3> destWS)
        {
            var corners = pathNS?.corners;
            if(agent == null || corners == null) return;
            for(int i = 0; i < corners.Count; i++) destWS.Add(agent.NavToWorldSpace(corners[i]));
        }

        private const float PathEndCopyTolerance = 0.05f;
        private const float PathEndTierRadius = 1.5f;
        private const float PathEndTierMinGap = 1f;

        public static Vector3 PathEndWorld(this RustNavMeshAgent agent, RustNavMeshPath pathNS, Vector3 endWS, out bool copiedEnd)
        {
            copiedEnd = false;
            var corners = pathNS?.corners;
            if(agent == null || corners == null || corners.Count == 0) return endWS;
            Vector3 last = agent.NavToWorldSpace(corners[corners.Count - 1]);
            if(pathNS.status != NavMeshPathStatus.PathPartial || corners.Count < 2) return last;
            if(Vector3Ex.Distance2D(last, endWS) > PathEndCopyTolerance || Mathf.Abs(last.y - endWS.y) > PathEndCopyTolerance) return last;
            copiedEnd = true;
            Vector3 previous = agent.NavToWorldSpace(corners[corners.Count - 2]);
            Vector3 under = new Vector3(last.x, previous.y, last.z);
            if(agent.SamplePositionTyped(under, out NavMeshHit hit, PathEndTierRadius)
               && Mathf.Abs(hit.position.y - last.y) >= PathEndTierMinGap) return hit.position;
            return under;
        }

        public static void AddCornersWorld(RustNavMeshPath pathNS, Vector3 startWS, List<Vector3> destWS)
        {
            var corners = pathNS?.corners;
            if(corners == null || destWS == null) return;
            var independant = Rust.Ai.Gen2.Nav.IndependantNavmesh.FindNavmeshAtPosition(startWS);
            bool own = independant != null && independant.Navmesh != null && independant.Navmesh.IsBuilt();
            for(int i = 0; i < corners.Count; i++)
                destWS.Add(own ? independant.TransformPointFromNavSpaceToWorldSpace(corners[i]) : corners[i].Value);
        }
    }
    public static class Linq
    {
        public static void AddRange<TKey, TValue>(this Dictionary<TKey, TValue> dictionary, Dictionary<TKey, TValue> add)
        {
            if(dictionary == null || add == null) throw Error.ArgumentNull("dictionary or add");
            foreach (var item in add) { if(!dictionary.ContainsKey(item.Key)) dictionary.Add(item.Key, item.Value); }
        }
        public static float Sum(this IEnumerable<float> source)
        {
            if (source == null)
            {
                throw Error.ArgumentNull("source");
            }

            double num = 0.0;
            foreach (float item in source)
            {
                num += (double)item;
            }

            return (float)num;
        }
        public static float Min(this IEnumerable<float> source)
        {
            if (source == null)
            {
                throw Error.ArgumentNull("source");
            }

            using IEnumerator<float> enumerator = source.GetEnumerator();
            if (!enumerator.MoveNext())
            {
                throw Error.NoElements();
            }

            float num = enumerator.Current;
            while (enumerator.MoveNext())
            {
                float current = enumerator.Current;
                if (current < num)
                {
                    num = current;
                }
                else if (float.IsNaN(current))
                {
                    return current;
                }
            }

            return num;
        }
        public static float Max(this IEnumerable<float> source)
        {
            if (source == null)
            {
                throw Error.ArgumentNull("source");
            }

            using IEnumerator<float> enumerator = source.GetEnumerator();
            if (!enumerator.MoveNext())
            {
                throw Error.NoElements();
            }

            float num = enumerator.Current;
            while (float.IsNaN(num))
            {
                if (!enumerator.MoveNext())
                {
                    return num;
                }

                num = enumerator.Current;
            }

            while (enumerator.MoveNext())
            {
                float current = enumerator.Current;
                if (current > num)
                {
                    num = current;
                }
            }

            return num;
        }
        public static int Max<TSource>(this IEnumerable<TSource> source, Func<TSource, int> selector)
        {
            if (source == null)
            {
                throw Error.ArgumentNull("source");
            }

            if (selector == null)
            {
                throw Error.ArgumentNull("selector");
            }

            using IEnumerator<TSource> enumerator = source.GetEnumerator();
            if (!enumerator.MoveNext())
            {
                throw Error.NoElements();
            }

            int num = selector(enumerator.Current);
            while (enumerator.MoveNext())
            {
                int num2 = selector(enumerator.Current);
                if (num2 > num)
                {
                    num = num2;
                }
            }

            return num;
        }
        public static List<TSource> Where<TSource>(this IEnumerable<TSource> source, Func<TSource, bool> predicate)
        {
            List<TSource> result = new List<TSource>();
            using (var enumerator = source.GetEnumerator()) while (enumerator.MoveNext()) if (predicate(enumerator.Current)) result.Add(enumerator.Current);
            return result;
        }
        public static bool Exists<TSource>(this IEnumerable<TSource> source, Func<TSource, bool> predicate)
        {
            bool result = false;
            using (var enumerator = source.GetEnumerator()) while (enumerator.MoveNext()) if (predicate(enumerator.Current)) { result = true; break; }
            ;
            return result;
        }
    }
    public static class PluginTask
    {
        private static CancellationTokenSource _generalTokenSource;
        private static HashSet<CancellationTokenSource> tokensSource;

        public static CancellationToken Token => _generalTokenSource?.Token ?? new CancellationToken(true);

        public static Task<T> NextTickAsync<T>(Func<T> action)
        {
            var tcs = new TaskCompletionSource<T>();
            Interface.Oxide.NextTick(() =>
            {
                try { tcs.SetResult(action()); }
                catch (Exception ex) { tcs.SetException(ex); }
            });
            return tcs.Task;
        }

        internal static Task Run(Action action)
        {
            return Run(action, _generalTokenSource);
        }

        public static Task Run(Action action, CancellationTokenSource sourceToken)
        {
            if (sourceToken == null || tokensSource == null) return Task.CompletedTask;
            if (sourceToken != _generalTokenSource && !tokensSource.Contains(sourceToken))
            {
                tokensSource.Add(sourceToken);
            }
            return Task.Run(() =>
            {
                try
                {
                    action.Invoke();
                }
                catch (OperationCanceledException log)
                {
                    Interface.Oxide.NextTick(() => Debug.Log("Task canceled: {0}", log));
                }
                catch (Exception ex)
                {
                    Interface.Oxide.NextTick(() => Debug.LogError("Task threw an exception: {0}", ex));
                }
            }, sourceToken.Token);
        }

        public static Task Run(Func<Task> action, CancellationTokenSource sourceToken)
        {
            if (sourceToken == null || tokensSource == null) return Task.CompletedTask;
            if (sourceToken != _generalTokenSource && !tokensSource.Contains(sourceToken))
            {
                tokensSource.Add(sourceToken);
            }
            return Task.Run(async () =>
            {
                try
                {
                    await action.Invoke();
                }
                catch (OperationCanceledException log)
                {
                    Interface.Oxide.NextTick(() => Debug.Log("PluginTask.Run(Func<Task>): task canceled: {0}", log.Message));
                }
                catch (Exception ex)
                {
                    Interface.Oxide.NextTick(() => Debug.LogError("PluginTask.Run(Func<Task>): exception: {0}", ex));
                }
            }, sourceToken.Token);
        }

        public static void OnInitPlugin()
        {
            _generalTokenSource = new CancellationTokenSource();
            tokensSource = new();
        }
        public static void OnUnloadPlugin()
        {
            StopTasks();
            _generalTokenSource = null;
            tokensSource = null;
        }
        private static void StopTasks()
        {
            CancelTask(_generalTokenSource);
            foreach (var tokenSource in tokensSource)
            {
                CancelTask(tokenSource);
            }
            tokensSource.Clear();
        }
        public static void CancelTask(CancellationTokenSource sourceToken)
        {
            if (sourceToken == null) return;
            try
            {
                if (!sourceToken.IsCancellationRequested) sourceToken.Cancel();
                sourceToken.Dispose();
            }
            catch (ObjectDisposedException) { }
        }
        public static void RemoveToken(CancellationTokenSource sourceToken)
        {
            tokensSource?.Remove(sourceToken);
        }
    }

    public static class Debug
    {
        private static string NamePlugin => nameof(NPCsController);

        private static string _filter;
        public static void SetFilter(string filter) => _filter = string.IsNullOrEmpty(filter) ? null : filter;

        [System.Diagnostics.Conditional("__DEBUGLOGTEST_DISABLED__")]
        public static void LogTest(string message, params object[] args) => LogMessage(NamePlugin, TypeDebug.Test, message, args);
        [System.Diagnostics.Conditional("__DEBUGLOGTEST_DISABLED__")]
        public static void LogTest<T>(string message, params object[] args) => LogMessage(typeof(T).FullName, TypeDebug.Test, message, args);

        public static string Id(BasePlayer npc) => npc == null ? "?" : $"{npc.displayName}#{npc.userID}";

        [System.Diagnostics.Conditional("__DEBUGLOG_DISABLED__")]
        public static void Log(string message, params object[] args) => LogMessage(NamePlugin, TypeDebug.Log, message, args);
        [System.Diagnostics.Conditional("__DEBUGLOG_DISABLED__")]
        public static void Log<T>(string message, params object[] args) => LogMessage(typeof(T).FullName, TypeDebug.Log, message, args);

        [System.Diagnostics.Conditional("__NAVTRACE_DISABLED__")]
        public static void LogTrace(string message, params object[] args) => LogMessage(NamePlugin, TypeDebug.Log, message, args);

        public static void LogError(string message, params object[] args) => LogMessage(NamePlugin, TypeDebug.LogError, message, args);
        public static void LogError<T>(string message, params object[] args) => LogMessage(typeof(T).FullName, TypeDebug.LogError, message, args);
        public static void LogWarning(string message, params object[] args) => LogMessage(NamePlugin, TypeDebug.LogWarning, message, args);
        public static void LogWarning<T>(string message, params object[] args) => LogMessage(typeof(T).FullName, TypeDebug.LogWarning, message, args);

        public static float GetTimeMethod(UnityAction action)
        {
            TimeSince timer = 0;
            action?.Invoke();
            return timer.TotalMilliseconds;
        }

        #region Visualization Methods (3D Debug Drawing)
        public static int DdrawBudgetPerSecond = 250;

        private class DdrawWindow
        {
            public float End;
            public int Used;
            public int Dropped;
        }
        private static readonly Dictionary<ulong, DdrawWindow> _ddrawWindows = new Dictionary<ulong, DdrawWindow>();
        private static readonly List<ulong> _ddrawWindowsScratch = new List<ulong>();

        private static DdrawWindow GetDdrawWindow(ulong id)
        {
            float now = UnityEngine.Time.realtimeSinceStartup;
            if (!_ddrawWindows.TryGetValue(id, out DdrawWindow w))
            {
                w = new DdrawWindow();
                _ddrawWindows[id] = w;
                if (_ddrawWindows.Count > 32) CleanupDdrawWindows(now);
            }
            if (now >= w.End)
            {
                w.End = now + 1f;
                w.Used = 0;
                w.Dropped = 0;
            }
            return w;
        }

        private static void CleanupDdrawWindows(float now)
        {
            _ddrawWindowsScratch.Clear();
            foreach (var kv in _ddrawWindows)
                if (now - kv.Value.End > 60f) _ddrawWindowsScratch.Add(kv.Key);
            for (int i = 0; i < _ddrawWindowsScratch.Count; i++) _ddrawWindows.Remove(_ddrawWindowsScratch[i]);
        }

        private static bool TakeDrawSlot(BasePlayer player)
        {
            if (player == null) return false;
            DdrawWindow w = GetDdrawWindow(player.userID);
            if (w.Used >= DdrawBudgetPerSecond) { w.Dropped++; return false; }
            w.Used++;
            return true;
        }

        public static void DrawClear(BasePlayer player) => player?.SendConsoleCommand("ddraw.clear");
        public static void DrawText(BasePlayer player, float duration, Color color, Vector3 position, string text, float distanceFade = 0, bool zTest = false, float scale = 1f)
        { if (!TakeDrawSlot(player)) return; player.SendConsoleCommand("ddraw.text", duration, color, position, text, distanceFade, zTest, scale); }
        public static void DrawArrow(BasePlayer player, float duration, Color color, Vector3 start, Vector3 end, float radius = 0.5f, float distanceFade = 0)
        { if (!TakeDrawSlot(player)) return; player.SendConsoleCommand("ddraw.arrow", duration, color, start, end, radius, distanceFade); }
        public static void DrawLine(BasePlayer player, float duration, Color color, Vector3 start, Vector3 end, float distanceFade = 0, bool zTest = false)
        { if (!TakeDrawSlot(player)) return; player.SendConsoleCommand("ddraw.line", duration, color, start, end, distanceFade, zTest); }
        public static void DrawSphere(BasePlayer player, float duration, Color color, Vector3 position, float radius = 0.5f, float distanceFade = 0)
        { if (!TakeDrawSlot(player)) return; player.SendConsoleCommand("ddraw.sphere", duration, color, position, radius, distanceFade); }
        public static void DrawCapsule(BasePlayer player, float duration, Color color, Vector3 position, Vector3 rotation, float radius = 0.5f, float height = 2f, float distanceFade = 0)
        { if (!TakeDrawSlot(player)) return; player.SendConsoleCommand("ddraw.capsule", duration, color, position, rotation, radius, height, distanceFade); }
        public static void DrawBox(BasePlayer player, float duration, Color color, Vector3 position, Vector3 size, Vector3 rotation, float distanceFade = 0, bool zTest = false)
        { if (!TakeDrawSlot(player)) return; player.SendConsoleCommand("ddraw.box", duration, color, position, size, rotation, distanceFade, zTest); }
        #endregion

        private static void LogMessage(string namePlugin, TypeDebug typeDebug, string message, params object[] args)
        {
            if ((typeDebug == TypeDebug.Log || typeDebug == TypeDebug.Test) && _filter != null)
            {
                string formatted = string.Format(message, args);
                if (formatted.IndexOf(_filter, StringComparison.OrdinalIgnoreCase) < 0) return;
                switch (typeDebug)
                {
                    case TypeDebug.Log: UnityEngine.Debug.Log($"[{namePlugin} Log]: " + formatted); break;
                    case TypeDebug.Test: UnityEngine.Debug.LogWarning($"[{namePlugin} Test log]: " + formatted); break;
                }
                return;
            }
            switch (typeDebug)
            {
                case TypeDebug.Log: UnityEngine.Debug.Log($"[{namePlugin} Log]: " + string.Format(message, args)); break;
                case TypeDebug.LogError: UnityEngine.Debug.LogError($"[{namePlugin} Error]: " + string.Format(message, args)); break;
                case TypeDebug.LogWarning: UnityEngine.Debug.LogWarning($"[{namePlugin} Warning]: " + string.Format(message, args)); break;
                case TypeDebug.Test: UnityEngine.Debug.LogWarning($"[{namePlugin} Test log]: " + string.Format(message, args)); break;
            }
        }

        private enum TypeDebug
        {
            Log, LogError, LogWarning, Test
        }

        public struct TimeSince
        {
            private long timestamp;

            public readonly float TotalSeconds => (float)TimeSpan.TotalSeconds;
            public readonly float TotalMilliseconds => (float)TimeSpan.TotalMilliseconds;
            public readonly TimeSpan TimeSpan => TimeSpan.FromTicks((long)((System.Diagnostics.Stopwatch.GetTimestamp() - timestamp) * (TimeSpan.TicksPerSecond / (double)System.Diagnostics.Stopwatch.Frequency)));

            public static implicit operator TimeSince(float second)
            {
                return new TimeSince() { timestamp = System.Diagnostics.Stopwatch.GetTimestamp() - (long)(second * (double)System.Diagnostics.Stopwatch.Frequency) };
            }
        }
    }
    public static class PooledCollection
    {
        public static void ClearAllPooledCollection<T>(this T plugin, out string response, bool ruResponse = false) where T : Oxide.Core.Plugins.Plugin
        {
            var allNestedTypes = GetAllNestedTypes(plugin.GetType());

            response = "Clearing pool from collections of plugin:";

            foreach (var type in allNestedTypes)
            {
                if (!type.IsClass ||
                    type.IsAbstract ||
                    !typeof(Pool.IPooled).IsAssignableFrom(type) ||
                    !type.IsNested)
                    continue;

                if (!IsDeclaredInPluginHierarchy(type, plugin.GetType()))
                    continue;

                bool remove = Pool.Directory.TryRemove(type, out var poolCollection);
                if (remove)
                {
                    poolCollection.Reset();
                }
                response += $"\n          Collection[{type.Name}]: {(remove ? "removed" : "not created")}";
            }
        }
        private static IEnumerable<Type> GetAllNestedTypes(Type type)
        {
            List<Type> result = new();
            foreach (var nestedType in type.GetNestedTypes(
                BindingFlags.Public |
                BindingFlags.NonPublic |
                BindingFlags.DeclaredOnly))
            {
                result.Add(nestedType);
                result.AddRange(GetAllNestedTypes(nestedType));
            }
            return result;
        }
        private static bool IsDeclaredInPluginHierarchy(Type type, Type pluginType)
        {
            while (type != null && type.IsNested)
            {
                type = type.DeclaringType;
                if (type == pluginType) return true;
            }
            return false;
        }
    }

