        }
    }

    public static class NpcInventorySerializer
    {
        public class SavedItemData
        {
            [JsonProperty("id")]
            public int ItemId;
            [JsonProperty("n")]
            public int Amount;
            [JsonProperty("sk")]
            public ulong SkinId;
            [JsonProperty("c")]
            public float Condition;
            [JsonProperty("mc")]
            public float MaxCondition;
            [JsonProperty("p")]
            public int Position;
            [JsonProperty("nm", NullValueHandling = NullValueHandling.Ignore)]
            public string Name;
            [JsonProperty("ai", NullValueHandling = NullValueHandling.Ignore)]
            public int AmmoId;
            [JsonProperty("ac", NullValueHandling = NullValueHandling.Ignore)]
            public int AmmoCount;
            [JsonProperty("fl", NullValueHandling = NullValueHandling.Ignore)]
            public int Flags;
            [JsonProperty("tx", NullValueHandling = NullValueHandling.Ignore)]
            public string Text;
            [JsonProperty("ct", NullValueHandling = NullValueHandling.Ignore)]
            public float CookTime;
            [JsonProperty("ins", NullValueHandling = NullValueHandling.Ignore)]
            public SavedInstanceData InstanceData;
            [JsonProperty("mods", NullValueHandling = NullValueHandling.Ignore)]
            public List<SavedItemData> Mods;

            public class SavedInstanceData
            {
                [JsonProperty("di", NullValueHandling = NullValueHandling.Ignore)]
                public int DataInt;
                [JsonProperty("df", NullValueHandling = NullValueHandling.Ignore)]
                public float DataFloat;
                [JsonProperty("bt", NullValueHandling = NullValueHandling.Ignore)]
                public int BlueprintTarget;
                [JsonProperty("ba", NullValueHandling = NullValueHandling.Ignore)]
                public int BlueprintAmount;

                public bool IsEmpty() => DataInt == 0 && DataFloat == 0f && BlueprintTarget == 0 && BlueprintAmount == 0;
            }
        }

        public static List<SavedItemData> SaveContainer(ItemContainer container)
        {
            if (container == null || container.itemList == null || container.itemList.Count == 0)
                return null;
            var result = new List<SavedItemData>(container.itemList.Count);
            for (int i = 0; i < container.itemList.Count; i++)
            {
                Item item = container.itemList[i];
                if (item != null)
                    result.Add(ToData(item));
            }
            return result.Count > 0 ? result : null;
        }

        public static void RestoreContainer(ItemContainer container, List<SavedItemData> items)
        {
            if (container == null || items == null || items.Count == 0) return;
            container.Clear();
            for (int i = 0; i < items.Count; i++)
            {
                Item item = ToItem(items[i]);
                if (item == null) continue;
                if (!item.MoveToContainer(container, items[i].Position, false))
                    item.Remove();
            }
        }

        private static SavedItemData ToData(Item item)
        {
            var data = new SavedItemData
            {
                ItemId = item.info.itemid,
                Amount = item.amount,
                SkinId = item.skin,
                Position = item.position,
                Flags = (int)item.flags,
            };
            if (item.hasCondition)
            {
                data.Condition = item.condition;
                data.MaxCondition = item.maxCondition;
            }
            if (!string.IsNullOrEmpty(item.name)) data.Name = item.name;
            if (!string.IsNullOrEmpty(item.text)) data.Text = item.text;
            if (item.cookTimeLeft > 0f) data.CookTime = item.cookTimeLeft;
            if (item.instanceData != null)
            {
                var ins = new SavedItemData.SavedInstanceData
                {
                    DataInt = item.instanceData.dataInt,
                    DataFloat = item.instanceData.dataFloat,
                    BlueprintTarget = item.instanceData.blueprintTarget,
                    BlueprintAmount = item.instanceData.blueprintAmount,
                };
                if (!ins.IsEmpty()) data.InstanceData = ins;
            }
            BaseEntity heldEnt = item.GetHeldEntity();
            if (heldEnt != null)
            {
                if (heldEnt is BaseProjectile proj && proj.primaryMagazine != null)
                {
                    data.AmmoId = proj.primaryMagazine.ammoType?.itemid ?? 0;
                    data.AmmoCount = proj.primaryMagazine.contents;
                }
                else if (heldEnt is Chainsaw chainsaw)
                {
                    data.AmmoCount = chainsaw.ammo;
                }
                else if (heldEnt is FlameThrower flameThrower)
                {
                    data.AmmoCount = flameThrower.ammo;
                }
            }
            if (item.contents != null && item.contents.itemList != null && item.contents.itemList.Count > 0)
            {
                data.Mods = new List<SavedItemData>(item.contents.itemList.Count);
                for (int i = 0; i < item.contents.itemList.Count; i++)
                {
                    Item mod = item.contents.itemList[i];
                    if (mod != null) data.Mods.Add(ToData(mod));
                }
            }
            return data;
        }

        private static Item ToItem(SavedItemData data)
        {
            if (data == null || data.ItemId == 0 || data.Amount == 0) return null;
            Item item = ItemManager.CreateByItemID(data.ItemId, data.Amount, data.SkinId);
            if (item == null) return null;
            if (item.hasCondition)
            {
                if (data.MaxCondition > 0f)
                {
                    item.maxCondition = data.MaxCondition;
                    item.condition = data.Condition;
                }
            }
            if (!string.IsNullOrEmpty(data.Name)) item.name = data.Name;
            if (!string.IsNullOrEmpty(data.Text)) item.text = data.Text;
            if (data.CookTime > 0f) item.cookTimeLeft = data.CookTime;
            if (data.Flags != 0) item.flags = (Item.Flag)data.Flags;
            if (data.InstanceData != null)
            {
                if (item.instanceData == null) item.instanceData = new ProtoBuf.Item.InstanceData();
                item.instanceData.ShouldPool = false;
                item.instanceData.dataInt = data.InstanceData.DataInt;
                item.instanceData.dataFloat = data.InstanceData.DataFloat;
                item.instanceData.blueprintTarget = data.InstanceData.BlueprintTarget;
                item.instanceData.blueprintAmount = data.InstanceData.BlueprintAmount;
            }
            BaseEntity heldEnt = item.GetHeldEntity();
            if (heldEnt != null)
            {
                if (heldEnt is BaseProjectile proj && proj.primaryMagazine != null)
                {
                    if (data.AmmoId != 0)
                    {
                        ItemDefinition ammoDef = ItemManager.FindItemDefinition(data.AmmoId);
                        if (ammoDef != null) proj.primaryMagazine.ammoType = ammoDef;
                    }
                    proj.primaryMagazine.contents = data.AmmoCount;
                }
                else if (heldEnt is Chainsaw chainsaw)
                {
                    chainsaw.ammo = data.AmmoCount;
                }
                else if (heldEnt is FlameThrower flameThrower)
                {
                    flameThrower.ammo = data.AmmoCount;
                }
            }
            if (data.Mods != null && data.Mods.Count > 0 && item.contents != null)
            {
                for (int i = 0; i < data.Mods.Count; i++)
                {
                    Item mod = ToItem(data.Mods[i]);
                    if (mod != null && !mod.MoveToContainer(item.contents))
                        mod.Remove();
                }
            }
            return item;
        }
    }
}
